// generated by scripts/import-upstream-catalogue.mjs from openGym 8fb98b16 (AGPL-3.0) — do not edit by hand
export const EXDB_UPSTREAM=[{"id":"0005","n":"band alternate biceps curl","bp":"upper arms","eq":"band","tg":"biceps","mg":"brachialis","sm":["brachialis","forearms"],"st":["Stand on the middle of a band and hold an end in each hand.","Keep your elbows at your sides with palms forward.","Curl one hand up toward your shoulder.","Lower it slowly while curling the other hand.","Keep your upper arms still and avoid leaning back.","Alternate sides for your reps."],"img":"opengym/0005.webp","gif":null,"ext":1},{"id":"0021","n":"ball sit up (on stability ball)","bp":"waist","eq":"stability ball","tg":"abs","mg":"hip flexors","sm":["hip flexors","obliques"],"st":["Sit on a stability ball and walk your feet out until your lower back is supported.","Place your hands by your head or across your chest.","Curl your torso up, bringing your ribs toward your hips.","Squeeze your abs at the top.","Lower slowly back over the ball.","Keep your feet planted and your neck relaxed."],"img":"opengym/0021.webp","gif":null,"ext":1},{"id":"0062","n":"barbell narrow row","bp":"back","eq":"barbell","tg":"upper back","mg":"lats","sm":["lats","biceps","rhomboids","rear deltoids","lower back"],"st":["Hold a barbell with a narrow, underhand or neutral grip, hinge at the hips and keep your back flat.","Let the bar hang at arm's length below your chest.","Pull the bar toward your lower ribs, keeping your elbows close to your sides.","Squeeze your shoulder blades together at the top.","Lower the bar under control until your arms are straight.","Keep your neck neutral and avoid jerking with your lower back."],"img":"opengym/0062.webp","gif":null,"ext":1},{"id":"0093","n":"barbell seated twist (on stability ball)","bp":"waist","eq":"barbell","tg":"obliques","mg":"lower back","sm":["lower back","core"],"st":["Sit on a stability ball with a barbell across your upper back and your feet wide.","Sit tall with your core braced.","Rotate your torso to one side without moving your hips.","Return to the centre.","Rotate to the other side.","Keep the movement slow and controlled."],"img":"opengym/0093.webp","gif":null,"ext":1},{"id":"0131","n":"bent knee lying twist (on stability ball)","bp":"waist","eq":"stability ball","tg":"obliques","mg":"abdominals","sm":["abdominals","lower back","hip flexors"],"st":["Lie with your upper back on a stability ball and your knees bent at 90 degrees.","Extend your arms out to the sides for balance.","Rotate your knees and hips slowly to one side.","Pause briefly.","Bring them back through the centre and rotate to the other side.","Keep your shoulders square to the ceiling."],"img":"opengym/0131.webp","gif":null,"ext":1},{"id":"0133","n":"bent knee side plank","bp":"waist","eq":"body weight","tg":"obliques","mg":"abdominals","sm":["abdominals","shoulders","glutes"],"st":["Lie on your side with your knees bent and your elbow under your shoulder.","Stack your hips and knees.","Lift your hips so your body forms a straight line from knee to head.","Hold for 20-30 seconds.","Lower your hips with control.","Repeat on the other side."],"img":"opengym/0133.webp","gif":null,"ext":1},{"id":"0134","n":"bent side knee push up","bp":"chest","eq":"body weight","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders","core","obliques"],"st":["Start in a push-up position with your knees bent and both hands under your shoulders.","Rotate your knees and hips slightly to one side.","Lower your chest to the floor with your elbows at about 45 degrees.","Push back up to the start.","Keep your core tight and your hips from sagging.","Switch the side of your knees between sets."],"img":"opengym/0134.webp","gif":null,"ext":1},{"id":"0136","n":"boat yoga pose","bp":"waist","eq":"body weight","tg":"abs","mg":"hip flexors","sm":["hip flexors","lower back","quadriceps"],"st":["Sit on the floor with your knees bent and your feet flat.","Lean back slightly while keeping your chest open.","Lift your feet off the floor and straighten your legs if you can.","Reach your arms forward alongside your knees.","Hold for 20-30 seconds while breathing steadily.","Lower your feet gently to rest."],"img":"opengym/0136.webp","gif":null,"ext":1},{"id":"0142","n":"bridge (on knees)","bp":"waist","eq":"body weight","tg":"abs","mg":"glutes","sm":["glutes","core","shoulders"],"st":["Kneel on a mat and lean forward onto your forearms.","Position your elbows under your shoulders.","Lift your hips so your body forms a straight line from knees to head.","Brace your abs and squeeze your glutes.","Hold for 20-30 seconds.","Lower gently and rest."],"img":"opengym/0142.webp","gif":null,"ext":1},{"id":"0143","n":"bridge (straight arm)","bp":"waist","eq":"body weight","tg":"abs","mg":"shoulders","sm":["shoulders","glutes","core"],"st":["Start in a high plank with your hands under your shoulders.","Extend your legs behind you with your toes on the floor.","Squeeze your glutes and brace your abs.","Keep your body in a straight line.","Hold for 20-30 seconds.","Lower your knees to rest."],"img":"opengym/0143.webp","gif":null,"ext":1},{"id":"0147","n":"bicycle twisting crunch","bp":"waist","eq":"body weight","tg":"obliques","mg":"abdominals","sm":["abdominals","hip flexors"],"st":["Lie on your back with your hands behind your head and your legs lifted.","Bring one knee toward your chest and rotate to touch the opposite elbow to it.","Extend the other leg straight.","Switch sides in a pedalling motion.","Keep your lower back pressed to the floor.","Move at a steady pace without pulling on your neck."],"img":"opengym/0147.webp","gif":null,"ext":1},{"id":"0163","n":"cable front seated row","bp":"back","eq":"cable","tg":"upper back","mg":"lats","sm":["lats","rhomboids","biceps","rear deltoids"],"st":["Sit at a cable row station with your feet on the platform and your knees slightly bent.","Grab the handle with both hands and sit tall.","Pull the handle toward your lower ribs, squeezing your shoulder blades together.","Pause briefly at the end.","Return slowly until your arms are straight.","Keep your chest up and avoid rocking back."],"img":"opengym/0163.webp","gif":null,"ext":1},{"id":"0166","n":"cable hammer curl","bp":"upper arms","eq":"cable","tg":"biceps","mg":"brachialis","sm":["brachialis","forearms"],"st":["Attach a rope or handle to a low pulley and hold it with palms facing each other.","Stand tall with your elbows at your sides.","Curl the handles up toward your shoulders.","Squeeze at the top.","Lower slowly until your arms are straight.","Keep your upper arms still and avoid swinging."],"img":"opengym/0166.webp","gif":null,"ext":1},{"id":"0183","n":"cable lying curl","bp":"upper arms","eq":"cable","tg":"biceps","mg":"brachialis","sm":["brachialis","forearms"],"st":["Lie on your back on a mat with your head toward a low pulley and take the bar overhead.","Start with your arms extended.","Curl the bar toward your forehead or chest.","Squeeze your biceps at the top.","Lower with control to full extension.","Keep your elbows pointing upward and your back flat."],"img":"opengym/0183.webp","gif":null,"ext":1},{"id":"0187","n":"cable lying triceps extension","bp":"upper arms","eq":"cable","tg":"triceps","mg":"forearms","sm":["forearms","shoulders"],"st":["Set a low pulley with a bar or rope and lie on a bench with your head near the stack.","Hold the handle with arms extended above your chest.","Keep your upper arms still and bend only at the elbows to lower the handle toward your forehead.","Pause when your forearms pass parallel to the floor.","Press back up by straightening your arms.","Keep your elbows pointing at the ceiling and don't flare them."],"img":"opengym/0187.webp","gif":null,"ext":1},{"id":"0250","n":"ceiling look stretch","bp":"neck","eq":"body weight","tg":"levator scapulae","mg":"sternocleidomastoid","sm":["sternocleidomastoid","upper back"],"st":["Sit or stand tall with relaxed shoulders.","Slowly tilt your head back to look at the ceiling.","Open your mouth slightly to relax the jaw.","Feel the stretch along the front of your neck.","Hold for 15-20 seconds.","Return to neutral slowly."],"img":"opengym/0250.webp","gif":null,"ext":1},{"id":"0255","n":"wall ball circles","bp":"shoulders","eq":"stability ball","tg":"delts","mg":"rotator cuff","sm":["rotator cuff","upper back","trapezius"],"st":["Stand facing a wall and place a ball against it at shoulder height with one hand.","Keep your arm straight but relaxed.","Roll the ball in small circles on the wall.","Do several circles in one direction.","Reverse the direction.","Keep your shoulder down, then switch arms."],"img":"opengym/0255.webp","gif":null,"ext":1},{"id":"0256","n":"elbow arm circles","bp":"shoulders","eq":"body weight","tg":"delts","mg":"rotator cuff","sm":["rotator cuff","upper back","trapezius"],"st":["Stand tall with your fingertips on your shoulders.","Raise your elbows out to the sides.","Draw big circles with your elbows.","Do several circles forward.","Reverse and circle backward.","Keep your neck relaxed and your breathing steady."],"img":"opengym/0256.webp","gif":null,"ext":1},{"id":"0261","n":"corkscrew push up","bp":"chest","eq":"body weight","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders","core","obliques"],"st":["Start in a high plank with your hands under your shoulders.","Lower your chest toward the floor while rotating your hips slightly to one side.","Push up and return to the centre.","Repeat to the other side.","Keep your core braced and your legs together.","Move smoothly and do not let your hips sag."],"img":"opengym/0261.webp","gif":null,"ext":1},{"id":"0263","n":"cross body twisting crunch","bp":"waist","eq":"body weight","tg":"obliques","mg":"abdominals","sm":["abdominals","hip flexors"],"st":["Lie on your back with your knees bent and your hands behind your head.","Lift your shoulders and twist your torso to one side.","Bring your elbow toward the opposite knee.","Lower back down and repeat on the other side.","Keep your lower back on the floor.","Do not pull on your neck."],"img":"opengym/0263.webp","gif":null,"ext":1},{"id":"0264","n":"cross jacks","bp":"full body","eq":"body weight","tg":"cardiovascular system","mg":"calves","sm":["calves","glutes","shoulders","quadriceps"],"st":["Stand with your feet together and your arms at your sides.","Jump your feet apart while raising your arms overhead.","Jump back crossing your arms and one leg in front.","Alternate which leg crosses on the next rep.","Land softly on the balls of your feet.","Keep a steady rhythm for 30-60 seconds."],"img":"opengym/0264.webp","gif":null,"ext":1},{"id":"0268","n":"crunch (leg raise)","bp":"waist","eq":"body weight","tg":"abs","mg":"hip flexors","sm":["hip flexors","lower abs","obliques"],"st":["Lie on your back with your hands by your head and your legs up.","Curl your shoulders off the floor while keeping your legs raised.","Squeeze your abs.","Lower your shoulders slowly.","Lift your legs slightly higher at the top for extra work.","Keep your lower back pressed down."],"img":"opengym/0268.webp","gif":null,"ext":1},{"id":"0269","n":"crunch (legs on stability ball)","bp":"waist","eq":"stability ball","tg":"abs","mg":"hip flexors","sm":["hip flexors","obliques"],"st":["Lie on your back with your calves on a stability ball and your knees bent at 90 degrees.","Place your hands by your head or across your chest.","Curl your shoulders off the floor.","Squeeze your abs at the top.","Lower slowly.","Keep your neck relaxed and the ball steady."],"img":"opengym/0269.webp","gif":null,"ext":1},{"id":"0273","n":"crunch (straight leg up)","bp":"waist","eq":"body weight","tg":"abs","mg":"hip flexors","sm":["hip flexors","lower abs"],"st":["Lie on your back with your legs straight up toward the ceiling.","Extend your arms toward your feet.","Curl your shoulders off the floor and reach toward your toes.","Squeeze your abs at the top.","Lower slowly.","Keep your legs still and your neck relaxed."],"img":"opengym/0273.webp","gif":null,"ext":1},{"id":"0275","n":"crunch floor v. 2","bp":"waist","eq":"body weight","tg":"abs","mg":"obliques","sm":["obliques","hip flexors"],"st":["Lie on your back with your knees bent and your feet flat.","Place your hands lightly by your head or across your chest.","Curl your shoulders off the floor.","Pause and squeeze your abs.","Lower with control.","Keep your chin off your chest and your lower back on the floor."],"img":"opengym/0275.webp","gif":null,"ext":1},{"id":"0278","n":"decline push up (on stability ball)","bp":"chest","eq":"stability ball","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders","upper chest","core"],"st":["Place your shins or feet on a stability ball and your hands on the floor under your shoulders.","Form a straight line from head to heels.","Lower your chest toward the floor.","Push back up without letting your hips sag.","Brace your core to keep the ball steady.","Keep your elbows at about 45 degrees."],"img":"opengym/0278.webp","gif":null,"ext":1},{"id":"0281","n":"decline sit up (arms straight)","bp":"waist","eq":"body weight","tg":"abs","mg":"hip flexors","sm":["hip flexors","obliques"],"st":["Lie on a decline bench and hook your feet under the pads.","Extend your arms straight in front of you, parallel to the floor.","Curl your torso up, rolling off the bench one section at a time.","Reach your arms toward your knees as you sit up.","Lower back down slowly with control.","Keep your chin off your chest and don't yank with your arms."],"img":"opengym/0281.webp","gif":null,"ext":1},{"id":"0357","n":"dumbbell one arm press (on stability ball)","bp":"chest","eq":"dumbbell","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders","core"],"st":["Sit on a stability ball with a dumbbell and walk your feet out until your upper back rests on the ball.","Lift your hips so your body is flat like a bench, feet wide for balance.","Hold the dumbbell at chest height and press it up over your shoulder.","Lower it slowly back to chest level.","Finish your reps, then switch arms.","Keep your hips up and don't let your body twist."],"img":"opengym/0357.webp","gif":null,"ext":1},{"id":"0412","n":"dumbbell squat (back on stability ball wall)","bp":"upper legs","eq":"dumbbell","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","adductors"],"st":["Place a stability ball between your lower back and a wall and hold a dumbbell in each hand.","Step your feet forward, shoulder width apart.","Bend your knees and sink down as the ball rolls up your back.","Lower until your thighs are about parallel to the floor.","Push through your heels to stand back up.","Keep your knees tracking over your toes."],"img":"opengym/0412.webp","gif":null,"ext":1},{"id":"0435","n":"dumbbell sumo squat (back on stability ball wall)","bp":"upper legs","eq":"dumbbell","tg":"glutes","mg":"quadriceps","sm":["quadriceps","adductors","inner thighs","hamstrings"],"st":["Place a stability ball against a wall and lean your lower back on it.","Hold a dumbbell with both hands in front of you and set your feet wide with toes turned out.","Squat down as the ball rolls up your back.","Lower until your thighs are about parallel.","Push through your heels to stand.","Keep your knees tracking over your toes."],"img":"opengym/0435.webp","gif":null,"ext":1},{"id":"0461","n":"frog squat","bp":"upper legs","eq":"body weight","tg":"quads","mg":"glutes","sm":["glutes","adductors","calves"],"st":["Stand with your feet wider than shoulders and your toes turned out.","Lower into a deep squat with your hands between your knees.","Explode up into a jump.","Land softly back in the deep squat.","Keep your chest up and your knees out.","Rest briefly between sets."],"img":"opengym/0461.webp","gif":null,"ext":1},{"id":"0462","n":"front and back neck stretch","bp":"neck","eq":"body weight","tg":"levator scapulae","mg":"sternocleidomastoid","sm":["sternocleidomastoid","trapezius"],"st":["Sit or stand tall with your shoulders relaxed.","Slowly lower your chin toward your chest until you feel a stretch at the back of the neck.","Hold for 20-30 seconds.","Raise your head and slowly tip it back to look up.","Hold for 20-30 seconds, staying comfortable.","Move slowly and keep your breathing relaxed."],"img":"opengym/0462.webp","gif":null,"ext":1},{"id":"0463","n":"front plank","bp":"waist","eq":"body weight","tg":"abs","mg":"core","sm":["core","shoulders","glutes"],"st":["Lie face down and prop yourself on your forearms, elbows under your shoulders.","Lift your hips and knees off the floor, resting on your toes.","Keep your body in a straight line from head to heels.","Squeeze your abs and glutes.","Hold for 20-60 seconds while breathing steadily.","Don't let your hips sag or pike up."],"img":"opengym/0463.webp","gif":null,"ext":1},{"id":"0468","n":"grasshopper push up","bp":"chest","eq":"body weight","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders","core","hip flexors"],"st":["Start in a high plank with your hands under your shoulders.","Lower your chest toward the floor and bring one knee toward the opposite elbow.","Push back up while returning the leg.","Repeat with the other leg.","Keep your core tight.","Move at a steady pace."],"img":"opengym/0468.webp","gif":null,"ext":1},{"id":"0470","n":"hand opposite knee crunch","bp":"waist","eq":"body weight","tg":"abs","mg":"obliques","sm":["obliques","hip flexors"],"st":["Lie on your back with your knees bent and your hands behind your head.","Lift your shoulders and bring one knee up.","Reach the opposite hand toward that knee.","Lower and repeat on the other side.","Keep your lower back on the floor.","Do not pull on your neck."],"img":"opengym/0470.webp","gif":null,"ext":1},{"id":"0479","n":"high knee step up","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","hip flexors","calves"],"st":["Stand in front of a sturdy bench or step.","Place one foot fully on it.","Drive through that foot to step up and lift the other knee high.","Step back down with control.","Keep your torso upright.","Repeat, then switch legs."],"img":"opengym/0479.webp","gif":null,"ext":1},{"id":"0480","n":"high knee twist","bp":"cardio","eq":"body weight","tg":"cardiovascular system","mg":"obliques","sm":["obliques","hip flexors","quadriceps","core"],"st":["Stand tall with your hands behind your head.","Lift one knee high and twist your torso to meet it with the opposite elbow.","Lower and switch sides.","Keep a quick, steady rhythm.","Land softly on the balls of your feet.","Go for 30-60 seconds."],"img":"opengym/0480.webp","gif":null,"ext":1},{"id":"0481","n":"high knees butt kicks","bp":"cardio","eq":"body weight","tg":"cardiovascular system","mg":"hamstrings","sm":["hamstrings","quadriceps","hip flexors","calves"],"st":["Stand tall with your arms ready to pump.","Run in place and drive your knees up high.","Switch to kicking your heels toward your buttocks.","Alternate between the two patterns.","Stay light on your feet.","Keep going for 30-60 seconds."],"img":"opengym/0481.webp","gif":null,"ext":1},{"id":"0482","n":"hip crunch (knees bent)","bp":"waist","eq":"body weight","tg":"abs","mg":"lower abs","sm":["lower abs","obliques","hip flexors"],"st":["Lie on your back with your knees bent and lifted over your hips.","Place your hands at your sides.","Curl your hips off the floor by bringing your knees toward your chest.","Pause at the top.","Lower slowly back to the start.","Use your abs instead of swinging your legs."],"img":"opengym/0482.webp","gif":null,"ext":1},{"id":"0485","n":"hip raise bridge v. 2","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"hamstrings","sm":["hamstrings","core","lower back"],"st":["Lie on your back with your knees bent and your feet flat.","Place your arms at your sides.","Press through your heels and lift your hips toward the ceiling.","Squeeze your glutes at the top.","Lower slowly to the floor.","Keep your ribs down and avoid overarching."],"img":"opengym/0485.webp","gif":null,"ext":1},{"id":"0486","n":"hip raise bridge","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"hamstrings","sm":["hamstrings","core","lower back"],"st":["Lie on your back with your knees bent and your feet flat.","Place your arms at your sides.","Drive through your heels to lift your hips.","Squeeze your glutes at the top.","Lower slowly.","Keep your ribs down and your neck relaxed."],"img":"opengym/0486.webp","gif":null,"ext":1},{"id":"0487","n":"hip raise crunch","bp":"waist","eq":"body weight","tg":"abs","mg":"lower abs","sm":["lower abs","hip flexors","obliques"],"st":["Lie on your back with your legs lifted and knees bent.","Place your hands at your sides or under your hips.","Curl your hips off the floor, bringing your knees toward your chest.","Hold briefly at the top.","Lower with control.","Avoid using momentum."],"img":"opengym/0487.webp","gif":null,"ext":1},{"id":"0502","n":"jack knife floor","bp":"waist","eq":"body weight","tg":"abs","mg":"hip flexors","sm":["hip flexors","obliques"],"st":["Lie on your back with legs straight and arms extended overhead.","Brace your abs and press your lower back into the floor.","Lift your arms and legs at the same time, folding up at the hips.","Reach your hands toward your toes at the top.","Lower with control until arms and legs hover just above the floor.","Keep your movement smooth and avoid swinging."],"img":"opengym/0502.webp","gif":null,"ext":1},{"id":"0503","n":"jack knife on ball","bp":"waist","eq":"stability ball","tg":"abs","mg":"shoulders","sm":["shoulders","hip flexors","core"],"st":["Get into a push-up position with your shins or feet resting on a stability ball.","Keep your hands under your shoulders and your body in a straight line.","Roll the ball toward your hands as you lift your hips toward the ceiling.","Keep your legs fairly straight and pull with your abs.","Pause briefly at the top.","Roll the ball back out to the plank without sagging your lower back."],"img":"opengym/0503.webp","gif":null,"ext":1},{"id":"0504","n":"jack press","bp":"full body","eq":"dumbbell","tg":"cardiovascular system","mg":"shoulders","sm":["shoulders","triceps","calves","glutes"],"st":["Stand tall with a dumbbell in each hand at shoulder height.","Jump your feet out wide as you press the dumbbells overhead.","Lock out the arms without arching your back.","Jump your feet together as you lower the weights to your shoulders.","Land softly on the balls of your feet.","Keep a steady rhythm for the set."],"img":"opengym/0504.webp","gif":null,"ext":1},{"id":"0505","n":"jack split crunches","bp":"waist","eq":"body weight","tg":"abs","mg":"hip flexors","sm":["hip flexors","obliques","quadriceps"],"st":["Lie on your back with your arms extended overhead and legs together.","Lift your shoulders and legs as you crunch up.","Open your legs wide in a split while your hands reach forward.","Bring the legs back together as you lower.","Keep your lower back pressed down.","Repeat at a smooth, steady pace."],"img":"opengym/0505.webp","gif":null,"ext":1},{"id":"0510","n":"jump lunge to feet jack","bp":"full body","eq":"body weight","tg":"cardiovascular system","mg":"quadriceps","sm":["quadriceps","glutes","hamstrings","calves","shoulders"],"st":["Start standing tall with feet together.","Step into a lunge and drop your back knee toward the floor.","Jump and switch legs in the air, landing in a lunge on the other side.","Jump up and land with feet wide as you swing your arms overhead, like a jumping jack.","Jump the feet back together and return to the start.","Land softly and keep your chest up."],"img":"opengym/0510.webp","gif":null,"ext":1},{"id":"0556","n":"kicks leg bent v. 2","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"hamstrings","sm":["hamstrings","core"],"st":["Start on all fours with hands under shoulders and knees under hips.","Keep your core tight and your back flat.","Lift one leg with the knee bent at 90 degrees.","Press the sole of your foot toward the ceiling until your thigh is in line with your back.","Squeeze your glute at the top.","Lower with control and finish all reps, then switch sides."],"img":"opengym/0556.webp","gif":null,"ext":1},{"id":"0559","n":"knee to chest stretch","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"lower back","sm":["lower back","hamstrings"],"st":["Lie on your back with both legs straight.","Bend one knee and clasp your hands around the shin or behind the thigh.","Gently pull the knee toward your chest.","Keep the other leg relaxed on the floor.","Hold for 20-30 seconds while breathing slowly.","Release and switch sides."],"img":"opengym/0559.webp","gif":null,"ext":1},{"id":"0560","n":"kneeling hip flexor","bp":"upper legs","eq":"body weight","tg":"hip flexors","mg":"quadriceps","sm":["quadriceps","glutes"],"st":["Kneel on one knee with the other foot flat in front of you.","Place a pad under your back knee if needed.","Tuck your pelvis and squeeze the glute of the back leg.","Shift your hips gently forward until you feel a stretch at the front of the hip.","Hold for 20-30 seconds.","Switch legs and repeat."],"img":"opengym/0560.webp","gif":null,"ext":1},{"id":"0561","n":"kneeling wrist flexor stretch","bp":"lower arms","eq":"body weight","tg":"forearms","mg":"wrist flexors","sm":["wrist flexors"],"st":["Kneel on the floor and place your palms down with fingers pointing toward your knees.","Keep your palms flat and arms straight.","Slowly sit your hips back to increase the stretch.","Stop when you feel a pull along the inner forearms.","Hold for 20-30 seconds.","Ease off gently and shake out your hands."],"img":"opengym/0561.webp","gif":null,"ext":1},{"id":"0564","n":"lateral box jump","bp":"upper legs","eq":"body weight","tg":"quads","mg":"glutes","sm":["glutes","calves","hamstrings"],"st":["Stand beside a sturdy box or step.","Bend your knees and swing your arms back.","Jump up and sideways, landing with both feet on the box.","Land softly with bent knees and stand tall.","Step down carefully.","Repeat, then switch the side you start from."],"img":"opengym/0564.webp","gif":null,"ext":1},{"id":"0565","n":"lateral speed step","bp":"lower legs","eq":"body weight","tg":"calves","mg":"quadriceps","sm":["quadriceps","glutes","ankles"],"st":["Stand in a slight athletic stance with knees bent.","Step quickly to one side, pushing off the opposite foot.","Bring the trailing foot in and step back the other way.","Stay on the balls of your feet.","Keep your chest up and arms moving naturally.","Work at a fast but controlled pace for the set."],"img":"opengym/0565.webp","gif":null,"ext":1},{"id":"0567","n":"lateral twist box jump","bp":"upper legs","eq":"body weight","tg":"quads","mg":"glutes","sm":["glutes","calves","obliques"],"st":["Stand facing a sturdy box with feet shoulder-width apart.","Dip into a quarter squat and swing your arms back.","Jump up and rotate your hips to land sideways on the box.","Land softly with bent knees.","Step down and reset.","Alternate the twist direction each rep."],"img":"opengym/0567.webp","gif":null,"ext":1},{"id":"0568","n":"leg bench side bridge","bp":"waist","eq":"body weight","tg":"obliques","mg":"core","sm":["core","glutes","shoulders"],"st":["Lie on your side with your top leg resting on a bench.","Place your forearm on the floor under your shoulder.","Lift your hips so your body forms a straight line.","Keep your hips stacked and your core tight.","Hold for 20-30 seconds.","Lower and repeat on the other side."],"img":"opengym/0568.webp","gif":null,"ext":1},{"id":"0569","n":"leg curl (on stability ball)","bp":"upper legs","eq":"stability ball","tg":"hamstrings","mg":"glutes","sm":["glutes","core","calves"],"st":["Lie on your back with your heels on a stability ball and legs straight.","Press your hips up so your body forms a line.","Pull the ball toward your glutes by bending your knees.","Keep your hips lifted throughout.","Pause at the top.","Roll the ball back out slowly."],"img":"opengym/0569.webp","gif":null,"ext":1},{"id":"0608","n":"lever twist","bp":"waist","eq":"leverage machine","tg":"obliques","mg":"abdominals","sm":["abdominals","lower back"],"st":["Sit in the machine and adjust the pads so your torso is secure.","Grip the handles and keep your hips facing forward.","Rotate your torso to one side in a controlled way.","Pause briefly at the end of the range.","Return to the centre and rotate to the other side.","Move slowly and avoid using momentum."],"img":"opengym/0608.webp","gif":null,"ext":1},{"id":"0610","n":"low jacks","bp":"full body","eq":"body weight","tg":"cardiovascular system","mg":"quadriceps","sm":["quadriceps","glutes","calves","adductors"],"st":["Start in a half squat with hands in front of your chest.","Jump your feet out wide, staying low.","Jump them back together and keep your knees bent.","Keep your chest up and weight on your heels.","Stay in the squat throughout.","Keep a steady pace for 30-60 seconds."],"img":"opengym/0610.webp","gif":null,"ext":1},{"id":"0611","n":"lunge push up","bp":"full body","eq":"body weight","tg":"pectorals","mg":"triceps","sm":["triceps","quadriceps","glutes","shoulders"],"st":["Stand tall with feet together.","Step back into a lunge and lower your back knee toward the floor.","Place your hands on the floor and step into a plank.","Lower into a push-up and press back up.","Step back into the lunge and stand up.","Alternate the lunging leg each rep."],"img":"opengym/0611.webp","gif":null,"ext":1},{"id":"0614","n":"lying alternate hip extension","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"hamstrings","sm":["hamstrings","lower back"],"st":["Lie face down with arms by your sides or under your forehead.","Keep your legs straight and your hips pressed down.","Lift one leg off the floor while squeezing your glute.","Lower it with control.","Lift the other leg and alternate.","Avoid arching your lower back."],"img":"opengym/0614.webp","gif":null,"ext":1},{"id":"0615","n":"lying crossover stretch","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"lower back","sm":["lower back","obliques"],"st":["Lie on your back with arms out to the sides.","Bend one knee and bring it across your body.","Let it lower toward the floor on the opposite side.","Keep both shoulders flat on the floor.","Hold for 20-30 seconds.","Switch sides."],"img":"opengym/0615.webp","gif":null,"ext":1},{"id":"0616","n":"lying hip flexor stretch","bp":"upper legs","eq":"body weight","tg":"hip flexors","mg":"quadriceps","sm":["quadriceps"],"st":["Lie on your back near the edge of a bench or bed.","Pull one knee toward your chest and hold it.","Let the other leg hang down relaxed over the edge.","Keep your lower back flat.","Hold for 20-30 seconds.","Switch legs."],"img":"opengym/0616.webp","gif":null,"ext":1},{"id":"0617","n":"lying hip leg raise (on floor)","bp":"upper legs","eq":"body weight","tg":"abductors","mg":"glutes","sm":["glutes","obliques"],"st":["Lie on your side with your legs straight and stacked.","Rest your head on your arm and keep your core tight.","Raise your top leg toward the ceiling.","Keep your toes pointing forward.","Lower slowly without touching the other leg.","Finish all reps, then switch sides."],"img":"opengym/0617.webp","gif":null,"ext":1},{"id":"0619","n":"lying hip straight leg raise","bp":"upper legs","eq":"body weight","tg":"hamstrings","mg":"hip flexors","sm":["hip flexors","glutes","core"],"st":["Lie on your back with both legs straight.","Brace your abs and press your lower back down.","Lift one straight leg to about hip height.","Lower it slowly toward the floor.","Keep the other leg flat.","Finish your reps, then switch legs."],"img":"opengym/0619.webp","gif":null,"ext":1},{"id":"0621","n":"lying scissor crunch","bp":"waist","eq":"body weight","tg":"abs","mg":"obliques","sm":["obliques","hip flexors"],"st":["Lie on your back with hands behind your head.","Lift your legs a few inches off the floor.","Crunch your shoulders up.","Scissor your legs, crossing one over the other.","Keep your lower back pressed down.","Switch which leg crosses on top each rep."],"img":"opengym/0621.webp","gif":null,"ext":1},{"id":"0622","n":"lying scissor kick","bp":"waist","eq":"body weight","tg":"abs","mg":"hip flexors","sm":["hip flexors","quadriceps"],"st":["Lie on your back with hands under your hips.","Lift both legs a few inches off the floor.","Raise one leg higher while the other stays low.","Switch legs in a smooth scissor motion.","Keep your lower back pressed to the floor.","Breathe steadily throughout."],"img":"opengym/0622.webp","gif":null,"ext":1},{"id":"0623","n":"lying simultaneous alternating leg raise","bp":"waist","eq":"body weight","tg":"abs","mg":"hip flexors","sm":["hip flexors","quadriceps"],"st":["Lie on your back with your arms by your sides.","Raise one leg toward the ceiling while the other hovers near the floor.","Switch the legs at the same time.","Keep both legs mostly straight.","Press your lower back into the floor.","Move at a controlled pace."],"img":"opengym/0623.webp","gif":null,"ext":1},{"id":"0625","n":"medicine ball sit up (wall)","bp":"waist","eq":"medicine ball","tg":"abs","mg":"hip flexors","sm":["hip flexors","shoulders","chest"],"st":["Sit on the floor facing a wall, knees bent, holding a medicine ball.","Lean back and lower your back to the floor.","Sit up and throw the ball at the wall.","Catch it on the rebound.","Lower back down with control.","Repeat for reps."],"img":"opengym/0625.webp","gif":null,"ext":1},{"id":"0629","n":"mountain climber lunge","bp":"full body","eq":"body weight","tg":"cardiovascular system","mg":"quadriceps","sm":["quadriceps","glutes","hip flexors","core","shoulders"],"st":["Start in a plank with hands under your shoulders.","Step one foot forward outside your hand.","Lower your hips into a lunge stretch.","Return the foot back to the plank.","Switch legs.","Keep your core tight and move at a steady pace."],"img":"opengym/0629.webp","gif":null,"ext":1},{"id":"0632","n":"narrow leg bench bridge","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"hamstrings","sm":["hamstrings","core"],"st":["Lie on your back with your feet close together on a bench.","Bend your knees and keep arms by your sides.","Drive through your heels and lift your hips.","Squeeze your glutes at the top.","Hold briefly.","Lower slowly."],"img":"opengym/0632.webp","gif":null,"ext":1},{"id":"0633","n":"neck bridge prone","bp":"neck","eq":"body weight","tg":"levator scapulae","mg":"trapezius","sm":["trapezius","upper back","sternocleidomastoid"],"st":["Kneel on a mat and lean forward so the top of your head rests lightly on the floor.","Place your hands on the floor for support.","Take some weight through your neck by rocking forward and back slowly.","Keep your movements small and controlled.","Return to the start and rest between sets.","Never bounce and keep most weight on your hands at first."],"img":"opengym/0633.webp","gif":null,"ext":1},{"id":"0647","n":"plyo sit squat (wall)","bp":"upper legs","eq":"body weight","tg":"quads","mg":"glutes","sm":["glutes","calves","hamstrings"],"st":["Stand with your back close to a wall, feet shoulder width apart.","Lower into a wall sit with your thighs parallel to the floor.","Drive through your feet and jump up explosively.","Land softly with bent knees.","Drop straight back into the sit and repeat.","Keep your chest tall and land quietly."],"img":"opengym/0647.webp","gif":null,"ext":1},{"id":"0649","n":"pretzel stretch","bp":"waist","eq":"body weight","tg":"abs","mg":"obliques","sm":["obliques","glutes","lower back"],"st":["Lie on one side and bend your top knee.","Pull the bottom foot toward your glutes.","Rotate your top knee back toward the floor behind you.","Keep your shoulders relaxed.","Hold for 20-30 seconds.","Switch sides."],"img":"opengym/0649.webp","gif":null,"ext":1},{"id":"0654","n":"push up (knee chest)","bp":"chest","eq":"body weight","tg":"pectorals","mg":"triceps","sm":["triceps","hip flexors","core","shoulders"],"st":["Start in a plank with your hands under your shoulders.","Lower into a push-up.","Press back up.","Drive one knee toward your chest.","Return that foot to the plank.","Alternate legs each rep."],"img":"opengym/0654.webp","gif":null,"ext":1},{"id":"0657","n":"push up (one arm on stability ball)","bp":"chest","eq":"stability ball","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders","core"],"st":["Get into a push-up position with one hand on a stability ball and one on the floor.","Keep your body in a straight line.","Lower your chest toward the floor.","Press back up.","Keep your core tight.","Finish your reps, then switch the ball hand."],"img":"opengym/0657.webp","gif":null,"ext":1},{"id":"0665","n":"push up w","bp":"chest","eq":"body weight","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders","core"],"st":["Get into a plank and place your hands in a W position.","Keep your body straight from head to heels.","Lower your chest toward the floor.","Keep your elbows angled slightly out.","Press back up.","Repeat without letting your hips sag."],"img":"opengym/0665.webp","gif":null,"ext":1},{"id":"0667","n":"raise single leg push up","bp":"chest","eq":"body weight","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders","glutes","core"],"st":["Start in a push-up position.","Lift one leg off the floor.","Lower your chest toward the floor.","Press back up without twisting your hips.","Keep your body in a line.","Switch the lifted leg every set."],"img":"opengym/0667.webp","gif":null,"ext":1},{"id":"0676","n":"reverse lunge (leg kick)","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","core"],"st":["Stand tall with feet hip-width apart.","Step one leg back into a lunge.","Push through the front heel to stand.","Kick the rear leg forward.","Place the foot down behind you for the next rep.","Finish reps, then switch legs."],"img":"opengym/0676.webp","gif":null,"ext":1},{"id":"0679","n":"rolling bridge","bp":"waist","eq":"body weight","tg":"abs","mg":"glutes","sm":["glutes","hamstrings","lower back"],"st":["Lie on your back with knees bent and feet flat.","Curl your pelvis up and peel your spine off the floor.","Lift to a bridge position.","Pause at the top.","Roll back down one vertebra at a time.","Move slowly and breathe."],"img":"opengym/0679.webp","gif":null,"ext":1},{"id":"0681","n":"rotate push up (on knees)","bp":"waist","eq":"body weight","tg":"pectorals","mg":"triceps","sm":["triceps","obliques","shoulders"],"st":["Start in a push-up position on your knees.","Lower your chest toward the floor.","Press back up.","Rotate your torso and lift one arm toward the ceiling.","Return the arm to the floor.","Alternate sides."],"img":"opengym/0681.webp","gif":null,"ext":1},{"id":"0683","n":"rotational jacks","bp":"full body","eq":"body weight","tg":"cardiovascular system","mg":"obliques","sm":["obliques","calves","shoulders"],"st":["Stand tall with feet together and arms at your sides.","Jump your feet wide and twist your torso to one side.","Jump back together.","Repeat and twist to the other side.","Keep your knees soft.","Maintain a steady pace."],"img":"opengym/0683.webp","gif":null,"ext":1},{"id":"0686","n":"russian twist (on stability ball arms straight)","bp":"waist","eq":"stability ball","tg":"obliques","mg":"core","sm":["core","shoulders","glutes"],"st":["Lie with your upper back on a stability ball.","Lift your hips so your body is flat like a table.","Extend your arms straight above your chest.","Rotate your torso to one side.","Return to center and rotate to the other side.","Keep your hips lifted throughout."],"img":"opengym/0686.webp","gif":null,"ext":1},{"id":"0692","n":"seated single leg hamstring stretch","bp":"upper legs","eq":"body weight","tg":"hamstrings","mg":"calves","sm":["calves","lower back"],"st":["Sit on the floor with one leg straight and the other bent.","Keep your back long.","Hinge forward from the hips and reach toward your toes.","Stop when you feel a stretch.","Hold for 20-30 seconds.","Switch legs."],"img":"opengym/0692.webp","gif":null,"ext":1},{"id":"0693","n":"seated straight leg calf stretch","bp":"lower legs","eq":"body weight","tg":"calves","mg":"soleus","sm":["soleus","hamstrings"],"st":["Sit on the floor with one leg straight.","Loop a towel around the ball of your foot, or hold your toes.","Pull your toes toward you.","Keep your knee straight.","Hold for 20-30 seconds.","Switch legs."],"img":"opengym/0693.webp","gif":null,"ext":1},{"id":"0694","n":"seated twist (on stability ball)","bp":"waist","eq":"stability ball","tg":"obliques","mg":"core","sm":["core","lower back"],"st":["Sit tall on a stability ball with feet flat.","Hold your arms in front of your chest.","Rotate your torso to one side.","Keep your hips facing forward.","Return to center and twist the other way.","Move slowly and controlled."],"img":"opengym/0694.webp","gif":null,"ext":1},{"id":"0698","n":"shoulder press (with band)","bp":"shoulders","eq":"band","tg":"delts","mg":"triceps","sm":["triceps","upper chest","core"],"st":["Stand on the band with feet shoulder-width apart.","Hold the band at shoulder height.","Press your hands overhead until your arms are straight.","Keep your core tight.","Lower slowly back to the shoulders.","Avoid leaning back."],"img":"opengym/0698.webp","gif":null,"ext":1},{"id":"0700","n":"side bend (on stability ball)","bp":"waist","eq":"stability ball","tg":"obliques","mg":"core","sm":["core","lower back"],"st":["Lie sideways over a stability ball with feet braced.","Place your hands behind your head.","Lower your upper body over the ball.","Lift back up by contracting the obliques.","Keep your hips steady.","Finish reps, then switch sides."],"img":"opengym/0700.webp","gif":null,"ext":1},{"id":"0701","n":"side bridge (bent knee)","bp":"waist","eq":"body weight","tg":"obliques","mg":"core","sm":["core","glutes","shoulders"],"st":["Lie on your side with your knees bent.","Place your forearm under your shoulder.","Lift your hips off the floor.","Keep your body in a straight line from knees to head.","Hold for 20-30 seconds.","Lower and switch sides."],"img":"opengym/0701.webp","gif":null,"ext":1},{"id":"0702","n":"side bridge (knee tuck)","bp":"waist","eq":"body weight","tg":"obliques","mg":"core","sm":["core","hip flexors","shoulders"],"st":["Start in a side plank on your forearm.","Raise your top leg slightly.","Pull your top knee toward your chest.","Extend the leg back.","Keep your hips lifted.","Finish reps, then switch sides."],"img":"opengym/0702.webp","gif":null,"ext":1},{"id":"0703","n":"side bridge hip abduction (star)","bp":"upper legs","eq":"body weight","tg":"abductors","mg":"obliques","sm":["obliques","glutes","shoulders"],"st":["Start in a side plank on your forearm.","Keep your body straight.","Lift your top leg toward the ceiling.","Hold briefly.","Lower the leg with control.","Switch sides after your reps."],"img":"opengym/0703.webp","gif":null,"ext":1},{"id":"0706","n":"side bridge","bp":"waist","eq":"body weight","tg":"obliques","mg":"core","sm":["core","glutes","shoulders"],"st":["Lie on your side with legs stacked.","Place your elbow under your shoulder.","Lift your hips until you form a straight line.","Brace your abs.","Hold for 20-30 seconds.","Lower and switch sides."],"img":"opengym/0706.webp","gif":null,"ext":1},{"id":"0707","n":"side crunch v. 2","bp":"waist","eq":"body weight","tg":"obliques","mg":"core","sm":["core","hip flexors"],"st":["Lie on your side with your knees bent.","Place your hands lightly behind your head.","Lift your upper body and legs toward each other.","Squeeze your side.","Lower slowly.","Finish reps, then switch sides."],"img":"opengym/0707.webp","gif":null,"ext":1},{"id":"0708","n":"side crunch","bp":"waist","eq":"body weight","tg":"obliques","mg":"core","sm":["core","hip flexors"],"st":["Lie on your back with knees bent and tilted to one side.","Place your hands behind your head.","Crunch up, lifting your shoulders.","Squeeze your side.","Lower with control.","Finish reps, then switch sides."],"img":"opengym/0708.webp","gif":null,"ext":1},{"id":"0711","n":"side lunge stretch","bp":"upper legs","eq":"body weight","tg":"adductors","mg":"groin","sm":["groin","hamstrings"],"st":["Stand with your feet wide apart.","Shift your weight to one side and bend that knee.","Keep the other leg straight.","Keep your chest up.","Hold for 20-30 seconds.","Switch sides."],"img":"opengym/0711.webp","gif":null,"ext":1},{"id":"0712","n":"side lying feet raise","bp":"upper legs","eq":"body weight","tg":"adductors","mg":"inner thighs","sm":["inner thighs","obliques"],"st":["Lie on your side with legs straight.","Support your head with your arm.","Lift both feet off the floor together.","Hold briefly.","Lower slowly.","Finish reps, then switch sides."],"img":"opengym/0712.webp","gif":null,"ext":1},{"id":"0714","n":"side plank v. 2","bp":"waist","eq":"body weight","tg":"obliques","mg":"core","sm":["core","glutes","shoulders"],"st":["Lie on your side and prop up on your forearm.","Stack your feet or stagger them.","Lift your hips into a straight line.","Keep your core tight.","Hold for 20-30 seconds.","Switch sides."],"img":"opengym/0714.webp","gif":null,"ext":1},{"id":"0715","n":"side plank","bp":"waist","eq":"body weight","tg":"obliques","mg":"abdominals","sm":["abdominals","glutes","shoulders"],"st":["Lie on your side with your elbow under your shoulder and legs stacked.","Lift your hips so your body forms a straight line from head to feet.","Keep your hips high and your neck neutral.","Hold for 20-45 seconds.","Lower with control and switch sides.","Don't let your hips drop or roll forward."],"img":"opengym/0715.webp","gif":null,"ext":1},{"id":"0718","n":"side sit up","bp":"waist","eq":"body weight","tg":"obliques","mg":"core","sm":["core","hip flexors"],"st":["Lie on your back with knees bent.","Place your hands behind your head.","Sit up while reaching one elbow toward the opposite knee.","Lower slowly.","Keep your feet planted.","Alternate sides."],"img":"opengym/0718.webp","gif":null,"ext":1},{"id":"0719","n":"side stretch crunch","bp":"waist","eq":"body weight","tg":"obliques","mg":"core","sm":["core"],"st":["Lie on your side with your bottom arm extended overhead.","Place your top hand behind your head.","Stretch along your side.","Crunch your top elbow toward your hip.","Return to the stretch.","Switch sides."],"img":"opengym/0719.webp","gif":null,"ext":1},{"id":"0722","n":"sideway leg bridge","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"hamstrings","sm":["hamstrings","obliques","core"],"st":["Lie on your back with knees bent.","Lift your hips into a bridge.","Step or shift your legs to one side.","Return to the center.","Alternate sides.","Keep your hips lifted."],"img":"opengym/0722.webp","gif":null,"ext":1},{"id":"0723","n":"sideways lifts vertical (straight legs)","bp":"waist","eq":"body weight","tg":"abs","mg":"obliques","sm":["obliques","core","hip flexors"],"st":["Lie on your back with legs straight up.","Place your arms by your sides.","Lift your hips off the floor.","Tilt your legs slightly to one side.","Lower with control.","Alternate sides."],"img":"opengym/0723.webp","gif":null,"ext":1},{"id":"0724","n":"sideways lifts vertical turn (straight legs)","bp":"waist","eq":"body weight","tg":"abs","mg":"obliques","sm":["obliques","core","hip flexors"],"st":["Lie on your back with legs straight up.","Press your arms into the floor.","Lift your hips and rotate them to one side.","Lower slowly.","Repeat to the other side.","Keep legs straight."],"img":"opengym/0724.webp","gif":null,"ext":1},{"id":"0726","n":"single leg bridge","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"hamstrings","sm":["hamstrings","core"],"st":["Lie on your back with knees bent.","Extend one leg straight.","Drive through the planted heel and lift your hips.","Squeeze your glute at the top.","Lower with control.","Finish reps, then switch legs."],"img":"opengym/0726.webp","gif":null,"ext":1},{"id":"0728","n":"single leg extension (on stability ball)","bp":"upper legs","eq":"stability ball","tg":"quads","mg":"hip flexors","sm":["hip flexors","core","glutes"],"st":["Sit on a stability ball with your feet flat.","Keep your torso tall.","Extend one leg until it is straight.","Hold briefly.","Lower the foot back down.","Finish reps, then switch legs."],"img":"opengym/0728.webp","gif":null,"ext":1},{"id":"0731","n":"single leg sit (wall)","bp":"upper legs","eq":"body weight","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","calves"],"st":["Lean your back against a wall and slide down into a wall sit.","Shift your weight onto one foot.","Lift the other leg and extend it in front of you.","Hold for 10-30 seconds while keeping your back flat on the wall.","Lower the leg and rest, then switch sides.","Keep your standing knee over your ankle."],"img":"opengym/0731.webp","gif":null,"ext":1},{"id":"0733","n":"single leg step up","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","calves"],"st":["Stand in front of a sturdy step.","Place one foot fully on the step.","Press through that heel and stand up.","Bring the other foot up to the step.","Lower slowly.","Finish reps, then switch legs."],"img":"opengym/0733.webp","gif":null,"ext":1},{"id":"0734","n":"sit (wall)","bp":"upper legs","eq":"body weight","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","calves"],"st":["Stand with your back against a wall and walk your feet forward.","Slide down until your knees are bent to about 90 degrees.","Keep your back flat against the wall and your weight on your heels.","Hold the position while breathing steadily.","Hold for 20-60 seconds, then slide back up the wall to finish."],"img":"opengym/0734.webp","gif":null,"ext":1},{"id":"0736","n":"sit up","bp":"waist","eq":"body weight","tg":"abs","mg":"hip flexors","sm":["hip flexors","obliques"],"st":["Lie on your back with knees bent and feet flat.","Cross your arms over your chest or rest your fingertips by your head.","Curl your torso up until your chest nears your thighs.","Lower slowly back to the floor with control.","Avoid yanking on your neck; lead with your chest."],"img":"opengym/0736.webp","gif":null,"ext":1},{"id":"0781","n":"split squat","bp":"upper legs","eq":"body weight","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","calves"],"st":["Stand in a long stride with one foot forward and the other back.","Keep your torso upright and core tight.","Bend both knees and lower until the back knee hovers just above the floor.","Press through the front heel to stand back up.","Finish all reps, then switch legs."],"img":"opengym/0781.webp","gif":null,"ext":1},{"id":"0782","n":"square hop","bp":"cardio","eq":"body weight","tg":"cardiovascular system","mg":"calves","sm":["calves","quadriceps","glutes"],"st":["Imagine a square on the floor and stand at one corner.","Hop on both feet to the next corner, staying light on your toes.","Keep hopping around the square in order.","Land softly with slightly bent knees.","Reverse direction halfway through your set."],"img":"opengym/0782.webp","gif":null,"ext":1},{"id":"0783","n":"squat (arms overhead)","bp":"upper legs","eq":"body weight","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","shoulders","core"],"st":["Stand with feet shoulder-width apart and reach both arms overhead.","Keep your arms in line with your ears and your ribs down.","Sit your hips back and down until your thighs are about parallel to the floor.","Keep your heels down and knees tracking over your toes.","Drive up through your feet to stand tall."],"img":"opengym/0783.webp","gif":null,"ext":1},{"id":"0785","n":"squat jacks","bp":"full body","eq":"body weight","tg":"cardiovascular system","mg":"quadriceps","sm":["quadriceps","glutes","calves"],"st":["Start in a squat with hands together at your chest.","Jump your feet wide while staying low in the squat.","Jump your feet back together, still low.","Keep your chest lifted and knees over your toes.","Continue at a steady, quick pace."],"img":"opengym/0785.webp","gif":null,"ext":1},{"id":"0789","n":"standing hamstring stretch","bp":"upper legs","eq":"body weight","tg":"hamstrings","mg":"calves","sm":["calves","lower back"],"st":["Stand tall and place one heel forward on the floor with the toes up.","Keep that leg straight and the other knee slightly bent.","Hinge forward at the hips with a flat back until you feel a stretch.","Hold for 20-30 seconds.","Switch legs and repeat."],"img":"opengym/0789.webp","gif":null,"ext":1},{"id":"0790","n":"standing hip abduction (bent knee)","bp":"upper legs","eq":"body weight","tg":"abductors","mg":"glutes","sm":["glutes","core"],"st":["Stand tall and hold onto a support if needed.","Shift your weight onto one leg and bend the other knee.","Lift the bent knee out to the side without leaning.","Lower with control.","Finish your reps, then switch sides."],"img":"opengym/0790.webp","gif":null,"ext":1},{"id":"0791","n":"standing hip abduction","bp":"upper legs","eq":"body weight","tg":"abductors","mg":"glutes","sm":["glutes","core"],"st":["Stand tall beside a wall or chair for balance.","Keep your hips square and toes pointing forward.","Lift one leg out to the side with the knee straight.","Pause briefly at the top.","Lower slowly, finish your reps, then switch legs."],"img":"opengym/0791.webp","gif":null,"ext":1},{"id":"0792","n":"standing hip extension (bent knee)","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"hamstrings","sm":["hamstrings","lower back"],"st":["Stand tall holding a support, with your core tight.","Shift onto one leg and bend the other knee.","Press that heel back and up, squeezing your glute.","Do not arch your lower back.","Lower with control, then switch legs after your reps."],"img":"opengym/0792.webp","gif":null,"ext":1},{"id":"0793","n":"band standing lateral raise","bp":"shoulders","eq":"band","tg":"delts","mg":"trapezius","sm":["trapezius","rotator cuff"],"st":["Stand on the middle of the band and hold an end in each hand.","Keep a slight bend in your elbows.","Raise your arms out to the sides to shoulder height.","Lower slowly against the band tension.","Avoid shrugging or swinging your body."],"img":"opengym/0793.webp","gif":null,"ext":1},{"id":"0799","n":"step up crossover","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","obliques"],"st":["Stand facing a sturdy step or box.","Step up with one foot and bring the other knee across your body.","Step back down with control.","Keep your chest tall and core tight.","Alternate sides at a steady pace."],"img":"opengym/0799.webp","gif":null,"ext":1},{"id":"0800","n":"step up opposite elbow to knee twist","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"quadriceps","sm":["quadriceps","obliques","core"],"st":["Stand facing a sturdy step with hands by your head.","Step up with your right foot and drive the left knee up.","Twist to bring your right elbow toward your left knee.","Step down carefully and reset.","Repeat on the other side, alternating."],"img":"opengym/0800.webp","gif":null,"ext":1},{"id":"0801","n":"step up","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","calves"],"st":["Stand facing a sturdy step or bench.","Place one foot fully on it.","Press through that heel to lift your body up until the leg is straight.","Lower back down slowly.","Finish your reps, then switch legs."],"img":"opengym/0801.webp","gif":null,"ext":1},{"id":"0810","n":"toe touch sit (wall)","bp":"upper legs","eq":"body weight","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","core"],"st":["Lean against a wall and slide down into a wall sit.","Hold the squat position with your feet flat.","Reach forward and down with your hands toward your toes.","Return to an upright position against the wall.","Repeat for the set, keeping the sit steady.","Slide back up when finished and keep your knees at about 90 degrees."],"img":"opengym/0810.webp","gif":null,"ext":1},{"id":"0820","n":"twist side bridge","bp":"waist","eq":"body weight","tg":"obliques","mg":"shoulders","sm":["shoulders","core"],"st":["Lie on your side and prop up on one forearm, feet stacked.","Lift your hips so your body forms a straight line.","Reach your top arm under your torso, twisting slightly.","Return to the straight line.","Finish your reps, then switch sides."],"img":"opengym/0820.webp","gif":null,"ext":1},{"id":"0821","n":"twist sit up","bp":"waist","eq":"body weight","tg":"obliques","mg":"abdominals","sm":["abdominals","hip flexors"],"st":["Lie on your back with knees bent and hands by your head.","Curl your torso up off the floor.","Rotate to bring one elbow toward the opposite knee.","Lower back down with control.","Alternate sides each rep."],"img":"opengym/0821.webp","gif":null,"ext":1},{"id":"0822","n":"twist squat","bp":"upper legs","eq":"body weight","tg":"quads","mg":"glutes","sm":["glutes","obliques","core"],"st":["Stand with feet shoulder-width apart and hands together at your chest.","Sit down into a squat.","As you stand, rotate your torso to one side.","Return to the centre and squat again.","Alternate twisting sides."],"img":"opengym/0822.webp","gif":null,"ext":1},{"id":"0823","n":"twisting crunch (arms straight)","bp":"waist","eq":"body weight","tg":"obliques","mg":"abdominals","sm":["abdominals"],"st":["Lie on your back with knees bent and arms extended toward the ceiling.","Curl your shoulders off the floor.","Reach your straight arms toward one side of your knees.","Lower slowly.","Alternate sides, keeping your neck relaxed."],"img":"opengym/0823.webp","gif":null,"ext":1},{"id":"0827","n":"vertical mountain climber","bp":"cardio","eq":"body weight","tg":"cardiovascular system","mg":"core","sm":["core","hip flexors","quadriceps"],"st":["Stand tall with hands raised in front of you at chest height.","Drive one knee up toward your hands.","Switch legs quickly, running in place.","Stay on the balls of your feet.","Keep a steady, brisk pace."],"img":"opengym/0827.webp","gif":null,"ext":1},{"id":"0828","n":"walk (equipment)","bp":"cardio","eq":"body weight","tg":"cardiovascular system","mg":"calves","sm":["calves","glutes","quadriceps","hamstrings"],"st":["Step onto the machine and set a comfortable speed.","Stand tall with your shoulders relaxed.","Swing your arms naturally as you walk.","Land on your heel and roll through to your toes.","Walk for 10-30 minutes at a pace where you can still talk.","Slow down gradually at the end."],"img":"opengym/0828.webp","gif":null,"ext":1},{"id":"0829","n":"walk (high knees)","bp":"cardio","eq":"body weight","tg":"cardiovascular system","mg":"hip flexors","sm":["hip flexors","quadriceps","calves"],"st":["Stand tall with your arms relaxed.","Lift one knee to hip height.","Step down and lift the other knee.","Swing your arms naturally.","Keep a steady rhythm for the set duration."],"img":"opengym/0829.webp","gif":null,"ext":1},{"id":"0831","n":"weighted crunch (bent knee)","bp":"waist","eq":"weighted","tg":"abs","mg":"obliques","sm":["obliques","hip flexors"],"st":["Lie on your back with knees bent and feet flat.","Hold a weight against your chest.","Curl your shoulders up off the floor.","Pause briefly at the top.","Lower slowly and repeat."],"img":"opengym/0831.webp","gif":null,"ext":1},{"id":"0836","n":"weighted leg extension crunch","bp":"waist","eq":"weighted","tg":"abs","mg":"hip flexors","sm":["hip flexors","quadriceps"],"st":["Lie on your back holding a weight at your chest.","Start with knees bent and lifted.","Curl up while straightening your legs forward.","Bring your knees back in as you lower.","Keep your lower back pressed to the floor."],"img":"opengym/0836.webp","gif":null,"ext":1},{"id":"0837","n":"weighted lying hip abduction","bp":"upper legs","eq":"weighted","tg":"abductors","mg":"glutes","sm":["glutes"],"st":["Lie on your side with a weight on your top thigh or ankle.","Keep your body in a straight line.","Lift the top leg up and slightly back.","Lower with control.","Finish your reps, then switch sides."],"img":"opengym/0837.webp","gif":null,"ext":1},{"id":"0838","n":"weighted lying side lifting head (with head harness)","bp":"neck","eq":"weighted","tg":"levator scapulae","mg":"sternocleidomastoid","sm":["sternocleidomastoid","trapezius"],"st":["Lie on your side on a bench with your head just past the edge, wearing a head harness with a light weight.","Let your head hang slightly toward the floor.","Lift your head up toward the ceiling, moving only your neck.","Pause briefly at the top.","Lower slowly and repeat, then switch sides.","Use a light weight and a controlled pace."],"img":"opengym/0838.webp","gif":null,"ext":1},{"id":"0839","n":"weighted lying twist","bp":"waist","eq":"weighted","tg":"obliques","mg":"abdominals","sm":["abdominals","lower back"],"st":["Lie on your back with knees bent and hold a weight above your chest.","Keep your shoulders on the floor.","Lower your knees to one side.","Return to centre and lower to the other side.","Move slowly and keep control."],"img":"opengym/0839.webp","gif":null,"ext":1},{"id":"0842","n":"weighted pullover (on stability ball)","bp":"chest","eq":"weighted","tg":"lats","mg":"chest","sm":["chest","triceps","core"],"st":["Lie with your upper back on the ball, hips lifted.","Hold a weight with both hands above your chest.","Lower it back over your head with slightly bent arms.","Pull it back up over your chest.","Keep your core tight and hips high."],"img":"opengym/0842.webp","gif":null,"ext":1},{"id":"0843","n":"weighted reduction triangle","bp":"upper legs","eq":"weighted","tg":"adductors","mg":"inner thighs","sm":["inner thighs","core"],"st":["Sit or lie with knees bent and a weight resting on your thighs.","Let your knees open into a triangle.","Squeeze your knees together against the weight.","Pause briefly.","Open slowly and repeat."],"img":"opengym/0843.webp","gif":null,"ext":1},{"id":"0848","n":"weighted seated neck extension (with head harness)","bp":"neck","eq":"weighted","tg":"levator scapulae","mg":"trapezius","sm":["trapezius","upper back","sternocleidomastoid"],"st":["Sit on a bench wearing a head harness with a light weight hanging in front.","Lean slightly forward and rest your hands on your thighs.","Let your chin drop toward your chest in a controlled way.","Raise your head back up until your neck is neutral.","Repeat slowly for the set.","Keep your back straight and use a light load."],"img":"opengym/0848.webp","gif":null,"ext":1},{"id":"0855","n":"weighted standing twist","bp":"waist","eq":"weighted","tg":"obliques","mg":"abdominals","sm":["abdominals","shoulders"],"st":["Stand with feet shoulder-width apart holding a weight at your chest.","Keep your hips facing forward.","Rotate your torso to one side.","Return to centre and rotate to the other side.","Move smoothly without jerking."],"img":"opengym/0855.webp","gif":null,"ext":1},{"id":"0867","n":"reverse plank","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"hamstrings","sm":["hamstrings","lower back","shoulders","triceps","core"],"st":["Sit on the floor with legs straight and hands behind your hips, fingers pointing forward.","Press into your hands and heels to lift your hips.","Straighten your body from head to heels.","Squeeze your glutes and keep your shoulders away from your ears.","Hold for 20-45 seconds.","Lower your hips with control."],"img":"opengym/0867.webp","gif":null,"ext":1},{"id":"0878","n":"barbell full squat (with rack)","bp":"upper legs","eq":"barbell","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","adductors","lower back"],"st":["Set the bar at upper chest height in a rack and step under it, resting it on your upper back.","Unrack and step back with your feet shoulder width apart.","Bend your hips and knees and squat down as deep as you comfortably can.","Keep your chest up and knees tracking over your toes.","Drive through your whole foot to stand back up.","Set the safety pins just below your lowest depth."],"img":"opengym/0878.webp","gif":null,"ext":1},{"id":"0880","n":"cable standing hip extension v. 2","bp":"upper legs","eq":"cable","tg":"glutes","mg":"hamstrings","sm":["hamstrings","lower back"],"st":["Attach an ankle strap to a low cable and stand facing the stack.","Hold the frame for support.","Keep your core tight and kick the strapped leg back.","Squeeze your glute at the top.","Return slowly, then switch legs after your reps."],"img":"opengym/0880.webp","gif":null,"ext":1},{"id":"0881","n":"dumbbell curtsey lunge","bp":"upper legs","eq":"dumbbell","tg":"glutes","mg":"quadriceps","sm":["quadriceps","adductors","hamstrings","core"],"st":["Stand tall holding a dumbbell in each hand at your sides.","Step one leg back and across behind the other.","Bend both knees and lower until your front thigh is near parallel.","Keep your chest up and hips square.","Push through your front foot to return to standing.","Repeat on the other side and alternate."],"img":"opengym/0881.webp","gif":null,"ext":1},{"id":"0882","n":"dumbbell one leg squat","bp":"upper legs","eq":"dumbbell","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","core"],"st":["Hold a dumbbell at your chest or by your side.","Stand on one leg with the other lifted in front.","Sit your hips back and lower under control.","Keep your knee in line with your toes.","Press up to stand, then switch legs."],"img":"opengym/0882.webp","gif":null,"ext":1},{"id":"0884","n":"smith lateral step up","bp":"upper legs","eq":"smith machine","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","adductors"],"st":["Place a bench beside you and set the bar across your upper back.","Stand with the bench at your side.","Step up sideways with the near foot.","Straighten your leg to lift your body.","Lower slowly, finish reps, then switch sides."],"img":"opengym/0884.webp","gif":null,"ext":1},{"id":"0885","n":"smith lying lift (on hip)","bp":"upper legs","eq":"smith machine","tg":"abductors","mg":"glutes","sm":["glutes"],"st":["Lie on your side under the bar and set it at a comfortable height.","Place your top foot or leg against the bar.","Lift the leg up smoothly against the resistance.","Lower with control.","Finish your reps, then switch sides."],"img":"opengym/0885.webp","gif":null,"ext":1},{"id":"0886","n":"smith one leg deadlift","bp":"upper legs","eq":"smith machine","tg":"hamstrings","mg":"glutes","sm":["glutes","lower back","core"],"st":["Stand holding the bar at hip height on a single leg.","Keep a slight bend in the standing knee.","Hinge forward, sliding the bar down your leg.","Keep your back flat and extend the free leg behind you.","Drive your hips forward to stand, then switch legs."],"img":"opengym/0886.webp","gif":null,"ext":1},{"id":"0891","n":"band back extension","bp":"back","eq":"band","tg":"spine","mg":"glutes","sm":["glutes","hamstrings"],"st":["Anchor the band and secure it across your upper back.","Hinge forward at the hips with a flat back.","Extend your torso up until your body is in a straight line.","Squeeze your glutes at the top.","Lower slowly and repeat."],"img":"opengym/0891.webp","gif":null,"ext":1},{"id":"0892","n":"band bent over row v. 2","bp":"back","eq":"band","tg":"upper back","mg":"lats","sm":["lats","rhomboids","biceps"],"st":["Stand on the band and hold the ends in your hands.","Hinge forward with a flat back and soft knees.","Pull your elbows back toward your hips.","Squeeze your shoulder blades together.","Lower with control."],"img":"opengym/0892.webp","gif":null,"ext":1},{"id":"0893","n":"band bent over rear lateral raise v. 3","bp":"shoulders","eq":"band","tg":"delts","mg":"rear deltoids","sm":["rear deltoids","rhomboids","trapezius"],"st":["Stand on the band and hold the ends in each hand.","Hinge forward with a flat back.","Raise your arms out to the sides with slightly bent elbows.","Squeeze your shoulder blades at the top.","Lower slowly."],"img":"opengym/0893.webp","gif":null,"ext":1},{"id":"0894","n":"band calf raise","bp":"lower legs","eq":"band","tg":"calves","mg":"soleus","sm":["soleus","ankles"],"st":["Sit or stand with the band looped under the balls of your feet.","Hold the ends firmly.","Press up onto your toes against the band.","Pause at the top.","Lower slowly."],"img":"opengym/0894.webp","gif":null,"ext":1},{"id":"0897","n":"band hammer curl","bp":"upper arms","eq":"band","tg":"biceps","mg":"brachialis","sm":["brachialis","forearms"],"st":["Stand on the band and hold the ends with palms facing in.","Keep your elbows at your sides.","Curl your hands up toward your shoulders.","Pause briefly.","Lower slowly without swinging."],"img":"opengym/0897.webp","gif":null,"ext":1},{"id":"0901","n":"band hip extension","bp":"upper legs","eq":"band","tg":"glutes","mg":"hamstrings","sm":["hamstrings","lower back"],"st":["Loop the band around your ankles or anchor it low.","Stand tall and hold support.","Press one leg straight back against the band.","Squeeze your glute at the top.","Return slowly, then switch legs."],"img":"opengym/0901.webp","gif":null,"ext":1},{"id":"0902","n":"band hyperextension","bp":"back","eq":"band","tg":"spine","mg":"glutes","sm":["glutes","hamstrings"],"st":["Secure the band over your shoulders and under your feet or anchor.","Hinge at the hips with a flat back.","Rise until your torso is in line with your legs.","Squeeze your glutes.","Lower slowly and repeat."],"img":"opengym/0902.webp","gif":null,"ext":1},{"id":"0903","n":"band kickback","bp":"upper arms","eq":"band","tg":"triceps","mg":"shoulders","sm":["shoulders"],"st":["Stand on the band, hinge forward and hold the ends.","Keep your upper arms close to your sides.","Straighten your elbows, pushing your hands back.","Squeeze your triceps at the top.","Bend slowly to return."],"img":"opengym/0903.webp","gif":null,"ext":1},{"id":"0905","n":"band kneeling pulldown","bp":"back","eq":"band","tg":"lats","mg":"biceps","sm":["biceps","rhomboids","core"],"st":["Anchor the band high and kneel facing it.","Grab the ends with arms extended up.","Pull your elbows down toward your ribs.","Squeeze your shoulder blades together.","Return slowly with control."],"img":"opengym/0905.webp","gif":null,"ext":1},{"id":"0906","n":"band kneeling rear kick","bp":"upper legs","eq":"band","tg":"glutes","mg":"hamstrings","sm":["hamstrings","core"],"st":["Get on all fours with the band around one foot and in your hands.","Keep your core tight.","Kick the banded leg back and up.","Squeeze your glute at the top.","Lower slowly, then switch legs."],"img":"opengym/0906.webp","gif":null,"ext":1},{"id":"0907","n":"band lateral raise","bp":"shoulders","eq":"band","tg":"delts","mg":"trapezius","sm":["trapezius","rotator cuff"],"st":["Stand on the band and hold the ends at your sides.","Keep a slight bend in your elbows.","Raise your arms out to shoulder height.","Lower slowly under control.","Avoid shrugging."],"img":"opengym/0907.webp","gif":null,"ext":1},{"id":"0908","n":"band low fly","bp":"chest","eq":"band","tg":"pectorals","mg":"upper chest","sm":["upper chest","shoulders"],"st":["Anchor the band low and stand with a staggered stance.","Hold the ends with arms slightly bent.","Sweep your arms up and together in front of your chest.","Squeeze your chest at the top.","Return slowly."],"img":"opengym/0908.webp","gif":null,"ext":1},{"id":"0909","n":"band lunges","bp":"upper legs","eq":"band","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","calves"],"st":["Stand on the band with the ends held at your shoulders.","Step forward into a long stride.","Lower your back knee toward the floor.","Press through the front heel to return.","Alternate legs."],"img":"opengym/0909.webp","gif":null,"ext":1},{"id":"0910","n":"band lying leg and hip raise","bp":"waist","eq":"band","tg":"abs","mg":"lower abs","sm":["lower abs","hip flexors"],"st":["Lie on your back with the band set around your feet or anchored.","Lift your legs toward the ceiling.","Curl your hips off the floor.","Lower slowly.","Keep your lower back controlled."],"img":"opengym/0910.webp","gif":null,"ext":1},{"id":"0911","n":"band lying leg curl","bp":"upper legs","eq":"band","tg":"hamstrings","mg":"calves","sm":["calves","glutes"],"st":["Lie face down with a band anchored to your ankles.","Keep your hips pressed down.","Curl your heels toward your glutes.","Squeeze your hamstrings.","Lower slowly."],"img":"opengym/0911.webp","gif":null,"ext":1},{"id":"0912","n":"band lying leg raise","bp":"upper legs","eq":"band","tg":"abductors","mg":"hip flexors","sm":["hip flexors","core"],"st":["Lie on your back with the band around your legs.","Keep your legs straight.","Raise one leg against the band.","Lower slowly.","Alternate sides."],"img":"opengym/0912.webp","gif":null,"ext":1},{"id":"0913","n":"band middle fly","bp":"chest","eq":"band","tg":"pectorals","mg":"shoulders","sm":["shoulders","upper chest"],"st":["Anchor the band at chest height and stand facing away.","Hold the ends with slightly bent elbows.","Bring your hands together in front of your chest.","Squeeze your pecs.","Return slowly."],"img":"opengym/0913.webp","gif":null,"ext":1},{"id":"0915","n":"band push up","bp":"chest","eq":"band","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders","core"],"st":["Loop the band across your upper back, holding the ends under your palms.","Set up in a high plank.","Lower your chest toward the floor.","Press back up against the band.","Keep your body in a straight line."],"img":"opengym/0915.webp","gif":null,"ext":1},{"id":"0917","n":"band reverse curl","bp":"lower arms","eq":"band","tg":"forearms","mg":"brachialis","sm":["brachialis","biceps"],"st":["Stand on the band and hold the ends with palms down.","Keep your elbows at your sides.","Curl your hands up toward your shoulders.","Lower slowly.","Avoid swinging."],"img":"opengym/0917.webp","gif":null,"ext":1},{"id":"0919","n":"band single stiff leg deadlift","bp":"upper legs","eq":"band","tg":"hamstrings","mg":"glutes","sm":["glutes","lower back","core"],"st":["Stand on the band on one leg and hold the ends.","Keep a slight bend in the standing knee.","Hinge forward with a flat back and kick the free leg back.","Return by driving your hips forward.","Finish reps, then switch legs."],"img":"opengym/0919.webp","gif":null,"ext":1},{"id":"0921","n":"band standing external shoulder rotation","bp":"shoulders","eq":"band","tg":"delts","mg":"rotator cuff","sm":["rotator cuff","rear deltoids"],"st":["Anchor the band at elbow height and stand sideways to it.","Hold the end with your elbow bent at 90 degrees.","Rotate your forearm outward away from your body.","Return slowly.","Finish reps, then switch arms."],"img":"opengym/0921.webp","gif":null,"ext":1},{"id":"0923","n":"band standing incline chest press","bp":"chest","eq":"band","tg":"pectorals","mg":"upper chest","sm":["upper chest","triceps","shoulders"],"st":["Anchor the band low behind you and hold the ends at your chest.","Step into a staggered stance.","Press your hands up and forward.","Squeeze your chest at the top.","Return slowly."],"img":"opengym/0923.webp","gif":null,"ext":1},{"id":"0924","n":"band standing internal shoulder rotation","bp":"shoulders","eq":"band","tg":"delts","mg":"rotator cuff","sm":["rotator cuff"],"st":["Anchor the band at elbow height and stand sideways to it.","Hold the end with your elbow bent at 90 degrees.","Rotate your forearm across toward your belly.","Return slowly.","Finish reps, then switch arms."],"img":"opengym/0924.webp","gif":null,"ext":1},{"id":"0926","n":"band standing leg extension","bp":"upper legs","eq":"band","tg":"quads","mg":"hip flexors","sm":["hip flexors"],"st":["Anchor the band behind you and loop it around one ankle.","Hold support and lift the knee slightly.","Straighten your knee forward.","Squeeze your quad.","Bend slowly to return, then switch legs."],"img":"opengym/0926.webp","gif":null,"ext":1},{"id":"0927","n":"band standing straight leg raise","bp":"upper legs","eq":"band","tg":"hip flexors","mg":"quadriceps","sm":["quadriceps","core"],"st":["Loop the band around your ankle and anchor it behind you.","Stand tall holding support.","Raise the straight leg forward.","Lower slowly.","Finish reps, then switch legs."],"img":"opengym/0927.webp","gif":null,"ext":1},{"id":"0928","n":"band straight arm pulldown","bp":"back","eq":"band","tg":"lats","mg":"triceps","sm":["triceps","core"],"st":["Anchor the band overhead and stand facing it.","Hold the ends with straight arms.","Pull your hands down toward your thighs.","Squeeze your lats.","Return slowly."],"img":"opengym/0928.webp","gif":null,"ext":1},{"id":"0930","n":"band standing row","bp":"back","eq":"band","tg":"upper back","mg":"lats","sm":["lats","rhomboids","biceps"],"st":["Anchor the band at chest height and hold the ends.","Step back to create tension.","Pull your elbows back past your ribs.","Squeeze your shoulder blades.","Return slowly."],"img":"opengym/0930.webp","gif":null,"ext":1},{"id":"0931","n":"band twist (down up)","bp":"waist","eq":"band","tg":"obliques","mg":"abdominals","sm":["abdominals","shoulders"],"st":["Anchor the band low and hold it with both hands beside the anchor.","Keep your hips facing forward.","Rotate your torso, pulling the band diagonally up.","Return slowly.","Finish reps, then switch sides."],"img":"opengym/0931.webp","gif":null,"ext":1},{"id":"0934","n":"band upright row","bp":"shoulders","eq":"band","tg":"delts","mg":"trapezius","sm":["trapezius","biceps","upper back"],"st":["Stand on the middle of the band with feet hip-width apart and grip the ends with both hands.","Let your arms hang in front of your thighs with the band slightly taut.","Pull your hands up along your body, leading with the elbows, until they reach about chest height.","Pause briefly, then lower under control without letting the band snap back.","Keep your chest tall and your shoulders away from your ears."],"img":"opengym/0934.webp","gif":null,"ext":1},{"id":"0935","n":"band upright shoulder external rotation","bp":"shoulders","eq":"band","tg":"delts","mg":"rotator cuff","sm":["rotator cuff","rear deltoids","upper back"],"st":["Anchor a band at elbow height and stand sideways to it, holding the handle with the far hand.","Tuck your elbow against your side with the elbow bent to 90 degrees.","Rotate your forearm away from your belly, keeping the elbow pinned in place.","Pause when your hand points slightly outward, then return slowly.","Finish all reps, then switch sides."],"img":"opengym/0935.webp","gif":null,"ext":1},{"id":"0938","n":"lever stepper","bp":"cardio","eq":"leverage machine","tg":"cardiovascular system","mg":"quadriceps","sm":["quadriceps","glutes","calves"],"st":["Step onto the pedals and hold the handles lightly for balance.","Push one pedal down while the other rises, keeping a smooth rhythm.","Stand tall and keep your knees pointing forward.","Continue at a comfortable pace for several minutes, adjusting resistance as needed.","Slow down gradually before stepping off."],"img":"opengym/0938.webp","gif":null,"ext":1},{"id":"0942","n":"cat pose","bp":"back","eq":"body weight","tg":"spine","mg":"core","sm":["core","upper back","shoulders"],"st":["Start on all fours with wrists under shoulders and knees under hips.","Exhale and press the floor away as you round your back toward the ceiling.","Tuck your chin toward your chest and draw your belly in.","Hold for 20-30 seconds while breathing slowly.","Inhale and return to a neutral back."],"img":"opengym/0942.webp","gif":null,"ext":1},{"id":"0943","n":"chair pose utkatasana v. 2","bp":"upper legs","eq":"body weight","tg":"quads","mg":"glutes","sm":["glutes","core","shoulders","lower back"],"st":["Stand with feet together and arms at your sides.","Bend your knees and sit your hips back and down as if lowering into a chair.","Reach your arms up beside your ears and lengthen your spine.","Sink a little deeper while keeping your weight in your heels.","Hold for 5 slow breaths, then straighten your legs to stand."],"img":"opengym/0943.webp","gif":null,"ext":1},{"id":"0944","n":"chair pose utkatasana","bp":"upper legs","eq":"body weight","tg":"quads","mg":"glutes","sm":["glutes","core","shoulders","lower back"],"st":["Stand with feet together or hip-width apart.","Bend your knees and send your hips back, keeping your chest lifted.","Raise your arms overhead with palms facing each other.","Keep your knees over your ankles and your tailbone tucked slightly.","Hold for 5 slow breaths, then stand up."],"img":"opengym/0944.webp","gif":null,"ext":1},{"id":"0945","n":"child pose","bp":"back","eq":"body weight","tg":"lats","mg":"lower back","sm":["lower back","glutes","shoulders"],"st":["Kneel on the floor with big toes touching and knees apart.","Sit your hips back toward your heels.","Fold forward and slide your arms out in front of you.","Rest your forehead on the floor and relax your shoulders.","Hold for 20-30 seconds while breathing slowly."],"img":"opengym/0945.webp","gif":null,"ext":1},{"id":"0946","n":"crane pose bakasana","bp":"full body","eq":"body weight","tg":"forearms","mg":"core","sm":["core","shoulders","triceps","wrist flexors"],"st":["Squat with feet together and place your hands flat on the floor shoulder-width apart.","Bend your elbows slightly and rest your shins against the backs of your upper arms.","Shift your weight forward onto your hands and lift one foot, then the other.","Round your upper back, draw your belly in and gaze slightly ahead.","Hold for a few breaths, then lower your feet gently."],"img":"opengym/0946.webp","gif":null,"ext":1},{"id":"0947","n":"crescent moon pose","bp":"waist","eq":"body weight","tg":"abs","mg":"obliques","sm":["obliques","lats","shoulders","core"],"st":["Stand tall with feet together and raise your arms overhead, palms joined.","Reach up through your fingertips and keep your hips level.","Lean your upper body slowly to one side in a gentle curve.","Hold for 3 to 5 breaths without twisting forward or back.","Return to center and repeat on the other side."],"img":"opengym/0947.webp","gif":null,"ext":1},{"id":"0948","n":"default pose","bp":"full body","eq":"body weight","tg":"spine","mg":"core","sm":["core","glutes","calves"],"st":["Stand with feet about hip-width apart and weight even on both feet.","Let your arms hang naturally at your sides.","Lengthen your spine and gently draw your ribs down.","Relax your shoulders and look straight ahead.","Breathe calmly for a few breaths."],"img":"opengym/0948.webp","gif":null,"ext":1},{"id":"0949","n":"downward facing dog adho mukha svanasana","bp":"full body","eq":"body weight","tg":"hamstrings","mg":"calves","sm":["calves","shoulders","lats","core"],"st":["Start on hands and knees with hands slightly ahead of shoulders.","Tuck your toes and lift your hips up and back.","Straighten your legs as far as comfortable and press your chest toward your thighs.","Spread your fingers and push the floor away.","Hold for 20-30 seconds while breathing slowly."],"img":"opengym/0949.webp","gif":null,"ext":1},{"id":"0950","n":"fish pose matsyasana","bp":"chest","eq":"body weight","tg":"pectorals","mg":"hip flexors","sm":["hip flexors","upper back","core"],"st":["Lie on your back with legs straight and arms at your sides, palms down.","Press your forearms into the floor and lift your chest.","Arch your upper back and lower the crown of your head lightly toward the floor.","Keep your legs relaxed and breathe deeply into the chest.","Hold for 15-30 seconds, then lower slowly."],"img":"opengym/0950.webp","gif":null,"ext":1},{"id":"0951","n":"garland pose malasana","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"adductors","sm":["adductors","groin","ankles","lower back"],"st":["Stand with feet slightly wider than hips and toes turned out.","Lower into a deep squat, keeping your heels down if you can.","Bring your palms together at your chest.","Press your elbows against your inner knees and lengthen your spine.","Hold for 20-30 seconds while breathing slowly."],"img":"opengym/0951.webp","gif":null,"ext":1},{"id":"0952","n":"half moon pose ardha chandrasana","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"adductors","sm":["adductors","core","hamstrings","shoulders"],"st":["Start in a wide-legged stance and turn one foot out.","Bend over that leg and place your hand on the floor or a block ahead of the foot.","Lift the back leg until it is parallel to the floor.","Open your chest and stack your hips, reaching the top arm up.","Hold for a few breaths, then lower and switch sides."],"img":"opengym/0952.webp","gif":null,"ext":1},{"id":"0953","n":"hands to feet pada hastasana","bp":"upper legs","eq":"body weight","tg":"hamstrings","mg":"calves","sm":["calves","lower back","core"],"st":["Stand with feet hip-width apart.","Hinge at the hips and fold forward with a long spine.","Slide your hands under your feet with palms up, toes on your fingers.","Pull gently to deepen the stretch while keeping your knees slightly soft.","Hold for 20-30 seconds while breathing slowly."],"img":"opengym/0953.webp","gif":null,"ext":1},{"id":"0954","n":"hero pose virasana","bp":"upper legs","eq":"body weight","tg":"quads","mg":"ankles","sm":["ankles","shins","hip flexors"],"st":["Kneel with knees together and feet slightly wider than your hips.","Sit your hips down between your heels, using a block if needed.","Rest your hands on your thighs and lengthen your spine.","Relax your shoulders and breathe evenly.","Hold for 30-60 seconds, then come out slowly."],"img":"opengym/0954.webp","gif":null,"ext":1},{"id":"0955","n":"leg to side","bp":"upper legs","eq":"body weight","tg":"adductors","mg":"hamstrings","sm":["hamstrings","groin","core"],"st":["Lie on your back with both legs straight.","Lift one leg and let it open out to the side, keeping the other leg down.","Keep your hips squared and your lower back relaxed.","Hold the stretch gently, breathing steadily.","Return to the middle and repeat with the other leg."],"img":"opengym/0955.webp","gif":null,"ext":1},{"id":"0956","n":"lotus yoga pose padmasana","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"hip flexors","sm":["hip flexors","adductors","ankles","core"],"st":["Sit tall with legs stretched out in front of you.","Bend one knee and place that foot high on the opposite thigh.","Bend the other knee and place that foot on top, if your hips allow it.","Rest your hands on your knees and lengthen your spine.","Breathe slowly for 30-60 seconds, then switch which leg goes on top."],"img":"opengym/0956.webp","gif":null,"ext":1},{"id":"0957","n":"revolved side angle pose parivrtta parsvakonasana","bp":"upper legs","eq":"body weight","tg":"quads","mg":"glutes","sm":["glutes","obliques","hamstrings","shoulders"],"st":["Step into a long lunge with the back heel lifted.","Bring your palms together at your chest.","Twist your torso and hook the opposite elbow outside the front knee.","Press your palms together and look up or ahead.","Hold for 3 to 5 breaths, then switch sides."],"img":"opengym/0957.webp","gif":null,"ext":1},{"id":"0958","n":"spread leg forward fold upavista konasana","bp":"upper legs","eq":"body weight","tg":"adductors","mg":"hamstrings","sm":["hamstrings","groin","lower back"],"st":["Sit on the floor with legs spread as wide as is comfortable.","Flex your feet and keep your knees pointing up.","Walk your hands forward and fold from the hips.","Keep your spine long instead of rounding.","Hold for 20-30 seconds while breathing slowly."],"img":"opengym/0958.webp","gif":null,"ext":1},{"id":"0959","n":"standing forward bend uttanasana","bp":"upper legs","eq":"body weight","tg":"hamstrings","mg":"calves","sm":["calves","lower back","core"],"st":["Stand with feet hip-width apart.","Hinge at your hips and fold forward, keeping your knees slightly soft.","Let your hands rest on the floor or hold opposite elbows.","Relax your neck and let the weight of your head drop.","Hold for 20-30 seconds while breathing slowly."],"img":"opengym/0959.webp","gif":null,"ext":1},{"id":"0960","n":"stand spread leg forward fold","bp":"upper legs","eq":"body weight","tg":"adductors","mg":"hamstrings","sm":["hamstrings","groin","lower back"],"st":["Stand with feet wide apart and toes pointing forward.","Hinge forward at the hips with a long spine.","Lower your hands to the floor or your shins.","Relax your head and neck.","Hold for 20-30 seconds while breathing slowly."],"img":"opengym/0960.webp","gif":null,"ext":1},{"id":"0961","n":"tree pose vrksasana","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"adductors","sm":["adductors","core","ankles","calves"],"st":["Stand tall and shift your weight onto one foot.","Place the sole of the other foot on your inner calf or thigh, never on the knee.","Bring your palms together at your chest or raise them overhead.","Fix your eyes on one point to stay steady.","Hold for 5 breaths, then switch legs."],"img":"opengym/0961.webp","gif":null,"ext":1},{"id":"0962","n":"triangle pose trikonasana","bp":"upper legs","eq":"body weight","tg":"hamstrings","mg":"obliques","sm":["obliques","adductors","shoulders","lats"],"st":["Stand with feet wide apart and turn one foot out 90 degrees.","Raise your arms to shoulder height.","Reach toward the front foot, then lower that hand to your shin or the floor.","Extend the other arm up and look toward it.","Hold for 3 to 5 breaths, then switch sides."],"img":"opengym/0962.webp","gif":null,"ext":1},{"id":"0963","n":"warrior pose virabhadrasana v. 2","bp":"upper legs","eq":"body weight","tg":"quads","mg":"glutes","sm":["glutes","adductors","shoulders","core"],"st":["Stand with feet wide and turn your front foot out.","Bend the front knee over the ankle.","Extend your arms out to the sides at shoulder height.","Turn your head to look over the front hand.","Hold for 5 breaths, then switch sides."],"img":"opengym/0963.webp","gif":null,"ext":1},{"id":"0964","n":"warrior pose i virabhadrasana","bp":"upper legs","eq":"body weight","tg":"quads","mg":"glutes","sm":["glutes","hip flexors","shoulders","core"],"st":["Step one foot back into a long stance, with the back foot turned out slightly.","Bend the front knee over the ankle.","Square your hips toward the front.","Raise both arms overhead and lift your chest.","Hold for 5 breaths, then switch sides."],"img":"opengym/0964.webp","gif":null,"ext":1},{"id":"0965","n":"wide legged forward bend prasarita padottanasana","bp":"upper legs","eq":"body weight","tg":"hamstrings","mg":"adductors","sm":["adductors","calves","lower back"],"st":["Stand with feet about one leg-length apart and toes pointing slightly in.","Place your hands on your hips and hinge forward with a flat back.","Lower your hands to the floor under your shoulders.","Let your head hang long.","Hold for 20-30 seconds while breathing slowly."],"img":"opengym/0965.webp","gif":null,"ext":1},{"id":"0966","n":"barbell deadlift (back view)","bp":"upper legs","eq":"barbell","tg":"glutes","mg":"hamstrings","sm":["hamstrings","lower back","upper back","grip muscles"],"st":["Stand with feet hip width apart, bar over mid-foot.","Hinge at the hips and grip the bar just outside your legs.","Brace your core and keep your back flat.","Push the floor away and stand up, keeping the bar close to your legs.","Lock out your hips at the top without leaning back.","Lower the bar by pushing your hips back and bending your knees."],"img":"opengym/0966.webp","gif":null,"ext":1},{"id":"0967","n":"barbell deadlift (front pov)","bp":"upper legs","eq":"barbell","tg":"glutes","mg":"hamstrings","sm":["hamstrings","lower back","upper back","grip muscles"],"st":["Stand with feet hip width apart, bar over mid-foot.","Hinge at the hips and grip the bar just outside your legs.","Brace your core and keep your back flat.","Push the floor away and stand up, keeping the bar close to your legs.","Lock out your hips at the top without leaning back.","Lower the bar by pushing your hips back and bending your knees."],"img":"opengym/0967.webp","gif":null,"ext":1},{"id":"0973","n":"band calf raise v. 2","bp":"lower legs","eq":"band","tg":"calves","mg":"soleus","sm":["soleus","ankles","feet"],"st":["Sit or stand with the band looped under the balls of your feet.","Hold the ends firmly so the band is taut.","Press up onto your toes as high as you can.","Pause at the top, then lower slowly.","Keep your ankles straight and avoid rolling out."],"img":"opengym/0973.webp","gif":null,"ext":1},{"id":"0982","n":"band lying hip external rotation","bp":"upper legs","eq":"band","tg":"glutes","mg":"core","sm":["core"],"st":["Lie on your side with knees bent and a loop band around your thighs just above the knees.","Keep your feet together and your hips stacked.","Rotate the top knee upward, opening like a clamshell.","Pause at the top.","Lower slowly and repeat, then switch sides.","Keep your pelvis still so the movement comes from the hip."],"img":"opengym/0982.webp","gif":null,"ext":1},{"id":"0995","n":"band seated hip external rotation","bp":"upper legs","eq":"band","tg":"glutes","mg":"core","sm":["core"],"st":["Sit on a bench or chair with a band looped around your knees or thighs.","Keep your feet planted and your back tall.","Push your knees apart against the band.","Hold briefly at the widest point.","Bring your knees back together slowly.","Keep your torso still and avoid leaning."],"img":"opengym/0995.webp","gif":null,"ext":1},{"id":"10003","n":"resistance band sitting floor ankle dorsi flexion","bp":"lower legs","eq":"resistance band","tg":"shins","mg":"calves","sm":["calves","ankles","feet"],"st":["Sit on the floor with your legs straight and loop the band around the top of one foot.","Hold the band ends or anchor them so there is light tension.","Pull your toes toward your shin.","Pause, then return slowly.","Complete all reps, then switch feet."],"img":"opengym/10003.webp","gif":null,"ext":1},{"id":"10014","n":"ball assisted lying supine hip adduction","bp":"upper legs","eq":"stability ball","tg":"adductors","mg":"inner thighs","sm":["inner thighs","groin","core"],"st":["Lie on your back with knees bent and a ball between your knees.","Rest your arms by your sides and keep your lower back relaxed.","Squeeze the ball with your inner thighs.","Hold for a moment, then release slowly.","Keep your hips level throughout."],"img":"opengym/10014.webp","gif":null,"ext":1},{"id":"10031","n":"finger flexion while extending thumb","bp":"lower arms","eq":"body weight","tg":"forearms","mg":"wrist flexors","sm":["wrist flexors","hands"],"st":["Hold one hand out with your palm open.","Extend your thumb out to the side and keep it straight.","Curl your four fingers slowly toward your palm.","Open the fingers again.","Repeat 10-15 times, then switch hands.","Keep the movement smooth and pain free."],"img":"opengym/10031.webp","gif":null,"ext":1},{"id":"10032","n":"thumb abduction","bp":"lower arms","eq":"body weight","tg":"forearms","mg":"hands","sm":["hands","wrist extensors"],"st":["Rest your hand on a table with the palm facing up.","Keep your fingers relaxed and straight.","Slowly move your thumb away from your palm.","Pause at the end of the range.","Return slowly to the start.","Do 10-15 reps, then switch hands."],"img":"opengym/10032.webp","gif":null,"ext":1},{"id":"10038","n":"dumbbell wrist supination","bp":"lower arms","eq":"dumbbell","tg":"forearms","mg":"biceps","sm":["biceps","wrist flexors"],"st":["Sit and rest your forearm on your thigh or a bench with the hand hanging free.","Hold a light dumbbell with your palm facing down.","Rotate your forearm so the palm turns up.","Pause at the top.","Rotate back slowly to the start.","Finish your reps, then switch arms. Keep your elbow still."],"img":"opengym/10038.webp","gif":null,"ext":1},{"id":"10040","n":"dumbbell standing alternating cross raise","bp":"shoulders","eq":"dumbbell","tg":"delts","mg":"upper chest","sm":["upper chest","chest","obliques"],"st":["Stand tall with a dumbbell in each hand at your sides.","Raise one arm up and across your body toward the opposite shoulder, elbow slightly bent.","Pause at the top.","Lower with control.","Repeat with the other arm, alternating.","Keep your torso steady and avoid swinging."],"img":"opengym/10040.webp","gif":null,"ext":1},{"id":"10041","n":"dumbbell side plank v. 2","bp":"waist","eq":"dumbbell","tg":"obliques","mg":"abdominals","sm":["abdominals","shoulders","glutes"],"st":["Lie on your side, elbow under your shoulder, with a dumbbell in your top hand.","Lift your hips into a straight line from head to feet.","Hold the dumbbell either at your side or pointing to the ceiling.","Hold for 15-30 seconds.","Lower with control, then switch sides.","Keep your hips high and don't rotate."],"img":"opengym/10041.webp","gif":null,"ext":1},{"id":"10042","n":"dumbbell lying floor squeeze press","bp":"chest","eq":"dumbbell","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders"],"st":["Lie on the floor with a dumbbell in each hand, pressed together above your chest.","Squeeze the dumbbells against each other.","Lower them until your upper arms touch the floor.","Press back up while still squeezing.","Keep your wrists straight and elbows tucked.","Lower slowly each rep."],"img":"opengym/10042.webp","gif":null,"ext":1},{"id":"10043","n":"dumbbell single arm z press","bp":"shoulders","eq":"dumbbell","tg":"delts","mg":"triceps","sm":["triceps","core","obliques","upper back"],"st":["Sit on the floor with legs straight out and back tall.","Hold a dumbbell at shoulder height in one hand.","Press the dumbbell overhead until your arm is straight.","Lower back to your shoulder with control.","Finish your reps and switch arms.","Brace your abs and don't lean back."],"img":"opengym/10043.webp","gif":null,"ext":1},{"id":"10044","n":"dumbbell hang snatch","bp":"full body","eq":"dumbbell","tg":"glutes","mg":"hamstrings","sm":["hamstrings","quadriceps","trapezius","shoulders","core"],"st":["Stand with a dumbbell hanging in front of your thighs, hips hinged slightly.","Drive your hips forward and shrug.","Pull the dumbbell up close to your body.","Punch it overhead and catch it with a straight arm.","Stand tall, then lower back to the hang.","Switch arms and keep the weight light enough to move fast."],"img":"opengym/10044.webp","gif":null,"ext":1},{"id":"10045","n":"snow angel face to floor","bp":"back","eq":"body weight","tg":"spine","mg":"rear deltoids","sm":["rear deltoids","glutes","upper back","trapezius"],"st":["Lie face down with arms by your sides and legs together.","Lift your chest and arms slightly off the floor.","Sweep your arms out and overhead while opening your legs.","Bring them back to the start in the same arc.","Repeat in a smooth rhythm.","Keep your neck long and look at the floor."],"img":"opengym/10045.webp","gif":null,"ext":1},{"id":"10046","n":"snow angel face to sky","bp":"waist","eq":"body weight","tg":"abs","mg":"hip flexors","sm":["hip flexors","shoulders","lower abs"],"st":["Lie on your back with arms by your sides and legs together.","Press your lower back toward the floor.","Sweep your arms overhead while opening your legs.","Bring them back together in the same arc.","Repeat at a steady pace.","Keep your abs braced and lower back flat."],"img":"opengym/10046.webp","gif":null,"ext":1},{"id":"10047","n":"barbell split stance rdl","bp":"upper legs","eq":"barbell","tg":"hamstrings","mg":"glutes","sm":["glutes","lower back","grip muscles","core"],"st":["Hold a barbell at your thighs and stand with one foot a step ahead of the other.","Put most of your weight on the front leg.","Hinge at the hips and slide the bar down your front leg.","Lower until you feel a stretch in your hamstring.","Drive your hips forward to stand tall.","Finish your reps, then switch legs."],"img":"opengym/10047.webp","gif":null,"ext":1},{"id":"10048","n":"cable step up","bp":"upper legs","eq":"cable","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","calves","core"],"st":["Stand facing a box or bench with a cable handle in your hands.","Place one foot fully on the box.","Push through that heel to step up.","Stand tall on top of the box.","Step back down with control.","Finish your reps, then switch legs."],"img":"opengym/10048.webp","gif":null,"ext":1},{"id":"10049","n":"barbell butterfly z press","bp":"shoulders","eq":"barbell","tg":"delts","mg":"triceps","sm":["triceps","upper chest","core"],"st":["Sit on the floor with legs out in front and the bar at upper-chest height.","Take a wide grip and brace your abs.","Press the bar overhead until your arms are straight.","Lower it back to your upper chest under control.","Keep your back tall and avoid arching.","Use a light weight at first."],"img":"opengym/10049.webp","gif":null,"ext":1},{"id":"10050","n":"superman to push up","bp":"full body","eq":"body weight","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders","lower back","glutes","core"],"st":["Lie face down with arms extended in front.","Lift your arms, chest and legs off the floor and hold briefly.","Lower and place your hands under your shoulders.","Press up into a push-up.","Lower your chest back to the floor.","Repeat, keeping your body straight."],"img":"opengym/10050.webp","gif":null,"ext":1},{"id":"10051","n":"bodyweight narrow squat lunge","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","adductors"],"st":["Stand with feet close together and hands on your hips or in front of you.","Step one foot back and lower into a lunge, keeping your feet in a narrow line.","Drop your back knee toward the floor.","Keep your front knee over your ankle and chest up.","Push through the front heel to stand back up.","Switch legs and repeat."],"img":"opengym/10051.webp","gif":null,"ext":1},{"id":"10052","n":"landmine cossack squat","bp":"upper legs","eq":"landmine","tg":"quads","mg":"glutes","sm":["glutes","adductors","hamstrings","core"],"st":["Stand with feet wide, holding the end of a landmine bar at your chest.","Shift to one side and bend that knee deeply.","Keep the other leg straight with the toes up.","Push through the bent leg to return to centre.","Shift to the other side.","Keep your chest tall and heel down on the working side."],"img":"opengym/10052.webp","gif":null,"ext":1},{"id":"10053","n":"jump from seated position","bp":"upper legs","eq":"body weight","tg":"quads","mg":"glutes","sm":["glutes","calves","hamstrings"],"st":["Sit on a sturdy box or bench with feet flat.","Lean slightly forward with arms ready.","Explode upward, swinging your arms.","Land softly on both feet with bent knees.","Sit back down and reset.","Repeat with a short pause each time."],"img":"opengym/10053.webp","gif":null,"ext":1},{"id":"10054","n":"barbell static lunge","bp":"upper legs","eq":"barbell","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","adductors","calves","core"],"st":["Place a barbell across your upper back.","Step into a split stance with one foot forward.","Lower straight down until your back knee nearly touches the floor.","Keep your chest tall and torso upright.","Press through the front heel to rise.","Finish your reps, then switch legs."],"img":"opengym/10054.webp","gif":null,"ext":1},{"id":"10055","n":"dumbbell narrow squat lunge","bp":"upper legs","eq":"dumbbell","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","adductors"],"st":["Stand with feet close together, a dumbbell in each hand at your sides.","Step one foot back and lower into a lunge, keeping your feet in a narrow line.","Drop your back knee toward the floor.","Keep your front knee over your ankle and chest up.","Push through the front heel to stand back up.","Switch legs and repeat."],"img":"opengym/10055.webp","gif":null,"ext":1},{"id":"10056","n":"landmine banded press","bp":"shoulders","eq":"landmine","tg":"delts","mg":"triceps","sm":["triceps","upper chest","core"],"st":["Set up a landmine with a band attached and hold the end of the bar at your shoulder.","Stand with feet staggered and core braced.","Press the bar up and forward until your arm is straight.","Lower it to your shoulder under control.","Finish your reps, then switch arms.","Keep your ribs down and avoid leaning back."],"img":"opengym/10056.webp","gif":null,"ext":1},{"id":"10057","n":"table top bridge jack","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"hamstrings","sm":["hamstrings","triceps","shoulders","core"],"st":["Sit with hands behind you, then lift hips into a tabletop with knees bent.","Squeeze your glutes to keep your hips high.","Hop your feet wide.","Hop them back together.","Keep going at a steady pace.","Keep your hips high and don't let them sag."],"img":"opengym/10057.webp","gif":null,"ext":1},{"id":"10058","n":"alternating kneeling to half kneeling","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hip flexors","core"],"st":["Kneel upright with both knees on the floor.","Step one foot forward into a half-kneeling position.","Pause and keep your torso tall.","Step back to full kneeling.","Repeat with the other foot.","Move slowly and use your arms for balance if needed."],"img":"opengym/10058.webp","gif":null,"ext":1},{"id":"1006","n":"band rear delt row","bp":"shoulders","eq":"band","tg":"delts","mg":"rear deltoids","sm":["rear deltoids","upper back","rhomboids","biceps"],"st":["Anchor a band at chest height and hold the ends with arms extended.","Step back until the band is taut.","Pull your hands toward your chest with elbows high.","Squeeze your shoulder blades together.","Return slowly without letting your shoulders round forward."],"img":"opengym/1006.webp","gif":null,"ext":1},{"id":"10065","n":"lever torso rotation","bp":"waist","eq":"leverage machine","tg":"obliques","mg":"abdominals","sm":["abdominals","lower back"],"st":["Sit in the machine and secure your torso against the pads.","Grip the handles.","Rotate your torso to one side while keeping your hips still.","Pause at the end.","Return to centre and rotate the other way.","Go slowly and avoid momentum."],"img":"opengym/10065.webp","gif":null,"ext":1},{"id":"10092","n":"barbell core squat","bp":"upper legs","eq":"barbell","tg":"quads","mg":"glutes","sm":["glutes","core","lower back","adductors"],"st":["Rest a barbell on your upper back and stand with feet shoulder width apart.","Take a deep breath and brace your abs.","Squat down until your thighs are about parallel.","Keep your torso tight and chest up.","Drive through your feet to stand back up.","Exhale at the top and reset your brace each rep."],"img":"opengym/10092.webp","gif":null,"ext":1},{"id":"10093","n":"dumbbell half kneeling thor lift","bp":"waist","eq":"dumbbell","tg":"abs","mg":"obliques","sm":["obliques","shoulders","glutes","hip flexors"],"st":["Kneel in a half-kneeling position and hold a dumbbell near the outside of your back hip.","Brace your abs and keep your torso upright.","Lift the dumbbell diagonally up and across your body.","Finish with it above the opposite shoulder.","Lower along the same path.","Finish reps, then switch sides."],"img":"opengym/10093.webp","gif":null,"ext":1},{"id":"10094","n":"dumbbell standing cross clean","bp":"shoulders","eq":"dumbbell","tg":"delts","mg":"trapezius","sm":["trapezius","glutes","hamstrings","core","forearms"],"st":["Stand with a dumbbell hanging in front of your thigh, hips hinged slightly.","Drive your hips forward and shrug.","Pull the dumbbell up and across your body.","Catch it at the opposite shoulder.","Lower it back to the hang.","Finish reps, then switch arms."],"img":"opengym/10094.webp","gif":null,"ext":1},{"id":"10095","n":"cable single arm bear fly","bp":"chest","eq":"cable","tg":"pectorals","mg":"shoulders","sm":["shoulders","upper chest","core"],"st":["Set a cable at chest height and stand with a staggered stance.","Grab the handle with one hand and brace your core.","Keep your elbow slightly bent and sweep your arm across your body.","Squeeze your chest at the end.","Return slowly to the start.","Finish reps and switch arms."],"img":"opengym/10095.webp","gif":null,"ext":1},{"id":"10096","n":"dumbbell rear lunge to single arm shoulders press","bp":"upper legs","eq":"dumbbell","tg":"glutes","mg":"quadriceps","sm":["quadriceps","shoulders","triceps","hamstrings","core"],"st":["Hold a dumbbell at one shoulder and stand tall.","Step one leg back into a lunge.","Push through the front foot to stand up.","As you rise, press the dumbbell overhead.","Lower it to your shoulder and repeat.","Switch arms or legs each set."],"img":"opengym/10096.webp","gif":null,"ext":1},{"id":"10097","n":"weighted plate side up squat","bp":"upper legs","eq":"weight plate","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","core","adductors"],"st":["Hold a weight plate at your chest with both hands.","Stand with feet shoulder width apart.","Squat down until your thighs are parallel.","Keep your chest up and elbows in.","Push through your heels to stand.","Keep the plate close to your body."],"img":"opengym/10097.webp","gif":null,"ext":1},{"id":"10106","n":"barbell high pull","bp":"shoulders","eq":"barbell","tg":"traps","mg":"shoulders","sm":["shoulders","biceps","glutes","hamstrings","forearms"],"st":["Hold a barbell at mid-thigh with an overhand grip, hips hinged slightly.","Drive your hips forward and shrug hard.","Pull the bar up to chest height, elbows high.","Let the bar settle and lower it to the thighs.","Reset your stance.","Keep the bar close to your body."],"img":"opengym/10106.webp","gif":null,"ext":1},{"id":"10107","n":"barbell hang clean high pull","bp":"shoulders","eq":"barbell","tg":"traps","mg":"shoulders","sm":["shoulders","biceps","glutes","hamstrings","forearms"],"st":["Hold a barbell just above the knees with an overhand grip.","Hinge at the hips and keep your back flat.","Explode up through the legs and shrug.","Pull the bar to chest height with high elbows.","Lower to the hang position.","Reset and repeat. Keep the bar close."],"img":"opengym/10107.webp","gif":null,"ext":1},{"id":"10108","n":"medicine ball overhead toss","bp":"full body","eq":"medicine ball","tg":"abs","mg":"shoulders","sm":["shoulders","triceps","glutes","hip flexors"],"st":["Stand holding a medicine ball overhead.","Reach back slightly and brace your abs.","Throw the ball forward powerfully.","Follow through with your arms.","Pick up the ball and reset.","Keep your back neutral."],"img":"opengym/10108.webp","gif":null,"ext":1},{"id":"10109","n":"medicine ball backward overhead toss","bp":"full body","eq":"medicine ball","tg":"glutes","mg":"hamstrings","sm":["hamstrings","lower back","shoulders","quadriceps"],"st":["Stand holding a medicine ball in front of your thighs.","Squat down and swing the ball between your legs.","Drive up and extend your hips.","Throw the ball up and backward over your head.","Retrieve the ball and reset.","Keep your arms long and make sure the space behind you is clear."],"img":"opengym/10109.webp","gif":null,"ext":1},{"id":"10110","n":"barbell fat bar reverse curl","bp":"lower arms","eq":"barbell","tg":"forearms","mg":"biceps","sm":["biceps","brachialis","grip muscles"],"st":["Hold a fat barbell with an overhand grip.","Stand with elbows by your sides.","Curl the bar up toward your shoulders.","Squeeze at the top.","Lower slowly.","Keep your wrists straight."],"img":"opengym/10110.webp","gif":null,"ext":1},{"id":"10112","n":"cable seated single arm lats focused row","bp":"back","eq":"cable","tg":"lats","mg":"biceps","sm":["biceps","rhomboids","rear deltoids"],"st":["Sit at the cable station with your feet braced and grab the handle with one hand.","Sit tall and let the arm extend with a slight stretch in the lat.","Pull your elbow down and back toward your hip, leading with the elbow.","Squeeze the lat for a moment, then slowly let the handle return.","Keep your torso still and shoulders down. Finish all reps, then switch arms."],"img":"opengym/10112.webp","gif":null,"ext":1},{"id":"10113","n":"lever isometric squat hip abduction","bp":"upper legs","eq":"leverage machine","tg":"abductors","mg":"glutes","sm":["glutes","quadriceps"],"st":["Set the machine pads against the outsides of your knees.","Lower into a half squat and keep your chest up.","Press your knees outward against the pads.","Hold the position steadily for the target time.","Release and stand up slowly."],"img":"opengym/10113.webp","gif":null,"ext":1},{"id":"10114","n":"weighted plate lu raise","bp":"shoulders","eq":"weight plate","tg":"delts","mg":"upper back","sm":["upper back","trapezius","rotator cuff"],"st":["Stand tall holding a weight plate with both hands at thigh height.","Raise the plate out and up in a wide arc until it is about overhead.","Pause briefly, keeping your ribs down and core tight.","Lower the plate back along the same path with control.","Use a light plate and avoid leaning back."],"img":"opengym/10114.webp","gif":null,"ext":1},{"id":"10115","n":"barbell decline close grip press","bp":"chest","eq":"barbell","tg":"triceps","mg":"chest","sm":["chest","shoulders"],"st":["Lie on a decline bench and grab the bar with hands about shoulder width apart.","Unrack the bar and hold it over your lower chest with locked elbows.","Lower the bar to your lower chest, keeping elbows tucked close.","Press the bar back up until your arms are straight.","Keep your wrists stacked over your elbows and use a spotter."],"img":"opengym/10115.webp","gif":null,"ext":1},{"id":"10116","n":"smith incline close grip bench press","bp":"upper arms","eq":"smith machine","tg":"triceps","mg":"upper chest","sm":["upper chest","shoulders","chest"],"st":["Set an incline bench under the Smith bar and lie back with eyes under the bar.","Grip the bar slightly narrower than shoulder width and unrack it.","Lower the bar to your upper chest with elbows close to your sides.","Press the bar up until your arms are straight.","Keep your feet planted and your shoulder blades pulled back."],"img":"opengym/10116.webp","gif":null,"ext":1},{"id":"10117","n":"dumbbell half kneeling single arm clean press","bp":"shoulders","eq":"dumbbell","tg":"delts","mg":"triceps","sm":["triceps","core","upper back","glutes"],"st":["Kneel on one knee with the dumbbell on the floor by your front foot and grab it.","Pull the dumbbell up to your shoulder in one smooth motion, rotating your wrist.","Press it overhead until your arm is straight.","Lower it back to your shoulder, then to the floor with control.","Keep your torso upright. Finish the reps, then switch sides."],"img":"opengym/10117.webp","gif":null,"ext":1},{"id":"10118","n":"medicine ball overhead slam circle","bp":"full body","eq":"medicine ball","tg":"abs","mg":"lats","sm":["lats","shoulders","glutes","triceps"],"st":["Stand with feet shoulder width apart holding a medicine ball overhead.","Circle the ball to one side and around as you start to bend your knees.","Slam the ball hard into the floor in front of you.","Catch it on the bounce or pick it up, and reset overhead.","Alternate the circle direction every set and keep your core braced."],"img":"opengym/10118.webp","gif":null,"ext":1},{"id":"10119","n":"cable lateral step up","bp":"upper legs","eq":"cable","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","adductors","core"],"st":["Stand sideways to a box with the cable handle held at your chest.","Place the near foot on the box and press through that heel.","Step up until your leg is straight and stand tall on top.","Lower slowly back to the floor with control.","Do all reps on one side, then turn around and switch."],"img":"opengym/10119.webp","gif":null,"ext":1},{"id":"10120","n":"cable unilateral step up","bp":"upper legs","eq":"cable","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","core","calves"],"st":["Face a box with the cable handle held at your chest or by your side.","Place one foot fully on the box.","Drive through that heel and stand up straight on the box.","Lower your trailing foot back to the floor slowly.","Keep your knee tracking over your toes. Finish the reps, then switch legs."],"img":"opengym/10120.webp","gif":null,"ext":1},{"id":"10126","n":"standing isometric shoulder external rotation with towel","bp":"shoulders","eq":"body weight","tg":"delts","mg":"rotator cuff","sm":["rotator cuff","rear deltoids","upper back"],"st":["Stand next to a wall with a towel between the back of your hand and the wall.","Bend your elbow to 90 degrees, tucked at your side.","Press your hand outward into the towel.","Hold the effort for 10 to 20 seconds.","Relax, then switch sides."],"img":"opengym/10126.webp","gif":null,"ext":1},{"id":"10138","n":"standing isometric biceps hold","bp":"upper arms","eq":"body weight","tg":"biceps","mg":"brachialis","sm":["brachialis","forearms"],"st":["Stand tall with feet hip width apart and your elbows at your sides.","Bend your elbows to about 90 degrees with palms facing up.","Squeeze your fists and flex your biceps hard.","Hold the position for 20-30 seconds, breathing steadily.","Keep your shoulders relaxed and elbows pinned, then rest and repeat."],"img":"opengym/10138.webp","gif":null,"ext":1},{"id":"10139","n":"sitting isometric hamstring curl hold with exercise ball","bp":"upper legs","eq":"stability ball","tg":"hamstrings","mg":"glutes","sm":["glutes","calves"],"st":["Sit on the floor with legs out and the ball under your heels.","Lean back on your hands.","Press your heels into the ball and slide it in until knees bend.","Hold the position steadily.","Slowly extend your legs again."],"img":"opengym/10139.webp","gif":null,"ext":1},{"id":"10160","n":"box jump drop 2 foot land","bp":"upper legs","eq":"body weight","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","calves"],"st":["Stand on a sturdy box with your toes near the edge.","Step off the box, do not jump.","Land on both feet at the same time with soft, bent knees.","Sink into a quarter squat to absorb the impact and hold the landing.","Step back up and repeat. Keep your knees in line with your toes."],"img":"opengym/10160.webp","gif":null,"ext":1},{"id":"10168","n":"bodyweight box squat","bp":"upper legs","eq":"body weight","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","core"],"st":["Place a box behind you and stand with feet a bit wider than shoulders.","Push your hips back and bend your knees to lower toward the box.","Lightly touch the box without dropping onto it.","Drive through your heels to stand back up.","Keep your chest up and knees tracking over your toes."],"img":"opengym/10168.webp","gif":null,"ext":1},{"id":"10182","n":"burpee over the dumbbell","bp":"full body","eq":"dumbbell","tg":"cardiovascular system","mg":"quadriceps","sm":["quadriceps","chest","shoulders","core","glutes"],"st":["Stand beside a dumbbell lying on the floor.","Squat down, place your hands on the floor, jump your feet back and do a push up.","Jump your feet forward under your hips.","Jump up and sideways over the dumbbell, landing softly.","Turn and repeat in the other direction at a steady pace."],"img":"opengym/10182.webp","gif":null,"ext":1},{"id":"10183","n":"dumbbell standing front raise twist","bp":"waist","eq":"dumbbell","tg":"obliques","mg":"abdominals","sm":["abdominals","shoulders"],"st":["Stand with feet shoulder width apart, holding a dumbbell in both hands at thigh level.","Raise the dumbbell in front of you to chest height.","Rotate your torso to one side, turning from the ribs while your hips face forward.","Rotate back to the center and lower the dumbbell with control.","Alternate sides each rep and keep the weight light."],"img":"opengym/10183.webp","gif":null,"ext":1},{"id":"10184","n":"resistance band alternating split stance pallof press","bp":"waist","eq":"resistance band","tg":"abs","mg":"obliques","sm":["obliques","core","shoulders"],"st":["Anchor the band at chest height and stand sideways to it in a split stance.","Hold the handle at your chest with both hands.","Press the band straight out in front of you without letting your torso turn.","Hold for a second, then bring the hands back to your chest.","Switch which foot is forward on each set or rep and keep your hips square."],"img":"opengym/10184.webp","gif":null,"ext":1},{"id":"10185","n":"dumbbell bear plank alternating row","bp":"waist","eq":"dumbbell","tg":"abs","mg":"lats","sm":["lats","upper back","obliques","shoulders","biceps"],"st":["Start on all fours with a dumbbell in each hand and knees hovering just off the floor.","Brace your core and keep your back flat.","Row one dumbbell to your ribs without twisting your hips.","Lower it back to the floor with control.","Row with the other arm and keep alternating at a steady pace."],"img":"opengym/10185.webp","gif":null,"ext":1},{"id":"10186","n":"dumbbell pullover to press bridge","bp":"upper legs","eq":"dumbbell","tg":"glutes","mg":"chest","sm":["chest","triceps","lats","hamstrings","core"],"st":["Lie on your back with knees bent and hold a dumbbell over your chest.","Drive through your heels to lift your hips into a bridge.","Lower the dumbbell back overhead in a pullover arc.","Pull it back over your chest and press it straight up.","Lower your hips with control and repeat, keeping your ribs down."],"img":"opengym/10186.webp","gif":null,"ext":1},{"id":"10187","n":"jump up side jump","bp":"full body","eq":"body weight","tg":"quads","mg":"glutes","sm":["glutes","calves","hamstrings","core"],"st":["Stand with feet hip width apart and your knees slightly bent.","Jump straight up, swinging your arms for momentum.","Land softly and immediately hop sideways to one side.","Land on both feet with soft knees and reset your balance.","Alternate the side of each hop and keep a steady rhythm."],"img":"opengym/10187.webp","gif":null,"ext":1},{"id":"10188","n":"standing bend alternating toe touch","bp":"waist","eq":"body weight","tg":"abs","mg":"hamstrings","sm":["hamstrings","obliques","lower back"],"st":["Stand tall with your feet wider than your hips and arms out to the sides.","Hinge forward and twist to reach one hand toward the opposite foot.","Return to standing with arms out.","Reach the other hand to the opposite foot.","Keep a flat back and move at a lively pace."],"img":"opengym/10188.webp","gif":null,"ext":1},{"id":"10189","n":"weighted plate deadlift rear lunge with overhead press","bp":"full body","eq":"weight plate","tg":"glutes","mg":"hamstrings","sm":["hamstrings","quadriceps","shoulders","triceps","core"],"st":["Stand holding a weight plate in front of your thighs.","Hinge at the hips and lower the plate toward your shins, then stand up.","Step one foot back into a reverse lunge as you press the plate overhead.","Return the foot and bring the plate back to your thighs.","Keep a flat back and repeat, alternating the lunging leg."],"img":"opengym/10189.webp","gif":null,"ext":1},{"id":"10190","n":"landmine single arm push press","bp":"shoulders","eq":"landmine","tg":"delts","mg":"triceps","sm":["triceps","core","quadriceps","glutes"],"st":["Stand facing the landmine end and hold it at your shoulder with one hand.","Dip a few inches by bending your knees.","Drive up with your legs and press the bar up and forward until your arm is straight.","Lower the end back to your shoulder with control.","Keep your ribs down and brace your core. Finish the reps, then switch arms."],"img":"opengym/10190.webp","gif":null,"ext":1},{"id":"10191","n":"clock goblet squat","bp":"upper legs","eq":"dumbbell","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","core","adductors"],"st":["Hold a dumbbell at your chest and picture a clock on the floor around you.","Step to 12 o'clock and squat down with your chest up.","Stand up and return to the center.","Step to the next position on the clock and squat again.","Work your way around the clock with control and switch direction on the next set."],"img":"opengym/10191.webp","gif":null,"ext":1},{"id":"10192","n":"kettlebell side swing","bp":"waist","eq":"kettlebell","tg":"obliques","mg":"abdominals","sm":["abdominals","glutes","hamstrings","shoulders"],"st":["Stand with feet wider than shoulders and a kettlebell in both hands.","Hinge at the hips and swing the bell back between your legs.","Snap your hips forward and swing the bell up toward chest height, angled to one side.","Let it swing back down with a flat back.","Finish the reps on one side, then switch."],"img":"opengym/10192.webp","gif":null,"ext":1},{"id":"10193","n":"burpee power sled push","bp":"full body","eq":"sled machine","tg":"cardiovascular system","mg":"quadriceps","sm":["quadriceps","glutes","chest","shoulders","triceps"],"st":["Stand behind a loaded sled and drop into a burpee, chest to the floor.","Jump up to your feet explosively.","Grab the sled handles with your arms extended and lean in.","Drive with short, powerful steps to push the sled for a set distance.","Return and repeat, keeping your back flat while pushing."],"img":"opengym/10193.webp","gif":null,"ext":1},{"id":"10194","n":"butterfly back roll","bp":"back","eq":"body weight","tg":"spine","mg":"core","sm":["core","hamstrings","glutes"],"st":["Sit with the soles of your feet together and knees open.","Hold your feet or ankles.","Roll back slowly along your spine.","Roll forward to sit up again.","Repeat smoothly for 8 to 10 reps."],"img":"opengym/10194.webp","gif":null,"ext":1},{"id":"10195","n":"barbell half kneeling thor lift","bp":"waist","eq":"barbell","tg":"abs","mg":"obliques","sm":["obliques","shoulders","glutes","core"],"st":["Kneel on one knee holding one end of a barbell in a landmine setup near your hip.","Brace your core and stay tall.","Lift the bar diagonally across your body and up toward the opposite shoulder.","Return the bar slowly to the start.","Keep your hips square. Finish the reps, then switch sides."],"img":"opengym/10195.webp","gif":null,"ext":1},{"id":"10196","n":"dumbbell shoulders complex","bp":"shoulders","eq":"dumbbell","tg":"delts","mg":"triceps","sm":["triceps","trapezius","upper back","core"],"st":["Stand with a light dumbbell in each hand at your sides.","Do a set of lateral raises, then straight into front raises.","Move into a set of overhead presses without putting the weights down.","Lower the dumbbells under control and rest.","Keep the weights light and your torso still throughout."],"img":"opengym/10196.webp","gif":null,"ext":1},{"id":"10197","n":"medicine ball horizontal smash","bp":"chest","eq":"medicine ball","tg":"pectorals","mg":"shoulders","sm":["shoulders","triceps","core","obliques"],"st":["Stand sideways to a wall or rebound surface holding a medicine ball at chest height.","Wind the ball slightly away from the target.","Rotate and throw the ball hard against the wall with both hands.","Catch it, reset your stance and go again.","Use your hips and keep your core tight. Finish the reps, then switch sides."],"img":"opengym/10197.webp","gif":null,"ext":1},{"id":"10198","n":"sled alternating single leg negative press","bp":"upper legs","eq":"sled machine","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","calves"],"st":["Sit in the sled with feet on the platform and release the safety.","Press the platform up with both legs and lock out gently.","Shift the load to one leg and lower it slowly for 3-4 seconds.","Press back up with both legs.","Alternate the lowering leg each rep and never let your lower back round."],"img":"opengym/10198.webp","gif":null,"ext":1},{"id":"10199","n":"dumbbell cross romanian deadlift","bp":"upper legs","eq":"dumbbell","tg":"hamstrings","mg":"glutes","sm":["glutes","lower back","forearms","core"],"st":["Stand holding a dumbbell in each hand with a soft bend in the knees.","Push your hips back and lower the weights down your legs.","Reach one dumbbell across toward the opposite foot, keeping your back flat.","Drive your hips forward to stand tall.","Alternate the crossing side each rep."],"img":"opengym/10199.webp","gif":null,"ext":1},{"id":"1020","n":"band side crunch","bp":"waist","eq":"band","tg":"obliques","mg":"core","sm":["core"],"st":["Anchor a band overhead and kneel or stand beside it.","Hold the band at your shoulder with the near hand.","Bend sideways toward your hip.","Return to upright under control.","Finish all reps, then switch sides."],"img":"opengym/1020.webp","gif":null,"ext":1},{"id":"10200","n":"dumbbell kneeling around head rotation","bp":"shoulders","eq":"dumbbell","tg":"delts","mg":"rotator cuff","sm":["rotator cuff","core","upper back"],"st":["Kneel tall holding a dumbbell by one end at chest level.","Circle the dumbbell around your head, keeping it close.","Keep your ribs down and your hips still.","Complete the circle back to the front.","Do a few reps one way, then reverse direction."],"img":"opengym/10200.webp","gif":null,"ext":1},{"id":"1021","n":"band standing leg raise","bp":"upper legs","eq":"band","tg":"hip flexors","mg":"quadriceps","sm":["quadriceps","core","glutes"],"st":["Loop a band around your ankles or one ankle and anchor it.","Stand tall and hold a support if needed.","Lift one straight leg forward to hip height.","Lower slowly.","Complete reps, then switch legs."],"img":"opengym/1021.webp","gif":null,"ext":1},{"id":"1027","n":"assisted single leg press","bp":"upper legs","eq":"leverage machine","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","calves"],"st":["Sit on the machine and place one foot on the platform.","Release the safety and lower the platform until your knee is bent about 90 degrees.","Press through your heel to straighten the leg without locking the knee.","Lower back with control.","Keep your hips on the seat. Finish the reps, then switch legs."],"img":"opengym/1027.webp","gif":null,"ext":1},{"id":"1028","n":"assisted standing triceps dip","bp":"upper arms","eq":"assisted","tg":"triceps","mg":"chest","sm":["chest","shoulders"],"st":["Set the assistance and stand on the pad holding the handles.","Keep your elbows close and your chest up.","Lower your body by bending the elbows until they are at 90 degrees.","Press back up until your arms are straight.","Avoid shrugging your shoulders and move smoothly."],"img":"opengym/1028.webp","gif":null,"ext":1},{"id":"1029","n":"lever parallel chest press","bp":"chest","eq":"leverage machine","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders","upper chest"],"st":["Adjust the seat so the handles are at mid-chest height and sit back.","Grip the handles with your elbows slightly below shoulder level.","Press the handles forward until your arms are almost straight.","Return slowly until you feel a stretch in the chest.","Keep your back against the pad."],"img":"opengym/1029.webp","gif":null,"ext":1},{"id":"10294","n":"heel walk","bp":"lower legs","eq":"body weight","tg":"shins","mg":"calves","sm":["calves","ankles","feet"],"st":["Stand tall with arms relaxed at your sides.","Lift your toes and forefoot off the floor so you balance on your heels.","Walk forward with small, controlled steps.","Keep your toes pulled up the whole time.","Walk for 20-30 seconds, then rest."],"img":"opengym/10294.webp","gif":null,"ext":1},{"id":"1030","n":"lever pec deck fly","bp":"chest","eq":"leverage machine","tg":"pectorals","mg":"shoulders","sm":["shoulders","rear deltoids","chest"],"st":["Sit on the pec deck with your back flat and the arms at chest level.","Place your forearms or hands on the pads with elbows slightly bent.","Bring the arms together in front of your chest.","Squeeze for a moment, then open slowly until you feel a chest stretch.","Keep your shoulders down and back."],"img":"opengym/1030.webp","gif":null,"ext":1},{"id":"1031","n":"lever standing hip extension","bp":"upper legs","eq":"leverage machine","tg":"glutes","mg":"hamstrings","sm":["hamstrings","lower back"],"st":["Stand facing the machine and rest your hands on the support.","Place the back of your working leg against the lever pad.","Push the leg back and slightly up by squeezing the glute.","Return slowly to the start.","Keep your torso upright without arching your back. Finish the reps, then switch legs."],"img":"opengym/1031.webp","gif":null,"ext":1},{"id":"1032","n":"lever alternate biceps curl","bp":"upper arms","eq":"leverage machine","tg":"biceps","mg":"brachialis","sm":["brachialis","forearms"],"st":["Sit with your upper arms resting on the pad and grab the handles.","Curl one handle up toward your shoulder.","Squeeze the biceps at the top.","Lower it slowly while curling the other arm.","Keep your shoulders relaxed and avoid swinging."],"img":"opengym/1032.webp","gif":null,"ext":1},{"id":"10326","n":"plank jump in squat","bp":"full body","eq":"body weight","tg":"quads","mg":"glutes","sm":["glutes","core","shoulders","hamstrings"],"st":["Start in a high plank with hands under shoulders.","Jump both feet forward, landing outside your hands in a wide squat.","Stand or hop up briefly if you like, then lower your hands.","Jump your feet back to the plank.","Keep a tight core and land softly."],"img":"opengym/10326.webp","gif":null,"ext":1},{"id":"10327","n":"kettlebell strong russian twist","bp":"waist","eq":"kettlebell","tg":"obliques","mg":"abdominals","sm":["abdominals","hip flexors","lower back"],"st":["Sit on the floor with knees bent and lean back slightly.","Hold a kettlebell at your chest with both hands.","Rotate your torso to bring the bell beside one hip.","Rotate to the other side in a smooth motion.","Keep your chest lifted and feet raised for more challenge."],"img":"opengym/10327.webp","gif":null,"ext":1},{"id":"10328","n":"lever belt bulgarian split squat","bp":"upper legs","eq":"leverage machine","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","adductors","core"],"st":["Set up in the belt squat machine and place your back foot on the bench behind you.","Stand tall with the front foot far enough forward.","Lower straight down until your front thigh is parallel.","Press through the front heel to stand.","Keep your torso upright. Finish the reps, then switch legs."],"img":"opengym/10328.webp","gif":null,"ext":1},{"id":"10329","n":"dumbbell kroc row","bp":"back","eq":"dumbbell","tg":"upper back","mg":"lats","sm":["lats","biceps","forearms","grip muscles","rear deltoids"],"st":["Stand beside a bench with one hand and knee supported on it and hold a heavy dumbbell.","Let the weight hang with a stretch in the lat.","Row the dumbbell to your hip using controlled momentum.","Lower slowly to a full stretch.","Keep your back flat. Finish the reps, then switch arms."],"img":"opengym/10329.webp","gif":null,"ext":1},{"id":"1033","n":"lever triceps extension v. 2","bp":"upper arms","eq":"leverage machine","tg":"triceps","mg":"forearms","sm":["forearms"],"st":["Sit and adjust the seat so your upper arms rest on the pad.","Grab the handles with your elbows bent.","Press the handles down until your arms are straight.","Squeeze the triceps for a second.","Return slowly without lifting your shoulders."],"img":"opengym/1033.webp","gif":null,"ext":1},{"id":"10330","n":"dumbbell powell raise","bp":"shoulders","eq":"dumbbell","tg":"delts","mg":"rear deltoids","sm":["rear deltoids","upper back","rhomboids"],"st":["Lie on your side on a bench holding a light dumbbell in your top hand.","Start with the arm hanging in front of your body.","Raise the arm out and back in an arc until it is in line with your torso.","Pause briefly, then lower with control.","Use a light weight and switch sides after your set."],"img":"opengym/10330.webp","gif":null,"ext":1},{"id":"10331","n":"resistance band weighted standing pronation twist curl (arm wrestler)","bp":"upper arms","eq":"resistance band","tg":"forearms","mg":"brachialis","sm":["brachialis","wrist flexors"],"st":["Stand on a resistance band and hold the handle with your palm turned to the side.","Curl the handle up while rotating your wrist.","Finish with your palm facing you and the biceps squeezed.","Lower slowly and untwist back to the start.","Keep your elbow tucked. Finish the reps, then switch arms."],"img":"opengym/10331.webp","gif":null,"ext":1},{"id":"1034","n":"lever side hip abduction","bp":"upper legs","eq":"leverage machine","tg":"abductors","mg":"glutes","sm":["glutes","hip flexors"],"st":["Stand next to the machine and place the outer side of your leg against the pad.","Hold the support for balance.","Push your leg out to the side in a smooth motion.","Pause briefly, then return slowly.","Keep your torso upright. Finish the reps, then switch legs."],"img":"opengym/1034.webp","gif":null,"ext":1},{"id":"10345","n":"superman pulse","bp":"back","eq":"body weight","tg":"spine","mg":"glutes","sm":["glutes","hamstrings","rear deltoids"],"st":["Lie face down with arms extended in front.","Lift your arms, chest and legs a few inches.","Pulse them up and down in small movements.","Keep your neck neutral.","Lower and rest after your set."],"img":"opengym/10345.webp","gif":null,"ext":1},{"id":"1035","n":"lever side hip adduction","bp":"upper legs","eq":"leverage machine","tg":"adductors","mg":"inner thighs","sm":["inner thighs","groin"],"st":["Stand next to the machine with the inner side of your leg against the pad.","Hold the support for balance.","Pull your leg across your body, squeezing your inner thigh.","Return slowly to the start.","Keep your hips level and avoid leaning. Finish the reps, then switch legs."],"img":"opengym/1035.webp","gif":null,"ext":1},{"id":"1036","n":"lever standing leg raise","bp":"upper legs","eq":"leverage machine","tg":"hip flexors","mg":"quadriceps","sm":["quadriceps","core"],"st":["Stand facing the machine with your hands on the support.","Place the front of your thigh against the pad.","Raise your leg forward until the thigh is about parallel with the floor.","Lower slowly to the start.","Keep your torso tall. Finish the reps, then switch legs."],"img":"opengym/1036.webp","gif":null,"ext":1},{"id":"10366","n":"resistance band sitting floor tibialis press","bp":"lower legs","eq":"resistance band","tg":"shins","mg":"calves","sm":["calves","ankles","feet"],"st":["Sit on the floor with your legs out and loop a band around your foot, anchored in front.","Keep your leg straight and your heel on the floor.","Pull your toes up toward your shin against the band.","Hold briefly, then slowly release.","Do all reps on one foot, then switch."],"img":"opengym/10366.webp","gif":null,"ext":1},{"id":"10367","n":"kettlebell sitting tibialis press","bp":"lower legs","eq":"kettlebell","tg":"shins","mg":"calves","sm":["calves","ankles","feet"],"st":["Sit on a bench or box with a kettlebell hanging from the top of one foot.","Plant your heel on the floor.","Lift the toes up toward your shin to raise the kettlebell.","Pause, then lower slowly.","Use a light weight. Finish the reps, then switch feet."],"img":"opengym/10367.webp","gif":null,"ext":1},{"id":"1037","n":"lever standing rear kick","bp":"upper legs","eq":"leverage machine","tg":"glutes","mg":"hamstrings","sm":["hamstrings","lower back"],"st":["Stand facing the machine and hold the handles for support.","Place the back of your working leg against the pad.","Kick the leg back by squeezing the glute.","Pause at the top, then return slowly.","Keep your torso upright. Finish the reps, then switch legs."],"img":"opengym/1037.webp","gif":null,"ext":1},{"id":"1038","n":"lever chair squat","bp":"upper legs","eq":"leverage machine","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","calves"],"st":["Position yourself in the machine with the pads on your shoulders and feet shoulder width apart.","Release the safety and brace your core.","Bend your knees and sit back and down.","Drive through your heels to stand back up.","Keep your chest up and knees tracking over your toes."],"img":"opengym/1038.webp","gif":null,"ext":1},{"id":"10383","n":"weighted sandbag deadlift","bp":"upper legs","eq":"sandbag","tg":"glutes","mg":"hamstrings","sm":["hamstrings","lower back","grip muscles","forearms"],"st":["Stand over a sandbag with feet hip width apart.","Hinge at your hips, bend your knees and grip the bag.","Brace your core and drive through your feet to stand tall with the bag.","Push your hips back and lower the bag to the floor.","Keep your back flat throughout."],"img":"opengym/10383.webp","gif":null,"ext":1},{"id":"10384","n":"weighted sandbag squat","bp":"upper legs","eq":"sandbag","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","core","upper back"],"st":["Hold a sandbag in a bear hug against your chest.","Stand with feet shoulder width apart.","Sit back and down into a squat with your chest up.","Drive through your heels to stand up.","Keep the bag tight to your body."],"img":"opengym/10384.webp","gif":null,"ext":1},{"id":"10385","n":"weighted sandbag shouldering","bp":"full body","eq":"sandbag","tg":"glutes","mg":"hamstrings","sm":["hamstrings","lower back","trapezius","quadriceps","upper back"],"st":["Stand over a sandbag and grip it firmly with both hands.","Lift the bag, driving through your legs and hips.","Pull it to your lap, then heave it up onto one shoulder.","Lower it to the floor with control.","Alternate shoulders each rep."],"img":"opengym/10385.webp","gif":null,"ext":1},{"id":"10386","n":"weighted sandbag carry (shoulders)","bp":"full body","eq":"sandbag","tg":"traps","mg":"core","sm":["core","glutes","upper back","forearms"],"st":["Lift the sandbag onto your shoulders and hold it there.","Stand tall with your core braced.","Walk forward with steady, controlled steps.","Keep your ribs stacked over your hips.","Carry for a set distance or time, then set the bag down carefully."],"img":"opengym/10386.webp","gif":null,"ext":1},{"id":"10387","n":"weighted sandbag carry (bear hug)","bp":"full body","eq":"sandbag","tg":"abs","mg":"biceps","sm":["biceps","upper back","glutes","forearms","grip muscles"],"st":["Lift the sandbag and hug it against your chest.","Stand tall with your core braced.","Walk forward with steady steps.","Keep your arms squeezing the bag tight.","Carry for a set distance or time, then lower the bag with care."],"img":"opengym/10387.webp","gif":null,"ext":1},{"id":"10388","n":"weighted sandbag military press","bp":"shoulders","eq":"sandbag","tg":"delts","mg":"triceps","sm":["triceps","upper chest","core","trapezius"],"st":["Hold a sandbag at your upper chest or shoulders.","Stand with feet hip width apart and brace your core.","Press the bag straight overhead.","Lock out the arms, then lower the bag with control.","Keep your ribs down and avoid leaning back."],"img":"opengym/10388.webp","gif":null,"ext":1},{"id":"10389","n":"weighted sandbag row","bp":"back","eq":"sandbag","tg":"upper back","mg":"lats","sm":["lats","biceps","rhomboids","grip muscles","lower back"],"st":["Stand over a sandbag, hinge forward and grab it with both hands.","Keep your back flat and knees slightly bent.","Row the bag toward your lower ribs.","Squeeze your shoulder blades together.","Lower slowly back to full arm extension."],"img":"opengym/10389.webp","gif":null,"ext":1},{"id":"1039","n":"lever full squat","bp":"upper legs","eq":"leverage machine","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","calves","adductors"],"st":["Step into the machine with the pads on your shoulders and feet shoulder width apart.","Release the safety and brace your core.","Squat as deep as you comfortably can.","Drive through your heels to stand.","Keep your chest up and knees over your toes."],"img":"opengym/1039.webp","gif":null,"ext":1},{"id":"1040","n":"lever pistol squat","bp":"upper legs","eq":"leverage machine","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","core","calves"],"st":["Step into the machine and put one foot on the platform with the other leg lifted or extended.","Brace your core and release the safety.","Lower slowly into a deep squat on one leg.","Press through your heel to stand.","Keep your knee in line with your toes. Finish the reps, then switch legs."],"img":"opengym/1040.webp","gif":null,"ext":1},{"id":"1041","n":"lever lying chest press (plate loaded)","bp":"chest","eq":"leverage machine","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders","upper chest"],"st":["Lie back on the machine bench and grip the handles at chest level.","Plant your feet and keep your shoulders pulled back.","Press the handles up until your arms are almost straight.","Lower slowly until you feel a stretch in the chest.","Keep your back on the pad throughout."],"img":"opengym/1041.webp","gif":null,"ext":1},{"id":"10410","n":"steel mace squat (weighted)","bp":"upper legs","eq":"macebell","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","core","lower back"],"st":["Rest the mace on your shoulders and hold it with both hands.","Stand with feet about shoulder width apart.","Sit your hips back and down until your thighs are about parallel.","Keep your chest tall and knees tracking over your toes.","Drive through your feet to stand back up."],"img":"opengym/10410.webp","gif":null,"ext":1},{"id":"10411","n":"steel mace halo (weighted)","bp":"shoulders","eq":"macebell","tg":"delts","mg":"rotator cuff","sm":["rotator cuff","upper back","core","triceps"],"st":["Stand tall with feet shoulder width apart and hold the mace upright near your chest.","Brace your core and keep your ribs down.","Circle the mace around your head in a smooth, controlled arc.","Keep your elbows close and your head still.","Do all reps, then reverse the direction."],"img":"opengym/10411.webp","gif":null,"ext":1},{"id":"1042","n":"weighted lying neck extension","bp":"neck","eq":"weighted","tg":"levator scapulae","mg":"traps","sm":["traps","upper back","trapezius","sternocleidomastoid"],"st":["Lie face down on a bench with your head past the edge and a light weight on the back of your head.","Start with your chin tucked toward your chest.","Slowly lift your head until your neck is in line with your torso.","Pause briefly, then lower with control.","Keep the load light and the motion smooth."],"img":"opengym/1042.webp","gif":null,"ext":1},{"id":"10427","n":"sandbag over the shoulder toss (weighted)","bp":"upper legs","eq":"sandbag","tg":"glutes","mg":"hamstrings","sm":["hamstrings","quadriceps","lower back","core","shoulders"],"st":["Stand over the sandbag with feet shoulder width apart.","Hinge down, grip the bag and keep your back flat.","Drive your hips forward and pull the bag up the front of your body.","Extend fully and throw the bag back over your shoulder.","Reset and repeat, facing the same way."],"img":"opengym/10427.webp","gif":null,"ext":1},{"id":"1043","n":"weighted lying neck flexion","bp":"neck","eq":"weighted","tg":"levator scapulae","mg":"traps","sm":["traps","sternocleidomastoid","upper back"],"st":["Lie on your back on a bench with your head past the edge and a light weight on your forehead.","Hold the weight with a hand for control.","Slowly curl your head up, tucking your chin.","Pause briefly, then lower with control.","Keep the load light and avoid jerking."],"img":"opengym/1043.webp","gif":null,"ext":1},{"id":"10437","n":"cable single arm low row (with rope)","bp":"back","eq":"cable","tg":"upper back","mg":"lats","sm":["lats","rhomboids","biceps","rear deltoids","forearms"],"st":["Attach a rope to a low pulley and sit facing the stack with your feet braced.","Hold the rope in one hand with your arm extended.","Pull your elbow back along your side, squeezing your shoulder blade.","Pause, then let the arm extend slowly.","Finish all reps, then switch sides."],"img":"opengym/10437.webp","gif":null,"ext":1},{"id":"10438","n":"alternating dead hang","bp":"back","eq":"body weight","tg":"lats","mg":"forearms","sm":["forearms","grip muscles","shoulders","core"],"st":["Grab a pull-up bar with an overhand grip, hands about shoulder width apart.","Hang with your arms long and your body relaxed.","Shift your weight toward one hand, letting that side stretch.","Shift to the other side and keep alternating.","Hold the hang for 20-30 seconds in total."],"img":"opengym/10438.webp","gif":null,"ext":1},{"id":"10439","n":"two ropes climb","bp":"back","eq":"rope","tg":"lats","mg":"biceps","sm":["biceps","forearms","grip muscles","core","upper back"],"st":["Grab one rope in each hand and hang with arms long.","Pull up with one arm while you bend your elbow close to your body.","Reach higher with the other hand and pull again.","Keep your core tight and your legs steady.","Climb to a safe height, then lower under control."],"img":"opengym/10439.webp","gif":null,"ext":1},{"id":"1044","n":"plate pinch","bp":"lower arms","eq":"weight plate","tg":"forearms","mg":"grip muscles","sm":["grip muscles","hands","wrist flexors"],"st":["Pick up two smooth plates and stack them with the smooth sides facing out.","Pinch them together with your fingertips and thumb.","Stand tall with your arm hanging by your side.","Hold for 20-30 seconds without letting the plates slip.","Switch hands and repeat."],"img":"opengym/1044.webp","gif":null,"ext":1},{"id":"1045","n":"barbell seated military press (inside squat cage)","bp":"shoulders","eq":"barbell","tg":"delts","mg":"triceps","sm":["triceps","upper chest","trapezius","core"],"st":["Set a bench inside the cage and the bar at shoulder height.","Sit tall, grip the bar just outside shoulder width and unrack it.","Press the bar straight overhead until your arms are extended.","Lower it to your upper chest with control.","Keep your ribs down and your back against the pad."],"img":"opengym/1045.webp","gif":null,"ext":1},{"id":"1046","n":"cable elevated row","bp":"back","eq":"cable","tg":"upper back","mg":"lats","sm":["lats","rhomboids","biceps","rear deltoids"],"st":["Set a cable handle at about head height and take a stable stance.","Grab the handle and lean back slightly with arms extended.","Pull toward your upper chest, driving your elbows back.","Squeeze your shoulder blades together.","Return slowly until your arms are straight."],"img":"opengym/1046.webp","gif":null,"ext":1},{"id":"10462","n":"seated hamstring stretch on a chair","bp":"upper legs","eq":"body weight","tg":"hamstrings","mg":"calves","sm":["calves","lower back"],"st":["Sit near the front edge of a chair.","Extend one leg straight with your heel on the floor and toes up.","Hinge forward from your hips with a flat back until you feel a stretch.","Hold for 20-30 seconds, breathing steadily.","Switch legs and repeat."],"img":"opengym/10462.webp","gif":null,"ext":1},{"id":"10463","n":"seated squeeze shoulder blades chest stretch on a chair","bp":"chest","eq":"body weight","tg":"pectorals","mg":"shoulders","sm":["shoulders","upper back","rhomboids"],"st":["Sit tall on a chair with your feet flat.","Reach your hands behind you and clasp them or hold the chair back.","Pull your shoulder blades together and lift your chest.","Hold for 20-30 seconds without arching your lower back.","Relax and repeat."],"img":"opengym/10463.webp","gif":null,"ext":1},{"id":"1047","n":"cable close grip front lat pulldown","bp":"back","eq":"cable","tg":"lats","mg":"biceps","sm":["biceps","upper back","rhomboids","forearms"],"st":["Sit at the pulldown station and secure your thighs under the pads.","Grab the bar with a close grip.","Lean back slightly and pull the bar down to your upper chest.","Drive your elbows down and squeeze your lats.","Let the bar rise slowly until your arms are straight."],"img":"opengym/1047.webp","gif":null,"ext":1},{"id":"1048","n":"dumbbell lying one arm rear lateral raise v. 2","bp":"shoulders","eq":"dumbbell","tg":"delts","mg":"rear deltoids","sm":["rear deltoids","upper back","rhomboids","trapezius"],"st":["Lie on your side on a bench holding a light dumbbell in your top hand.","Start with your arm hanging in front of you, slight bend in the elbow.","Raise the arm out and up until it is about shoulder height.","Pause, then lower with control.","Finish your reps, then switch sides."],"img":"opengym/1048.webp","gif":null,"ext":1},{"id":"1049","n":"one leg kickback (with bench support)","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"hamstrings","sm":["hamstrings","core","lower back"],"st":["Place your hands on a bench and step back into a hinged position.","Keep your back flat and your core braced.","Kick one leg straight back and up, squeezing your glute.","Lower without letting your hips rotate.","Finish your reps, then switch legs."],"img":"opengym/1049.webp","gif":null,"ext":1},{"id":"1050","n":"smith calf raise (with block)","bp":"lower legs","eq":"smith machine","tg":"calves","mg":"soleus","sm":["soleus","ankles","feet"],"st":["Place a block under the Smith bar and rest the bar on your upper back.","Stand with the balls of your feet on the block.","Lower your heels for a full stretch.","Rise onto your toes as high as you can.","Pause at the top, then lower slowly."],"img":"opengym/1050.webp","gif":null,"ext":1},{"id":"10503","n":"cable reverse narrow grip lat pulldown","bp":"back","eq":"cable","tg":"lats","mg":"biceps","sm":["biceps","upper back","rhomboids","forearms"],"st":["Sit at the pulldown station and secure your thighs.","Grab the bar with a narrow underhand grip.","Lean back a little and pull the bar to your upper chest.","Keep your elbows close to your sides.","Return slowly until your arms are fully extended."],"img":"opengym/10503.webp","gif":null,"ext":1},{"id":"1051","n":"cat stretch","bp":"back","eq":"body weight","tg":"spine","mg":"upper back","sm":["upper back","core","lower abs"],"st":["Start on hands and knees with hands under shoulders.","Tuck your chin and round your back toward the ceiling.","Draw your belly button in and hold for a few breaths.","Return to a neutral spine.","Repeat slowly, holding the rounded position 15-20 seconds."],"img":"opengym/1051.webp","gif":null,"ext":1},{"id":"10517","n":"standing single leg hip swirl with chair support","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"hip flexors","sm":["hip flexors","adductors","core"],"st":["Stand beside a chair and hold it for balance.","Lift one leg slightly off the floor.","Draw slow, controlled circles with your leg.","Do half of the reps one way, then reverse the direction.","Switch legs and repeat."],"img":"opengym/10517.webp","gif":null,"ext":1},{"id":"1052","n":"fixed bar back stretch","bp":"back","eq":"body weight","tg":"lats","mg":"upper back","sm":["upper back","shoulders","lower back"],"st":["Grip a fixed bar or post at about hip height.","Step back until your arms are straight.","Sink your hips back and let your chest drop.","Feel the stretch along your back and sides.","Hold for 20-30 seconds."],"img":"opengym/1052.webp","gif":null,"ext":1},{"id":"10534","n":"seated single leg knee flexion","bp":"upper legs","eq":"body weight","tg":"hamstrings","mg":"calves","sm":["calves","glutes"],"st":["Sit on a chair with your feet flat on the floor.","Slide one foot back under the chair, bending the knee.","Pause briefly at the end of the range.","Return the foot slowly to the start.","Finish your reps, then switch legs."],"img":"opengym/10534.webp","gif":null,"ext":1},{"id":"10535","n":"seated single leg tibialis press","bp":"lower legs","eq":"body weight","tg":"shins","mg":"calves","sm":["calves","ankles","feet"],"st":["Sit with one foot resting flat and the other leg crossed over it.","Hook the toes of the lower foot under your other foot for light resistance.","Lift the toes and forefoot up toward your shin.","Pause at the top, then lower slowly.","Finish your reps, then switch feet."],"img":"opengym/10535.webp","gif":null,"ext":1},{"id":"10536","n":"resistance band standing single leg knee extension","bp":"upper legs","eq":"resistance band","tg":"quads","mg":"core","sm":["core","ankles"],"st":["Anchor a band behind you and loop it around one ankle or behind the knee.","Stand tall and hold on for balance if needed.","Straighten your knee against the band.","Pause with the leg extended.","Bend slowly back, then switch legs after your reps."],"img":"opengym/10536.webp","gif":null,"ext":1},{"id":"10537","n":"seated single leg knee extension","bp":"upper legs","eq":"body weight","tg":"quads","mg":"hip flexors","sm":["hip flexors"],"st":["Sit tall on a chair with your feet flat.","Slowly straighten one knee to lift your foot.","Squeeze your thigh at the top for a second.","Lower the foot back to the floor with control.","Finish your reps, then switch legs."],"img":"opengym/10537.webp","gif":null,"ext":1},{"id":"10538","n":"seated single leg knee extension v. 2","bp":"upper legs","eq":"body weight","tg":"quads","mg":"hip flexors","sm":["hip flexors"],"st":["Sit tall on a chair, holding the seat edge for support.","Straighten one knee until the leg is level.","Hold for a second, tightening your thigh.","Lower slowly to the start.","Finish your reps, then switch legs."],"img":"opengym/10538.webp","gif":null,"ext":1},{"id":"10539","n":"weighted seated single leg knee extension v. 2","bp":"upper legs","eq":"weighted","tg":"quads","mg":"hip flexors","sm":["hip flexors"],"st":["Strap a light ankle weight on and sit tall on a chair.","Hold the seat edge for support.","Straighten the knee until your leg is level.","Hold for a second and squeeze your thigh.","Lower slowly, then switch legs after your reps."],"img":"opengym/10539.webp","gif":null,"ext":1},{"id":"1054","n":"lunging straight leg calf stretch","bp":"lower legs","eq":"body weight","tg":"calves","mg":"soleus","sm":["soleus","hamstrings","ankles"],"st":["Step into a lunge with hands on a wall or knee.","Keep the back leg straight with heel down.","Lean forward until you feel a stretch.","Keep your foot pointing forward.","Hold for 20-30 seconds, then switch sides."],"img":"opengym/1054.webp","gif":null,"ext":1},{"id":"10540","n":"lying bent knee tibialis press","bp":"lower legs","eq":"body weight","tg":"shins","mg":"calves","sm":["calves","ankles","feet"],"st":["Lie on your back with your knees bent and feet flat.","Slide one foot under the other for light resistance.","Lift the toes of the lower foot toward your shin.","Pause at the top, then lower slowly.","Finish your reps, then switch feet."],"img":"opengym/10540.webp","gif":null,"ext":1},{"id":"10541","n":"seated single leg hugging knee flexion","bp":"upper legs","eq":"body weight","tg":"hamstrings","mg":"glutes","sm":["glutes","calves","hip flexors"],"st":["Sit tall on a chair with feet flat.","Lift one knee and clasp your hands around the shin.","Gently pull the knee toward your chest and flex it.","Hold for a moment, then release.","Finish your reps, then switch legs."],"img":"opengym/10541.webp","gif":null,"ext":1},{"id":"10542","n":"seated single leg hugging knee flexion with towel","bp":"upper legs","eq":"body weight","tg":"hamstrings","mg":"glutes","sm":["glutes","calves","hip flexors"],"st":["Sit tall on a chair and loop a towel around one shin.","Hold the towel ends with both hands.","Pull the knee gently toward your chest, bending it.","Hold for a moment, then release.","Finish your reps, then switch legs."],"img":"opengym/10542.webp","gif":null,"ext":1},{"id":"10543","n":"kneeling bend knee chair supported","bp":"upper legs","eq":"body weight","tg":"quads","mg":"hip flexors","sm":["hip flexors","glutes","calves"],"st":["Hold the back of a chair and kneel on one knee on a soft surface.","Keep your torso upright.","Slowly sit back toward your heel to bend the knee.","Stay within a comfortable range.","Return to the start and switch sides after your reps."],"img":"opengym/10543.webp","gif":null,"ext":1},{"id":"10547","n":"standing single leg calf rock","bp":"lower legs","eq":"body weight","tg":"calves","mg":"soleus","sm":["soleus","ankles","feet"],"st":["Stand on one leg next to a wall for balance.","Rock your weight back onto your heel, lifting the toes.","Roll forward onto the ball of your foot.","Keep the movement smooth and controlled.","Finish your reps, then switch legs."],"img":"opengym/10547.webp","gif":null,"ext":1},{"id":"10548","n":"standing single leg concentration calf raise","bp":"lower legs","eq":"body weight","tg":"calves","mg":"soleus","sm":["soleus","ankles","feet"],"st":["Stand on one leg and hold a wall or rail lightly.","Lower your heel slightly for a stretch.","Rise high onto your toes, squeezing the calf.","Pause for a second at the top.","Lower slowly, finish your reps, then switch legs."],"img":"opengym/10548.webp","gif":null,"ext":1},{"id":"10549","n":"elevated single leg bridge","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"hamstrings","sm":["hamstrings","core","lower back"],"st":["Lie on your back with one foot raised on a bench or step.","Extend the other leg straight up.","Drive through your heel and lift your hips.","Squeeze your glute at the top without arching your back.","Lower slowly, finish your reps, then switch legs."],"img":"opengym/10549.webp","gif":null,"ext":1},{"id":"10550","n":"lying floor svend press","bp":"chest","eq":"weight plate","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders","upper chest"],"st":["Lie on your back holding a plate between your palms at your chest.","Squeeze the plate firmly.","Press it straight up until your arms are extended.","Keep squeezing as you lower it back to your chest.","Repeat with steady control."],"img":"opengym/10550.webp","gif":null,"ext":1},{"id":"10551","n":"squat mobilization","bp":"upper legs","eq":"body weight","tg":"quads","mg":"glutes","sm":["glutes","adductors","hip flexors","calves","lower back"],"st":["Stand with feet slightly wider than your shoulders.","Squat down as deep as is comfortable.","Press your elbows against your knees and keep your chest up.","Rock gently side to side.","Stay for 20-30 seconds, then stand."],"img":"opengym/10551.webp","gif":null,"ext":1},{"id":"10552","n":"medicine ball split stance torso twist","bp":"waist","eq":"medicine ball","tg":"obliques","mg":"abdominals","sm":["abdominals","shoulders","glutes"],"st":["Stand in a split stance and hold a medicine ball at chest height.","Brace your core.","Rotate your torso to one side, keeping your hips steady.","Return to the centre and rotate the other way.","Complete all reps, then switch the front foot."],"img":"opengym/10552.webp","gif":null,"ext":1},{"id":"10553","n":"resistance band overhead hit","bp":"chest","eq":"resistance band","tg":"pectorals","mg":"shoulders","sm":["shoulders","core","lats","triceps"],"st":["Anchor a band overhead and hold the handles with both hands.","Stand with a staggered stance and your arms raised.","Pull the handles down and forward in a controlled hit.","Brace your core as you finish.","Return slowly and repeat."],"img":"opengym/10553.webp","gif":null,"ext":1},{"id":"10554","n":"plank alternating hit the ball","bp":"waist","eq":"medicine ball","tg":"abs","mg":"core","sm":["core","shoulders","obliques"],"st":["Start in a straight-arm plank with a ball in front of you.","Tighten your core and glutes.","Lift one hand and tap the ball.","Return the hand and tap with the other.","Keep your hips as still as possible."],"img":"opengym/10554.webp","gif":null,"ext":1},{"id":"10555","n":"seated neck flexion to extension on chair","bp":"neck","eq":"body weight","tg":"levator scapulae","mg":"sternocleidomastoid","sm":["sternocleidomastoid","upper back","trapezius"],"st":["Sit tall on a chair with your shoulders relaxed.","Slowly lower your chin toward your chest.","Gently lift your head and look slightly upward.","Keep the motion smooth and pain free.","Repeat for several slow reps."],"img":"opengym/10555.webp","gif":null,"ext":1},{"id":"10556","n":"seated side to side neck twist on chair","bp":"neck","eq":"body weight","tg":"levator scapulae","mg":"sternocleidomastoid","sm":["sternocleidomastoid","upper back","trapezius"],"st":["Sit tall on a chair with your shoulders relaxed.","Slowly turn your head to look over one shoulder.","Return to the centre.","Turn to the other side.","Repeat for several slow reps."],"img":"opengym/10556.webp","gif":null,"ext":1},{"id":"10557","n":"seated side to side neck bend on chair","bp":"neck","eq":"body weight","tg":"levator scapulae","mg":"sternocleidomastoid","sm":["sternocleidomastoid","upper back","trapezius"],"st":["Sit tall on a chair with your shoulders relaxed.","Slowly tilt your head so your ear moves toward one shoulder.","Return to the centre.","Tilt toward the other shoulder.","Repeat for several slow reps."],"img":"opengym/10557.webp","gif":null,"ext":1},{"id":"10558","n":"medicine ball sit up slam","bp":"waist","eq":"medicine ball","tg":"abs","mg":"lower abs","sm":["lower abs","hip flexors","shoulders","lats"],"st":["Lie on your back with knees bent, holding a medicine ball overhead.","Sit up in one motion, bringing the ball forward.","Slam the ball down in front of your feet.","Catch it on the bounce or pick it up.","Lie back with control and repeat."],"img":"opengym/10558.webp","gif":null,"ext":1},{"id":"10559","n":"dumbbell full front raise catch","bp":"shoulders","eq":"dumbbell","tg":"delts","mg":"upper chest","sm":["upper chest","trapezius","core","forearms"],"st":["Stand tall holding a dumbbell with both hands in front of your thighs.","Raise it straight up in front of you to overhead.","Control it at the top and keep your core braced.","Lower it slowly back down.","Use a moderate weight and avoid arching your back."],"img":"opengym/10559.webp","gif":null,"ext":1},{"id":"1056","n":"lying glute stretch","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"hamstrings","sm":["hamstrings","lower back"],"st":["Lie on your back.","Cross one ankle over the opposite knee.","Pull the bottom leg toward your chest.","Keep your head and shoulders relaxed.","Hold for 20-30 seconds, then switch sides."],"img":"opengym/1056.webp","gif":null,"ext":1},{"id":"10560","n":"barbell bench press catch","bp":"chest","eq":"barbell","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders","upper chest"],"st":["Lie on a bench with a spotter or safety pins set.","Unrack the bar over your chest.","Lower the bar toward your chest under control.","Stop it just above the chest and press up.","Keep your feet planted and your shoulder blades pinched."],"img":"opengym/10560.webp","gif":null,"ext":1},{"id":"10561","n":"kettlebell single leg deadlift pass","bp":"upper legs","eq":"kettlebell","tg":"hamstrings","mg":"glutes","sm":["glutes","lower back","core","forearms"],"st":["Stand on one leg holding a kettlebell in one hand.","Hinge at the hips and reach the bell toward the floor.","Pass the bell to the other hand below your knee.","Stand back up using your glute and hamstring.","Finish your reps, then switch legs."],"img":"opengym/10561.webp","gif":null,"ext":1},{"id":"10562","n":"kettlebell ipsilateral reverse lunge high knee","bp":"upper legs","eq":"kettlebell","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","core","hip flexors"],"st":["Hold a kettlebell in one hand and stand tall.","Step back with the leg on the same side as the bell.","Lower into a lunge.","Drive up and lift that knee high as you stand.","Finish your reps, then switch sides."],"img":"opengym/10562.webp","gif":null,"ext":1},{"id":"10563","n":"knee to box calf stretch","bp":"lower legs","eq":"body weight","tg":"calves","mg":"soleus","sm":["soleus","ankles"],"st":["Place a foot flat a short distance from a box or step.","Keep your heel down.","Push your knee forward to touch the box.","Hold for 20-30 seconds, feeling a calf stretch.","Switch legs and repeat."],"img":"opengym/10563.webp","gif":null,"ext":1},{"id":"10564","n":"seated pronation supination foot","bp":"lower legs","eq":"body weight","tg":"calves","mg":"ankles","sm":["ankles","feet","shins"],"st":["Sit on a chair with one foot lifted slightly off the floor.","Roll the sole of your foot inward.","Roll it outward as far as is comfortable.","Keep the lower leg still.","Finish your reps, then switch feet."],"img":"opengym/10564.webp","gif":null,"ext":1},{"id":"10565","n":"90 to 90 press stretch","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"hip flexors","sm":["hip flexors","adductors","lower back"],"st":["Sit on the floor with both knees bent at 90 degrees, one leg in front, one to the side.","Sit tall.","Hinge forward over the front shin with a flat back.","Hold for 20-30 seconds.","Switch sides and repeat."],"img":"opengym/10565.webp","gif":null,"ext":1},{"id":"10566","n":"half kneeling torso twist","bp":"waist","eq":"body weight","tg":"obliques","mg":"abdominals","sm":["abdominals","hip flexors","glutes","upper back"],"st":["Kneel on one knee with the other foot forward.","Hold your arms crossed in front of your chest.","Rotate your upper body toward the front leg.","Return to the centre and keep your hips square.","Finish your reps, then switch sides."],"img":"opengym/10566.webp","gif":null,"ext":1},{"id":"1058","n":"standing one arm chest stretch","bp":"chest","eq":"body weight","tg":"pectorals","mg":"shoulders","sm":["shoulders","biceps"],"st":["Stand next to a wall or door frame.","Place your forearm or hand on the wall at shoulder height.","Slowly turn your body away from the arm.","Hold for 20-30 seconds.","Switch arms and repeat."],"img":"opengym/1058.webp","gif":null,"ext":1},{"id":"10588","n":"barbell lying front raise","bp":"shoulders","eq":"barbell","tg":"delts","mg":"upper chest","sm":["upper chest","trapezius","triceps"],"st":["Lie on a bench holding a barbell at arm's length over your thighs.","Keep your arms straight with a soft elbow.","Raise the bar in an arc until it is above your chest.","Lower it slowly back down.","Use a light weight and keep your back flat."],"img":"opengym/10588.webp","gif":null,"ext":1},{"id":"10589","n":"stick lying front raise","bp":"shoulders","eq":"body weight","tg":"delts","mg":"upper chest","sm":["upper chest","trapezius","rotator cuff"],"st":["Lie on your back holding a stick with an overhand grip.","Keep your arms straight.","Raise the stick overhead as far as is comfortable.","Return to your thighs slowly.","Keep your ribs down throughout."],"img":"opengym/10589.webp","gif":null,"ext":1},{"id":"1059","n":"standing quadriceps stretch","bp":"upper legs","eq":"body weight","tg":"quads","mg":"hip flexors","sm":["hip flexors","glutes"],"st":["Stand tall and hold something for balance if needed.","Bend one knee and grab your ankle.","Pull your heel toward your glute, knees together.","Hold for 20-30 seconds.","Switch legs and repeat."],"img":"opengym/1059.webp","gif":null,"ext":1},{"id":"10590","n":"walkout lat stretch","bp":"back","eq":"body weight","tg":"lats","mg":"upper back","sm":["upper back","shoulders","core"],"st":["Stand and hinge forward to place your hands on the floor.","Walk your hands out in front of you.","Sit your hips back and press your chest down.","Hold for 20-30 seconds.","Walk your hands back in and stand up."],"img":"opengym/10590.webp","gif":null,"ext":1},{"id":"10591","n":"resistance band seated single leg hugging knee flexion","bp":"upper legs","eq":"band","tg":"hamstrings","mg":"glutes","sm":["glutes","calves","hip flexors"],"st":["Sit tall on a chair with a band around one foot.","Hold the band ends in your hands.","Pull the knee up and bend it toward your chest.","Hold for a moment, then release slowly.","Finish your reps, then switch legs."],"img":"opengym/10591.webp","gif":null,"ext":1},{"id":"10592","n":"half kneeling hamstrings stretch","bp":"upper legs","eq":"body weight","tg":"hamstrings","mg":"calves","sm":["calves","glutes","lower back"],"st":["Kneel on one knee with the other leg extended, heel on the floor.","Keep your toes pointing up.","Hinge forward from your hips with a flat back.","Hold for 20-30 seconds.","Switch legs and repeat."],"img":"opengym/10592.webp","gif":null,"ext":1},{"id":"10593","n":"incline jack plank","bp":"waist","eq":"body weight","tg":"abs","mg":"core","sm":["core","shoulders","hip flexors","glutes"],"st":["Place your hands on a bench in an incline plank.","Brace your core and keep your body straight.","Jump your feet wide.","Jump them back together.","Keep your hips level and the pace steady."],"img":"opengym/10593.webp","gif":null,"ext":1},{"id":"10594","n":"resistance band lateral hit","bp":"chest","eq":"resistance band","tg":"pectorals","mg":"shoulders","sm":["shoulders","triceps","core"],"st":["Anchor the band at chest height beside you and hold the handle at your chest.","Stand tall in a stable stance with your core braced.","Press the handle forward and across your body in a quick controlled motion.","Return slowly to your chest without letting the band pull you around.","Keep your hips square throughout.","Finish all reps, then switch sides."],"img":"opengym/10594.webp","gif":null,"ext":1},{"id":"10595","n":"medicine ball pullover catch","bp":"back","eq":"medicine ball","tg":"lats","mg":"chest","sm":["chest","triceps","core","shoulders"],"st":["Lie on your back with knees bent, holding a medicine ball overhead.","Pull the ball forward over your chest to throw it up toward a partner or wall.","Catch the ball with soft elbows as it returns.","Let it travel back overhead in a controlled arc.","Keep your lower back pressed to the floor.","Repeat at a steady rhythm."],"img":"opengym/10595.webp","gif":null,"ext":1},{"id":"10597","n":"cable 90 degrees internal rotation catch","bp":"shoulders","eq":"cable","tg":"delts","mg":"rotator cuff","sm":["rotator cuff","chest","core"],"st":["Set the cable at shoulder height and stand sideways to it.","Raise your upper arm out to the side with the elbow bent 90 degrees.","Let the cable pull your forearm back into external rotation.","Catch it, then rotate the forearm forward and down smoothly.","Keep your upper arm still and level.","Complete the reps, then switch arms."],"img":"opengym/10597.webp","gif":null,"ext":1},{"id":"10598","n":"medicine ball lying floor close press catch","bp":"chest","eq":"medicine ball","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders","core"],"st":["Lie on your back with knees bent, holding a medicine ball above your chest.","Press the ball up quickly with your hands close together.","Catch it as it comes down with soft elbows.","Lower it to just above your chest.","Keep your back flat and ribs down.","Repeat for controlled, crisp reps."],"img":"opengym/10598.webp","gif":null,"ext":1},{"id":"1061","n":"barbell one leg hip thrust","bp":"upper legs","eq":"barbell","tg":"glutes","mg":"hamstrings","sm":["hamstrings","core","quadriceps"],"st":["Set your upper back on a bench with a padded barbell over your hips.","Extend one leg or hold it bent in the air.","Drive through the planted heel to lift your hips level.","Squeeze your glute at the top without twisting.","Lower under control.","Finish the reps, then switch legs."],"img":"opengym/1061.webp","gif":null,"ext":1},{"id":"1062","n":"weighted one leg hip thrust","bp":"upper legs","eq":"weighted","tg":"glutes","mg":"hamstrings","sm":["hamstrings","core","quadriceps"],"st":["Rest your upper back on a bench and place the weight on your hips.","Plant one foot and lift the other leg off the floor.","Push through your heel to raise your hips until your torso is level.","Pause and squeeze your glute.","Lower slowly.","Complete the reps, then change legs."],"img":"opengym/1062.webp","gif":null,"ext":1},{"id":"1063","n":"barbell sumo squat","bp":"upper legs","eq":"barbell","tg":"glutes","mg":"adductors","sm":["adductors","quadriceps","hamstrings","core"],"st":["Set the bar on your upper back and stand with feet well wider than your shoulders.","Turn your toes out about 30 degrees.","Brace your core and sit down between your legs.","Keep your knees tracking over your toes.","Descend to thigh level or lower, then push through your heels to stand.","Keep your chest tall."],"img":"opengym/1063.webp","gif":null,"ext":1},{"id":"10639","n":"glute ham developer full sit up","bp":"waist","eq":"leverage machine","tg":"abs","mg":"hip flexors","sm":["hip flexors","lower back","glutes"],"st":["Lock your feet in the machine and sit with your hips on the pad.","Lean back until your torso is in line with or just below your hips.","Cross your arms over your chest.","Curl up until your chest reaches your thighs.","Lower back slowly with a braced core.","Avoid yanking on your neck."],"img":"opengym/10639.webp","gif":null,"ext":1},{"id":"1064","n":"sumo squat","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"adductors","sm":["adductors","quadriceps","hamstrings","core"],"st":["Stand with feet wide and toes turned out.","Hold your hands together at your chest.","Sit your hips down and back between your legs.","Keep your knees over your toes and chest upright.","Lower to thigh level.","Push through your heels to stand and squeeze your glutes."],"img":"opengym/1064.webp","gif":null,"ext":1},{"id":"10646","n":"lever incline prone row","bp":"back","eq":"leverage machine","tg":"upper back","mg":"lats","sm":["lats","rhomboids","biceps","rear deltoids"],"st":["Lie chest-down on the incline pad and grab the handles.","Let your arms extend fully.","Pull the handles back, driving your elbows toward your hips.","Squeeze your shoulder blades together.","Lower slowly until your arms are straight.","Keep your head neutral."],"img":"opengym/10646.webp","gif":null,"ext":1},{"id":"1065","n":"lying hip lift (on stability ball)","bp":"upper legs","eq":"stability ball","tg":"glutes","mg":"hamstrings","sm":["hamstrings","core","lower back"],"st":["Lie on your back with your heels resting on the stability ball.","Press your arms into the floor for support.","Lift your hips until your body forms a straight line.","Squeeze your glutes at the top.","Lower your hips under control.","Keep the ball steady throughout."],"img":"opengym/1065.webp","gif":null,"ext":1},{"id":"10650","n":"resistance band explosive push up","bp":"chest","eq":"resistance band","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders","core"],"st":["Loop the band across your upper back and hold the ends under your palms.","Set up in a push-up position with a straight body.","Lower your chest to the floor with control.","Push up hard so your hands briefly leave the floor.","Land softly with elbows slightly bent.","Keep your hips in line."],"img":"opengym/10650.webp","gif":null,"ext":1},{"id":"10651","n":"band standing on bosu ball single leg abduction","bp":"upper legs","eq":"band","tg":"abductors","mg":"glutes","sm":["glutes","core","ankles"],"st":["Place a band around your ankles and stand on the bosu with one foot.","Hold your core tight and stay tall.","Lift your free leg out to the side against the band.","Pause briefly at the top.","Return slowly without leaning.","Finish the reps, then switch legs."],"img":"opengym/10651.webp","gif":null,"ext":1},{"id":"10654","n":"pilates machine lying knee extension on toes","bp":"upper legs","eq":"leverage machine","tg":"quads","mg":"calves","sm":["calves","core"],"st":["Lie on the carriage with feet on the bar, on your toes.","Bend your knees with a neutral spine.","Press the carriage away until legs straighten.","Return under control.","Keep your hips still."],"img":"opengym/10654.webp","gif":null,"ext":1},{"id":"10655","n":"pilates machine lying knee extension","bp":"upper legs","eq":"leverage machine","tg":"quads","mg":"calves","sm":["calves","core"],"st":["Lie on the carriage with feet on the bar.","Bend your knees.","Press out until legs are straight.","Return slowly.","Keep your lower back stable."],"img":"opengym/10655.webp","gif":null,"ext":1},{"id":"10656","n":"pilates machine lying knee extension on heels","bp":"upper legs","eq":"leverage machine","tg":"quads","mg":"hamstrings","sm":["hamstrings","core"],"st":["Lie on the carriage with heels on the bar.","Bend your knees.","Press out through the heels until straight.","Return slowly.","Keep your hips level."],"img":"opengym/10656.webp","gif":null,"ext":1},{"id":"10657","n":"pilates machine lying calf raise","bp":"upper legs","eq":"leverage machine","tg":"calves","mg":"soleus","sm":["soleus","ankles"],"st":["Lie on the carriage with legs straight, balls of feet on the bar.","Press your heels down.","Rise up onto your toes.","Return slowly.","Keep your knees locked softly."],"img":"opengym/10657.webp","gif":null,"ext":1},{"id":"10658","n":"pilates machine hundred","bp":"waist","eq":"leverage machine","tg":"abs","mg":"lower abs","sm":["lower abs","hip flexors","core"],"st":["Lie on the carriage holding the straps.","Lift your head and legs.","Pump your arms in small movements.","Breathe in for five counts and out for five.","Continue for 100 pumps."],"img":"opengym/10658.webp","gif":null,"ext":1},{"id":"10660","n":"resistance band assisted single arm pull up","bp":"back","eq":"resistance band","tg":"lats","mg":"biceps","sm":["biceps","upper back","forearms","core"],"st":["Loop a band over the bar and place your foot or knee in it.","Hang with one hand on the bar and the other holding your wrist or the band.","Pull your chin toward the bar, driving the elbow down.","Pause at the top.","Lower with control to a full hang.","Switch arms after each set."],"img":"opengym/10660.webp","gif":null,"ext":1},{"id":"10661","n":"ring resistance band assisted single arm pull up","bp":"back","eq":"suspension trainer","tg":"lats","mg":"biceps","sm":["biceps","upper back","forearms","core"],"st":["Hang a band from the rings or bar and place your foot in it.","Grip one ring with one hand and hold the other ring loosely or let it go.","Pull your chest toward the ring.","Keep your body tight and avoid swinging.","Lower slowly to a full hang.","Repeat, then switch sides."],"img":"opengym/10661.webp","gif":null,"ext":1},{"id":"10662","n":"ring rocky pull up pulldown","bp":"back","eq":"suspension trainer","tg":"lats","mg":"biceps","sm":["biceps","upper back","core","forearms"],"st":["Hang from the rings with arms straight and shoulders engaged.","Pull your chest up toward the rings.","At the top, drive the rings down toward your hips.","Pause with your arms close to your sides.","Return to the top, then lower slowly.","Keep your core braced."],"img":"opengym/10662.webp","gif":null,"ext":1},{"id":"10663","n":"ring skin the cat","bp":"back","eq":"suspension trainer","tg":"upper back","mg":"shoulders","sm":["shoulders","lats","core","biceps"],"st":["Hang from the rings with a firm grip.","Tuck your knees and lift your hips overhead.","Rotate backward, passing your legs between your arms.","Lower your feet toward the floor until you stretch your shoulders.","Pause, then reverse the motion with control.","Move slowly and stop if you feel pinching."],"img":"opengym/10663.webp","gif":null,"ext":1},{"id":"10664","n":"planche press","bp":"shoulders","eq":"body weight","tg":"delts","mg":"chest","sm":["chest","core","triceps","wrist flexors"],"st":["Start in a deep planche lean with hands under your shoulders.","Protract your shoulders and squeeze your glutes.","Lean forward and lift your feet from the floor.","Press into the ground and hold the position.","Lower under control.","Warm up your wrists first."],"img":"opengym/10664.webp","gif":null,"ext":1},{"id":"10665","n":"elbow planche","bp":"shoulders","eq":"body weight","tg":"delts","mg":"core","sm":["core","chest","triceps","wrist flexors"],"st":["Place your hands on the floor and tuck your elbows into your waist.","Lean forward over your hands.","Lift your feet off the floor one at a time.","Hold your body level with a tight core.","Keep your shoulders pressed forward.","Lower down after the hold."],"img":"opengym/10665.webp","gif":null,"ext":1},{"id":"10667","n":"cable kneeling single arm horizontal row","bp":"back","eq":"cable","tg":"upper back","mg":"lats","sm":["lats","rhomboids","biceps","core"],"st":["Set a cable at chest height and kneel facing it.","Hold the handle with one hand and brace your core.","Pull your elbow back along your side.","Squeeze your shoulder blade toward your spine.","Extend the arm slowly.","Complete the reps, then switch arms."],"img":"opengym/10667.webp","gif":null,"ext":1},{"id":"10668","n":"band kneeling single arm horizontal row","bp":"back","eq":"band","tg":"upper back","mg":"lats","sm":["lats","rhomboids","biceps","core"],"st":["Anchor a band at chest height and kneel facing it.","Hold the band with one hand and keep your torso upright.","Pull the elbow back past your ribs.","Squeeze your shoulder blade in.","Return slowly against the tension.","Switch arms after the set."],"img":"opengym/10668.webp","gif":null,"ext":1},{"id":"10669","n":"lever stack seated incline chest press","bp":"chest","eq":"leverage machine","tg":"pectorals","mg":"upper chest","sm":["upper chest","triceps","shoulders"],"st":["Adjust the seat so the handles are at upper-chest height.","Sit back with your feet flat and shoulder blades pinched.","Press the handles forward and up until your arms are almost straight.","Pause briefly.","Return slowly to a stretch across your chest.","Keep your back against the pad."],"img":"opengym/10669.webp","gif":null,"ext":1},{"id":"1067","n":"cable straight arm pulldown v. 3","bp":"back","eq":"cable","tg":"lats","mg":"triceps","sm":["triceps","core","rear deltoids"],"st":["Stand facing a high pulley and grip the bar.","Hinge slightly forward.","Pull the bar down to your thighs.","Squeeze your lats.","Return slowly."],"img":"opengym/1067.webp","gif":null,"ext":1},{"id":"10670","n":"lever stack seated incline single arm chest press","bp":"chest","eq":"leverage machine","tg":"pectorals","mg":"upper chest","sm":["upper chest","triceps","shoulders","core"],"st":["Sit on the machine and grab one handle at upper-chest height.","Brace your core to avoid twisting.","Press the handle forward and up.","Pause, then lower slowly.","Keep your shoulder pulled back.","Do all reps, then switch arms."],"img":"opengym/10670.webp","gif":null,"ext":1},{"id":"10671","n":"lever stack seated chest press","bp":"chest","eq":"leverage machine","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders","upper chest"],"st":["Set the seat so the handles are level with your mid chest.","Sit back and pull your shoulder blades together.","Press the handles forward until your arms are nearly straight.","Pause without locking out.","Return slowly to a gentle chest stretch.","Keep your feet flat."],"img":"opengym/10671.webp","gif":null,"ext":1},{"id":"10672","n":"lever stack seated single arm chest press","bp":"chest","eq":"leverage machine","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders","core"],"st":["Sit with your back against the pad and grip one handle.","Brace your core and keep your torso square.","Press the handle forward in a smooth line.","Pause, then lower slowly.","Keep your shoulder down.","Do the reps, then switch arms."],"img":"opengym/10672.webp","gif":null,"ext":1},{"id":"10673","n":"kettlebell squat","bp":"upper legs","eq":"kettlebell","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","core","adductors"],"st":["Hold a kettlebell by the horns at your chest.","Stand with feet shoulder-width apart.","Sit your hips down and back while keeping your chest tall.","Lower until your thighs are parallel or lower.","Push through your heels to stand.","Keep your elbows close to your body."],"img":"opengym/10673.webp","gif":null,"ext":1},{"id":"10674","n":"kettlebell back squat","bp":"upper legs","eq":"kettlebell","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","core","upper back"],"st":["Hold the kettlebell behind your neck on your upper back with both hands.","Stand with feet shoulder-width apart.","Brace your core and sit down and back.","Lower to parallel while keeping your chest up.","Drive through your heels to stand.","Keep your elbows pointing down."],"img":"opengym/10674.webp","gif":null,"ext":1},{"id":"10675","n":"landmine squat jump","bp":"upper legs","eq":"landmine","tg":"quads","mg":"glutes","sm":["glutes","calves","core","shoulders"],"st":["Hold the end of a landmine bar at your chest.","Stand with feet shoulder-width apart.","Squat down with a tall chest.","Jump up explosively through your feet.","Land softly with bent knees.","Reset and repeat."],"img":"opengym/10675.webp","gif":null,"ext":1},{"id":"10676","n":"weighted backpack walking","bp":"full body","eq":"weighted","tg":"quads","mg":"glutes","sm":["glutes","calves","core","upper back"],"st":["Put on a backpack and tighten the straps snug.","Stand tall with your shoulders back.","Walk at a steady pace on flat ground.","Take natural strides and breathe evenly.","Keep your core lightly braced.","Walk for 10-30 minutes depending on your fitness."],"img":"opengym/10676.webp","gif":null,"ext":1},{"id":"10677","n":"weighted backpack running","bp":"cardio","eq":"weighted","tg":"cardiovascular system","mg":"quadriceps","sm":["quadriceps","glutes","calves","core"],"st":["Strap a snug backpack with a modest load on your back.","Start with an easy jog on flat ground.","Keep your torso tall and your steps light.","Maintain a pace where you can breathe steadily.","Cut back the load if your form suffers.","Run for 10-20 minutes."],"img":"opengym/10677.webp","gif":null,"ext":1},{"id":"1068","n":"cable kickback v. 3","bp":"upper arms","eq":"cable","tg":"triceps","mg":"shoulders","sm":["shoulders","forearms"],"st":["Hinge forward and hold a handle with elbow bent.","Keep your upper arm parallel to the floor.","Extend your arm back.","Squeeze the triceps.","Return slowly and switch sides."],"img":"opengym/1068.webp","gif":null,"ext":1},{"id":"1069","n":"cable twist v. 3","bp":"waist","eq":"cable","tg":"obliques","mg":"core","sm":["core","shoulders"],"st":["Stand sideways to the pulley and hold the handle with both hands.","Keep your arms extended.","Rotate your torso away from the stack.","Return slowly.","Switch sides."],"img":"opengym/1069.webp","gif":null,"ext":1},{"id":"1070","n":"suspender arm curl","bp":"upper arms","eq":"suspension trainer","tg":"biceps","mg":"brachialis","sm":["brachialis","forearms","core"],"st":["Hold the handles and lean back with arms extended.","Keep your body straight.","Bend your elbows to pull yourself up.","Squeeze the biceps.","Lower slowly."],"img":"opengym/1070.webp","gif":null,"ext":1},{"id":"1071","n":"suspender bent knee inverted row","bp":"back","eq":"suspension trainer","tg":"upper back","mg":"lats","sm":["lats","biceps","rhomboids","core"],"st":["Lie under the straps and grip the handles.","Bend your knees with feet flat.","Lift your hips and pull your chest toward the handles.","Squeeze your shoulder blades.","Lower slowly."],"img":"opengym/1071.webp","gif":null,"ext":1},{"id":"10710","n":"weight plate lying crunch","bp":"waist","eq":"weight plate","tg":"abs","mg":"lower abs","sm":["lower abs","core","hip flexors"],"st":["Lie on your back with knees bent.","Hold the plate on your chest.","Curl your shoulders up.","Pause and squeeze.","Lower slowly."],"img":"opengym/10710.webp","gif":null,"ext":1},{"id":"1072","n":"suspender chest dip","bp":"chest","eq":"suspension trainer","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders","core"],"st":["Support yourself on the straps with arms straight.","Lean slightly forward.","Lower until elbows reach 90 degrees.","Press back up.","Keep the straps steady."],"img":"opengym/1072.webp","gif":null,"ext":1},{"id":"10729","n":"aquabike","bp":"cardio","eq":"body weight","tg":"cardiovascular system","mg":"quadriceps","sm":["quadriceps","hamstrings","core"],"st":["Stand in chest-deep water, holding the pool edge.","Lift your knees alternately.","Pedal at a steady rhythm.","Keep your core tight.","Continue for several minutes."],"img":"opengym/10729.webp","gif":null,"ext":1},{"id":"1073","n":"suspender chest press","bp":"chest","eq":"suspension trainer","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders","core"],"st":["Face away from the anchor and hold the handles at chest level.","Lean forward in a straight line.","Press your body away.","Squeeze the chest.","Return slowly."],"img":"opengym/1073.webp","gif":null,"ext":1},{"id":"10730","n":"weighted sandbag romanian deadlift","bp":"upper legs","eq":"sandbag","tg":"hamstrings","mg":"glutes","sm":["glutes","lower back","grip muscles","core"],"st":["Hold a sandbag in front of your thighs with a firm grip.","Stand with feet hip-width apart and knees slightly bent.","Push your hips back and slide the bag down your legs.","Lower until you feel a stretch in your hamstrings.","Drive your hips forward to stand tall.","Keep your back flat."],"img":"opengym/10730.webp","gif":null,"ext":1},{"id":"10731","n":"l sit rope climb","bp":"back","eq":"rope","tg":"lats","mg":"biceps","sm":["biceps","forearms","core","hip flexors"],"st":["Grip the rope and hang with your legs raised in front of you.","Keep your legs straight and together.","Pull with one hand over the other while staying in the L position.","Reach up and repeat.","Lower under control.","Stop if your legs drop."],"img":"opengym/10731.webp","gif":null,"ext":1},{"id":"10732","n":"side to side jump over stepbox","bp":"upper legs","eq":"body weight","tg":"quads","mg":"glutes","sm":["glutes","calves","core"],"st":["Stand beside a low box with your feet together.","Bend your knees and swing your arms.","Jump sideways over the box.","Land softly on both feet.","Jump back the other way at once.","Keep the pace fast but controlled."],"img":"opengym/10732.webp","gif":null,"ext":1},{"id":"10733","n":"balance board single leg balance","bp":"lower legs","eq":"body weight","tg":"calves","mg":"ankles","sm":["ankles","core","glutes"],"st":["Place a balance board on a flat floor next to a wall for safety.","Step on with one foot and find your centre.","Lift the other foot off the floor.","Hold steady for 20-30 seconds.","Keep your hips level.","Switch legs."],"img":"opengym/10733.webp","gif":null,"ext":1},{"id":"10734","n":"balance pad single leg balance","bp":"lower legs","eq":"body weight","tg":"calves","mg":"ankles","sm":["ankles","core","glutes"],"st":["Place the pad on a flat floor.","Step on with one foot and stand tall.","Lift the other foot off the floor.","Hold for 20-30 seconds.","Keep your eyes on a fixed point.","Switch legs."],"img":"opengym/10734.webp","gif":null,"ext":1},{"id":"10735","n":"hanging alternating knee raise","bp":"waist","eq":"body weight","tg":"abs","mg":"hip flexors","sm":["hip flexors","lower abs","forearms","grip muscles"],"st":["Hang from a bar with arms straight.","Brace your core and keep your body still.","Lift one knee toward your chest.","Lower it slowly and lift the other knee.","Avoid swinging.","Alternate for the reps."],"img":"opengym/10735.webp","gif":null,"ext":1},{"id":"10736","n":"headbanger","bp":"back","eq":"body weight","tg":"spine","mg":"upper back","sm":["upper back","glutes","hamstrings"],"st":["Stand with feet hip-width apart and hands behind your head.","Soften your knees.","Hinge forward at the hips with a flat back.","Nod your head slightly and return to standing.","Move at a smooth pace.","Keep your neck relaxed."],"img":"opengym/10736.webp","gif":null,"ext":1},{"id":"10738","n":"box jump through the arms","bp":"upper legs","eq":"body weight","tg":"quads","mg":"glutes","sm":["glutes","calves","core","shoulders"],"st":["Stand facing a sturdy box.","Swing your arms back and bend your knees.","Jump onto the box, driving your arms through.","Land softly with both feet.","Stand tall at the top.","Step down and reset."],"img":"opengym/10738.webp","gif":null,"ext":1},{"id":"10739","n":"lying single arm triceps stretch","bp":"upper arms","eq":"body weight","tg":"triceps","mg":"shoulders","sm":["shoulders","lats"],"st":["Lie on your back with knees bent.","Raise one arm and bend the elbow, hand reaching behind your head.","Use your other hand to press the elbow gently toward the floor.","Hold for 20-30 seconds.","Keep your ribs down.","Switch arms."],"img":"opengym/10739.webp","gif":null,"ext":1},{"id":"1074","n":"suspender fly","bp":"chest","eq":"suspension trainer","tg":"pectorals","mg":"shoulders","sm":["shoulders","core"],"st":["Face away from the anchor, hands at chest level.","Lean forward with arms together.","Open your arms wide.","Pull back together.","Keep your elbows slightly bent."],"img":"opengym/1074.webp","gif":null,"ext":1},{"id":"10740","n":"stick lying single arm triceps stretch","bp":"upper arms","eq":"body weight","tg":"triceps","mg":"shoulders","sm":["shoulders","lats"],"st":["Lie on your back holding a stick in both hands.","Bend one arm and take that hand behind your head.","Use the other hand to push the stick and press that elbow down.","Hold for 20-30 seconds.","Keep your neck relaxed.","Switch arms."],"img":"opengym/10740.webp","gif":null,"ext":1},{"id":"10741","n":"resistance band standing single arm triceps stretch","bp":"upper arms","eq":"resistance band","tg":"triceps","mg":"shoulders","sm":["shoulders","lats"],"st":["Stand tall and hold a band behind your back with one hand low.","Raise the other arm overhead and bend the elbow, holding the band.","Gently pull down with the lower hand.","Feel a stretch in the back of the upper arm.","Hold for 20-30 seconds.","Switch arms."],"img":"opengym/10741.webp","gif":null,"ext":1},{"id":"10742","n":"lying single arm slide from y to t","bp":"back","eq":"body weight","tg":"traps","mg":"rear deltoids","sm":["rear deltoids","rhomboids","shoulders"],"st":["Lie face down with your arms overhead in a Y.","Lift one arm slightly off the floor.","Slide it out and down into a T position.","Hold for a moment.","Slide it back to the Y.","Switch arms after each set."],"img":"opengym/10742.webp","gif":null,"ext":1},{"id":"10743","n":"kneeling to box jump","bp":"upper legs","eq":"body weight","tg":"quads","mg":"glutes","sm":["glutes","calves","core"],"st":["Kneel in front of a sturdy box.","Swing your arms back and drive your hips forward.","Pop up from your knees onto your feet.","Jump onto the box in one motion.","Land softly and stand tall.","Step down and reset."],"img":"opengym/10743.webp","gif":null,"ext":1},{"id":"10744","n":"resistance band seated single leg hamstring stretch","bp":"upper legs","eq":"resistance band","tg":"hamstrings","mg":"calves","sm":["calves","lower back"],"st":["Sit tall with one leg extended and a band around that foot.","Hold the band ends in both hands.","Keep your leg straight and gently pull your toes toward you.","Hinge forward until you feel a stretch.","Hold for 20-30 seconds.","Switch legs."],"img":"opengym/10744.webp","gif":null,"ext":1},{"id":"10745","n":"seated single leg half circle","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"hip flexors","sm":["hip flexors","core"],"st":["Sit tall on the floor with hands behind you for support.","Lift one leg slightly with the knee straight.","Draw a half circle with your foot from one side to the other.","Keep your torso steady.","Repeat for the reps.","Switch legs."],"img":"opengym/10745.webp","gif":null,"ext":1},{"id":"10746","n":"resistance band seated single leg knee extension","bp":"upper legs","eq":"resistance band","tg":"quads","mg":"hip flexors","sm":["hip flexors","core"],"st":["Sit on a bench and secure a band around one ankle.","Anchor the other end behind you.","Straighten your knee against the band.","Squeeze the front of your thigh at the top.","Lower slowly.","Switch legs."],"img":"opengym/10746.webp","gif":null,"ext":1},{"id":"10747","n":"quick feet in out run","bp":"cardio","eq":"body weight","tg":"cardiovascular system","mg":"quadriceps","sm":["quadriceps","calves","core"],"st":["Stand tall with feet together.","Jog in place.","Quickly move your feet in and out.","Stay light on your toes.","Continue for the set time."],"img":"opengym/10747.webp","gif":null,"ext":1},{"id":"10748","n":"standing single leg front back side to side toe tap","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"adductors","sm":["adductors","core","calves"],"st":["Stand on one leg.","Tap the other toe forward.","Tap to the side, then back.","Keep your balance.","Switch legs."],"img":"opengym/10748.webp","gif":null,"ext":1},{"id":"10749","n":"walk leg kick","bp":"cardio","eq":"body weight","tg":"cardiovascular system","mg":"hamstrings","sm":["hamstrings","quadriceps","hip flexors"],"st":["Stand tall.","Step forward and kick the opposite leg up.","Alternate legs.","Swing your arms.","Continue for the set time."],"img":"opengym/10749.webp","gif":null,"ext":1},{"id":"1075","n":"suspender front raise","bp":"shoulders","eq":"suspension trainer","tg":"delts","mg":"core","sm":["core","upper back","chest"],"st":["Hold the handles and lean back with arms down.","Keep your body straight.","Raise your arms overhead.","Pause.","Lower slowly."],"img":"opengym/1075.webp","gif":null,"ext":1},{"id":"10750","n":"kneeling to stand","bp":"upper legs","eq":"body weight","tg":"quads","mg":"glutes","sm":["glutes","core","calves"],"st":["Kneel with your torso upright.","Place one foot forward into a lunge.","Push through that foot to stand.","Bring your back foot to meet it.","Reverse the motion to return to kneeling.","Alternate the lead leg."],"img":"opengym/10750.webp","gif":null,"ext":1},{"id":"10751","n":"calf jump","bp":"lower legs","eq":"body weight","tg":"calves","mg":"soleus","sm":["soleus","ankles","feet"],"st":["Stand tall.","Keep knees nearly straight.","Jump using your ankles.","Land softly.","Repeat quickly."],"img":"opengym/10751.webp","gif":null,"ext":1},{"id":"10752","n":"bodyweight jefferson curl","bp":"back","eq":"body weight","tg":"spine","mg":"hamstrings","sm":["hamstrings","glutes","upper back"],"st":["Stand tall with feet hip-width apart.","Tuck your chin and roll down one vertebra at a time.","Let your arms hang toward the floor.","Reach only as far as is comfortable.","Reverse slowly to stand.","Move with control and keep the load light."],"img":"opengym/10752.webp","gif":null,"ext":1},{"id":"10753","n":"resistance band seated knee raise","bp":"upper legs","eq":"resistance band","tg":"abs","mg":"hip flexors","sm":["hip flexors","quadriceps"],"st":["Sit tall on a bench or chair with a band looped around your foot and anchored low.","Hold the seat edge and brace your core.","Lift one knee toward your chest against the band.","Pause briefly at the top.","Lower the foot slowly with control.","Finish all reps, then switch legs."],"img":"opengym/10753.webp","gif":null,"ext":1},{"id":"10754","n":"single leg calf jump","bp":"lower legs","eq":"body weight","tg":"calves","mg":"soleus","sm":["soleus","ankles","feet"],"st":["Stand on one leg with a slight knee bend and arms relaxed.","Push through the ball of your foot and jump up using mainly your ankles.","Keep the knee nearly straight in the air.","Land softly on the ball of the same foot.","Rebound right away into the next hop.","Complete your reps, then switch legs."],"img":"opengym/10754.webp","gif":null,"ext":1},{"id":"10755","n":"single leg calf jump step box supported","bp":"lower legs","eq":"body weight","tg":"calves","mg":"soleus","sm":["soleus","ankles","feet"],"st":["Stand beside a step box and rest a hand lightly on it for balance.","Lift one foot off the floor.","Hop up using mostly your ankle and calf.","Land softly on the ball of your foot.","Keep the hops small and quick.","Switch legs after your set."],"img":"opengym/10755.webp","gif":null,"ext":1},{"id":"10756","n":"calf forward jump","bp":"lower legs","eq":"body weight","tg":"calves","mg":"soleus","sm":["soleus","ankles","feet"],"st":["Stand tall with feet together and knees slightly soft.","Push off the balls of your feet and hop forward a short distance.","Keep your knees nearly straight.","Land softly on the balls of your feet.","Hop back or turn around and repeat.","Stay light and quick through the whole set."],"img":"opengym/10756.webp","gif":null,"ext":1},{"id":"10757","n":"calf side to side jump","bp":"lower legs","eq":"body weight","tg":"calves","mg":"soleus","sm":["soleus","ankles","feet"],"st":["Stand tall with feet together and knees slightly soft.","Spring off your toes and hop to one side.","Land softly on the balls of your feet.","Immediately hop to the other side.","Keep your chest up and hips level.","Continue alternating for the set."],"img":"opengym/10757.webp","gif":null,"ext":1},{"id":"10758","n":"medicine ball skater hop","bp":"upper legs","eq":"medicine ball","tg":"glutes","mg":"quadriceps","sm":["quadriceps","calves","core","hip flexors"],"st":["Hold a medicine ball at your chest.","Hop sideways onto one leg.","Land softly with a bent knee.","Pause briefly, then push off to the other side.","Keep your chest up.","Alternate for the reps."],"img":"opengym/10758.webp","gif":null,"ext":1},{"id":"10759","n":"high knee walk","bp":"upper legs","eq":"body weight","tg":"quads","mg":"hip flexors","sm":["hip flexors","glutes","core","calves"],"st":["Stand tall with your arms relaxed.","Lift one knee toward your chest.","Step forward and lower it to the floor.","Repeat on the other side.","Keep your torso upright.","Walk 10-20 steps per leg."],"img":"opengym/10759.webp","gif":null,"ext":1},{"id":"1076","n":"suspension hamstring runner","bp":"upper legs","eq":"suspension trainer","tg":"hamstrings","mg":"glutes","sm":["glutes","core","lower back"],"st":["Lie on your back with both heels in the straps and lift your hips.","Press your arms into the floor for balance.","Curl one heel toward your glutes while the other leg extends.","Switch legs in a smooth running rhythm.","Keep your hips high and level.","Continue for the set."],"img":"opengym/1076.webp","gif":null,"ext":1},{"id":"10760","n":"resistance band toe walk","bp":"lower legs","eq":"band","tg":"calves","mg":"ankles","sm":["ankles","feet","shins"],"st":["Place a band around your forefeet or ankles.","Rise onto the balls of your feet.","Walk forward in small controlled steps.","Stay high on your toes.","Keep your hips level.","Walk for 20-30 steps."],"img":"opengym/10760.webp","gif":null,"ext":1},{"id":"10761","n":"resistance band toe side walk","bp":"lower legs","eq":"band","tg":"calves","mg":"ankles","sm":["ankles","hip flexors","feet"],"st":["Place a band around your ankles.","Rise onto your toes with knees slightly bent.","Step sideways in small steps.","Keep tension on the band.","Do not let your heels drop.","Walk one way, then back."],"img":"opengym/10761.webp","gif":null,"ext":1},{"id":"10762","n":"toe side walk","bp":"lower legs","eq":"body weight","tg":"calves","mg":"ankles","sm":["ankles","feet","glutes"],"st":["Stand tall and rise onto your toes.","Bend your knees slightly.","Step sideways with small controlled steps.","Stay high on your toes.","Keep your hips level.","Walk one way, then return."],"img":"opengym/10762.webp","gif":null,"ext":1},{"id":"10763","n":"lever seated single leg curl (plate loaded)","bp":"upper legs","eq":"leverage machine","tg":"hamstrings","mg":"calves","sm":["calves","glutes"],"st":["Sit on the machine and set the pad above your ankle.","Hold the handles and keep your back against the seat.","Curl one leg down and back.","Squeeze at the bottom.","Return slowly.","Finish the reps, then switch legs."],"img":"opengym/10763.webp","gif":null,"ext":1},{"id":"10764","n":"sled lying single leg squat","bp":"upper legs","eq":"sled machine","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","core"],"st":["Lie back on the sled with one foot on the platform.","Hold the handles and brace your core.","Bend your knee and lower the sled toward you.","Stop before your lower back lifts.","Push through your heel to extend the leg.","Do all reps, then switch legs."],"img":"opengym/10764.webp","gif":null,"ext":1},{"id":"1077","n":"suspension hip abduction","bp":"upper legs","eq":"suspension trainer","tg":"abductors","mg":"glutes","sm":["glutes","core"],"st":["Put one foot in a strap and stand tall on the other leg, holding the anchor for balance.","Brace your core.","Sweep the strapped leg out to the side.","Pause briefly at the end.","Bring it back under control.","Finish your reps, then switch legs."],"img":"opengym/1077.webp","gif":null,"ext":1},{"id":"1078","n":"suspension hip bridge","bp":"upper legs","eq":"suspension trainer","tg":"glutes","mg":"hamstrings","sm":["hamstrings","core","lower back"],"st":["Lie on your back with your heels in the straps and knees bent.","Place your arms by your sides.","Drive through your heels and lift your hips.","Squeeze your glutes at the top in a straight line from shoulders to knees.","Lower slowly without touching down.","Repeat for reps."],"img":"opengym/1078.webp","gif":null,"ext":1},{"id":"10780","n":"lying neck flexion","bp":"neck","eq":"body weight","tg":"levator scapulae","mg":"sternocleidomastoid","sm":["sternocleidomastoid"],"st":["Lie on your back with your knees bent.","Relax your shoulders.","Tuck your chin and lift your head slightly off the floor.","Hold for a second.","Lower slowly.","Keep the motion small and smooth."],"img":"opengym/10780.webp","gif":null,"ext":1},{"id":"10781","n":"lying neck extension","bp":"neck","eq":"body weight","tg":"levator scapulae","mg":"upper back","sm":["upper back","trapezius"],"st":["Lie face down with your forehead hanging near the edge of a bench or resting just off the floor.","Keep your shoulders relaxed.","Lift your head a few centimeters, keeping your chin slightly tucked.","Pause briefly.","Lower slowly.","Use small, controlled reps."],"img":"opengym/10781.webp","gif":null,"ext":1},{"id":"1079","n":"suspension hyperextension","bp":"back","eq":"suspension trainer","tg":"spine","mg":"glutes","sm":["glutes","hamstrings"],"st":["Place your feet in the straps and lie face down, hands behind your head or across your chest.","Brace your core.","Lift your chest by extending your back and hips.","Stop when your body forms a straight line.","Lower slowly.","Avoid overarching at the top."],"img":"opengym/1079.webp","gif":null,"ext":1},{"id":"1080","n":"suspension inverted row","bp":"back","eq":"suspension trainer","tg":"upper back","mg":"lats","sm":["lats","biceps","rhomboids","core"],"st":["Hold the handles and lean back with arms extended and body straight.","Brace your abs and glutes.","Pull your chest toward your hands, driving elbows back.","Squeeze your shoulder blades together.","Lower with control to full arm extension.","Walk your feet forward to make it harder."],"img":"opengym/1080.webp","gif":null,"ext":1},{"id":"1081","n":"suspension jackknife pike","bp":"waist","eq":"suspension trainer","tg":"abs","mg":"lower abs","sm":["lower abs","hip flexors","shoulders"],"st":["Start in a plank with your feet in the straps and hands under shoulders.","Keep your legs straight.","Lift your hips high toward the ceiling.","Roll to an inverted V shape.","Lower back to plank slowly.","Keep your arms straight throughout."],"img":"opengym/1081.webp","gif":null,"ext":1},{"id":"10817","n":"dumbbell wrist rotation","bp":"lower arms","eq":"dumbbell","tg":"forearms","mg":"wrist flexors","sm":["wrist flexors","wrist extensors","grip muscles"],"st":["Sit with your forearm resting on your thigh or a bench.","Hold a light dumbbell with your palm facing up.","Rotate your forearm so the palm turns down.","Pause, then rotate back.","Move slowly with control.","Switch arms."],"img":"opengym/10817.webp","gif":null,"ext":1},{"id":"10818","n":"4 way single leg hop v. 2","bp":"upper legs","eq":"body weight","tg":"quads","mg":"glutes","sm":["glutes","calves","core","ankles"],"st":["Stand on one leg with a soft knee.","Hop forward and land softly.","Hop back to the start, then out to the side and back.","Hop in the fourth direction.","Stick every landing.","Switch legs."],"img":"opengym/10818.webp","gif":null,"ext":1},{"id":"10819","n":"split stance single leg calf raise","bp":"lower legs","eq":"body weight","tg":"calves","mg":"soleus","sm":["soleus","ankles"],"st":["Stand in a split stance, front foot flat and back toes lightly touching the floor.","Keep most weight on the front leg.","Rise onto the ball of the front foot.","Pause at the top.","Lower the heel slowly.","Finish your reps, then switch sides."],"img":"opengym/10819.webp","gif":null,"ext":1},{"id":"1082","n":"suspension jackknife","bp":"waist","eq":"suspension trainer","tg":"abs","mg":"lower abs","sm":["lower abs","hip flexors","shoulders"],"st":["Start in a plank with your feet in the straps and hands under shoulders.","Brace your core.","Pull your knees toward your chest by rolling your hips up.","Pause briefly.","Extend your legs back to plank.","Keep your shoulders stacked over your hands."],"img":"opengym/1082.webp","gif":null,"ext":1},{"id":"10820","n":"resistance band standing balance bent leg hip abduction","bp":"upper legs","eq":"resistance band","tg":"abductors","mg":"glutes","sm":["glutes","core","ankles"],"st":["Place a band around your ankles or knees.","Balance on one leg with a soft knee.","Bend the other knee and lift it out to the side.","Keep your torso upright.","Return slowly.","Finish the reps, then switch legs."],"img":"opengym/10820.webp","gif":null,"ext":1},{"id":"1083","n":"suspension leg curl","bp":"upper legs","eq":"suspension trainer","tg":"hamstrings","mg":"glutes","sm":["glutes","core"],"st":["Lie on your back with your heels in the straps and legs extended.","Lift your hips off the floor.","Curl your heels toward your glutes.","Keep your hips high.","Extend your legs slowly.","Repeat for reps."],"img":"opengym/1083.webp","gif":null,"ext":1},{"id":"1084","n":"suspension mountain climber","bp":"waist","eq":"suspension trainer","tg":"abs","mg":"hip flexors","sm":["hip flexors","shoulders","core"],"st":["Start in a plank with your feet in the straps.","Keep your hands under your shoulders.","Drive one knee toward your chest.","Switch legs in a quick running rhythm.","Keep your hips level.","Continue for the set."],"img":"opengym/1084.webp","gif":null,"ext":1},{"id":"10847","n":"pilates machine lying frog and leg circle","bp":"upper legs","eq":"leverage machine","tg":"adductors","mg":"glutes","sm":["glutes","inner thighs","core"],"st":["Lie on the reformer with your feet in the straps or on the bar.","Bend your knees and open them out, heels together, in a frog shape.","Press your legs straight.","Circle them out, around and back together.","Reverse the circle direction after a few reps.","Keep your back steady on the pad."],"img":"opengym/10847.webp","gif":null,"ext":1},{"id":"10848","n":"pilates machine lying running","bp":"lower legs","eq":"leverage machine","tg":"calves","mg":"quadriceps","sm":["quadriceps","glutes","core"],"st":["Lie on the reformer with the balls of your feet on the bar.","Straighten both legs.","Lower one heel while bending the other knee.","Alternate smoothly.","Keep your pelvis still.","Maintain steady breathing."],"img":"opengym/10848.webp","gif":null,"ext":1},{"id":"10849","n":"pilates machine lying pelvic lift","bp":"upper legs","eq":"leverage machine","tg":"glutes","mg":"hamstrings","sm":["hamstrings","lower back","core"],"st":["Lie on your back with your feet on the bar and knees bent.","Press your arms into the pad.","Lift your hips one vertebra at a time.","Hold at the top.","Roll down slowly.","Keep your ribs relaxed."],"img":"opengym/10849.webp","gif":null,"ext":1},{"id":"10850","n":"pilates machine side split","bp":"upper legs","eq":"leverage machine","tg":"adductors","mg":"inner thighs","sm":["inner thighs","glutes","core"],"st":["Stand with one foot on the carriage and one on the platform.","Brace your core.","Slide the carriage out to widen your stance.","Pause.","Draw it back under control with your inner thighs.","Keep your hips square."],"img":"opengym/10850.webp","gif":null,"ext":1},{"id":"10851","n":"pilates machine russian squat","bp":"upper legs","eq":"leverage machine","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","core"],"st":["Set your feet on the carriage and platform.","Stand tall and brace your core.","Bend your knees into a squat.","Keep your chest lifted and knees over toes.","Press back up to standing.","Move with the carriage smoothly."],"img":"opengym/10851.webp","gif":null,"ext":1},{"id":"10852","n":"pilates machine russian split","bp":"upper legs","eq":"leverage machine","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","core"],"st":["Place one foot on the carriage and one on the platform.","Stand tall with your core braced.","Slide the carriage back while lowering into a split squat.","Pause.","Press back to the start.","Switch sides after your set."],"img":"opengym/10852.webp","gif":null,"ext":1},{"id":"10853","n":"pilates machine long spine","bp":"back","eq":"leverage machine","tg":"spine","mg":"hamstrings","sm":["hamstrings","core","glutes"],"st":["Lie on your back with your feet against the shoulder rests.","Press your legs straight up.","Roll your hips off the pad.","Lift your hips over your shoulders.","Roll down slowly one vertebra at a time.","Avoid pressing on your neck."],"img":"opengym/10853.webp","gif":null,"ext":1},{"id":"10854","n":"pilates machine arm circle","bp":"shoulders","eq":"leverage machine","tg":"delts","mg":"chest","sm":["chest","lats","core"],"st":["Lie on your back holding the straps with arms up.","Bend your knees and brace your core.","Lower your arms out to the sides.","Circle them down and up in a smooth arc.","Reverse the direction after a few reps.","Keep your ribs down."],"img":"opengym/10854.webp","gif":null,"ext":1},{"id":"10855","n":"pilates machine chest expansion","bp":"back","eq":"leverage machine","tg":"upper back","mg":"rear deltoids","sm":["rear deltoids","triceps","core"],"st":["Kneel facing the straps with your torso upright.","Hold the straps with straight arms.","Pull the straps back behind your body.","Turn your head gently to each side.","Return slowly to the start.","Keep your chest lifted and ribs down."],"img":"opengym/10855.webp","gif":null,"ext":1},{"id":"10856","n":"pilates machine overhead","bp":"waist","eq":"leverage machine","tg":"abs","mg":"shoulders","sm":["shoulders","lats","core"],"st":["Sit or kneel on the carriage holding the straps overhead.","Brace your core.","Press the straps forward and down in a controlled arc.","Return to the overhead position.","Keep your spine tall.","Move smoothly with breath."],"img":"opengym/10856.webp","gif":null,"ext":1},{"id":"10857","n":"barbell jefferson curl","bp":"back","eq":"barbell","tg":"spine","mg":"hamstrings","sm":["hamstrings","glutes","upper back"],"st":["Stand holding a very light barbell in front of your thighs.","Tuck your chin and roll down one segment at a time.","Let the bar hang close to your legs.","Go only as low as feels controlled.","Roll back up slowly.","Keep your knees soft."],"img":"opengym/10857.webp","gif":null,"ext":1},{"id":"10858","n":"dumbbell lu raise","bp":"shoulders","eq":"dumbbell","tg":"delts","mg":"upper back","sm":["upper back","trapezius","rotator cuff"],"st":["Stand tall holding a light dumbbell in each hand, arms by your sides.","Raise both arms out to the sides until they reach shoulder height, elbows bent to 90 degrees.","Rotate your forearms upward so the dumbbells point to the ceiling.","Pause, then lower back down the same path with control.","Keep your ribs down and avoid shrugging."],"img":"opengym/10858.webp","gif":null,"ext":1},{"id":"10859","n":"standing floor tibialis raise wall supported","bp":"lower legs","eq":"body weight","tg":"shins","mg":"calves","sm":["calves","ankles"],"st":["Stand with your back and hips against a wall, feet a little way out in front.","Keep your legs straight and your heels planted on the floor.","Pull your toes up toward your shins as high as you can.","Pause briefly at the top.","Lower your toes slowly and repeat."],"img":"opengym/10859.webp","gif":null,"ext":1},{"id":"1086","n":"suspension power pull","bp":"back","eq":"suspension trainer","tg":"lats","mg":"biceps","sm":["biceps","upper back","core"],"st":["Hold the handles with arms straight and lean back.","Keep your body in a straight line.","Pull explosively with your arms and back.","Bring your chest toward your hands.","Lower slowly.","Keep your core tight."],"img":"opengym/1086.webp","gif":null,"ext":1},{"id":"10860","n":"cable side leg kick from back","bp":"upper legs","eq":"cable","tg":"abductors","mg":"glutes","sm":["glutes","core"],"st":["Attach an ankle cuff to a low pulley and strap it to one ankle.","Stand side-on to the machine and hold the frame for balance.","Kick the working leg out and slightly behind you, keeping the knee mostly straight.","Pause, then return slowly without letting the weight stack touch down.","Keep your torso still. Finish all reps, then switch legs."],"img":"opengym/10860.webp","gif":null,"ext":1},{"id":"10861","n":"weighted ball reverse hyperextension on ghd","bp":"upper legs","eq":"medicine ball","tg":"glutes","mg":"hamstrings","sm":["hamstrings","lower back"],"st":["Lie face down on the GHD with hips at the edge and a ball between your feet.","Hold the pad.","Lift your legs until they line up with your torso.","Squeeze your glutes at the top.","Lower slowly.","Do not swing."],"img":"opengym/10861.webp","gif":null,"ext":1},{"id":"10862","n":"bodyweight single leg deadlift against ball","bp":"upper legs","eq":"body weight","tg":"hamstrings","mg":"glutes","sm":["glutes","lower back","core"],"st":["Stand facing a wall with a ball between your hand and the wall.","Lift one foot slightly.","Hinge at the hip as the free leg extends back.","Keep your back flat.","Return to standing.","Switch legs after the set."],"img":"opengym/10862.webp","gif":null,"ext":1},{"id":"10863","n":"smith seated single arm neutral grip shoulders press","bp":"shoulders","eq":"smith machine","tg":"delts","mg":"triceps","sm":["triceps","upper chest","core"],"st":["Set a bench under the smith bar and sit upright with your back supported.","Hold the bar with one hand in a neutral grip and unhook it.","Press the bar overhead until your arm is almost straight.","Lower it slowly to around chin height.","Keep your torso steady. Finish all reps, then switch arms."],"img":"opengym/10863.webp","gif":null,"ext":1},{"id":"10864","n":"high box step up","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings"],"st":["Stand facing a high box.","Place one foot fully on top.","Drive through that heel to stand up.","Bring the other foot up.","Step down with control.","Switch leading legs."],"img":"opengym/10864.webp","gif":null,"ext":1},{"id":"10865","n":"dumbbell single leg romanian deadlift on bench","bp":"upper legs","eq":"dumbbell","tg":"hamstrings","mg":"glutes","sm":["glutes","lower back","core"],"st":["Hold dumbbells with your rear foot resting on a bench.","Keep your front knee soft.","Hinge forward at the hips.","Lower the weights along your leg.","Squeeze your glutes to stand up.","Switch legs after the set."],"img":"opengym/10865.webp","gif":null,"ext":1},{"id":"10866","n":"lever bent over single arm lats focused row","bp":"back","eq":"leverage machine","tg":"lats","mg":"rhomboids","sm":["rhomboids","biceps","rear deltoids"],"st":["Set the machine and lean forward from the hips with a flat back.","Grip the handle with one hand and let the arm reach forward.","Pull the elbow back and down toward your hip.","Squeeze your lat at the end of the pull.","Return slowly, then switch sides after your reps."],"img":"opengym/10866.webp","gif":null,"ext":1},{"id":"10867","n":"lever incline prone neutral grip row","bp":"back","eq":"leverage machine","tg":"upper back","mg":"lats","sm":["lats","rhomboids","biceps","rear deltoids"],"st":["Lie face down on the incline pad with your chest supported.","Grip the neutral handles and extend your arms.","Pull your elbows back past your torso, squeezing the shoulder blades together.","Pause for a moment.","Let the handles return slowly until your arms are straight."],"img":"opengym/10867.webp","gif":null,"ext":1},{"id":"10868","n":"bosu ball squat","bp":"upper legs","eq":"bosu ball","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","core"],"st":["Stand on the Bosu with feet shoulder width apart.","Hold your arms forward.","Sit your hips back and bend your knees.","Keep your chest lifted.","Stand tall.","Keep your knees tracking over your toes."],"img":"opengym/10868.webp","gif":null,"ext":1},{"id":"10869","n":"bosu ball single leg squat","bp":"upper legs","eq":"bosu ball","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","core"],"st":["Stand on one foot on the Bosu.","Extend your arms for balance.","Lower into a controlled squat.","Keep your knee in line with your toes.","Press back up.","Switch legs after the set."],"img":"opengym/10869.webp","gif":null,"ext":1},{"id":"1087","n":"suspension pull through","bp":"upper legs","eq":"suspension trainer","tg":"glutes","mg":"hamstrings","sm":["hamstrings","core","lower back"],"st":["Face away from the anchor, holding the handles between your legs.","Step forward to create tension.","Hinge at the hips and let your hands pass between your legs.","Drive your hips forward.","Stand tall and squeeze your glutes.","Keep your back flat."],"img":"opengym/1087.webp","gif":null,"ext":1},{"id":"10870","n":"resistance band glute bridge walk","bp":"upper legs","eq":"band","tg":"glutes","mg":"hamstrings","sm":["hamstrings","core"],"st":["Lie on your back with a band above your knees and feet flat.","Lift your hips into a bridge.","Step your feet out and in sideways.","Keep the band tight.","Keep your hips high.","Lower after the set."],"img":"opengym/10870.webp","gif":null,"ext":1},{"id":"10871","n":"weighted plate crunch (hands overhead)","bp":"waist","eq":"weight plate","tg":"abs","mg":"lower abs","sm":["lower abs","hip flexors"],"st":["Lie on your back with knees bent and feet flat.","Hold a plate with both hands and extend your arms overhead.","Curl your shoulders and upper back off the floor, reaching the plate upward.","Pause at the top and squeeze your abs.","Lower slowly without dropping your head back."],"img":"opengym/10871.webp","gif":null,"ext":1},{"id":"10873","n":"dumbbell weighted crunch (hands overhead)","bp":"waist","eq":"dumbbell","tg":"abs","mg":"lower abs","sm":["lower abs","hip flexors"],"st":["Lie on your back with knees bent and feet flat.","Hold one dumbbell upright with both hands and extend your arms overhead.","Curl your shoulders off the floor, driving the dumbbell toward the ceiling.","Pause and squeeze your abs.","Lower slowly and repeat."],"img":"opengym/10873.webp","gif":null,"ext":1},{"id":"10875","n":"weighted plate 45 degrees side bend","bp":"waist","eq":"weight plate","tg":"obliques","mg":"abdominals","sm":["abdominals","lower back"],"st":["Set up on a 45 degree bench or hyperextension frame, side-on, feet secured.","Hold a plate against your chest.","Lower your torso sideways with control.","Bend back up until your body is in a straight line.","Avoid twisting. Finish your reps and switch sides."],"img":"opengym/10875.webp","gif":null,"ext":1},{"id":"10877","n":"weighted plate crunch (hands overhead) v. 2","bp":"waist","eq":"weight plate","tg":"abs","mg":"lower abs","sm":["lower abs","hip flexors"],"st":["Lie on your back with knees bent and feet planted.","Hold a plate with straight arms overhead.","Crunch up, lifting your shoulder blades off the floor.","Keep your arms by your ears as you rise.","Lower back down slowly and repeat."],"img":"opengym/10877.webp","gif":null,"ext":1},{"id":"10879","n":"weighted dumbbell crunch (hands overhead) v. 2","bp":"waist","eq":"dumbbell","tg":"abs","mg":"lower abs","sm":["lower abs","hip flexors"],"st":["Lie on your back with knees bent and feet flat.","Hold a dumbbell at one end with both hands, arms extended overhead.","Crunch up and let the dumbbell travel in an arc toward your knees.","Squeeze your abs at the top.","Lower with control and repeat."],"img":"opengym/10879.webp","gif":null,"ext":1},{"id":"1088","n":"suspension pull up","bp":"back","eq":"suspension trainer","tg":"lats","mg":"biceps","sm":["biceps","upper back","forearms","core"],"st":["Hang from the handles with arms extended.","Brace your core.","Pull your chest up between the handles.","Lead with your elbows.","Pause at the top.","Lower slowly."],"img":"opengym/1088.webp","gif":null,"ext":1},{"id":"10882","n":"kneeling plyo push up","bp":"chest","eq":"body weight","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders","core"],"st":["Kneel in a push-up position with hands under shoulders.","Keep a straight line from knees to head.","Lower your chest toward the floor.","Push up explosively so your hands leave the floor.","Land softly with bent elbows.","Go straight into the next rep."],"img":"opengym/10882.webp","gif":null,"ext":1},{"id":"10890","n":"elastic bed toe jump","bp":"lower legs","eq":"body weight","tg":"calves","mg":"soleus","sm":["soleus","ankles","feet"],"st":["Stand on the elastic bed with feet together.","Rise onto your toes.","Jump using your ankles.","Land softly on the balls of your feet.","Stay quick and light.","Continue for the set."],"img":"opengym/10890.webp","gif":null,"ext":1},{"id":"10899","n":"resistance band lying abduction","bp":"upper legs","eq":"band","tg":"abductors","mg":"glutes","sm":["glutes"],"st":["Loop a band around both legs just above the knees and lie on your side.","Stack your hips and bend your knees slightly.","Lift the top knee or leg away from the bottom one against the band.","Pause at the top.","Lower slowly. Finish your reps and switch sides."],"img":"opengym/10899.webp","gif":null,"ext":1},{"id":"1090","n":"suspension reverse fly","bp":"shoulders","eq":"suspension trainer","tg":"delts","mg":"rear deltoids","sm":["rear deltoids","upper back","rhomboids"],"st":["Hold the handles and lean back with arms extended.","Keep your body straight.","Open your arms out to the sides.","Squeeze your shoulder blades.","Return slowly.","Do not shrug."],"img":"opengym/1090.webp","gif":null,"ext":1},{"id":"10901","n":"dumbbell single arm shrug","bp":"back","eq":"dumbbell","tg":"traps","mg":"upper back","sm":["upper back","grip muscles","trapezius"],"st":["Stand tall holding a dumbbell in one hand at your side.","Keep your arm straight and your shoulders relaxed.","Lift your shoulder straight up toward your ear.","Hold for a moment at the top.","Lower slowly. Finish your reps and switch arms."],"img":"opengym/10901.webp","gif":null,"ext":1},{"id":"10902","n":"eccentric single arm pull up","bp":"back","eq":"body weight","tg":"lats","mg":"biceps","sm":["biceps","forearms","grip muscles","core"],"st":["Get into the top position of a pull-up, with one hand on the bar and the other assisting or at rest.","Let go of any help and shift your weight onto the working arm.","Lower yourself as slowly as you can until your arm is straight.","Keep your body tight and avoid swinging.","Step back up to the top and repeat, then switch arms."],"img":"opengym/10902.webp","gif":null,"ext":1},{"id":"10903","n":"resistance band assisted single arm pull up v. 2","bp":"back","eq":"band","tg":"lats","mg":"biceps","sm":["biceps","forearms","grip muscles"],"st":["Hang a band from the bar and place a foot or knee in the loop.","Grip the bar with one hand and keep the other arm across your chest.","Pull your chin toward the bar, driving your elbow down.","Pause at the top.","Lower under control. Finish your reps and switch arms."],"img":"opengym/10903.webp","gif":null,"ext":1},{"id":"10904","n":"hamstring bridge v. 2","bp":"upper legs","eq":"body weight","tg":"hamstrings","mg":"glutes","sm":["glutes","lower back"],"st":["Lie on your back with knees bent and heels on the floor, a bit further from your hips.","Press through your heels.","Lift your hips until your body forms a straight line from shoulders to knees.","Squeeze your hamstrings and glutes at the top.","Lower slowly and repeat."],"img":"opengym/10904.webp","gif":null,"ext":1},{"id":"10905","n":"hamstring bridge leg kick v. 2","bp":"upper legs","eq":"body weight","tg":"hamstrings","mg":"glutes","sm":["glutes","core","lower back"],"st":["Lie on your back with knees bent and heels on the floor.","Lift your hips into a bridge.","Straighten one leg out in front, keeping hips level.","Bring the foot back to the floor without dropping your hips.","Alternate legs or finish one side first."],"img":"opengym/10905.webp","gif":null,"ext":1},{"id":"10906","n":"bodyweight split squat hold","bp":"upper legs","eq":"body weight","tg":"quads","mg":"glutes","sm":["glutes","hip flexors","hamstrings"],"st":["Step one foot far forward and the other back into a split stance.","Lower your hips until the front knee is bent to about 90 degrees.","Keep your torso upright and your front heel down.","Hold for 20-30 seconds, breathing steadily.","Rise up and switch legs."],"img":"opengym/10906.webp","gif":null,"ext":1},{"id":"10907","n":"bodyweight half split squat hold","bp":"upper legs","eq":"body weight","tg":"quads","mg":"hamstrings","sm":["hamstrings","glutes","calves"],"st":["Kneel on one knee with the other leg extended in front, heel on the floor.","Sit your hips back toward the rear heel.","Keep the front leg straight and your back long.","Hold for 20-30 seconds.","Switch legs."],"img":"opengym/10907.webp","gif":null,"ext":1},{"id":"10908","n":"seated single leg foot circle","bp":"lower legs","eq":"body weight","tg":"calves","mg":"ankles","sm":["ankles","feet","shins"],"st":["Sit tall on a chair and lift one foot slightly off the floor.","Keep your lower leg still.","Draw slow circles with your toes, as wide as is comfortable.","Do half your reps clockwise, then switch to counterclockwise.","Repeat on the other foot."],"img":"opengym/10908.webp","gif":null,"ext":1},{"id":"10909","n":"seated feet circle","bp":"lower legs","eq":"body weight","tg":"calves","mg":"ankles","sm":["ankles","feet","shins"],"st":["Sit tall on a chair with both feet lifted off the floor.","Keep your knees still.","Circle both feet in the same direction, as wide as feels comfortable.","Reverse the direction after several turns.","Keep your breathing relaxed."],"img":"opengym/10909.webp","gif":null,"ext":1},{"id":"1091","n":"suspension rollout","bp":"waist","eq":"suspension trainer","tg":"abs","mg":"lower abs","sm":["lower abs","shoulders","lats"],"st":["Kneel holding the handles close to your chest.","Brace your core.","Push your arms forward as you lean out.","Keep your back flat.","Pull back to the start.","Do not let your hips sag."],"img":"opengym/1091.webp","gif":null,"ext":1},{"id":"10910","n":"seated single leg foot side to side","bp":"lower legs","eq":"body weight","tg":"calves","mg":"ankles","sm":["ankles","feet","shins"],"st":["Sit tall and lift one foot slightly off the floor.","Keep your lower leg still.","Turn your foot inward, then outward, in a smooth motion.","Move through a comfortable range.","Repeat for your reps, then switch feet."],"img":"opengym/10910.webp","gif":null,"ext":1},{"id":"10911","n":"seated squeezing toes","bp":"lower legs","eq":"body weight","tg":"calves","mg":"feet","sm":["feet","ankles"],"st":["Sit on a chair with both feet flat on the floor.","Curl all your toes down as if gripping the floor.","Squeeze for a couple of seconds.","Relax and spread your toes wide.","Repeat smoothly."],"img":"opengym/10911.webp","gif":null,"ext":1},{"id":"10912","n":"seated single leg squeezing toes","bp":"lower legs","eq":"body weight","tg":"calves","mg":"feet","sm":["feet","ankles"],"st":["Sit on a chair and place one foot flat on the floor.","Curl your toes down and squeeze.","Hold for a second or two.","Relax and spread the toes.","Finish your reps, then switch feet."],"img":"opengym/10912.webp","gif":null,"ext":1},{"id":"10913","n":"lying single leg raise","bp":"upper legs","eq":"body weight","tg":"hip flexors","mg":"quadriceps","sm":["quadriceps","core","lower abs"],"st":["Lie on your back with one knee bent and that foot flat.","Straighten the other leg and tighten the thigh.","Raise it to the height of your bent knee.","Pause briefly.","Lower slowly. Finish your reps and switch legs."],"img":"opengym/10913.webp","gif":null,"ext":1},{"id":"10914","n":"bodyweight quarter squat","bp":"upper legs","eq":"body weight","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","calves"],"st":["Stand with feet shoulder-width apart.","Push your hips back and bend your knees a short way.","Keep your chest up and heels down.","Press through your feet to stand tall.","Repeat at a steady pace."],"img":"opengym/10914.webp","gif":null,"ext":1},{"id":"10915","n":"bodyweight single leg deadlift hold","bp":"upper legs","eq":"body weight","tg":"hamstrings","mg":"glutes","sm":["glutes","lower back","core"],"st":["Stand on one leg with a soft knee.","Hinge forward from the hips as the other leg extends behind you.","Keep your back flat until your torso is nearly parallel to the floor.","Hold for several seconds, hips level.","Return upright and switch legs."],"img":"opengym/10915.webp","gif":null,"ext":1},{"id":"10916","n":"bodyweight single leg deadlift toe touch","bp":"upper legs","eq":"body weight","tg":"hamstrings","mg":"glutes","sm":["glutes","lower back","core"],"st":["Stand on one leg with a soft knee.","Hinge forward as the free leg lifts behind you.","Reach your hands toward the toes of the standing foot.","Keep your back flat and hips square.","Stand back up with control. Finish your reps and switch legs."],"img":"opengym/10916.webp","gif":null,"ext":1},{"id":"10917","n":"seated single leg tibialis press v. 2","bp":"lower legs","eq":"body weight","tg":"shins","mg":"calves","sm":["calves","ankles"],"st":["Sit on a chair with one foot flat and the other crossed over it.","Press the top foot up against the resistance of the bottom foot.","Feel the front of your shin work.","Hold for a second.","Relax and repeat, then switch feet."],"img":"opengym/10917.webp","gif":null,"ext":1},{"id":"10918","n":"seated single leg squeezing toes v. 2","bp":"lower legs","eq":"body weight","tg":"calves","mg":"feet","sm":["feet","ankles"],"st":["Sit with one foot flat on the floor.","Curl your toes down and hold the squeeze.","Keep your heel planted.","Release and spread your toes.","Do all reps, then switch feet."],"img":"opengym/10918.webp","gif":null,"ext":1},{"id":"10919","n":"seated single leg foot side to side v. 2","bp":"lower legs","eq":"body weight","tg":"calves","mg":"ankles","sm":["ankles","feet","shins"],"st":["Sit tall and lift one foot a little off the floor.","Keep your leg still.","Sweep the foot to the inside, then to the outside.","Keep the motion smooth and pain free.","Repeat, then switch feet."],"img":"opengym/10919.webp","gif":null,"ext":1},{"id":"10920","n":"seated single leg toes press","bp":"lower legs","eq":"body weight","tg":"calves","mg":"feet","sm":["feet","ankles"],"st":["Sit on a chair with one foot on the floor.","Lift your heel slightly and press your toes into the floor.","Hold briefly.","Lower your heel again.","Finish your reps, then switch feet."],"img":"opengym/10920.webp","gif":null,"ext":1},{"id":"10921","n":"resistance band seated single leg knee extension hold","bp":"upper legs","eq":"band","tg":"quads","mg":"hip flexors","sm":["hip flexors"],"st":["Sit on a chair with a band anchored around one ankle behind you.","Straighten that knee against the band.","Hold the leg straight for 10-20 seconds.","Keep the thigh tight and your back upright.","Lower slowly and switch legs."],"img":"opengym/10921.webp","gif":null,"ext":1},{"id":"10922","n":"standing back achilles stretch","bp":"lower legs","eq":"body weight","tg":"calves","mg":"soleus","sm":["soleus","ankles"],"st":["Stand facing a wall and step one foot back.","Keep the back heel down and the knee slightly bent.","Lean forward until you feel the stretch low in the calf.","Hold for 20-30 seconds.","Switch legs."],"img":"opengym/10922.webp","gif":null,"ext":1},{"id":"10925","n":"two to one leg jump","bp":"upper legs","eq":"body weight","tg":"quads","mg":"glutes","sm":["glutes","calves","hamstrings"],"st":["Stand with feet hip-width apart.","Dip into a quarter squat and swing your arms back.","Jump up and land on one foot.","Absorb the landing with a bent knee and hold steady.","Reset and alternate landing legs."],"img":"opengym/10925.webp","gif":null,"ext":1},{"id":"10926","n":"standing wall slide quarter squat hold","bp":"upper legs","eq":"body weight","tg":"quads","mg":"glutes","sm":["glutes","calves"],"st":["Stand with your back against a wall and feet slightly forward.","Slide down until your knees bend about a quarter of the way.","Keep your back flat to the wall.","Hold for 15-30 seconds.","Slide back up."],"img":"opengym/10926.webp","gif":null,"ext":1},{"id":"10927","n":"standing forward slide press with towel","bp":"chest","eq":"body weight","tg":"pectorals","mg":"shoulders","sm":["shoulders","triceps","core"],"st":["Stand facing a wall and place a towel under your hand against it.","Keep your elbow bent and the hand at chest height.","Slide the towel forward as your arm straightens.","Slide it back slowly.","Finish your reps, then switch arms."],"img":"opengym/10927.webp","gif":null,"ext":1},{"id":"10928","n":"standing wall serratus slide with towel","bp":"back","eq":"body weight","tg":"serratus anterior","mg":"shoulders","sm":["shoulders","upper back"],"st":["Stand facing a wall with a towel under your forearm on the wall.","Keep your elbow bent and your body upright.","Slide your arm upward along the wall.","Reach the top without shrugging.","Slide back down slowly and switch arms."],"img":"opengym/10928.webp","gif":null,"ext":1},{"id":"10929","n":"standing internal rotation slide with towel","bp":"chest","eq":"body weight","tg":"pectorals","mg":"shoulders","sm":["shoulders","rotator cuff"],"st":["Stand side-on to a wall with a towel under your forearm.","Bend your elbow to 90 degrees against your side.","Slide your hand across your body along the wall.","Return slowly.","Finish your reps, then switch arms."],"img":"opengym/10929.webp","gif":null,"ext":1},{"id":"1093","n":"suspension self assisted chest dip","bp":"chest","eq":"suspension trainer","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders"],"st":["Hold the handles with arms straight and feet on the floor.","Lean your chest forward.","Lower your body by bending your elbows.","Use your legs for light help.","Press back up.","Keep your shoulders down."],"img":"opengym/1093.webp","gif":null,"ext":1},{"id":"10930","n":"standing external rotation slide with towel","bp":"back","eq":"body weight","tg":"upper back","mg":"rotator cuff","sm":["rotator cuff","rear deltoids","shoulders"],"st":["Stand side-on to a wall with a towel under your forearm.","Keep your elbow at 90 degrees, tucked at your side.","Slide your hand outward along the wall.","Return slowly.","Finish your reps, then switch arms."],"img":"opengym/10930.webp","gif":null,"ext":1},{"id":"10931","n":"standing external rotation behind back with towel","bp":"back","eq":"body weight","tg":"upper back","mg":"rotator cuff","sm":["rotator cuff","rear deltoids","shoulders"],"st":["Stand tall holding a towel behind your back with both hands.","Keep the lower hand still and pull the upper hand away.","Rotate the upper shoulder outward.","Hold briefly and release.","Finish your reps, then switch hands."],"img":"opengym/10931.webp","gif":null,"ext":1},{"id":"10932","n":"shoulder stretch behind the back with towel","bp":"shoulders","eq":"body weight","tg":"delts","mg":"rotator cuff","sm":["rotator cuff","triceps","chest"],"st":["Hold a towel with one hand over your shoulder and the other behind your lower back.","Gently pull the towel upward with the lower hand.","Keep your chest open and neck relaxed.","Hold for 20-30 seconds.","Switch sides."],"img":"opengym/10932.webp","gif":null,"ext":1},{"id":"10933","n":"side lying external rotation","bp":"shoulders","eq":"body weight","tg":"delts","mg":"rotator cuff","sm":["rotator cuff","rear deltoids"],"st":["Lie on your side with your top elbow bent to 90 degrees against your ribs.","Hold your forearm across your stomach.","Rotate your forearm upward without moving your elbow.","Lower slowly.","Finish your reps, then switch sides."],"img":"opengym/10933.webp","gif":null,"ext":1},{"id":"10934","n":"bodyweight side lying shoulder external rotation","bp":"back","eq":"body weight","tg":"upper back","mg":"rotator cuff","sm":["rotator cuff","rear deltoids","shoulders"],"st":["Lie on your side with a small towel under the top elbow.","Bend the elbow to 90 degrees.","Rotate your forearm up toward the ceiling.","Pause, then lower slowly.","Finish your reps, then switch sides."],"img":"opengym/10934.webp","gif":null,"ext":1},{"id":"10935","n":"stick shoulder mobilization in abduction behind back","bp":"shoulders","eq":"body weight","tg":"delts","mg":"rotator cuff","sm":["rotator cuff","chest","triceps"],"st":["Stand tall holding a stick behind your back.","Hold it with one hand low and the other high.","Use the low hand to guide the top arm out and up.","Move only in a comfortable range.","Return slowly and switch sides."],"img":"opengym/10935.webp","gif":null,"ext":1},{"id":"10936","n":"stick shoulder rotation over head","bp":"shoulders","eq":"body weight","tg":"delts","mg":"rotator cuff","sm":["rotator cuff","chest","upper back"],"st":["Hold a stick with a wide grip in front of your thighs.","Raise it overhead with straight arms.","Continue the arc behind your back as far as comfortable.","Return along the same path.","Narrow your grip over time."],"img":"opengym/10936.webp","gif":null,"ext":1},{"id":"10937","n":"standing wall shoulder rotation","bp":"shoulders","eq":"body weight","tg":"delts","mg":"rotator cuff","sm":["rotator cuff","upper back"],"st":["Stand facing a wall and place your forearm against it.","Bend your elbow to 90 degrees.","Rotate your forearm up and down against the wall.","Keep your shoulder relaxed.","Switch arms after your reps."],"img":"opengym/10937.webp","gif":null,"ext":1},{"id":"1094","n":"suspension self assisted pull up","bp":"back","eq":"suspension trainer","tg":"lats","mg":"biceps","sm":["biceps","upper back","forearms"],"st":["Hold the handles with feet on the floor.","Lean back.","Pull your chest toward your hands.","Use your legs for light help.","Lower slowly.","Keep your core tight."],"img":"opengym/1094.webp","gif":null,"ext":1},{"id":"10948","n":"scapular pull up swing","bp":"back","eq":"body weight","tg":"upper back","mg":"lats","sm":["lats","trapezius","grip muscles","core"],"st":["Hang from a pull-up bar with straight arms.","Pull your shoulder blades down without bending your elbows.","Swing your body forward and back in a small arc.","Keep the motion controlled.","Lower to a full hang and repeat."],"img":"opengym/10948.webp","gif":null,"ext":1},{"id":"10949","n":"dumbbell straight arm bicep swing","bp":"upper arms","eq":"dumbbell","tg":"biceps","mg":"shoulders","sm":["shoulders","forearms"],"st":["Stand holding a dumbbell in each hand, palms forward.","Keep your arms nearly straight.","Swing the dumbbells forward and up in a controlled arc.","Lower them back down.","Keep your torso still and avoid momentum."],"img":"opengym/10949.webp","gif":null,"ext":1},{"id":"1095","n":"suspension self assisted triceps dip","bp":"upper arms","eq":"suspension trainer","tg":"triceps","mg":"chest","sm":["chest","shoulders"],"st":["Hold the handles with arms straight and feet on the floor.","Keep your torso upright.","Bend your elbows to lower.","Use your legs for light help.","Press back up.","Keep your elbows close."],"img":"opengym/1095.webp","gif":null,"ext":1},{"id":"10950","n":"ring long arms push up hold","bp":"chest","eq":"suspension trainer","tg":"pectorals","mg":"shoulders","sm":["shoulders","triceps","core","upper back"],"st":["Set the rings low and take a plank with your hands on them.","Keep your arms straight and rings close to your sides.","Squeeze your glutes and abs.","Hold for 15-30 seconds.","Lower to the floor to rest."],"img":"opengym/10950.webp","gif":null,"ext":1},{"id":"10951","n":"l sit leg raise","bp":"waist","eq":"body weight","tg":"abs","mg":"hip flexors","sm":["hip flexors","triceps","lower abs"],"st":["Sit on the floor with your hands on parallettes or flat beside you.","Press down to lift your hips.","Extend your legs in front of you.","Raise your legs higher and lower them back to the L position.","Keep your arms straight and shoulders down."],"img":"opengym/10951.webp","gif":null,"ext":1},{"id":"1096","n":"suspension shoulder external rotation","bp":"shoulders","eq":"suspension trainer","tg":"delts","mg":"rotator cuff","sm":["rotator cuff","rear deltoids"],"st":["Hold the handles with elbows bent at 90 degrees.","Lean back slightly.","Rotate your forearms outward and upward.","Keep your elbows by your sides.","Return slowly.","Keep the motion small."],"img":"opengym/1096.webp","gif":null,"ext":1},{"id":"1097","n":"suspension side bend","bp":"waist","eq":"suspension trainer","tg":"obliques","mg":"core","sm":["core"],"st":["Hold a handle and stand sideways to the anchor.","Brace your core.","Bend sideways away from the anchor.","Return to upright using your side muscles.","Do all reps, then switch sides.","Keep your hips still."],"img":"opengym/1097.webp","gif":null,"ext":1},{"id":"10977","n":"dumbbell hyperextension v. 2","bp":"back","eq":"dumbbell","tg":"spine","mg":"glutes","sm":["glutes","hamstrings"],"st":["Set the pad at hip height and hold a dumbbell at your chest.","Lower your torso with a flat back.","Lift until you are in a straight line.","Squeeze your glutes.","Lower slowly.","Do not overextend."],"img":"opengym/10977.webp","gif":null,"ext":1},{"id":"1098","n":"suspension side bridge","bp":"waist","eq":"suspension trainer","tg":"obliques","mg":"abdominals","sm":["abdominals","shoulders","glutes"],"st":["Lie on your side with feet in the straps and your elbow below your shoulder.","Lift your hips.","Hold a straight line.","Breathe steadily.","Hold for 20-30 seconds.","Switch sides."],"img":"opengym/1098.webp","gif":null,"ext":1},{"id":"10987","n":"dumbbell jump box","bp":"upper legs","eq":"dumbbell","tg":"quads","mg":"glutes","sm":["glutes","calves","hamstrings"],"st":["Stand in front of a sturdy box holding a dumbbell in each hand.","Dip into a quarter squat and swing your arms back.","Jump onto the box, landing softly with bent knees.","Stand tall on top.","Step down carefully and reset."],"img":"opengym/10987.webp","gif":null,"ext":1},{"id":"10988","n":"dumbbell kneeling to jump box","bp":"upper legs","eq":"dumbbell","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","calves","core"],"st":["Kneel in front of a box holding dumbbells at your sides.","Swing your arms and drive up to your feet.","Jump onto the box, landing softly.","Stand tall.","Step down carefully and reset to kneeling."],"img":"opengym/10988.webp","gif":null,"ext":1},{"id":"10989","n":"tuck planche on parallette","bp":"upper arms","eq":"body weight","tg":"delts","mg":"core","sm":["core","triceps","forearms","upper back"],"st":["Place your hands on parallettes and squat down.","Lean forward over your hands, arms straight.","Lift your feet with knees tucked toward the chest.","Hold for a few seconds, rounding your upper back slightly.","Lower your feet gently."],"img":"opengym/10989.webp","gif":null,"ext":1},{"id":"1099","n":"suspension single leg split squat (self assisted)","bp":"upper legs","eq":"suspension trainer","tg":"quads","mg":"glutes","sm":["glutes","hamstrings"],"st":["Hold the handles and place your back foot behind you.","Stand tall.","Lower your back knee toward the floor.","Use your arms for light help.","Press up through your front heel.","Switch legs."],"img":"opengym/1099.webp","gif":null,"ext":1},{"id":"10995","n":"forward and backward crab walk","bp":"full body","eq":"body weight","tg":"abs","mg":"triceps","sm":["triceps","glutes","shoulders","core"],"st":["Sit with hands behind you and feet flat, then lift your hips.","Keep your chest open and hips high.","Walk forward with alternating hands and feet.","Then walk backward the same way.","Keep your core braced."],"img":"opengym/10995.webp","gif":null,"ext":1},{"id":"10997","n":"wall assisted handstand to tuck planche negative","bp":"shoulders","eq":"body weight","tg":"delts","mg":"core","sm":["core","triceps","upper back","forearms"],"st":["Kick up into a handstand with your heels on the wall.","Brace your core and keep your arms straight.","Slowly lower your body forward.","Tuck your knees as you reach the planche position.","Control the descent and then reset."],"img":"opengym/10997.webp","gif":null,"ext":1},{"id":"10998","n":"wall facing single leg split handstand hold","bp":"shoulders","eq":"body weight","tg":"delts","mg":"core","sm":["core","triceps","forearms","upper back"],"st":["Kick up into a handstand facing the wall.","Keep your arms straight and push the floor away.","Lift one leg off the wall.","Hold for 10-20 seconds with control.","Return the leg and come down safely."],"img":"opengym/10998.webp","gif":null,"ext":1},{"id":"1100","n":"suspension single leg split squat","bp":"upper legs","eq":"suspension trainer","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","core"],"st":["Put your rear foot in the strap and step forward.","Stand tall.","Lower your hips, back knee down.","Keep your front knee over your foot.","Press up.","Switch legs."],"img":"opengym/1100.webp","gif":null,"ext":1},{"id":"11006","n":"seated arm crossover and chest out on a chair","bp":"chest","eq":"body weight","tg":"pectorals","mg":"shoulders","sm":["shoulders","upper back"],"st":["Sit tall on a chair.","Cross your arms in front of your chest and hug yourself.","Open your arms wide and push your chest out.","Hold the open position for 5-10 seconds.","Repeat."],"img":"opengym/11006.webp","gif":null,"ext":1},{"id":"1101","n":"suspension single leg squat","bp":"upper legs","eq":"suspension trainer","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","core"],"st":["Hold the handles and stand on one leg.","Extend the other leg forward.","Sit back and lower.","Keep your knee over your toes.","Stand up.","Switch legs."],"img":"opengym/1101.webp","gif":null,"ext":1},{"id":"11010","n":"hip lift low back off floor","bp":"waist","eq":"body weight","tg":"abs","mg":"lower abs","sm":["lower abs","hip flexors"],"st":["Lie on your back with legs raised toward the ceiling.","Press your arms into the floor.","Lift your hips so your lower back comes off the floor.","Lower slowly with control.","Avoid swinging."],"img":"opengym/11010.webp","gif":null,"ext":1},{"id":"11014","n":"dumbbell underhand front raise","bp":"shoulders","eq":"dumbbell","tg":"delts","mg":"upper chest","sm":["upper chest","biceps","core"],"st":["Stand holding a dumbbell in each hand, palms facing forward.","Keep your elbows slightly soft.","Raise your arms in front of you to shoulder height.","Pause at the top.","Lower slowly and avoid leaning back."],"img":"opengym/11014.webp","gif":null,"ext":1},{"id":"11015","n":"scapular pull up v. 2","bp":"back","eq":"body weight","tg":"upper back","mg":"lats","sm":["lats","rhomboids","trapezius","grip muscles"],"st":["Hang from a pull-up bar with an overhand grip, arms straight.","Let your shoulders relax up toward your ears.","Pull your shoulder blades down and together to lift your body a few centimetres.","Keep your elbows locked straight the whole time.","Pause briefly, then lower slowly back to the full hang."],"img":"opengym/11015.webp","gif":null,"ext":1},{"id":"11016","n":"dumbbell half kneeling single arm shoulder press","bp":"shoulders","eq":"dumbbell","tg":"delts","mg":"triceps","sm":["triceps","upper chest","core","glutes"],"st":["Kneel on one knee with the other foot flat in front, and hold a dumbbell at shoulder height.","Brace your core and squeeze the glute of the kneeling leg.","Press the dumbbell straight overhead until your arm is extended.","Lower it under control back to your shoulder.","Finish your reps, then switch sides."],"img":"opengym/11016.webp","gif":null,"ext":1},{"id":"11017","n":"dumbbell kneeling single arm shoulder press","bp":"shoulders","eq":"dumbbell","tg":"delts","mg":"triceps","sm":["triceps","upper chest","core","glutes"],"st":["Kneel on both knees with your hips tall and hold a dumbbell at shoulder height.","Brace your abs and keep your ribs down.","Press the dumbbell overhead until your arm is straight.","Lower it slowly back to your shoulder without leaning sideways.","Complete your reps, then switch arms."],"img":"opengym/11017.webp","gif":null,"ext":1},{"id":"1102","n":"suspension straight hip leg curl","bp":"upper legs","eq":"suspension trainer","tg":"hamstrings","mg":"glutes","sm":["glutes","core"],"st":["Lie on your back with heels in the straps.","Lift your hips into a straight line.","Curl your heels toward you.","Keep your hips high.","Extend slowly.","Repeat."],"img":"opengym/1102.webp","gif":null,"ext":1},{"id":"1103","n":"suspension triceps dip","bp":"upper arms","eq":"suspension trainer","tg":"triceps","mg":"chest","sm":["chest","shoulders"],"st":["Hold the handles with arms straight.","Keep your body upright.","Lower by bending your elbows.","Keep your elbows close.","Press back up.","Stay controlled."],"img":"opengym/1103.webp","gif":null,"ext":1},{"id":"1104","n":"suspension triceps extension v. 2","bp":"upper arms","eq":"suspension trainer","tg":"triceps","mg":"shoulders","sm":["shoulders","core"],"st":["Hold the handles and lean forward.","Keep your elbows bent and by your head.","Straighten your arms.","Keep your body straight.","Return slowly.","Keep your elbows still."],"img":"opengym/1104.webp","gif":null,"ext":1},{"id":"11047","n":"lying abduction","bp":"upper legs","eq":"body weight","tg":"abductors","mg":"glutes","sm":["glutes","obliques"],"st":["Lie on your side with your legs straight and stacked.","Rest your head on your lower arm and keep your hips stacked.","Lift your top leg up and slightly back without rolling your torso.","Pause at the top, then lower with control.","Finish your reps, then roll over and do the other side."],"img":"opengym/11047.webp","gif":null,"ext":1},{"id":"11048","n":"seated bent knee abduction","bp":"upper legs","eq":"body weight","tg":"abductors","mg":"glutes","sm":["glutes"],"st":["Sit tall with your knees bent and feet on the floor.","Place your hands on your outer knees.","Press your knees outward against your hands.","Hold briefly.","Release slowly.","Keep your back straight."],"img":"opengym/11048.webp","gif":null,"ext":1},{"id":"11049","n":"seated bent knee abduction feet floor off","bp":"upper legs","eq":"body weight","tg":"abductors","mg":"glutes","sm":["glutes","core"],"st":["Sit tall and lift your feet off the floor.","Hold the seat edge.","Open your knees outward.","Pause.","Close slowly.","Keep your back straight."],"img":"opengym/11049.webp","gif":null,"ext":1},{"id":"1105","n":"suspension twist","bp":"waist","eq":"suspension trainer","tg":"obliques","mg":"shoulders","sm":["shoulders","core"],"st":["Start in a plank with your feet in the straps.","Keep your arms straight.","Rotate your hips to one side.","Return to centre.","Rotate to the other side.","Keep your shoulders steady."],"img":"opengym/1105.webp","gif":null,"ext":1},{"id":"11050","n":"resistance band seated bent knee abduction feet floor off","bp":"upper legs","eq":"band","tg":"abductors","mg":"glutes","sm":["glutes","core"],"st":["Sit tall with a band around your thighs and feet off the floor.","Hold the seat edge.","Open your knees against the band.","Pause.","Close slowly.","Keep your back straight."],"img":"opengym/11050.webp","gif":null,"ext":1},{"id":"11051","n":"cable standing high cross neutral grip triceps extension","bp":"upper arms","eq":"cable","tg":"triceps","mg":"forearms","sm":["forearms","shoulders"],"st":["Set both pulleys high and stand in the middle, holding the handles with palms facing in.","Cross your hands in front of your chest with elbows tucked to your sides.","Press the handles down and out until your arms are straight.","Squeeze your triceps for a moment.","Let the handles rise back slowly without moving your elbows."],"img":"opengym/11051.webp","gif":null,"ext":1},{"id":"11053","n":"smith staggered stance hip thrust","bp":"upper legs","eq":"smith machine","tg":"glutes","mg":"hamstrings","sm":["hamstrings","core"],"st":["Sit with your upper back on a bench and the bar over your hips.","Stagger your feet, one slightly ahead.","Drive through your heels.","Lift your hips to full extension.","Squeeze your glutes.","Lower slowly and switch the stance."],"img":"opengym/11053.webp","gif":null,"ext":1},{"id":"11054","n":"lever staggered stance hip thrust (plate loaded)","bp":"upper legs","eq":"leverage machine","tg":"glutes","mg":"hamstrings","sm":["hamstrings","core"],"st":["Sit in the machine with the pad over your hips.","Stagger your feet.","Drive through your heels.","Lift your hips fully.","Squeeze your glutes.","Lower slowly and switch the stance."],"img":"opengym/11054.webp","gif":null,"ext":1},{"id":"11055","n":"lever belt sumo deadlift (v bar)","bp":"upper legs","eq":"leverage machine","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","adductors","lower back"],"st":["Stand wide on the platform with toes angled out and grip the V bar.","Sit your hips back, chest up, and keep your arms straight.","Push through your heels to stand fully upright.","Squeeze your glutes at the top.","Lower under control, letting your knees track over your toes."],"img":"opengym/11055.webp","gif":null,"ext":1},{"id":"11056","n":"lever seated scapular retraction (plate loaded)","bp":"back","eq":"leverage machine","tg":"upper back","mg":"rhomboids","sm":["rhomboids","trapezius","rear deltoids"],"st":["Sit with your chest against the pad and grab the handles with straight arms.","Let your shoulder blades spread forward slightly.","Squeeze your shoulder blades together without bending your elbows.","Hold the squeeze for a second.","Return slowly to the start."],"img":"opengym/11056.webp","gif":null,"ext":1},{"id":"11057","n":"cable seated scapular retraction","bp":"back","eq":"cable","tg":"upper back","mg":"rhomboids","sm":["rhomboids","trapezius","rear deltoids"],"st":["Sit at a low cable station, feet braced, and hold the handle with straight arms.","Sit tall and let your shoulder blades stretch forward.","Pull your shoulder blades together, keeping your arms straight.","Hold the squeeze briefly.","Return slowly to the start."],"img":"opengym/11057.webp","gif":null,"ext":1},{"id":"11058","n":"dumbbell hip supported romanian deadlift","bp":"upper legs","eq":"dumbbell","tg":"hamstrings","mg":"glutes","sm":["glutes","lower back","grip muscles"],"st":["Stand with your hips lightly against the support, holding dumbbells in front of your thighs.","Soften your knees and keep your back flat.","Push your hips back and slide the dumbbells down your legs.","Stop when you feel a stretch in your hamstrings.","Drive your hips forward to stand tall."],"img":"opengym/11058.webp","gif":null,"ext":1},{"id":"11059","n":"resistance band kneeling leg kickback on bench","bp":"upper legs","eq":"resistance band","tg":"glutes","mg":"hamstrings","sm":["hamstrings","core"],"st":["Anchor the band and loop it around one foot, then kneel on a bench with hands on the front.","Brace your core and keep your back flat.","Kick the working leg back and up until the hip is fully extended.","Squeeze the glute for a moment at the top.","Lower slowly under control without letting the band yank your leg.","Finish your reps, then switch legs."],"img":"opengym/11059.webp","gif":null,"ext":1},{"id":"1106","n":"suspender twisting jackknife","bp":"waist","eq":"suspension trainer","tg":"obliques","mg":"abdominals","sm":["abdominals","hip flexors","shoulders"],"st":["Set your feet in the straps and get into a straight-arm plank.","Keep your shoulders stacked over your hands.","Pull both knees toward your chest, twisting them toward one elbow.","Pause briefly, then extend the legs back to plank.","Alternate sides each rep.","Keep your hips from sagging as you return."],"img":"opengym/1106.webp","gif":null,"ext":1},{"id":"11060","n":"cable face pull with external rotation","bp":"shoulders","eq":"cable","tg":"delts","mg":"rear deltoids","sm":["rear deltoids","rotator cuff","rhomboids","trapezius"],"st":["Set a rope at upper chest height and hold it with both hands, arms extended.","Pull the rope toward your face with elbows high.","At the end, rotate your fists upward so your hands finish above your elbows.","Squeeze your rear shoulders for a second.","Reverse the rotation and return slowly."],"img":"opengym/11060.webp","gif":null,"ext":1},{"id":"1107","n":"suspender y lateral raise","bp":"shoulders","eq":"suspension trainer","tg":"delts","mg":"upper back","sm":["upper back","trapezius","rear deltoids"],"st":["Hold the handles and lean back with arms straight and body in a line.","Keep your core tight and feet planted.","Raise your arms up and out until they form a Y overhead.","Pause at the top without shrugging.","Lower slowly back to the start.","Step your feet forward to make it harder."],"img":"opengym/1107.webp","gif":null,"ext":1},{"id":"11077","n":"dumbbell over the chest lying abduction","bp":"upper legs","eq":"dumbbell","tg":"abductors","mg":"glutes","sm":["glutes","obliques","core"],"st":["Lie on your side with legs stacked and hold a dumbbell over your chest with both hands.","Keep your hips stacked and core braced.","Raise your top leg without rotating your torso.","Pause at the top.","Lower with control, finish your reps, then switch sides."],"img":"opengym/11077.webp","gif":null,"ext":1},{"id":"1108","n":"suspender arm curl to ears","bp":"upper arms","eq":"suspension trainer","tg":"biceps","mg":"forearms","sm":["forearms","brachialis","core"],"st":["Hold the handles with palms up and lean back with arms extended.","Keep your body straight from head to heels.","Bend your elbows and pull your hands toward your ears.","Keep elbows high and out to the sides.","Squeeze the biceps at the top.","Lower with control until the arms are straight."],"img":"opengym/1108.webp","gif":null,"ext":1},{"id":"11088","n":"reverse lunge arm reach twist","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","obliques","core"],"st":["Stand tall with your arms by your sides.","Step one leg back into a lunge and reach both arms overhead.","Twist your torso toward the front leg.","Untwist, then push through your front foot to stand.","Alternate legs for the set."],"img":"opengym/11088.webp","gif":null,"ext":1},{"id":"11089","n":"split stretch spine rolling","bp":"waist","eq":"body weight","tg":"spine","mg":"hamstrings","sm":["hamstrings","adductors","core"],"st":["Sit on the floor with your legs spread wide in a comfortable split.","Sit tall and reach your arms forward.","Round your spine and roll down slowly, one segment at a time.","Roll back up slowly until you are upright.","Repeat for 8-10 slow reps without forcing the stretch."],"img":"opengym/11089.webp","gif":null,"ext":1},{"id":"1109","n":"suspender biceps clutch","bp":"upper arms","eq":"suspension trainer","tg":"biceps","mg":"forearms","sm":["forearms","brachialis","upper back"],"st":["Grab the handles palms up and lean back with arms straight.","Keep your body rigid.","Curl yourself up, drawing the hands in beside your head.","Hold the top position for a second and squeeze.","Lower slowly to straight arms.","Walk your feet closer to make it easier."],"img":"opengym/1109.webp","gif":null,"ext":1},{"id":"11090","n":"negative front lever raise","bp":"waist","eq":"body weight","tg":"abs","mg":"lats","sm":["lats","lower abs","grip muscles","upper back"],"st":["Hang from a bar and pull your body up so your hips and legs are above you.","Straighten your body and keep your arms locked.","Lower slowly toward a horizontal position, keeping your body in a straight line.","Stop when you cannot hold the line, then bend your knees to come back up.","Rest and repeat for a few careful reps."],"img":"opengym/11090.webp","gif":null,"ext":1},{"id":"11091","n":"single arm hanging toes to bar","bp":"waist","eq":"body weight","tg":"abs","mg":"hip flexors","sm":["hip flexors","lower abs","grip muscles","obliques"],"st":["Hang from a bar with one hand and keep your shoulder active.","Brace your core and keep your legs together.","Lift your toes up toward the bar.","Lower your legs slowly without swinging.","Finish your reps, then switch hands."],"img":"opengym/11091.webp","gif":null,"ext":1},{"id":"11092","n":"landmine kneeling 180s","bp":"waist","eq":"landmine","tg":"abs","mg":"obliques","sm":["obliques","shoulders","core"],"st":["Kneel facing the landmine and hold the end of the bar with both hands in front of your chest.","Keep your hips squared and core tight.","Swing the bar in an arc to one side by rotating your torso.","Swing across to the other side in a controlled sweep.","Keep a steady rhythm for the set."],"img":"opengym/11092.webp","gif":null,"ext":1},{"id":"11093","n":"barbell 2 3 deadlift","bp":"upper legs","eq":"barbell","tg":"glutes","mg":"hamstrings","sm":["hamstrings","quadriceps","lower back","grip muscles"],"st":["Stand with your feet hip width and the bar over your mid foot.","Grip the bar, brace your core, and keep your back flat.","Push the floor away and stand up.","Lower the bar back toward the floor under control.","Reset each rep and keep your back neutral."],"img":"opengym/11093.webp","gif":null,"ext":1},{"id":"11095","n":"sitting cat cow stretch on a chair","bp":"back","eq":"body weight","tg":"spine","mg":"core","sm":["core","lower back"],"st":["Sit tall on a chair with your hands on your knees and feet flat.","Inhale, arch your back and lift your chest.","Exhale, round your spine and tuck your chin.","Move slowly between the two positions.","Repeat for 8-10 breaths."],"img":"opengym/11095.webp","gif":null,"ext":1},{"id":"1110","n":"suspender body saw","bp":"waist","eq":"suspension trainer","tg":"abs","mg":"shoulders","sm":["shoulders","lower back","core"],"st":["Place your feet in the straps and set up on your forearms.","Brace your abs and keep your body straight.","Shift your body backward by pushing through the forearms.","Rock forward past the starting point in a short controlled motion.","Keep your hips level, do not let your lower back arch.","Continue for the planned reps or time."],"img":"opengym/1110.webp","gif":null,"ext":1},{"id":"1111","n":"suspender close grip chest press","bp":"chest","eq":"suspension trainer","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders","core"],"st":["Hold the handles close together and lean forward with arms straight.","Keep your body in a straight line.","Lower your chest between the handles, elbows tucked close.","Pause when your chest is near your hands.","Press back up until the arms are straight.","Move your feet back to increase difficulty."],"img":"opengym/1111.webp","gif":null,"ext":1},{"id":"1112","n":"suspender crunch","bp":"waist","eq":"suspension trainer","tg":"abs","mg":"hip flexors","sm":["hip flexors","lower abs","shoulders"],"st":["Put your feet in the straps and set a straight-arm plank.","Keep shoulders over hands.","Pull your knees toward your chest while rounding your spine slightly.","Squeeze your abs at the top.","Extend your legs back to plank slowly.","Avoid dropping the hips as you return."],"img":"opengym/1112.webp","gif":null,"ext":1},{"id":"1113","n":"suspender face pull","bp":"shoulders","eq":"suspension trainer","tg":"delts","mg":"rear deltoids","sm":["rear deltoids","upper back","rotator cuff"],"st":["Hold the handles with palms facing in and lean back.","Keep your body straight and arms extended.","Pull the handles toward your forehead, elbows flaring high.","Squeeze your shoulder blades together at the end.","Lower slowly to full arm extension.","Do not let your hips drop."],"img":"opengym/1113.webp","gif":null,"ext":1},{"id":"1115","n":"suspender handstand push up","bp":"upper arms","eq":"suspension trainer","tg":"delts","mg":"triceps","sm":["triceps","core"],"st":["Set the straps low and place your hands in the handles in a pike position.","Kick or walk your feet up into an inverted position with a tight core.","Bend your elbows to lower your head between the handles.","Press back up until your arms are straight.","Keep your body steady, using a wall or spotter if needed.","Come down carefully when finished."],"img":"opengym/1115.webp","gif":null,"ext":1},{"id":"1116","n":"suspender incline push up","bp":"chest","eq":"suspension trainer","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders","core"],"st":["Hold the handles and walk your feet back so your body is at a slant.","Keep your body straight and core tight.","Lower your chest to the handles by bending the elbows.","Keep elbows at about 45 degrees.","Press up to straight arms.","Walk your feet back to make it harder."],"img":"opengym/1116.webp","gif":null,"ext":1},{"id":"1117","n":"suspender jump squat","bp":"upper legs","eq":"suspension trainer","tg":"quads","mg":"glutes","sm":["glutes","calves","hamstrings"],"st":["Hold the handles with slightly bent arms and stand tall.","Lower into a squat with your chest up.","Drive through your feet and jump up.","Land softly on the balls of your feet and sink into the next squat.","Use the straps for balance only.","Keep knees tracking over toes."],"img":"opengym/1117.webp","gif":null,"ext":1},{"id":"1119","n":"suspender lunge back crossover","bp":"upper legs","eq":"suspension trainer","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","adductors"],"st":["Hold the handles and stand facing the anchor.","Step one leg back and across behind the other.","Lower until the front thigh is near parallel.","Keep your chest tall and front knee over the ankle.","Push through the front heel to stand.","Finish your reps, then switch sides."],"img":"opengym/1119.webp","gif":null,"ext":1},{"id":"1120","n":"suspender middle row","bp":"shoulders","eq":"suspension trainer","tg":"upper back","mg":"lats","sm":["lats","rhomboids","biceps"],"st":["Grip the handles and lean back with arms straight.","Keep your body in a straight line.","Pull your chest toward your hands, elbows close by.","Squeeze the shoulder blades together.","Lower slowly to straight arms.","Step forward to ease the load."],"img":"opengym/1120.webp","gif":null,"ext":1},{"id":"1121","n":"suspender mountain climber push up","bp":"upper legs","eq":"suspension trainer","tg":"quads","mg":"core","sm":["core","hip flexors","chest"],"st":["Place your feet in the straps and set up in a high plank.","Do one push-up, keeping your body straight.","Drive one knee toward your chest, then the other.","Alternate legs in a steady rhythm.","Keep your hips level.","Repeat the sequence for the set."],"img":"opengym/1121.webp","gif":null,"ext":1},{"id":"1122","n":"suspender oblique rollout","bp":"waist","eq":"suspension trainer","tg":"obliques","mg":"shoulders","sm":["shoulders","core"],"st":["Hold the handles kneeling or standing, arms in front.","Brace your core and keep your back flat.","Roll forward and angle your arms toward one side.","Go only as far as you can hold a flat back.","Pull back to the start using your abs.","Alternate sides each rep."],"img":"opengym/1122.webp","gif":null,"ext":1},{"id":"1123","n":"suspender one arm biceps curl","bp":"upper arms","eq":"suspension trainer","tg":"biceps","mg":"forearms","sm":["forearms","brachialis","obliques"],"st":["Hold one handle palm up and lean back at an angle.","Keep your feet planted and body straight.","Bend the elbow and pull your body toward your hand.","Squeeze the biceps at the top.","Lower slowly to a straight arm.","Finish your reps and switch arms."],"img":"opengym/1123.webp","gif":null,"ext":1},{"id":"1124","n":"suspender one arm chest press","bp":"chest","eq":"suspension trainer","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders","obliques"],"st":["Hold one handle, lean forward and place your feet wide for balance.","Keep your hips square.","Bend your elbow and lower your chest toward the hand.","Resist twisting at the torso.","Press back to a straight arm.","Do all reps, then switch sides."],"img":"opengym/1124.webp","gif":null,"ext":1},{"id":"1125","n":"suspender one arm leg push up","bp":"chest","eq":"suspension trainer","tg":"pectorals","mg":"triceps","sm":["triceps","core","shoulders"],"st":["Put your feet in the straps and set a plank with one hand on the floor.","Brace your core firmly.","Lower your chest by bending the supporting elbow.","Keep your hips level and avoid twisting.","Press back up.","Complete your reps, then switch hands."],"img":"opengym/1125.webp","gif":null,"ext":1},{"id":"11250","n":"cable standing fly v. 3","bp":"chest","eq":"cable","tg":"pectorals","mg":"upper chest","sm":["upper chest","shoulders"],"st":["Set both pulleys at shoulder height and hold a handle in each hand.","Step forward with a staggered stance and lean slightly.","With soft elbows, bring your hands together in front of your chest.","Squeeze your chest for a moment.","Open your arms slowly until you feel a stretch."],"img":"opengym/11250.webp","gif":null,"ext":1},{"id":"11251","n":"cable kneeling woodchop v. 3","bp":"waist","eq":"cable","tg":"obliques","mg":"shoulders","sm":["shoulders","core"],"st":["Set the cable high, kneel side-on to it and hold the handle with both hands.","Keep your hips square and your core tight.","Pull the handle diagonally across your body down toward the opposite hip.","Rotate through your torso, not your arms.","Return slowly, finish your reps, then switch sides."],"img":"opengym/11251.webp","gif":null,"ext":1},{"id":"11252","n":"cable overhead squat v. 3","bp":"upper legs","eq":"cable","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","shoulders","core"],"st":["Set a cable low and hold the handle overhead with straight arms, standing tall.","Brace your core and keep your ribs down.","Squat down by pushing your hips back and bending your knees.","Keep the handle over your head and chest up.","Drive through your heels to stand."],"img":"opengym/11252.webp","gif":null,"ext":1},{"id":"11253","n":"cable kneeling pulldown v. 3","bp":"back","eq":"cable","tg":"lats","mg":"biceps","sm":["biceps","rhomboids","rear deltoids","core"],"st":["Kneel facing a high pulley and hold the bar or handles with arms extended.","Sit tall with your core braced.","Pull the handle down toward your chest, driving your elbows down.","Squeeze your lats at the bottom.","Let the handle rise back slowly to a full stretch."],"img":"opengym/11253.webp","gif":null,"ext":1},{"id":"11254","n":"cable standing reverse fly v. 3","bp":"shoulders","eq":"cable","tg":"delts","mg":"rear deltoids","sm":["rear deltoids","rhomboids","trapezius"],"st":["Set the pulleys at shoulder height and hold the opposite handles, arms crossed.","Stand tall with soft elbows.","Pull your hands apart and back in a wide arc.","Squeeze your shoulder blades together.","Return slowly to the crossed start."],"img":"opengym/11254.webp","gif":null,"ext":1},{"id":"11255","n":"cable lateral lunge v. 3","bp":"upper legs","eq":"cable","tg":"glutes","mg":"quadriceps","sm":["quadriceps","adductors","hamstrings"],"st":["Stand side-on to a low pulley and hold the handle at your chest.","Step wide to the side and sit your hips back.","Keep the other leg straight and your chest up.","Push through the bent leg to return to standing.","Finish your reps, then switch sides."],"img":"opengym/11255.webp","gif":null,"ext":1},{"id":"11256","n":"cable bench press v. 3","bp":"chest","eq":"cable","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders","upper chest"],"st":["Lie on a bench between two low pulleys and hold a handle in each hand at chest level.","Plant your feet and keep your shoulder blades back.","Press the handles up until your arms are straight.","Squeeze your chest at the top.","Lower slowly until you feel a stretch."],"img":"opengym/11256.webp","gif":null,"ext":1},{"id":"11257","n":"cable seated high row v. 3","bp":"back","eq":"cable","tg":"lats","mg":"upper back","sm":["upper back","rhomboids","rear deltoids","biceps","trapezius"],"st":["Sit at a cable station with the pulley set high and grab the handles.","Sit tall with your chest up.","Pull the handles toward your upper chest, elbows flaring slightly.","Squeeze your shoulder blades together.","Return slowly to full arm extension."],"img":"opengym/11257.webp","gif":null,"ext":1},{"id":"11258","n":"cable standing push pull v. 3","bp":"back","eq":"cable","tg":"upper back","mg":"chest","sm":["chest","triceps","biceps","core"],"st":["Stand in a staggered stance between two cables, one handle in each hand.","Brace your core and keep your hips square.","Press one handle forward while pulling the other back toward your ribs.","Reverse the roles slowly.","Alternate sides for the set."],"img":"opengym/11258.webp","gif":null,"ext":1},{"id":"11259","n":"cable standing hip extension v. 3","bp":"upper legs","eq":"cable","tg":"glutes","mg":"hamstrings","sm":["hamstrings","core"],"st":["Attach an ankle strap to a low pulley and stand facing the machine, holding on for balance.","Keep your core tight and your torso upright.","Push your working leg straight back.","Squeeze your glute at the top without arching.","Return slowly, finish your reps, then switch legs."],"img":"opengym/11259.webp","gif":null,"ext":1},{"id":"1126","n":"suspender one leg chest press","bp":"chest","eq":"suspension trainer","tg":"pectorals","mg":"triceps","sm":["triceps","core","glutes"],"st":["Hold the handles, lean forward and lift one foot off the floor.","Keep your body straight.","Lower your chest between your hands.","Press back up without letting the hips drop.","Keep the raised leg in line with your body.","Switch legs after your set."],"img":"opengym/1126.webp","gif":null,"ext":1},{"id":"11260","n":"cable kneeling military press v. 3","bp":"shoulders","eq":"cable","tg":"delts","mg":"triceps","sm":["triceps","upper chest","core","glutes"],"st":["Kneel between two low pulleys and hold the handles at shoulder height.","Squeeze your glutes and brace your abs.","Press both handles straight overhead.","Lock out without leaning back.","Lower under control to your shoulders."],"img":"opengym/11260.webp","gif":null,"ext":1},{"id":"11261","n":"cable standing biceps curl (rope attachment) v. 3","bp":"upper arms","eq":"cable","tg":"biceps","mg":"brachialis","sm":["brachialis","forearms"],"st":["Attach a rope to a low pulley and hold it with palms facing each other.","Stand tall with your elbows at your sides.","Curl the rope up toward your shoulders.","Squeeze your biceps at the top.","Lower slowly without swinging your body."],"img":"opengym/11261.webp","gif":null,"ext":1},{"id":"11262","n":"cable lying alternating bent leg jackknife v. 3","bp":"waist","eq":"cable","tg":"abs","mg":"lower abs","sm":["lower abs","hip flexors","core"],"st":["Lie on your back with your feet attached to a low cable and hands by your sides.","Press your lower back into the floor.","Bring one bent knee toward your chest.","Lower it slowly and switch legs.","Keep a controlled alternating rhythm."],"img":"opengym/11262.webp","gif":null,"ext":1},{"id":"11263","n":"cable single arm row with rotation v. 3","bp":"back","eq":"cable","tg":"upper back","mg":"lats","sm":["lats","rhomboids","biceps","obliques"],"st":["Stand facing a cable at chest height with a single handle in one hand.","Take a staggered stance and brace your core.","Row the handle to your ribs while rotating your torso slightly.","Squeeze your back at the end.","Return slowly, finish your reps, then switch arms."],"img":"opengym/11263.webp","gif":null,"ext":1},{"id":"11264","n":"cable incline bench press v. 3","bp":"chest","eq":"cable","tg":"pectorals","mg":"upper chest","sm":["upper chest","triceps","shoulders"],"st":["Set an incline bench between two low pulleys and hold a handle in each hand.","Plant your feet and pull your shoulder blades back.","Press the handles up and slightly together.","Squeeze your upper chest at the top.","Lower slowly to a comfortable stretch."],"img":"opengym/11264.webp","gif":null,"ext":1},{"id":"11265","n":"cable standing hip flexion v. 3","bp":"upper legs","eq":"cable","tg":"hip flexors","mg":"quadriceps","sm":["quadriceps","core"],"st":["Attach an ankle strap to a low pulley, face away from the machine, and hold on for balance.","Stand tall with your core braced.","Drive your working knee forward and up.","Pause at the top.","Lower slowly, finish your reps, then switch legs."],"img":"opengym/11265.webp","gif":null,"ext":1},{"id":"11266","n":"cable standing hip abduction v. 3","bp":"upper legs","eq":"cable","tg":"abductors","mg":"glutes","sm":["glutes","obliques"],"st":["Attach an ankle strap to a low pulley on the near side and hold something for balance.","Stand tall with your core tight.","Lift your outside leg out to the side.","Pause at the top without leaning.","Return slowly, finish your reps, then switch sides."],"img":"opengym/11266.webp","gif":null,"ext":1},{"id":"11267","n":"cable standing hip adduction v. 3","bp":"upper legs","eq":"cable","tg":"adductors","mg":"inner thighs","sm":["inner thighs","groin"],"st":["Attach an ankle strap to a low pulley on the far side and hold something for balance.","Stand tall with your core tight.","Sweep your working leg across in front of the other leg.","Squeeze your inner thigh.","Return slowly, finish your reps, then switch sides."],"img":"opengym/11267.webp","gif":null,"ext":1},{"id":"11268","n":"cable squat v. 3","bp":"upper legs","eq":"cable","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","core"],"st":["Hold a cable handle at your chest and stand with feet shoulder width.","Brace your core and keep your chest up.","Sit down and back until your thighs are about parallel.","Keep your knees tracking over your toes.","Drive through your heels to stand."],"img":"opengym/11268.webp","gif":null,"ext":1},{"id":"11269","n":"cable bent over single arm row v. 3","bp":"back","eq":"cable","tg":"upper back","mg":"lats","sm":["lats","rhomboids","biceps","rear deltoids"],"st":["Face a low pulley, hinge forward with a flat back and hold the handle.","Brace your core and keep your hips back.","Row the handle toward your hip.","Squeeze your back at the top.","Lower slowly, finish your reps, then switch arms."],"img":"opengym/11269.webp","gif":null,"ext":1},{"id":"1127","n":"suspender pull up v. 2","bp":"back","eq":"suspension trainer","tg":"lats","mg":"biceps","sm":["biceps","upper back","forearms"],"st":["Hold the handles overhead and hang with arms straight.","Brace your core.","Pull your chest up toward the handles, elbows down.","Squeeze your back at the top.","Lower slowly to full extension.","Bend your knees or lean back to make it easier."],"img":"opengym/1127.webp","gif":null,"ext":1},{"id":"11270","n":"cable kneeling crunch v. 3","bp":"waist","eq":"cable","tg":"abs","mg":"lower abs","sm":["lower abs","obliques","core"],"st":["Kneel under a high pulley and hold the rope beside your head.","Keep your hips still.","Curl your torso down, bringing elbows toward your knees.","Squeeze your abs at the bottom.","Return slowly to the upright start."],"img":"opengym/11270.webp","gif":null,"ext":1},{"id":"11271","n":"cable standing torso twist v. 3","bp":"waist","eq":"cable","tg":"obliques","mg":"core","sm":["core","shoulders"],"st":["Stand side-on to a cable set at chest height and hold the handle with both hands.","Keep your arms straight and feet planted.","Rotate your torso away from the machine.","Pause, then return slowly.","Finish your reps, then switch sides."],"img":"opengym/11271.webp","gif":null,"ext":1},{"id":"11272","n":"cable standing biceps curl to arnold press v. 3","bp":"shoulders","eq":"cable","tg":"delts","mg":"biceps","sm":["biceps","triceps","upper chest","forearms"],"st":["Hold low cable handles, palms forward, arms down.","Curl the handles up to your shoulders.","Rotate your palms inward as you start to press.","Press overhead, turning your palms forward.","Reverse the move and lower under control."],"img":"opengym/11272.webp","gif":null,"ext":1},{"id":"11273","n":"cable lying fly v. 3","bp":"chest","eq":"cable","tg":"pectorals","mg":"upper chest","sm":["upper chest","shoulders"],"st":["Lie on a bench between two low pulleys and hold a handle in each hand over your chest.","Keep a soft bend in your elbows.","Lower your arms out to the sides in a wide arc.","Stop at a comfortable stretch.","Bring the handles back together over your chest."],"img":"opengym/11273.webp","gif":null,"ext":1},{"id":"11274","n":"cable standing alternating diagonal chest press v. 3","bp":"chest","eq":"cable","tg":"pectorals","mg":"upper chest","sm":["upper chest","triceps","shoulders","core"],"st":["Stand in a staggered stance holding a high cable handle in each hand.","Brace your core.","Press one handle forward and down diagonally.","Return slowly and press with the other arm.","Alternate for the set without twisting your hips."],"img":"opengym/11274.webp","gif":null,"ext":1},{"id":"11275","n":"cable side plank row v. 3","bp":"waist","eq":"cable","tg":"obliques","mg":"abdominals","sm":["abdominals","lats","upper back","shoulders"],"st":["Set up in a side plank with a low cable handle in your top hand.","Lift your hips so your body is in a straight line.","Row the handle toward your ribs.","Keep your hips high and stable.","Extend slowly, finish your reps, then switch sides."],"img":"opengym/11275.webp","gif":null,"ext":1},{"id":"11276","n":"cable prone single leg curl v. 3","bp":"upper legs","eq":"cable","tg":"hamstrings","mg":"calves","sm":["calves","glutes"],"st":["Lie face down with an ankle strap attached to a low cable.","Keep your hips pressed down.","Curl your heel toward your glutes.","Squeeze your hamstring at the top.","Lower slowly, finish your reps, then switch legs."],"img":"opengym/11276.webp","gif":null,"ext":1},{"id":"11277","n":"cable standing front raise v. 3","bp":"shoulders","eq":"cable","tg":"delts","mg":"upper chest","sm":["upper chest","core"],"st":["Stand facing away from a low pulley, holding the handle between your legs.","Keep your core tight and arm nearly straight.","Raise the handle forward to shoulder height.","Pause briefly.","Lower slowly, finish your reps, then switch arms."],"img":"opengym/11277.webp","gif":null,"ext":1},{"id":"11278","n":"cable standing side bend v. 3","bp":"waist","eq":"cable","tg":"obliques","mg":"core","sm":["core"],"st":["Stand side-on to a low pulley and hold the handle at your side.","Keep your chest tall.","Bend sideways away from the machine.","Contract your obliques to return upright.","Finish your reps, then switch sides."],"img":"opengym/11278.webp","gif":null,"ext":1},{"id":"11279","n":"cable standing single arm overhead triceps extension v. 3","bp":"upper arms","eq":"cable","tg":"triceps","mg":"shoulders","sm":["shoulders","core"],"st":["Hold a handle from a low pulley overhead, elbow bent, with your upper arm close to your head.","Brace your core.","Straighten your arm overhead.","Squeeze your triceps at the top.","Lower slowly, finish your reps, then switch arms."],"img":"opengym/11279.webp","gif":null,"ext":1},{"id":"11282","n":"glute ham developer straight arms sit up","bp":"waist","eq":"body weight","tg":"abs","mg":"hip flexors","sm":["hip flexors","lower abs","core"],"st":["Set up on the GHD with your feet secured and hips on the pad.","Extend your arms overhead and lean back.","Curl up, bringing your arms forward.","Reach your torso over your knees.","Lower slowly with control."],"img":"opengym/11282.webp","gif":null,"ext":1},{"id":"11283","n":"criss cross tuck jump","bp":"full body","eq":"body weight","tg":"cardiovascular system","mg":"quadriceps","sm":["quadriceps","calves","core","glutes"],"st":["Stand tall with feet shoulder width apart.","Jump up and pull your knees toward your chest.","Cross your feet in the air.","Land softly on the balls of your feet.","Uncross on the next jump, alternating the crossing foot.","Keep a steady quick rhythm."],"img":"opengym/11283.webp","gif":null,"ext":1},{"id":"11284","n":"kettlebell single arm alternate fly","bp":"chest","eq":"kettlebell","tg":"pectorals","mg":"shoulders","sm":["shoulders","core","upper chest"],"st":["Lie on your back holding a kettlebell over your chest in one hand.","Keep a soft bend in your elbow.","Lower the kettlebell out to the side in an arc.","Bring it back over your chest.","Switch hands and alternate."],"img":"opengym/11284.webp","gif":null,"ext":1},{"id":"11285","n":"resistance band lying floor chest press","bp":"chest","eq":"resistance band","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders","upper chest"],"st":["Lie on your back with the band under your upper back and a handle in each hand.","Start with your hands at chest level.","Press your hands straight up until your arms extend.","Squeeze your chest.","Lower slowly back to the start."],"img":"opengym/11285.webp","gif":null,"ext":1},{"id":"11286","n":"kettlebell half kneeling side lunge","bp":"upper legs","eq":"kettlebell","tg":"adductors","mg":"glutes","sm":["glutes","quadriceps","groin","core"],"st":["Start in a half kneeling position holding a kettlebell at your chest.","Straighten the front leg to the side as you shift your weight back.","Feel a stretch in your inner thigh.","Return to the start.","Finish your reps, then switch sides."],"img":"opengym/11286.webp","gif":null,"ext":1},{"id":"11287","n":"kettlebell standing behind back romanian deadlift","bp":"upper legs","eq":"kettlebell","tg":"hamstrings","mg":"glutes","sm":["glutes","lower back","grip muscles"],"st":["Hold a kettlebell behind your back in both hands, feet hip width.","Soften your knees and brace your core.","Push your hips back and hinge forward with a flat back.","Stop when you feel your hamstrings stretch.","Drive your hips forward to stand tall."],"img":"opengym/11287.webp","gif":null,"ext":1},{"id":"11288","n":"bodyweight standing overhead shrug","bp":"back","eq":"body weight","tg":"traps","mg":"trapezius","sm":["trapezius","shoulders"],"st":["Stand tall and raise your arms straight overhead.","Keep your ribs down and core tight.","Shrug your shoulders up toward your ears.","Pause briefly.","Lower slowly and repeat."],"img":"opengym/11288.webp","gif":null,"ext":1},{"id":"11289","n":"standing ankle and hip drill","bp":"lower legs","eq":"body weight","tg":"calves","mg":"ankles","sm":["ankles","hip flexors","glutes"],"st":["Stand tall with your feet hip width.","Shift your weight onto one foot.","Rotate your ankle and hip through a smooth circle.","Keep your upper body steady.","Do 8-10 slow reps, then switch sides."],"img":"opengym/11289.webp","gif":null,"ext":1},{"id":"1129","n":"suspender rear lunge","bp":"upper legs","eq":"suspension trainer","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","core"],"st":["Hold the handles and stand tall, facing the anchor.","Step one leg back and lower into a lunge.","Keep your front knee above the ankle.","Press through the front heel to return.","Use the straps for balance only.","Alternate legs or finish one side first."],"img":"opengym/1129.webp","gif":null,"ext":1},{"id":"1130","n":"suspender reverse fly wake up","bp":"back","eq":"suspension trainer","tg":"delts","mg":"rear deltoids","sm":["rear deltoids","rhomboids","trapezius"],"st":["Hold the handles and lean back with arms straight in front.","Keep your body in a line.","Open your arms wide, pulling the shoulder blades together.","Keep arms slightly bent and level with the shoulders.","Return slowly to the start.","Walk your feet forward to lighten the load."],"img":"opengym/1130.webp","gif":null,"ext":1},{"id":"11303","n":"smith bench squat","bp":"upper legs","eq":"smith machine","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","core"],"st":["Set a bench behind you and place the bar on your upper back.","Unrack and step your feet slightly forward.","Sit down until you lightly touch the bench.","Keep your chest up and knees tracking over your toes.","Drive through your heels to stand."],"img":"opengym/11303.webp","gif":null,"ext":1},{"id":"11309","n":"lever single arm reverse grip lateral pulldown (plate loaded)","bp":"back","eq":"leverage machine","tg":"lats","mg":"biceps","sm":["biceps","upper back","rhomboids"],"st":["Sit in the machine and grab one handle with an underhand grip.","Sit tall and brace your core.","Pull the handle down, driving your elbow toward your side.","Squeeze your lat at the bottom.","Return slowly, finish your reps, then switch arms."],"img":"opengym/11309.webp","gif":null,"ext":1},{"id":"1131","n":"suspender side cross lunge","bp":"upper legs","eq":"suspension trainer","tg":"glutes","mg":"adductors","sm":["adductors","quadriceps","hamstrings"],"st":["Hold the handles and stand tall.","Step one leg out and slightly behind the other, crossing the body.","Sink back into the hip with a flat back.","Push through the working foot to return.","Keep your knee in line with your toes.","Switch sides after your reps."],"img":"opengym/1131.webp","gif":null,"ext":1},{"id":"11315","n":"incline close grip push up with chair against wall","bp":"upper arms","eq":"body weight","tg":"triceps","mg":"chest","sm":["chest","shoulders","core"],"st":["Brace a chair against a wall and place your hands close together on the seat.","Walk your feet back until your body is in a straight line.","Lower your chest toward the chair, elbows close to your body.","Press back up until your arms are straight.","Keep your hips in line."],"img":"opengym/11315.webp","gif":null,"ext":1},{"id":"11316","n":"standing wall slide half squat","bp":"upper legs","eq":"body weight","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","calves"],"st":["Stand with your back against a wall and your feet slightly forward.","Slide down until your knees are bent to about 45 degrees.","Keep your back flat on the wall.","Press through your heels to rise.","Repeat for the set."],"img":"opengym/11316.webp","gif":null,"ext":1},{"id":"11317","n":"weighted plate hyperextension v. 2","bp":"back","eq":"weight plate","tg":"spine","mg":"glutes","sm":["glutes","hamstrings","lower back"],"st":["Set up on a hyperextension bench with your feet secured and hold a plate against your chest.","Keep your back straight and body in a line.","Lower your torso with control.","Raise until you are back in a straight line.","Squeeze your glutes at the top without overarching."],"img":"opengym/11317.webp","gif":null,"ext":1},{"id":"1132","n":"suspender side lunge","bp":"upper legs","eq":"suspension trainer","tg":"glutes","mg":"quadriceps","sm":["quadriceps","adductors","hamstrings"],"st":["Hold the handles and stand with feet together.","Step out wide to one side.","Bend that knee and push your hips back, keeping the other leg straight.","Keep your chest up and heel down.","Push off to return to the start.","Alternate sides."],"img":"opengym/1132.webp","gif":null,"ext":1},{"id":"1133","n":"suspender single arm rear delt row","bp":"shoulders","eq":"suspension trainer","tg":"delts","mg":"rear deltoids","sm":["rear deltoids","upper back","biceps"],"st":["Hold one handle and lean back at an angle.","Keep your hips level and free hand on your chest or hip.","Pull the handle toward your shoulder with the elbow flared out.","Squeeze the rear delt at the end.","Lower slowly to a straight arm.","Finish your reps, then switch arms."],"img":"opengym/1133.webp","gif":null,"ext":1},{"id":"1134","n":"suspender single leg plank straight arm","bp":"waist","eq":"suspension trainer","tg":"abs","mg":"shoulders","sm":["shoulders","glutes","core"],"st":["Put your feet in the straps and set a high plank.","Lift one leg slightly higher.","Keep your hips level and body straight.","Hold for 20-30 seconds.","Lower the leg and switch sides.","Breathe steadily throughout."],"img":"opengym/1134.webp","gif":null,"ext":1},{"id":"1135","n":"suspender single leg plank","bp":"waist","eq":"suspension trainer","tg":"abs","mg":"shoulders","sm":["shoulders","glutes","core"],"st":["Place your feet in the straps and rest on your forearms.","Lift one leg a bit higher than the other.","Keep your hips square and abs tight.","Hold for 20-30 seconds.","Lower and switch legs.","Do not let the lower back arch."],"img":"opengym/1135.webp","gif":null,"ext":1},{"id":"1136","n":"suspender single leg squat figure","bp":"upper legs","eq":"suspension trainer","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","core"],"st":["Hold the handles and stand on one leg, other leg forward.","Sit your hips back and bend the knee.","Lower as far as you can control.","Keep your knee over your toes and chest tall.","Drive through the heel to stand.","Finish your reps, then switch legs."],"img":"opengym/1136.webp","gif":null,"ext":1},{"id":"1137","n":"suspender sit up","bp":"waist","eq":"suspension trainer","tg":"abs","mg":"hip flexors","sm":["hip flexors","obliques","core"],"st":["Lie on your back with your feet in the straps and knees bent.","Place your hands by your head or across your chest.","Curl your torso up toward your knees.","Squeeze the abs at the top.","Lower back down slowly.","Avoid pulling on your neck."],"img":"opengym/1137.webp","gif":null,"ext":1},{"id":"11374","n":"sleepers stretch","bp":"shoulders","eq":"body weight","tg":"delts","mg":"rotator cuff","sm":["rotator cuff","rear deltoids"],"st":["Lie on your side with the bottom arm in front of you, elbow bent to 90 degrees.","Keep your shoulder stacked and the upper arm at chest height.","Use your top hand to gently press the bottom forearm toward the floor.","Stop where you feel a mild stretch at the back of the shoulder.","Hold for 20-30 seconds, then switch sides."],"img":"opengym/11374.webp","gif":null,"ext":1},{"id":"1138","n":"suspender spiderman push up","bp":"chest","eq":"suspension trainer","tg":"pectorals","mg":"triceps","sm":["triceps","obliques","core","hip flexors"],"st":["Put your feet in the straps and set a high plank.","Lower into a push-up.","As you descend, bring one knee toward the same elbow.","Press up and extend the leg back.","Alternate sides each rep.","Keep your hips low and steady."],"img":"opengym/1138.webp","gif":null,"ext":1},{"id":"11383","n":"wrist extensor stretch","bp":"lower arms","eq":"body weight","tg":"forearms","mg":"wrist extensors","sm":["wrist extensors"],"st":["Extend one arm in front of you with the elbow straight and palm facing down.","Bend the wrist so your fingers point toward the floor.","With your other hand, gently pull the back of the hand toward you.","Keep the stretch mild and your shoulder relaxed.","Hold for 20-30 seconds, then switch arms."],"img":"opengym/11383.webp","gif":null,"ext":1},{"id":"1139","n":"suspender split fly","bp":"shoulders","eq":"suspension trainer","tg":"delts","mg":"chest","sm":["chest","core"],"st":["Hold the handles and step into a split stance leaning forward.","Keep arms slightly bent and hands in front of you.","Open your arms out wide to the sides.","Squeeze at the end of the stretch without shrugging.","Bring the arms back together under control.","Switch the lead leg halfway through."],"img":"opengym/1139.webp","gif":null,"ext":1},{"id":"1140","n":"suspender sprinter","bp":"upper legs","eq":"suspension trainer","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","calves","core"],"st":["Hold the handles and lean slightly forward.","Stand on one leg with the other knee raised.","Drive one knee up as the opposite arm moves.","Switch legs with a quick hop.","Stay on the balls of your feet.","Keep your core tight and pace steady."],"img":"opengym/1140.webp","gif":null,"ext":1},{"id":"1141","n":"suspender squat arms overhead","bp":"upper legs","eq":"suspension trainer","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","shoulders","core"],"st":["Hold the handles overhead with arms straight.","Stand with feet shoulder width apart.","Sit back and down into a squat.","Keep your arms up and chest tall.","Drive through your heels to stand.","Do not let the lower back round."],"img":"opengym/1141.webp","gif":null,"ext":1},{"id":"1143","n":"suspender squat","bp":"upper legs","eq":"suspension trainer","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","core"],"st":["Hold the handles with arms extended.","Stand with feet shoulder width apart.","Sit your hips back and bend your knees.","Lower until your thighs are parallel to the floor.","Push through the heels to stand.","Keep your chest tall and knees tracking over toes."],"img":"opengym/1143.webp","gif":null,"ext":1},{"id":"11436","n":"cable standing neutral grip overhead triceps extension","bp":"upper arms","eq":"cable","tg":"triceps","mg":"shoulders","sm":["shoulders","core"],"st":["Attach a rope or neutral handle to a low pulley and face away from the stack.","Hold it overhead with elbows bent and pointing forward, one foot slightly ahead.","Keep your upper arms close to your ears and your ribs down.","Extend your elbows until your arms are straight overhead.","Lower slowly back to a deep stretch and repeat."],"img":"opengym/11436.webp","gif":null,"ext":1},{"id":"1144","n":"suspender standing ab rollout","bp":"waist","eq":"suspension trainer","tg":"abs","mg":"shoulders","sm":["shoulders","lats","core"],"st":["Hold the handles in front of you and lean forward.","Brace your abs and tuck the pelvis.","Extend your arms overhead as your body leans out.","Stop before your lower back arches.","Pull back to the start with your abs.","Take a smaller range if you need."],"img":"opengym/1144.webp","gif":null,"ext":1},{"id":"1145","n":"suspender star plank","bp":"waist","eq":"suspension trainer","tg":"abs","mg":"obliques","sm":["obliques","shoulders","glutes"],"st":["Put your feet in the straps and set a high plank.","Spread your legs wide.","Keep your hips level and body straight.","Brace the abs.","Hold for 20-30 seconds.","Breathe steadily and do not sag."],"img":"opengym/1145.webp","gif":null,"ext":1},{"id":"11450","n":"step up (1st and 2nd stairs steps)","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","calves"],"st":["Stand facing the stairs with your feet hip-width apart.","Place one foot on the first step and push through the heel to climb up.","Continue onto the second step, then step back down in control.","Keep your torso tall and your knee tracking over your toes.","Alternate the leading leg each rep or finish all reps on one side first."],"img":"opengym/11450.webp","gif":null,"ext":1},{"id":"11451","n":"standing wall slide half squat hold","bp":"upper legs","eq":"body weight","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","calves"],"st":["Stand with your back against a wall and feet about a step in front of you.","Slide down until your knees are bent to about 45-60 degrees.","Keep your back flat on the wall and your knees over your ankles.","Press through your whole foot and breathe steadily.","Hold for 20-45 seconds, then slide back up."],"img":"opengym/11451.webp","gif":null,"ext":1},{"id":"11452","n":"calves stretch v. 2","bp":"lower legs","eq":"body weight","tg":"calves","mg":"soleus","sm":["soleus","ankles"],"st":["Stand facing a wall and place your hands on it at chest height.","Step one foot back with the heel flat on the floor and the toes pointing forward.","Bend the front knee and lean in until you feel the back calf stretch.","Keep the back leg straight and the heel down.","Hold for 20-30 seconds, then switch legs."],"img":"opengym/11452.webp","gif":null,"ext":1},{"id":"1146","n":"suspender star push up","bp":"waist","eq":"suspension trainer","tg":"abs","mg":"chest","sm":["chest","triceps","shoulders","glutes"],"st":["Place your feet in the straps spread wide in a high plank.","Keep your core tight.","Lower your chest toward the floor.","Keep elbows at about 45 degrees.","Press back up.","Hold the wide leg position the whole set."],"img":"opengym/1146.webp","gif":null,"ext":1},{"id":"1147","n":"suspender supine crunch","bp":"waist","eq":"suspension trainer","tg":"abs","mg":"hip flexors","sm":["hip flexors","lower abs","core"],"st":["Lie on your back with your feet in the straps and legs up.","Place your arms flat on the floor.","Curl your hips up, pulling the knees toward your chest.","Squeeze your abs at the top.","Lower slowly to the start.","Do not swing the legs."],"img":"opengym/1147.webp","gif":null,"ext":1},{"id":"1148","n":"suspender supine plank","bp":"waist","eq":"suspension trainer","tg":"abs","mg":"glutes","sm":["glutes","lower back","hamstrings"],"st":["Lie on your back with heels in the straps.","Press through your heels and lift your hips.","Make a straight line from shoulders to heels.","Squeeze your glutes and keep abs tight.","Hold for 20-30 seconds.","Lower under control."],"img":"opengym/1148.webp","gif":null,"ext":1},{"id":"1149","n":"suspender triceps extension push up","bp":"upper arms","eq":"suspension trainer","tg":"triceps","mg":"shoulders","sm":["shoulders","chest","core"],"st":["Hold the handles and lean forward with arms straight.","Keep your body in a straight line.","Bend your elbows and lower your forehead between the hands.","Keep elbows pointing forward.","Press back up to straight arms.","Move your feet back for more challenge."],"img":"opengym/1149.webp","gif":null,"ext":1},{"id":"1150","n":"suspender triceps kickback","bp":"upper arms","eq":"suspension trainer","tg":"triceps","mg":"shoulders","sm":["shoulders","core","rear deltoids"],"st":["Hold the handles and hinge forward with elbows by your sides.","Keep your upper arms still.","Straighten your arms and push them behind you.","Squeeze the triceps at the end.","Bend the elbows slowly to return.","Keep your back flat."],"img":"opengym/1150.webp","gif":null,"ext":1},{"id":"1151","n":"suspender twist side","bp":"waist","eq":"suspension trainer","tg":"obliques","mg":"shoulders","sm":["shoulders","core"],"st":["Place your feet in the straps and set a high plank.","Brace your core.","Twist your hips to one side, bringing the knees across.","Return to the center with control.","Twist to the other side.","Keep your shoulders square."],"img":"opengym/1151.webp","gif":null,"ext":1},{"id":"1152","n":"suspender twist up","bp":"waist","eq":"suspension trainer","tg":"obliques","mg":"abdominals","sm":["abdominals","hip flexors","shoulders"],"st":["Put your feet in the straps and set a high plank.","Pull your knees up and rotate them toward one elbow.","Pause and squeeze the obliques.","Extend your legs back to plank.","Repeat to the other side.","Keep your hands firmly planted."],"img":"opengym/1152.webp","gif":null,"ext":1},{"id":"11529","n":"lever belt single leg romanian deadlift","bp":"upper legs","eq":"leverage machine","tg":"hamstrings","mg":"glutes","sm":["glutes","lower back","core"],"st":["Fasten the belt and stand on one leg on the platform with a slight knee bend.","Hinge at the hips and push them back as your torso lowers.","Let the free leg extend behind you for balance.","Lower until you feel a hamstring stretch, keeping your back flat.","Drive your hips forward to stand tall, then switch legs after your reps."],"img":"opengym/11529.webp","gif":null,"ext":1},{"id":"1153","n":"suspender upper back stretch","bp":"back","eq":"suspension trainer","tg":"upper back","mg":"lats","sm":["lats","rhomboids","trapezius"],"st":["Hold the handles and step back so your arms are straight.","Sit your hips back and lower your chest.","Round the upper back gently and push the straps away.","Feel the stretch between the shoulder blades.","Hold for 20-30 seconds.","Breathe slowly and return."],"img":"opengym/1153.webp","gif":null,"ext":1},{"id":"1154","n":"suspender calf raise","bp":"lower legs","eq":"suspension trainer","tg":"calves","mg":"soleus","sm":["soleus","ankles","feet"],"st":["Hold the handles and stand with feet hip width apart.","Keep your body upright.","Rise onto the balls of your feet as high as you can.","Pause and squeeze the calves.","Lower the heels slowly below the start if comfortable.","Use the straps only for balance."],"img":"opengym/1154.webp","gif":null,"ext":1},{"id":"1155","n":"suspender single leg deadlift","bp":"upper legs","eq":"suspension trainer","tg":"hamstrings","mg":"glutes","sm":["glutes","lower back","core"],"st":["Hold the handles and stand on one leg.","Soften the standing knee.","Hinge at the hip as the other leg extends behind you.","Keep your back flat and hips square.","Squeeze the glute to stand back up.","Finish your reps, then switch legs."],"img":"opengym/1155.webp","gif":null,"ext":1},{"id":"1156","n":"suspender pendulum","bp":"waist","eq":"suspension trainer","tg":"abs","mg":"obliques","sm":["obliques","hip flexors","shoulders"],"st":["Put your feet in the straps and set a high plank.","Brace your core.","Swing your legs together to one side.","Swing back through the center to the other side.","Keep the movement slow and controlled.","Keep your shoulders stable."],"img":"opengym/1156.webp","gif":null,"ext":1},{"id":"11567","n":"lever lying leg curl to reverse hyperextension","bp":"upper legs","eq":"leverage machine","tg":"hamstrings","mg":"glutes","sm":["glutes","lower back","calves"],"st":["Lie face down on the machine with the pads behind your lower legs.","Curl your heels toward your glutes, then lower with control.","Move into the reverse hyperextension position with the pad behind your legs.","Squeeze your glutes to raise your legs until they line up with your torso.","Lower slowly and avoid swinging."],"img":"opengym/11567.webp","gif":null,"ext":1},{"id":"11568","n":"smith unilateral bulgarian split squat from deficit","bp":"upper legs","eq":"smith machine","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","adductors"],"st":["Set the bar on your upper back and stand with the front foot on a low plate or step.","Place the rear foot on a bench behind you.","Lower straight down until the front thigh is about parallel or deeper.","Keep your torso upright and the front knee tracking over the toes.","Push through the front heel to stand, then switch legs."],"img":"opengym/11568.webp","gif":null,"ext":1},{"id":"11569","n":"resistance band standing side leg raise","bp":"upper legs","eq":"resistance band","tg":"abductors","mg":"glutes","sm":["glutes","core","hip flexors"],"st":["Loop the band around your ankles or above the knees and stand tall.","Hold onto something for balance if needed.","Lift one leg out to the side with a straight knee.","Pause at the top without leaning.","Lower slowly.","Finish your reps and switch legs."],"img":"opengym/11569.webp","gif":null,"ext":1},{"id":"1157","n":"suspender hip hinge","bp":"upper legs","eq":"suspension trainer","tg":"glutes","mg":"hamstrings","sm":["hamstrings","lower back","core"],"st":["Hold the handles with arms straight and feet hip width apart.","Soften your knees.","Push your hips back with a flat back.","Lean on the straps for balance.","Drive your hips forward to stand tall.","Squeeze the glutes at the top."],"img":"opengym/1157.webp","gif":null,"ext":1},{"id":"11570","n":"resistance band standing hip extension","bp":"upper legs","eq":"resistance band","tg":"glutes","mg":"hamstrings","sm":["hamstrings","core","lower back"],"st":["Loop the band around your ankles or secure it low, and stand tall.","Hold a support for balance.","Keep your core tight.","Kick one leg straight back without arching the back.","Squeeze the glute at the end.","Return slowly, then switch legs."],"img":"opengym/11570.webp","gif":null,"ext":1},{"id":"11571","n":"butt walking","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"hamstrings","sm":["hamstrings","core","hip flexors"],"st":["Sit on the floor with legs straight and arms crossed.","Lean back slightly.","Shift your weight to one side and swing the other hip forward.","Alternate sides to walk forward.","Keep your torso upright.","Walk back to reverse."],"img":"opengym/11571.webp","gif":null,"ext":1},{"id":"11572","n":"lying thoracic extensions on foam roller","bp":"back","eq":"roller","tg":"spine","mg":"upper back","sm":["upper back","rhomboids","core"],"st":["Lie on your back with the roller under your upper back.","Support your head with your hands.","Keep your hips on the floor and knees bent.","Gently lean back over the roller.","Return to neutral and shift the roller up or down.","Move slowly and breathe out as you extend."],"img":"opengym/11572.webp","gif":null,"ext":1},{"id":"1158","n":"suspender side stretch","bp":"upper legs","eq":"suspension trainer","tg":"adductors","mg":"groin","sm":["groin","inner thighs","hamstrings"],"st":["Hold the handles and step your legs wide.","Shift your weight to one side and bend that knee.","Keep the other leg straight.","Sit back into the stretch.","Hold for 20-30 seconds.","Switch sides."],"img":"opengym/1158.webp","gif":null,"ext":1},{"id":"1159","n":"suspender abduction lunge","bp":"upper legs","eq":"suspension trainer","tg":"abductors","mg":"glutes","sm":["glutes","quadriceps","adductors"],"st":["Hold the handles and stand tall.","Step out wide to one side.","Bend that knee and push the hips back.","Keep your chest up and the other leg straight.","Push off to return.","Alternate sides."],"img":"opengym/1159.webp","gif":null,"ext":1},{"id":"1161","n":"rowing (with rowing machine)","bp":"cardio","eq":"leverage machine","tg":"cardiovascular system","mg":"lats","sm":["lats","quadriceps","hamstrings","core"],"st":["Sit on the machine, strap in your feet and grab the handle with straight arms.","Push through your legs first, then lean back slightly.","Pull the handle to your lower ribs with elbows close.","Reverse the order: arms out, hips hinge, then knees bend to slide forward.","Keep a smooth rhythm for 10-30 minutes at a comfortable pace."],"img":"opengym/1161.webp","gif":null,"ext":1},{"id":"1162","n":"barbell standing military press","bp":"shoulders","eq":"barbell","tg":"delts","mg":"triceps","sm":["triceps","upper chest","core"],"st":["Unrack the bar at shoulder height, hands just outside your shoulders.","Stand tall with feet hip-width apart and squeeze your glutes.","Press the bar straight up, moving your head slightly back then through.","Lock out overhead with the bar over your mid-foot.","Lower the bar back to your collarbone with control."],"img":"opengym/1162.webp","gif":null,"ext":1},{"id":"1163","n":"lying leg raise","bp":"waist","eq":"body weight","tg":"abs","mg":"lower abs","sm":["lower abs","hip flexors"],"st":["Lie on your back with legs straight and hands under your hips.","Press your lower back gently into the floor.","Lift your legs together until they point at the ceiling.","Lower them slowly, stopping just above the floor.","Keep your back from arching throughout."],"img":"opengym/1163.webp","gif":null,"ext":1},{"id":"1164","n":"smith calf raise v. 2","bp":"lower legs","eq":"smith machine","tg":"calves","mg":"soleus","sm":["soleus","ankles"],"st":["Set the bar on your shoulders and stand with the balls of your feet on a step.","Keep your knees almost straight and your torso upright.","Lower your heels for a full stretch.","Rise onto your toes as high as you can.","Pause at the top, then lower under control."],"img":"opengym/1164.webp","gif":null,"ext":1},{"id":"11644","n":"resistance band side lying hip abduction","bp":"upper legs","eq":"resistance band","tg":"abductors","mg":"glutes","sm":["glutes","core"],"st":["Lie on your side with the band around your thighs or ankles.","Keep your legs straight and stacked.","Lift the top leg up without rolling backward.","Pause at the top.","Lower slowly.","Finish reps, then switch sides."],"img":"opengym/11644.webp","gif":null,"ext":1},{"id":"11645","n":"static quadriceps contraction (isometric)","bp":"upper legs","eq":"body weight","tg":"quads","mg":"quadriceps","sm":["quadriceps"],"st":["Sit or lie with one leg straight in front.","Relax your upper body.","Tighten the front of the thigh and press the knee down.","Hold for 5-10 seconds.","Relax fully.","Repeat, then switch legs."],"img":"opengym/11645.webp","gif":null,"ext":1},{"id":"11646","n":"static glutes contraction (isometric)","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"hamstrings","sm":["hamstrings","core"],"st":["Lie on your back or stand with your body relaxed.","Squeeze both glute muscles together.","Keep your legs and back still.","Hold the squeeze for 5-10 seconds.","Release fully.","Repeat for several reps."],"img":"opengym/11646.webp","gif":null,"ext":1},{"id":"11647","n":"single leg pogo jump","bp":"lower legs","eq":"body weight","tg":"calves","mg":"soleus","sm":["soleus","ankles","quadriceps","feet"],"st":["Stand on one leg with a soft knee and your arms relaxed at your sides.","Hop straight up by pushing through the ball of your foot, keeping the knee almost straight.","Land softly on the ball of the same foot and rebound right away.","Keep your hops small and quick, with your hips level and your core tight.","Hop for the planned time or reps, then switch legs."],"img":"opengym/11647.webp","gif":null,"ext":1},{"id":"11648","n":"floor w raise","bp":"back","eq":"body weight","tg":"upper back","mg":"rear deltoids","sm":["rear deltoids","rhomboids","trapezius"],"st":["Lie face down with arms bent and elbows out to the sides.","Rest your forehead lightly on the floor.","Squeeze your shoulder blades together and lift your arms and chest slightly.","Form a W shape with your arms and hold for a second.","Lower slowly and repeat."],"img":"opengym/11648.webp","gif":null,"ext":1},{"id":"11649","n":"bent knee calves stretch","bp":"lower legs","eq":"body weight","tg":"calves","mg":"soleus","sm":["soleus","ankles"],"st":["Stand facing a wall with hands on it and one foot back.","Bend both knees, keeping the back heel flat on the floor.","Lean forward until you feel a stretch low in the back calf.","Keep your hips square and chest up.","Hold for 20-30 seconds, then switch legs."],"img":"opengym/11649.webp","gif":null,"ext":1},{"id":"1165","n":"barbell standing military press (without rack)","bp":"shoulders","eq":"barbell","tg":"delts","mg":"triceps","sm":["triceps","upper chest","core"],"st":["Lift the barbell from the floor to your collarbone using a safe clean or deadlift and curl.","Set your feet hip-width apart with hands just outside your shoulders.","Brace your core and glutes.","Press the bar straight overhead to full lockout.","Lower to your collarbone under control and repeat."],"img":"opengym/1165.webp","gif":null,"ext":1},{"id":"11650","n":"seated single leg calf raise on a chair","bp":"lower legs","eq":"body weight","tg":"calves","mg":"soleus","sm":["soleus","ankles"],"st":["Sit on a chair with one foot flat on the floor, knee bent to 90 degrees.","Lift the other foot off the floor or tuck it behind.","Press through the ball of the working foot and raise your heel.","Pause at the top, then lower slowly.","Complete your reps, then switch legs."],"img":"opengym/11650.webp","gif":null,"ext":1},{"id":"11651","n":"seated patella mobilization","bp":"upper legs","eq":"body weight","tg":"quads","mg":"quadriceps","sm":["quadriceps","ankles"],"st":["Sit tall on a chair or bench with one leg extended and the thigh muscle relaxed.","Place your fingertips or the heel of your hand on the edges of your kneecap.","Gently glide the kneecap side to side and up and down in small, slow motions.","Keep the quad relaxed and stay in a comfortable range with no sharp pain.","Move for 30-60 seconds, then switch legs."],"img":"opengym/11651.webp","gif":null,"ext":1},{"id":"11652","n":"sciatic nerve glide floss","bp":"upper legs","eq":"body weight","tg":"hamstrings","mg":"calves","sm":["calves","lower back","glutes"],"st":["Sit tall at the edge of a chair with your hands on the seat or resting in your lap.","Slowly straighten one knee while you lower your chin toward your chest.","Bend the knee back down while you lift your head and look up.","Keep the motion smooth and gentle, never forcing into a strong stretch or tingling.","Repeat for 10-15 slow reps, then switch legs."],"img":"opengym/11652.webp","gif":null,"ext":1},{"id":"11653","n":"standing glute squeeze","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"hamstrings","sm":["hamstrings","core"],"st":["Stand tall with your feet hip width apart and your arms relaxed.","Tighten your abs lightly so your ribs stay stacked over your hips.","Squeeze your glutes together as hard as you comfortably can.","Hold for 3-5 seconds without leaning back or tucking your hips excessively.","Relax fully, then repeat for 10-15 reps."],"img":"opengym/11653.webp","gif":null,"ext":1},{"id":"11654","n":"seated knee down","bp":"upper legs","eq":"body weight","tg":"adductors","mg":"hip flexors","sm":["hip flexors","groin","glutes"],"st":["Sit tall on the floor or a bench with the soles of your feet together or one leg crossed in.","Let one knee drop slowly out to the side toward the floor.","Keep your back straight and your chest lifted as the knee lowers.","Pause briefly at the end of the comfortable range, then lift the knee back up.","Repeat for 8-12 reps per side."],"img":"opengym/11654.webp","gif":null,"ext":1},{"id":"11656","n":"hydrotherapy walking on spot","bp":"cardio","eq":"body weight","tg":"cardiovascular system","mg":"quadriceps","sm":["quadriceps","calves","hip flexors","core"],"st":["Stand in waist-to-chest-deep water with your feet hip width apart.","Lift one knee up in front of you, then lower it and lift the other.","Swing your arms naturally and keep your posture tall.","Walk at a relaxed, steady pace without leaning forward.","Continue for 2-5 minutes at an easy to moderate effort."],"img":"opengym/11656.webp","gif":null,"ext":1},{"id":"11657","n":"weighted plate overhead reverse lunge","bp":"upper legs","eq":"weight plate","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","shoulders","core"],"st":["Hold a weight plate overhead with straight arms.","Stand tall with feet hip-width apart.","Step one foot back and lower until both knees are about 90 degrees.","Keep your ribs down and the plate stable over your head.","Push through the front foot to return, then alternate legs."],"img":"opengym/11657.webp","gif":null,"ext":1},{"id":"1166","n":"jump split","bp":"upper legs","eq":"body weight","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","calves"],"st":["Start in a split stance with a slight lunge dip.","Drop down and jump up powerfully.","Switch leg positions in mid-air.","Land softly in a lunge with the other leg in front.","Keep your torso upright and repeat at a steady pace."],"img":"opengym/1166.webp","gif":null,"ext":1},{"id":"1168","n":"lying (prone) abdominal stretch","bp":"waist","eq":"body weight","tg":"abs","mg":"hip flexors","sm":["hip flexors","lower back"],"st":["Lie face down with your hands under your shoulders.","Press up slowly, straightening your arms as far as is comfortable.","Keep your hips on the floor and relax your glutes.","Look forward and feel the stretch along your belly.","Hold for 20-30 seconds, then lower down."],"img":"opengym/1168.webp","gif":null,"ext":1},{"id":"1169","n":"seated groin stretch","bp":"upper legs","eq":"body weight","tg":"adductors","mg":"groin","sm":["groin","inner thighs"],"st":["Sit tall on the floor and bring the soles of your feet together.","Hold your feet or ankles and let your knees fall out.","Keep your back straight and chest lifted.","Lean forward slightly from the hips until you feel a stretch.","Hold for 20-30 seconds and breathe slowly."],"img":"opengym/1169.webp","gif":null,"ext":1},{"id":"1170","n":"45 degree one leg hyperextension (arms in front of chest)","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"hamstrings","sm":["hamstrings","lower back","core"],"st":["Set the pad under your hips and hook one foot under the roller, with the other leg lifted off.","Cross your arms over your chest and keep your body in a straight line.","Lower your torso toward the floor with a flat back.","Raise back up by squeezing your glute until your body is level, without overarching.","Complete all reps, then switch legs."],"img":"opengym/1170.webp","gif":null,"ext":1},{"id":"1171","n":"45 degree twisting hyperextension","bp":"waist","eq":"body weight","tg":"spine","mg":"glutes","sm":["glutes","hamstrings","obliques"],"st":["Position yourself on the bench with your ankles under the pads and your hips just off the edge.","Cross your arms over your chest and lower your torso with a flat back.","Raise your torso back up, squeezing your glutes.","At the top, rotate your upper body gently to one side, then return to center.","Alternate sides each rep and keep the movement slow and controlled."],"img":"opengym/1171.webp","gif":null,"ext":1},{"id":"11714","n":"bodyweight rope pull up","bp":"back","eq":"rope","tg":"lats","mg":"biceps","sm":["biceps","forearms","grip muscles","upper back"],"st":["Hang from two ropes with arms straight and legs together.","Brace your core and pull your shoulder blades down.","Pull yourself up until your hands reach chest or chin level.","Keep your elbows pointing down and close.","Lower under control to a full hang."],"img":"opengym/11714.webp","gif":null,"ext":1},{"id":"11715","n":"bodyweight rope inverted row","bp":"back","eq":"rope","tg":"upper back","mg":"lats","sm":["lats","biceps","rhomboids","grip muscles"],"st":["Set ropes at about waist height and lie under them, holding the ends.","Keep your body straight from heels to head, heels on the floor.","Pull your chest toward your hands, squeezing your shoulder blades.","Keep your elbows close to your body.","Lower slowly until your arms are straight."],"img":"opengym/11715.webp","gif":null,"ext":1},{"id":"11716","n":"weighted stone standing power overhead press","bp":"shoulders","eq":"weighted","tg":"delts","mg":"triceps","sm":["triceps","upper back","core","glutes"],"st":["Lift the stone to your chest, hugging it close.","Stand with feet hip-width apart and brace your core.","Dip slightly and drive up through your legs.","Press the stone overhead to full lockout.","Lower it back to your chest with control."],"img":"opengym/11716.webp","gif":null,"ext":1},{"id":"11717","n":"plyo push up v. 2","bp":"chest","eq":"body weight","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders","core"],"st":["Start in a high plank with hands under your shoulders.","Lower your chest toward the floor with control.","Explode upward so your hands leave the ground.","Land softly with slightly bent elbows.","Reset your body line and repeat."],"img":"opengym/11717.webp","gif":null,"ext":1},{"id":"11718","n":"lever incline chest supported reverse delt fly (plate loaded)","bp":"shoulders","eq":"leverage machine","tg":"delts","mg":"rear deltoids","sm":["rear deltoids","rhomboids","upper back","trapezius"],"st":["Sit with your chest against the incline pad and grab the handles.","Start with arms forward and slightly bent.","Sweep your arms out and back in a wide arc.","Squeeze your shoulder blades at the end.","Return slowly without letting the weight crash."],"img":"opengym/11718.webp","gif":null,"ext":1},{"id":"1172","n":"assisted weighted push up","bp":"chest","eq":"weighted","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders","core"],"st":["Get into a plank with hands under your shoulders and load placed on your upper back.","Brace your core and keep your body in a straight line.","Lower your chest toward the floor.","Press back up until your elbows are straight.","Use the assistance as needed to keep every rep clean."],"img":"opengym/1172.webp","gif":null,"ext":1},{"id":"1173","n":"barbell incline wide reverse grip bench press","bp":"chest","eq":"barbell","tg":"pectorals","mg":"upper chest","sm":["upper chest","shoulders","triceps"],"st":["Lie on an incline bench and grip the bar wide with palms facing you.","Unrack and hold the bar over your upper chest.","Lower it to the upper chest with elbows slightly tucked.","Press back up to lockout.","Use a spotter, as this grip is less stable."],"img":"opengym/1173.webp","gif":null,"ext":1},{"id":"1174","n":"diamond push up (on knees)","bp":"upper arms","eq":"body weight","tg":"triceps","mg":"chest","sm":["chest","shoulders","core"],"st":["Kneel on the floor and place your hands under your chest, thumbs and fingers forming a diamond.","Keep your body straight from knees to head.","Lower your chest toward your hands, elbows close.","Press up until your arms are straight.","Keep your core tight throughout."],"img":"opengym/1174.webp","gif":null,"ext":1},{"id":"1175","n":"dumbbell forward leaning lunge","bp":"upper legs","eq":"dumbbell","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","core"],"st":["Hold a dumbbell in each hand and stand tall with your feet hip width apart.","Step forward with one foot and lean your chest slightly forward with a flat back.","Lower until both knees are bent about 90 degrees.","Push through the front heel to return to standing.","Alternate legs or finish all reps on one side before switching."],"img":"opengym/1175.webp","gif":null,"ext":1},{"id":"1176","n":"dumbbell incline front raise","bp":"shoulders","eq":"dumbbell","tg":"delts","mg":"upper chest","sm":["upper chest","trapezius"],"st":["Lie face down or back on an incline bench holding dumbbells.","Start with your arms hanging or in front of you.","Raise the weights forward to shoulder height with straight arms.","Pause briefly at the top.","Lower slowly under control."],"img":"opengym/1176.webp","gif":null,"ext":1},{"id":"11762","n":"smith bent over row (chest supported)","bp":"back","eq":"smith machine","tg":"upper back","mg":"lats","sm":["lats","biceps","rhomboids","rear deltoids"],"st":["Set an incline bench under the bar and lie chest down on it.","Grip the bar just wider than shoulder width.","Pull the bar toward your lower ribs.","Squeeze your shoulder blades together at the top.","Lower slowly until your arms are straight."],"img":"opengym/11762.webp","gif":null,"ext":1},{"id":"11763","n":"cable seated incline curl","bp":"upper arms","eq":"cable","tg":"biceps","mg":"brachialis","sm":["brachialis","forearms"],"st":["Set a bench to incline and place a low pulley behind you.","Sit back with your arms hanging and grab the handles.","Curl the handles toward your shoulders, keeping elbows back.","Squeeze the biceps at the top.","Lower slowly to a full stretch."],"img":"opengym/11763.webp","gif":null,"ext":1},{"id":"11764","n":"cable standing single arm supinated grip chest press","bp":"chest","eq":"cable","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders","biceps","core"],"st":["Set a cable at chest height and hold the handle with a palm-up grip.","Stand facing away in a staggered stance.","Press the handle forward until your arm is straight.","Keep your torso still and resist twisting.","Return slowly and switch arms after your reps."],"img":"opengym/11764.webp","gif":null,"ext":1},{"id":"1177","n":"dumbbell lying hammer press v. 2","bp":"chest","eq":"dumbbell","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders"],"st":["Lie on a bench holding dumbbells with palms facing each other.","Start with the weights above your chest.","Lower them to the sides of your chest, elbows slightly tucked.","Press back up until your arms are straight.","Keep your feet planted and shoulder blades pinched."],"img":"opengym/1177.webp","gif":null,"ext":1},{"id":"1178","n":"dumbbell standing single leg calf raise","bp":"lower legs","eq":"dumbbell","tg":"calves","mg":"soleus","sm":["soleus","ankles"],"st":["Hold a dumbbell in one hand and stand on one foot on a step.","Hold a wall or rail with your other hand for balance.","Lower your heel to a full stretch.","Press up onto your toes as high as possible.","Complete your reps, then switch legs."],"img":"opengym/1178.webp","gif":null,"ext":1},{"id":"11781","n":"jump step box","bp":"upper legs","eq":"body weight","tg":"quads","mg":"glutes","sm":["glutes","calves","hamstrings"],"st":["Stand facing a step box with your feet hip width apart.","Dip into a quarter squat and swing your arms back.","Jump explosively up onto the box, landing softly with bent knees.","Stand tall on top, then step back down one foot at a time.","Reset and repeat, staying quick but controlled."],"img":"opengym/11781.webp","gif":null,"ext":1},{"id":"11782","n":"lateral jump","bp":"upper legs","eq":"body weight","tg":"abductors","mg":"glutes","sm":["glutes","quadriceps","calves","adductors"],"st":["Stand on both feet with your knees slightly bent and your arms ready.","Push off and jump sideways, covering a comfortable distance.","Land softly on both feet with your knees tracking over your toes.","Immediately jump back to the starting side.","Keep your chest up and repeat for the planned reps or time."],"img":"opengym/11782.webp","gif":null,"ext":1},{"id":"11783","n":"explosive fingers","bp":"lower arms","eq":"body weight","tg":"forearms","mg":"hands","sm":["hands","wrist extensors","grip muscles"],"st":["Hold your hands out in front of you.","Close both hands into tight fists.","Open them fast, spreading your fingers as wide as possible.","Repeat quickly for 20-30 reps.","Keep your wrists relaxed."],"img":"opengym/11783.webp","gif":null,"ext":1},{"id":"11784","n":"explosive hang squat","bp":"upper legs","eq":"body weight","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","calves"],"st":["Hang from a bar with arms straight and knees slightly bent.","Lower into a deep squat position.","Explode upward through your legs.","Absorb the movement softly and return to the start.","Keep your core tight and repeat."],"img":"opengym/11784.webp","gif":null,"ext":1},{"id":"11785","n":"internal rotation shoulders mobilization","bp":"shoulders","eq":"body weight","tg":"delts","mg":"rotator cuff","sm":["rotator cuff"],"st":["Stand or sit tall with one elbow bent to 90 degrees at your side.","Rotate your forearm across your belly.","Move slowly through a comfortable range.","Return to the start and repeat 8-12 times.","Switch arms."],"img":"opengym/11785.webp","gif":null,"ext":1},{"id":"11786","n":"seated radial nerve mobilization","bp":"upper arms","eq":"body weight","tg":"triceps","mg":"forearms","sm":["forearms","wrist flexors","shoulders"],"st":["Sit tall with one arm down at your side, palm facing back.","Lower your shoulder slightly and rotate your arm inward.","Bend your wrist gently and tilt your head away.","Move slowly and stop at a mild pull, never pain.","Repeat 8-10 times, then switch arms."],"img":"opengym/11786.webp","gif":null,"ext":1},{"id":"11787","n":"seated median nerve mobilization","bp":"lower arms","eq":"body weight","tg":"forearms","mg":"wrist flexors","sm":["wrist flexors","biceps","shoulders"],"st":["Sit tall and lift one arm out to the side, palm up.","Extend your wrist and fingers backward.","Tilt your head slightly away from that arm.","Return slowly and repeat 8-10 times.","Stay within a mild stretch, then switch arms."],"img":"opengym/11787.webp","gif":null,"ext":1},{"id":"11788","n":"seated ulnar nerve mobilization","bp":"lower arms","eq":"body weight","tg":"forearms","mg":"wrist flexors","sm":["wrist flexors","shoulders"],"st":["Sit tall with one arm out to the side.","Bend your elbow and bring your hand toward your face like a mask.","Tilt your head slightly away.","Straighten the arm back out, keeping it gentle.","Repeat 8-10 times, then switch arms."],"img":"opengym/11788.webp","gif":null,"ext":1},{"id":"11789","n":"barbell staggered stance stiff legged deadlift","bp":"upper legs","eq":"barbell","tg":"hamstrings","mg":"glutes","sm":["glutes","lower back","core","grip muscles"],"st":["Hold a barbell in front of your thighs and place one foot slightly behind the other, mostly on the ball of the back foot.","Keep most of your weight on the front leg with a soft knee.","Hinge at the hips, sliding the bar down your legs with a flat back.","Lower until you feel a strong hamstring stretch, then drive your hips forward to stand.","Finish all reps, then switch the stance."],"img":"opengym/11789.webp","gif":null,"ext":1},{"id":"1179","n":"flutter kicks v. 2","bp":"waist","eq":"body weight","tg":"abs","mg":"lower abs","sm":["lower abs","hip flexors"],"st":["Lie on your back with hands under your hips.","Lift both legs a few inches off the floor.","Kick your legs up and down in small, quick alternating moves.","Press your lower back into the floor.","Continue for 20-40 seconds."],"img":"opengym/1179.webp","gif":null,"ext":1},{"id":"11790","n":"balance 3 point toe tap","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"quadriceps","sm":["quadriceps","core","ankles"],"st":["Stand on one leg with a slight knee bend and your hands on your hips.","Tap the free foot out in front of you, then lightly out to the side.","Tap it behind you, keeping your torso upright.","Return to center and repeat the sequence under control.","Complete all reps, then switch legs."],"img":"opengym/11790.webp","gif":null,"ext":1},{"id":"11791","n":"single arm fingers press with ball","bp":"lower arms","eq":"body weight","tg":"forearms","mg":"hands","sm":["hands","grip muscles"],"st":["Hold a small ball in one palm.","Press down on it with your fingers.","Spread and squeeze with control, keeping your wrist neutral.","Hold the press for 2-3 seconds.","Repeat for reps, then switch hands."],"img":"opengym/11791.webp","gif":null,"ext":1},{"id":"11792","n":"kneeling isometric biceps hold","bp":"upper arms","eq":"body weight","tg":"biceps","mg":"brachialis","sm":["brachialis","forearms"],"st":["Kneel upright with your elbows bent at about 90 degrees.","Hold your hands in front of you with palms up.","Keep your elbows pinned to your sides.","Squeeze your biceps and hold the position.","Hold for 20-30 seconds, then rest."],"img":"opengym/11792.webp","gif":null,"ext":1},{"id":"11793","n":"external press shoulders mobilization","bp":"shoulders","eq":"body weight","tg":"delts","mg":"rotator cuff","sm":["rotator cuff"],"st":["Stand tall with your elbow bent at your side.","Press your forearm outward away from your body.","Hold for a moment at the end of your comfortable range.","Return slowly and repeat 8-12 times.","Switch arms."],"img":"opengym/11793.webp","gif":null,"ext":1},{"id":"11794","n":"single arm fingers press with ball v. 2","bp":"lower arms","eq":"body weight","tg":"forearms","mg":"hands","sm":["hands","grip muscles"],"st":["Place a ball under one hand on a table or hold it in your palm.","Spread your fingers over the ball.","Press down and hold for 2-3 seconds.","Release with control.","Repeat for reps, then switch hands."],"img":"opengym/11794.webp","gif":null,"ext":1},{"id":"11795","n":"backward press shoulders mobilization","bp":"shoulders","eq":"body weight","tg":"delts","mg":"rotator cuff","sm":["rotator cuff","rear deltoids"],"st":["Stand tall with your arms at your sides.","Press one arm backward, keeping the elbow straight.","Move through a comfortable range.","Return slowly and repeat 8-12 times.","Switch arms."],"img":"opengym/11795.webp","gif":null,"ext":1},{"id":"11796","n":"external rotation shoulders mobilization","bp":"shoulders","eq":"body weight","tg":"delts","mg":"rotator cuff","sm":["rotator cuff"],"st":["Stand tall with your elbow bent to 90 degrees at your side.","Rotate your forearm outward away from your belly.","Keep your elbow tucked in.","Return slowly and repeat 8-12 times.","Switch arms."],"img":"opengym/11796.webp","gif":null,"ext":1},{"id":"11797","n":"forward press shoulders mobilization","bp":"shoulders","eq":"body weight","tg":"delts","mg":"chest","sm":["chest","rotator cuff"],"st":["Stand tall with your elbows bent in front of you.","Press your arm forward until it is straight.","Keep your shoulder relaxed.","Return slowly and repeat 8-12 times.","Switch arms."],"img":"opengym/11797.webp","gif":null,"ext":1},{"id":"11798","n":"bent over back to side to front arms raise","bp":"shoulders","eq":"body weight","tg":"delts","mg":"rear deltoids","sm":["rear deltoids","upper back","rhomboids","core"],"st":["Hinge forward at the hips with a flat back and let your arms hang down.","Sweep both arms back behind your hips.","Swing them out wide to the sides up to shoulder height.","Continue the arc forward until your arms point ahead of you, then reverse the path.","Keep your neck neutral and move smoothly for the planned reps."],"img":"opengym/11798.webp","gif":null,"ext":1},{"id":"11799","n":"dumbbell bent over back to side to front arms raise","bp":"shoulders","eq":"dumbbell","tg":"delts","mg":"rear deltoids","sm":["rear deltoids","upper back","rhomboids","core"],"st":["Hold light dumbbells and hinge forward at the hips with a flat back.","Start with your arms back by your hips.","Sweep the dumbbells out to the sides up to shoulder height.","Continue forward in an arc, then reverse the path with control.","Use light weights and avoid swinging your torso."],"img":"opengym/11799.webp","gif":null,"ext":1},{"id":"1180","n":"lying simultaneous alternating straight leg raise","bp":"waist","eq":"body weight","tg":"abs","mg":"lower abs","sm":["lower abs","hip flexors","quadriceps"],"st":["Lie on your back with your legs straight and your hands under your hips or at your sides.","Press your lower back into the floor and brace your abs.","Raise one leg while the other lowers toward the floor, keeping both straight.","Switch legs in a smooth scissor pattern without letting your back arch.","Continue for the planned reps or time."],"img":"opengym/1180.webp","gif":null,"ext":1},{"id":"11800","n":"dumbbell lying single straight arm press on floor","bp":"chest","eq":"dumbbell","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders","upper chest","core"],"st":["Lie on your back on the floor with knees bent and one dumbbell held above your chest.","Keep the other arm resting on the floor beside you.","Press the dumbbell up until your arm is straight and the shoulder reaches forward.","Lower it back with control until your upper arm touches the floor.","Complete the reps, then switch arms."],"img":"opengym/11800.webp","gif":null,"ext":1},{"id":"11801","n":"lying single leg quadriceps mobilization","bp":"upper legs","eq":"body weight","tg":"quads","mg":"hip flexors","sm":["hip flexors","ankles"],"st":["Lie on your side or stomach with your legs extended.","Bend one knee and bring your heel toward your glute, holding the ankle if needed.","Move the knee in and out of the bend in a slow, controlled rhythm.","Keep your hips level and stay within a comfortable range.","Repeat for 10-15 reps, then switch legs."],"img":"opengym/11801.webp","gif":null,"ext":1},{"id":"1181","n":"lying straight leg raise v. 2","bp":"waist","eq":"body weight","tg":"abs","mg":"lower abs","sm":["lower abs","hip flexors","quadriceps"],"st":["Lie on your back with your legs straight and your hands under your hips.","Press your lower back into the floor.","Raise both legs together until they point to the ceiling.","Lower them slowly, stopping just above the floor.","Keep your core braced and your back from arching."],"img":"opengym/1181.webp","gif":null,"ext":1},{"id":"1183","n":"smith kneeling rear kick","bp":"upper legs","eq":"smith machine","tg":"glutes","mg":"hamstrings","sm":["hamstrings","core","lower back"],"st":["Set the bar at a low height and kneel on all fours facing it, with the sole of one foot under the bar.","Brace your abs and keep your back flat.","Press your foot up and back against the bar until your hip is fully extended.","Squeeze your glute at the top, then lower under control.","Finish your reps, then switch legs."],"img":"opengym/1183.webp","gif":null,"ext":1},{"id":"1184","n":"weighted inverted row","bp":"back","eq":"weighted","tg":"upper back","mg":"lats","sm":["lats","biceps","rhomboids","rear deltoids"],"st":["Set a bar at waist height and lie under it with extra weight on your torso.","Grip the bar just wider than shoulders.","Keep your body straight from heels to head.","Pull your chest to the bar.","Lower under control."],"img":"opengym/1184.webp","gif":null,"ext":1},{"id":"1186","n":"alternate straight leg raise (on bosu ball)","bp":"waist","eq":"bosu ball","tg":"abs","mg":"lower abs","sm":["lower abs","hip flexors","core"],"st":["Lie back on a bosu ball with your lower back supported and your hands holding it lightly.","Brace your abs and extend both legs.","Raise one leg while keeping it straight.","Lower it and switch to the other leg.","Keep your torso steady and move with control."],"img":"opengym/1186.webp","gif":null,"ext":1},{"id":"11864","n":"dumbbell single arm curl with isometric hold","bp":"upper arms","eq":"dumbbell","tg":"biceps","mg":"brachialis","sm":["brachialis","forearms"],"st":["Stand holding a dumbbell at your side, palm forward.","Curl the weight up until your elbow is bent to 90 degrees.","Hold that position for 2-3 seconds.","Finish the curl, then lower slowly.","Complete your reps and switch arms."],"img":"opengym/11864.webp","gif":null,"ext":1},{"id":"1187","n":"kettlebell sit up","bp":"waist","eq":"kettlebell","tg":"abs","mg":"hip flexors","sm":["hip flexors","shoulders"],"st":["Lie on your back with knees bent and hold a kettlebell at your chest.","Brace your core.","Curl up until your torso is upright.","Keep the kettlebell close to you.","Lower slowly back down."],"img":"opengym/1187.webp","gif":null,"ext":1},{"id":"11877","n":"hanging l sit","bp":"waist","eq":"body weight","tg":"abs","mg":"hip flexors","sm":["hip flexors","lower abs","forearms"],"st":["Hang from a bar with straight arms.","Lift your legs straight in front until they are parallel to the floor.","Keep your toes pointed and your knees locked.","Avoid swinging.","Hold for 10-20 seconds, then lower."],"img":"opengym/11877.webp","gif":null,"ext":1},{"id":"11878","n":"stall bar leg raise","bp":"waist","eq":"body weight","tg":"abs","mg":"lower abs","sm":["lower abs","hip flexors","forearms"],"st":["Hang on a stall bar with arms straight.","Brace your core and keep your body still.","Raise your legs up in front of you.","Lift as high as you can without swinging.","Lower slowly and repeat."],"img":"opengym/11878.webp","gif":null,"ext":1},{"id":"11879","n":"smith step up","bp":"upper legs","eq":"smith machine","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","calves"],"st":["Set the bar across your upper back and stand in front of a bench.","Place one foot on the bench.","Drive through that heel to stand up fully.","Step back down under control.","Complete your reps, then switch legs."],"img":"opengym/11879.webp","gif":null,"ext":1},{"id":"1188","n":"weighted twisting crunch (on bench)","bp":"waist","eq":"weighted","tg":"obliques","mg":"hip flexors","sm":["hip flexors","core"],"st":["Lie back on a bench with your knees bent and a weight held on your chest.","Brace your abs and curl your upper body up.","Rotate your torso so one elbow moves toward the opposite knee.","Lower back down slowly without letting go of tension.","Alternate sides each rep."],"img":"opengym/1188.webp","gif":null,"ext":1},{"id":"11880","n":"lever t bar close grip row (plate loaded)","bp":"back","eq":"leverage machine","tg":"upper back","mg":"lats","sm":["lats","biceps","rhomboids","rear deltoids"],"st":["Stand on the platform with your chest supported.","Grab the close-grip handle with straight arms.","Pull the handle toward your torso, elbows close.","Squeeze your shoulder blades together.","Lower slowly to full extension."],"img":"opengym/11880.webp","gif":null,"ext":1},{"id":"1189","n":"weighted v crunch (on bosu ball)","bp":"waist","eq":"bosu ball","tg":"abs","mg":"lower abs","sm":["lower abs","hip flexors","core"],"st":["Sit on a bosu ball and lean back slightly, holding a weight in front of you.","Lift your feet off the floor with your legs bent or straight.","Bring your chest and knees toward each other in a V shape.","Lower back with control, keeping your spine long.","Stay stable on the ball throughout."],"img":"opengym/1189.webp","gif":null,"ext":1},{"id":"1190","n":"incline twisting sit up v. 2","bp":"waist","eq":"body weight","tg":"obliques","mg":"abdominals","sm":["abdominals","hip flexors"],"st":["Lie on an incline bench with your feet secured.","Place your hands lightly behind your head.","Curl up while rotating your torso to one side.","Lower slowly.","Alternate sides each rep."],"img":"opengym/1190.webp","gif":null,"ext":1},{"id":"11903","n":"standing hip flexors stretch","bp":"upper legs","eq":"body weight","tg":"hip flexors","mg":"quadriceps","sm":["quadriceps","glutes","core"],"st":["Stand tall and hold a wall or support for balance.","Bend one knee and bring your heel toward your glute, holding the ankle.","Tuck your pelvis slightly and push your hips gently forward.","Keep your knees close together and your chest upright.","Hold for 20-30 seconds, then switch legs."],"img":"opengym/11903.webp","gif":null,"ext":1},{"id":"11904","n":"standing half kneeling hip flexors stretch","bp":"upper legs","eq":"body weight","tg":"hip flexors","mg":"quadriceps","sm":["quadriceps","glutes","core"],"st":["Kneel on one knee with the other foot forward and a pad under your knee.","Keep your torso upright and tuck your pelvis under.","Shift your weight forward until you feel a stretch at the front of the back hip.","Keep your front knee over your ankle and your core engaged.","Hold for 20-30 seconds, then switch sides."],"img":"opengym/11904.webp","gif":null,"ext":1},{"id":"1191","n":"triceps press (head below bench)","bp":"upper arms","eq":"dumbbell","tg":"triceps","mg":"shoulders","sm":["shoulders","forearms"],"st":["Lie on a bench with your head just past the end, holding a weight overhead.","Keep your upper arms still and pointing up.","Bend your elbows to lower the weight toward your head.","Extend your arms to straight.","Keep your elbows tucked in."],"img":"opengym/1191.webp","gif":null,"ext":1},{"id":"1193","n":"iron cross plank","bp":"waist","eq":"body weight","tg":"abs","mg":"core","sm":["core","shoulders","glutes"],"st":["Start in a plank position with hands under your shoulders.","Spread your arms and legs wide in an X shape.","Brace your core and keep your hips level.","Breathe steadily.","Hold for 20-40 seconds."],"img":"opengym/1193.webp","gif":null,"ext":1},{"id":"1194","n":"lever lying t bar row","bp":"back","eq":"leverage machine","tg":"upper back","mg":"lats","sm":["lats","biceps","rhomboids","rear deltoids"],"st":["Lie chest-down on the pad and grab the handles.","Start with your arms straight.","Pull the handles toward your torso.","Squeeze your shoulder blades.","Lower under control."],"img":"opengym/1194.webp","gif":null,"ext":1},{"id":"1195","n":"lever incline hammer chest press","bp":"chest","eq":"leverage machine","tg":"pectorals","mg":"upper chest","sm":["upper chest","triceps","shoulders"],"st":["Adjust the seat so the handles sit at upper chest height.","Sit back with your shoulder blades pinned to the pad and grip the neutral handles.","Press the handles up and forward until your arms are almost straight.","Lower slowly until you feel a stretch across the chest.","Keep your wrists straight and your back against the pad."],"img":"opengym/1195.webp","gif":null,"ext":1},{"id":"11954","n":"lying pretzel stretch","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"hip flexors","sm":["hip flexors","lower back","quadriceps"],"st":["Lie on your side with your hips stacked and your bottom leg bent in front.","Bend the top knee and bring that foot back toward your glutes, holding it with your hand.","Gently roll your top knee back and open your chest toward the floor.","Hold for 20-30 seconds while breathing slowly.","Switch sides and repeat."],"img":"opengym/11954.webp","gif":null,"ext":1},{"id":"1196","n":"dumbbell alternate biceps curl v. 2","bp":"upper arms","eq":"dumbbell","tg":"biceps","mg":"brachialis","sm":["brachialis","forearms"],"st":["Stand tall with a dumbbell in each hand, palms facing forward.","Keeping your elbow by your side, curl one dumbbell up toward your shoulder.","Squeeze at the top, then lower it under control.","Repeat with the other arm and keep alternating.","Avoid swinging your torso to lift the weight."],"img":"opengym/1196.webp","gif":null,"ext":1},{"id":"1198","n":"jumping pull up","bp":"back","eq":"body weight","tg":"lats","mg":"biceps","sm":["biceps","upper back","quadriceps"],"st":["Stand under a pull-up bar and grip it slightly wider than your shoulders.","Bend your knees and jump up, pulling your chin above the bar.","Pause for a moment at the top.","Lower yourself slowly until your arms are straight.","Reset on the floor and repeat."],"img":"opengym/1198.webp","gif":null,"ext":1},{"id":"1199","n":"sumo deadlift high pull","bp":"upper legs","eq":"barbell","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","trapezius","shoulders","upper back"],"st":["Stand with a wide stance and grip the barbell between your legs with hands close together.","Keep your back flat and drive through your legs to stand up.","As the bar passes your hips, pull it up to chest height with your elbows high.","Lower the bar back along the same path.","Keep the bar close to your body throughout."],"img":"opengym/1199.webp","gif":null,"ext":1},{"id":"1200","n":"push press","bp":"shoulders","eq":"barbell","tg":"delts","mg":"triceps","sm":["triceps","upper chest","quadriceps","core"],"st":["Hold the barbell at your upper chest with your elbows slightly in front of the bar.","Dip a few inches by bending your knees, keeping your torso upright.","Drive up through your legs and press the bar overhead.","Lock out with the bar over your mid foot, then lower it back to your chest.","Brace your core and avoid leaning back."],"img":"opengym/1200.webp","gif":null,"ext":1},{"id":"12018","n":"kettlebell standing slingshots (advanced)","bp":"waist","eq":"kettlebell","tg":"abs","mg":"obliques","sm":["obliques","shoulders","forearms","core"],"st":["Stand with your feet hip width apart holding a kettlebell by the handle.","Pass it around your waist from one hand to the other behind your back.","Continue the circle to the front, keeping the movement smooth.","Keep your core tight and your hips still.","After several reps, reverse the direction."],"img":"opengym/12018.webp","gif":null,"ext":1},{"id":"1202","n":"cable horizontal pallof press","bp":"waist","eq":"cable","tg":"abs","mg":"obliques","sm":["obliques","core","shoulders"],"st":["Set a cable at chest height and stand sideways to the stack.","Hold the handle at your chest with both hands and brace your core.","Press the handle straight out until your arms are extended.","Hold for a second without letting your torso twist.","Bring it back to your chest and finish the set, then switch sides."],"img":"opengym/1202.webp","gif":null,"ext":1},{"id":"1203","n":"cable one arm inner biceps curl","bp":"upper arms","eq":"cable","tg":"biceps","mg":"brachialis","sm":["brachialis","forearms"],"st":["Attach a handle to a low cable and stand facing the stack.","Hold the handle with one hand, palm up, and turn your elbow slightly out.","Curl the handle toward your shoulder.","Squeeze at the top, then lower under control.","Finish your reps, then switch arms."],"img":"opengym/1203.webp","gif":null,"ext":1},{"id":"1204","n":"cable one arm lat pulldown","bp":"back","eq":"cable","tg":"lats","mg":"biceps","sm":["biceps","upper back","rhomboids"],"st":["Attach a handle to a high pulley and sit facing the stack.","Grab the handle with one hand and sit tall.","Pull the handle down to the side of your chest, driving your elbow toward your hip.","Pause, then let your arm rise slowly.","Complete your reps and switch sides."],"img":"opengym/1204.webp","gif":null,"ext":1},{"id":"1205","n":"cable one arm twisting seated row","bp":"back","eq":"cable","tg":"upper back","mg":"lats","sm":["lats","biceps","rhomboids","obliques"],"st":["Sit at a low cable with your feet braced and grab the handle with one hand.","Start with your torso turned slightly toward the cable.","Row the handle to your side while rotating your torso open.","Squeeze your shoulder blade back, then return slowly.","Do all reps, then change arms."],"img":"opengym/1205.webp","gif":null,"ext":1},{"id":"1206","n":"cable pull through","bp":"upper legs","eq":"cable","tg":"glutes","mg":"hamstrings","sm":["hamstrings","lower back","core"],"st":["Attach a rope to a low pulley and face away from the stack, holding the rope between your legs.","Step forward until the cable is taut and bend your knees slightly.","Push your hips back, letting the rope travel behind you.","Drive your hips forward and squeeze your glutes to stand tall.","Keep your back flat throughout."],"img":"opengym/1206.webp","gif":null,"ext":1},{"id":"1207","n":"cable twist (down up)","bp":"waist","eq":"cable","tg":"obliques","mg":"shoulders","sm":["shoulders","core"],"st":["Set the cable pulley low and stand sideways to the machine, holding the handle with both hands.","Start with the handle near your lower hip, arms mostly straight.","Rotate your torso and pull the handle diagonally up across your body.","Pivot your back foot and keep your hips stable.","Return slowly, finish your reps, then switch sides."],"img":"opengym/1207.webp","gif":null,"ext":1},{"id":"1208","n":"cable twist (up down) v. 2","bp":"waist","eq":"cable","tg":"obliques","mg":"shoulders","sm":["shoulders","core"],"st":["Set the cable pulley high and stand sideways to the machine, holding the handle with both hands.","Start with the handle above your shoulder, arms mostly straight.","Rotate your torso and pull the handle diagonally down across your body.","Keep your hips steady and your core braced.","Return slowly, finish your reps, then switch sides."],"img":"opengym/1208.webp","gif":null,"ext":1},{"id":"1209","n":"cable twisting overhead press","bp":"shoulders","eq":"cable","tg":"delts","mg":"triceps","sm":["triceps","obliques","core"],"st":["Set a cable low and stand sideways, holding the handle at your shoulder.","Brace your core and turn slightly toward the cable.","Press the handle overhead while rotating your torso to face forward.","Lower the handle back to your shoulder with control.","Finish your reps, then switch sides."],"img":"opengym/1209.webp","gif":null,"ext":1},{"id":"1210","n":"cable twisting standing high row","bp":"back","eq":"cable","tg":"lats","mg":"upper back","sm":["upper back","rear deltoids","biceps","obliques"],"st":["Set a cable at about head height and stand facing it with the handle in one hand.","Take a split stance and lean back slightly.","Pull the handle toward your upper chest, turning your torso as you go.","Squeeze your shoulder blade, then return slowly.","Complete the set and switch sides."],"img":"opengym/1210.webp","gif":null,"ext":1},{"id":"1211","n":"cable twisting standing one arm chest press","bp":"chest","eq":"cable","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders","obliques","core"],"st":["Set the cable at chest height and stand sideways with the handle in your inside hand.","Take a stable stance and hold the handle at your chest.","Press the handle forward while rotating your torso toward the press.","Return to the start with control.","Complete your reps, then switch sides."],"img":"opengym/1211.webp","gif":null,"ext":1},{"id":"1212","n":"cable twisting standing row","bp":"back","eq":"cable","tg":"upper back","mg":"lats","sm":["lats","biceps","rhomboids","obliques"],"st":["Set a cable at mid height and stand facing it, holding the handle with one hand.","Stand in a stable stance with a slight lean back.","Pull the handle to your ribs and rotate your torso open.","Squeeze your shoulder blade at the end.","Return slowly, finish your reps, then switch sides."],"img":"opengym/1212.webp","gif":null,"ext":1},{"id":"1213","n":"cable vertical pallof press","bp":"waist","eq":"cable","tg":"abs","mg":"obliques","sm":["obliques","core","shoulders"],"st":["Set a cable at a high or low position and stand sideways to it.","Hold the handle at your chest with both hands.","Press the handle straight up (or down) along a vertical line.","Hold for a second without letting your torso twist.","Return to your chest, finish the set, then switch sides."],"img":"opengym/1213.webp","gif":null,"ext":1},{"id":"1214","n":"dumbbell incline reverse grip 30 degrees bench press","bp":"chest","eq":"dumbbell","tg":"pectorals","mg":"upper chest","sm":["upper chest","triceps","shoulders","biceps"],"st":["Set a bench to about 30 degrees and lie back with dumbbells held palms facing you.","Start with the dumbbells at your chest.","Press them up until your arms are almost straight.","Lower slowly back to your chest.","Keep your elbows close to your body."],"img":"opengym/1214.webp","gif":null,"ext":1},{"id":"1215","n":"dumbbell side lunge","bp":"upper legs","eq":"dumbbell","tg":"glutes","mg":"quadriceps","sm":["quadriceps","adductors","hamstrings","core"],"st":["Hold a dumbbell in each hand or one at your chest and stand tall.","Step out wide to one side and sit your hips back.","Keep the other leg straight and your chest upright.","Push through the bent leg to return to the middle.","Alternate sides or finish all reps on one side before switching."],"img":"opengym/1215.webp","gif":null,"ext":1},{"id":"1216","n":"lever seated one leg calf raise","bp":"lower legs","eq":"leverage machine","tg":"calves","mg":"soleus","sm":["soleus","ankles"],"st":["Sit on the machine and place the ball of one foot on the platform.","Set the pad on your thigh and release the safety.","Lower your heel for a stretch.","Press up as high as you can onto your toes.","Pause, lower slowly, then switch legs."],"img":"opengym/1216.webp","gif":null,"ext":1},{"id":"1220","n":"lever calf raise (bench press machine)","bp":"lower legs","eq":"leverage machine","tg":"calves","mg":"soleus","sm":["soleus","ankles"],"st":["Sit on the machine and place the balls of your feet on the lower platform or press plate.","Push to straighten your legs and release the safety.","Lower your heels as far as is comfortable.","Rise up onto your toes as high as possible.","Pause at the top and lower under control."],"img":"opengym/1220.webp","gif":null,"ext":1},{"id":"1221","n":"lever shrug (bench press machine)","bp":"back","eq":"leverage machine","tg":"traps","mg":"upper back","sm":["upper back","trapezius","forearms"],"st":["Set the machine so the handles are at your sides and grip them firmly.","Stand or sit tall with your arms straight.","Lift your shoulders straight up toward your ears.","Pause at the top for a moment.","Lower your shoulders slowly without rolling them."],"img":"opengym/1221.webp","gif":null,"ext":1},{"id":"1222","n":"assisted close grip underhand chin up","bp":"back","eq":"assisted","tg":"lats","mg":"biceps","sm":["biceps","brachialis","upper back"],"st":["Set the assistance weight and kneel or stand on the platform.","Grip the bar with palms facing you, hands close together.","Pull yourself up until your chin clears the bar.","Squeeze your back and biceps at the top.","Lower slowly until your arms are straight."],"img":"opengym/1222.webp","gif":null,"ext":1},{"id":"1223","n":"underhand grip inverted back row","bp":"back","eq":"body weight","tg":"upper back","mg":"lats","sm":["lats","biceps","rhomboids","core"],"st":["Set a bar at waist height and lie under it, gripping it with palms facing you.","Straighten your body from heels to head.","Pull your chest up to the bar, squeezing your shoulder blades.","Lower yourself under control until your arms are straight.","Keep your hips up the whole time."],"img":"opengym/1223.webp","gif":null,"ext":1},{"id":"1224","n":"smith standing shoulder press","bp":"shoulders","eq":"smith machine","tg":"delts","mg":"triceps","sm":["triceps","upper chest"],"st":["Set the bar at shoulder height and stand under it with a shoulder width grip.","Unrack the bar and hold it at your collarbone.","Press up until your arms are straight.","Lower the bar back to your shoulders slowly.","Brace your core and keep your ribs down."],"img":"opengym/1224.webp","gif":null,"ext":1},{"id":"1225","n":"standing plate presses","bp":"shoulders","eq":"weight plate","tg":"delts","mg":"triceps","sm":["triceps","upper chest","core"],"st":["Stand tall holding a plate at the sides with both hands at chest height.","Brace your core and keep your elbows slightly forward.","Press the plate overhead until your arms are straight.","Lower it slowly to your chest.","Keep your ribs down and avoid arching."],"img":"opengym/1225.webp","gif":null,"ext":1},{"id":"1226","n":"ez barbell standing overhead press","bp":"shoulders","eq":"ez barbell","tg":"delts","mg":"triceps","sm":["triceps","upper chest","core"],"st":["Stand holding an EZ bar at your upper chest with a comfortable grip.","Brace your core and squeeze your glutes.","Press the bar overhead until your arms are straight.","Lower it slowly back to your chest.","Keep your head neutral and avoid leaning back."],"img":"opengym/1226.webp","gif":null,"ext":1},{"id":"1227","n":"cable standing one arm triceps pushdown (overhand grip)","bp":"upper arms","eq":"cable","tg":"triceps","mg":"forearms","sm":["forearms","core"],"st":["Attach a handle to a high pulley and stand facing it.","Hold the handle with an overhand grip and tuck your elbow to your side.","Push down until your arm is fully straight.","Squeeze your triceps, then let the handle rise slowly.","Finish your reps, then switch arms."],"img":"opengym/1227.webp","gif":null,"ext":1},{"id":"1228","n":"dumbbell standing inner biceps curl","bp":"upper arms","eq":"dumbbell","tg":"biceps","mg":"brachialis","sm":["brachialis","forearms"],"st":["Stand tall with a dumbbell in each hand, elbows slightly out from your sides.","Curl the weights toward your shoulders.","Squeeze at the top.","Lower them slowly to the start.","Keep your upper arms still."],"img":"opengym/1228.webp","gif":null,"ext":1},{"id":"1229","n":"cable standing lat pushdown (rope equipment)","bp":"back","eq":"cable","tg":"lats","mg":"triceps","sm":["triceps","rear deltoids","core"],"st":["Attach a rope to a high pulley and stand facing it, hinging slightly forward.","Grab the rope with straight arms.","Push the rope down to your thighs, keeping your arms nearly straight.","Squeeze your lats at the bottom.","Let the rope rise slowly to shoulder height."],"img":"opengym/1229.webp","gif":null,"ext":1},{"id":"1230","n":"dumbbell standing alternate vertical front raises","bp":"shoulders","eq":"dumbbell","tg":"delts","mg":"upper chest","sm":["upper chest","core"],"st":["Stand holding dumbbells at your thighs with palms facing in.","Raise one dumbbell straight up to shoulder height.","Pause, then lower it slowly.","Repeat with the other arm and keep alternating.","Avoid swinging your body."],"img":"opengym/1230.webp","gif":null,"ext":1},{"id":"1231","n":"dumbbell seated one arm shoulder press","bp":"shoulders","eq":"dumbbell","tg":"delts","mg":"triceps","sm":["triceps","upper chest","core"],"st":["Sit on a bench with back support, holding a dumbbell at your shoulder.","Brace your core.","Press the dumbbell up until your arm is straight.","Lower it slowly to your shoulder.","Finish your reps, then switch arms."],"img":"opengym/1231.webp","gif":null,"ext":1},{"id":"1232","n":"lever seated squat","bp":"upper legs","eq":"leverage machine","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","adductors"],"st":["Sit in the machine with your back against the pad and shoulders under the supports.","Place your feet on the platform about shoulder width apart.","Push through your feet to extend your legs.","Lower slowly until your knees are comfortably bent.","Keep your knees in line with your toes."],"img":"opengym/1232.webp","gif":null,"ext":1},{"id":"1233","n":"dumbbell incline alternate hammer curl","bp":"upper arms","eq":"dumbbell","tg":"biceps","mg":"brachialis","sm":["brachialis","forearms"],"st":["Sit back on an incline bench holding dumbbells with palms facing in.","Let your arms hang straight down.","Curl one dumbbell up without twisting your wrist.","Lower it slowly and repeat with the other arm.","Keep your upper arms still."],"img":"opengym/1233.webp","gif":null,"ext":1},{"id":"1234","n":"plate hyperextension","bp":"back","eq":"weight plate","tg":"spine","mg":"glutes","sm":["glutes","hamstrings"],"st":["Set the hyperextension bench so your hips are just past the pad.","Hold a weight plate against your chest and cross your arms over it.","Lower your torso toward the floor with a flat back.","Raise your torso until your body forms a straight line.","Squeeze your glutes at the top and avoid overarching."],"img":"opengym/1234.webp","gif":null,"ext":1},{"id":"1235","n":"lever one arm seated row (seated row machine)","bp":"back","eq":"leverage machine","tg":"upper back","mg":"lats","sm":["lats","biceps","rhomboids"],"st":["Sit at the machine with your chest on the pad and grab one handle.","Start with your arm extended.","Pull the handle toward your torso, driving your elbow back.","Squeeze your shoulder blade, then return slowly.","Finish your reps, then switch arms."],"img":"opengym/1235.webp","gif":null,"ext":1},{"id":"1236","n":"dumbbell one arm row (rack support)","bp":"back","eq":"dumbbell","tg":"upper back","mg":"lats","sm":["lats","biceps","rear deltoids"],"st":["Place one hand on a rack or sturdy support and hinge forward with a flat back.","Hold a dumbbell in your other hand with your arm hanging.","Row the dumbbell toward your hip.","Squeeze your back at the top, then lower slowly.","Finish your reps, then switch arms."],"img":"opengym/1236.webp","gif":null,"ext":1},{"id":"1237","n":"lever row (plate loaded)","bp":"back","eq":"leverage machine","tg":"upper back","mg":"lats","sm":["lats","biceps","rhomboids"],"st":["Adjust the seat and chest pad, then grab the handles.","Sit tall with your chest against the pad.","Pull the handles toward your torso, squeezing your shoulder blades.","Pause for a moment.","Return slowly until your arms are straight."],"img":"opengym/1237.webp","gif":null,"ext":1},{"id":"1238","n":"cable seated row (bent bar)","bp":"back","eq":"cable","tg":"upper back","mg":"lats","sm":["lats","biceps","rhomboids"],"st":["Sit at a low cable station with your feet on the platform and knees slightly bent.","Grab the bent bar with both hands.","Pull the bar to your lower ribs, keeping your back straight.","Squeeze your shoulder blades.","Extend your arms slowly without rounding forward."],"img":"opengym/1238.webp","gif":null,"ext":1},{"id":"1241","n":"bird dog","bp":"waist","eq":"body weight","tg":"spine","mg":"glutes","sm":["glutes","core","shoulders","hamstrings"],"st":["Start on all fours with hands under your shoulders and knees under your hips.","Extend your right arm forward and left leg back.","Keep your hips level and your back flat.","Hold for a moment, then return.","Repeat on the other side and alternate."],"img":"opengym/1241.webp","gif":null,"ext":1},{"id":"1242","n":"crunch (on bosu ball)","bp":"waist","eq":"bosu ball","tg":"abs","mg":"obliques","sm":["obliques","core"],"st":["Sit on the bosu ball and lie back so it supports your lower back.","Place your hands lightly behind your head.","Curl your shoulders up by contracting your abs.","Hold the top briefly.","Lower slowly and keep your feet planted."],"img":"opengym/1242.webp","gif":null,"ext":1},{"id":"1243","n":"dead bug v. 2","bp":"waist","eq":"body weight","tg":"abs","mg":"core","sm":["core","lower abs","hip flexors"],"st":["Lie on your back with arms pointing up and knees bent at 90 degrees.","Press your lower back into the floor.","Lower your right arm and left leg toward the floor.","Return and switch sides.","Move slowly and keep your back flat."],"img":"opengym/1243.webp","gif":null,"ext":1},{"id":"1244","n":"flutter kicks v. 3","bp":"waist","eq":"body weight","tg":"abs","mg":"lower abs","sm":["lower abs","hip flexors","core"],"st":["Lie on your back with your legs straight and hands under your hips.","Lift your legs a few inches off the floor.","Kick your legs up and down in small alternating motions.","Keep your lower back pressed to the floor.","Continue for a set time and breathe steadily."],"img":"opengym/1244.webp","gif":null,"ext":1},{"id":"1245","n":"lying leg raise and hold","bp":"waist","eq":"body weight","tg":"abs","mg":"lower abs","sm":["lower abs","hip flexors","core"],"st":["Lie on your back with your legs straight and your hands by your sides.","Press your lower back into the floor.","Raise your legs until they are vertical.","Lower them to just above the floor and hold for a couple of seconds.","Repeat without letting your back arch."],"img":"opengym/1245.webp","gif":null,"ext":1},{"id":"1246","n":"hollow hold","bp":"waist","eq":"body weight","tg":"abs","mg":"lower abs","sm":["lower abs","hip flexors","core"],"st":["Lie on your back with your arms overhead and legs straight.","Press your lower back into the floor.","Lift your shoulders and legs a few inches off the ground.","Hold the shape and breathe steadily.","Hold for 20-30 seconds, then rest."],"img":"opengym/1246.webp","gif":null,"ext":1},{"id":"1247","n":"russian twist (with medicine ball)","bp":"waist","eq":"medicine ball","tg":"obliques","mg":"core","sm":["core","hip flexors"],"st":["Sit with your knees bent and lean back slightly, holding a medicine ball at your chest.","Lift your feet slightly if you can.","Rotate your torso to one side and tap the ball by your hip.","Rotate to the other side.","Keep your chest tall and move with control."],"img":"opengym/1247.webp","gif":null,"ext":1},{"id":"1248","n":"half wipers (bent leg)","bp":"waist","eq":"body weight","tg":"obliques","mg":"lower abs","sm":["lower abs","hip flexors"],"st":["Lie on your back with your arms out to the sides for support.","Lift your knees to 90 degrees.","Lower both knees to one side, stopping before the floor.","Bring them back to the middle and go to the other side.","Keep your shoulders on the floor."],"img":"opengym/1248.webp","gif":null,"ext":1},{"id":"1249","n":"wipers (straight leg)","bp":"waist","eq":"body weight","tg":"obliques","mg":"lower abs","sm":["lower abs","hip flexors"],"st":["Lie on your back with your arms out to the sides.","Raise your legs straight up over your hips.","Lower both legs to one side with control.","Lift them back to the middle and lower to the other side.","Keep your shoulders flat on the floor."],"img":"opengym/1249.webp","gif":null,"ext":1},{"id":"1250","n":"weighted crunch (behind head)","bp":"waist","eq":"weighted","tg":"abs","mg":"obliques","sm":["obliques","core"],"st":["Lie on your back with your knees bent and feet flat.","Hold a weight behind your head with your elbows out.","Curl your shoulders up, contracting your abs.","Pause at the top.","Lower slowly without pulling on your neck."],"img":"opengym/1250.webp","gif":null,"ext":1},{"id":"1315","n":"back relaxation","bp":"back","eq":"body weight","tg":"spine","mg":"lower back","sm":["lower back","glutes"],"st":["Get into a comfortable resting position, such as kneeling with your torso folded forward.","Rest your arms in a relaxed position.","Let your back round and release.","Breathe slowly into your lower back.","Hold for 30-60 seconds."],"img":"opengym/1315.webp","gif":null,"ext":1},{"id":"1337","n":"exercise ball back stretch","bp":"back","eq":"stability ball","tg":"lats","mg":"lower back","sm":["lower back","core"],"st":["Sit on a stability ball and walk your feet forward.","Lean back until your back rests over the ball.","Let your arms fall overhead and relax.","Breathe deeply and let your back open.","Hold for 20-30 seconds."],"img":"opengym/1337.webp","gif":null,"ext":1},{"id":"1340","n":"exercise ball lower back prone stretch","bp":"back","eq":"stability ball","tg":"spine","mg":"lats","sm":["lats","glutes","hamstrings"],"st":["Kneel by a stability ball and lay your torso over it.","Roll forward so your hips rest on the ball.","Let your arms and head hang down in a relaxed way.","Breathe slowly and let your lower back release.","Hold for 20-30 seconds."],"img":"opengym/1340.webp","gif":null,"ext":1},{"id":"1357","n":"one handed hang","bp":"lower arms","eq":"body weight","tg":"forearms","mg":"grip muscles","sm":["grip muscles","lats","hands"],"st":["Stand under a pull-up bar and grip it with one hand.","Lift your feet and hang with your arm straight.","Keep your shoulder active and your body still.","Hold for 10-20 seconds.","Lower yourself carefully and switch hands."],"img":"opengym/1357.webp","gif":null,"ext":1},{"id":"1400","n":"squat side kick","bp":"upper legs","eq":"body weight","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","core"],"st":["Stand with your feet shoulder width apart.","Squat down with your chest up.","Stand up and kick your right leg out to the side.","Return the foot to the floor and drop into the next squat.","Alternate sides each rep."],"img":"opengym/1400.webp","gif":null,"ext":1},{"id":"1402","n":"l sit","bp":"waist","eq":"body weight","tg":"abs","mg":"hip flexors","sm":["hip flexors","triceps","shoulders","quadriceps"],"st":["Sit between two supports or on the floor and place your hands beside your hips.","Press down through your hands to lift your hips and legs off the floor.","Extend your legs straight in front of you.","Keep your shoulders pressed down and your core tight.","Hold for as long as you can with good form, then lower."],"img":"opengym/1402.webp","gif":null,"ext":1},{"id":"1404","n":"back stretch","bp":"back","eq":"body weight","tg":"lats","mg":"lower back","sm":["lower back","upper back"],"st":["Stand or sit tall and clasp your hands in front of you.","Press your arms forward and round your upper back.","Let your head drop gently.","Breathe slowly into your back.","Hold for 20-30 seconds."],"img":"opengym/1404.webp","gif":null,"ext":1},{"id":"1406","n":"hamstring lying stretch","bp":"upper legs","eq":"body weight","tg":"hamstrings","mg":"calves","sm":["calves","glutes","lower back"],"st":["Lie on your back with both legs extended.","Raise one leg and hold behind the thigh or calf.","Gently straighten the knee while pulling the leg toward you.","Keep your other leg flat and your back relaxed.","Hold for 20-30 seconds, then switch legs."],"img":"opengym/1406.webp","gif":null,"ext":1},{"id":"1440","n":"plank arm lifts","bp":"waist","eq":"body weight","tg":"abs","mg":"shoulders","sm":["shoulders","core","glutes","upper back"],"st":["Get into a forearm or high plank with your body in a straight line.","Brace your abs and squeeze your glutes.","Lift one arm forward without letting your hips rotate.","Place it back down with control and lift the other.","Keep your neck neutral and alternate arms for the planned reps."],"img":"opengym/1440.webp","gif":null,"ext":1},{"id":"1442","n":"dip hold","bp":"upper arms","eq":"body weight","tg":"triceps","mg":"chest","sm":["chest","shoulders","core"],"st":["Grip the parallel bars and press yourself up with straight arms.","Lean slightly forward and lock your shoulders down.","Hold the position with your body still.","Keep your elbows near your sides.","Hold for 15-30 seconds and step down."],"img":"opengym/1442.webp","gif":null,"ext":1},{"id":"1443","n":"dumbbell lying pronated grip maltese hold","bp":"shoulders","eq":"dumbbell","tg":"delts","mg":"upper chest","sm":["upper chest","chest","core"],"st":["Lie face up with a dumbbell in each hand, palms down.","Lift your arms out to the sides at about hip level.","Keep your arms straight and your body tight.","Hold the position without letting the weights drop.","Hold for 10-20 seconds, then lower carefully."],"img":"opengym/1443.webp","gif":null,"ext":1},{"id":"1444","n":"dumbbell bent arm pullover hold","bp":"chest","eq":"dumbbell","tg":"pectorals","mg":"lats","sm":["lats","triceps","core"],"st":["Lie on a bench holding a dumbbell with both hands over your chest.","Lower it behind your head with your elbows bent.","Stop where you feel a stretch in your chest and lats.","Hold the position with your core tight.","Hold for 15-30 seconds, then lift it back up."],"img":"opengym/1444.webp","gif":null,"ext":1},{"id":"1445","n":"dumbbell rdl stretch","bp":"upper legs","eq":"dumbbell","tg":"hamstrings","mg":"glutes","sm":["glutes","lower back","grip muscles"],"st":["Stand holding dumbbells in front of your thighs.","Push your hips back and lower the dumbbells along your legs.","Stop when you feel a deep stretch in your hamstrings.","Hold the position with a flat back.","Hold for 15-30 seconds, then stand up."],"img":"opengym/1445.webp","gif":null,"ext":1},{"id":"1446","n":"barbell zercher squat hold","bp":"upper legs","eq":"barbell","tg":"quads","mg":"glutes","sm":["glutes","core","biceps","adductors"],"st":["Place the barbell in the crooks of your elbows.","Squat down until your thighs are about parallel.","Keep your chest up and your core tight.","Hold the bottom position steadily.","Hold for 10-20 seconds, then stand up."],"img":"opengym/1446.webp","gif":null,"ext":1},{"id":"1447","n":"lever calf stretch (plate loaded)","bp":"lower legs","eq":"leverage machine","tg":"calves","mg":"soleus","sm":["soleus","ankles"],"st":["Set up on the machine and place the ball of one foot on the platform with the heel free.","Keep your knee straight and stand tall.","Let the heel sink down until you feel a stretch in the calf.","Hold for 20-30 seconds, breathing steadily, then release slowly.","Switch legs and repeat."],"img":"opengym/1447.webp","gif":null,"ext":1},{"id":"1448","n":"barbell pullover hold","bp":"back","eq":"barbell","tg":"lats","mg":"chest","sm":["chest","triceps","core"],"st":["Lie on a bench holding a light barbell above your chest with arms nearly straight.","Lower the bar back over your head until you feel a deep stretch in your lats.","Brace your core and keep your ribs down and your elbows softly bent.","Hold the position for 15-30 seconds without letting the bar drift.","Return the bar over your chest with control and set it down safely."],"img":"opengym/1448.webp","gif":null,"ext":1},{"id":"1449","n":"dumbbell incline 30 degrees flye hold","bp":"chest","eq":"dumbbell","tg":"pectorals","mg":"upper chest","sm":["upper chest","shoulders","biceps"],"st":["Set a bench to about 30 degrees and lie back with a dumbbell in each hand above your chest.","Open your arms wide with soft elbows until the dumbbells are level with your chest.","Keep your shoulder blades pinned back and down.","Hold the stretched position for 15-30 seconds without sagging.","Bring the weights back together over your chest and set them down carefully."],"img":"opengym/1449.webp","gif":null,"ext":1},{"id":"1450","n":"dumbbell flat flye hold","bp":"chest","eq":"dumbbell","tg":"pectorals","mg":"upper chest","sm":["upper chest","shoulders","biceps"],"st":["Lie flat on a bench with a dumbbell in each hand above your chest.","Open your arms wide with soft elbows until the dumbbells are level with your chest.","Keep your shoulder blades pinned back and your feet planted.","Hold the position for 15-30 seconds without letting the weights drop.","Bring the dumbbells back together over your chest and set them down carefully."],"img":"opengym/1450.webp","gif":null,"ext":1},{"id":"1453","n":"lever seated twist","bp":"waist","eq":"leverage machine","tg":"obliques","mg":"abdominals","sm":["abdominals","lower back"],"st":["Sit on the machine, adjust the pads and place your arms or hands as designed.","Sit tall with your hips facing forward.","Rotate your torso to one side with a smooth, controlled turn.","Pause briefly, then return to the centre without letting the weight stack slam.","Repeat to the other side and keep alternating."],"img":"opengym/1453.webp","gif":null,"ext":1},{"id":"1454","n":"lever seated shoulder press","bp":"shoulders","eq":"leverage machine","tg":"delts","mg":"triceps","sm":["triceps","upper chest"],"st":["Adjust the seat so the handles start near shoulder height and sit with your back on the pad.","Grip the handles and brace your core.","Press the handles overhead until your arms are nearly straight.","Pause briefly at the top without shrugging.","Lower slowly back to shoulder height and repeat."],"img":"opengym/1454.webp","gif":null,"ext":1},{"id":"1455","n":"lever chest press v. 2","bp":"chest","eq":"leverage machine","tg":"pectorals","mg":"triceps","sm":["triceps","upper chest","shoulders"],"st":["Adjust the seat so the handles line up with the middle of your chest.","Sit back with your shoulder blades against the pad and feet flat.","Press the handles forward until your arms are almost straight.","Pause, then return slowly until you feel a stretch across the chest.","Keep your wrists straight and your back on the pad throughout."],"img":"opengym/1455.webp","gif":null,"ext":1},{"id":"1465","n":"45 degree hyperextension (arms in front of chest) (side pov)","bp":"back","eq":"body weight","tg":"spine","mg":"glutes","sm":["glutes","hamstrings","core"],"st":["Set the pad at hip height and hook your heels under the roller.","Cross your arms over your chest and keep your body straight.","Lower your torso with a flat back until you feel a hamstring stretch.","Raise back up until your body is in line, without overarching.","Move slowly and squeeze your glutes at the top."],"img":"opengym/1465.webp","gif":null,"ext":1},{"id":"1469","n":"lateral side plank (bent leg)","bp":"waist","eq":"body weight","tg":"obliques","mg":"shoulders","sm":["shoulders","glutes","core"],"st":["Lie on your side with your forearm under your shoulder and your knees bent.","Stack your hips and shoulders in a line.","Lift your hips off the floor until your body forms a straight line from knee to head.","Keep your core tight and your hips from sagging.","Hold for the planned time, then switch sides."],"img":"opengym/1469.webp","gif":null,"ext":1},{"id":"1478","n":"jack plank","bp":"waist","eq":"body weight","tg":"abs","mg":"shoulders","sm":["shoulders","core","hip flexors","quadriceps"],"st":["Start in a high plank with your hands under your shoulders.","Brace your core and keep your hips level.","Jump your feet apart, then jump them back together.","Keep your upper body steady and your hips from rising.","Continue at a steady pace for the planned time."],"img":"opengym/1478.webp","gif":null,"ext":1},{"id":"1480","n":"biceps stretch behind the back","bp":"upper arms","eq":"body weight","tg":"biceps","mg":"forearms","sm":["forearms","chest","shoulders"],"st":["Stand tall and reach both arms behind your back.","Straighten your elbows and turn your palms down or clasp your hands.","Lift your hands slightly away from your body until you feel a stretch in the biceps.","Keep your chest open and your neck relaxed.","Hold for 20-30 seconds, breathing steadily, then release slowly."],"img":"opengym/1480.webp","gif":null,"ext":1},{"id":"1481","n":"bow yoga pose","bp":"upper legs","eq":"body weight","tg":"quads","mg":"hip flexors","sm":["hip flexors","chest","lower back"],"st":["Lie on your stomach with your arms along your sides.","Bend your knees and reach back to hold your ankles.","Lift your chest and kick your feet gently into your hands to raise your thighs.","Keep your gaze forward and breathe steadily.","Hold for 15-30 seconds, then release slowly and rest on the mat."],"img":"opengym/1481.webp","gif":null,"ext":1},{"id":"1482","n":"cobra yoga pose","bp":"waist","eq":"body weight","tg":"abs","mg":"lower back","sm":["lower back","chest","shoulders"],"st":["Lie on your stomach with your palms under your shoulders and legs extended.","Press the tops of your feet into the floor.","Lift your chest by straightening your arms partway, keeping your hips down.","Keep your shoulders away from your ears and your neck long.","Hold for 15-30 seconds, then lower slowly."],"img":"opengym/1482.webp","gif":null,"ext":1},{"id":"1483","n":"full lotus yoga pose","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"groin","sm":["groin","ankles","hip flexors"],"st":["Sit tall on the floor with your legs extended.","Bring one foot onto the opposite thigh, then the other foot on top of the other thigh.","Only go as far as your hips allow, and never force your knees.","Rest your hands on your knees and lengthen your spine.","Hold for 20-30 seconds with calm breathing, then switch the leg order next time."],"img":"opengym/1483.webp","gif":null,"ext":1},{"id":"1484","n":"locust yoga pose (iron man pose)","bp":"back","eq":"body weight","tg":"spine","mg":"glutes","sm":["glutes","hamstrings","upper back"],"st":["Lie face down with your arms along your sides and palms facing up.","Press your pelvis into the floor and engage your glutes.","Lift your chest, arms and legs off the floor together.","Look slightly forward and keep your neck long.","Hold for 10-20 seconds, then lower slowly and rest."],"img":"opengym/1484.webp","gif":null,"ext":1},{"id":"1485","n":"plow yoga pose","bp":"back","eq":"body weight","tg":"spine","mg":"hamstrings","sm":["hamstrings","shoulders","upper back"],"st":["Lie on your back with your arms by your sides.","Lift your legs and hips up and over, supporting your lower back with your hands if needed.","Lower your toes toward the floor behind your head.","Keep your neck relaxed and do not turn your head.","Hold for 15-30 seconds, then roll down slowly one vertebra at a time."],"img":"opengym/1485.webp","gif":null,"ext":1},{"id":"1486","n":"push up (with push up handles)","bp":"chest","eq":"body weight","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders","core"],"st":["Place the handles shoulder-width apart and grip them in a plank position.","Keep your body in a straight line from head to heels.","Lower your chest until it is between the handles, elbows about 45 degrees from your body.","Press back up until your arms are straight.","Keep your core tight and your hips from sagging."],"img":"opengym/1486.webp","gif":null,"ext":1},{"id":"1487","n":"shoulder stand yoga pose","bp":"back","eq":"body weight","tg":"upper back","mg":"shoulders","sm":["shoulders","core","trapezius"],"st":["Lie on your back and lift your legs overhead, supporting your lower back with your hands.","Walk your hands up toward your shoulder blades.","Raise your legs straight up so your body forms a line over your shoulders.","Keep your neck long and still, and do not turn your head.","Hold for 15-30 seconds, then lower slowly."],"img":"opengym/1487.webp","gif":null,"ext":1},{"id":"1488","n":"shoulder stretch behind the back","bp":"shoulders","eq":"body weight","tg":"delts","mg":"chest","sm":["chest","triceps","upper chest"],"st":["Stand tall and clasp your hands behind your back.","Straighten your arms and squeeze your shoulder blades together.","Lift your hands gently away from your body until you feel a stretch.","Keep your chest open and avoid arching your lower back.","Hold for 20-30 seconds, breathing steadily, then release slowly."],"img":"opengym/1488.webp","gif":null,"ext":1},{"id":"1491","n":"supine spinal twist yoga pose","bp":"waist","eq":"body weight","tg":"spine","mg":"obliques","sm":["obliques","glutes","chest"],"st":["Lie on your back with your arms out to the sides.","Pull one knee toward your chest.","Guide that knee across your body toward the floor on the opposite side.","Keep both shoulders on the floor and turn your head the other way if comfortable.","Hold for 20-30 seconds, then switch sides."],"img":"opengym/1491.webp","gif":null,"ext":1},{"id":"1492","n":"triceps dip stretch","bp":"upper arms","eq":"body weight","tg":"triceps","mg":"shoulders","sm":["shoulders","chest","lats"],"st":["Stand or sit tall and raise one arm overhead.","Bend the elbow so your hand drops behind your head.","Use your other hand to gently press the elbow back and down.","Keep your ribs down and avoid arching your back.","Hold for 20-30 seconds, then switch arms."],"img":"opengym/1492.webp","gif":null,"ext":1},{"id":"1493","n":"wheel pose yoga pose","bp":"back","eq":"body weight","tg":"spine","mg":"shoulders","sm":["shoulders","glutes","quadriceps","chest"],"st":["Lie on your back with your knees bent and feet flat near your hips.","Place your palms beside your head with fingers pointing toward your shoulders.","Press through your hands and feet to lift your hips and then your head.","Straighten your arms as far as comfortable and keep your thighs parallel.","Hold for 5-15 seconds, then lower slowly with your chin tucked."],"img":"opengym/1493.webp","gif":null,"ext":1},{"id":"1497","n":"barbell reverse band bench press","bp":"chest","eq":"barbell","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders","upper chest"],"st":["Set up on a bench with bands anchored to the rack and attached to the bar.","Lie back with your eyes under the bar and your shoulder blades pinched.","Lower the bar to your mid chest with control.","Press the bar back up to straight arms, feeling the band resistance change.","Keep your feet planted and your wrists stacked over your elbows."],"img":"opengym/1497.webp","gif":null,"ext":1},{"id":"1498","n":"band decline sit up","bp":"waist","eq":"band","tg":"abs","mg":"hip flexors","sm":["hip flexors","obliques"],"st":["Anchor a band behind you and hold the other end at your chest.","Lie on a decline bench with your feet secured.","Curl your torso up toward your knees, keeping tension on the band.","Pause at the top without pulling on your neck.","Lower back down slowly under control."],"img":"opengym/1498.webp","gif":null,"ext":1},{"id":"1499","n":"band behind neck shoulder press","bp":"shoulders","eq":"band","tg":"delts","mg":"triceps","sm":["triceps","trapezius","upper back"],"st":["Stand on the band and hold the ends at the back of your shoulders.","Brace your core and keep your head forward.","Press your hands straight up until your arms are extended.","Lower slowly back behind your head to shoulder level.","Only use this variation if your shoulders move comfortably in that position."],"img":"opengym/1499.webp","gif":null,"ext":1},{"id":"1500","n":"band upright row (under two feet)","bp":"shoulders","eq":"band","tg":"delts","mg":"trapezius","sm":["trapezius","biceps","upper back"],"st":["Stand with both feet on the middle of the band and hold the ends in front of your thighs.","Keep your chest up and your core tight.","Pull your hands up along your body until they reach chest height, elbows leading.","Pause briefly without shrugging too high.","Lower slowly back down."],"img":"opengym/1500.webp","gif":null,"ext":1},{"id":"1501","n":"band side plank row with partner","bp":"back","eq":"band","tg":"upper back","mg":"lats","sm":["lats","obliques","rhomboids","biceps","core"],"st":["Get into a side plank on one forearm, with a partner holding the band in front of you.","Grip the band with your top hand and keep your hips lifted.","Row your hand back toward your ribs, squeezing the shoulder blade.","Return slowly without letting your hips drop.","Finish your reps, then switch sides."],"img":"opengym/1501.webp","gif":null,"ext":1},{"id":"1502","n":"band pushdown","bp":"upper arms","eq":"band","tg":"triceps","mg":"forearms","sm":["forearms","shoulders"],"st":["Anchor the band high and hold the ends with your elbows at your sides.","Stand tall with a slight forward lean.","Push your hands down until your arms are straight.","Pause and squeeze your triceps.","Return slowly while keeping your elbows pinned to your sides."],"img":"opengym/1502.webp","gif":null,"ext":1},{"id":"1503","n":"band pull apart","bp":"back","eq":"band","tg":"upper back","mg":"rear deltoids","sm":["rear deltoids","rhomboids","trapezius","rotator cuff"],"st":["Hold a band in front of you at shoulder height with your arms straight.","Keep your ribs down and your shoulders away from your ears.","Pull the band apart by moving your hands out to the sides.","Squeeze your shoulder blades together at the end.","Return slowly with control."],"img":"opengym/1503.webp","gif":null,"ext":1},{"id":"1504","n":"band skull crusher","bp":"upper arms","eq":"band","tg":"triceps","mg":"forearms","sm":["forearms","shoulders"],"st":["Anchor the band behind your head and lie on your back holding the ends.","Start with your arms straight above your chest.","Bend only your elbows to lower your hands toward your forehead.","Extend your arms back up against the band.","Keep your upper arms still throughout."],"img":"opengym/1504.webp","gif":null,"ext":1},{"id":"1505","n":"band calf raise v. 3","bp":"lower legs","eq":"band","tg":"calves","mg":"soleus","sm":["soleus","ankles","feet"],"st":["Secure the band under your feet or around your shoulders as set up.","Stand tall with your feet hip-width apart.","Rise onto the balls of your feet as high as you can.","Pause and squeeze your calves.","Lower slowly until your heels are back on the floor."],"img":"opengym/1505.webp","gif":null,"ext":1},{"id":"1506","n":"band ez barbell close grip curl","bp":"upper arms","eq":"ez barbell","tg":"biceps","mg":"brachialis","sm":["brachialis","forearms"],"st":["Stand on the band and hold the EZ bar with a close grip, palms up.","Keep your elbows at your sides and your chest tall.","Curl the bar up toward your shoulders.","Squeeze at the top without swinging.","Lower slowly until your arms are straight."],"img":"opengym/1506.webp","gif":null,"ext":1},{"id":"1507","n":"band hip flexion","bp":"upper legs","eq":"band","tg":"hip flexors","mg":"quadriceps","sm":["quadriceps","lower abs","core"],"st":["Attach a band to a low anchor and loop it around one ankle.","Stand tall and hold a support for balance.","Lift the knee forward and up toward hip height.","Pause briefly, then lower with control.","Finish your reps and switch legs."],"img":"opengym/1507.webp","gif":null,"ext":1},{"id":"1508","n":"band lateral raise v. 2","bp":"shoulders","eq":"band","tg":"delts","mg":"trapezius","sm":["trapezius","upper back"],"st":["Stand on the band and hold the ends at your sides.","Keep a slight bend in your elbows.","Raise your arms out to the sides until they reach shoulder height.","Pause briefly without shrugging.","Lower slowly back to your sides."],"img":"opengym/1508.webp","gif":null,"ext":1},{"id":"1509","n":"barbell bench squat (with chains)","bp":"upper legs","eq":"barbell","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","core","lower back"],"st":["Set a bench behind you and load the bar with chains.","Place the bar on your upper back and stand with feet shoulder-width apart.","Sit back and down until you touch the bench lightly.","Keep your chest up and your knees tracking over your toes.","Drive through your feet to stand, feeling the chains add weight."],"img":"opengym/1509.webp","gif":null,"ext":1},{"id":"1510","n":"crossover reverse lunge","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","adductors","core"],"st":["Stand tall with your hands on your hips.","Step one foot back and across behind your other leg.","Lower until both knees are bent about 90 degrees.","Keep your torso upright and your front knee stable.","Push through the front foot to stand, then repeat or switch sides."],"img":"opengym/1510.webp","gif":null,"ext":1},{"id":"1513","n":"band good morning","bp":"upper legs","eq":"band","tg":"hamstrings","mg":"glutes","sm":["glutes","lower back","core"],"st":["Stand on the band and loop it behind your neck across your shoulders.","Keep your knees softly bent and your back flat.","Push your hips back and lean your torso forward.","Stop when you feel a stretch in the hamstrings.","Drive your hips forward to stand tall again."],"img":"opengym/1513.webp","gif":null,"ext":1},{"id":"1514","n":"barbell quarter squat","bp":"upper legs","eq":"barbell","tg":"quads","mg":"glutes","sm":["glutes","core","lower back"],"st":["Rest the bar on your upper back and stand with feet shoulder-width apart.","Brace your core and keep your chest up.","Bend your knees and hips a short way, about a quarter of the full depth.","Keep your knees tracking over your toes.","Drive up through your feet to stand tall."],"img":"opengym/1514.webp","gif":null,"ext":1},{"id":"1515","n":"barbell clean deadlift","bp":"upper legs","eq":"barbell","tg":"glutes","mg":"hamstrings","sm":["hamstrings","quadriceps","lower back","upper back","grip muscles"],"st":["Stand with the bar over your mid-foot and grip just outside your knees.","Set a flat back, chest up and shoulders over the bar.","Push the floor away to lift the bar, keeping it close to your legs.","Stand tall with hips and knees fully extended.","Lower the bar back down with control along the same path."],"img":"opengym/1515.webp","gif":null,"ext":1},{"id":"1516","n":"barbell clean from blocks","bp":"full body","eq":"barbell","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","trapezius","shoulders","core"],"st":["Set the bar on blocks and grip it just outside your knees with a flat back.","Brace your core and keep the bar close to your body.","Extend your hips and knees powerfully and shrug your shoulders.","Pull yourself under the bar and catch it on your front shoulders in a full squat.","Stand tall to finish, then lower the bar with control."],"img":"opengym/1516.webp","gif":null,"ext":1},{"id":"1517","n":"barbell clean pull","bp":"full body","eq":"barbell","tg":"glutes","mg":"hamstrings","sm":["hamstrings","trapezius","quadriceps","lower back","grip muscles"],"st":["Set up over the bar with a flat back and a grip just outside your knees.","Lift the bar past your knees, keeping it close.","Extend your hips and knees explosively and shrug.","Let your elbows rise high, but do not catch the bar.","Lower the bar with control and reset."],"img":"opengym/1517.webp","gif":null,"ext":1},{"id":"1518","n":"barbell decline bench lunge","bp":"upper legs","eq":"barbell","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","adductors","core"],"st":["Place the bar on your upper back and rest one foot behind you on a decline bench.","Step the front foot out to set a stable stance.","Lower your back knee toward the floor, torso upright.","Drive through the front foot to rise.","Finish your reps, then switch legs."],"img":"opengym/1518.webp","gif":null,"ext":1},{"id":"1519","n":"smith good morning off pins","bp":"upper legs","eq":"smith machine","tg":"hamstrings","mg":"glutes","sm":["glutes","lower back","core"],"st":["Set the bar on the pins at upper-chest height and duck under it.","Stand tall with the bar on your upper back and knees slightly bent.","Push your hips back, keeping your back flat.","Stop when your torso is near parallel with the floor.","Drive your hips forward to stand, then return the bar to the pins when done."],"img":"opengym/1519.webp","gif":null,"ext":1},{"id":"1520","n":"barbell hang clean","bp":"full body","eq":"barbell","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","trapezius","shoulders","core"],"st":["Stand holding the bar at mid-thigh with a grip just outside your legs and a flat back.","Brace your core and keep the bar close to your body.","Extend your hips and knees powerfully and shrug your shoulders.","Pull yourself under the bar and catch it on your front shoulders in a squat.","Stand tall to finish, then lower the bar with control."],"img":"opengym/1520.webp","gif":null,"ext":1},{"id":"1521","n":"barbell hang clean below the knees","bp":"full body","eq":"barbell","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","trapezius","shoulders","core"],"st":["Hold the bar just below your knees with a flat back and your shoulders over the bar.","Brace your core and keep the bar close to your body.","Extend your hips and knees powerfully and shrug your shoulders.","Pull yourself under the bar and catch it on your front shoulders in a squat.","Stand tall to finish, then lower the bar with control."],"img":"opengym/1521.webp","gif":null,"ext":1},{"id":"1522","n":"barbell hang snatch","bp":"full body","eq":"barbell","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","trapezius","shoulders","core"],"st":["Hold the bar at mid-thigh with a wide snatch grip and a flat back.","Brace your core and keep the bar close to your body.","Extend your hips and knees powerfully and shrug your shoulders.","Pull under the bar and catch it overhead with locked arms in a squat.","Stand tall to finish, then lower the bar with control."],"img":"opengym/1522.webp","gif":null,"ext":1},{"id":"1523","n":"barbell hang snatch below the knees","bp":"full body","eq":"barbell","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","trapezius","shoulders","core"],"st":["Hold the bar just below your knees with a wide grip and a flat back.","Brace your core and keep the bar close to your body.","Extend your hips and knees powerfully and shrug your shoulders.","Pull under the bar and catch it overhead with locked arms in a squat.","Stand tall to finish, then lower the bar with control."],"img":"opengym/1523.webp","gif":null,"ext":1},{"id":"1524","n":"barbell heaving snatch balance","bp":"full body","eq":"barbell","tg":"quads","mg":"shoulders","sm":["shoulders","triceps","glutes","core","upper back"],"st":["Rest the bar on your upper back and take a wide snatch grip.","Dip and drive up explosively, pushing the bar off your shoulders.","Drop quickly into a squat while pressing the bar overhead.","Catch it with locked arms over your mid-foot.","Stand up with control and return the bar to your back."],"img":"opengym/1524.webp","gif":null,"ext":1},{"id":"1525","n":"barbell jerk dip squat","bp":"upper legs","eq":"barbell","tg":"quads","mg":"glutes","sm":["glutes","calves","core","shoulders"],"st":["Rack the bar on your front shoulders and stand with feet hip-width apart.","Keep your torso upright and your core tight.","Dip a short way by bending your knees straight down.","Drive up explosively through your whole foot.","Settle back to standing and reset."],"img":"opengym/1525.webp","gif":null,"ext":1},{"id":"1526","n":"barbell muscle snatch","bp":"full body","eq":"barbell","tg":"traps","mg":"quadriceps","sm":["quadriceps","hamstrings","trapezius","shoulders","core"],"st":["Hold the bar at the hips with a wide grip, shoulders over the bar.","Brace your core and keep the bar close to your body.","Extend your hips and knees powerfully and shrug your shoulders.","Pull the bar up high with your elbows, turn it over and press to locked arms overhead without squatting.","Stand tall to finish, then lower the bar with control."],"img":"opengym/1526.webp","gif":null,"ext":1},{"id":"1527","n":"barbell olympic squat","bp":"upper legs","eq":"barbell","tg":"quads","mg":"glutes","sm":["glutes","adductors","hamstrings","core","lower back"],"st":["Place the bar high on your upper back and set your feet about shoulder-width.","Brace your core and keep your chest up.","Sit straight down as deep as you can with heels flat.","Keep your knees tracking over your toes.","Drive up through your feet to stand tall."],"img":"opengym/1527.webp","gif":null,"ext":1},{"id":"1528","n":"barbell power clean from blocks","bp":"full body","eq":"barbell","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","trapezius","shoulders","core"],"st":["Set the bar on blocks and grip it just outside your knees with a flat back.","Brace your core and keep the bar close to your body.","Extend your hips and knees powerfully and shrug your shoulders.","Pull and catch the bar on your front shoulders in a quarter squat.","Stand tall to finish, then lower the bar with control."],"img":"opengym/1528.webp","gif":null,"ext":1},{"id":"1529","n":"barbell power jerk","bp":"full body","eq":"barbell","tg":"delts","mg":"triceps","sm":["triceps","quadriceps","glutes","core","calves"],"st":["Rack the bar on your front shoulders with elbows slightly forward.","Dip a short way with your torso upright.","Drive up explosively and punch the bar overhead.","Dip under slightly and catch it with locked arms.","Stand tall, then lower the bar to your shoulders with control."],"img":"opengym/1529.webp","gif":null,"ext":1},{"id":"1530","n":"barbell power snatch","bp":"full body","eq":"barbell","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","trapezius","shoulders","core"],"st":["Hold the bar at your shins with a wide grip, flat back and chest up.","Brace your core and keep the bar close to your body.","Extend your hips and knees powerfully and shrug your shoulders.","Pull under and catch the bar overhead with locked arms in a quarter squat.","Stand tall to finish, then lower the bar with control."],"img":"opengym/1530.webp","gif":null,"ext":1},{"id":"1531","n":"barbell power snatch from blocks","bp":"full body","eq":"barbell","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","trapezius","shoulders","core"],"st":["Set the bar on blocks and take a wide grip with a flat back.","Brace your core and keep the bar close to your body.","Extend your hips and knees powerfully and shrug your shoulders.","Pull under and catch the bar overhead with locked arms in a quarter squat.","Stand tall to finish, then lower the bar with control."],"img":"opengym/1531.webp","gif":null,"ext":1},{"id":"1532","n":"barbell romanian deadlift from deficit","bp":"upper legs","eq":"barbell","tg":"hamstrings","mg":"glutes","sm":["glutes","lower back","grip muscles","upper back"],"st":["Stand on a low platform holding the bar at your thighs.","Keep your knees soft and your back flat.","Push your hips back and slide the bar down your legs.","Lower as far as you can with a flat back.","Drive your hips forward to stand tall."],"img":"opengym/1532.webp","gif":null,"ext":1},{"id":"1533","n":"barbell snatch","bp":"full body","eq":"barbell","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","trapezius","shoulders","core"],"st":["Grip the bar wide, with it over your mid-foot, flat back and chest up.","Brace your core and keep the bar close to your body.","Extend your hips and knees powerfully and shrug your shoulders.","Pull under the bar and catch it overhead in a full squat, then stand up.","Stand tall to finish, then lower the bar with control."],"img":"opengym/1533.webp","gif":null,"ext":1},{"id":"1534","n":"barbell snatch balance","bp":"full body","eq":"barbell","tg":"quads","mg":"shoulders","sm":["shoulders","triceps","glutes","core","upper back"],"st":["Rest the bar on your upper back and take a wide snatch grip.","Dip a short way and drive up.","Drop into a squat while pressing the bar overhead.","Catch it with locked arms and your chest up.","Stand up with control and return the bar to your back."],"img":"opengym/1534.webp","gif":null,"ext":1},{"id":"1535","n":"barbell snatch deadlift","bp":"upper legs","eq":"barbell","tg":"glutes","mg":"hamstrings","sm":["hamstrings","quadriceps","lower back","upper back","grip muscles"],"st":["Stand with the bar over your mid-foot and take a wide snatch grip.","Set your back flat and chest up.","Push the floor away to lift the bar, keeping it close.","Stand tall with your hips and knees extended.","Lower the bar with control along the same path."],"img":"opengym/1535.webp","gif":null,"ext":1},{"id":"1536","n":"barbell snatch from blocks","bp":"full body","eq":"barbell","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","trapezius","shoulders","core"],"st":["Set the bar on blocks and take a wide grip with a flat back.","Brace your core and keep the bar close to your body.","Extend your hips and knees powerfully and shrug your shoulders.","Pull under the bar and catch it overhead in a full squat, then stand up.","Stand tall to finish, then lower the bar with control."],"img":"opengym/1536.webp","gif":null,"ext":1},{"id":"1537","n":"barbell split clean","bp":"full body","eq":"barbell","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","trapezius","shoulders","core"],"st":["Grip the bar just outside your legs with a flat back, shoulders over the bar.","Brace your core and keep the bar close to your body.","Extend your hips and knees powerfully and shrug your shoulders.","Split your feet front and back and catch the bar on your front shoulders.","Stand tall to finish, then lower the bar with control."],"img":"opengym/1537.webp","gif":null,"ext":1},{"id":"1538","n":"barbell split jerk","bp":"full body","eq":"barbell","tg":"delts","mg":"triceps","sm":["triceps","quadriceps","glutes","core","calves"],"st":["Rack the bar on your front shoulders with elbows slightly forward.","Dip a short way with your torso upright.","Drive up explosively and press the bar overhead.","Split your feet front and back and catch with locked arms.","Bring your feet back together and lower the bar with control."],"img":"opengym/1538.webp","gif":null,"ext":1},{"id":"1539","n":"barbell split jump","bp":"upper legs","eq":"barbell","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","calves","core"],"st":["Rest a light bar on your upper back and take a split stance.","Lower into a shallow lunge.","Jump explosively and switch your legs in the air.","Land softly in the opposite split stance.","Keep your torso upright and continue alternating."],"img":"opengym/1539.webp","gif":null,"ext":1},{"id":"1540","n":"barbell squat to shoulder press","bp":"full body","eq":"barbell","tg":"quads","mg":"shoulders","sm":["shoulders","glutes","triceps","core"],"st":["Hold the barbell at your upper chest with your elbows slightly forward and feet shoulder-width apart.","Squat down until your thighs are about parallel to the floor, keeping your chest up.","Drive up through your heels and use that momentum to press the bar overhead.","Lock out the press with the bar over your mid-foot, then lower it back to your chest.","Keep your core braced the whole time and avoid arching your lower back."],"img":"opengym/1540.webp","gif":null,"ext":1},{"id":"1541","n":"barbell squat to upright row (thighs)","bp":"upper legs","eq":"barbell","tg":"quads","mg":"glutes","sm":["glutes","shoulders","trapezius","hamstrings"],"st":["Stand with feet shoulder-width apart, holding the barbell in front of your thighs with an overhand grip.","Push your hips back and squat down, letting the bar slide down to your knees.","Drive up through your heels to stand tall.","As you rise, pull the bar up close to your body until your elbows reach shoulder height.","Lower the bar under control and go straight into the next squat."],"img":"opengym/1541.webp","gif":null,"ext":1},{"id":"1542","n":"barbell stiff leg deadlift on bench","bp":"upper legs","eq":"barbell","tg":"hamstrings","mg":"glutes","sm":["glutes","lower back","grip muscles"],"st":["Stand on a sturdy bench holding a barbell at thigh level, feet hip-width apart.","Keep your knees almost straight and push your hips back.","Lower the bar toward your toes with a flat back as far as your hamstrings allow.","Pause briefly, then squeeze your glutes to stand back up.","Keep the bar close to your legs and stay in control throughout."],"img":"opengym/1542.webp","gif":null,"ext":1},{"id":"1543","n":"barbell stiff legged deadlift","bp":"upper legs","eq":"barbell","tg":"hamstrings","mg":"glutes","sm":["glutes","lower back","grip muscles"],"st":["Stand holding a barbell in front of your thighs, feet hip-width apart.","Keep a slight bend in your knees and push your hips back.","Lower the bar along your legs until you feel a deep stretch in your hamstrings.","Keep your back flat and your chest proud the whole way.","Drive your hips forward to return to standing."],"img":"opengym/1543.webp","gif":null,"ext":1},{"id":"1544","n":"barbell wide stance stiff leg deadlift","bp":"upper legs","eq":"barbell","tg":"hamstrings","mg":"glutes","sm":["glutes","adductors","lower back","grip muscles"],"st":["Take a wide stance, toes slightly out, with the barbell held in front of your thighs.","Keep your knees nearly straight and push your hips back.","Lower the bar between your legs while keeping your back flat.","Stop when you feel a strong stretch in the hamstrings and inner thighs.","Squeeze your glutes to rise back to standing."],"img":"opengym/1544.webp","gif":null,"ext":1},{"id":"1546","n":"bodyweight wall squat","bp":"upper legs","eq":"body weight","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","calves"],"st":["Lean your back against a wall with your feet about a step in front of you.","Slide down until your thighs are roughly parallel to the floor.","Keep your knees in line with your toes and your back flat on the wall.","Press through your heels to slide back up.","Repeat for the planned number of reps."],"img":"opengym/1546.webp","gif":null,"ext":1},{"id":"1547","n":"cable standing leg curl","bp":"upper legs","eq":"cable","tg":"hamstrings","mg":"calves","sm":["calves","glutes"],"st":["Attach an ankle cuff to a low pulley and strap it around one ankle.","Stand facing the machine and hold on for balance, with the working leg slightly behind you.","Bend your knee and curl your heel toward your glutes.","Squeeze at the top without swinging your torso.","Lower slowly, finish your reps, then switch legs."],"img":"opengym/1547.webp","gif":null,"ext":1},{"id":"1549","n":"double leg butt kick","bp":"cardio","eq":"body weight","tg":"cardiovascular system","mg":"hamstrings","sm":["hamstrings","quadriceps","calves"],"st":["Stand tall with your feet hip-width apart and arms relaxed.","Jump up off both feet.","Kick both heels up toward your glutes while you are in the air.","Land softly on the balls of your feet with slightly bent knees.","Go straight into the next jump at a steady rhythm."],"img":"opengym/1549.webp","gif":null,"ext":1},{"id":"1550","n":"dumbbell bench one leg squat","bp":"upper legs","eq":"dumbbell","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","core","calves"],"st":["Hold a dumbbell in each hand and stand a step in front of a bench, facing away from it.","Rest the top of one foot on the bench behind you.","Lower your back knee toward the floor by bending your front leg.","Keep your front knee over your toes and your chest up.","Push through your front heel to stand, then switch legs after your reps."],"img":"opengym/1550.webp","gif":null,"ext":1},{"id":"1551","n":"dumbbell decline bench lunge","bp":"upper legs","eq":"dumbbell","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","calves","core"],"st":["Hold a dumbbell in each hand and stand facing away from a decline bench.","Place the top of one foot on the bench behind you.","Lower your hips straight down until your front thigh is about parallel to the floor.","Keep your torso upright and your front knee tracking over your toes.","Push through your front foot to rise, then switch legs after your reps."],"img":"opengym/1551.webp","gif":null,"ext":1},{"id":"1552","n":"dumbbell jumping squat","bp":"upper legs","eq":"dumbbell","tg":"quads","mg":"glutes","sm":["glutes","calves","hamstrings"],"st":["Stand with feet shoulder-width apart, holding a dumbbell in each hand at your sides.","Squat down until your thighs are about parallel to the floor.","Explode upward and jump as high as you can.","Land softly on the balls of your feet and sink straight into the next squat.","Keep your chest up and your knees tracking your toes."],"img":"opengym/1552.webp","gif":null,"ext":1},{"id":"1553","n":"dumbbell lateral lunge with bicep curl","bp":"full body","eq":"dumbbell","tg":"glutes","mg":"quadriceps","sm":["quadriceps","adductors","biceps","hamstrings"],"st":["Stand tall holding a dumbbell in each hand with your palms facing forward.","Take a big step to the side and sit back into that hip, keeping the other leg straight.","Curl both dumbbells up as you lower into the lunge.","Push off your bent leg to return to the middle while lowering the weights.","Alternate sides or finish all reps on one side before switching."],"img":"opengym/1553.webp","gif":null,"ext":1},{"id":"1554","n":"dumbbell split jump","bp":"upper legs","eq":"dumbbell","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","calves"],"st":["Hold a dumbbell in each hand and step into a lunge position.","Lower until both knees are bent at about 90 degrees.","Explode upward and swap your leg positions in the air.","Land softly in a lunge with the opposite leg forward.","Keep your torso upright and move fluidly from rep to rep."],"img":"opengym/1554.webp","gif":null,"ext":1},{"id":"1555","n":"dumbbell squat v. 2","bp":"upper legs","eq":"dumbbell","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","calves","core"],"st":["Stand with feet shoulder-width apart, holding a dumbbell in each hand at your sides.","Push your hips back and bend your knees to lower down.","Go until your thighs are parallel to the floor or a bit lower.","Keep your chest up and your heels planted.","Press through your feet to stand back up."],"img":"opengym/1555.webp","gif":null,"ext":1},{"id":"1556","n":"dumbbell stiff leg deadlift on bench","bp":"upper legs","eq":"dumbbell","tg":"hamstrings","mg":"glutes","sm":["glutes","lower back","grip muscles"],"st":["Stand on a sturdy bench holding a dumbbell in each hand in front of your thighs.","Keep your knees nearly straight and push your hips back.","Lower the dumbbells down your legs and below the bench level with a flat back.","Pause when you feel a deep hamstring stretch.","Squeeze your glutes to return to standing."],"img":"opengym/1556.webp","gif":null,"ext":1},{"id":"1557","n":"dumbbell walking lunges","bp":"upper legs","eq":"dumbbell","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","calves","core"],"st":["Hold a dumbbell in each hand at your sides and stand tall.","Step forward with one leg and lower until both knees are bent at about 90 degrees.","Keep your torso upright and your front knee over your ankle.","Push off your back foot and step through into a lunge with the other leg.","Continue walking forward, alternating legs."],"img":"opengym/1557.webp","gif":null,"ext":1},{"id":"1558","n":"dumbbell wall squat","bp":"upper legs","eq":"dumbbell","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","calves"],"st":["Hold a dumbbell in each hand and lean your back against a wall.","Walk your feet forward so your knees stay over your ankles when you squat.","Slide down until your thighs are about parallel to the floor.","Keep your back flat against the wall.","Press through your heels to slide back up."],"img":"opengym/1558.webp","gif":null,"ext":1},{"id":"1561","n":"exercise ball seated quad stretch","bp":"upper legs","eq":"stability ball","tg":"quads","mg":"hip flexors","sm":["hip flexors"],"st":["Sit on the edge of a stability ball with your torso upright.","Hold on to something steady for balance if needed.","Bend one knee and bring your heel toward your glutes, holding your ankle.","Keep your knees close together and your hips square.","Hold for 20-30 seconds, then switch legs."],"img":"opengym/1561.webp","gif":null,"ext":1},{"id":"1562","n":"exercise ball wall squat","bp":"upper legs","eq":"stability ball","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","calves"],"st":["Place a stability ball between your lower back and a wall.","Walk your feet forward about a step and stand shoulder-width apart.","Bend your knees and let the ball roll down your back as you squat.","Lower until your thighs are about parallel to the floor.","Press through your heels to rise back up."],"img":"opengym/1562.webp","gif":null,"ext":1},{"id":"1563","n":"front back leg raises","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"hip flexors","sm":["hip flexors","hamstrings","core"],"st":["Stand tall next to a wall or support and hold on with one hand.","Swing your outside leg forward with a straight knee.","Swing it back behind you, squeezing your glute.","Keep your torso upright and avoid arching your lower back.","Do all reps on one side, then turn around and switch legs."],"img":"opengym/1563.webp","gif":null,"ext":1},{"id":"1565","n":"kettlebell dead clean","bp":"full body","eq":"kettlebell","tg":"glutes","mg":"hamstrings","sm":["hamstrings","upper back","shoulders","grip muscles"],"st":["Stand over a kettlebell with feet hip-width apart and hinge down to grab the handle.","Brace your core and keep your back flat.","Drive your hips forward and pull the bell up close to your body.","Rotate your hand around the handle and catch the bell at your shoulder.","Lower it back to the floor under control and reset before the next rep."],"img":"opengym/1565.webp","gif":null,"ext":1},{"id":"1566","n":"kettlebell one arm overhead squat (thighs)","bp":"upper legs","eq":"kettlebell","tg":"quads","mg":"shoulders","sm":["shoulders","core","glutes","triceps"],"st":["Press a kettlebell overhead with one arm and lock out your elbow.","Stand with feet shoulder-width apart and keep your ribs down.","Squat down with your chest up while keeping the bell stable over your shoulder.","Go as low as you can with good control.","Drive up through your heels, then switch arms after your reps."],"img":"opengym/1566.webp","gif":null,"ext":1},{"id":"1567","n":"kettlebell open palm clean","bp":"full body","eq":"kettlebell","tg":"glutes","mg":"hamstrings","sm":["hamstrings","shoulders","upper back","forearms"],"st":["Stand with feet shoulder-width apart and a kettlebell on the floor in front of you.","Hinge down and grab the handle with one hand.","Hike the bell back, then drive your hips forward to pull it up.","Keep your hand open and guide the bell to rest at your shoulder.","Lower it back with control and repeat, then switch sides."],"img":"opengym/1567.webp","gif":null,"ext":1},{"id":"1568","n":"kettlebell one arm swing","bp":"full body","eq":"kettlebell","tg":"glutes","mg":"hamstrings","sm":["hamstrings","lower back","shoulders","core"],"st":["Stand with feet slightly wider than shoulders and hold a kettlebell with one hand.","Hinge at the hips and swing the bell back between your legs.","Snap your hips forward and let the bell float up to chest height.","Keep your arm relaxed and your back flat.","Let the bell fall back and hinge again, then switch hands after your reps."],"img":"opengym/1568.webp","gif":null,"ext":1},{"id":"1569","n":"kettlebell one legged deadlift","bp":"upper legs","eq":"kettlebell","tg":"hamstrings","mg":"glutes","sm":["glutes","lower back","core","grip muscles"],"st":["Hold a kettlebell in one hand and stand on the opposite leg with a soft knee.","Hinge forward at the hip and extend your free leg straight back.","Lower the bell toward the floor while keeping your back flat.","Stop when your torso is about parallel to the floor.","Squeeze your glute to return upright, then switch legs."],"img":"opengym/1569.webp","gif":null,"ext":1},{"id":"1570","n":"knee tuck jump","bp":"full body","eq":"body weight","tg":"quads","mg":"hip flexors","sm":["hip flexors","calves","core"],"st":["Stand with feet shoulder-width apart and arms ready.","Dip into a quarter squat and swing your arms back.","Jump explosively and tuck both knees toward your chest.","Extend your legs again before landing.","Land softly on bent knees and reset before the next jump."],"img":"opengym/1570.webp","gif":null,"ext":1},{"id":"1571","n":"lever one leg extension","bp":"upper legs","eq":"leverage machine","tg":"quads","mg":"hip flexors","sm":["hip flexors"],"st":["Sit on the machine and adjust the pad so it rests on your lower shin.","Set one foot under the pad and keep the other foot on the floor or footrest.","Extend your working leg until it is almost straight.","Squeeze your quad at the top.","Lower slowly, finish your reps, then switch legs."],"img":"opengym/1571.webp","gif":null,"ext":1},{"id":"1572","n":"lever seated one leg wide squat","bp":"upper legs","eq":"leverage machine","tg":"quads","mg":"glutes","sm":["glutes","adductors","hamstrings"],"st":["Sit in the machine with your back against the pad and shoulders under the supports.","Place one foot wide on the platform and keep the other leg off the load.","Lower by bending your working knee as far as is comfortable.","Keep your knee tracking over your toes.","Press back up, then switch legs after your reps."],"img":"opengym/1572.webp","gif":null,"ext":1},{"id":"1573","n":"lever seated one leg squat","bp":"upper legs","eq":"leverage machine","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","calves"],"st":["Sit in the machine with your back against the pad and shoulders under the supports.","Place one foot on the platform at about shoulder width.","Lower under control by bending your knee.","Keep your heel flat and your knee in line with your toes.","Press back up, then switch legs after your reps."],"img":"opengym/1573.webp","gif":null,"ext":1},{"id":"1574","n":"lever seated wide squat","bp":"upper legs","eq":"leverage machine","tg":"quads","mg":"glutes","sm":["glutes","adductors","hamstrings"],"st":["Sit in the machine with your back against the pad and shoulders under the supports.","Set both feet wide on the platform with toes slightly out.","Lower by bending your knees until your thighs are about parallel.","Keep your knees pointing in the same direction as your toes.","Press through your heels to stand back up."],"img":"opengym/1574.webp","gif":null,"ext":1},{"id":"1575","n":"sled 45° narrow stance leg press","bp":"upper legs","eq":"sled machine","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","calves"],"st":["Sit in the sled with your back flat against the pad and feet close together on the platform.","Release the safety handles.","Lower the sled by bending your knees toward your chest.","Stop before your lower back lifts off the pad.","Press through your heels to extend your legs without locking the knees."],"img":"opengym/1575.webp","gif":null,"ext":1},{"id":"1577","n":"lying hip flexor","bp":"upper legs","eq":"body weight","tg":"hip flexors","mg":"quadriceps","sm":["quadriceps","groin"],"st":["Lie on your back near the edge of a bench or bed.","Hug one knee to your chest.","Let the other leg hang off the edge with the knee relaxed.","Keep your lower back pressed down and breathe slowly.","Hold for 20-30 seconds, then switch legs."],"img":"opengym/1577.webp","gif":null,"ext":1},{"id":"1578","n":"one leg quarter squat","bp":"upper legs","eq":"body weight","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","calves","core"],"st":["Stand on one leg with the other foot lifted slightly off the floor.","Extend your arms in front for balance.","Bend your knee and sink down about a quarter of the way.","Keep your knee in line with your toes and your chest up.","Stand back up, then switch legs after your reps."],"img":"opengym/1578.webp","gif":null,"ext":1},{"id":"1579","n":"sled one leg hack squat","bp":"upper legs","eq":"sled machine","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","calves"],"st":["Position yourself in the hack squat sled with your back and shoulders against the pads.","Place one foot in the middle of the platform and keep the other foot off.","Release the safety and lower by bending your working knee.","Go as deep as you can with control.","Press up through your heel, then switch legs after your reps."],"img":"opengym/1579.webp","gif":null,"ext":1},{"id":"1580","n":"prisoner squat","bp":"upper legs","eq":"body weight","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","core","calves"],"st":["Stand with feet shoulder-width apart and place your hands behind your head.","Pull your elbows back and keep your chest up.","Push your hips back and bend your knees to lower down.","Go until your thighs are about parallel to the floor.","Drive through your heels to stand back up."],"img":"opengym/1580.webp","gif":null,"ext":1},{"id":"1581","n":"bodyweight rear lunge","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","calves"],"st":["Stand tall with your feet hip-width apart.","Step one foot back and lower until both knees are bent at about 90 degrees.","Keep your torso upright and your front heel planted.","Push through your front foot to return to standing.","Alternate legs or finish all reps on one side first."],"img":"opengym/1581.webp","gif":null,"ext":1},{"id":"1583","n":"sled reverse hack squat","bp":"upper legs","eq":"sled machine","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","calves"],"st":["Face the pad of the hack squat sled with your chest against it and feet on the platform.","Hold the handles and release the safety.","Lower by bending your knees and pushing your hips back.","Keep your chest pressed against the pad.","Drive through your heels to stand back up."],"img":"opengym/1583.webp","gif":null,"ext":1},{"id":"1584","n":"rocket jump","bp":"upper legs","eq":"body weight","tg":"quads","mg":"glutes","sm":["glutes","calves","hamstrings"],"st":["Stand with feet shoulder-width apart.","Squat down while swinging your arms back.","Explode upward and reach both arms overhead as you jump.","Extend your whole body like a rocket.","Land softly on bent knees and reset before the next jump."],"img":"opengym/1584.webp","gif":null,"ext":1},{"id":"1586","n":"lever seated one leg curl","bp":"upper legs","eq":"leverage machine","tg":"hamstrings","mg":"calves","sm":["calves"],"st":["Sit on the machine with your back against the pad and adjust the leg pad above your heel.","Place one leg under the pad and rest the other foot on the footrest.","Curl your heel down and back as far as you can.","Squeeze your hamstring at the bottom.","Return slowly, then switch legs after your reps."],"img":"opengym/1586.webp","gif":null,"ext":1},{"id":"1588","n":"side to side box shuffle","bp":"cardio","eq":"body weight","tg":"cardiovascular system","mg":"calves","sm":["calves","quadriceps","glutes"],"st":["Stand next to a low box or step on one side.","Place the foot closest to it on top.","Hop across, landing the other foot on the box as the first foot goes down.","Keep your steps light and quick.","Continue shuffling side to side at a steady pace."],"img":"opengym/1588.webp","gif":null,"ext":1},{"id":"1589","n":"single leg butt kick","bp":"cardio","eq":"body weight","tg":"hamstrings","mg":"quadriceps","sm":["quadriceps","calves","core"],"st":["Stand on one leg with the other foot lifted.","Hop lightly on your standing foot.","Kick your free heel toward your glutes each hop.","Land softly on the ball of your foot.","Complete your reps, then switch legs."],"img":"opengym/1589.webp","gif":null,"ext":1},{"id":"1590","n":"lever lying single leg curl","bp":"upper legs","eq":"leverage machine","tg":"hamstrings","mg":"calves","sm":["calves"],"st":["Lie face down on the machine and place one leg under the pad above your heel.","Hold the handles and keep your hips pressed down.","Curl your heel up toward your glutes.","Squeeze your hamstring at the top.","Lower slowly, then switch legs after your reps."],"img":"opengym/1590.webp","gif":null,"ext":1},{"id":"1591","n":"single leg push off","bp":"upper legs","eq":"body weight","tg":"quads","mg":"glutes","sm":["glutes","calves","hamstrings"],"st":["Stand in front of a low step with one foot planted on it.","Lean slightly forward and keep your core tight.","Push off the step explosively with that leg and drive your opposite knee up.","Land softly on the same foot.","Complete your reps, then switch legs."],"img":"opengym/1591.webp","gif":null,"ext":1},{"id":"1592","n":"single leg stride jump","bp":"upper legs","eq":"body weight","tg":"quads","mg":"glutes","sm":["glutes","calves","hamstrings"],"st":["Stand on one leg with a slight knee bend.","Push off and leap forward as far as you can.","Land on the opposite leg and absorb the impact with a soft knee.","Hold the landing for a moment to stay balanced.","Repeat, alternating legs or staying on one side."],"img":"opengym/1592.webp","gif":null,"ext":1},{"id":"1593","n":"sit squat","bp":"upper legs","eq":"body weight","tg":"quads","mg":"glutes","sm":["glutes","hamstrings"],"st":["Stand in front of a chair or bench with feet shoulder-width apart.","Push your hips back and lower yourself toward the seat.","Lightly touch the seat without relaxing completely.","Keep your chest up and your knees over your toes.","Press through your heels to stand back up."],"img":"opengym/1593.webp","gif":null,"ext":1},{"id":"1594","n":"smith frankenstein squat","bp":"upper legs","eq":"smith machine","tg":"quads","mg":"glutes","sm":["glutes","core","shoulders","hamstrings"],"st":["Set the bar at upper chest height and rest it on your front shoulders.","Extend your arms straight forward, like a zombie, to keep the bar in place.","Unrack the bar and step into a stable stance.","Squat down with your chest up and your torso upright.","Drive through your heels to stand and rerack when finished."],"img":"opengym/1594.webp","gif":null,"ext":1},{"id":"1595","n":"smith front squat","bp":"upper legs","eq":"smith machine","tg":"quads","mg":"glutes","sm":["glutes","core","hamstrings","upper back"],"st":["Set the bar at shoulder height and rest it on the front of your shoulders with elbows up.","Unrack it and step your feet slightly forward.","Squat down until your thighs are about parallel to the floor.","Keep your elbows high and your chest up.","Press through your heels to stand and rerack when done."],"img":"opengym/1595.webp","gif":null,"ext":1},{"id":"1596","n":"smith squat to bench","bp":"upper legs","eq":"smith machine","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","core"],"st":["Place a bench behind you under the smith bar.","Rest the bar on your upper back and unrack it.","Sit your hips back and lower until you touch the bench lightly.","Keep your chest up and your knees tracking your toes.","Drive through your heels to stand and rerack when finished."],"img":"opengym/1596.webp","gif":null,"ext":1},{"id":"1597","n":"smith stiff legged deadlift","bp":"upper legs","eq":"smith machine","tg":"hamstrings","mg":"glutes","sm":["glutes","lower back","grip muscles"],"st":["Stand close to the smith bar with feet hip-width apart and grip the bar overhand.","Unrack it and keep your knees nearly straight.","Push your hips back and slide the bar down your legs.","Lower until you feel a deep stretch in your hamstrings.","Squeeze your glutes to stand tall."],"img":"opengym/1597.webp","gif":null,"ext":1},{"id":"1598","n":"smith zercher squat","bp":"upper legs","eq":"smith machine","tg":"quads","mg":"glutes","sm":["glutes","core","biceps","upper back"],"st":["Set the bar at waist height and hook your elbows under it with your arms crossed.","Unrack and stand with feet shoulder-width apart.","Squat down while keeping your chest up and the bar close to your body.","Go until your thighs are about parallel.","Press through your heels to stand and rerack when done."],"img":"opengym/1598.webp","gif":null,"ext":1},{"id":"1600","n":"standing long jump","bp":"upper legs","eq":"body weight","tg":"quads","mg":"glutes","sm":["glutes","calves","hamstrings"],"st":["Stand with feet shoulder-width apart at a clear starting line.","Swing your arms back and bend your knees.","Swing your arms forward and jump as far as you can.","Land on both feet with your knees bent to absorb the impact.","Reset and repeat."],"img":"opengym/1600.webp","gif":null,"ext":1},{"id":"1601","n":"standing straight leg hamstring contract relax on exercise ball","bp":"upper legs","eq":"stability ball","tg":"hamstrings","mg":"calves","sm":["calves","lower back"],"st":["Stand and rest one heel on a stability ball in front of you with your knee straight.","Hinge forward at the hips until you feel a stretch in the back of the thigh.","Gently press your heel into the ball for about 5 seconds, then relax.","Lean a little deeper into the stretch.","Hold for 20-30 seconds, then switch legs."],"img":"opengym/1601.webp","gif":null,"ext":1},{"id":"1602","n":"transverse step up","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","calves"],"st":["Stand sideways next to a bench or step.","Place the inside foot fully on top.","Drive through that heel and step up until your leg is straight.","Bring your other foot up to meet it.","Step back down with control, finish your reps, then switch sides."],"img":"opengym/1602.webp","gif":null,"ext":1},{"id":"1603","n":"weighted exercise ball wall squat","bp":"upper legs","eq":"weighted","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","calves"],"st":["Place a stability ball between your lower back and a wall.","Hold your weight at chest level or at your sides.","Step your feet forward and squat as the ball rolls down your back.","Lower until your thighs are about parallel to the floor.","Press through your heels to rise back up."],"img":"opengym/1603.webp","gif":null,"ext":1},{"id":"1605","n":"cable triceps pushdown (sz bar)","bp":"upper arms","eq":"cable","tg":"triceps","mg":"forearms","sm":["forearms"],"st":["Attach an SZ bar to a high pulley and grip it with your hands shoulder-width apart.","Pin your elbows to your sides.","Push the bar down until your arms are fully straight.","Squeeze your triceps for a moment.","Let the bar rise slowly until your forearms are just above parallel."],"img":"opengym/1605.webp","gif":null,"ext":1},{"id":"1606","n":"cable reverse grip triceps pushdown (sz bar)","bp":"upper arms","eq":"cable","tg":"triceps","mg":"forearms","sm":["forearms","wrist extensors"],"st":["Attach an SZ bar to a high pulley and grip it palms up with hands shoulder-width apart.","Keep your elbows tucked at your sides.","Push the bar down until your arms are straight.","Squeeze your triceps at the bottom.","Return slowly without letting your elbows drift forward."],"img":"opengym/1606.webp","gif":null,"ext":1},{"id":"1607","n":"cable biceps curl (sz bar)","bp":"upper arms","eq":"cable","tg":"biceps","mg":"brachialis","sm":["brachialis","forearms"],"st":["Attach an SZ bar to a low pulley and grip it with an underhand grip.","Stand tall with your elbows at your sides.","Curl the bar up toward your shoulders.","Squeeze your biceps at the top.","Lower slowly and avoid swinging your body."],"img":"opengym/1607.webp","gif":null,"ext":1},{"id":"1608","n":"cable standing reverse curl (sz bar)","bp":"upper arms","eq":"cable","tg":"biceps","mg":"brachialis","sm":["brachialis","forearms"],"st":["Attach an SZ bar to a low pulley and grip it overhand with your hands shoulder-width apart.","Stand tall with your elbows pinned to your sides.","Curl the bar up while keeping your wrists straight.","Pause at the top.","Lower slowly and keep your torso still."],"img":"opengym/1608.webp","gif":null,"ext":1},{"id":"1609","n":"cable one arm side triceps pushdown","bp":"upper arms","eq":"cable","tg":"triceps","mg":"forearms","sm":["forearms"],"st":["Attach a handle to a high pulley and stand sideways to the machine.","Grip the handle with the arm closest to the stack and keep your elbow at your side.","Push the handle down until your arm is straight.","Squeeze your triceps at the bottom.","Return slowly, finish your reps, then switch arms."],"img":"opengym/1609.webp","gif":null,"ext":1},{"id":"1610","n":"barbell behind back finger curl","bp":"lower arms","eq":"barbell","tg":"forearms","mg":"wrist flexors","sm":["wrist flexors","grip muscles"],"st":["Stand holding a barbell behind your back with an overhand grip, arms straight.","Let the bar roll down to your fingertips.","Curl your fingers closed and lift the bar back into your palms.","Curl your wrists up a little at the top.","Lower with control and repeat."],"img":"opengym/1610.webp","gif":null,"ext":1},{"id":"1611","n":"dumbbell behind back finger curl","bp":"lower arms","eq":"dumbbell","tg":"forearms","mg":"wrist flexors","sm":["wrist flexors","grip muscles","hands"],"st":["Stand tall with a light dumbbell held in one hand behind your back.","Let the dumbbell roll down until it rests on your fingertips.","Close your fingers and curl the weight back into your palm.","Keep your wrist still and your arm close to your body.","Lower under control and repeat, then switch hands."],"img":"opengym/1611.webp","gif":null,"ext":1},{"id":"1612","n":"swimmer hips","bp":"back","eq":"body weight","tg":"spine","mg":"glutes","sm":["glutes","hamstrings","rhomboids","shoulders"],"st":["Lie face down with your arms extended overhead and your legs straight.","Lift your chest slightly and brace your glutes.","Raise one arm and the opposite leg a few inches.","Switch sides in a controlled flutter.","Keep your neck neutral and breathe steadily."],"img":"opengym/1612.webp","gif":null,"ext":1},{"id":"1681","n":"dumbbell two arm seated hammer curl on exercise ball","bp":"upper arms","eq":"dumbbell","tg":"biceps","mg":"brachialis","sm":["brachialis","forearms","core"],"st":["Sit upright on a stability ball with a dumbbell in each hand, palms facing in.","Plant your feet wide for balance and keep your elbows by your sides.","Curl both dumbbells up toward your shoulders without turning your wrists.","Squeeze at the top, then lower slowly to full arm extension.","Keep your chest tall and avoid swinging your torso."],"img":"opengym/1681.webp","gif":null,"ext":1},{"id":"1692","n":"sagittal plane lunge with overhead medicine ball press","bp":"upper legs","eq":"medicine ball","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","shoulders","triceps","core"],"st":["Hold a medicine ball at chest height and stand tall.","Step forward into a lunge and lower your back knee toward the floor.","Press the ball overhead as you rise.","Lower the ball and step back to the start.","Alternate legs for the planned reps."],"img":"opengym/1692.webp","gif":null,"ext":1},{"id":"1693","n":"medicine ball single leg deadlift","bp":"upper legs","eq":"medicine ball","tg":"hamstrings","mg":"glutes","sm":["glutes","lower back","core","ankles"],"st":["Hold a medicine ball at your chest and stand on one leg with a soft knee.","Hinge at the hips while your free leg extends behind you.","Lower the ball toward the floor with a flat back.","Squeeze your glute to return to standing.","Finish all reps, then switch legs."],"img":"opengym/1693.webp","gif":null,"ext":1},{"id":"1694","n":"dumbbell overhead side lunge","bp":"upper legs","eq":"dumbbell","tg":"glutes","mg":"quadriceps","sm":["quadriceps","adductors","shoulders","core"],"st":["Hold one dumbbell overhead with both hands or one hand and stand tall.","Step out wide to one side and sit back into the hips.","Keep your chest tall and your arm locked out overhead.","Push through the bent leg to return to the middle.","Alternate sides for the planned reps."],"img":"opengym/1694.webp","gif":null,"ext":1},{"id":"1695","n":"stability ball single leg squat","bp":"upper legs","eq":"stability ball","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","core","ankles"],"st":["Place a stability ball between your lower back and a wall.","Lift one foot and balance on the other leg.","Lower into a squat while the ball rolls down the wall.","Press through your heel to stand back up.","Complete the reps, then switch legs."],"img":"opengym/1695.webp","gif":null,"ext":1},{"id":"1696","n":"transverse plane dumbbell lunge","bp":"upper legs","eq":"dumbbell","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","adductors","core"],"st":["Hold a dumbbell in each hand and stand tall.","Step diagonally back or across your body into a lunge.","Lower until both knees are bent, keeping your chest upright.","Push through the front foot to return to the start.","Alternate sides for the planned reps."],"img":"opengym/1696.webp","gif":null,"ext":1},{"id":"1697","n":"medicine ball reverse wood chop squat","bp":"waist","eq":"medicine ball","tg":"obliques","mg":"abdominals","sm":["abdominals","quadriceps","glutes","shoulders"],"st":["Hold a medicine ball overhead to one side and stand with your feet shoulder width apart.","Squat down while chopping the ball diagonally across your body.","Rotate your torso and bring the ball toward the opposite knee.","Stand up as you return the ball overhead.","Alternate sides each set."],"img":"opengym/1697.webp","gif":null,"ext":1},{"id":"1698","n":"forward hops","bp":"upper legs","eq":"body weight","tg":"quads","mg":"calves","sm":["calves","glutes","hamstrings","ankles"],"st":["Stand on both feet with your knees slightly bent.","Swing your arms and hop forward a short distance.","Land softly on the balls of your feet.","Reset your posture and hop again.","Keep your hops controlled and your chest tall."],"img":"opengym/1698.webp","gif":null,"ext":1},{"id":"1699","n":"medicine ball rotational throw","bp":"waist","eq":"medicine ball","tg":"obliques","mg":"abdominals","sm":["abdominals","shoulders","glutes","hip flexors"],"st":["Stand sideways to a wall holding a medicine ball at your hip.","Rotate away from the wall and load your back hip.","Explosively rotate and throw the ball into the wall.","Catch it on the rebound and repeat.","Switch sides after the planned reps."],"img":"opengym/1699.webp","gif":null,"ext":1},{"id":"1702","n":"single leg foot touch","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"hamstrings","sm":["hamstrings","quadriceps","core","ankles"],"st":["Stand on one leg with a soft knee.","Hinge at the hips and reach down toward your foot or the floor.","Keep your back flat and your free leg extended behind you.","Return to standing by squeezing your glute.","Finish all reps, then switch legs."],"img":"opengym/1702.webp","gif":null,"ext":1},{"id":"1703","n":"single leg transverse bend","bp":"upper legs","eq":"body weight","tg":"hamstrings","mg":"glutes","sm":["glutes","obliques","core","ankles"],"st":["Stand on one leg with a soft knee.","Hinge forward at the hips and reach across your body.","Rotate your torso slightly as you reach.","Return to standing with control.","Complete the reps, then switch legs."],"img":"opengym/1703.webp","gif":null,"ext":1},{"id":"1704","n":"medicine ball single leg wood chop","bp":"waist","eq":"medicine ball","tg":"obliques","mg":"glutes","sm":["glutes","shoulders","core"],"st":["Stand on one leg holding a medicine ball overhead to one side.","Chop the ball diagonally down across your body.","Rotate your torso and pivot your standing foot.","Return the ball overhead with control.","Complete the reps, then switch legs."],"img":"opengym/1704.webp","gif":null,"ext":1},{"id":"1706","n":"stability ball front plank","bp":"waist","eq":"stability ball","tg":"abs","mg":"core","sm":["core","shoulders","glutes"],"st":["Kneel behind a stability ball and place your forearms on it.","Walk your feet back until your body forms a straight line from head to heels.","Brace your abs and squeeze your glutes.","Keep your neck neutral and your hips from sagging or rising.","Hold for 20-40 seconds, then lower to the floor."],"img":"opengym/1706.webp","gif":null,"ext":1},{"id":"1711","n":"assisted oblique glute minimus and medius stretch","bp":"upper legs","eq":"assisted","tg":"abductors","mg":"obliques","sm":["obliques","glutes","hip flexors"],"st":["Lie on your back or side while your partner supports your top leg.","Have your partner gently guide the leg across your body while you stay relaxed.","Keep your shoulders relaxed and your breathing slow and steady.","Hold for 20-30 seconds without bouncing.","Release gently and repeat, switching sides if the stretch is one-sided."],"img":"opengym/1711.webp","gif":null,"ext":1},{"id":"1715","n":"assisted oblique and latissimus dorsi stretch on stability ball","bp":"back","eq":"assisted","tg":"lats","mg":"obliques","sm":["obliques","core","shoulders"],"st":["Lie sideways over a stability ball with your hips supported and one arm reaching overhead.","Let your partner gently guide your reaching arm further while you roll slightly over the ball.","Keep your shoulders relaxed and your breathing slow and steady.","Hold for 20-30 seconds without bouncing.","Release gently and repeat, switching sides if the stretch is one-sided."],"img":"opengym/1715.webp","gif":null,"ext":1},{"id":"1762","n":"single leg squat with support (pistol)","bp":"upper legs","eq":"body weight","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","core","calves"],"st":["Stand next to a sturdy support and hold it with one or both hands.","Lift one leg out in front of you and balance on the other.","Sit your hips back and bend your knee, lowering as far as you can control.","Keep your heel down and your knee tracking over your toes.","Press through your foot to stand, using the support only as needed, then switch legs."],"img":"opengym/1762.webp","gif":null,"ext":1},{"id":"1776","n":"lying single straight leg hip extension","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"hamstrings","sm":["hamstrings","lower back","core"],"st":["Lie face down with your legs straight and your forehead on your hands.","Tighten your abs and glutes.","Raise one straight leg a few inches off the floor.","Pause briefly at the top without arching your lower back.","Lower under control and repeat, then switch legs."],"img":"opengym/1776.webp","gif":null,"ext":1},{"id":"1777","n":"above head chest stretch","bp":"chest","eq":"body weight","tg":"pectorals","mg":"shoulders","sm":["shoulders","upper chest"],"st":["Stand tall and interlace your fingers, then raise your arms overhead.","Press your arms slightly back and lift your chest without arching your lower back.","Keep your shoulders relaxed and your breathing slow and steady.","Hold for 20-30 seconds without bouncing.","Release gently and repeat, switching sides if the stretch is one-sided."],"img":"opengym/1777.webp","gif":null,"ext":1},{"id":"1778","n":"assisted standing chest stretch","bp":"chest","eq":"assisted","tg":"pectorals","mg":"shoulders","sm":["shoulders","upper chest"],"st":["Stand tall with your arms out to the sides and your hands at shoulder height or slightly lower.","Have your partner hold your wrists and slowly pull your arms back until you feel a stretch across your chest.","Keep your shoulders relaxed and your breathing slow and steady.","Hold for 20-30 seconds without bouncing.","Release gently and repeat, switching sides if the stretch is one-sided."],"img":"opengym/1778.webp","gif":null,"ext":1},{"id":"1779","n":"assisted seated chest stretch","bp":"chest","eq":"assisted","tg":"pectorals","mg":"shoulders","sm":["shoulders","upper chest"],"st":["Sit upright on a bench or chair with your hands behind your head or arms out wide.","Have your partner stand behind you and gently draw your elbows or wrists back.","Keep your shoulders relaxed and your breathing slow and steady.","Hold for 20-30 seconds without bouncing.","Release gently and repeat, switching sides if the stretch is one-sided."],"img":"opengym/1779.webp","gif":null,"ext":1},{"id":"1780","n":"bent arm chest stretch","bp":"chest","eq":"body weight","tg":"pectorals","mg":"shoulders","sm":["shoulders","upper chest"],"st":["Stand beside a wall or doorframe and place your forearm on it with your elbow bent to 90 degrees.","Step forward and turn your body away until you feel the stretch across your chest.","Keep your shoulders relaxed and your breathing slow and steady.","Hold for 20-30 seconds without bouncing.","Release gently and repeat, switching sides if the stretch is one-sided."],"img":"opengym/1780.webp","gif":null,"ext":1},{"id":"1781","n":"corner wall chest stretch","bp":"chest","eq":"body weight","tg":"pectorals","mg":"shoulders","sm":["shoulders","upper chest"],"st":["Stand facing a wall corner and place a forearm on each wall at about shoulder height.","Step one foot forward and lean your chest into the corner until you feel a stretch.","Keep your shoulders relaxed and your breathing slow and steady.","Hold for 20-30 seconds without bouncing.","Release gently and repeat, switching sides if the stretch is one-sided."],"img":"opengym/1781.webp","gif":null,"ext":1},{"id":"1782","n":"reverse chest stretch","bp":"chest","eq":"body weight","tg":"pectorals","mg":"shoulders","sm":["shoulders","upper chest"],"st":["Stand tall and clasp your hands behind your back with straight arms.","Lift your hands up and away from your body while opening your chest.","Keep your shoulders relaxed and your breathing slow and steady.","Hold for 20-30 seconds without bouncing.","Release gently and repeat, switching sides if the stretch is one-sided."],"img":"opengym/1782.webp","gif":null,"ext":1},{"id":"1783","n":"standing chest stretch (with training wall bars)","bp":"chest","eq":"body weight","tg":"pectorals","mg":"shoulders","sm":["shoulders","upper chest"],"st":["Stand beside wall bars and grip a bar at about shoulder height with one hand.","Slowly turn your body away from the bars until you feel a stretch across your chest.","Keep your shoulders relaxed and your breathing slow and steady.","Hold for 20-30 seconds without bouncing.","Release gently and repeat, switching sides if the stretch is one-sided."],"img":"opengym/1783.webp","gif":null,"ext":1},{"id":"1784","n":"assisted pulling backs chest stretch","bp":"chest","eq":"assisted","tg":"pectorals","mg":"shoulders","sm":["shoulders","upper chest"],"st":["Stand or sit tall with your arms extended behind you at hip to shoulder height.","Have your partner hold your wrists and gently pull your arms back and slightly up.","Keep your shoulders relaxed and your breathing slow and steady.","Hold for 20-30 seconds without bouncing.","Release gently and repeat, switching sides if the stretch is one-sided."],"img":"opengym/1784.webp","gif":null,"ext":1},{"id":"1785","n":"kneeling chest stretch","bp":"chest","eq":"body weight","tg":"pectorals","mg":"shoulders","sm":["shoulders","upper chest","lats"],"st":["Kneel in front of a bench or chair and rest your forearms or hands on it.","Sit your hips back and let your chest drop toward the floor until you feel the stretch.","Keep your shoulders relaxed and your breathing slow and steady.","Hold for 20-30 seconds without bouncing.","Release gently and repeat, switching sides if the stretch is one-sided."],"img":"opengym/1785.webp","gif":null,"ext":1},{"id":"1786","n":"assisted trunk flex chest stretch","bp":"chest","eq":"assisted","tg":"pectorals","mg":"shoulders","sm":["shoulders","upper chest","core"],"st":["Sit or stand with your hands clasped behind your head and your elbows wide.","Have your partner pull your elbows back as you gently tilt your trunk forward.","Keep your shoulders relaxed and your breathing slow and steady.","Hold for 20-30 seconds without bouncing.","Release gently and repeat, switching sides if the stretch is one-sided."],"img":"opengym/1786.webp","gif":null,"ext":1},{"id":"1787","n":"straight arms backward chest stretch","bp":"chest","eq":"body weight","tg":"pectorals","mg":"shoulders","sm":["shoulders","upper chest"],"st":["Stand tall with your feet hip-width apart and reach both straight arms behind you.","Lift your arms slightly and open your chest without leaning back.","Keep your shoulders relaxed and your breathing slow and steady.","Hold for 20-30 seconds without bouncing.","Release gently and repeat, switching sides if the stretch is one-sided."],"img":"opengym/1787.webp","gif":null,"ext":1},{"id":"1788","n":"over head straight arm stretch","bp":"chest","eq":"body weight","tg":"pectorals","mg":"shoulders","sm":["shoulders","lats","triceps"],"st":["Stand tall and raise both straight arms overhead with your palms facing forward.","Reach up and slightly back, keeping your ribs down and your core lightly braced.","Keep your shoulders relaxed and your breathing slow and steady.","Hold for 20-30 seconds without bouncing.","Release gently and repeat, switching sides if the stretch is one-sided."],"img":"opengym/1788.webp","gif":null,"ext":1},{"id":"1789","n":"assisted straight arms lying stretch (chest)","bp":"chest","eq":"assisted","tg":"pectorals","mg":"shoulders","sm":["shoulders","lats","upper chest"],"st":["Lie on your back with your arms stretched out straight to the sides or overhead.","Have your partner gently press your wrists or arms down toward the floor.","Keep your shoulders relaxed and your breathing slow and steady.","Hold for 20-30 seconds without bouncing.","Release gently and repeat, switching sides if the stretch is one-sided."],"img":"opengym/1789.webp","gif":null,"ext":1},{"id":"1790","n":"assisted pulling arms in prone position chest stretch","bp":"chest","eq":"assisted","tg":"pectorals","mg":"shoulders","sm":["shoulders","upper chest"],"st":["Lie face down with your arms out to the sides and your forehead resting on the floor.","Have your partner hold your wrists and slowly lift your arms up and back.","Keep your shoulders relaxed and your breathing slow and steady.","Hold for 20-30 seconds without bouncing.","Release gently and repeat, switching sides if the stretch is one-sided."],"img":"opengym/1790.webp","gif":null,"ext":1},{"id":"1791","n":"trap and neck stretch","bp":"neck","eq":"body weight","tg":"levator scapulae","mg":"traps","sm":["traps","sternocleidomastoid","trapezius"],"st":["Sit or stand tall and hold the edge of the seat or a hand behind your back to anchor one shoulder down.","Tilt your head toward the opposite shoulder until you feel a stretch along your neck.","Keep your shoulders relaxed and your breathing slow and steady.","Hold for 20-30 seconds without bouncing.","Release gently and repeat, switching sides if the stretch is one-sided."],"img":"opengym/1791.webp","gif":null,"ext":1},{"id":"1792","n":"wrap around shoulder stretch","bp":"shoulders","eq":"body weight","tg":"delts","mg":"rear deltoids","sm":["rear deltoids","upper back","rhomboids"],"st":["Stand tall and bring one arm across your chest at shoulder height.","Hook it with your other forearm and pull it gently closer to your chest.","Keep your shoulders relaxed and your breathing slow and steady.","Hold for 20-30 seconds without bouncing.","Release gently and repeat, switching sides if the stretch is one-sided."],"img":"opengym/1792.webp","gif":null,"ext":1},{"id":"1793","n":"cross over shoulder stretch","bp":"shoulders","eq":"body weight","tg":"delts","mg":"rear deltoids","sm":["rear deltoids","upper back","rhomboids"],"st":["Stand tall and bring one straight arm across your chest.","Use your other hand to hold it just above the elbow and draw it closer to you.","Keep your shoulders relaxed and your breathing slow and steady.","Hold for 20-30 seconds without bouncing.","Release gently and repeat, switching sides if the stretch is one-sided."],"img":"opengym/1793.webp","gif":null,"ext":1},{"id":"1794","n":"reach forward upper back stretch","bp":"back","eq":"body weight","tg":"upper back","mg":"rhomboids","sm":["rhomboids","lats","shoulders"],"st":["Stand or sit and clasp your hands or hold a support in front of you at chest height.","Round your upper back and push your hands forward while dropping your head between your arms.","Keep your shoulders relaxed and your breathing slow and steady.","Hold for 20-30 seconds without bouncing.","Release gently and repeat, switching sides if the stretch is one-sided."],"img":"opengym/1794.webp","gif":null,"ext":1},{"id":"1795","n":"reaching upper back stretch","bp":"back","eq":"body weight","tg":"upper back","mg":"rhomboids","sm":["rhomboids","lats","shoulders"],"st":["Stand with your feet hip-width apart and reach both arms forward at chest height.","Round your upper back and spread your shoulder blades apart as you reach farther.","Keep your shoulders relaxed and your breathing slow and steady.","Hold for 20-30 seconds without bouncing.","Release gently and repeat, switching sides if the stretch is one-sided."],"img":"opengym/1795.webp","gif":null,"ext":1},{"id":"1796","n":"standing reach up back rotation stretch","bp":"back","eq":"body weight","tg":"lats","mg":"obliques","sm":["obliques","upper back","lower back"],"st":["Stand with your feet shoulder-width apart and reach one arm overhead.","Rotate your upper body gently away from the raised arm and reach up and over.","Keep your shoulders relaxed and your breathing slow and steady.","Hold for 20-30 seconds without bouncing.","Release gently and repeat, switching sides if the stretch is one-sided."],"img":"opengym/1796.webp","gif":null,"ext":1},{"id":"1797","n":"reach up back stretch","bp":"back","eq":"body weight","tg":"lats","mg":"upper back","sm":["upper back","shoulders","triceps"],"st":["Stand tall and reach both arms overhead with your palms facing each other.","Reach up and lean slightly back, keeping your lower back relaxed and your ribs down.","Keep your shoulders relaxed and your breathing slow and steady.","Hold for 20-30 seconds without bouncing.","Release gently and repeat, switching sides if the stretch is one-sided."],"img":"opengym/1797.webp","gif":null,"ext":1},{"id":"1798","n":"lying whole body stretch","bp":"full body","eq":"body weight","tg":"lats","mg":"core","sm":["core","shoulders","hamstrings"],"st":["Lie on your back with your arms overhead and your legs straight.","Reach your fingertips up and your toes down, as if you want to get taller.","Keep your shoulders relaxed and your breathing slow and steady.","Hold for 20-30 seconds without bouncing.","Release gently and repeat, switching sides if the stretch is one-sided."],"img":"opengym/1798.webp","gif":null,"ext":1},{"id":"1799","n":"two handed hang back stretch (with training wall bars)","bp":"back","eq":"body weight","tg":"lats","mg":"shoulders","sm":["shoulders","upper back","forearms"],"st":["Grip a wall bar overhead with both hands and walk your feet out slightly.","Let your body hang and sink your hips back, relaxing your upper back and shoulders.","Keep your shoulders relaxed and your breathing slow and steady.","Hold for 20-30 seconds without bouncing.","Release gently and repeat, switching sides if the stretch is one-sided."],"img":"opengym/1799.webp","gif":null,"ext":1},{"id":"1800","n":"cable suspension back stretch","bp":"back","eq":"cable","tg":"lats","mg":"upper back","sm":["upper back","shoulders","forearms"],"st":["Hold the cable attachment or handles with both hands at about chest height.","Lean back with straight arms and sit your hips back until you feel your back lengthen.","Keep your shoulders relaxed and your breathing slow and steady.","Hold for 20-30 seconds without bouncing.","Release gently and repeat, switching sides if the stretch is one-sided."],"img":"opengym/1800.webp","gif":null,"ext":1},{"id":"1801","n":"one arm lat stretch","bp":"back","eq":"body weight","tg":"lats","mg":"obliques","sm":["obliques","shoulders","triceps"],"st":["Stand tall and hold a pole or frame with one hand above head height.","Lean away from the arm and sit your hips slightly back to feel a stretch along your side.","Keep your shoulders relaxed and your breathing slow and steady.","Hold for 20-30 seconds without bouncing.","Release gently and repeat, switching sides if the stretch is one-sided."],"img":"opengym/1801.webp","gif":null,"ext":1},{"id":"1802","n":"side lat stretch","bp":"back","eq":"body weight","tg":"lats","mg":"obliques","sm":["obliques","shoulders","core"],"st":["Stand tall with your feet hip-width apart and raise one arm overhead.","Lean to the opposite side from the raised arm, reaching over without twisting.","Keep your shoulders relaxed and your breathing slow and steady.","Hold for 20-30 seconds without bouncing.","Release gently and repeat, switching sides if the stretch is one-sided."],"img":"opengym/1802.webp","gif":null,"ext":1},{"id":"1803","n":"sitting lower trunk extensor stretch","bp":"back","eq":"body weight","tg":"spine","mg":"lower back","sm":["lower back","glutes","hamstrings"],"st":["Sit on the floor or a bench with your knees slightly bent and your feet flat.","Round your back and fold your chest toward your thighs, letting your arms hang down.","Keep your shoulders relaxed and your breathing slow and steady.","Hold for 20-30 seconds without bouncing.","Release gently and repeat, switching sides if the stretch is one-sided."],"img":"opengym/1803.webp","gif":null,"ext":1},{"id":"1804","n":"seated lower trunk extensor lateral flexor stretch","bp":"back","eq":"body weight","tg":"spine","mg":"lower back","sm":["lower back","obliques","glutes"],"st":["Sit tall on a chair or bench with your feet flat on the floor.","Fold forward and reach your hands toward one foot, letting your trunk bend slightly to that side.","Keep your shoulders relaxed and your breathing slow and steady.","Hold for 20-30 seconds without bouncing.","Release gently and repeat, switching sides if the stretch is one-sided."],"img":"opengym/1804.webp","gif":null,"ext":1},{"id":"1805","n":"sitting bent over back stretch","bp":"back","eq":"body weight","tg":"spine","mg":"lower back","sm":["lower back","hamstrings","upper back"],"st":["Sit on a bench or chair with your feet flat and your knees apart.","Bend forward from your hips and let your head and arms hang between your knees.","Keep your shoulders relaxed and your breathing slow and steady.","Hold for 20-30 seconds without bouncing.","Release gently and repeat, switching sides if the stretch is one-sided."],"img":"opengym/1805.webp","gif":null,"ext":1},{"id":"1806","n":"sitting side reach stretch","bp":"back","eq":"body weight","tg":"lats","mg":"obliques","sm":["obliques","lower back","shoulders"],"st":["Sit tall with your legs crossed or your feet flat and place one hand on the floor beside you.","Reach your other arm up and over your head toward the side, lengthening along your flank.","Keep your shoulders relaxed and your breathing slow and steady.","Hold for 20-30 seconds without bouncing.","Release gently and repeat, switching sides if the stretch is one-sided."],"img":"opengym/1806.webp","gif":null,"ext":1},{"id":"1807","n":"sitting cross legged reach forward stretch","bp":"back","eq":"body weight","tg":"spine","mg":"lower back","sm":["lower back","glutes","hip flexors"],"st":["Sit on the floor with your legs crossed and your back tall.","Walk your hands forward along the floor and fold from your hips until you feel a stretch.","Keep your shoulders relaxed and your breathing slow and steady.","Hold for 20-30 seconds without bouncing.","Release gently and repeat, switching sides if the stretch is one-sided."],"img":"opengym/1807.webp","gif":null,"ext":1},{"id":"1808","n":"reclining lower trunk extensor stretch","bp":"upper legs","eq":"body weight","tg":"spine","mg":"lower back","sm":["lower back","glutes","hip flexors"],"st":["Lie on your back with your knees bent and your feet flat.","Draw both knees toward your chest and hold them with your hands.","Keep your shoulders relaxed and your breathing slow and steady.","Hold for 20-30 seconds without bouncing.","Release gently and repeat, switching sides if the stretch is one-sided."],"img":"opengym/1808.webp","gif":null,"ext":1},{"id":"1809","n":"sitting feet together reach forward stretch","bp":"back","eq":"body weight","tg":"spine","mg":"lower back","sm":["lower back","adductors","groin"],"st":["Sit on the floor with the soles of your feet together and your knees falling out.","Hold your feet and fold forward from your hips, keeping your spine long.","Keep your shoulders relaxed and your breathing slow and steady.","Hold for 20-30 seconds without bouncing.","Release gently and repeat, switching sides if the stretch is one-sided."],"img":"opengym/1809.webp","gif":null,"ext":1},{"id":"1810","n":"lying knee to chest stretch","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"lower back","sm":["lower back","hip flexors","hamstrings"],"st":["Lie on your back with both legs extended.","Pull one knee toward your chest with both hands while the other leg stays flat.","Keep your shoulders relaxed and your breathing slow and steady.","Hold for 20-30 seconds without bouncing.","Release gently and repeat, switching sides if the stretch is one-sided."],"img":"opengym/1810.webp","gif":null,"ext":1},{"id":"1811","n":"standing knee to chest stretch","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"lower back","sm":["lower back","hip flexors","core"],"st":["Stand tall, using a wall for balance if needed.","Lift one knee and pull it gently toward your chest with both hands.","Keep your shoulders relaxed and your breathing slow and steady.","Hold for 20-30 seconds without bouncing.","Release gently and repeat, switching sides if the stretch is one-sided."],"img":"opengym/1811.webp","gif":null,"ext":1},{"id":"1812","n":"kneeling back rotation stretch","bp":"back","eq":"body weight","tg":"spine","mg":"obliques","sm":["obliques","upper back","lower back"],"st":["Start on your hands and knees with your hands under your shoulders.","Place one hand behind your head and rotate your elbow up toward the ceiling.","Keep your shoulders relaxed and your breathing slow and steady.","Hold for 20-30 seconds without bouncing.","Release gently and repeat, switching sides if the stretch is one-sided."],"img":"opengym/1812.webp","gif":null,"ext":1},{"id":"1813","n":"standing back rotation stretch","bp":"back","eq":"body weight","tg":"spine","mg":"obliques","sm":["obliques","upper back","lower back"],"st":["Stand with your feet shoulder-width apart and your arms at chest height.","Rotate your upper body to one side, keeping your hips facing forward.","Keep your shoulders relaxed and your breathing slow and steady.","Hold for 20-30 seconds without bouncing.","Release gently and repeat, switching sides if the stretch is one-sided."],"img":"opengym/1813.webp","gif":null,"ext":1},{"id":"1814","n":"elbow flexor stretch","bp":"upper arms","eq":"body weight","tg":"biceps","mg":"brachialis","sm":["brachialis","forearms","shoulders"],"st":["Extend one arm in front of you with your palm facing up.","Use your other hand to gently press the fingers down and back until you feel the stretch.","Keep your shoulders relaxed and your breathing slow and steady.","Hold for 20-30 seconds without bouncing.","Release gently and repeat, switching sides if the stretch is one-sided."],"img":"opengym/1814.webp","gif":null,"ext":1},{"id":"1815","n":"forearm pronator stretch","bp":"lower arms","eq":"body weight","tg":"forearms","mg":"wrist flexors","sm":["wrist flexors","biceps"],"st":["Extend one arm in front of you with your elbow straight and palm down.","Use your other hand to rotate the palm outward until you feel a stretch along your forearm.","Keep your shoulders relaxed and your breathing slow and steady.","Hold for 20-30 seconds without bouncing.","Release gently and repeat, switching sides if the stretch is one-sided."],"img":"opengym/1815.webp","gif":null,"ext":1},{"id":"1816","n":"extension of arms in vertical stretch","bp":"upper arms","eq":"body weight","tg":"biceps","mg":"shoulders","sm":["shoulders","forearms","chest"],"st":["Stand tall with your arms raised straight overhead.","Press your arms back slightly and reach long through your fingertips.","Keep your shoulders relaxed and your breathing slow and steady.","Hold for 20-30 seconds without bouncing.","Release gently and repeat, switching sides if the stretch is one-sided."],"img":"opengym/1816.webp","gif":null,"ext":1},{"id":"1817","n":"arms stretch on a support","bp":"upper arms","eq":"body weight","tg":"biceps","mg":"forearms","sm":["forearms","shoulders","chest"],"st":["Place your hands or forearms on a bench or other stable support behind you.","Lower your body slightly and lean away until you feel a stretch in the front of your arms.","Keep your shoulders relaxed and your breathing slow and steady.","Hold for 20-30 seconds without bouncing.","Release gently and repeat, switching sides if the stretch is one-sided."],"img":"opengym/1817.webp","gif":null,"ext":1},{"id":"1818","n":"supination bar suspension stretch","bp":"upper arms","eq":"body weight","tg":"biceps","mg":"forearms","sm":["forearms","lats","shoulders"],"st":["Grip a pull-up bar with an underhand, shoulder-width grip.","Let your body hang with your arms straight, relaxing your shoulders downward.","Take as much weight through your legs as you need to stay comfortable.","Hold for 20-30 seconds without bouncing.","Release gently and repeat, switching sides if the stretch is one-sided."],"img":"opengym/1818.webp","gif":null,"ext":1},{"id":"1819","n":"suspension in pulley machine in supination stretch","bp":"upper arms","eq":"cable","tg":"biceps","mg":"forearms","sm":["forearms","lats","shoulders"],"st":["Hold a pulley handle with an underhand grip and your arm straight.","Lean your body weight back gently until you feel a stretch in the biceps and forearm.","Keep your shoulders relaxed and your breathing slow and steady.","Hold for 20-30 seconds without bouncing.","Release gently and repeat, switching sides if the stretch is one-sided."],"img":"opengym/1819.webp","gif":null,"ext":1},{"id":"1820","n":"ez bar preacher arms stretch","bp":"upper arms","eq":"ez barbell","tg":"biceps","mg":"brachialis","sm":["brachialis","forearms","shoulders"],"st":["Sit at a preacher bench and rest your upper arms on the pad, holding an EZ bar.","Let the bar lower under control until your arms are fully extended, using a light load.","Keep your shoulders relaxed and your breathing slow and steady.","Hold for 20-30 seconds without bouncing.","Release gently and repeat, switching sides if the stretch is one-sided."],"img":"opengym/1820.webp","gif":null,"ext":1},{"id":"1821","n":"elbow extension and supination pronation forearm stretch","bp":"lower arms","eq":"body weight","tg":"forearms","mg":"wrist flexors","sm":["wrist flexors","wrist extensors","biceps"],"st":["Extend one arm in front of you with your elbow straight.","Slowly rotate your palm up and down and let your other hand add gentle pressure at each end.","Keep your shoulders relaxed and your breathing slow and steady.","Hold for 20-30 seconds without bouncing.","Release gently and repeat, switching sides if the stretch is one-sided."],"img":"opengym/1821.webp","gif":null,"ext":1},{"id":"1822","n":"wrist ulnar deviator and extensor stretch","bp":"lower arms","eq":"body weight","tg":"forearms","mg":"wrist extensors","sm":["wrist extensors","hands"],"st":["Extend one arm in front of you with the palm down.","Bend the wrist so your fingers point down.","Gently tilt the hand toward the little finger side.","Use the other hand to apply light pressure.","Hold for 20-30 seconds, then switch arms."],"img":"opengym/1822.webp","gif":null,"ext":1},{"id":"1823","n":"wrist radial deviator and extensor stretch","bp":"lower arms","eq":"body weight","tg":"forearms","mg":"wrist extensors","sm":["wrist extensors","hands"],"st":["Extend one arm in front of you with the palm down.","Bend the wrist so your fingers point down.","Gently tilt the hand toward the thumb side.","Use the other hand to apply light pressure.","Hold for 20-30 seconds, then switch arms."],"img":"opengym/1823.webp","gif":null,"ext":1},{"id":"1824","n":"wrist radial deviator and flexor stretch","bp":"lower arms","eq":"body weight","tg":"forearms","mg":"wrist flexors","sm":["wrist flexors","hands"],"st":["Extend one arm in front of you with the palm up.","Use your other hand to pull the fingers back toward you.","Gently tilt the hand toward the thumb side.","Keep the elbow straight and your shoulder relaxed.","Hold for 20-30 seconds, then switch arms."],"img":"opengym/1824.webp","gif":null,"ext":1},{"id":"1825","n":"wrist ulnar deviator and flexor stretch","bp":"lower arms","eq":"body weight","tg":"forearms","mg":"wrist flexors","sm":["wrist flexors","hands"],"st":["Extend one arm in front of you with the palm up.","Use your other hand to pull the fingers back toward you.","Gently tilt the hand toward the little finger side.","Keep the elbow straight and your shoulder relaxed.","Hold for 20-30 seconds, then switch arms."],"img":"opengym/1825.webp","gif":null,"ext":1},{"id":"1826","n":"finger flexor stretch","bp":"lower arms","eq":"body weight","tg":"forearms","mg":"wrist flexors","sm":["wrist flexors","hands","grip muscles"],"st":["Extend one arm forward with your palm facing up or out.","Use your other hand to gently pull your fingers and palm back toward you.","Keep your shoulders relaxed and your breathing slow and steady.","Hold for 20-30 seconds without bouncing.","Release gently and repeat, switching sides if the stretch is one-sided."],"img":"opengym/1826.webp","gif":null,"ext":1},{"id":"1827","n":"finger extensor stretch","bp":"lower arms","eq":"body weight","tg":"forearms","mg":"wrist extensors","sm":["wrist extensors","hands"],"st":["Extend one arm forward with your palm facing down and your wrist relaxed.","Use your other hand to gently press your fingers and hand down toward you.","Keep your shoulders relaxed and your breathing slow and steady.","Hold for 20-30 seconds without bouncing.","Release gently and repeat, switching sides if the stretch is one-sided."],"img":"opengym/1827.webp","gif":null,"ext":1},{"id":"1828","n":"reaching down triceps stretch","bp":"upper arms","eq":"body weight","tg":"triceps","mg":"shoulders","sm":["shoulders","lats"],"st":["Raise one arm overhead, bend the elbow and drop your hand behind your head.","Use your other hand to press your elbow gently back and down.","Keep your shoulders relaxed and your breathing slow and steady.","Hold for 20-30 seconds without bouncing.","Release gently and repeat, switching sides if the stretch is one-sided."],"img":"opengym/1828.webp","gif":null,"ext":1},{"id":"1829","n":"triceps stretch against wall","bp":"upper arms","eq":"body weight","tg":"triceps","mg":"shoulders","sm":["shoulders","lats"],"st":["Stand next to a wall and place your bent elbow on it above head height.","Lean your body forward and down until you feel the stretch along the back of your upper arm.","Keep your shoulders relaxed and your breathing slow and steady.","Hold for 20-30 seconds without bouncing.","Release gently and repeat, switching sides if the stretch is one-sided."],"img":"opengym/1829.webp","gif":null,"ext":1},{"id":"1830","n":"elbow extensor anconeus stretch","bp":"lower arms","eq":"body weight","tg":"triceps","mg":"forearms","sm":["forearms","wrist extensors"],"st":["Extend one arm forward and bend the elbow fully with your palm down.","Use your other hand to press your forearm toward your upper arm, then rotate it gently.","Keep your shoulders relaxed and your breathing slow and steady.","Hold for 20-30 seconds without bouncing.","Release gently and repeat, switching sides if the stretch is one-sided."],"img":"opengym/1830.webp","gif":null,"ext":1},{"id":"1831","n":"rotating neck stretch","bp":"neck","eq":"body weight","tg":"levator scapulae","mg":"sternocleidomastoid","sm":["sternocleidomastoid","trapezius"],"st":["Sit or stand tall with your shoulders relaxed.","Slowly turn your head to one side, then to the other, as far as is comfortable.","Keep your chin level and avoid pushing into any pain.","Hold for 20-30 seconds without bouncing.","Release gently and repeat, switching sides if the stretch is one-sided."],"img":"opengym/1831.webp","gif":null,"ext":1},{"id":"1832","n":"diagonal flexion neck stretch","bp":"neck","eq":"body weight","tg":"levator scapulae","mg":"trapezius","sm":["trapezius","sternocleidomastoid"],"st":["Sit tall and gently turn your head about 45 degrees to one side.","Drop your chin diagonally toward your chest, using your hand for light added pressure.","Keep your shoulders relaxed and your breathing slow and steady.","Hold for 20-30 seconds without bouncing.","Release gently and repeat, switching sides if the stretch is one-sided."],"img":"opengym/1832.webp","gif":null,"ext":1},{"id":"1833","n":"neck extension stretch","bp":"neck","eq":"body weight","tg":"levator scapulae","mg":"sternocleidomastoid","sm":["sternocleidomastoid","trapezius"],"st":["Sit or stand tall with your shoulders relaxed.","Slowly tilt your head back to look up at the ceiling, keeping your jaw relaxed.","Keep your shoulders relaxed and your breathing slow and steady.","Hold for 20-30 seconds without bouncing.","Release gently and repeat, switching sides if the stretch is one-sided."],"img":"opengym/1833.webp","gif":null,"ext":1},{"id":"1834","n":"neck protraction stretch","bp":"neck","eq":"body weight","tg":"levator scapulae","mg":"sternocleidomastoid","sm":["sternocleidomastoid","upper back"],"st":["Sit or stand tall with your shoulders relaxed.","Keep your eyes level and slide your chin and head straight forward.","Stop when you feel a stretch at the back of the neck.","Hold for 20-30 seconds, breathing slowly.","Draw your head back to neutral and relax."],"img":"opengym/1834.webp","gif":null,"ext":1},{"id":"1835","n":"sitting neck flexion stretch","bp":"neck","eq":"body weight","tg":"levator scapulae","mg":"upper back","sm":["upper back","trapezius"],"st":["Sit tall on a chair with your hands resting in your lap.","Slowly lower your chin toward your chest.","Let the weight of your head do the work, without forcing it.","Hold for 20-30 seconds, breathing slowly.","Lift your head back to neutral slowly."],"img":"opengym/1835.webp","gif":null,"ext":1},{"id":"1836","n":"forward flexion neck stretch","bp":"neck","eq":"body weight","tg":"levator scapulae","mg":"trapezius","sm":["trapezius","upper back"],"st":["Stand or sit tall with your shoulders down.","Place both hands lightly behind your head.","Let your elbows drop forward and ease your head toward your chest.","Hold for 20-30 seconds, breathing slowly.","Release your hands and return to neutral."],"img":"opengym/1836.webp","gif":null,"ext":1},{"id":"1837","n":"neck extensor stretch","bp":"neck","eq":"body weight","tg":"levator scapulae","mg":"trapezius","sm":["trapezius","upper back"],"st":["Sit tall with your back straight.","Tuck your chin toward your chest.","Rest one hand on the back of your head and add very light pressure down.","Hold for 20-30 seconds, breathing slowly.","Remove your hand and lift your head slowly."],"img":"opengym/1837.webp","gif":null,"ext":1},{"id":"1838","n":"neck extensor and rotational stretch","bp":"neck","eq":"body weight","tg":"levator scapulae","mg":"trapezius","sm":["trapezius","upper back"],"st":["Sit tall with your shoulders relaxed.","Turn your head about 45 degrees to one side.","Rest a hand on the back of your head and ease your nose toward your armpit.","Hold for 20-30 seconds, breathing slowly.","Switch sides and repeat."],"img":"opengym/1838.webp","gif":null,"ext":1},{"id":"1839","n":"neck flexor stretch","bp":"neck","eq":"body weight","tg":"levator scapulae","mg":"sternocleidomastoid","sm":["sternocleidomastoid"],"st":["Sit or stand tall with your shoulders relaxed.","Lift your chin and slowly tilt your head back.","Keep the movement small and comfortable.","Hold for 20-30 seconds, breathing slowly.","Return your head to neutral."],"img":"opengym/1839.webp","gif":null,"ext":1},{"id":"1840","n":"neck flexor and rotational stretch","bp":"neck","eq":"body weight","tg":"levator scapulae","mg":"sternocleidomastoid","sm":["sternocleidomastoid"],"st":["Sit or stand tall with your shoulders down.","Turn your head slightly to one side.","Tilt your chin up and back until you feel a stretch along the front of your neck.","Hold for 20-30 seconds, breathing slowly.","Switch sides and repeat."],"img":"opengym/1840.webp","gif":null,"ext":1},{"id":"1841","n":"lying neck extensor stretch","bp":"neck","eq":"body weight","tg":"levator scapulae","mg":"upper back","sm":["upper back","trapezius"],"st":["Lie on your back with your knees bent.","Clasp your hands behind your head.","Gently lift your head and ease your chin toward your chest.","Hold for 20-30 seconds, breathing slowly.","Lower your head back down slowly."],"img":"opengym/1841.webp","gif":null,"ext":1},{"id":"1842","n":"lying neck extension stretch","bp":"neck","eq":"body weight","tg":"levator scapulae","mg":"sternocleidomastoid","sm":["sternocleidomastoid"],"st":["Lie on your back with your head near the edge of a bench or bed, shoulders supported.","Slowly let your head relax backward past the edge.","Support it with your hands if it feels heavy.","Hold for 20-30 seconds, breathing slowly.","Use your hands to lift your head back up carefully."],"img":"opengym/1842.webp","gif":null,"ext":1},{"id":"1843","n":"assisted rotating neck stretch","bp":"neck","eq":"body weight","tg":"levator scapulae","mg":"sternocleidomastoid","sm":["sternocleidomastoid","upper back"],"st":["Sit tall with your shoulders relaxed.","Turn your head to one side as far as is comfortable.","Place one hand on your chin and the other on the back of your head.","Add light pressure to deepen the turn.","Hold for 20-30 seconds, breathing slowly.","Switch sides and repeat."],"img":"opengym/1843.webp","gif":null,"ext":1},{"id":"1844","n":"extension and inclination neck stretch","bp":"neck","eq":"body weight","tg":"levator scapulae","mg":"sternocleidomastoid","sm":["sternocleidomastoid","trapezius"],"st":["Sit or stand tall with your shoulders down.","Tilt your head back slightly.","Lower one ear toward the same shoulder.","Hold for 20-30 seconds, breathing slowly.","Switch sides and repeat."],"img":"opengym/1844.webp","gif":null,"ext":1},{"id":"1845","n":"decline bent leg reverse crunch","bp":"waist","eq":"body weight","tg":"abs","mg":"lower abs","sm":["lower abs","hip flexors"],"st":["Lie on a decline bench and hold the top edge above your head.","Bring your knees up and bend them.","Curl your hips off the bench, drawing your knees toward your chest.","Lower back down slowly without swinging.","Keep the movement controlled throughout."],"img":"opengym/1845.webp","gif":null,"ext":1},{"id":"1848","n":"calves stretch static position","bp":"lower legs","eq":"body weight","tg":"calves","mg":"soleus","sm":["soleus","hamstrings","ankles"],"st":["Stand facing a wall with one foot back and your heel on the floor.","Keep your back leg straight and lean toward the wall.","Press your back heel down until you feel a stretch in the calf.","Keep your hips square and your toes pointing forward.","Hold for 20-30 seconds, then switch legs."],"img":"opengym/1848.webp","gif":null,"ext":1},{"id":"1850","n":"wrist flexor stretch","bp":"lower arms","eq":"body weight","tg":"forearms","mg":"wrist flexors","sm":["wrist flexors","hands"],"st":["Extend one arm in front of you with the palm up.","Use your other hand to pull the fingers back toward you.","Keep your elbow straight and your shoulder relaxed.","Feel the stretch along the inner forearm.","Hold for 20-30 seconds, then switch arms."],"img":"opengym/1850.webp","gif":null,"ext":1},{"id":"1851","n":"incline push press","bp":"chest","eq":"barbell","tg":"delts","mg":"triceps","sm":["triceps","upper chest","quadriceps"],"st":["Set an incline bench and hold the bar at your upper chest.","Dip slightly through your legs to start momentum.","Drive the bar up while pressing with your arms.","Lock out above your chest, then lower under control.","Keep your core braced and your lower back from arching."],"img":"opengym/1851.webp","gif":null,"ext":1},{"id":"1852","n":"leg raise hip lift","bp":"waist","eq":"body weight","tg":"abs","mg":"lower abs","sm":["lower abs","hip flexors","glutes"],"st":["Lie on your back with your legs straight and your hands by your sides.","Raise your legs to vertical.","Curl your hips up off the floor, pushing your feet toward the ceiling.","Lower your hips, then your legs, with control.","Keep your movement smooth and avoid swinging."],"img":"opengym/1852.webp","gif":null,"ext":1},{"id":"1854","n":"leg raise slightly bent knee","bp":"waist","eq":"body weight","tg":"abs","mg":"lower abs","sm":["lower abs","hip flexors"],"st":["Lie on your back with your hands under your hips.","Bend your knees slightly and lift your feet off the floor.","Raise your legs until they are above your hips.","Lower slowly without letting your back arch.","Keep your core tight throughout."],"img":"opengym/1854.webp","gif":null,"ext":1},{"id":"1855","n":"leg raise hip lift with head up","bp":"waist","eq":"body weight","tg":"abs","mg":"lower abs","sm":["lower abs","hip flexors"],"st":["Lie on your back with your legs straight and your hands by your sides.","Lift your head and shoulders slightly off the floor.","Raise your legs to vertical.","Push your hips a little off the floor, lifting your feet toward the ceiling.","Lower your hips and legs slowly with control."],"img":"opengym/1855.webp","gif":null,"ext":1},{"id":"1856","n":"lever lying leg raise (bent knee)","bp":"waist","eq":"leverage machine","tg":"abs","mg":"lower abs","sm":["lower abs","hip flexors"],"st":["Lie back on the machine and grip the handles.","Bend your knees and place your legs under the pads.","Curl your knees up toward your chest.","Pause briefly at the top.","Lower slowly until you feel tension, then repeat."],"img":"opengym/1856.webp","gif":null,"ext":1},{"id":"1857","n":"lever total abdominal crunch","bp":"waist","eq":"leverage machine","tg":"abs","mg":"obliques","sm":["obliques","hip flexors"],"st":["Adjust the seat and sit with your chest against the pad.","Hold the handles and set your feet firmly.","Curl your torso forward by contracting your abs.","Pause at the bottom.","Return slowly to the start without letting the weight drop."],"img":"opengym/1857.webp","gif":null,"ext":1},{"id":"1858","n":"lever decline sit up","bp":"waist","eq":"leverage machine","tg":"abs","mg":"hip flexors","sm":["hip flexors","obliques"],"st":["Lie back on the decline seat and hook your feet under the pads.","Cross your arms or hold the handles.","Curl your torso up toward your knees.","Squeeze your abs at the top.","Lower back slowly under control."],"img":"opengym/1858.webp","gif":null,"ext":1},{"id":"1859","n":"cable kneeling triceps extension v. 2","bp":"upper arms","eq":"cable","tg":"triceps","mg":"shoulders","sm":["shoulders","core"],"st":["Attach a rope or bar to a high pulley and kneel facing away.","Hold it overhead with your elbows bent behind your head.","Keep your upper arms still and straighten your elbows.","Squeeze your triceps at full extension.","Return slowly to the start."],"img":"opengym/1859.webp","gif":null,"ext":1},{"id":"1860","n":"hyperextension v. 2","bp":"back","eq":"body weight","tg":"spine","mg":"glutes","sm":["glutes","hamstrings"],"st":["Set the pad at hip level and hook your heels under the rollers.","Cross your arms over your chest and keep your body straight.","Bend forward at the hips with a flat back.","Lift your torso until it forms a straight line with your legs.","Do not overarch at the top, then lower with control."],"img":"opengym/1860.webp","gif":null,"ext":1},{"id":"1861","n":"cable curl with multipurpose v bar","bp":"upper arms","eq":"cable","tg":"biceps","mg":"brachialis","sm":["brachialis","forearms"],"st":["Attach a multipurpose V bar to a low pulley and grip it with palms up.","Stand tall with your elbows at your sides.","Curl the bar up toward your shoulders.","Squeeze your biceps at the top.","Lower slowly without letting your elbows drift."],"img":"opengym/1861.webp","gif":null,"ext":1},{"id":"1862","n":"lever cable shoulder press","bp":"shoulders","eq":"leverage machine","tg":"delts","mg":"triceps","sm":["triceps","upper chest"],"st":["Adjust the seat so the handles are at shoulder height.","Sit back with your feet flat and grip the handles.","Press upward until your arms are nearly straight.","Pause briefly at the top.","Lower slowly back to the start."],"img":"opengym/1862.webp","gif":null,"ext":1},{"id":"1863","n":"lever cable rear pulldown","bp":"back","eq":"leverage machine","tg":"lats","mg":"biceps","sm":["biceps","rhomboids","rear deltoids"],"st":["Adjust the seat and grip the handles overhead.","Sit tall with your chest up.","Pull the handles down, driving your elbows toward your sides.","Squeeze your shoulder blades together at the bottom.","Return slowly to full stretch."],"img":"opengym/1863.webp","gif":null,"ext":1},{"id":"1864","n":"extra decline sit up","bp":"waist","eq":"body weight","tg":"abs","mg":"hip flexors","sm":["hip flexors","obliques"],"st":["Set a decline bench to a steep angle and hook your feet under the pads.","Lie back and cross your arms over your chest.","Curl your torso up until you are sitting.","Squeeze your abs at the top.","Lower slowly back down."],"img":"opengym/1864.webp","gif":null,"ext":1},{"id":"1865","n":"hammer grip pull up on dip cage","bp":"back","eq":"body weight","tg":"lats","mg":"biceps","sm":["biceps","brachialis","forearms"],"st":["Grab the neutral grip handles with your palms facing each other.","Hang with your arms fully extended.","Pull your chest toward the handles by driving your elbows down.","Pause with your chin above the bars.","Lower slowly to a full hang."],"img":"opengym/1865.webp","gif":null,"ext":1},{"id":"1866","n":"wide grip pull up on dip cage","bp":"back","eq":"body weight","tg":"lats","mg":"biceps","sm":["biceps","rhomboids","forearms"],"st":["Grab the wide handles with your palms facing forward.","Hang with your arms fully extended.","Pull yourself up by driving your elbows down and back.","Pause when your chin clears the bar.","Lower slowly to a full hang."],"img":"opengym/1866.webp","gif":null,"ext":1},{"id":"1867","n":"lever seated hip adduction v. 2","bp":"upper legs","eq":"leverage machine","tg":"adductors","mg":"inner thighs","sm":["inner thighs","groin"],"st":["Sit on the machine with your back against the pad.","Place your legs against the pads, set wide.","Squeeze your legs together smoothly.","Pause for a moment when they meet.","Open slowly back to the start."],"img":"opengym/1867.webp","gif":null,"ext":1},{"id":"1868","n":"barbell low bar squat (with rack)","bp":"upper legs","eq":"barbell","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","lower back"],"st":["Set the bar in the rack and place it on your rear delts, below the traps.","Step back and set your feet shoulder width.","Lean forward slightly and sit your hips back and down.","Descend until your thighs are at least parallel.","Drive through your heels to stand, keeping your chest up."],"img":"opengym/1868.webp","gif":null,"ext":1},{"id":"1869","n":"lever seated hip abduction v. 2","bp":"upper legs","eq":"leverage machine","tg":"abductors","mg":"glutes","sm":["glutes"],"st":["Sit with your back against the pad and your legs inside the pads.","Hold the handles for stability.","Push your legs apart smoothly.","Pause at the widest point.","Return slowly without letting the weights crash."],"img":"opengym/1869.webp","gif":null,"ext":1},{"id":"1870","n":"lever lateral pulldown (plate loaded)","bp":"back","eq":"leverage machine","tg":"lats","mg":"biceps","sm":["biceps","rhomboids"],"st":["Adjust the seat and grip the handles overhead.","Sit tall with your chest up.","Pull down until the handles reach chest level.","Squeeze your shoulder blades together.","Return slowly to full stretch."],"img":"opengym/1870.webp","gif":null,"ext":1},{"id":"1871","n":"lever triceps dip (plate loaded)","bp":"upper arms","eq":"leverage machine","tg":"triceps","mg":"chest","sm":["chest","shoulders"],"st":["Sit upright and grip the handles beside you.","Set your elbows tight to your sides.","Press down until your arms are straight.","Squeeze your triceps.","Return slowly to the start."],"img":"opengym/1871.webp","gif":null,"ext":1},{"id":"1872","n":"lever preacher curl (plate loaded)","bp":"upper arms","eq":"leverage machine","tg":"biceps","mg":"brachialis","sm":["brachialis","forearms"],"st":["Adjust the seat so your upper arms rest on the pad.","Grip the handles with your palms up.","Curl up until your biceps are fully contracted.","Pause briefly.","Lower slowly until your arms are almost straight."],"img":"opengym/1872.webp","gif":null,"ext":1},{"id":"1873","n":"lever leg extension (plate loaded)","bp":"upper legs","eq":"leverage machine","tg":"quads","mg":"hip flexors","sm":["hip flexors"],"st":["Sit with your back against the pad and your shins behind the roller.","Hold the handles.","Extend your knees until your legs are straight.","Squeeze your quads at the top.","Lower slowly under control."],"img":"opengym/1873.webp","gif":null,"ext":1},{"id":"1874","n":"lever alternate leg extension (plate loaded)","bp":"upper legs","eq":"leverage machine","tg":"quads","mg":"hip flexors","sm":["hip flexors"],"st":["Sit with your back against the pad and your shins behind the rollers.","Hold the handles.","Extend one leg until it is straight.","Lower it slowly.","Repeat with the other leg and keep alternating."],"img":"opengym/1874.webp","gif":null,"ext":1},{"id":"1875","n":"lever squat (plate loaded)","bp":"upper legs","eq":"leverage machine","tg":"quads","mg":"glutes","sm":["glutes","hamstrings"],"st":["Step under the shoulder pads and set your feet shoulder width.","Release the safeties and stand tall.","Sit down and back until your thighs are parallel.","Drive through your heels to stand.","Keep your chest up and your knees tracking over your toes."],"img":"opengym/1875.webp","gif":null,"ext":1},{"id":"1876","n":"lever lateral raise (plate loaded)","bp":"shoulders","eq":"leverage machine","tg":"delts","mg":"trapezius","sm":["trapezius","rear deltoids"],"st":["Adjust the seat and place your arms against the pads.","Sit upright.","Raise your arms out to the sides until about shoulder height.","Pause at the top.","Lower slowly to the start."],"img":"opengym/1876.webp","gif":null,"ext":1},{"id":"1877","n":"standing hip out aductor stretch","bp":"upper legs","eq":"body weight","tg":"adductors","mg":"inner thighs","sm":["inner thighs","groin"],"st":["Stand tall with your feet wider than hip width.","Shift your weight onto one leg and bend that knee.","Keep the other leg straight, foot flat.","Push your hip out until you feel a stretch in the inner thigh.","Hold for 20-30 seconds, breathing slowly.","Switch sides and repeat."],"img":"opengym/1877.webp","gif":null,"ext":1},{"id":"1878","n":"standing leg cross abductor stretch","bp":"upper legs","eq":"body weight","tg":"abductors","mg":"glutes","sm":["glutes"],"st":["Stand tall, next to a wall if you need balance.","Cross one leg behind the other.","Lean your hips toward the side of your back leg.","Feel the stretch along the outer hip.","Hold for 20-30 seconds, breathing slowly.","Switch sides and repeat."],"img":"opengym/1878.webp","gif":null,"ext":1},{"id":"1879","n":"standing leg resting hip stretch","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"hip flexors","sm":["hip flexors","groin"],"st":["Stand facing a bench or step.","Place one heel on it with the knee slightly bent.","Keep your chest tall and hinge forward at the hips.","Feel the stretch in the hip and glute.","Hold for 20-30 seconds, breathing slowly.","Switch sides and repeat."],"img":"opengym/1879.webp","gif":null,"ext":1},{"id":"1880","n":"leaning abductor stretch","bp":"upper legs","eq":"body weight","tg":"abductors","mg":"glutes","sm":["glutes"],"st":["Stand next to a wall and lean on it with one hand.","Cross your outer leg behind the inner one.","Lean your hips toward the wall.","Keep both feet flat.","Hold for 20-30 seconds, breathing slowly.","Switch sides and repeat."],"img":"opengym/1880.webp","gif":null,"ext":1},{"id":"1881","n":"standing leg under abductor stretch","bp":"upper legs","eq":"body weight","tg":"abductors","mg":"glutes","sm":["glutes"],"st":["Stand tall near a support.","Pass one leg behind and under the other.","Push your hips gently to the side of the back leg.","Keep your torso upright.","Hold for 20-30 seconds, breathing slowly.","Switch sides and repeat."],"img":"opengym/1881.webp","gif":null,"ext":1},{"id":"1882","n":"lying abductor stretch","bp":"upper legs","eq":"body weight","tg":"abductors","mg":"glutes","sm":["glutes"],"st":["Lie on your back with your legs straight.","Bring one knee up and across your body.","Use the opposite hand to ease it toward the floor.","Keep your shoulders flat on the ground.","Hold for 20-30 seconds, breathing slowly.","Switch sides and repeat."],"img":"opengym/1882.webp","gif":null,"ext":1},{"id":"1883","n":"exercise ball lying abductor stretch","bp":"upper legs","eq":"stability ball","tg":"abductors","mg":"glutes","sm":["glutes"],"st":["Lie on your back with your calves resting on a stability ball.","Cross one ankle over the opposite knee.","Roll the ball gently to bring your legs toward your chest.","Feel the stretch in the outer hip.","Hold for 20-30 seconds, breathing slowly.","Switch sides and repeat."],"img":"opengym/1883.webp","gif":null,"ext":1},{"id":"1884","n":"lying leg hang abductor stretch","bp":"upper legs","eq":"body weight","tg":"abductors","mg":"glutes","sm":["glutes","hip flexors"],"st":["Lie on your back on a bench.","Cross one leg over your body and let it hang off the side.","Keep your shoulders flat.","Let gravity lower the leg slowly.","Hold for 20-30 seconds, breathing slowly.","Switch sides and repeat."],"img":"opengym/1884.webp","gif":null,"ext":1},{"id":"1885","n":"standing toe up achilles stretch","bp":"lower legs","eq":"body weight","tg":"calves","mg":"soleus","sm":["soleus","ankles"],"st":["Stand facing a wall with one foot forward.","Place the ball of the forward foot against the wall, heel on the floor.","Lean your hips toward the wall.","Feel the stretch in the calf and Achilles.","Hold for 20-30 seconds, breathing slowly.","Switch sides and repeat."],"img":"opengym/1885.webp","gif":null,"ext":1},{"id":"1886","n":"single heel drop achilles stretch","bp":"lower legs","eq":"body weight","tg":"calves","mg":"soleus","sm":["soleus","ankles"],"st":["Stand on a step with the ball of one foot on the edge.","Hold a rail for balance.","Lower your heel slowly below the step.","Keep the knee straight for the calf, then slightly bent for the soleus.","Hold for 20-30 seconds, breathing slowly.","Switch sides and repeat."],"img":"opengym/1886.webp","gif":null,"ext":1},{"id":"1887","n":"standing heel back achilles stretch","bp":"lower legs","eq":"body weight","tg":"calves","mg":"soleus","sm":["soleus"],"st":["Stand facing a wall and step one foot back.","Keep the back leg straight and the heel down.","Bend your front knee and lean forward.","Feel the stretch in the back calf.","Hold for 20-30 seconds, breathing slowly.","Switch sides and repeat."],"img":"opengym/1887.webp","gif":null,"ext":1},{"id":"1888","n":"standing achilles stretch","bp":"lower legs","eq":"body weight","tg":"calves","mg":"soleus","sm":["soleus","ankles"],"st":["Stand near a wall or support.","Step one foot back with the heel down.","Slightly bend the back knee to target the lower Achilles.","Keep your back foot pointing forward.","Hold for 20-30 seconds, breathing slowly.","Switch sides and repeat."],"img":"opengym/1888.webp","gif":null,"ext":1},{"id":"1889","n":"sitting toe pull achilles stretch","bp":"lower legs","eq":"body weight","tg":"calves","mg":"soleus","sm":["soleus","shins"],"st":["Sit on the floor with one leg straight.","Loop a towel around the ball of your foot or grip your toes.","Pull your toes toward your shin.","Keep your knee straight.","Hold for 20-30 seconds, breathing slowly.","Switch sides and repeat."],"img":"opengym/1889.webp","gif":null,"ext":1},{"id":"1890","n":"crouching heel back achilles stretch","bp":"lower legs","eq":"body weight","tg":"calves","mg":"soleus","sm":["soleus","ankles"],"st":["Crouch down with your hands on the floor for balance.","Extend one leg back with the heel down.","Press the heel toward the floor.","Keep your chest lifted.","Hold for 20-30 seconds, breathing slowly.","Switch sides and repeat."],"img":"opengym/1890.webp","gif":null,"ext":1},{"id":"1891","n":"toe squat stretch","bp":"lower legs","eq":"body weight","tg":"calves","mg":"feet","sm":["feet","ankles"],"st":["Kneel on a mat with your toes tucked under.","Sit back onto your heels slowly.","Rest your hands on your thighs.","Ease off if the stretch is too sharp.","Hold for 20-30 seconds, breathing slowly.","Release and shake out your feet."],"img":"opengym/1891.webp","gif":null,"ext":1},{"id":"1892","n":"kneeling heel down achilles stretch","bp":"lower legs","eq":"body weight","tg":"calves","mg":"soleus","sm":["soleus","ankles"],"st":["Kneel on one knee with the other foot forward.","Lean forward, keeping your front heel on the floor.","Press your front knee over your toes.","Feel the stretch behind the ankle.","Hold for 20-30 seconds, breathing slowly.","Switch sides and repeat."],"img":"opengym/1892.webp","gif":null,"ext":1},{"id":"1893","n":"squatting achilles stretch","bp":"lower legs","eq":"body weight","tg":"calves","mg":"soleus","sm":["soleus","ankles","hip flexors"],"st":["Stand with your feet shoulder width apart.","Sink into a deep squat with your heels down.","Hold on to a support if needed.","Gently shift your weight forward over your toes.","Hold for 20-30 seconds, breathing slowly.","Stand up slowly."],"img":"opengym/1893.webp","gif":null,"ext":1},{"id":"1894","n":"standing wide knees adductor stretch","bp":"upper legs","eq":"body weight","tg":"adductors","mg":"groin","sm":["groin","inner thighs","hamstrings"],"st":["Stand with your feet wide apart and toes pointing slightly out.","Bend your knees and place your hands on your thighs.","Shift your weight from side to side, sinking into the stretch.","Keep your chest tall and your back flat.","Hold for 20-30 seconds on each side."],"img":"opengym/1894.webp","gif":null,"ext":1},{"id":"1895","n":"standing rotational hip stretch","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"hip flexors","sm":["hip flexors","groin"],"st":["Stand tall near a support.","Cross one ankle over the opposite knee.","Sit your hips back as if sitting into a chair.","Feel the stretch in the hip of the crossed leg.","Hold for 20-30 seconds, breathing slowly.","Switch sides and repeat."],"img":"opengym/1895.webp","gif":null,"ext":1},{"id":"1896","n":"standing raised leg hip adductor stretch","bp":"upper legs","eq":"body weight","tg":"adductors","mg":"groin","sm":["groin","inner thighs","hamstrings"],"st":["Stand tall and place one foot on a bench or raised surface to the side.","Keep your standing leg straight and your toes forward.","Shift your weight toward the raised leg side until you feel a stretch.","Keep your chest upright and your hips square.","Hold for 20-30 seconds, then switch legs."],"img":"opengym/1896.webp","gif":null,"ext":1},{"id":"1897","n":"standing leg up adductor stretch","bp":"upper legs","eq":"body weight","tg":"adductors","mg":"inner thighs","sm":["inner thighs","groin"],"st":["Stand next to a bench or low support.","Place one foot on it with the leg out to the side.","Keep your hips square.","Shift your weight toward the raised leg.","Hold for 20-30 seconds, breathing slowly.","Switch sides and repeat."],"img":"opengym/1897.webp","gif":null,"ext":1},{"id":"1898","n":"kneeling leg out adductor stretch","bp":"upper legs","eq":"body weight","tg":"adductors","mg":"groin","sm":["groin","inner thighs","hamstrings"],"st":["Kneel on all fours with your knees under your hips.","Extend one leg out to the side with the foot flat.","Sit your hips back toward the opposite heel.","Keep your back straight and your extended leg straight.","Hold for 20-30 seconds, then switch legs."],"img":"opengym/1898.webp","gif":null,"ext":1},{"id":"1899","n":"side lunge adductor stretch","bp":"upper legs","eq":"body weight","tg":"adductors","mg":"inner thighs","sm":["inner thighs","groin","glutes"],"st":["Stand with your feet wide apart.","Shift your weight to one side and bend that knee.","Keep the other leg straight with the foot flat.","Keep your chest tall.","Hold for 20-30 seconds, breathing slowly.","Switch sides and repeat."],"img":"opengym/1899.webp","gif":null,"ext":1},{"id":"1900","n":"standing bent knee hip adductor stretch","bp":"upper legs","eq":"body weight","tg":"adductors","mg":"inner thighs","sm":["inner thighs","groin"],"st":["Stand with your feet wide.","Bend one knee and lower into that side.","Keep your other leg straight.","Push the bent knee gently out with your hand.","Hold for 20-30 seconds, breathing slowly.","Switch sides and repeat."],"img":"opengym/1900.webp","gif":null,"ext":1},{"id":"1901","n":"kneeling face down adductor stretch","bp":"upper legs","eq":"body weight","tg":"adductors","mg":"groin","sm":["groin","hip flexors"],"st":["Kneel on a mat, then lower your chest and forearms to the floor.","Slide your knees wide apart and sink your hips back toward your heels until you feel the inner thighs stretch.","Keep your breathing slow and stay relaxed, without bouncing.","Hold for 20-30 seconds, feeling a gentle pull rather than pain.","Release slowly and repeat, switching sides if the stretch is one sided."],"img":"opengym/1901.webp","gif":null,"ext":1},{"id":"1902","n":"sitting wide leg adductor stretch","bp":"upper legs","eq":"body weight","tg":"adductors","mg":"inner thighs","sm":["inner thighs","groin","hamstrings"],"st":["Sit on the floor with your legs spread wide.","Keep your knees pointing up.","Hinge forward from the hips with a long spine.","Walk your hands forward until you feel the stretch.","Hold for 20-30 seconds, breathing slowly.","Come up slowly."],"img":"opengym/1902.webp","gif":null,"ext":1},{"id":"1903","n":"hip abduction with flexion in front stretch","bp":"upper legs","eq":"body weight","tg":"abductors","mg":"glutes","sm":["glutes","hip flexors"],"st":["Sit on the floor with one leg bent in front of you.","Place the other leg to the side.","Lean your torso forward over the front shin.","Keep your hips grounded.","Hold for 20-30 seconds, breathing slowly.","Switch sides and repeat."],"img":"opengym/1903.webp","gif":null,"ext":1},{"id":"1904","n":"standing wide leg adductor stretch","bp":"upper legs","eq":"body weight","tg":"adductors","mg":"groin","sm":["groin","inner thighs"],"st":["Stand with your feet wide apart, toes pointing slightly out.","Shift your weight to one side and bend that knee while the other leg stays straight, and feel the inner thigh stretch.","Keep your chest up and the straight leg's foot flat on the floor.","Hold for 20-30 seconds, feeling a gentle pull rather than pain.","Release slowly and repeat, switching sides if the stretch is one sided."],"img":"opengym/1904.webp","gif":null,"ext":1},{"id":"1905","n":"lying leaning against the wall stretch","bp":"upper legs","eq":"body weight","tg":"adductors","mg":"inner thighs","sm":["inner thighs","hamstrings"],"st":["Lie on your back with your hips close to a wall.","Rest your legs straight up the wall.","Let your legs fall slowly out to the sides.","Relax and let gravity do the work.","Hold for 20-30 seconds, breathing slowly.","Bring your legs together to finish."],"img":"opengym/1905.webp","gif":null,"ext":1},{"id":"1906","n":"abduction of one leg flexion stretch","bp":"upper legs","eq":"body weight","tg":"adductors","mg":"groin","sm":["groin","hip flexors"],"st":["Lie on your back with your legs straight.","Bend one knee, let it fall out to the side and, if needed, ease it down with your hand until the inner thigh stretches.","Keep your lower back and the opposite hip flat on the floor.","Hold for 20-30 seconds, feeling a gentle pull rather than pain.","Release slowly and repeat, switching sides if the stretch is one sided."],"img":"opengym/1906.webp","gif":null,"ext":1},{"id":"1907","n":"assisted lying adductors stretch","bp":"upper legs","eq":"assisted","tg":"adductors","mg":"inner thighs","sm":["inner thighs","groin"],"st":["Lie on your back with your legs straight.","Have your partner lift one leg slightly and move it out to the side.","Keep your hips level.","Tell your partner to stop at a comfortable stretch.","Hold for 20-30 seconds, breathing slowly.","Switch sides and repeat."],"img":"opengym/1907.webp","gif":null,"ext":1},{"id":"1908","n":"standing toe down hamstring stretch","bp":"upper legs","eq":"body weight","tg":"hamstrings","mg":"calves","sm":["calves","lower back"],"st":["Stand with one heel on the floor in front of you.","Point your toes down.","Hinge forward from the hips with a flat back.","Keep the front leg nearly straight.","Hold for 20-30 seconds, breathing slowly.","Switch sides and repeat."],"img":"opengym/1908.webp","gif":null,"ext":1},{"id":"1909","n":"standing toe up hamstring stretch","bp":"upper legs","eq":"body weight","tg":"hamstrings","mg":"calves","sm":["calves","lower back"],"st":["Stand tall and step one foot forward, resting the heel on the floor with the toes pulled up.","Keep the front leg straight and the back knee slightly bent.","Hinge forward at the hips with a flat back until you feel a pull behind the thigh.","Keep your chest open and avoid rounding your spine.","Hold for 20-30 seconds, then switch sides."],"img":"opengym/1909.webp","gif":null,"ext":1},{"id":"1910","n":"standing leg up hamstring stretch","bp":"upper legs","eq":"body weight","tg":"hamstrings","mg":"calves","sm":["calves","lower back"],"st":["Stand facing a low support and place one heel on it with the leg straight.","Hinge forward from the hips with a long back until you feel the back of the thigh stretch.","Keep your toes pointing up and your standing knee soft.","Hold for 20-30 seconds, feeling a gentle pull rather than pain.","Release slowly and repeat, switching sides if the stretch is one sided."],"img":"opengym/1910.webp","gif":null,"ext":1},{"id":"1911","n":"raised leg knee flexor stretch","bp":"upper legs","eq":"body weight","tg":"hamstrings","mg":"calves","sm":["calves","glutes"],"st":["Place one heel on a low bench or step in front of you with the leg straight.","Stand tall with the standing knee soft.","Hinge forward from the hips, keeping your back flat, until you feel a stretch behind the raised thigh.","Keep your toes pointing up and breathe slowly.","Hold for 20-30 seconds, then switch sides."],"img":"opengym/1911.webp","gif":null,"ext":1},{"id":"1912","n":"standing high leg bent knee hamstring stretch","bp":"upper legs","eq":"body weight","tg":"hamstrings","mg":"glutes","sm":["glutes","calves"],"st":["Stand tall and place one heel on a high support with the knee slightly bent.","Lean your chest toward your thigh with a flat back until you feel the stretch behind the thigh.","Straighten the knee a little more as you get looser.","Hold for 20-30 seconds, feeling a gentle pull rather than pain.","Release slowly and repeat, switching sides if the stretch is one sided."],"img":"opengym/1912.webp","gif":null,"ext":1},{"id":"1913","n":"kneeling toe up hamstring stretch","bp":"upper legs","eq":"body weight","tg":"hamstrings","mg":"calves","sm":["calves","lower back"],"st":["Kneel on one knee and extend the other leg in front, heel on the floor and toes pulled up.","Place your hands on the floor or the front thigh for support.","Hinge forward at the hips with a flat back until you feel a pull behind the extended leg.","Keep the extended knee straight but not locked.","Hold for 20-30 seconds, then switch sides."],"img":"opengym/1913.webp","gif":null,"ext":1},{"id":"1914","n":"seated knee flexor and hip adductor stretch","bp":"upper legs","eq":"body weight","tg":"hamstrings","mg":"adductors","sm":["adductors","groin","lower back"],"st":["Sit on the floor with your legs spread wide and knees straight.","Sit tall with your toes pointing up.","Hinge forward from the hips, walking your hands out in front of you.","Stop when you feel a stretch along the inner thighs and backs of the legs.","Hold for 20-30 seconds, breathing slowly, then sit back up."],"img":"opengym/1914.webp","gif":null,"ext":1},{"id":"1915","n":"seated knee flexor stretch","bp":"upper legs","eq":"body weight","tg":"hamstrings","mg":"calves","sm":["calves","lower back"],"st":["Sit on the floor with one leg straight out in front of you.","Reach toward your toes with a long back until you feel the back of the thigh stretch.","Keep your knee straight but not locked, and avoid rounding your back too much.","Hold for 20-30 seconds, feeling a gentle pull rather than pain.","Release slowly and repeat, switching sides if the stretch is one sided."],"img":"opengym/1915.webp","gif":null,"ext":1},{"id":"1916","n":"standing reach down hamstring stretch","bp":"upper legs","eq":"body weight","tg":"hamstrings","mg":"calves","sm":["calves","lower back"],"st":["Stand with your feet hip width apart.","Hinge at the hips and reach your hands down toward your shins or toes until you feel the back of the thighs stretch.","Let your head and neck hang relaxed and keep a slight bend in the knees.","Hold for 20-30 seconds, feeling a gentle pull rather than pain.","Release slowly and repeat, switching sides if the stretch is one sided."],"img":"opengym/1916.webp","gif":null,"ext":1},{"id":"1917","n":"standing reach down hamstring crossed legs stretch","bp":"upper legs","eq":"body weight","tg":"hamstrings","mg":"calves","sm":["calves","glutes"],"st":["Stand tall and cross one foot over the other.","Hinge forward at the hips and reach toward the floor until the back of the thighs stretch.","Keep both legs fairly straight and let your head hang relaxed.","Hold for 20-30 seconds, feeling a gentle pull rather than pain.","Release slowly and repeat, switching sides if the stretch is one sided."],"img":"opengym/1917.webp","gif":null,"ext":1},{"id":"1918","n":"seated hip external rotator and hip extensor stretch","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"hip flexors","sm":["hip flexors","lower back"],"st":["Sit upright on the floor or a chair and cross one ankle over the opposite knee.","Gently press the raised knee down and lean your chest forward with a long back until the buttock stretches.","Keep your spine long instead of collapsing forward.","Hold for 20-30 seconds, feeling a gentle pull rather than pain.","Release slowly and repeat, switching sides if the stretch is one sided."],"img":"opengym/1918.webp","gif":null,"ext":1},{"id":"1919","n":"seated hip stretch with opposite leg from behind","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"hip flexors","sm":["hip flexors","hamstrings"],"st":["Sit on the floor with one leg bent in front of you and the other leg bent behind.","Lean your chest forward over the front shin until you feel the stretch deep in the hip and buttock.","Keep both sit bones as level as you can.","Hold for 20-30 seconds, feeling a gentle pull rather than pain.","Release slowly and repeat, switching sides if the stretch is one sided."],"img":"opengym/1919.webp","gif":null,"ext":1},{"id":"1920","n":"plantar flexion stretch","bp":"lower legs","eq":"body weight","tg":"calves","mg":"shins","sm":["shins","ankles","feet"],"st":["Sit on a chair or the floor with one leg extended.","Point your toes away from you as far as is comfortable.","Gently press the top of the foot with your hand for a little extra stretch.","Keep the movement slow and avoid forcing the ankle.","Hold for 20-30 seconds, then switch sides."],"img":"opengym/1920.webp","gif":null,"ext":1},{"id":"1921","n":"recumbent knee flexor stretch","bp":"upper legs","eq":"body weight","tg":"hamstrings","mg":"calves","sm":["calves","glutes"],"st":["Lie on your back with both legs straight.","Lift one leg toward the ceiling, holding behind the thigh or calf.","Keep the knee as straight as is comfortable and the other leg flat on the floor.","Gently draw the leg toward you until you feel a pull behind the thigh.","Hold for 20-30 seconds, then switch sides."],"img":"opengym/1921.webp","gif":null,"ext":1},{"id":"1922","n":"recumbent knee flexor stretch with towel","bp":"upper legs","eq":"body weight","tg":"hamstrings","mg":"calves","sm":["calves","glutes"],"st":["Lie on your back and loop a towel around the ball of one foot.","Raise that leg toward the ceiling, holding both ends of the towel.","Keep the knee nearly straight and the other leg flat on the floor.","Gently pull the towel until you feel a stretch behind the thigh.","Hold for 20-30 seconds, then switch sides."],"img":"opengym/1922.webp","gif":null,"ext":1},{"id":"1923","n":"assisted lying hamstring stretch","bp":"upper legs","eq":"assisted","tg":"hamstrings","mg":"calves","sm":["calves","glutes"],"st":["Lie on your back with your legs straight and relax completely.","Have a partner lift one leg by the heel, keeping the knee straight.","Tell your partner to stop when you feel a pull behind the thigh.","Keep your other leg and lower back flat on the floor.","Hold for 20-30 seconds, then switch legs."],"img":"opengym/1923.webp","gif":null,"ext":1},{"id":"1924","n":"standing toe up calf stretch","bp":"lower legs","eq":"body weight","tg":"calves","mg":"soleus","sm":["soleus","hamstrings"],"st":["Stand facing a wall or step and place the ball of one foot against it with the heel on the floor.","Keep the leg straight.","Lean your hips gently toward the wall until you feel a stretch in the calf.","Keep your heel down and your back tall.","Hold for 20-30 seconds, then switch sides."],"img":"opengym/1924.webp","gif":null,"ext":1},{"id":"1925","n":"single heel drop calf stretch","bp":"lower legs","eq":"body weight","tg":"calves","mg":"soleus","sm":["soleus","ankles"],"st":["Stand on the edge of a step with the ball of one foot on it and hold a rail for balance.","Slowly lower that heel below the step until you feel the calf stretch.","Keep the knee straight to hit the calf, then bend it slightly to reach deeper into the soleus.","Hold for 20-30 seconds, feeling a gentle pull rather than pain.","Release slowly and repeat, switching sides if the stretch is one sided."],"img":"opengym/1925.webp","gif":null,"ext":1},{"id":"1926","n":"plantar flexor and foot everter stretch","bp":"lower legs","eq":"body weight","tg":"calves","mg":"ankles","sm":["ankles","feet","shins"],"st":["Sit with one leg extended and hold the foot with your hand.","Point the foot down and turn the sole slightly outward.","Gently press the foot until you feel a stretch along the front and outer ankle.","Move slowly and stop at a mild stretch.","Hold for 20-30 seconds, then switch sides."],"img":"opengym/1926.webp","gif":null,"ext":1},{"id":"1927","n":"plantar flexor and foot inverter stretch","bp":"lower legs","eq":"body weight","tg":"calves","mg":"ankles","sm":["ankles","feet","shins"],"st":["Sit with one leg extended and hold the foot with your hand.","Point the foot down and turn the sole slightly inward.","Gently press the foot until you feel a stretch along the front and inner ankle.","Move slowly and stop at a mild stretch.","Hold for 20-30 seconds, then switch sides."],"img":"opengym/1927.webp","gif":null,"ext":1},{"id":"1928","n":"tibial flexion stretch on wall bar","bp":"lower legs","eq":"body weight","tg":"calves","mg":"shins","sm":["shins","ankles"],"st":["Stand facing the wall bars and place the front of one foot against a low bar.","Lean your body forward and press your heel toward the floor until the lower leg stretches.","Hold the bars with your hands to stay balanced.","Hold for 20-30 seconds, feeling a gentle pull rather than pain.","Release slowly and repeat, switching sides if the stretch is one sided."],"img":"opengym/1928.webp","gif":null,"ext":1},{"id":"1929","n":"tibial stretch with semi flexed knee","bp":"lower legs","eq":"body weight","tg":"calves","mg":"shins","sm":["shins","soleus","ankles"],"st":["Stand facing a wall with one foot back and the toes pressed against the wall or floor.","Bend the knee of the stretching leg slightly.","Shift your weight forward until you feel a stretch low in the calf.","Keep the heel on the floor.","Hold for 20-30 seconds, then switch sides."],"img":"opengym/1929.webp","gif":null,"ext":1},{"id":"1930","n":"crouching heel back calf stretch","bp":"lower legs","eq":"body weight","tg":"calves","mg":"soleus","sm":["soleus","ankles"],"st":["Crouch down with your feet flat and hands on the floor for balance.","Shift one heel backward and press it toward the floor.","Keep the other leg bent and supporting your weight.","Feel the stretch in the calf of the pressing leg.","Hold for 20-30 seconds, then switch sides."],"img":"opengym/1930.webp","gif":null,"ext":1},{"id":"1931","n":"hip and knee flexion squatting stretch","bp":"upper legs","eq":"body weight","tg":"quads","mg":"glutes","sm":["glutes","adductors","calves"],"st":["Stand with your feet a little wider than your shoulders and toes turned slightly out.","Sink down into a deep squat and press your elbows against your inner knees to open the hips.","Keep your heels on the floor and your chest tall.","Hold for 20-30 seconds, feeling a gentle pull rather than pain.","Release slowly and repeat, switching sides if the stretch is one sided."],"img":"opengym/1931.webp","gif":null,"ext":1},{"id":"1932","n":"assisted lying hip stretch in supine position","bp":"upper legs","eq":"assisted","tg":"glutes","mg":"hip flexors","sm":["hip flexors","lower back"],"st":["Lie on your back with your legs straight and relax.","Have a partner bring one knee slowly toward your chest.","Tell them to stop when you feel a stretch in the hip and buttock.","Keep the other leg flat on the floor.","Hold for 20-30 seconds, then switch legs."],"img":"opengym/1932.webp","gif":null,"ext":1},{"id":"1933","n":"seated knee up rotation stretch","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"obliques","sm":["obliques","lower back"],"st":["Sit on the floor with one leg straight and the other knee bent, foot flat on the floor.","Cross the bent leg over the straight one, and rotate your torso toward the raised knee, hugging it with the opposite arm.","Sit tall and twist from the middle of your back.","Hold for 20-30 seconds, feeling a gentle pull rather than pain.","Release slowly and repeat, switching sides if the stretch is one sided."],"img":"opengym/1933.webp","gif":null,"ext":1},{"id":"1934","n":"seated knee up extended rotation stretch","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"obliques","sm":["obliques","lower back"],"st":["Sit on the floor with one leg extended and the other knee bent and crossed over it.","Rotate your torso toward the bent knee, using the opposite elbow to guide it, until the hip stretches.","Keep your spine long and look over your back shoulder.","Hold for 20-30 seconds, feeling a gentle pull rather than pain.","Release slowly and repeat, switching sides if the stretch is one sided."],"img":"opengym/1934.webp","gif":null,"ext":1},{"id":"1935","n":"lying cross over knee pull up stretch","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"lower back","sm":["lower back","hip flexors"],"st":["Lie on your back with your knees bent.","Cross one ankle over the opposite knee.","Hold the knee of the lower leg or behind the thigh and pull it up toward your chest.","Keep your head and shoulders relaxed on the floor.","Hold for 20-30 seconds, then switch sides."],"img":"opengym/1935.webp","gif":null,"ext":1},{"id":"1936","n":"lying cross over knee pull down stretch","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"lower back","sm":["lower back","hip flexors"],"st":["Lie on your back with your knees bent.","Cross one ankle over the opposite knee.","Use your hand to guide the crossed knee gently down and across your body.","Keep your shoulders on the floor.","Hold for 20-30 seconds, then switch sides."],"img":"opengym/1936.webp","gif":null,"ext":1},{"id":"1937","n":"seated bent knee to chest buttock stretch","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"hip flexors","sm":["hip flexors","lower back"],"st":["Sit on the floor with your legs out in front.","Bend one knee, hold it with both hands and gently pull it toward your chest.","Keep your back tall and avoid rounding it as you pull.","Hold for 20-30 seconds, feeling a gentle pull rather than pain.","Release slowly and repeat, switching sides if the stretch is one sided."],"img":"opengym/1937.webp","gif":null,"ext":1},{"id":"1938","n":"seated hip stretch with slightly bent leg","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"hamstrings","sm":["hamstrings","hip flexors"],"st":["Sit on the floor with one leg slightly bent in front of you and the other leg folded comfortably.","Hinge forward from the hips with a long back until you feel the hip and buttock stretch.","Keep the knee of the front leg soft throughout.","Hold for 20-30 seconds, feeling a gentle pull rather than pain.","Release slowly and repeat, switching sides if the stretch is one sided."],"img":"opengym/1938.webp","gif":null,"ext":1},{"id":"1939","n":"recumbent hip external rotator and hip extensor stretch","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"lower back","sm":["lower back","hip flexors"],"st":["Lie on your back and bend both knees.","Bring one knee toward your chest and turn it slightly outward.","Hold the shin and ankle and draw the leg closer.","Keep your lower back resting on the floor.","Hold for 20-30 seconds, then switch sides."],"img":"opengym/1939.webp","gif":null,"ext":1},{"id":"1940","n":"sitting foot to chest buttocks stretch","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"lower back","sm":["lower back","hamstrings"],"st":["Sit on the floor with your back tall and legs extended.","Bend one knee and hold the foot and shin.","Pull the foot gently toward your chest while keeping your spine upright.","Feel the stretch deep in the buttock and hip.","Hold for 20-30 seconds, then switch sides."],"img":"opengym/1940.webp","gif":null,"ext":1},{"id":"1941","n":"standing hip adduction stretch","bp":"upper legs","eq":"body weight","tg":"abductors","mg":"glutes","sm":["glutes","obliques"],"st":["Stand tall and cross one leg behind the other, feet close together.","Lean your torso away from the back leg and push the hip out slightly until you feel the outer hip stretch.","Keep both feet flat on the floor.","Hold for 20-30 seconds, feeling a gentle pull rather than pain.","Release slowly and repeat, switching sides if the stretch is one sided."],"img":"opengym/1941.webp","gif":null,"ext":1},{"id":"1942","n":"standing iliotibial stretch","bp":"upper legs","eq":"body weight","tg":"abductors","mg":"glutes","sm":["glutes","obliques"],"st":["Stand next to a wall or support and cross your outer leg behind the other.","Lean your hips toward the wall and reach the outer arm overhead until the outside of the hip and thigh stretches.","Keep your chest facing forward.","Hold for 20-30 seconds, feeling a gentle pull rather than pain.","Release slowly and repeat, switching sides if the stretch is one sided."],"img":"opengym/1942.webp","gif":null,"ext":1},{"id":"1943","n":"pigeon hip stretch","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"hip flexors","sm":["hip flexors","lower back"],"st":["Start on hands and knees and slide one knee forward behind your wrist.","Extend the other leg straight behind you.","Lower your hips toward the floor and keep your chest tall.","Fold forward over the front leg for a deeper stretch if comfortable.","Hold for 20-30 seconds, then switch sides."],"img":"opengym/1943.webp","gif":null,"ext":1},{"id":"1944","n":"hip external rotator stretch","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"hip flexors","sm":["hip flexors","lower back"],"st":["Lie on your back with your knees bent.","Cross one ankle over the opposite knee and pull the lower thigh toward your chest until the buttock stretches.","Keep your head and shoulders relaxed on the floor.","Hold for 20-30 seconds, feeling a gentle pull rather than pain.","Release slowly and repeat, switching sides if the stretch is one sided."],"img":"opengym/1944.webp","gif":null,"ext":1},{"id":"1946","n":"standing leg tuck hip stretch","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"hip flexors","sm":["hip flexors","hamstrings"],"st":["Stand tall, holding a wall or support for balance.","Lift one knee and hold the shin and ankle with both hands.","Pull the leg gently toward your chest and slightly across the body.","Keep your standing leg soft and your back straight.","Hold for 20-30 seconds, then switch sides."],"img":"opengym/1946.webp","gif":null,"ext":1},{"id":"1947","n":"standing outer hip stretch","bp":"upper legs","eq":"body weight","tg":"abductors","mg":"glutes","sm":["glutes","obliques"],"st":["Stand next to a wall and cross one leg behind the other.","Push your hips sideways toward the wall.","Lean your upper body away from the hips until you feel the outer hip stretch.","Keep both feet flat on the floor.","Hold for 20-30 seconds, then switch sides."],"img":"opengym/1947.webp","gif":null,"ext":1},{"id":"1948","n":"sitting rotational hip stretch","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"obliques","sm":["obliques","lower back"],"st":["Sit on the floor with your knees bent and both feet flat.","Let both knees drop to one side and rotate your torso the opposite way until you feel the hip stretch.","Keep your hands behind you for support.","Hold for 20-30 seconds, feeling a gentle pull rather than pain.","Release slowly and repeat, switching sides if the stretch is one sided."],"img":"opengym/1948.webp","gif":null,"ext":1},{"id":"1951","n":"sitting one leg external stretch","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"hip flexors","sm":["hip flexors","groin"],"st":["Sit on the floor and bend one leg so the foot rests against the opposite thigh.","Lean your chest forward over the bent leg while pressing the knee toward the floor until the hip stretches.","Keep your back long.","Hold for 20-30 seconds, feeling a gentle pull rather than pain.","Release slowly and repeat, switching sides if the stretch is one sided."],"img":"opengym/1951.webp","gif":null,"ext":1},{"id":"1952","n":"assisted one leg extension","bp":"upper legs","eq":"assisted","tg":"quads","mg":"hip flexors","sm":["hip flexors","hamstrings"],"st":["Lie on your back and relax.","Have a partner support one leg and gently extend it.","Let the partner move the leg only to a mild stretch.","Keep your lower back flat on the floor.","Hold for 20-30 seconds, then switch legs."],"img":"opengym/1952.webp","gif":null,"ext":1},{"id":"1953","n":"supported one leg standing hip flexor and knee extensor stretch","bp":"upper legs","eq":"body weight","tg":"quads","mg":"hip flexors","sm":["hip flexors","glutes"],"st":["Stand tall holding a wall or chair for support.","Bend one knee and hold the ankle behind you.","Pull the heel toward your glutes and push the hip slightly forward.","Keep your knees close together.","Hold for 20-30 seconds, then switch sides."],"img":"opengym/1953.webp","gif":null,"ext":1},{"id":"1954","n":"quadriceps stretch on box","bp":"upper legs","eq":"body weight","tg":"quads","mg":"hip flexors","sm":["hip flexors","glutes"],"st":["Stand facing away from a box or bench and place the top of one foot on it behind you.","Stand tall on the front leg with a soft knee.","Tuck your pelvis and lower the hips slightly until you feel a stretch in the front of the thigh.","Hold a support for balance if needed.","Hold for 20-30 seconds, then switch sides."],"img":"opengym/1954.webp","gif":null,"ext":1},{"id":"1955","n":"single lean back quadriceps stretch","bp":"upper legs","eq":"body weight","tg":"quads","mg":"hip flexors","sm":["hip flexors","core"],"st":["Kneel on both knees, then lift one foot out in front so that the other leg is folded.","Place your hands behind you on the floor.","Lean back slowly until you feel a stretch in the front of the folded thigh.","Keep your hips lifted and avoid sagging into the lower back.","Hold for 20-30 seconds, then switch sides."],"img":"opengym/1955.webp","gif":null,"ext":1},{"id":"1956","n":"double lean back quadriceps stretch","bp":"upper legs","eq":"body weight","tg":"quads","mg":"hip flexors","sm":["hip flexors","core"],"st":["Kneel and sit back so your hips rest on your heels.","Place your hands on the floor behind you.","Lean back slowly and lift the hips slightly until you feel a stretch in the front of both thighs.","Stop if you feel any pinch in the knees.","Hold for 20-30 seconds, then come back up slowly."],"img":"opengym/1956.webp","gif":null,"ext":1},{"id":"1957","n":"standing shin stretch","bp":"lower legs","eq":"body weight","tg":"shins","mg":"calves","sm":["calves","ankles","feet"],"st":["Stand tall and hold a wall for balance.","Place the top of one foot on the floor behind you with the toes curled under.","Gently press the foot down by bending the standing knee.","Feel the stretch along the front of the shin and ankle.","Hold for 20-30 seconds, then switch sides."],"img":"opengym/1957.webp","gif":null,"ext":1},{"id":"1958","n":"standing toe extensor stretch","bp":"lower legs","eq":"body weight","tg":"calves","mg":"shins","sm":["shins","feet"],"st":["Stand next to a support and place the top of one foot on the floor behind you with the toes curled under.","Gently bend your standing knee and press the toes down until you feel the stretch on top of the foot and shin.","Keep the pressure light and controlled.","Hold for 20-30 seconds, feeling a gentle pull rather than pain.","Release slowly and repeat, switching sides if the stretch is one sided."],"img":"opengym/1958.webp","gif":null,"ext":1},{"id":"1959","n":"raised foot shin stretch","bp":"lower legs","eq":"body weight","tg":"shins","mg":"calves","sm":["calves","ankles"],"st":["Stand next to a wall and lift one foot behind you onto a low support with the top of the foot down.","Keep your torso upright and your standing leg soft.","Press your hips forward gently until you feel the shin stretch.","Keep the movement slow and controlled.","Hold for 20-30 seconds, then switch sides."],"img":"opengym/1959.webp","gif":null,"ext":1},{"id":"1960","n":"double kneeling shin stretch","bp":"lower legs","eq":"body weight","tg":"shins","mg":"calves","sm":["calves","ankles"],"st":["Kneel on a mat with your feet pointing straight back and the tops of the feet on the floor.","Slowly sit back toward your heels until you feel the shins and ankles stretch.","Place your hands on the floor in front of you to control the pressure.","Hold for 20-30 seconds, feeling a gentle pull rather than pain.","Release slowly and repeat, switching sides if the stretch is one sided."],"img":"opengym/1960.webp","gif":null,"ext":1},{"id":"1961","n":"squatting toe stretch","bp":"lower legs","eq":"body weight","tg":"calves","mg":"feet","sm":["feet","ankles","shins"],"st":["Crouch down with your heels lifted and toes tucked under.","Place your hands on the floor in front of you for support.","Slowly sit back toward your heels until you feel the toes and soles stretch.","Ease off if the stretch is too sharp.","Hold for 20-30 seconds, then release."],"img":"opengym/1961.webp","gif":null,"ext":1},{"id":"1962","n":"seated toe extensor stretch","bp":"lower legs","eq":"body weight","tg":"calves","mg":"feet","sm":["feet","shins","ankles"],"st":["Sit and cross one ankle over the opposite knee.","Hold the top of the foot and toes with your hand.","Gently curl the toes and foot downward until you feel a stretch on the top.","Keep the motion gentle.","Hold for 20-30 seconds, then switch sides."],"img":"opengym/1962.webp","gif":null,"ext":1},{"id":"1963","n":"seated toe extensor and foot everter stretch","bp":"lower legs","eq":"body weight","tg":"calves","mg":"feet","sm":["feet","shins","ankles"],"st":["Sit and cross one ankle over the opposite knee.","Hold the top of the foot and toes with your hand.","Curl the toes down and turn the sole gently outward.","Feel the stretch along the top and outer edge of the foot.","Hold for 20-30 seconds, then switch sides."],"img":"opengym/1963.webp","gif":null,"ext":1},{"id":"1964","n":"seated toe extensor and foot inverter stretch","bp":"lower legs","eq":"body weight","tg":"calves","mg":"feet","sm":["feet","shins","ankles"],"st":["Sit and cross one ankle over the opposite knee.","Hold the top of the foot and toes with your hand.","Curl the toes down and turn the sole gently inward.","Feel the stretch along the top and inner edge of the foot.","Hold for 20-30 seconds, then switch sides."],"img":"opengym/1964.webp","gif":null,"ext":1},{"id":"1965","n":"seated toe flexor stretch","bp":"lower legs","eq":"body weight","tg":"calves","mg":"feet","sm":["feet","ankles"],"st":["Sit and cross one ankle over the opposite knee.","Hold the toes with your hand.","Gently pull the toes back toward your shin.","Feel the stretch along the sole of the foot.","Hold for 20-30 seconds, then switch sides."],"img":"opengym/1965.webp","gif":null,"ext":1},{"id":"1966","n":"seated toe flexor and foot everter stretch","bp":"lower legs","eq":"body weight","tg":"calves","mg":"feet","sm":["feet","ankles"],"st":["Sit and cross one ankle over the opposite knee.","Hold the toes with your hand.","Pull the toes back toward your shin and turn the sole gently outward.","Feel the stretch along the sole and inner edge of the foot.","Hold for 20-30 seconds, then switch sides."],"img":"opengym/1966.webp","gif":null,"ext":1},{"id":"1967","n":"seated toe flexor and foot inverter stretch","bp":"lower legs","eq":"body weight","tg":"calves","mg":"feet","sm":["feet","ankles"],"st":["Sit and cross one ankle over the opposite knee.","Hold the toes with your hand.","Pull the toes back toward your shin and turn the sole gently inward.","Feel the stretch along the sole and outer edge of the foot.","Hold for 20-30 seconds, then switch sides."],"img":"opengym/1967.webp","gif":null,"ext":1},{"id":"1968","n":"standing toe flexor stretch","bp":"lower legs","eq":"body weight","tg":"calves","mg":"feet","sm":["feet","soleus"],"st":["Stand facing a wall and place the toes of one foot on it with the heel on the floor.","Lean forward gently until you feel the stretch along the bottom of the foot and into the calf.","Keep your heel firmly on the floor.","Hold for 20-30 seconds, feeling a gentle pull rather than pain.","Release slowly and repeat, switching sides if the stretch is one sided."],"img":"opengym/1968.webp","gif":null,"ext":1},{"id":"1969","n":"mobilization of ankle stretch","bp":"lower legs","eq":"body weight","tg":"calves","mg":"ankles","sm":["ankles","soleus","shins"],"st":["Stand facing a wall with one foot forward, toes a few inches from it.","Keep your front heel on the floor.","Bend the front knee and glide it toward the wall.","Return and repeat slowly for 10-15 reps, then switch feet."],"img":"opengym/1969.webp","gif":null,"ext":1},{"id":"1970","n":"standing upright shoulders stretch","bp":"shoulders","eq":"body weight","tg":"delts","mg":"upper back","sm":["upper back","chest"],"st":["Stand tall with your feet hip-width apart.","Clasp your hands behind your back.","Straighten your arms and lift them gently away from your body.","Keep your chest open and your neck relaxed.","Hold for 20-30 seconds."],"img":"opengym/1970.webp","gif":null,"ext":1},{"id":"1971","n":"reverse shoulder stretch","bp":"shoulders","eq":"body weight","tg":"delts","mg":"chest","sm":["chest","biceps"],"st":["Stand tall and clasp your hands behind your back.","Straighten your arms and lift your hands up and away from your body until the shoulders and chest stretch.","Keep your chest open and avoid leaning forward.","Hold for 20-30 seconds, feeling a gentle pull rather than pain.","Release slowly and repeat, switching sides if the stretch is one sided."],"img":"opengym/1971.webp","gif":null,"ext":1},{"id":"1972","n":"sitting shoulders stretch on bench","bp":"shoulders","eq":"body weight","tg":"delts","mg":"chest","sm":["chest","upper back"],"st":["Sit on the edge of a bench and place your hands behind you on it, fingers pointing back.","Walk your hips slightly forward off the bench.","Lower your hips gently until you feel a stretch at the front of the shoulders.","Keep your back close to the bench and shoulders down.","Hold for 20-30 seconds, then rise up."],"img":"opengym/1972.webp","gif":null,"ext":1},{"id":"1973","n":"assisted sitting reverse shoulder stretch","bp":"shoulders","eq":"assisted","tg":"delts","mg":"chest","sm":["chest","upper back"],"st":["Sit tall and put your arms behind you, palms facing down.","Have a partner stand behind and hold your wrists or forearms.","Ask them to lift your arms slowly until you feel a stretch.","Keep your shoulders relaxed and chest open.","Hold for 20-30 seconds, then lower slowly."],"img":"opengym/1973.webp","gif":null,"ext":1},{"id":"1974","n":"standing reverse shoulder stretch","bp":"shoulders","eq":"body weight","tg":"delts","mg":"chest","sm":["chest","upper back"],"st":["Stand tall and clasp your hands behind your back.","Straighten your arms and squeeze your shoulder blades together.","Lift your hands slightly away from your body.","Keep your chest up and avoid arching your lower back.","Hold for 20-30 seconds, then release."],"img":"opengym/1974.webp","gif":null,"ext":1},{"id":"1975","n":"seated shoulder flexor depressor retractor stretch","bp":"shoulders","eq":"body weight","tg":"delts","mg":"upper back","sm":["upper back","rhomboids","chest"],"st":["Sit tall on a chair or bench.","Place your hands behind you on the seat, fingers pointing back.","Press your shoulders down and back, opening your chest.","Lean slightly forward until you feel the stretch.","Hold for 20-30 seconds, then relax."],"img":"opengym/1975.webp","gif":null,"ext":1},{"id":"1976","n":"one arm shoulder flexor stretch","bp":"shoulders","eq":"body weight","tg":"delts","mg":"biceps","sm":["biceps","chest"],"st":["Stand next to a wall or post and place one hand on it behind you with the arm straight.","Slowly turn your body away until you feel the front of the shoulder stretch.","Keep the arm straight and the shoulder relaxed.","Hold for 20-30 seconds, feeling a gentle pull rather than pain.","Release slowly and repeat, switching sides if the stretch is one sided."],"img":"opengym/1976.webp","gif":null,"ext":1},{"id":"1977","n":"adduction of arm in back stretch","bp":"shoulders","eq":"body weight","tg":"delts","mg":"triceps","sm":["triceps","upper back"],"st":["Stand or sit tall.","Reach one arm behind your back.","Grab that wrist with the other hand and gently pull it across your body.","Keep your shoulders level.","Hold for 20-30 seconds, then switch sides."],"img":"opengym/1977.webp","gif":null,"ext":1},{"id":"1978","n":"shoulder extensor adductor and retractor stretch","bp":"shoulders","eq":"body weight","tg":"delts","mg":"rhomboids","sm":["rhomboids","upper back","triceps"],"st":["Stand tall and extend one arm behind you.","Reach across to grab it with the other hand.","Draw the arm gently back and across the body.","Keep your chest open and your shoulders down.","Hold for 20-30 seconds, then switch sides."],"img":"opengym/1978.webp","gif":null,"ext":1},{"id":"1979","n":"shoulder adductor elevator and protractor stretch","bp":"shoulders","eq":"body weight","tg":"delts","mg":"rear deltoids","sm":["rear deltoids","rhomboids","trapezius"],"st":["Stand or sit tall and bring one arm across your chest.","Use the opposite hand to press the arm toward you until the shoulder and upper back stretch.","Keep your shoulders down away from your ears.","Hold for 20-30 seconds, feeling a gentle pull rather than pain.","Release slowly and repeat, switching sides if the stretch is one sided."],"img":"opengym/1979.webp","gif":null,"ext":1},{"id":"1980","n":"across chest shoulder stretch","bp":"shoulders","eq":"body weight","tg":"delts","mg":"rear deltoids","sm":["rear deltoids","upper back"],"st":["Stand tall and bring one arm straight across your chest.","Use your other forearm to press the arm gently toward your body.","Keep the shoulder relaxed and down.","Feel the stretch in the back of the shoulder.","Hold for 20-30 seconds, then switch sides."],"img":"opengym/1980.webp","gif":null,"ext":1},{"id":"1981","n":"bent arm shoulder stretch","bp":"shoulders","eq":"body weight","tg":"delts","mg":"rear deltoids","sm":["rear deltoids","triceps"],"st":["Stand tall and bring one arm across your chest with the elbow bent.","Hold the elbow with your other hand.","Gently pull the elbow toward the opposite shoulder.","Keep your shoulders level and your neck relaxed.","Hold for 20-30 seconds, then switch sides."],"img":"opengym/1981.webp","gif":null,"ext":1},{"id":"1982","n":"rotation shoulder stretch","bp":"shoulders","eq":"body weight","tg":"delts","mg":"rotator cuff","sm":["rotator cuff","chest"],"st":["Stand tall and bend one elbow to 90 degrees at your side.","Slowly rotate your forearm outward or inward, using the other hand to assist, until you feel the shoulder stretch.","Keep your elbow tucked in close to your body.","Hold for 20-30 seconds, feeling a gentle pull rather than pain.","Release slowly and repeat, switching sides if the stretch is one sided."],"img":"opengym/1982.webp","gif":null,"ext":1},{"id":"1983","n":"reaching up shoulder stretch","bp":"shoulders","eq":"body weight","tg":"delts","mg":"lats","sm":["lats","triceps"],"st":["Stand tall with your feet hip width apart.","Reach one or both arms overhead and up as high as you can, then press them slightly backward.","Do not arch your lower back as you reach.","Hold for 20-30 seconds, feeling a gentle pull rather than pain.","Release slowly and repeat, switching sides if the stretch is one sided."],"img":"opengym/1983.webp","gif":null,"ext":1},{"id":"1984","n":"rotator cuff stretch","bp":"shoulders","eq":"body weight","tg":"delts","mg":"rotator cuff","sm":["rotator cuff","rear deltoids"],"st":["Stand tall and bring one arm across your body at chest height.","Hold the arm just above the elbow with the other hand and draw it in until the back of the shoulder stretches.","Keep the shoulder blade down and relaxed.","Hold for 20-30 seconds, feeling a gentle pull rather than pain.","Release slowly and repeat, switching sides if the stretch is one sided."],"img":"opengym/1984.webp","gif":null,"ext":1},{"id":"1985","n":"elbow out rotator stretch","bp":"shoulders","eq":"body weight","tg":"delts","mg":"rotator cuff","sm":["rotator cuff","upper back"],"st":["Stand tall and lift one elbow out to the side, hand behind your head.","Hold the elbow with your other hand.","Gently press the elbow back and slightly down.","Feel the stretch in the shoulder.","Hold for 20-30 seconds, then switch sides."],"img":"opengym/1985.webp","gif":null,"ext":1},{"id":"1986","n":"arm up rotator stretch","bp":"shoulders","eq":"body weight","tg":"delts","mg":"rotator cuff","sm":["rotator cuff","triceps"],"st":["Raise one arm overhead and bend the elbow, palm resting on your upper back.","Use your other hand to hold the elbow.","Gently press the elbow back and down.","Keep your ribs down and chest open.","Hold for 20-30 seconds, then switch sides."],"img":"opengym/1986.webp","gif":null,"ext":1},{"id":"1987","n":"arm down rotator stretch","bp":"shoulders","eq":"body weight","tg":"delts","mg":"rotator cuff","sm":["rotator cuff","chest"],"st":["Stand tall and place one arm behind your back, bent at the elbow.","Hold the wrist with the other hand.","Gently draw the hand away from your body and slightly up.","Keep your shoulders relaxed.","Hold for 20-30 seconds, then switch sides."],"img":"opengym/1987.webp","gif":null,"ext":1},{"id":"1988","n":"kneeling one arm cross body stretch","bp":"shoulders","eq":"body weight","tg":"delts","mg":"rear deltoids","sm":["rear deltoids","upper back"],"st":["Kneel on a mat and slide one arm across the floor in front of you, palm down.","Sink your chest toward the floor and keep reaching until the shoulder and upper back stretch.","Keep your hips over your knees.","Hold for 20-30 seconds, feeling a gentle pull rather than pain.","Release slowly and repeat, switching sides if the stretch is one sided."],"img":"opengym/1988.webp","gif":null,"ext":1},{"id":"1989","n":"depression in parallel bars stretch","bp":"shoulders","eq":"body weight","tg":"lats","mg":"chest","sm":["chest","shoulders","triceps"],"st":["Stand between parallel bars and grip them at hip height.","Walk back slightly, letting your arms straighten.","Lower your chest toward the floor and press your head between your arms.","Feel the stretch in the lats and shoulders.","Hold for 20-30 seconds, then walk forward to release."],"img":"opengym/1989.webp","gif":null,"ext":1},{"id":"1990","n":"external shoulder rotation stretch","bp":"shoulders","eq":"body weight","tg":"delts","mg":"rotator cuff","sm":["rotator cuff","chest"],"st":["Stand next to a doorframe and bend your elbow to 90 degrees with your forearm on the frame.","Slowly turn your body away from the arm until you feel the front of the shoulder stretch.","Keep your elbow level with your shoulder.","Hold for 20-30 seconds, feeling a gentle pull rather than pain.","Release slowly and repeat, switching sides if the stretch is one sided."],"img":"opengym/1990.webp","gif":null,"ext":1},{"id":"1991","n":"internal shoulder rotation stretch","bp":"shoulders","eq":"body weight","tg":"delts","mg":"rotator cuff","sm":["rotator cuff","rear deltoids"],"st":["Stand tall and place one hand behind your lower back with the elbow bent.","Use the other hand or a towel to gently draw the hand up your back until the back of the shoulder stretches.","Keep your shoulders level and do not twist.","Hold for 20-30 seconds, feeling a gentle pull rather than pain.","Release slowly and repeat, switching sides if the stretch is one sided."],"img":"opengym/1991.webp","gif":null,"ext":1},{"id":"1992","n":"sled full hack squat","bp":"upper legs","eq":"sled machine","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","calves"],"st":["Set your shoulders under the pads and your feet shoulder-width on the platform.","Unlock the safety and straighten your legs.","Lower your hips slowly until your thighs are below parallel.","Keep your back flat against the pad and knees tracking over your toes.","Press through your whole foot to stand back up."],"img":"opengym/1992.webp","gif":null,"ext":1},{"id":"2071","n":"single leg hip thrusts","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"hamstrings","sm":["hamstrings","core"],"st":["Sit with your upper back against a bench and one foot flat on the floor.","Extend the other leg or hold it up.","Drive through the heel to lift your hips until your body is flat.","Squeeze your glute at the top, then lower under control.","Complete the reps, then switch legs."],"img":"opengym/2071.webp","gif":null,"ext":1},{"id":"2072","n":"hip thrusts","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"hamstrings","sm":["hamstrings","core"],"st":["Sit on the floor with your upper back against a bench and knees bent.","Plant your feet flat, hip-width apart.","Drive through your heels to lift your hips until your torso is level.","Squeeze your glutes at the top.","Lower slowly and repeat."],"img":"opengym/2072.webp","gif":null,"ext":1},{"id":"2087","n":"shoulder adductor protractor and elevator stretch","bp":"shoulders","eq":"body weight","tg":"delts","mg":"upper back","sm":["upper back","trapezius","rhomboids"],"st":["Stand tall and bring one arm across your chest.","Hold it with the other arm just above the elbow.","Gently pull while rounding the upper back slightly forward.","Keep your neck relaxed.","Hold for 20-30 seconds, then switch sides."],"img":"opengym/2087.webp","gif":null,"ext":1},{"id":"2088","n":"shoulder stretch with towel behind the back","bp":"shoulders","eq":"body weight","tg":"delts","mg":"triceps","sm":["triceps","chest"],"st":["Hold a towel in one hand and raise that arm overhead, bending the elbow.","Reach the other hand up from behind your back and grab the towel.","Gently pull the towel down with the lower hand.","Keep your head upright.","Hold for 20-30 seconds, then switch sides."],"img":"opengym/2088.webp","gif":null,"ext":1},{"id":"2089","n":"finger stretch","bp":"lower arms","eq":"body weight","tg":"forearms","mg":"wrist flexors","sm":["wrist flexors","hands"],"st":["Hold one arm out in front of you with the elbow straight.","Use the other hand to gently pull the fingers back until you feel a stretch in the palm and forearm.","Keep the fingers straight and relaxed.","Hold for 20-30 seconds, feeling a gentle pull rather than pain.","Release slowly and repeat, switching sides if the stretch is one sided."],"img":"opengym/2089.webp","gif":null,"ext":1},{"id":"2090","n":"palms out forearm stretch","bp":"lower arms","eq":"body weight","tg":"forearms","mg":"wrist flexors","sm":["wrist flexors","hands"],"st":["Stand or sit tall and interlace your fingers.","Turn your palms outward and straighten your arms in front of you.","Push your hands gently away until you feel the stretch in the forearms.","Keep your shoulders relaxed.","Hold for 20-30 seconds, then release."],"img":"opengym/2090.webp","gif":null,"ext":1},{"id":"2091","n":"fingers down forearm stretch","bp":"lower arms","eq":"body weight","tg":"forearms","mg":"wrist extensors","sm":["wrist extensors","hands"],"st":["Extend one arm in front of you with the palm facing down.","Bend the wrist so the fingers point toward the floor.","Use your other hand to press the back of the hand gently toward you.","Keep your elbow straight.","Hold for 20-30 seconds, then switch sides."],"img":"opengym/2091.webp","gif":null,"ext":1},{"id":"2092","n":"wall flexors stretch","bp":"lower arms","eq":"body weight","tg":"forearms","mg":"wrist flexors","sm":["wrist flexors","hands"],"st":["Stand facing a wall and place one palm on it with the fingers pointing down.","Keep your arm straight.","Slowly turn your body away until you feel the stretch in the forearm.","Keep your fingers flat on the wall.","Hold for 20-30 seconds, then switch sides."],"img":"opengym/2092.webp","gif":null,"ext":1},{"id":"2093","n":"seated wrist ulnar deviator and flexor stretch","bp":"lower arms","eq":"body weight","tg":"forearms","mg":"wrist flexors","sm":["wrist flexors","hands"],"st":["Sit tall and extend one arm forward with the palm facing up.","Use the other hand to bend the wrist back and tilt it toward the thumb side until the forearm stretches.","Keep the elbow straight.","Hold for 20-30 seconds, feeling a gentle pull rather than pain.","Release slowly and repeat, switching sides if the stretch is one sided."],"img":"opengym/2093.webp","gif":null,"ext":1},{"id":"2094","n":"thumb stretch","bp":"lower arms","eq":"body weight","tg":"forearms","mg":"hands","sm":["hands","wrist flexors"],"st":["Extend one arm with the palm facing up.","Use your other hand to hold the thumb.","Gently pull the thumb back and away from the palm.","Stop at a mild stretch.","Hold for 20-30 seconds, then switch sides."],"img":"opengym/2094.webp","gif":null,"ext":1},{"id":"2095","n":"finger extension stretch","bp":"lower arms","eq":"body weight","tg":"forearms","mg":"hands","sm":["hands","wrist flexors"],"st":["Extend one arm in front with the palm facing up.","Use your other hand to hold the fingers.","Gently pull the fingers back toward you.","Keep your elbow straight and the wrist relaxed.","Hold for 20-30 seconds, then switch sides."],"img":"opengym/2095.webp","gif":null,"ext":1},{"id":"2096","n":"flexion finger stretch","bp":"lower arms","eq":"body weight","tg":"forearms","mg":"wrist flexors","sm":["wrist flexors","hands"],"st":["Hold one arm out in front of you with the palm facing down.","Use your other hand to press the fingers of the extended hand gently downward.","Keep the elbow of the extended arm straight and the shoulders relaxed.","Stop at a mild pull, never at pain.","Hold for 20-30 seconds.","Release and repeat on the other hand."],"img":"opengym/2096.webp","gif":null,"ext":1},{"id":"2097","n":"separation finger stretch","bp":"lower arms","eq":"body weight","tg":"forearms","mg":"hands","sm":["hands","wrist flexors"],"st":["Hold one hand up in front of you with the palm facing you.","Spread your fingers as far apart as feels comfortable.","If you want more stretch, press between the fingers with your other hand.","Keep the wrist straight and the shoulder relaxed.","Hold for 20-30 seconds.","Relax the hand and switch sides."],"img":"opengym/2097.webp","gif":null,"ext":1},{"id":"2098","n":"adduction hand with elbow extended stretch","bp":"lower arms","eq":"body weight","tg":"forearms","mg":"wrist flexors","sm":["wrist flexors","wrist extensors"],"st":["Stand tall and extend one arm in front of you with the elbow straight.","Turn the palm so the thumb points up.","Grab the hand with your other hand and tilt it gently toward the little finger side.","Keep the elbow locked and the shoulder down.","Hold for 20-30 seconds.","Release and repeat on the other arm."],"img":"opengym/2098.webp","gif":null,"ext":1},{"id":"2099","n":"recumbent hip external rotator and hip extensor stretch (crossed leg)","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"hip flexors","sm":["hip flexors","lower back"],"st":["Lie on your back with your knees bent and feet flat.","Cross one ankle over the opposite knee, then pull the legs toward your chest until the buttock stretches.","Keep your head and shoulders relaxed on the floor.","Hold for 20-30 seconds, feeling a gentle pull rather than pain.","Release slowly and repeat, switching sides if the stretch is one sided."],"img":"opengym/2099.webp","gif":null,"ext":1},{"id":"2100","n":"seated quadriceps stretch","bp":"upper legs","eq":"body weight","tg":"quads","mg":"hip flexors","sm":["hip flexors","quadriceps"],"st":["Sit sideways on a bench or sturdy seat with one leg hanging off the side.","Bend the hanging knee and bring the heel back toward your glutes.","Hold the foot or ankle with your hand and gently pull the heel closer.","Keep your torso upright and your knees close together.","Hold for 20-30 seconds.","Release and switch legs."],"img":"opengym/2100.webp","gif":null,"ext":1},{"id":"2101","n":"front cross over shin stretch","bp":"lower legs","eq":"body weight","tg":"shins","mg":"calves","sm":["calves","ankles"],"st":["Stand tall and cross one leg in front of the other.","Point the toes of the back foot against the floor and gently bend the knee until the shin and ankle stretch.","Hold a wall or chair for balance.","Hold for 20-30 seconds, feeling a gentle pull rather than pain.","Release slowly and repeat, switching sides if the stretch is one sided."],"img":"opengym/2101.webp","gif":null,"ext":1},{"id":"2102","n":"sitting toe pull calf stretch","bp":"lower legs","eq":"body weight","tg":"calves","mg":"soleus","sm":["soleus","shins","feet"],"st":["Sit on the floor with one leg straight out in front of you.","Reach forward and grab the toes or the ball of the foot of that leg.","Gently pull the toes toward your shin while keeping the knee straight.","Sit tall and avoid rounding your back.","Hold for 20-30 seconds.","Release and switch legs."],"img":"opengym/2102.webp","gif":null,"ext":1},{"id":"2103","n":"separation between fingers stretch","bp":"lower legs","eq":"body weight","tg":"calves","mg":"feet","sm":["feet","ankles"],"st":["Sit comfortably and bring one foot up to rest on the opposite knee.","Hold the foot with your hand.","Slide your fingers between the toes and gently spread them apart.","Keep the movement slow and easy.","Hold the spread for 15-20 seconds.","Release and switch feet."],"img":"opengym/2103.webp","gif":null,"ext":1},{"id":"2104","n":"leaning heel back achilles stretch","bp":"lower legs","eq":"body weight","tg":"calves","mg":"soleus","sm":["soleus","ankles"],"st":["Stand facing a wall and place your hands on it at chest height.","Step one foot back and keep that heel on the floor.","Bend both knees slightly and lean forward until you feel a pull low in the back calf.","Keep the back heel flat and the toes pointing forward.","Hold for 20-30 seconds.","Switch legs."],"img":"opengym/2104.webp","gif":null,"ext":1},{"id":"2105","n":"lower trunk flexor stretch","bp":"waist","eq":"body weight","tg":"abs","mg":"hip flexors","sm":["hip flexors","lower abs"],"st":["Lie face down with your hands under your shoulders.","Press up through your hands and let your hips sink toward the floor until the lower abdomen stretches.","Keep your hips on the floor and your shoulders relaxed.","Hold for 20-30 seconds, feeling a gentle pull rather than pain.","Release slowly and repeat, switching sides if the stretch is one sided."],"img":"opengym/2105.webp","gif":null,"ext":1},{"id":"2106","n":"cat stretch v. 2","bp":"waist","eq":"body weight","tg":"spine","mg":"core","sm":["core","upper back","lower back"],"st":["Start on all fours with hands under shoulders and knees under hips.","Tuck your chin and tilt the pelvis as you push the floor away.","Round your back up toward the ceiling like a cat.","Hold the rounded position for a few seconds.","Return slowly to the neutral starting position.","Repeat for 8-10 slow reps."],"img":"opengym/2106.webp","gif":null,"ext":1},{"id":"2107","n":"cow stretch","bp":"waist","eq":"body weight","tg":"spine","mg":"core","sm":["core","lower back","hip flexors"],"st":["Start on all fours with hands under shoulders and knees under hips.","Inhale and let your belly drop toward the floor.","Lift your chest and tailbone while looking slightly forward.","Keep your arms straight and shoulders away from your ears.","Hold for a couple of seconds, then return to neutral.","Repeat for 8-10 slow reps."],"img":"opengym/2107.webp","gif":null,"ext":1},{"id":"2108","n":"standing lean back stomach stretch","bp":"waist","eq":"body weight","tg":"abs","mg":"hip flexors","sm":["hip flexors","lower abs"],"st":["Stand tall with your hands on your hips.","Gently lean back and push your hips slightly forward until you feel a stretch across the stomach.","Keep your movement small and avoid cranking your lower back.","Hold for 20-30 seconds, feeling a gentle pull rather than pain.","Release slowly and repeat, switching sides if the stretch is one sided."],"img":"opengym/2108.webp","gif":null,"ext":1},{"id":"2109","n":"kneeling abdominal stretch","bp":"waist","eq":"body weight","tg":"abs","mg":"hip flexors","sm":["hip flexors","lower abs"],"st":["Kneel with your knees hip width apart and place your hands on your lower back.","Push your hips forward and lean back until the abdominal muscles stretch.","Tuck your chin a little and avoid dropping your head back.","Hold for 20-30 seconds, feeling a gentle pull rather than pain.","Release slowly and repeat, switching sides if the stretch is one sided."],"img":"opengym/2109.webp","gif":null,"ext":1},{"id":"2110","n":"standing abs rotation stretch","bp":"waist","eq":"body weight","tg":"abs","mg":"obliques","sm":["obliques","core","lower back"],"st":["Stand tall with feet hip-width apart and arms relaxed.","Place your hands on your hips or hold them out to the sides.","Keep the hips facing forward and turn your upper body slowly to one side.","Look over your shoulder and breathe steadily.","Hold for 20-30 seconds.","Return to the front and rotate to the other side."],"img":"opengym/2110.webp","gif":null,"ext":1},{"id":"2111","n":"rotating stomach stretch","bp":"waist","eq":"body weight","tg":"abs","mg":"obliques","sm":["obliques","core","hip flexors"],"st":["Lie face down and prop yourself up on your forearms or hands.","Keep your hips on the floor and lift your chest.","Slowly turn your head and shoulders toward one side.","Stay relaxed and avoid pushing into pain in the lower back.","Hold for 20-30 seconds.","Return to centre and rotate to the other side."],"img":"opengym/2111.webp","gif":null,"ext":1},{"id":"2112","n":"hip extension supported from back","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"hamstrings","sm":["hamstrings","lower back","core"],"st":["Lie on your back with knees bent and feet flat on the floor.","Place your arms by your sides for support.","Push through your heels and lift the hips until the body forms a straight line.","Squeeze your glutes at the top without arching the lower back.","Lower the hips back down with control.","Repeat for 10-12 reps."],"img":"opengym/2112.webp","gif":null,"ext":1},{"id":"2113","n":"standing lower trunk lateral flexor stretch","bp":"waist","eq":"body weight","tg":"abs","mg":"obliques","sm":["obliques","lower back"],"st":["Stand with feet slightly wider than hip-width.","Place one hand on your hip and reach the other arm overhead.","Push the hips slightly to the side opposite your reach.","Bend sideways from the waist without leaning forward or back.","Hold for 20-30 seconds.","Return to upright and switch sides."],"img":"opengym/2113.webp","gif":null,"ext":1},{"id":"2114","n":"seated lower trunk lateral flexor stretch","bp":"waist","eq":"body weight","tg":"abs","mg":"obliques","sm":["obliques","lats"],"st":["Sit tall on the floor or a chair with your legs crossed or feet flat.","Reach one arm overhead and bend sideways away from it until you feel the side of the waist stretch.","Keep both hips grounded and avoid leaning forward.","Hold for 20-30 seconds, feeling a gentle pull rather than pain.","Release slowly and repeat, switching sides if the stretch is one sided."],"img":"opengym/2114.webp","gif":null,"ext":1},{"id":"2115","n":"hip extension on knees","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"hip flexors","sm":["hip flexors","core","quadriceps"],"st":["Kneel on a soft surface with knees hip-width apart and thighs upright.","Place your hands on your hips or the back of your pelvis.","Squeeze your glutes and push your hips forward.","Keep your ribs down and avoid over-arching your lower back.","Hold for a moment, then return to the start.","Repeat for 8-12 reps."],"img":"opengym/2115.webp","gif":null,"ext":1},{"id":"2116","n":"lying knee roll over stretch","bp":"waist","eq":"body weight","tg":"spine","mg":"obliques","sm":["obliques","lower back","glutes"],"st":["Lie on your back with arms out to the sides and knees bent.","Keep your shoulders flat on the floor.","Slowly lower both knees to one side.","Turn your head the other way if it feels comfortable.","Hold for 20-30 seconds.","Bring the knees back to centre and roll to the other side."],"img":"opengym/2116.webp","gif":null,"ext":1},{"id":"2118","n":"sitting lateral side stretch","bp":"waist","eq":"body weight","tg":"abs","mg":"obliques","sm":["obliques","lats"],"st":["Sit tall with your legs crossed or feet flat on the floor.","Reach one arm overhead and lean sideways away from it, placing the other hand on the floor for support.","Keep both sit bones grounded.","Hold for 20-30 seconds, feeling a gentle pull rather than pain.","Release slowly and repeat, switching sides if the stretch is one sided."],"img":"opengym/2118.webp","gif":null,"ext":1},{"id":"2119","n":"standing side stretch","bp":"waist","eq":"body weight","tg":"abs","mg":"obliques","sm":["obliques","lats","shoulders"],"st":["Stand tall with feet hip-width apart.","Raise one arm overhead with the palm facing inward.","Lean your torso sideways away from the raised arm.","Keep both hips level and your chest facing forward.","Hold for 20-30 seconds.","Return upright and repeat on the other side."],"img":"opengym/2119.webp","gif":null,"ext":1},{"id":"2120","n":"standing side stretch with stick","bp":"waist","eq":"body weight","tg":"abs","mg":"obliques","sm":["obliques","lats","shoulders"],"st":["Stand with feet shoulder-width apart holding a stick with both hands overhead.","Keep your arms straight and your shoulders relaxed.","Lean your torso slowly to one side without twisting.","Keep your hips steady and your chest facing forward.","Hold for 20-30 seconds.","Return to upright and lean to the other side."],"img":"opengym/2120.webp","gif":null,"ext":1},{"id":"2121","n":"lateral bend lying down","bp":"waist","eq":"body weight","tg":"obliques","mg":"abdominals","sm":["abdominals","lats"],"st":["Lie on your back with legs together and arms stretched overhead.","Slide both feet and both hands to the same side so the body forms a gentle arc.","Keep your hips and shoulders on the floor.","Breathe slowly and relax into the curve.","Hold for 20-30 seconds.","Return to centre and bend to the other side."],"img":"opengym/2121.webp","gif":null,"ext":1},{"id":"2122","n":"assisted side bent","bp":"waist","eq":"assisted","tg":"obliques","mg":"abdominals","sm":["abdominals","lats"],"st":["Stand tall with feet shoulder-width apart and one arm overhead.","Have your partner stand behind you with a hand on your hip and a hand on your raised arm.","Lean sideways as your partner gently guides the movement.","Tell your partner to stop at a mild pull.","Hold for 20-30 seconds.","Return upright and switch sides."],"img":"opengym/2122.webp","gif":null,"ext":1},{"id":"2123","n":"assisted obliques stretch","bp":"waist","eq":"assisted","tg":"obliques","mg":"abdominals","sm":["abdominals","lats","lower back"],"st":["Stand upright with feet shoulder-width apart.","Raise one arm overhead while your partner steadies your hips.","Lean away from the raised arm while your partner gently guides your arm.","Keep your chest open and avoid leaning forward.","Hold for 20-30 seconds.","Come back to upright and switch sides."],"img":"opengym/2123.webp","gif":null,"ext":1},{"id":"2124","n":"lateral bend on floor by kneeling","bp":"waist","eq":"body weight","tg":"obliques","mg":"abdominals","sm":["abdominals","lats"],"st":["Kneel on a mat and extend one arm sideways along the floor.","Walk your hands to one side and sink your hips the other way until the side of the waist stretches.","Keep your hips over your knees.","Hold for 20-30 seconds, feeling a gentle pull rather than pain.","Release slowly and repeat, switching sides if the stretch is one sided."],"img":"opengym/2124.webp","gif":null,"ext":1},{"id":"2125","n":"lateral stretch on floor lying down","bp":"waist","eq":"body weight","tg":"abs","mg":"obliques","sm":["obliques","lats"],"st":["Lie on your back with your arms extended overhead.","Shift your feet and your upper body to one side to form a gentle banana curve until the opposite side stretches.","Keep both shoulders and hips on the floor.","Hold for 20-30 seconds, feeling a gentle pull rather than pain.","Release slowly and repeat, switching sides if the stretch is one sided."],"img":"opengym/2125.webp","gif":null,"ext":1},{"id":"2127","n":"weighted captain's chair leg raise","bp":"waist","eq":"weighted","tg":"abs","mg":"lower abs","sm":["lower abs","hip flexors","forearms"],"st":["Position yourself on a captain's chair with your forearms on the pads and back against the backrest.","Hold the weight securely between your feet or on your ankles.","Brace your core and raise your knees or legs up toward your chest.","Curl your pelvis slightly at the top.","Lower your legs slowly without swinging.","Repeat for the planned reps."],"img":"opengym/2127.webp","gif":null,"ext":1},{"id":"2130","n":"weighted decline crunch","bp":"waist","eq":"weighted","tg":"abs","mg":"obliques","sm":["obliques","hip flexors"],"st":["Lie on a decline bench and hook your feet under the pads.","Hold a weight plate or dumbbell against your chest.","Curl your upper body up by contracting the abs.","Pause briefly at the top without pulling on your neck.","Lower back down with control.","Repeat for the planned reps."],"img":"opengym/2130.webp","gif":null,"ext":1},{"id":"2140","n":"walk wave machine","bp":"cardio","eq":"elliptical machine","tg":"cardiovascular system","mg":"quadriceps","sm":["quadriceps","glutes","calves"],"st":["Step onto the machine and hold the handles lightly.","Start moving your legs in a smooth walking rhythm.","Keep your posture tall and your core lightly braced.","Pick a pace that lets you breathe steadily.","Keep going for 10-30 minutes depending on your fitness.","Slow down for the last minute before stepping off."],"img":"opengym/2140.webp","gif":null,"ext":1},{"id":"2146","n":"lever hip thrust","bp":"upper legs","eq":"leverage machine","tg":"glutes","mg":"hamstrings","sm":["hamstrings","quadriceps","adductors"],"st":["Sit on the machine with your upper back against the pad and the belt across your hips.","Plant your feet flat, about hip width apart.","Drive through your heels and lift your hips until your torso and thighs are in line.","Squeeze your glutes at the top for a moment.","Lower with control and repeat, keeping your chin tucked."],"img":"opengym/2146.webp","gif":null,"ext":1},{"id":"2147","n":"lever hip thrust with resistance band","bp":"upper legs","eq":"leverage machine","tg":"glutes","mg":"hamstrings","sm":["hamstrings","adductors","quadriceps"],"st":["Sit on the machine with your upper back on the pad and a band around your thighs above the knees.","Place your feet flat and push your knees gently out against the band.","Drive through your heels and lift your hips until your torso and thighs are in line.","Squeeze your glutes at the top.","Lower slowly and repeat, keeping the knees pressed out."],"img":"opengym/2147.webp","gif":null,"ext":1},{"id":"2148","n":"lever single leg hip thrust","bp":"upper legs","eq":"leverage machine","tg":"glutes","mg":"hamstrings","sm":["hamstrings","core","quadriceps"],"st":["Sit on the machine with your upper back on the pad and the belt across your hips.","Plant one foot flat and lift the other leg off the floor.","Drive through the planted heel and raise your hips until your torso is level.","Squeeze your glute at the top, keeping your hips level.","Lower with control, finish your reps, then switch legs."],"img":"opengym/2148.webp","gif":null,"ext":1},{"id":"2149","n":"resistance band bent leg kickback (kneeling)","bp":"upper legs","eq":"resistance band","tg":"glutes","mg":"hamstrings","sm":["hamstrings","core"],"st":["Anchor the band low and loop it around one foot, then get on all fours.","Keep your back flat and your core braced.","Press the foot with the bent knee up toward the ceiling against the band.","Squeeze your glute at the top without arching your lower back.","Lower slowly, finish your reps, then switch legs."],"img":"opengym/2149.webp","gif":null,"ext":1},{"id":"2150","n":"resistance band clam","bp":"upper legs","eq":"band","tg":"glutes","mg":"hip flexors","sm":["hip flexors","obliques"],"st":["Lie on your side with a loop band just above your knees and knees bent.","Stack your hips and keep your feet together.","Open the top knee away from the bottom one like a clam.","Keep your pelvis still and do not roll backward.","Lower the knee slowly.","Complete the reps, then switch sides."],"img":"opengym/2150.webp","gif":null,"ext":1},{"id":"2151","n":"resistance band external rotation","bp":"shoulders","eq":"resistance band","tg":"delts","mg":"rotator cuff","sm":["rotator cuff","rear deltoids","upper back"],"st":["Anchor a band at elbow height and stand sideways to it.","Hold the handle with the hand farther from the anchor.","Tuck your elbow against your side with the elbow bent to 90 degrees.","Rotate your forearm outward, away from your belly.","Return slowly to the start.","Finish the reps, then switch arms."],"img":"opengym/2151.webp","gif":null,"ext":1},{"id":"2152","n":"resistance band front plank with kicked leg","bp":"waist","eq":"resistance band","tg":"glutes","mg":"core","sm":["core","shoulders","hamstrings"],"st":["Place a band around your feet or ankles and get into a forearm or high plank.","Brace your core so your body forms a straight line.","Kick one leg back and up against the band without shifting your hips.","Return the leg with control.","Alternate legs, keeping your hips level throughout."],"img":"opengym/2152.webp","gif":null,"ext":1},{"id":"2153","n":"resistance band full squat","bp":"upper legs","eq":"resistance band","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","adductors","calves"],"st":["Stand on the band with your feet shoulder width apart and hold the handles at your shoulders.","Keep your chest up and your core braced.","Sit your hips back and down into a full squat.","Keep your knees tracking over your toes and heels on the floor.","Drive up through your feet to stand tall."],"img":"opengym/2153.webp","gif":null,"ext":1},{"id":"2154","n":"resistance band glute bridge","bp":"upper legs","eq":"resistance band","tg":"glutes","mg":"hamstrings","sm":["hamstrings","core","adductors"],"st":["Lie on your back with your knees bent and a band around your thighs just above the knees.","Place your feet flat, hip width apart.","Push your knees gently out against the band.","Drive through your heels and lift your hips until your body forms a straight line.","Squeeze your glutes, then lower slowly and repeat."],"img":"opengym/2154.webp","gif":null,"ext":1},{"id":"2155","n":"resistance band kneeling side plank","bp":"waist","eq":"resistance band","tg":"obliques","mg":"abdominals","sm":["abdominals","glutes","shoulders"],"st":["Wrap a band around your thighs and lie on one side with your knees bent.","Place your elbow under your shoulder.","Lift your hips so your body forms a straight line from knees to head.","Push your top knee gently out against the band.","Hold for 20-30 seconds, then switch sides."],"img":"opengym/2155.webp","gif":null,"ext":1},{"id":"2157","n":"resistance band lying leg raise","bp":"upper legs","eq":"resistance band","tg":"abductors","mg":"glutes","sm":["glutes","hip flexors","core"],"st":["Place a band around your thighs or ankles and lie on your side with your legs straight.","Rest your head on your arm and keep your hips stacked.","Raise the top leg against the band without rolling backward.","Pause at the top.","Lower slowly, finish your reps, then switch sides."],"img":"opengym/2157.webp","gif":null,"ext":1},{"id":"2158","n":"resistance band one leg glute bridge with straight leg","bp":"upper legs","eq":"resistance band","tg":"glutes","mg":"hamstrings","sm":["hamstrings","core","quadriceps"],"st":["Lie on your back with a band around your thighs and one knee bent, foot flat.","Extend the other leg straight, in line with your thigh.","Drive through the planted heel and lift your hips.","Keep your hips level and squeeze your glute at the top.","Lower slowly, finish your reps, then switch legs."],"img":"opengym/2158.webp","gif":null,"ext":1},{"id":"2159","n":"resistance band one leg glute bridge","bp":"upper legs","eq":"band","tg":"glutes","mg":"hamstrings","sm":["hamstrings","core","lower back"],"st":["Lie on your back with a loop band above your knees and knees bent.","Lift one foot off the floor and extend that leg.","Drive through the other heel and lift your hips.","Squeeze the glutes at the top and keep the hips level.","Lower with control.","Finish the reps, then switch legs."],"img":"opengym/2159.webp","gif":null,"ext":1},{"id":"2161","n":"resistance band one leg kickback","bp":"upper legs","eq":"resistance band","tg":"glutes","mg":"hamstrings","sm":["hamstrings","core"],"st":["Loop a band around your ankles or anchor it and loop it around one foot.","Stand holding a support, or get on all fours, with your core braced.","Kick one leg back against the band, keeping the knee straight.","Squeeze your glute and avoid arching your lower back.","Return slowly, finish your reps, then switch legs."],"img":"opengym/2161.webp","gif":null,"ext":1},{"id":"2162","n":"resistance band plank march","bp":"upper legs","eq":"band","tg":"abs","mg":"quadriceps","sm":["quadriceps","core","hip flexors","glutes"],"st":["Place a loop band around your thighs or ankles and get into a forearm or high plank.","Keep a straight line from head to heels.","Lift one knee toward your chest against the band.","Return it quietly and lift the other knee.","Keep your hips from rocking side to side.","Alternate for the planned time or reps."],"img":"opengym/2162.webp","gif":null,"ext":1},{"id":"2163","n":"resistance band reverse hyperextension","bp":"upper legs","eq":"band","tg":"glutes","mg":"hamstrings","sm":["hamstrings","lower back","core"],"st":["Lie face down over a bench or box with a band anchored near your feet.","Hold the bench edge and loop the band around your ankles.","Squeeze your glutes and lift your legs until they are in line with your body.","Avoid swinging or arching the lower back.","Lower the legs slowly.","Repeat for the planned reps."],"img":"opengym/2163.webp","gif":null,"ext":1},{"id":"2164","n":"resistance band side plank","bp":"waist","eq":"resistance band","tg":"obliques","mg":"abdominals","sm":["abdominals","glutes","shoulders"],"st":["Place a band around your thighs and lie on one side with your legs straight.","Put your elbow under your shoulder.","Lift your hips so your body forms a straight line from head to feet.","Press your top leg gently up against the band.","Hold for 20-30 seconds, then switch sides."],"img":"opengym/2164.webp","gif":null,"ext":1},{"id":"2165","n":"resistance band side walk","bp":"upper legs","eq":"resistance band","tg":"abductors","mg":"glutes","sm":["glutes","quadriceps","calves"],"st":["Place a band around your thighs or ankles and stand with your feet hip width apart.","Bend your knees slightly into a quarter squat.","Step sideways with the lead foot, keeping tension on the band.","Bring the trailing foot in without letting the feet touch.","Take 10-15 steps one way, then walk back the other way."],"img":"opengym/2165.webp","gif":null,"ext":1},{"id":"2166","n":"resistance band supine hip bridge march","bp":"upper legs","eq":"resistance band","tg":"glutes","mg":"hamstrings","sm":["hamstrings","core","hip flexors"],"st":["Lie on your back with a band around your thighs and your knees bent.","Lift your hips into a bridge and squeeze your glutes.","Lift one foot off the floor, drawing the knee toward your chest.","Lower it and lift the other foot, keeping your hips level.","Continue alternating at a steady pace, then lower your hips."],"img":"opengym/2166.webp","gif":null,"ext":1},{"id":"2192","n":"elliptical machine walk","bp":"cardio","eq":"elliptical machine","tg":"cardiovascular system","mg":"quadriceps","sm":["quadriceps","glutes","hamstrings"],"st":["Step onto the pedals and hold the handles.","Start walking forward in a smooth rhythm.","Stand tall and keep your shoulders relaxed.","Set a resistance and pace you can keep up while breathing steadily.","Continue for 15-45 minutes.","Slow down for a minute before you step off."],"img":"opengym/2192.webp","gif":null,"ext":1},{"id":"2193","n":"bicycle recline walk","bp":"cardio","eq":"stationary bike","tg":"cardiovascular system","mg":"quadriceps","sm":["quadriceps","hamstrings","glutes"],"st":["Sit on the recumbent bike and adjust the seat so your knees stay slightly bent at full extension.","Place your feet on the pedals and hold the handles.","Pedal at an easy, walking-like pace.","Keep your back against the backrest and breathe steadily.","Continue for 15-30 minutes.","Cool down by slowing the pedalling gradually."],"img":"opengym/2193.webp","gif":null,"ext":1},{"id":"2198","n":"lever triceps extension v. 3","bp":"upper arms","eq":"leverage machine","tg":"triceps","mg":"shoulders","sm":["shoulders","forearms"],"st":["Adjust the seat and sit with your upper arms on the pad.","Grip the handles with your elbows bent.","Press down by straightening your elbows.","Squeeze your triceps at the bottom.","Return slowly to the start without lifting your shoulders.","Repeat for the planned reps."],"img":"opengym/2198.webp","gif":null,"ext":1},{"id":"2200","n":"roll hip thrust","bp":"upper legs","eq":"stability ball","tg":"glutes","mg":"hamstrings","sm":["hamstrings","core","lower back"],"st":["Lie on your back with your heels on a stability ball and your arms by your sides.","Brace your core and press your heels into the ball.","Lift your hips until your body forms a straight line from shoulders to knees.","Squeeze your glutes at the top for a second.","Lower your hips slowly without letting the ball drift away.","Repeat for the planned reps, keeping the ball steady."],"img":"opengym/2200.webp","gif":null,"ext":1},{"id":"2224","n":"sled 45 degrees leg press","bp":"upper legs","eq":"sled machine","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","adductors","calves"],"st":["Sit in the seat with your back and head flat against the pad.","Place your feet shoulder-width apart in the middle of the platform.","Release the safety handles and lower the sled until your knees are bent to about 90 degrees.","Keep your lower back pressed into the pad as you descend.","Push through your whole foot to extend your legs without locking your knees.","Lower under control and repeat."],"img":"opengym/2224.webp","gif":null,"ext":1},{"id":"2234","n":"dumbbell standing lateral raise","bp":"shoulders","eq":"dumbbell","tg":"delts","mg":"trapezius","sm":["trapezius","rotator cuff"],"st":["Stand tall with a dumbbell in each hand at your sides, palms facing in.","Keep a slight bend in your elbows and brace your core.","Raise both arms out to the sides until they reach shoulder height.","Lead with your elbows and avoid shrugging.","Pause briefly at the top.","Lower slowly to the start and repeat."],"img":"opengym/2234.webp","gif":null,"ext":1},{"id":"2258","n":"walking","bp":"cardio","eq":"body weight","tg":"cardiovascular system","mg":"quadriceps","sm":["quadriceps","hamstrings","calves"],"st":["Stand tall with your shoulders relaxed and your gaze ahead.","Start walking with a natural stride.","Swing your arms gently opposite to your legs.","Land softly on your heel and roll through to the toes.","Keep a pace that lets you breathe comfortably.","Walk for 20-60 minutes."],"img":"opengym/2258.webp","gif":null,"ext":1},{"id":"2265","n":"lever seated row v. 2","bp":"back","eq":"leverage machine","tg":"upper back","mg":"lats","sm":["lats","rhomboids","biceps"],"st":["Adjust the seat and chest pad, then sit with your chest against the pad.","Grip the handles with arms extended.","Pull the handles toward your torso by driving the elbows back.","Squeeze your shoulder blades together.","Return slowly until your arms are straight again.","Repeat for the planned reps."],"img":"opengym/2265.webp","gif":null,"ext":1},{"id":"2266","n":"lever back extension v. 2","bp":"back","eq":"leverage machine","tg":"spine","mg":"glutes","sm":["glutes","hamstrings"],"st":["Adjust the machine and sit with your back against the pad.","Cross your arms or hold the handles as the machine allows.","Push back by extending at the hips and lower back.","Stop when your torso is in a neutral, tall position.","Return slowly to the start.","Repeat for the planned reps."],"img":"opengym/2266.webp","gif":null,"ext":1},{"id":"2267","n":"lever seated leg press","bp":"upper legs","eq":"leverage machine","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","calves"],"st":["Adjust the seat and sit with your back flat against the pad.","Place your feet on the platform about shoulder-width apart.","Push through your heels until your legs are nearly straight.","Do not lock your knees.","Bend your knees slowly to return.","Repeat for the planned reps."],"img":"opengym/2267.webp","gif":null,"ext":1},{"id":"2268","n":"lever seated crunch (hands pad)","bp":"waist","eq":"leverage machine","tg":"abs","mg":"obliques","sm":["obliques","hip flexors"],"st":["Sit on the machine and adjust the seat so your hands reach the pad.","Place your hands on the pads and brace your feet.","Curl your torso forward by contracting your abs.","Pause briefly at the bottom.","Return slowly to the upright start.","Repeat for the planned reps."],"img":"opengym/2268.webp","gif":null,"ext":1},{"id":"2269","n":"ab roller crunch","bp":"waist","eq":"wheel roller","tg":"abs","mg":"lower abs","sm":["lower abs","core","shoulders"],"st":["Kneel on a mat and hold the ab wheel with both hands in front of your knees.","Round your lower back slightly and brace your abs.","Roll forward a short distance while keeping your hips stable.","Pull the wheel back toward your knees by curling your ribs toward your hips.","Exhale as you crunch and avoid arching your back.","Repeat with smooth control."],"img":"opengym/2269.webp","gif":null,"ext":1},{"id":"2272","n":"boxing jab","bp":"shoulders","eq":"body weight","tg":"delts","mg":"triceps","sm":["triceps","chest","core"],"st":["Stand in a boxing stance with your lead foot forward and hands up by your chin.","Extend your lead hand straight toward the target.","Rotate your fist so the palm faces down as it lands.","Keep your chin tucked and your rear hand guarding.","Snap the hand back to the guard quickly.","Repeat, then switch stance if you want."],"img":"opengym/2272.webp","gif":null,"ext":1},{"id":"2273","n":"boxing right cross","bp":"shoulders","eq":"body weight","tg":"delts","mg":"triceps","sm":["triceps","chest","core"],"st":["Stand in a boxing stance with hands up.","Push off the back foot and rotate your hips and shoulders.","Throw your rear hand straight toward the target.","Keep your lead hand up to protect your chin.","Pull the hand back along the same line.","Return to your stance and repeat."],"img":"opengym/2273.webp","gif":null,"ext":1},{"id":"2274","n":"boxing right uppercut","bp":"shoulders","eq":"body weight","tg":"delts","mg":"biceps","sm":["biceps","core","chest"],"st":["Stand in a boxing stance with hands up.","Bend your knees slightly and dip your right side.","Drive up through your legs as you rotate your hips.","Throw your right fist upward with the palm facing you.","Keep your left hand guarding your chin.","Return to stance and repeat."],"img":"opengym/2274.webp","gif":null,"ext":1},{"id":"2275","n":"boxing left uppercut","bp":"shoulders","eq":"body weight","tg":"delts","mg":"biceps","sm":["biceps","core","chest"],"st":["Stand in a boxing stance with hands up.","Bend your knees slightly and dip your left side.","Drive up through your legs as you rotate your hips.","Throw your left fist upward with the palm facing you.","Keep your right hand guarding your chin.","Return to stance and repeat."],"img":"opengym/2275.webp","gif":null,"ext":1},{"id":"2276","n":"lever lying crunch","bp":"waist","eq":"leverage machine","tg":"abs","mg":"obliques","sm":["obliques","hip flexors"],"st":["Lie back on the machine and place your hands or arms as indicated.","Hook your feet or grip the handles for stability.","Curl your torso up by contracting your abs.","Pause briefly at the top.","Lower slowly back to the start.","Repeat for the planned reps."],"img":"opengym/2276.webp","gif":null,"ext":1},{"id":"2277","n":"lever chest press v. 4","bp":"chest","eq":"leverage machine","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders","upper chest"],"st":["Adjust the seat so the handles are at mid-chest height.","Sit back with your shoulder blades pulled together.","Press the handles forward until your arms are almost straight.","Do not lock your elbows.","Return slowly until you feel a stretch in the chest.","Repeat for the planned reps."],"img":"opengym/2277.webp","gif":null,"ext":1},{"id":"2278","n":"lever decline chest press v. 2","bp":"chest","eq":"leverage machine","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders"],"st":["Adjust the seat and sit with your back against the pad.","Grip the handles with elbows bent.","Press forward and slightly downward until your arms are almost straight.","Keep your shoulders down and your chest up.","Return slowly under control.","Repeat for the planned reps."],"img":"opengym/2278.webp","gif":null,"ext":1},{"id":"2279","n":"stationary bike run v. 4","bp":"cardio","eq":"stationary bike","tg":"cardiovascular system","mg":"quadriceps","sm":["quadriceps","hamstrings","glutes"],"st":["Adjust the seat so your knees stay slightly bent at the bottom of the stroke.","Hold the handles and sit tall.","Start pedalling at an easy pace to warm up.","Raise the speed to a brisk rhythm you can sustain.","Keep your upper body relaxed.","Continue for 10-30 minutes, then slow down to cool off."],"img":"opengym/2279.webp","gif":null,"ext":1},{"id":"2282","n":"lever neck extension (plate loaded)","bp":"neck","eq":"leverage machine","tg":"levator scapulae","mg":"trapezius","sm":["trapezius","sternocleidomastoid"],"st":["Set the weight light and adjust the pad to rest on the back of your head.","Sit tall and bring your chin slightly down.","Press your head back against the pad slowly.","Move only through a comfortable range.","Return slowly to the start.","Repeat for the planned reps with control."],"img":"opengym/2282.webp","gif":null,"ext":1},{"id":"2283","n":"lever neck left side flexion (plate loaded)","bp":"neck","eq":"leverage machine","tg":"levator scapulae","mg":"trapezius","sm":["trapezius","sternocleidomastoid"],"st":["Set the weight light and position the pad against the left side of your head.","Sit tall with your shoulders relaxed.","Tilt your head to the left against the resistance.","Keep the movement small and smooth.","Return slowly to the centre.","Repeat for the planned reps with control."],"img":"opengym/2283.webp","gif":null,"ext":1},{"id":"2284","n":"lever neck right side flexion (plate loaded)","bp":"neck","eq":"leverage machine","tg":"levator scapulae","mg":"trapezius","sm":["trapezius","sternocleidomastoid"],"st":["Set the weight light and position the pad against the right side of your head.","Sit tall with your shoulders relaxed.","Tilt your head to the right against the resistance.","Keep the movement small and smooth.","Return slowly to the centre.","Repeat for the planned reps with control."],"img":"opengym/2284.webp","gif":null,"ext":1},{"id":"2290","n":"dumbbell bulgarian split squat","bp":"upper legs","eq":"dumbbell","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","adductors","core"],"st":["Stand a stride length in front of a bench holding a dumbbell in each hand.","Rest the top of your back foot on the bench.","Lower straight down until your front thigh is about parallel to the floor.","Keep your torso upright and your front knee tracking over your toes.","Drive through your front heel to stand back up.","Finish all reps, then switch legs."],"img":"opengym/2290.webp","gif":null,"ext":1},{"id":"2291","n":"cable wide grip lat pulldown","bp":"back","eq":"cable","tg":"lats","mg":"biceps","sm":["biceps","rhomboids","upper back","forearms"],"st":["Sit at the pulldown station and secure your thighs under the pads.","Grab the bar with a wide overhand grip.","Lean back slightly and pull the bar down to your upper chest.","Drive your elbows down and back, squeezing your shoulder blades.","Control the bar back up until your arms are fully extended.","Avoid swinging your torso."],"img":"opengym/2291.webp","gif":null,"ext":1},{"id":"2296","n":"stability ball rollout","bp":"waist","eq":"stability ball","tg":"abs","mg":"lower abs","sm":["lower abs","core","shoulders","lats"],"st":["Kneel in front of a stability ball and place your forearms on it.","Brace your abs and keep your body in a straight line from knees to head.","Roll the ball forward by extending your arms and body.","Stop when you feel your core working hard without your back sagging.","Pull the ball back by squeezing your abs.","Repeat slowly."],"img":"opengym/2296.webp","gif":null,"ext":1},{"id":"2301","n":"rear leg hook kick","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"hamstrings","sm":["hamstrings","hip flexors","core"],"st":["Stand in a fighting stance with your hands up.","Shift your weight onto the lead foot.","Lift the rear knee and extend the leg across the target.","Hook the heel around in an arc.","Bring the leg back under control.","Return to stance and repeat, then switch sides."],"img":"opengym/2301.webp","gif":null,"ext":1},{"id":"2302","n":"front leg hook kick","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"hamstrings","sm":["hamstrings","hip flexors","core"],"st":["Stand in a fighting stance with your hands up.","Lift the lead knee and point it forward.","Extend the leg and hook the heel across the target.","Keep your supporting foot grounded and your core tight.","Bring the leg back under control.","Return to stance and repeat, then switch sides."],"img":"opengym/2302.webp","gif":null,"ext":1},{"id":"2303","n":"front groin kick","bp":"upper legs","eq":"body weight","tg":"quads","mg":"glutes","sm":["glutes","hip flexors","core"],"st":["Stand in a fighting stance with your hands up.","Lift your knee in front of you.","Snap the lower leg forward and low.","Keep your torso upright and balanced.","Pull the leg back quickly.","Return to stance and repeat, then switch legs."],"img":"opengym/2303.webp","gif":null,"ext":1},{"id":"2304","n":"rear axe kick","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"hamstrings","sm":["hamstrings","hip flexors","core"],"st":["Stand in a fighting stance with your hands up.","Swing your rear leg straight up in front of you.","Reach the top with the leg extended.","Bring the heel sharply down.","Keep your supporting leg slightly bent and balanced.","Return to stance and repeat, then switch sides."],"img":"opengym/2304.webp","gif":null,"ext":1},{"id":"2305","n":"front snap kick","bp":"upper legs","eq":"body weight","tg":"quads","mg":"glutes","sm":["glutes","hip flexors","core"],"st":["Stand in a fighting stance with your hands up.","Lift your knee toward your chest.","Snap your lower leg forward to the target.","Pull the leg back quickly along the same line.","Keep your supporting foot grounded.","Return to stance and repeat, then switch legs."],"img":"opengym/2305.webp","gif":null,"ext":1},{"id":"2306","n":"spin hook kick","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"hamstrings","sm":["hamstrings","core","calves"],"st":["Stand in a fighting stance with your hands up.","Turn your head and shoulders to look behind you.","Spin on the ball of your supporting foot.","Swing your kicking leg around and hook the heel across the target.","Land in a balanced stance.","Repeat, then switch sides."],"img":"opengym/2306.webp","gif":null,"ext":1},{"id":"2307","n":"side kick","bp":"upper legs","eq":"body weight","tg":"abductors","mg":"glutes","sm":["glutes","quadriceps","core"],"st":["Stand sideways in a fighting stance with your hands up.","Lift your knee toward your chest.","Extend the leg sideways and push the heel to the target.","Keep your supporting foot turned slightly away.","Pull the leg back and set it down.","Repeat, then switch legs."],"img":"opengym/2307.webp","gif":null,"ext":1},{"id":"2308","n":"roundhouse kick","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"quadriceps","sm":["quadriceps","core","hip flexors"],"st":["Stand in a fighting stance with your hands up.","Pivot on your supporting foot and turn the hip over.","Lift the knee and swing the leg in an arc across the target.","Extend the lower leg at the end.","Pull the leg back and return to stance.","Repeat, then switch legs."],"img":"opengym/2308.webp","gif":null,"ext":1},{"id":"2309","n":"heel push kick","bp":"upper legs","eq":"body weight","tg":"quads","mg":"glutes","sm":["glutes","hip flexors","core"],"st":["Stand in a fighting stance with your hands up.","Lift the knee and point the toes up.","Push your heel straight forward, leaning back slightly.","Keep your supporting foot grounded.","Bring the leg back and set it down.","Repeat, then switch legs."],"img":"opengym/2309.webp","gif":null,"ext":1},{"id":"2310","n":"spin back kick","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"hamstrings","sm":["hamstrings","core","calves"],"st":["Stand in a fighting stance with your hands up.","Turn your head and shoulders to look behind you.","Pivot on your supporting foot.","Kick your leg straight back with the heel leading.","Keep your torso leaning slightly forward for balance.","Return to stance and repeat, then switch sides."],"img":"opengym/2310.webp","gif":null,"ext":1},{"id":"2314","n":"lever lying crunch v. 2","bp":"waist","eq":"leverage machine","tg":"abs","mg":"lower abs","sm":["lower abs","obliques","hip flexors"],"st":["Lie back on the machine and set your feet or hands as the machine requires.","Grip the handles lightly and set your lower back against the pad.","Curl your ribs toward your hips to crunch up.","Exhale and squeeze your abs at the top.","Lower slowly without letting the weight stack rest.","Repeat for the planned reps."],"img":"opengym/2314.webp","gif":null,"ext":1},{"id":"2323","n":"dumbbells sumo squat","bp":"upper legs","eq":"dumbbell","tg":"glutes","mg":"quadriceps","sm":["quadriceps","adductors","inner thighs","hamstrings"],"st":["Stand with your feet wider than your shoulders and toes pointing out.","Hold one or two dumbbells with both hands in front of you.","Sit your hips down and back, keeping your chest up.","Lower until your thighs are about parallel to the floor.","Push through your heels and squeeze your glutes to stand.","Keep your knees in line with your toes."],"img":"opengym/2323.webp","gif":null,"ext":1},{"id":"2324","n":"cable straight legs pull through (with rope)","bp":"upper legs","eq":"cable","tg":"glutes","mg":"hamstrings","sm":["hamstrings","lower back","core"],"st":["Attach a rope to a low pulley and stand facing away from the stack.","Reach through your legs and grab the rope, then step forward to add tension.","Keep your legs nearly straight and hinge forward at the hips.","Drive your hips forward to stand tall while the rope passes between your legs.","Squeeze your glutes at the top.","Hinge back with control and repeat."],"img":"opengym/2324.webp","gif":null,"ext":1},{"id":"2325","n":"dumbbell pronated to neutral grip row","bp":"back","eq":"dumbbell","tg":"upper back","mg":"lats","sm":["lats","rhomboids","biceps","rear deltoids"],"st":["Hinge forward with a flat back, holding dumbbells with an overhand grip.","Let your arms hang straight below your shoulders.","Row the weights toward your hips while rotating your palms to face each other.","Squeeze your shoulder blades together at the top.","Lower the dumbbells slowly while turning your palms back down.","Keep your torso still."],"img":"opengym/2325.webp","gif":null,"ext":1},{"id":"2326","n":"dumbbell pronated grip row","bp":"back","eq":"dumbbell","tg":"upper back","mg":"lats","sm":["lats","rhomboids","biceps","rear deltoids"],"st":["Hold a dumbbell in each hand and hinge forward with a flat back.","Let your arms hang with palms facing your legs.","Pull the dumbbells up toward your lower ribs.","Keep your elbows close to your body and squeeze your shoulder blades.","Lower slowly until your arms are straight.","Avoid jerking with your torso."],"img":"opengym/2326.webp","gif":null,"ext":1},{"id":"2336","n":"barbell chest bench press forearms (form check)","bp":"chest","eq":"barbell","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders","forearms"],"st":["Lie on a bench with your eyes under the bar and your feet planted.","Grip the bar slightly wider than shoulder-width.","Keep your forearms vertical when the bar is at your chest.","Lower the bar with control to the mid-chest.","Press it up to straight arms without flaring the elbows.","Repeat for the planned reps."],"img":"opengym/2336.webp","gif":null,"ext":1},{"id":"2337","n":"dumbbell chest fly arms (form check)","bp":"chest","eq":"dumbbell","tg":"pectorals","mg":"shoulders","sm":["shoulders","upper chest","biceps"],"st":["Lie on a bench with a dumbbell in each hand above your chest.","Keep a slight bend in your elbows.","Lower your arms out to the sides in a wide arc.","Stop when you feel a gentle stretch across the chest.","Bring the dumbbells back together above your chest.","Repeat for the planned reps."],"img":"opengym/2337.webp","gif":null,"ext":1},{"id":"2338","n":"chest bench press butt (form check)","bp":"chest","eq":"barbell","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders"],"st":["Lie on the bench with your eyes under the bar and your feet flat on the floor.","Compare the faulty version with the correct one: your hips stay planted on the pad and never lift off.","Perform the lift slowly with a light load and keep the correct position throughout.","Use a mirror or film a set from the side to check your own position.","Fix the cue before adding weight, and rest between sets so form stays clean."],"img":"opengym/2338.webp","gif":null,"ext":1},{"id":"2339","n":"chest bench press grip width (form check)","bp":"chest","eq":"barbell","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders"],"st":["Lie on the bench and grip the bar at a moderate width.","Compare the faulty version with the correct one: your forearms are vertical at the bottom, with hands just wider than the shoulders.","Perform the lift slowly with a light load and keep the correct position throughout.","Use a mirror or film a set from the side to check your own position.","Fix the cue before adding weight, and rest between sets so form stays clean."],"img":"opengym/2339.webp","gif":null,"ext":1},{"id":"2340","n":"chest bench press shoulders (form check)","bp":"chest","eq":"barbell","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders"],"st":["Lie on the bench and pinch your shoulder blades together before unracking.","Compare the faulty version with the correct one: your shoulder blades stay pulled back and down against the bench.","Perform the lift slowly with a light load and keep the correct position throughout.","Use a mirror or film a set from the side to check your own position.","Fix the cue before adding weight, and rest between sets so form stays clean."],"img":"opengym/2340.webp","gif":null,"ext":1},{"id":"2341","n":"chest bench press arms (form check)","bp":"chest","eq":"barbell","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders"],"st":["Lie on the bench and unrack the bar over your shoulders.","Compare the faulty version with the correct one: your arms move in a controlled line and the bar tracks over the lower chest.","Perform the lift slowly with a light load and keep the correct position throughout.","Use a mirror or film a set from the side to check your own position.","Fix the cue before adding weight, and rest between sets so form stays clean."],"img":"opengym/2341.webp","gif":null,"ext":1},{"id":"2342","n":"chest bench press elbows (form check)","bp":"chest","eq":"barbell","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders"],"st":["Lie on the bench with the bar unracked above your chest.","Compare the faulty version with the correct one: your elbows sit at roughly 45 degrees from the torso instead of flaring wide.","Perform the lift slowly with a light load and keep the correct position throughout.","Use a mirror or film a set from the side to check your own position.","Fix the cue before adding weight, and rest between sets so form stays clean."],"img":"opengym/2342.webp","gif":null,"ext":1},{"id":"2343","n":"bent over row back (form check)","bp":"back","eq":"barbell","tg":"upper back","mg":"lats","sm":["lats","biceps","lower back"],"st":["Hold the bar and hinge forward at the hips with soft knees.","Compare the faulty version with the correct one: your spine stays long and flat, not rounded.","Perform the lift slowly with a light load and keep the correct position throughout.","Use a mirror or film a set from the side to check your own position.","Fix the cue before adding weight, and rest between sets so form stays clean."],"img":"opengym/2343.webp","gif":null,"ext":1},{"id":"2344","n":"crunch back (form check)","bp":"waist","eq":"body weight","tg":"abs","mg":"obliques","sm":["obliques","hip flexors"],"st":["Lie on your back with knees bent and hands by your head.","Compare the faulty version with the correct one: your lower back stays gently on the floor while only the upper back curls up.","Perform the lift slowly with a light load and keep the correct position throughout.","Use a mirror or film a set from the side to check your own position.","Fix the cue before adding weight, and rest between sets so form stays clean."],"img":"opengym/2344.webp","gif":null,"ext":1},{"id":"2345","n":"sled hack squat legs (form check)","bp":"upper legs","eq":"sled machine","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","calves"],"st":["Set your back and shoulders against the pads and place your feet on the platform.","Compare the faulty version with the correct one: your knees track over your toes and your feet sit flat on the platform.","Perform the lift slowly with a light load and keep the correct position throughout.","Use a mirror or film a set from the side to check your own position.","Fix the cue before adding weight, and rest between sets so form stays clean."],"img":"opengym/2345.webp","gif":null,"ext":1},{"id":"2346","n":"bench dip back arms (form check)","bp":"upper arms","eq":"body weight","tg":"triceps","mg":"chest","sm":["chest","shoulders"],"st":["Sit on the edge of a bench, grip it beside your hips and slide your butt off.","Compare the faulty version with the correct one: your back stays close to the bench and your elbows point straight behind you.","Perform the lift slowly with a light load and keep the correct position throughout.","Use a mirror or film a set from the side to check your own position.","Fix the cue before adding weight, and rest between sets so form stays clean."],"img":"opengym/2346.webp","gif":null,"ext":1},{"id":"2347","n":"front plank butt (form check)","bp":"waist","eq":"body weight","tg":"abs","mg":"core","sm":["core","glutes","shoulders","lower back"],"st":["Place your forearms on the floor with elbows under your shoulders.","Extend your legs behind you with your toes on the floor.","Lift your body into a straight line from head to heels.","Avoid pushing your butt up or letting your hips sag.","Squeeze your abs and glutes to keep the line.","Hold for 20-40 seconds and breathe steadily."],"img":"opengym/2347.webp","gif":null,"ext":1},{"id":"2348","n":"preacher curl wrists (form check)","bp":"upper arms","eq":"ez barbell","tg":"biceps","mg":"forearms","sm":["forearms","brachialis"],"st":["Sit at the preacher bench with your upper arms flat on the pad.","Compare the faulty version with the correct one: your wrists stay neutral and straight rather than bending back or curling in.","Perform the lift slowly with a light load and keep the correct position throughout.","Use a mirror or film a set from the side to check your own position.","Fix the cue before adding weight, and rest between sets so form stays clean."],"img":"opengym/2348.webp","gif":null,"ext":1},{"id":"2349","n":"side plank butt (form check)","bp":"waist","eq":"body weight","tg":"obliques","mg":"core","sm":["core","glutes","shoulders"],"st":["Lie on your side with your forearm on the floor and elbow under your shoulder.","Stack your feet and lift your hips off the floor.","Make a straight line from your head to your feet.","Avoid letting your butt stick out or your hips drop.","Squeeze your abs and glutes to stay level.","Hold for 20-30 seconds, then switch sides."],"img":"opengym/2349.webp","gif":null,"ext":1},{"id":"2350","n":"push up start position (form check)","bp":"chest","eq":"body weight","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders","core"],"st":["Set your hands on the floor under your shoulders and extend your legs back.","Compare the faulty version with the correct one: your body forms one straight line from head to heels with hands under the shoulders.","Perform the lift slowly with a light load and keep the correct position throughout.","Use a mirror or film a set from the side to check your own position.","Fix the cue before adding weight, and rest between sets so form stays clean."],"img":"opengym/2350.webp","gif":null,"ext":1},{"id":"2351","n":"push up end position (form check)","bp":"chest","eq":"body weight","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders","core"],"st":["Start in a high plank and lower yourself under control.","Compare the faulty version with the correct one: your chest nearly touches the floor, elbows angled back, and hips stay in line.","Perform the lift slowly with a light load and keep the correct position throughout.","Use a mirror or film a set from the side to check your own position.","Fix the cue before adding weight, and rest between sets so form stays clean."],"img":"opengym/2351.webp","gif":null,"ext":1},{"id":"2352","n":"biceps curl arms body (form check)","bp":"upper arms","eq":"dumbbell","tg":"biceps","mg":"forearms","sm":["forearms","brachialis"],"st":["Stand tall holding dumbbells at your sides with palms forward.","Compare the faulty version with the correct one: your elbows stay pinned at your sides and your torso does not swing.","Perform the lift slowly with a light load and keep the correct position throughout.","Use a mirror or film a set from the side to check your own position.","Fix the cue before adding weight, and rest between sets so form stays clean."],"img":"opengym/2352.webp","gif":null,"ext":1},{"id":"2353","n":"concentration curl arms (form check)","bp":"upper arms","eq":"dumbbell","tg":"biceps","mg":"forearms","sm":["forearms","brachialis"],"st":["Sit on a bench, lean forward and brace your elbow against your inner thigh.","Compare the faulty version with the correct one: your upper arm rests against the inner thigh and only the forearm moves.","Perform the lift slowly with a light load and keep the correct position throughout.","Use a mirror or film a set from the side to check your own position.","Fix the cue before adding weight, and rest between sets so form stays clean."],"img":"opengym/2353.webp","gif":null,"ext":1},{"id":"2354","n":"deadlift back (form check)","bp":"upper legs","eq":"barbell","tg":"glutes","mg":"hamstrings","sm":["hamstrings","lower back","upper back"],"st":["Stand with the bar over mid-foot, hinge down and grip it just outside your legs.","Compare the faulty version with the correct one: your back stays neutral and braced from the floor to lockout.","Perform the lift slowly with a light load and keep the correct position throughout.","Use a mirror or film a set from the side to check your own position.","Fix the cue before adding weight, and rest between sets so form stays clean."],"img":"opengym/2354.webp","gif":null,"ext":1},{"id":"2357","n":"deadlift hips (form check)","bp":"upper legs","eq":"barbell","tg":"glutes","mg":"hamstrings","sm":["hamstrings","lower back","quadriceps"],"st":["Stand with the bar over mid-foot and set your hips at a mid height before gripping.","Compare the faulty version with the correct one: your hips start above the knees and rise together with your shoulders.","Perform the lift slowly with a light load and keep the correct position throughout.","Use a mirror or film a set from the side to check your own position.","Fix the cue before adding weight, and rest between sets so form stays clean."],"img":"opengym/2357.webp","gif":null,"ext":1},{"id":"2358","n":"plank butt (form check)","bp":"waist","eq":"body weight","tg":"abs","mg":"core","sm":["core","shoulders","glutes"],"st":["Set your forearms on the floor with elbows under the shoulders and legs extended.","Compare the faulty version with the correct one: your butt stays level with your shoulders, not piked up or sagging down.","Perform the lift slowly with a light load and keep the correct position throughout.","Use a mirror or film a set from the side to check your own position.","Fix the cue before adding weight, and rest between sets so form stays clean."],"img":"opengym/2358.webp","gif":null,"ext":1},{"id":"2359","n":"barbell squat knees end position (form check)","bp":"upper legs","eq":"barbell","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","adductors"],"st":["Set the bar on your upper back and descend into a full squat.","Compare the faulty version with the correct one: your knees push out over your toes and do not cave inward.","Perform the lift slowly with a light load and keep the correct position throughout.","Use a mirror or film a set from the side to check your own position.","Fix the cue before adding weight, and rest between sets so form stays clean."],"img":"opengym/2359.webp","gif":null,"ext":1},{"id":"2360","n":"squat knees middle position (form check)","bp":"upper legs","eq":"barbell","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","adductors"],"st":["Stand with feet shoulder width apart and begin to squat.","Compare the faulty version with the correct one: your knees keep tracking in line with your toes on the way up and down.","Perform the lift slowly with a light load and keep the correct position throughout.","Use a mirror or film a set from the side to check your own position.","Fix the cue before adding weight, and rest between sets so form stays clean."],"img":"opengym/2360.webp","gif":null,"ext":1},{"id":"2361","n":"barbell squat hips (form check)","bp":"upper legs","eq":"barbell","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","lower back"],"st":["Set the bar on your upper back and squat down to depth.","Compare the faulty version with the correct one: your hips and chest rise together, without the hips shooting up first.","Perform the lift slowly with a light load and keep the correct position throughout.","Use a mirror or film a set from the side to check your own position.","Fix the cue before adding weight, and rest between sets so form stays clean."],"img":"opengym/2361.webp","gif":null,"ext":1},{"id":"2362","n":"squat back (form check)","bp":"upper legs","eq":"barbell","tg":"quads","mg":"glutes","sm":["glutes","lower back","hamstrings"],"st":["Set the bar on your upper back, brace your core and squat down.","Compare the faulty version with the correct one: your back stays flat and braced without rounding at the bottom.","Perform the lift slowly with a light load and keep the correct position throughout.","Use a mirror or film a set from the side to check your own position.","Fix the cue before adding weight, and rest between sets so form stays clean."],"img":"opengym/2362.webp","gif":null,"ext":1},{"id":"2365","n":"dumbbells straight arm pullover v. 2","bp":"chest","eq":"dumbbell","tg":"lats","mg":"chest","sm":["chest","triceps","core"],"st":["Lie on a bench with your upper back supported and hold a dumbbell over your chest.","Keep your arms nearly straight with a slight bend in the elbows.","Lower the dumbbell in an arc behind your head until you feel a stretch.","Keep your ribs down and your hips stable.","Pull the dumbbell back over your chest using your lats.","Repeat with control."],"img":"opengym/2365.webp","gif":null,"ext":1},{"id":"2367","n":"dumbbell rear lunge from step","bp":"upper legs","eq":"dumbbell","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","core","calves"],"st":["Stand on a low step with a dumbbell in each hand.","Step one foot back and off the step.","Lower your back knee toward the floor while keeping your torso upright.","Keep your front knee over your ankle.","Push through your front heel to return to standing.","Finish your reps, then switch legs."],"img":"opengym/2367.webp","gif":null,"ext":1},{"id":"2375","n":"single leg squat with support","bp":"upper legs","eq":"body weight","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","adductors","core"],"st":["Stand next to a sturdy support and hold it lightly with one hand.","Lift one foot slightly off the floor in front of you.","Sit your hips back and lower on the standing leg.","Keep your knee tracking over your toes.","Push through your heel to stand back up.","Finish your reps, then switch legs."],"img":"opengym/2375.webp","gif":null,"ext":1},{"id":"2381","n":"dumbbell one arm shoulder press v. 3","bp":"shoulders","eq":"dumbbell","tg":"delts","mg":"triceps","sm":["triceps","upper chest","core"],"st":["Hold a dumbbell at shoulder height with your palm facing forward.","Stand or sit tall and brace your core.","Press the dumbbell overhead until your arm is straight.","Avoid leaning to the side.","Lower the dumbbell slowly back to your shoulder.","Finish your reps, then switch arms."],"img":"opengym/2381.webp","gif":null,"ext":1},{"id":"2394","n":"floor hyperextension","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"lower back","sm":["lower back","hamstrings","core"],"st":["Lie face down with your arms extended or by your head.","Squeeze your glutes and lift your chest and legs slightly off the floor.","Keep your neck neutral and look at the floor.","Pause at the top for a second.","Lower slowly to the floor.","Repeat without forcing a big arch."],"img":"opengym/2394.webp","gif":null,"ext":1},{"id":"2395","n":"air bike v. 2","bp":"waist","eq":"body weight","tg":"abs","mg":"obliques","sm":["obliques","hip flexors","lower abs"],"st":["Lie on your back with your hands behind your head.","Lift your shoulders and bring your knees up.","Bring one elbow toward the opposite knee while extending the other leg.","Switch sides in a smooth pedalling motion.","Keep your lower back pressed down.","Continue for the planned reps or time."],"img":"opengym/2395.webp","gif":null,"ext":1},{"id":"2396","n":"cable lying biceps curl v. 2","bp":"upper arms","eq":"cable","tg":"biceps","mg":"brachialis","sm":["brachialis","forearms"],"st":["Lie on your back on the floor facing the cable stack and hold the bar or handle with palms up.","Keep your upper arms still and pinned to the floor.","Curl the handle toward your shoulders, squeezing the biceps at the top.","Lower slowly until your arms are almost straight.","Keep your back flat and avoid lifting your shoulders as you curl."],"img":"opengym/2396.webp","gif":null,"ext":1},{"id":"2408","n":"weighted lying neck extension (with head harness)","bp":"neck","eq":"weighted","tg":"levator scapulae","mg":"upper back","sm":["upper back","trapezius"],"st":["Lie face down on a bench with your head past the edge and the weighted harness fitted.","Start with your chin tucked toward your chest.","Raise your head slowly until your face looks forward.","Pause, then lower back under control.","Use a light weight and smooth reps, never jerking the neck."],"img":"opengym/2408.webp","gif":null,"ext":1},{"id":"2409","n":"weighted lying neck flexion (with head harness)","bp":"neck","eq":"weighted","tg":"levator scapulae","mg":"upper back","sm":["upper back","trapezius"],"st":["Lie on your back on a bench with your head past the edge and the harness fitted.","Let your head hang back slightly in a comfortable range.","Curl your chin toward your chest slowly.","Pause briefly at the top.","Lower under control and keep the weight light with smooth reps."],"img":"opengym/2409.webp","gif":null,"ext":1},{"id":"2410","n":"weighted standing neck extension (with head harness)","bp":"neck","eq":"weighted","tg":"levator scapulae","mg":"upper back","sm":["upper back","trapezius"],"st":["Fit the head harness with a light weight hanging in front.","Stand and hinge forward, resting your hands on your thighs.","Let your chin drop toward your chest.","Lift your head until your gaze is forward.","Lower slowly and keep the movement small and controlled."],"img":"opengym/2410.webp","gif":null,"ext":1},{"id":"2411","n":"cable seated neck extension (with head harness)","bp":"neck","eq":"cable","tg":"levator scapulae","mg":"upper back","sm":["upper back","trapezius"],"st":["Fit the head harness and sit facing the cable with it attached at head height.","Start with your head tipped slightly forward.","Pull your head back until it is upright.","Pause, then return slowly against the cable.","Keep the load light and your shoulders relaxed."],"img":"opengym/2411.webp","gif":null,"ext":1},{"id":"2412","n":"cable seated neck flexion (with head harness)","bp":"neck","eq":"cable","tg":"levator scapulae","mg":"upper back","sm":["upper back","trapezius"],"st":["Fit the head harness and sit facing away from the cable, attached at head height.","Start with your head tilted slightly back.","Bring your chin toward your chest.","Pause, then return slowly in control.","Keep the load light and your shoulders relaxed."],"img":"opengym/2412.webp","gif":null,"ext":1},{"id":"2413","n":"barbell wide grip drag curl","bp":"upper arms","eq":"barbell","tg":"biceps","mg":"brachialis","sm":["brachialis","forearms","rear deltoids"],"st":["Stand holding a barbell with a wide underhand grip.","Keep your elbows pointing back and the bar close to your body.","Drag the bar up your torso by pulling your elbows behind you.","Squeeze your biceps at the top.","Lower slowly along the same path.","Keep your torso upright."],"img":"opengym/2413.webp","gif":null,"ext":1},{"id":"2415","n":"dumbbell single arm leaning lateral raise","bp":"shoulders","eq":"dumbbell","tg":"delts","mg":"trapezius","sm":["trapezius","rotator cuff"],"st":["Hold a support with one hand and lean your body away.","Hold a dumbbell in your free hand by your side.","Raise the dumbbell out to the side until it reaches shoulder height.","Keep a slight bend in your elbow.","Lower slowly to the start.","Finish your reps, then switch arms."],"img":"opengym/2415.webp","gif":null,"ext":1},{"id":"2417","n":"resistance band duck walk","bp":"upper legs","eq":"band","tg":"glutes","mg":"quadriceps","sm":["quadriceps","core"],"st":["Place a loop band around your thighs or knees.","Lower into a half squat with your chest up.","Step sideways or forward with a wide stride.","Keep tension on the band and your knees out.","Bring your other foot in, staying low.","Walk for the planned distance, then return."],"img":"opengym/2417.webp","gif":null,"ext":1},{"id":"2418","n":"resistance band bent leg side kick (kneeling)","bp":"upper legs","eq":"band","tg":"glutes","mg":"core","sm":["core","quadriceps"],"st":["Kneel on all fours with a band around your thighs.","Keep your core braced and your back flat.","Lift one bent leg out to the side against the band.","Pause when your thigh is about hip height.","Lower slowly without twisting your torso.","Finish your reps, then switch legs."],"img":"opengym/2418.webp","gif":null,"ext":1},{"id":"2419","n":"resistance band leg lift","bp":"upper legs","eq":"band","tg":"glutes","mg":"hamstrings","sm":["hamstrings","lower back"],"st":["Place a loop band around your ankles or thighs.","Get on all fours or stand with support.","Lift one leg back or out against the band.","Squeeze your glutes at the top.","Lower slowly without arching your back.","Finish your reps, then switch legs."],"img":"opengym/2419.webp","gif":null,"ext":1},{"id":"2420","n":"resistance band air bike","bp":"waist","eq":"band","tg":"abs","mg":"obliques","sm":["obliques","hip flexors","lower abs"],"st":["Lie on your back with a band looped around your feet.","Hold the ends with your hands or place them by your head.","Lift your shoulders and bring your knees up.","Pedal your legs while twisting your elbow toward the opposite knee.","Keep your lower back flat.","Continue for the planned reps."],"img":"opengym/2420.webp","gif":null,"ext":1},{"id":"2423","n":"resistance band floor hyperextension","bp":"back","eq":"band","tg":"spine","mg":"glutes","sm":["glutes","hamstrings","rhomboids"],"st":["Lie face down and anchor a band under your hands or around your upper back.","Squeeze your glutes and lift your chest slightly off the floor.","Keep your neck neutral.","Pause for a second at the top.","Lower slowly to the floor.","Repeat without overarching."],"img":"opengym/2423.webp","gif":null,"ext":1},{"id":"2424","n":"resistance band lunge","bp":"upper legs","eq":"band","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","calves","core"],"st":["Stand on the middle of a band and hold the ends at your shoulders.","Step forward into a lunge.","Lower your back knee toward the floor.","Keep your front knee over your ankle and your torso tall.","Push through your front heel to return.","Alternate legs for the planned reps."],"img":"opengym/2424.webp","gif":null,"ext":1},{"id":"2431","n":"dumbbell sumo squat off benches","bp":"upper legs","eq":"dumbbell","tg":"glutes","mg":"quadriceps","sm":["quadriceps","adductors","inner thighs","hamstrings"],"st":["Place a bench under each foot with a wide stance.","Hold a dumbbell in front of you with both hands.","Sit your hips down between the benches.","Lower until you feel a deep stretch in your hips.","Push through your heels to stand.","Keep your chest up throughout."],"img":"opengym/2431.webp","gif":null,"ext":1},{"id":"2434","n":"cable seated twist on floor","bp":"waist","eq":"cable","tg":"obliques","mg":"core","sm":["core","lower back"],"st":["Sit on the floor facing a low cable and hold the handle.","Lean back slightly and lift your feet if you can.","Rotate your torso from side to side.","Keep your arms steady and your core tight.","Move slowly without jerking.","Continue for the planned reps."],"img":"opengym/2434.webp","gif":null,"ext":1},{"id":"2458","n":"wall ball","bp":"full body","eq":"medicine ball","tg":"quads","mg":"glutes","sm":["glutes","shoulders","triceps","core"],"st":["Stand facing a wall holding a medicine ball at your chest.","Squat down with your chest up.","Drive up powerfully and throw the ball to a target on the wall.","Catch the ball as it returns.","Flow straight into the next squat.","Keep a steady rhythm."],"img":"opengym/2458.webp","gif":null,"ext":1},{"id":"2461","n":"side lying clam","bp":"upper legs","eq":"body weight","tg":"abductors","mg":"glutes","sm":["glutes","hip flexors"],"st":["Lie on your side with knees bent and feet stacked, head on your arm.","Keep your hips stacked and your core lightly braced.","Lift the top knee while keeping your feet together.","Pause at the top, then lower slowly.","Do all reps, then switch sides."],"img":"opengym/2461.webp","gif":null,"ext":1},{"id":"2463","n":"resistance band toe touch","bp":"waist","eq":"band","tg":"abs","mg":"hip flexors","sm":["hip flexors","hamstrings","lower abs"],"st":["Lie on your back with a band around your feet.","Lift your legs toward the ceiling.","Hold the band ends and reach toward your toes.","Curl your shoulders off the floor.","Lower with control.","Repeat for the planned reps."],"img":"opengym/2463.webp","gif":null,"ext":1},{"id":"2465","n":"resistance band jumping jack","bp":"full body","eq":"band","tg":"cardiovascular system","mg":"glutes","sm":["glutes","shoulders","calves","quadriceps"],"st":["Stand with a loop band around your thighs or ankles.","Keep your knees soft and your core tight.","Jump your feet apart while raising your arms overhead.","Push against the band as you land.","Jump back to the start with your arms down.","Keep a steady rhythm."],"img":"opengym/2465.webp","gif":null,"ext":1},{"id":"2468","n":"dumbbell lateral step up","bp":"upper legs","eq":"dumbbell","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","adductors","calves"],"st":["Stand beside a bench holding a dumbbell in each hand.","Place your near foot on the bench.","Drive through that heel to step up onto the bench.","Bring your other foot up to balance.","Step down with control.","Finish your reps, then switch sides."],"img":"opengym/2468.webp","gif":null,"ext":1},{"id":"2469","n":"exercise ball frog crunch","bp":"waist","eq":"stability ball","tg":"abs","mg":"lower abs","sm":["lower abs","hip flexors","core"],"st":["Lie back on a stability ball with your lower back supported.","Place the soles of your feet together with your knees out.","Place your hands lightly by your head.","Crunch up while pulling your knees toward your chest.","Squeeze your abs.","Lower slowly and repeat."],"img":"opengym/2469.webp","gif":null,"ext":1},{"id":"2471","n":"glute bridge two legs on floor","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"hamstrings","sm":["hamstrings","core","lower back"],"st":["Lie on your back with your knees bent and feet flat.","Place your arms by your sides.","Push through your heels to lift your hips.","Make a straight line from shoulders to knees.","Squeeze your glutes at the top.","Lower slowly and repeat."],"img":"opengym/2471.webp","gif":null,"ext":1},{"id":"2473","n":"glute bridge one leg on bench","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"hamstrings","sm":["hamstrings","core","lower back"],"st":["Lie on your back with one foot on a bench and the other leg extended.","Brace your core.","Push through the planted heel to lift your hips.","Keep your hips level.","Squeeze your glute at the top.","Finish your reps, then switch legs."],"img":"opengym/2473.webp","gif":null,"ext":1},{"id":"2474","n":"glute bridge one leg on floor (straight leg)","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"hamstrings","sm":["hamstrings","core","lower back"],"st":["Lie on your back with one knee bent and the other leg straight up.","Keep your arms by your sides.","Push through your planted heel to lift your hips.","Keep your hips level.","Squeeze your glute at the top.","Finish your reps, then switch legs."],"img":"opengym/2474.webp","gif":null,"ext":1},{"id":"2475","n":"glute bridge one leg on floor (bent knee)","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"hamstrings","sm":["hamstrings","core","lower back"],"st":["Lie on your back with one foot on the floor and the other knee pulled up.","Place your arms by your sides.","Push through the planted heel to lift your hips.","Keep your pelvis level.","Squeeze your glute at the top.","Finish your reps, then switch legs."],"img":"opengym/2475.webp","gif":null,"ext":1},{"id":"2485","n":"dumbbell hammer curl v. 3","bp":"upper arms","eq":"dumbbell","tg":"biceps","mg":"brachialis","sm":["brachialis","forearms"],"st":["Stand holding dumbbells at your sides with palms facing in.","Keep your elbows close to your torso.","Curl the dumbbells up toward your shoulders.","Keep your wrists straight.","Squeeze at the top.","Lower slowly and repeat."],"img":"opengym/2485.webp","gif":null,"ext":1},{"id":"2487","n":"dumbbell rear delt fly","bp":"shoulders","eq":"dumbbell","tg":"delts","mg":"rear deltoids","sm":["rear deltoids","rhomboids","upper back"],"st":["Hinge forward with a flat back, holding dumbbells below your chest.","Keep a slight bend in your elbows.","Raise the dumbbells out to the sides.","Squeeze your shoulder blades together.","Lower slowly to the start.","Keep your neck neutral."],"img":"opengym/2487.webp","gif":null,"ext":1},{"id":"2500","n":"dumbbell incline rear fly","bp":"shoulders","eq":"dumbbell","tg":"delts","mg":"rear deltoids","sm":["rear deltoids","rhomboids","upper back"],"st":["Lie face down on an incline bench with a dumbbell in each hand.","Let your arms hang with a slight bend in the elbows.","Raise the dumbbells out to the sides.","Squeeze your shoulder blades at the top.","Lower slowly.","Keep your chest on the pad."],"img":"opengym/2500.webp","gif":null,"ext":1},{"id":"2509","n":"barbell reverse grip incline row","bp":"back","eq":"barbell","tg":"upper back","mg":"lats","sm":["lats","biceps","rhomboids"],"st":["Lie chest down on an incline bench holding a barbell with an underhand grip.","Let your arms hang straight.","Row the bar toward your lower ribs.","Squeeze your shoulder blades together.","Lower slowly until your arms are straight.","Keep your chest on the pad."],"img":"opengym/2509.webp","gif":null,"ext":1},{"id":"2511","n":"dumbbell reverse grip incline row","bp":"back","eq":"dumbbell","tg":"upper back","mg":"lats","sm":["lats","biceps","rhomboids"],"st":["Lie chest down on an incline bench holding dumbbells with an underhand grip.","Let your arms hang straight.","Row the dumbbells toward your lower ribs.","Squeeze your shoulder blades together.","Lower slowly until your arms are straight.","Keep your chest on the pad."],"img":"opengym/2511.webp","gif":null,"ext":1},{"id":"2515","n":"cable front raise v. 2","bp":"shoulders","eq":"cable","tg":"delts","mg":"upper chest","sm":["upper chest","trapezius","core"],"st":["Stand facing away from a low pulley, holding the handle in front of your thighs.","Keep a slight bend in your elbow.","Raise your arm forward to shoulder height.","Avoid leaning back.","Lower slowly.","Finish your reps, then switch arms."],"img":"opengym/2515.webp","gif":null,"ext":1},{"id":"2523","n":"decline twisting sit up","bp":"waist","eq":"body weight","tg":"obliques","mg":"hip flexors","sm":["hip flexors","lower abs"],"st":["Lie on a decline bench with your feet secured.","Place your hands lightly behind your head.","Sit up while rotating your torso to one side.","Pause at the top.","Lower with control.","Alternate sides each rep."],"img":"opengym/2523.webp","gif":null,"ext":1},{"id":"2525","n":"vibrate plate standing","bp":"full body","eq":"weighted","tg":"quads","mg":"calves","sm":["calves","glutes","core"],"st":["Step onto the vibrating plate with your feet shoulder-width apart.","Keep your knees slightly bent.","Hold your posture tall and your core braced.","Keep your weight balanced over your feet.","Hold for 30-60 seconds.","Step off carefully."],"img":"opengym/2525.webp","gif":null,"ext":1},{"id":"2526","n":"vibrate plate plank","bp":"waist","eq":"weighted","tg":"abs","mg":"core","sm":["core","shoulders","glutes"],"st":["Place your forearms or hands on the vibrating plate.","Extend your legs behind you.","Form a straight line from head to heels.","Brace your abs and squeeze your glutes.","Hold for 20-40 seconds.","Come down carefully."],"img":"opengym/2526.webp","gif":null,"ext":1},{"id":"2527","n":"vibrate plate lunge","bp":"upper legs","eq":"weighted","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","core"],"st":["Place one foot on the vibrating plate and step the other back.","Lower into a lunge with your torso upright.","Keep your front knee over your ankle.","Hold the bottom briefly.","Push up to return.","Finish your reps, then switch legs."],"img":"opengym/2527.webp","gif":null,"ext":1},{"id":"2544","n":"cable wide grip rear pulldown behind neck v. 2","bp":"back","eq":"cable","tg":"lats","mg":"upper back","sm":["upper back","rhomboids","biceps","rear deltoids"],"st":["Sit at the pulldown station with your thighs secured.","Grab the bar with a wide overhand grip.","Lean forward slightly and pull the bar down behind your head to the base of your neck.","Squeeze your shoulder blades together.","Control the bar back up.","Move gently and keep your neck neutral."],"img":"opengym/2544.webp","gif":null,"ext":1},{"id":"2555","n":"resistance band glute bridge v. 2","bp":"upper legs","eq":"band","tg":"glutes","mg":"hamstrings","sm":["hamstrings","core"],"st":["Lie on your back with a loop band around your thighs.","Bend your knees with feet flat.","Push your knees out against the band.","Lift your hips until your body forms a straight line.","Squeeze your glutes at the top.","Lower slowly and repeat."],"img":"opengym/2555.webp","gif":null,"ext":1},{"id":"2560","n":"bench full squat","bp":"upper legs","eq":"body weight","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","adductors","core"],"st":["Stand in front of a bench with your feet shoulder-width apart.","Keep your chest up.","Sit your hips back and lower until you touch the bench.","Pause briefly without relaxing.","Push through your heels to stand.","Repeat for the planned reps."],"img":"opengym/2560.webp","gif":null,"ext":1},{"id":"2561","n":"side up jump top bench","bp":"upper legs","eq":"body weight","tg":"quads","mg":"glutes","sm":["glutes","calves","hamstrings"],"st":["Stand beside a sturdy bench.","Bend your knees and swing your arms back.","Jump up and sideways onto the bench.","Land softly with your knees bent.","Step down carefully.","Repeat, alternating sides."],"img":"opengym/2561.webp","gif":null,"ext":1},{"id":"2562","n":"side jump step up","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"quadriceps","sm":["quadriceps","calves","hamstrings"],"st":["Stand beside a low step.","Place your near foot on the step.","Drive up with a small jump.","Land softly on the step.","Step down with control.","Finish your reps, then switch sides."],"img":"opengym/2562.webp","gif":null,"ext":1},{"id":"2563","n":"power sled pull row","bp":"back","eq":"sled machine","tg":"upper back","mg":"lats","sm":["lats","biceps","hamstrings","core"],"st":["Attach a rope or handles to a loaded sled.","Hold the rope with your knees slightly bent.","Pull the sled toward you with a rowing motion.","Squeeze your shoulder blades.","Keep your back flat.","Repeat for the planned distance."],"img":"opengym/2563.webp","gif":null,"ext":1},{"id":"2564","n":"jack plank on medicine ball","bp":"waist","eq":"medicine ball","tg":"abs","mg":"core","sm":["core","shoulders","hip flexors"],"st":["Place your hands on a medicine ball in a plank.","Brace your abs and keep your body straight.","Jump your feet wide.","Jump them back together.","Keep your hips level.","Continue for the planned reps."],"img":"opengym/2564.webp","gif":null,"ext":1},{"id":"2566","n":"dumbbell bent arm pullover with knees bent","bp":"chest","eq":"dumbbell","tg":"pectorals","mg":"lats","sm":["lats","triceps","core"],"st":["Lie back on a bench or the floor with knees bent and feet flat, holding one dumbbell over your chest.","Bend your elbows slightly and lock that angle.","Lower the dumbbell back over your head in a slow arc until you feel a stretch in your chest.","Pull the weight back over your chest along the same arc.","Keep your ribs down and your lower back from arching."],"img":"opengym/2566.webp","gif":null,"ext":1},{"id":"2569","n":"cossack squats","bp":"upper legs","eq":"body weight","tg":"quads","mg":"glutes","sm":["glutes","adductors","hamstrings","inner thighs"],"st":["Stand with your feet much wider than shoulder width and toes slightly out.","Shift your weight to one side and bend that knee, sitting your hips down and back.","Keep the other leg straight with the heel down and toes up.","Push through the bent leg to slide back to the centre.","Repeat on the other side and keep your chest tall."],"img":"opengym/2569.webp","gif":null,"ext":1},{"id":"2570","n":"bent leg circle kick (kneeling)","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"hamstrings","sm":["hamstrings","core","obliques"],"st":["Start on hands and knees with your hands under your shoulders.","Lift one leg out to the side with the knee bent.","Draw slow circles in the air with your knee.","Keep your hips level and your spine still.","Switch direction, then repeat on the other leg."],"img":"opengym/2570.webp","gif":null,"ext":1},{"id":"2572","n":"roll overs into v sits","bp":"waist","eq":"body weight","tg":"abs","mg":"hip flexors","sm":["hip flexors","lower abs","core"],"st":["Sit with knees bent and arms reaching forward.","Roll back, lifting your legs up and over toward your head.","Roll forward with control and extend your legs.","Land in a balanced V sit, with arms reaching toward your feet.","Move smoothly and use your abs to drive the motion."],"img":"opengym/2572.webp","gif":null,"ext":1},{"id":"2589","n":"dumbbell lying triceps extension v. 2","bp":"upper arms","eq":"dumbbell","tg":"triceps","mg":"shoulders","sm":["shoulders","forearms"],"st":["Lie on a bench holding a dumbbell in each hand above your chest, palms facing in.","Keep your upper arms still and bend your elbows to lower the weights beside your head.","Stop when you feel a stretch in the triceps.","Straighten your arms back to the start.","Keep your elbows pointing at the ceiling."],"img":"opengym/2589.webp","gif":null,"ext":1},{"id":"2656","n":"cable one arm biceps curl v. 2","bp":"upper arms","eq":"cable","tg":"biceps","mg":"brachialis","sm":["brachialis","forearms"],"st":["Stand facing the cable with the handle at low height and grip it with one hand, palm up.","Keep your elbow tucked at your side.","Curl the handle toward your shoulder and squeeze the biceps.","Lower slowly until the arm is nearly straight.","Finish all reps, then switch arms."],"img":"opengym/2656.webp","gif":null,"ext":1},{"id":"2658","n":"elliptical machine skiing","bp":"cardio","eq":"elliptical machine","tg":"cardiovascular system","mg":"glutes","sm":["glutes","quadriceps","hamstrings","core"],"st":["Step onto the elliptical and hold the handles.","Start striding in a smooth, ski-like rhythm, swinging your arms with your legs.","Stay upright and keep your core engaged.","Hold a steady pace for your chosen time.","Slow down gradually to finish."],"img":"opengym/2658.webp","gif":null,"ext":1},{"id":"2659","n":"lever incline chest press (plate loaded)","bp":"chest","eq":"leverage machine","tg":"pectorals","mg":"upper chest","sm":["upper chest","triceps","shoulders"],"st":["Adjust the seat so the handles are level with your upper chest.","Sit back and grip the handles with feet flat on the floor.","Press forward until your arms are nearly straight.","Squeeze the chest, then return slowly.","Keep your back against the pad and your shoulders down."],"img":"opengym/2659.webp","gif":null,"ext":1},{"id":"2660","n":"lever preacher curl (plate loaded) v. 2","bp":"upper arms","eq":"leverage machine","tg":"biceps","mg":"brachialis","sm":["brachialis","forearms"],"st":["Adjust the seat so your upper arms rest flat on the pad.","Grip the handles with palms up.","Curl the handles toward your shoulders.","Squeeze at the top, then lower slowly.","Do not lift your elbows off the pad or let the weight drop."],"img":"opengym/2660.webp","gif":null,"ext":1},{"id":"2661","n":"cable seated row with v bar","bp":"back","eq":"cable","tg":"upper back","mg":"lats","sm":["lats","biceps","rhomboids"],"st":["Sit at the cable row station with your feet on the platform and knees slightly bent.","Grip the V bar and sit tall with arms extended.","Pull the bar toward your lower ribs and squeeze your shoulder blades.","Return slowly until your arms are straight.","Keep your chest up and avoid rocking."],"img":"opengym/2661.webp","gif":null,"ext":1},{"id":"2662","n":"lever high row (plate loaded) v. 2","bp":"back","eq":"leverage machine","tg":"lats","mg":"upper back","sm":["upper back","biceps","rhomboids"],"st":["Adjust the seat and chest pad so you can grip the handles with arms extended.","Sit tall with your chest on the pad.","Pull the handles down and back, driving the elbows toward your hips.","Squeeze the shoulder blades together.","Return slowly and keep your shoulders down."],"img":"opengym/2662.webp","gif":null,"ext":1},{"id":"2663","n":"lever high row (plate loaded) v. 3","bp":"back","eq":"leverage machine","tg":"lats","mg":"upper back","sm":["upper back","biceps","rhomboids"],"st":["Adjust the seat and chest pad so you can grip the handles with arms extended.","Sit tall with your chest on the pad.","Pull the handles down and back, driving the elbows toward your hips.","Squeeze the shoulder blades together.","Return slowly and keep your shoulders down."],"img":"opengym/2663.webp","gif":null,"ext":1},{"id":"2664","n":"lever seated row (plate loaded)","bp":"back","eq":"leverage machine","tg":"upper back","mg":"lats","sm":["lats","biceps","rhomboids"],"st":["Adjust the seat so the handles line up with your mid chest.","Sit with your chest against the pad and grip the handles.","Pull your elbows back and squeeze the shoulder blades.","Pause briefly, then return slowly.","Keep your torso tight against the pad."],"img":"opengym/2664.webp","gif":null,"ext":1},{"id":"2665","n":"lever lateral wide pulldown","bp":"back","eq":"leverage machine","tg":"lats","mg":"biceps","sm":["biceps","upper back","rhomboids"],"st":["Adjust the seat and thigh pad, then grip the wide handles.","Sit tall with your chest up.","Pull the handles down toward your upper chest, leading with the elbows.","Squeeze the lats, then let the handles rise slowly.","Avoid leaning far back or using momentum."],"img":"opengym/2665.webp","gif":null,"ext":1},{"id":"2666","n":"lever seated calf raise (plate loaded) v. 2","bp":"lower legs","eq":"leverage machine","tg":"calves","mg":"soleus","sm":["soleus","ankles"],"st":["Sit with the balls of your feet on the platform and the pad over your thighs.","Release the safety and lower your heels for a stretch.","Press up through the balls of your feet as high as you can.","Pause and squeeze the calves.","Lower slowly to full stretch."],"img":"opengym/2666.webp","gif":null,"ext":1},{"id":"2671","n":"smith narrow row v. 2","bp":"back","eq":"smith machine","tg":"upper back","mg":"lats","sm":["lats","biceps","rhomboids","forearms"],"st":["Set the bar at knee height and grip it with hands close together.","Hinge forward at the hips with a flat back and slightly bent knees.","Pull the bar toward your lower ribs, keeping elbows close to your body.","Squeeze your back at the top.","Lower the bar under control to full arm extension."],"img":"opengym/2671.webp","gif":null,"ext":1},{"id":"2689","n":"cable one arm front raise","bp":"shoulders","eq":"cable","tg":"delts","mg":"upper chest","sm":["upper chest","shoulders","core"],"st":["Stand facing away from a low cable pulley with the handle in one hand.","Keep your arm nearly straight and raise it forward to shoulder height.","Pause briefly at the top.","Lower with control.","Finish your reps, then switch arms."],"img":"opengym/2689.webp","gif":null,"ext":1},{"id":"2690","n":"dumbbell one arm lateral raise v. 2","bp":"shoulders","eq":"dumbbell","tg":"delts","mg":"trapezius","sm":["trapezius","rotator cuff"],"st":["Stand holding a dumbbell in one hand at your side.","Keep a soft bend in the elbow.","Raise the arm out to the side until it reaches shoulder height.","Lower slowly without swinging.","Do all reps, then switch sides."],"img":"opengym/2690.webp","gif":null,"ext":1},{"id":"2707","n":"strongman log lift","bp":"full body","eq":"weight plate","tg":"delts","mg":"triceps","sm":["triceps","upper back","glutes","core"],"st":["Stand over the log with feet shoulder width apart and grip it with a firm hold.","Lift it to your lap with a flat back and drive the hips forward.","Rack it on your chest with elbows high.","Dip your knees, then drive up and press the log overhead.","Lock out, then lower with control.","Start light and keep your core braced."],"img":"opengym/2707.webp","gif":null,"ext":1},{"id":"2708","n":"strongman mas wrestling","bp":"full body","eq":"weight plate","tg":"forearms","mg":"grip muscles","sm":["grip muscles","upper back","core"],"st":["Sit facing a partner with feet against theirs and both hands on a stick.","Brace your core.","Pull the stick toward you with a strong grip.","Resist your partner while keeping your back straight.","Keep the effort steady and control the end of each pull."],"img":"opengym/2708.webp","gif":null,"ext":1},{"id":"2709","n":"strongman arm over arm","bp":"back","eq":"rope","tg":"lats","mg":"biceps","sm":["biceps","forearms","core","upper back"],"st":["Face the load with the rope in both hands and feet set wide.","Lean back slightly with a braced core.","Pull the rope with one arm and then the other.","Keep a steady rhythm.","Reach and pull smoothly while keeping your back flat."],"img":"opengym/2709.webp","gif":null,"ext":1},{"id":"2710","n":"strongman truck pull","bp":"full body","eq":"rope","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","grip muscles","core"],"st":["Stand facing away from the truck with the rope held across your body.","Lean forward and dig your feet in.","Take short, powerful steps driving through the legs.","Keep your core braced and the rope close.","Pull the full distance, then rest."],"img":"opengym/2710.webp","gif":null,"ext":1},{"id":"2711","n":"strongman duck walk","bp":"upper legs","eq":"weight plate","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","core"],"st":["Hold the weight in front of you and lower into a deep squat.","Keep your chest up.","Take small steps while staying low.","Keep your core braced and your knees tracking over your toes.","Walk the full distance, then stand and rest."],"img":"opengym/2711.webp","gif":null,"ext":1},{"id":"2712","n":"strongman sandbag walk","bp":"full body","eq":"sandbag","tg":"spine","mg":"glutes","sm":["glutes","core","upper back","grip muscles"],"st":["Lift the sandbag off the floor and hug it against your chest.","Stand tall with your core braced.","Walk forward at a steady pace with short steps.","Keep your posture upright and do not lean back.","Set the bag down under control at the end."],"img":"opengym/2712.webp","gif":null,"ext":1},{"id":"2713","n":"strongman iron block press","bp":"shoulders","eq":"weight plate","tg":"delts","mg":"triceps","sm":["triceps","upper chest","core"],"st":["Lift the block to your shoulders and set your feet hip width apart.","Brace your core and squeeze your glutes.","Press the block overhead until your arms lock out.","Pause at the top.","Lower it back to your shoulders under control."],"img":"opengym/2713.webp","gif":null,"ext":1},{"id":"2714","n":"strongman iceland cross","bp":"full body","eq":"weight plate","tg":"delts","mg":"upper back","sm":["upper back","forearms","grip muscles","core"],"st":["Pick up a weight in each hand and stand tall.","Raise your arms out to the sides to shoulder height.","Hold them there with a braced core.","Keep your shoulders down and avoid shrugging.","Hold as long as you can, then lower under control."],"img":"opengym/2714.webp","gif":null,"ext":1},{"id":"2715","n":"strongman timber carry","bp":"full body","eq":"weight plate","tg":"spine","mg":"glutes","sm":["glutes","core","upper back","trapezius"],"st":["Lift the timber onto your shoulder and balance it.","Stand tall with your core braced.","Walk with short, steady steps.","Keep the load balanced and avoid leaning to one side.","Set it down under control, then switch shoulders."],"img":"opengym/2715.webp","gif":null,"ext":1},{"id":"2716","n":"strongman circle of conan","bp":"full body","eq":"weight plate","tg":"spine","mg":"glutes","sm":["glutes","core","upper back","grip muscles"],"st":["Pick up the load and hold it against your body.","Brace your core and keep your chest up.","Walk in a circle with steady steps.","Stay balanced and avoid leaning away.","Set the load down under control when you finish."],"img":"opengym/2716.webp","gif":null,"ext":1},{"id":"2717","n":"strongman crucifix hold","bp":"shoulders","eq":"weight plate","tg":"delts","mg":"upper back","sm":["upper back","forearms","grip muscles","core"],"st":["Pick up a weight in each hand and stand tall.","Raise your arms out to the sides until level with your shoulders.","Hold the position with a braced core.","Keep your shoulders down and wrists straight.","Hold as long as you can, then lower with control."],"img":"opengym/2717.webp","gif":null,"ext":1},{"id":"2718","n":"strongman front hold","bp":"shoulders","eq":"weight plate","tg":"delts","mg":"upper chest","sm":["upper chest","forearms","core","grip muscles"],"st":["Pick up the weights and stand tall.","Raise your arms forward to shoulder height.","Hold with a braced core.","Keep your shoulders down and avoid leaning back.","Hold as long as you can, then lower with control."],"img":"opengym/2718.webp","gif":null,"ext":1},{"id":"2719","n":"strongman viking press","bp":"shoulders","eq":"weight plate","tg":"delts","mg":"triceps","sm":["triceps","upper chest","core"],"st":["Stand inside the frame and grab the handles.","Lift the handles to shoulder height and set your feet.","Brace your core and press overhead.","Lock out your arms.","Lower back to shoulder height under control."],"img":"opengym/2719.webp","gif":null,"ext":1},{"id":"2720","n":"strongman squats with platform","bp":"upper legs","eq":"weight plate","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","core"],"st":["Stand with the platform loaded on your shoulders and feet shoulder width apart.","Brace your core.","Squat down with your chest up and knees tracking over toes.","Drive back up through your heels.","Stand tall and lock out at the top."],"img":"opengym/2720.webp","gif":null,"ext":1},{"id":"2721","n":"strongman loading","bp":"full body","eq":"weight plate","tg":"glutes","mg":"hamstrings","sm":["hamstrings","lower back","core","upper back"],"st":["Stand over the first object with feet shoulder width apart.","Hinge at the hips and grip it with a flat back.","Lift it by driving through the hips.","Carry it to the platform and load it.","Return, repeat with the next object, and keep your core braced."],"img":"opengym/2721.webp","gif":null,"ext":1},{"id":"2722","n":"strongman hood stones","bp":"full body","eq":"weight plate","tg":"glutes","mg":"hamstrings","sm":["hamstrings","lower back","core","upper back"],"st":["Straddle the stone and squat down to hug it.","Lift it to your lap by driving the hips forward.","Roll the stone up your chest.","Extend your hips to land it on the platform.","Lower the stone under control and reset."],"img":"opengym/2722.webp","gif":null,"ext":1},{"id":"2723","n":"strongman wheelbarrow","bp":"full body","eq":"weight plate","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","core","grip muscles"],"st":["Grip the wheelbarrow handles and lift them with a flat back.","Brace your core.","Push forward with strong steps.","Keep your arms straight and your body in line.","Set it down under control at the end."],"img":"opengym/2723.webp","gif":null,"ext":1},{"id":"2724","n":"strongman atlas stones","bp":"full body","eq":"weight plate","tg":"glutes","mg":"hamstrings","sm":["hamstrings","lower back","core","upper back"],"st":["Straddle the stone and squat down to wrap your arms around it.","Lift it to your lap by driving the hips forward.","Roll the stone up your chest.","Extend your hips to load it on the platform.","Lower it back to the floor under control and reset."],"img":"opengym/2724.webp","gif":null,"ext":1},{"id":"2725","n":"strongman power stairs","bp":"full body","eq":"weight plate","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","calves","core"],"st":["Pick up the load and hold it against your chest.","Brace your core and stand tall.","Climb the stairs one step at a time.","Push through your whole foot and keep your chest up.","Set the load down under control at the top."],"img":"opengym/2725.webp","gif":null,"ext":1},{"id":"2726","n":"strongman hercules hold","bp":"full body","eq":"weight plate","tg":"forearms","mg":"grip muscles","sm":["grip muscles","upper back","shoulders","core"],"st":["Pick up the weights and stand tall.","Hold your arms out to your sides.","Brace your core and keep your shoulders down.","Hold the position as long as you can.","Lower under control when done."],"img":"opengym/2726.webp","gif":null,"ext":1},{"id":"2727","n":"strongman shield carry","bp":"full body","eq":"weight plate","tg":"spine","mg":"core","sm":["core","glutes","upper back","forearms"],"st":["Lift the shield and hold it in front of you.","Stand tall with your core braced.","Walk forward at a steady pace.","Keep your posture upright.","Set it down under control when you finish."],"img":"opengym/2727.webp","gif":null,"ext":1},{"id":"2728","n":"strongman front chest squat","bp":"upper legs","eq":"weight plate","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","core","upper back"],"st":["Hold the load tight against your chest with your elbows up.","Stand with feet shoulder width apart.","Squat down keeping your chest tall.","Drive up through your heels.","Lock out the hips at the top."],"img":"opengym/2728.webp","gif":null,"ext":1},{"id":"2729","n":"strongman deadlift","bp":"upper legs","eq":"barbell","tg":"glutes","mg":"hamstrings","sm":["hamstrings","lower back","grip muscles","trapezius"],"st":["Stand with feet hip width apart and the bar over mid foot.","Hinge down and grip the bar just outside your knees, chest up and back flat.","Brace your core and push the floor away, keeping the bar close to your legs.","Stand tall by driving your hips forward, then lower the bar under control."],"img":"opengym/2729.webp","gif":null,"ext":1},{"id":"2730","n":"strongman tire flip","bp":"full body","eq":"tire","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","lower back","shoulders","chest"],"st":["Stand close to the tire and squat down, getting your fingers under its edge.","Press your chest against the tire with a flat back and hips low.","Explode up with your legs and hips, lifting the tire as you rise.","Shove the tire over with your hands and shoulders, then step in and reset for the next flip."],"img":"opengym/2730.webp","gif":null,"ext":1},{"id":"2731","n":"strongman weight for height","bp":"full body","eq":"weighted","tg":"upper back","mg":"shoulders","sm":["shoulders","glutes","quadriceps","core","triceps"],"st":["Hold the weight with both hands low in front of you, feet shoulder width apart.","Swing it back between your legs while hinging at the hips.","Drive your hips and legs up hard and swing the weight up and overhead.","Release it over the bar, then step back and reset for the next throw."],"img":"opengym/2731.webp","gif":null,"ext":1},{"id":"2732","n":"strongman dumbbell one arm clean and jerk","bp":"full body","eq":"dumbbell","tg":"delts","mg":"triceps","sm":["triceps","glutes","quadriceps","core","trapezius"],"st":["Stand over a dumbbell with feet shoulder width apart and grab it with one hand.","Pull it explosively to your shoulder with a hip drive, dipping slightly under it.","Dip your knees, then drive up and press the dumbbell overhead to a locked arm.","Lower it back to the shoulder and then the floor with control, then switch arms."],"img":"opengym/2732.webp","gif":null,"ext":1},{"id":"2733","n":"strongman apollons axle","bp":"full body","eq":"barbell","tg":"forearms","mg":"grip muscles","sm":["grip muscles","shoulders","trapezius","glutes","triceps"],"st":["Stand over the thick axle with feet shoulder width apart and grip it firmly.","Pull it up the thighs with a flat back and clean it to your chest.","Dip and drive with your legs, pressing the axle overhead until your arms lock.","Bring it back down to your chest and then the floor with control."],"img":"opengym/2733.webp","gif":null,"ext":1},{"id":"2734","n":"strongman barbell farmers walk","bp":"full body","eq":"barbell","tg":"forearms","mg":"grip muscles","sm":["grip muscles","trapezius","core","glutes","shoulders"],"st":["Stand inside the loaded bar and grip the handle, then lift it to hang at your sides.","Keep your chest tall, shoulders back and core braced.","Walk forward with short, quick steps for a set distance.","Stop, lower the weights to the floor with a flat back, and rest."],"img":"opengym/2734.webp","gif":null,"ext":1},{"id":"2735","n":"strongman yoke walk","bp":"full body","eq":"barbell","tg":"traps","mg":"core","sm":["core","glutes","quadriceps","upper back","calves"],"st":["Step under the yoke so it rests across your upper back and grip the frame.","Brace your core and stand up to lift it off the supports.","Walk forward in quick, controlled steps, keeping your torso upright.","At the end, lower the yoke back onto the supports with care."],"img":"opengym/2735.webp","gif":null,"ext":1},{"id":"2737","n":"standing hip extension (straight leg)","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"hamstrings","sm":["hamstrings","lower back","core"],"st":["Stand tall and hold a support for balance.","Keep your standing knee slightly soft.","Lift one straight leg back behind you without arching your lower back.","Squeeze the glute at the top.","Lower with control and switch legs after your reps."],"img":"opengym/2737.webp","gif":null,"ext":1},{"id":"2738","n":"dumbbell lying triceps extension on floor","bp":"upper arms","eq":"dumbbell","tg":"triceps","mg":"shoulders","sm":["shoulders","forearms"],"st":["Lie on the floor with knees bent, holding a dumbbell in each hand over your chest.","Keep upper arms still and bend your elbows to lower the weights toward your head.","Stop just before the weights touch the floor.","Press back up by straightening your arms.","Keep your elbows pointing up."],"img":"opengym/2738.webp","gif":null,"ext":1},{"id":"2740","n":"wide push up (wall)","bp":"chest","eq":"body weight","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders","core"],"st":["Stand facing a wall and place your hands on it, wider than your shoulders.","Step your feet back so your body leans in a straight line.","Bend your elbows to bring your chest toward the wall.","Push back to the start.","Keep your hips in line with your shoulders."],"img":"opengym/2740.webp","gif":null,"ext":1},{"id":"2742","n":"lever hip thrust (with stepbox) v. 2","bp":"upper legs","eq":"leverage machine","tg":"glutes","mg":"hamstrings","sm":["hamstrings","quadriceps","core"],"st":["Sit in the machine with your feet on the step box and the pad across your hips.","Brace your core and drive through your heels.","Lift your hips until your body is straight from shoulders to knees.","Squeeze your glutes at the top.","Lower slowly to the start."],"img":"opengym/2742.webp","gif":null,"ext":1},{"id":"2743","n":"lever hip thrust v. 2","bp":"upper legs","eq":"leverage machine","tg":"glutes","mg":"hamstrings","sm":["hamstrings","quadriceps","core"],"st":["Sit in the machine with your back against the pad and your feet flat.","Secure the hip pad over your lap.","Drive through your heels to lift your hips.","Squeeze your glutes at the top.","Lower with control without letting the weight crash."],"img":"opengym/2743.webp","gif":null,"ext":1},{"id":"2744","n":"cable standing hip thrust","bp":"upper legs","eq":"cable","tg":"glutes","mg":"hamstrings","sm":["hamstrings","core","quadriceps"],"st":["Attach a belt or strap to a low cable and stand facing away from the stack.","Hold the cable at your hips with feet shoulder width apart.","Hinge slightly, then thrust your hips forward.","Squeeze your glutes at the top.","Return slowly and keep your ribs down."],"img":"opengym/2744.webp","gif":null,"ext":1},{"id":"2745","n":"smith reverse hyperextension","bp":"upper legs","eq":"smith machine","tg":"glutes","mg":"hamstrings","sm":["hamstrings","lower back"],"st":["Lie face down over a bench with your hips at the edge and legs hanging.","Hook your heels under the smith bar if it is set low.","Lift your legs by extending the hips until they are in line with your body.","Squeeze your glutes at the top.","Lower slowly without swinging."],"img":"opengym/2745.webp","gif":null,"ext":1},{"id":"2746","n":"lever abduction squat","bp":"upper legs","eq":"leverage machine","tg":"abductors","mg":"glutes","sm":["glutes","quadriceps","adductors"],"st":["Set the machine and step in with the pads on your shoulders.","Squat down with control, keeping your chest up.","Drive up through your feet.","Push your knees slightly outward as you rise.","Keep your core braced."],"img":"opengym/2746.webp","gif":null,"ext":1},{"id":"2747","n":"lever adduction thrust","bp":"upper legs","eq":"leverage machine","tg":"adductors","mg":"glutes","sm":["glutes","hamstrings","inner thighs"],"st":["Sit in the machine with the pads between or around your legs as set.","Brace your core.","Thrust your hips up while squeezing your legs inward.","Hold the squeeze briefly at the top.","Lower with control."],"img":"opengym/2747.webp","gif":null,"ext":1},{"id":"2748","n":"lever kneeling reverse hyperextension","bp":"upper legs","eq":"leverage machine","tg":"glutes","mg":"hamstrings","sm":["hamstrings","lower back"],"st":["Kneel on the machine pad and hold the handles.","Place the back of your working leg against the lever pad.","Press the leg back and up until your hip is fully extended.","Squeeze your glute at the top.","Lower slowly and switch legs."],"img":"opengym/2748.webp","gif":null,"ext":1},{"id":"2749","n":"lever assisted leg press","bp":"upper legs","eq":"leverage machine","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","calves"],"st":["Sit in the machine and place your feet on the platform about shoulder width apart.","Release the safety handles.","Lower the platform by bending your knees until they reach about 90 degrees.","Push through your heels to extend the legs.","Do not lock your knees fully."],"img":"opengym/2749.webp","gif":null,"ext":1},{"id":"2750","n":"dumbbell single leg deadlift with wall support","bp":"upper legs","eq":"dumbbell","tg":"hamstrings","mg":"glutes","sm":["glutes","lower back","core"],"st":["Stand near a wall, holding a dumbbell and resting one hand on it for balance.","Lift one leg behind you.","Hinge at the hips and lower the dumbbell down your standing leg.","Keep your back flat.","Squeeze your glute to stand tall, then switch legs."],"img":"opengym/2750.webp","gif":null,"ext":1},{"id":"2751","n":"kettlebell dumbbell sumo squat off stepbox","bp":"upper legs","eq":"kettlebell","tg":"glutes","mg":"quadriceps","sm":["quadriceps","adductors","hamstrings","inner thighs"],"st":["Stand on a step box in a wide stance with toes out.","Hold a kettlebell or dumbbell in front of you.","Sit down between your legs, keeping your chest up.","Lower as far as comfortable.","Push through your feet to stand."],"img":"opengym/2751.webp","gif":null,"ext":1},{"id":"2752","n":"split squat v. 2","bp":"upper legs","eq":"body weight","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","adductors"],"st":["Stand in a long stride with one foot forward and one back.","Lower your back knee toward the floor.","Keep your front knee over your ankle.","Push through the front heel to rise.","Finish your reps, then switch legs."],"img":"opengym/2752.webp","gif":null,"ext":1},{"id":"2753","n":"kettlebell resistance band full squat from deficit","bp":"upper legs","eq":"kettlebell","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","adductors","core"],"st":["Stand on a low platform, band under your feet and a kettlebell at your chest.","Sit down into the deepest squat you can control.","Keep your heels flat and chest up.","Push through your feet to stand.","Keep tension in the band all the way up."],"img":"opengym/2753.webp","gif":null,"ext":1},{"id":"2754","n":"weighted hip thrusts","bp":"upper legs","eq":"weighted","tg":"glutes","mg":"hamstrings","sm":["hamstrings","quadriceps","core"],"st":["Sit on the floor with your upper back against a bench and the weight across your hips.","Plant your feet flat and bend your knees.","Drive through your heels to lift your hips.","Squeeze your glutes at the top.","Lower slowly and repeat."],"img":"opengym/2754.webp","gif":null,"ext":1},{"id":"2755","n":"cable hip abduction (toe out)","bp":"upper legs","eq":"cable","tg":"abductors","mg":"glutes","sm":["glutes","core"],"st":["Attach an ankle cuff to a low cable and stand side-on to the stack.","Hold a support for balance.","Turn your toes out slightly.","Lift the working leg out to the side.","Return slowly, then switch legs."],"img":"opengym/2755.webp","gif":null,"ext":1},{"id":"2756","n":"cable hip abduction (toe in)","bp":"upper legs","eq":"cable","tg":"abductors","mg":"glutes","sm":["glutes","core"],"st":["Attach an ankle cuff to a low cable and stand side-on to the stack.","Hold a support for balance.","Turn your toes inward slightly.","Lift the working leg out to the side.","Return slowly, then switch legs."],"img":"opengym/2756.webp","gif":null,"ext":1},{"id":"2757","n":"frog hip thrust","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"adductors","sm":["adductors","hamstrings","core"],"st":["Lie on your back with the soles of your feet together and knees falling out.","Keep your heels near your hips.","Drive through the feet to lift your hips.","Squeeze your glutes at the top.","Lower slowly and repeat."],"img":"opengym/2757.webp","gif":null,"ext":1},{"id":"2758","n":"cable stand up","bp":"upper legs","eq":"cable","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","core"],"st":["Hold the cable handle at your chest and sit back into a deep squat.","Keep your chest tall.","Push through your heels to stand fully.","Squeeze your glutes at the top.","Lower with control."],"img":"opengym/2758.webp","gif":null,"ext":1},{"id":"2760","n":"resistance band hip thrust","bp":"upper legs","eq":"resistance band","tg":"glutes","mg":"hamstrings","sm":["hamstrings","quadriceps","core"],"st":["Sit with your upper back against a bench and the band over your hips, anchored at both sides.","Plant your feet flat.","Drive your hips up against the band.","Squeeze your glutes at the top.","Lower slowly."],"img":"opengym/2760.webp","gif":null,"ext":1},{"id":"2761","n":"ankle dorsal flexion","bp":"lower legs","eq":"body weight","tg":"shins","mg":"calves","sm":["calves","ankles"],"st":["Stand or sit tall with a relaxed posture and the joint in a neutral starting position.","Sit with one leg out and your heel resting on the floor.","Pull your toes and the top of your foot toward your shin as far as is comfortable.","Pause briefly, then lower the foot back down slowly.","Repeat for 10-15 smooth reps, then switch sides if you are working one side at a time."],"img":"opengym/2761.webp","gif":null,"ext":1},{"id":"2762","n":"ankle plantar flexion","bp":"lower legs","eq":"body weight","tg":"calves","mg":"soleus","sm":["soleus","ankles"],"st":["Stand or sit tall with a relaxed posture and the joint in a neutral starting position.","Sit with one leg out and your foot relaxed.","Point your toes down and away from you, as if pressing a gas pedal.","Pause briefly at the end, then return to the neutral position.","Repeat for 10-15 smooth reps, then switch sides if you are working one side at a time."],"img":"opengym/2762.webp","gif":null,"ext":1},{"id":"2763","n":"elbow extension","bp":"upper arms","eq":"body weight","tg":"triceps","mg":"forearms","sm":["forearms"],"st":["Stand or sit tall with a relaxed posture and the joint in a neutral starting position.","Hold your upper arm still with the elbow bent.","Straighten the arm slowly until it is almost fully extended.","Pause briefly, keeping the shoulder relaxed and the upper arm fixed.","Repeat for 10-15 smooth reps, then switch sides if you are working one side at a time."],"img":"opengym/2763.webp","gif":null,"ext":1},{"id":"2764","n":"elbow flexion","bp":"upper arms","eq":"body weight","tg":"biceps","mg":"brachialis","sm":["brachialis","forearms"],"st":["Stand or sit tall with a relaxed posture and the joint in a neutral starting position.","Start with your arm straight down at your side, palm forward.","Bend the elbow to bring your hand up toward your shoulder.","Pause briefly, then lower back down slowly without swinging.","Repeat for 10-15 smooth reps, then switch sides if you are working one side at a time."],"img":"opengym/2764.webp","gif":null,"ext":1},{"id":"2765","n":"forearm pronation","bp":"lower arms","eq":"body weight","tg":"forearms","mg":"wrist flexors","sm":["wrist flexors"],"st":["Stand or sit tall with a relaxed posture and the joint in a neutral starting position.","Hold your elbow close to your side bent at 90 degrees, palm facing up.","Rotate your forearm so your palm turns down to face the floor.","Keep the elbow still and pause briefly at the end.","Repeat for 10-15 smooth reps, then switch sides if you are working one side at a time."],"img":"opengym/2765.webp","gif":null,"ext":1},{"id":"2766","n":"forearm supination","bp":"lower arms","eq":"body weight","tg":"forearms","mg":"biceps","sm":["biceps"],"st":["Stand or sit tall with a relaxed posture and the joint in a neutral starting position.","Hold your elbow close to your side bent at 90 degrees, palm facing down.","Rotate your forearm so your palm turns up to face the ceiling.","Keep the elbow still and pause briefly at the end.","Repeat for 10-15 smooth reps, then switch sides if you are working one side at a time."],"img":"opengym/2766.webp","gif":null,"ext":1},{"id":"2767","n":"hip abduction","bp":"upper legs","eq":"body weight","tg":"abductors","mg":"glutes","sm":["glutes"],"st":["Stand or sit tall with a relaxed posture and the joint in a neutral starting position.","Stand tall holding a support, with your weight on one leg.","Lift the other leg straight out to the side, toes pointing forward.","Pause briefly, then lower slowly without leaning your torso.","Repeat for 10-15 smooth reps, then switch sides if you are working one side at a time."],"img":"opengym/2767.webp","gif":null,"ext":1},{"id":"2768","n":"hip adduction","bp":"upper legs","eq":"body weight","tg":"adductors","mg":"inner thighs","sm":["inner thighs"],"st":["Stand or sit tall with a relaxed posture and the joint in a neutral starting position.","Stand tall holding a support, with your weight on one leg.","Lift the other leg slightly out to the side.","Bring it back in and across the front of the standing leg, then pause.","Repeat for 10-15 smooth reps, then switch sides if you are working one side at a time."],"img":"opengym/2768.webp","gif":null,"ext":1},{"id":"2769","n":"hip extension","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"hamstrings","sm":["hamstrings","lower back"],"st":["Stand or sit tall with a relaxed posture and the joint in a neutral starting position.","Stand tall holding a support, with your weight on one leg.","Swing the other leg straight back, keeping your knee mostly straight.","Squeeze the glute at the top, avoiding any arching of your lower back.","Repeat for 10-15 smooth reps, then switch sides if you are working one side at a time."],"img":"opengym/2769.webp","gif":null,"ext":1},{"id":"2770","n":"hip flexion","bp":"upper legs","eq":"body weight","tg":"hip flexors","mg":"quadriceps","sm":["quadriceps","lower abs"],"st":["Stand or sit tall with a relaxed posture and the joint in a neutral starting position.","Stand tall holding a support, with your weight on one leg.","Lift the other knee up in front of you toward hip height.","Pause briefly, then lower slowly without rounding your back.","Repeat for 10-15 smooth reps, then switch sides if you are working one side at a time."],"img":"opengym/2770.webp","gif":null,"ext":1},{"id":"2771","n":"hip lateral rotation (external rotation)","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"adductors","sm":["adductors","hip flexors"],"st":["Stand or sit tall with a relaxed posture and the joint in a neutral starting position.","Sit tall on a bench or chair, one knee bent at 90 degrees.","Keep your thigh still and swing your lower leg inward, which rotates the hip outward.","Pause briefly, then return to the starting position under control.","Repeat for 10-15 smooth reps, then switch sides if you are working one side at a time."],"img":"opengym/2771.webp","gif":null,"ext":1},{"id":"2772","n":"hip medial rotation (internal rotation)","bp":"upper legs","eq":"body weight","tg":"abductors","mg":"glutes","sm":["glutes","adductors"],"st":["Stand or sit tall with a relaxed posture and the joint in a neutral starting position.","Sit tall on a bench or chair, one knee bent at 90 degrees.","Keep your thigh still and swing your lower leg outward, which rotates the hip inward.","Pause briefly, then return to the starting position under control.","Repeat for 10-15 smooth reps, then switch sides if you are working one side at a time."],"img":"opengym/2772.webp","gif":null,"ext":1},{"id":"2773","n":"knee extension","bp":"upper legs","eq":"body weight","tg":"quads","mg":"hip flexors","sm":["hip flexors"],"st":["Stand or sit tall with a relaxed posture and the joint in a neutral starting position.","Sit tall on a bench or chair with your feet off the floor.","Straighten one knee until the leg is almost fully extended.","Squeeze your thigh at the top, then lower slowly.","Repeat for 10-15 smooth reps, then switch sides if you are working one side at a time."],"img":"opengym/2773.webp","gif":null,"ext":1},{"id":"2774","n":"knee flexion","bp":"upper legs","eq":"body weight","tg":"hamstrings","mg":"calves","sm":["calves","glutes"],"st":["Stand or sit tall with a relaxed posture and the joint in a neutral starting position.","Stand tall holding a support, with your weight on one leg.","Bend the other knee to bring your heel up toward your glutes.","Keep your thighs side by side, pause, then lower slowly.","Repeat for 10-15 smooth reps, then switch sides if you are working one side at a time."],"img":"opengym/2774.webp","gif":null,"ext":1},{"id":"2775","n":"shoulder abduction","bp":"shoulders","eq":"body weight","tg":"delts","mg":"trapezius","sm":["trapezius","rotator cuff"],"st":["Stand or sit tall with a relaxed posture and the joint in a neutral starting position.","Stand tall with your arms at your sides.","Raise one arm out to the side up to about shoulder height.","Lower slowly without shrugging.","Repeat for 10-15 smooth reps, then switch sides if you are working one side at a time."],"img":"opengym/2775.webp","gif":null,"ext":1},{"id":"2776","n":"shoulder adduction","bp":"shoulders","eq":"body weight","tg":"lats","mg":"chest","sm":["chest","upper back"],"st":["Stand or sit tall with a relaxed posture and the joint in a neutral starting position.","Stand tall with one arm raised out to the side at shoulder height.","Pull the arm down toward your side with control.","Keep your torso still and finish with the arm next to your body.","Repeat for 10-15 smooth reps, then switch sides if you are working one side at a time."],"img":"opengym/2776.webp","gif":null,"ext":1},{"id":"2777","n":"shoulder extension","bp":"shoulders","eq":"body weight","tg":"lats","mg":"rear deltoids","sm":["rear deltoids","triceps"],"st":["Stand or sit tall with a relaxed posture and the joint in a neutral starting position.","Stand tall with your arm straight down at your side.","Swing the arm back behind you, keeping it straight.","Avoid leaning forward, pause, then return to the start.","Repeat for 10-15 smooth reps, then switch sides if you are working one side at a time."],"img":"opengym/2777.webp","gif":null,"ext":1},{"id":"2778","n":"shoulder flexion","bp":"shoulders","eq":"body weight","tg":"delts","mg":"upper chest","sm":["upper chest","biceps"],"st":["Stand or sit tall with a relaxed posture and the joint in a neutral starting position.","Stand tall with your arms at your sides, palms facing in.","Raise one arm forward and up to about shoulder height or higher.","Keep your ribs down, then lower slowly.","Repeat for 10-15 smooth reps, then switch sides if you are working one side at a time."],"img":"opengym/2778.webp","gif":null,"ext":1},{"id":"2779","n":"shoulder lateral rotation (external rotation)","bp":"shoulders","eq":"body weight","tg":"delts","mg":"rotator cuff","sm":["rotator cuff","rear deltoids"],"st":["Stand or sit tall with a relaxed posture and the joint in a neutral starting position.","Stand with your elbow at your side bent at 90 degrees, forearm pointing forward.","Rotate your forearm outward, keeping the elbow tucked against your side.","Pause briefly, then return slowly.","Repeat for 10-15 smooth reps, then switch sides if you are working one side at a time."],"img":"opengym/2779.webp","gif":null,"ext":1},{"id":"2780","n":"shoulder medial rotation (internal rotation)","bp":"shoulders","eq":"body weight","tg":"delts","mg":"rotator cuff","sm":["rotator cuff","chest"],"st":["Stand or sit tall with a relaxed posture and the joint in a neutral starting position.","Stand with your elbow at your side bent at 90 degrees, forearm pointing forward.","Rotate your forearm inward across your stomach, keeping the elbow tucked in.","Pause briefly, then return slowly.","Repeat for 10-15 smooth reps, then switch sides if you are working one side at a time."],"img":"opengym/2780.webp","gif":null,"ext":1},{"id":"2781","n":"shoulder transverse abduction","bp":"shoulders","eq":"body weight","tg":"delts","mg":"rear deltoids","sm":["rear deltoids","rhomboids"],"st":["Stand or sit tall with a relaxed posture and the joint in a neutral starting position.","Stand tall with one arm held out in front at shoulder height.","Sweep the arm out and back in a horizontal arc as far as is comfortable.","Keep the arm at shoulder height, pause, then return.","Repeat for 10-15 smooth reps, then switch sides if you are working one side at a time."],"img":"opengym/2781.webp","gif":null,"ext":1},{"id":"2782","n":"shoulder transverse adduction","bp":"shoulders","eq":"body weight","tg":"pectorals","mg":"shoulders","sm":["shoulders","upper chest"],"st":["Stand or sit tall with a relaxed posture and the joint in a neutral starting position.","Stand tall with one arm held out to the side at shoulder height.","Sweep the arm forward and across your body in a horizontal arc.","Keep the arm at shoulder height, pause, then return.","Repeat for 10-15 smooth reps, then switch sides if you are working one side at a time."],"img":"opengym/2782.webp","gif":null,"ext":1},{"id":"2783","n":"shoulder transverse extension","bp":"shoulders","eq":"body weight","tg":"delts","mg":"rear deltoids","sm":["rear deltoids","upper back"],"st":["Stand or sit tall with a relaxed posture and the joint in a neutral starting position.","Stand tall with your arm held in front at shoulder height.","Pull the arm back and out to the side, keeping it level.","Squeeze your shoulder blade lightly, then return slowly.","Repeat for 10-15 smooth reps, then switch sides if you are working one side at a time."],"img":"opengym/2783.webp","gif":null,"ext":1},{"id":"2784","n":"shoulder transverse flexion","bp":"shoulders","eq":"body weight","tg":"pectorals","mg":"shoulders","sm":["shoulders","upper chest"],"st":["Stand or sit tall with a relaxed posture and the joint in a neutral starting position.","Stand tall with your arm held out to the side at shoulder height.","Bring the arm forward in front of your chest, keeping it level.","Pause briefly, then return slowly to the side.","Repeat for 10-15 smooth reps, then switch sides if you are working one side at a time."],"img":"opengym/2784.webp","gif":null,"ext":1},{"id":"2785","n":"spine (lumbar) extension","bp":"waist","eq":"body weight","tg":"spine","mg":"lower back","sm":["lower back","glutes"],"st":["Stand or sit tall with a relaxed posture and the joint in a neutral starting position.","Stand with feet hip width apart and your hands on your hips.","Lean back gently, arching your lower back within a comfortable range.","Pause briefly, then return upright.","Repeat for 10-15 smooth reps, then switch sides if you are working one side at a time."],"img":"opengym/2785.webp","gif":null,"ext":1},{"id":"2786","n":"spine (lumbar) flexion","bp":"waist","eq":"body weight","tg":"abs","mg":"lower abs","sm":["lower abs","lower back"],"st":["Stand or sit tall with a relaxed posture and the joint in a neutral starting position.","Stand with feet hip width apart and knees slightly soft.","Round your lower back forward and tuck your chin and pelvis in.","Pause briefly, then return upright.","Repeat for 10-15 smooth reps, then switch sides if you are working one side at a time."],"img":"opengym/2786.webp","gif":null,"ext":1},{"id":"2787","n":"spine (lumbar) lateral flexion","bp":"waist","eq":"body weight","tg":"obliques","mg":"abdominals","sm":["abdominals","lower back"],"st":["Stand or sit tall with a relaxed posture and the joint in a neutral starting position.","Stand with feet hip width apart and your arms at your sides.","Slide one hand down the outside of your leg as you bend sideways.","Keep your hips level, return to upright, then bend to the other side.","Repeat for 10-15 smooth reps, then switch sides if you are working one side at a time."],"img":"opengym/2787.webp","gif":null,"ext":1},{"id":"2788","n":"spine (lumbar) rotation","bp":"waist","eq":"body weight","tg":"abs","mg":"obliques","sm":["obliques","lower back"],"st":["Stand or sit tall with a relaxed posture and the joint in a neutral starting position.","Stand with feet hip width apart and your arms crossed over your chest.","Rotate your torso to one side while keeping the hips facing forward.","Return to center, then rotate to the other side.","Repeat for 10-15 smooth reps, then switch sides if you are working one side at a time."],"img":"opengym/2788.webp","gif":null,"ext":1},{"id":"2789","n":"wrist adduction","bp":"lower arms","eq":"body weight","tg":"forearms","mg":"wrist flexors","sm":["wrist flexors","wrist extensors"],"st":["Stand or sit tall with a relaxed posture and the joint in a neutral starting position.","Rest your forearm on a table with your hand hanging off the edge, thumb up.","Tilt your hand down toward the little finger side.","Pause briefly, then return to neutral under control.","Repeat for 10-15 smooth reps, then switch sides if you are working one side at a time."],"img":"opengym/2789.webp","gif":null,"ext":1},{"id":"2790","n":"wrist extension","bp":"lower arms","eq":"body weight","tg":"forearms","mg":"wrist extensors","sm":["wrist extensors"],"st":["Stand or sit tall with a relaxed posture and the joint in a neutral starting position.","Rest your forearm on a table with your hand hanging off the edge, palm down.","Raise your hand upward by bending the wrist back.","Pause briefly, then lower slowly.","Repeat for 10-15 smooth reps, then switch sides if you are working one side at a time."],"img":"opengym/2790.webp","gif":null,"ext":1},{"id":"2791","n":"wrist flexion","bp":"lower arms","eq":"body weight","tg":"forearms","mg":"wrist flexors","sm":["wrist flexors"],"st":["Stand or sit tall with a relaxed posture and the joint in a neutral starting position.","Rest your forearm on a table with your hand hanging off the edge, palm up.","Curl your hand upward by bending the wrist toward your forearm.","Pause briefly, then lower slowly.","Repeat for 10-15 smooth reps, then switch sides if you are working one side at a time."],"img":"opengym/2791.webp","gif":null,"ext":1},{"id":"2792","n":"plank jump","bp":"full body","eq":"body weight","tg":"cardiovascular system","mg":"core","sm":["core","shoulders","quadriceps"],"st":["Start in a high plank with hands under shoulders.","Jump both feet out wide.","Jump them back together.","Keep your hips level and core tight.","Move at a steady pace."],"img":"opengym/2792.webp","gif":null,"ext":1},{"id":"2793","n":"plank walk up","bp":"full body","eq":"body weight","tg":"abs","mg":"shoulders","sm":["shoulders","triceps","core","chest"],"st":["Start in a forearm plank.","Place one hand and then the other on the floor to rise to a high plank.","Lower one forearm and then the other back down.","Keep your hips steady.","Alternate the leading arm each rep."],"img":"opengym/2793.webp","gif":null,"ext":1},{"id":"2797","n":"barbell squat jump step rear lunge v. 2","bp":"upper legs","eq":"barbell","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","calves","core"],"st":["Rest the barbell across your upper back and stand with feet shoulder width apart.","Squat down, then jump up lightly and land softly.","Step one foot back into a rear lunge, lowering your back knee toward the floor.","Push through the front foot to return to standing.","Alternate legs on each rep, keeping your chest tall."],"img":"opengym/2797.webp","gif":null,"ext":1},{"id":"2804","n":"dumbbell supported squat v. 2","bp":"upper legs","eq":"dumbbell","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","calves","core"],"st":["Hold a dumbbell in one hand and rest the other hand on a stable support.","Stand with feet shoulder width apart and toes slightly out.","Sit your hips back and down until your thighs are about parallel.","Drive through your heels to stand, keeping your chest up.","Switch the dumbbell hand halfway through if needed."],"img":"opengym/2804.webp","gif":null,"ext":1},{"id":"2806","n":"dumbbell single leg deadlift with stepbox support v. 2","bp":"upper legs","eq":"dumbbell","tg":"hamstrings","mg":"glutes","sm":["glutes","lower back","core","grip muscles"],"st":["Hold a dumbbell and rest the toes of one foot on a step box behind you.","Soften the front knee and hinge at the hips, lowering the dumbbell along your leg.","Keep your back flat and go as far as your hamstring allows.","Drive your hips forward to stand tall.","Complete all reps, then switch legs."],"img":"opengym/2806.webp","gif":null,"ext":1},{"id":"2807","n":"dumbbell sumo pull through v. 2","bp":"upper legs","eq":"dumbbell","tg":"glutes","mg":"adductors","sm":["adductors","hamstrings","quadriceps","lower back"],"st":["Stand with feet wide and toes turned out, holding one dumbbell with both hands.","Hinge at the hips and swing the dumbbell back between your legs.","Keep your back flat and chest up.","Drive your hips forward and stand tall, swinging the dumbbell to hip height.","Squeeze your glutes at the top."],"img":"opengym/2807.webp","gif":null,"ext":1},{"id":"2809","n":"barbell split squat v. 3","bp":"upper legs","eq":"barbell","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","adductors","core"],"st":["Rest the barbell across your upper back and step into a split stance.","Keep your torso upright and core braced.","Lower straight down until your back knee nearly touches the floor.","Press through your front foot to rise.","Finish all reps, then switch legs."],"img":"opengym/2809.webp","gif":null,"ext":1},{"id":"2811","n":"barbell leg twist press","bp":"upper legs","eq":"barbell","tg":"glutes","mg":"quadriceps","sm":["quadriceps","obliques","shoulders","core"],"st":["Hold a barbell at your shoulders with feet shoulder width apart.","Step one foot out and rotate your hips and torso with it, bending into a rotated lunge.","Drive back up and press the bar overhead as you stand.","Lower the bar to your shoulders.","Alternate sides on each rep."],"img":"opengym/2811.webp","gif":null,"ext":1},{"id":"2814","n":"one arm twisted clean and press","bp":"full body","eq":"dumbbell","tg":"delts","mg":"glutes","sm":["glutes","triceps","obliques","quadriceps","core"],"st":["Stand with feet shoulder width apart, holding a weight in one hand low in front of you.","Pull it up to your shoulder with a hip drive and a slight turn of the body.","Turn your feet and hips back to face forward as you dip your knees.","Press the weight overhead until your arm locks.","Lower with control and repeat, then switch sides."],"img":"opengym/2814.webp","gif":null,"ext":1},{"id":"2815","n":"v up down (with stability ball)","bp":"waist","eq":"stability ball","tg":"abs","mg":"lower abs","sm":["lower abs","hip flexors","core"],"st":["Lie on your back holding the stability ball overhead with straight arms.","Lift your arms and legs up together, curling into a V.","Pass the ball from your hands to your feet.","Lower back down slowly, holding the ball between your feet.","Repeat, passing the ball back to your hands."],"img":"opengym/2815.webp","gif":null,"ext":1},{"id":"2828","n":"battling ropes side raise","bp":"shoulders","eq":"rope","tg":"delts","mg":"upper back","sm":["upper back","forearms","core","trapezius"],"st":["Stand in a slight squat holding a rope end in each hand.","Keep your core braced and elbows soft.","Raise both arms out to the sides to about shoulder height in a quick, controlled motion.","Lower and repeat at a steady fast pace.","Work in intervals of 20-30 seconds."],"img":"opengym/2828.webp","gif":null,"ext":1},{"id":"2830","n":"power sled rear lunge","bp":"upper legs","eq":"sled machine","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","calves","core"],"st":["Hold the sled handles and stand tall with your feet together.","Step one foot back into a lunge, lowering your back knee toward the floor.","Keep your torso upright and your front knee over your ankle.","Push through the front foot to return to standing.","Alternate legs on each rep."],"img":"opengym/2830.webp","gif":null,"ext":1},{"id":"2831","n":"pike push up (on bench)","bp":"shoulders","eq":"body weight","tg":"delts","mg":"triceps","sm":["triceps","upper chest","core","upper back"],"st":["Place your feet on a bench and your hands on the floor, hips raised in an inverted V.","Keep your legs straight and your core braced.","Bend your elbows and lower your head toward the floor.","Press back up until your arms are straight.","Keep your elbows at about 45 degrees to your body."],"img":"opengym/2831.webp","gif":null,"ext":1},{"id":"2834","n":"suspender weighted inverted row","bp":"back","eq":"suspension trainer","tg":"upper back","mg":"lats","sm":["lats","biceps","rhomboids","rear deltoids","core"],"st":["Hold the suspension handles and lean back with your body in a straight line, with weight on your torso.","Keep your arms straight and heels on the floor.","Pull your chest up toward the handles, squeezing your shoulder blades.","Pause briefly at the top.","Lower slowly to full arm extension."],"img":"opengym/2834.webp","gif":null,"ext":1},{"id":"2835","n":"cable narrow chair stand up","bp":"upper legs","eq":"cable","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","core"],"st":["Sit on a chair holding the cable handle at your chest.","Keep your feet close together.","Lean forward slightly.","Push through your heels to stand.","Lower back under control."],"img":"opengym/2835.webp","gif":null,"ext":1},{"id":"2836","n":"cable stiff leg deadlift from stepbox","bp":"upper legs","eq":"cable","tg":"hamstrings","mg":"glutes","sm":["glutes","lower back","core"],"st":["Stand on a step box facing a low cable and hold the handle.","Keep your knees nearly straight.","Hinge at the hips and lower the handle.","Keep your back flat.","Squeeze your glutes to stand."],"img":"opengym/2836.webp","gif":null,"ext":1},{"id":"2837","n":"cable rear lunge from stepbox","bp":"upper legs","eq":"cable","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","core"],"st":["Stand on a step box facing a cable and hold the handle.","Step one leg back and down to lunge.","Lower the back knee toward the floor.","Push through your front foot to return.","Switch legs after your reps."],"img":"opengym/2837.webp","gif":null,"ext":1},{"id":"2839","n":"chest lift with rotation","bp":"waist","eq":"body weight","tg":"abs","mg":"obliques","sm":["obliques","core"],"st":["Lie on your back with knees bent and hands behind your head.","Curl your head and shoulders up.","Rotate your torso to one side.","Return to centre and lower.","Alternate sides."],"img":"opengym/2839.webp","gif":null,"ext":1},{"id":"2840","n":"control balance","bp":"waist","eq":"body weight","tg":"abs","mg":"hip flexors","sm":["hip flexors","hamstrings","core"],"st":["Lie on your back and roll your legs overhead.","Hold one ankle with both hands.","Extend the other leg out above you.","Switch legs with control.","Roll down slowly."],"img":"opengym/2840.webp","gif":null,"ext":1},{"id":"2841","n":"corkscrew","bp":"waist","eq":"body weight","tg":"abs","mg":"obliques","sm":["obliques","core","hip flexors"],"st":["Lie on your back with arms by your sides and legs raised up.","Lift your hips slightly and swing your legs across to one side.","Circle them down and around.","Bring them back up to the start.","Reverse the direction."],"img":"opengym/2841.webp","gif":null,"ext":1},{"id":"2842","n":"crab","bp":"waist","eq":"body weight","tg":"abs","mg":"obliques","sm":["obliques","core","hip flexors"],"st":["Sit with your legs crossed and hold your feet.","Roll back onto your shoulders.","Cross your legs the other way.","Roll back up.","Keep your movement smooth."],"img":"opengym/2842.webp","gif":null,"ext":1},{"id":"2843","n":"double leg stretch","bp":"waist","eq":"body weight","tg":"abs","mg":"lower abs","sm":["lower abs","hip flexors","core"],"st":["Lie on your back and curl your head and shoulders up.","Hug your knees to your chest.","Reach your arms overhead while extending your legs.","Circle your arms and draw your knees back in.","Keep your lower back down."],"img":"opengym/2843.webp","gif":null,"ext":1},{"id":"2844","n":"floor hyperextension v. 2","bp":"back","eq":"body weight","tg":"spine","mg":"glutes","sm":["glutes","hamstrings","upper back"],"st":["Lie face down with arms extended in front.","Lengthen your neck.","Lift your arms, chest and legs off the floor.","Hold briefly.","Lower slowly."],"img":"opengym/2844.webp","gif":null,"ext":1},{"id":"2845","n":"hip twist supported arms","bp":"waist","eq":"body weight","tg":"obliques","mg":"core","sm":["core","hip flexors"],"st":["Sit with your hands behind you and legs lifted.","Keep your chest open.","Rotate your hips to one side.","Circle your legs back to the centre.","Switch sides."],"img":"opengym/2845.webp","gif":null,"ext":1},{"id":"2846","n":"hundred","bp":"waist","eq":"body weight","tg":"abs","mg":"lower abs","sm":["lower abs","hip flexors","core"],"st":["Lie on your back and lift your head and shoulders.","Raise your legs to a tabletop or extend them.","Pump your arms up and down in small beats.","Breathe in for five beats and out for five.","Aim for one hundred beats."],"img":"opengym/2846.webp","gif":null,"ext":1},{"id":"2848","n":"leg pull side","bp":"waist","eq":"body weight","tg":"abs","mg":"obliques","sm":["obliques","shoulders","glutes"],"st":["Start in a side plank on one hand.","Keep your body in a straight line.","Lift your top leg.","Hold briefly.","Lower and switch sides."],"img":"opengym/2848.webp","gif":null,"ext":1},{"id":"2849","n":"leg pull","bp":"waist","eq":"body weight","tg":"abs","mg":"shoulders","sm":["shoulders","glutes","hamstrings","core"],"st":["Start in a high plank.","Brace your core.","Lift one leg a few inches.","Lower and switch legs.","Keep your hips level."],"img":"opengym/2849.webp","gif":null,"ext":1},{"id":"2850","n":"leg raise (bent knee)","bp":"waist","eq":"body weight","tg":"abs","mg":"lower abs","sm":["lower abs","hip flexors"],"st":["Lie on your back with arms by your sides.","Bend your knees.","Raise your legs until your thighs are vertical.","Lower slowly without arching.","Keep your lower back on the floor."],"img":"opengym/2850.webp","gif":null,"ext":1},{"id":"2851","n":"lying double leg kick","bp":"back","eq":"body weight","tg":"spine","mg":"glutes","sm":["glutes","hamstrings","upper back"],"st":["Lie face down with your hands clasped behind your back.","Kick both heels toward your glutes.","Lift your chest and extend your arms back.","Lower down.","Repeat smoothly."],"img":"opengym/2851.webp","gif":null,"ext":1},{"id":"2852","n":"lying leg lift side","bp":"upper legs","eq":"body weight","tg":"abductors","mg":"glutes","sm":["glutes","obliques"],"st":["Lie on your side with legs stacked.","Support your head with your arm.","Lift your top leg.","Lower slowly.","Finish your reps, then switch sides."],"img":"opengym/2852.webp","gif":null,"ext":1},{"id":"2853","n":"lying neck pull","bp":"waist","eq":"body weight","tg":"abs","mg":"hip flexors","sm":["hip flexors","sternocleidomastoid","core"],"st":["Lie on your back with hands behind your head.","Curl your head and shoulders up.","Roll up to sit.","Reach forward.","Roll down with control."],"img":"opengym/2853.webp","gif":null,"ext":1},{"id":"2854","n":"lying single leg circle","bp":"upper legs","eq":"body weight","tg":"abductors","mg":"glutes","sm":["glutes","hip flexors","core"],"st":["Lie on your back with one leg extended up.","Keep your pelvis still.","Draw small circles with that leg.","Reverse direction.","Switch legs."],"img":"opengym/2854.webp","gif":null,"ext":1},{"id":"2855","n":"lying single leg kick","bp":"back","eq":"body weight","tg":"spine","mg":"hamstrings","sm":["hamstrings","glutes","upper back"],"st":["Lie face down and prop yourself on your forearms.","Keep your chest lifted.","Kick one heel toward your glute twice.","Lower and switch legs.","Keep your hips down."],"img":"opengym/2855.webp","gif":null,"ext":1},{"id":"2856","n":"rocker with open legs","bp":"waist","eq":"body weight","tg":"abs","mg":"hip flexors","sm":["hip flexors","hamstrings","core"],"st":["Sit and hold your ankles with your legs in a V.","Balance on your tailbone.","Roll back onto your shoulders.","Roll up to balance again.","Keep your back rounded."],"img":"opengym/2856.webp","gif":null,"ext":1},{"id":"2857","n":"rocking","bp":"back","eq":"body weight","tg":"spine","mg":"glutes","sm":["glutes","hamstrings","upper back"],"st":["Lie face down and reach back to hold your ankles.","Lift your chest and legs.","Rock forward and back.","Keep your movement smooth.","Lower down to finish."],"img":"opengym/2857.webp","gif":null,"ext":1},{"id":"2858","n":"roll up v. 2","bp":"waist","eq":"body weight","tg":"abs","mg":"hip flexors","sm":["hip flexors","core"],"st":["Lie on your back with arms overhead.","Lift your arms and curl your head and chest up.","Roll up one vertebra at a time.","Reach over your legs.","Roll back down slowly."],"img":"opengym/2858.webp","gif":null,"ext":1},{"id":"2859","n":"rolling back","bp":"waist","eq":"body weight","tg":"abs","mg":"lower abs","sm":["lower abs","core"],"st":["Sit with your knees tucked and hold your shins.","Round your back.","Roll back onto your shoulders.","Roll back up to balance.","Keep your chin tucked."],"img":"opengym/2859.webp","gif":null,"ext":1},{"id":"2860","n":"rollover","bp":"waist","eq":"body weight","tg":"abs","mg":"lower abs","sm":["lower abs","hip flexors","hamstrings"],"st":["Lie on your back with legs raised.","Roll your legs overhead.","Open them to hip width.","Roll down slowly.","Keep your arms pressing down."],"img":"opengym/2860.webp","gif":null,"ext":1},{"id":"2861","n":"saw","bp":"waist","eq":"body weight","tg":"abs","mg":"obliques","sm":["obliques","hamstrings","lower back"],"st":["Sit with legs wide and arms out.","Rotate your torso to one side.","Reach your hand past your opposite foot.","Return to centre.","Switch sides."],"img":"opengym/2861.webp","gif":null,"ext":1},{"id":"2862","n":"scissors","bp":"waist","eq":"body weight","tg":"abs","mg":"lower abs","sm":["lower abs","hip flexors","hamstrings"],"st":["Lie on your back with your hips lifted and hands supporting them.","Raise your legs up.","Lower one leg while the other stays up.","Switch legs.","Keep the movement steady."],"img":"opengym/2862.webp","gif":null,"ext":1},{"id":"2863","n":"shoulder bridge","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"hamstrings","sm":["hamstrings","core","lower back"],"st":["Lie on your back with knees bent.","Lift your hips into a bridge.","Extend one leg up.","Lower it and switch legs.","Roll down slowly."],"img":"opengym/2863.webp","gif":null,"ext":1},{"id":"2866","n":"side twist","bp":"waist","eq":"body weight","tg":"obliques","mg":"core","sm":["core","shoulders"],"st":["Set up in a side support with one hand on the mat and your feet stacked.","Lift your hips and reach your top arm to the ceiling.","Thread the top arm under your body as you rotate your torso.","Open back up and reach to the ceiling again.","Keep your hips lifted throughout, then switch sides."],"img":"opengym/2866.webp","gif":null,"ext":1},{"id":"2868","n":"spine twist v. 2","bp":"waist","eq":"body weight","tg":"obliques","mg":"core","sm":["core","lower back"],"st":["Sit tall with your legs extended and arms reaching out to the sides.","Flex your feet and grow tall through the crown of your head.","Twist your torso to one side, pulsing gently for a small extra turn.","Return to center without sagging in the chest.","Twist to the other side and repeat."],"img":"opengym/2868.webp","gif":null,"ext":1},{"id":"2869","n":"swan dive","bp":"back","eq":"body weight","tg":"spine","mg":"glutes","sm":["glutes","hamstrings","shoulders"],"st":["Lie face down with your hands under your shoulders and legs together.","Press up into a swan, lifting your chest off the mat.","Let your arms float forward as you rock your chest and legs up.","Rock back and forth in a smooth, controlled rhythm.","Keep your neck long and your abs gently drawn in."],"img":"opengym/2869.webp","gif":null,"ext":1},{"id":"2870","n":"swimming","bp":"back","eq":"body weight","tg":"spine","mg":"glutes","sm":["glutes","hamstrings","rear deltoids"],"st":["Lie face down with arms extended overhead and legs long.","Lift your arms, chest and legs slightly off the mat.","Flutter opposite arm and leg up and down in a quick, small rhythm.","Keep your abs drawn in and your neck long.","Continue for 20-30 seconds, then rest."],"img":"opengym/2870.webp","gif":null,"ext":1},{"id":"2871","n":"teaser","bp":"waist","eq":"body weight","tg":"abs","mg":"hip flexors","sm":["hip flexors","lower abs","core"],"st":["Lie on your back with legs extended and arms overhead.","Roll up while lifting your legs to form a V shape.","Reach your arms parallel to your legs and balance on your sit bones.","Hold briefly with a flat, strong back.","Roll down slowly with control and repeat."],"img":"opengym/2871.webp","gif":null,"ext":1},{"id":"2872","n":"single leg stretch (bent knee) v. 2","bp":"waist","eq":"body weight","tg":"abs","mg":"hip flexors","sm":["hip flexors","core","obliques"],"st":["Lie on your back and curl your head and shoulders off the mat.","Pull one knee toward your chest, with hands on that shin.","Extend the other leg long at a low angle.","Switch legs in a steady rhythm.","Keep your lower back anchored to the mat."],"img":"opengym/2872.webp","gif":null,"ext":1},{"id":"2873","n":"spine stretch forward v. 2","bp":"back","eq":"body weight","tg":"spine","mg":"hamstrings","sm":["hamstrings","core","lower back"],"st":["Sit tall with legs extended hip-width apart and arms reaching forward.","Draw your belly in and flex your feet.","Curl forward one vertebra at a time, reaching over an imaginary ball.","Hold for a breath at the bottom.","Roll back up to tall sitting and repeat."],"img":"opengym/2873.webp","gif":null,"ext":1},{"id":"2874","n":"leg pull front supported","bp":"waist","eq":"body weight","tg":"abs","mg":"shoulders","sm":["shoulders","glutes","hamstrings"],"st":["Start in a high plank with hands under your shoulders.","Keep your body in one straight line from head to heels.","Lift one leg a few inches without shifting your hips.","Lower it and repeat on the other leg.","Keep your abs tight and your neck long."],"img":"opengym/2874.webp","gif":null,"ext":1},{"id":"2875","n":"side kick kneeling","bp":"upper legs","eq":"body weight","tg":"abductors","mg":"glutes","sm":["glutes","obliques","core"],"st":["Kneel on one knee with the opposite leg extended to the side.","Place your bottom hand on the mat and keep the top hand light behind your head.","Kick the top leg forward, then sweep it back with control.","Keep your torso steady and tall.","Complete your reps, then switch sides."],"img":"opengym/2875.webp","gif":null,"ext":1},{"id":"2876","n":"boomerang","bp":"waist","eq":"body weight","tg":"abs","mg":"hip flexors","sm":["hip flexors","core","lower back"],"st":["Sit tall with legs extended and crossed at the ankles.","Roll back and lift your legs overhead, then switch the cross.","Roll up to a teaser with your legs lifted.","Hold your hands behind you and then reach forward over your legs.","Move smoothly, using your abs to control each roll."],"img":"opengym/2876.webp","gif":null,"ext":1},{"id":"2877","n":"seal","bp":"waist","eq":"body weight","tg":"abs","mg":"lower back","sm":["lower back","hip flexors","core"],"st":["Sit balanced on your tailbone with knees open and hands inside your ankles.","Tuck your chin and round your back into a ball.","Roll back to your shoulders and clap your feet together.","Roll up to the balance position and clap again.","Keep the roll smooth and avoid rolling onto your neck."],"img":"opengym/2877.webp","gif":null,"ext":1},{"id":"2878","n":"prone press swan","bp":"back","eq":"body weight","tg":"spine","mg":"glutes","sm":["glutes","triceps","shoulders"],"st":["Lie face down with hands beside your chest and legs together.","Press your pubic bone into the mat and engage your glutes.","Press through your hands to lift your chest.","Keep your neck long and shoulders away from your ears.","Lower slowly with control and repeat."],"img":"opengym/2878.webp","gif":null,"ext":1},{"id":"2879","n":"mermaid","bp":"waist","eq":"body weight","tg":"abs","mg":"obliques","sm":["obliques","lats","shoulders"],"st":["Sit with your legs folded to one side in a comfortable position.","Place one hand on the mat beside you.","Reach the other arm overhead and bend sideways over the supporting hand.","Hold for a breath, feeling the side stretch.","Return to tall sitting and switch sides."],"img":"opengym/2879.webp","gif":null,"ext":1},{"id":"2880","n":"swimming all fours","bp":"back","eq":"body weight","tg":"spine","mg":"glutes","sm":["glutes","rear deltoids","core"],"st":["Start on all fours with hands under shoulders and knees under hips.","Reach one arm forward and the opposite leg back.","Flutter them in small, quick pulses.","Keep your spine neutral and your hips level.","Switch sides and repeat."],"img":"opengym/2880.webp","gif":null,"ext":1},{"id":"2887","n":"cable hanging leg raise","bp":"waist","eq":"cable","tg":"abs","mg":"lower abs","sm":["lower abs","hip flexors","forearms","grip muscles"],"st":["Hang from a pull-up bar with the cable attached to your ankles.","Keep your arms straight and your body steady.","Raise your legs up in front of you toward hip height or higher.","Curl your pelvis slightly at the top.","Lower slowly without swinging."],"img":"opengym/2887.webp","gif":null,"ext":1},{"id":"2889","n":"starfish crunch (advanced)","bp":"waist","eq":"body weight","tg":"abs","mg":"obliques","sm":["obliques","hip flexors","core"],"st":["Lie on your back with arms and legs spread wide.","Brace your core and press your lower back into the floor.","Crunch up, bringing your arms and legs toward the center.","Slowly open back out to the starfish shape.","Keep your movements controlled and repeat."],"img":"opengym/2889.webp","gif":null,"ext":1},{"id":"2890","n":"front plank to push up","bp":"chest","eq":"body weight","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders","core"],"st":["Start in a forearm plank with elbows under shoulders.","Place one hand on the floor and press up, then the other.","Reach a high plank with straight arms.","Lower back to your forearms one arm at a time.","Alternate the leading arm each rep and keep your hips level."],"img":"opengym/2890.webp","gif":null,"ext":1},{"id":"2891","n":"flutter kicks (hands under hips head up)","bp":"waist","eq":"body weight","tg":"abs","mg":"lower abs","sm":["lower abs","hip flexors","quadriceps"],"st":["Lie on your back with hands tucked under your hips.","Lift your head and shoulders slightly off the floor.","Raise both legs a few inches above the ground.","Kick your legs up and down in small alternating pulses.","Keep your lower back pressed down and breathe steadily."],"img":"opengym/2891.webp","gif":null,"ext":1},{"id":"2892","n":"scissors (beginner)","bp":"waist","eq":"body weight","tg":"abs","mg":"lower abs","sm":["lower abs","hip flexors","core"],"st":["Lie on your back with arms by your sides.","Lift both legs a little off the floor.","Open them wide, then cross one over the other.","Alternate which leg is on top with each rep.","Keep your lower back flat on the floor."],"img":"opengym/2892.webp","gif":null,"ext":1},{"id":"2894","n":"front plank with arm lift","bp":"waist","eq":"body weight","tg":"abs","mg":"shoulders","sm":["shoulders","glutes","core"],"st":["Set up in a forearm plank with elbows under shoulders.","Squeeze your glutes and keep a straight line from head to heels.","Lift one arm forward without letting your hips twist.","Return it and lift the other arm.","Alternate in a slow, controlled rhythm."],"img":"opengym/2894.webp","gif":null,"ext":1},{"id":"2895","n":"front plank with arm lift (push up position)","bp":"waist","eq":"body weight","tg":"abs","mg":"shoulders","sm":["shoulders","triceps","core"],"st":["Start in a high plank with hands under shoulders.","Set your feet slightly wider for balance.","Lift one hand and reach it forward without twisting your hips.","Place it down and switch arms.","Keep your core braced throughout."],"img":"opengym/2895.webp","gif":null,"ext":1},{"id":"2897","n":"front plank with arm and leg lift (push up position)","bp":"waist","eq":"body weight","tg":"abs","mg":"glutes","sm":["glutes","shoulders","core"],"st":["Start in a high plank with hands under shoulders.","Lift one arm and the opposite leg at the same time.","Hold them in line with your body for a moment.","Lower them back to the floor with control.","Switch to the other arm and leg and repeat."],"img":"opengym/2897.webp","gif":null,"ext":1},{"id":"2899","n":"side plank (beginner)","bp":"waist","eq":"body weight","tg":"obliques","mg":"abdominals","sm":["abdominals","shoulders","glutes"],"st":["Lie on your side with knees bent and your elbow under your shoulder.","Stack your hips and knees.","Press into your forearm to lift your hips off the floor.","Hold a straight line from knees to head.","Hold for 20-30 seconds, then switch sides."],"img":"opengym/2899.webp","gif":null,"ext":1},{"id":"2900","n":"ez barbell standing preacher curl","bp":"upper arms","eq":"ez barbell","tg":"biceps","mg":"brachialis","sm":["brachialis","forearms","upper chest"],"st":["Stand facing a preacher pad and hold an EZ bar with an underhand grip.","Rest your upper arms on the pad with the arms extended.","Curl the bar up toward your shoulders.","Squeeze your biceps at the top.","Lower slowly until the arms are almost straight."],"img":"opengym/2900.webp","gif":null,"ext":1},{"id":"2901","n":"power sled biceps curl","bp":"upper arms","eq":"sled machine","tg":"biceps","mg":"brachialis","sm":["brachialis","forearms"],"st":["Stand facing the sled and grip the handle or strap with an underhand grip.","Keep your elbows tucked at your sides.","Curl your hands up toward your shoulders, moving the sled.","Squeeze your biceps at the top.","Lower slowly and keep your torso still."],"img":"opengym/2901.webp","gif":null,"ext":1},{"id":"2902","n":"power sled rear lunge row","bp":"back","eq":"sled machine","tg":"upper back","mg":"lats","sm":["lats","quadriceps","glutes","biceps","core"],"st":["Hold the sled handles with arms extended and feet together.","Step back into a rear lunge, lowering your back knee.","As you rise, row the handles toward your ribs, squeezing your shoulder blades.","Return to standing and extend your arms.","Alternate legs on each rep."],"img":"opengym/2902.webp","gif":null,"ext":1},{"id":"2903","n":"power sled rear lunge v. 2","bp":"upper legs","eq":"sled machine","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","calves","core"],"st":["Hold the sled handles and stand tall with feet together.","Step one foot back into a lunge, lowering your back knee toward the floor.","Keep your torso upright.","Push through the front foot to return to standing.","Alternate legs on each rep."],"img":"opengym/2903.webp","gif":null,"ext":1},{"id":"2904","n":"power sled rear batwing","bp":"upper legs","eq":"sled machine","tg":"hamstrings","mg":"glutes","sm":["glutes","rear deltoids","upper back","core"],"st":["Hold the sled handles and hinge slightly at the hips.","Keep your back flat and knees soft.","Pull the handles back and out to the sides like wings.","Squeeze your shoulder blades together.","Return slowly to the start."],"img":"opengym/2904.webp","gif":null,"ext":1},{"id":"2905","n":"power sled rear fly","bp":"shoulders","eq":"sled machine","tg":"delts","mg":"rear deltoids","sm":["rear deltoids","upper back","rhomboids","core"],"st":["Hold the sled handles with arms out in front and hinge slightly at the hips.","Keep a slight bend in your elbows.","Sweep your arms out to the sides, squeezing your shoulder blades.","Pause briefly.","Return slowly."],"img":"opengym/2905.webp","gif":null,"ext":1},{"id":"2906","n":"power sled rear drag","bp":"upper legs","eq":"sled machine","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","calves","core"],"st":["Face the sled, holding its handles or straps with a slight lean back.","Keep your chest up and core braced.","Walk backward in steady steps, pulling the sled with you.","Keep your knees soft and drive through your legs.","Cover a set distance, then rest."],"img":"opengym/2906.webp","gif":null,"ext":1},{"id":"2907","n":"power sled backward push","bp":"upper legs","eq":"sled machine","tg":"quads","mg":"glutes","sm":["glutes","calves","core","hamstrings"],"st":["Stand behind the sled with your back to it and grip the handles.","Brace your core and lean slightly into the load.","Walk forward in powerful steps, pushing the sled.","Keep your stride steady and breathing controlled.","Cover a set distance, then rest."],"img":"opengym/2907.webp","gif":null,"ext":1},{"id":"2908","n":"power sled anti rotation forward walk","bp":"upper legs","eq":"sled machine","tg":"abs","mg":"glutes","sm":["glutes","core","obliques","quadriceps","hamstrings"],"st":["Set a light load and stand side-on to the pull, gripping the handle at chest height.","Brace your abs and keep your hips and shoulders square.","Walk forward in controlled steps without letting the torso twist.","Walk the set distance, then reset and repeat.","Switch sides and do the same distance."],"img":"opengym/2908.webp","gif":null,"ext":1},{"id":"2909","n":"power sled high pull","bp":"shoulders","eq":"sled machine","tg":"delts","mg":"upper back","sm":["upper back","trapezius","biceps","glutes"],"st":["Stand facing the sled and hold the handles or rope with arms long.","Hinge slightly at the hips with a flat back.","Drive your hips forward and pull the handles up toward your chest, elbows high.","Pause briefly at the top.","Lower under control and repeat."],"img":"opengym/2909.webp","gif":null,"ext":1},{"id":"2910","n":"dumbbell suitcase carry","bp":"upper legs","eq":"dumbbell","tg":"obliques","mg":"glutes","sm":["glutes","core","forearms","grip muscles","trapezius"],"st":["Pick up one dumbbell with a tall, braced posture and hold it at your side.","Keep your shoulders level and your ribs stacked over your hips.","Walk with steady steps without leaning toward the weight.","Cover the set distance, then put the weight down safely.","Switch hands and repeat."],"img":"opengym/2910.webp","gif":null,"ext":1},{"id":"2911","n":"dumbbell high low carry","bp":"upper legs","eq":"dumbbell","tg":"abs","mg":"glutes","sm":["glutes","shoulders","core","obliques","forearms","grip muscles"],"st":["Hold one dumbbell overhead with a locked, stable arm and the other at your side.","Stand tall with your ribs down and abs braced.","Walk with steady steps and keep the top arm stacked over your shoulder.","Walk the set distance, then lower the weights carefully.","Swap positions and repeat."],"img":"opengym/2911.webp","gif":null,"ext":1},{"id":"2912","n":"trap bar farmers carry","bp":"upper legs","eq":"trap bar","tg":"forearms","mg":"traps","sm":["traps","grip muscles","glutes","core","quadriceps"],"st":["Stand inside the trap bar and hinge down to grip the handles.","Stand up with a flat back, shoulders back and chest tall.","Walk with short, quick steps, keeping the bar still.","Cover the set distance without leaning or shrugging.","Lower the bar back to the floor with control."],"img":"opengym/2912.webp","gif":null,"ext":1},{"id":"2913","n":"dumbbell overhead carry","bp":"shoulders","eq":"dumbbell","tg":"delts","mg":"triceps","sm":["triceps","core","upper back","trapezius","obliques"],"st":["Press a dumbbell overhead and lock out your elbow with the biceps near your ear.","Brace your abs and keep your ribs down.","Walk with steady steps without letting the arm drift forward.","Cover the set distance, then lower the weight with control.","Switch arms and repeat."],"img":"opengym/2913.webp","gif":null,"ext":1},{"id":"2914","n":"barbell overhead carry","bp":"shoulders","eq":"barbell","tg":"delts","mg":"triceps","sm":["triceps","core","upper back","trapezius","glutes"],"st":["Press the barbell overhead with a grip just outside shoulder width.","Squeeze your glutes and keep your ribs down.","Walk with small, steady steps, keeping the bar over your mid-foot.","Cover the set distance without arching your back.","Lower the bar to your shoulders and set it down safely."],"img":"opengym/2914.webp","gif":null,"ext":1},{"id":"2915","n":"barbell zercher carry","bp":"upper legs","eq":"barbell","tg":"abs","mg":"glutes","sm":["glutes","quadriceps","core","biceps","upper back","lower back"],"st":["Set the bar in your elbow crooks, hugging it tight to your chest.","Stand tall with your chest up and your abs braced.","Walk with controlled steps while keeping the bar close.","Cover the set distance without rounding forward.","Lower the bar to the rack or floor carefully."],"img":"opengym/2915.webp","gif":null,"ext":1},{"id":"2916","n":"kettlebell goblet carry","bp":"upper legs","eq":"kettlebell","tg":"abs","mg":"glutes","sm":["glutes","core","biceps","upper back","forearms","quadriceps"],"st":["Hold a kettlebell by the horns close to your chest, elbows tucked.","Stand tall with your ribs down and abs braced.","Walk with steady steps without leaning back.","Cover the set distance, keeping the bell high and still.","Set the kettlebell down with a flat back."],"img":"opengym/2916.webp","gif":null,"ext":1},{"id":"2917","n":"dumbbell farmers carry","bp":"lower arms","eq":"dumbbell","tg":"forearms","mg":"grip muscles","sm":["grip muscles","trapezius","core","glutes","upper back"],"st":["Hold a dumbbell in each hand at your sides and stand tall.","Pull your shoulders back and down and brace your abs.","Walk with quick, controlled steps without swinging the weights.","Cover the set distance, then lower the dumbbells safely."],"img":"opengym/2917.webp","gif":null,"ext":1},{"id":"2918","n":"barbell suitcase carry","bp":"waist","eq":"barbell","tg":"abs","mg":"core","sm":["core","glutes","forearms","grip muscles","trapezius"],"st":["Stand with the barbell at your side and grip it near its center of balance.","Lift it while keeping your torso tall and level.","Walk with steady steps and resist tilting toward the weight.","Cover the set distance, then lower the bar carefully.","Switch hands and repeat."],"img":"opengym/2918.webp","gif":null,"ext":1},{"id":"2919","n":"smith hex press","bp":"chest","eq":"smith machine","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders","upper chest"],"st":["Lie on a bench under the Smith bar and hold a weight plate between your palms if you like.","Unrack the bar with a close grip and hold it over your chest.","Squeeze your hands inward as you lower the bar to your mid chest.","Press back up while still squeezing.","Rerack the bar when done."],"img":"opengym/2919.webp","gif":null,"ext":1},{"id":"2920","n":"single leg bodyweight deadlift with arm and leg extended","bp":"upper legs","eq":"body weight","tg":"hamstrings","mg":"glutes","sm":["glutes","lower back","core"],"st":["Stand on one leg with arms reaching forward.","Soften your standing knee slightly.","Hinge at the hips as your free leg lifts behind you.","Keep your back flat and body in a long line.","Return to standing and repeat, then switch legs."],"img":"opengym/2920.webp","gif":null,"ext":1},{"id":"2921","n":"pike push up","bp":"shoulders","eq":"body weight","tg":"delts","mg":"triceps","sm":["triceps","upper chest","core"],"st":["Start in a push-up position, then walk your feet in and lift your hips into an inverted V.","Keep your arms and back straight.","Bend your elbows and lower the top of your head toward the floor.","Press back up until your arms are straight.","Keep your core tight throughout."],"img":"opengym/2921.webp","gif":null,"ext":1},{"id":"2922","n":"bodyweight standing biceps curl","bp":"upper arms","eq":"body weight","tg":"biceps","mg":"brachialis","sm":["brachialis","forearms","shoulders"],"st":["Stand tall with your feet hip-width apart.","Place one hand under the wrist of your other hand to give resistance.","Curl the working hand toward your shoulder while the other hand pushes down.","Squeeze the biceps at the top.","Lower slowly, finish the reps, then switch arms."],"img":"opengym/2922.webp","gif":null,"ext":1},{"id":"2924","n":"cable side lying lateral raise","bp":"shoulders","eq":"cable","tg":"delts","mg":"rotator cuff","sm":["rotator cuff","upper back","trapezius"],"st":["Lie on your side next to a low cable pulley and grab the handle with your top hand.","Keep your arm straight with a slight bend in the elbow.","Raise your arm out to the side until it is near shoulder height.","Pause briefly at the top.","Lower slowly, finish the reps, then switch sides."],"img":"opengym/2924.webp","gif":null,"ext":1},{"id":"2925","n":"dumbbell single leg step up","bp":"upper legs","eq":"dumbbell","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","calves","core"],"st":["Hold a dumbbell in each hand and stand facing a box or bench.","Place one foot fully on the box.","Drive through that heel to stand up tall.","Lower back down under control without bouncing off the floor foot.","Finish the reps, then switch legs."],"img":"opengym/2925.webp","gif":null,"ext":1},{"id":"2926","n":"x band side walk","bp":"upper legs","eq":"band","tg":"abductors","mg":"glutes","sm":["glutes","quadriceps","hip flexors","calves"],"st":["Cross the band into an X and place it around your feet or lower legs, holding the ends as needed.","Stand in a quarter squat with your chest up.","Step sideways, keeping tension on the band.","Bring the trailing foot in without letting your feet touch.","Walk the set distance, then return the other way."],"img":"opengym/2926.webp","gif":null,"ext":1},{"id":"2927","n":"kettlebell kneeling one arm bottoms up press","bp":"shoulders","eq":"kettlebell","tg":"delts","mg":"triceps","sm":["triceps","rotator cuff","core","forearms","grip muscles"],"st":["Kneel on both knees and hold a kettlebell bottoms up at shoulder height.","Squeeze the handle tight and keep your wrist straight.","Press the bell straight overhead.","Lower slowly to your shoulder, keeping the bell balanced.","Finish the reps, then switch arms."],"img":"opengym/2927.webp","gif":null,"ext":1},{"id":"2928","n":"barbell overhead shrug","bp":"back","eq":"barbell","tg":"traps","mg":"upper back","sm":["upper back","shoulders","trapezius","forearms","core"],"st":["Hold a barbell locked out overhead with a wide grip.","Keep your arms straight and your ribs down.","Shrug your shoulders up toward your ears.","Pause briefly at the top.","Lower slowly without bending your elbows."],"img":"opengym/2928.webp","gif":null,"ext":1},{"id":"2929","n":"kneeling battling ropes","bp":"full body","eq":"rope","tg":"delts","mg":"core","sm":["core","upper back","forearms","grip muscles","lats"],"st":["Kneel in front of the anchored ropes and hold an end in each hand.","Brace your abs and keep your chest up.","Raise and lower your arms alternately to create waves.","Keep the waves quick and steady.","Work for a set time, then rest."],"img":"opengym/2929.webp","gif":null,"ext":1},{"id":"2930","n":"resistance band pullapart (supination at 90 degrees)","bp":"shoulders","eq":"resistance band","tg":"delts","mg":"upper back","sm":["upper back","rhomboids","trapezius","rotator cuff"],"st":["Hold a band in front of you at chest height with palms up and elbows bent at 90 degrees.","Keep your elbows tucked near your sides.","Rotate your forearms outward, pulling the band apart.","Squeeze your shoulder blades together briefly.","Return slowly and repeat."],"img":"opengym/2930.webp","gif":null,"ext":1},{"id":"2931","n":"shoulder flexion back to wall","bp":"shoulders","eq":"body weight","tg":"delts","mg":"upper back","sm":["upper back","trapezius","rotator cuff","core"],"st":["Stand with your back, head and hips against a wall.","Keep your arms at your sides with elbows straight.","Raise your arms forward and up overhead as far as you can without arching your back.","Pause at the top.","Lower slowly and repeat."],"img":"opengym/2931.webp","gif":null,"ext":1},{"id":"2932","n":"kettlebell kneeling one arm shoulder press","bp":"shoulders","eq":"kettlebell","tg":"delts","mg":"triceps","sm":["triceps","core","upper chest","glutes"],"st":["Kneel on both knees with a kettlebell racked at your shoulder.","Squeeze your glutes and brace your abs.","Press the kettlebell overhead until your arm is straight.","Lower it slowly back to your shoulder.","Finish the reps, then switch arms."],"img":"opengym/2932.webp","gif":null,"ext":1},{"id":"2933","n":"rear lunge with battling ropes","bp":"full body","eq":"rope","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","shoulders","core","upper back"],"st":["Stand holding the ends of the battle ropes, feet hip-width apart.","Step one foot back into a lunge while making a wave with the ropes.","Push through your front heel to return to standing.","Alternate legs, keeping the rope waves going.","Work for a set time, then rest."],"img":"opengym/2933.webp","gif":null,"ext":1},{"id":"2934","n":"kettlebell half kneeling shoulder press","bp":"shoulders","eq":"kettlebell","tg":"delts","mg":"triceps","sm":["triceps","core","glutes","upper chest"],"st":["Kneel on one knee with the other foot forward and a kettlebell racked at your shoulder.","Brace your abs and squeeze the glute of the kneeling leg.","Press the bell straight overhead.","Lower it back under control.","Finish the reps, then switch sides."],"img":"opengym/2934.webp","gif":null,"ext":1},{"id":"2935","n":"half kneeling pvc pec mobilization stretch","bp":"chest","eq":"body weight","tg":"pectorals","mg":"shoulders","sm":["shoulders","upper chest","biceps"],"st":["Kneel on one knee and grip a pipe or stick with one hand while the other arm reaches out.","Place the working forearm against a wall or post.","Gently rotate your torso away until you feel a stretch across your chest.","Hold for 20-30 seconds.","Switch sides."],"img":"opengym/2935.webp","gif":null,"ext":1},{"id":"2936","n":"rocking ankle stretch","bp":"lower legs","eq":"body weight","tg":"calves","mg":"soleus","sm":["soleus","ankles","shins"],"st":["Kneel on one knee with the front foot flat on the floor.","Keep your front heel down.","Rock your front knee forward over your toes until you feel a stretch.","Rock back and forth slowly for 20-30 seconds.","Switch legs."],"img":"opengym/2936.webp","gif":null,"ext":1},{"id":"2937","n":"stability ball rounded rollout","bp":"waist","eq":"stability ball","tg":"abs","mg":"shoulders","sm":["shoulders","lats","core"],"st":["Kneel in front of a stability ball with forearms on top.","Round your back slightly and tuck your pelvis.","Roll the ball forward by extending your arms.","Pull it back using your abs.","Keep your hips from sagging and move slowly."],"img":"opengym/2937.webp","gif":null,"ext":1},{"id":"2938","n":"band upper body resistance dead bug","bp":"waist","eq":"band","tg":"abs","mg":"core","sm":["core","lower abs","shoulders","hip flexors"],"st":["Lie on your back holding a band overhead and bring your knees up at 90 degrees.","Press your lower back into the floor.","Lower the opposite arm and leg while keeping band tension.","Return to the start and switch sides.","Keep your ribs down and move slowly."],"img":"opengym/2938.webp","gif":null,"ext":1},{"id":"2939","n":"kettlebell around head rotation","bp":"shoulders","eq":"kettlebell","tg":"delts","mg":"core","sm":["core","upper back","forearms","triceps"],"st":["Hold a kettlebell by the horns at chest height.","Stand tall with your abs braced.","Circle the bell around your head, keeping it close.","Keep your hips and ribs still.","Finish the reps, then reverse direction."],"img":"opengym/2939.webp","gif":null,"ext":1},{"id":"2940","n":"prone single arm trap raise","bp":"back","eq":"body weight","tg":"traps","mg":"upper back","sm":["upper back","rhomboids","rear deltoids","trapezius"],"st":["Lie face down with one arm hanging or reaching overhead, thumb up.","Keep your forehead down and neck relaxed.","Lift your arm in a Y shape by squeezing your shoulder blade down and back.","Pause at the top.","Lower slowly, finish the reps, then switch arms."],"img":"opengym/2940.webp","gif":null,"ext":1},{"id":"2941","n":"forearm wall slide","bp":"shoulders","eq":"body weight","tg":"serratus anterior","mg":"shoulders","sm":["shoulders","upper back","trapezius","rotator cuff"],"st":["Stand facing a wall with your forearms on it, elbows at shoulder height.","Lean in slightly and keep your abs braced.","Slide your forearms up the wall as you reach upward.","Pause at the top without arching your back.","Slide back down and repeat."],"img":"opengym/2941.webp","gif":null,"ext":1},{"id":"2942","n":"kettlebell angled press","bp":"shoulders","eq":"kettlebell","tg":"delts","mg":"triceps","sm":["triceps","upper chest","core"],"st":["Hold a kettlebell at your shoulder and stand tall.","Brace your abs and squeeze your glutes.","Press the bell up and slightly out to the side in a diagonal path.","Lock out your arm without leaning back.","Lower under control, finish the reps, then switch arms."],"img":"opengym/2942.webp","gif":null,"ext":1},{"id":"2943","n":"resistance band spider crawls","bp":"full body","eq":"resistance band","tg":"pectorals","mg":"shoulders","sm":["shoulders","core","triceps","hip flexors","obliques"],"st":["Place a band around your thighs and start in a push-up position.","Brace your core.","Bring one knee toward the same-side elbow while crawling forward.","Alternate sides while keeping the band under tension.","Crawl the set distance, then rest."],"img":"opengym/2943.webp","gif":null,"ext":1},{"id":"2944","n":"seal push up","bp":"chest","eq":"body weight","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders","upper back","lower back","core"],"st":["Lie face down with your hands under your shoulders and legs straight.","Push your upper body up with your arms like a seal.","Keep your hips on the floor and your core tight.","Lower slowly to the floor.","Repeat for smooth, controlled reps."],"img":"opengym/2944.webp","gif":null,"ext":1},{"id":"2945","n":"scapular slide back to wall","bp":"back","eq":"body weight","tg":"serratus anterior","mg":"trapezius","sm":["trapezius","rhomboids","shoulders","rotator cuff"],"st":["Stand with your back flat against a wall and your elbows bent at your sides.","Press your forearms and head lightly into the wall.","Slide your arms up the wall while keeping your shoulder blades down.","Stop before your back arches.","Slide down slowly and repeat."],"img":"opengym/2945.webp","gif":null,"ext":1},{"id":"2946","n":"single arm scapula push up","bp":"chest","eq":"body weight","tg":"serratus anterior","mg":"chest","sm":["chest","shoulders","triceps","core"],"st":["Start in a plank with one hand on the floor, the other behind your back or on your hip.","Keep your elbow locked straight.","Let your chest sink slightly between your shoulder blades.","Push the floor away to round your upper back slightly.","Finish the reps, then switch arms."],"img":"opengym/2946.webp","gif":null,"ext":1},{"id":"2947","n":"roll anterior calf foam rolling","bp":"lower legs","eq":"roller","tg":"shins","mg":"calves","sm":["calves","ankles"],"st":["Kneel on the floor and place the roller under the front of your shin.","Support yourself with your hands on the floor.","Roll slowly up and down the shin muscle.","Pause on tight spots for a few seconds.","Switch legs and keep the pressure comfortable."],"img":"opengym/2947.webp","gif":null,"ext":1},{"id":"2948","n":"roll pec foam rolling","bp":"chest","eq":"roller","tg":"pectorals","mg":"shoulders","sm":["shoulders","upper chest"],"st":["Lie face down and place the roller under one side of your chest.","Extend that arm out to the side.","Roll slowly side to side and up and down.","Pause on tight spots for a few seconds.","Switch sides and keep the pressure comfortable."],"img":"opengym/2948.webp","gif":null,"ext":1},{"id":"2949","n":"roll lat foam rolling","bp":"back","eq":"roller","tg":"lats","mg":"upper back","sm":["upper back","shoulders","triceps"],"st":["Lie on your side with the roller under your armpit area and your arm extended.","Support yourself with your lower arm and legs.","Roll slowly along your side toward the ribs.","Pause on tight spots for a few seconds.","Switch sides and keep the pressure comfortable."],"img":"opengym/2949.webp","gif":null,"ext":1},{"id":"2950","n":"lever belt squat","bp":"upper legs","eq":"leverage machine","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","adductors","calves"],"st":["Step into the belt and stand on the platforms with the belt snug on your hips.","Stand tall and brace your abs.","Squat down until your thighs are about parallel.","Push through your heels to stand back up.","Keep your chest up and knees tracking over your toes."],"img":"opengym/2950.webp","gif":null,"ext":1},{"id":"2951","n":"lever horizontal leg press","bp":"upper legs","eq":"leverage machine","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","adductors","calves"],"st":["Sit on the machine with your back flat against the pad and feet on the platform.","Set your feet about shoulder-width apart.","Press the platform away until your legs are nearly straight.","Do not lock your knees.","Lower slowly until your knees are bent about 90 degrees and repeat."],"img":"opengym/2951.webp","gif":null,"ext":1},{"id":"2952","n":"smith kneeling rear kick (with partner)","bp":"upper legs","eq":"smith machine","tg":"glutes","mg":"hamstrings","sm":["hamstrings","core","quadriceps"],"st":["Get on all fours and place the sole of one foot on the Smith bar, with your partner steadying you if needed.","Brace your core.","Press the bar up by extending your hip.","Squeeze your glute at the top.","Lower slowly, finish the reps, then switch legs."],"img":"opengym/2952.webp","gif":null,"ext":1},{"id":"2954","n":"cable standing reverse grip curl (straight bar)","bp":"lower arms","eq":"cable","tg":"forearms","mg":"brachialis","sm":["brachialis","biceps","wrist extensors"],"st":["Stand facing a low cable with a straight bar in an overhand grip.","Keep your elbows at your sides.","Curl the bar up toward your shoulders without swinging.","Squeeze at the top.","Lower slowly until your arms are straight."],"img":"opengym/2954.webp","gif":null,"ext":1},{"id":"2956","n":"dumbbell goblet split squat front foot elevated","bp":"upper legs","eq":"dumbbell","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","adductors","core"],"st":["Hold one dumbbell at your chest and place your front foot on a low platform.","Place your back foot behind you on the floor.","Lower your back knee toward the floor with your torso upright.","Push through your front heel to stand.","Finish the reps, then switch legs."],"img":"opengym/2956.webp","gif":null,"ext":1},{"id":"2957","n":"dumbbell split squat front foot elevated","bp":"upper legs","eq":"dumbbell","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","adductors","core"],"st":["Hold a dumbbell in each hand and place your front foot on a low platform.","Step your back foot behind you.","Lower your back knee toward the floor with your torso upright.","Push through your front heel to stand.","Finish the reps, then switch legs."],"img":"opengym/2957.webp","gif":null,"ext":1},{"id":"2960","n":"dumbbell split squat","bp":"upper legs","eq":"dumbbell","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","adductors","core"],"st":["Hold a dumbbell in each hand and take a long stance, one foot forward.","Keep your torso upright.","Lower your back knee toward the floor.","Push through your front heel to stand.","Finish the reps, then switch legs."],"img":"opengym/2960.webp","gif":null,"ext":1},{"id":"2961","n":"plank push up row","bp":"full body","eq":"dumbbell","tg":"upper back","mg":"lats","sm":["lats","chest","triceps","core","shoulders"],"st":["Start in a plank with a dumbbell in each hand and your feet wide.","Do a push-up, keeping your body straight.","Row one dumbbell up to your ribs without twisting your hips.","Lower it and row the other side.","Repeat the sequence with control."],"img":"opengym/2961.webp","gif":null,"ext":1},{"id":"2962","n":"lever seated hammer grip shoulder press","bp":"shoulders","eq":"leverage machine","tg":"delts","mg":"triceps","sm":["triceps","upper chest","trapezius"],"st":["Sit with your back against the pad and grip the neutral handles.","Keep your feet flat on the floor.","Press the handles overhead until your arms are almost straight.","Pause briefly.","Lower slowly to shoulder height and repeat."],"img":"opengym/2962.webp","gif":null,"ext":1},{"id":"2964","n":"barbell glute bridge (hands on bar)","bp":"upper legs","eq":"barbell","tg":"glutes","mg":"hamstrings","sm":["hamstrings","core","adductors"],"st":["Sit on the floor with a barbell over your hips, padded if needed.","Roll back, set your feet, and hold the bar with both hands.","Drive through your heels to lift your hips.","Squeeze your glutes at the top.","Lower slowly and repeat."],"img":"opengym/2964.webp","gif":null,"ext":1},{"id":"2966","n":"dumbbell front squat","bp":"upper legs","eq":"dumbbell","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","core","adductors"],"st":["Hold a dumbbell in each hand at your shoulders, elbows forward.","Stand with your feet shoulder-width apart.","Squat down until your thighs are about parallel.","Keep your chest up and knees tracking your toes.","Drive through your heels to stand."],"img":"opengym/2966.webp","gif":null,"ext":1},{"id":"2968","n":"dumbbell thruster","bp":"full body","eq":"dumbbell","tg":"quads","mg":"glutes","sm":["glutes","shoulders","triceps","core","hamstrings"],"st":["Hold dumbbells at your shoulders and stand with your feet shoulder-width apart.","Squat down with your chest up.","Drive up through your heels and press the dumbbells overhead in one motion.","Lock out your arms at the top.","Lower the weights to your shoulders and go straight into the next rep."],"img":"opengym/2968.webp","gif":null,"ext":1},{"id":"2969","n":"dumbbell thruster v. 2","bp":"full body","eq":"dumbbell","tg":"quads","mg":"glutes","sm":["glutes","shoulders","triceps"],"st":["Hold a dumbbell in each hand at your shoulders.","Squat down with your chest tall and knees tracking over your toes.","Drive up through your heels as you stand.","Use that momentum to press the dumbbells overhead.","Lower them to your shoulders and go into the next squat."],"img":"opengym/2969.webp","gif":null,"ext":1},{"id":"2970","n":"band thruster","bp":"full body","eq":"band","tg":"quads","mg":"glutes","sm":["glutes","shoulders","triceps","core","hamstrings"],"st":["Stand on the band and hold the ends at your shoulders.","Squat down with your chest up.","Drive up and press your hands overhead in one motion.","Lock out your arms at the top.","Lower your hands to your shoulders and repeat."],"img":"opengym/2970.webp","gif":null,"ext":1},{"id":"2972","n":"side lunge","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"quadriceps","sm":["quadriceps","adductors","hamstrings","inner thighs"],"st":["Stand tall with your feet together and hands in front of your chest.","Step wide to one side.","Bend that knee and sit your hips back, keeping the other leg straight.","Push off the bent leg to return.","Alternate sides."],"img":"opengym/2972.webp","gif":null,"ext":1},{"id":"2974","n":"lever one arm chest press (plate loaded)","bp":"chest","eq":"leverage machine","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders","upper chest"],"st":["Sit on the machine with your back against the pad and grip one handle.","Set your feet flat on the floor.","Press the handle forward until your arm is nearly straight.","Pause briefly.","Return slowly, finish the reps, then switch arms."],"img":"opengym/2974.webp","gif":null,"ext":1},{"id":"2976","n":"landmine squat and press","bp":"full body","eq":"landmine","tg":"quads","mg":"glutes","sm":["glutes","shoulders","triceps","core","hamstrings"],"st":["Hold the end of the landmine bar at your chest with both hands.","Stand with your feet shoulder-width apart.","Squat down with your chest up.","Drive up and press the bar away until your arms are straight.","Lower the bar to your chest and repeat."],"img":"opengym/2976.webp","gif":null,"ext":1},{"id":"2978","n":"elbow up and down dynamic plank","bp":"waist","eq":"body weight","tg":"abs","mg":"core","sm":["core","shoulders","triceps","obliques"],"st":["Start in a forearm plank with your body in a straight line.","Place one hand on the floor and press up to a high plank.","Place the other hand down.","Lower back to your forearms one arm at a time.","Alternate the leading arm and keep your hips still."],"img":"opengym/2978.webp","gif":null,"ext":1},{"id":"2980","n":"dumbbell renegade row","bp":"back","eq":"dumbbell","tg":"upper back","mg":"lats","sm":["lats","rhomboids","biceps","core","obliques"],"st":["Start in a high plank with a dumbbell in each hand and your feet wide.","Brace your core.","Row one dumbbell to your ribs without twisting your hips.","Lower it with control.","Repeat on the other side."],"img":"opengym/2980.webp","gif":null,"ext":1},{"id":"2982","n":"dumbbell alternating floor press","bp":"chest","eq":"dumbbell","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders","upper chest","core"],"st":["Lie on the floor with a dumbbell in each hand and knees bent.","Press both dumbbells up over your chest.","Lower one dumbbell until your upper arm touches the floor.","Press it back up and lower the other side.","Keep alternating."],"img":"opengym/2982.webp","gif":null,"ext":1},{"id":"2984","n":"pistol squat to box","bp":"upper legs","eq":"body weight","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","core","adductors"],"st":["Stand in front of a box with one leg extended forward.","Brace your core and reach your arms forward for balance.","Sit back and down slowly on the standing leg until you touch the box.","Drive through your heel to stand.","Finish the reps, then switch legs."],"img":"opengym/2984.webp","gif":null,"ext":1},{"id":"2986","n":"weighted hammer grip pull up on dip cage","bp":"back","eq":"weighted","tg":"lats","mg":"biceps","sm":["biceps","brachialis","upper back","forearms","core"],"st":["Attach a belt or vest with weight and grip the neutral handles of the cage.","Hang with your arms straight and your core braced.","Pull your chest up until your chin passes the handles.","Pause briefly.","Lower slowly to a full hang and repeat."],"img":"opengym/2986.webp","gif":null,"ext":1},{"id":"2988","n":"squat mobility","bp":"upper legs","eq":"body weight","tg":"quads","mg":"glutes","sm":["glutes","adductors","ankles"],"st":["Stand with feet slightly wider than shoulder width.","Sink into a deep squat, keeping your heels down.","Press your elbows gently against your knees.","Rock side to side and sit tall.","Spend 30-45 seconds there, then stand up."],"img":"opengym/2988.webp","gif":null,"ext":1},{"id":"2989","n":"squat mobility complex","bp":"upper legs","eq":"body weight","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","adductors","ankles"],"st":["Stand with your feet a little wider than shoulder width and toes turned out slightly.","Sink into a deep squat and keep your heels on the floor.","Press your elbows against your knees to open the hips and hold for a moment.","Shift gently from side to side, then rock forward and back.","Stand up tall and repeat the flow for 6-8 rounds.","Keep your chest lifted and your back long throughout."],"img":"opengym/2989.webp","gif":null,"ext":1},{"id":"2990","n":"barbell walk calves activation","bp":"lower legs","eq":"barbell","tg":"calves","mg":"soleus","sm":["soleus","ankles","feet","core"],"st":["Rest a light barbell across your upper back and hold it with both hands.","Stand tall with your core braced and rise onto the balls of your feet.","Walk forward in small, controlled steps without letting your heels drop.","Keep your ankles steady and your hips level.","Walk 10-15 metres, rest, then repeat for a few rounds.","Use a light load so you can stay high on your toes."],"img":"opengym/2990.webp","gif":null,"ext":1},{"id":"2991","n":"rollball seated single leg shoulder flexor depressor retractor","bp":"shoulders","eq":"stability ball","tg":"delts","mg":"rhomboids","sm":["rhomboids","lats","trapezius","core"],"st":["Sit tall on a stability ball with your feet on the floor.","Lift one foot slightly off the ground and hold your balance.","Raise your arms forward, then press your shoulders down away from your ears.","Pull your shoulder blades back and together without arching your back.","Return slowly to the start and complete your reps.","Switch legs and repeat on the other side."],"img":"opengym/2991.webp","gif":null,"ext":1},{"id":"2992","n":"calf self massage with barbell","bp":"lower legs","eq":"barbell","tg":"calves","mg":"soleus","sm":["soleus"],"st":["Sit on the floor with one calf resting on a barbell.","Support yourself with your hands behind you.","Roll your calf slowly back and forth over the bar.","Pause on tender spots for a few breaths.","Switch to the other leg."],"img":"opengym/2992.webp","gif":null,"ext":1},{"id":"2993","n":"kettlebell goblet squat mobility","bp":"upper legs","eq":"kettlebell","tg":"quads","mg":"glutes","sm":["glutes","adductors","hamstrings","core"],"st":["Hold a kettlebell by the horns against your chest.","Stand with your feet wider than your shoulders and toes slightly out.","Squat down as deep as you comfortably can with your chest up.","Use your elbows to push your knees out and pause at the bottom.","Rock gently side to side to open the hips.","Drive through your feet to stand back up."],"img":"opengym/2993.webp","gif":null,"ext":1},{"id":"2994","n":"self anterior calf foam rolling","bp":"lower legs","eq":"roller","tg":"shins","mg":"soleus","sm":["soleus"],"st":["Kneel on a mat with the foam roller under your shins.","Support yourself with your hands in front.","Shift your weight to roll along the front of your lower leg.","Move slowly and pause on tight spots.","Roll for 30-60 seconds per leg."],"img":"opengym/2994.webp","gif":null,"ext":1},{"id":"2996","n":"band single arm shoulder press","bp":"shoulders","eq":"band","tg":"delts","mg":"triceps","sm":["triceps","upper chest","core","trapezius"],"st":["Stand on the band with your feet hip width apart and hold the other end at shoulder height.","Brace your core and keep your ribs down.","Press the hand straight overhead until your arm is almost straight.","Lower under control back to your shoulder.","Complete your reps without leaning sideways.","Switch arms and repeat."],"img":"opengym/2996.webp","gif":null,"ext":1},{"id":"2997","n":"band assisted pull up v. 3","bp":"back","eq":"assisted","tg":"lats","mg":"biceps","sm":["biceps","rhomboids","grip muscles","forearms"],"st":["Loop a band over the pull-up bar and place a foot or knee in it.","Grab the bar with an overhand grip a little wider than your shoulders.","Hang with your arms long and your shoulders engaged.","Pull your chest toward the bar by driving your elbows down.","Lower slowly until your arms are straight again.","Use a thinner band as you get stronger."],"img":"opengym/2997.webp","gif":null,"ext":1},{"id":"2998","n":"seated ankle stretch","bp":"lower legs","eq":"body weight","tg":"calves","mg":"ankles","sm":["ankles","shins","feet"],"st":["Sit on a chair or the floor with one leg extended.","Point your toes away from you so the top of the foot lengthens.","Slowly circle or press the foot until you feel a comfortable stretch.","Hold for 20-30 seconds without forcing it.","Release and switch legs.","Repeat 2-3 times on each side."],"img":"opengym/2998.webp","gif":null,"ext":1},{"id":"2999","n":"resistance band standing back achilles stretch","bp":"lower legs","eq":"resistance band","tg":"calves","mg":"soleus","sm":["soleus","ankles","feet"],"st":["Loop a resistance band around the front of the foot of your back leg.","Hold the band ends in your hands and stand tall.","Step that leg back with the heel on the floor.","Pull the band gently so your toes move toward your shin.","Hold for 20-30 seconds with your back leg fairly straight.","Switch sides and repeat."],"img":"opengym/2999.webp","gif":null,"ext":1},{"id":"3000","n":"resistance band standing forward achilles stretch","bp":"lower legs","eq":"resistance band","tg":"calves","mg":"soleus","sm":["soleus","ankles","feet"],"st":["Loop a resistance band around the ball of your front foot.","Hold the band ends and stand tall.","Place the front heel on the floor with the toes lifted.","Pull the band so your toes draw toward you and lean slightly forward.","Hold for 20-30 seconds with a comfortable stretch.","Switch feet and repeat."],"img":"opengym/3000.webp","gif":null,"ext":1},{"id":"3001","n":"squats knee position","bp":"upper legs","eq":"body weight","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","adductors","calves"],"st":["Stand with your feet shoulder width apart and toes slightly out.","Brace your core and lift your chest.","Bend at the hips and knees to lower into a squat.","Push your knees out so they follow the line of your toes.","Go down as deep as feels controlled.","Drive up through your whole foot to stand."],"img":"opengym/3001.webp","gif":null,"ext":1},{"id":"3002","n":"single arm push up (on knees)","bp":"chest","eq":"body weight","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders","core","obliques"],"st":["Kneel and place one hand under your shoulder, with the other arm behind your back.","Spread your knees a bit wider for balance.","Keep a straight line from your head to your knees.","Lower your chest toward the floor with control.","Press back up without twisting your hips.","Switch arms and repeat."],"img":"opengym/3002.webp","gif":null,"ext":1},{"id":"3004","n":"briskly walking","bp":"cardio","eq":"body weight","tg":"cardiovascular system","mg":"calves","sm":["calves","glutes","quadriceps","hamstrings"],"st":["Stand tall with your shoulders relaxed.","Start walking at a pace faster than a stroll.","Swing your arms naturally with elbows bent.","Land on your heel and roll through to your toes.","Keep breathing steadily and stay able to talk.","Walk for 20-45 minutes."],"img":"opengym/3004.webp","gif":null,"ext":1},{"id":"3009","n":"stair up","bp":"upper legs","eq":"body weight","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","calves"],"st":["Stand at the bottom of a staircase, standing tall.","Step up with one foot, placing your whole foot on the step.","Press through your heel and bring the other foot up.","Keep your torso upright and swing your arms naturally.","Continue at a steady pace and alternate the leading leg."],"img":"opengym/3009.webp","gif":null,"ext":1},{"id":"3018","n":"standing calf raise","bp":"lower legs","eq":"body weight","tg":"calves","mg":"soleus","sm":["soleus","ankles"],"st":["Stand tall with feet hip-width apart.","Rise up onto the balls of your feet as high as you can.","Pause at the top for a second.","Lower your heels slowly back to the floor.","Hold a wall for balance if needed."],"img":"opengym/3018.webp","gif":null,"ext":1},{"id":"3023","n":"band lying hip internal rotation v. 2","bp":"upper legs","eq":"band","tg":"glutes","mg":"adductors","sm":["adductors","hip flexors"],"st":["Lie on your back with a band around your lower leg anchored to the side.","Bend your knees with your feet on the floor.","Rotate your lower leg outward against the band, turning the hip inward.","Return slowly to the start.","Complete your reps and switch legs."],"img":"opengym/3023.webp","gif":null,"ext":1},{"id":"3030","n":"barbell split squat","bp":"upper legs","eq":"barbell","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","adductors","core"],"st":["Rest a barbell across your upper back and step one foot forward.","Stand with a long stride and your torso upright.","Bend both knees and lower your back knee toward the floor.","Keep your front heel down and your front knee over your foot.","Press through the front foot to rise.","Finish your reps, then switch legs."],"img":"opengym/3030.webp","gif":null,"ext":1},{"id":"3034","n":"bent leg kickback (kneeling)","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"hamstrings","sm":["hamstrings","lower back","core"],"st":["Start on hands and knees with your hands under your shoulders.","Brace your core and keep your back flat.","Lift one leg with the knee bent at 90 degrees.","Push the sole of your foot toward the ceiling and squeeze your glute.","Lower slowly without arching your back.","Complete your reps, then switch legs."],"img":"opengym/3034.webp","gif":null,"ext":1},{"id":"3035","n":"bent leg side kick (kneeling)","bp":"upper legs","eq":"body weight","tg":"abductors","mg":"glutes","sm":["glutes","obliques","core"],"st":["Start on hands and knees with a flat back.","Keep your knee bent at about 90 degrees.","Lift the bent leg out to the side to hip height.","Squeeze your outer hip at the top without rotating your torso.","Lower under control.","Finish your reps, then switch legs."],"img":"opengym/3035.webp","gif":null,"ext":1},{"id":"3037","n":"butt kicks","bp":"cardio","eq":"body weight","tg":"hamstrings","mg":"calves","sm":["calves","quadriceps","glutes","hip flexors"],"st":["Stand tall with your arms bent at your sides.","Jog on the spot or move forward slowly.","Kick each heel up toward your glute.","Stay on the balls of your feet and keep your knees pointing down.","Pump your arms in rhythm.","Continue for 20-40 seconds."],"img":"opengym/3037.webp","gif":null,"ext":1},{"id":"3040","n":"cable bar high pulley overhead tricep extension","bp":"upper arms","eq":"cable","tg":"triceps","mg":"shoulders","sm":["shoulders","core"],"st":["Attach a bar to a high pulley and face away from the machine.","Hold the bar behind your head with elbows pointing forward.","Step forward and stagger your feet.","Extend your arms to press the bar overhead.","Lower slowly back and keep your elbows in place."],"img":"opengym/3040.webp","gif":null,"ext":1},{"id":"3048","n":"cable hip abduction v. 2","bp":"upper legs","eq":"cable","tg":"abductors","mg":"glutes","sm":["glutes","obliques","core"],"st":["Attach an ankle cuff to a low pulley and strap it to your outer ankle.","Stand sideways to the machine and hold a support.","Keep your torso upright and your standing leg slightly bent.","Lift the cuffed leg out to the side.","Pause at the top, then lower slowly.","Finish your reps and switch legs."],"img":"opengym/3048.webp","gif":null,"ext":1},{"id":"3068","n":"cable standing biceps curl (with rope)","bp":"upper arms","eq":"cable","tg":"biceps","mg":"brachialis","sm":["brachialis","forearms"],"st":["Attach a rope to a low pulley and hold an end in each hand.","Stand tall with elbows by your sides.","Curl the rope up toward your shoulders.","Squeeze your biceps at the top.","Lower under control without swinging."],"img":"opengym/3068.webp","gif":null,"ext":1},{"id":"3075","n":"dumbbell close grip press v. 2","bp":"chest","eq":"dumbbell","tg":"triceps","mg":"chest","sm":["chest","shoulders"],"st":["Lie on a bench with a dumbbell in each hand pressed together over your chest.","Keep your palms facing each other.","Lower the dumbbells to your chest with your elbows tucked.","Press back up while keeping the weights touching.","Keep your wrists straight."],"img":"opengym/3075.webp","gif":null,"ext":1},{"id":"3083","n":"dumbbell seated curl v. 2","bp":"upper arms","eq":"dumbbell","tg":"biceps","mg":"brachialis","sm":["brachialis","forearms"],"st":["Sit on a bench with a dumbbell in each hand.","Let your arms hang by your sides, palms forward.","Curl the weights up toward your shoulders.","Squeeze at the top and keep elbows pinned.","Lower slowly to full extension."],"img":"opengym/3083.webp","gif":null,"ext":1},{"id":"3084","n":"dumbbell single arm preacher curl","bp":"upper arms","eq":"dumbbell","tg":"biceps","mg":"brachialis","sm":["brachialis","forearms"],"st":["Sit at a preacher bench with your upper arm on the pad.","Hold a dumbbell with your palm facing up.","Curl the weight toward your shoulder.","Squeeze at the top.","Lower slowly until nearly straight, then switch arms."],"img":"opengym/3084.webp","gif":null,"ext":1},{"id":"3086","n":"elbow to knee twists","bp":"cardio","eq":"body weight","tg":"obliques","mg":"hip flexors","sm":["hip flexors","quadriceps","core"],"st":["Stand tall with your hands behind your head.","Lift one knee up and across your body.","Twist your torso to meet the knee with the opposite elbow.","Return to standing.","Alternate sides at a steady pace.","Keep your chest lifted and breathe evenly."],"img":"opengym/3086.webp","gif":null,"ext":1},{"id":"3088","n":"frog hops","bp":"upper legs","eq":"body weight","tg":"quads","mg":"glutes","sm":["glutes","calves","hamstrings","core"],"st":["Stand with your feet wider than your shoulders and sink into a deep squat.","Place your fingertips on the floor between your feet.","Jump forward and up, swinging your arms.","Land softly back in the squat.","Reset and hop again right away.","Keep your knees tracking over your toes."],"img":"opengym/3088.webp","gif":null,"ext":1},{"id":"3091","n":"high knee skips","bp":"cardio","eq":"body weight","tg":"cardiovascular system","mg":"hip flexors","sm":["hip flexors","quadriceps","calves","core"],"st":["Stand tall and relaxed.","Skip forward, driving one knee up high.","Hop lightly on the other foot.","Swing the opposite arm forward with each knee.","Alternate legs in a smooth rhythm.","Keep your chest up and land softly."],"img":"opengym/3091.webp","gif":null,"ext":1},{"id":"3092","n":"high knee squat","bp":"upper legs","eq":"body weight","tg":"quads","mg":"glutes","sm":["glutes","hip flexors","hamstrings","calves"],"st":["Stand with your feet shoulder width apart.","Squat down with your chest up.","Drive up through your feet to stand.","Lift one knee toward your chest as you reach the top.","Lower the foot and go back into the squat.","Alternate knees on each rep."],"img":"opengym/3092.webp","gif":null,"ext":1},{"id":"3094","n":"jumping jack","bp":"full body","eq":"body weight","tg":"cardiovascular system","mg":"calves","sm":["calves","shoulders","glutes","hip flexors"],"st":["Stand with your feet together and your arms at your sides.","Jump your feet apart as you swing your arms overhead.","Jump back to the start position.","Land softly on the balls of your feet.","Keep a steady rhythm.","Continue for 30-60 seconds."],"img":"opengym/3094.webp","gif":null,"ext":1},{"id":"3096","n":"lever alternating narrow grip seated row (plate loaded)","bp":"back","eq":"leverage machine","tg":"upper back","mg":"lats","sm":["lats","biceps","rhomboids"],"st":["Sit with your chest against the pad and grab the narrow handles.","Pull one handle back, driving your elbow behind you.","Squeeze your shoulder blade at the end.","Return slowly and pull with the other arm.","Alternate sides and keep your torso still."],"img":"opengym/3096.webp","gif":null,"ext":1},{"id":"3102","n":"lever narrow grip seated row (plate loaded)","bp":"back","eq":"leverage machine","tg":"upper back","mg":"lats","sm":["lats","biceps","rhomboids"],"st":["Sit with your chest against the pad and take the narrow handles.","Pull both handles toward your torso.","Squeeze your shoulder blades together at the end.","Pause briefly.","Return slowly with control."],"img":"opengym/3102.webp","gif":null,"ext":1},{"id":"3108","n":"plyo jacks","bp":"full body","eq":"body weight","tg":"cardiovascular system","mg":"quadriceps","sm":["quadriceps","glutes","calves","shoulders"],"st":["Stand with your feet together.","Jump your feet wide and land in a quarter squat.","Swing your arms out as you land.","Jump your feet back together.","Land softly each time.","Keep a quick, controlled pace."],"img":"opengym/3108.webp","gif":null,"ext":1},{"id":"3109","n":"skater","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hip flexors","calves","core"],"st":["Stand on one leg with a slight bend in the knee.","Leap sideways to the other leg.","Land softly and sweep the back leg behind you.","Swing your arms across your body for balance.","Immediately bound back the other way.","Keep your hips low and your chest forward."],"img":"opengym/3109.webp","gif":null,"ext":1},{"id":"3110","n":"smith hip thrust","bp":"upper legs","eq":"smith machine","tg":"glutes","mg":"hamstrings","sm":["hamstrings","quadriceps","core","adductors"],"st":["Sit on the floor with your upper back against a bench and the Smith bar over your hips.","Pad the bar and roll it into the crease of your hips.","Plant your feet hip width apart and unrack the bar.","Drive through your heels and lift your hips until your body is level.","Squeeze your glutes at the top.","Lower slowly and repeat."],"img":"opengym/3110.webp","gif":null,"ext":1},{"id":"3113","n":"split jacks","bp":"full body","eq":"body weight","tg":"cardiovascular system","mg":"quadriceps","sm":["quadriceps","glutes","hip flexors","shoulders"],"st":["Stand tall with your arms at your sides.","Jump one foot forward and the other back as you swing opposite arms.","Land softly with soft knees.","Jump again and switch legs.","Keep your torso upright.","Continue at a steady pace for 30-45 seconds."],"img":"opengym/3113.webp","gif":null,"ext":1},{"id":"3114","n":"straight leg kickback (kneeling)","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"hamstrings","sm":["hamstrings","lower back","core"],"st":["Start on hands and knees with a flat back.","Brace your core.","Extend one leg straight back.","Lift it to hip height and squeeze your glute.","Lower without letting your back arch.","Finish your reps, then switch legs."],"img":"opengym/3114.webp","gif":null,"ext":1},{"id":"3120","n":"standing calf raise with support","bp":"lower legs","eq":"body weight","tg":"calves","mg":"soleus","sm":["soleus","ankles"],"st":["Stand holding a wall or rail for balance.","Place your feet hip-width apart.","Rise up on your toes as high as you can.","Pause and squeeze your calves.","Lower slowly."],"img":"opengym/3120.webp","gif":null,"ext":1},{"id":"3121","n":"band seated straight back row","bp":"back","eq":"band","tg":"upper back","mg":"lats","sm":["lats","rhomboids","biceps"],"st":["Sit on the floor with legs extended and a band around your feet.","Hold the ends with your arms straight.","Sit tall with a flat back.","Pull the band toward your waist, squeezing your shoulder blades.","Return slowly."],"img":"opengym/3121.webp","gif":null,"ext":1},{"id":"3125","n":"resistance band foot external rotation","bp":"lower legs","eq":"resistance band","tg":"calves","mg":"ankles","sm":["ankles","shins","feet"],"st":["Sit with one leg out and a band looped around the forefoot.","Anchor the other end to a fixed point on the inside.","Keep your heel still on the floor.","Turn your foot outward against the band.","Return slowly to the start.","Complete your reps, then switch feet."],"img":"opengym/3125.webp","gif":null,"ext":1},{"id":"3126","n":"resistance band foot plantar flexion","bp":"lower legs","eq":"resistance band","tg":"calves","mg":"soleus","sm":["soleus","ankles","feet"],"st":["Sit with your leg straight and a band looped around the ball of your foot.","Hold the band ends in your hands.","Point your toes away from you against the band.","Pause at the end of the range.","Return slowly.","Finish your reps, then switch feet."],"img":"opengym/3126.webp","gif":null,"ext":1},{"id":"3127","n":"resistance band foot eversion","bp":"lower legs","eq":"resistance band","tg":"calves","mg":"ankles","sm":["ankles","shins","feet"],"st":["Sit with your leg extended and a band around your forefoot.","Anchor the band on the inside of your foot.","Keep your leg still.","Turn the sole of your foot outward against the band.","Return slowly.","Complete your reps, then switch feet."],"img":"opengym/3127.webp","gif":null,"ext":1},{"id":"3128","n":"resistance band foot inversion","bp":"lower legs","eq":"resistance band","tg":"calves","mg":"shins","sm":["shins","ankles","feet"],"st":["Sit with your leg extended and a band around your forefoot.","Anchor the band on the outside of your foot.","Keep your leg still.","Turn the sole of your foot inward against the band.","Return slowly.","Complete your reps, then switch feet."],"img":"opengym/3128.webp","gif":null,"ext":1},{"id":"3129","n":"scapula retraction protraction","bp":"back","eq":"body weight","tg":"upper back","mg":"rhomboids","sm":["rhomboids","lats","trapezius","shoulders"],"st":["Stand or sit tall with your arms forward at shoulder height.","Pull your shoulder blades together behind you.","Hold for a moment.","Then push your hands forward and let the blades spread apart.","Move slowly between the two positions.","Keep your neck relaxed and your ribs down."],"img":"opengym/3129.webp","gif":null,"ext":1},{"id":"3130","n":"scapula elevation depression","bp":"back","eq":"body weight","tg":"upper back","mg":"rhomboids","sm":["rhomboids","trapezius","shoulders"],"st":["Stand or sit tall with your arms at your sides.","Shrug your shoulders up toward your ears.","Hold for a second.","Press your shoulders down away from your ears.","Move slowly through the full range.","Keep your arms relaxed and your head still."],"img":"opengym/3130.webp","gif":null,"ext":1},{"id":"3141","n":"bird dog v. 2","bp":"waist","eq":"body weight","tg":"spine","mg":"glutes","sm":["glutes","core","rear deltoids"],"st":["Start on all fours with a neutral spine.","Extend one arm forward and the opposite leg back.","Keep your hips level and avoid arching your back.","Pause for a moment.","Return and switch sides."],"img":"opengym/3141.webp","gif":null,"ext":1},{"id":"3149","n":"chin tuck","bp":"neck","eq":"body weight","tg":"levator scapulae","mg":"sternocleidomastoid","sm":["sternocleidomastoid","upper back","trapezius"],"st":["Sit or stand tall with your eyes level.","Place a finger on your chin if it helps.","Draw your chin straight back as if making a double chin.","Keep your head level without tilting.","Hold for 3-5 seconds.","Release and repeat 8-10 times."],"img":"opengym/3149.webp","gif":null,"ext":1},{"id":"3150","n":"assisted chin tuck","bp":"neck","eq":"assisted","tg":"levator scapulae","mg":"sternocleidomastoid","sm":["sternocleidomastoid","upper back","trapezius"],"st":["Sit or stand tall with your eyes level.","Place two fingers on your chin.","Gently guide your chin straight back.","Keep your head level and your shoulders relaxed.","Hold for 3-5 seconds.","Release and repeat 8-10 times."],"img":"opengym/3150.webp","gif":null,"ext":1},{"id":"3153","n":"side kick burpee","bp":"full body","eq":"body weight","tg":"cardiovascular system","mg":"chest","sm":["chest","quadriceps","glutes","triceps","core"],"st":["Stand with your feet shoulder width apart.","Drop your hands to the floor and jump your feet back to a plank.","Do a push-up, then jump your feet back in.","Stand up and kick one leg out to the side.","Land and go straight into the next rep.","Alternate kicking sides."],"img":"opengym/3153.webp","gif":null,"ext":1},{"id":"3171","n":"boxing right hook","bp":"full body","eq":"body weight","tg":"delts","mg":"obliques","sm":["obliques","core","chest","calves"],"st":["Stand in a boxing stance with your hands up.","Bend your right elbow to about 90 degrees.","Pivot on your back foot and rotate your hips and torso.","Swing your fist in an arc to your target.","Snap back to guard position.","Keep your chin tucked and your left hand up."],"img":"opengym/3171.webp","gif":null,"ext":1},{"id":"3174","n":"barbell bench press (knees at 90 degrees)","bp":"chest","eq":"barbell","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders","upper chest","core"],"st":["Lie on a bench and lift your feet with your knees bent to 90 degrees.","Grip the bar slightly wider than your shoulders.","Unrack and hold it over your chest.","Lower the bar to your mid chest with control.","Press it back up until your arms are straight.","Keep your lower back flat on the bench."],"img":"opengym/3174.webp","gif":null,"ext":1},{"id":"3175","n":"dumbbell fly (knees at 90 degrees)","bp":"chest","eq":"dumbbell","tg":"pectorals","mg":"shoulders","sm":["shoulders","biceps","upper chest","core"],"st":["Lie on a bench holding dumbbells above your chest.","Lift your feet so your knees are bent to 90 degrees.","Keep a slight bend in your elbows.","Open your arms out wide until you feel a chest stretch.","Bring the dumbbells back together over your chest.","Move slowly and keep your back flat."],"img":"opengym/3175.webp","gif":null,"ext":1},{"id":"3176","n":"dumbbell straight arm pullover (knees at 90 degrees)","bp":"chest","eq":"dumbbell","tg":"pectorals","mg":"lats","sm":["lats","triceps","shoulders","core"],"st":["Lie on a bench with your feet up and knees at 90 degrees.","Hold one dumbbell with both hands above your chest.","Keep your arms nearly straight.","Lower the dumbbell in an arc behind your head.","Pull it back over your chest.","Keep your ribs down and your back flat."],"img":"opengym/3176.webp","gif":null,"ext":1},{"id":"3178","n":"stability ball reverse hyperextension (off a bench)","bp":"upper legs","eq":"stability ball","tg":"glutes","mg":"hamstrings","sm":["hamstrings","lower back"],"st":["Lie face down with your hips over the ball and hands on the floor.","Hold the bench or the ball for stability.","Lift your legs until they are in line with your body.","Squeeze your glutes at the top.","Lower with control."],"img":"opengym/3178.webp","gif":null,"ext":1},{"id":"3180","n":"incline reverse hyperextension","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"hamstrings","sm":["hamstrings","lower back"],"st":["Lie face down on an incline bench with hips at the edge.","Hold the sides of the bench.","Raise both legs until they are in line with your torso.","Squeeze your glutes at the top.","Lower slowly and repeat."],"img":"opengym/3180.webp","gif":null,"ext":1},{"id":"3181","n":"bodyweight frog pump","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"hamstrings","sm":["hamstrings","adductors"],"st":["Lie on your back with the soles of your feet together and knees dropped open.","Bring your heels close to your hips.","Drive your hips up by squeezing your glutes.","Pause at the top.","Lower and repeat in quick pumps."],"img":"opengym/3181.webp","gif":null,"ext":1},{"id":"3182","n":"weighted frog pump","bp":"upper legs","eq":"weighted","tg":"glutes","mg":"hamstrings","sm":["hamstrings","adductors"],"st":["Lie on your back with the soles of your feet together and knees open.","Rest a weight on your hips.","Drive your hips up by squeezing your glutes.","Pause at the top.","Lower and repeat."],"img":"opengym/3182.webp","gif":null,"ext":1},{"id":"3183","n":"barbell hang clean below the knees v. 2","bp":"full body","eq":"olympic barbell","tg":"glutes","mg":"hamstrings","sm":["hamstrings","trapezius","quadriceps","lats","core"],"st":["Stand with the bar hanging below your knees in an overhand grip.","Hinge back with a flat back and shoulders over the bar.","Drive your hips forward and jump explosively.","Shrug and pull your elbows high.","Drop under the bar and catch it on your shoulders.","Stand tall, then lower the bar under control."],"img":"opengym/3183.webp","gif":null,"ext":1},{"id":"3184","n":"barbell squat (with hanging band technique)","bp":"upper legs","eq":"barbell","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","core","adductors"],"st":["Set up the bar with bands hanging kettlebells or weights from each end.","Rest the bar across your upper back and step out.","Stand with your feet shoulder width apart.","Squat down with a braced core.","Drive up through your feet.","Use a lighter load and move slowly."],"img":"opengym/3184.webp","gif":null,"ext":1},{"id":"3185","n":"barbell bench press (with hanging band technique)","bp":"chest","eq":"barbell","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders","upper chest","core"],"st":["Hang weights from each end of the bar with bands.","Lie on the bench and unrack the bar.","Hold it over your chest.","Lower the bar slowly to your mid chest.","Press up and keep the bar steady.","Use a lighter load than a normal bench press."],"img":"opengym/3185.webp","gif":null,"ext":1},{"id":"3186","n":"barbell military press (with hanging band technique)","bp":"shoulders","eq":"barbell","tg":"delts","mg":"triceps","sm":["triceps","upper chest","core","trapezius"],"st":["Hang weights from each end of the bar with bands.","Hold the bar at your shoulders and stand tall.","Brace your core and squeeze your glutes.","Press the bar straight overhead.","Lower it slowly back to your shoulders.","Use a lighter load and keep the bar steady."],"img":"opengym/3186.webp","gif":null,"ext":1},{"id":"3187","n":"kettlebell goblet squat jump","bp":"upper legs","eq":"kettlebell","tg":"quads","mg":"glutes","sm":["glutes","calves","core"],"st":["Hold a kettlebell at your chest with both hands.","Squat down with your chest tall.","Explode upward into a jump.","Land softly with bent knees.","Reset and go into the next squat."],"img":"opengym/3187.webp","gif":null,"ext":1},{"id":"3188","n":"dumbbell straight arm pullover (with hanging band technique)","bp":"chest","eq":"dumbbell","tg":"pectorals","mg":"lats","sm":["lats","triceps","shoulders","core"],"st":["Hang a weight from the dumbbell with a band.","Lie on a bench and hold it above your chest with straight arms.","Lower it in an arc behind your head.","Pull it back over your chest slowly.","Keep your ribs down and your core tight.","Use a light load to stay controlled."],"img":"opengym/3188.webp","gif":null,"ext":1},{"id":"3196","n":"quick feet run","bp":"cardio","eq":"body weight","tg":"cardiovascular system","mg":"calves","sm":["calves","quadriceps","hip flexors","core"],"st":["Stand tall with your knees slightly bent.","Run on the spot as fast as you can with small steps.","Stay on the balls of your feet.","Pump your arms.","Keep your chest up.","Continue for 20-30 seconds."],"img":"opengym/3196.webp","gif":null,"ext":1},{"id":"3197","n":"prancing","bp":"cardio","eq":"body weight","tg":"cardiovascular system","mg":"calves","sm":["calves","hip flexors","quadriceps","core"],"st":["Stand tall and relaxed.","Move forward in a bouncy trot.","Lift each knee up with a springy step.","Stay on the balls of your feet.","Swing your arms in rhythm.","Continue for 30-60 seconds."],"img":"opengym/3197.webp","gif":null,"ext":1},{"id":"3198","n":"zigzag hops","bp":"cardio","eq":"body weight","tg":"cardiovascular system","mg":"calves","sm":["calves","glutes","quadriceps","hip flexors"],"st":["Stand with your knees slightly bent.","Hop forward and to one side.","Land softly on both feet.","Hop forward and to the other side.","Keep your hops light and quick.","Continue for 20-30 seconds."],"img":"opengym/3198.webp","gif":null,"ext":1},{"id":"3199","n":"skips","bp":"cardio","eq":"body weight","tg":"cardiovascular system","mg":"calves","sm":["calves","quadriceps","hip flexors","core"],"st":["Stand tall and relaxed.","Step forward and hop on the same foot.","Switch and hop on the other foot.","Swing the opposite arm forward with each step.","Stay light on the balls of your feet.","Keep a steady rhythm."],"img":"opengym/3199.webp","gif":null,"ext":1},{"id":"3225","n":"floor t raise","bp":"back","eq":"body weight","tg":"upper back","mg":"rhomboids","sm":["rhomboids","rear deltoids","trapezius","lower back"],"st":["Lie face down with your arms out to the sides in a T.","Keep your forehead near the floor.","Turn your thumbs up toward the ceiling.","Squeeze your shoulder blades together and lift your arms.","Pause for a second.","Lower slowly and repeat."],"img":"opengym/3225.webp","gif":null,"ext":1},{"id":"3226","n":"prone cobra palms under thighs","bp":"back","eq":"body weight","tg":"spine","mg":"glutes","sm":["glutes","upper back","trapezius","hamstrings"],"st":["Lie face down with your palms under your thighs.","Keep your neck long and look at the floor.","Lift your chest off the ground using your back muscles.","Squeeze your glutes.","Hold for 15-30 seconds.","Lower slowly and rest."],"img":"opengym/3226.webp","gif":null,"ext":1},{"id":"3227","n":"swimmer kicks","bp":"back","eq":"body weight","tg":"spine","mg":"glutes","sm":["glutes","hamstrings","upper back","core"],"st":["Lie face down with your arms extended in front.","Lift your chest and legs slightly off the floor.","Kick your legs up and down in small, fast alternations.","Keep your neck long.","Breathe steadily.","Continue for 20-30 seconds."],"img":"opengym/3227.webp","gif":null,"ext":1},{"id":"3228","n":"lying back extension","bp":"back","eq":"body weight","tg":"spine","mg":"glutes","sm":["glutes","hamstrings","upper back","trapezius"],"st":["Lie face down with your hands beside your head.","Keep your legs straight and your feet on the floor.","Lift your chest using your lower back.","Pause briefly at the top.","Lower slowly.","Keep your neck in line with your spine."],"img":"opengym/3228.webp","gif":null,"ext":1},{"id":"3229","n":"lying back extension with press","bp":"back","eq":"body weight","tg":"spine","mg":"triceps","sm":["triceps","glutes","upper back","shoulders"],"st":["Lie face down with your hands near your shoulders.","Lift your chest off the floor.","Press your arms forward in front of you.","Pull them back to your shoulders.","Lower your chest slowly.","Keep your neck long throughout."],"img":"opengym/3229.webp","gif":null,"ext":1},{"id":"3230","n":"prone cobra hands interlocked","bp":"back","eq":"body weight","tg":"spine","mg":"glutes","sm":["glutes","upper back","rear deltoids","trapezius"],"st":["Lie face down with your hands clasped behind your lower back.","Keep your neck long and look at the floor.","Lift your chest off the floor.","Reach your hands toward your feet.","Hold for 15-30 seconds.","Lower slowly and rest."],"img":"opengym/3230.webp","gif":null,"ext":1},{"id":"3232","n":"cable standing rear delt horizontal row (with rope)","bp":"shoulders","eq":"cable","tg":"delts","mg":"rear deltoids","sm":["rear deltoids","rhomboids","upper back","trapezius"],"st":["Attach a rope to a cable at chest height.","Hold the ends and step back.","Stand with your knees slightly bent.","Pull the rope toward your face with your elbows high and wide.","Squeeze your rear shoulders.","Return slowly."],"img":"opengym/3232.webp","gif":null,"ext":1},{"id":"3233","n":"cable seated supine grip row","bp":"back","eq":"cable","tg":"upper back","mg":"lats","sm":["lats","biceps","rhomboids","forearms"],"st":["Sit at a cable row with your feet braced.","Grip the handle with your palms facing up.","Sit tall with your chest up.","Pull the handle toward your lower ribs.","Squeeze your shoulder blades.","Return slowly without rounding your back."],"img":"opengym/3233.webp","gif":null,"ext":1},{"id":"3238","n":"kneeling plank","bp":"waist","eq":"body weight","tg":"abs","mg":"core","sm":["core","shoulders","glutes","lower abs"],"st":["Kneel and place your forearms on the floor under your shoulders.","Lift your hips so your body is in a line from your knees to your head.","Brace your core and squeeze your glutes.","Keep your neck neutral.","Hold for 20-45 seconds.","Lower and rest."],"img":"opengym/3238.webp","gif":null,"ext":1},{"id":"3242","n":"lying lower back stretch (bent knee)","bp":"back","eq":"body weight","tg":"spine","mg":"glutes","sm":["glutes","hip flexors"],"st":["Lie on your back with your knees bent.","Pull one knee toward your chest with both hands.","Keep your lower back relaxed on the floor.","Hold for 20-30 seconds.","Switch legs."],"img":"opengym/3242.webp","gif":null,"ext":1},{"id":"3243","n":"lying lower back stretch","bp":"back","eq":"body weight","tg":"spine","mg":"glutes","sm":["glutes","hamstrings"],"st":["Lie on your back.","Pull both knees toward your chest.","Wrap your arms around your shins.","Hold for 20-30 seconds.","Release slowly."],"img":"opengym/3243.webp","gif":null,"ext":1},{"id":"3244","n":"abdominal stretch","bp":"waist","eq":"body weight","tg":"abs","mg":"hip flexors","sm":["hip flexors","chest"],"st":["Lie face down with hands under your shoulders.","Press up, lifting your chest.","Keep your hips on the floor.","Look straight ahead and relax.","Hold for 20-30 seconds."],"img":"opengym/3244.webp","gif":null,"ext":1},{"id":"3245","n":"feet and ankles side to side stretch","bp":"lower legs","eq":"body weight","tg":"calves","mg":"ankles","sm":["ankles","feet","shins"],"st":["Sit with your legs extended.","Keep your heels on the floor.","Roll your feet slowly to the outside.","Then roll them inward.","Continue for 20-30 seconds."],"img":"opengym/3245.webp","gif":null,"ext":1},{"id":"3248","n":"front toe touching","bp":"waist","eq":"body weight","tg":"abs","mg":"hamstrings","sm":["hamstrings","lower back","obliques"],"st":["Stand with feet hip-width apart.","Hinge forward and reach toward your toes.","Let your head hang relaxed.","Rise slowly.","Repeat at a steady pace."],"img":"opengym/3248.webp","gif":null,"ext":1},{"id":"3249","n":"two front toe touching","bp":"waist","eq":"body weight","tg":"abs","mg":"hamstrings","sm":["hamstrings","lower back","obliques"],"st":["Stand with feet wide apart.","Hinge forward with both arms reaching down.","Touch the floor or your toes.","Rise slowly.","Repeat for the set."],"img":"opengym/3249.webp","gif":null,"ext":1},{"id":"3250","n":"side toe touching","bp":"waist","eq":"body weight","tg":"abs","mg":"obliques","sm":["obliques","hamstrings","lower back"],"st":["Stand with your feet wide apart.","Reach one hand toward the opposite foot.","Keep your other arm extended behind you.","Rise and switch sides.","Alternate at an easy pace."],"img":"opengym/3250.webp","gif":null,"ext":1},{"id":"3251","n":"side two front toe touching","bp":"waist","eq":"body weight","tg":"abs","mg":"obliques","sm":["obliques","hamstrings","lower back"],"st":["Stand with feet wide apart.","Turn your torso slightly to one side.","Reach both hands to the foot on that side.","Rise, then turn to the other side.","Repeat at a steady pace."],"img":"opengym/3251.webp","gif":null,"ext":1},{"id":"3253","n":"standing side bend","bp":"waist","eq":"body weight","tg":"obliques","mg":"abdominals","sm":["abdominals","lats"],"st":["Stand with your feet shoulder-width apart.","Raise one arm overhead.","Bend sideways, reaching over to the other side.","Return to upright.","Switch sides and repeat."],"img":"opengym/3253.webp","gif":null,"ext":1},{"id":"3254","n":"standing two side bend","bp":"waist","eq":"body weight","tg":"obliques","mg":"abdominals","sm":["abdominals","lats","shoulders"],"st":["Stand with feet shoulder-width apart.","Clasp your hands overhead.","Bend to one side, keeping your hips still.","Return to the center.","Bend to the other side and repeat."],"img":"opengym/3254.webp","gif":null,"ext":1},{"id":"3256","n":"standing two side bend (bent arm)","bp":"waist","eq":"body weight","tg":"obliques","mg":"abdominals","sm":["abdominals","lats","shoulders"],"st":["Stand with feet shoulder-width apart.","Place your hands behind your head with elbows out.","Bend to one side without twisting.","Return to the center.","Bend to the other side and repeat."],"img":"opengym/3256.webp","gif":null,"ext":1},{"id":"3257","n":"standing one arm circling","bp":"shoulders","eq":"body weight","tg":"delts","mg":"rotator cuff","sm":["rotator cuff","upper back"],"st":["Stand tall with feet shoulder-width apart.","Extend one arm out to the side.","Make slow circles, gradually larger.","Reverse the direction.","Switch arms."],"img":"opengym/3257.webp","gif":null,"ext":1},{"id":"3258","n":"standing arms circling","bp":"shoulders","eq":"body weight","tg":"delts","mg":"rotator cuff","sm":["rotator cuff","upper back"],"st":["Stand tall with feet shoulder-width apart.","Extend both arms out to the sides.","Make slow circles forward.","Then reverse direction.","Keep your shoulders relaxed."],"img":"opengym/3258.webp","gif":null,"ext":1},{"id":"3259","n":"standing alternate arms circling","bp":"shoulders","eq":"body weight","tg":"delts","mg":"rotator cuff","sm":["rotator cuff","upper back"],"st":["Stand tall with feet hip-width apart and arms hanging at your sides.","Swing one arm forward, up and back in a large smooth circle.","As that arm finishes, start the same circle with the other arm.","Keep your ribs down and your neck relaxed.","Continue alternating for 20-30 seconds, then reverse the direction."],"img":"opengym/3259.webp","gif":null,"ext":1},{"id":"3260","n":"standing arms flinging","bp":"shoulders","eq":"body weight","tg":"delts","mg":"chest","sm":["chest","upper back"],"st":["Stand tall with feet shoulder-width apart and arms out in front at chest height.","Fling both arms wide open to the sides, squeezing your shoulder blades together.","Swing them back across your body, letting one arm cross over the other.","Keep the motion loose and controlled, without arching your back.","Repeat for 15-20 swings."],"img":"opengym/3260.webp","gif":null,"ext":1},{"id":"3263","n":"lying full leg raise","bp":"waist","eq":"body weight","tg":"abs","mg":"hip flexors","sm":["hip flexors","lower abs"],"st":["Lie on your back with legs straight and hands under your hips or by your sides.","Press your lower back gently into the floor.","Lift both legs together until they point at the ceiling.","Lower them slowly, stopping just above the floor.","Keep your legs straight and do not let your back arch."],"img":"opengym/3263.webp","gif":null,"ext":1},{"id":"3264","n":"side plank leg raise","bp":"upper legs","eq":"body weight","tg":"abductors","mg":"glutes","sm":["glutes","obliques","core"],"st":["Lie on your side and prop yourself up on one forearm with elbow under the shoulder.","Lift your hips so your body forms a straight line.","Raise your top leg to about hip height, toes pointing forward.","Lower it a little without dropping your hips.","Finish your reps, then switch sides."],"img":"opengym/3264.webp","gif":null,"ext":1},{"id":"3265","n":"kneeling push up to child pose","bp":"chest","eq":"body weight","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders","glutes"],"st":["Start on your hands and knees with hands slightly wider than your shoulders.","Lower your chest toward the floor, elbows at about 45 degrees.","Press back up to the start.","Push your hips back onto your heels and reach your arms forward into child pose.","Return to the start and repeat."],"img":"opengym/3265.webp","gif":null,"ext":1},{"id":"3266","n":"elbow push up","bp":"waist","eq":"body weight","tg":"abs","mg":"core","sm":["core","shoulders","triceps"],"st":["Start in a forearm plank with body in a straight line.","Press up onto one hand, then the other, into a high plank.","Lower back down to your forearms one arm at a time.","Keep your hips steady and avoid rocking side to side.","Alternate which arm leads each rep."],"img":"opengym/3266.webp","gif":null,"ext":1},{"id":"3268","n":"lying leg raise to side","bp":"waist","eq":"body weight","tg":"abs","mg":"obliques","sm":["obliques","hip flexors"],"st":["Lie on your back with arms out to the sides and legs raised straight up.","Keep your shoulders on the floor.","Lower both legs toward one side, stopping just above the floor.","Bring them back up through the middle.","Repeat to the other side and keep alternating."],"img":"opengym/3268.webp","gif":null,"ext":1},{"id":"3269","n":"run and hop","bp":"cardio","eq":"body weight","tg":"cardiovascular system","mg":"quadriceps","sm":["quadriceps","calves","glutes"],"st":["Stand tall with feet under your hips.","Run on the spot at a steady pace, pumping your arms.","Every few steps, hop off one foot and land softly.","Stay light on the balls of your feet.","Keep going for 30-60 seconds at a pace you can hold."],"img":"opengym/3269.webp","gif":null,"ext":1},{"id":"3270","n":"run and jack jump","bp":"cardio","eq":"body weight","tg":"cardiovascular system","mg":"calves","sm":["calves","shoulders","glutes"],"st":["Stand tall and start jogging on the spot.","After a few steps, jump your feet wide while raising your arms overhead.","Jump your feet back together and lower the arms.","Resume running and repeat the pattern.","Keep your landings soft and keep going for 30-60 seconds."],"img":"opengym/3270.webp","gif":null,"ext":1},{"id":"3271","n":"run and half knee bend","bp":"cardio","eq":"body weight","tg":"cardiovascular system","mg":"quadriceps","sm":["quadriceps","glutes","calves"],"st":["Stand tall with feet hip-width apart.","Jog on the spot for a few steps.","Pause into a shallow knee bend, hips back and chest up.","Stand tall and go straight back into running.","Repeat for 30-60 seconds."],"img":"opengym/3271.webp","gif":null,"ext":1},{"id":"3272","n":"run and semi squat jump","bp":"cardio","eq":"body weight","tg":"cardiovascular system","mg":"quadriceps","sm":["quadriceps","glutes","calves"],"st":["Stand tall and run on the spot for a few steps.","Drop into a half squat with your chest up.","Jump up, swinging your arms.","Land softly with bent knees and go back to running.","Repeat for 30-60 seconds."],"img":"opengym/3272.webp","gif":null,"ext":1},{"id":"3279","n":"floor crunch feet on bench","bp":"waist","eq":"body weight","tg":"abs","mg":"obliques","sm":["obliques","hip flexors"],"st":["Lie on your back and rest your lower legs on a bench, knees bent at about 90 degrees.","Place your hands lightly behind your head or across your chest.","Curl your shoulders off the floor by squeezing your abs.","Pause briefly at the top.","Lower slowly and repeat without pulling on your neck."],"img":"opengym/3279.webp","gif":null,"ext":1},{"id":"3280","n":"floor twisting crunch feet on bench","bp":"waist","eq":"body weight","tg":"obliques","mg":"core","sm":["core"],"st":["Lie on your back with your calves on a bench and knees bent.","Place your hands lightly behind your head.","Curl up and rotate so one shoulder moves toward the opposite knee.","Lower with control.","Alternate sides on each rep."],"img":"opengym/3280.webp","gif":null,"ext":1},{"id":"3282","n":"weighted floor crunch feet on bench","bp":"waist","eq":"weighted","tg":"abs","mg":"obliques","sm":["obliques","hip flexors"],"st":["Lie on your back with your calves on a bench and knees bent.","Hold a weight plate or dumbbell against your chest.","Curl your shoulders off the floor by tightening your abs.","Pause at the top.","Lower slowly and repeat."],"img":"opengym/3282.webp","gif":null,"ext":1},{"id":"3283","n":"weighted floor twisting crunch feet on bench","bp":"waist","eq":"weighted","tg":"obliques","mg":"core","sm":["core"],"st":["Lie on your back with your calves on a bench and knees bent.","Hold a light weight against your chest with both hands.","Curl up and rotate one shoulder toward the opposite knee.","Lower with control.","Alternate sides each rep."],"img":"opengym/3283.webp","gif":null,"ext":1},{"id":"3306","n":"strongman fingal's fingers","bp":"full body","eq":"body weight","tg":"forearms","mg":"grip muscles","sm":["grip muscles","hands","wrist flexors","core"],"st":["Set up the implement in front of you.","Grip it firmly with both hands.","Brace your core and keep your back flat.","Lift it using your legs and hips.","Hold it steady for a moment.","Lower it under control."],"img":"opengym/3306.webp","gif":null,"ext":1},{"id":"3307","n":"strongman keg toss","bp":"full body","eq":"weighted","tg":"glutes","mg":"hamstrings","sm":["hamstrings","lower back","shoulders","upper back"],"st":["Stand with feet wide and the keg between your legs, gripping it low with both hands.","Hinge at the hips, keep your chest up and your back flat.","Drive your hips forward hard and pull the keg up your body.","Extend fully and throw the keg up and back over the bar.","Reset, step back to the start and repeat with control."],"img":"opengym/3307.webp","gif":null,"ext":1},{"id":"3308","n":"barbell weighted deadlift","bp":"upper legs","eq":"barbell","tg":"glutes","mg":"hamstrings","sm":["hamstrings","lower back","grip muscles","quadriceps"],"st":["Stand with feet hip width apart and the bar over your mid foot.","Hinge down, grip the bar just outside your legs and brace your core.","Push the floor away and keep the bar close as you stand up.","Lock out with hips and knees extended and shoulders back.","Lower the bar along your legs with a flat back to the floor."],"img":"opengym/3308.webp","gif":null,"ext":1},{"id":"3309","n":"barbell weighted front chest squat","bp":"upper legs","eq":"barbell","tg":"quads","mg":"glutes","sm":["glutes","core","upper back","hamstrings"],"st":["Rest the bar on your front shoulders with elbows high and hands steadying it.","Stand with feet shoulder width apart and brace your core.","Sit down between your hips, keeping your chest tall.","Descend until your thighs are at least parallel to the floor.","Drive up through your whole foot and keep your elbows up the whole way."],"img":"opengym/3309.webp","gif":null,"ext":1},{"id":"3310","n":"barbell weighted bench press","bp":"chest","eq":"barbell","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders","upper chest"],"st":["Lie on the bench with eyes under the bar and feet flat on the floor.","Grip the bar slightly wider than shoulder width and unrack it over your chest.","Lower the bar under control to your mid chest.","Press it back up until your arms are straight.","Keep your shoulder blades pinched and your feet planted throughout."],"img":"opengym/3310.webp","gif":null,"ext":1},{"id":"3311","n":"barbell front squat (from blocks)","bp":"upper legs","eq":"barbell","tg":"quads","mg":"glutes","sm":["glutes","core","upper back","hamstrings"],"st":["Set the bar on the blocks or rack at front shoulder height.","Step in, rest the bar on your front shoulders with elbows high.","Lift it off and stand tall with feet shoulder width apart.","Squat down with a tall chest until your thighs pass parallel.","Stand back up by driving through your feet, then re-rack the bar."],"img":"opengym/3311.webp","gif":null,"ext":1},{"id":"3316","n":"barbell weightlifting complex","bp":"full body","eq":"barbell","tg":"cardiovascular system","mg":"glutes","sm":["glutes","hamstrings","shoulders","upper back","core"],"st":["Load a light to moderate barbell and stand over it with feet hip width apart.","Perform the first lift of your chosen sequence, such as a deadlift.","Move straight into the next lift without setting the bar down.","Keep each rep crisp with a braced core and a flat back.","Finish all lifts for one round, then lower the bar and rest before repeating."],"img":"opengym/3316.webp","gif":null,"ext":1},{"id":"3317","n":"strongman car flip","bp":"full body","eq":"weighted","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","lower back","shoulders","upper back"],"st":["Squat low at the edge of the vehicle with a flat back and hands underneath.","Brace your core and pull your chest up.","Drive hard through your legs and lift the edge to hip height.","Shift your hands and push up and over with your legs and arms.","Let it roll over fully, then step back and reset for the next flip."],"img":"opengym/3317.webp","gif":null,"ext":1},{"id":"3319","n":"dumbbell lying on floor hammer press","bp":"chest","eq":"dumbbell","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders","upper chest"],"st":["Lie on the floor with knees bent and a dumbbell in each hand, palms facing in.","Start with your upper arms resting on the floor.","Press the dumbbells straight up over your chest.","Pause briefly at the top without locking out hard.","Lower slowly until your triceps touch the floor and repeat."],"img":"opengym/3319.webp","gif":null,"ext":1},{"id":"3320","n":"dumbbell hammer grip incline bench two arm row","bp":"back","eq":"dumbbell","tg":"upper back","mg":"lats","sm":["lats","biceps","rear deltoids","rhomboids"],"st":["Set a bench to a low incline and lie chest down on it with a dumbbell in each hand.","Let your arms hang with palms facing each other.","Row both dumbbells toward your hips, leading with your elbows.","Squeeze your shoulder blades together at the top.","Lower slowly to full arm extension and repeat."],"img":"opengym/3320.webp","gif":null,"ext":1},{"id":"3321","n":"resistance band rear fly","bp":"shoulders","eq":"resistance band","tg":"delts","mg":"rear deltoids","sm":["rear deltoids","upper back","rhomboids","trapezius"],"st":["Hold the band in both hands in front of you with arms straight.","Stand tall with a soft knee bend and your core tight.","Pull your hands apart and out to the sides at shoulder height.","Squeeze your shoulder blades together at the end.","Return slowly to the start without letting the band snap back."],"img":"opengym/3321.webp","gif":null,"ext":1},{"id":"3322","n":"kettlebell deadlift","bp":"upper legs","eq":"kettlebell","tg":"glutes","mg":"hamstrings","sm":["hamstrings","lower back","quadriceps","grip muscles"],"st":["Stand with feet hip width apart and the kettlebell between your feet.","Push your hips back and bend your knees to grab the handle with both hands.","Keep your chest up and back flat.","Drive through your feet and stand tall, squeezing your glutes.","Hinge back down to set the kettlebell on the floor and repeat."],"img":"opengym/3322.webp","gif":null,"ext":1},{"id":"3323","n":"kettlebell half turkish get up","bp":"full body","eq":"kettlebell","tg":"abs","mg":"shoulders","sm":["shoulders","glutes","core","obliques","quadriceps"],"st":["Lie on your back with a kettlebell pressed up in one hand and the same side knee bent.","Keep your eyes on the bell and your arm vertical.","Roll onto the opposite elbow, then onto your hand.","Come up to a tall seated position with your arm still locked overhead.","Reverse the steps slowly to lie back down, then switch sides."],"img":"opengym/3323.webp","gif":null,"ext":1},{"id":"3324","n":"band alternate incline chest press with twist","bp":"chest","eq":"band","tg":"pectorals","mg":"upper chest","sm":["upper chest","triceps","shoulders","obliques","core"],"st":["Anchor a band low behind you and hold the handles at chest height.","Stand in a split stance with your core braced.","Press one hand up and forward while rotating your torso slightly.","Return under control and press with the other arm.","Keep your hips steady and alternate sides for the full set."],"img":"opengym/3324.webp","gif":null,"ext":1},{"id":"3325","n":"band alternate low row with twist","bp":"back","eq":"band","tg":"upper back","mg":"lats","sm":["lats","biceps","rhomboids","obliques","core"],"st":["Anchor a band in front of you at low height and hold both handles.","Stand in a staggered stance with arms extended.","Pull one handle back toward your hip while rotating your torso.","Squeeze your shoulder blade, then return slowly.","Repeat with the other arm and keep alternating."],"img":"opengym/3325.webp","gif":null,"ext":1},{"id":"3326","n":"band alternate lat pulldown with twist","bp":"back","eq":"band","tg":"lats","mg":"biceps","sm":["biceps","upper back","rhomboids","obliques","core"],"st":["Anchor a band high in front of you and hold both handles with arms overhead.","Stand tall in a staggered stance.","Pull one handle down toward your ribs while rotating your torso.","Keep your elbow tucked and shoulder down.","Return slowly and switch to the other arm."],"img":"opengym/3326.webp","gif":null,"ext":1},{"id":"3328","n":"barbell complex stiff leg deadlift clean step","bp":"full body","eq":"barbell","tg":"hamstrings","mg":"glutes","sm":["glutes","lower back","upper back","shoulders","quadriceps"],"st":["Stand holding a light barbell with an overhand grip at thigh height.","Lower the bar down your legs with soft knees and a flat back.","Stand up, then pull the bar explosively and catch it on your shoulders.","Take a controlled step forward with the bar racked.","Step back, lower the bar and begin the next round."],"img":"opengym/3328.webp","gif":null,"ext":1},{"id":"3329","n":"roman chair sit up","bp":"waist","eq":"body weight","tg":"abs","mg":"hip flexors","sm":["hip flexors","lower abs","obliques"],"st":["Sit on the roman chair with your feet locked under the pads.","Cross your arms over your chest and lean back slightly.","Curl your torso up until your chest nears your thighs.","Pause at the top and keep your neck relaxed.","Lower back slowly under control and repeat."],"img":"opengym/3329.webp","gif":null,"ext":1},{"id":"3330","n":"oblique crunches with bent knee leg lift","bp":"waist","eq":"body weight","tg":"obliques","mg":"lower abs","sm":["lower abs","hip flexors"],"st":["Lie on your back with your hands by your head and knees bent.","Lift your shoulders and knees at the same time.","Twist and bring one elbow toward the opposite knee.","Hold briefly, then lower with control.","Alternate sides through the set."],"img":"opengym/3330.webp","gif":null,"ext":1},{"id":"3331","n":"oblique crunches with straight leg lift","bp":"waist","eq":"body weight","tg":"obliques","mg":"lower abs","sm":["lower abs","hip flexors"],"st":["Lie on your back with legs raised straight and hands by your head.","Lift your shoulders off the floor.","Rotate to bring one elbow toward the opposite hip.","Keep your legs steady and low back pressed down.","Return slowly and alternate sides."],"img":"opengym/3331.webp","gif":null,"ext":1},{"id":"3332","n":"weighted stability ball crunch (full range)","bp":"waist","eq":"stability ball","tg":"abs","mg":"obliques","sm":["obliques","hip flexors","lower abs"],"st":["Sit on a stability ball and walk your feet out until your back is supported.","Hold a weight against your chest.","Let your torso drape back over the ball for a full stretch.","Curl up until your upper back clears the ball.","Lower slowly back into the stretch and repeat."],"img":"opengym/3332.webp","gif":null,"ext":1},{"id":"3333","n":"dumbbell one arm wide grip bench press","bp":"chest","eq":"dumbbell","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders","upper chest","core"],"st":["Lie on a bench with one dumbbell held over your chest.","Place your free arm on your stomach or out to the side.","Lower the dumbbell with elbow flared out until you feel a chest stretch.","Press it back up over your chest.","Keep your torso square, then switch arms after the set."],"img":"opengym/3333.webp","gif":null,"ext":1},{"id":"3334","n":"dumbbell one arm floor fly","bp":"chest","eq":"dumbbell","tg":"pectorals","mg":"shoulders","sm":["shoulders","upper chest","biceps"],"st":["Lie on the floor with knees bent and a dumbbell in one hand over your chest.","Keep a slight bend in your elbow.","Open your arm out to the side until your upper arm touches the floor.","Squeeze your chest to bring the dumbbell back above you.","Finish all reps, then switch arms."],"img":"opengym/3334.webp","gif":null,"ext":1},{"id":"3335","n":"dumbbell glute bridge","bp":"upper legs","eq":"dumbbell","tg":"glutes","mg":"hamstrings","sm":["hamstrings","core","lower back"],"st":["Lie on your back with knees bent and feet flat on the floor.","Hold a dumbbell across your hips.","Drive through your heels and lift your hips toward the ceiling.","Squeeze your glutes hard at the top.","Lower your hips slowly and repeat."],"img":"opengym/3335.webp","gif":null,"ext":1},{"id":"3336","n":"dumbbell v up","bp":"waist","eq":"dumbbell","tg":"abs","mg":"hip flexors","sm":["hip flexors","lower abs","obliques"],"st":["Lie flat with legs straight and a dumbbell held in both hands overhead.","Brace your core.","Lift your arms and legs together, forming a V shape.","Touch the dumbbell near your shins.","Lower back down slowly without dropping your legs."],"img":"opengym/3336.webp","gif":null,"ext":1},{"id":"3337","n":"dumbbell side bridge","bp":"waist","eq":"dumbbell","tg":"obliques","mg":"core","sm":["core","glutes","shoulders"],"st":["Lie on one side with your elbow under your shoulder and legs stacked.","Hold a dumbbell on your top hip.","Lift your hips so your body forms a straight line.","Hold for 20 to 30 seconds without sagging.","Lower, then repeat on the other side."],"img":"opengym/3337.webp","gif":null,"ext":1},{"id":"3338","n":"dumbbell single stiff leg deadlift","bp":"upper legs","eq":"dumbbell","tg":"hamstrings","mg":"glutes","sm":["glutes","lower back","core","grip muscles"],"st":["Stand on one leg with a dumbbell in the opposite hand or both hands.","Keep a soft bend in your standing knee.","Hinge forward while your free leg extends behind you.","Lower the dumbbell toward the floor with a flat back.","Squeeze your glute to stand back up, then switch legs."],"img":"opengym/3338.webp","gif":null,"ext":1},{"id":"3339","n":"dumbbell one arm lunge","bp":"upper legs","eq":"dumbbell","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","core","obliques"],"st":["Stand tall holding a dumbbell in one hand at your side.","Step forward into a long stride.","Lower your back knee toward the floor, keeping your torso upright.","Push through your front foot to return to standing.","Alternate legs and switch the dumbbell hand halfway."],"img":"opengym/3339.webp","gif":null,"ext":1},{"id":"3340","n":"dumbbell stiff leg deadlift v. 2","bp":"upper legs","eq":"dumbbell","tg":"hamstrings","mg":"glutes","sm":["glutes","lower back","grip muscles"],"st":["Stand with feet hip width apart holding dumbbells in front of your thighs.","Keep your knees slightly bent and back flat.","Push your hips back and slide the dumbbells down your legs.","Stop when you feel a hamstring stretch.","Drive your hips forward to stand tall."],"img":"opengym/3340.webp","gif":null,"ext":1},{"id":"3341","n":"dumbbell lunge v. 2","bp":"upper legs","eq":"dumbbell","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","calves","core"],"st":["Stand tall with a dumbbell in each hand at your sides.","Step forward into a long stride.","Bend both knees until your back knee nearly touches the floor.","Keep your front knee over your ankle and torso upright.","Push back to the start and switch legs."],"img":"opengym/3341.webp","gif":null,"ext":1},{"id":"3342","n":"cable y raise","bp":"shoulders","eq":"cable","tg":"delts","mg":"rear deltoids","sm":["rear deltoids","trapezius","upper back","rotator cuff"],"st":["Set the pulleys low and hold a handle in each hand, arms crossed in front.","Stand tall with a slight lean forward.","Raise both arms up and out into a Y shape.","Keep your thumbs pointing up and shoulders down.","Lower slowly to the start."],"img":"opengym/3342.webp","gif":null,"ext":1},{"id":"3343","n":"lever lateral raise v. 2","bp":"shoulders","eq":"leverage machine","tg":"delts","mg":"trapezius","sm":["trapezius","rotator cuff","upper back"],"st":["Adjust the seat so your shoulders line up with the machine pivots.","Sit tall and place your arms against the pads.","Raise your arms out to the sides to shoulder height.","Pause briefly at the top.","Lower slowly without letting the weights rest."],"img":"opengym/3343.webp","gif":null,"ext":1},{"id":"3344","n":"lever crossovers","bp":"chest","eq":"leverage machine","tg":"pectorals","mg":"shoulders","sm":["shoulders","upper chest","biceps"],"st":["Set the seat height and grip the handles with a slight elbow bend.","Sit tall with your back against the pad.","Sweep your arms together in front of your chest.","Squeeze your chest at the center.","Return slowly until you feel a stretch."],"img":"opengym/3344.webp","gif":null,"ext":1},{"id":"3345","n":"hand spring wrist curl","bp":"lower arms","eq":"weighted","tg":"forearms","mg":"wrist flexors","sm":["wrist flexors","grip muscles","hands"],"st":["Sit with a forearm resting on your thigh or a bench, palm up.","Hold the hand spring in that hand.","Squeeze the handles together by curling your wrist and fingers.","Hold briefly at full squeeze.","Release slowly, finish your reps, then switch hands."],"img":"opengym/3345.webp","gif":null,"ext":1},{"id":"3347","n":"dumbbell curl to press","bp":"upper arms","eq":"dumbbell","tg":"biceps","mg":"shoulders","sm":["shoulders","triceps","brachialis"],"st":["Stand tall holding a dumbbell in each hand, palms forward.","Curl both weights up to shoulder height without swinging.","Rotate your wrists slightly and press the weights overhead.","Lower to your shoulders, then back down to your sides.","Brace your core and keep your ribs down."],"img":"opengym/3347.webp","gif":null,"ext":1},{"id":"3348","n":"incline shoulder tap","bp":"chest","eq":"body weight","tg":"pectorals","mg":"shoulders","sm":["shoulders","core","triceps"],"st":["Place your hands on a bench or box and extend into a plank position.","Spread your feet slightly wider for balance.","Lift one hand and tap the opposite shoulder.","Keep your hips level and body in a straight line.","Alternate sides at a steady pace."],"img":"opengym/3348.webp","gif":null,"ext":1},{"id":"3349","n":"cable front squat","bp":"upper legs","eq":"cable","tg":"quads","mg":"glutes","sm":["glutes","core","hamstrings"],"st":["Set the cable low and hold the handle at your chest.","Step back to create tension and stand with feet shoulder width apart.","Sit down and back into a squat with your chest tall.","Descend until your thighs are parallel.","Drive up through your heels."],"img":"opengym/3349.webp","gif":null,"ext":1},{"id":"3350","n":"cable lateral lunge","bp":"upper legs","eq":"cable","tg":"glutes","mg":"quadriceps","sm":["quadriceps","adductors","hamstrings","core"],"st":["Hold a low cable handle at your chest and stand sideways to the stack.","Step wide to one side and sit back into that hip.","Keep the other leg straight and feet flat.","Push off your bent leg to return to center.","Complete the reps, then switch sides."],"img":"opengym/3350.webp","gif":null,"ext":1},{"id":"3351","n":"cable lunge","bp":"upper legs","eq":"cable","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","core"],"st":["Hold a cable handle at chest height and step away from the stack.","Step forward into a long stride.","Lower your back knee toward the floor.","Keep your torso upright and front heel down.","Push back to standing and alternate legs."],"img":"opengym/3351.webp","gif":null,"ext":1},{"id":"3352","n":"cable kneeling pull through","bp":"upper legs","eq":"cable","tg":"glutes","mg":"hamstrings","sm":["hamstrings","lower back","core"],"st":["Kneel facing away from a low cable with a rope held between your legs.","Sit your hips back with a flat back.","Let the rope pull your hands back between your knees.","Drive your hips forward to a tall kneeling position.","Squeeze your glutes at the top and repeat."],"img":"opengym/3352.webp","gif":null,"ext":1},{"id":"3353","n":"cable one arm high pulley overhead tricep extension","bp":"upper arms","eq":"cable","tg":"triceps","mg":"shoulders","sm":["shoulders","core"],"st":["Face away from a high pulley and hold the handle overhead with one hand.","Stand in a split stance with your elbow pointing up.","Extend your arm forward and up until it is straight.","Keep your upper arm still.","Return slowly and switch arms after the set."],"img":"opengym/3353.webp","gif":null,"ext":1},{"id":"3354","n":"cable front squat v. 2","bp":"upper legs","eq":"cable","tg":"quads","mg":"glutes","sm":["glutes","core","hamstrings"],"st":["Set the cable low and hold the handle against your chest.","Stand with feet shoulder width apart.","Sit down into a deep squat, chest tall.","Keep your knees tracking over your toes.","Press through your heels back to standing."],"img":"opengym/3354.webp","gif":null,"ext":1},{"id":"3355","n":"cable lateral lunge v. 2","bp":"upper legs","eq":"cable","tg":"glutes","mg":"quadriceps","sm":["quadriceps","adductors","hamstrings","core"],"st":["Hold a cable handle at chest height, standing sideways to the stack.","Step wide to the side and bend that knee.","Push your hips back and keep your chest up.","Push off the bent leg to return.","Finish your reps, then switch sides."],"img":"opengym/3355.webp","gif":null,"ext":1},{"id":"3356","n":"cable forward lunge","bp":"upper legs","eq":"cable","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","core"],"st":["Hold a low cable handle at your chest and stand facing away from the stack.","Take a big step forward.","Drop your back knee toward the floor.","Keep your front knee stable over the ankle.","Push back to the start and switch legs."],"img":"opengym/3356.webp","gif":null,"ext":1},{"id":"3357","n":"cable seated on floor row with rope","bp":"back","eq":"cable","tg":"upper back","mg":"lats","sm":["lats","biceps","rhomboids","rear deltoids"],"st":["Sit on the floor facing a low cable with legs extended and the rope in your hands.","Sit tall with a straight back.","Pull the rope toward your lower chest, spreading your hands.","Squeeze your shoulder blades together.","Extend your arms slowly and repeat."],"img":"opengym/3357.webp","gif":null,"ext":1},{"id":"3358","n":"cable parallel grip lat pulldown on floor","bp":"back","eq":"cable","tg":"lats","mg":"biceps","sm":["biceps","upper back","rhomboids"],"st":["Kneel or sit on the floor under a high cable with a parallel grip handle.","Sit tall and lean back slightly.","Pull the handle down to your upper chest.","Drive your elbows down and back.","Return slowly to full arm extension."],"img":"opengym/3358.webp","gif":null,"ext":1},{"id":"3359","n":"cable standing chest press","bp":"chest","eq":"cable","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders","upper chest","core"],"st":["Set the cables at chest height and hold a handle in each hand.","Step forward into a split stance.","Press the handles forward until your arms are straight.","Squeeze your chest at the end.","Return slowly with control."],"img":"opengym/3359.webp","gif":null,"ext":1},{"id":"3362","n":"cable lying close press","bp":"upper arms","eq":"cable","tg":"triceps","mg":"chest","sm":["chest","shoulders"],"st":["Lie on a bench with the cable behind your head and hold the handle with a narrow grip.","Start with arms bent over your chest.","Press up until your arms are straight.","Keep your elbows close to your body.","Lower slowly and repeat."],"img":"opengym/3362.webp","gif":null,"ext":1},{"id":"3363","n":"cable standing close press","bp":"upper arms","eq":"cable","tg":"triceps","mg":"chest","sm":["chest","shoulders","core"],"st":["Set the cable at chest height and hold the handle with a narrow grip.","Stand in a split stance, core tight.","Press forward until your arms are straight.","Keep your elbows tucked in.","Return slowly to the start."],"img":"opengym/3363.webp","gif":null,"ext":1},{"id":"3364","n":"cable seating close press","bp":"upper arms","eq":"cable","tg":"triceps","mg":"chest","sm":["chest","shoulders"],"st":["Sit on a bench facing away from a cable at chest height.","Hold the handle with a narrow grip.","Press forward until your arms are straight.","Keep your back against the pad.","Return slowly and repeat."],"img":"opengym/3364.webp","gif":null,"ext":1},{"id":"3365","n":"hawaiian squat","bp":"upper legs","eq":"body weight","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","adductors"],"st":["Stand with feet slightly wider than your shoulders and toes turned out.","Brace your core and keep your chest up.","Sit your hips down and back into a deep squat.","Pause at the bottom without rounding your back.","Drive through your feet to stand up."],"img":"opengym/3365.webp","gif":null,"ext":1},{"id":"3366","n":"shrimp squat","bp":"upper legs","eq":"body weight","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","core"],"st":["Stand on one leg and bend the other knee, holding that foot behind you.","Reach your free arm forward for balance.","Lower slowly until the back knee lightly touches the floor.","Drive through the front foot to stand.","Finish your reps, then switch legs."],"img":"opengym/3366.webp","gif":null,"ext":1},{"id":"3367","n":"skater squat","bp":"upper legs","eq":"body weight","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","core"],"st":["Stand on one leg with the other knee bent and the foot lifted behind you.","Swing your arms forward for balance.","Sit your hips back and lower on the standing leg.","Lightly tap the back knee near the floor.","Stand up through the front foot, then switch legs after your reps."],"img":"opengym/3367.webp","gif":null,"ext":1},{"id":"3368","n":"dumbbell swing","bp":"upper legs","eq":"dumbbell","tg":"glutes","mg":"hamstrings","sm":["hamstrings","lower back","shoulders","core"],"st":["Stand with feet wider than hips and hold one dumbbell in both hands.","Hinge at the hips and swing the dumbbell between your legs.","Snap your hips forward to swing it to chest height.","Let your arms stay relaxed.","Guide it back down and hinge into the next rep."],"img":"opengym/3368.webp","gif":null,"ext":1},{"id":"3369","n":"battling ropes alternate arms squat","bp":"full body","eq":"rope","tg":"cardiovascular system","mg":"quadriceps","sm":["quadriceps","glutes","shoulders","core"],"st":["Hold one rope end in each hand and stand with feet shoulder width apart.","Sit into a squat position.","Whip the ropes up and down with alternating arms.","Keep your chest tall and your knees stable.","Continue for a set time at a steady pace."],"img":"opengym/3369.webp","gif":null,"ext":1},{"id":"3370","n":"battling ropes alternate arms jump squat","bp":"full body","eq":"rope","tg":"cardiovascular system","mg":"quadriceps","sm":["quadriceps","glutes","calves","shoulders"],"st":["Hold the rope ends and stand in a squat position.","Start waving the ropes with alternating arms.","Jump up explosively and land softly.","Go straight into the next squat.","Keep going for a set time and rest when needed."],"img":"opengym/3370.webp","gif":null,"ext":1},{"id":"3371","n":"battling ropes side to side arms","bp":"shoulders","eq":"rope","tg":"cardiovascular system","mg":"shoulders","sm":["shoulders","core","obliques","upper back"],"st":["Hold the rope ends in an athletic stance with knees bent.","Swing both ropes to one side.","Swing them across to the other side in a flowing motion.","Rotate through your torso a little.","Keep a steady rhythm for the set time."],"img":"opengym/3371.webp","gif":null,"ext":1},{"id":"3372","n":"battling ropes alternate arms side lunge","bp":"full body","eq":"rope","tg":"cardiovascular system","mg":"glutes","sm":["glutes","quadriceps","adductors","shoulders"],"st":["Hold the rope ends and stand with feet together.","Step wide to one side and sit into a side lunge.","Whip the ropes alternately with your arms.","Push back to the middle.","Alternate sides and keep the waves going."],"img":"opengym/3372.webp","gif":null,"ext":1},{"id":"3373","n":"battling ropes inside circle","bp":"shoulders","eq":"rope","tg":"cardiovascular system","mg":"shoulders","sm":["shoulders","upper back","core","forearms"],"st":["Stand with knees bent and a rope end in each hand.","Move your arms in circles that turn inward.","Keep the circles even and large.","Brace your core and keep your chest up.","Continue for a set time then rest."],"img":"opengym/3373.webp","gif":null,"ext":1},{"id":"3374","n":"battling ropes outside circle","bp":"shoulders","eq":"rope","tg":"cardiovascular system","mg":"shoulders","sm":["shoulders","upper back","core","forearms"],"st":["Stand with knees bent and a rope end in each hand.","Move your arms in circles that turn outward.","Keep the movement smooth and even.","Keep your core tight.","Continue for a set time."],"img":"opengym/3374.webp","gif":null,"ext":1},{"id":"3375","n":"battling ropes fly","bp":"shoulders","eq":"rope","tg":"delts","mg":"chest","sm":["chest","upper back","core","rear deltoids"],"st":["Stand with knees bent, a rope end in each hand and arms in front.","Sweep your arms out wide and slightly up.","Bring them back together in front of you.","Keep a steady rhythm.","Continue for a set time."],"img":"opengym/3375.webp","gif":null,"ext":1},{"id":"3376","n":"battling ropes jumping jack","bp":"full body","eq":"rope","tg":"cardiovascular system","mg":"shoulders","sm":["shoulders","calves","quadriceps","core"],"st":["Hold the rope ends with feet together.","Jump your feet apart while raising your arms and making waves.","Jump back to the start.","Keep your landings soft.","Keep a steady pace for the set time."],"img":"opengym/3376.webp","gif":null,"ext":1},{"id":"3377","n":"battling ropes russian twist","bp":"waist","eq":"rope","tg":"obliques","mg":"shoulders","sm":["shoulders","core","hip flexors"],"st":["Sit on the floor with knees bent and lean back slightly.","Hold the rope ends in front of you.","Twist your torso to one side and swing the ropes.","Twist to the other side.","Keep your chest lifted and continue for the set time."],"img":"opengym/3377.webp","gif":null,"ext":1},{"id":"3378","n":"battling ropes split jump","bp":"full body","eq":"rope","tg":"cardiovascular system","mg":"quadriceps","sm":["quadriceps","glutes","calves","shoulders"],"st":["Hold the rope ends and stand in a split stance.","Start making waves with your arms.","Jump and switch legs in mid air.","Land softly in a lunge.","Keep switching for the set time."],"img":"opengym/3378.webp","gif":null,"ext":1},{"id":"3379","n":"battling ropes high waves","bp":"shoulders","eq":"rope","tg":"cardiovascular system","mg":"shoulders","sm":["shoulders","upper back","core","forearms"],"st":["Stand with feet shoulder width apart and a rope end in each hand.","Bend your knees slightly.","Raise both arms overhead and slam the ropes down.","Repeat quickly to make big waves.","Keep your core braced for the set time."],"img":"opengym/3379.webp","gif":null,"ext":1},{"id":"3380","n":"battling ropes low waves","bp":"cardio","eq":"rope","tg":"cardiovascular system","mg":"shoulders","sm":["shoulders","core","forearms","glutes"],"st":["Hold one rope end in each hand and stand in a quarter squat.","Brace your core and keep your chest up.","Whip the ropes down and up so waves travel low along the floor.","Keep the waves even and your hips stable.","Work for 20-30 seconds at a hard pace.","Rest, then repeat for several rounds."],"img":"opengym/3380.webp","gif":null,"ext":1},{"id":"3381","n":"inverted row under table","bp":"back","eq":"body weight","tg":"upper back","mg":"lats","sm":["lats","biceps","rhomboids","rear deltoids","core"],"st":["Lie under a sturdy table and grip the edge with both hands.","Extend your legs with heels on the floor and body in a straight line.","Pull your chest toward the table edge, squeezing your shoulder blades.","Lower with control until your arms are straight.","Keep your hips up the whole time."],"img":"opengym/3381.webp","gif":null,"ext":1},{"id":"3382","n":"inverted row bent knee under table","bp":"back","eq":"body weight","tg":"upper back","mg":"lats","sm":["lats","biceps","rhomboids","rear deltoids"],"st":["Lie under a sturdy table and grip the edge with both hands.","Bend your knees and plant your feet on the floor.","Lift your hips so your body forms a line from knees to shoulders.","Pull your chest to the table edge, squeezing your shoulder blades.","Lower slowly and repeat."],"img":"opengym/3382.webp","gif":null,"ext":1},{"id":"3383","n":"pike push up (on bench) v. 2","bp":"shoulders","eq":"body weight","tg":"delts","mg":"triceps","sm":["triceps","upper chest","core"],"st":["Place your feet on a bench and your hands on the floor, hips piked high.","Walk your hands back until your body forms an inverted V.","Bend your elbows and lower your head toward the floor.","Keep your elbows at about 45 degrees from your body.","Press back up until your arms are straight.","Keep your core tight throughout."],"img":"opengym/3383.webp","gif":null,"ext":1},{"id":"3384","n":"battling ropes power slam","bp":"cardio","eq":"rope","tg":"cardiovascular system","mg":"shoulders","sm":["shoulders","core","lats","glutes"],"st":["Hold a rope end in each hand and stand in an athletic stance.","Raise both ropes overhead while rising onto your toes.","Slam them down hard while dropping into a squat.","Keep your back flat and your core braced.","Reset and repeat at a steady, powerful pace.","Work in bursts of 15-30 seconds."],"img":"opengym/3384.webp","gif":null,"ext":1},{"id":"3385","n":"lever seated leg press v. 2","bp":"upper legs","eq":"leverage machine","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","calves"],"st":["Sit on the machine and set your back firmly against the pad.","Place your feet on the platform about shoulder-width apart.","Release the safety and lower the weight until your knees bend to about 90 degrees.","Press through your whole foot to extend your legs.","Stop just short of locking your knees.","Lower under control and repeat."],"img":"opengym/3385.webp","gif":null,"ext":1},{"id":"3386","n":"lever seated leg extension v. 2","bp":"upper legs","eq":"leverage machine","tg":"quads","mg":"hip flexors","sm":["hip flexors"],"st":["Sit on the machine with your back against the pad.","Hook your lower shins under the roller and align your knees with the pivot.","Extend your legs until they are nearly straight.","Squeeze your quads briefly at the top.","Lower slowly back to the start.","Avoid swinging or lifting your hips."],"img":"opengym/3386.webp","gif":null,"ext":1},{"id":"3387","n":"dips between chairs","bp":"upper arms","eq":"body weight","tg":"triceps","mg":"chest","sm":["chest","shoulders","upper chest"],"st":["Place two sturdy chairs facing each other and brace them against a wall.","Grip the seats, lift your body and straighten your arms.","Lower yourself by bending your elbows until your upper arms are about parallel to the floor.","Keep your elbows pointing back and your chest up.","Press up to straight arms.","Make sure the chairs cannot slide."],"img":"opengym/3387.webp","gif":null,"ext":1},{"id":"3388","n":"inverted row between chairs","bp":"back","eq":"body weight","tg":"upper back","mg":"lats","sm":["lats","biceps","rhomboids","core"],"st":["Set a sturdy bar or table edge between two stable chairs and lie under it.","Grip the support with straight arms and your body in a plank line.","Pull your chest toward the support.","Squeeze your shoulder blades together at the top.","Lower slowly until your arms are straight.","Keep your hips up the whole time."],"img":"opengym/3388.webp","gif":null,"ext":1},{"id":"3389","n":"sit up with chair assisted","bp":"waist","eq":"body weight","tg":"abs","mg":"hip flexors","sm":["hip flexors","obliques"],"st":["Lie on your back and rest your lower legs on a chair seat, knees bent.","Cross your arms over your chest or place your hands by your ears.","Curl your torso up toward your knees.","Pause briefly at the top.","Lower back down slowly.","Do not pull on your neck."],"img":"opengym/3389.webp","gif":null,"ext":1},{"id":"3390","n":"calf raise from deficit with chair supported","bp":"lower legs","eq":"body weight","tg":"calves","mg":"soleus","sm":["soleus","ankles","feet"],"st":["Stand with the balls of your feet on a step edge, holding a chair for balance.","Let your heels drop below the step to stretch your calves.","Rise as high onto your toes as you can.","Pause for a second at the top.","Lower slowly into the deep stretch.","Keep your knees almost straight."],"img":"opengym/3390.webp","gif":null,"ext":1},{"id":"3391","n":"bent over twist","bp":"waist","eq":"body weight","tg":"obliques","mg":"abdominals","sm":["abdominals","lower back","hamstrings"],"st":["Stand with feet wide and hinge forward at the hips with a flat back.","Extend your arms out to the sides.","Rotate your torso and reach one hand toward the opposite foot.","Return through the middle and twist to the other side.","Move with control and keep your hips square.","Do 10-12 reps per side."],"img":"opengym/3391.webp","gif":null,"ext":1},{"id":"3392","n":"narrow squat from deficit","bp":"upper legs","eq":"body weight","tg":"quads","mg":"glutes","sm":["glutes","adductors","calves"],"st":["Stand with your heels on a low platform and your feet close together.","Hold your arms in front for balance.","Squat down, keeping your knees over your toes.","Go as deep as comfortable with your chest up.","Drive up through your feet.","Stand tall without locking out hard."],"img":"opengym/3392.webp","gif":null,"ext":1},{"id":"3393","n":"lying leg hip raise on floor","bp":"waist","eq":"body weight","tg":"abs","mg":"lower abs","sm":["lower abs","hip flexors"],"st":["Lie on your back with arms by your sides or holding something behind your head.","Raise your legs to vertical.","Lift your hips off the floor, pushing your feet toward the ceiling.","Lower your hips slowly.","Lower your legs without arching your back.","Keep movements smooth, not swinging."],"img":"opengym/3393.webp","gif":null,"ext":1},{"id":"3394","n":"glute march","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"hamstrings","sm":["hamstrings","core"],"st":["Lie on your back with knees bent and feet flat.","Lift your hips into a bridge.","Raise one knee toward your chest without letting your hips drop.","Place that foot down and lift the other.","Keep squeezing your glutes the whole time.","Continue alternating for 10-20 marches."],"img":"opengym/3394.webp","gif":null,"ext":1},{"id":"3395","n":"sliding leg curl on floor with towel","bp":"upper legs","eq":"body weight","tg":"hamstrings","mg":"glutes","sm":["glutes","calves","core"],"st":["Lie on your back with your heels on towels on a smooth floor.","Lift your hips into a bridge.","Slide your heels away until your legs are nearly straight.","Pull your heels back toward your hips.","Keep your hips high throughout.","Move slowly to stay in control."],"img":"opengym/3395.webp","gif":null,"ext":1},{"id":"3396","n":"flexion and extension hip stretch","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"hip flexors","sm":["hip flexors","hamstrings","lower back"],"st":["Lie on your back with your legs extended.","Pull one knee toward your chest with both hands.","Hold for 20-30 seconds.","Extend the leg again and press it down to the floor.","Repeat on the other leg.","Breathe slowly and stay relaxed."],"img":"opengym/3396.webp","gif":null,"ext":1},{"id":"3397","n":"dumbbell full swing","bp":"upper legs","eq":"dumbbell","tg":"glutes","mg":"hamstrings","sm":["hamstrings","lower back","shoulders","core"],"st":["Hold one dumbbell with both hands and stand with feet shoulder-width apart.","Hinge back and swing the weight between your legs.","Drive your hips forward to swing the dumbbell overhead.","Let it fall back and hinge again.","Keep your back flat and your arms loose.","Control the dumbbell at all times."],"img":"opengym/3397.webp","gif":null,"ext":1},{"id":"3398","n":"dumbbell front rack lunge","bp":"upper legs","eq":"dumbbell","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","core"],"st":["Hold a dumbbell in each hand at shoulder height.","Step forward into a long stride.","Lower your back knee toward the floor.","Keep your torso upright and your front knee over your ankle.","Push back to the start.","Alternate legs for each rep."],"img":"opengym/3398.webp","gif":null,"ext":1},{"id":"3399","n":"barbell front rack lunge","bp":"upper legs","eq":"barbell","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","core","upper back"],"st":["Rest the barbell on your front shoulders with elbows high.","Step forward into a long stride.","Lower your back knee toward the floor.","Keep your chest tall and your core braced.","Push through the front foot to return.","Alternate legs or finish all reps on one side."],"img":"opengym/3399.webp","gif":null,"ext":1},{"id":"3400","n":"dumbbell clean and press","bp":"full body","eq":"dumbbell","tg":"delts","mg":"triceps","sm":["triceps","glutes","quadriceps","upper back"],"st":["Stand over two dumbbells and grip them with a flat back.","Pull the weights up explosively and catch them at your shoulders.","Dip slightly and drive them overhead.","Lock out your arms.","Lower to your shoulders, then to the floor with control.","Keep the weights close to your body."],"img":"opengym/3400.webp","gif":null,"ext":1},{"id":"3401","n":"pike push up (between benches)","bp":"shoulders","eq":"body weight","tg":"delts","mg":"triceps","sm":["triceps","upper chest","core"],"st":["Put your feet on one bench and your hands on the floor or a second bench.","Raise your hips into a pike.","Lower your head between your hands.","Keep elbows at about 45 degrees.","Press back up to straight arms.","Keep your core tight."],"img":"opengym/3401.webp","gif":null,"ext":1},{"id":"3402","n":"pike push up (between chairs)","bp":"shoulders","eq":"body weight","tg":"delts","mg":"triceps","sm":["triceps","upper chest","core"],"st":["Set two sturdy chairs shoulder-width apart and grip them.","Walk your feet back and lift your hips into a pike.","Bend your elbows to lower your head between the chairs.","Keep your back flat and elbows slightly in.","Press back up.","Make sure the chairs are stable."],"img":"opengym/3402.webp","gif":null,"ext":1},{"id":"3403","n":"standing y raise","bp":"shoulders","eq":"body weight","tg":"traps","mg":"rear deltoids","sm":["rear deltoids","shoulders","rhomboids"],"st":["Stand tall with arms by your sides, thumbs pointing up.","Raise both arms diagonally overhead to form a Y.","Squeeze your shoulder blades down and back.","Pause briefly, then lower slowly.","Keep your neck long and avoid shrugging."],"img":"opengym/3403.webp","gif":null,"ext":1},{"id":"3404","n":"standing t raise","bp":"shoulders","eq":"body weight","tg":"upper back","mg":"rear deltoids","sm":["rear deltoids","rhomboids","trapezius"],"st":["Stand tall with arms in front of you at chest height.","Open your arms out to the sides into a T.","Squeeze your shoulder blades together.","Pause, then return slowly.","Keep your ribs down and avoid leaning back."],"img":"opengym/3404.webp","gif":null,"ext":1},{"id":"3405","n":"standing w raise","bp":"shoulders","eq":"body weight","tg":"upper back","mg":"rotator cuff","sm":["rotator cuff","rear deltoids","rhomboids"],"st":["Stand tall with elbows bent and hands in front of your chest.","Pull your elbows back and down, forming a W.","Squeeze your shoulder blades together and rotate your hands outward.","Pause briefly.","Return slowly and repeat."],"img":"opengym/3405.webp","gif":null,"ext":1},{"id":"3407","n":"standing low body rotation","bp":"waist","eq":"body weight","tg":"obliques","mg":"abdominals","sm":["abdominals","lower back"],"st":["Stand with feet slightly wider than your hips and knees soft.","Hold your hands in front of your waist.","Rotate your hips and trunk to one side.","Return through the centre and rotate to the other side.","Move smoothly for 10-15 reps per side."],"img":"opengym/3407.webp","gif":null,"ext":1},{"id":"3408","n":"standing upper body rotation","bp":"waist","eq":"body weight","tg":"obliques","mg":"abdominals","sm":["abdominals","upper back"],"st":["Stand with feet hip-width apart and hands clasped in front of your chest.","Keep your hips facing forward.","Rotate your upper body to one side as far as is comfortable.","Return through the centre and rotate the other way.","Keep it smooth for 10-15 reps per side."],"img":"opengym/3408.webp","gif":null,"ext":1},{"id":"3409","n":"standing phelps","bp":"shoulders","eq":"body weight","tg":"delts","mg":"rotator cuff","sm":["rotator cuff","upper back","chest"],"st":["Stand tall with feet shoulder-width apart.","Swing both arms forward and up in big arcs.","Swing them back down past your hips behind you.","Keep the movement loose and rhythmic.","Continue for 20-30 seconds."],"img":"opengym/3409.webp","gif":null,"ext":1},{"id":"3410","n":"standing wring the towel","bp":"waist","eq":"body weight","tg":"abs","mg":"obliques","sm":["obliques","shoulders","forearms"],"st":["Stand with feet hip-width apart and hands clasped in front of you.","Rotate your torso to one side while your hands twist across.","Return to the centre and rotate the other way.","Keep your hips mostly facing forward.","Continue for 10-15 reps per side."],"img":"opengym/3410.webp","gif":null,"ext":1},{"id":"3411","n":"standing hip circle","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"hip flexors","sm":["hip flexors","core","obliques"],"st":["Stand with feet shoulder-width apart and hands on your hips.","Push your hips out to one side, then forward, back and around.","Draw a large smooth circle.","Keep your shoulders still.","Do 10 circles, then reverse direction."],"img":"opengym/3411.webp","gif":null,"ext":1},{"id":"3412","n":"lying glute squeeze","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"hamstrings","sm":["hamstrings","lower back","core"],"st":["Lie on your back with knees bent and feet flat on the floor.","Squeeze your glutes and lift your hips slightly.","Hold the squeeze for 2 seconds.","Lower your hips without relaxing completely.","Repeat for 12-15 reps."],"img":"opengym/3412.webp","gif":null,"ext":1},{"id":"3413","n":"lying shoulder sweep","bp":"shoulders","eq":"body weight","tg":"delts","mg":"upper back","sm":["upper back","chest","rotator cuff"],"st":["Lie on your back with arms straight out to the sides.","Sweep both arms up in an arc toward overhead.","Keep your arms as close to the floor as you comfortably can.","Return along the same path.","Move slowly for 10-12 reps."],"img":"opengym/3413.webp","gif":null,"ext":1},{"id":"3414","n":"lying upper body rotation","bp":"waist","eq":"body weight","tg":"spine","mg":"obliques","sm":["obliques","core","upper back"],"st":["Lie on your side with knees bent and arms stretched in front of you.","Keep your knees stacked.","Lift the top arm and open it across to the other side, following it with your eyes.","Return the arm to the start.","Do 10 reps, then switch sides."],"img":"opengym/3414.webp","gif":null,"ext":1},{"id":"3415","n":"assisted inverse leg curl","bp":"upper legs","eq":"assisted","tg":"hamstrings","mg":"glutes","sm":["glutes","calves","core"],"st":["Kneel with your ankles secured and your torso upright.","Use the assistance as needed.","Lean forward slowly, resisting with your hamstrings.","Lower as far as you can control.","Pull yourself back up with your hamstrings and hands if needed.","Keep your hips extended."],"img":"opengym/3415.webp","gif":null,"ext":1},{"id":"3416","n":"standing shoulder circling","bp":"shoulders","eq":"body weight","tg":"delts","mg":"trapezius","sm":["trapezius","rotator cuff","upper back"],"st":["Stand tall with arms relaxed at your sides.","Lift your shoulders up and roll them back in a large circle.","Keep your neck relaxed.","Do 10 circles, then reverse the direction."],"img":"opengym/3416.webp","gif":null,"ext":1},{"id":"3417","n":"kneeling one arm reach roll lift","bp":"back","eq":"body weight","tg":"upper back","mg":"core","sm":["core","shoulders","obliques"],"st":["Start on hands and knees with hands under shoulders.","Reach one arm forward along the floor.","Roll that arm up and across, rotating your chest.","Lift it toward the ceiling, following your hand with your eyes.","Return and repeat, then switch arms."],"img":"opengym/3417.webp","gif":null,"ext":1},{"id":"3422","n":"medicine ball crunch","bp":"waist","eq":"medicine ball","tg":"abs","mg":"obliques","sm":["obliques","hip flexors"],"st":["Lie on your back with knees bent and hold a medicine ball on your chest.","Curl your shoulders off the floor.","Squeeze your abs at the top.","Lower slowly.","Keep your chin off your chest.","Breathe out as you crunch up."],"img":"opengym/3422.webp","gif":null,"ext":1},{"id":"3428","n":"dumbbell front raise v. 3","bp":"shoulders","eq":"dumbbell","tg":"delts","mg":"upper chest","sm":["upper chest","trapezius"],"st":["Stand tall holding a dumbbell in each hand in front of your thighs.","Brace your core and keep a slight bend in your elbows.","Raise the weights in front of you to shoulder height.","Pause briefly.","Lower slowly without swinging your body."],"img":"opengym/3428.webp","gif":null,"ext":1},{"id":"3435","n":"single leg hip bridge (straight leg)","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"hamstrings","sm":["hamstrings","core","lower back"],"st":["Lie on your back with one knee bent and foot flat.","Extend the other leg straight.","Drive through your heel and lift your hips.","Keep your pelvis level.","Lower with control.","Switch legs after your set."],"img":"opengym/3435.webp","gif":null,"ext":1},{"id":"3436","n":"superman","bp":"back","eq":"body weight","tg":"spine","mg":"glutes","sm":["glutes","hamstrings","rear deltoids"],"st":["Lie face down with arms extended in front.","Lift your arms, chest and legs off the floor together.","Squeeze your glutes and lower back.","Hold for 1-2 seconds.","Lower slowly.","Keep your neck neutral."],"img":"opengym/3436.webp","gif":null,"ext":1},{"id":"3438","n":"decline leg hip raise","bp":"waist","eq":"body weight","tg":"abs","mg":"lower abs","sm":["lower abs","hip flexors"],"st":["Lie on a decline bench and hold the top edge.","Bring your legs up over your hips.","Lift your hips toward the ceiling.","Lower your hips first.","Lower your legs with control.","Avoid swinging."],"img":"opengym/3438.webp","gif":null,"ext":1},{"id":"3439","n":"medicine ball backward throw","bp":"full body","eq":"medicine ball","tg":"glutes","mg":"hamstrings","sm":["hamstrings","lower back","shoulders","core"],"st":["Stand with a medicine ball held between your legs.","Squat slightly, then explode up.","Swing the ball up and back over your head.","Release it behind you at full extension.","Retrieve the ball.","Reset your stance and repeat."],"img":"opengym/3439.webp","gif":null,"ext":1},{"id":"3440","n":"split jump to box","bp":"upper legs","eq":"body weight","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","calves"],"st":["Stand in a lunge position facing a box.","Swing your arms and jump up.","Land with both feet softly on the box.","Stand tall.","Step down carefully.","Switch your front leg and repeat."],"img":"opengym/3440.webp","gif":null,"ext":1},{"id":"3441","n":"seated flexion and extension neck","bp":"neck","eq":"body weight","tg":"levator scapulae","mg":"sternocleidomastoid","sm":["sternocleidomastoid","trapezius"],"st":["Sit tall with your shoulders relaxed.","Lower your chin gently toward your chest.","Hold for a moment.","Slowly lift your head and look up slightly.","Move through a comfortable range only.","Repeat 8-10 times smoothly."],"img":"opengym/3441.webp","gif":null,"ext":1},{"id":"3442","n":"medicine ball standing overhead throw","bp":"chest","eq":"medicine ball","tg":"pectorals","mg":"shoulders","sm":["shoulders","triceps","core"],"st":["Stand with feet shoulder-width apart holding the ball overhead.","Arch back slightly.","Throw the ball forward and down with force.","Follow through with your arms.","Pick up the ball.","Reset and repeat."],"img":"opengym/3442.webp","gif":null,"ext":1},{"id":"3443","n":"dip on floor with chair","bp":"upper arms","eq":"body weight","tg":"triceps","mg":"shoulders","sm":["shoulders","chest"],"st":["Sit on the floor with hands on a chair behind you.","Lift your hips off the floor.","Bend your elbows to lower your body.","Keep elbows pointing back.","Press up.","Brace the chair against a wall."],"img":"opengym/3443.webp","gif":null,"ext":1},{"id":"3444","n":"step up on chair","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","calves"],"st":["Face a sturdy chair.","Place one foot fully on the seat.","Drive through that heel to stand up.","Bring the other foot up.","Step down with control.","Do all reps on one leg, then switch."],"img":"opengym/3444.webp","gif":null,"ext":1},{"id":"3448","n":"dumbbell side lunge v. 3","bp":"upper legs","eq":"dumbbell","tg":"glutes","mg":"quadriceps","sm":["quadriceps","adductors","hamstrings"],"st":["Hold a dumbbell in each hand.","Step wide to one side.","Sit your hips back and bend that knee.","Keep your other leg straight.","Push off to return to center.","Alternate sides."],"img":"opengym/3448.webp","gif":null,"ext":1},{"id":"3449","n":"dumbbell russian twist","bp":"waist","eq":"dumbbell","tg":"obliques","mg":"abdominals","sm":["abdominals","hip flexors","lower back"],"st":["Sit with knees bent and lean back slightly.","Hold a dumbbell with both hands in front of you.","Rotate your torso to one side.","Rotate to the other side.","Keep your chest lifted.","Move with control."],"img":"opengym/3449.webp","gif":null,"ext":1},{"id":"3452","n":"dumbbell svend press","bp":"chest","eq":"dumbbell","tg":"pectorals","mg":"shoulders","sm":["shoulders","triceps"],"st":["Stand holding a dumbbell upright between your palms.","Hold it at chest level.","Squeeze your palms together.","Press the weight straight out.","Return to your chest.","Keep the squeeze all the time."],"img":"opengym/3452.webp","gif":null,"ext":1},{"id":"3454","n":"dumbbell superman","bp":"back","eq":"dumbbell","tg":"spine","mg":"glutes","sm":["glutes","hamstrings","rear deltoids"],"st":["Lie face down holding light dumbbells with arms extended.","Lift your chest, arms and legs.","Squeeze your glutes.","Hold for a moment.","Lower with control.","Keep your neck neutral."],"img":"opengym/3454.webp","gif":null,"ext":1},{"id":"3457","n":"burpee with push up","bp":"full body","eq":"body weight","tg":"cardiovascular system","mg":"chest","sm":["chest","triceps","quadriceps","core"],"st":["Stand with feet shoulder-width apart.","Squat and place your hands on the floor.","Jump your feet back to a plank.","Do a push-up.","Jump your feet in and leap up.","Repeat at a steady pace."],"img":"opengym/3457.webp","gif":null,"ext":1},{"id":"3458","n":"side split","bp":"upper legs","eq":"body weight","tg":"adductors","mg":"groin","sm":["groin","hamstrings","inner thighs"],"st":["Sit or stand with your legs as wide as comfortable.","Keep your toes pointing up or forward.","Lower slowly into the split.","Keep your back long.","Hold for 20-30 seconds.","Come out gently."],"img":"opengym/3458.webp","gif":null,"ext":1},{"id":"3459","n":"pulse up","bp":"waist","eq":"body weight","tg":"abs","mg":"lower abs","sm":["lower abs","hip flexors"],"st":["Lie on your back with legs pointing to the ceiling.","Place your hands by your sides.","Lift your hips slightly with a small pulse.","Lower and repeat.","Keep movement small.","Do 15-20 pulses."],"img":"opengym/3459.webp","gif":null,"ext":1},{"id":"3460","n":"side plank hip adduction (bent knee)","bp":"upper legs","eq":"body weight","tg":"adductors","mg":"obliques","sm":["obliques","core","glutes"],"st":["Set up in a side plank with the bottom knee bent.","Keep your body straight.","Lift your hips.","Raise the bottom leg toward the top leg.","Lower with control.","Switch sides."],"img":"opengym/3460.webp","gif":null,"ext":1},{"id":"3461","n":"warming up in lunge (one)","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","hip flexors"],"st":["Stand tall with your feet hip-width apart and your core braced.","Step into the lunge position described by this variation with control.","Keep your front knee over your ankle and your torso upright.","Move smoothly through the full range without bouncing.","Return to standing and repeat on the other side.","Do 8-10 slow reps per side as part of a warm-up."],"img":"opengym/3461.webp","gif":null,"ext":1},{"id":"3462","n":"warming up in lunge (two)","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","hip flexors"],"st":["Stand tall with your feet hip-width apart and your core braced.","Step into the lunge position described by this variation with control.","Keep your front knee over your ankle and your torso upright.","Move smoothly through the full range without bouncing.","Return to standing and repeat on the other side.","Do 8-10 slow reps per side as part of a warm-up."],"img":"opengym/3462.webp","gif":null,"ext":1},{"id":"3463","n":"warming up in lunge (three)","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","hip flexors"],"st":["Stand tall with your feet hip-width apart and your core braced.","Step into the lunge position described by this variation with control.","Keep your front knee over your ankle and your torso upright.","Move smoothly through the full range without bouncing.","Return to standing and repeat on the other side.","Do 8-10 slow reps per side as part of a warm-up."],"img":"opengym/3463.webp","gif":null,"ext":1},{"id":"3464","n":"warming up in lunge (four)","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","hip flexors"],"st":["Stand tall with your feet hip-width apart and your core braced.","Step into the lunge position described by this variation with control.","Keep your front knee over your ankle and your torso upright.","Move smoothly through the full range without bouncing.","Return to standing and repeat on the other side.","Do 8-10 slow reps per side as part of a warm-up."],"img":"opengym/3464.webp","gif":null,"ext":1},{"id":"3465","n":"warming up in lunge (five)","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","hip flexors"],"st":["Stand tall with your feet hip-width apart and your core braced.","Step into the lunge position described by this variation with control.","Keep your front knee over your ankle and your torso upright.","Move smoothly through the full range without bouncing.","Return to standing and repeat on the other side.","Do 8-10 slow reps per side as part of a warm-up."],"img":"opengym/3465.webp","gif":null,"ext":1},{"id":"3466","n":"warming up in lunge (six)","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","hip flexors"],"st":["Stand tall with your feet hip-width apart and your core braced.","Step into the lunge position described by this variation with control.","Keep your front knee over your ankle and your torso upright.","Move smoothly through the full range without bouncing.","Return to standing and repeat on the other side.","Do 8-10 slow reps per side as part of a warm-up."],"img":"opengym/3466.webp","gif":null,"ext":1},{"id":"3467","n":"warming up in lunge (seven)","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","hip flexors"],"st":["Stand tall with your feet hip-width apart and your core braced.","Step into the lunge position described by this variation with control.","Keep your front knee over your ankle and your torso upright.","Move smoothly through the full range without bouncing.","Return to standing and repeat on the other side.","Do 8-10 slow reps per side as part of a warm-up."],"img":"opengym/3467.webp","gif":null,"ext":1},{"id":"3468","n":"front hamstring stretch","bp":"upper legs","eq":"body weight","tg":"hamstrings","mg":"calves","sm":["calves","lower back"],"st":["Place one heel forward on the floor with the toes up.","Keep that leg straight.","Hinge at the hips with a flat back.","Feel the stretch behind your thigh.","Hold for 20-30 seconds.","Switch legs."],"img":"opengym/3468.webp","gif":null,"ext":1},{"id":"3469","n":"downward facing dog","bp":"full body","eq":"body weight","tg":"hamstrings","mg":"calves","sm":["calves","shoulders","upper back"],"st":["Start on hands and knees.","Tuck your toes and lift your hips up and back.","Press your chest toward your thighs.","Keep your arms straight.","Hold for 20-30 seconds.","Lower down gently."],"img":"opengym/3469.webp","gif":null,"ext":1},{"id":"3471","n":"warrior pose","bp":"upper legs","eq":"body weight","tg":"quads","mg":"glutes","sm":["glutes","hip flexors","shoulders","core"],"st":["Take a long stance.","Bend your front knee over your ankle.","Raise your arms.","Keep your back leg straight.","Hold for 20-30 seconds.","Switch sides."],"img":"opengym/3471.webp","gif":null,"ext":1},{"id":"3472","n":"lying leg tuck hip stretch","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"hip flexors","sm":["hip flexors","lower back","hamstrings"],"st":["Lie on your back.","Pull one knee toward your chest.","Keep your other leg relaxed.","Hold for 20-30 seconds.","Release slowly.","Switch legs."],"img":"opengym/3472.webp","gif":null,"ext":1},{"id":"3473","n":"standing balance outer hip stretch","bp":"upper legs","eq":"body weight","tg":"abductors","mg":"glutes","sm":["glutes","core","ankles"],"st":["Stand tall near a support.","Cross one ankle over the opposite knee.","Sit back slightly.","Feel the stretch in your outer hip.","Hold for 20-30 seconds.","Switch sides."],"img":"opengym/3473.webp","gif":null,"ext":1},{"id":"3474","n":"lying leg tuck hip stretch with overhead hands","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"hip flexors","sm":["hip flexors","lower back","hamstrings"],"st":["Lie on your back with your arms overhead.","Pull one knee toward your chest.","Keep your arms reaching.","Hold for 20-30 seconds.","Release slowly.","Switch legs."],"img":"opengym/3474.webp","gif":null,"ext":1},{"id":"3475","n":"lying leg tuck hip back stretch","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"hip flexors","sm":["hip flexors","lower back","hamstrings"],"st":["Lie on your back.","Hug both knees toward your chest.","Rock gently if comfortable.","Hold for 20-30 seconds.","Relax your shoulders.","Release slowly."],"img":"opengym/3475.webp","gif":null,"ext":1},{"id":"3476","n":"lying leg tuck hip twist stretch","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"hip flexors","sm":["hip flexors","lower back","hamstrings"],"st":["Lie on your back and pull your knees in.","Drop both knees to one side.","Keep your shoulders on the floor.","Hold for 20-30 seconds.","Return to the center.","Switch sides."],"img":"opengym/3476.webp","gif":null,"ext":1},{"id":"3477","n":"lying leg tuck hip back to right stretch","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"hip flexors","sm":["hip flexors","lower back","hamstrings"],"st":["Lie on your back and tuck your knees.","Lower your knees to the right.","Keep both shoulders down.","Hold for 20-30 seconds.","Breathe slowly.","Return to center."],"img":"opengym/3477.webp","gif":null,"ext":1},{"id":"3478","n":"lying leg tuck hip twist to left stretch","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"hip flexors","sm":["hip flexors","lower back","hamstrings"],"st":["Lie on your back and tuck your knees.","Lower your knees to the left.","Keep both shoulders down.","Hold for 20-30 seconds.","Breathe slowly.","Return to center."],"img":"opengym/3478.webp","gif":null,"ext":1},{"id":"3479","n":"alternate heel touch side kick squat","bp":"upper legs","eq":"body weight","tg":"quads","mg":"glutes","sm":["glutes","hip flexors","core"],"st":["Stand with feet hip-width apart.","Squat down.","Stand and kick one leg to the side.","Touch the heel with your hand.","Squat again.","Alternate sides."],"img":"opengym/3479.webp","gif":null,"ext":1},{"id":"3480","n":"alternate sprinter lunge","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","hip flexors"],"st":["Stand tall.","Step back into a deep lunge.","Drive your arms like a sprinter.","Push back to standing.","Alternate legs.","Keep your torso upright."],"img":"opengym/3480.webp","gif":null,"ext":1},{"id":"3481","n":"split sprinter low lunge","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","hip flexors"],"st":["Step into a long lunge.","Lower your back knee near the floor.","Keep your torso tall.","Hold the low position briefly.","Push up.","Switch legs."],"img":"opengym/3481.webp","gif":null,"ext":1},{"id":"3482","n":"split sprinter high lunge","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","hip flexors","calves"],"st":["Stand tall and step one foot well back into a staggered stance.","Bend both knees and lower into a lunge, back heel lifted.","Swing the arm opposite the front leg forward and the other arm back, like sprinting.","Keep your torso upright and the front knee over the ankle.","Push through the front foot to rise, then repeat all reps.","Switch legs and do the same number."],"img":"opengym/3482.webp","gif":null,"ext":1},{"id":"3483","n":"around the world superman hold","bp":"upper legs","eq":"body weight","tg":"spine","mg":"glutes","sm":["glutes","hamstrings","rear deltoids","core"],"st":["Lie face down with your arms extended overhead and legs straight.","Lift your arms, chest and legs a few centimetres off the floor.","Sweep your arms out to the sides and down toward your hips in a wide arc.","Sweep them back overhead along the same path.","Keep your neck neutral and legs lifted throughout.","Lower down with control after your set."],"img":"opengym/3483.webp","gif":null,"ext":1},{"id":"3484","n":"elbow to knee sit up","bp":"waist","eq":"body weight","tg":"abs","mg":"obliques","sm":["obliques","hip flexors"],"st":["Lie on your back with knees bent and hands behind your head.","Curl up and rotate your torso, bringing one elbow toward the opposite knee.","Pause briefly at the top.","Lower your back to the floor with control.","Repeat on the other side, alternating.","Avoid pulling on your neck."],"img":"opengym/3484.webp","gif":null,"ext":1},{"id":"3485","n":"inverted row with bent knee between chairs","bp":"back","eq":"body weight","tg":"upper back","mg":"lats","sm":["lats","biceps","rhomboids","forearms"],"st":["Set a sturdy bar across two stable chairs and lie underneath it.","Grip the bar overhand, arms straight, knees bent and feet flat.","Keep your body in a straight line from shoulders to knees.","Pull your chest up toward the bar, squeezing your shoulder blades.","Lower slowly until your arms are straight again.","Make sure the chairs cannot slide."],"img":"opengym/3485.webp","gif":null,"ext":1},{"id":"3486","n":"inverted chin curl with bent knee between chairs","bp":"upper arms","eq":"body weight","tg":"biceps","mg":"forearms","sm":["forearms","lats","brachialis"],"st":["Place a sturdy bar across two stable chairs and lie underneath it.","Grip the bar underhand, arms straight, knees bent.","Keep your hips up and body in a line.","Curl yourself up by bending the elbows, keeping them close.","Lower with control until the arms are straight.","Check the chairs are stable before each set."],"img":"opengym/3486.webp","gif":null,"ext":1},{"id":"3487","n":"pull up with bent knee between chairs","bp":"back","eq":"body weight","tg":"lats","mg":"biceps","sm":["biceps","upper back","forearms","rhomboids"],"st":["Set a sturdy bar across two stable chairs, high enough to sit under.","Sit or lie beneath it and grip the bar slightly wider than your shoulders.","Keep your knees bent with feet on the floor for light help.","Pull your chest toward the bar by driving elbows down.","Lower slowly until your arms are straight.","Use your legs as little as you can."],"img":"opengym/3487.webp","gif":null,"ext":1},{"id":"3488","n":"cobra push up","bp":"chest","eq":"body weight","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders","lower back","core"],"st":["Start in a push-up position with hands under your shoulders.","Lower your chest to the floor with elbows tucked.","Press up and keep going, letting your hips sink forward.","Lift your chest and look slightly up, like a cobra.","Return to the plank by lifting your hips back.","Keep the movement smooth and controlled."],"img":"opengym/3488.webp","gif":null,"ext":1},{"id":"3489","n":"kneeling cobra push up","bp":"chest","eq":"body weight","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders","lower back","core"],"st":["Kneel on a mat and place your hands under your shoulders.","Keep a straight line from head to knees.","Lower your chest to the floor with elbows close.","Press up and let your hips sink forward, lifting your chest into a cobra.","Shift your hips back to the start.","Repeat smoothly."],"img":"opengym/3489.webp","gif":null,"ext":1},{"id":"3490","n":"decline kneeling push up on box","bp":"chest","eq":"body weight","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders","upper chest","core"],"st":["Place a sturdy box in front of you and kneel on the floor.","Put your hands on the box edge, slightly wider than your shoulders.","Form a straight line from head to knees.","Lower your chest to the box with elbows at about 45 degrees.","Press back up until your arms are straight.","Keep your hips from sagging."],"img":"opengym/3490.webp","gif":null,"ext":1},{"id":"3491","n":"decline push up against wall","bp":"chest","eq":"body weight","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders","upper chest","core"],"st":["Place your hands on the floor and walk your feet up a wall behind you.","Set your hands under your shoulders in a straight body line.","Lower your chest toward the floor with elbows tucked.","Press back up to straight arms.","Keep your core tight and your hips level.","Walk your feet down to finish."],"img":"opengym/3491.webp","gif":null,"ext":1},{"id":"3492","n":"kneeling rotational push up","bp":"chest","eq":"body weight","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders","obliques","core"],"st":["Start in a kneeling push-up position, hands under shoulders.","Lower your chest toward the floor.","Press up and rotate your torso, lifting one arm toward the ceiling.","Look at your raised hand for a moment.","Bring the hand back down and lower for the next rep.","Alternate sides each rep."],"img":"opengym/3492.webp","gif":null,"ext":1},{"id":"3493","n":"single leg low box squat","bp":"upper legs","eq":"body weight","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","core","calves"],"st":["Stand in front of a low box or bench on one leg.","Extend the other leg forward and raise your arms for balance.","Sit your hips back and lower until you lightly touch the box.","Keep your chest up and knee tracking over your toes.","Drive through the heel to stand.","Finish your reps, then switch legs."],"img":"opengym/3493.webp","gif":null,"ext":1},{"id":"3494","n":"single leg heel touch squat","bp":"upper legs","eq":"body weight","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","core","calves"],"st":["Stand on one leg with the other foot slightly off the floor.","Sit your hips back and bend the knee to squat down.","Reach down toward the heel of your standing foot.","Keep your chest as tall as you can.","Push through your foot to rise.","Complete your reps, then switch legs."],"img":"opengym/3494.webp","gif":null,"ext":1},{"id":"3495","n":"lying floor row with bent knee","bp":"back","eq":"body weight","tg":"upper back","mg":"lats","sm":["lats","biceps","rhomboids","forearms"],"st":["Lie on your back with knees bent and feet flat.","Hold a secure anchor, such as a towel around a sturdy post, with arms straight.","Pull your body toward your hands by driving the elbows back.","Squeeze your shoulder blades together.","Lower slowly to straight arms.","Keep your hips on or near the floor."],"img":"opengym/3495.webp","gif":null,"ext":1},{"id":"3496","n":"lying straight leg marches","bp":"waist","eq":"body weight","tg":"abs","mg":"lower abs","sm":["lower abs","hip flexors","core"],"st":["Lie on your back, arms by your sides.","Press your lower back gently into the floor.","Raise one straight leg toward the ceiling.","Lower it as you raise the other leg.","Keep alternating in a slow, steady march.","Keep your back from arching."],"img":"opengym/3496.webp","gif":null,"ext":1},{"id":"3497","n":"sliding floor pulldown on towel","bp":"back","eq":"body weight","tg":"lats","mg":"upper back","sm":["upper back","triceps","core","shoulders"],"st":["Kneel or lie face down with your hands on towels on a smooth floor.","Start with your arms extended overhead.","Press down and pull your arms back toward your hips, sliding the towels.","Squeeze your lats at the end.","Slide the hands back overhead with control.","Keep your core braced."],"img":"opengym/3497.webp","gif":null,"ext":1},{"id":"3498","n":"sliding floor bridge curl on towel","bp":"upper legs","eq":"body weight","tg":"hamstrings","mg":"glutes","sm":["glutes","lower back","calves"],"st":["Lie on your back with your heels on towels on a smooth floor.","Lift your hips into a bridge.","Slide your heels away until your legs are nearly straight.","Pull your heels back toward your glutes.","Keep your hips high throughout.","Lower your hips to finish the set."],"img":"opengym/3498.webp","gif":null,"ext":1},{"id":"3499","n":"self assisted inverted pullover","bp":"back","eq":"body weight","tg":"lats","mg":"upper back","sm":["upper back","triceps","core","shoulders"],"st":["Set a sturdy bar at hip height or lower and hang beneath it with an overhand grip.","Keep your feet on the floor to help as needed.","Pull your chest toward the bar and let your hips rise.","Continue to rotate your torso up and over the bar toward your hands, as your range allows.","Reverse slowly back to the start.","Use your legs only as needed."],"img":"opengym/3499.webp","gif":null,"ext":1},{"id":"3500","n":"full squat mobility","bp":"upper legs","eq":"body weight","tg":"quads","mg":"glutes","sm":["glutes","adductors","hip flexors","ankles","lower back"],"st":["Stand with feet slightly wider than your shoulders, toes turned out.","Lower into a deep squat, keeping your heels down.","Press your elbows against your inner knees with hands together.","Shift gently side to side and hold the bottom.","Keep your chest lifted.","Stand up slowly."],"img":"opengym/3500.webp","gif":null,"ext":1},{"id":"3501","n":"front plank with leg lift","bp":"waist","eq":"body weight","tg":"abs","mg":"glutes","sm":["glutes","lower back","shoulders","core"],"st":["Set up in a forearm plank with elbows under your shoulders.","Keep your body in a straight line.","Lift one leg a few inches without rotating your hips.","Lower it and lift the other leg.","Keep your core tight and your hips level.","Breathe steadily."],"img":"opengym/3501.webp","gif":null,"ext":1},{"id":"3502","n":"back forward leg swings","bp":"upper legs","eq":"body weight","tg":"hamstrings","mg":"hip flexors","sm":["hip flexors","glutes","adductors","core"],"st":["Stand tall beside a wall or support and hold it for balance.","Shift your weight onto the inside leg.","Swing the outside leg forward and back in a controlled arc.","Keep your torso upright.","Increase the range gradually.","Switch legs after your reps."],"img":"opengym/3502.webp","gif":null,"ext":1},{"id":"3503","n":"elbow to knee side plank crunch","bp":"waist","eq":"body weight","tg":"obliques","mg":"shoulders","sm":["shoulders","core","hip flexors"],"st":["Set up in a side plank on your forearm, top hand behind your head.","Lift your hips so your body is in line.","Bring your top elbow and knee together in a crunch.","Extend back to the side plank.","Keep your hips lifted throughout.","Finish your reps, then switch sides."],"img":"opengym/3503.webp","gif":null,"ext":1},{"id":"3504","n":"standing balance quadriceps stretch","bp":"upper legs","eq":"body weight","tg":"quads","mg":"hip flexors","sm":["hip flexors","ankles","core"],"st":["Stand tall, holding a wall for balance if needed.","Bend one knee and grab your ankle behind you.","Pull your heel toward your glutes with knees together.","Keep your hips tucked and your chest up.","Hold for 20-30 seconds.","Release and switch legs."],"img":"opengym/3504.webp","gif":null,"ext":1},{"id":"3505","n":"camel pose","bp":"waist","eq":"body weight","tg":"abs","mg":"hip flexors","sm":["hip flexors","chest","quadriceps","lower back"],"st":["Kneel with knees hip-width apart and hands on your lower back.","Push your hips forward and lift your chest.","Lean back and reach for your heels if comfortable.","Let your head relax back gently.","Hold for 20-30 seconds, breathing evenly.","Come up slowly, leading with your chest."],"img":"opengym/3505.webp","gif":null,"ext":1},{"id":"3506","n":"bodyweight row in doorway","bp":"back","eq":"body weight","tg":"upper back","mg":"lats","sm":["lats","biceps","rhomboids","forearms"],"st":["Stand in a doorway and grip both sides of the frame firmly.","Lean back with arms straight and feet close to the frame.","Keep your body in a straight line.","Pull your chest toward the frame, squeezing your shoulder blades.","Lower with control.","Use a sturdy frame and a non-slip grip."],"img":"opengym/3506.webp","gif":null,"ext":1},{"id":"3507","n":"self assisted inverse leg curl v. 2","bp":"upper legs","eq":"body weight","tg":"hamstrings","mg":"glutes","sm":["glutes","calves","core"],"st":["Kneel with your ankles anchored under something stable.","Keep your body straight from knees to head.","Lower your torso forward slowly, using your hamstrings to resist.","Catch yourself with your hands near the floor.","Push off lightly and use your hamstrings to return.","Keep your hips extended."],"img":"opengym/3507.webp","gif":null,"ext":1},{"id":"3508","n":"resistance band seated single leg curl","bp":"upper legs","eq":"resistance band","tg":"hamstrings","mg":"calves","sm":["calves","glutes"],"st":["Sit on the floor with a band anchored in front and looped around one foot.","Extend your leg with a slight tension on the band.","Curl your heel toward your glutes, pulling against the band.","Squeeze the hamstring briefly.","Return with control.","Complete your reps, then switch legs."],"img":"opengym/3508.webp","gif":null,"ext":1},{"id":"3509","n":"seated in out leg raise on floor","bp":"waist","eq":"body weight","tg":"abs","mg":"lower abs","sm":["lower abs","hip flexors","core"],"st":["Sit on the floor, hands behind you for support.","Lean back slightly with legs extended and lifted.","Pull your knees toward your chest.","Extend your legs back out without touching the floor.","Keep your back long and your core tight.","Breathe steadily."],"img":"opengym/3509.webp","gif":null,"ext":1},{"id":"3510","n":"crunchy frog on floor","bp":"waist","eq":"body weight","tg":"abs","mg":"lower abs","sm":["lower abs","hip flexors","obliques"],"st":["Lie on your back with arms and legs extended.","Lift your shoulders and legs slightly off the floor.","Pull your knees in while reaching your hands toward your shins.","Squeeze your abs.","Extend back out without resting on the floor.","Keep your lower back pressed down."],"img":"opengym/3510.webp","gif":null,"ext":1},{"id":"3511","n":"resistance band bird dog","bp":"waist","eq":"resistance band","tg":"spine","mg":"glutes","sm":["glutes","core","shoulders"],"st":["Start on hands and knees with a band looped under one hand and around the opposite foot.","Brace your core and keep your back flat.","Extend that arm forward and the opposite leg back against the band.","Pause, then return under control.","Do all reps, then switch sides."],"img":"opengym/3511.webp","gif":null,"ext":1},{"id":"3512","n":"resistance band upper body dead bug","bp":"waist","eq":"resistance band","tg":"abs","mg":"core","sm":["core","shoulders","obliques","lats"],"st":["Lie on your back with knees bent over your hips, holding a band in both hands above your chest.","Press your lower back into the floor.","Pull one hand overhead while stretching the band.","Bring it back and alternate.","Keep your ribs down and core braced.","Move slowly."],"img":"opengym/3512.webp","gif":null,"ext":1},{"id":"3513","n":"resistance band shoulder stretch behind the back","bp":"shoulders","eq":"resistance band","tg":"delts","mg":"chest","sm":["chest","biceps","rotator cuff"],"st":["Stand tall holding a band behind your back with both hands.","Keep your arms straight and your hands wide.","Lift your hands away from your back gently.","Keep your chest open and your ribs down.","Hold for 20-30 seconds.","Release slowly."],"img":"opengym/3513.webp","gif":null,"ext":1},{"id":"3514","n":"single leg sliding floor bridge curl on towel","bp":"upper legs","eq":"body weight","tg":"hamstrings","mg":"glutes","sm":["glutes","lower back","core"],"st":["Lie on your back with one heel on a towel on a smooth floor.","Lift the other leg straight up.","Raise your hips into a bridge.","Slide your heel away until the leg is nearly straight.","Pull the heel back toward your glutes.","Complete your reps, then switch legs."],"img":"opengym/3514.webp","gif":null,"ext":1},{"id":"3515","n":"oblique v up on floor","bp":"waist","eq":"body weight","tg":"obliques","mg":"hip flexors","sm":["hip flexors","core"],"st":["Lie on one side with legs together and an arm extended overhead.","Lift your legs and upper body at the same time.","Reach your top hand toward your feet.","Lower with control, not resting.","Keep your movement smooth.","Do your reps, then switch sides."],"img":"opengym/3515.webp","gif":null,"ext":1},{"id":"3516","n":"shoulder backbend stretch","bp":"shoulders","eq":"body weight","tg":"delts","mg":"chest","sm":["chest","upper chest","biceps","upper back"],"st":["Stand tall with your feet hip-width apart.","Clasp your hands behind your back.","Lift your arms up behind you and open your chest.","Tilt back slightly if comfortable.","Hold for 20-30 seconds.","Release slowly."],"img":"opengym/3516.webp","gif":null,"ext":1},{"id":"3517","n":"spine backbend stretch","bp":"upper legs","eq":"body weight","tg":"spine","mg":"hip flexors","sm":["hip flexors","core","glutes"],"st":["Stand tall with feet hip-width apart.","Place your hands on your lower back.","Squeeze your glutes and push your hips forward.","Lean back gently, lifting your chest.","Hold for 20-30 seconds.","Return upright slowly."],"img":"opengym/3517.webp","gif":null,"ext":1},{"id":"3518","n":"band seated leg extension","bp":"upper legs","eq":"band","tg":"quads","mg":"hip flexors","sm":["hip flexors","core"],"st":["Sit on a chair with a band anchored behind and looped around one ankle.","Start with your knee bent to 90 degrees.","Extend your leg until it is straight.","Squeeze the quad at the top.","Lower with control.","Complete your reps, then switch legs."],"img":"opengym/3518.webp","gif":null,"ext":1},{"id":"3522","n":"kettlebell single leg glute bridge pullover","bp":"upper legs","eq":"kettlebell","tg":"glutes","mg":"hamstrings","sm":["hamstrings","lats","core","chest"],"st":["Lie on your back with one foot flat, other leg raised.","Hold a kettlebell by the horns above your chest.","Lift your hips into a bridge.","Lower the kettlebell back overhead in an arc.","Bring it back up as you hold the bridge.","Lower your hips, then switch legs."],"img":"opengym/3522.webp","gif":null,"ext":1},{"id":"3524","n":"band horizontal pallof press with resistance band squat","bp":"upper legs","eq":"resistance band","tg":"quads","mg":"glutes","sm":["glutes","core","obliques","shoulders"],"st":["Anchor a band at chest height and stand side-on, holding it at your chest.","Squat down, keeping your torso tall.","Stand and press the band straight out in front.","Resist the band trying to rotate you.","Bring your hands back to your chest.","Finish your reps, then switch sides."],"img":"opengym/3524.webp","gif":null,"ext":1},{"id":"3525","n":"landmine kneeling one arm shoulder press","bp":"shoulders","eq":"landmine","tg":"delts","mg":"triceps","sm":["triceps","upper chest","core"],"st":["Kneel facing the end of a landmine barbell.","Hold the end at shoulder height with one hand.","Keep your core tight and torso upright.","Press the end up and forward until your arm is straight.","Lower with control.","Complete your reps, then switch arms."],"img":"opengym/3525.webp","gif":null,"ext":1},{"id":"3526","n":"kneeling t spine mobility","bp":"back","eq":"body weight","tg":"spine","mg":"obliques","sm":["obliques","upper back","shoulders"],"st":["Kneel on all fours.","Place one hand behind your head.","Rotate your elbow toward the opposite arm.","Open up and rotate toward the ceiling.","Follow your elbow with your eyes.","Do your reps, then switch sides."],"img":"opengym/3526.webp","gif":null,"ext":1},{"id":"3527","n":"downward facing dog toe touch","bp":"full body","eq":"body weight","tg":"hamstrings","mg":"calves","sm":["calves","shoulders","core"],"st":["Start in a downward facing dog, hips high.","Press your chest toward your thighs.","Reach one hand back to touch the opposite foot.","Return the hand and switch sides.","Keep your hips high.","Move slowly with steady breathing."],"img":"opengym/3527.webp","gif":null,"ext":1},{"id":"3528","n":"downward facing dog spine mobility","bp":"back","eq":"body weight","tg":"spine","mg":"hamstrings","sm":["hamstrings","shoulders","core"],"st":["Start in a downward facing dog.","Bend one knee, then the other, pedaling gently.","Shift your hips side to side.","Let your spine twist a little.","Keep your hands pressed into the floor.","Breathe slowly."],"img":"opengym/3528.webp","gif":null,"ext":1},{"id":"3529","n":"landmine stand up high knee","bp":"full body","eq":"landmine","tg":"quads","mg":"glutes","sm":["glutes","core","shoulders","hip flexors"],"st":["Hold the end of a landmine barbell at your chest.","Stand from a squat, driving through your legs.","Raise one knee high as you stand.","Lower the foot and squat again.","Keep the barbell close to your chest.","Alternate legs each rep."],"img":"opengym/3529.webp","gif":null,"ext":1},{"id":"3530","n":"barbell banded squat","bp":"upper legs","eq":"barbell","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","core","lower back"],"st":["Set the bands on the rack and barbell.","Rest the bar on your upper back.","Stand with feet shoulder-width apart.","Squat down with your chest up.","Drive up through your heels.","Brace your core throughout."],"img":"opengym/3530.webp","gif":null,"ext":1},{"id":"3531","n":"alternate punching","bp":"cardio","eq":"body weight","tg":"cardiovascular system","mg":"shoulders","sm":["shoulders","triceps","core","obliques"],"st":["Stand with a staggered stance and fists up.","Punch forward with one arm, rotating your torso slightly.","Pull it back as you punch with the other.","Keep your core tight.","Keep a steady rhythm for 30-60 seconds.","Rest briefly and repeat."],"img":"opengym/3531.webp","gif":null,"ext":1},{"id":"3532","n":"boxer shuffle","bp":"cardio","eq":"body weight","tg":"cardiovascular system","mg":"calves","sm":["calves","quadriceps","core","shoulders"],"st":["Stand with feet shoulder-width apart, knees soft.","Shift your weight from foot to foot.","Stay on the balls of your feet.","Keep your hands up like a guard.","Keep it light and quick for 30-60 seconds.","Rest briefly and repeat."],"img":"opengym/3532.webp","gif":null,"ext":1},{"id":"3534","n":"bodyweight standing pulse calf raise","bp":"lower legs","eq":"body weight","tg":"calves","mg":"soleus","sm":["soleus","ankles","feet"],"st":["Stand with feet hip-width apart, holding a support for balance.","Rise up onto the balls of your feet.","Pulse up and down in small movements.","Keep your knees straight.","Lower fully when you finish.","Keep the movement controlled."],"img":"opengym/3534.webp","gif":null,"ext":1},{"id":"3535","n":"bodyweight pulse squat","bp":"upper legs","eq":"body weight","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","calves"],"st":["Stand with feet shoulder-width apart.","Squat down until thighs are parallel.","Pulse up and down a few centimetres.","Keep your chest up and knees tracking over your toes.","Keep your weight on your heels.","Stand up fully to finish."],"img":"opengym/3535.webp","gif":null,"ext":1},{"id":"3536","n":"elevated inverted row between 3 chairs","bp":"back","eq":"body weight","tg":"upper back","mg":"lats","sm":["lats","biceps","rhomboids","forearms"],"st":["Set a bar across two stable chairs and place a third chair at your feet.","Lie under the bar and grip it overhand.","Put your heels on the third chair.","Pull your chest to the bar.","Lower slowly to straight arms.","Keep your body in a straight line."],"img":"opengym/3536.webp","gif":null,"ext":1},{"id":"3537","n":"elevated inverted underhand grip row between 3 chairs","bp":"back","eq":"body weight","tg":"upper back","mg":"lats","sm":["lats","biceps","rhomboids","forearms"],"st":["Set a bar across two stable chairs and a third chair at your feet.","Lie under the bar and grip it underhand.","Place your heels on the third chair.","Pull your chest to the bar with elbows close.","Lower slowly to straight arms.","Keep your body straight."],"img":"opengym/3537.webp","gif":null,"ext":1},{"id":"3538","n":"inverted underhand grip row between chairs","bp":"back","eq":"body weight","tg":"upper back","mg":"lats","sm":["lats","biceps","rhomboids","forearms"],"st":["Set a bar across two stable chairs.","Lie under it and grip underhand.","Keep your legs straight with heels on the floor.","Pull your chest to the bar.","Lower slowly.","Keep your body in a line."],"img":"opengym/3538.webp","gif":null,"ext":1},{"id":"3539","n":"lying t spine mobility stretching","bp":"back","eq":"body weight","tg":"spine","mg":"obliques","sm":["obliques","upper back","chest"],"st":["Lie on your side with knees bent and arms in front.","Lift your top arm and open it toward the other side.","Follow your hand with your eyes.","Hold for 20-30 seconds.","Return to the start.","Switch sides."],"img":"opengym/3539.webp","gif":null,"ext":1},{"id":"3540","n":"kneeling t spine mobility stretching","bp":"back","eq":"body weight","tg":"spine","mg":"obliques","sm":["obliques","upper back","shoulders"],"st":["Kneel on all fours.","Place one hand behind your head.","Rotate your elbow up toward the ceiling.","Hold for 20-30 seconds.","Return to start.","Switch sides."],"img":"opengym/3540.webp","gif":null,"ext":1},{"id":"3550","n":"seated pull up between chairs","bp":"back","eq":"body weight","tg":"lats","mg":"biceps","sm":["biceps","upper back","forearms","rhomboids"],"st":["Set a bar across two sturdy chairs.","Sit on the floor beneath it and grip the bar.","Keep your legs bent for light help.","Pull your chest toward the bar.","Lower with control.","Use your legs as little as possible."],"img":"opengym/3550.webp","gif":null,"ext":1},{"id":"3551","n":"side shuttle","bp":"cardio","eq":"body weight","tg":"cardiovascular system","mg":"quadriceps","sm":["quadriceps","glutes","calves","adductors"],"st":["Stand with knees bent in an athletic stance.","Shuffle to one side in quick steps.","Touch the floor or change direction.","Shuffle back the other way.","Keep your chest up.","Keep up the pace for 30-60 seconds."],"img":"opengym/3551.webp","gif":null,"ext":1},{"id":"3553","n":"rotational push up","bp":"chest","eq":"body weight","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders","obliques","core"],"st":["Start in a push-up position.","Lower your chest to the floor.","Press up and rotate, reaching one arm toward the ceiling.","Return the hand to the floor.","Lower again for the next rep.","Alternate sides."],"img":"opengym/3553.webp","gif":null,"ext":1},{"id":"3554","n":"bottle hammer curl","bp":"upper arms","eq":"weighted","tg":"biceps","mg":"brachialis","sm":["brachialis","forearms","grip muscles"],"st":["Hold a filled bottle in each hand with palms facing each other.","Keep your elbows by your sides.","Curl the bottles toward your shoulders.","Squeeze at the top.","Lower with control.","Avoid swinging."],"img":"opengym/3554.webp","gif":null,"ext":1},{"id":"3555","n":"power push aways","bp":"back","eq":"body weight","tg":"upper back","mg":"rhomboids","sm":["rhomboids","trapezius","shoulders","core"],"st":["Stand facing a wall and lean in with arms extended.","Push away from the wall forcefully.","Retract your shoulder blades as you reach back.","Return to the wall with control.","Keep your core tight.","Reset between reps."],"img":"opengym/3555.webp","gif":null,"ext":1},{"id":"3556","n":"high knee run","bp":"cardio","eq":"body weight","tg":"cardiovascular system","mg":"quadriceps","sm":["quadriceps","hip flexors","calves","core"],"st":["Stand tall with feet hip-width apart.","Run in place, driving your knees up toward waist height.","Pump your arms in rhythm.","Land softly on the balls of your feet.","Keep your chest tall.","Continue for 30-60 seconds."],"img":"opengym/3556.webp","gif":null,"ext":1},{"id":"3557","n":"kneeling wide hand push up","bp":"chest","eq":"body weight","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders","upper chest","core"],"st":["Kneel on a mat and place your hands wider than your shoulders.","Keep a straight line from head to knees.","Lower your chest toward the floor.","Press back up to straight arms.","Keep your core tight.","Do not let your hips sag."],"img":"opengym/3557.webp","gif":null,"ext":1},{"id":"3558","n":"lying biceps curl with towel","bp":"upper arms","eq":"body weight","tg":"biceps","mg":"brachialis","sm":["brachialis","forearms"],"st":["Lie on your back and hold a towel in both hands, arms extended.","Pull the towel taut and curl your hands toward your shoulders.","Keep your upper arms still and your elbows close to your sides.","Squeeze at the top, then lower slowly to the start.","Repeat for the planned reps."],"img":"opengym/3558.webp","gif":null,"ext":1},{"id":"3559","n":"superman row with towel","bp":"back","eq":"body weight","tg":"upper back","mg":"rear deltoids","sm":["rear deltoids","lower back","rhomboids"],"st":["Lie face down with arms extended overhead, holding a towel taut.","Lift your chest and arms slightly off the floor.","Pull the towel down toward your upper chest, squeezing your shoulder blades.","Extend your arms forward again with control.","Keep your neck neutral and repeat."],"img":"opengym/3559.webp","gif":null,"ext":1},{"id":"3564","n":"seated shoulder flexor depressor retractor stretch (bent knee)","bp":"shoulders","eq":"body weight","tg":"delts","mg":"chest","sm":["chest","upper back","lats"],"st":["Sit on the floor with one knee bent and the other leg comfortable.","Place your hands behind you on the floor, fingers pointing away.","Slowly slide your hips forward while keeping your chest tall.","Feel the stretch in the front of your shoulders.","Hold for 20-30 seconds while breathing steadily.","Release slowly and repeat on the other side if needed."],"img":"opengym/3564.webp","gif":null,"ext":1},{"id":"3565","n":"bridge pose yoga stretch","bp":"back","eq":"body weight","tg":"glutes","mg":"lower back","sm":["lower back","hamstrings","chest"],"st":["Lie on your back with knees bent and feet flat near your hips.","Place your hands beside your head, palms down, fingers toward your shoulders.","Press through hands and feet to lift your hips and chest.","Straighten your arms as far as is comfortable and relax your neck.","Hold for 15-30 seconds, then lower slowly."],"img":"opengym/3565.webp","gif":null,"ext":1},{"id":"3566","n":"roll upper back","bp":"back","eq":"roller","tg":"upper back","mg":"trapezius","sm":["trapezius","rhomboids","lats"],"st":["Sit with a foam roller behind your upper back and lie back onto it.","Cross your arms over your chest and lift your hips.","Roll slowly between your shoulder blades and mid back.","Pause on tender spots for a few breaths.","Avoid rolling your lower back and continue for about a minute."],"img":"opengym/3566.webp","gif":null,"ext":1},{"id":"3567","n":"roll recumbent hip external rotator and hip extensor stretch (crossed leg)","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"hip flexors","sm":["hip flexors","lower back"],"st":["Lie on your back with both knees bent and feet flat.","Cross one ankle over the opposite knee.","Pull the bottom thigh toward your chest with both hands.","Keep your head and shoulders relaxed on the floor.","Hold for 20-30 seconds while breathing steadily.","Release slowly and repeat on the other side if needed."],"img":"opengym/3567.webp","gif":null,"ext":1},{"id":"3568","n":"roll ball piriformis release","bp":"upper legs","eq":"massage ball","tg":"glutes","mg":"hip flexors","sm":["hip flexors","hamstrings"],"st":["Sit on the floor and place a ball under one buttock.","Cross that ankle over the opposite knee for more access.","Shift your weight to find a tender spot and stay there.","Breathe slowly for 20-30 seconds, then roll gently.","Switch sides."],"img":"opengym/3568.webp","gif":null,"ext":1},{"id":"3569","n":"roll ball pectoral release","bp":"chest","eq":"massage ball","tg":"pectorals","mg":"shoulders","sm":["shoulders","upper chest"],"st":["Place a ball between your chest and a wall, just below the collarbone.","Lean in until you feel pressure on the chest muscle.","Roll slowly in small circles or up and down.","Hold on tender spots for a few breaths.","Switch sides after about 30-60 seconds."],"img":"opengym/3569.webp","gif":null,"ext":1},{"id":"3570","n":"roll ball upper trapezius release","bp":"back","eq":"massage ball","tg":"traps","mg":"upper back","sm":["upper back","shoulders"],"st":["Stand with your back to a wall and place a ball on top of one shoulder.","Lean into the wall to press the ball into the muscle.","Move slowly by bending your knees.","Pause on tender spots and breathe.","Switch to the other shoulder."],"img":"opengym/3570.webp","gif":null,"ext":1},{"id":"3571","n":"kettlebell full swing","bp":"upper legs","eq":"kettlebell","tg":"glutes","mg":"hamstrings","sm":["hamstrings","lower back","core","shoulders"],"st":["Stand with feet shoulder width apart, kettlebell on the floor in front.","Hinge at the hips and grip the handle with both hands.","Hike the bell back, then drive your hips forward to swing it overhead.","Let it fall back between your legs while hinging again.","Keep your back flat and repeat in a smooth rhythm."],"img":"opengym/3571.webp","gif":null,"ext":1},{"id":"3572","n":"kettlebell strict press","bp":"shoulders","eq":"kettlebell","tg":"delts","mg":"triceps","sm":["triceps","upper chest","core"],"st":["Hold the kettlebell at shoulder height in the rack position.","Stand tall with glutes and abs tight.","Press the bell straight overhead until your arm is locked out.","Lower it back to the shoulder under control.","Finish your reps, then switch arms."],"img":"opengym/3572.webp","gif":null,"ext":1},{"id":"3573","n":"kettlebell sots press","bp":"shoulders","eq":"kettlebell","tg":"delts","mg":"quadriceps","sm":["quadriceps","glutes","triceps","core"],"st":["Hold kettlebells in the rack position and sink into a deep squat.","Keep your chest up and heels flat.","Press the bells overhead while staying in the squat.","Lower them back to the shoulders with control.","Stand up and repeat once the set is done."],"img":"opengym/3573.webp","gif":null,"ext":1},{"id":"3574","n":"kettlebell forward lunge","bp":"upper legs","eq":"kettlebell","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","core"],"st":["Hold a kettlebell at your chest or by your side.","Step forward with one leg into a long stride.","Lower until both knees are bent about 90 degrees.","Push through the front foot to return to standing.","Alternate legs for the set."],"img":"opengym/3574.webp","gif":null,"ext":1},{"id":"3575","n":"kettlebell backward lunge","bp":"upper legs","eq":"kettlebell","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","core"],"st":["Hold a kettlebell at your chest or by your side.","Step one leg back and lower your back knee toward the floor.","Keep your front shin vertical and torso tall.","Push through the front heel to stand.","Alternate legs for the set."],"img":"opengym/3575.webp","gif":null,"ext":1},{"id":"3576","n":"kettlebell farmers carry","bp":"full body","eq":"kettlebell","tg":"forearms","mg":"grip muscles","sm":["grip muscles","trapezius","core","glutes"],"st":["Stand between two kettlebells and pick them up with a flat back.","Stand tall with shoulders back and arms straight.","Walk with short, controlled steps.","Keep your core braced and avoid leaning.","Set the weights down carefully after the distance."],"img":"opengym/3576.webp","gif":null,"ext":1},{"id":"3577","n":"kettlebell lunge clean and press","bp":"full body","eq":"kettlebell","tg":"glutes","mg":"quadriceps","sm":["quadriceps","shoulders","triceps","core"],"st":["Start standing with a kettlebell hanging in one hand.","Step back into a lunge while cleaning the bell to your shoulder.","Rise from the lunge and press the bell overhead.","Lower the bell to the shoulder, then to your side.","Alternate legs and switch hands after the set."],"img":"opengym/3577.webp","gif":null,"ext":1},{"id":"3578","n":"kettlebell slingshot","bp":"shoulders","eq":"kettlebell","tg":"delts","mg":"core","sm":["core","forearms","upper back"],"st":["Stand with feet shoulder width apart and hold the kettlebell in one hand.","Pass it behind your back to the other hand.","Bring it around your waist to the front.","Keep your hips square and core tight.","Repeat in the same direction, then reverse."],"img":"opengym/3578.webp","gif":null,"ext":1},{"id":"3579","n":"kettlebell deck squat","bp":"full body","eq":"kettlebell","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","core","hip flexors"],"st":["Hold a kettlebell at your chest and squat down.","Sit back and roll onto your back, keeping the bell close.","Use momentum to roll forward onto your feet.","Stand up out of the squat.","Keep a tight grip and repeat smoothly."],"img":"opengym/3579.webp","gif":null,"ext":1},{"id":"3580","n":"kettlebell deep push up","bp":"chest","eq":"kettlebell","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders","core"],"st":["Place two kettlebells shoulder width apart and grip the handles.","Set up in a straight plank position.","Lower your chest below your hands with elbows at about 45 degrees.","Press back up to straight arms.","Keep your body in a straight line."],"img":"opengym/3580.webp","gif":null,"ext":1},{"id":"3581","n":"lunge with leg lift","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","core","hip flexors"],"st":["Stand tall and step one leg forward into a lunge.","Lower until both knees reach about 90 degrees.","Press up and lift the rear leg behind or beside you.","Hold briefly with your core tight.","Lower and repeat, then switch sides."],"img":"opengym/3581.webp","gif":null,"ext":1},{"id":"3583","n":"single leg bridge with hip flexion","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"hamstrings","sm":["hamstrings","core","hip flexors"],"st":["Lie on your back with knees bent and feet flat.","Lift one knee toward your chest.","Press through the other foot to raise your hips.","Keep your hips level and avoid arching.","Lower slowly and switch sides after the set."],"img":"opengym/3583.webp","gif":null,"ext":1},{"id":"3584","n":"side bridge with arm leg swing","bp":"waist","eq":"body weight","tg":"obliques","mg":"abdominals","sm":["abdominals","glutes","shoulders","hip flexors"],"st":["Lie on one side and prop yourself on your forearm.","Lift your hips into a straight line.","Raise the top leg and arm.","Swing them toward each other under control.","Keep your hips high, then switch sides."],"img":"opengym/3584.webp","gif":null,"ext":1},{"id":"3585","n":"single leg deadlift with knee lift","bp":"upper legs","eq":"body weight","tg":"hamstrings","mg":"glutes","sm":["glutes","lower back","core","hip flexors"],"st":["Stand on one leg with a slight knee bend.","Hinge forward as the other leg extends behind you.","Return to upright by squeezing the glute.","Drive the free knee up toward your chest.","Finish the reps, then switch legs."],"img":"opengym/3585.webp","gif":null,"ext":1},{"id":"3586","n":"scissors (advanced)","bp":"waist","eq":"body weight","tg":"abs","mg":"lower abs","sm":["lower abs","hip flexors","obliques"],"st":["Lie on your back with legs extended and hands under your hips.","Lift your head, shoulders and legs slightly off the floor.","Cross one leg over the other in a scissor motion.","Alternate sides in a controlled rhythm.","Keep your lower back pressed down."],"img":"opengym/3586.webp","gif":null,"ext":1},{"id":"3587","n":"weighted single leg lift","bp":"upper legs","eq":"weighted","tg":"glutes","mg":"hamstrings","sm":["hamstrings","core","lower back"],"st":["Wear ankle weights and get on hands and knees or lie face down.","Brace your core and keep your hips level.","Raise the weighted leg without swinging.","Pause at the top and squeeze.","Lower slowly and switch legs."],"img":"opengym/3587.webp","gif":null,"ext":1},{"id":"3588","n":"quickly swing arms in place","bp":"shoulders","eq":"body weight","tg":"delts","mg":"chest","sm":["chest","upper back","core"],"st":["Stand with feet hip width apart and knees soft.","Swing both arms across your chest and open wide.","Keep your torso upright and relaxed.","Increase speed gradually.","Continue for 30-60 seconds."],"img":"opengym/3588.webp","gif":null,"ext":1},{"id":"3589","n":"quickly trot in place","bp":"cardio","eq":"body weight","tg":"cardiovascular system","mg":"calves","sm":["calves","quadriceps","hip flexors"],"st":["Stand tall with arms bent at your sides.","Lift your knees and run lightly on the spot.","Land softly on the balls of your feet.","Pump your arms with each step.","Keep the pace for 30-60 seconds or longer."],"img":"opengym/3589.webp","gif":null,"ext":1},{"id":"3590","n":"alternate lying floor leg raise","bp":"waist","eq":"body weight","tg":"abs","mg":"lower abs","sm":["lower abs","hip flexors"],"st":["Lie on your back with legs straight and arms at your sides.","Press your lower back into the floor.","Raise one leg to about 90 degrees.","Lower it slowly and lift the other leg.","Alternate without arching your back."],"img":"opengym/3590.webp","gif":null,"ext":1},{"id":"3591","n":"band twist","bp":"waist","eq":"band","tg":"obliques","mg":"shoulders","sm":["shoulders","core"],"st":["Anchor a band at chest height and hold the handle with both hands.","Stand sideways with arms extended.","Rotate your torso away from the anchor.","Return under control.","Finish reps, then switch sides."],"img":"opengym/3591.webp","gif":null,"ext":1},{"id":"3606","n":"leg extension crunch (with stability ball)","bp":"waist","eq":"stability ball","tg":"abs","mg":"lower abs","sm":["lower abs","hip flexors","quadriceps"],"st":["Sit on a stability ball and walk your feet out until your back is supported.","Place your hands lightly behind your head.","Crunch up as you extend one leg.","Lower slowly and bend the knee.","Alternate legs for the set."],"img":"opengym/3606.webp","gif":null,"ext":1},{"id":"3616","n":"sled 45 degrees narrow stance leg press","bp":"upper legs","eq":"sled machine","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","adductors","calves"],"st":["Sit in the sled with your back flat on the pad and feet close together on the platform.","Release the safety handles.","Lower the sled until your knees are bent to about 90 degrees.","Press through your feet to extend your legs without locking your knees.","Keep your hips on the seat."],"img":"opengym/3616.webp","gif":null,"ext":1},{"id":"3617","n":"sled 45 degrees wide stance leg press","bp":"upper legs","eq":"sled machine","tg":"quads","mg":"glutes","sm":["glutes","adductors","hamstrings","calves"],"st":["Sit in the sled with your back flat on the pad and feet wide on the platform, toes slightly out.","Release the safety handles.","Lower the sled with your knees tracking over your toes.","Press back up without locking your knees.","Keep your hips on the seat."],"img":"opengym/3617.webp","gif":null,"ext":1},{"id":"3621","n":"twisting crunch (straight arms)","bp":"waist","eq":"body weight","tg":"obliques","mg":"abdominals","sm":["abdominals","hip flexors"],"st":["Lie on your back with knees bent and arms straight up.","Lift your shoulders off the floor.","Twist to reach one side.","Return to center and twist the other way.","Keep your lower back on the floor."],"img":"opengym/3621.webp","gif":null,"ext":1},{"id":"3622","n":"v up","bp":"waist","eq":"body weight","tg":"abs","mg":"lower abs","sm":["lower abs","hip flexors","quadriceps"],"st":["Lie flat with arms extended overhead.","Raise legs and torso at the same time.","Reach your hands toward your toes.","Lower with control without touching the floor.","Keep your legs as straight as you can."],"img":"opengym/3622.webp","gif":null,"ext":1},{"id":"3623","n":"vertical leg raise (on parallel bars) v. 3","bp":"waist","eq":"body weight","tg":"abs","mg":"hip flexors","sm":["hip flexors","lower abs","forearms"],"st":["Support yourself on parallel bars with straight arms and shoulders down.","Let your legs hang together.","Raise your legs in front of you until they are about parallel to the floor or higher.","Lower slowly without swinging.","Keep your torso still."],"img":"opengym/3623.webp","gif":null,"ext":1},{"id":"3630","n":"standing hamstrings and back stretch","bp":"upper legs","eq":"body weight","tg":"hamstrings","mg":"lower back","sm":["lower back","calves","glutes"],"st":["Stand tall with feet hip width apart.","Hinge forward at the hips with a long spine.","Let your arms hang toward the floor.","Keep your knees soft.","Hold for 20-30 seconds while breathing steadily.","Release slowly and repeat on the other side if needed."],"img":"opengym/3630.webp","gif":null,"ext":1},{"id":"3631","n":"sitting sumo mobility stretch","bp":"upper legs","eq":"body weight","tg":"adductors","mg":"groin","sm":["groin","hamstrings","lower back"],"st":["Sit on the floor with legs spread wide.","Keep your back straight and toes pointing up.","Lean forward from the hips.","Place your hands on the floor in front of you.","Stay for 20-30 seconds, then return slowly."],"img":"opengym/3631.webp","gif":null,"ext":1},{"id":"3632","n":"sitting sumo right twist stretch","bp":"upper legs","eq":"body weight","tg":"adductors","mg":"obliques","sm":["obliques","hamstrings","lower back"],"st":["Sit with legs spread wide and back tall.","Rotate your torso to the right.","Reach both hands toward your right foot.","Keep your hips grounded.","Hold for 20-30 seconds while breathing steadily.","Release slowly and repeat on the other side if needed."],"img":"opengym/3632.webp","gif":null,"ext":1},{"id":"3633","n":"sitting sumo left twist stretch","bp":"upper legs","eq":"body weight","tg":"adductors","mg":"obliques","sm":["obliques","hamstrings","lower back"],"st":["Sit with legs spread wide and back tall.","Rotate your torso to the left.","Reach both hands toward your left foot.","Keep your hips grounded.","Hold for 20-30 seconds while breathing steadily.","Release slowly and repeat on the other side if needed."],"img":"opengym/3633.webp","gif":null,"ext":1},{"id":"3634","n":"sitting sumo with arms up mobility stretch","bp":"upper legs","eq":"body weight","tg":"adductors","mg":"shoulders","sm":["shoulders","groin","lower back"],"st":["Sit with legs spread wide and back straight.","Raise both arms overhead.","Lean forward slowly from the hips.","Keep your arms extended and your chest open.","Hold for 20-30 seconds, then sit tall."],"img":"opengym/3634.webp","gif":null,"ext":1},{"id":"3651","n":"dumbbell rdl death march","bp":"upper legs","eq":"dumbbell","tg":"hamstrings","mg":"glutes","sm":["glutes","lower back","core"],"st":["Hold dumbbells at your sides and stand tall.","Hinge at the hips on one leg as you step forward.","Keep your back flat and raise the rear leg.","Stand tall and step into the next rep.","Alternate legs as you move forward."],"img":"opengym/3651.webp","gif":null,"ext":1},{"id":"3652","n":"trap bar split stance rdl","bp":"upper legs","eq":"trap bar","tg":"hamstrings","mg":"glutes","sm":["glutes","lower back","core"],"st":["Stand inside a trap bar with one foot slightly behind.","Hinge at the hips with a flat back.","Lower the bar along your legs.","Drive your hips forward to stand.","Finish reps, then switch the stance."],"img":"opengym/3652.webp","gif":null,"ext":1},{"id":"3653","n":"band assisted sprinter run","bp":"cardio","eq":"band","tg":"cardiovascular system","mg":"quadriceps","sm":["quadriceps","hamstrings","calves","glutes"],"st":["Anchor a band behind you and loop it around your waist.","Lean forward into a sprint position.","Drive your knees and pump your arms.","Stay light on your feet.","Repeat for short bursts."],"img":"opengym/3653.webp","gif":null,"ext":1},{"id":"3654","n":"barbell lying row on rack","bp":"back","eq":"barbell","tg":"upper back","mg":"lats","sm":["lats","biceps","rear deltoids"],"st":["Set a barbell on a rack at a height you can reach lying down.","Lie under it and grip the bar overhand.","Pull your chest toward the bar.","Squeeze your shoulder blades.","Lower slowly to full extension."],"img":"opengym/3654.webp","gif":null,"ext":1},{"id":"3657","n":"static position lying back with pad","bp":"back","eq":"body weight","tg":"spine","mg":"core","sm":["core"],"st":["Place a pad on the floor or bench.","Lie on your back with your head supported.","Keep your spine neutral.","Relax your arms at your sides.","Hold the position and breathe."],"img":"opengym/3657.webp","gif":null,"ext":1},{"id":"3658","n":"static position seated back with pad","bp":"back","eq":"body weight","tg":"spine","mg":"core","sm":["core"],"st":["Sit on the seat with your back against the pad.","Keep your feet flat on the floor.","Press your back gently into the pad.","Keep your shoulders relaxed.","Hold the position and breathe."],"img":"opengym/3658.webp","gif":null,"ext":1},{"id":"3659","n":"static position standing","bp":"full body","eq":"body weight","tg":"spine","mg":"core","sm":["core","glutes"],"st":["Stand with feet hip width apart.","Keep your knees soft.","Stack ribs over hips and shoulders back.","Let your arms hang.","Hold and breathe steadily."],"img":"opengym/3659.webp","gif":null,"ext":1},{"id":"3660","n":"static position lying front","bp":"back","eq":"body weight","tg":"spine","mg":"glutes","sm":["glutes","core"],"st":["Lie face down on a mat.","Extend your legs and rest your forehead down.","Keep your arms alongside your body.","Keep your hips relaxed.","Hold and breathe."],"img":"opengym/3660.webp","gif":null,"ext":1},{"id":"3661","n":"static position seated back","bp":"back","eq":"body weight","tg":"spine","mg":"core","sm":["core"],"st":["Sit tall with feet flat on the floor.","Keep your back straight.","Place your hands on your thighs.","Relax your shoulders.","Hold and breathe."],"img":"opengym/3661.webp","gif":null,"ext":1},{"id":"3668","n":"dumbbell lying on floor chest press","bp":"chest","eq":"dumbbell","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders","upper chest"],"st":["Lie on the floor holding dumbbells above your chest.","Lower them until your upper arms touch the floor.","Pause briefly.","Press back up to straight arms.","Keep your wrists straight."],"img":"opengym/3668.webp","gif":null,"ext":1},{"id":"3673","n":"standing pose (form check) front view","bp":"full body","eq":"body weight","tg":"spine","mg":"core","sm":["core","glutes"],"st":["Stand with feet hip width apart.","Keep your knees soft and hips level.","Stack your shoulders over your hips.","Look straight ahead.","Compare yourself to the correct posture."],"img":"opengym/3673.webp","gif":null,"ext":1},{"id":"3674","n":"standing pose (form check) side view","bp":"full body","eq":"body weight","tg":"spine","mg":"core","sm":["core","glutes"],"st":["Stand with feet hip width apart.","Keep your ears over your shoulders and hips.","Keep a natural curve in your lower back.","Relax your arms.","Compare yourself to the correct posture."],"img":"opengym/3674.webp","gif":null,"ext":1},{"id":"3675","n":"side to side jump rope","bp":"full body","eq":"rope","tg":"cardiovascular system","mg":"calves","sm":["calves","shoulders","quadriceps"],"st":["Hold the rope handles and stand tall.","Swing the rope overhead.","Hop side to side over the rope.","Land softly on the balls of your feet.","Keep a steady rhythm."],"img":"opengym/3675.webp","gif":null,"ext":1},{"id":"3676","n":"skip jump rope","bp":"full body","eq":"rope","tg":"cardiovascular system","mg":"calves","sm":["calves","quadriceps","shoulders"],"st":["Hold the rope handles and swing the rope overhead.","Skip over the rope, alternating feet.","Land softly on the balls of your feet.","Keep your elbows near your sides.","Continue at a steady pace."],"img":"opengym/3676.webp","gif":null,"ext":1},{"id":"3677","n":"high knee jump rope","bp":"full body","eq":"rope","tg":"cardiovascular system","mg":"hip flexors","sm":["hip flexors","calves","quadriceps"],"st":["Hold the rope handles and swing the rope overhead.","Run over the rope.","Lift your knees to hip height.","Stay on the balls of your feet.","Keep your torso upright."],"img":"opengym/3677.webp","gif":null,"ext":1},{"id":"3678","n":"high jump rope","bp":"full body","eq":"rope","tg":"cardiovascular system","mg":"calves","sm":["calves","quadriceps","shoulders"],"st":["Hold the rope handles and stand tall.","Swing the rope overhead.","Jump higher than usual.","Land softly with bent knees.","Keep your rhythm."],"img":"opengym/3678.webp","gif":null,"ext":1},{"id":"3680","n":"kettlebell overhand grip swing","bp":"upper legs","eq":"kettlebell","tg":"glutes","mg":"hamstrings","sm":["hamstrings","lower back","core","shoulders","grip muscles"],"st":["Stand with feet shoulder-width apart and a kettlebell on the floor in front of you.","Hinge at the hips and grip the handle with an overhand grip.","Hike the bell back between your legs.","Snap your hips forward and swing it to chest height.","Let it fall back and hinge again, keeping your back flat."],"img":"opengym/3680.webp","gif":null,"ext":1},{"id":"3681","n":"dumbbell squeeze bench press","bp":"chest","eq":"dumbbell","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders","upper chest"],"st":["Lie on a bench holding dumbbells pressed together above your chest.","Squeeze them together throughout.","Lower them to your chest.","Press back up.","Keep your feet planted."],"img":"opengym/3681.webp","gif":null,"ext":1},{"id":"3682","n":"dumbbell incline alternate bicep curl","bp":"upper arms","eq":"dumbbell","tg":"biceps","mg":"brachialis","sm":["brachialis","forearms"],"st":["Sit back on an incline bench with dumbbells hanging down.","Curl one dumbbell up with the palm facing up.","Lower it slowly.","Curl the other arm.","Keep your upper arms still."],"img":"opengym/3682.webp","gif":null,"ext":1},{"id":"3683","n":"dumbbell goblet curtsey lunge","bp":"upper legs","eq":"dumbbell","tg":"glutes","mg":"quadriceps","sm":["quadriceps","adductors","core"],"st":["Hold a dumbbell at your chest.","Step one leg behind and across the other.","Lower until both knees bend.","Press through the front leg to return.","Alternate legs for the set."],"img":"opengym/3683.webp","gif":null,"ext":1},{"id":"3684","n":"dumbbell external rotation","bp":"shoulders","eq":"dumbbell","tg":"delts","mg":"rotator cuff","sm":["rotator cuff","rear deltoids","upper back"],"st":["Lie on your side with a dumbbell in the top hand and elbow bent.","Keep your elbow tucked at your side.","Rotate your forearm upward.","Lower slowly.","Switch sides after the set."],"img":"opengym/3684.webp","gif":null,"ext":1},{"id":"3685","n":"dumbbell chest supported lateral raises","bp":"shoulders","eq":"dumbbell","tg":"delts","mg":"trapezius","sm":["trapezius","upper back"],"st":["Lie chest-down on an incline bench holding dumbbells.","Raise your arms out to the sides.","Stop at shoulder height.","Lower slowly.","Keep your neck neutral."],"img":"opengym/3685.webp","gif":null,"ext":1},{"id":"3686","n":"dumbbell kneeling hold to stand","bp":"upper legs","eq":"dumbbell","tg":"glutes","mg":"quadriceps","sm":["quadriceps","core","hamstrings"],"st":["Kneel on both knees holding a dumbbell at your chest.","Step one foot forward into a half-kneel.","Drive through that foot to stand.","Lower back into the kneeling position.","Alternate lead legs."],"img":"opengym/3686.webp","gif":null,"ext":1},{"id":"3687","n":"dumbbell drag bicep curl","bp":"upper arms","eq":"dumbbell","tg":"biceps","mg":"forearms","sm":["forearms","brachialis"],"st":["Stand tall holding a dumbbell in each hand, palms forward.","Pull your elbows back slightly and curl the weights up, keeping them close to your body.","Squeeze your biceps at the top without letting your elbows drift forward.","Lower the dumbbells slowly along the same path.","Keep your torso still and avoid swinging."],"img":"opengym/3687.webp","gif":null,"ext":1},{"id":"3688","n":"dumbbell seated reverse grip biceps curl","bp":"lower arms","eq":"dumbbell","tg":"forearms","mg":"biceps","sm":["biceps","brachialis","wrist extensors"],"st":["Sit on a bench with a dumbbell in each hand, palms facing down, arms hanging at your sides.","Keep your elbows pinned to your sides and curl the weights up.","Stop when your forearms are near vertical and your wrists stay straight.","Lower the dumbbells slowly until your arms are fully extended.","Use a lighter weight than a normal curl."],"img":"opengym/3688.webp","gif":null,"ext":1},{"id":"3689","n":"dumbbell seated one arm front raise","bp":"shoulders","eq":"dumbbell","tg":"delts","mg":"upper chest","sm":["upper chest","trapezius"],"st":["Sit upright on a bench holding a dumbbell in one hand, arm down at your thigh.","Raise the dumbbell straight in front of you to shoulder height with a soft elbow.","Pause briefly at the top.","Lower it slowly back to your thigh.","Finish your reps, then switch arms."],"img":"opengym/3689.webp","gif":null,"ext":1},{"id":"3690","n":"dumbbell seated on exercise ball shoulder press","bp":"shoulders","eq":"dumbbell","tg":"delts","mg":"triceps","sm":["triceps","upper chest","core","trapezius"],"st":["Sit on a stability ball with your feet wide and a dumbbell in each hand at shoulder height.","Brace your core and sit tall.","Press the dumbbells overhead until your arms are almost straight.","Lower them back to shoulder height with control.","Keep your ribs down and avoid leaning back."],"img":"opengym/3690.webp","gif":null,"ext":1},{"id":"3691","n":"dumbbell goblet split squat","bp":"upper legs","eq":"dumbbell","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","adductors","core"],"st":["Hold one dumbbell vertically against your chest and step into a split stance.","Keep your torso tall and lower your back knee toward the floor.","Stop when your front thigh is about parallel to the ground.","Push through your front foot to stand back up.","Finish your reps, then switch legs."],"img":"opengym/3691.webp","gif":null,"ext":1},{"id":"3692","n":"dumbbell goblet box squat","bp":"upper legs","eq":"dumbbell","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","core","adductors"],"st":["Place a box or bench behind you and hold a dumbbell at your chest.","Stand with your feet shoulder width apart.","Push your hips back and lower until you lightly touch the box.","Keep your chest up and knees in line with your toes.","Drive through your heels to stand up without rocking."],"img":"opengym/3692.webp","gif":null,"ext":1},{"id":"3693","n":"dumbbell bench supported external rotation","bp":"shoulders","eq":"dumbbell","tg":"delts","mg":"rotator cuff","sm":["rotator cuff","rear deltoids"],"st":["Lie on your side on a bench with a light dumbbell in your top hand, elbow bent 90 degrees at your side.","Keep your elbow tucked against your ribs.","Rotate your forearm upward, lifting the dumbbell toward the ceiling.","Lower it slowly back to the start.","Finish your reps, then switch sides."],"img":"opengym/3693.webp","gif":null,"ext":1},{"id":"3694","n":"dumbbell incline alternate reverse fly","bp":"shoulders","eq":"dumbbell","tg":"delts","mg":"rear deltoids","sm":["rear deltoids","rhomboids","upper back","trapezius"],"st":["Lie chest down on an incline bench with a dumbbell in each hand, arms hanging.","Raise one arm out to the side with a soft elbow until it is level with your shoulder.","Squeeze your shoulder blade, then lower slowly.","Repeat with the other arm.","Keep your neck relaxed and avoid swinging."],"img":"opengym/3694.webp","gif":null,"ext":1},{"id":"3695","n":"dumbbell alternate bench press (high start)","bp":"chest","eq":"dumbbell","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders","upper chest"],"st":["Lie on a flat bench and press both dumbbells up above your chest.","Keep one arm locked out and lower the other dumbbell to chest level.","Press it back up to the top.","Repeat with the other arm, alternating each rep.","Keep your feet planted and your back flat on the bench."],"img":"opengym/3695.webp","gif":null,"ext":1},{"id":"3696","n":"dumbbell bent over alternate rear delt fly","bp":"shoulders","eq":"dumbbell","tg":"delts","mg":"rear deltoids","sm":["rear deltoids","rhomboids","upper back","lower back"],"st":["Hinge forward at the hips with a flat back, a dumbbell in each hand hanging down.","Raise one arm out to the side to shoulder height with a soft elbow.","Lower it slowly.","Repeat with the other arm, alternating.","Keep your torso still and your neck neutral."],"img":"opengym/3696.webp","gif":null,"ext":1},{"id":"3700","n":"tuck jump v. 2","bp":"full body","eq":"body weight","tg":"cardiovascular system","mg":"quadriceps","sm":["quadriceps","glutes","calves","core"],"st":["Stand with your feet shoulder width apart and arms ready.","Dip into a quarter squat and swing your arms up.","Jump as high as you can and pull your knees toward your chest.","Land softly on the balls of your feet with bent knees.","Reset briefly and repeat."],"img":"opengym/3700.webp","gif":null,"ext":1},{"id":"3701","n":"high knee sprints","bp":"cardio","eq":"body weight","tg":"cardiovascular system","mg":"hip flexors","sm":["hip flexors","quadriceps","calves","core"],"st":["Stand tall with your arms bent at your sides.","Start running in place, driving each knee up to hip height.","Pump your arms in rhythm with your legs.","Stay on the balls of your feet and keep your chest up.","Go hard for 20 to 30 seconds, then rest."],"img":"opengym/3701.webp","gif":null,"ext":1},{"id":"3702","n":"forward pulse lunge with hands overhead","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","shoulders","core"],"st":["Stand tall and raise both arms straight overhead.","Step one foot forward into a lunge and lower until both knees are about 90 degrees.","Pulse up and down a few inches in the low position.","Push back to standing.","Switch legs and repeat."],"img":"opengym/3702.webp","gif":null,"ext":1},{"id":"3703","n":"frogger","bp":"full body","eq":"body weight","tg":"cardiovascular system","mg":"quadriceps","sm":["quadriceps","glutes","core","shoulders"],"st":["Start in a deep squat with your hands on the floor.","Jump or step your feet back into a plank.","Hop your feet to the outside of your hands.","Stand up or jump up from the squat.","Repeat at a steady quick pace."],"img":"opengym/3703.webp","gif":null,"ext":1},{"id":"3704","n":"double jump squat","bp":"upper legs","eq":"body weight","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","calves","core"],"st":["Stand with your feet shoulder width apart.","Lower into a squat and explode into a jump.","Land softly and immediately jump a second time.","Land with bent knees and sink back into the squat.","Keep your chest up and repeat."],"img":"opengym/3704.webp","gif":null,"ext":1},{"id":"3705","n":"squat thrust","bp":"full body","eq":"body weight","tg":"cardiovascular system","mg":"quadriceps","sm":["quadriceps","core","chest","triceps"],"st":["Stand with your feet shoulder width apart.","Squat down and place your hands on the floor.","Kick your feet back into a plank.","Jump your feet back toward your hands.","Stand up and repeat at a steady pace."],"img":"opengym/3705.webp","gif":null,"ext":1},{"id":"3706","n":"squat tuck jump","bp":"upper legs","eq":"body weight","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","calves","core"],"st":["Stand with your feet shoulder width apart.","Lower into a squat with your arms back.","Explode upward and pull your knees toward your chest.","Land softly with bent knees.","Sink straight into the next squat and repeat."],"img":"opengym/3706.webp","gif":null,"ext":1},{"id":"3707","n":"dumbbell press squat (thighs)","bp":"upper legs","eq":"dumbbell","tg":"quads","mg":"glutes","sm":["glutes","shoulders","triceps","core"],"st":["Hold a dumbbell in each hand at shoulder height.","Squat down until your thighs are about parallel to the floor.","Drive up through your heels as you stand.","Use that momentum to press the dumbbells overhead.","Lower them to your shoulders and go into the next squat."],"img":"opengym/3707.webp","gif":null,"ext":1},{"id":"3708","n":"cardio lunge","bp":"cardio","eq":"body weight","tg":"cardiovascular system","mg":"quadriceps","sm":["quadriceps","glutes","hamstrings","calves"],"st":["Stand tall with your hands on your hips or swinging with the movement.","Step forward and lower into a lunge.","Push off the front foot and return to standing.","Switch legs and keep a quick rhythm.","Keep your torso upright throughout."],"img":"opengym/3708.webp","gif":null,"ext":1},{"id":"3709","n":"dumbbell overhead squat","bp":"upper legs","eq":"dumbbell","tg":"quads","mg":"glutes","sm":["glutes","shoulders","core","upper back"],"st":["Press two dumbbells overhead with your arms straight.","Stand with your feet shoulder width apart.","Sit down into a squat while keeping the weights above your head.","Keep your chest up and ribs down.","Stand back up, driving through your heels."],"img":"opengym/3709.webp","gif":null,"ext":1},{"id":"3710","n":"dumbbell split squat front foot elevated with bosu ball","bp":"upper legs","eq":"dumbbell","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","core","calves"],"st":["Hold a dumbbell in each hand and place your front foot on a bosu ball, back foot behind you.","Keep your torso upright.","Lower your back knee toward the floor.","Press through your front foot to stand.","Finish your reps, then switch legs."],"img":"opengym/3710.webp","gif":null,"ext":1},{"id":"3711","n":"single leg step up v. 2","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","calves"],"st":["Stand facing a sturdy box or bench.","Place one foot fully on it.","Drive through that heel to stand tall on the box.","Lower slowly back down.","Finish your reps, then switch legs."],"img":"opengym/3711.webp","gif":null,"ext":1},{"id":"3712","n":"standing single leg calf raise with support","bp":"lower legs","eq":"body weight","tg":"calves","mg":"soleus","sm":["soleus","ankles","feet"],"st":["Stand on one foot and hold a wall or rail for balance.","Rise as high as you can onto the ball of your foot.","Pause briefly at the top.","Lower slowly below flat if you can do so comfortably.","Finish your reps, then switch legs."],"img":"opengym/3712.webp","gif":null,"ext":1},{"id":"3713","n":"dumbbell standing single leg calf raise v. 2","bp":"lower legs","eq":"dumbbell","tg":"calves","mg":"soleus","sm":["soleus","ankles","feet"],"st":["Hold a dumbbell in one hand and stand on the opposite leg, lightly touching a wall for balance.","Rise up onto the ball of your foot as high as you can.","Pause at the top.","Lower your heel slowly below the start if possible.","Finish your reps, then switch legs."],"img":"opengym/3713.webp","gif":null,"ext":1},{"id":"3714","n":"single leg stand","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"ankles","sm":["ankles","feet","core","calves"],"st":["Stand tall with your feet together.","Lift one foot off the floor and bend the knee slightly.","Keep your hips level and eyes on a fixed point.","Hold for 20 to 30 seconds.","Switch legs and repeat."],"img":"opengym/3714.webp","gif":null,"ext":1},{"id":"3715","n":"single leg stand on bosu ball","bp":"upper legs","eq":"bosu ball","tg":"glutes","mg":"ankles","sm":["ankles","feet","core","calves"],"st":["Place a bosu ball dome-up in front of you.","Step onto it with one foot near the center.","Lift your other foot and hold it off the ground.","Keep your hips level and your core tight.","Hold for 20 to 30 seconds, then switch legs."],"img":"opengym/3715.webp","gif":null,"ext":1},{"id":"3716","n":"split squat with roll","bp":"upper legs","eq":"body weight","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","core"],"st":["Start in a split stance with your torso upright.","Lower into a split squat until the front thigh is parallel.","Sit back and roll onto your back with control.","Roll up and return to the split stance.","Stand and repeat, then switch legs."],"img":"opengym/3716.webp","gif":null,"ext":1},{"id":"3718","n":"split lateral squat with roll","bp":"upper legs","eq":"body weight","tg":"quads","mg":"glutes","sm":["glutes","adductors","core"],"st":["Stand with feet wide and toes forward.","Shift your weight to one side and squat on that leg, keeping the other leg straight.","Roll back with control and roll up again.","Push back to the centre.","Alternate sides."],"img":"opengym/3718.webp","gif":null,"ext":1},{"id":"3719","n":"cable standing high cross triceps extension","bp":"upper arms","eq":"cable","tg":"triceps","mg":"shoulders","sm":["shoulders","forearms"],"st":["Set a cable to a high position and hold the handle with one hand.","Stand facing the machine with your elbow bent and tucked.","Press the handle down and across your body until your arm is straight.","Return slowly to the start.","Finish your reps, then switch arms."],"img":"opengym/3719.webp","gif":null,"ext":1},{"id":"3720","n":"stair jump","bp":"upper legs","eq":"body weight","tg":"quads","mg":"glutes","sm":["glutes","calves","hamstrings","core"],"st":["Stand at the bottom of a staircase with your feet together.","Bend your knees and swing your arms back.","Jump up onto a step, landing softly with both feet.","Step back down carefully.","Reset and repeat."],"img":"opengym/3720.webp","gif":null,"ext":1},{"id":"3721","n":"barbell bent over wide grip row","bp":"back","eq":"barbell","tg":"upper back","mg":"lats","sm":["lats","rhomboids","rear deltoids","biceps","lower back"],"st":["Hold a barbell with a wide overhand grip and hinge forward with a flat back.","Let the bar hang at arm length below your chest.","Pull the bar toward your lower chest, flaring your elbows.","Squeeze your shoulder blades together.","Lower the bar with control."],"img":"opengym/3721.webp","gif":null,"ext":1},{"id":"3722","n":"barbell incline lying rear delt raise","bp":"shoulders","eq":"barbell","tg":"delts","mg":"rear deltoids","sm":["rear deltoids","upper back","rhomboids","trapezius"],"st":["Lie chest down on an incline bench holding a barbell hanging below you.","Keep your arms nearly straight.","Raise the bar by lifting your elbows out and back.","Squeeze your rear delts at the top.","Lower the barbell slowly."],"img":"opengym/3722.webp","gif":null,"ext":1},{"id":"3723","n":"barbell curtsey lunge","bp":"upper legs","eq":"barbell","tg":"glutes","mg":"quadriceps","sm":["quadriceps","adductors","hamstrings","core"],"st":["Rest a barbell across your upper back and stand tall.","Step one leg back and across behind the other, like a curtsey.","Lower until your front thigh is near parallel.","Push through your front heel to stand.","Alternate sides or finish one side first."],"img":"opengym/3723.webp","gif":null,"ext":1},{"id":"3724","n":"barbell floor chest press","bp":"chest","eq":"barbell","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders","upper chest"],"st":["Lie on the floor with your knees bent and a barbell set above your chest.","Grip the bar slightly wider than shoulder width.","Lower the bar until your upper arms touch the floor.","Pause briefly.","Press the bar back up to full extension."],"img":"opengym/3724.webp","gif":null,"ext":1},{"id":"3725","n":"barbell overhead lunge","bp":"upper legs","eq":"barbell","tg":"glutes","mg":"quadriceps","sm":["quadriceps","shoulders","core","hamstrings"],"st":["Press a barbell overhead and hold it with straight arms.","Step forward into a lunge.","Lower until both knees are around 90 degrees.","Push off your front foot back to standing.","Alternate legs and keep the bar steady."],"img":"opengym/3725.webp","gif":null,"ext":1},{"id":"3726","n":"barbell seated front raise","bp":"shoulders","eq":"barbell","tg":"delts","mg":"upper chest","sm":["upper chest","trapezius"],"st":["Sit on a bench holding a barbell with an overhand grip, resting on your thighs.","Raise the bar straight in front of you to shoulder height.","Pause at the top.","Lower it slowly to your thighs.","Keep your back straight and avoid swinging."],"img":"opengym/3726.webp","gif":null,"ext":1},{"id":"3727","n":"barbell front bench squat","bp":"upper legs","eq":"barbell","tg":"quads","mg":"glutes","sm":["glutes","core","upper back"],"st":["Place a bench behind you and rest the bar across your front shoulders.","Keep your elbows high and your chest up.","Sit back and down until you lightly touch the bench.","Drive through your feet to stand.","Avoid rocking or collapsing onto the bench."],"img":"opengym/3727.webp","gif":null,"ext":1},{"id":"3728","n":"barbell front step up","bp":"upper legs","eq":"barbell","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","core"],"st":["Rack a barbell across your front shoulders and stand facing a box.","Place one foot fully on the box.","Drive through that heel to step up and stand tall.","Lower back down slowly.","Finish your reps, then switch legs."],"img":"opengym/3728.webp","gif":null,"ext":1},{"id":"3729","n":"barbell chest press on stability ball","bp":"chest","eq":"barbell","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders","core"],"st":["Sit on a stability ball and walk your feet out until your upper back rests on it.","Keep your hips up and take the barbell above your chest.","Lower the bar to your chest.","Press it back up to full extension.","Keep your core tight and feet planted."],"img":"opengym/3729.webp","gif":null,"ext":1},{"id":"3730","n":"barbell behind the back shrug","bp":"back","eq":"barbell","tg":"traps","mg":"forearms","sm":["forearms","grip muscles","upper back"],"st":["Stand holding a barbell behind your back with straight arms.","Keep your chest up and shoulders relaxed.","Shrug your shoulders straight up toward your ears.","Pause at the top.","Lower slowly without rolling your shoulders."],"img":"opengym/3730.webp","gif":null,"ext":1},{"id":"3731","n":"barbell sumo romanian deadlift","bp":"upper legs","eq":"barbell","tg":"hamstrings","mg":"glutes","sm":["glutes","adductors","lower back","grip muscles"],"st":["Hold a barbell in front of your thighs with a wide stance and toes turned out.","Push your hips back, keeping your knees slightly bent.","Lower the bar along your legs until you feel a hamstring stretch.","Keep your back flat.","Drive your hips forward to stand tall."],"img":"opengym/3731.webp","gif":null,"ext":1},{"id":"3732","n":"kettlebell goblet curtsey lunge","bp":"upper legs","eq":"kettlebell","tg":"glutes","mg":"quadriceps","sm":["quadriceps","adductors","hamstrings","core"],"st":["Hold a kettlebell by the horns at your chest and stand tall.","Step one leg back and across behind the other.","Lower until your front thigh is near parallel.","Push through your front heel to return.","Finish your reps, then switch legs."],"img":"opengym/3732.webp","gif":null,"ext":1},{"id":"3733","n":"kettlebell straight leg deadlift","bp":"upper legs","eq":"kettlebell","tg":"hamstrings","mg":"glutes","sm":["glutes","lower back","grip muscles"],"st":["Stand holding a kettlebell with both hands in front of your thighs.","Keep your legs almost straight with a soft knee.","Hinge at the hips and lower the bell along your legs.","Keep your back flat.","Drive your hips forward to stand."],"img":"opengym/3733.webp","gif":null,"ext":1},{"id":"3734","n":"kettlebell kickstand one leg deadlift","bp":"upper legs","eq":"kettlebell","tg":"hamstrings","mg":"glutes","sm":["glutes","lower back","core"],"st":["Hold a kettlebell and stand with one foot slightly behind, toes on the ground as a kickstand.","Hinge at the hips over your front leg.","Lower the bell toward the floor with a flat back.","Drive through your front heel to stand.","Finish your reps, then switch legs."],"img":"opengym/3734.webp","gif":null,"ext":1},{"id":"3735","n":"kettlebell pullover 3 month position","bp":"back","eq":"kettlebell","tg":"lats","mg":"chest","sm":["chest","triceps","core"],"st":["Lie on your back holding a kettlebell with both hands above your chest.","Keep your arms slightly bent.","Lower the bell back over your head in an arc.","Stop when you feel a stretch in your lats.","Pull it back over your chest."],"img":"opengym/3735.webp","gif":null,"ext":1},{"id":"3736","n":"kettlebell standing bottoms up one arm shoulder press","bp":"shoulders","eq":"kettlebell","tg":"delts","mg":"triceps","sm":["triceps","forearms","grip muscles","core"],"st":["Hold a kettlebell upside down by the handle at shoulder height.","Squeeze the handle and brace your core.","Press the bell straight overhead, keeping it balanced.","Lower it back to your shoulder with control.","Finish your reps, then switch arms."],"img":"opengym/3736.webp","gif":null,"ext":1},{"id":"3737","n":"kettlebell seated one arm military press","bp":"shoulders","eq":"kettlebell","tg":"delts","mg":"triceps","sm":["triceps","upper chest","core"],"st":["Sit on a bench with a kettlebell held at your shoulder.","Sit tall with your core braced.","Press the bell straight overhead until your arm is straight.","Lower it slowly to your shoulder.","Finish your reps, then switch arms."],"img":"opengym/3737.webp","gif":null,"ext":1},{"id":"3738","n":"kettlebell one arm bench press","bp":"chest","eq":"kettlebell","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders","core"],"st":["Lie on a bench holding a kettlebell above your chest.","Keep your wrist straight and your feet planted.","Lower the bell to the side of your chest.","Press it back up to full extension.","Finish your reps, then switch arms."],"img":"opengym/3738.webp","gif":null,"ext":1},{"id":"3739","n":"kettlebell bottom up one arm bench press","bp":"chest","eq":"kettlebell","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders","forearms","grip muscles"],"st":["Lie on a bench holding a kettlebell upside down above your chest.","Squeeze the handle and keep your wrist stacked.","Lower the bell slowly toward your chest.","Press it back up while keeping it balanced.","Use a light weight and switch arms after your reps."],"img":"opengym/3739.webp","gif":null,"ext":1},{"id":"3740","n":"kettlebell lateral raise","bp":"shoulders","eq":"kettlebell","tg":"delts","mg":"trapezius","sm":["trapezius","rotator cuff"],"st":["Stand holding a kettlebell in one hand at your side.","Keep a soft bend in your elbow.","Raise your arm out to the side to shoulder height.","Lower it slowly.","Finish your reps, then switch arms."],"img":"opengym/3740.webp","gif":null,"ext":1},{"id":"3741","n":"lateral raise with towel","bp":"shoulders","eq":"body weight","tg":"delts","mg":"trapezius","sm":["trapezius","rotator cuff"],"st":["Hold a towel with both hands and stand on its middle with one foot, or pull its ends apart.","Keep your elbows slightly bent.","Raise your arms out to the sides to shoulder height.","Lower slowly.","Keep tension on the towel throughout."],"img":"opengym/3741.webp","gif":null,"ext":1},{"id":"3742","n":"sliding leg curl on floor with towel v. 2","bp":"upper legs","eq":"body weight","tg":"hamstrings","mg":"glutes","sm":["glutes","calves","core"],"st":["Lie on your back with your heels on towels on a smooth floor.","Lift your hips off the ground.","Slide your heels toward your butt, curling your legs.","Slowly slide them back out.","Keep your hips high throughout."],"img":"opengym/3742.webp","gif":null,"ext":1},{"id":"3743","n":"bulgarian split squat with chair","bp":"upper legs","eq":"body weight","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","adductors","core"],"st":["Stand facing away from a chair and rest the top of one foot on it.","Step your front foot forward so it is stable.","Lower your back knee toward the floor.","Push through your front foot to stand.","Finish your reps, then switch legs."],"img":"opengym/3743.webp","gif":null,"ext":1},{"id":"3744","n":"rear delt fly with bed sheet","bp":"shoulders","eq":"body weight","tg":"delts","mg":"rear deltoids","sm":["rear deltoids","upper back","rhomboids"],"st":["Hold a bed sheet taut in both hands in front of you.","Keep your arms nearly straight.","Pull your hands apart, opening your arms out to the sides.","Squeeze your shoulder blades together.","Return slowly and keep tension on the sheet."],"img":"opengym/3744.webp","gif":null,"ext":1},{"id":"3745","n":"overhead triceps extension with bed sheet","bp":"upper arms","eq":"body weight","tg":"triceps","mg":"shoulders","sm":["shoulders","core"],"st":["Hold a bed sheet with both hands behind your head, one hand pulling up, one down.","Keep your elbows pointing forward.","Press your top hand overhead against the resistance.","Return slowly to the start.","Finish your reps, then swap hand positions."],"img":"opengym/3745.webp","gif":null,"ext":1},{"id":"3746","n":"rear delt row with bed sheet","bp":"back","eq":"body weight","tg":"delts","mg":"rear deltoids","sm":["rear deltoids","rhomboids","biceps"],"st":["Loop a bed sheet around a sturdy anchor and hold the ends.","Lean back with your arms straight.","Pull your hands toward your chest, elbows flared out.","Squeeze your shoulder blades.","Return slowly."],"img":"opengym/3746.webp","gif":null,"ext":1},{"id":"3747","n":"assisted pistol squat with bed sheet","bp":"upper legs","eq":"assisted","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","core","ankles"],"st":["Hold the ends of a bed sheet anchored to a door or post.","Stand on one leg with the other leg extended forward.","Sit down on your standing leg, using the sheet as support.","Lower as far as you can control.","Push up to stand and switch legs after your reps."],"img":"opengym/3747.webp","gif":null,"ext":1},{"id":"3748","n":"biceps curl with bed sheet","bp":"upper arms","eq":"body weight","tg":"biceps","mg":"forearms","sm":["forearms","brachialis"],"st":["Hold a bed sheet with both hands, one arm pulling down, the other curling up.","Keep your elbow at your side.","Curl the working hand toward your shoulder against the resistance.","Lower slowly.","Finish your reps, then switch arms."],"img":"opengym/3748.webp","gif":null,"ext":1},{"id":"3749","n":"inverted row with bed sheet","bp":"back","eq":"body weight","tg":"upper back","mg":"lats","sm":["lats","biceps","rhomboids","core"],"st":["Anchor a bed sheet securely and hold both ends.","Lean back with your body straight.","Pull your chest toward your hands.","Squeeze your shoulder blades together.","Lower yourself slowly."],"img":"opengym/3749.webp","gif":null,"ext":1},{"id":"3750","n":"front plank side hop","bp":"waist","eq":"body weight","tg":"abs","mg":"obliques","sm":["obliques","shoulders","core","hip flexors"],"st":["Start in a high plank with hands under shoulders.","Brace your core.","Hop both feet a short way to one side.","Hop them back to the other side.","Keep your shoulders stable and your hips low."],"img":"opengym/3750.webp","gif":null,"ext":1},{"id":"3751","n":"reverse push up","bp":"upper arms","eq":"body weight","tg":"triceps","mg":"chest","sm":["chest","shoulders","core"],"st":["Sit on the floor and place your hands behind you, fingers pointing toward your hips.","Lift your hips off the floor.","Bend your elbows and lower your hips.","Press back up to straight arms.","Keep your elbows pointing back."],"img":"opengym/3751.webp","gif":null,"ext":1},{"id":"3752","n":"lying double legs biceps curl with towel","bp":"upper arms","eq":"body weight","tg":"biceps","mg":"forearms","sm":["forearms","brachialis","hamstrings"],"st":["Lie on your back and wrap a towel around both feet, holding the ends.","Lift your legs slightly and press them against the towel.","Curl the towel toward your chest while your legs resist.","Lower slowly.","Keep your elbows at your sides."],"img":"opengym/3752.webp","gif":null,"ext":1},{"id":"3757","n":"band high fly","bp":"chest","eq":"band","tg":"pectorals","mg":"shoulders","sm":["shoulders","upper chest"],"st":["Anchor a band high and hold one end in each hand, facing away.","Step forward and lean slightly.","Bring your hands together in front of your waist with a soft elbow.","Squeeze your chest at the end.","Return slowly."],"img":"opengym/3757.webp","gif":null,"ext":1},{"id":"3761","n":"dumbbell seated alternate biceps curl","bp":"upper arms","eq":"dumbbell","tg":"biceps","mg":"brachialis","sm":["brachialis","forearms"],"st":["Sit upright holding a dumbbell in each hand with arms hanging.","Keep your elbows by your sides.","Curl one dumbbell up to shoulder height.","Lower slowly.","Alternate arms and avoid swinging."],"img":"opengym/3761.webp","gif":null,"ext":1},{"id":"3764","n":"dumbbell incline biceps curl v. 2","bp":"upper arms","eq":"dumbbell","tg":"biceps","mg":"brachialis","sm":["brachialis","forearms"],"st":["Sit back on an incline bench with a dumbbell in each hand, arms hanging.","Keep your shoulders against the bench.","Curl both dumbbells toward your shoulders.","Pause and squeeze.","Lower slowly to a full stretch."],"img":"opengym/3764.webp","gif":null,"ext":1},{"id":"3765","n":"jump step up","bp":"cardio","eq":"body weight","tg":"cardiovascular system","mg":"quadriceps","sm":["quadriceps","glutes","calves","hamstrings"],"st":["Stand facing a sturdy box or step.","Place one foot on top.","Drive through it and jump up into the air.","Land softly on the box and step back down.","Switch legs and keep a steady rhythm."],"img":"opengym/3765.webp","gif":null,"ext":1},{"id":"3767","n":"dumbbell single leg squat v. 2","bp":"upper legs","eq":"dumbbell","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","core","ankles"],"st":["Hold a dumbbell at your chest and stand on one leg.","Extend your other leg in front of you.","Lower into a squat as far as you can control.","Push through your heel to stand.","Finish your reps, then switch legs."],"img":"opengym/3767.webp","gif":null,"ext":1},{"id":"3768","n":"lever seated horizontal leg press","bp":"upper legs","eq":"leverage machine","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","adductors","calves"],"st":["Sit on the machine with your back against the pad and feet on the platform.","Release the safety and press the platform away.","Stop just before your knees lock.","Lower the weight slowly until your knees are bent about 90 degrees.","Keep your hips down and your back flat on the pad."],"img":"opengym/3768.webp","gif":null,"ext":1},{"id":"3770","n":"band squat with single arm row","bp":"upper legs","eq":"band","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","lats","upper back","biceps"],"st":["Anchor the band at a low point and hold the handle in one hand.","Stand tall with feet shoulder width apart and the band under light tension.","Sit your hips back and down into a squat while keeping your chest up.","Stand up and, at the top, pull the handle to your ribs with your elbow close to your body, then let it return slowly.","Finish your reps, then switch sides."],"img":"opengym/3770.webp","gif":null,"ext":1},{"id":"3771","n":"band deadlift with single arm row","bp":"upper legs","eq":"band","tg":"glutes","mg":"hamstrings","sm":["hamstrings","lower back","lats","upper back","biceps"],"st":["Anchor the band at a low point and hold the handle in one hand.","Stand with soft knees and the band under light tension.","Push your hips back and lower your torso with a flat back.","Drive your hips forward to stand, then row the handle to your ribs.","Lower the handle under control. Finish your reps, then switch sides."],"img":"opengym/3771.webp","gif":null,"ext":1},{"id":"3772","n":"band high knee lunge with single arm row","bp":"upper legs","eq":"band","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","lats","upper back","core"],"st":["Anchor the band at a low point and hold the handle in one hand.","Step back into a lunge and lower until your front thigh is about parallel.","Push through your front foot and drive the rear knee up to hip height.","Row the handle to your ribs while balancing on one leg.","Return to the start under control. Finish your reps, then switch sides."],"img":"opengym/3772.webp","gif":null,"ext":1},{"id":"3773","n":"band single stiff leg deadlift with single arm row","bp":"upper legs","eq":"band","tg":"hamstrings","mg":"glutes","sm":["glutes","lower back","lats","upper back","core"],"st":["Anchor the band at a low point and hold the handle in one hand.","Stand on one leg with a soft knee and the band under light tension.","Hinge forward at the hips while the free leg extends behind you.","Keep your back flat, then pull the handle to your ribs.","Lower the handle and stand tall again. Finish your reps, then switch sides."],"img":"opengym/3773.webp","gif":null,"ext":1},{"id":"3774","n":"band squat with horizontal pallof hold","bp":"upper legs","eq":"band","tg":"quads","mg":"glutes","sm":["glutes","core","obliques","shoulders"],"st":["Anchor the band at chest height and stand side-on to it.","Hold the handle with both hands at your chest, then press it straight out.","Keep your hips and shoulders square as you squat down.","Stand back up while holding the band steady.","Complete your reps, then turn around and repeat on the other side."],"img":"opengym/3774.webp","gif":null,"ext":1},{"id":"3775","n":"band split squat with horizontal pallof hold","bp":"upper legs","eq":"band","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","core","obliques"],"st":["Anchor the band at chest height and stand side-on to it.","Take a split stance and press the handle straight out with both hands.","Lower your back knee toward the floor without letting the band twist you.","Push through your front foot to rise.","Finish your reps, then switch legs and anchor side."],"img":"opengym/3775.webp","gif":null,"ext":1},{"id":"3776","n":"band side step with horizontal pallof hold","bp":"upper legs","eq":"band","tg":"abductors","mg":"glutes","sm":["glutes","core","obliques","shoulders"],"st":["Anchor the band at chest height and stand side-on to it.","Press the handle straight out and sink into a quarter squat.","Take small steps sideways away from the anchor, keeping your torso square.","Step back in under control.","Repeat for your set, then switch sides."],"img":"opengym/3776.webp","gif":null,"ext":1},{"id":"3777","n":"band front plank with single arm pulldown","bp":"waist","eq":"band","tg":"abs","mg":"shoulders","sm":["shoulders","lats","core","obliques"],"st":["Anchor the band overhead and set up in a forearm or high plank.","Brace your abs and keep your hips level.","Pull the band down with one hand toward your hip without twisting.","Return the arm slowly to the start.","Alternate arms and keep your body in one straight line."],"img":"opengym/3777.webp","gif":null,"ext":1},{"id":"3778","n":"band upper body lying air bike","bp":"waist","eq":"band","tg":"abs","mg":"lower abs","sm":["lower abs","shoulders","core","obliques"],"st":["Lie on your back with the band anchored behind your head, a handle in each hand.","Lift your shoulders and legs slightly off the floor.","Alternate pulling one handle toward your opposite knee in a pedalling motion.","Keep your lower back pressed down.","Continue at a steady pace for your set."],"img":"opengym/3778.webp","gif":null,"ext":1},{"id":"3779","n":"band skier","bp":"full body","eq":"band","tg":"lats","mg":"glutes","sm":["glutes","hamstrings","shoulders","core","triceps"],"st":["Anchor the band overhead and hold a handle in each hand.","Stand with soft knees and arms extended in front of you.","Pull the handles down and back past your hips as you hinge forward.","Return the arms up and stand tall in one smooth motion.","Keep your back flat and move with control."],"img":"opengym/3779.webp","gif":null,"ext":1},{"id":"3780","n":"band standing chest press","bp":"chest","eq":"band","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders","upper chest"],"st":["Anchor the band behind you at chest height and hold the handles at your chest.","Stand in a staggered stance with your core braced.","Press both hands forward until your arms are straight.","Pause briefly, then return slowly to your chest.","Keep your shoulders down and your back still."],"img":"opengym/3780.webp","gif":null,"ext":1},{"id":"3781","n":"band split jump with single arm row","bp":"upper legs","eq":"band","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","calves","lats","upper back"],"st":["Anchor the band at a low point and hold the handle in one hand.","Start in a split stance with a slight bend in both knees.","Jump up and switch legs in mid-air.","Land softly in the opposite split stance and row the handle to your ribs.","Alternate legs, and switch rowing arm for the next set."],"img":"opengym/3781.webp","gif":null,"ext":1},{"id":"3782","n":"band jump lunge with single arm row","bp":"upper legs","eq":"band","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","calves","lats","upper back"],"st":["Anchor the band at a low point and hold the handle in one hand.","Start in a lunge position with your chest up.","Jump and switch legs in mid-air.","Land softly in a lunge and pull the handle to your ribs.","Keep your front knee over your ankle on each landing.","Switch rowing arm for the next set."],"img":"opengym/3782.webp","gif":null,"ext":1},{"id":"3783","n":"dumbbell archer","bp":"shoulders","eq":"dumbbell","tg":"delts","mg":"triceps","sm":["triceps","upper back","rear deltoids","core"],"st":["Stand with feet wide and hold a dumbbell in one hand.","Shift your weight toward the empty-hand side and bend that knee.","Raise the dumbbell out to the side, keeping the other leg straight.","Lower with control and shift back to the center.","Repeat all reps, then switch arms."],"img":"opengym/3783.webp","gif":null,"ext":1},{"id":"3784","n":"cross arms push up","bp":"upper arms","eq":"body weight","tg":"triceps","mg":"chest","sm":["chest","shoulders","core"],"st":["Start in a high plank with your hands crossed under your chest.","Keep your body in a straight line from head to heels.","Lower your chest toward the floor with your elbows close.","Press back up until your arms are straight.","Switch which hand is on top each set."],"img":"opengym/3784.webp","gif":null,"ext":1},{"id":"3798","n":"resistance band punch","bp":"chest","eq":"resistance band","tg":"pectorals","mg":"shoulders","sm":["shoulders","triceps","core"],"st":["Anchor the band behind you and hold a handle in each hand at your shoulders.","Stand in a staggered stance with a braced core.","Punch one hand forward and rotate your torso slightly.","Return the hand and punch with the other side.","Keep the movement quick but controlled."],"img":"opengym/3798.webp","gif":null,"ext":1},{"id":"3799","n":"dumbbell bent over reverse row","bp":"back","eq":"dumbbell","tg":"upper back","mg":"lats","sm":["lats","rear deltoids","biceps","rhomboids","forearms"],"st":["Hold a dumbbell in each hand with palms facing forward.","Hinge at the hips with a flat back and let the weights hang.","Pull the dumbbells to your lower ribs, squeezing your shoulder blades.","Lower slowly until your arms are straight.","Keep your neck neutral throughout."],"img":"opengym/3799.webp","gif":null,"ext":1},{"id":"3812","n":"elevated push up","bp":"chest","eq":"body weight","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders","core","upper chest"],"st":["Place your hands on a bench or box slightly wider than your shoulders.","Step back so your body forms a straight line.","Lower your chest to the edge with your elbows at about 45 degrees.","Press back up until your arms are straight.","Keep your hips from sagging."],"img":"opengym/3812.webp","gif":null,"ext":1},{"id":"3813","n":"starfish crunch (beginner)","bp":"waist","eq":"body weight","tg":"abs","mg":"lower abs","sm":["lower abs","obliques","hip flexors"],"st":["Lie on your back with your arms and legs spread wide.","Brace your abs and press your lower back down.","Crunch up, bringing your elbows toward your knees as they pull in.","Lower back to the starfish position under control.","Breathe out as you crunch."],"img":"opengym/3813.webp","gif":null,"ext":1},{"id":"3814","n":"front plank toe tap","bp":"waist","eq":"body weight","tg":"abs","mg":"hip flexors","sm":["hip flexors","glutes","shoulders","core","obliques"],"st":["Start in a high plank with your hands under your shoulders.","Brace your abs and keep your hips level.","Tap one toe out to the side and bring it back.","Repeat with the other foot.","Keep your body steady and avoid rocking."],"img":"opengym/3814.webp","gif":null,"ext":1},{"id":"3821","n":"crunch (arms straight)","bp":"waist","eq":"body weight","tg":"abs","mg":"obliques","sm":["obliques","hip flexors","core"],"st":["Lie on your back with knees bent and feet flat.","Extend your arms straight toward your knees.","Curl your shoulders off the floor, keeping your arms reaching.","Pause briefly at the top.","Lower slowly without pulling on your neck."],"img":"opengym/3821.webp","gif":null,"ext":1},{"id":"3822","n":"pulse row","bp":"back","eq":"body weight","tg":"upper back","mg":"lats","sm":["lats","rear deltoids","biceps","rhomboids"],"st":["Hinge forward at the hips with a flat back and arms hanging.","Pull your elbows back and squeeze your shoulder blades.","Pulse in short movements at the top.","Lower your arms under control.","Keep your neck neutral."],"img":"opengym/3822.webp","gif":null,"ext":1},{"id":"3823","n":"decline shoulder tap","bp":"chest","eq":"body weight","tg":"delts","mg":"core","sm":["core","chest","triceps"],"st":["Place your feet on a bench and your hands on the floor under your shoulders.","Keep your body in a straight line.","Lift one hand and tap the opposite shoulder.","Return it and tap with the other hand.","Keep your hips from rocking."],"img":"opengym/3823.webp","gif":null,"ext":1},{"id":"3824","n":"pseudo planche push up","bp":"chest","eq":"body weight","tg":"pectorals","mg":"shoulders","sm":["shoulders","triceps","core","upper chest"],"st":["Start in a plank with your hands turned out beside your lower ribs.","Lean your shoulders forward beyond your hands.","Lower your chest with your elbows close to your body.","Press up while keeping the lean.","Keep your core braced."],"img":"opengym/3824.webp","gif":null,"ext":1},{"id":"3825","n":"mid air lateral raises with switching palms","bp":"shoulders","eq":"dumbbell","tg":"delts","mg":"rotator cuff","sm":["rotator cuff","trapezius","forearms"],"st":["Stand with a light dumbbell in each hand at your sides.","Raise your arms out to shoulder height with palms down.","Turn your palms up in mid air, then back down.","Lower the weights slowly.","Keep your elbows slightly bent."],"img":"opengym/3825.webp","gif":null,"ext":1},{"id":"3826","n":"lying around the world","bp":"shoulders","eq":"body weight","tg":"delts","mg":"upper back","sm":["upper back","rear deltoids","chest","rotator cuff"],"st":["Lie on your back with your arms by your sides.","Raise your arms to the ceiling.","Sweep them in a wide arc overhead toward the floor.","Continue the arc back down to your sides.","Move slowly and keep your ribs down."],"img":"opengym/3826.webp","gif":null,"ext":1},{"id":"3827","n":"lying floor hyperextension","bp":"upper legs","eq":"body weight","tg":"spine","mg":"glutes","sm":["glutes","hamstrings","lower back"],"st":["Lie face down with your arms extended or by your sides.","Squeeze your glutes and lift your chest and legs slightly.","Pause briefly at the top.","Lower back down with control.","Keep your neck neutral."],"img":"opengym/3827.webp","gif":null,"ext":1},{"id":"3828","n":"bent over row with towel","bp":"back","eq":"body weight","tg":"upper back","mg":"lats","sm":["lats","biceps","rear deltoids","forearms"],"st":["Hold a towel with both hands and stretch it taut.","Hinge forward at the hips with a flat back.","Pull the towel toward your chest while pulling it apart.","Squeeze your shoulder blades together.","Return slowly."],"img":"opengym/3828.webp","gif":null,"ext":1},{"id":"3829","n":"lying floor hyperextension with towel","bp":"upper legs","eq":"body weight","tg":"spine","mg":"glutes","sm":["glutes","hamstrings","lower back","upper back"],"st":["Lie face down holding a taut towel in front of you.","Lift your chest and legs off the floor.","Keep pulling the towel apart.","Pause at the top.","Lower back down with control."],"img":"opengym/3829.webp","gif":null,"ext":1},{"id":"3830","n":"lying double legs hammer curl with towel","bp":"upper arms","eq":"body weight","tg":"biceps","mg":"brachialis","sm":["brachialis","forearms","grip muscles"],"st":["Lie on your back and loop a towel around both feet.","Hold the ends with palms facing each other.","Pull the towel toward your chest while pushing your feet against it.","Pause, then slowly extend your arms.","Keep your elbows near your sides."],"img":"opengym/3830.webp","gif":null,"ext":1},{"id":"3831","n":"lying single leg reverse biceps curl with towel","bp":"lower arms","eq":"body weight","tg":"forearms","mg":"brachialis","sm":["brachialis","biceps","grip muscles"],"st":["Lie on your back and loop a towel around one foot.","Hold the ends with an overhand grip.","Pull the towel toward you while the foot resists.","Pause at the top.","Lower slowly, then switch legs."],"img":"opengym/3831.webp","gif":null,"ext":1},{"id":"3832","n":"handboard slope hang","bp":"lower arms","eq":"body weight","tg":"forearms","mg":"grip muscles","sm":["grip muscles","lats","shoulders","hands"],"st":["Grip the sloped hold with open hands.","Step off the ground and hang with straight arms.","Keep your shoulders active and your core tight.","Hold for 5-10 seconds.","Rest fully, then repeat."],"img":"opengym/3832.webp","gif":null,"ext":1},{"id":"3833","n":"handboard open hand grip","bp":"lower arms","eq":"body weight","tg":"forearms","mg":"grip muscles","sm":["grip muscles","hands","shoulders"],"st":["Grip the edge with fingers extended and a slight arch.","Step off and hang with straight arms.","Keep your shoulders engaged.","Hold for 5-10 seconds.","Lower down and rest before the next hang."],"img":"opengym/3833.webp","gif":null,"ext":1},{"id":"3834","n":"handboard half crimp","bp":"lower arms","eq":"body weight","tg":"forearms","mg":"grip muscles","sm":["grip muscles","hands","shoulders"],"st":["Place your fingers on the edge with the knuckles bent at about 90 degrees.","Step off and hang with straight arms.","Keep your shoulders engaged.","Hold for 5-10 seconds.","Rest fully between hangs."],"img":"opengym/3834.webp","gif":null,"ext":1},{"id":"3835","n":"handboard hang with 90 degree elbow","bp":"lower arms","eq":"body weight","tg":"forearms","mg":"grip muscles","sm":["grip muscles","biceps","lats","shoulders"],"st":["Grip the hold and pull yourself up until your elbows are at 90 degrees.","Keep your shoulders back and your core tight.","Hold for 5-10 seconds.","Lower down under control.","Rest before the next hold."],"img":"opengym/3835.webp","gif":null,"ext":1},{"id":"3836","n":"handboard hang with 135 degree elbow","bp":"lower arms","eq":"body weight","tg":"forearms","mg":"grip muscles","sm":["grip muscles","biceps","lats","shoulders"],"st":["Grip the hold and pull up slightly so your elbows bend to about 135 degrees.","Keep your shoulders back and your core tight.","Hold for 5-10 seconds.","Lower down under control.","Rest before the next hold."],"img":"opengym/3836.webp","gif":null,"ext":1},{"id":"3838","n":"crunch (on bench)","bp":"waist","eq":"body weight","tg":"abs","mg":"obliques","sm":["obliques","hip flexors","core"],"st":["Lie on a bench with your knees bent and feet flat.","Place your hands by your temples.","Curl your shoulders up, bringing your ribs toward your hips.","Pause briefly at the top.","Lower slowly without pulling on your neck."],"img":"opengym/3838.webp","gif":null,"ext":1},{"id":"3841","n":"band side bend","bp":"waist","eq":"band","tg":"obliques","mg":"core","sm":["core","lower back"],"st":["Stand on the band and hold the handle in one hand.","Keep your chest up and your hips square.","Bend sideways toward the band hand.","Return to upright.","Finish your reps, then switch sides."],"img":"opengym/3841.webp","gif":null,"ext":1},{"id":"3847","n":"band twist (up down)","bp":"waist","eq":"band","tg":"obliques","mg":"core","sm":["core","shoulders"],"st":["Anchor the band at a low point and stand side-on to it.","Hold the handle with both hands.","Rotate your torso and pull the band diagonally upward across your body.","Return slowly.","Finish your reps, then switch sides."],"img":"opengym/3847.webp","gif":null,"ext":1},{"id":"3848","n":"seated row with towel","bp":"back","eq":"body weight","tg":"upper back","mg":"lats","sm":["lats","biceps","rear deltoids","forearms"],"st":["Sit with your legs extended and loop a towel around your feet.","Hold the ends with arms straight.","Pull the towel toward your lower ribs.","Squeeze your shoulder blades together.","Extend your arms slowly."],"img":"opengym/3848.webp","gif":null,"ext":1},{"id":"3850","n":"two legs reverse biceps curl with towel v. 2","bp":"upper arms","eq":"body weight","tg":"biceps","mg":"brachialis","sm":["brachialis","forearms","grip muscles"],"st":["Lie on your back and loop a towel around both feet.","Hold the ends with an overhand grip.","Pull the towel toward your chest while your legs resist.","Pause briefly.","Lower slowly."],"img":"opengym/3850.webp","gif":null,"ext":1},{"id":"3851","n":"two legs hammer curl with towel v. 2","bp":"upper arms","eq":"body weight","tg":"biceps","mg":"brachialis","sm":["brachialis","forearms","grip muscles"],"st":["Lie on your back and loop a towel around both feet.","Hold the ends with palms facing each other.","Pull the towel toward your chest while your legs resist.","Pause briefly.","Lower slowly."],"img":"opengym/3851.webp","gif":null,"ext":1},{"id":"3852","n":"plank lateral raise","bp":"waist","eq":"body weight","tg":"abs","mg":"shoulders","sm":["shoulders","core","obliques"],"st":["Start in a high plank with your hands under your shoulders.","Brace your abs and keep your hips level.","Lift one arm out to the side to shoulder height.","Lower it with control.","Alternate arms and avoid twisting."],"img":"opengym/3852.webp","gif":null,"ext":1},{"id":"3853","n":"resistance band standing hip abduction","bp":"upper legs","eq":"resistance band","tg":"abductors","mg":"glutes","sm":["glutes","core","hip flexors"],"st":["Loop the band around your ankles or anchor it to one foot.","Stand tall holding a support if needed.","Lift one leg out to the side, keeping your toes forward.","Return slowly.","Finish your reps, then switch legs."],"img":"opengym/3853.webp","gif":null,"ext":1},{"id":"3854","n":"front plank walkout","bp":"waist","eq":"body weight","tg":"abs","mg":"shoulders","sm":["shoulders","core","hip flexors","chest"],"st":["Stand tall with your feet hip width apart.","Hinge forward and place your hands on the floor.","Walk your hands out to a front plank.","Hold briefly with your hips level.","Walk your hands back and stand up."],"img":"opengym/3854.webp","gif":null,"ext":1},{"id":"3855","n":"standing back extension and flexion","bp":"back","eq":"body weight","tg":"spine","mg":"lower back","sm":["lower back","glutes","core"],"st":["Stand with your feet hip width apart and hands on your hips.","Gently arch your back and look slightly up.","Round your back and tuck your chin.","Move slowly between positions.","Stay within a comfortable range."],"img":"opengym/3855.webp","gif":null,"ext":1},{"id":"3856","n":"resistance band smith squat","bp":"upper legs","eq":"smith machine","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","core"],"st":["Set the bar on the smith machine and attach the band as required.","Place the bar on your upper back with your feet slightly forward.","Lower into a squat until your thighs are about parallel.","Drive through your heels to stand.","Keep your chest up."],"img":"opengym/3856.webp","gif":null,"ext":1},{"id":"3857","n":"resistance band cable squat","bp":"upper legs","eq":"resistance band","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","core"],"st":["Anchor the band at chest height and hold the handles at your chest, facing away from the anchor.","Stand with feet shoulder-width apart and brace your core.","Sit your hips back and down until your thighs are about parallel to the floor.","Keep your chest tall and knees tracking over your toes.","Push through your heels to stand up.","Repeat for the desired reps."],"img":"opengym/3857.webp","gif":null,"ext":1},{"id":"3858","n":"resistance band bent over row","bp":"back","eq":"resistance band","tg":"upper back","mg":"lats","sm":["lats","rhomboids","biceps","rear deltoids"],"st":["Stand on the middle of the band with feet hip-width apart and hold an end in each hand.","Hinge at the hips with a flat back until your torso is nearly parallel to the floor.","Let your arms hang straight down.","Pull your elbows back toward your hips, squeezing your shoulder blades together.","Pause briefly, then lower with control.","Keep your neck neutral throughout."],"img":"opengym/3858.webp","gif":null,"ext":1},{"id":"3859","n":"cable bent over row","bp":"back","eq":"cable","tg":"upper back","mg":"lats","sm":["lats","rhomboids","biceps","rear deltoids"],"st":["Attach a handle or bar to a low pulley and grab it.","Step back and hinge at the hips with a flat back and soft knees.","Start with your arms extended toward the pulley.","Pull the handle toward your lower ribs, driving your elbows back.","Squeeze your shoulder blades together at the top.","Lower slowly until your arms are straight again."],"img":"opengym/3859.webp","gif":null,"ext":1},{"id":"3860","n":"weighted plate bent over row","bp":"back","eq":"weight plate","tg":"upper back","mg":"lats","sm":["lats","rhomboids","biceps","grip muscles"],"st":["Hold a weight plate firmly with both hands at its edges.","Hinge forward at the hips with a flat back and slightly bent knees.","Let the plate hang below your chest with arms extended.","Pull the plate toward your lower ribs, keeping your elbows close.","Squeeze your shoulder blades together, then lower with control.","Keep your hips still and your neck neutral."],"img":"opengym/3860.webp","gif":null,"ext":1},{"id":"3861","n":"stability ball body saw","bp":"waist","eq":"stability ball","tg":"abs","mg":"core","sm":["core","shoulders","lower back"],"st":["Place your forearms on a stability ball and extend your legs into a plank.","Squeeze your glutes and brace your abs so your body forms a straight line.","Slowly push your elbows forward a few inches by shifting your body weight.","Pull back to the start without letting your hips sag.","Keep the movement small and controlled.","Repeat for time or reps."],"img":"opengym/3861.webp","gif":null,"ext":1},{"id":"3862","n":"resistance band long jump","bp":"upper legs","eq":"resistance band","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","calves","core"],"st":["Anchor a band behind you and loop it around your hips.","Stand tall with feet shoulder-width apart and slightly bend your knees.","Swing your arms back and load your hips.","Jump forward as far as you can against the band.","Land softly on both feet with bent knees.","Reset and repeat."],"img":"opengym/3862.webp","gif":null,"ext":1},{"id":"3863","n":"bulgarian jump squat","bp":"upper legs","eq":"body weight","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","calves","core"],"st":["Stand facing away from a bench and rest the top of one foot on it.","Lower into a split squat until your front thigh is about parallel.","Drive up explosively through your front foot so it leaves the floor.","Land softly and sink straight back into the next rep.","Keep your torso upright and your front knee stable.","Finish all reps, then switch legs."],"img":"opengym/3863.webp","gif":null,"ext":1},{"id":"3864","n":"kettlebell burpee","bp":"full body","eq":"kettlebell","tg":"cardiovascular system","mg":"shoulders","sm":["shoulders","chest","quadriceps","core","glutes"],"st":["Stand with a kettlebell on the floor between your feet.","Squat down and place your hands on the floor beside it, or on the handle if you prefer.","Jump your feet back into a plank.","Lower your chest, push up, then jump your feet back in.","Grab the kettlebell and stand, then press or swing it overhead if you like.","Return it to the floor and repeat."],"img":"opengym/3864.webp","gif":null,"ext":1},{"id":"3865","n":"sprinter crunch","bp":"waist","eq":"body weight","tg":"abs","mg":"obliques","sm":["obliques","hip flexors","core"],"st":["Lie on your back with your hands lightly behind your head.","Lift your shoulders off the floor and bring one knee toward the opposite elbow.","Extend the other leg out low above the floor.","Switch sides in a smooth running rhythm.","Keep your lower back pressed down.","Continue for the set."],"img":"opengym/3865.webp","gif":null,"ext":1},{"id":"3866","n":"resistance band anti rotation dead bug","bp":"waist","eq":"resistance band","tg":"abs","mg":"obliques","sm":["obliques","core","hip flexors","shoulders"],"st":["Anchor a band at the side and lie on your back, holding the band above your chest with both hands.","Raise your knees to a tabletop position.","Brace your core so the band does not pull you sideways.","Slowly extend one leg and the opposite arm back.","Return and switch sides.","Keep your lower back flat on the floor."],"img":"opengym/3866.webp","gif":null,"ext":1},{"id":"3867","n":"duck walk","bp":"upper legs","eq":"body weight","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","calves","core"],"st":["Lower into a deep squat with your chest up.","Place your hands on your hips or in front of you for balance.","Step forward with one foot, keeping the squat low.","Step with the other foot and continue walking.","Keep your heels down and your back straight.","Walk for a set distance or time."],"img":"opengym/3867.webp","gif":null,"ext":1},{"id":"3868","n":"cable fly with chest supported","bp":"chest","eq":"cable","tg":"pectorals","mg":"upper chest","sm":["upper chest","shoulders","biceps"],"st":["Set the pulleys at about shoulder height and position an incline bench facing the stack, chest against the pad.","Hold a handle in each hand with arms out to the sides.","With a slight bend in your elbows, sweep your arms forward in a wide arc.","Squeeze your chest as the handles meet.","Return slowly until you feel a stretch across the chest."],"img":"opengym/3868.webp","gif":null,"ext":1},{"id":"3869","n":"cable seated chest fly","bp":"chest","eq":"cable","tg":"pectorals","mg":"upper chest","sm":["upper chest","shoulders","biceps"],"st":["Sit on a bench between two cable stacks with the pulleys at chest height.","Grab a handle in each hand and hold your arms out with soft elbows.","Press your back firmly into the bench.","Bring your hands together in front of your chest in a wide arc.","Squeeze, then open your arms slowly.","Stop when you feel a good stretch."],"img":"opengym/3869.webp","gif":null,"ext":1},{"id":"3870","n":"frog reverse hyperextension (on a bench)","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"hamstrings","sm":["hamstrings","lower back","adductors"],"st":["Lie face down on a bench with your hips at the edge and hold the bench for support.","Let your legs hang and bring the soles of your feet together, knees out.","Squeeze your glutes and lift your legs up behind you.","Pause when your thighs are in line with your torso.","Lower slowly and repeat.","Avoid arching your lower back too far."],"img":"opengym/3870.webp","gif":null,"ext":1},{"id":"3871","n":"barbell front chest squat with resistance band","bp":"upper legs","eq":"barbell","tg":"quads","mg":"glutes","sm":["glutes","core","hamstrings","upper back"],"st":["Set up a band under your feet or anchored to the floor and attach it to the bar.","Rest the bar on your front shoulders with elbows high.","Stand with feet shoulder-width apart and brace your core.","Squat down until your thighs are about parallel.","Drive up through your heels against the band tension.","Keep your chest tall throughout."],"img":"opengym/3871.webp","gif":null,"ext":1},{"id":"3872","n":"heel drops","bp":"lower legs","eq":"body weight","tg":"calves","mg":"soleus","sm":["soleus","ankles","feet"],"st":["Stand on the edge of a step with the balls of your feet on it.","Hold a rail for balance.","Rise onto your toes.","Slowly lower your heels below the step level.","Pause and feel the stretch in your calves.","Raise up and repeat."],"img":"opengym/3872.webp","gif":null,"ext":1},{"id":"3873","n":"barbell hip thrust with resistance band","bp":"upper legs","eq":"barbell","tg":"glutes","mg":"hamstrings","sm":["hamstrings","quadriceps","core","adductors"],"st":["Sit with your upper back against a bench and the loaded bar across your hips.","Set a band over your hips or around your thighs as the setup allows.","Plant your feet hip-width apart.","Drive your hips up until your torso is level with the floor.","Squeeze your glutes at the top.","Lower with control and repeat."],"img":"opengym/3873.webp","gif":null,"ext":1},{"id":"3874","n":"smith kneeling hip thrust","bp":"upper legs","eq":"smith machine","tg":"glutes","mg":"hamstrings","sm":["hamstrings","core","quadriceps"],"st":["Set the bar on the Smith machine at a low height and kneel facing away from it.","Place the bar across your hips with a pad for comfort.","Keep your torso upright and your core braced.","Thrust your hips forward and squeeze your glutes.","Slowly return to the start.","Keep your ribs down and avoid leaning back."],"img":"opengym/3874.webp","gif":null,"ext":1},{"id":"3875","n":"resistance band 45 degrees hyperextension","bp":"upper legs","eq":"resistance band","tg":"spine","mg":"glutes","sm":["glutes","hamstrings","core"],"st":["Set up on a 45 degree hyperextension bench with your hips just over the pad.","Loop a band across your upper back and under your feet or the base.","Cross your arms over your chest or hold them lightly.","Lower your torso with a straight back.","Raise your torso until your body is in a straight line.","Do not over-arch at the top."],"img":"opengym/3875.webp","gif":null,"ext":1},{"id":"3876","n":"weighted squat jump with plate","bp":"upper legs","eq":"weight plate","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","calves","core"],"st":["Hold a weight plate close to your chest.","Stand with feet shoulder-width apart.","Squat down until your thighs are near parallel.","Jump up explosively, extending your hips, knees and ankles.","Land softly and go straight into the next rep.","Keep your chest up throughout."],"img":"opengym/3876.webp","gif":null,"ext":1},{"id":"3877","n":"medicine ball squat jump","bp":"upper legs","eq":"medicine ball","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","calves","core"],"st":["Hold a medicine ball at your chest with both hands.","Stand with feet shoulder-width apart.","Sink into a squat with your chest up.","Jump up as high as you can.","Land softly with bent knees.","Reset and repeat."],"img":"opengym/3877.webp","gif":null,"ext":1},{"id":"3878","n":"resistance band jump squat","bp":"upper legs","eq":"band","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","calves","core"],"st":["Stand on a band with feet shoulder-width apart and hold the other end at your shoulders.","Squat down until your thighs are about parallel.","Jump up explosively against the band.","Land softly through your toes and heels.","Sink immediately into the next squat.","Keep your knees in line with your toes."],"img":"opengym/3878.webp","gif":null,"ext":1},{"id":"3879","n":"dumbbell poliquin lateral raise","bp":"shoulders","eq":"dumbbell","tg":"delts","mg":"trapezius","sm":["trapezius","rotator cuff","upper back"],"st":["Hold a dumbbell in each hand, standing with a slight forward lean.","Start with the dumbbells in front of your thighs, palms facing in.","Raise your arms out and up in a slight arc until about shoulder height.","Lead with your elbows and keep your wrists neutral.","Pause briefly, then lower slowly.","Avoid swinging your torso."],"img":"opengym/3879.webp","gif":null,"ext":1},{"id":"3880","n":"cable leaning lateral raise","bp":"shoulders","eq":"cable","tg":"delts","mg":"trapezius","sm":["trapezius","rotator cuff","upper back"],"st":["Stand sideways to a low pulley and hold the handle with the far hand.","Hold the upright support with the other hand and lean away from the machine.","Start with your working arm across your body.","Raise it out to shoulder height with a soft elbow.","Lower slowly under control.","Finish your reps, then switch sides."],"img":"opengym/3880.webp","gif":null,"ext":1},{"id":"3881","n":"lever seated full crunch","bp":"waist","eq":"leverage machine","tg":"abs","mg":"obliques","sm":["obliques","hip flexors","core"],"st":["Adjust the seat and sit with the pads in position.","Hold the handles and keep your feet planted.","Exhale and curl your torso forward, bringing your ribs toward your hips.","Squeeze your abs at the bottom.","Return slowly to the start.","Keep your hips on the seat."],"img":"opengym/3881.webp","gif":null,"ext":1},{"id":"3882","n":"lever seated left side crunch","bp":"waist","eq":"leverage machine","tg":"obliques","mg":"core","sm":["core","hip flexors"],"st":["Sit in the machine with the pads positioned for a left side crunch.","Hold the handles and brace your core.","Exhale and crunch your torso toward the left.","Squeeze your side at the bottom.","Return slowly to the start.","Avoid using momentum."],"img":"opengym/3882.webp","gif":null,"ext":1},{"id":"3883","n":"lever seated right side crunch","bp":"waist","eq":"leverage machine","tg":"obliques","mg":"core","sm":["core","hip flexors"],"st":["Sit in the machine with the pads positioned for a right side crunch.","Hold the handles and brace your core.","Exhale and crunch your torso toward the right.","Squeeze your side at the bottom.","Return slowly to the start.","Avoid using momentum."],"img":"opengym/3883.webp","gif":null,"ext":1},{"id":"3885","n":"double under jump rope","bp":"full body","eq":"rope","tg":"cardiovascular system","mg":"calves","sm":["calves","forearms","shoulders","core"],"st":["Hold the rope handles at your hips with your elbows close.","Stand tall and start with a few normal jumps.","Jump a little higher and spin the rope faster with your wrists.","Let the rope pass twice under your feet before landing.","Land softly on the balls of your feet.","Keep your jumps small and your body upright."],"img":"opengym/3885.webp","gif":null,"ext":1},{"id":"3886","n":"dumbbell complex push up row clean and press","bp":"full body","eq":"dumbbell","tg":"cardiovascular system","mg":"chest","sm":["chest","upper back","shoulders","triceps","glutes"],"st":["Start in a push-up position with your hands on two dumbbells.","Do a push-up, then row one dumbbell to your ribs and switch sides.","Jump or step your feet toward your hands and stand up, cleaning the dumbbells to your shoulders.","Press them overhead.","Lower to the floor and return to the push-up position.","Move smoothly and keep your core tight."],"img":"opengym/3886.webp","gif":null,"ext":1},{"id":"3887","n":"jump box over","bp":"upper legs","eq":"body weight","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","calves","core"],"st":["Stand facing a sturdy box with feet shoulder-width apart.","Swing your arms back and load your hips.","Jump onto the box and land softly with bent knees.","Step or hop down on the other side.","Turn around and repeat in the other direction.","Reset your balance between reps."],"img":"opengym/3887.webp","gif":null,"ext":1},{"id":"3889","n":"frog sit up","bp":"waist","eq":"body weight","tg":"abs","mg":"hip flexors","sm":["hip flexors","obliques","inner thighs"],"st":["Lie on your back with the soles of your feet together and knees falling out.","Place your hands behind your head or reach forward.","Curl up and sit all the way up.","Reach your hands toward your feet at the top.","Lower with control.","Avoid pulling on your neck."],"img":"opengym/3889.webp","gif":null,"ext":1},{"id":"3890","n":"hanging knees to elbows","bp":"waist","eq":"body weight","tg":"abs","mg":"hip flexors","sm":["hip flexors","grip muscles","lats","obliques"],"st":["Hang from a pull-up bar with a firm grip.","Brace your core and tuck your knees.","Raise your knees up toward your elbows.","Curl your pelvis up at the top.","Lower slowly without swinging.","Repeat for the desired reps."],"img":"opengym/3890.webp","gif":null,"ext":1},{"id":"3891","n":"hanging toes to bar","bp":"waist","eq":"body weight","tg":"abs","mg":"hip flexors","sm":["hip flexors","grip muscles","lats","obliques"],"st":["Hang from a bar with a firm grip.","Engage your lats and brace your core.","Raise your straight legs up until your toes touch the bar.","Pause briefly at the top.","Lower your legs with control.","Avoid excessive swinging."],"img":"opengym/3891.webp","gif":null,"ext":1},{"id":"3893","n":"assault bike run","bp":"cardio","eq":"stationary bike","tg":"cardiovascular system","mg":"quadriceps","sm":["quadriceps","glutes","hamstrings","shoulders","core"],"st":["Adjust the seat height and sit on the bike.","Grip the handles and push and pull with your arms.","Pedal at a steady, strong pace.","Increase the effort for intervals.","Keep your breathing controlled.","Ride for a set time or distance."],"img":"opengym/3893.webp","gif":null,"ext":1},{"id":"3894","n":"dumbbell stiff leg deadlift v. 3","bp":"upper legs","eq":"dumbbell","tg":"hamstrings","mg":"glutes","sm":["glutes","lower back","grip muscles"],"st":["Stand holding a dumbbell in each hand in front of your thighs.","Keep your knees almost straight.","Hinge at the hips and slide the weights down your legs.","Stop when you feel a stretch in the hamstrings.","Drive your hips forward to stand, keeping your back flat."],"img":"opengym/3894.webp","gif":null,"ext":1},{"id":"3896","n":"band seated row","bp":"back","eq":"band","tg":"upper back","mg":"lats","sm":["lats","rhomboids","biceps","rear deltoids"],"st":["Sit on the floor with your legs extended and loop a band around your feet.","Hold the ends with your arms extended.","Sit tall with your chest up.","Pull your elbows back and squeeze your shoulder blades together.","Slowly extend your arms.","Keep your shoulders away from your ears."],"img":"opengym/3896.webp","gif":null,"ext":1},{"id":"3903","n":"resistance band one leg kickback (bent position)","bp":"upper legs","eq":"resistance band","tg":"glutes","mg":"hamstrings","sm":["hamstrings","lower back","core"],"st":["Loop a resistance band around your ankle and anchor the other end low in front of you.","Hold a support and lean forward slightly.","Brace your core and keep your hips level.","Kick your leg back and up against the band.","Squeeze your glute at the top.","Return slowly, then switch legs after your reps."],"img":"opengym/3903.webp","gif":null,"ext":1},{"id":"3904","n":"pike press (between benches)","bp":"shoulders","eq":"body weight","tg":"delts","mg":"triceps","sm":["triceps","upper chest","trapezius","core"],"st":["Place your hands on two benches shoulder-width apart and your feet on the floor.","Lift your hips into a pike shape.","Bend your elbows and lower your head between the benches.","Press back up to straight arms.","Keep your core tight.","Keep your hips high throughout."],"img":"opengym/3904.webp","gif":null,"ext":1},{"id":"3905","n":"arm circles","bp":"shoulders","eq":"body weight","tg":"delts","mg":"rotator cuff","sm":["rotator cuff","trapezius","upper back"],"st":["Stand tall with your arms out to the sides at shoulder height.","Make small circles forward.","Gradually make the circles larger.","Do 10 to 15 circles, then reverse direction.","Keep your shoulders relaxed.","Breathe normally."],"img":"opengym/3905.webp","gif":null,"ext":1},{"id":"3906","n":"bodyweight kneeling push up row","bp":"chest","eq":"body weight","tg":"pectorals","mg":"upper back","sm":["upper back","triceps","shoulders","core"],"st":["Start in a kneeling push-up position with your hands on the floor, or on light dumbbells.","Lower your chest to the floor.","Push back up.","Pull one elbow toward your ribs.","Return that hand to the floor and alternate sides.","Keep your hips level."],"img":"opengym/3906.webp","gif":null,"ext":1},{"id":"3908","n":"bodyweight windmill","bp":"waist","eq":"body weight","tg":"obliques","mg":"abdominals","sm":["abdominals","hamstrings","shoulders","lower back"],"st":["Stand with feet wider than shoulder-width and one arm overhead.","Turn your feet slightly outward.","Hinge at the hips and rotate your torso toward the floor.","Reach your free hand toward the opposite foot.","Return to standing with control.","Switch sides after your reps."],"img":"opengym/3908.webp","gif":null,"ext":1},{"id":"3910","n":"weighted push up with vest","bp":"chest","eq":"weighted","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders","core"],"st":["Put on a weighted vest and start in a plank with hands under shoulders.","Brace your core and glutes.","Lower your chest to the floor with elbows at about 45 degrees.","Press back up to straight arms.","Keep your body in a straight line.","Repeat for the set."],"img":"opengym/3910.webp","gif":null,"ext":1},{"id":"3911","n":"dumbbell low fly","bp":"chest","eq":"dumbbell","tg":"pectorals","mg":"upper chest","sm":["upper chest","shoulders","biceps"],"st":["Lie on a flat bench or stand and hold dumbbells with palms facing each other.","Keep a slight bend in your elbows.","Move the dumbbells in a wide arc.","Bring them together in front of your lower chest.","Squeeze your chest.","Lower slowly under control."],"img":"opengym/3911.webp","gif":null,"ext":1},{"id":"3912","n":"cable bent over one arm lateral raise","bp":"shoulders","eq":"cable","tg":"delts","mg":"rear deltoids","sm":["rear deltoids","upper back","trapezius"],"st":["Stand next to a low pulley and bend forward at the hips with a flat back.","Grab the handle with the far hand.","Raise your arm out to the side with a soft elbow.","Lift to shoulder height.","Lower slowly.","Switch sides after your reps."],"img":"opengym/3912.webp","gif":null,"ext":1},{"id":"3913","n":"dumbbell one arm front raise","bp":"shoulders","eq":"dumbbell","tg":"delts","mg":"upper chest","sm":["upper chest","trapezius","core"],"st":["Stand with a dumbbell in one hand in front of your thigh.","Keep your core braced.","Raise your arm forward to shoulder height.","Pause at the top.","Lower slowly.","Switch arms after your reps."],"img":"opengym/3913.webp","gif":null,"ext":1},{"id":"3914","n":"cable rear delt row","bp":"shoulders","eq":"cable","tg":"delts","mg":"rear deltoids","sm":["rear deltoids","upper back","rhomboids","trapezius"],"st":["Set a cable at chest height with a handle or rope.","Hold it with your arms extended.","Step back and lean slightly.","Pull the handle toward your upper chest with your elbows flared out.","Squeeze your rear delts.","Return slowly."],"img":"opengym/3914.webp","gif":null,"ext":1},{"id":"3915","n":"decline pike press (between benches)","bp":"shoulders","eq":"body weight","tg":"delts","mg":"triceps","sm":["triceps","upper chest","trapezius","core"],"st":["Place your hands on two benches and your feet on a higher surface behind you.","Lift your hips into a pike.","Bend your elbows and lower your head between the benches.","Press up to straight arms.","Keep your core tight.","Control the descent."],"img":"opengym/3915.webp","gif":null,"ext":1},{"id":"3916","n":"handstand shoulder press with wall (between benches)","bp":"shoulders","eq":"body weight","tg":"delts","mg":"triceps","sm":["triceps","trapezius","core","upper chest"],"st":["Place your hands on two benches and kick up into a handstand with your heels against the wall.","Brace your core and keep your body straight.","Lower your head between the benches by bending your elbows.","Press back up to straight arms.","Keep the movement controlled.","Come down carefully when done."],"img":"opengym/3916.webp","gif":null,"ext":1},{"id":"3917","n":"barbell reverse grip floor press","bp":"upper arms","eq":"barbell","tg":"triceps","mg":"chest","sm":["chest","upper chest","shoulders","forearms"],"st":["Lie on the floor with a barbell above your chest, hands in an underhand grip.","Plant your feet and brace your core.","Lower the bar until your upper arms touch the floor.","Pause briefly.","Press the bar back up.","Keep your wrists straight."],"img":"opengym/3917.webp","gif":null,"ext":1},{"id":"3918","n":"landmine single leg landmine rdl","bp":"upper legs","eq":"landmine","tg":"hamstrings","mg":"glutes","sm":["glutes","lower back","core"],"st":["Hold the end of a landmine bar with both hands.","Stand on one leg with a soft knee.","Hinge at the hips and extend the other leg behind you.","Lower the bar toward the floor with a flat back.","Squeeze your glute to stand.","Switch legs after your reps."],"img":"opengym/3918.webp","gif":null,"ext":1},{"id":"3919","n":"landmine rear lunge","bp":"upper legs","eq":"landmine","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","core"],"st":["Hold the end of a landmine bar at your chest.","Stand tall with feet hip-width apart.","Step one foot back and lower into a lunge.","Keep your front knee over your ankle.","Push through the front foot to stand.","Alternate legs."],"img":"opengym/3919.webp","gif":null,"ext":1},{"id":"3920","n":"cable triceps pushdown on floor","bp":"upper arms","eq":"cable","tg":"triceps","mg":"forearms","sm":["forearms","shoulders","core"],"st":["Set a cable at a low or mid position and sit on the floor facing it.","Hold the handle with elbows tucked at your sides.","Press the handle down until your arms are straight.","Squeeze your triceps.","Return slowly to the start.","Keep your upper arms still."],"img":"opengym/3920.webp","gif":null,"ext":1},{"id":"3921","n":"landmine kneeling squeeze press","bp":"chest","eq":"landmine","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders","core"],"st":["Kneel facing the landmine and hold the bar end close to your chest with both hands pressed together.","Brace your core.","Press the bar forward and up.","Squeeze your hands together as you press.","Lower it slowly.","Keep your torso upright."],"img":"opengym/3921.webp","gif":null,"ext":1},{"id":"3922","n":"side push up with towel","bp":"chest","eq":"body weight","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders","core","obliques"],"st":["Start in a push-up position with one hand on a towel on the floor.","Slide that hand out to the side.","Lower your chest toward the other hand.","Push back up.","Slide the towel hand back in.","Switch sides."],"img":"opengym/3922.webp","gif":null,"ext":1},{"id":"3923","n":"landmine floor one arm chest fly","bp":"chest","eq":"landmine","tg":"pectorals","mg":"upper chest","sm":["upper chest","shoulders","core"],"st":["Lie on the floor holding the landmine bar end with one hand.","Extend the arm above your chest.","Lower the bar out to the side in an arc.","Stop when your arm touches the floor.","Squeeze your chest to bring the bar back up.","Switch sides."],"img":"opengym/3923.webp","gif":null,"ext":1},{"id":"3924","n":"floor fly with towels","bp":"chest","eq":"body weight","tg":"pectorals","mg":"shoulders","sm":["shoulders","core","triceps"],"st":["Kneel or get into a plank with your hands on towels.","Slide your hands out wide to the sides.","Lower your chest toward the floor.","Squeeze your chest to slide your hands back together.","Keep your core tight.","Do not let your hips sag."],"img":"opengym/3924.webp","gif":null,"ext":1},{"id":"3925","n":"cable seated floor one arm concentration curl","bp":"upper arms","eq":"cable","tg":"biceps","mg":"brachialis","sm":["brachialis","forearms"],"st":["Sit on the floor facing a low cable with a handle in one hand.","Brace your elbow against your inner thigh.","Curl the handle toward your shoulder.","Squeeze your biceps.","Lower slowly.","Switch arms."],"img":"opengym/3925.webp","gif":null,"ext":1},{"id":"3926","n":"side lying leg circle","bp":"upper legs","eq":"body weight","tg":"abductors","mg":"glutes","sm":["glutes","hip flexors","adductors","core"],"st":["Lie on your side with your legs stacked.","Lift the top leg slightly.","Draw small circles in the air.","Do 10 circles, then reverse direction.","Keep your pelvis still.","Switch sides."],"img":"opengym/3926.webp","gif":null,"ext":1},{"id":"3927","n":"squat tip toe","bp":"upper legs","eq":"body weight","tg":"quads","mg":"calves","sm":["calves","glutes","hamstrings","core"],"st":["Stand with feet shoulder-width apart and rise onto your toes.","Hold your arms in front for balance.","Squat down while staying up on your toes.","Pause at the bottom.","Stand back up.","Keep your chest tall."],"img":"opengym/3927.webp","gif":null,"ext":1},{"id":"3928","n":"bodyweight single leg deadlift","bp":"upper legs","eq":"body weight","tg":"hamstrings","mg":"glutes","sm":["glutes","lower back","core"],"st":["Stand on one foot with a soft knee and your arms hanging in front.","Hinge at the hips and extend the free leg straight behind you.","Lower your torso until it is nearly parallel to the floor, back flat.","Squeeze your glute to stand tall again.","Finish your reps, then switch legs."],"img":"opengym/3928.webp","gif":null,"ext":1},{"id":"3929","n":"standing side leg raise","bp":"upper legs","eq":"body weight","tg":"abductors","mg":"glutes","sm":["glutes","obliques"],"st":["Stand tall, hands on your hips or on a support.","Keep your toes pointing forward and lift one leg out to the side.","Raise it as high as you can without leaning your torso.","Lower with control and repeat, then switch legs."],"img":"opengym/3929.webp","gif":null,"ext":1},{"id":"3930","n":"plank jack","bp":"waist","eq":"body weight","tg":"abs","mg":"shoulders","sm":["shoulders","glutes","hip flexors"],"st":["Start in a forearm or high plank with your body in a straight line.","Jump both feet out wide.","Jump them back together.","Keep your hips level and your abs tight throughout.","Continue for the planned reps or time."],"img":"opengym/3930.webp","gif":null,"ext":1},{"id":"3935","n":"decline push up (kneeling)","bp":"chest","eq":"body weight","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders","core"],"st":["Kneel with your knees on a bench or step and hands on the floor.","Keep a straight line from head to knees.","Lower your chest toward the floor.","Press back up.","Keep your core tight and your elbows at about 45 degrees."],"img":"opengym/3935.webp","gif":null,"ext":1},{"id":"3939","n":"band overhead triceps extension","bp":"upper arms","eq":"band","tg":"triceps","mg":"shoulders","sm":["shoulders","core"],"st":["Anchor the band low or stand on it and hold the other end behind your head.","Keep your elbows pointing up and close to your ears.","Straighten your arms overhead.","Bend the elbows slowly to return.","Keep your upper arms still and your ribs down."],"img":"opengym/3939.webp","gif":null,"ext":1},{"id":"3942","n":"romanian chair sit up v. 2","bp":"waist","eq":"body weight","tg":"abs","mg":"hip flexors","sm":["hip flexors","lower back"],"st":["Sit on the floor and rest your lower legs on a chair or bench, knees bent.","Cross your arms over your chest.","Curl your torso up until your chest nears your knees.","Lower slowly back to the floor.","Do not pull on your neck."],"img":"opengym/3942.webp","gif":null,"ext":1},{"id":"3943","n":"cable seated rear delt fly with chest support","bp":"shoulders","eq":"cable","tg":"delts","mg":"rear deltoids","sm":["rear deltoids","rhomboids","upper back"],"st":["Sit facing the stack with your chest against the pad and hold the handles.","Start with your arms forward and elbows slightly bent.","Sweep your arms out and back to shoulder height.","Pause, then return slowly.","Keep your neck relaxed."],"img":"opengym/3943.webp","gif":null,"ext":1},{"id":"3944","n":"seated alternate crunch","bp":"waist","eq":"body weight","tg":"abs","mg":"obliques","sm":["obliques","hip flexors"],"st":["Sit on the floor, lean back slightly and lift your feet.","Place your hands behind your head.","Bring one knee in while rotating your torso toward it.","Return and repeat on the other side.","Keep your chest open and move with control."],"img":"opengym/3944.webp","gif":null,"ext":1},{"id":"3945","n":"smith single arm bent over row","bp":"back","eq":"smith machine","tg":"upper back","mg":"lats","sm":["lats","biceps","rhomboids"],"st":["Set the bar at a low height and hinge at the hips with a flat back.","Grip the bar with one hand and brace the other on your thigh.","Pull the bar toward your lower ribs.","Lower it under control.","Finish your reps, then switch arms."],"img":"opengym/3945.webp","gif":null,"ext":1},{"id":"3946","n":"dumbbell seated upright alternate squeeze press","bp":"chest","eq":"dumbbell","tg":"pectorals","mg":"triceps","sm":["triceps","upper chest","shoulders"],"st":["Sit upright with a dumbbell in each hand, pressed together in front of your chest.","Keep the two dumbbells touching.","Press one dumbbell forward until the arm is straight.","Bring it back and press with the other arm.","Keep squeezing the weights together."],"img":"opengym/3946.webp","gif":null,"ext":1},{"id":"3947","n":"hands release push up","bp":"chest","eq":"body weight","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders","core"],"st":["Start in a high plank with hands under shoulders.","Lower your whole body to the floor.","Lift your hands off the floor briefly.","Place them back and press up.","Keep your body in a straight line."],"img":"opengym/3947.webp","gif":null,"ext":1},{"id":"3948","n":"air squat","bp":"upper legs","eq":"body weight","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","core"],"st":["Stand with feet shoulder-width apart.","Reach your arms forward for balance.","Sit your hips back and down until your thighs are parallel.","Keep your chest up.","Drive through your feet to stand."],"img":"opengym/3948.webp","gif":null,"ext":1},{"id":"3950","n":"crawl to crab","bp":"full body","eq":"body weight","tg":"abs","mg":"shoulders","sm":["shoulders","triceps","glutes","core"],"st":["Start on hands and knees.","Lift your knees slightly into a low crawl.","Rotate your body and sit back into a crab position, face up.","Lift your hips.","Rotate back into the crawl and repeat."],"img":"opengym/3950.webp","gif":null,"ext":1},{"id":"3952","n":"high knees lunge","bp":"cardio","eq":"body weight","tg":"cardiovascular system","mg":"quadriceps","sm":["quadriceps","glutes","hip flexors"],"st":["Stand tall.","Step forward into a lunge.","Push off and drive the back knee up high.","Step back and repeat on the other side.","Keep your pace steady for 30-60 seconds."],"img":"opengym/3952.webp","gif":null,"ext":1},{"id":"3954","n":"front to side plank","bp":"waist","eq":"body weight","tg":"obliques","mg":"shoulders","sm":["shoulders","core"],"st":["Start in a front plank on your forearms or hands.","Rotate your body to one side, lifting one arm up.","Hold briefly in a side plank.","Return to the front plank.","Alternate sides."],"img":"opengym/3954.webp","gif":null,"ext":1},{"id":"3956","n":"twist step stretch","bp":"upper legs","eq":"body weight","tg":"quads","mg":"hip flexors","sm":["hip flexors","obliques","glutes"],"st":["Stand tall.","Step forward into a lunge.","Twist your torso toward the front leg.","Return to centre and step back.","Alternate sides for 8-10 reps each."],"img":"opengym/3956.webp","gif":null,"ext":1},{"id":"3958","n":"side step front plank","bp":"waist","eq":"body weight","tg":"abs","mg":"obliques","sm":["obliques","shoulders","core"],"st":["Start in a high plank.","Step one hand and foot out to the side.","Bring the other hand and foot to meet them.","Keep your hips level.","Repeat in one direction, then reverse."],"img":"opengym/3958.webp","gif":null,"ext":1},{"id":"3959","n":"forward step front plank","bp":"waist","eq":"body weight","tg":"abs","mg":"shoulders","sm":["shoulders","core","hip flexors"],"st":["Start in a high plank.","Step one hand forward, then the other.","Follow with your feet.","Keep your hips level.","Walk forward a few steps, then back."],"img":"opengym/3959.webp","gif":null,"ext":1},{"id":"3960","n":"pike to cobra","bp":"shoulders","eq":"body weight","tg":"delts","mg":"triceps","sm":["triceps","core","lower back"],"st":["Start on hands and toes with your hips high in an inverted V.","Bend your elbows and glide your chest forward and down between your hands.","Sweep forward and up, straightening your arms and lifting your chest into a cobra.","Keep your legs active and look slightly forward.","Reverse the path, pushing your hips back up into the pike, and repeat smoothly."],"img":"opengym/3960.webp","gif":null,"ext":1},{"id":"3961","n":"forward to side to rear lunge","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","adductors","core"],"st":["Stand tall with your feet together and hands on your hips.","Step one foot forward into a lunge, then push back to standing.","Step the same foot out to the side, sit back into the hip, then return to center.","Step the same foot backward into a lunge and push back to standing.","Keep your chest up and knees tracking over your toes, then switch legs after your set."],"img":"opengym/3961.webp","gif":null,"ext":1},{"id":"3962","n":"seated flutter kick","bp":"waist","eq":"body weight","tg":"abs","mg":"hip flexors","sm":["hip flexors","lower abs"],"st":["Sit with your hands behind you and lean back slightly.","Lift both legs off the floor.","Kick your legs up and down in short alternating moves.","Keep your core tight and your back from rounding.","Continue for time."],"img":"opengym/3962.webp","gif":null,"ext":1},{"id":"3963","n":"dumbbell single spider curl with chest support","bp":"upper arms","eq":"dumbbell","tg":"biceps","mg":"brachialis","sm":["brachialis","forearms"],"st":["Lie chest down on an incline bench with one arm hanging, dumbbell in hand.","Keep your upper arm vertical.","Curl the weight up toward your shoulder.","Squeeze, then lower fully.","Finish your reps, then switch arms."],"img":"opengym/3963.webp","gif":null,"ext":1},{"id":"3964","n":"twist push up","bp":"chest","eq":"body weight","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders","obliques"],"st":["Start in a high plank with hands under your shoulders.","Lower your chest to the floor.","Push up and rotate one arm toward the ceiling.","Return the hand to the floor.","Alternate sides each rep."],"img":"opengym/3964.webp","gif":null,"ext":1},{"id":"3965","n":"side bear crawl","bp":"full body","eq":"body weight","tg":"quads","mg":"shoulders","sm":["shoulders","core","glutes"],"st":["Get on hands and toes with knees just off the floor.","Keep your back flat.","Step the hand and foot on one side out, then bring the other pair along.","Move several steps one way, then return.","Stay low and keep your hips steady."],"img":"opengym/3965.webp","gif":null,"ext":1},{"id":"3966","n":"static lunge kick","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","hip flexors"],"st":["Step into a lunge with your front knee over your ankle.","Lower down until both knees are bent.","Drive up through the front foot.","Swing the back leg forward in a kick.","Return to the lunge and repeat, then switch legs."],"img":"opengym/3966.webp","gif":null,"ext":1},{"id":"3967","n":"dumbbell incline around the world","bp":"shoulders","eq":"dumbbell","tg":"delts","mg":"chest","sm":["chest","upper chest","upper back"],"st":["Lie back on an incline bench holding dumbbells over your chest.","Keep your arms nearly straight.","Lower them out to the sides in a wide arc.","Continue down to your hips.","Reverse the arc to return."],"img":"opengym/3967.webp","gif":null,"ext":1},{"id":"3968","n":"dumbbell flat around the world","bp":"shoulders","eq":"dumbbell","tg":"delts","mg":"chest","sm":["chest","upper back","lats"],"st":["Lie on a flat bench with dumbbells over your chest.","Keep your arms nearly straight.","Lower them out and back in a wide arc.","Take them down toward your hips.","Reverse the arc with control."],"img":"opengym/3968.webp","gif":null,"ext":1},{"id":"3969","n":"tuck up","bp":"waist","eq":"body weight","tg":"abs","mg":"hip flexors","sm":["hip flexors","lower abs"],"st":["Sit on the floor, lean back slightly and hold the floor or your sides for support.","Extend your legs out in front, hovering just above the floor.","Pull your knees toward your chest while curling your torso forward.","Pause briefly at the top with your abs tight.","Extend back out under control without letting your feet touch down, and repeat."],"img":"opengym/3969.webp","gif":null,"ext":1},{"id":"3970","n":"jack burpee with push up","bp":"full body","eq":"body weight","tg":"cardiovascular system","mg":"chest","sm":["chest","triceps","quadriceps","core","shoulders"],"st":["Stand with your feet shoulder-width apart.","Squat down, place your hands on the floor and jump your feet back into a plank.","Lower your chest to the floor in a push-up and press back up.","Jump your feet back toward your hands.","Explode up into a jumping jack, landing softly, then flow into the next rep."],"img":"opengym/3970.webp","gif":null,"ext":1},{"id":"3971","n":"band bent over rear lateral raise","bp":"shoulders","eq":"band","tg":"delts","mg":"rear deltoids","sm":["rear deltoids","rhomboids","upper back"],"st":["Stand on the band and hinge forward with a flat back.","Hold the band ends with arms hanging.","Raise your arms out to the sides to shoulder height.","Pause, then lower slowly.","Keep your elbows slightly bent."],"img":"opengym/3971.webp","gif":null,"ext":1},{"id":"3972","n":"dumbbell alternate shoulder press","bp":"shoulders","eq":"dumbbell","tg":"delts","mg":"triceps","sm":["triceps","upper chest","core"],"st":["Stand or sit with dumbbells at shoulder height.","Press one dumbbell overhead until the arm is straight.","Lower it back to your shoulder.","Press with the other arm.","Brace your core and avoid leaning back."],"img":"opengym/3972.webp","gif":null,"ext":1},{"id":"3973","n":"dumbbell single leg calf raise v. 2","bp":"lower legs","eq":"dumbbell","tg":"calves","mg":"soleus","sm":["soleus","ankles","feet"],"st":["Hold a dumbbell in one hand and stand on the ball of the opposite foot, ideally on a step.","Rest your free hand on a wall or rail for balance.","Lift your heel as high as you can, squeezing the calf.","Pause for a moment at the top.","Lower your heel slowly below the step level, then repeat and switch legs."],"img":"opengym/3973.webp","gif":null,"ext":1},{"id":"3977","n":"push up toe touch","bp":"chest","eq":"body weight","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders","core"],"st":["Start in a high plank.","Lower your chest and push back up.","Lift your hips and reach one hand to the opposite foot.","Return to plank.","Alternate hands each rep."],"img":"opengym/3977.webp","gif":null,"ext":1},{"id":"3978","n":"seated side to side leg raise crunch on floor","bp":"waist","eq":"body weight","tg":"abs","mg":"obliques","sm":["obliques","hip flexors"],"st":["Sit and lean back on your hands, legs lifted.","Swing both knees to one side while crunching in.","Return through the middle.","Swing to the other side.","Keep the motion smooth and controlled."],"img":"opengym/3978.webp","gif":null,"ext":1},{"id":"3979","n":"cross body push up","bp":"chest","eq":"body weight","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders","core"],"st":["Start in a high plank.","Lower into a push up.","Push up and cross one hand over toward the other side.","Place it down and repeat.","Alternate the crossing hand."],"img":"opengym/3979.webp","gif":null,"ext":1},{"id":"3980","n":"dumbbell incline front raise with chest support","bp":"shoulders","eq":"dumbbell","tg":"delts","mg":"upper chest","sm":["upper chest","upper back"],"st":["Lie chest down on an incline bench with dumbbells hanging.","Keep a soft bend in the elbows.","Raise the weights forward to shoulder height.","Lower slowly.","Keep your chest against the pad."],"img":"opengym/3980.webp","gif":null,"ext":1},{"id":"3981","n":"finger push up","bp":"chest","eq":"body weight","tg":"pectorals","mg":"triceps","sm":["triceps","forearms","grip muscles"],"st":["Get into a high plank on your fingertips.","Keep your body straight.","Lower your chest to the floor.","Press up.","Reduce the range if your fingers tire."],"img":"opengym/3981.webp","gif":null,"ext":1},{"id":"3982","n":"leg lift to chest front plank","bp":"waist","eq":"body weight","tg":"abs","mg":"hip flexors","sm":["hip flexors","shoulders","glutes"],"st":["Start in a high plank.","Draw one knee toward your chest.","Return it to the floor.","Alternate legs.","Keep your hips level."],"img":"opengym/3982.webp","gif":null,"ext":1},{"id":"3983","n":"one arm front plank","bp":"waist","eq":"body weight","tg":"abs","mg":"shoulders","sm":["shoulders","obliques","glutes"],"st":["Start in a high plank with feet wide.","Lift one hand off the floor.","Hold your hips steady.","Hold for 20-30 seconds.","Switch arms."],"img":"opengym/3983.webp","gif":null,"ext":1},{"id":"3984","n":"push up pike toe touch","bp":"chest","eq":"body weight","tg":"pectorals","mg":"shoulders","sm":["shoulders","triceps","core"],"st":["Start in a high plank.","Do a push up.","Lift your hips into a pike.","Reach one hand to the opposite toe.","Return to plank and alternate."],"img":"opengym/3984.webp","gif":null,"ext":1},{"id":"3985","n":"push up hand by hand","bp":"chest","eq":"body weight","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders","core"],"st":["Start in a high plank.","Lower into a push up.","Step one hand wider, then the other.","Do another push up.","Step your hands back in."],"img":"opengym/3985.webp","gif":null,"ext":1},{"id":"3986","n":"ez bar front twist raise","bp":"shoulders","eq":"ez barbell","tg":"delts","mg":"upper chest","sm":["upper chest","forearms","core"],"st":["Stand holding an EZ bar at thigh height.","Raise it forward to chest height.","Rotate your wrists as you lift.","Pause at the top.","Lower slowly."],"img":"opengym/3986.webp","gif":null,"ext":1},{"id":"3987","n":"barbell incline wrist curl with chest support","bp":"lower arms","eq":"barbell","tg":"forearms","mg":"wrist flexors","sm":["wrist flexors","grip muscles"],"st":["Lie chest down on an incline bench with the barbell in hands, palms up.","Let your wrists extend gently.","Curl your wrists upward.","Squeeze at the top.","Lower slowly."],"img":"opengym/3987.webp","gif":null,"ext":1},{"id":"3988","n":"barbell incline reverse grip spider curl with chest support","bp":"lower arms","eq":"barbell","tg":"forearms","mg":"brachialis","sm":["brachialis","biceps","wrist extensors"],"st":["Lie chest down on an incline bench holding a barbell overhand.","Keep your upper arms vertical.","Curl the bar up.","Squeeze at the top.","Lower fully with control."],"img":"opengym/3988.webp","gif":null,"ext":1},{"id":"3989","n":"ez bar incline front raise","bp":"shoulders","eq":"ez barbell","tg":"delts","mg":"upper chest","sm":["upper chest","forearms"],"st":["Sit on an incline bench with the EZ bar at thighs.","Keep arms straight with a slight bend.","Raise the bar to eye level.","Lower under control.","Keep your back on the pad."],"img":"opengym/3989.webp","gif":null,"ext":1},{"id":"3990","n":"ez bar seated close grip shoulder press","bp":"shoulders","eq":"ez barbell","tg":"delts","mg":"triceps","sm":["triceps","upper chest"],"st":["Sit upright holding the EZ bar with a close grip at your chest.","Brace your core.","Press the bar overhead.","Lower it back to chest height.","Keep your ribs down."],"img":"opengym/3990.webp","gif":null,"ext":1},{"id":"3991","n":"barbell bent over wide alternate row plus","bp":"back","eq":"barbell","tg":"upper back","mg":"lats","sm":["lats","rhomboids","biceps","rear deltoids"],"st":["Hinge forward holding the barbell with a wide grip.","Keep your back flat.","Pull one side toward your ribs.","Lower and pull the other side.","Keep your hips still."],"img":"opengym/3991.webp","gif":null,"ext":1},{"id":"3992","n":"barbell bent over wide row plus","bp":"back","eq":"barbell","tg":"upper back","mg":"lats","sm":["lats","rhomboids","biceps","rear deltoids"],"st":["Hinge forward with a wide overhand grip.","Keep a flat back.","Row the bar toward your upper abdomen.","Squeeze your shoulder blades.","Lower slowly."],"img":"opengym/3992.webp","gif":null,"ext":1},{"id":"3993","n":"dumbbell push up front raise","bp":"chest","eq":"dumbbell","tg":"pectorals","mg":"shoulders","sm":["shoulders","triceps","core"],"st":["Start in a high plank gripping two dumbbells.","Do a push up.","Lift one dumbbell forward to shoulder height.","Return it to the floor.","Alternate arms."],"img":"opengym/3993.webp","gif":null,"ext":1},{"id":"3994","n":"neck circle stretch","bp":"neck","eq":"body weight","tg":"levator scapulae","mg":"sternocleidomastoid","sm":["sternocleidomastoid","trapezius"],"st":["Stand or sit tall with relaxed shoulders.","Drop your chin toward your chest.","Slowly roll your head to one side.","Continue in a smooth circle.","Do 5 circles, then reverse."],"img":"opengym/3994.webp","gif":null,"ext":1},{"id":"3995","n":"back slaps wrap around stretch","bp":"back","eq":"body weight","tg":"upper back","mg":"shoulders","sm":["shoulders","rhomboids","lats"],"st":["Stand with your feet shoulder width apart.","Swing your arms wide.","Wrap them around your body so the hands slap your upper back.","Open them wide again.","Keep it loose and rhythmic."],"img":"opengym/3995.webp","gif":null,"ext":1},{"id":"3997","n":"standing side bend (bent arm)","bp":"waist","eq":"body weight","tg":"obliques","mg":"abdominals","sm":["abdominals","lats"],"st":["Stand tall with feet hip width apart.","Bend one arm overhead.","Lean to the opposite side.","Hold for 20-30 seconds.","Switch sides."],"img":"opengym/3997.webp","gif":null,"ext":1},{"id":"3999","n":"standing air bike","bp":"waist","eq":"body weight","tg":"abs","mg":"obliques","sm":["obliques","hip flexors"],"st":["Stand with hands behind your head.","Lift one knee while rotating your torso.","Touch your elbow to the knee.","Switch sides in a pedaling rhythm.","Stay upright."],"img":"opengym/3999.webp","gif":null,"ext":1},{"id":"4000","n":"static lunge","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","calves"],"st":["Step one foot forward and stay in a split stance.","Lower your back knee toward the floor.","Keep your front knee above the ankle.","Push through the front heel.","Finish reps, then switch legs."],"img":"opengym/4000.webp","gif":null,"ext":1},{"id":"4001","n":"alternate leg raise with head up","bp":"waist","eq":"body weight","tg":"abs","mg":"hip flexors","sm":["hip flexors","lower abs"],"st":["Lie on your back with your head slightly lifted.","Raise one leg to vertical.","Lower it without touching the floor.","Raise the other leg.","Keep your lower back pressed down."],"img":"opengym/4001.webp","gif":null,"ext":1},{"id":"4002","n":"v up double crunch","bp":"waist","eq":"body weight","tg":"abs","mg":"hip flexors","sm":["hip flexors","lower abs"],"st":["Lie flat with arms overhead.","Lift your arms and legs into a V.","Crunch in again.","Lower with control.","Keep your legs straight."],"img":"opengym/4002.webp","gif":null,"ext":1},{"id":"4003","n":"v up with clap","bp":"waist","eq":"body weight","tg":"abs","mg":"hip flexors","sm":["hip flexors","lower abs"],"st":["Lie flat with arms overhead.","Lift your arms and legs into a V.","Clap above your shins.","Lower with control.","Repeat smoothly."],"img":"opengym/4003.webp","gif":null,"ext":1},{"id":"4004","n":"place jog","bp":"cardio","eq":"body weight","tg":"cardiovascular system","mg":"quadriceps","sm":["quadriceps","calves","hip flexors"],"st":["Stand tall with your arms bent.","Jog in place, lifting your knees.","Land softly on the balls of your feet.","Keep a steady pace.","Continue for 1-5 minutes."],"img":"opengym/4004.webp","gif":null,"ext":1},{"id":"4006","n":"backward abdominal stretch","bp":"waist","eq":"body weight","tg":"abs","mg":"hip flexors","sm":["hip flexors","lower back"],"st":["Lie face down with hands under your shoulders.","Press your chest up.","Keep your hips on the floor.","Hold for 20-30 seconds.","Lower slowly."],"img":"opengym/4006.webp","gif":null,"ext":1},{"id":"4007","n":"90 degree heel touch","bp":"waist","eq":"body weight","tg":"abs","mg":"obliques","sm":["obliques","hip flexors"],"st":["Lie with your legs up and knees bent at 90 degrees.","Lift your shoulders.","Reach one hand toward the heel.","Switch sides.","Keep your legs still."],"img":"opengym/4007.webp","gif":null,"ext":1},{"id":"4008","n":"straight leg sit up","bp":"waist","eq":"body weight","tg":"abs","mg":"hip flexors","sm":["hip flexors"],"st":["Lie on your back with legs straight.","Cross your arms over your chest.","Curl up to sitting.","Lower with control.","Do not pull on your neck."],"img":"opengym/4008.webp","gif":null,"ext":1},{"id":"4009","n":"long arm crunch","bp":"waist","eq":"body weight","tg":"abs","mg":"hip flexors","sm":["hip flexors"],"st":["Lie on your back with arms straight overhead.","Bend your knees.","Crunch up reaching forward.","Lower slowly.","Keep your arms by your ears."],"img":"opengym/4009.webp","gif":null,"ext":1},{"id":"4010","n":"cable kneeling shoulder press","bp":"shoulders","eq":"cable","tg":"delts","mg":"triceps","sm":["triceps","core","upper chest"],"st":["Kneel in front of a low cable and hold the handles at shoulder height.","Brace your abs.","Press the handles overhead.","Lower under control.","Keep your hips tall."],"img":"opengym/4010.webp","gif":null,"ext":1},{"id":"4011","n":"cable bent over row with bar","bp":"back","eq":"cable","tg":"upper back","mg":"lats","sm":["lats","biceps","rhomboids"],"st":["Face the low pulley and hinge forward holding the bar.","Keep a flat back.","Pull the bar toward your waist.","Squeeze your back.","Extend your arms slowly."],"img":"opengym/4011.webp","gif":null,"ext":1},{"id":"4012","n":"cable incline cross rear fly","bp":"shoulders","eq":"cable","tg":"delts","mg":"rear deltoids","sm":["rear deltoids","rhomboids","upper back"],"st":["Lie chest down on an incline bench between two cables, holding opposite handles.","Keep elbows slightly bent.","Pull your arms out and back.","Pause.","Return slowly."],"img":"opengym/4012.webp","gif":null,"ext":1},{"id":"4013","n":"cable lying cross lateral raise","bp":"shoulders","eq":"cable","tg":"delts","mg":"rotator cuff","sm":["rotator cuff","upper chest"],"st":["Lie on a bench with a cable running across your body.","Hold the handle with the far hand.","Raise the arm out to the side.","Lower with control.","Finish reps, then switch arms."],"img":"opengym/4013.webp","gif":null,"ext":1},{"id":"4014","n":"cable standing front raise variation","bp":"shoulders","eq":"cable","tg":"delts","mg":"upper chest","sm":["upper chest","forearms"],"st":["Stand facing away from a low pulley.","Hold the handle with a slight elbow bend.","Raise the arm to eye level.","Lower slowly.","Switch arms."],"img":"opengym/4014.webp","gif":null,"ext":1},{"id":"4015","n":"dumbbell incline close grip press variation","bp":"upper arms","eq":"dumbbell","tg":"triceps","mg":"chest","sm":["chest","upper chest","shoulders"],"st":["Lie on an incline bench with dumbbells together over your chest.","Keep your elbows tucked.","Lower to your chest.","Press up.","Keep the dumbbells touching."],"img":"opengym/4015.webp","gif":null,"ext":1},{"id":"4016","n":"barbell seated shrug","bp":"back","eq":"barbell","tg":"traps","mg":"upper back","sm":["upper back","forearms","grip muscles"],"st":["Sit upright holding the barbell at thigh level.","Keep your arms straight.","Lift your shoulders to your ears.","Pause.","Lower slowly."],"img":"opengym/4016.webp","gif":null,"ext":1},{"id":"4017","n":"dumbbell standing single spider curl","bp":"upper arms","eq":"dumbbell","tg":"biceps","mg":"brachialis","sm":["brachialis","forearms"],"st":["Stand and hinge forward, bracing against a support.","Let one arm hang with a dumbbell.","Curl up.","Squeeze.","Lower and switch arms."],"img":"opengym/4017.webp","gif":null,"ext":1},{"id":"4018","n":"lying leg hip raise on floor v. 2","bp":"waist","eq":"body weight","tg":"abs","mg":"lower abs","sm":["lower abs","hip flexors"],"st":["Lie on your back with your legs raised.","Press your arms into the floor.","Lift your hips off the floor.","Lower with control.","Avoid swinging."],"img":"opengym/4018.webp","gif":null,"ext":1},{"id":"4019","n":"reverse crunch v. 2","bp":"waist","eq":"body weight","tg":"abs","mg":"lower abs","sm":["lower abs","hip flexors"],"st":["Lie on your back with knees bent.","Lift your legs.","Curl hips off the floor.","Lower slowly.","Do not swing."],"img":"opengym/4019.webp","gif":null,"ext":1},{"id":"4020","n":"criss cross leg raises","bp":"waist","eq":"body weight","tg":"abs","mg":"lower abs","sm":["lower abs","obliques","adductors"],"st":["Lie on your back with legs straight and raised.","Lower them slightly.","Cross one leg over the other.","Switch the cross.","Keep your lower back down."],"img":"opengym/4020.webp","gif":null,"ext":1},{"id":"4022","n":"seated 8 leg crunch","bp":"waist","eq":"body weight","tg":"abs","mg":"hip flexors","sm":["hip flexors","obliques","core"],"st":["Sit on the floor, lean back slightly and support yourself with your hands behind you.","Lift both feet off the floor and brace your core.","Draw a figure eight in the air with your legs, slow and controlled.","Keep your chest lifted and your lower back from collapsing.","Lower your feet and rest, then repeat."],"img":"opengym/4022.webp","gif":null,"ext":1},{"id":"4023","n":"front plank to toe tap","bp":"waist","eq":"body weight","tg":"abs","mg":"hip flexors","sm":["hip flexors","shoulders","glutes","obliques"],"st":["Start in a front plank with your body in a straight line from head to heels.","Brace your abs and squeeze your glutes.","Lift one foot and tap the toes out to the side without twisting your hips.","Bring the foot back to the start.","Repeat on the other leg and keep alternating."],"img":"opengym/4023.webp","gif":null,"ext":1},{"id":"4024","n":"resistance band standing overhead warming up","bp":"shoulders","eq":"resistance band","tg":"delts","mg":"upper back","sm":["upper back","rotator cuff","triceps"],"st":["Stand tall with feet hip-width apart and hold the band with both hands at chest height.","Keep a slight tension in the band.","Raise your arms overhead in a smooth arc.","Lower back to chest height slowly.","Repeat for 10 to 15 easy reps without shrugging."],"img":"opengym/4024.webp","gif":null,"ext":1},{"id":"4025","n":"resistance band standing down warming up","bp":"shoulders","eq":"resistance band","tg":"delts","mg":"lats","sm":["lats","rotator cuff","upper back"],"st":["Stand tall and hold the band overhead with both hands, a little wider than shoulder width.","Keep your ribs down and core braced.","Pull your hands down in front of you toward your chest.","Return slowly overhead keeping tension.","Repeat for 10 to 15 easy reps."],"img":"opengym/4025.webp","gif":null,"ext":1},{"id":"4026","n":"resistance band standing front warming up","bp":"shoulders","eq":"resistance band","tg":"delts","mg":"chest","sm":["chest","upper back","rotator cuff"],"st":["Stand tall with feet hip-width apart and hold the band in front of you at shoulder height.","Keep your arms mostly straight.","Move your hands apart, stretching the band across your chest.","Bring your hands back together slowly.","Repeat for 10 to 15 easy reps."],"img":"opengym/4026.webp","gif":null,"ext":1},{"id":"4027","n":"resistance band standing back warming up","bp":"back","eq":"resistance band","tg":"upper back","mg":"rear deltoids","sm":["rear deltoids","rhomboids","rotator cuff"],"st":["Stand tall holding the band with both hands in front of you.","Keep a slight bend in your elbows.","Pull the band apart and back, squeezing your shoulder blades together.","Pause briefly then return slowly.","Repeat for 10 to 15 easy reps without arching your lower back."],"img":"opengym/4027.webp","gif":null,"ext":1},{"id":"4028","n":"resistance band squatting front warming up","bp":"shoulders","eq":"resistance band","tg":"delts","mg":"upper back","sm":["upper back","quadriceps","glutes","core"],"st":["Hold the band in front of you and sink into a comfortable deep squat.","Keep your heels down and chest up.","Move your hands apart, stretching the band at shoulder height.","Bring your hands back together under control.","Repeat for 10 to 15 easy reps, then stand up."],"img":"opengym/4028.webp","gif":null,"ext":1},{"id":"4029","n":"band hip adduction","bp":"upper legs","eq":"band","tg":"adductors","mg":"inner thighs","sm":["inner thighs","groin","glutes"],"st":["Anchor the band low and loop it around the ankle nearest the anchor.","Stand tall and hold a support for balance.","Pull the working leg across in front of the other leg.","Pause for a moment and return slowly.","Finish all reps, then switch legs."],"img":"opengym/4029.webp","gif":null,"ext":1},{"id":"4030","n":"dumbbell bar grip sumo squat","bp":"upper legs","eq":"dumbbell","tg":"glutes","mg":"quadriceps","sm":["quadriceps","adductors","inner thighs","hamstrings","core"],"st":["Stand with feet wider than shoulders and toes turned out.","Hold the dumbbell vertically by its bar with both hands in front of you.","Sit your hips down while keeping your chest up.","Push your knees out over your toes.","Drive through your heels to stand and squeeze your glutes."],"img":"opengym/4030.webp","gif":null,"ext":1},{"id":"4031","n":"band hip abduction","bp":"upper legs","eq":"band","tg":"abductors","mg":"glutes","sm":["glutes","hip flexors","core"],"st":["Anchor the band low and loop it around the ankle farthest from the anchor.","Stand tall and hold a support for balance.","Lift the working leg out to the side without leaning.","Pause, then lower slowly against the band.","Finish all reps, then switch legs."],"img":"opengym/4031.webp","gif":null,"ext":1},{"id":"4033","n":"band standing leg curl","bp":"upper legs","eq":"band","tg":"hamstrings","mg":"calves","sm":["calves","glutes"],"st":["Anchor the band low and loop it around one ankle.","Stand tall facing the anchor and hold a support.","Bend your knee and curl your heel toward your glute.","Keep your thighs together and hips still.","Lower slowly, finish the reps, then switch legs."],"img":"opengym/4033.webp","gif":null,"ext":1},{"id":"4036","n":"resistance band leg curl","bp":"upper legs","eq":"resistance band","tg":"hamstrings","mg":"calves","sm":["calves","glutes"],"st":["Attach the band to a low anchor and loop the handle around one ankle.","Face the anchor and hold a support for balance.","Curl your heel toward your glute.","Keep your knees close and your hips steady.","Lower slowly, finish the reps, then switch legs."],"img":"opengym/4036.webp","gif":null,"ext":1},{"id":"4038","n":"landmine one arm bent over row","bp":"back","eq":"landmine","tg":"upper back","mg":"lats","sm":["lats","rhomboids","biceps","rear deltoids","lower back"],"st":["Load the landmine bar and stand over it with a hip hinge, knees soft.","Grip the bar end with one hand and keep your back flat.","Pull the bar toward your hip, squeezing your shoulder blade back.","Lower slowly until the arm is straight.","Finish the reps, then switch arms."],"img":"opengym/4038.webp","gif":null,"ext":1},{"id":"4039","n":"landmine one arm bent over bench row","bp":"back","eq":"landmine","tg":"upper back","mg":"lats","sm":["lats","rhomboids","biceps","rear deltoids"],"st":["Set the landmine bar next to a bench and place one hand and knee on the bench.","Grip the bar end with your free hand and keep your back flat.","Pull your elbow up toward your hip.","Pause and squeeze your shoulder blade.","Lower slowly, finish the reps, then switch sides."],"img":"opengym/4039.webp","gif":null,"ext":1},{"id":"4040","n":"landmine rear lunge v. 2","bp":"upper legs","eq":"landmine","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","core","shoulders"],"st":["Hold the bar end against your chest with both hands.","Stand tall with feet hip-width apart.","Step one foot back and lower until both knees are bent about 90 degrees.","Keep your front heel down and your torso upright.","Push through the front foot to return, then switch legs."],"img":"opengym/4040.webp","gif":null,"ext":1},{"id":"4041","n":"dumbbell russian twist (on stability ball)","bp":"waist","eq":"dumbbell","tg":"obliques","mg":"core","sm":["core","hip flexors","glutes"],"st":["Sit on a stability ball and walk your feet out until your upper back rests on it, hips lifted.","Hold a dumbbell with both hands above your chest.","Rotate your torso and arms to one side.","Rotate smoothly to the other side.","Keep your hips high and move with control."],"img":"opengym/4041.webp","gif":null,"ext":1},{"id":"4042","n":"cable seated cross arm twist","bp":"waist","eq":"cable","tg":"obliques","mg":"core","sm":["core","shoulders"],"st":["Sit next to a cable machine set at chest height and grab the handle with both hands.","Start with your arms extended in front of you.","Rotate your torso away from the stack, pulling the handle across your body.","Pause, then return slowly.","Keep your hips still, finish the reps, then switch sides."],"img":"opengym/4042.webp","gif":null,"ext":1},{"id":"4043","n":"inverted shrug (on parallel bars)","bp":"back","eq":"body weight","tg":"upper back","mg":"traps","sm":["traps","rhomboids","shoulders","grip muscles"],"st":["Grip the parallel bars and hang in an inverted position with arms straight.","Keep your body stable and your elbows locked.","Draw your shoulder blades down and together, pulling your body up a little.","Lower back to a full hang under control.","Repeat for controlled reps."],"img":"opengym/4043.webp","gif":null,"ext":1},{"id":"4044","n":"single leg glute bridge with knee to chest","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"hamstrings","sm":["hamstrings","core","hip flexors"],"st":["Lie on your back with one knee bent and the foot flat, the other knee pulled toward your chest.","Brace your core.","Push through the planted heel and lift your hips.","Squeeze your glute at the top.","Lower slowly, finish the reps, then switch legs."],"img":"opengym/4044.webp","gif":null,"ext":1},{"id":"4045","n":"kettlebell lateral lunge","bp":"upper legs","eq":"kettlebell","tg":"glutes","mg":"quadriceps","sm":["quadriceps","adductors","hamstrings","core"],"st":["Hold the kettlebell at your chest with both hands and stand tall.","Take a big step to one side.","Sit your hips back and bend that knee while the other leg stays straight.","Keep your chest up and both feet flat.","Push back to the start and alternate sides."],"img":"opengym/4045.webp","gif":null,"ext":1},{"id":"4046","n":"kettlebell sumo deadlift","bp":"upper legs","eq":"kettlebell","tg":"glutes","mg":"hamstrings","sm":["hamstrings","quadriceps","adductors","lower back","grip muscles"],"st":["Stand with feet wide and toes angled out, the kettlebell between your feet.","Hinge and bend your knees to grip the handle with both hands.","Keep your back flat and chest up.","Drive through your feet to stand tall and squeeze your glutes.","Lower the kettlebell under control."],"img":"opengym/4046.webp","gif":null,"ext":1},{"id":"4047","n":"kettlebell dead bug","bp":"waist","eq":"kettlebell","tg":"abs","mg":"core","sm":["core","lower abs","hip flexors","shoulders"],"st":["Lie on your back and hold a kettlebell by the horns above your chest.","Lift your knees to a tabletop position.","Slowly extend one leg while pressing your lower back into the floor.","Bring the leg back and switch.","Keep the kettlebell steady and breathe."],"img":"opengym/4047.webp","gif":null,"ext":1},{"id":"4048","n":"dumbbell ipsilateral split squat","bp":"upper legs","eq":"dumbbell","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","adductors","core"],"st":["Hold a dumbbell in one hand and step into a split stance, the dumbbell on the same side as your front leg.","Keep your torso upright.","Lower your back knee toward the floor.","Press through the front foot to rise.","Finish the reps, then switch sides."],"img":"opengym/4048.webp","gif":null,"ext":1},{"id":"4049","n":"inverted shrug","bp":"back","eq":"body weight","tg":"upper back","mg":"traps","sm":["traps","rhomboids","shoulders","grip muscles"],"st":["Set up under a bar or rings and hang with straight arms.","Keep your body in a straight line.","Pull your shoulder blades down and back to rise a little.","Hold briefly, then lower to a full hang.","Repeat for controlled reps."],"img":"opengym/4049.webp","gif":null,"ext":1},{"id":"4051","n":"side lying leg raise","bp":"upper legs","eq":"body weight","tg":"abductors","mg":"glutes","sm":["glutes","hip flexors","core"],"st":["Lie on your side with your legs stacked and your head supported.","Keep your hips stacked and core braced.","Lift the top leg up with the toes pointing forward.","Pause at the top.","Lower slowly, finish the reps, then switch sides."],"img":"opengym/4051.webp","gif":null,"ext":1},{"id":"4052","n":"battling ropes half kneeling","bp":"cardio","eq":"rope","tg":"cardiovascular system","mg":"shoulders","sm":["shoulders","core","forearms","glutes"],"st":["Kneel on one knee with the other foot forward and hold a rope end in each hand.","Brace your core and keep your chest up.","Make fast alternating waves with your arms.","Keep the rhythm steady for a set time.","Switch the front leg for the next set."],"img":"opengym/4052.webp","gif":null,"ext":1},{"id":"4053","n":"dumbbell seated gittleson shrug","bp":"back","eq":"dumbbell","tg":"traps","mg":"upper back","sm":["upper back","rhomboids","grip muscles","forearms"],"st":["Sit upright on a bench holding a dumbbell in each hand at your sides.","Keep your arms straight and chest up.","Shrug your shoulders straight up toward your ears.","Pause at the top.","Lower slowly and repeat without rolling your shoulders."],"img":"opengym/4053.webp","gif":null,"ext":1},{"id":"4054","n":"dumbbell one arm triceps extension on stability ball","bp":"upper arms","eq":"dumbbell","tg":"triceps","mg":"shoulders","sm":["shoulders","core"],"st":["Sit tall on a stability ball and hold a dumbbell overhead in one hand.","Keep your upper arm close to your head.","Bend your elbow and lower the dumbbell behind your head.","Extend your arm back up.","Finish the reps, then switch arms."],"img":"opengym/4054.webp","gif":null,"ext":1},{"id":"4055","n":"dumbbell seated lateral raise on stability ball","bp":"shoulders","eq":"dumbbell","tg":"delts","mg":"trapezius","sm":["trapezius","core","upper back"],"st":["Sit upright on a stability ball with a dumbbell in each hand at your sides.","Keep a slight bend in your elbows.","Raise your arms out to the sides to shoulder height.","Pause briefly.","Lower slowly without swinging."],"img":"opengym/4055.webp","gif":null,"ext":1},{"id":"4056","n":"dead bug with stability ball","bp":"waist","eq":"stability ball","tg":"abs","mg":"core","sm":["core","lower abs","hip flexors","shoulders"],"st":["Lie on your back and hold the ball above your chest with your knees raised.","Press your lower back into the floor.","Extend your opposite arm and leg away, holding the ball with the rest.","Return to the center.","Alternate sides slowly."],"img":"opengym/4056.webp","gif":null,"ext":1},{"id":"4057","n":"kettlebell turkish get up to hand","bp":"full body","eq":"kettlebell","tg":"delts","mg":"core","sm":["core","glutes","quadriceps","shoulders","obliques"],"st":["Lie on your back with a kettlebell pressed up in one hand and the same-side knee bent.","Keep your eyes on the kettlebell.","Roll up onto your opposite elbow, then onto your hand.","Hold the seated position with your arm vertical.","Reverse the steps to lie back down, then switch sides."],"img":"opengym/4057.webp","gif":null,"ext":1},{"id":"4058","n":"leg raise dragon flag","bp":"waist","eq":"body weight","tg":"abs","mg":"lower abs","sm":["lower abs","hip flexors","lats","core"],"st":["Lie on a bench and grip it behind your head.","Lift your hips and legs so your body is straight from shoulders to toes.","Keep your body rigid and lower slowly without sitting.","Raise your legs back up under control.","Stop before your lower back arches."],"img":"opengym/4058.webp","gif":null,"ext":1},{"id":"4059","n":"kettlebell split squat","bp":"upper legs","eq":"kettlebell","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","adductors","core"],"st":["Hold a kettlebell at your chest and take a long split stance.","Keep your torso upright.","Lower your back knee toward the floor.","Press through the front heel to stand.","Finish the reps, then switch legs."],"img":"opengym/4059.webp","gif":null,"ext":1},{"id":"4060","n":"bird dog push up","bp":"chest","eq":"body weight","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders","core","glutes"],"st":["Start in a high plank.","Lower into a push up with elbows about 45 degrees from your body.","Press back up.","Lift one arm and the opposite leg and hold briefly.","Return and alternate sides each rep."],"img":"opengym/4060.webp","gif":null,"ext":1},{"id":"4061","n":"barbell banded bench squat","bp":"upper legs","eq":"barbell","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","lower back","core"],"st":["Set a bench behind you and place the bar on your upper back with bands attached.","Stand with feet shoulder-width apart.","Sit back and down until you touch the bench.","Keep your chest up and knees pushing out.","Drive through your heels to stand."],"img":"opengym/4061.webp","gif":null,"ext":1},{"id":"4062","n":"lever lying banded t bar row","bp":"back","eq":"leverage machine","tg":"upper back","mg":"lats","sm":["lats","rhomboids","biceps","rear deltoids"],"st":["Lie chest down on the support and grip the handles.","Keep your head neutral.","Pull your elbows back and squeeze your shoulder blades.","Pause at the top.","Lower slowly against the band tension."],"img":"opengym/4062.webp","gif":null,"ext":1},{"id":"4063","n":"band biceps curl","bp":"upper arms","eq":"band","tg":"biceps","mg":"brachialis","sm":["brachialis","forearms"],"st":["Stand on the band and hold the ends with palms forward.","Keep your elbows at your sides.","Curl your hands up toward your shoulders.","Squeeze your biceps at the top.","Lower slowly without swinging."],"img":"opengym/4063.webp","gif":null,"ext":1},{"id":"4064","n":"barbell squat with chains","bp":"upper legs","eq":"barbell","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","lower back","core"],"st":["Set chains on the bar and unrack it onto your upper back.","Stand with feet shoulder-width apart.","Squat down with your chest up until your thighs are at least parallel.","Drive up through your feet.","Keep your core braced throughout."],"img":"opengym/4064.webp","gif":null,"ext":1},{"id":"4065","n":"dumbbell standing alternate arnold press","bp":"shoulders","eq":"dumbbell","tg":"delts","mg":"triceps","sm":["triceps","upper chest","trapezius","core"],"st":["Stand holding dumbbells at shoulder height with palms facing you.","Brace your core.","Press one dumbbell overhead while rotating your palm forward.","Lower while rotating back.","Alternate arms."],"img":"opengym/4065.webp","gif":null,"ext":1},{"id":"4066","n":"dumbbell seated bent over alternate rear delt fly","bp":"shoulders","eq":"dumbbell","tg":"delts","mg":"rear deltoids","sm":["rear deltoids","upper back","rhomboids"],"st":["Sit at the edge of a bench and lean forward with dumbbells hanging below your knees.","Keep your back flat and elbows slightly bent.","Raise one arm out to the side to shoulder height.","Lower slowly.","Alternate arms."],"img":"opengym/4066.webp","gif":null,"ext":1},{"id":"4067","n":"dumbbell alternate arnold press","bp":"shoulders","eq":"dumbbell","tg":"delts","mg":"triceps","sm":["triceps","upper chest","trapezius"],"st":["Sit upright holding dumbbells at shoulder height with palms facing you.","Press one dumbbell overhead while rotating your palm forward.","Lower it while rotating back.","Alternate arms.","Keep your back against the pad and avoid arching."],"img":"opengym/4067.webp","gif":null,"ext":1},{"id":"4068","n":"barbell bench press with 3 board","bp":"chest","eq":"barbell","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders","upper chest"],"st":["Lie on a bench with three boards stacked on your chest.","Grip the bar slightly wider than shoulders.","Lower the bar until it touches the boards.","Press back up to full extension.","Keep your feet planted and shoulder blades pinched."],"img":"opengym/4068.webp","gif":null,"ext":1},{"id":"4069","n":"barbell bench press with 2 board","bp":"chest","eq":"barbell","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders","upper chest"],"st":["Lie on a bench with two boards stacked on your chest.","Grip the bar slightly wider than shoulders.","Lower the bar until it touches the boards.","Press back up to full extension.","Keep your feet planted and shoulder blades pinched."],"img":"opengym/4069.webp","gif":null,"ext":1},{"id":"4070","n":"barbell bench press with 1 board","bp":"chest","eq":"barbell","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders","upper chest"],"st":["Lie on a bench with a single board on your chest.","Grip the bar slightly wider than shoulders.","Lower the bar until it touches the board.","Press back up to full extension.","Keep your feet planted and shoulder blades pinched."],"img":"opengym/4070.webp","gif":null,"ext":1},{"id":"4071","n":"dumbbell incline one arm front raise with chest support","bp":"shoulders","eq":"dumbbell","tg":"delts","mg":"upper chest","sm":["upper chest","trapezius","biceps"],"st":["Set an incline bench and lie chest down on it.","Hold a dumbbell in one hand hanging straight down.","Raise the dumbbell forward to shoulder height with a slight elbow bend.","Lower slowly.","Finish the reps, then switch arms."],"img":"opengym/4071.webp","gif":null,"ext":1},{"id":"4072","n":"bodyweight single leg wall squat","bp":"upper legs","eq":"body weight","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","core","calves"],"st":["Lean your back on a wall and lift one foot off the floor.","Place your standing foot forward.","Slide down into a squat as far as you can control.","Press through your heel to rise.","Finish the reps, then switch legs."],"img":"opengym/4072.webp","gif":null,"ext":1},{"id":"4073","n":"band low chest fly","bp":"chest","eq":"band","tg":"pectorals","mg":"shoulders","sm":["shoulders","upper chest","biceps"],"st":["Anchor the band low behind you and hold the ends.","Step forward with a slight lean.","Start with arms out to the sides and slightly bent.","Sweep your hands up and together in front of your chest.","Return slowly."],"img":"opengym/4073.webp","gif":null,"ext":1},{"id":"4074","n":"band low chest press","bp":"chest","eq":"band","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders","upper chest"],"st":["Anchor the band low behind you and hold the ends at chest level.","Step forward into a staggered stance.","Press your hands up and forward.","Pause, then return slowly.","Keep your core braced."],"img":"opengym/4074.webp","gif":null,"ext":1},{"id":"4075","n":"band chest fly","bp":"chest","eq":"band","tg":"pectorals","mg":"shoulders","sm":["shoulders","biceps","upper chest"],"st":["Anchor the band behind you at chest height and hold the ends.","Stand in a staggered stance.","Start with arms out to the sides and slightly bent.","Bring your hands together in front of your chest.","Return slowly under control."],"img":"opengym/4075.webp","gif":null,"ext":1},{"id":"4076","n":"band cross body one arm chest press","bp":"chest","eq":"band","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders","core","obliques"],"st":["Anchor the band behind you and hold the end in one hand.","Stand in a staggered stance.","Press your hand forward and across your body.","Return slowly while resisting rotation.","Finish the reps, then switch arms."],"img":"opengym/4076.webp","gif":null,"ext":1},{"id":"4077","n":"band low alternate chest press","bp":"chest","eq":"band","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders","upper chest"],"st":["Anchor the band low behind you and hold both ends.","Stand in a staggered stance.","Press one hand up and forward.","Return, then press the other hand.","Keep your core braced."],"img":"opengym/4077.webp","gif":null,"ext":1},{"id":"4078","n":"band alternate low chest fly","bp":"chest","eq":"band","tg":"pectorals","mg":"shoulders","sm":["shoulders","upper chest","biceps"],"st":["Anchor the band low behind you and hold the ends.","Stand in a staggered stance.","Sweep one arm up and across in front of your chest.","Return slowly.","Alternate arms."],"img":"opengym/4078.webp","gif":null,"ext":1},{"id":"4079","n":"band standing alternate chest press","bp":"chest","eq":"band","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders","core"],"st":["Anchor the band behind you at chest height and hold both ends.","Stand in a staggered stance.","Press one hand straight forward.","Return and press the other hand.","Keep your torso steady."],"img":"opengym/4079.webp","gif":null,"ext":1},{"id":"4080","n":"band kneeling crunch","bp":"waist","eq":"band","tg":"abs","mg":"obliques","sm":["obliques","core"],"st":["Anchor the band high and kneel facing it, holding the ends beside your head.","Keep your hips still.","Crunch your ribs toward your hips.","Pause and squeeze your abs.","Return slowly."],"img":"opengym/4080.webp","gif":null,"ext":1},{"id":"4081","n":"band reverse crunch","bp":"waist","eq":"band","tg":"abs","mg":"lower abs","sm":["lower abs","hip flexors","core"],"st":["Lie on your back with the band anchored overhead and held in your hands.","Bend your knees and lift your feet.","Curl your hips off the floor toward your chest.","Pause at the top.","Lower slowly."],"img":"opengym/4081.webp","gif":null,"ext":1},{"id":"4082","n":"band overhead side bend","bp":"waist","eq":"band","tg":"obliques","mg":"shoulders","sm":["shoulders","core"],"st":["Stand on the band and hold the ends overhead.","Keep your core braced.","Bend sideways at your waist.","Return to upright.","Finish the reps, then switch sides."],"img":"opengym/4082.webp","gif":null,"ext":1},{"id":"4083","n":"band upper crunch","bp":"waist","eq":"band","tg":"abs","mg":"core","sm":["core","obliques"],"st":["Lie on your back with your knees bent and the band anchored overhead, ends in hand.","Hold the band near your chest.","Curl your shoulders off the floor.","Pause and squeeze your abs.","Lower slowly."],"img":"opengym/4083.webp","gif":null,"ext":1},{"id":"4084","n":"band horizontal biceps curl","bp":"upper arms","eq":"band","tg":"biceps","mg":"brachialis","sm":["brachialis","forearms"],"st":["Anchor the band at chest height and face away from the anchor, holding the ends.","Step out until the band is taut and raise your arms out to the sides at shoulder height.","Bend your elbows to bring your hands toward your head.","Squeeze your biceps, then slowly extend your arms again.","Keep your elbows level with your shoulders the whole time."],"img":"opengym/4084.webp","gif":null,"ext":1},{"id":"4085","n":"band kneeling preacher curl","bp":"upper arms","eq":"band","tg":"biceps","mg":"brachialis","sm":["brachialis","forearms"],"st":["Anchor the band low and kneel facing it with your upper arms resting on a bench or pad.","Hold the band ends with palms up and arms extended.","Curl your hands toward your shoulders.","Squeeze at the top, then lower slowly until your arms are nearly straight.","Keep your upper arms pressed down on the pad."],"img":"opengym/4085.webp","gif":null,"ext":1},{"id":"4086","n":"band standard biceps curl","bp":"upper arms","eq":"band","tg":"biceps","mg":"brachialis","sm":["brachialis","forearms"],"st":["Stand on the middle of the band with your feet hip-width apart and grip the ends.","Keep your elbows at your sides and your chest tall.","Curl your hands up toward your shoulders without swinging.","Pause briefly, then lower slowly until your arms are straight.","Keep your wrists neutral throughout."],"img":"opengym/4086.webp","gif":null,"ext":1},{"id":"4087","n":"band 45 degrees biceps curl","bp":"upper arms","eq":"band","tg":"biceps","mg":"brachialis","sm":["brachialis","forearms"],"st":["Stand on the band and hold the ends, then set your arms about 45 degrees behind your torso.","Keep your chest up and shoulders back.","Curl your hands up while your upper arms stay in that angled position.","Squeeze at the top and lower slowly.","Avoid leaning back to finish the rep."],"img":"opengym/4087.webp","gif":null,"ext":1},{"id":"4088","n":"band cross chest biceps curl","bp":"upper arms","eq":"band","tg":"biceps","mg":"brachialis","sm":["brachialis","forearms","shoulders"],"st":["Stand on the band and hold the ends with palms facing in.","Keep your elbows near your sides.","Curl one hand across your chest toward the opposite shoulder.","Lower under control, then repeat on the other arm.","Keep your torso still and avoid swinging."],"img":"opengym/4088.webp","gif":null,"ext":1},{"id":"4089","n":"kettlebell sumo squat","bp":"upper legs","eq":"kettlebell","tg":"glutes","mg":"quadriceps","sm":["quadriceps","adductors","hamstrings","core"],"st":["Stand with your feet wider than shoulders and toes turned out, holding a kettlebell with both hands in front of you.","Brace your core and keep your chest tall.","Sit your hips down and back, pushing your knees out over your toes.","Lower until your thighs are about parallel.","Drive through your heels to stand and squeeze your glutes."],"img":"opengym/4089.webp","gif":null,"ext":1},{"id":"4090","n":"landmine sumo squat","bp":"upper legs","eq":"landmine","tg":"glutes","mg":"quadriceps","sm":["quadriceps","adductors","core","hamstrings"],"st":["Stand facing the landmine anchor with a wide stance and hold the bar end against your chest.","Brace your core and keep your elbows tucked in.","Sit down between your legs, knees tracking over your toes.","Lower until your thighs are about parallel.","Press through your heels to stand tall."],"img":"opengym/4090.webp","gif":null,"ext":1},{"id":"4091","n":"twist superman","bp":"waist","eq":"body weight","tg":"spine","mg":"glutes","sm":["glutes","obliques","hamstrings","core"],"st":["Lie face down with your arms extended overhead and legs straight.","Lift your arms, chest and legs off the floor.","Rotate your torso slightly to one side while holding the lift.","Return to the center, then rotate to the other side.","Lower down with control and keep your neck neutral."],"img":"opengym/4091.webp","gif":null,"ext":1},{"id":"4092","n":"weighted seated triceps extension","bp":"upper arms","eq":"weighted","tg":"triceps","mg":"shoulders","sm":["shoulders","forearms"],"st":["Sit upright on a bench and hold the weight overhead with both hands.","Keep your elbows pointing forward and close to your head.","Lower the weight behind your head by bending your elbows.","Extend your arms to straighten them fully.","Keep your back straight and core tight."],"img":"opengym/4092.webp","gif":null,"ext":1},{"id":"4093","n":"wheel rollout with wall support","bp":"waist","eq":"wheel roller","tg":"abs","mg":"lats","sm":["lats","shoulders","core","lower abs"],"st":["Kneel facing a wall with the ab wheel on the floor in front of you.","Grip the handles and tuck your pelvis under.","Roll forward until the wheel touches the wall.","Pull the wheel back by contracting your abs.","Keep your back flat and avoid sagging at the hips."],"img":"opengym/4093.webp","gif":null,"ext":1},{"id":"4094","n":"suspender forward lunge with rear fly","bp":"shoulders","eq":"suspension trainer","tg":"delts","mg":"rear deltoids","sm":["rear deltoids","rhomboids","quadriceps","glutes"],"st":["Hold the straps with both hands, leaning back slightly with arms extended.","Step one foot forward into a lunge.","As you lower, pull your arms out wide in a rear fly.","Push through the front foot to return to standing and bring your hands together.","Switch legs on the next rep."],"img":"opengym/4094.webp","gif":null,"ext":1},{"id":"4095","n":"crunch with leg lift","bp":"waist","eq":"body weight","tg":"abs","mg":"lower abs","sm":["lower abs","hip flexors","obliques"],"st":["Lie on your back with your hands behind your head and legs extended.","Crunch your shoulders off the floor.","At the same time lift your legs toward the ceiling.","Hold for a moment, then lower slowly.","Keep your lower back pressed into the floor."],"img":"opengym/4095.webp","gif":null,"ext":1},{"id":"4096","n":"wall press heel tap","bp":"waist","eq":"body weight","tg":"abs","mg":"lower abs","sm":["lower abs","hip flexors","glutes"],"st":["Lie on your back with your hips and knees bent at 90 degrees and feet flat on a wall.","Press your lower back into the floor.","Lower one heel to tap the floor while the other foot stays on the wall.","Return and tap with the other heel.","Move slowly without arching your back."],"img":"opengym/4096.webp","gif":null,"ext":1},{"id":"4097","n":"reverse crunch to dead bug","bp":"waist","eq":"body weight","tg":"abs","mg":"lower abs","sm":["lower abs","hip flexors","core"],"st":["Lie on your back with knees bent over your hips.","Curl your pelvis off the floor in a reverse crunch.","Lower your hips and extend one leg and the opposite arm.","Return to the start, then repeat on the other side.","Keep your lower back flat."],"img":"opengym/4097.webp","gif":null,"ext":1},{"id":"4099","n":"medicine ball half kneeling chest push","bp":"chest","eq":"medicine ball","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders","core"],"st":["Kneel on one knee with the other foot forward and hold a medicine ball at your chest.","Brace your core and stay tall.","Push the ball forward explosively or against a wall.","Catch it or bring it back to your chest.","Switch the kneeling leg after your set."],"img":"opengym/4099.webp","gif":null,"ext":1},{"id":"4100","n":"sled wide hack squat","bp":"upper legs","eq":"sled machine","tg":"quads","mg":"glutes","sm":["glutes","adductors","hamstrings"],"st":["Set your back on the pad and place your feet wide and slightly turned out on the platform.","Release the safety handles.","Lower by bending your knees until your thighs are parallel to the platform.","Press through your feet to extend your legs without locking out.","Keep your hips and back against the pad."],"img":"opengym/4100.webp","gif":null,"ext":1},{"id":"4101","n":"weighted straight leg toe touch crunch","bp":"waist","eq":"weighted","tg":"abs","mg":"lower abs","sm":["lower abs","hip flexors","obliques"],"st":["Lie on your back with your legs straight up and a weight held in both hands.","Reach the weight toward your toes.","Lift your shoulder blades off the floor.","Lower slowly with control.","Keep your legs vertical and your neck relaxed."],"img":"opengym/4101.webp","gif":null,"ext":1},{"id":"4102","n":"weighted chin up","bp":"back","eq":"weighted","tg":"lats","mg":"biceps","sm":["biceps","upper back","forearms","rhomboids"],"st":["Attach the weight with a belt and grip the bar with palms facing you.","Hang with arms straight.","Pull your chest toward the bar by driving your elbows down.","Pause with your chin above the bar.","Lower under control to full extension."],"img":"opengym/4102.webp","gif":null,"ext":1},{"id":"4103","n":"trap bar standing shrug","bp":"back","eq":"trap bar","tg":"traps","mg":"trapezius","sm":["trapezius","forearms","grip muscles","upper back"],"st":["Stand inside the trap bar and lift it, holding the handles at your sides.","Keep your arms straight and chest tall.","Shrug your shoulders straight up toward your ears.","Hold briefly at the top.","Lower slowly and do not roll your shoulders."],"img":"opengym/4103.webp","gif":null,"ext":1},{"id":"4104","n":"trap bar bent over row","bp":"back","eq":"trap bar","tg":"upper back","mg":"lats","sm":["lats","biceps","rhomboids","lower back"],"st":["Stand in the trap bar and hinge forward with a flat back, gripping the handles.","Brace your core.","Row the bar toward your lower ribs.","Squeeze your shoulder blades together.","Lower the bar with control."],"img":"opengym/4104.webp","gif":null,"ext":1},{"id":"4105","n":"trap bar deadlift from deficit","bp":"upper legs","eq":"trap bar","tg":"glutes","mg":"hamstrings","sm":["hamstrings","quadriceps","lower back","grip muscles"],"st":["Stand on a low platform inside the trap bar.","Squat down and grip the handles with a flat back.","Brace and push the floor away.","Stand tall and squeeze your glutes at the top.","Lower the bar with control to the start."],"img":"opengym/4105.webp","gif":null,"ext":1},{"id":"4106","n":"cable split stance horizontal pallof press","bp":"waist","eq":"cable","tg":"abs","mg":"obliques","sm":["obliques","core","shoulders"],"st":["Set the cable at chest height and stand sideways in a split stance.","Hold the handle at your chest with both hands.","Press the handle straight out in front of you.","Hold for a second without letting your torso twist.","Return the handle to your chest, then switch sides."],"img":"opengym/4106.webp","gif":null,"ext":1},{"id":"4107","n":"barbell sumo deadlift from blocks","bp":"upper legs","eq":"barbell","tg":"glutes","mg":"hamstrings","sm":["hamstrings","adductors","quadriceps","lower back"],"st":["Stand with a wide stance and toes out in front of a bar on blocks.","Grip the bar inside your knees and set a flat back.","Push the floor apart with your feet and stand up.","Lock out by squeezing your glutes.","Lower the bar back to the blocks with control."],"img":"opengym/4107.webp","gif":null,"ext":1},{"id":"4108","n":"dumbbell standing arnold press","bp":"shoulders","eq":"dumbbell","tg":"delts","mg":"triceps","sm":["triceps","upper chest","trapezius"],"st":["Stand holding dumbbells at chest height with palms facing you.","Press up while rotating your palms to face forward.","Fully extend your arms overhead.","Lower while rotating back to palms facing you.","Keep your core tight and avoid arching."],"img":"opengym/4108.webp","gif":null,"ext":1},{"id":"4109","n":"resistance band adduction split squat","bp":"upper legs","eq":"resistance band","tg":"adductors","mg":"glutes","sm":["glutes","quadriceps","inner thighs"],"st":["Anchor the band to the side and loop it around the working leg.","Step into a split stance.","Lower your back knee toward the floor.","Press back up while resisting the band.","Finish all reps, then switch legs."],"img":"opengym/4109.webp","gif":null,"ext":1},{"id":"4110","n":"dumbbell seated zottman curl","bp":"upper arms","eq":"dumbbell","tg":"biceps","mg":"brachialis","sm":["brachialis","forearms","wrist extensors"],"st":["Sit upright holding dumbbells with palms facing forward.","Curl both dumbbells up to shoulder height.","At the top rotate your palms to face down.","Lower slowly in that reverse grip.","Rotate your palms back up at the bottom."],"img":"opengym/4110.webp","gif":null,"ext":1},{"id":"4111","n":"cable seated horizontal shrug","bp":"back","eq":"cable","tg":"upper back","mg":"trapezius","sm":["trapezius","rhomboids"],"st":["Sit facing a low cable with a handle in each hand.","Start with arms straight and shoulders forward.","Pull your shoulders back and up.","Squeeze your traps at the end.","Return slowly to the start."],"img":"opengym/4111.webp","gif":null,"ext":1},{"id":"4112","n":"battling ropes seated","bp":"cardio","eq":"rope","tg":"cardiovascular system","mg":"shoulders","sm":["shoulders","core","forearms","upper back"],"st":["Sit tall on the floor or a bench holding the ends of the ropes.","Brace your core.","Whip the ropes up and down in alternating waves.","Keep a steady fast rhythm for 20-30 seconds.","Rest, then repeat."],"img":"opengym/4112.webp","gif":null,"ext":1},{"id":"4113","n":"landmine romanian deadlift","bp":"upper legs","eq":"landmine","tg":"hamstrings","mg":"glutes","sm":["glutes","lower back","forearms"],"st":["Stand holding the end of the bar close to your thighs.","Soften your knees and push your hips back.","Lower the bar along your legs with a flat back.","Feel a stretch in your hamstrings.","Drive your hips forward to stand tall."],"img":"opengym/4113.webp","gif":null,"ext":1},{"id":"4114","n":"resistance band bent over rear delt fly","bp":"shoulders","eq":"resistance band","tg":"delts","mg":"rear deltoids","sm":["rear deltoids","rhomboids","upper back","trapezius"],"st":["Stand on the band and hinge forward holding the handles.","Keep a slight bend in your elbows.","Raise your arms out to the sides.","Squeeze your shoulder blades together.","Lower slowly."],"img":"opengym/4114.webp","gif":null,"ext":1},{"id":"4115","n":"cable overhead tricep extension straight bar","bp":"upper arms","eq":"cable","tg":"triceps","mg":"shoulders","sm":["shoulders","forearms"],"st":["Set a straight bar on a low pulley and face away from it.","Hold the bar overhead with elbows bent.","Keep your elbows pointing forward.","Extend your arms to straighten them fully.","Lower the bar back behind your head slowly."],"img":"opengym/4115.webp","gif":null,"ext":1},{"id":"4116","n":"barbell reeves deadlift","bp":"upper legs","eq":"barbell","tg":"glutes","mg":"hamstrings","sm":["hamstrings","quadriceps","adductors","lower back"],"st":["Stand with a wide stance and hold the bar with a wide grip.","Set a flat back and chest up.","Drive through your feet to lift.","Lock out your hips at the top.","Lower the bar with control."],"img":"opengym/4116.webp","gif":null,"ext":1},{"id":"4117","n":"kneeling scapular push up","bp":"back","eq":"body weight","tg":"serratus anterior","mg":"upper back","sm":["upper back","chest","shoulders","core"],"st":["Kneel in a plank position with straight arms.","Keep your elbows locked.","Let your chest sink by pinching your shoulder blades together.","Push the floor away to spread them apart.","Keep your core braced."],"img":"opengym/4117.webp","gif":null,"ext":1},{"id":"4118","n":"prisoner jump squat","bp":"upper legs","eq":"body weight","tg":"quads","mg":"glutes","sm":["glutes","calves","hamstrings"],"st":["Stand with your hands behind your head and feet shoulder-width apart.","Squat down until your thighs are about parallel.","Explode upward into a jump.","Land softly on bent knees.","Go straight into the next rep."],"img":"opengym/4118.webp","gif":null,"ext":1},{"id":"4119","n":"power sled triceps extension","bp":"upper arms","eq":"sled machine","tg":"triceps","mg":"shoulders","sm":["shoulders","forearms"],"st":["Set up on the sled and grip the handles or bar.","Keep your elbows tucked.","Extend your arms to straighten them.","Squeeze your triceps at the end.","Return slowly."],"img":"opengym/4119.webp","gif":null,"ext":1},{"id":"4120","n":"dumbbell seated one arm arnold press","bp":"shoulders","eq":"dumbbell","tg":"delts","mg":"triceps","sm":["triceps","upper chest","trapezius"],"st":["Sit upright with a dumbbell in one hand at chest height, palm facing you.","Press up while rotating your palm forward.","Fully extend overhead.","Lower while rotating back.","Finish all reps, then switch arms."],"img":"opengym/4120.webp","gif":null,"ext":1},{"id":"4121","n":"single arm push up on medicine ball","bp":"chest","eq":"medicine ball","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders","core"],"st":["Place one hand on the ball and the other on the floor in a plank.","Spread your feet for balance.","Lower your chest toward the ball.","Press back up.","Finish your reps, then switch hands."],"img":"opengym/4121.webp","gif":null,"ext":1},{"id":"4122","n":"cable one arm reverse fly","bp":"shoulders","eq":"cable","tg":"delts","mg":"rear deltoids","sm":["rear deltoids","rhomboids","upper back"],"st":["Stand sideways to a cable at shoulder height and grab the handle with the far hand.","Keep a slight bend in your elbow.","Pull your arm across and back in an arc.","Squeeze your rear delt.","Return slowly, then switch arms."],"img":"opengym/4122.webp","gif":null,"ext":1},{"id":"4123","n":"kettlebell single front squat","bp":"upper legs","eq":"kettlebell","tg":"quads","mg":"glutes","sm":["glutes","core","adductors"],"st":["Hold a kettlebell at your shoulder with one hand.","Stand with your feet shoulder-width apart.","Squat down with your chest tall.","Drive through your heels to stand.","Switch sides after your set."],"img":"opengym/4123.webp","gif":null,"ext":1},{"id":"4124","n":"dead bug with medicine ball","bp":"waist","eq":"medicine ball","tg":"abs","mg":"lower abs","sm":["lower abs","hip flexors","core"],"st":["Lie on your back holding a medicine ball above your chest, knees bent over your hips.","Press your lower back into the floor.","Lower the ball overhead while extending the opposite leg.","Return to the start.","Alternate sides."],"img":"opengym/4124.webp","gif":null,"ext":1},{"id":"4125","n":"dumbbell face down lying shoulder press","bp":"shoulders","eq":"dumbbell","tg":"delts","mg":"triceps","sm":["triceps","upper back","rear deltoids"],"st":["Lie face down on an incline bench holding dumbbells at ear height.","Press the dumbbells up and slightly back.","Pause at the top.","Lower slowly.","Keep your chest on the bench."],"img":"opengym/4125.webp","gif":null,"ext":1},{"id":"4126","n":"barbell deadstop row with rack","bp":"back","eq":"barbell","tg":"upper back","mg":"lats","sm":["lats","biceps","rhomboids","lower back"],"st":["Set the bar on pins at knee height.","Hinge forward and grip the bar.","Row it to your lower ribs.","Lower it back to the pins and pause.","Reset your back before the next rep."],"img":"opengym/4126.webp","gif":null,"ext":1},{"id":"4127","n":"weighted dead bug","bp":"waist","eq":"weighted","tg":"abs","mg":"lower abs","sm":["lower abs","hip flexors","core"],"st":["Lie on your back holding a weight above your chest.","Raise your knees over your hips.","Extend the opposite arm and leg.","Return to the start.","Alternate sides, keeping your back flat."],"img":"opengym/4127.webp","gif":null,"ext":1},{"id":"4128","n":"weighted counterbalanced squat","bp":"upper legs","eq":"weighted","tg":"quads","mg":"glutes","sm":["glutes","core","hamstrings"],"st":["Hold a weight at chest height and stand with feet shoulder-width apart.","Extend your arms forward as you descend.","Squat until thighs are parallel.","Keep your chest tall.","Stand back up through your heels."],"img":"opengym/4128.webp","gif":null,"ext":1},{"id":"4129","n":"weighted counterbalanced skater squat","bp":"upper legs","eq":"weighted","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","core"],"st":["Hold a weight out in front and stand on one leg.","Bend your standing knee while reaching your rear leg back.","Lower until your rear knee nearly touches the floor.","Push back to standing.","Finish your reps, then switch legs."],"img":"opengym/4129.webp","gif":null,"ext":1},{"id":"4130","n":"ez bar california skullcrusher","bp":"upper arms","eq":"ez barbell","tg":"triceps","mg":"shoulders","sm":["shoulders","forearms"],"st":["Lie on a bench holding an ez bar above your chest.","Lower the bar toward your forehead.","Let it travel back past your head slightly.","Extend your arms to return.","Keep your upper arms still."],"img":"opengym/4130.webp","gif":null,"ext":1},{"id":"4131","n":"battling ropes alternating waves with kneeling get up","bp":"full body","eq":"rope","tg":"cardiovascular system","mg":"shoulders","sm":["shoulders","core","quadriceps","glutes"],"st":["Kneel holding the rope ends.","Make alternating waves with your arms.","Rise to a standing position while continuing.","Wave for a few more seconds.","Return to kneeling and repeat."],"img":"opengym/4131.webp","gif":null,"ext":1},{"id":"4132","n":"kettlebell sumo deadlift with high pull","bp":"full body","eq":"kettlebell","tg":"glutes","mg":"hamstrings","sm":["hamstrings","trapezius","shoulders","quadriceps","upper back"],"st":["Stand wide over a kettlebell and grip it with both hands.","Drive up through your legs.","Pull it to chin height with elbows high.","Lower it under control.","Keep your back flat."],"img":"opengym/4132.webp","gif":null,"ext":1},{"id":"4133","n":"kettlebell suitcase deadlift","bp":"upper legs","eq":"kettlebell","tg":"glutes","mg":"hamstrings","sm":["hamstrings","quadriceps","obliques","grip muscles"],"st":["Stand beside a kettlebell and hinge to grip it.","Keep your back flat.","Stand up without leaning sideways.","Lower it back to the floor.","Switch hands after your set."],"img":"opengym/4133.webp","gif":null,"ext":1},{"id":"4134","n":"kettlebell single leg step up","bp":"upper legs","eq":"kettlebell","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","core"],"st":["Hold a kettlebell and stand facing a box.","Place one foot on the box.","Drive through that heel to step up.","Lower slowly.","Finish all reps, then switch legs."],"img":"opengym/4134.webp","gif":null,"ext":1},{"id":"4135","n":"band split squat","bp":"upper legs","eq":"band","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","adductors"],"st":["Stand on the band in a split stance and hold the ends at your shoulders.","Lower your back knee toward the floor.","Keep your front shin vertical.","Push back up.","Switch legs after your set."],"img":"opengym/4135.webp","gif":null,"ext":1},{"id":"4136","n":"band cross abduction","bp":"upper legs","eq":"band","tg":"abductors","mg":"glutes","sm":["glutes","core"],"st":["Attach the band to a low anchor and loop it around your outer ankle.","Stand tall and hold support if needed.","Move that leg across then out to the side.","Control the return.","Switch legs after your set."],"img":"opengym/4136.webp","gif":null,"ext":1},{"id":"4137","n":"band squat twist","bp":"waist","eq":"band","tg":"obliques","mg":"glutes","sm":["glutes","quadriceps","core"],"st":["Anchor the band at chest height and stand sideways, holding the end.","Squat down.","Rise and rotate your arms away from the anchor.","Return to the center.","Complete all reps, then switch sides."],"img":"opengym/4137.webp","gif":null,"ext":1},{"id":"4138","n":"band close grip biceps curl","bp":"upper arms","eq":"band","tg":"biceps","mg":"brachialis","sm":["brachialis","forearms"],"st":["Stand on the band and grip it close to your feet with a narrow hold.","Keep your elbows at your sides.","Curl your hands to your shoulders.","Squeeze the top.","Lower slowly."],"img":"opengym/4138.webp","gif":null,"ext":1},{"id":"4139","n":"band overhead triceps extension v. 2","bp":"upper arms","eq":"band","tg":"triceps","mg":"shoulders","sm":["shoulders","forearms"],"st":["Stand on one end of the band and hold the other overhead with both hands.","Bend your elbows behind your head.","Extend your arms upward.","Keep your elbows close to your ears.","Lower under control."],"img":"opengym/4139.webp","gif":null,"ext":1},{"id":"4140","n":"band overhead single arm triceps extension","bp":"upper arms","eq":"band","tg":"triceps","mg":"shoulders","sm":["shoulders","forearms"],"st":["Stand on the band and hold the other end overhead with one hand.","Bend your elbow behind your head.","Extend your arm upward.","Keep your upper arm still.","Switch arms after your set."],"img":"opengym/4140.webp","gif":null,"ext":1},{"id":"4141","n":"band overhead single arm triceps extension v. 2","bp":"upper arms","eq":"band","tg":"triceps","mg":"shoulders","sm":["shoulders","forearms"],"st":["Anchor or stand on the band and hold it overhead in one hand.","Bend your elbow so your hand drops behind your head.","Extend your arm fully.","Keep your core tight.","Switch arms after your set."],"img":"opengym/4141.webp","gif":null,"ext":1},{"id":"4142","n":"band lying reverse grip pressdown","bp":"upper arms","eq":"band","tg":"triceps","mg":"forearms","sm":["forearms","shoulders"],"st":["Lie on your back with the band anchored overhead and grip it palms up.","Keep your elbows pointing at the ceiling.","Press your hands down toward your thighs.","Squeeze your triceps.","Return slowly."],"img":"opengym/4142.webp","gif":null,"ext":1},{"id":"4143","n":"band triceps kickback","bp":"upper arms","eq":"band","tg":"triceps","mg":"shoulders","sm":["shoulders","forearms"],"st":["Stand on the band and hinge forward holding the other end.","Pin your upper arm to your side.","Extend your elbow straight back.","Squeeze your triceps.","Return slowly, then switch arms."],"img":"opengym/4143.webp","gif":null,"ext":1},{"id":"4144","n":"band bent over lat pulldown","bp":"back","eq":"band","tg":"lats","mg":"upper back","sm":["upper back","biceps","rear deltoids"],"st":["Anchor the band high and hold it with both hands, arms extended.","Hinge at the hips with a flat back and soft knees.","Pull the band down toward your hips, driving your elbows back.","Squeeze your lats at the bottom for a moment.","Let the band rise slowly until your arms are straight again.","Keep your torso still and your neck neutral."],"img":"opengym/4144.webp","gif":null,"ext":1},{"id":"4145","n":"band close grip row","bp":"back","eq":"band","tg":"upper back","mg":"lats","sm":["lats","biceps","rhomboids"],"st":["Anchor the band at chest height and hold both ends with hands close together.","Step back until the band is taut and stand tall with soft knees.","Row your hands toward your lower ribs, elbows brushing your sides.","Squeeze your shoulder blades together at the end.","Extend your arms slowly back to the start.","Keep your shoulders down and avoid leaning back."],"img":"opengym/4145.webp","gif":null,"ext":1},{"id":"4146","n":"band standing single arm twist row","bp":"back","eq":"band","tg":"upper back","mg":"lats","sm":["lats","obliques","biceps"],"st":["Anchor the band at chest height and hold the handle in one hand.","Stand sideways to the anchor with feet shoulder width apart.","Row the handle toward your ribs while turning your torso gently toward the pulling side.","Squeeze your back at the end of the pull.","Return slowly, untwisting as your arm extends.","Finish all reps, then switch sides."],"img":"opengym/4146.webp","gif":null,"ext":1},{"id":"4147","n":"band narrow grip high row","bp":"back","eq":"band","tg":"lats","mg":"upper back","sm":["upper back","rear deltoids","biceps","rhomboids"],"st":["Anchor the band at or above head height and grip it with hands close together.","Step back until there is tension and stand tall.","Pull your hands toward your upper chest, elbows high and out.","Squeeze your shoulder blades together.","Return slowly with control.","Keep your ribs down and avoid arching your back."],"img":"opengym/4147.webp","gif":null,"ext":1},{"id":"4148","n":"band narrow grip high row v. 2","bp":"back","eq":"band","tg":"lats","mg":"upper back","sm":["upper back","rear deltoids","biceps","rhomboids"],"st":["Anchor the band high and grip it with hands close together.","Step back to create tension and stand tall.","Pull your hands toward your upper chest, elbows flaring slightly.","Pause and squeeze your shoulder blades together.","Extend your arms slowly back to the start.","Keep your torso upright throughout."],"img":"opengym/4148.webp","gif":null,"ext":1},{"id":"4149","n":"dumbbell floor fly","bp":"chest","eq":"dumbbell","tg":"pectorals","mg":"shoulders","sm":["shoulders","biceps","upper chest"],"st":["Lie on your back with knees bent and a dumbbell in each hand above your chest.","Soften your elbows slightly and keep that bend.","Open your arms wide until your upper arms touch the floor.","Pause briefly without resting your weight.","Squeeze your chest to bring the dumbbells back together above you.","Move slowly and keep your wrists stacked over your elbows."],"img":"opengym/4149.webp","gif":null,"ext":1},{"id":"4150","n":"dumbbell one arm low fly","bp":"chest","eq":"dumbbell","tg":"pectorals","mg":"upper chest","sm":["upper chest","shoulders","biceps"],"st":["Stand with feet staggered and hold a dumbbell at your side with a slight elbow bend.","Brace your core and keep your chest up.","Sweep the dumbbell out and up in an arc to chest height in front of you.","Squeeze your chest at the top.","Lower slowly along the same arc.","Finish your reps, then switch arms."],"img":"opengym/4150.webp","gif":null,"ext":1},{"id":"4151","n":"dumbbell lying floor skullcrusher","bp":"upper arms","eq":"dumbbell","tg":"triceps","mg":"shoulders","sm":["shoulders","forearms"],"st":["Lie on your back with knees bent, a dumbbell in each hand over your chest.","Keep your upper arms vertical and still.","Bend your elbows to lower the weights toward your head.","Stop when your upper arms touch the floor lightly.","Extend your elbows to press the weights back up.","Keep your elbows pointed forward and avoid flaring them."],"img":"opengym/4151.webp","gif":null,"ext":1},{"id":"4152","n":"dumbbell close grip curl","bp":"upper arms","eq":"dumbbell","tg":"biceps","mg":"brachialis","sm":["brachialis","forearms"],"st":["Stand tall holding dumbbells with palms forward and hands close together.","Pin your elbows to your sides.","Curl the weights up toward your shoulders.","Squeeze your biceps at the top.","Lower slowly until your arms are straight.","Avoid swinging your torso."],"img":"opengym/4152.webp","gif":null,"ext":1},{"id":"4153","n":"one side archer push up","bp":"chest","eq":"body weight","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders","core"],"st":["Start in a wide push up position with hands well outside your shoulders.","Keep your body in a straight line.","Shift your weight to one arm and bend that elbow while the other arm stays straight.","Lower your chest toward the bent arm side.","Push back up and shift to the centre.","Alternate or complete reps on one side, then switch."],"img":"opengym/4153.webp","gif":null,"ext":1},{"id":"4154","n":"weighted seated neutral wrist curl","bp":"lower arms","eq":"weighted","tg":"forearms","mg":"wrist flexors","sm":["wrist flexors","grip muscles"],"st":["Sit with your forearm resting on your thigh, hand hanging past the knee.","Hold the weight with a neutral grip, thumb up.","Curl your wrist up toward your forearm.","Pause at the top.","Lower slowly until your wrist is extended.","Complete all reps, then switch arms."],"img":"opengym/4154.webp","gif":null,"ext":1},{"id":"4155","n":"weighted seated calf raise","bp":"lower legs","eq":"weighted","tg":"calves","mg":"soleus","sm":["soleus","ankles"],"st":["Sit on a bench with feet flat and the weight resting on your thighs.","Place the balls of your feet on a raised edge if possible.","Lift your heels as high as you can.","Pause and squeeze your calves.","Lower your heels slowly below the edge for a stretch.","Hold the weight steady throughout."],"img":"opengym/4155.webp","gif":null,"ext":1},{"id":"4156","n":"lying leg hip side raise on floor","bp":"waist","eq":"body weight","tg":"obliques","mg":"abdominals","sm":["abdominals","hip flexors","adductors"],"st":["Lie on your side with legs stacked and straight.","Rest your head on your lower arm and brace your core.","Lift both legs together a short way off the floor.","Pause at the top, squeezing your side.","Lower slowly without touching the floor.","Complete reps, then switch sides."],"img":"opengym/4156.webp","gif":null,"ext":1},{"id":"4157","n":"dumbbell seated front and back tate press","bp":"shoulders","eq":"dumbbell","tg":"triceps","mg":"chest","sm":["chest","shoulders"],"st":["Sit upright holding dumbbells above your chest, palms facing your feet.","Keep your upper arms close to your torso.","Lower the weights with elbows flared until they touch your chest.","Extend your elbows to push the weights up and slightly forward.","Return to the start in a controlled path.","Keep your back straight and avoid arching."],"img":"opengym/4157.webp","gif":null,"ext":1},{"id":"4158","n":"weighted side crunch","bp":"waist","eq":"weighted","tg":"obliques","mg":"core","sm":["core"],"st":["Lie on your side with knees bent and hold a weight against your chest.","Support your head lightly.","Crunch your top ribs toward your hip.","Pause and squeeze your side.","Lower slowly without losing tension.","Complete all reps, then switch sides."],"img":"opengym/4158.webp","gif":null,"ext":1},{"id":"4159","n":"kick through push up","bp":"chest","eq":"body weight","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders","core"],"st":["Start in a push up position with hands under your shoulders.","Lower your chest and press back up.","Lift one hand and rotate, sweeping the opposite leg through underneath you.","Return the leg and hand to the starting position.","Repeat the push up and kick on the other side.","Stay controlled and keep your core braced."],"img":"opengym/4159.webp","gif":null,"ext":1},{"id":"4160","n":"squat hold calf raise","bp":"lower legs","eq":"body weight","tg":"calves","mg":"quadriceps","sm":["quadriceps","glutes","soleus"],"st":["Stand with feet shoulder width apart and lower into a half squat.","Hold that depth with your chest up.","Raise your heels as high as you can.","Lower your heels slowly.","Repeat while holding the squat position.","Keep your knees tracking over your toes."],"img":"opengym/4160.webp","gif":null,"ext":1},{"id":"4161","n":"dumbbell rear lunge front raise","bp":"upper legs","eq":"dumbbell","tg":"glutes","mg":"quadriceps","sm":["quadriceps","shoulders","hamstrings"],"st":["Stand tall holding a dumbbell in each hand at your thighs.","Step one foot back into a lunge.","As you lower, raise the dumbbells in front to shoulder height.","Push through your front foot to stand back up.","Lower the dumbbells as you return.","Alternate legs for each rep."],"img":"opengym/4161.webp","gif":null,"ext":1},{"id":"4162","n":"push up to knee tap","bp":"chest","eq":"body weight","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders","core"],"st":["Start in a push up position with a straight body.","Lower your chest toward the floor.","Press back up to straight arms.","Bring one knee toward the same side elbow.","Return the foot and repeat on the other side.","Keep your hips level and your core braced."],"img":"opengym/4162.webp","gif":null,"ext":1},{"id":"4163","n":"cable one arm wrist curl","bp":"lower arms","eq":"cable","tg":"forearms","mg":"wrist flexors","sm":["wrist flexors","grip muscles"],"st":["Sit by a low pulley with your forearm resting on your thigh.","Hold the handle with your palm facing up.","Curl your wrist up as far as you can.","Pause at the top.","Lower slowly under control.","Complete all reps, then switch arms."],"img":"opengym/4163.webp","gif":null,"ext":1},{"id":"4164","n":"dumbbell devils press","bp":"full body","eq":"dumbbell","tg":"delts","mg":"glutes","sm":["glutes","hamstrings","core","triceps"],"st":["Stand holding a dumbbell in each hand.","Squat and place the dumbbells on the floor, then step or jump your feet back.","Do a push up if you like.","Jump your feet forward and stand up, swinging the dumbbells overhead.","Lower the dumbbells under control.","Keep your back flat and move with rhythm."],"img":"opengym/4164.webp","gif":null,"ext":1},{"id":"4166","n":"trap bar jump squat","bp":"upper legs","eq":"trap bar","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","calves"],"st":["Stand inside a trap bar with feet shoulder width apart.","Grip the handles and stand tall.","Squat down quickly with your chest up.","Jump up explosively off the floor.","Land softly with bent knees.","Reset before the next rep."],"img":"opengym/4166.webp","gif":null,"ext":1},{"id":"4167","n":"kettlebell banded swing","bp":"upper legs","eq":"kettlebell","tg":"glutes","mg":"hamstrings","sm":["hamstrings","lower back","core"],"st":["Set up with the band around your hips and the kettlebell in front of you.","Hinge back and swing the bell between your legs.","Drive your hips forward powerfully.","Let the kettlebell rise to chest height.","Guide it back between your legs as you hinge.","Keep your back flat and arms relaxed."],"img":"opengym/4167.webp","gif":null,"ext":1},{"id":"4168","n":"jump pistol squat box","bp":"upper legs","eq":"body weight","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","calves"],"st":["Stand in front of a box on one leg, other leg forward.","Squat down on one leg to touch the box.","Drive through your heel and jump upward.","Land softly on the same leg.","Control your balance and reset.","Complete reps, then switch legs."],"img":"opengym/4168.webp","gif":null,"ext":1},{"id":"4169","n":"jumping pistol squat","bp":"upper legs","eq":"body weight","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","calves"],"st":["Stand on one leg with the other extended forward.","Lower into a single leg squat.","Explode upward off the standing leg.","Land softly on the same leg.","Sink back into the next squat.","Complete reps, then switch legs."],"img":"opengym/4169.webp","gif":null,"ext":1},{"id":"4170","n":"bear plank","bp":"waist","eq":"body weight","tg":"abs","mg":"core","sm":["core","shoulders","quadriceps"],"st":["Start on hands and knees with wrists under shoulders.","Tuck your toes and lift your knees a few centimetres off the floor.","Keep your back flat and hips level.","Brace your abs and breathe steadily.","Hold for 20-30 seconds.","Lower your knees to rest."],"img":"opengym/4170.webp","gif":null,"ext":1},{"id":"4171","n":"smith rack pull","bp":"upper legs","eq":"smith machine","tg":"glutes","mg":"hamstrings","sm":["hamstrings","lower back","upper back","grip muscles"],"st":["Set the bar at knee height in the Smith machine.","Grip the bar and set your back flat.","Drive through your feet and extend your hips.","Stand tall and squeeze your glutes.","Lower the bar to the start with control.","Keep the bar close to your legs."],"img":"opengym/4171.webp","gif":null,"ext":1},{"id":"4172","n":"bodyweight bent over rear delt fly","bp":"shoulders","eq":"body weight","tg":"delts","mg":"rear deltoids","sm":["rear deltoids","upper back","rhomboids"],"st":["Hinge forward with a flat back and arms hanging down.","Keep a slight bend in your elbows.","Raise your arms out to the sides to shoulder height.","Squeeze your shoulder blades.","Lower slowly.","Keep your neck neutral."],"img":"opengym/4172.webp","gif":null,"ext":1},{"id":"4173","n":"barbell banded romanian deadlift","bp":"upper legs","eq":"barbell","tg":"hamstrings","mg":"glutes","sm":["glutes","lower back","grip muscles"],"st":["Stand on the band with it attached to the barbell and hold the bar at your thighs.","Push your hips back with soft knees.","Lower the bar along your legs to mid shin.","Drive your hips forward to stand tall.","Squeeze your glutes at the top.","Keep your back flat throughout."],"img":"opengym/4173.webp","gif":null,"ext":1},{"id":"4174","n":"lever reverse shoulder press (plate loaded)","bp":"shoulders","eq":"leverage machine","tg":"delts","mg":"triceps","sm":["triceps","upper chest"],"st":["Adjust the seat and sit with your back against the pad.","Grip the handles with a reverse grip.","Press the handles up until your arms are extended.","Pause at the top.","Lower slowly to shoulder level.","Keep your core braced."],"img":"opengym/4174.webp","gif":null,"ext":1},{"id":"4175","n":"weighted standing shoulder press","bp":"shoulders","eq":"weighted","tg":"delts","mg":"triceps","sm":["triceps","upper chest","core"],"st":["Stand with feet shoulder width apart, weight at shoulder height.","Brace your core and squeeze your glutes.","Press the weight straight overhead.","Lock out without leaning back.","Lower slowly to your shoulders.","Keep your ribs down."],"img":"opengym/4175.webp","gif":null,"ext":1},{"id":"4176","n":"shrug (on parallel bars)","bp":"back","eq":"body weight","tg":"upper back","mg":"trapezius","sm":["trapezius"],"st":["Support yourself on parallel bars with straight arms.","Let your shoulders sink down.","Push up to elevate your shoulders toward your ears.","Pause at the top.","Lower with control.","Keep your elbows locked."],"img":"opengym/4176.webp","gif":null,"ext":1},{"id":"4177","n":"hanging scapular shrug","bp":"back","eq":"body weight","tg":"upper back","mg":"lats","sm":["lats","grip muscles","trapezius"],"st":["Hang from a pull up bar with straight arms.","Relax your shoulders up toward your ears.","Pull your shoulder blades down, lifting your body slightly.","Pause briefly.","Relax back to the hang.","Keep your elbows straight."],"img":"opengym/4177.webp","gif":null,"ext":1},{"id":"4178","n":"barbell elevated heel squat","bp":"upper legs","eq":"barbell","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","core"],"st":["Place your heels on small plates under the bar.","Set the bar on your upper back.","Brace your core and squat down.","Keep your torso upright.","Drive through your feet to stand.","Keep your knees tracking over your toes."],"img":"opengym/4178.webp","gif":null,"ext":1},{"id":"4179","n":"smith banded full squat","bp":"upper legs","eq":"smith machine","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","adductors"],"st":["Attach the band to the Smith machine and set the bar on your back.","Place feet slightly forward of the bar.","Squat as deep as you can with control.","Keep your chest up.","Drive up through your heels.","Stand tall without locking hard."],"img":"opengym/4179.webp","gif":null,"ext":1},{"id":"4180","n":"cable seated pullover","bp":"back","eq":"cable","tg":"lats","mg":"chest","sm":["chest","triceps","core"],"st":["Sit at a high pulley holding the rope or bar with straight arms.","Lean slightly forward.","Pull the handle down in an arc to your thighs.","Squeeze your lats.","Return slowly with arms straight.","Avoid bending your elbows."],"img":"opengym/4180.webp","gif":null,"ext":1},{"id":"4181","n":"weighted hang chin up","bp":"back","eq":"weighted","tg":"lats","mg":"biceps","sm":["biceps","upper back","grip muscles"],"st":["Attach weight and hang from the bar with palms facing you.","Start from straight arms.","Pull your chest toward the bar.","Get your chin over the bar.","Lower fully with control.","Avoid swinging."],"img":"opengym/4181.webp","gif":null,"ext":1},{"id":"4183","n":"dumbbell seated cuban press","bp":"shoulders","eq":"dumbbell","tg":"delts","mg":"rotator cuff","sm":["rotator cuff","rear deltoids","upper back"],"st":["Sit tall holding dumbbells at your thighs.","Row them up to chest height with elbows high.","Rotate your forearms upward.","Press the dumbbells overhead.","Reverse the path slowly.","Use light weights."],"img":"opengym/4183.webp","gif":null,"ext":1},{"id":"4184","n":"dumbbell banded bench press","bp":"chest","eq":"dumbbell","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders","upper chest"],"st":["Lie on a bench with a band across your upper back and hands.","Hold dumbbells at chest level.","Press up against the band.","Lock out at the top.","Lower slowly.","Keep your feet flat."],"img":"opengym/4184.webp","gif":null,"ext":1},{"id":"4185","n":"weighted overhead press step up","bp":"upper legs","eq":"weighted","tg":"glutes","mg":"quadriceps","sm":["quadriceps","shoulders","triceps"],"st":["Hold weight at your shoulders and stand facing a bench.","Step up with one foot.","As you stand, press the weight overhead.","Lower the weight as you step down.","Alternate legs.","Keep your core braced."],"img":"opengym/4185.webp","gif":null,"ext":1},{"id":"4186","n":"resistance band overhead squat","bp":"upper legs","eq":"resistance band","tg":"quads","mg":"glutes","sm":["glutes","shoulders","core"],"st":["Stand on the band and hold it overhead with wide grip.","Brace your core.","Squat down keeping arms overhead.","Keep your chest up.","Drive up through your feet.","Keep your arms in line with your ears."],"img":"opengym/4186.webp","gif":null,"ext":1},{"id":"4187","n":"ez bar legs side pull in sit up","bp":"waist","eq":"ez barbell","tg":"abs","mg":"obliques","sm":["obliques","hip flexors","core"],"st":["Lie on your back holding an EZ bar over your chest.","Bend your knees.","Sit up while pulling your knees to one side.","Lower slowly.","Repeat on the other side.","Keep the bar stable."],"img":"opengym/4187.webp","gif":null,"ext":1},{"id":"4188","n":"ez bar reverse crunch","bp":"waist","eq":"ez barbell","tg":"abs","mg":"lower abs","sm":["lower abs","hip flexors"],"st":["Lie on your back holding an EZ bar overhead.","Lift your legs with knees bent.","Curl your hips off the floor.","Pause at the top.","Lower slowly.","Keep your arms steady."],"img":"opengym/4188.webp","gif":null,"ext":1},{"id":"4189","n":"ez bar kneeling rollout","bp":"waist","eq":"ez barbell","tg":"abs","mg":"core","sm":["core","lats","shoulders"],"st":["Kneel holding the EZ bar on the floor.","Brace your core.","Roll forward with a flat back.","Stop before your back sags.","Pull the bar back to the start.","Keep your hips in line."],"img":"opengym/4189.webp","gif":null,"ext":1},{"id":"4190","n":"ez bar up down twist","bp":"waist","eq":"ez barbell","tg":"obliques","mg":"shoulders","sm":["shoulders","core"],"st":["Stand holding the EZ bar in front of you.","Raise it overhead.","Lower it diagonally across your body, twisting.","Return overhead.","Alternate sides.","Move with control."],"img":"opengym/4190.webp","gif":null,"ext":1},{"id":"4191","n":"dumbbell partials lateral raise","bp":"shoulders","eq":"dumbbell","tg":"delts","mg":"trapezius","sm":["trapezius","rotator cuff"],"st":["Stand holding dumbbells at your sides.","Raise them out to the sides.","Stay within the mid range, between hip and shoulder height.","Pause briefly.","Lower slowly.","Avoid shrugging."],"img":"opengym/4191.webp","gif":null,"ext":1},{"id":"4192","n":"knuckle push up","bp":"chest","eq":"body weight","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders","core","wrist flexors"],"st":["Make fists and place them under your shoulders.","Keep your body straight.","Lower your chest.","Press up.","Keep wrists neutral.","Brace your core."],"img":"opengym/4192.webp","gif":null,"ext":1},{"id":"4193","n":"cable half kneeling pallof press","bp":"waist","eq":"cable","tg":"abs","mg":"obliques","sm":["obliques","core","shoulders"],"st":["Kneel on one knee side on to a cable at chest height.","Hold the handle at your chest.","Press it straight out.","Resist the twist.","Bring it back.","Switch sides."],"img":"opengym/4193.webp","gif":null,"ext":1},{"id":"4194","n":"cable half kneeling external rotation","bp":"shoulders","eq":"cable","tg":"delts","mg":"rotator cuff","sm":["rotator cuff","rear deltoids"],"st":["Kneel on one knee beside a cable at elbow height.","Hold the handle with elbow at your side.","Rotate your forearm outward.","Pause.","Return slowly.","Switch sides."],"img":"opengym/4194.webp","gif":null,"ext":1},{"id":"4195","n":"resistance band half kneeling face pull","bp":"shoulders","eq":"resistance band","tg":"delts","mg":"rear deltoids","sm":["rear deltoids","upper back","rotator cuff"],"st":["Anchor the band at face height.","Kneel on one knee.","Pull the handles toward your face.","Flare your elbows.","Return slowly.","Keep your chest up."],"img":"opengym/4195.webp","gif":null,"ext":1},{"id":"4196","n":"cable half kneeling adductor pallof press","bp":"waist","eq":"cable","tg":"abs","mg":"adductors","sm":["adductors","obliques","core"],"st":["Kneel on one knee with the cable at chest height.","Hold the handle at your chest.","Press it forward.","Squeeze your inner thigh.","Return.","Switch sides."],"img":"opengym/4196.webp","gif":null,"ext":1},{"id":"4197","n":"cable pallof press with glute bridge","bp":"waist","eq":"cable","tg":"abs","mg":"glutes","sm":["glutes","obliques","core"],"st":["Lie on your back with a cable beside you.","Hold the handle at your chest.","Bridge your hips up.","Press the handle forward.","Return and lower.","Switch sides."],"img":"opengym/4197.webp","gif":null,"ext":1},{"id":"4198","n":"depth jump to hurdle hop","bp":"upper legs","eq":"body weight","tg":"quads","mg":"glutes","sm":["glutes","calves","hamstrings"],"st":["Stand on a box.","Step off.","Land softly.","Jump over the hurdle immediately.","Land softly.","Reset."],"img":"opengym/4198.webp","gif":null,"ext":1},{"id":"4199","n":"barbell deadlift against chains","bp":"upper legs","eq":"barbell","tg":"glutes","mg":"hamstrings","sm":["hamstrings","lower back","grip muscles"],"st":["Set chains on the bar.","Grip the bar.","Brace.","Drive your feet through the floor.","Stand tall.","Lower with control."],"img":"opengym/4199.webp","gif":null,"ext":1},{"id":"4200","n":"fly against chains","bp":"chest","eq":"dumbbell","tg":"pectorals","mg":"shoulders","sm":["shoulders","biceps"],"st":["Lie on a bench with chains.","Hold weights above your chest.","Open arms.","Stretch your chest.","Bring weights together.","Keep elbows soft."],"img":"opengym/4200.webp","gif":null,"ext":1},{"id":"4201","n":"barbell bench press against chains","bp":"chest","eq":"barbell","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders"],"st":["Lie on bench.","Unrack the bar.","Lower to chest.","Press up.","Lock out.","Keep feet planted."],"img":"opengym/4201.webp","gif":null,"ext":1},{"id":"4202","n":"landmine resistance band one arm shoulder press","bp":"shoulders","eq":"landmine","tg":"delts","mg":"triceps","sm":["triceps","upper chest","core"],"st":["Hold the landmine end at your shoulder.","Brace your core.","Press up and forward.","Lock out.","Lower slowly.","Switch arms."],"img":"opengym/4202.webp","gif":null,"ext":1},{"id":"4203","n":"barbell banded sumo deadlift","bp":"upper legs","eq":"barbell","tg":"glutes","mg":"adductors","sm":["adductors","hamstrings","lower back"],"st":["Set the band over the bar.","Stand wide.","Grip inside your legs.","Drive up.","Squeeze glutes.","Lower with control."],"img":"opengym/4203.webp","gif":null,"ext":1},{"id":"4204","n":"resistance band assisted nordic hamstring curl","bp":"upper legs","eq":"resistance band","tg":"hamstrings","mg":"glutes","sm":["glutes","calves","core"],"st":["Kneel with ankles secured.","Hold the band.","Lower your body forward.","Use the band to help.","Pull back up.","Keep hips extended."],"img":"opengym/4204.webp","gif":null,"ext":1},{"id":"4205","n":"band assisted dip","bp":"upper arms","eq":"band","tg":"triceps","mg":"chest","sm":["chest","shoulders"],"st":["Loop a band around the dip bars and set your knees or feet in it.","Grip the bars and straighten your arms with your chest up.","Lower your body until your upper arms are about parallel to the floor.","Keep your elbows close and your shoulders down.","Press back up until your arms are straight.","Use a thinner band as you get stronger."],"img":"opengym/4205.webp","gif":null,"ext":1},{"id":"4206","n":"band assisted chin up (from knee)","bp":"back","eq":"band","tg":"lats","mg":"biceps","sm":["biceps","upper back","rhomboids"],"st":["Attach a band to a pull-up bar and place one knee in the loop.","Grab the bar with an underhand, shoulder-width grip.","Hang with your arms straight and your core tight.","Pull your chest up until your chin clears the bar.","Lower yourself slowly until your arms are straight.","Switch knees halfway through your sets."],"img":"opengym/4206.webp","gif":null,"ext":1},{"id":"4207","n":"chin up around the bar","bp":"back","eq":"body weight","tg":"lats","mg":"biceps","sm":["biceps","upper back","forearms"],"st":["Grab the bar with an underhand grip and hang with straight arms.","Brace your core and pull your elbows down.","Pull your chest toward the bar, sweeping your head around one side.","Pause briefly at the top.","Lower with control back to a full hang.","Alternate the side you pass on each rep."],"img":"opengym/4207.webp","gif":null,"ext":1},{"id":"4208","n":"2 to 1 jump box","bp":"upper legs","eq":"body weight","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","calves"],"st":["Stand facing a sturdy box with your feet shoulder-width apart.","Swing your arms and jump up, landing softly on the box with both feet.","Stand tall on top of the box.","Step down with one leg first, then the other.","Reset and repeat, alternating the leading leg.","Land quietly with bent knees."],"img":"opengym/4208.webp","gif":null,"ext":1},{"id":"4209","n":"1 to 2 jump box","bp":"upper legs","eq":"body weight","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","calves"],"st":["Stand facing a sturdy box on one leg.","Drive your arms up and push off explosively from that leg.","Land softly on the box with both feet at once.","Stand fully upright before stepping down.","Complete your reps, then switch legs.","Keep your knees tracking over your toes."],"img":"opengym/4209.webp","gif":null,"ext":1},{"id":"4210","n":"kettlebell split snatch","bp":"upper legs","eq":"kettlebell","tg":"glutes","mg":"shoulders","sm":["shoulders","hamstrings","quadriceps","core"],"st":["Stand over a kettlebell in a hip hinge with a flat back.","Swing it back, then drive your hips forward.","As the bell rises, step into a split stance and punch it overhead.","Lock out your arm with the bell resting behind your wrist.","Stand up, bring your feet together and lower the bell to a swing.","Switch arms after your reps."],"img":"opengym/4210.webp","gif":null,"ext":1},{"id":"4211","n":"dumbbell 4 ways lateral raise","bp":"shoulders","eq":"dumbbell","tg":"delts","mg":"trapezius","sm":["trapezius","rotator cuff","upper back"],"st":["Stand with a light dumbbell in each hand and a slight knee bend.","Raise both arms out to your sides to shoulder height.","Lower, then raise them to the front to shoulder height.","Lower, then hinge forward slightly and raise them out to the rear.","Return and finish with a raise to the sides again.","Keep the weights light and avoid swinging."],"img":"opengym/4211.webp","gif":null,"ext":1},{"id":"4212","n":"one leg star balance","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"core","sm":["core","calves","ankles","hamstrings"],"st":["Stand on one leg with a soft knee.","Reach your free foot forward and tap lightly, then return.","Tap out to the side, then return.","Tap behind you, then return.","Keep your hips level and chest tall.","Switch legs after a set of taps."],"img":"opengym/4212.webp","gif":null,"ext":1},{"id":"4213","n":"lever banded chest press","bp":"chest","eq":"leverage machine","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders","upper chest"],"st":["Adjust the seat so the handles line up with your mid chest.","Sit back with your shoulder blades pinned to the pad.","Grip the handles and press forward until your arms are nearly straight.","Feel the band tension build as you lock out.","Lower slowly until you feel a stretch across your chest.","Keep your wrists straight."],"img":"opengym/4213.webp","gif":null,"ext":1},{"id":"4214","n":"lever low row (plate loaded)","bp":"back","eq":"leverage machine","tg":"upper back","mg":"lats","sm":["lats","biceps","rhomboids","rear deltoids"],"st":["Sit with your chest against the pad and your feet planted.","Grab both handles with straight arms.","Pull the handles toward your lower ribs, squeezing your shoulder blades.","Pause for a moment at the end.","Let the arms extend slowly under control.","Do not lean back to move the weight."],"img":"opengym/4214.webp","gif":null,"ext":1},{"id":"4215","n":"lever one arm low row (plate loaded)","bp":"back","eq":"leverage machine","tg":"upper back","mg":"lats","sm":["lats","biceps","rhomboids","rear deltoids"],"st":["Sit with your chest on the pad and grab one handle.","Start with your arm extended and shoulder relaxed forward.","Pull the handle back, driving your elbow past your torso.","Squeeze your shoulder blade toward your spine.","Lower slowly until your arm is straight.","Finish your reps, then switch sides."],"img":"opengym/4215.webp","gif":null,"ext":1},{"id":"4216","n":"climbing monkey bars","bp":"upper arms","eq":"body weight","tg":"lats","mg":"forearms","sm":["forearms","grip muscles","shoulders","biceps"],"st":["Grab the first bar with both hands and hang.","Swing your body slightly and reach for the next bar with one hand.","Release the back hand and reach for the following bar.","Keep a steady rhythm using your hips for momentum.","Continue to the end of the ladder.","Drop down softly and rest before the next pass."],"img":"opengym/4216.webp","gif":null,"ext":1},{"id":"4217","n":"cable wide neutral grip pulldown","bp":"back","eq":"cable","tg":"lats","mg":"biceps","sm":["biceps","upper back","rhomboids","forearms"],"st":["Sit at the pulldown station and lock your thighs under the pads.","Grab the wide neutral-grip handles with straight arms.","Lean back slightly and lift your chest.","Pull the handles down toward your upper chest, driving your elbows down.","Pause, then let the bar rise slowly.","Do not swing your torso."],"img":"opengym/4217.webp","gif":null,"ext":1},{"id":"4218","n":"safety bar front squat","bp":"upper legs","eq":"barbell","tg":"quads","mg":"glutes","sm":["glutes","core","upper back","hamstrings"],"st":["Set the safety bar on a rack and step under the pad.","Hold the handles, rest the pad on your shoulders and unrack.","Step back and set your feet shoulder-width apart.","Squat down while keeping your chest tall and elbows up.","Go as deep as you can with good form.","Drive up through your whole foot to stand."],"img":"opengym/4218.webp","gif":null,"ext":1},{"id":"4219","n":"safety bar elevated heel squat","bp":"upper legs","eq":"barbell","tg":"quads","mg":"glutes","sm":["glutes","core","calves","hamstrings"],"st":["Place plates or a wedge under your heels in front of the rack.","Unrack the safety bar and step onto the platform.","Keep your chest upright and brace your core.","Squat down with your knees tracking over your toes.","Pause briefly at the bottom.","Press up and rack the bar when done."],"img":"opengym/4219.webp","gif":null,"ext":1},{"id":"4220","n":"tiger tail forearm","bp":"lower arms","eq":"roller","tg":"forearms","mg":"wrist flexors","sm":["wrist flexors","wrist extensors"],"st":["Rest your forearm on a table, palm up.","Hold the tiger tail roller in your other hand.","Roll slowly from wrist to elbow with moderate pressure.","Pause on tender spots for a few seconds.","Turn your palm down and repeat.","Switch arms and roll for 30-60 seconds each."],"img":"opengym/4220.webp","gif":null,"ext":1},{"id":"4221","n":"tiger tail hamstring","bp":"upper legs","eq":"roller","tg":"hamstrings","mg":"glutes","sm":["glutes","calves"],"st":["Sit on the floor with one leg extended.","Hold the roller by both handles on the back of your thigh.","Roll from the knee toward your hip with steady pressure.","Slow down on tight spots.","Keep breathing and keep the leg relaxed.","Switch legs after 30-60 seconds."],"img":"opengym/4221.webp","gif":null,"ext":1},{"id":"4222","n":"tiger tail neck","bp":"neck","eq":"roller","tg":"levator scapulae","mg":"trapezius","sm":["trapezius","sternocleidomastoid"],"st":["Sit or stand tall with relaxed shoulders.","Hold the roller by both handles behind your neck.","Roll gently up and down along one side with light pressure.","Avoid pressing on the spine itself.","Repeat on the other side.","Roll for 30-60 seconds and stop if it hurts."],"img":"opengym/4222.webp","gif":null,"ext":1},{"id":"4223","n":"tiger tail peroneal","bp":"lower legs","eq":"roller","tg":"calves","mg":"shins","sm":["shins","ankles","soleus"],"st":["Sit with your leg bent or extended and the outer shin facing up.","Hold the roller by the handles on the outside of your lower leg.","Roll from the ankle to just below the knee.","Use gentle pressure and avoid the bone.","Pause on any tight areas.","Switch legs after 30-60 seconds."],"img":"opengym/4223.webp","gif":null,"ext":1},{"id":"4224","n":"cable lying pallof press","bp":"waist","eq":"cable","tg":"abs","mg":"obliques","sm":["obliques","core","shoulders"],"st":["Lie on your back beside a low cable pulley with a handle in both hands.","Hold the handle at your chest, arms bent.","Brace your core to stay flat.","Press your arms straight up while resisting the cable pull.","Hold a second, then bring the handle back to your chest.","Finish your reps and switch sides."],"img":"opengym/4224.webp","gif":null,"ext":1},{"id":"4225","n":"cable lying upright row","bp":"shoulders","eq":"cable","tg":"delts","mg":"trapezius","sm":["trapezius","biceps","upper back"],"st":["Lie on your back with your feet toward a low pulley.","Hold a bar or handle with an overhand grip, arms straight.","Pull the handle up toward your chin, leading with your elbows.","Keep the handle close to your body.","Pause at the top.","Lower slowly until your arms are straight."],"img":"opengym/4225.webp","gif":null,"ext":1},{"id":"4226","n":"cable lying shrug","bp":"back","eq":"cable","tg":"traps","mg":"upper back","sm":["upper back","trapezius","forearms"],"st":["Lie on your back with a low pulley near your feet.","Hold the handle with straight arms down by your sides.","Shrug your shoulders toward your ears.","Squeeze at the top for a second.","Lower slowly to a full stretch.","Keep your arms straight throughout."],"img":"opengym/4226.webp","gif":null,"ext":1},{"id":"4227","n":"cable lying front raise","bp":"shoulders","eq":"cable","tg":"delts","mg":"upper chest","sm":["upper chest","shoulders","trapezius"],"st":["Lie on your back with your head toward a low pulley.","Hold the handle with straight arms by your hips.","Raise your arms in an arc until they point straight up.","Pause at the top.","Lower slowly back toward your thighs.","Keep your ribs down and core braced."],"img":"opengym/4227.webp","gif":null,"ext":1},{"id":"4228","n":"cable half kneeling push pull","bp":"waist","eq":"cable","tg":"abs","mg":"obliques","sm":["obliques","shoulders","upper back","core"],"st":["Kneel on one knee between two cable stations, holding a handle in each hand.","Keep your torso tall and your core braced.","Press one handle forward while pulling the other toward your ribs.","Return to the start under control.","Do not let your torso twist.","Switch your kneeling leg after a set."],"img":"opengym/4228.webp","gif":null,"ext":1},{"id":"4229","n":"assault run","bp":"cardio","eq":"body weight","tg":"cardiovascular system","mg":"quadriceps","sm":["quadriceps","hamstrings","calves","glutes"],"st":["Step onto the curved treadmill and hold the handles.","Lean slightly forward and begin to run.","Drive your knees and push the belt back with each stride.","Keep a steady rhythm, or alternate sprints and rest.","Land on the balls of your feet.","Slow down gradually to finish."],"img":"opengym/4229.webp","gif":null,"ext":1},{"id":"4230","n":"kettlebell bottoms up to knee turkish get up","bp":"full body","eq":"kettlebell","tg":"abs","mg":"shoulders","sm":["shoulders","glutes","core","quadriceps","rotator cuff"],"st":["Lie on your back holding a kettlebell upside down in one hand, arm straight up.","Bend the same-side knee and plant the foot.","Roll onto your elbow, then your hand.","Lift your hips and sweep the straight leg back to kneel.","Reverse the steps slowly to lie down.","Keep your eyes on the bell and switch sides after your reps."],"img":"opengym/4230.webp","gif":null,"ext":1},{"id":"4231","n":"weighted seated supination","bp":"lower arms","eq":"weighted","tg":"forearms","mg":"biceps","sm":["biceps","wrist flexors"],"st":["Sit with your forearm resting on your thigh, hand over the knee.","Hold a weighted handle or dumbbell end in your hand.","Start with your palm facing down.","Rotate your forearm slowly until your palm faces up.","Return slowly to the start.","Switch arms after your reps."],"img":"opengym/4231.webp","gif":null,"ext":1},{"id":"4232","n":"weighted seated reverse wrist curl","bp":"lower arms","eq":"weighted","tg":"forearms","mg":"wrist extensors","sm":["wrist extensors","grip muscles"],"st":["Sit with your forearms on your thighs, palms facing down.","Let your hands hang over your knees holding weights.","Lower your wrists to stretch the forearms.","Curl your wrists up as high as you can.","Lower slowly.","Keep your forearms still on your thighs."],"img":"opengym/4232.webp","gif":null,"ext":1},{"id":"4233","n":"weighted seated one arm wrist curl","bp":"lower arms","eq":"weighted","tg":"forearms","mg":"wrist flexors","sm":["wrist flexors","grip muscles"],"st":["Sit and rest one forearm on your thigh, palm up.","Let the weight roll toward your fingertips.","Curl your wrist up as far as you can.","Pause at the top.","Lower slowly.","Finish your reps and switch arms."],"img":"opengym/4233.webp","gif":null,"ext":1},{"id":"4234","n":"weighted seated one arm reverse wrist curl","bp":"lower arms","eq":"weighted","tg":"forearms","mg":"wrist extensors","sm":["wrist extensors","grip muscles"],"st":["Sit and rest one forearm on your thigh, palm down.","Let your hand hang over your knee with the weight.","Lower your wrist for a stretch.","Lift your hand up as high as you can.","Lower slowly under control.","Complete your reps and switch arms."],"img":"opengym/4234.webp","gif":null,"ext":1},{"id":"4235","n":"dumbbell seated bent over rear delt row","bp":"shoulders","eq":"dumbbell","tg":"delts","mg":"rear deltoids","sm":["rear deltoids","upper back","rhomboids","trapezius"],"st":["Sit at the end of a bench with a dumbbell in each hand.","Lean forward with a flat back, arms hanging.","Pull the weights toward your sides with elbows flared out.","Squeeze your rear delts and upper back.","Lower slowly.","Keep your chest close to your thighs."],"img":"opengym/4235.webp","gif":null,"ext":1},{"id":"4236","n":"dumbbell incline two front raise with chest support","bp":"shoulders","eq":"dumbbell","tg":"delts","mg":"upper chest","sm":["upper chest","trapezius","rotator cuff"],"st":["Set a bench to an incline and lie chest down on it.","Hold a dumbbell in each hand, arms hanging.","Raise both arms forward to shoulder height or just above.","Pause for a second.","Lower under control.","Keep your head neutral and your movement smooth."],"img":"opengym/4236.webp","gif":null,"ext":1},{"id":"4237","n":"dumbbell seated close grip press","bp":"shoulders","eq":"dumbbell","tg":"delts","mg":"triceps","sm":["triceps","upper chest","trapezius"],"st":["Sit upright on a bench with back support, dumbbells at shoulder height.","Hold them close together with palms facing each other.","Press them overhead until your arms are straight.","Keep your core tight and ribs down.","Lower slowly back to your shoulders.","Do not arch your lower back."],"img":"opengym/4237.webp","gif":null,"ext":1},{"id":"4238","n":"dumbbell seated lateral to front raise","bp":"shoulders","eq":"dumbbell","tg":"delts","mg":"upper chest","sm":["upper chest","trapezius","rotator cuff"],"st":["Sit tall on a bench holding light dumbbells at your sides.","Raise both arms out to the sides to shoulder height.","Lower them back to your sides.","Raise both arms to the front to shoulder height.","Lower and repeat.","Avoid leaning back or swinging."],"img":"opengym/4238.webp","gif":null,"ext":1},{"id":"4239","n":"dumbbell one arm reverse fly (with support) v. 2","bp":"shoulders","eq":"dumbbell","tg":"delts","mg":"rear deltoids","sm":["rear deltoids","upper back","rhomboids","trapezius"],"st":["Hinge forward and brace your free hand on a bench or support.","Hold a light dumbbell hanging straight down.","Raise the dumbbell out to the side with a slight elbow bend.","Lift until your arm is about parallel to the floor.","Pause and lower slowly.","Finish your reps and switch arms."],"img":"opengym/4239.webp","gif":null,"ext":1},{"id":"4240","n":"resistance band horizontal pallof press","bp":"waist","eq":"resistance band","tg":"abs","mg":"obliques","sm":["obliques","core","shoulders"],"st":["Anchor a band at chest height and stand sideways to it.","Hold the handle at your chest with both hands.","Step away until the band is taut and brace your core.","Press your hands straight out in front of you.","Hold for a second without twisting, then bring them back.","Complete your reps and switch sides."],"img":"opengym/4240.webp","gif":null,"ext":1},{"id":"4241","n":"resistance band shuttle","bp":"upper legs","eq":"resistance band","tg":"abductors","mg":"glutes","sm":["glutes","quadriceps","calves","core"],"st":["Anchor a band at hip height or place it around your waist with a partner or post.","Get into a slight squat with your chest up.","Shuffle sideways several steps against the tension.","Keep your feet from crossing.","Shuffle back the other way under control.","Stay low throughout."],"img":"opengym/4241.webp","gif":null,"ext":1},{"id":"4242","n":"broad jump to vertical","bp":"upper legs","eq":"body weight","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","calves","core"],"st":["Stand with your feet shoulder-width apart and swing your arms back.","Jump forward as far as you can.","Land softly with bent knees.","Immediately explode into a vertical jump with your arms up.","Land softly and reset.","Take a short rest between reps."],"img":"opengym/4242.webp","gif":null,"ext":1},{"id":"4243","n":"medicine ball overhead throw","bp":"full body","eq":"medicine ball","tg":"abs","mg":"shoulders","sm":["shoulders","lats","glutes","triceps"],"st":["Stand with your feet shoulder-width apart holding a medicine ball overhead.","Lean back slightly and brace your core.","Throw the ball forward or against a wall as hard as you can.","Follow through with your arms.","Catch or pick up the ball and reset.","Keep your back from over-arching."],"img":"opengym/4243.webp","gif":null,"ext":1},{"id":"4244","n":"kettlebell overhead carry","bp":"full body","eq":"kettlebell","tg":"delts","mg":"core","sm":["core","trapezius","forearms","obliques"],"st":["Clean and press a kettlebell overhead with one arm.","Lock out your elbow with the bell stable.","Stand tall with your ribs down.","Walk forward with slow, controlled steps.","Keep your wrist straight and avoid leaning.","Lower the bell and repeat on the other arm."],"img":"opengym/4244.webp","gif":null,"ext":1},{"id":"4245","n":"single leg board jump","bp":"upper legs","eq":"body weight","tg":"quads","mg":"glutes","sm":["glutes","calves","hamstrings"],"st":["Stand on one leg next to or in front of a board.","Bend slightly and swing your arms.","Jump up and across or onto the board.","Land softly on the same leg with a bent knee.","Hold the landing for a second.","Finish your reps and switch legs."],"img":"opengym/4245.webp","gif":null,"ext":1},{"id":"4246","n":"landmine front squat","bp":"upper legs","eq":"landmine","tg":"quads","mg":"glutes","sm":["glutes","core","shoulders","hamstrings"],"st":["Load the landmine bar and hold the end against your chest with both hands.","Stand with your feet shoulder-width apart.","Brace and squat down, keeping your chest tall.","Go as deep as you can with a flat back.","Drive up through your whole foot.","Keep your elbows pointing down."],"img":"opengym/4246.webp","gif":null,"ext":1},{"id":"4247","n":"landmine romanian deadlift v. 2","bp":"upper legs","eq":"landmine","tg":"hamstrings","mg":"glutes","sm":["glutes","lower back","core","forearms"],"st":["Hold the end of the landmine bar with both hands in front of your thighs.","Stand with soft knees and a flat back.","Push your hips back and slide the bar down your legs.","Lower until you feel a hamstring stretch.","Drive your hips forward to stand.","Squeeze your glutes at the top."],"img":"opengym/4247.webp","gif":null,"ext":1},{"id":"4248","n":"dumbbell straight arm crunch","bp":"waist","eq":"dumbbell","tg":"abs","mg":"lower abs","sm":["lower abs","core","shoulders"],"st":["Lie on your back with your knees bent and feet flat.","Hold a dumbbell with both hands, arms straight up.","Curl your shoulders off the floor, reaching toward the ceiling.","Squeeze your abs at the top.","Lower slowly.","Keep your arms straight and your neck relaxed."],"img":"opengym/4248.webp","gif":null,"ext":1},{"id":"4249","n":"dumbbell straight leg russian twist","bp":"waist","eq":"dumbbell","tg":"obliques","mg":"hip flexors","sm":["hip flexors","core"],"st":["Sit with your legs straight out and heels just off the floor.","Lean back slightly with a flat back.","Hold a dumbbell in both hands in front of your chest.","Rotate your torso to one side, then the other.","Keep your legs steady.","Move smoothly and breathe."],"img":"opengym/4249.webp","gif":null,"ext":1},{"id":"4250","n":"dumbbell v up v. 2","bp":"waist","eq":"dumbbell","tg":"abs","mg":"lower abs","sm":["lower abs","hip flexors","core"],"st":["Lie on your back with your legs straight, holding a dumbbell overhead.","Brace your core.","Lift your legs and torso together, reaching the dumbbell toward your feet.","Form a V at the top.","Lower slowly with control.","Keep your lower back pressed down."],"img":"opengym/4250.webp","gif":null,"ext":1},{"id":"4251","n":"dumbbell straight arm twisting sit up","bp":"waist","eq":"dumbbell","tg":"obliques","mg":"abdominals","sm":["abdominals","hip flexors","shoulders"],"st":["Lie on your back with knees bent, holding a dumbbell over your chest.","Sit up while keeping your arms straight.","Twist toward one side at the top.","Return to centre and lower slowly.","Alternate sides on each rep.","Keep your feet down and movement controlled."],"img":"opengym/4251.webp","gif":null,"ext":1},{"id":"4252","n":"weighted crunch v. 2","bp":"waist","eq":"weighted","tg":"abs","mg":"lower abs","sm":["lower abs","core"],"st":["Lie on your back with knees bent and feet flat.","Hold a weight against your chest.","Curl your shoulders and upper back off the floor.","Squeeze your abs at the top.","Lower slowly.","Keep your chin off your chest."],"img":"opengym/4252.webp","gif":null,"ext":1},{"id":"4253","n":"medicine ball crunch v. 2","bp":"waist","eq":"medicine ball","tg":"abs","mg":"lower abs","sm":["lower abs","core","shoulders"],"st":["Lie on your back with knees bent and feet flat.","Hold a medicine ball against your chest or overhead.","Curl your shoulders off the floor.","Reach the ball toward your knees.","Lower slowly.","Keep your lower back on the floor."],"img":"opengym/4253.webp","gif":null,"ext":1},{"id":"4254","n":"single leg vertical jump","bp":"upper legs","eq":"body weight","tg":"quads","mg":"glutes","sm":["glutes","calves","hamstrings"],"st":["Stand on one leg with a slight knee bend.","Swing your arms back.","Jump straight up as high as you can.","Land softly on the same leg.","Reset your balance.","Finish your reps and switch legs."],"img":"opengym/4254.webp","gif":null,"ext":1},{"id":"4255","n":"straight leg hip bridge","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"hamstrings","sm":["hamstrings","lower back","core"],"st":["Lie on your back with your legs straight and heels on the floor.","Place your arms by your sides.","Press through your heels and lift your hips.","Form a straight line from shoulders to heels.","Squeeze your glutes at the top.","Lower slowly."],"img":"opengym/4255.webp","gif":null,"ext":1},{"id":"4256","n":"stepdown squat","bp":"upper legs","eq":"body weight","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","calves"],"st":["Stand on a step with one foot hanging off the edge.","Hold your arms in front for balance.","Squat down on the standing leg and lower the free heel to the floor.","Keep your knee tracking over your toes.","Press back up to the start.","Finish your reps and switch legs."],"img":"opengym/4256.webp","gif":null,"ext":1},{"id":"4257","n":"shuffle","bp":"cardio","eq":"body weight","tg":"cardiovascular system","mg":"glutes","sm":["glutes","quadriceps","calves","adductors"],"st":["Stand with your feet slightly wider than your shoulders and knees bent.","Keep your chest up and your weight on your toes.","Step sideways without crossing your feet.","Move quickly for a few steps.","Change direction and shuffle back.","Stay low throughout."],"img":"opengym/4257.webp","gif":null,"ext":1},{"id":"4258","n":"backwards run","bp":"cardio","eq":"body weight","tg":"cardiovascular system","mg":"quadriceps","sm":["quadriceps","calves","hamstrings","glutes"],"st":["Find a clear, flat area or treadmill at a low speed.","Stand tall with your arms bent.","Run backwards, landing on the balls of your feet.","Glance over your shoulder from time to time.","Keep a steady, controlled pace.","Slow down gradually to finish."],"img":"opengym/4258.webp","gif":null,"ext":1},{"id":"4259","n":"walking on elliptical machine v. 7","bp":"cardio","eq":"elliptical machine","tg":"cardiovascular system","mg":"quadriceps","sm":["quadriceps","glutes","hamstrings","calves"],"st":["Step onto the pedals and hold the handles lightly.","Start moving in a smooth, walking-style stride.","Stand tall with your shoulders relaxed and core braced.","Choose a moderate resistance and keep a steady pace.","Continue for 10 to 30 minutes, depending on your fitness, then cool down slowly."],"img":"opengym/4259.webp","gif":null,"ext":1},{"id":"4278","n":"circles knee stretch v. 2","bp":"lower legs","eq":"body weight","tg":"calves","mg":"ankles","sm":["ankles","hamstrings"],"st":["Stand with your feet together and bend your knees slightly.","Place your hands on your knees for support.","Slowly rotate your knees in a circle in one direction.","Keep the movement smooth and controlled.","Switch to the other direction after 8 to 10 circles."],"img":"opengym/4278.webp","gif":null,"ext":1},{"id":"4279","n":"boat stretch","bp":"waist","eq":"body weight","tg":"abs","mg":"obliques","sm":["obliques","hip flexors","lower back"],"st":["Lie on your stomach with your legs together.","Place your hands under your shoulders.","Press up, lifting your chest and straightening your arms.","Keep your hips on the floor.","Hold for 20-30 seconds.","Lower slowly and relax."],"img":"opengym/4279.webp","gif":null,"ext":1},{"id":"4280","n":"ceiling look stretch v. 2","bp":"upper legs","eq":"body weight","tg":"quads","mg":"hip flexors","sm":["hip flexors","core"],"st":["Stand tall with your feet hip-width apart.","Reach both arms overhead and slightly back.","Tilt your head back to look at the ceiling while pressing your hips forward.","Keep your core engaged so your lower back is not over-arched.","Hold for 20-30 seconds, breathing steadily, then relax."],"img":"opengym/4280.webp","gif":null,"ext":1},{"id":"4282","n":"feet and ankles stretch","bp":"lower legs","eq":"body weight","tg":"calves","mg":"ankles","sm":["ankles","feet","shins"],"st":["Sit on a chair or the floor with one leg extended.","Point your toes away from you.","Hold for 15 seconds.","Pull your toes back toward your shin.","Hold for another 15 seconds.","Switch legs and repeat."],"img":"opengym/4282.webp","gif":null,"ext":1},{"id":"4283","n":"feet and ankles rotation stretch","bp":"lower legs","eq":"body weight","tg":"calves","mg":"ankles","sm":["ankles","feet","shins"],"st":["Sit with one leg extended or crossed over your knee.","Hold your lower leg steady.","Draw slow circles with your foot.","Do 10 circles in one direction.","Switch to the other direction.","Repeat on the other foot."],"img":"opengym/4283.webp","gif":null,"ext":1},{"id":"4286","n":"hip circles stretch","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"hip flexors","sm":["hip flexors","core","lower back"],"st":["Stand with your feet slightly wider than shoulder width.","Place your hands on your hips.","Rotate your hips in a wide circle.","Do 10 circles in one direction.","Reverse and circle the other way.","Keep your shoulders still and your knees soft."],"img":"opengym/4286.webp","gif":null,"ext":1},{"id":"4287","n":"knee raise","bp":"upper legs","eq":"body weight","tg":"hip flexors","mg":"quadriceps","sm":["quadriceps","core","glutes"],"st":["Stand tall with your arms at your sides.","Lift one knee up toward your chest.","Hold it for a moment.","Lower the foot with control.","Alternate legs.","Keep your standing leg steady and your back straight."],"img":"opengym/4287.webp","gif":null,"ext":1},{"id":"4288","n":"middle back stretch","bp":"back","eq":"body weight","tg":"upper back","mg":"rhomboids","sm":["rhomboids","lats","trapezius"],"st":["Stand or sit and clasp your hands in front of you.","Straighten your arms and push them forward.","Round your upper back and tuck your chin.","Feel the stretch between your shoulder blades.","Hold for 20-30 seconds.","Release slowly and repeat."],"img":"opengym/4288.webp","gif":null,"ext":1},{"id":"4290","n":"dumbbell static lunge","bp":"upper legs","eq":"dumbbell","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","adductors","core"],"st":["Hold a dumbbell in each hand and stand in a long split stance, rear heel lifted.","Keep your torso upright and core braced.","Bend both knees and lower until the back knee nearly touches the floor.","Press through the front heel to stand back up without moving your feet.","Finish your reps, then switch legs."],"img":"opengym/4290.webp","gif":null,"ext":1},{"id":"4291","n":"dumbbell single leg glute bridge","bp":"upper legs","eq":"dumbbell","tg":"glutes","mg":"hamstrings","sm":["hamstrings","core","lower back"],"st":["Lie on your back with one knee bent, foot flat, and the other leg extended or raised.","Rest a dumbbell across your hips and hold it steady.","Drive through the planted heel and lift your hips until your body forms a straight line.","Squeeze your glute at the top for a second.","Lower with control and repeat, then switch legs."],"img":"opengym/4291.webp","gif":null,"ext":1},{"id":"4292","n":"dumbbell lying hamstring curl","bp":"upper legs","eq":"dumbbell","tg":"hamstrings","mg":"calves","sm":["calves","glutes"],"st":["Lie face down on a bench and grip the edge for support.","Have a dumbbell gripped between your feet, or placed by a partner, with legs straight.","Bend your knees and curl the weight toward your glutes.","Pause briefly at the top without lifting your hips.","Lower slowly until your legs are almost straight."],"img":"opengym/4292.webp","gif":null,"ext":1},{"id":"4293","n":"dumbbell straight legs deadlift","bp":"upper legs","eq":"dumbbell","tg":"hamstrings","mg":"glutes","sm":["glutes","lower back","grip muscles"],"st":["Stand with feet hip-width apart, holding a dumbbell in each hand in front of your thighs.","Keep your legs almost straight with a soft knee and a flat back.","Push your hips back and lower the weights along your legs until you feel a hamstring stretch.","Drive your hips forward to stand tall and squeeze your glutes."],"img":"opengym/4293.webp","gif":null,"ext":1},{"id":"4294","n":"bodyweight overhead squat","bp":"upper legs","eq":"body weight","tg":"quads","mg":"glutes","sm":["glutes","shoulders","core","hamstrings","upper back"],"st":["Stand with feet shoulder-width apart and raise both arms straight overhead.","Brace your core and keep your arms in line with your ears.","Sit your hips back and down into a deep squat, chest tall.","Drive through your heels to stand, keeping your arms locked overhead."],"img":"opengym/4294.webp","gif":null,"ext":1},{"id":"4295","n":"dumbbell walking lunge","bp":"upper legs","eq":"dumbbell","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","calves","core"],"st":["Stand tall holding a dumbbell in each hand at your sides.","Step forward with one leg and lower until both knees are about 90 degrees.","Keep your torso upright and your front knee over your ankle.","Push through the front foot and bring the back leg forward into the next step.","Alternate legs for the desired number of steps."],"img":"opengym/4295.webp","gif":null,"ext":1},{"id":"4296","n":"crossover kneeling hip flexor stretch","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"hip flexors","sm":["hip flexors","quadriceps","obliques"],"st":["Kneel on one knee with the other foot forward in a lunge, on a mat.","Tuck your pelvis slightly and keep your torso upright.","Reach the arm on the kneeling side up and across toward the opposite side.","Shift your hips gently forward until you feel the stretch at the front of the hip.","Hold for 20-30 seconds, then switch sides."],"img":"opengym/4296.webp","gif":null,"ext":1},{"id":"4299","n":"quadriceps lying stretch","bp":"upper legs","eq":"body weight","tg":"quads","mg":"hip flexors","sm":["hip flexors","shins"],"st":["Lie on your side with your legs stacked and your head resting on one arm.","Bend the top knee and grab that ankle with your top hand.","Pull your heel toward your glutes while keeping your knees close together.","Hold for 20-30 seconds, then switch sides."],"img":"opengym/4299.webp","gif":null,"ext":1},{"id":"4307","n":"seated twist (straight arm)","bp":"waist","eq":"body weight","tg":"obliques","mg":"abdominals","sm":["abdominals","lower back","shoulders"],"st":["Sit tall on the floor with your legs crossed or extended.","Extend both arms straight out to the sides at shoulder height.","Rotate your torso slowly to one side, keeping your spine long.","Hold for a moment, then rotate to the other side.","Repeat for 8-10 slow rotations each way."],"img":"opengym/4307.webp","gif":null,"ext":1},{"id":"4309","n":"single leg stretch (bent knee)","bp":"waist","eq":"body weight","tg":"abs","mg":"hip flexors","sm":["hip flexors","obliques","quadriceps"],"st":["Lie on your back, lift your head and shoulders, and bring both knees toward your chest.","Place your hands on one shin and extend the other leg out low.","Switch legs smoothly, drawing the other knee in.","Keep your lower back pressed down and your abs tight.","Continue alternating with a steady breath rhythm."],"img":"opengym/4309.webp","gif":null,"ext":1},{"id":"4310","n":"single straight leg stretch","bp":"waist","eq":"body weight","tg":"abs","mg":"hip flexors","sm":["hip flexors","hamstrings","obliques"],"st":["Lie on your back, lift your head and shoulders off the mat.","Extend one leg straight up and the other hovering low.","Hold the raised leg with both hands and pulse twice toward you.","Switch legs and repeat, keeping your torso steady.","Keep your lower back anchored throughout."],"img":"opengym/4310.webp","gif":null,"ext":1},{"id":"4312","n":"slopes towards stretch","bp":"back","eq":"body weight","tg":"lats","mg":"obliques","sm":["obliques","shoulders","lower back"],"st":["Stand tall with feet hip-width apart.","Raise one arm overhead and keep the other hand resting on your hip.","Lean slowly toward the opposite side, lengthening along the raised arm.","Hold for 20-30 seconds while breathing steadily.","Return to upright and switch sides."],"img":"opengym/4312.webp","gif":null,"ext":1},{"id":"4314","n":"spinal stretch (on stability ball)","bp":"waist","eq":"stability ball","tg":"spine","mg":"lats","sm":["lats","shoulders","core"],"st":["Kneel in front of a stability ball and place your forearms or hands on top.","Roll the ball forward as you sink your hips back.","Let your head drop between your arms and lengthen your spine.","Hold for 20-30 seconds, breathing deeply.","Roll the ball back in to come up."],"img":"opengym/4314.webp","gif":null,"ext":1},{"id":"4315","n":"spine stretch forward","bp":"waist","eq":"body weight","tg":"spine","mg":"hamstrings","sm":["hamstrings","lower back","core"],"st":["Sit tall with legs extended hip-width apart and arms reaching forward.","Flex your feet and lift your torso up out of your hips.","Curl your chin to your chest and round forward, reaching past your toes.","Hold for a breath, then stack your spine back up slowly.","Repeat for several slow reps."],"img":"opengym/4315.webp","gif":null,"ext":1},{"id":"4318","n":"dumbbell pullover on floor","bp":"back","eq":"dumbbell","tg":"lats","mg":"chest","sm":["chest","triceps","core"],"st":["Lie on your back with knees bent and hold one dumbbell with both hands above your chest.","Keep a slight bend in your elbows.","Lower the weight in an arc behind your head until your upper arms touch the floor.","Pull it back over your chest using your lats.","Keep your ribs down and core tight throughout."],"img":"opengym/4318.webp","gif":null,"ext":1},{"id":"4322","n":"standing side bend (bent arm) v. 2","bp":"waist","eq":"body weight","tg":"obliques","mg":"abdominals","sm":["abdominals","lower back"],"st":["Stand with feet shoulder-width apart and one hand behind your head, elbow bent.","Place your other hand on your hip.","Bend sideways toward the hand on your hip without leaning forward.","Squeeze your side to return upright.","Finish your reps, then switch sides."],"img":"opengym/4322.webp","gif":null,"ext":1},{"id":"4326","n":"dumbbell bent arm pullover","bp":"chest","eq":"dumbbell","tg":"pectorals","mg":"lats","sm":["lats","triceps","shoulders"],"st":["Lie back on a bench holding one dumbbell with both hands above your chest.","Bend your elbows slightly and keep them bent throughout.","Lower the dumbbell back over your head until you feel a stretch in your chest.","Keep your ribs down and your core braced.","Pull the dumbbell back over your chest and repeat."],"img":"opengym/4326.webp","gif":null,"ext":1},{"id":"4327","n":"sled vertical leg press","bp":"upper legs","eq":"sled machine","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","adductors","calves"],"st":["Lie on your back under the sled and place your feet shoulder-width on the platform.","Release the safety catches and lower the platform until your knees are deeply bent.","Keep your lower back flat on the pad.","Press the platform up without locking your knees.","Lower under control for each rep."],"img":"opengym/4327.webp","gif":null,"ext":1},{"id":"4328","n":"standing scissors","bp":"full body","eq":"body weight","tg":"cardiovascular system","mg":"glutes","sm":["glutes","quadriceps","hamstrings","calves"],"st":["Stand tall with one foot forward and one back, arms ready.","Hop lightly and switch your leg positions in the air.","Swing your arms opposite to your legs for balance.","Land softly on the balls of your feet.","Keep a quick, steady rhythm for the set."],"img":"opengym/4328.webp","gif":null,"ext":1},{"id":"4329","n":"push with chair","bp":"chest","eq":"body weight","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders","core"],"st":["Place a stable chair against a wall and set your hands on the seat edge.","Walk your feet back until your body is straight.","Lower your chest toward the seat, elbows at about 45 degrees.","Push back up until your arms are straight.","Keep your core tight and hips level."],"img":"opengym/4329.webp","gif":null,"ext":1},{"id":"4330","n":"reverse crunch kick","bp":"waist","eq":"body weight","tg":"abs","mg":"lower abs","sm":["lower abs","hip flexors","quadriceps"],"st":["Lie on your back with arms by your sides and knees bent over your hips.","Curl your hips off the floor, bringing your knees toward your chest.","Kick your feet up toward the ceiling.","Lower your hips slowly and bend your knees again.","Avoid swinging; use your abs to lift."],"img":"opengym/4330.webp","gif":null,"ext":1},{"id":"4331","n":"crunch single leg lift","bp":"waist","eq":"body weight","tg":"abs","mg":"lower abs","sm":["lower abs","hip flexors","obliques"],"st":["Lie on your back with knees bent and hands behind your head.","Extend one leg and lift it a few inches off the floor.","Curl your shoulders up toward your hips.","Lower slowly, then repeat.","Switch legs halfway through or alternate each rep."],"img":"opengym/4331.webp","gif":null,"ext":1},{"id":"4332","n":"crunch hold","bp":"waist","eq":"body weight","tg":"abs","mg":"obliques","sm":["obliques","hip flexors"],"st":["Lie on your back with knees bent and feet flat.","Place your hands lightly behind your head or across your chest.","Curl your head and shoulders off the floor.","Hold the top position for 20-30 seconds, breathing steadily.","Lower down with control."],"img":"opengym/4332.webp","gif":null,"ext":1},{"id":"4333","n":"bench reverse crunch circle","bp":"waist","eq":"body weight","tg":"abs","mg":"lower abs","sm":["lower abs","hip flexors","obliques"],"st":["Lie on a bench and grip behind your head for support.","Bring your knees up over your hips.","Curl your hips up and draw a small circle with your knees.","Reverse the circle on the next rep.","Lower your hips slowly each time."],"img":"opengym/4333.webp","gif":null,"ext":1},{"id":"4334","n":"side plank oblique crunch","bp":"waist","eq":"body weight","tg":"obliques","mg":"abdominals","sm":["abdominals","shoulders","glutes"],"st":["Set up in a side plank on one forearm, feet stacked or staggered.","Put your free hand behind your head.","Bring your top knee and elbow together beneath your torso.","Extend back to the side plank position.","Complete your reps, then switch sides."],"img":"opengym/4334.webp","gif":null,"ext":1},{"id":"4335","n":"dumbbell side bend v. 2","bp":"waist","eq":"dumbbell","tg":"obliques","mg":"abdominals","sm":["abdominals","lower back"],"st":["Stand tall holding a dumbbell in one hand at your side.","Place your other hand behind your head.","Bend sideways toward the weighted side, keeping your hips still.","Squeeze the opposite side to return upright.","Finish your reps, then switch hands."],"img":"opengym/4335.webp","gif":null,"ext":1},{"id":"4338","n":"barbell spider curl","bp":"upper arms","eq":"barbell","tg":"biceps","mg":"brachialis","sm":["brachialis","forearms"],"st":["Lie chest-down on an incline bench with your arms hanging and a barbell in your hands.","Grip the bar with palms facing up, shoulder-width.","Curl the bar toward your shoulders without moving your upper arms.","Squeeze at the top.","Lower slowly to full extension."],"img":"opengym/4338.webp","gif":null,"ext":1},{"id":"4339","n":"barbell pullover v. 2","bp":"back","eq":"barbell","tg":"lats","mg":"chest","sm":["chest","triceps","core"],"st":["Lie on a bench holding a barbell over your chest with a close grip.","Keep a slight bend in your elbows.","Lower the bar in an arc behind your head until you feel a deep stretch.","Pull it back over your chest using your lats.","Keep your core braced and your ribs down."],"img":"opengym/4339.webp","gif":null,"ext":1},{"id":"4340","n":"barbell wide pullover","bp":"back","eq":"barbell","tg":"lats","mg":"chest","sm":["chest","triceps","core"],"st":["Lie on a bench with a barbell held wider than shoulder-width above your chest.","Keep your elbows slightly bent.","Lower the bar behind your head in a smooth arc.","Pull the bar back over your chest.","Maintain a stable core and avoid arching your back."],"img":"opengym/4340.webp","gif":null,"ext":1},{"id":"4341","n":"dumbbell alternate front raise","bp":"shoulders","eq":"dumbbell","tg":"delts","mg":"upper chest","sm":["upper chest","trapezius","core"],"st":["Stand holding a dumbbell in each hand in front of your thighs.","Keep a slight bend in your elbows and your torso still.","Raise one arm forward to shoulder height.","Lower it slowly as you raise the other arm.","Avoid swinging; keep alternating for your reps."],"img":"opengym/4341.webp","gif":null,"ext":1},{"id":"4342","n":"dumbbell twisted fly","bp":"chest","eq":"dumbbell","tg":"pectorals","mg":"shoulders","sm":["shoulders","upper chest","biceps"],"st":["Lie on a bench with a dumbbell in each hand above your chest, palms facing in.","Open your arms wide in an arc with elbows slightly bent.","Rotate your wrists as you lower until you feel a chest stretch.","Bring the dumbbells back together, twisting them to finish with palms inward.","Control the weight on the way down."],"img":"opengym/4342.webp","gif":null,"ext":1},{"id":"4343","n":"dumbbell one arm triceps extension","bp":"upper arms","eq":"dumbbell","tg":"triceps","mg":"shoulders","sm":["shoulders","core"],"st":["Hold a dumbbell in one hand and press it overhead.","Keep your upper arm close to your head with the elbow pointing up.","Bend the elbow and lower the dumbbell behind your head.","Extend the elbow to press the weight back up.","Finish your reps, then switch arms."],"img":"opengym/4343.webp","gif":null,"ext":1},{"id":"4344","n":"barbell incline triceps extension skull crusher","bp":"upper arms","eq":"barbell","tg":"triceps","mg":"shoulders","sm":["shoulders","forearms"],"st":["Lie back on an incline bench holding a barbell above your chest, arms straight.","Keep your upper arms still.","Bend your elbows and lower the bar toward your forehead.","Extend your arms to return to the start.","Keep your elbows pointing forward."],"img":"opengym/4344.webp","gif":null,"ext":1},{"id":"4345","n":"cable incline close grip curl","bp":"upper arms","eq":"cable","tg":"biceps","mg":"brachialis","sm":["brachialis","forearms"],"st":["Lean back on an incline bench in front of a low cable with a straight bar.","Grip the bar close together with palms up.","Curl the bar toward your shoulders, upper arms still.","Squeeze at the top.","Lower slowly until your arms are nearly straight."],"img":"opengym/4345.webp","gif":null,"ext":1},{"id":"4346","n":"bodyweight standing military press","bp":"shoulders","eq":"body weight","tg":"delts","mg":"triceps","sm":["triceps","upper chest","core"],"st":["Stand tall with feet shoulder-width apart and fists at your shoulders.","Brace your core and squeeze your glutes.","Press your arms straight overhead.","Lower back to your shoulders with control.","Avoid leaning back."],"img":"opengym/4346.webp","gif":null,"ext":1},{"id":"4347","n":"lever standing leg curl","bp":"upper legs","eq":"leverage machine","tg":"hamstrings","mg":"calves","sm":["calves","glutes"],"st":["Stand facing the machine and set the pad behind your working ankle.","Hold the supports for balance.","Curl your heel toward your glutes.","Squeeze your hamstring at the top.","Lower slowly, then switch legs."],"img":"opengym/4347.webp","gif":null,"ext":1},{"id":"4348","n":"abdominal 4 points","bp":"waist","eq":"body weight","tg":"abs","mg":"core","sm":["core","shoulders","hip flexors"],"st":["Start on hands and knees with wrists under shoulders and knees under hips.","Keep your back flat and neck neutral.","Draw your belly button toward your spine.","Hold for 15-30 seconds while breathing normally.","Relax and repeat."],"img":"opengym/4348.webp","gif":null,"ext":1},{"id":"4350","n":"cable lying regular grip curl","bp":"upper arms","eq":"cable","tg":"biceps","mg":"brachialis","sm":["brachialis","forearms"],"st":["Lie on your back with your feet toward a low pulley and grab the bar with an underhand grip.","Pin your upper arms to the floor beside you.","Curl the bar up toward your shoulders.","Squeeze your biceps at the top.","Lower the bar slowly until your arms are straight and repeat."],"img":"opengym/4350.webp","gif":null,"ext":1},{"id":"4351","n":"cable incline skull crusher","bp":"upper arms","eq":"cable","tg":"triceps","mg":"shoulders","sm":["shoulders","forearms"],"st":["Set an incline bench facing away from a low cable and hold the bar overhead.","Keep your upper arms still.","Bend your elbows and lower the bar toward your forehead.","Extend your arms to return.","Keep your elbows from flaring."],"img":"opengym/4351.webp","gif":null,"ext":1},{"id":"4352","n":"bench dip on floor v. 2","bp":"upper arms","eq":"body weight","tg":"triceps","mg":"shoulders","sm":["shoulders","chest"],"st":["Sit on the floor with your back to a bench and place your hands on its edge.","Lift your hips and extend your legs slightly in front.","Bend your elbows and lower your body.","Press back up until your arms are straight.","Keep your shoulders away from your ears."],"img":"opengym/4352.webp","gif":null,"ext":1},{"id":"4353","n":"cable lying triceps extension (with rope)","bp":"upper arms","eq":"cable","tg":"triceps","mg":"shoulders","sm":["shoulders","forearms"],"st":["Lie on a bench with your head toward a low pulley and hold the rope above your chest.","Keep your upper arms still.","Bend your elbows and lower the rope behind your head.","Extend your arms to return.","Spread the rope slightly at the end."],"img":"opengym/4353.webp","gif":null,"ext":1},{"id":"4354","n":"alternate oblique crunch","bp":"waist","eq":"body weight","tg":"obliques","mg":"abdominals","sm":["abdominals","hip flexors"],"st":["Lie on your back with knees bent and hands behind your head.","Lift your shoulders off the floor.","Twist and bring one elbow toward the opposite knee.","Return to center and switch sides.","Move slowly and avoid pulling on your neck."],"img":"opengym/4354.webp","gif":null,"ext":1},{"id":"4355","n":"cable triceps pushdown (v bar) v. 2","bp":"upper arms","eq":"cable","tg":"triceps","mg":"forearms","sm":["forearms","shoulders"],"st":["Stand facing a high pulley and grip the V bar with elbows at your sides.","Keep your torso upright and slightly forward.","Push the bar down until your arms are straight.","Squeeze your triceps for a moment.","Let the bar rise slowly, elbows still."],"img":"opengym/4355.webp","gif":null,"ext":1},{"id":"4356","n":"cable horizontal pallof press v. 2","bp":"waist","eq":"cable","tg":"abs","mg":"obliques","sm":["obliques","shoulders","core"],"st":["Stand sideways to a cable set at chest height, hands holding the handle at your chest.","Step away to load the cable and brace your core.","Press the handle straight out in front of you.","Hold for a second without rotating.","Bring it back to your chest, then switch sides."],"img":"opengym/4356.webp","gif":null,"ext":1},{"id":"4357","n":"band biceps curl v. 2","bp":"upper arms","eq":"band","tg":"biceps","mg":"brachialis","sm":["brachialis","forearms"],"st":["Stand on the band with feet shoulder-width apart and hold the ends, palms up.","Keep your elbows pinned to your sides.","Curl your hands toward your shoulders.","Squeeze at the top.","Lower slowly against the band."],"img":"opengym/4357.webp","gif":null,"ext":1},{"id":"4359","n":"band overhead triceps extension v. 3","bp":"upper arms","eq":"band","tg":"triceps","mg":"shoulders","sm":["shoulders","core"],"st":["Stand holding a band behind your head, one hand low and one hand high.","Keep your elbows close to your head.","Extend your top arm straight overhead.","Pause briefly.","Lower slowly, then switch sides."],"img":"opengym/4359.webp","gif":null,"ext":1},{"id":"4360","n":"bench dip with legs on bench","bp":"upper arms","eq":"body weight","tg":"triceps","mg":"shoulders","sm":["shoulders","chest"],"st":["Place your hands on one bench behind you and your heels on another in front.","Straighten your legs and lift your hips.","Bend your elbows to lower your body.","Press back up.","Keep your back close to the bench."],"img":"opengym/4360.webp","gif":null,"ext":1},{"id":"4361","n":"bodyweight shrug","bp":"back","eq":"body weight","tg":"traps","mg":"upper back","sm":["upper back","trapezius"],"st":["Stand tall with arms by your sides.","Lift your shoulders straight up toward your ears.","Hold for a second.","Lower them slowly.","Avoid rolling your shoulders."],"img":"opengym/4361.webp","gif":null,"ext":1},{"id":"4362","n":"barbell squat 2 sec hold","bp":"upper legs","eq":"barbell","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","core","adductors"],"st":["Set a barbell on your upper back and stand with feet shoulder-width apart.","Brace your core and sit down into a deep squat.","Pause for two seconds at the bottom.","Drive through your heels to stand.","Keep your chest up throughout."],"img":"opengym/4362.webp","gif":null,"ext":1},{"id":"4363","n":"counterbalanced skater squat","bp":"upper legs","eq":"body weight","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","core"],"st":["Stand on one leg and extend the other behind you.","Reach your arms forward for balance.","Bend your standing knee and lower slowly.","Touch lightly with your back knee if needed.","Drive back up and switch legs."],"img":"opengym/4363.webp","gif":null,"ext":1},{"id":"4364","n":"single leg dip on floor","bp":"upper arms","eq":"body weight","tg":"triceps","mg":"shoulders","sm":["shoulders","chest","glutes"],"st":["Sit on the floor with hands behind you and knees bent.","Lift your hips and extend one leg out.","Bend your elbows to lower.","Press back up.","Switch legs after your reps."],"img":"opengym/4364.webp","gif":null,"ext":1},{"id":"4365","n":"animal resting yoga pose","bp":"back","eq":"body weight","tg":"spine","mg":"lats","sm":["lats","shoulders","hip flexors"],"st":["Kneel on a mat and sit back toward your heels.","Fold forward and stretch your arms ahead.","Rest your forehead on the floor.","Breathe deeply and hold for 30-60 seconds.","Release slowly."],"img":"opengym/4365.webp","gif":null,"ext":1},{"id":"4366","n":"standing side crunch","bp":"waist","eq":"body weight","tg":"obliques","mg":"abdominals","sm":["abdominals"],"st":["Stand tall with your hands behind your head.","Lift one knee out to the side.","Crunch your elbow down toward it.","Return to standing.","Repeat on both sides."],"img":"opengym/4366.webp","gif":null,"ext":1},{"id":"4367","n":"cable bent over reverse grip row","bp":"back","eq":"cable","tg":"upper back","mg":"lats","sm":["lats","biceps","rhomboids","lower back"],"st":["Stand facing a low cable and hinge forward with a flat back.","Grip the bar with palms up.","Pull the bar toward your lower ribs.","Squeeze your shoulder blades together.","Lower slowly."],"img":"opengym/4367.webp","gif":null,"ext":1},{"id":"4368","n":"cable bent over row with rope attachment","bp":"back","eq":"cable","tg":"upper back","mg":"lats","sm":["lats","biceps","rhomboids","rear deltoids"],"st":["Attach a rope to a low pulley and hinge forward with a flat back.","Grip the rope with palms facing each other.","Pull the rope toward your lower chest.","Spread the rope as you squeeze your back.","Lower with control."],"img":"opengym/4368.webp","gif":null,"ext":1},{"id":"4369","n":"bodyweight standing biceps curl v. 2","bp":"upper arms","eq":"body weight","tg":"biceps","mg":"forearms","sm":["forearms","brachialis"],"st":["Stand tall with arms at your sides.","Make fists and curl your hands to your shoulders.","Tense your biceps at the top.","Lower slowly.","Keep your elbows pinned."],"img":"opengym/4369.webp","gif":null,"ext":1},{"id":"4370","n":"smith seated calf raise","bp":"lower legs","eq":"smith machine","tg":"calves","mg":"soleus","sm":["soleus","ankles"],"st":["Sit on a bench under the bar with the balls of your feet on a raised block.","Rest the bar across your thighs with a pad.","Lift your heels as high as possible.","Pause at the top.","Lower slowly for a full stretch."],"img":"opengym/4370.webp","gif":null,"ext":1},{"id":"4371","n":"lever incline one arm chest press (plate loaded)","bp":"chest","eq":"leverage machine","tg":"pectorals","mg":"upper chest","sm":["upper chest","triceps","shoulders"],"st":["Sit on the machine and grip one handle.","Set your back firmly against the pad.","Press the handle forward and up.","Squeeze your chest at the top.","Return slowly, then switch arms."],"img":"opengym/4371.webp","gif":null,"ext":1},{"id":"4372","n":"crocodile yoga pose","bp":"waist","eq":"body weight","tg":"abs","mg":"shoulders","sm":["shoulders","triceps","core"],"st":["Lie face down with palms under your shoulders.","Tuck your toes and lift your body.","Lower into a low plank with elbows tucked in.","Keep your body straight and hold for 20-30 seconds.","Lower to the floor."],"img":"opengym/4372.webp","gif":null,"ext":1},{"id":"4373","n":"hanging deadbug","bp":"waist","eq":"body weight","tg":"abs","mg":"lower abs","sm":["lower abs","hip flexors","grip muscles"],"st":["Hang from a pull-up bar with a firm grip.","Lift your knees to hip height.","Extend one leg while keeping control of your torso.","Return and switch legs.","Avoid swinging."],"img":"opengym/4373.webp","gif":null,"ext":1},{"id":"4374","n":"cable standing alternate low fly","bp":"chest","eq":"cable","tg":"pectorals","mg":"upper chest","sm":["upper chest","shoulders"],"st":["Stand between two low pulleys holding the handles.","Take a small step forward with a slight lean.","Sweep one arm up and across toward the center of your chest.","Return slowly.","Alternate sides."],"img":"opengym/4374.webp","gif":null,"ext":1},{"id":"4375","n":"medicine ball around head rotation","bp":"shoulders","eq":"medicine ball","tg":"delts","mg":"upper back","sm":["upper back","core","obliques"],"st":["Stand tall with feet hip-width apart, holding a medicine ball at chest height.","Brace your core and keep your hips still.","Pass the ball around your head in a smooth circle, keeping it close.","Complete several circles, then reverse the direction.","Keep your ribs down and avoid leaning back as the ball passes behind you."],"img":"opengym/4375.webp","gif":null,"ext":1},{"id":"4376","n":"handstand walk","bp":"shoulders","eq":"body weight","tg":"delts","mg":"triceps","sm":["triceps","core","upper back","wrist extensors","forearms"],"st":["Kick up into a handstand against a wall or with a spotter, hands shoulder-width apart.","Squeeze your glutes and legs together and push tall through your shoulders.","Shift your weight onto one hand and move the other forward a small step.","Alternate hands in short, controlled steps, keeping your core tight.","Come down safely with control, and practise on soft ground."],"img":"opengym/4376.webp","gif":null,"ext":1},{"id":"4377","n":"dumbbell hang clean and jerk","bp":"full body","eq":"dumbbell","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","shoulders","triceps","upper back"],"st":["Stand with feet hip-width apart, holding a dumbbell hanging in front of your thighs.","Hinge at the hips, then drive them forward and shrug as you pull the dumbbell up.","Drop under it and catch it at your shoulder with a slight knee bend.","Dip a little, then drive up through your legs and press the dumbbell overhead.","Lower it back to your shoulder, then to the hang under control."],"img":"opengym/4377.webp","gif":null,"ext":1},{"id":"4378","n":"lever reverse grip high row (plate loaded)","bp":"back","eq":"leverage machine","tg":"lats","mg":"biceps","sm":["biceps","rhomboids","upper back","rear deltoids"],"st":["Sit at the machine with your chest against the pad and grab the handles underhand.","Set your shoulders back and down.","Pull the handles toward your lower ribs, driving your elbows back.","Squeeze your back at the end of the pull.","Slowly extend your arms without letting your shoulders round forward."],"img":"opengym/4378.webp","gif":null,"ext":1},{"id":"4379","n":"resistance band inverted row","bp":"back","eq":"resistance band","tg":"upper back","mg":"lats","sm":["lats","biceps","rhomboids","rear deltoids","core"],"st":["Anchor the band to a sturdy bar or rack and hold it while lying under the anchor point.","Keep your body in a straight line with heels on the floor.","Pull your chest up toward your hands, squeezing your shoulder blades together.","Pause briefly at the top.","Lower yourself under control until your arms are straight."],"img":"opengym/4379.webp","gif":null,"ext":1},{"id":"4380","n":"standing leg slide with towel","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","adductors","core","hip flexors"],"st":["Stand on a smooth floor with one foot on a towel and hold a support if needed.","Bend the standing knee slightly and keep your chest tall.","Slide the towel foot out to the side or back as far as you can control.","Pull it back to the start using your hip and thigh muscles.","Complete your reps, then switch legs."],"img":"opengym/4380.webp","gif":null,"ext":1},{"id":"4381","n":"legs up the wall yoga pose","bp":"upper legs","eq":"body weight","tg":"hamstrings","mg":"lower back","sm":["lower back","calves","glutes"],"st":["Sit sideways next to a wall and lie back as you swing your legs up the wall.","Move your hips close to the wall, with your arms relaxed at your sides.","Keep your knees soft if the hamstrings feel tight.","Breathe slowly and relax your shoulders and jaw.","Hold for 1-5 minutes, then bend your knees and roll to one side to come up."],"img":"opengym/4381.webp","gif":null,"ext":1},{"id":"4382","n":"barbell front rack lunge v. 2","bp":"upper legs","eq":"barbell","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","core","adductors"],"st":["Rest the barbell on the front of your shoulders with elbows high.","Stand tall with feet hip-width apart.","Step forward into a long stride and lower until both knees reach about 90 degrees.","Push through the front foot to return to standing.","Alternate legs, keeping your torso upright."],"img":"opengym/4382.webp","gif":null,"ext":1},{"id":"4383","n":"medicine ball step behind rotational throw","bp":"full body","eq":"medicine ball","tg":"obliques","mg":"abdominals","sm":["abdominals","glutes","shoulders","quadriceps"],"st":["Stand sideways to a wall, holding a medicine ball at hip height.","Step your rear foot behind you and load your weight onto it.","Rotate your hips and torso toward the wall.","Throw the ball hard into the wall at chest height.","Catch it, reset, and switch sides after your set."],"img":"opengym/4383.webp","gif":null,"ext":1},{"id":"4384","n":"body saw plank","bp":"waist","eq":"body weight","tg":"abs","mg":"core","sm":["core","shoulders","lower abs","glutes"],"st":["Get into a forearm plank with elbows under your shoulders.","Squeeze your glutes and brace your abs.","Shift your body forward so your shoulders move past your elbows.","Rock back to the start in a slow, smooth motion.","Keep your hips level and avoid sagging."],"img":"opengym/4384.webp","gif":null,"ext":1},{"id":"4385","n":"hip roll plank","bp":"waist","eq":"body weight","tg":"abs","mg":"obliques","sm":["obliques","core","shoulders","glutes"],"st":["Start in a forearm plank with feet slightly wider than hip-width.","Brace your abs and keep your shoulders stable.","Rotate your hips to one side, lowering them toward the floor.","Roll back through the middle to the other side.","Keep the movement controlled and breathe steadily."],"img":"opengym/4385.webp","gif":null,"ext":1},{"id":"4386","n":"leg extension plank","bp":"waist","eq":"body weight","tg":"abs","mg":"core","sm":["core","glutes","shoulders","hip flexors"],"st":["Get into a forearm or high plank with a flat back.","Brace your abs and squeeze your glutes.","Lift one leg straight behind you without rotating your hips.","Lower it with control.","Repeat on the other leg and alternate."],"img":"opengym/4386.webp","gif":null,"ext":1},{"id":"4387","n":"prayer squat yoga pose","bp":"upper legs","eq":"body weight","tg":"adductors","mg":"glutes","sm":["glutes","quadriceps","hip flexors","groin"],"st":["Stand with feet wider than hips and toes turned out.","Lower into a deep squat, keeping your heels down if you can.","Press your palms together at your chest.","Use your elbows to gently press your knees outward.","Hold for 30-60 seconds while breathing slowly."],"img":"opengym/4387.webp","gif":null,"ext":1},{"id":"4388","n":"prisoner get up","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","core"],"st":["Kneel on the floor, with your hands behind your head.","Keep your chest tall and your core braced.","Step one foot forward and drive up through it to stand.","Lower back down with control to kneeling.","Alternate the leading leg on each rep."],"img":"opengym/4388.webp","gif":null,"ext":1},{"id":"4389","n":"dumbbell push jerk","bp":"shoulders","eq":"dumbbell","tg":"delts","mg":"triceps","sm":["triceps","quadriceps","glutes","core","upper chest"],"st":["Hold dumbbells at shoulder height, feet hip-width apart.","Dip by bending your knees slightly while keeping your torso upright.","Drive up through your legs explosively.","Press the dumbbells overhead as you straighten, then lock out your arms.","Lower them back to your shoulders with control."],"img":"opengym/4389.webp","gif":null,"ext":1},{"id":"4390","n":"barbell front rack rear lunge","bp":"upper legs","eq":"barbell","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","core","adductors"],"st":["Rest the barbell across your front shoulders with elbows high.","Stand tall with your feet hip-width apart.","Step one leg back and lower until both knees are around 90 degrees.","Push through the front foot to return to standing.","Alternate legs and keep your torso upright."],"img":"opengym/4390.webp","gif":null,"ext":1},{"id":"4391","n":"cable low row with rope attachment","bp":"back","eq":"cable","tg":"upper back","mg":"lats","sm":["lats","rhomboids","biceps","rear deltoids","lower back"],"st":["Sit at the low pulley with the rope attached, feet on the platform and knees slightly bent.","Grab the rope ends with a neutral grip and sit tall.","Pull the rope toward your lower stomach, driving your elbows back.","Squeeze your shoulder blades together.","Return slowly until your arms are straight without rounding your back."],"img":"opengym/4391.webp","gif":null,"ext":1},{"id":"4392","n":"rowing boat yoga pose","bp":"waist","eq":"body weight","tg":"abs","mg":"hip flexors","sm":["hip flexors","quadriceps","core","lower back"],"st":["Sit with your knees bent and your feet on the floor.","Lean back slightly, keeping your chest lifted and back long.","Lift your feet and extend your legs into a V shape.","Reach your arms forward alongside your legs.","Hold for 20-30 seconds while breathing steadily."],"img":"opengym/4392.webp","gif":null,"ext":1},{"id":"4393","n":"kettlebell russian twist","bp":"waist","eq":"kettlebell","tg":"obliques","mg":"core","sm":["core","hip flexors","lower back"],"st":["Sit on the floor with knees bent and lean back a little.","Hold a kettlebell by the horns at your chest.","Lift your feet slightly if you can, and keep your back straight.","Rotate your torso to one side, then the other.","Move with control and keep your chest lifted."],"img":"opengym/4393.webp","gif":null,"ext":1},{"id":"4394","n":"alternate shoulder flexion back to wall","bp":"shoulders","eq":"body weight","tg":"delts","mg":"upper chest","sm":["upper chest","upper back","core"],"st":["Stand with your back, head and hips against a wall.","Keep your ribs down and your lower back near the wall.","Raise one arm forward and overhead as far as you can without arching.","Lower it with control.","Alternate arms for the set."],"img":"opengym/4394.webp","gif":null,"ext":1},{"id":"4395","n":"shoulder circle","bp":"back","eq":"body weight","tg":"upper back","mg":"trapezius","sm":["trapezius","shoulders","rotator cuff"],"st":["Stand tall with your arms relaxed by your sides.","Lift your shoulders up toward your ears.","Roll them back and down in a smooth circle.","Complete several slow circles.","Reverse the direction and repeat."],"img":"opengym/4395.webp","gif":null,"ext":1},{"id":"4396","n":"kettlebell side bend v. 2","bp":"waist","eq":"kettlebell","tg":"obliques","mg":"lower back","sm":["lower back","core"],"st":["Stand tall, holding a kettlebell in one hand at your side.","Keep your feet hip-width apart and your core braced.","Bend sideways toward the weighted side without twisting.","Use your obliques to return to upright.","Finish your reps, then switch hands."],"img":"opengym/4396.webp","gif":null,"ext":1},{"id":"4397","n":"barbell front rack split squat","bp":"upper legs","eq":"barbell","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","core","adductors"],"st":["Rest the barbell on your front shoulders with elbows high.","Take a split stance with one foot well in front of the other.","Lower your back knee toward the floor while keeping your torso upright.","Press through the front foot to rise.","Finish your reps, then switch legs."],"img":"opengym/4397.webp","gif":null,"ext":1},{"id":"4399","n":"standing seal yoga pose","bp":"back","eq":"body weight","tg":"spine","mg":"core","sm":["core","hip flexors","shoulders"],"st":["Stand with feet hip-width apart and your hands on your lower back.","Lengthen through your spine.","Lift your chest and gently arch backward.","Keep your neck relaxed and your legs strong.","Hold for 15-30 seconds, then come back up slowly."],"img":"opengym/4399.webp","gif":null,"ext":1},{"id":"4400","n":"kettlebell step up","bp":"upper legs","eq":"kettlebell","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","calves","core"],"st":["Stand facing a sturdy box or bench holding a kettlebell at your chest or by your side.","Place one foot fully on the box.","Press through that heel to stand tall on top.","Lower back down slowly with control.","Finish your reps, then switch legs."],"img":"opengym/4400.webp","gif":null,"ext":1},{"id":"4401","n":"barbell knee raise step up","bp":"upper legs","eq":"barbell","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","hip flexors","core"],"st":["Rest a barbell on your upper back and stand facing a box.","Place one foot on the box and press up through that heel.","Drive the other knee up toward your hip at the top.","Lower the knee and step back down under control.","Complete your reps, then switch legs."],"img":"opengym/4401.webp","gif":null,"ext":1},{"id":"4402","n":"straight angle yoga pose","bp":"upper legs","eq":"body weight","tg":"hamstrings","mg":"adductors","sm":["adductors","inner thighs","groin","lower back"],"st":["Stand with your feet wide apart and toes pointing forward.","Place your hands on your hips and lengthen your spine.","Hinge forward at the hips with a flat back.","Lower your hands to the floor or to your shins.","Hold for 20-30 seconds, then rise slowly."],"img":"opengym/4402.webp","gif":null,"ext":1},{"id":"4403","n":"kettlebells sumo deadlift","bp":"upper legs","eq":"kettlebell","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","adductors","lower back","grip muscles"],"st":["Stand with feet wide and toes turned out, kettlebells on the floor between your feet.","Hinge down and grip the handles with a flat back.","Push through your feet and stand up, squeezing your glutes.","Keep the kettlebells close to your body.","Lower back down by hinging at the hips."],"img":"opengym/4403.webp","gif":null,"ext":1},{"id":"4404","n":"swaying palm tree yoga pose","bp":"waist","eq":"body weight","tg":"abs","mg":"lats","sm":["lats","shoulders","core"],"st":["Stand tall with feet together and arms overhead, palms joined.","Reach up through your fingertips.","Lean gently to one side without twisting.","Breathe and hold for 15-20 seconds.","Return to center and repeat on the other side."],"img":"opengym/4404.webp","gif":null,"ext":1},{"id":"4405","n":"the eagle yoga pose","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"quadriceps","sm":["quadriceps","shoulders","upper back","hip flexors"],"st":["Stand tall and bend both knees slightly.","Lift one leg and wrap it across the other thigh.","Cross your arms in front, one elbow over the other, palms together.","Lift your elbows and sink your hips slightly.","Hold for 20-30 seconds, then switch sides."],"img":"opengym/4405.webp","gif":null,"ext":1},{"id":"4406","n":"tiger yoga pose","bp":"back","eq":"body weight","tg":"spine","mg":"core","sm":["core","glutes","shoulders","hip flexors"],"st":["Start on all fours with hands under shoulders and knees under hips.","Round your back and draw one knee toward your nose.","Then extend that leg back and up while lifting your chest.","Move smoothly with your breath.","Do your reps, then switch legs."],"img":"opengym/4406.webp","gif":null,"ext":1},{"id":"4407","n":"tiger tail tricep","bp":"upper arms","eq":"body weight","tg":"triceps","mg":"forearms","sm":["forearms","core","shoulders"],"st":["Set up facing your anchor or support, with your upper arms close to your body.","Brace your core and keep your elbows still.","Straighten your arms fully to engage the triceps.","Squeeze at the bottom for a moment.","Return slowly to the start."],"img":"opengym/4407.webp","gif":null,"ext":1},{"id":"4408","n":"kettlebell upright row","bp":"shoulders","eq":"kettlebell","tg":"delts","mg":"trapezius","sm":["trapezius","biceps","upper back","forearms"],"st":["Stand tall holding a kettlebell with both hands in front of your thighs.","Keep it close to your body.","Pull it up toward your chest, leading with your elbows.","Stop at about chest height.","Lower slowly under control."],"img":"opengym/4408.webp","gif":null,"ext":1},{"id":"4409","n":"barbell front rack walking lunge","bp":"upper legs","eq":"barbell","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","core","adductors"],"st":["Rest the barbell across your front shoulders with elbows high.","Step forward into a long stride.","Lower until both knees reach about 90 degrees.","Push through the front foot and bring the back leg through into the next step.","Keep walking, alternating legs, with an upright torso."],"img":"opengym/4409.webp","gif":null,"ext":1},{"id":"4410","n":"warrior ii yoga pose","bp":"upper legs","eq":"body weight","tg":"quads","mg":"glutes","sm":["glutes","adductors","shoulders","core"],"st":["Stand with your feet wide apart and turn your front foot out.","Bend the front knee over the ankle.","Extend your arms out to the sides at shoulder height.","Gaze over your front fingertips and keep your torso upright.","Hold for 20-30 seconds, then switch sides."],"img":"opengym/4410.webp","gif":null,"ext":1},{"id":"4411","n":"barbell seated high front raise","bp":"shoulders","eq":"barbell","tg":"delts","mg":"upper chest","sm":["upper chest","trapezius","triceps"],"st":["Sit on a bench holding a barbell with an overhand grip, in front of your thighs.","Keep your back straight and your core braced.","Lift the bar forward and up to eye level or higher.","Pause briefly.","Lower slowly under control."],"img":"opengym/4411.webp","gif":null,"ext":1},{"id":"4412","n":"resistance band pullapart (pronated at 90 degrees)","bp":"shoulders","eq":"resistance band","tg":"delts","mg":"rear deltoids","sm":["rear deltoids","rhomboids","upper back","trapezius"],"st":["Stand holding a band in front of you at shoulder height with an overhand grip.","Keep your arms straight and your core braced.","Pull your hands apart until the band touches your chest.","Squeeze your shoulder blades together.","Return slowly to the start."],"img":"opengym/4412.webp","gif":null,"ext":1},{"id":"4414","n":"barbell bench press with band suspended kettlebell","bp":"chest","eq":"barbell","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders","upper chest","core"],"st":["Lie on a bench and unrack the barbell with kettlebells hung from bands.","Plant your feet and brace your core.","Lower the bar slowly to your mid chest.","Press it up to full extension while keeping the bar steady.","Rack the bar safely when finished."],"img":"opengym/4414.webp","gif":null,"ext":1},{"id":"4415","n":"band resisted chin up","bp":"back","eq":"band","tg":"lats","mg":"biceps","sm":["biceps","upper back","rhomboids","forearms"],"st":["Attach a band to the bar and loop it around your body or waist.","Hang from the bar with an underhand grip.","Pull yourself up until your chin clears the bar.","Squeeze your back at the top.","Lower with control to a full hang."],"img":"opengym/4415.webp","gif":null,"ext":1},{"id":"4416","n":"sliding leg bird dog","bp":"waist","eq":"body weight","tg":"abs","mg":"glutes","sm":["glutes","lower back","core","shoulders"],"st":["Start on all fours with a sliding disc or towel under one foot.","Brace your core and keep your hips level.","Slide that leg straight back as you extend the opposite arm forward.","Return to the start in a controlled way.","Complete your reps, then switch sides."],"img":"opengym/4416.webp","gif":null,"ext":1},{"id":"4417","n":"sumo squat floor touch","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"quadriceps","sm":["quadriceps","adductors","hamstrings","core"],"st":["Stand with your feet wide and toes turned out.","Push your hips back and squat down.","Touch the floor with your fingertips between your feet.","Keep your chest lifted and your knees tracking over your toes.","Drive through your heels to stand."],"img":"opengym/4417.webp","gif":null,"ext":1},{"id":"4419","n":"lying leg raise (modified)","bp":"waist","eq":"body weight","tg":"abs","mg":"lower abs","sm":["lower abs","hip flexors","core"],"st":["Lie on your back with your hands by your sides.","Bend your knees slightly and press your lower back into the floor.","Raise your legs until your hips flex to about 90 degrees.","Lower them slowly without arching your back.","Stop short of the floor and repeat."],"img":"opengym/4419.webp","gif":null,"ext":1},{"id":"4420","n":"marching on spot","bp":"cardio","eq":"body weight","tg":"cardiovascular system","mg":"hip flexors","sm":["hip flexors","quadriceps","calves","core"],"st":["Stand tall with your arms bent at your sides.","Lift one knee up toward hip height.","Lower it and lift the other knee.","Swing your arms in rhythm with your steps.","Keep a steady pace for 1-3 minutes."],"img":"opengym/4420.webp","gif":null,"ext":1},{"id":"4421","n":"cable donkey kickback","bp":"upper legs","eq":"cable","tg":"glutes","mg":"hamstrings","sm":["hamstrings","core","lower back"],"st":["Attach an ankle strap to a low cable and get on all fours facing the machine.","Hook the strap around one ankle.","Keeping the knee bent, drive your heel up toward the ceiling.","Squeeze your glute at the top without arching your back.","Return slowly and repeat, then switch legs."],"img":"opengym/4421.webp","gif":null,"ext":1},{"id":"4422","n":"ez bar drag bicep curl","bp":"upper arms","eq":"ez barbell","tg":"biceps","mg":"brachialis","sm":["brachialis","forearms","shoulders"],"st":["Stand holding an ez bar with an underhand grip at your thighs.","Keep the bar close to your body.","Curl it up while moving your elbows back behind you.","Let the bar slide up your torso to chest height.","Lower slowly under control."],"img":"opengym/4422.webp","gif":null,"ext":1},{"id":"4423","n":"barbell lying close grip underhand row on rack","bp":"back","eq":"barbell","tg":"upper back","mg":"lats","sm":["lats","biceps","rhomboids","core"],"st":["Set a barbell in a rack at about waist height.","Lie underneath and grab it with a close underhand grip.","Keep your body straight and heels on the floor.","Pull your chest to the bar.","Lower yourself under control."],"img":"opengym/4423.webp","gif":null,"ext":1},{"id":"4424","n":"barbell lying close grip overhand row on rack","bp":"back","eq":"barbell","tg":"upper back","mg":"lats","sm":["lats","biceps","rhomboids","rear deltoids","core"],"st":["Set a barbell in a rack at about waist height.","Lie beneath it and grip the bar overhand with hands close together.","Keep your body straight from head to heels.","Pull your chest to the bar and squeeze your shoulder blades.","Lower with control."],"img":"opengym/4424.webp","gif":null,"ext":1},{"id":"4425","n":"dumbbell lying close grip parallel row on rack","bp":"back","eq":"dumbbell","tg":"upper back","mg":"lats","sm":["lats","biceps","rhomboids","core"],"st":["Lie face down on a high bench or rack with a dumbbell in each hand.","Let your arms hang with palms facing each other.","Row the dumbbells toward your ribs, keeping elbows close.","Squeeze your shoulder blades at the top.","Lower slowly to full extension."],"img":"opengym/4425.webp","gif":null,"ext":1},{"id":"4426","n":"dumbbell lying wide grip row on rack","bp":"back","eq":"dumbbell","tg":"upper back","mg":"rear deltoids","sm":["rear deltoids","rhomboids","lats","biceps"],"st":["Lie face down on a high bench with a dumbbell in each hand.","Let your arms hang straight down.","Row the dumbbells up with elbows flaring out to the sides.","Squeeze your shoulder blades together.","Lower under control."],"img":"opengym/4426.webp","gif":null,"ext":1},{"id":"4428","n":"power sled push","bp":"full body","eq":"sled machine","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","calves","core","shoulders"],"st":["Load the sled and grip the handles at chest or hip height.","Lean forward with a straight body line.","Drive through your legs with powerful steps.","Keep your core tight and push the sled forward.","Maintain a steady pace for the set distance."],"img":"opengym/4428.webp","gif":null,"ext":1},{"id":"4429","n":"weighted lying side neck raise","bp":"neck","eq":"weighted","tg":"levator scapulae","mg":"sternocleidomastoid","sm":["sternocleidomastoid","trapezius"],"st":["Lie on your side with your head supported at the edge of the bench.","Place a light weight or plate on the side of your head, held steady.","Lift your head slowly toward the ceiling.","Pause, then lower under control.","Complete your reps, then switch sides. Use light weight."],"img":"opengym/4429.webp","gif":null,"ext":1},{"id":"4430","n":"weighted side lying side neck raise","bp":"neck","eq":"weighted","tg":"levator scapulae","mg":"sternocleidomastoid","sm":["sternocleidomastoid","trapezius"],"st":["Lie on your side with your head supported at the edge of the bench.","Place a light weight or plate on the side of your head, held steady.","Lift your head slowly toward the ceiling.","Pause, then lower under control.","Complete your reps, then switch sides. Use light weight."],"img":"opengym/4430.webp","gif":null,"ext":1},{"id":"4431","n":"weighted lying neck side to side","bp":"neck","eq":"weighted","tg":"levator scapulae","mg":"sternocleidomastoid","sm":["sternocleidomastoid","trapezius"],"st":["Lie face up with a light weight on your forehead.","Keep your shoulders relaxed.","Slowly turn your head toward one side.","Return to the middle and turn the other way.","Use light weight and smooth movement."],"img":"opengym/4431.webp","gif":null,"ext":1},{"id":"4432","n":"weighted lying neck head twist","bp":"neck","eq":"weighted","tg":"levator scapulae","mg":"sternocleidomastoid","sm":["sternocleidomastoid","trapezius"],"st":["Lie face up with a light weight resting on your forehead.","Keep your chin slightly tucked.","Rotate your head slowly to one side.","Return to the middle and rotate to the other side.","Keep the movement small and controlled."],"img":"opengym/4432.webp","gif":null,"ext":1},{"id":"4435","n":"high knee squat v. 2","bp":"upper legs","eq":"body weight","tg":"quads","mg":"glutes","sm":["glutes","hip flexors","calves","core"],"st":["Stand with your feet shoulder-width apart.","Squat down with your chest lifted.","Stand up explosively and drive one knee up toward your chest.","Land softly and drop into the next squat.","Alternate knees on each rep."],"img":"opengym/4435.webp","gif":null,"ext":1},{"id":"4436","n":"alternating step out","bp":"full body","eq":"body weight","tg":"cardiovascular system","mg":"quadriceps","sm":["quadriceps","glutes","calves","core"],"st":["Stand with feet together and hands in front of your chest.","Step one foot out to the side.","Bring it back and step the other foot out.","Keep your knees slightly bent.","Keep a steady rhythm for 30-60 seconds."],"img":"opengym/4436.webp","gif":null,"ext":1},{"id":"4437","n":"alternating hamstring curl with punches","bp":"full body","eq":"body weight","tg":"hamstrings","mg":"glutes","sm":["glutes","calves","shoulders","core","triceps"],"st":["Stand tall with your fists in front of your chin.","Curl one heel up toward your glute.","Punch forward as you curl the leg.","Lower the leg and repeat on the other side.","Keep a steady rhythm and stay light on your feet."],"img":"opengym/4437.webp","gif":null,"ext":1},{"id":"4438","n":"jack step","bp":"full body","eq":"body weight","tg":"cardiovascular system","mg":"quadriceps","sm":["quadriceps","glutes","calves","shoulders"],"st":["Stand with feet together and arms at your sides.","Step one foot out to the side while raising your arms overhead.","Step it back as you lower your arms.","Repeat on the other side.","Keep a steady pace for 30-60 seconds."],"img":"opengym/4438.webp","gif":null,"ext":1},{"id":"4439","n":"dumbbell power clean and jerk","bp":"full body","eq":"dumbbell","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","shoulders","triceps","upper back"],"st":["Stand over dumbbells with feet hip-width apart.","Hinge down and grip them with a flat back.","Pull explosively, extend your hips and shrug.","Catch the dumbbells at your shoulders, then dip and drive them overhead.","Lower to your shoulders, then the floor with control."],"img":"opengym/4439.webp","gif":null,"ext":1},{"id":"4440","n":"kettlebell step up v. 2","bp":"upper legs","eq":"kettlebell","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","calves","core"],"st":["Stand facing a bench or box holding a kettlebell.","Place one foot flat on the box.","Press through that heel to stand up.","Lower back down slowly.","Finish your reps, then switch legs."],"img":"opengym/4440.webp","gif":null,"ext":1},{"id":"4441","n":"kettlebell front rack walking lunge","bp":"upper legs","eq":"kettlebell","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","core","shoulders"],"st":["Clean two kettlebells to the front rack, elbows tucked and close to your ribs.","Stand tall with your feet hip width apart.","Step forward and lower until both knees are around 90 degrees.","Push through the front foot and bring the back leg forward into the next step.","Keep your torso upright and the bells steady against your chest.","Continue alternating legs for the planned distance."],"img":"opengym/4441.webp","gif":null,"ext":1},{"id":"4442","n":"assisted bulgarian split squat","bp":"upper legs","eq":"body weight","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","adductors","core"],"st":["Stand facing away from a bench and hold a sturdy post or rack with one hand for balance.","Place the top of your rear foot on a bench behind you.","Step your front foot far enough forward to stay balanced.","Lower straight down until your front thigh is about parallel to the floor.","Keep your torso upright and your front knee tracking over your toes.","Drive through the front heel to stand, then switch legs after your set."],"img":"opengym/4442.webp","gif":null,"ext":1},{"id":"4443","n":"dumbbell assisted bulgarian split squat","bp":"upper legs","eq":"dumbbell","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","adductors","core"],"st":["Hold a dumbbell in one hand and rest the other hand on a sturdy support, standing away from a bench.","Place the top of your rear foot on a bench behind you.","Step your front foot far enough forward to stay balanced.","Lower straight down until your front thigh is about parallel to the floor.","Keep your torso upright and your front knee tracking over your toes.","Drive through the front heel to stand, then switch legs after your set."],"img":"opengym/4443.webp","gif":null,"ext":1},{"id":"4444","n":"kettlebell assisted bulgarian split squat","bp":"upper legs","eq":"kettlebell","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","adductors","core"],"st":["Hold a kettlebell at your chest in one hand and rest the other hand on a sturdy support, standing away from a bench.","Place the top of your rear foot on a bench behind you.","Step your front foot far enough forward to stay balanced.","Lower straight down until your front thigh is about parallel to the floor.","Keep your torso upright and your front knee tracking over your toes.","Drive through the front heel to stand, then switch legs after your set."],"img":"opengym/4444.webp","gif":null,"ext":1},{"id":"4445","n":"resistance band seated face pull","bp":"shoulders","eq":"resistance band","tg":"delts","mg":"rear deltoids","sm":["rear deltoids","rhomboids","rotator cuff","trapezius"],"st":["Anchor a band at chest height and sit facing it, holding the ends with both hands.","Sit tall with arms extended and the band under light tension.","Pull the band toward your face, flaring your elbows out and high.","Squeeze your shoulder blades together at the end.","Pause briefly, then return slowly with control.","Keep your ribs down and avoid leaning back."],"img":"opengym/4445.webp","gif":null,"ext":1},{"id":"4446","n":"kettlebell half kneeling one arm bottoms up press","bp":"shoulders","eq":"kettlebell","tg":"delts","mg":"triceps","sm":["triceps","core","forearms","grip muscles","rotator cuff"],"st":["Kneel on one knee with the opposite foot flat in front, back upright.","Hold a kettlebell by the handle with the bell pointing up, at shoulder height.","Squeeze the handle tight and brace your core.","Press straight overhead while keeping the bell balanced.","Lower under control back to the shoulder.","Finish your reps, then switch sides."],"img":"opengym/4446.webp","gif":null,"ext":1},{"id":"4447","n":"resistance band elevated glute bridge","bp":"upper legs","eq":"band","tg":"glutes","mg":"hamstrings","sm":["hamstrings","core","lower back","adductors"],"st":["Lie on your back with your feet on a bench and a band around your thighs just above the knees.","Bend your knees and place your arms by your sides.","Push your knees out against the band and drive through your heels.","Lift your hips until your body forms a straight line from shoulders to knees.","Squeeze your glutes at the top for a moment.","Lower your hips slowly and repeat."],"img":"opengym/4447.webp","gif":null,"ext":1},{"id":"4449","n":"dumbbell hang clean","bp":"full body","eq":"dumbbell","tg":"glutes","mg":"hamstrings","sm":["hamstrings","trapezius","quadriceps","shoulders","core"],"st":["Stand holding dumbbells at your thighs, then push your hips back to lower them to the knees.","Keep your back flat and arms straight.","Drive your hips forward powerfully and shrug.","Pull the dumbbells up close to your body and rotate your elbows under them.","Catch them on your shoulders in a slight quarter squat.","Stand tall, then lower them back to your thighs and reset."],"img":"opengym/4449.webp","gif":null,"ext":1},{"id":"4450","n":"suspender wide grip inverted row","bp":"back","eq":"suspension trainer","tg":"upper back","mg":"lats","sm":["lats","biceps","rhomboids","rear deltoids","core","forearms"],"st":["Hold the handles of a suspension trainer with a wide overhand grip and lean back, arms straight.","Walk your feet forward to set the difficulty.","Keep your body in a straight line from head to heels.","Pull your chest toward the handles, squeezing your shoulder blades.","Pause briefly at the top.","Lower yourself with control until your arms are straight."],"img":"opengym/4450.webp","gif":null,"ext":1},{"id":"4451","n":"suspension wide grip inverted row on floor","bp":"back","eq":"suspension trainer","tg":"upper back","mg":"lats","sm":["lats","rhomboids","biceps","core","rear deltoids"],"st":["Hold the handles with a wide, overhand grip and lie back with your body straight.","Keep your heels on the floor and your core tight.","Pull your chest toward the handles, squeezing your shoulder blades.","Pause briefly at the top.","Lower yourself slowly until your arms are straight and repeat."],"img":"opengym/4451.webp","gif":null,"ext":1},{"id":"4452","n":"band bent over wide grip row","bp":"back","eq":"band","tg":"upper back","mg":"lats","sm":["lats","rhomboids","rear deltoids","biceps","lower back"],"st":["Stand on the band with feet hip width apart and grab it with a wide overhand grip.","Hinge at the hips with a flat back and soft knees.","Pull your hands toward your lower ribs, elbows flaring out.","Squeeze your shoulder blades together at the top.","Lower slowly until your arms are straight.","Keep your torso still throughout."],"img":"opengym/4452.webp","gif":null,"ext":1},{"id":"4453","n":"band one arm standing wide grip low row","bp":"back","eq":"band","tg":"upper back","mg":"lats","sm":["lats","rhomboids","biceps","rear deltoids","core"],"st":["Anchor a band low and stand facing it, holding the end in one hand.","Step back until the band is taut, feet hip width apart.","Pull your elbow back and out, leading with the elbow.","Squeeze your shoulder blade toward your spine.","Return slowly to a straight arm.","Finish your reps, then switch arms."],"img":"opengym/4453.webp","gif":null,"ext":1},{"id":"4454","n":"band seated wide grip row","bp":"back","eq":"band","tg":"upper back","mg":"lats","sm":["lats","rhomboids","biceps","rear deltoids"],"st":["Sit with your legs extended and loop the band around your feet.","Grab the band with a wide grip and sit tall.","Pull your hands toward your chest with elbows flared.","Squeeze your shoulder blades together.","Return slowly with control and repeat."],"img":"opengym/4454.webp","gif":null,"ext":1},{"id":"4455","n":"45 degrees back extension","bp":"back","eq":"body weight","tg":"spine","mg":"glutes","sm":["glutes","hamstrings","lower back","core"],"st":["Set the pad at hip level and hook your heels under the rollers.","Cross your arms over your chest or hold them behind your head.","Lower your torso with a straight spine until you feel a hamstring stretch.","Raise your torso by squeezing your glutes and lower back.","Stop when your body forms a straight line.","Avoid over-arching at the top."],"img":"opengym/4455.webp","gif":null,"ext":1},{"id":"4456","n":"glute ham raise v. 2","bp":"upper legs","eq":"body weight","tg":"hamstrings","mg":"glutes","sm":["glutes","lower back","calves","core"],"st":["Set your feet on the platform with your thighs against the pad and knees just behind it.","Start with your torso hanging down and your body straight.","Curl your body up by bending your knees and squeezing your hamstrings.","Finish with hips extended and torso upright.","Lower slowly with control, keeping your hips locked.","Repeat for reps."],"img":"opengym/4456.webp","gif":null,"ext":1},{"id":"4457","n":"dumbbell side bridge with bent leg","bp":"waist","eq":"dumbbell","tg":"obliques","mg":"glutes","sm":["glutes","shoulders","core"],"st":["Lie on your side with your knees bent and your forearm under your shoulder.","Hold a dumbbell in your top hand, resting on your hip.","Lift your hips so your body forms a line from head to knees.","Hold the position while breathing steadily.","Keep your hips stacked and do not sink.","Lower and switch sides after your set."],"img":"opengym/4457.webp","gif":null,"ext":1},{"id":"4458","n":"side bridge with straight legs","bp":"waist","eq":"body weight","tg":"obliques","mg":"glutes","sm":["glutes","shoulders","core"],"st":["Lie on your side with your elbow under your shoulder and legs stacked.","Lift your hips so your body forms a straight line.","Keep your core tight and your neck neutral.","Hold for 20-40 seconds without letting your hips sag.","Lower down and repeat on the other side."],"img":"opengym/4458.webp","gif":null,"ext":1},{"id":"4459","n":"lying ab press","bp":"waist","eq":"body weight","tg":"abs","mg":"lower abs","sm":["lower abs","hip flexors","obliques"],"st":["Lie on your back with arms and legs extended.","Brace your abs and press your lower back to the floor.","Lift your shoulders and bring your knees toward your chest.","Reach your hands to your knees and squeeze.","Return slowly without letting your feet touch down.","Repeat for reps."],"img":"opengym/4459.webp","gif":null,"ext":1},{"id":"4462","n":"roll ball foot","bp":"lower legs","eq":"massage ball","tg":"calves","mg":"feet","sm":["feet","soleus","ankles"],"st":["Place the ball under your foot sole while seated or standing.","Shift your weight onto the ball until you feel moderate, tolerable pressure.","Roll slowly back and forth over a short range, about 2-3 cm at a time.","When you find a tender spot, pause on it and breathe for 20-30 seconds.","Keep your breathing steady and avoid rolling over bone or joints.","Repeat on the other side if needed."],"img":"opengym/4462.webp","gif":null,"ext":1},{"id":"4463","n":"roll ball peroneus","bp":"lower legs","eq":"massage ball","tg":"calves","mg":"shins","sm":["shins","ankles"],"st":["Place the ball under your outer lower leg (peroneus muscles) while sitting on the floor with your leg extended.","Shift your weight onto the ball until you feel moderate, tolerable pressure.","Roll slowly back and forth over a short range, about 2-3 cm at a time.","When you find a tender spot, pause on it and breathe for 20-30 seconds.","Keep your breathing steady and avoid rolling over bone or joints.","Repeat on the other side if needed."],"img":"opengym/4463.webp","gif":null,"ext":1},{"id":"4464","n":"roll ball tibialis anterior","bp":"lower legs","eq":"massage ball","tg":"shins","mg":"calves","sm":["calves","ankles"],"st":["Place the ball under your shin (tibialis anterior) while kneeling or sitting on the floor.","Shift your weight onto the ball until you feel moderate, tolerable pressure.","Roll slowly back and forth over a short range, about 2-3 cm at a time.","When you find a tender spot, pause on it and breathe for 20-30 seconds.","Keep your breathing steady and avoid rolling over bone or joints.","Repeat on the other side if needed."],"img":"opengym/4464.webp","gif":null,"ext":1},{"id":"4465","n":"roll ball calf","bp":"lower legs","eq":"massage ball","tg":"calves","mg":"soleus","sm":["soleus","ankles"],"st":["Place the ball under your calf while seated with your leg extended.","Shift your weight onto the ball until you feel moderate, tolerable pressure.","Roll slowly back and forth over a short range, about 2-3 cm at a time.","When you find a tender spot, pause on it and breathe for 20-30 seconds.","Keep your breathing steady and avoid rolling over bone or joints.","Repeat on the other side if needed."],"img":"opengym/4465.webp","gif":null,"ext":1},{"id":"4466","n":"roll ball popliteal","bp":"upper legs","eq":"massage ball","tg":"hamstrings","mg":"calves","sm":["calves","soleus"],"st":["Place the ball under your back of the knee (popliteal area) while sitting on the floor with your knee gently bent.","Shift your weight onto the ball until you feel moderate, tolerable pressure.","Roll slowly back and forth over a short range, about 2-3 cm at a time.","When you find a tender spot, pause on it and breathe for 20-30 seconds.","Use very light pressure here and stop if you feel tingling.","Repeat on the other side if needed."],"img":"opengym/4466.webp","gif":null,"ext":1},{"id":"4467","n":"roll ball tibialis posterior","bp":"lower legs","eq":"massage ball","tg":"calves","mg":"shins","sm":["shins","soleus","ankles"],"st":["Place the ball under your inner calf (tibialis posterior) while sitting on the floor with your leg rotated outward.","Shift your weight onto the ball until you feel moderate, tolerable pressure.","Roll slowly back and forth over a short range, about 2-3 cm at a time.","When you find a tender spot, pause on it and breathe for 20-30 seconds.","Keep your breathing steady and avoid rolling over bone or joints.","Repeat on the other side if needed."],"img":"opengym/4467.webp","gif":null,"ext":1},{"id":"4468","n":"roll ball rectus femoris","bp":"upper legs","eq":"massage ball","tg":"quads","mg":"hip flexors","sm":["hip flexors","quadriceps"],"st":["Place the ball under your front of the thigh (rectus femoris) while lying face down on the floor.","Shift your weight onto the ball until you feel moderate, tolerable pressure.","Roll slowly back and forth over a short range, about 2-3 cm at a time.","When you find a tender spot, pause on it and breathe for 20-30 seconds.","Keep your breathing steady and avoid rolling over bone or joints.","Repeat on the other side if needed."],"img":"opengym/4468.webp","gif":null,"ext":1},{"id":"4469","n":"roll ball lateral vastus","bp":"upper legs","eq":"massage ball","tg":"quads","mg":"quadriceps","sm":["quadriceps","hip flexors"],"st":["Place the ball under your outer thigh (lateral vastus) while lying on your side.","Shift your weight onto the ball until you feel moderate, tolerable pressure.","Roll slowly back and forth over a short range, about 2-3 cm at a time.","When you find a tender spot, pause on it and breathe for 20-30 seconds.","Keep your breathing steady and avoid rolling over bone or joints.","Repeat on the other side if needed."],"img":"opengym/4469.webp","gif":null,"ext":1},{"id":"4470","n":"roll ball adductors","bp":"upper legs","eq":"massage ball","tg":"adductors","mg":"inner thighs","sm":["inner thighs","groin"],"st":["Place the ball under your inner thigh (adductors) while lying face down with your thigh turned out.","Shift your weight onto the ball until you feel moderate, tolerable pressure.","Roll slowly back and forth over a short range, about 2-3 cm at a time.","When you find a tender spot, pause on it and breathe for 20-30 seconds.","Keep your breathing steady and avoid rolling over bone or joints.","Repeat on the other side if needed."],"img":"opengym/4470.webp","gif":null,"ext":1},{"id":"4471","n":"roll ball tensor fasciae latae","bp":"upper legs","eq":"massage ball","tg":"abductors","mg":"glutes","sm":["glutes","hip flexors"],"st":["Place the ball under your front outer hip (tensor fasciae latae) while lying on your side.","Shift your weight onto the ball until you feel moderate, tolerable pressure.","Roll slowly back and forth over a short range, about 2-3 cm at a time.","When you find a tender spot, pause on it and breathe for 20-30 seconds.","Keep your breathing steady and avoid rolling over bone or joints.","Repeat on the other side if needed."],"img":"opengym/4471.webp","gif":null,"ext":1},{"id":"4472","n":"roll ball gluteus medius","bp":"upper legs","eq":"massage ball","tg":"glutes","mg":"hip flexors","sm":["hip flexors","lower back"],"st":["Place the ball under your side of the glutes (gluteus medius) while lying on your side or leaning on a wall.","Shift your weight onto the ball until you feel moderate, tolerable pressure.","Roll slowly back and forth over a short range, about 2-3 cm at a time.","When you find a tender spot, pause on it and breathe for 20-30 seconds.","Keep your breathing steady and avoid rolling over bone or joints.","Repeat on the other side if needed."],"img":"opengym/4472.webp","gif":null,"ext":1},{"id":"4473","n":"roll ball piriformis","bp":"upper legs","eq":"massage ball","tg":"glutes","mg":"hip flexors","sm":["hip flexors","lower back"],"st":["Place the ball under your deep glutes (piriformis) while sitting on the floor with your ankle over the opposite knee.","Shift your weight onto the ball until you feel moderate, tolerable pressure.","Roll slowly back and forth over a short range, about 2-3 cm at a time.","When you find a tender spot, pause on it and breathe for 20-30 seconds.","Keep your breathing steady and avoid rolling over bone or joints.","Repeat on the other side if needed."],"img":"opengym/4473.webp","gif":null,"ext":1},{"id":"4474","n":"roll ball piriformis v. 2","bp":"upper legs","eq":"massage ball","tg":"glutes","mg":"hip flexors","sm":["hip flexors","lower back"],"st":["Place the ball under your deep glutes (piriformis) while lying on your back with your knee falling across your body.","Shift your weight onto the ball until you feel moderate, tolerable pressure.","Roll slowly back and forth over a short range, about 2-3 cm at a time.","When you find a tender spot, pause on it and breathe for 20-30 seconds.","Keep your breathing steady and avoid rolling over bone or joints.","Repeat on the other side if needed."],"img":"opengym/4474.webp","gif":null,"ext":1},{"id":"4475","n":"roll ball iliospsoas","bp":"upper legs","eq":"massage ball","tg":"glutes","mg":"hip flexors","sm":["hip flexors","core"],"st":["Place the ball under your deep hip flexor (iliopsoas) while lying face down.","Shift your weight onto the ball until you feel moderate, tolerable pressure.","Roll slowly back and forth over a short range, about 2-3 cm at a time.","When you find a tender spot, pause on it and breathe for 20-30 seconds.","Use gentle pressure and breathe slowly so your stomach stays relaxed.","Repeat on the other side if needed."],"img":"opengym/4475.webp","gif":null,"ext":1},{"id":"4476","n":"roll ball psoas abdominal region","bp":"waist","eq":"massage ball","tg":"abs","mg":"hip flexors","sm":["hip flexors","core"],"st":["Place the ball under your psoas area beside the belly button while lying face down.","Shift your weight onto the ball until you feel moderate, tolerable pressure.","Roll slowly back and forth over a short range, about 2-3 cm at a time.","When you find a tender spot, pause on it and breathe for 20-30 seconds.","Use gentle pressure and breathe slowly so your stomach stays relaxed.","Repeat on the other side if needed."],"img":"opengym/4476.webp","gif":null,"ext":1},{"id":"4477","n":"roll ball iliacus abdominal region","bp":"waist","eq":"massage ball","tg":"abs","mg":"hip flexors","sm":["hip flexors","core"],"st":["Place the ball under your iliacus area at the inner hip bone while lying face down.","Shift your weight onto the ball until you feel moderate, tolerable pressure.","Roll slowly back and forth over a short range, about 2-3 cm at a time.","When you find a tender spot, pause on it and breathe for 20-30 seconds.","Use gentle pressure and breathe slowly so your stomach stays relaxed.","Repeat on the other side if needed."],"img":"opengym/4477.webp","gif":null,"ext":1},{"id":"4478","n":"roll ball external oblique","bp":"waist","eq":"massage ball","tg":"obliques","mg":"core","sm":["core"],"st":["Place the ball under your side of the trunk (external oblique) while lying on your side.","Shift your weight onto the ball until you feel moderate, tolerable pressure.","Roll slowly back and forth over a short range, about 2-3 cm at a time.","When you find a tender spot, pause on it and breathe for 20-30 seconds.","Keep your breathing steady and avoid rolling over bone or joints.","Repeat on the other side if needed."],"img":"opengym/4478.webp","gif":null,"ext":1},{"id":"4479","n":"roll ball rectus abdominis","bp":"waist","eq":"massage ball","tg":"abs","mg":"core","sm":["core","lower abs"],"st":["Place the ball under your front abdomen (rectus abdominis) while lying face down.","Shift your weight onto the ball until you feel moderate, tolerable pressure.","Roll slowly back and forth over a short range, about 2-3 cm at a time.","When you find a tender spot, pause on it and breathe for 20-30 seconds.","Use gentle pressure and breathe slowly so your stomach stays relaxed.","Repeat on the other side if needed."],"img":"opengym/4479.webp","gif":null,"ext":1},{"id":"4480","n":"roll ball erector spinae","bp":"back","eq":"massage ball","tg":"spine","mg":"lower back","sm":["lower back","core"],"st":["Place the ball under your muscles beside the lower spine (erector spinae) while lying on your back.","Shift your weight onto the ball until you feel moderate, tolerable pressure.","Roll slowly back and forth over a short range, about 2-3 cm at a time.","When you find a tender spot, pause on it and breathe for 20-30 seconds.","Keep the ball beside the spine, never on it.","Repeat on the other side if needed."],"img":"opengym/4480.webp","gif":null,"ext":1},{"id":"4481","n":"roll ball lumbar diagonal","bp":"back","eq":"massage ball","tg":"spine","mg":"lower back","sm":["lower back","obliques"],"st":["Place the ball under your lower back at a diagonal angle while lying on your back with your hips slightly rotated.","Shift your weight onto the ball until you feel moderate, tolerable pressure.","Roll slowly back and forth over a short range, about 2-3 cm at a time.","When you find a tender spot, pause on it and breathe for 20-30 seconds.","Keep the ball beside the spine, never on it.","Repeat on the other side if needed."],"img":"opengym/4481.webp","gif":null,"ext":1},{"id":"4482","n":"roll ball diaphragm","bp":"waist","eq":"massage ball","tg":"abs","mg":"core","sm":["core","obliques"],"st":["Place the ball under your area just under the lower ribs while lying face down.","Shift your weight onto the ball until you feel moderate, tolerable pressure.","Roll slowly back and forth over a short range, about 2-3 cm at a time.","When you find a tender spot, pause on it and breathe for 20-30 seconds.","Use gentle pressure and breathe slowly so your stomach stays relaxed.","Repeat on the other side if needed."],"img":"opengym/4482.webp","gif":null,"ext":1},{"id":"4483","n":"roll ball pectoralis major sternal","bp":"chest","eq":"massage ball","tg":"pectorals","mg":"chest","sm":["chest","shoulders"],"st":["Place the ball under your mid chest (sternal pectoralis major) while leaning on a wall or lying face down.","Shift your weight onto the ball until you feel moderate, tolerable pressure.","Roll slowly back and forth over a short range, about 2-3 cm at a time.","When you find a tender spot, pause on it and breathe for 20-30 seconds.","Keep your breathing steady and avoid rolling over bone or joints.","Repeat on the other side if needed."],"img":"opengym/4483.webp","gif":null,"ext":1},{"id":"4484","n":"roll ball pectoralis major clavicular","bp":"chest","eq":"massage ball","tg":"pectorals","mg":"upper chest","sm":["upper chest","shoulders"],"st":["Place the ball under your upper chest below the collarbone while leaning on a wall or lying face down.","Shift your weight onto the ball until you feel moderate, tolerable pressure.","Roll slowly back and forth over a short range, about 2-3 cm at a time.","When you find a tender spot, pause on it and breathe for 20-30 seconds.","Keep your breathing steady and avoid rolling over bone or joints.","Repeat on the other side if needed."],"img":"opengym/4484.webp","gif":null,"ext":1},{"id":"4485","n":"roll ball infraspinatus","bp":"back","eq":"massage ball","tg":"delts","mg":"rotator cuff","sm":["rotator cuff","upper back"],"st":["Place the ball under your back of the shoulder blade (infraspinatus) while leaning back against a wall.","Shift your weight onto the ball until you feel moderate, tolerable pressure.","Roll slowly back and forth over a short range, about 2-3 cm at a time.","When you find a tender spot, pause on it and breathe for 20-30 seconds.","Keep your breathing steady and avoid rolling over bone or joints.","Repeat on the other side if needed."],"img":"opengym/4485.webp","gif":null,"ext":1},{"id":"4486","n":"roll ball infraspinatus v. 2","bp":"back","eq":"massage ball","tg":"delts","mg":"rotator cuff","sm":["rotator cuff","upper back"],"st":["Place the ball under your back of the shoulder blade (infraspinatus) while lying on your back on the floor.","Shift your weight onto the ball until you feel moderate, tolerable pressure.","Roll slowly back and forth over a short range, about 2-3 cm at a time.","When you find a tender spot, pause on it and breathe for 20-30 seconds.","Keep your breathing steady and avoid rolling over bone or joints.","Repeat on the other side if needed."],"img":"opengym/4486.webp","gif":null,"ext":1},{"id":"4487","n":"roll ball scapula levator","bp":"back","eq":"massage ball","tg":"levator scapulae","mg":"trapezius","sm":["trapezius","upper back"],"st":["Place the ball under your top inner shoulder blade (levator scapulae) while leaning back against a wall.","Shift your weight onto the ball until you feel moderate, tolerable pressure.","Roll slowly back and forth over a short range, about 2-3 cm at a time.","When you find a tender spot, pause on it and breathe for 20-30 seconds.","Keep your breathing steady and avoid rolling over bone or joints.","Repeat on the other side if needed."],"img":"opengym/4487.webp","gif":null,"ext":1},{"id":"4488","n":"roll ball scapula levator v. 2","bp":"back","eq":"massage ball","tg":"levator scapulae","mg":"trapezius","sm":["trapezius","upper back"],"st":["Place the ball under your top inner shoulder blade (levator scapulae) while lying on your back on the floor.","Shift your weight onto the ball until you feel moderate, tolerable pressure.","Roll slowly back and forth over a short range, about 2-3 cm at a time.","When you find a tender spot, pause on it and breathe for 20-30 seconds.","Keep your breathing steady and avoid rolling over bone or joints.","Repeat on the other side if needed."],"img":"opengym/4488.webp","gif":null,"ext":1},{"id":"4489","n":"roll ball rhomboid","bp":"back","eq":"massage ball","tg":"upper back","mg":"rhomboids","sm":["rhomboids","trapezius"],"st":["Place the ball under your area between the spine and shoulder blade (rhomboids) while leaning back against a wall.","Shift your weight onto the ball until you feel moderate, tolerable pressure.","Roll slowly back and forth over a short range, about 2-3 cm at a time.","When you find a tender spot, pause on it and breathe for 20-30 seconds.","Keep your breathing steady and avoid rolling over bone or joints.","Repeat on the other side if needed."],"img":"opengym/4489.webp","gif":null,"ext":1},{"id":"4490","n":"roll ball trapezius upper","bp":"back","eq":"massage ball","tg":"traps","mg":"upper back","sm":["upper back","rhomboids"],"st":["Place the ball under your upper trapezius while leaning back against a wall.","Shift your weight onto the ball until you feel moderate, tolerable pressure.","Roll slowly back and forth over a short range, about 2-3 cm at a time.","When you find a tender spot, pause on it and breathe for 20-30 seconds.","Keep your breathing steady and avoid rolling over bone or joints.","Repeat on the other side if needed."],"img":"opengym/4490.webp","gif":null,"ext":1},{"id":"4491","n":"roll ball trapezius lower","bp":"back","eq":"massage ball","tg":"traps","mg":"upper back","sm":["upper back","rhomboids"],"st":["Place the ball under your lower trapezius while leaning back against a wall.","Shift your weight onto the ball until you feel moderate, tolerable pressure.","Roll slowly back and forth over a short range, about 2-3 cm at a time.","When you find a tender spot, pause on it and breathe for 20-30 seconds.","Keep your breathing steady and avoid rolling over bone or joints.","Repeat on the other side if needed."],"img":"opengym/4491.webp","gif":null,"ext":1},{"id":"4492","n":"roll ball trapezius lower v. 2","bp":"back","eq":"massage ball","tg":"traps","mg":"upper back","sm":["upper back","rhomboids"],"st":["Place the ball under your lower trapezius while lying on your back on the floor.","Shift your weight onto the ball until you feel moderate, tolerable pressure.","Roll slowly back and forth over a short range, about 2-3 cm at a time.","When you find a tender spot, pause on it and breathe for 20-30 seconds.","Keep your breathing steady and avoid rolling over bone or joints.","Repeat on the other side if needed."],"img":"opengym/4492.webp","gif":null,"ext":1},{"id":"4493","n":"roll ball latissimus dorsi","bp":"back","eq":"massage ball","tg":"lats","mg":"upper back","sm":["upper back","shoulders"],"st":["Place the ball under your side of the back (latissimus dorsi) while lying on your side with your arm overhead.","Shift your weight onto the ball until you feel moderate, tolerable pressure.","Roll slowly back and forth over a short range, about 2-3 cm at a time.","When you find a tender spot, pause on it and breathe for 20-30 seconds.","Keep your breathing steady and avoid rolling over bone or joints.","Repeat on the other side if needed."],"img":"opengym/4493.webp","gif":null,"ext":1},{"id":"4494","n":"roll ball forearm flexors","bp":"lower arms","eq":"massage ball","tg":"forearms","mg":"wrist flexors","sm":["wrist flexors","hands"],"st":["Place the ball under your inside of the forearm (flexors) on a table with your palm facing up.","Shift your weight onto the ball until you feel moderate, tolerable pressure.","Roll slowly back and forth over a short range, about 2-3 cm at a time.","When you find a tender spot, pause on it and breathe for 20-30 seconds.","Keep your breathing steady and avoid rolling over bone or joints.","Repeat on the other side if needed."],"img":"opengym/4494.webp","gif":null,"ext":1},{"id":"4495","n":"roll ball forearm supinator","bp":"lower arms","eq":"massage ball","tg":"forearms","mg":"wrist extensors","sm":["wrist extensors","brachialis"],"st":["Place the ball under your upper forearm (supinator) on a table with your arm resting on it.","Shift your weight onto the ball until you feel moderate, tolerable pressure.","Roll slowly back and forth over a short range, about 2-3 cm at a time.","When you find a tender spot, pause on it and breathe for 20-30 seconds.","Keep your breathing steady and avoid rolling over bone or joints.","Repeat on the other side if needed."],"img":"opengym/4495.webp","gif":null,"ext":1},{"id":"4496","n":"roll ball forearm extensors","bp":"lower arms","eq":"massage ball","tg":"forearms","mg":"wrist extensors","sm":["wrist extensors","hands"],"st":["Place the ball under your top of the forearm (extensors) on a table with your palm facing down.","Shift your weight onto the ball until you feel moderate, tolerable pressure.","Roll slowly back and forth over a short range, about 2-3 cm at a time.","When you find a tender spot, pause on it and breathe for 20-30 seconds.","Keep your breathing steady and avoid rolling over bone or joints.","Repeat on the other side if needed."],"img":"opengym/4496.webp","gif":null,"ext":1},{"id":"4497","n":"roll ball forearm pronator","bp":"lower arms","eq":"massage ball","tg":"forearms","mg":"wrist flexors","sm":["wrist flexors","hands"],"st":["Place the ball under your inner forearm near the elbow (pronator) on a table with your palm facing up.","Shift your weight onto the ball until you feel moderate, tolerable pressure.","Roll slowly back and forth over a short range, about 2-3 cm at a time.","When you find a tender spot, pause on it and breathe for 20-30 seconds.","Keep your breathing steady and avoid rolling over bone or joints.","Repeat on the other side if needed."],"img":"opengym/4497.webp","gif":null,"ext":1},{"id":"4498","n":"roll ball bicep brachii","bp":"upper arms","eq":"massage ball","tg":"biceps","mg":"brachialis","sm":["brachialis","forearms"],"st":["Place the ball under your front of the upper arm (biceps brachii) on a table or against a wall.","Shift your weight onto the ball until you feel moderate, tolerable pressure.","Roll slowly back and forth over a short range, about 2-3 cm at a time.","When you find a tender spot, pause on it and breathe for 20-30 seconds.","Keep your breathing steady and avoid rolling over bone or joints.","Repeat on the other side if needed."],"img":"opengym/4498.webp","gif":null,"ext":1},{"id":"4499","n":"bodyweight full squat with overhead press","bp":"full body","eq":"body weight","tg":"quads","mg":"glutes","sm":["glutes","shoulders","core","triceps"],"st":["Stand with feet shoulder width apart and hands at your shoulders.","Squat down until your thighs pass parallel.","Drive up through your heels as you stand.","Press both arms overhead as you reach the top.","Lower your hands back to your shoulders.","Repeat in a smooth rhythm."],"img":"opengym/4499.webp","gif":null,"ext":1},{"id":"4500","n":"bodyweight front plank to downward dog","bp":"full body","eq":"body weight","tg":"abs","mg":"shoulders","sm":["shoulders","hamstrings","core","calves"],"st":["Start in a straight-arm plank with hands under shoulders.","Brace your core and squeeze your glutes.","Push your hips up and back into an inverted V.","Press your heels toward the floor and lengthen your spine.","Return to plank with control.","Keep moving smoothly for reps."],"img":"opengym/4500.webp","gif":null,"ext":1},{"id":"4506","n":"kneeling shoulder tap","bp":"waist","eq":"body weight","tg":"abs","mg":"shoulders","sm":["shoulders","core","obliques","chest"],"st":["Start on hands and knees, then lift your knees slightly into a kneeling plank.","Keep a straight line from head to knees.","Lift one hand and tap the opposite shoulder.","Place it back down without rocking your hips.","Alternate sides at a steady pace.","Keep your abs tight throughout."],"img":"opengym/4506.webp","gif":null,"ext":1},{"id":"4509","n":"chin to chest stretch","bp":"neck","eq":"body weight","tg":"levator scapulae","mg":"trapezius","sm":["trapezius","sternocleidomastoid"],"st":["Sit or stand tall with your shoulders relaxed.","Slowly lower your chin toward your chest.","Place your hands lightly on the back of your head if you want a deeper stretch.","Keep your shoulders down away from your ears.","Hold for 20-30 seconds.","Return slowly to neutral."],"img":"opengym/4509.webp","gif":null,"ext":1},{"id":"4510","n":"calves stretch","bp":"lower legs","eq":"body weight","tg":"calves","mg":"soleus","sm":["soleus","ankles"],"st":["Stand facing a wall with your hands on it.","Step one foot back with the heel on the floor.","Bend your front knee and lean forward.","Feel the stretch in the back calf.","Hold for 20-30 seconds.","Switch legs and repeat."],"img":"opengym/4510.webp","gif":null,"ext":1},{"id":"4511","n":"bridge pose setu bandhasana","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"hamstrings","sm":["hamstrings","lower back","core","chest"],"st":["Lie on your back with your knees bent and feet hip width apart.","Place your arms alongside your body, palms down.","Press through your feet and lift your hips.","Roll your shoulders under and lengthen your chest.","Hold for 20-30 seconds while breathing steadily.","Lower down slowly."],"img":"opengym/4511.webp","gif":null,"ext":1},{"id":"4512","n":"adductor stretch","bp":"upper legs","eq":"body weight","tg":"adductors","mg":"inner thighs","sm":["inner thighs","groin"],"st":["Sit on the floor with the soles of your feet together.","Hold your ankles and sit tall.","Let your knees fall out to the sides.","Gently press your elbows on your thighs.","Hold for 20-30 seconds.","Release slowly."],"img":"opengym/4512.webp","gif":null,"ext":1},{"id":"4515","n":"back pec stretch v. 2","bp":"chest","eq":"body weight","tg":"pectorals","mg":"shoulders","sm":["shoulders","upper chest"],"st":["Stand tall with your feet hip-width apart.","Clasp your hands together behind your back.","Straighten your arms and lift them gently away from your body.","Open your chest and pull your shoulder blades together.","Hold for 20-30 seconds while breathing slowly.","Release and repeat."],"img":"opengym/4515.webp","gif":null,"ext":1},{"id":"4516","n":"band warm up shoulder stretch","bp":"shoulders","eq":"band","tg":"delts","mg":"rotator cuff","sm":["rotator cuff","upper back"],"st":["Hold a light band with both hands in front of your thighs, hands wide.","Keep your arms straight and your core braced.","Lift the band overhead and continue back behind your head as far as is comfortable.","Return along the same path to the start.","Keep the movement slow and controlled.","Repeat for 10-15 reps, widening your grip if it feels tight."],"img":"opengym/4516.webp","gif":null,"ext":1},{"id":"4518","n":"kettlebell single arm thruster","bp":"full body","eq":"kettlebell","tg":"quads","mg":"glutes","sm":["glutes","shoulders","triceps","core"],"st":["Hold a kettlebell at your shoulder with one hand in the rack position.","Squat down with your chest up and elbow close.","Drive up through your legs.","Use that momentum to press the kettlebell overhead.","Lower it back to your shoulder, repeat, then switch arms."],"img":"opengym/4518.webp","gif":null,"ext":1},{"id":"4521","n":"kettlebell press up","bp":"chest","eq":"kettlebell","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders","core"],"st":["Place two kettlebells on the floor shoulder-width apart and grip the handles.","Extend your legs into a plank position.","Lower your chest between the handles with elbows at about 45 degrees.","Keep your body in a straight line.","Press back up until your arms are straight and repeat."],"img":"opengym/4521.webp","gif":null,"ext":1},{"id":"4524","n":"kettlebell side squat step","bp":"upper legs","eq":"kettlebell","tg":"quads","mg":"glutes","sm":["glutes","adductors","core"],"st":["Hold a kettlebell at your chest with both hands.","Step out to the side and sit back into a squat.","Keep your chest up and knees tracking over your toes.","Push through your heels and bring your feet together.","Alternate directions or complete all steps on one side before switching."],"img":"opengym/4524.webp","gif":null,"ext":1},{"id":"4527","n":"kettlebell single arm swing","bp":"upper legs","eq":"kettlebell","tg":"glutes","mg":"hamstrings","sm":["hamstrings","lower back","shoulders","core"],"st":["Stand with feet slightly wider than your shoulders and the kettlebell in front of you.","Hinge back and swing the bell between your legs.","Snap your hips forward to swing it to chest height.","Let the arm stay relaxed; the hips do the work.","Let the bell fall back and hinge again. Switch hands after your set."],"img":"opengym/4527.webp","gif":null,"ext":1},{"id":"4528","n":"kettlebell farmers walk","bp":"full body","eq":"kettlebell","tg":"forearms","mg":"grip muscles","sm":["grip muscles","trapezius","core","glutes"],"st":["Pick up a kettlebell in each hand and stand tall.","Pull your shoulders back and brace your core.","Walk forward in controlled steps.","Keep the kettlebells from swinging.","Walk for a set distance or time, then set them down carefully."],"img":"opengym/4528.webp","gif":null,"ext":1},{"id":"4530","n":"kettlebell single arm clean","bp":"full body","eq":"kettlebell","tg":"glutes","mg":"hamstrings","sm":["hamstrings","shoulders","biceps","core"],"st":["Stand over a kettlebell and hinge to grip it with one hand.","Swing it back slightly between your legs.","Drive your hips forward and pull the bell up close to your body.","Rotate your hand around so it lands softly in the rack position.","Lower it back down under control, repeat, then switch arms."],"img":"opengym/4530.webp","gif":null,"ext":1},{"id":"4531","n":"kettlebell single arm clean and press","bp":"full body","eq":"kettlebell","tg":"delts","mg":"triceps","sm":["triceps","glutes","hamstrings","core"],"st":["Hinge and swing the kettlebell back, then clean it to your shoulder.","Settle into a stable rack position with your core tight.","Bend your knees slightly, then press the bell straight overhead.","Lock out your elbow with your biceps near your ear.","Lower it to your shoulder, then to the floor. Switch arms after your set."],"img":"opengym/4531.webp","gif":null,"ext":1},{"id":"4532","n":"kettlebell snatch","bp":"full body","eq":"kettlebell","tg":"glutes","mg":"hamstrings","sm":["hamstrings","shoulders","trapezius","core"],"st":["Stand over the kettlebell and hinge to grip it with one hand.","Swing it back between your legs.","Drive your hips forward and pull the bell up close to your body.","Punch your hand through to catch it overhead with a straight arm.","Lower it back under control and repeat, then switch arms."],"img":"opengym/4532.webp","gif":null,"ext":1},{"id":"4533","n":"kettlebell forward lunge and press","bp":"full body","eq":"kettlebell","tg":"glutes","mg":"quadriceps","sm":["quadriceps","shoulders","triceps","core"],"st":["Hold a kettlebell at your shoulder in the rack position.","Step forward into a lunge.","As you push back up, press the kettlebell overhead.","Lower the bell to your shoulder as you step back.","Alternate legs or finish one side before switching."],"img":"opengym/4533.webp","gif":null,"ext":1},{"id":"4534","n":"kettlebell standing slingshots","bp":"shoulders","eq":"kettlebell","tg":"delts","mg":"core","sm":["core","forearms","obliques"],"st":["Stand tall holding a kettlebell by the handle with both hands.","Pass it behind your back from one hand to the other.","Bring it around to the front and pass it again.","Keep your hips steady and your core tight.","Reverse direction halfway through your set."],"img":"opengym/4534.webp","gif":null,"ext":1},{"id":"4535","n":"kettlebell single arm sit up","bp":"waist","eq":"kettlebell","tg":"abs","mg":"hip flexors","sm":["hip flexors","shoulders","obliques"],"st":["Lie on your back with knees bent and a kettlebell held straight up in one hand.","Keep your eyes on the kettlebell and your arm locked.","Curl up and sit all the way to standing or upright.","Control your descent back to the floor.","Finish your reps, then switch arms."],"img":"opengym/4535.webp","gif":null,"ext":1},{"id":"4536","n":"kettlebell rear delt row","bp":"back","eq":"kettlebell","tg":"delts","mg":"upper back","sm":["upper back","rhomboids","rear deltoids","biceps"],"st":["Hinge forward with a flat back holding a kettlebell in each hand.","Let the weights hang below your chest.","Pull your elbows out wide and up toward the ceiling.","Squeeze your shoulder blades together at the top.","Lower slowly and repeat."],"img":"opengym/4536.webp","gif":null,"ext":1},{"id":"4538","n":"kettlebell bent arm pullover with knees bent","bp":"back","eq":"kettlebell","tg":"lats","mg":"chest","sm":["chest","triceps","core"],"st":["Lie on your back with your knees bent and feet flat.","Hold a kettlebell by the horns above your chest with elbows slightly bent.","Lower it back over your head, feeling a stretch in your lats.","Keep your lower back close to the floor.","Pull it back over your chest and repeat."],"img":"opengym/4538.webp","gif":null,"ext":1},{"id":"4539","n":"diamond press","bp":"chest","eq":"body weight","tg":"triceps","mg":"chest","sm":["chest","shoulders","core"],"st":["Start in a plank position with your hands under your chest, thumbs and index fingers forming a diamond.","Keep your body in a straight line from head to heels.","Lower your chest toward your hands, elbows tracking back close to your ribs.","Pause briefly just above your hands.","Press back up until your arms are straight.","Keep your core tight so your hips do not sag."],"img":"opengym/4539.webp","gif":null,"ext":1},{"id":"4540","n":"dumbbell one arm thruster","bp":"full body","eq":"dumbbell","tg":"quads","mg":"glutes","sm":["glutes","shoulders","triceps","core"],"st":["Hold a dumbbell at your shoulder with one hand and stand with feet shoulder-width apart.","Squat down with your chest tall and knees tracking over your toes.","Drive up through your heels.","Use that momentum to press the dumbbell overhead until your arm is straight.","Lower it back to your shoulder as you sink into the next squat.","Finish your reps, then switch arms."],"img":"opengym/4540.webp","gif":null,"ext":1},{"id":"4542","n":"kettlebell clean and jerk","bp":"full body","eq":"kettlebell","tg":"delts","mg":"glutes","sm":["glutes","hamstrings","quadriceps","triceps","core"],"st":["Stand over a kettlebell with feet shoulder-width apart and hinge to grab it.","Swing it back between your legs, then drive your hips forward.","Pull the bell up and guide it into the rack position at your shoulder.","Dip slightly with your knees, then explode up.","Punch the kettlebell overhead and lock out your arm.","Lower it back to the rack, then to the floor with control. Switch sides."],"img":"opengym/4542.webp","gif":null,"ext":1},{"id":"4544","n":"band incline bench press","bp":"chest","eq":"band","tg":"pectorals","mg":"upper chest","sm":["upper chest","shoulders","triceps"],"st":["Set an incline bench and anchor a band behind it or under the bench.","Sit back with the band handles at chest level.","Brace your core and keep your shoulder blades pulled together.","Press the handles up and slightly forward until your arms are straight.","Lower slowly back to the start, feeling the band pull.","Keep your wrists straight throughout."],"img":"opengym/4544.webp","gif":null,"ext":1},{"id":"4545","n":"cable bent over single arm kickback","bp":"upper arms","eq":"cable","tg":"triceps","mg":"shoulders","sm":["shoulders","core"],"st":["Set a low pulley with a single handle and hinge forward at the hips.","Hold the handle with your elbow bent at your side, upper arm parallel to the floor.","Keep your upper arm still and straighten your elbow back.","Squeeze your triceps at full extension.","Return slowly to the start.","Finish your reps, then switch arms."],"img":"opengym/4545.webp","gif":null,"ext":1},{"id":"4546","n":"smith drag curl","bp":"upper arms","eq":"smith machine","tg":"biceps","mg":"brachialis","sm":["brachialis","forearms","shoulders"],"st":["Stand close to the smith bar with an underhand shoulder-width grip.","Let the bar hang at arm length against your thighs.","Pull your elbows back and drag the bar up along your torso.","Squeeze your biceps at the top.","Lower the bar along the same line with control.","Keep your torso still and avoid leaning back."],"img":"opengym/4546.webp","gif":null,"ext":1},{"id":"4547","n":"good morning squat","bp":"upper legs","eq":"body weight","tg":"hamstrings","mg":"glutes","sm":["glutes","quadriceps","lower back","core"],"st":["Stand with feet shoulder-width apart and hands behind your head.","Push your hips back and hinge forward with a flat back.","Come back up to standing.","Bend your knees and sink into a squat with your chest tall.","Stand up and repeat the hinge, then the squat.","Keep your core braced and your weight over your mid-foot."],"img":"opengym/4547.webp","gif":null,"ext":1},{"id":"4548","n":"burpee squat","bp":"full body","eq":"body weight","tg":"cardiovascular system","mg":"quadriceps","sm":["quadriceps","glutes","chest","shoulders","core"],"st":["Stand with feet shoulder-width apart.","Drop into a squat and place your hands on the floor.","Jump or step your feet back into a plank.","Lower your chest down, then press back up.","Jump your feet forward to your hands.","Stand and finish with a bodyweight squat before the next rep."],"img":"opengym/4548.webp","gif":null,"ext":1},{"id":"4552","n":"diagonal lunge","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","adductors","core"],"st":["Stand tall with feet hip-width apart.","Step one foot out diagonally, about 45 degrees away from you.","Bend both knees and lower into a lunge, keeping your chest up.","Push off the front foot to return to the start.","Alternate legs each rep.","Keep your front knee pointing the same way as your toes."],"img":"opengym/4552.webp","gif":null,"ext":1},{"id":"4553","n":"thoracic bridge","bp":"back","eq":"body weight","tg":"glutes","mg":"lower back","sm":["lower back","shoulders","core"],"st":["Sit on the floor with your knees bent and one hand behind you.","Lift your hips toward the ceiling.","Reach your free arm up and over, rotating your chest toward the ceiling.","Open your chest as far as feels comfortable.","Return to the start under control.","Repeat for reps, then switch sides."],"img":"opengym/4553.webp","gif":null,"ext":1},{"id":"4554","n":"seated glute stretch v. 2","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"hip flexors","sm":["hip flexors","lower back"],"st":["Sit on a chair or the floor with your back tall.","Cross one ankle over the opposite knee.","Keep your back straight and lean your chest forward slowly.","Feel the stretch in the glute of the crossed leg.","Hold for 20-30 seconds.","Switch legs."],"img":"opengym/4554.webp","gif":null,"ext":1},{"id":"4555","n":"dynamic 90 90 hip twist","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"adductors","sm":["adductors","hip flexors","obliques"],"st":["Sit on the floor with both knees bent at 90 degrees, feet wide.","Lean back a little and support yourself with your hands.","Rotate both knees to one side so they drop toward the floor.","Rotate smoothly to the other side.","Keep your movements slow and controlled.","Continue for 10-12 reps per side."],"img":"opengym/4555.webp","gif":null,"ext":1},{"id":"4556","n":"push through reach","bp":"back","eq":"body weight","tg":"upper back","mg":"shoulders","sm":["shoulders","obliques","core"],"st":["Start on all fours with hands under shoulders and knees under hips.","Slide one arm under your body, palm up, reaching across.","Let your shoulder and head lower toward the floor.","Hold briefly, then pull the arm back.","Reach it up toward the ceiling, following with your eyes.","Repeat, then switch sides."],"img":"opengym/4556.webp","gif":null,"ext":1},{"id":"4557","n":"couch stretch","bp":"upper legs","eq":"body weight","tg":"quads","mg":"hip flexors","sm":["hip flexors","glutes"],"st":["Kneel facing away from a wall or couch with one shin up against it.","Place your other foot flat on the floor in front in a lunge.","Squeeze your glute and tuck your pelvis under.","Lift your torso upright until you feel the stretch in the front of your rear thigh.","Hold for 30-60 seconds.","Switch legs."],"img":"opengym/4557.webp","gif":null,"ext":1},{"id":"4558","n":"child to cobra pose","bp":"back","eq":"body weight","tg":"spine","mg":"core","sm":["core","shoulders","glutes"],"st":["Start in child pose, knees apart, arms stretched forward.","Shift forward and lower your chest toward the floor.","Slide forward and press into your hands to lift your chest into cobra.","Keep your hips down and your shoulders away from your ears.","Hold for a few breaths.","Push back into child pose and repeat."],"img":"opengym/4558.webp","gif":null,"ext":1},{"id":"4559","n":"kneeling lat stretch on bench","bp":"back","eq":"body weight","tg":"lats","mg":"shoulders","sm":["shoulders","triceps"],"st":["Kneel in front of a bench and place both elbows on top of it.","Keep your hands together or hold a light stick.","Sit your hips back and let your chest sink toward the floor.","Keep your lower back relaxed.","Hold for 20-30 seconds while breathing slowly.","Come back up carefully."],"img":"opengym/4559.webp","gif":null,"ext":1},{"id":"4560","n":"body extension","bp":"upper legs","eq":"body weight","tg":"quads","mg":"lower abs","sm":["lower abs","hip flexors","core"],"st":["Kneel with your knees hip-width apart and your body upright.","Cross your arms or put your hands on your hips.","Squeeze your glutes and lean back from the knees as one straight line.","Go back as far as you can control.","Pull yourself back up to the start.","Keep your hips forward."],"img":"opengym/4560.webp","gif":null,"ext":1},{"id":"4561","n":"bodyweight elevated heel squat","bp":"upper legs","eq":"body weight","tg":"quads","mg":"glutes","sm":["glutes","calves","core"],"st":["Place your heels on a small plate or wedge, feet shoulder-width apart.","Hold your arms in front for balance.","Bend your knees and sink down with your chest tall.","Let your knees travel forward over your toes.","Drive back up through your whole foot.","Keep your core tight throughout."],"img":"opengym/4561.webp","gif":null,"ext":1},{"id":"4562","n":"dumbbell cossack squats","bp":"upper legs","eq":"dumbbell","tg":"quads","mg":"glutes","sm":["glutes","adductors","hamstrings","core"],"st":["Hold a dumbbell at your chest and stand with a wide stance.","Shift your weight to one side and bend that knee, keeping the other leg straight.","Sit deep with your chest up and the straight leg's toes pointing up.","Push through the bent leg to return to the center.","Move into the other side.","Alternate sides with control."],"img":"opengym/4562.webp","gif":null,"ext":1},{"id":"4563","n":"dumbbell squat hold calf raise","bp":"lower legs","eq":"dumbbell","tg":"calves","mg":"quadriceps","sm":["quadriceps","glutes","soleus"],"st":["Hold dumbbells at your sides and sink into a half squat.","Keep your chest tall and weight over your feet.","Lift your heels as high as you can.","Pause briefly at the top.","Lower your heels slowly without standing up.","Stay in the squat for the full set."],"img":"opengym/4563.webp","gif":null,"ext":1},{"id":"4564","n":"dumbbell squat lunges jump complex","bp":"full body","eq":"dumbbell","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","calves","core"],"st":["Hold dumbbells at your sides and stand with feet shoulder-width apart.","Do a squat and stand back up.","Step into a lunge on each leg.","Finish with a jump, landing softly with bent knees.","Continue the chain without putting the weights down.","Rest, then repeat the sequence."],"img":"opengym/4564.webp","gif":null,"ext":1},{"id":"4565","n":"dumbbell step up with knee raise","bp":"upper legs","eq":"dumbbell","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hip flexors","core","calves"],"st":["Hold dumbbells at your sides and stand facing a bench or box.","Place one foot fully on the box.","Push through that heel and step up.","Lift the other knee toward your chest at the top.","Step down with control.","Finish your reps, then switch legs."],"img":"opengym/4565.webp","gif":null,"ext":1},{"id":"4566","n":"cable neutral grip kickback","bp":"upper arms","eq":"cable","tg":"triceps","mg":"shoulders","sm":["shoulders","forearms"],"st":["Set a low cable with a neutral grip handle and hinge forward at the hips.","Pin your upper arm against your side.","Hold the handle with your palm facing in.","Extend your elbow back until your arm is straight.","Squeeze your triceps for a moment.","Return slowly and switch arms after the set."],"img":"opengym/4566.webp","gif":null,"ext":1},{"id":"4567","n":"cable bent over single arm neutral grip kickback with rope attachment","bp":"upper arms","eq":"cable","tg":"triceps","mg":"shoulders","sm":["shoulders","forearms"],"st":["Attach a rope to a low pulley and hold one end with a neutral grip.","Hinge at the hips with a flat back.","Keep your upper arm parallel to the floor and tucked in.","Straighten your elbow and pull the rope back.","Squeeze at the end of the motion.","Lower slowly, then switch arms."],"img":"opengym/4567.webp","gif":null,"ext":1},{"id":"4568","n":"resistance band pull apart","bp":"shoulders","eq":"resistance band","tg":"delts","mg":"rear deltoids","sm":["rear deltoids","upper back","rhomboids","trapezius"],"st":["Hold a resistance band in front of you at chest height, arms straight.","Keep your hands about shoulder-width apart.","Pull the band apart by moving your hands out to the sides.","Squeeze your shoulder blades together.","Return slowly to the start.","Keep your ribs down and shoulders relaxed."],"img":"opengym/4568.webp","gif":null,"ext":1},{"id":"4569","n":"resistance band one arm bent over row","bp":"back","eq":"resistance band","tg":"upper back","mg":"lats","sm":["lats","biceps","rhomboids","core"],"st":["Stand on the band with a staggered stance and hinge forward.","Hold the handle in one hand with your arm extended.","Brace your core and keep your back flat.","Pull your elbow back toward your hip.","Squeeze your shoulder blade at the top.","Lower slowly, then switch sides."],"img":"opengym/4569.webp","gif":null,"ext":1},{"id":"4570","n":"resistance band bent over neutral grip row","bp":"back","eq":"resistance band","tg":"upper back","mg":"lats","sm":["lats","biceps","rhomboids","lower back"],"st":["Stand on the band with feet hip-width apart and hinge forward.","Hold the handles with a neutral grip, arms straight.","Keep your back flat and neck neutral.","Pull both handles toward your lower ribs.","Squeeze your shoulder blades together.","Lower with control."],"img":"opengym/4570.webp","gif":null,"ext":1},{"id":"4572","n":"dumbbell half kneeling lift and chop","bp":"waist","eq":"dumbbell","tg":"abs","mg":"obliques","sm":["obliques","shoulders","glutes","core"],"st":["Kneel on one knee with the other foot forward and hold a dumbbell with both hands.","Start with the weight by your low outside hip.","Lift the dumbbell diagonally across your body to above the opposite shoulder.","Rotate your torso and keep your hips square.","Chop it back down along the same line.","Finish your reps, then switch sides."],"img":"opengym/4572.webp","gif":null,"ext":1},{"id":"4573","n":"band half kneeling chop","bp":"waist","eq":"band","tg":"abs","mg":"obliques","sm":["obliques","shoulders","core"],"st":["Anchor a band high and kneel on one knee side-on to the anchor.","Hold the band with both hands near your high shoulder.","Pull the band diagonally down across your body.","Rotate your torso and keep your hips square.","Return slowly to the start.","Complete your reps, then switch sides."],"img":"opengym/4573.webp","gif":null,"ext":1},{"id":"4574","n":"dumbbell standing biceps curl to shoulder press","bp":"upper arms","eq":"dumbbell","tg":"biceps","mg":"shoulders","sm":["shoulders","triceps","forearms","core"],"st":["Stand holding dumbbells at your sides, palms forward.","Curl both dumbbells up to your shoulders.","Rotate your palms to face forward at the top of the curl.","Press the dumbbells overhead until your arms are straight.","Lower them back to your shoulders, then down to your sides.","Keep your core tight and avoid swinging."],"img":"opengym/4574.webp","gif":null,"ext":1},{"id":"4575","n":"band standing single arm row","bp":"back","eq":"band","tg":"upper back","mg":"lats","sm":["lats","biceps","rhomboids","core"],"st":["Anchor a band at chest height and stand facing it.","Hold the band in one hand with your arm extended.","Step back until there is tension and brace your core.","Pull your elbow back past your ribs.","Squeeze your shoulder blade toward your spine.","Return slowly, then switch arms."],"img":"opengym/4575.webp","gif":null,"ext":1},{"id":"4576","n":"band standing straight arm pulldown","bp":"back","eq":"band","tg":"lats","mg":"triceps","sm":["triceps","core","upper back"],"st":["Anchor a band overhead and hold the ends with arms extended in front of you.","Stand with a slight forward lean and a braced core.","Keep your arms nearly straight.","Pull the band down in an arc until your hands reach your thighs.","Squeeze your lats.","Return slowly to the start."],"img":"opengym/4576.webp","gif":null,"ext":1},{"id":"4577","n":"dumbbell half kneeling military press","bp":"shoulders","eq":"dumbbell","tg":"delts","mg":"triceps","sm":["triceps","upper chest","core","glutes"],"st":["Kneel on one knee with the other foot in front and dumbbells at your shoulders.","Squeeze the glute of the kneeling leg.","Brace your core and keep your ribs down.","Press the dumbbells overhead until your arms are straight.","Lower slowly to shoulder height.","Switch your lead leg halfway through or on the next set."],"img":"opengym/4577.webp","gif":null,"ext":1},{"id":"4578","n":"cable bent over neutral grip kickback with rope attachment","bp":"upper arms","eq":"cable","tg":"triceps","mg":"shoulders","sm":["shoulders","forearms"],"st":["Attach a rope to a low pulley and hold both ends.","Hinge forward at the hips with a flat back.","Keep your upper arms parallel to the floor and close to your sides.","Straighten your elbows and spread the rope slightly at the end.","Squeeze your triceps.","Return slowly to the start."],"img":"opengym/4578.webp","gif":null,"ext":1},{"id":"4579","n":"bodyweight step up on stepbox","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","calves"],"st":["Stand facing a step box with feet hip-width apart.","Place one foot fully on the box.","Push through your heel to step up and stand tall.","Bring the other foot up to meet it.","Step down with control.","Finish your reps, then switch the lead leg."],"img":"opengym/4579.webp","gif":null,"ext":1},{"id":"4580","n":"cat cow stretch","bp":"back","eq":"body weight","tg":"spine","mg":"core","sm":["core","shoulders"],"st":["Start on all fours with hands under shoulders and knees under hips.","Inhale and drop your belly, lifting your chest and tailbone into cow.","Exhale and round your back toward the ceiling into cat.","Tuck your chin and pull your belly in.","Move slowly between the two positions.","Repeat for 10-12 breaths."],"img":"opengym/4580.webp","gif":null,"ext":1},{"id":"4581","n":"boxing block","bp":"shoulders","eq":"body weight","tg":"delts","mg":"forearms","sm":["forearms","core","upper back"],"st":["Stand in a boxing stance with feet staggered and knees slightly bent.","Bring your fists up to your cheeks with elbows tucked in.","Keep your chin down.","Raise your forearms to cover your face as if blocking a punch.","Bring your elbows together to cover your ribs.","Reset to your guard and repeat."],"img":"opengym/4581.webp","gif":null,"ext":1},{"id":"4582","n":"boxing jab (with boxing bag)","bp":"shoulders","eq":"body weight","tg":"delts","mg":"triceps","sm":["triceps","chest","core"],"st":["Stand in a boxing stance facing the bag with your hands up.","Extend your lead hand straight toward the bag.","Rotate your fist so the palm faces down on impact.","Keep your rear hand guarding your chin.","Snap the punch back to your guard right away.","Stay light on your feet and repeat."],"img":"opengym/4582.webp","gif":null,"ext":1},{"id":"4583","n":"boxing right cross (with boxing bag)","bp":"shoulders","eq":"body weight","tg":"delts","mg":"chest","sm":["chest","triceps","obliques","core"],"st":["Stand in a boxing stance facing the bag.","Rotate your rear foot and hips as you throw the right hand.","Drive your fist straight to the bag.","Rotate your shoulder and keep your chin tucked.","Keep your lead hand up to guard.","Snap back to your stance and repeat."],"img":"opengym/4583.webp","gif":null,"ext":1},{"id":"4584","n":"boxing right hook (with boxing bag)","bp":"shoulders","eq":"body weight","tg":"delts","mg":"chest","sm":["chest","obliques","core"],"st":["Stand in a boxing stance facing the bag.","Bend your right elbow to about 90 degrees.","Rotate your hips and torso to swing the fist in an arc.","Pivot your rear foot as you turn.","Hit the bag and keep your left hand guarding.","Return to your guard and repeat."],"img":"opengym/4584.webp","gif":null,"ext":1},{"id":"4585","n":"front groin kick kickboxing (with boxing bag)","bp":"upper legs","eq":"body weight","tg":"quads","mg":"hip flexors","sm":["hip flexors","glutes","core","calves"],"st":["Stand in a fighting stance facing the bag with hands up.","Lift your rear knee toward your chest.","Extend your leg and drive the ball of your foot into the bag.","Lean back slightly to stay balanced.","Pull your leg back quickly.","Return to your stance and switch sides."],"img":"opengym/4585.webp","gif":null,"ext":1},{"id":"4586","n":"front kick kickboxing (with boxing bag)","bp":"upper legs","eq":"body weight","tg":"quads","mg":"hip flexors","sm":["hip flexors","glutes","core","calves"],"st":["Stand in a fighting stance facing the bag.","Lift your rear knee up in front of you.","Extend your leg and push your heel or ball of your foot into the bag.","Lean back slightly and keep your guard up.","Pull the leg back to bend it.","Plant your foot and switch sides."],"img":"opengym/4586.webp","gif":null,"ext":1},{"id":"4587","n":"front snap kick kickboxing (with boxing bag)","bp":"upper legs","eq":"body weight","tg":"quads","mg":"hip flexors","sm":["hip flexors","hamstrings","core","calves"],"st":["Stand in a fighting stance facing the bag.","Raise your knee quickly.","Snap your lower leg out to hit the bag with the ball of your foot.","Recoil right away to bend the knee again.","Keep your hands up.","Set your foot down and switch sides."],"img":"opengym/4587.webp","gif":null,"ext":1},{"id":"4588","n":"hook kick kickboxing (with boxing bag)","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"hip flexors","sm":["hip flexors","obliques","quadriceps","core"],"st":["Stand in a fighting stance facing the bag.","Pivot on your standing foot and lift your rear knee out to the side.","Rotate your hips and swing your leg in an arc.","Hit the bag with the top of your foot or shin.","Keep your hands up and your torso steady.","Bring the leg back and switch sides."],"img":"opengym/4588.webp","gif":null,"ext":1},{"id":"4589","n":"boxing jab (with partner)","bp":"shoulders","eq":"body weight","tg":"delts","mg":"triceps","sm":["triceps","chest","core"],"st":["Face your partner, who holds a pad at head height.","Stand in a boxing stance with hands up.","Throw your lead hand straight to the pad.","Rotate your fist so the palm faces down.","Retract your hand quickly to your guard.","Keep your feet light and repeat."],"img":"opengym/4589.webp","gif":null,"ext":1},{"id":"4590","n":"boxing left uppercut (with partner)","bp":"shoulders","eq":"body weight","tg":"delts","mg":"biceps","sm":["biceps","chest","obliques","core"],"st":["Face your partner, who holds a pad low in front of them.","Stand in a boxing stance and bend your knees slightly.","Dip slightly and drive up through your legs.","Rotate your hips as you bring your left fist up in a tight arc.","Hit the pad with the palm facing you.","Reset your guard."],"img":"opengym/4590.webp","gif":null,"ext":1},{"id":"4591","n":"boxing right cross (with partner)","bp":"shoulders","eq":"body weight","tg":"delts","mg":"chest","sm":["chest","triceps","obliques","core"],"st":["Face your partner, who holds a pad at head height.","Stand in a boxing stance with hands up.","Rotate your rear foot and hips as you throw the right hand.","Drive your fist straight to the pad.","Keep your chin tucked and left hand up.","Snap back to your stance."],"img":"opengym/4591.webp","gif":null,"ext":1},{"id":"4592","n":"boxing right hook (with partner)","bp":"shoulders","eq":"body weight","tg":"delts","mg":"chest","sm":["chest","obliques","core"],"st":["Face your partner, who holds a pad out to the side.","Stand in a boxing stance with hands up.","Bend your right elbow and rotate your hips and torso.","Swing the fist in an arc into the pad.","Pivot your rear foot as you turn.","Return to your guard."],"img":"opengym/4592.webp","gif":null,"ext":1},{"id":"4593","n":"boxing right uppercut (with partner)","bp":"shoulders","eq":"body weight","tg":"delts","mg":"biceps","sm":["biceps","chest","obliques","core"],"st":["Face your partner, who holds a pad low in front of them.","Stand in a boxing stance and bend your knees slightly.","Drive up through your legs and rotate your hips.","Bring your right fist up in a tight arc to the pad.","Keep your left hand guarding.","Reset your stance."],"img":"opengym/4593.webp","gif":null,"ext":1},{"id":"4594","n":"front kick kickboxing (with partner)","bp":"upper legs","eq":"body weight","tg":"quads","mg":"hip flexors","sm":["hip flexors","glutes","core","calves"],"st":["Face your partner, who holds a kick pad at body height.","Stand in a fighting stance with hands up.","Raise your rear knee in front of you.","Extend your leg and push the ball of your foot into the pad.","Pull your leg back quickly.","Switch sides after your reps."],"img":"opengym/4594.webp","gif":null,"ext":1},{"id":"4595","n":"front knee kick kickboxing (with partner)","bp":"upper legs","eq":"body weight","tg":"quads","mg":"hip flexors","sm":["hip flexors","glutes","lower abs","core"],"st":["Face your partner, who holds a pad at waist height.","Stand in a fighting stance with hands up.","Drive your rear knee up and forward into the pad.","Rise slightly onto the toes of your standing foot.","Keep your torso upright.","Lower the leg and switch sides."],"img":"opengym/4595.webp","gif":null,"ext":1},{"id":"4596","n":"front snap kick kickboxing (with partner)","bp":"upper legs","eq":"body weight","tg":"quads","mg":"hip flexors","sm":["hip flexors","hamstrings","core","calves"],"st":["Face your partner, who holds a pad at body height.","Raise your knee quickly.","Snap your lower leg out to hit the pad with the ball of your foot.","Recoil right away to bend the knee again.","Keep your hands up.","Set your foot down and switch sides."],"img":"opengym/4596.webp","gif":null,"ext":1},{"id":"4597","n":"hook kick kickboxing (with partner)","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"hip flexors","sm":["hip flexors","obliques","quadriceps","core"],"st":["Face your partner, who holds a kick pad to the side.","Stand in a fighting stance with hands up.","Pivot on your standing foot and lift your rear knee out.","Rotate your hips and swing your leg in an arc into the pad.","Keep your torso steady.","Bring the leg back and switch sides."],"img":"opengym/4597.webp","gif":null,"ext":1},{"id":"4598","n":"roll tensor fasciae latae","bp":"upper legs","eq":"roller","tg":"abductors","mg":"glutes","sm":["glutes","hip flexors"],"st":["Lie on your side with the roller under the front of your outer hip.","Support yourself with your forearm and opposite foot.","Slowly roll up and down a few inches.","Pause on tender spots for a few seconds.","Breathe slowly and keep the movement gentle.","Roll for 30-60 seconds, then switch sides."],"img":"opengym/4598.webp","gif":null,"ext":1},{"id":"4599","n":"roll iliopsoas","bp":"upper legs","eq":"roller","tg":"glutes","mg":"hip flexors","sm":["hip flexors","lower back","core"],"st":["Lie face down with the roller under the front of one hip, just inside the hip bone.","Support your weight on your forearms.","Shift your weight gently over the roller.","Roll slowly a small distance up and down.","Pause on tight spots while breathing deeply.","Roll for 30-60 seconds, then switch sides."],"img":"opengym/4599.webp","gif":null,"ext":1},{"id":"4600","n":"roll ball lower back","bp":"back","eq":"massage ball","tg":"spine","mg":"glutes","sm":["glutes"],"st":["Lie on your back with a small ball under one side of your lower back.","Bend your knees and keep your feet flat on the floor.","Shift your weight slowly so the ball rolls along the muscle next to the spine.","Pause on tender spots for a few breaths, then move on.","Switch sides and keep the pressure comfortable, never on the spine itself."],"img":"opengym/4600.webp","gif":null,"ext":1},{"id":"4601","n":"open book stretch","bp":"back","eq":"body weight","tg":"upper back","mg":"obliques","sm":["obliques","shoulders","chest"],"st":["Lie on your side with your knees bent and stacked, arms straight in front of you.","Keep your knees together and lift the top arm up and over.","Rotate your chest open toward the ceiling, following your hand with your eyes.","Hold for 20-30 seconds, breathing slowly.","Return the arm and repeat, then switch sides."],"img":"opengym/4601.webp","gif":null,"ext":1},{"id":"4602","n":"pvc external rotation","bp":"shoulders","eq":"body weight","tg":"delts","mg":"rotator cuff","sm":["rotator cuff","rear deltoids"],"st":["Hold a PVC pipe in both hands with your elbows tucked at your sides and bent to 90 degrees.","Keep your elbows pinned and rotate the pipe so one hand moves outward.","Return to the start and rotate the other way.","Move slowly and keep your ribs down and your wrists straight.","Continue alternating for the planned reps."],"img":"opengym/4602.webp","gif":null,"ext":1},{"id":"4603","n":"pvc front rack stretch","bp":"back","eq":"body weight","tg":"lats","mg":"shoulders","sm":["shoulders","wrist flexors","triceps"],"st":["Stand tall holding a PVC pipe across your upper chest in a front rack grip.","Lift your elbows forward and up as high as you comfortably can.","Keep your chest up and your lower back from arching.","Hold for 20-30 seconds while breathing steadily.","Lower the elbows and repeat."],"img":"opengym/4603.webp","gif":null,"ext":1},{"id":"4604","n":"pvc good morning","bp":"upper legs","eq":"body weight","tg":"hamstrings","mg":"glutes","sm":["glutes","lower back","core"],"st":["Stand with feet shoulder-width apart and a PVC pipe across your upper back.","Soften your knees slightly and push your hips straight back.","Lower your torso until you feel a stretch in the hamstrings, keeping your back flat.","Drive your hips forward to stand tall again.","Keep the pipe in contact with your head, upper back and tailbone if you can."],"img":"opengym/4604.webp","gif":null,"ext":1},{"id":"4605","n":"pvc hip hinge","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"hamstrings","sm":["hamstrings","lower back","core"],"st":["Hold a PVC pipe vertically along your spine, one hand at the neck and one at the lower back.","Keep the pipe touching head, upper back and tailbone.","Push your hips back with soft knees and tip forward.","Stop when you feel the hamstrings stretch, then squeeze your glutes to stand.","Keep the pipe contact the whole time."],"img":"opengym/4605.webp","gif":null,"ext":1},{"id":"4606","n":"pvc overhead squat","bp":"upper legs","eq":"body weight","tg":"quads","mg":"glutes","sm":["glutes","shoulders","core","upper back"],"st":["Hold a PVC pipe overhead with a wide grip and arms locked out.","Stand with feet slightly wider than shoulders.","Squat down by sitting between your hips, keeping the pipe over your mid-foot.","Go as deep as you can with your chest up and heels down.","Drive through your feet to stand back up."],"img":"opengym/4606.webp","gif":null,"ext":1},{"id":"4607","n":"pvc pass through","bp":"shoulders","eq":"body weight","tg":"delts","mg":"chest","sm":["chest","upper back","rotator cuff"],"st":["Stand holding a PVC pipe in front of your thighs with a wide overhand grip.","Keep your arms straight and raise the pipe overhead.","Continue moving it down behind your back as far as comfortable.","Reverse the path back to the front with control.","Widen your grip if the shoulders feel pinched."],"img":"opengym/4607.webp","gif":null,"ext":1},{"id":"4608","n":"shin box switch","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"hip flexors","sm":["hip flexors","adductors","groin"],"st":["Sit on the floor with both knees bent at 90 degrees, one leg in front and one to the side.","Sit tall and keep your hands on the floor if needed.","Rotate your knees to the other side so the legs swap positions.","Move smoothly without using your hands to push too hard.","Repeat back and forth for the set."],"img":"opengym/4608.webp","gif":null,"ext":1},{"id":"4609","n":"lying side to side knee","bp":"upper legs","eq":"body weight","tg":"spine","mg":"obliques","sm":["obliques","glutes","core"],"st":["Lie on your back with arms out to the sides and knees bent, feet flat.","Keep your shoulders on the floor.","Slowly drop both knees to one side as far as is comfortable.","Bring them back to the middle and drop them to the other side.","Move at an easy pace and breathe through each rep."],"img":"opengym/4609.webp","gif":null,"ext":1},{"id":"4611","n":"roll ball deltoid posterior","bp":"shoulders","eq":"massage ball","tg":"delts","mg":"rear deltoids","sm":["rear deltoids","rotator cuff"],"st":["Place a small ball between the back of your shoulder and a wall.","Lean in until you feel moderate pressure.","Roll slowly up, down and sideways over the rear deltoid.","Pause on tight spots for a few breaths.","Switch to the other shoulder."],"img":"opengym/4611.webp","gif":null,"ext":1},{"id":"4612","n":"bodyweight standing around the world (wall supported)","bp":"shoulders","eq":"body weight","tg":"delts","mg":"upper back","sm":["upper back","chest","rotator cuff"],"st":["Stand with your back flat against a wall, feet slightly forward.","Start with arms straight down at your sides, palms forward.","Sweep your arms out to the sides and overhead in a wide arc, staying close to the wall.","Lower them back down the same way.","Keep your ribs and head against the wall."],"img":"opengym/4612.webp","gif":null,"ext":1},{"id":"4613","n":"bodyweight standing military press (wall supported)","bp":"shoulders","eq":"body weight","tg":"delts","mg":"triceps","sm":["triceps","upper back"],"st":["Stand with your back, head and hips against a wall, hands at shoulder height with elbows bent.","Brace your abs so your lower back stays on the wall.","Press your hands straight overhead until your arms are locked out.","Lower back to shoulder height with control.","Keep your wrists stacked over your elbows."],"img":"opengym/4613.webp","gif":null,"ext":1},{"id":"4615","n":"hip swirls","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"hip flexors","sm":["hip flexors","obliques","core"],"st":["Stand with feet shoulder-width apart and hands on your hips.","Slightly bend your knees.","Move your hips in a large smooth circle, as if drawing it with your belt buckle.","Do several circles one way, then switch direction.","Keep your shoulders still and relaxed."],"img":"opengym/4615.webp","gif":null,"ext":1},{"id":"4616","n":"leg front kick","bp":"waist","eq":"body weight","tg":"abs","mg":"hip flexors","sm":["hip flexors","quadriceps"],"st":["Stand tall with your arms out for balance or hands on your hips.","Shift your weight onto one foot.","Swing the other leg forward and up in a controlled kick, keeping it fairly straight.","Lower it with control without leaning back.","Complete your reps, then switch legs."],"img":"opengym/4616.webp","gif":null,"ext":1},{"id":"4617","n":"single arm push up (wall supported)","bp":"chest","eq":"body weight","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders","core"],"st":["Stand facing a wall at arm's length and place one hand on it at chest height.","Keep your other arm behind your back or at your side.","Bend your elbow to lower your chest toward the wall, body in a straight line.","Press back to the start.","Finish your reps, then switch arms."],"img":"opengym/4617.webp","gif":null,"ext":1},{"id":"4618","n":"band deadlift","bp":"upper legs","eq":"band","tg":"glutes","mg":"hamstrings","sm":["hamstrings","lower back","core","grip muscles"],"st":["Stand on the band with feet hip-width apart and grab it with both hands.","Hinge at the hips with a flat back and slightly bent knees.","Lower your hands along your legs until you feel a hamstring stretch.","Drive your hips forward to stand tall and squeeze your glutes.","Keep the band close to your body."],"img":"opengym/4618.webp","gif":null,"ext":1},{"id":"4619","n":"band standing hammer curl","bp":"upper arms","eq":"band","tg":"biceps","mg":"brachialis","sm":["brachialis","forearms"],"st":["Stand on the band and hold the ends with palms facing each other.","Keep your elbows at your sides.","Curl your hands up toward your shoulders without turning your wrists.","Pause briefly at the top.","Lower slowly back to the start."],"img":"opengym/4619.webp","gif":null,"ext":1},{"id":"4621","n":"dumbbell close grip shoulder press sit up","bp":"waist","eq":"dumbbell","tg":"abs","mg":"shoulders","sm":["shoulders","triceps","hip flexors"],"st":["Lie on your back with knees bent, holding a dumbbell in each hand at your shoulders, palms facing in.","Sit up using your abs.","Press the dumbbells overhead at the top.","Lower them to your shoulders and roll back down slowly.","Keep your feet planted, or anchor them if needed."],"img":"opengym/4621.webp","gif":null,"ext":1},{"id":"4622","n":"dumbbell front plank arm raise","bp":"waist","eq":"dumbbell","tg":"abs","mg":"shoulders","sm":["shoulders"],"st":["Start in a forearm or high plank with a dumbbell in one hand.","Brace your abs and keep hips level.","Lift the dumbbell forward in line with your torso.","Lower it with control.","Alternate arms for the set."],"img":"opengym/4622.webp","gif":null,"ext":1},{"id":"4623","n":"weighted seated tuck crunch on floor","bp":"waist","eq":"weighted","tg":"abs","mg":"hip flexors","sm":["hip flexors","lower abs"],"st":["Sit on the floor holding a weight at your chest, leaning back slightly with legs extended.","Lift your feet off the floor.","Pull your knees in while bringing your chest forward.","Extend your legs again without touching the floor.","Keep your back long and breathe steadily."],"img":"opengym/4623.webp","gif":null,"ext":1},{"id":"4624","n":"dumbbell crunch up","bp":"waist","eq":"dumbbell","tg":"abs","mg":"obliques","sm":["obliques"],"st":["Lie on your back with knees bent and a dumbbell held against your chest.","Brace your abs.","Curl your head and shoulders off the floor.","Pause at the top.","Lower back down slowly."],"img":"opengym/4624.webp","gif":null,"ext":1},{"id":"4625","n":"dumbbell russian twist close grip shoulder press sit up","bp":"waist","eq":"dumbbell","tg":"obliques","mg":"abdominals","sm":["abdominals","shoulders","triceps"],"st":["Lie on your back with knees bent, holding dumbbells at your shoulders.","Sit up and rotate your torso to one side.","Rotate back to center and press the dumbbells overhead.","Lower them to your shoulders and roll back down.","Alternate sides each rep."],"img":"opengym/4625.webp","gif":null,"ext":1},{"id":"4626","n":"dumbbell seated tuck crunch on floor","bp":"waist","eq":"dumbbell","tg":"abs","mg":"hip flexors","sm":["hip flexors","lower abs"],"st":["Sit on the floor holding a dumbbell at your chest and lean back slightly.","Extend your legs and lift your feet off the floor.","Pull your knees in toward your chest.","Extend your legs back out under control.","Keep your spine long throughout."],"img":"opengym/4626.webp","gif":null,"ext":1},{"id":"4627","n":"dumbbell front plank arm leg raise","bp":"waist","eq":"dumbbell","tg":"abs","mg":"glutes","sm":["glutes","shoulders"],"st":["Start in a high plank with a dumbbell in one hand.","Brace your abs and squeeze your glutes.","Lift the dumbbell forward and the opposite leg back at the same time.","Lower both under control.","Alternate sides each rep."],"img":"opengym/4627.webp","gif":null,"ext":1},{"id":"4628","n":"dumbbell seated tuck twisting crunch on floor","bp":"waist","eq":"dumbbell","tg":"obliques","mg":"abdominals","sm":["abdominals","hip flexors"],"st":["Sit on the floor holding a dumbbell at your chest and lean back slightly.","Lift your feet off the floor.","Pull your knees in and rotate your torso to one side.","Extend your legs and rotate back to center.","Repeat on the other side."],"img":"opengym/4628.webp","gif":null,"ext":1},{"id":"4629","n":"dumbbell renegade row to squat","bp":"full body","eq":"dumbbell","tg":"upper back","mg":"lats","sm":["lats","core","quadriceps","glutes","biceps"],"st":["Start in a high plank with your hands on dumbbells.","Row one dumbbell to your hip, keeping hips level.","Lower it, then hop or step your feet toward your hands.","Stand up with the dumbbells and squat down.","Return to plank and alternate the rowing arm."],"img":"opengym/4629.webp","gif":null,"ext":1},{"id":"4630","n":"side to side leg swings","bp":"upper legs","eq":"body weight","tg":"adductors","mg":"glutes","sm":["glutes","hip flexors"],"st":["Stand tall and hold a wall or support for balance.","Shift onto one leg.","Swing the other leg across your body, then out to the side.","Keep your torso upright and the swing controlled.","Do your reps, then switch legs."],"img":"opengym/4630.webp","gif":null,"ext":1},{"id":"4631","n":"scorpion stretch","bp":"waist","eq":"body weight","tg":"abs","mg":"hip flexors","sm":["hip flexors","obliques","lower back"],"st":["Lie face down with your arms out to the sides.","Bend one knee and swing that foot up and across your body.","Reach toward the opposite hand and keep shoulders on the floor.","Hold for 20-30 seconds.","Return and switch sides."],"img":"opengym/4631.webp","gif":null,"ext":1},{"id":"4634","n":"high knee to butt kick","bp":"cardio","eq":"body weight","tg":"cardiovascular system","mg":"quadriceps","sm":["quadriceps","hamstrings","hip flexors","calves"],"st":["Stand tall with feet hip-width apart.","Drive one knee up to hip height.","Lower it and kick the same heel toward your glutes.","Alternate sides at a steady, light pace.","Keep your core braced and stay on the balls of your feet."],"img":"opengym/4634.webp","gif":null,"ext":1},{"id":"4646","n":"russian twist with hands on chest","bp":"waist","eq":"body weight","tg":"obliques","mg":"abdominals","sm":["abdominals","hip flexors","lower back"],"st":["Sit on the floor with your knees bent and lean back slightly.","Cross your hands over your chest.","Lift your feet slightly off the floor if you can.","Rotate your torso to one side, then to the other.","Move with control and keep your chest lifted."],"img":"opengym/4646.webp","gif":null,"ext":1},{"id":"4653","n":"standing single leg high knee to butt kick (with support)","bp":"upper legs","eq":"body weight","tg":"quads","mg":"hamstrings","sm":["hamstrings","hip flexors","glutes"],"st":["Stand next to a wall or support and hold it with one hand.","Raise the opposite knee to hip height.","Lower it and kick that heel up toward your glutes.","Repeat smoothly for the reps.","Switch sides and keep your torso upright."],"img":"opengym/4653.webp","gif":null,"ext":1},{"id":"4658","n":"kneeling shoulder tap push up","bp":"chest","eq":"body weight","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders","core"],"st":["Start in a kneeling push-up position with hands under your shoulders.","Lower your chest toward the floor.","Press back up to straight arms.","Lift one hand and tap the opposite shoulder, then switch.","Keep your hips steady and repeat."],"img":"opengym/4658.webp","gif":null,"ext":1},{"id":"4663","n":"backhand raise","bp":"shoulders","eq":"body weight","tg":"delts","mg":"rear deltoids","sm":["rear deltoids","upper back","rhomboids","lower back"],"st":["Lie face down with your arms by your sides, palms up.","Lift your chest and arms slightly off the floor.","Raise your hands up and back by squeezing your shoulder blades.","Pause at the top.","Lower slowly and repeat."],"img":"opengym/4663.webp","gif":null,"ext":1},{"id":"4665","n":"overhead clap","bp":"shoulders","eq":"body weight","tg":"delts","mg":"upper back","sm":["upper back","core","triceps"],"st":["Stand tall with your feet hip-width apart and arms at your sides.","Raise both arms out to the sides and overhead.","Clap your hands above your head.","Lower your arms back to your sides with control.","Keep your ribs down and move smoothly through your reps."],"img":"opengym/4665.webp","gif":null,"ext":1},{"id":"4667","n":"bodyweight overhead triceps extension","bp":"upper arms","eq":"body weight","tg":"triceps","mg":"shoulders","sm":["shoulders","core"],"st":["Place your hands on a bar or sturdy surface at about waist height, shoulder-width apart.","Walk your feet back and lean forward in a plank.","Bend your elbows and lower your head between your arms.","Keep your elbows pointing forward and your body straight.","Press back up by extending your arms and repeat."],"img":"opengym/4667.webp","gif":null,"ext":1},{"id":"4669","n":"kneeling hip thrust","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"hamstrings","sm":["hamstrings","core","lower back"],"st":["Kneel upright with your hips over your knees and your arms by your sides.","Sit your hips back toward your heels.","Drive your hips forward, squeezing your glutes.","Stand tall at the top without leaning back.","Return slowly and repeat."],"img":"opengym/4669.webp","gif":null,"ext":1},{"id":"4671","n":"dynamic back stretch","bp":"back","eq":"body weight","tg":"lats","mg":"upper back","sm":["upper back","obliques","shoulders"],"st":["Stand with feet wider than hips and arms overhead.","Reach up and over to one side.","Return to center and reach to the other side.","Let your torso rotate slightly as you go.","Move smoothly for the reps."],"img":"opengym/4671.webp","gif":null,"ext":1},{"id":"4672","n":"elbows back stretch","bp":"chest","eq":"body weight","tg":"pectorals","mg":"shoulders","sm":["shoulders","upper chest"],"st":["Stand tall with your hands behind your head and elbows pointing out.","Draw your elbows back and squeeze your shoulder blades together.","Lift your chest slightly.","Hold for 20-30 seconds.","Relax and repeat."],"img":"opengym/4672.webp","gif":null,"ext":1},{"id":"4673","n":"hip extension stretch","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"hip flexors","sm":["hip flexors","quadriceps","lower back"],"st":["Stand or kneel with one foot forward in a lunge position.","Tuck your pelvis under and squeeze the back glute.","Lean slightly forward to feel the stretch at the front of the hip.","Hold for 20-30 seconds.","Switch sides."],"img":"opengym/4673.webp","gif":null,"ext":1},{"id":"4674","n":"hip flexor stretch (rear foot elevated)","bp":"upper legs","eq":"body weight","tg":"hip flexors","mg":"quadriceps","sm":["quadriceps","glutes"],"st":["Place the top of your back foot on a bench behind you.","Step your front foot forward into a lunge.","Tuck your pelvis and push your hips forward.","Keep your chest tall and hold for 20-30 seconds.","Switch sides."],"img":"opengym/4674.webp","gif":null,"ext":1},{"id":"4675","n":"plyo side lunge stretch","bp":"upper legs","eq":"body weight","tg":"adductors","mg":"glutes","sm":["glutes","quadriceps","groin"],"st":["Stand with feet wide apart.","Shift your weight to one side and sit into a side lunge.","Straighten the other leg and feel the inner thigh stretch.","Push off to hop to the other side.","Continue alternating at a controlled pace."],"img":"opengym/4675.webp","gif":null,"ext":1},{"id":"4677","n":"band kneeling single leg kick","bp":"upper legs","eq":"band","tg":"glutes","mg":"hamstrings","sm":["hamstrings","core","lower back"],"st":["Get on all fours with a band looped around your foot and hands.","Brace your core and keep your back flat.","Extend one leg back, squeezing your glute.","Pause briefly at full extension.","Return with control and repeat, then switch legs."],"img":"opengym/4677.webp","gif":null,"ext":1},{"id":"4678","n":"band swing","bp":"upper legs","eq":"band","tg":"glutes","mg":"hamstrings","sm":["hamstrings","lower back","shoulders","core"],"st":["Stand on the band holding the other end with both hands.","Hinge your hips back with a flat back.","Drive your hips forward to swing your arms up to chest height.","Squeeze your glutes at the top.","Control the return and repeat."],"img":"opengym/4678.webp","gif":null,"ext":1},{"id":"4679","n":"band split squat v. 2","bp":"upper legs","eq":"band","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","adductors","core"],"st":["Stand on the band with your front foot and hold the other end at your shoulders.","Step your other foot back into a split stance.","Lower your back knee toward the floor.","Keep your torso upright and your front knee stable.","Drive up through the front foot, then switch legs after your set."],"img":"opengym/4679.webp","gif":null,"ext":1},{"id":"4680","n":"band standing triceps extension","bp":"upper arms","eq":"band","tg":"triceps","mg":"shoulders","sm":["shoulders","core"],"st":["Anchor the band overhead and hold the ends with both hands.","Keep your elbows tucked at your sides.","Press your hands down until your arms are straight.","Squeeze your triceps at the bottom.","Let your hands rise slowly and repeat."],"img":"opengym/4680.webp","gif":null,"ext":1},{"id":"4681","n":"band lying alternate leg press","bp":"upper legs","eq":"band","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","calves"],"st":["Lie on your back and loop the band around the soles of your feet, holding the ends.","Bend both knees toward your chest.","Press one foot out straight against the band.","Bring it back and press the other leg.","Alternate smoothly with control."],"img":"opengym/4681.webp","gif":null,"ext":1},{"id":"4683","n":"band squat v. 2","bp":"upper legs","eq":"band","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","adductors","core"],"st":["Stand on the band with your feet shoulder-width apart and hold the ends at your shoulders.","Brace your core and keep your chest up.","Sit your hips back and down.","Go to at least parallel without letting your knees cave in.","Drive up through your heels and repeat."],"img":"opengym/4683.webp","gif":null,"ext":1},{"id":"4684","n":"band kneeling incline press","bp":"chest","eq":"band","tg":"pectorals","mg":"upper chest","sm":["upper chest","shoulders","triceps","core"],"st":["Anchor the band low behind you and kneel facing away from it.","Hold the ends at chest height.","Press your hands up and forward at an incline.","Squeeze your chest at the top.","Return slowly with control and repeat."],"img":"opengym/4684.webp","gif":null,"ext":1},{"id":"4685","n":"band standing side bend","bp":"waist","eq":"band","tg":"obliques","mg":"core","sm":["core"],"st":["Stand on one end of the band and hold the other end at your side.","Keep your feet shoulder-width apart.","Bend sideways at the waist away from the band.","Squeeze your obliques and return upright.","Finish your reps, then switch sides."],"img":"opengym/4685.webp","gif":null,"ext":1},{"id":"4686","n":"band standing behind head military press","bp":"shoulders","eq":"band","tg":"delts","mg":"triceps","sm":["triceps","upper back","trapezius"],"st":["Stand on the band and hold the ends behind your head at shoulder level.","Brace your core and keep your ribs down.","Press your hands straight overhead.","Lock out your arms without shrugging.","Lower slowly back behind your head and repeat."],"img":"opengym/4686.webp","gif":null,"ext":1},{"id":"4690","n":"leg over knee glute bridge","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"hamstrings","sm":["hamstrings","core","lower back"],"st":["Lie on your back with knees bent and one ankle crossed over the other knee.","Press through the grounded foot.","Lift your hips until your body forms a line.","Squeeze your glutes at the top.","Lower slowly and switch sides."],"img":"opengym/4690.webp","gif":null,"ext":1},{"id":"4692","n":"bent knee back to side kick","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"hamstrings","sm":["hamstrings","core"],"st":["Start on all fours with a flat back.","Lift one bent knee back and up.","Swing the leg out to the side into a kick.","Return the knee under control.","Switch legs after the set."],"img":"opengym/4692.webp","gif":null,"ext":1},{"id":"4693","n":"kneeling leg half circle","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"hip flexors","sm":["hip flexors","core"],"st":["Start on all fours, hands under shoulders.","Lift one leg out straight behind you.","Sweep it in a half circle out to the side.","Return the same way.","Keep your hips square and switch sides."],"img":"opengym/4693.webp","gif":null,"ext":1},{"id":"4694","n":"band overhead triceps extension v. 4","bp":"upper arms","eq":"band","tg":"triceps","mg":"shoulders","sm":["shoulders","core"],"st":["Stand on the band and hold the ends behind your head with elbows bent.","Keep your elbows pointing forward.","Extend your arms overhead.","Squeeze your triceps at the top.","Lower slowly and repeat."],"img":"opengym/4694.webp","gif":null,"ext":1},{"id":"4695","n":"band standing single arm upright row","bp":"shoulders","eq":"band","tg":"delts","mg":"trapezius","sm":["trapezius","biceps","upper back"],"st":["Stand on the band and hold the other end in one hand at your thigh.","Keep your elbow leading the movement.","Pull your hand up toward your chest, elbow higher than the wrist.","Pause at the top.","Lower slowly, then repeat and switch arms."],"img":"opengym/4695.webp","gif":null,"ext":1},{"id":"4696","n":"band down to up twist","bp":"waist","eq":"band","tg":"obliques","mg":"shoulders","sm":["shoulders","core"],"st":["Anchor the band low and stand sideways to it, holding the end with both hands.","Start with your hands near the low hip.","Pull diagonally upward across your body as you rotate your torso.","Pivot your back foot and keep your arms long.","Return slowly, repeat, then switch sides."],"img":"opengym/4696.webp","gif":null,"ext":1},{"id":"4697","n":"band skier v. 2","bp":"shoulders","eq":"band","tg":"delts","mg":"lats","sm":["lats","core","glutes"],"st":["Anchor the band overhead and hold the ends with both hands.","Stand with a slight bend in your knees.","Pull your arms down and back past your hips.","Squeeze your lats and keep your core braced.","Return slowly overhead and repeat."],"img":"opengym/4697.webp","gif":null,"ext":1},{"id":"4698","n":"band bent over row v. 3","bp":"back","eq":"band","tg":"upper back","mg":"lats","sm":["lats","rhomboids","biceps","rear deltoids"],"st":["Stand on the band and hold the ends, hinging forward with a flat back.","Let your arms hang straight down.","Row your elbows back toward your hips.","Squeeze your shoulder blades together.","Lower slowly and repeat."],"img":"opengym/4698.webp","gif":null,"ext":1},{"id":"4699","n":"band air bike","bp":"waist","eq":"band","tg":"abs","mg":"hip flexors","sm":["hip flexors","obliques","lower abs"],"st":["Lie on your back with the band looped around your feet and hold the ends.","Raise your legs and shoulders slightly off the floor.","Pedal one leg in while extending the other.","Twist your torso to bring the opposite elbow to the knee.","Keep a steady rhythm and keep your core tight."],"img":"opengym/4699.webp","gif":null,"ext":1},{"id":"4700","n":"band side bend press","bp":"shoulders","eq":"band","tg":"delts","mg":"obliques","sm":["obliques","triceps","core"],"st":["Stand on the band and hold the end in one hand at your shoulder.","Press the band overhead as you bend gently to the opposite side.","Keep your hips steady and your chest open.","Return to upright as you lower your hand.","Finish your reps, then switch sides."],"img":"opengym/4700.webp","gif":null,"ext":1},{"id":"4701","n":"band single leg reverse hyperextension","bp":"upper legs","eq":"band","tg":"glutes","mg":"hamstrings","sm":["hamstrings","lower back","core"],"st":["Lie face down with a band looped around one foot and anchored under you.","Rest your arms under your head.","Lift one leg up, keeping it straight.","Squeeze your glute at the top.","Lower slowly, repeat, then switch legs."],"img":"opengym/4701.webp","gif":null,"ext":1},{"id":"4702","n":"alternating superman","bp":"back","eq":"body weight","tg":"spine","mg":"glutes","sm":["glutes","rear deltoids","hamstrings"],"st":["Lie face down with arms extended in front.","Lift one arm and the opposite leg together.","Hold for a second.","Lower and switch to the other side.","Keep your neck neutral and move with control."],"img":"opengym/4702.webp","gif":null,"ext":1},{"id":"4703","n":"bodyweight full squat with overhead press (version 2)","bp":"full body","eq":"body weight","tg":"quads","mg":"glutes","sm":["glutes","shoulders","triceps","core"],"st":["Stand with feet shoulder-width apart and hands at your shoulders.","Squat deep, keeping chest up.","Drive up out of the squat.","Press your arms overhead as you stand.","Lower your hands and repeat."],"img":"opengym/4703.webp","gif":null,"ext":1},{"id":"4706","n":"jump step jump","bp":"full body","eq":"body weight","tg":"cardiovascular system","mg":"quadriceps","sm":["quadriceps","calves","glutes"],"st":["Stand with feet hip-width apart.","Jump up and land softly with bent knees.","Step to the side or forward.","Jump again and land softly.","Keep a steady rhythm."],"img":"opengym/4706.webp","gif":null,"ext":1},{"id":"4709","n":"basketball shot jump","bp":"full body","eq":"body weight","tg":"quads","mg":"calves","sm":["calves","glutes","shoulders","triceps"],"st":["Stand in an athletic stance with hands at chest height.","Dip into a quarter squat.","Jump up and extend one arm like shooting a basketball.","Land softly with bent knees.","Reset and repeat."],"img":"opengym/4709.webp","gif":null,"ext":1},{"id":"4711","n":"criss cross jack","bp":"full body","eq":"body weight","tg":"cardiovascular system","mg":"calves","sm":["calves","shoulders","adductors","quadriceps"],"st":["Stand with feet together and arms at your sides.","Jump your feet apart while the arms swing overhead.","Jump and cross one foot in front and the arms across your chest.","Alternate which side crosses.","Keep a quick but controlled pace."],"img":"opengym/4711.webp","gif":null,"ext":1},{"id":"4714","n":"air squat (version 2)","bp":"upper legs","eq":"body weight","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","calves","core"],"st":["Stand with feet shoulder-width apart, toes slightly out.","Push your hips back and bend your knees.","Lower until thighs are at least parallel with chest up.","Drive through your heels to stand.","Keep your knees tracking over your toes."],"img":"opengym/4714.webp","gif":null,"ext":1},{"id":"4715","n":"alternating superman v. 2","bp":"back","eq":"body weight","tg":"spine","mg":"glutes","sm":["glutes","rear deltoids","hamstrings"],"st":["Lie face down with arms extended overhead.","Raise your right arm and left leg.","Hold briefly and lower.","Raise your left arm and right leg.","Keep your neck neutral and move smoothly."],"img":"opengym/4715.webp","gif":null,"ext":1},{"id":"4716","n":"assisted chin up (low bar position)","bp":"back","eq":"assisted","tg":"lats","mg":"biceps","sm":["biceps","upper back","forearms"],"st":["Set a bar at about chest height and sit or lie beneath it.","Grip the bar with palms facing you.","Pull your chest toward the bar using your arms and back.","Use your legs only as much as needed.","Lower with control."],"img":"opengym/4716.webp","gif":null,"ext":1},{"id":"4717","n":"assisted commando pull up","bp":"back","eq":"assisted","tg":"lats","mg":"biceps","sm":["biceps","upper back","obliques","forearms"],"st":["Grip a bar with one hand in front of the other.","Use a band or feet for assistance.","Pull until your head passes the bar to one side.","Lower with control.","Switch the head side on the next rep."],"img":"opengym/4717.webp","gif":null,"ext":1},{"id":"4718","n":"band assisted chin up","bp":"back","eq":"assisted","tg":"lats","mg":"biceps","sm":["biceps","upper back","forearms","core"],"st":["Hang from a bar with an underhand grip and the band looped under your feet.","Engage your lats and keep your core tight.","Pull your chin over the bar.","Pause at the top.","Lower slowly until your arms are straight and repeat."],"img":"opengym/4718.webp","gif":null,"ext":1},{"id":"4719","n":"band assisted dip (version 2)","bp":"upper arms","eq":"band","tg":"triceps","mg":"chest","sm":["chest","shoulders"],"st":["Loop a band across dip bars and place your knees in it.","Support yourself with straight arms.","Lower until your elbows reach about 90 degrees.","Press back up.","Keep your shoulders away from your ears."],"img":"opengym/4719.webp","gif":null,"ext":1},{"id":"4720","n":"band kneeling crunch v. 2","bp":"waist","eq":"band","tg":"abs","mg":"hip flexors","sm":["hip flexors","obliques"],"st":["Anchor the band overhead and kneel facing it.","Hold the band beside your head.","Crunch down, bringing your elbows toward your thighs.","Round your spine and tighten your abs.","Return slowly and repeat."],"img":"opengym/4720.webp","gif":null,"ext":1},{"id":"4721","n":"bar biceps curl","bp":"upper arms","eq":"barbell","tg":"biceps","mg":"brachialis","sm":["brachialis","forearms"],"st":["Stand holding a bar with an underhand shoulder-width grip.","Keep your elbows at your sides.","Curl the bar up to shoulder height.","Squeeze your biceps.","Lower slowly without swinging."],"img":"opengym/4721.webp","gif":null,"ext":1},{"id":"4722","n":"bodyweight kneeling sissy squat","bp":"upper legs","eq":"body weight","tg":"quads","mg":"hip flexors","sm":["hip flexors","core"],"st":["Kneel with your knees hip-width apart and a support nearby.","Squeeze your glutes to keep your hips forward.","Lean back slowly as far as you can.","Pull back up with your quads.","Keep a straight line from knees to head."],"img":"opengym/4722.webp","gif":null,"ext":1},{"id":"4723","n":"bodyweight standing sissy squat","bp":"upper legs","eq":"body weight","tg":"quads","mg":"hip flexors","sm":["hip flexors","calves","core"],"st":["Stand holding a support, feet hip-width apart.","Rise onto the balls of your feet.","Bend your knees forward and lean back.","Lower as far as you can control.","Press back up."],"img":"opengym/4723.webp","gif":null,"ext":1},{"id":"4724","n":"chin up (in squatting position)","bp":"back","eq":"body weight","tg":"lats","mg":"biceps","sm":["biceps","upper back","quadriceps","forearms"],"st":["Set a low bar and grip it with palms facing you.","Sit into a deep squat beneath it.","Pull your chest to the bar.","Lower back down.","Use your legs as little as possible."],"img":"opengym/4724.webp","gif":null,"ext":1},{"id":"4725","n":"chin up (isometric and negative)","bp":"back","eq":"body weight","tg":"lats","mg":"biceps","sm":["biceps","upper back","forearms","core"],"st":["Jump or step up so your chin is above the bar.","Hold the top position for a few seconds.","Lower yourself slowly over several seconds.","Reset on the floor.","Repeat for the reps."],"img":"opengym/4725.webp","gif":null,"ext":1},{"id":"4726","n":"commando pull up","bp":"back","eq":"body weight","tg":"lats","mg":"biceps","sm":["biceps","upper back","forearms","core"],"st":["Grab the bar with one hand in front of the other, palms facing each other, and hang with arms straight.","Brace your core and pull your body up, moving your head to one side of the bar.","Get your chin or shoulder level with the bar.","Lower under control to a full hang.","Switch which side your head passes on each rep, or each set."],"img":"opengym/4726.webp","gif":null,"ext":1},{"id":"4727","n":"crunch (arms on chest)","bp":"waist","eq":"body weight","tg":"abs","mg":"obliques","sm":["obliques","hip flexors"],"st":["Lie on your back with your knees bent and feet flat.","Cross your arms over your chest.","Curl your head and shoulders off the floor.","Squeeze your abs at the top.","Lower slowly and repeat."],"img":"opengym/4727.webp","gif":null,"ext":1},{"id":"4728","n":"dumbbell bench dip","bp":"upper arms","eq":"dumbbell","tg":"triceps","mg":"chest","sm":["chest","shoulders","forearms"],"st":["Sit on a bench edge, hands beside your hips, and slide your hips off the front.","Rest a dumbbell on your thighs, holding it steady with your hips and legs.","Bend your elbows to lower until they reach about 90 degrees.","Keep your back close to the bench and shoulders down.","Press through your palms to straighten your arms."],"img":"opengym/4728.webp","gif":null,"ext":1},{"id":"4729","n":"dumbbell bench dip with legs elevated","bp":"upper arms","eq":"dumbbell","tg":"triceps","mg":"chest","sm":["chest","shoulders","core"],"st":["Place two benches facing each other, hands on one and heels on the other.","Set a dumbbell on your lap and keep your legs straight.","Lower your hips by bending your elbows to about 90 degrees.","Keep your chest up and your elbows pointing back.","Press up until your arms are straight again."],"img":"opengym/4729.webp","gif":null,"ext":1},{"id":"4730","n":"dumbbell bent over single arm row v. 2","bp":"back","eq":"dumbbell","tg":"upper back","mg":"lats","sm":["lats","rhomboids","biceps","rear deltoids","forearms"],"st":["Hold a dumbbell in one hand and hinge forward with a flat back, knees slightly bent.","Let the weight hang with your arm straight below your shoulder.","Pull the dumbbell toward your hip, leading with your elbow.","Pause briefly, then lower slowly.","Finish all reps, then switch arms."],"img":"opengym/4730.webp","gif":null,"ext":1},{"id":"4731","n":"dumbbell bridge bench press","bp":"chest","eq":"dumbbell","tg":"pectorals","mg":"triceps","sm":["triceps","glutes","shoulders","upper chest"],"st":["Lie on the floor or a bench holding a dumbbell in each hand.","Plant your feet and drive your hips up into a bridge.","Press the dumbbells up until your arms are straight.","Lower them to chest level under control.","Keep your hips high for the whole set."],"img":"opengym/4731.webp","gif":null,"ext":1},{"id":"4732","n":"dumbbell cossack squat v. 2","bp":"upper legs","eq":"dumbbell","tg":"quads","mg":"glutes","sm":["glutes","adductors","hamstrings","inner thighs"],"st":["Stand with feet wide and hold a dumbbell at your chest.","Shift your weight to one side and squat down on that leg.","Keep the other leg straight with the toes up.","Drive through the bent leg to stand and shift to the other side.","Keep your chest tall and your heel down."],"img":"opengym/4732.webp","gif":null,"ext":1},{"id":"4733","n":"dumbbell decline lying leg curl","bp":"upper legs","eq":"dumbbell","tg":"hamstrings","mg":"calves","sm":["calves","glutes"],"st":["Lie face down on a decline bench with the dumbbell held between your feet.","Let your legs hang straight with your hips pressed to the bench.","Curl your heels up toward your glutes.","Squeeze at the top without lifting your hips.","Lower slowly to full extension."],"img":"opengym/4733.webp","gif":null,"ext":1},{"id":"4734","n":"dumbbell decline overhead sit up","bp":"waist","eq":"dumbbell","tg":"abs","mg":"hip flexors","sm":["hip flexors","lower abs","shoulders"],"st":["Hook your feet on a decline bench and lie back holding a dumbbell above your chest.","Extend your arms overhead behind you.","Curl your torso up, keeping the dumbbell over your head.","Reach the top with your arms above your knees.","Lower back slowly with control."],"img":"opengym/4734.webp","gif":null,"ext":1},{"id":"4735","n":"dumbbell decline sit up","bp":"waist","eq":"dumbbell","tg":"abs","mg":"hip flexors","sm":["hip flexors","lower abs","obliques"],"st":["Secure your feet on a decline bench and hold a dumbbell against your chest.","Lie back until your torso is just above the bench.","Curl up until your torso is upright.","Keep your neck relaxed and avoid pulling on your head.","Lower slowly to the start."],"img":"opengym/4735.webp","gif":null,"ext":1},{"id":"4736","n":"dumbbell deep push up and renegade row","bp":"full body","eq":"dumbbell","tg":"pectorals","mg":"triceps","sm":["triceps","lats","core","shoulders","upper back"],"st":["Start in a plank with hands on two dumbbells, feet wide.","Lower your chest between the dumbbells in a deep push-up.","Press back up to a plank.","Row one dumbbell to your ribs while bracing to stay level.","Lower it, row the other side, and repeat."],"img":"opengym/4736.webp","gif":null,"ext":1},{"id":"4737","n":"dumbbell floor wiper","bp":"waist","eq":"dumbbell","tg":"obliques","mg":"abdominals","sm":["abdominals","shoulders","hip flexors"],"st":["Lie on your back holding a dumbbell above your chest with straight arms.","Lift your legs straight up over your hips.","Lower both legs to one side without touching the floor.","Bring them back to the middle.","Repeat to the other side, keeping your shoulders flat."],"img":"opengym/4737.webp","gif":null,"ext":1},{"id":"4738","n":"dumbbell goblet squat and biceps curl","bp":"full body","eq":"dumbbell","tg":"quads","mg":"glutes","sm":["glutes","biceps","hamstrings","core"],"st":["Stand with feet shoulder-width apart holding a dumbbell by one end at your chest.","Squat down with your chest up and elbows inside your knees.","At the bottom, lower the dumbbell and curl it back up.","Drive through your heels to stand.","Repeat the full sequence for each rep."],"img":"opengym/4738.webp","gif":null,"ext":1},{"id":"4739","n":"dumbbell hang power clean","bp":"upper legs","eq":"dumbbell","tg":"glutes","mg":"hamstrings","sm":["hamstrings","trapezius","quadriceps","shoulders","core"],"st":["Stand holding dumbbells and hinge until they hang just above your knees.","Keep your back flat and arms straight.","Drive your hips forward and shrug as you pull the weights up.","Drop under them and catch at your shoulders in a quarter squat.","Stand tall, then lower to the hang and repeat."],"img":"opengym/4739.webp","gif":null,"ext":1},{"id":"4740","n":"dumbbell hang power clean and jerk","bp":"full body","eq":"dumbbell","tg":"glutes","mg":"shoulders","sm":["shoulders","triceps","quadriceps","hamstrings","trapezius"],"st":["Hold dumbbells hanging just above your knees with a flat back.","Explode up and pull the weights to your shoulders, catching in a quarter squat.","Stand tall, then dip slightly with your knees.","Drive up and press the dumbbells overhead.","Lower to your shoulders, then to the hang, and reset."],"img":"opengym/4740.webp","gif":null,"ext":1},{"id":"4741","n":"dumbbell head supported row","bp":"back","eq":"dumbbell","tg":"upper back","mg":"lats","sm":["lats","rhomboids","rear deltoids","biceps"],"st":["Set a bench at a slight incline and lie chest down on it with a dumbbell in each hand.","Rest your forehead on the top and let your arms hang.","Row both dumbbells toward your ribs.","Squeeze your shoulder blades together at the top.","Lower slowly to straight arms."],"img":"opengym/4741.webp","gif":null,"ext":1},{"id":"4742","n":"dumbbell hip thrust","bp":"upper legs","eq":"dumbbell","tg":"glutes","mg":"hamstrings","sm":["hamstrings","quadriceps","core"],"st":["Sit on the floor with your upper back against a bench and a dumbbell across your hips.","Plant your feet hip-width apart, knees bent.","Drive through your heels and lift your hips until your torso is level.","Squeeze your glutes at the top with your chin tucked.","Lower your hips under control."],"img":"opengym/4742.webp","gif":null,"ext":1},{"id":"4743","n":"dumbbell incline biceps curl v. 3","bp":"upper arms","eq":"dumbbell","tg":"biceps","mg":"brachialis","sm":["brachialis","forearms","shoulders"],"st":["Sit back on an incline bench with a dumbbell in each hand, arms hanging straight.","Keep your elbows back and your shoulders against the bench.","Curl both dumbbells toward your shoulders.","Squeeze your biceps at the top.","Lower slowly until your arms are fully extended and repeat."],"img":"opengym/4743.webp","gif":null,"ext":1},{"id":"4744","n":"dumbbell incline head supported row","bp":"back","eq":"dumbbell","tg":"upper back","mg":"lats","sm":["lats","rhomboids","rear deltoids","biceps"],"st":["Lie chest down on an incline bench with a dumbbell in each hand.","Rest your head on the top of the bench and let your arms hang.","Pull your elbows back and the dumbbells toward your ribs.","Pause and squeeze your shoulder blades.","Lower slowly to full arm extension."],"img":"opengym/4744.webp","gif":null,"ext":1},{"id":"4745","n":"dumbbell kneeling arnold press","bp":"shoulders","eq":"dumbbell","tg":"delts","mg":"triceps","sm":["triceps","upper chest","core","glutes"],"st":["Kneel tall holding dumbbells in front of your shoulders, palms facing you.","Brace your core and squeeze your glutes.","Press up while rotating your palms to face forward.","Finish with your arms straight overhead.","Reverse the rotation as you lower back to the start."],"img":"opengym/4745.webp","gif":null,"ext":1},{"id":"4746","n":"dumbbell low windmill","bp":"waist","eq":"dumbbell","tg":"obliques","mg":"abdominals","sm":["abdominals","hamstrings","shoulders","lower back"],"st":["Stand with feet wide and a dumbbell in one hand.","Turn your back foot out and push your hips toward the dumbbell side.","Slide the dumbbell down your leg as you bend sideways and hinge.","Keep both legs mostly straight.","Return to standing and finish the set, then switch sides."],"img":"opengym/4746.webp","gif":null,"ext":1},{"id":"4747","n":"dumbbell lying woodchop","bp":"waist","eq":"dumbbell","tg":"obliques","mg":"abdominals","sm":["abdominals","shoulders","hip flexors"],"st":["Lie on your back with knees bent, holding a dumbbell with both hands beside one hip.","Keep your arms mostly straight.","Sweep the dumbbell diagonally up and across to above the opposite shoulder.","Rotate your torso with the movement.","Return under control and switch sides after the set."],"img":"opengym/4747.webp","gif":null,"ext":1},{"id":"4748","n":"dumbbell overhead sit up","bp":"waist","eq":"dumbbell","tg":"abs","mg":"hip flexors","sm":["hip flexors","lower abs","shoulders"],"st":["Lie on your back with knees bent and feet flat or anchored.","Hold a dumbbell with both hands, arms extended overhead.","Curl up to a seated position, keeping the dumbbell above you.","Keep your arms by your ears.","Lower back down slowly."],"img":"opengym/4748.webp","gif":null,"ext":1},{"id":"4749","n":"dumbbell rdl and bent over row","bp":"back","eq":"dumbbell","tg":"upper back","mg":"lats","sm":["lats","hamstrings","glutes","lower back","biceps"],"st":["Stand holding dumbbells in front of your thighs, knees soft.","Hinge at the hips, pushing them back, until the dumbbells are below your knees.","Keep your back flat and row both dumbbells to your ribs.","Lower them, then drive your hips forward to stand.","Repeat the full sequence for each rep."],"img":"opengym/4749.webp","gif":null,"ext":1},{"id":"4750","n":"dumbbell russian twist with legs floor off","bp":"waist","eq":"dumbbell","tg":"obliques","mg":"hip flexors","sm":["hip flexors","lower abs"],"st":["Sit down and lean back slightly with a dumbbell held in both hands.","Lift your feet off the floor with knees bent.","Rotate your torso to bring the dumbbell beside one hip.","Twist to the other side in a controlled way.","Keep your chest up and your back long."],"img":"opengym/4750.webp","gif":null,"ext":1},{"id":"4751","n":"dumbbell glute bridge v. 2","bp":"upper legs","eq":"dumbbell","tg":"glutes","mg":"hamstrings","sm":["hamstrings","core","lower back"],"st":["Lie on your back with your knees bent and feet flat.","Rest a dumbbell on your hips and hold it in place.","Drive through your heels to lift your hips.","Squeeze your glutes at the top.","Lower slowly and repeat."],"img":"opengym/4751.webp","gif":null,"ext":1},{"id":"4752","n":"dumbbell side bench squat","bp":"upper legs","eq":"dumbbell","tg":"quads","mg":"glutes","sm":["glutes","adductors","hamstrings","inner thighs"],"st":["Stand sideways to a bench holding a dumbbell at your chest, feet wide.","Shift your weight to the leg nearest the bench.","Sit back and down until you lightly touch the bench.","Keep the other leg straight.","Drive up through your heel and repeat, then switch sides."],"img":"opengym/4752.webp","gif":null,"ext":1},{"id":"4753","n":"dumbbell side lunge with shoulder press","bp":"full body","eq":"dumbbell","tg":"glutes","mg":"quadriceps","sm":["quadriceps","adductors","shoulders","triceps","core"],"st":["Stand holding dumbbells at your shoulders.","Step out wide to one side and sit your hips back into a side lunge.","Keep the other leg straight and your chest up.","Push back to the middle and press the dumbbells overhead.","Lower to your shoulders and lunge to the other side."],"img":"opengym/4753.webp","gif":null,"ext":1},{"id":"4754","n":"dumbbell side squat","bp":"upper legs","eq":"dumbbell","tg":"quads","mg":"glutes","sm":["glutes","adductors","hamstrings","inner thighs"],"st":["Stand with feet wide holding a dumbbell at your chest.","Shift to one side and bend that knee, sitting your hips back.","Keep the other leg straight and both feet flat.","Lower until your thigh is parallel to the floor.","Push back to the middle and alternate sides."],"img":"opengym/4754.webp","gif":null,"ext":1},{"id":"4755","n":"dumbbell single leg hip thrust","bp":"upper legs","eq":"dumbbell","tg":"glutes","mg":"hamstrings","sm":["hamstrings","core","quadriceps"],"st":["Sit with your upper back on a bench and a dumbbell across your hips.","Plant one foot and lift the other leg off the floor.","Drive through the planted heel to raise your hips until level.","Squeeze your glute at the top.","Lower slowly, finish the reps, then switch legs."],"img":"opengym/4755.webp","gif":null,"ext":1},{"id":"4756","n":"dumbbell sit up","bp":"waist","eq":"dumbbell","tg":"abs","mg":"hip flexors","sm":["hip flexors","lower abs","obliques"],"st":["Lie on your back with knees bent and feet flat or anchored.","Hold a dumbbell against your chest with both hands.","Curl your torso up until you are sitting.","Keep your neck neutral.","Lower back down slowly."],"img":"opengym/4756.webp","gif":null,"ext":1},{"id":"4757","n":"dumbbell staggered stance romanian deadlift","bp":"upper legs","eq":"dumbbell","tg":"hamstrings","mg":"glutes","sm":["glutes","lower back","forearms","core"],"st":["Stand with one foot a half step ahead and hold dumbbells in front of you.","Keep most of your weight on the front leg.","Hinge at the hips, sliding the dumbbells down your legs.","Stop when you feel a stretch in the hamstring, back flat.","Drive your hips forward to stand, then switch feet."],"img":"opengym/4757.webp","gif":null,"ext":1},{"id":"4758","n":"dumbbell step back lunge and row","bp":"full body","eq":"dumbbell","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","lats","upper back","biceps"],"st":["Stand holding dumbbells at your sides.","Step one leg back and lower into a lunge.","Hinge your torso slightly forward with a flat back.","Row both dumbbells to your ribs.","Lower them, push through the front foot to stand, and switch legs."],"img":"opengym/4758.webp","gif":null,"ext":1},{"id":"4760","n":"elevated standing calf raise","bp":"lower legs","eq":"body weight","tg":"calves","mg":"soleus","sm":["soleus","ankles","feet"],"st":["Stand with the balls of your feet on a step or block, heels hanging off.","Hold something for balance.","Lower your heels below the step to stretch your calves.","Rise up as high as you can on your toes.","Pause at the top, then lower slowly."],"img":"opengym/4760.webp","gif":null,"ext":1},{"id":"4761","n":"elevated standing single leg calf raise","bp":"lower legs","eq":"body weight","tg":"calves","mg":"soleus","sm":["soleus","ankles","feet"],"st":["Stand on one foot with the ball of that foot on a step, other foot lifted.","Hold a wall or rail for balance.","Lower your heel below the step.","Press up onto your toes as high as you can.","Lower slowly, finish the reps, then switch legs."],"img":"opengym/4761.webp","gif":null,"ext":1},{"id":"4762","n":"glute ham developer hip extension","bp":"upper legs","eq":"leverage machine","tg":"glutes","mg":"hamstrings","sm":["hamstrings","lower back"],"st":["Set up on the GHD with your feet planted and hips just past the pad.","Cross your arms over your chest.","Lower your torso by hinging at the hips with a flat back.","Squeeze your glutes to raise back to a straight line.","Do not arch past neutral at the top."],"img":"opengym/4762.webp","gif":null,"ext":1},{"id":"4763","n":"glute ham developer sit up and russian twist","bp":"waist","eq":"leverage machine","tg":"obliques","mg":"hip flexors","sm":["hip flexors","lower abs"],"st":["Lock your feet in the GHD and lie back with arms crossed or hands clasped.","Sit up in a controlled way.","At the top, rotate your torso to one side.","Return to the middle and lower back down.","Alternate the twist side each rep."],"img":"opengym/4763.webp","gif":null,"ext":1},{"id":"4764","n":"glute ham hyperextension twist","bp":"waist","eq":"leverage machine","tg":"spine","mg":"glutes","sm":["glutes","hamstrings","obliques"],"st":["Position yourself on the bench with hips on the pad and feet locked in.","Cross your arms on your chest.","Lower your torso with a straight back.","Raise up to a straight line and rotate your torso to one side.","Untwist, lower, and alternate sides."],"img":"opengym/4764.webp","gif":null,"ext":1},{"id":"4765","n":"glute ham single leg hyperextension","bp":"upper legs","eq":"leverage machine","tg":"glutes","mg":"hamstrings","sm":["hamstrings","lower back","core"],"st":["Set up on the bench with one foot planted and the other lifted behind you.","Cross your arms over your chest.","Lower your torso with a flat back.","Raise to a straight line, squeezing your glute.","Finish the reps, then switch legs."],"img":"opengym/4765.webp","gif":null,"ext":1},{"id":"4766","n":"hanging flutter kick","bp":"waist","eq":"body weight","tg":"abs","mg":"hip flexors","sm":["hip flexors","lower abs","forearms","grip muscles"],"st":["Hang from a pull-up bar with arms straight.","Tighten your core and lift your legs slightly in front of you.","Kick your legs up and down in alternating small movements.","Keep your swing minimal.","Continue for the set time or reps."],"img":"opengym/4766.webp","gif":null,"ext":1},{"id":"4767","n":"hanging knee circle raise","bp":"waist","eq":"body weight","tg":"abs","mg":"hip flexors","sm":["hip flexors","obliques","lower abs","grip muscles"],"st":["Hang from a bar with arms straight and legs together.","Raise your knees toward your chest.","Move them in a circle to one side and back down.","Keep your body from swinging.","Alternate the circle direction each rep."],"img":"opengym/4767.webp","gif":null,"ext":1},{"id":"4768","n":"incline alternate flutter kicks","bp":"waist","eq":"body weight","tg":"abs","mg":"hip flexors","sm":["hip flexors","lower abs"],"st":["Lie back on an incline bench and hold the edges behind your head.","Lift your legs a few inches off the floor.","Kick your legs up and down alternately in small motions.","Keep your lower back pressed down.","Continue for the set time or reps."],"img":"opengym/4768.webp","gif":null,"ext":1},{"id":"4769","n":"inverted row slide","bp":"back","eq":"body weight","tg":"upper back","mg":"lats","sm":["lats","biceps","rhomboids","core"],"st":["Lie under a bar or rings and grab with an overhand grip.","Keep your body straight with heels on a slick surface.","Pull your chest toward the bar while your feet slide forward.","Squeeze your shoulder blades together.","Lower slowly with control."],"img":"opengym/4769.webp","gif":null,"ext":1},{"id":"4770","n":"inverted wide row","bp":"back","eq":"body weight","tg":"upper back","mg":"lats","sm":["lats","rhomboids","rear deltoids","biceps"],"st":["Lie under a bar and grab it with a wide overhand grip.","Keep your body in a straight line, heels on the floor.","Pull your chest up toward the bar.","Squeeze your shoulder blades together.","Lower under control to straight arms."],"img":"opengym/4770.webp","gif":null,"ext":1},{"id":"4771","n":"jump split with hands on hip","bp":"upper legs","eq":"body weight","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","calves","core"],"st":["Stand tall with hands on your hips.","Step into a lunge position.","Jump and switch legs in the air.","Land softly in a lunge on the other leg.","Keep your chest up and repeat."],"img":"opengym/4771.webp","gif":null,"ext":1},{"id":"4772","n":"kneeling straight leg kickback v. 2","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"hamstrings","sm":["hamstrings","core"],"st":["Get on all fours with hands under shoulders and knees under hips.","Extend one leg straight behind you with the toes on the floor.","Squeeze the glute and lift the straight leg to hip height.","Pause briefly, then lower the leg without letting the back arch.","Keep your hips level and your core tight.","Finish your reps, then switch legs."],"img":"opengym/4772.webp","gif":null,"ext":1},{"id":"4773","n":"narrow seated chin up","bp":"back","eq":"body weight","tg":"lats","mg":"biceps","sm":["biceps","upper back","forearms"],"st":["Sit under a low bar with your hands close together, palms facing you.","Extend your legs in front with heels on the floor.","Pull your chest up toward the bar.","Squeeze your back and arms at the top.","Lower slowly until your arms are straight."],"img":"opengym/4773.webp","gif":null,"ext":1},{"id":"4775","n":"push up and triceps dip on parallel bars","bp":"chest","eq":"body weight","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders","core"],"st":["Place hands on parallel bars and support yourself in a plank.","Lower into a push-up with your elbows out.","Press back up to a plank.","Shift your hands to the edge of the bars, body upright.","Dip down and press up, then repeat the cycle."],"img":"opengym/4775.webp","gif":null,"ext":1},{"id":"4776","n":"resistance band kneeling woodchop","bp":"waist","eq":"resistance band","tg":"obliques","mg":"abdominals","sm":["abdominals","shoulders","glutes"],"st":["Anchor a band high and kneel sideways to it.","Hold the handle with both hands.","Pull the band diagonally down across your body.","Rotate your torso as you chop.","Return slowly, then switch sides."],"img":"opengym/4776.webp","gif":null,"ext":1},{"id":"4777","n":"reverse back extension on floor","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"hamstrings","sm":["hamstrings","lower back"],"st":["Lie face down with arms extended in front or under your head.","Keep your legs straight.","Raise both legs off the floor by squeezing your glutes.","Pause at the top.","Lower slowly and repeat."],"img":"opengym/4777.webp","gif":null,"ext":1},{"id":"4778","n":"reverse crunch v. 3","bp":"waist","eq":"body weight","tg":"abs","mg":"lower abs","sm":["lower abs","hip flexors"],"st":["Lie on your back with your arms by your sides.","Lift your knees to a tabletop position.","Curl your hips off the floor, bringing your knees toward your chest.","Pause at the top.","Lower slowly without swinging."],"img":"opengym/4778.webp","gif":null,"ext":1},{"id":"4779","n":"reverse flutter kick on floor (hand under head)","bp":"waist","eq":"body weight","tg":"abs","mg":"hip flexors","sm":["hip flexors","lower abs"],"st":["Lie on your back and place your hands under your head.","Lift your legs a few inches off the floor.","Kick up and down alternately in small, quick motions.","Keep your lower back pressed down.","Continue for the set time."],"img":"opengym/4779.webp","gif":null,"ext":1},{"id":"4780","n":"seated chin up (low bar position)","bp":"back","eq":"body weight","tg":"lats","mg":"biceps","sm":["biceps","upper back","forearms"],"st":["Set a bar at a low height and sit under it.","Grab it with an underhand grip, arms extended.","Extend your legs in front with heels on the floor.","Pull your chest toward the bar.","Lower slowly to straight arms."],"img":"opengym/4780.webp","gif":null,"ext":1},{"id":"4781","n":"seated chin up","bp":"back","eq":"body weight","tg":"lats","mg":"biceps","sm":["biceps","upper back","forearms"],"st":["Sit under a bar with an underhand grip, shoulder-width apart.","Extend your legs in front of you.","Pull your chin toward the bar.","Squeeze your back and biceps at the top.","Lower slowly until your arms are straight."],"img":"opengym/4781.webp","gif":null,"ext":1},{"id":"4782","n":"seated commando pull up","bp":"back","eq":"body weight","tg":"lats","mg":"biceps","sm":["biceps","upper back","forearms","core"],"st":["Sit under a bar and grab it with one hand in front of the other.","Extend your legs in front of you.","Pull your body up and bring your head to one side.","Lower under control.","Alternate sides each rep or each set."],"img":"opengym/4782.webp","gif":null,"ext":1},{"id":"4783","n":"seated pull up (legs elevated)","bp":"back","eq":"body weight","tg":"lats","mg":"biceps","sm":["biceps","upper back","core","forearms"],"st":["Place your feet on a bench and sit under a bar.","Grab it with an overhand grip, arms extended.","Pull your chest up toward the bar.","Squeeze your shoulder blades at the top.","Lower slowly to straight arms."],"img":"opengym/4783.webp","gif":null,"ext":1},{"id":"4784","n":"seated pull up (low bar position)","bp":"back","eq":"body weight","tg":"lats","mg":"biceps","sm":["biceps","upper back","forearms"],"st":["Set a bar low and sit beneath it.","Grab it with an overhand grip, a little wider than your shoulders.","Extend your legs in front with heels on the floor.","Pull your chest to the bar.","Lower under control."],"img":"opengym/4784.webp","gif":null,"ext":1},{"id":"4785","n":"seated pull up","bp":"back","eq":"body weight","tg":"lats","mg":"biceps","sm":["biceps","upper back","forearms"],"st":["Sit under a bar and grab it with an overhand grip.","Extend your legs in front of you.","Pull your chest up toward the bar.","Squeeze your back at the top.","Lower slowly until your arms are straight."],"img":"opengym/4785.webp","gif":null,"ext":1},{"id":"4786","n":"side bench squat","bp":"upper legs","eq":"body weight","tg":"quads","mg":"glutes","sm":["glutes","adductors","hamstrings","inner thighs"],"st":["Stand sideways to a bench with feet wide.","Shift your weight to the leg nearest the bench.","Sit back and down until you lightly touch the bench.","Keep the other leg straight.","Drive up through your heel and repeat, then switch sides."],"img":"opengym/4786.webp","gif":null,"ext":1},{"id":"4787","n":"side crunch with hands on chest","bp":"waist","eq":"body weight","tg":"obliques","mg":"core","sm":["core"],"st":["Lie on your side with knees slightly bent and arms crossed over your chest.","Brace your core and lift your shoulders and legs toward each other.","Crunch sideways, squeezing the side of your waist.","Pause at the top, then lower slowly.","Keep the movement small and controlled, without pulling on your neck.","Complete your reps, then switch sides."],"img":"opengym/4787.webp","gif":null,"ext":1},{"id":"4788","n":"side split squat","bp":"upper legs","eq":"body weight","tg":"quads","mg":"glutes","sm":["glutes","adductors","hamstrings","inner thighs"],"st":["Stand with feet wide and toes slightly out.","Shift your weight to one side and bend that knee.","Keep the other leg straight with the foot flat or toes up.","Lower until your thigh is parallel.","Push back to the middle and alternate sides."],"img":"opengym/4788.webp","gif":null,"ext":1},{"id":"4789","n":"side squat","bp":"upper legs","eq":"body weight","tg":"quads","mg":"glutes","sm":["glutes","adductors","hamstrings","inner thighs"],"st":["Stand with feet wide and your arms in front for balance.","Shift your weight to one leg and sit back and down.","Keep the other leg straight.","Keep your chest up and your heel down.","Push back to the middle and switch sides."],"img":"opengym/4789.webp","gif":null,"ext":1},{"id":"4790","n":"single leg bench squat","bp":"upper legs","eq":"body weight","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","core"],"st":["Stand in front of a bench with your back to it and lift one foot off the floor.","Reach your arms forward for balance.","Sit your hips back and lower until you lightly touch the bench.","Keep the working knee in line with your toes.","Drive through the heel to stand back up.","Finish your reps, then switch legs."],"img":"opengym/4790.webp","gif":null,"ext":1},{"id":"4791","n":"single leg glute bridge (arms on chest)","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"hamstrings","sm":["hamstrings","core"],"st":["Lie on your back with one knee bent, foot flat, and the other leg extended or raised.","Cross your arms over your chest.","Push through the planted heel and lift your hips.","Squeeze the glute at the top so your body forms a straight line.","Lower your hips slowly without touching the floor fully.","Complete your reps, then switch legs."],"img":"opengym/4791.webp","gif":null,"ext":1},{"id":"4792","n":"single leg hip thrust v. 2","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"hamstrings","sm":["hamstrings","core"],"st":["Rest your upper back on a bench with one foot flat on the floor.","Lift the other leg off the floor, knee bent or straight.","Drive through the planted heel and raise your hips.","Squeeze your glute at the top until your torso is level.","Lower your hips under control.","Finish your reps, then switch legs."],"img":"opengym/4792.webp","gif":null,"ext":1},{"id":"4793","n":"single leg hip thrust jump","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"hamstrings","sm":["hamstrings","quadriceps","calves","core"],"st":["Sit with your upper back on a bench and one foot planted.","Lift the other leg.","Drive up through your heel and thrust your hips explosively.","Let your hips leave the floor briefly.","Land softly, finish the reps, then switch legs."],"img":"opengym/4793.webp","gif":null,"ext":1},{"id":"4794","n":"single leg jumping glute bridge","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"hamstrings","sm":["hamstrings","quadriceps","calves","core"],"st":["Lie on your back with one foot planted and the other leg lifted.","Drive through the planted heel and thrust your hips up.","Push hard enough that your hips leave the floor.","Land softly back in the bridge.","Finish the reps, then switch legs."],"img":"opengym/4794.webp","gif":null,"ext":1},{"id":"4795","n":"single leg step up on bench","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","calves"],"st":["Stand facing a sturdy bench and place one foot fully on top.","Lean slightly forward and press through that heel.","Step up until the leg is straight and you stand tall.","Lower yourself slowly back down with control.","Avoid pushing off the trailing foot.","Complete your reps, then switch legs."],"img":"opengym/4795.webp","gif":null,"ext":1},{"id":"4796","n":"standing single leg calf raise balance","bp":"lower legs","eq":"body weight","tg":"calves","mg":"soleus","sm":["soleus","ankles","feet"],"st":["Stand tall on one foot with the other lifted.","Keep your hands on your hips or lightly on a wall.","Rise up onto your toes as high as you can.","Hold briefly at the top, steady.","Lower slowly, finish the reps, then switch legs."],"img":"opengym/4796.webp","gif":null,"ext":1},{"id":"4797","n":"supported squat","bp":"upper legs","eq":"body weight","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","core"],"st":["Stand holding a stable support at about chest height, feet shoulder width apart.","Brace your core and keep your chest up.","Sit your hips back and bend your knees to lower down.","Go as deep as you can with your heels down.","Push through your feet to stand back up.","Use the support for balance, not to pull yourself up."],"img":"opengym/4797.webp","gif":null,"ext":1},{"id":"4798","n":"suspender alternate superman","bp":"waist","eq":"suspension trainer","tg":"spine","mg":"glutes","sm":["glutes","rear deltoids","core"],"st":["Place your feet in the suspension straps and get into a plank face down.","Brace your core and keep your hips level.","Lift one arm forward while keeping your body steady.","Return it, then lift the other arm.","Move slowly and avoid sagging your lower back.","Alternate sides for the full set."],"img":"opengym/4798.webp","gif":null,"ext":1},{"id":"4799","n":"suspender rollout v. 2","bp":"waist","eq":"suspension trainer","tg":"abs","mg":"core","sm":["core","shoulders","lats"],"st":["Kneel facing the anchor and hold the suspension handles under your shoulders.","Brace your core and tuck your pelvis slightly.","Roll your arms forward as your body leans out in a straight line.","Go only as far as you can keep your back flat.","Pull back to the start using your abs.","Keep your ribs down throughout."],"img":"opengym/4799.webp","gif":null,"ext":1},{"id":"4800","n":"table top bridge","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"hamstrings","sm":["hamstrings","core","triceps","shoulders"],"st":["Sit on the floor with knees bent and feet flat, hands behind you with fingers pointing toward your feet.","Press through your hands and heels to lift your hips.","Raise until your torso and thighs are level like a tabletop.","Squeeze your glutes and keep your head in line with your spine.","Hold briefly, then lower your hips back to the floor under control."],"img":"opengym/4800.webp","gif":null,"ext":1},{"id":"4801","n":"table top bridge rotation","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"core","sm":["core","obliques","shoulders","hamstrings"],"st":["Set up in a table top bridge with hips lifted and hands under your shoulders.","Shift your weight onto one hand and both feet.","Lift the free arm and reach it up and over your body as you rotate your chest.","Keep your hips high and level throughout.","Return the arm to the floor and repeat, then switch sides."],"img":"opengym/4801.webp","gif":null,"ext":1},{"id":"4802","n":"toe walk","bp":"lower legs","eq":"body weight","tg":"calves","mg":"shins","sm":["shins","feet","ankles"],"st":["Stand tall with feet hip-width apart and rise onto the balls of your feet.","Keep your heels lifted as high as you comfortably can.","Walk forward with small, controlled steps.","Keep your core tight and your gaze forward.","Walk for 20-30 steps, rest, and repeat."],"img":"opengym/4802.webp","gif":null,"ext":1},{"id":"4803","n":"triceps press (high bar position)","bp":"upper arms","eq":"barbell","tg":"triceps","mg":"shoulders","sm":["shoulders","chest","core"],"st":["Set up with a barbell held at arm's length above your head, hands about shoulder-width apart.","Keep your upper arms still and pointing up.","Bend your elbows to lower the bar toward your forehead or just behind your head.","Keep your elbows from flaring out.","Extend your arms to press the bar back to the start."],"img":"opengym/4803.webp","gif":null,"ext":1},{"id":"4804","n":"triceps press (low bar position)","bp":"upper arms","eq":"barbell","tg":"triceps","mg":"shoulders","sm":["shoulders","chest","core"],"st":["Hold a barbell at arm's length over your chest, hands about shoulder-width apart.","Keep your upper arms vertical and your elbows tucked.","Bend only at the elbows to lower the bar toward your forehead.","Pause briefly when the bar is low.","Extend your arms to return the bar to the start."],"img":"opengym/4804.webp","gif":null,"ext":1},{"id":"4805","n":"wide air squat","bp":"upper legs","eq":"body weight","tg":"quads","mg":"glutes","sm":["glutes","adductors","hamstrings","core"],"st":["Stand with feet well wider than your shoulders and toes angled out.","Raise your arms in front for balance.","Sit your hips down and back, pushing your knees out over your toes.","Lower until your thighs are about parallel to the floor.","Drive through your heels to stand back up."],"img":"opengym/4805.webp","gif":null,"ext":1},{"id":"4806","n":"wide seated pull up","bp":"back","eq":"body weight","tg":"lats","mg":"biceps","sm":["biceps","rhomboids","forearms","grip muscles"],"st":["Sit under a pull-up bar and take a wide overhand grip.","Hang with arms extended and your chest lifted.","Pull your elbows down and toward your ribs to bring your chest toward the bar.","Squeeze your shoulder blades together at the top.","Lower yourself slowly to full arm extension."],"img":"opengym/4806.webp","gif":null,"ext":1},{"id":"4807","n":"wide to narrow push up","bp":"chest","eq":"body weight","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders","core"],"st":["Start in a high plank with your hands wider than your shoulders.","Lower your chest to the floor with your body in a straight line.","Push back up to the top.","Walk your hands in to a narrow, close position.","Repeat a push-up, then step your hands back out wide."],"img":"opengym/4807.webp","gif":null,"ext":1},{"id":"4808","n":"lying leg raise v. 2","bp":"waist","eq":"body weight","tg":"abs","mg":"hip flexors","sm":["hip flexors","lower abs"],"st":["Lie on your back with legs straight and arms by your sides.","Press your lower back gently into the floor.","Lift both legs together until they point to the ceiling.","Lower them slowly, stopping before your back arches.","Keep your legs as straight as you comfortably can.","Breathe steadily through each rep."],"img":"opengym/4808.webp","gif":null,"ext":1},{"id":"4810","n":"standing side bend v. 2","bp":"waist","eq":"body weight","tg":"obliques","mg":"core","sm":["core"],"st":["Stand tall with feet hip width apart and one arm overhead.","Brace your core lightly.","Bend sideways at the waist, reaching over with the raised arm.","Pause when you feel the side muscles work.","Return to upright with control.","Complete your reps, then switch sides."],"img":"opengym/4810.webp","gif":null,"ext":1},{"id":"4811","n":"side plank v. 3","bp":"waist","eq":"body weight","tg":"obliques","mg":"abdominals","sm":["abdominals","glutes","shoulders"],"st":["Lie on your side and prop yourself on your forearm under your shoulder.","Stack or stagger your feet.","Lift your hips so your body forms a straight line.","Keep your neck neutral and your core tight.","Hold for 20-40 seconds.","Lower down and repeat on the other side."],"img":"opengym/4811.webp","gif":null,"ext":1},{"id":"4812","n":"side crunch v. 3","bp":"waist","eq":"body weight","tg":"obliques","mg":"core","sm":["core"],"st":["Lie on your side with knees bent and one hand behind your head.","Rest the other hand on the floor for balance.","Lift your shoulders and knees toward each other.","Squeeze the side of your waist at the top.","Lower slowly without relaxing fully.","Complete your reps, then switch sides."],"img":"opengym/4812.webp","gif":null,"ext":1},{"id":"4816","n":"dumbbell goblet 2 sec hold squat","bp":"upper legs","eq":"dumbbell","tg":"quads","mg":"glutes","sm":["glutes","adductors","core","hamstrings"],"st":["Hold one dumbbell vertically against your chest with both hands.","Stand with feet shoulder-width apart and toes slightly out.","Squat down with your chest tall until your thighs are at least parallel.","Hold the bottom position for two seconds.","Drive through your heels to stand."],"img":"opengym/4816.webp","gif":null,"ext":1},{"id":"4817","n":"kettlebell good morning","bp":"upper legs","eq":"kettlebell","tg":"hamstrings","mg":"glutes","sm":["glutes","lower back","core"],"st":["Hold a kettlebell by the horns against your chest.","Stand with feet shoulder-width apart and knees slightly bent.","Push your hips back and hinge forward with a flat back.","Lower until you feel a stretch in your hamstrings.","Squeeze your glutes to stand tall again."],"img":"opengym/4817.webp","gif":null,"ext":1},{"id":"4818","n":"ring elevated row","bp":"back","eq":"suspension trainer","tg":"upper back","mg":"lats","sm":["lats","biceps","rhomboids","core"],"st":["Set the rings at about chest height and rest your heels on a bench.","Grab the rings and hang with arms extended and body straight.","Pull your chest toward your hands, driving your elbows back.","Squeeze your shoulder blades together at the top.","Lower with control without letting your hips sag."],"img":"opengym/4818.webp","gif":null,"ext":1},{"id":"4819","n":"ring leg curl","bp":"upper legs","eq":"suspension trainer","tg":"hamstrings","mg":"glutes","sm":["glutes","core","calves"],"st":["Lie on your back with your heels in the ring straps and legs extended.","Lift your hips into a bridge.","Bend your knees to pull your heels toward your glutes.","Keep your hips high the whole time.","Extend your legs slowly to return."],"img":"opengym/4819.webp","gif":null,"ext":1},{"id":"4820","n":"ring reverse ab rollout","bp":"waist","eq":"suspension trainer","tg":"abs","mg":"lower abs","sm":["lower abs","shoulders","hip flexors","core"],"st":["Set up in a push-up position with your feet in the ring straps.","Keep your arms straight and shoulders over your hands.","Pull your knees toward your chest by curling your pelvis.","Pause with your hips lifted and abs tight.","Extend your legs back to a straight plank slowly."],"img":"opengym/4820.webp","gif":null,"ext":1},{"id":"4821","n":"dumbbell single leg step up on bench","bp":"upper legs","eq":"dumbbell","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","calves","core"],"st":["Stand facing a bench holding a dumbbell in each hand.","Place one foot fully on the bench.","Press through that heel to stand up on the bench.","Lower your other foot back down slowly.","Finish your reps, then switch legs."],"img":"opengym/4821.webp","gif":null,"ext":1},{"id":"4822","n":"dumbbell rdl to jump shrug","bp":"full body","eq":"dumbbell","tg":"hamstrings","mg":"glutes","sm":["glutes","trapezius","calves","quadriceps","core"],"st":["Stand holding dumbbells in front of your thighs.","Hinge your hips back and lower the weights along your legs with a flat back.","Drive your hips forward and jump as you shrug your shoulders.","Land softly with bent knees.","Reset into the hinge and repeat."],"img":"opengym/4822.webp","gif":null,"ext":1},{"id":"4824","n":"diagonal punch","bp":"full body","eq":"body weight","tg":"delts","mg":"core","sm":["core","obliques","triceps","chest"],"st":["Stand in an athletic stance with your fists up.","Rotate your hips and torso as you throw a punch across your body.","Extend your arm fully and pivot your back foot.","Pull the arm back quickly.","Alternate sides at a brisk, controlled pace."],"img":"opengym/4824.webp","gif":null,"ext":1},{"id":"4825","n":"superman chest stretch","bp":"chest","eq":"body weight","tg":"pectorals","mg":"shoulders","sm":["shoulders","upper chest"],"st":["Lie face down on the floor with your arms extended out wide.","Gently lift your chest off the floor.","Draw your shoulder blades together and back.","Keep your neck in a neutral position.","Hold for 20-30 seconds, then relax."],"img":"opengym/4825.webp","gif":null,"ext":1},{"id":"4826","n":"alternate leg raise","bp":"waist","eq":"body weight","tg":"abs","mg":"lower abs","sm":["lower abs","hip flexors","core"],"st":["Lie flat on your back with your legs straight and arms at your sides.","Press your lower back into the floor.","Raise one leg up toward the ceiling.","Lower it slowly while lifting the other leg.","Keep alternating without arching your back."],"img":"opengym/4826.webp","gif":null,"ext":1},{"id":"4829","n":"jump skip rope","bp":"full body","eq":"rope","tg":"cardiovascular system","mg":"calves","sm":["calves","shoulders","forearms","feet"],"st":["Hold the rope handles at hip height with elbows near your sides.","Swing the rope over your head using your wrists.","Jump just high enough to clear the rope.","Land softly on the balls of your feet.","Keep a steady rhythm for 30-60 seconds, rest, and repeat."],"img":"opengym/4829.webp","gif":null,"ext":1},{"id":"4830","n":"push up in child pose","bp":"chest","eq":"body weight","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders","core","lats"],"st":["Kneel and sit back on your heels with your arms stretched forward.","Place your hands on the floor at chest height.","Shift forward and lower your chest between your hands.","Push the floor away to rise.","Sit back to the starting pose and repeat."],"img":"opengym/4830.webp","gif":null,"ext":1},{"id":"4831","n":"sliding floor pulldown on towel v. 2","bp":"back","eq":"body weight","tg":"lats","mg":"biceps","sm":["biceps","upper back","core","rhomboids"],"st":["Kneel with your hands on a towel placed on a smooth floor, arms stretched forward.","Brace your core and keep your back flat.","Pull your elbows down and back as your hands slide toward you.","Squeeze your lats at the bottom.","Slide back out slowly to the start."],"img":"opengym/4831.webp","gif":null,"ext":1},{"id":"4832","n":"lying rear lateral raise","bp":"shoulders","eq":"dumbbell","tg":"delts","mg":"rear deltoids","sm":["rear deltoids","upper back","rhomboids","trapezius"],"st":["Lie face down on a bench holding a light dumbbell in each hand.","Let your arms hang down with a slight bend in your elbows.","Raise your arms out to the sides until they reach shoulder height.","Squeeze your shoulder blades at the top.","Lower slowly."],"img":"opengym/4832.webp","gif":null,"ext":1},{"id":"4833","n":"dumbbell standing single arm arnold press","bp":"shoulders","eq":"dumbbell","tg":"delts","mg":"triceps","sm":["triceps","upper chest","core","trapezius"],"st":["Stand tall holding a dumbbell at shoulder height, palm facing you.","Brace your core and keep your other arm at your side.","Press the dumbbell up while rotating your palm to face forward.","Fully extend your arm overhead.","Lower while rotating back, then switch sides."],"img":"opengym/4833.webp","gif":null,"ext":1},{"id":"4834","n":"dumbbell alternate chest press on stability ball","bp":"chest","eq":"dumbbell","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders","core","upper chest"],"st":["Sit on a stability ball holding dumbbells and walk out until your upper back rests on it.","Lift your hips so your body forms a bridge.","Press one dumbbell up over your chest.","Lower it slowly while keeping your hips steady.","Alternate arms for each rep."],"img":"opengym/4834.webp","gif":null,"ext":1},{"id":"4835","n":"dumbbell rotational grip bench press","bp":"chest","eq":"dumbbell","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders","upper chest"],"st":["Lie on a bench holding dumbbells at chest level with palms facing each other.","Press the weights up while turning your palms to face forward.","Reach full arm extension over your chest.","Lower the weights while rotating back to a neutral grip.","Keep your feet planted and shoulder blades tight."],"img":"opengym/4835.webp","gif":null,"ext":1},{"id":"4836","n":"dumbbell reverse grip squeeze bench press","bp":"upper arms","eq":"dumbbell","tg":"triceps","mg":"chest","sm":["chest","shoulders"],"st":["Lie on a bench holding two dumbbells together over your chest with a reverse (palms toward you) grip.","Squeeze the dumbbells together firmly.","Lower them to your chest with elbows close to your body.","Press back up, keeping the squeeze.","Keep your wrists straight throughout."],"img":"opengym/4836.webp","gif":null,"ext":1},{"id":"4837","n":"dumbbell single arm bent over row","bp":"back","eq":"dumbbell","tg":"upper back","mg":"lats","sm":["lats","biceps","rhomboids","forearms"],"st":["Hold a dumbbell in one hand and hinge forward with a flat back.","Let the arm hang straight down.","Pull the dumbbell toward your hip, leading with your elbow.","Squeeze your back at the top.","Lower slowly and switch sides after your reps."],"img":"opengym/4837.webp","gif":null,"ext":1},{"id":"4838","n":"cable unilateral bicep curl","bp":"upper arms","eq":"cable","tg":"biceps","mg":"brachialis","sm":["brachialis","forearms"],"st":["Attach a handle to a low cable and stand facing the machine.","Hold the handle with one hand, elbow at your side.","Curl the handle toward your shoulder.","Squeeze your biceps at the top.","Lower slowly and switch arms."],"img":"opengym/4838.webp","gif":null,"ext":1},{"id":"4839","n":"banded lower body dead bug","bp":"waist","eq":"band","tg":"abs","mg":"lower abs","sm":["lower abs","hip flexors","core"],"st":["Lie on your back with a band around your feet and legs bent over your hips.","Press your lower back into the floor.","Extend one leg away against the band.","Return it and switch legs.","Keep your ribs down and your core braced."],"img":"opengym/4839.webp","gif":null,"ext":1},{"id":"4840","n":"straight leg dead bug","bp":"waist","eq":"body weight","tg":"abs","mg":"lower abs","sm":["lower abs","hip flexors","core"],"st":["Lie on your back with arms and legs straight up toward the ceiling.","Press your lower back into the floor.","Lower one arm and the opposite leg toward the floor.","Return to the start and switch sides.","Keep your lower back flat the whole time."],"img":"opengym/4840.webp","gif":null,"ext":1},{"id":"4841","n":"barbell band assisted deadlift","bp":"upper legs","eq":"barbell","tg":"glutes","mg":"hamstrings","sm":["hamstrings","lower back","grip muscles","quadriceps"],"st":["Attach a band to the barbell and anchor it overhead or to a rack.","Stand with the bar over midfoot and grip just outside your knees.","Brace and push the floor away to lift.","Stand tall and lock out your hips.","Lower with control."],"img":"opengym/4841.webp","gif":null,"ext":1},{"id":"4842","n":"trap bar banded deadlift","bp":"upper legs","eq":"trap bar","tg":"glutes","mg":"hamstrings","sm":["hamstrings","quadriceps","lower back","grip muscles"],"st":["Attach bands to the trap bar and stand inside the bar.","Grip the handles with a flat back and chest up.","Drive through your feet to stand up.","Lock your hips out at the top against the band.","Lower slowly back to the floor."],"img":"opengym/4842.webp","gif":null,"ext":1},{"id":"4843","n":"depth jump to broad jump","bp":"upper legs","eq":"body weight","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","calves"],"st":["Stand at the edge of a low box.","Step off and land on both feet.","Immediately explode forward into a broad jump.","Swing your arms for momentum.","Land softly with bent knees and reset."],"img":"opengym/4843.webp","gif":null,"ext":1},{"id":"4844","n":"depth jump","bp":"upper legs","eq":"body weight","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","calves"],"st":["Stand at the edge of a low box.","Step off and land on both feet.","Rebound immediately into a maximum vertical jump.","Spend as little time on the ground as you can.","Land softly and reset for the next rep."],"img":"opengym/4844.webp","gif":null,"ext":1},{"id":"4845","n":"kettlebell lying on floor chest press","bp":"chest","eq":"kettlebell","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders","core"],"st":["Lie on the floor holding a kettlebell in each hand at chest level.","Keep your elbows at about 45 degrees from your body.","Press the kettlebells up until your arms are straight.","Lower until your upper arms touch the floor.","Press again."],"img":"opengym/4845.webp","gif":null,"ext":1},{"id":"4846","n":"kettlebell lying on floor single arm bottoms up chest press","bp":"chest","eq":"kettlebell","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders","forearms","core"],"st":["Lie on the floor and hold a kettlebell upside down in one hand.","Keep your wrist straight and the bell steady.","Press it up to full extension.","Lower slowly until your upper arm touches the floor.","Switch sides after your reps."],"img":"opengym/4846.webp","gif":null,"ext":1},{"id":"4847","n":"weighted plate standing high front raise","bp":"shoulders","eq":"weight plate","tg":"delts","mg":"upper chest","sm":["upper chest","trapezius","core"],"st":["Stand holding a weight plate with both hands at your thighs.","Keep your arms nearly straight.","Raise the plate up and overhead.","Pause at the top.","Lower slowly."],"img":"opengym/4847.webp","gif":null,"ext":1},{"id":"4848","n":"barbell pin front squat","bp":"upper legs","eq":"barbell","tg":"quads","mg":"glutes","sm":["glutes","core","adductors","lower back"],"st":["Set pins at the bottom depth and place the bar on them.","Get under the bar in a front rack position.","Brace and drive up to stand.","Lower back to the pins under control.","Pause and reset between reps."],"img":"opengym/4848.webp","gif":null,"ext":1},{"id":"4849","n":"banded glute ham raise v. 2","bp":"upper legs","eq":"band","tg":"hamstrings","mg":"glutes","sm":["glutes","lower back","calves"],"st":["Set up on a glute-ham bench or anchor your feet with a band assisting you.","Start with your torso down and hips locked.","Curl up using your hamstrings.","Squeeze your glutes at the top.","Lower with control."],"img":"opengym/4849.webp","gif":null,"ext":1},{"id":"4850","n":"barbell single leg good morning","bp":"upper legs","eq":"barbell","tg":"hamstrings","mg":"glutes","sm":["glutes","lower back","core"],"st":["Rest a barbell on your upper back and stand on one leg.","Keep your standing knee slightly bent.","Hinge forward while your free leg extends behind you.","Lower until your torso is near parallel.","Return and switch legs after your reps."],"img":"opengym/4850.webp","gif":null,"ext":1},{"id":"4851","n":"barbell pin good morning","bp":"upper legs","eq":"barbell","tg":"hamstrings","mg":"glutes","sm":["glutes","lower back","core"],"st":["Set the pins to a hip-hinge height and set the bar on them.","Get under the bar, brace and unrack.","Hinge forward with a flat back.","Return the bar to the pins.","Stand tall and repeat."],"img":"opengym/4851.webp","gif":null,"ext":1},{"id":"4852","n":"dumbbell alternate lateral raise","bp":"shoulders","eq":"dumbbell","tg":"delts","mg":"trapezius","sm":["trapezius","rotator cuff","upper back"],"st":["Stand holding light dumbbells at your sides.","Keep a slight bend in your elbows.","Raise one arm out to shoulder height.","Lower it slowly.","Switch arms."],"img":"opengym/4852.webp","gif":null,"ext":1},{"id":"4854","n":"barbell sitting on floor oblique twist","bp":"waist","eq":"barbell","tg":"obliques","mg":"core","sm":["core","hip flexors"],"st":["Sit on the floor with legs bent and a bar across your shoulders.","Lean back slightly and brace.","Rotate your torso to one side.","Return to center.","Rotate to the other side."],"img":"opengym/4854.webp","gif":null,"ext":1},{"id":"4855","n":"bodyweight standing oblique twist","bp":"waist","eq":"body weight","tg":"obliques","mg":"core","sm":["core"],"st":["Stand with feet shoulder-width apart and arms at chest height.","Rotate your torso to one side.","Return to center.","Rotate to the other side.","Keep your hips facing forward."],"img":"opengym/4855.webp","gif":null,"ext":1},{"id":"4856","n":"barbell pin close grip bench press","bp":"upper arms","eq":"barbell","tg":"triceps","mg":"chest","sm":["chest","shoulders"],"st":["Set the bar on pins at chest height.","Lie on the bench and grip the bar shoulder-width.","Press the bar up.","Lock out your elbows.","Lower back to the pins."],"img":"opengym/4856.webp","gif":null,"ext":1},{"id":"4857","n":"barbell behind the back push press","bp":"shoulders","eq":"barbell","tg":"delts","mg":"triceps","sm":["triceps","quadriceps","upper chest","core"],"st":["Hold a barbell on your upper back with a wide grip.","Dip your knees slightly.","Drive up explosively and press overhead.","Lock out your arms.","Lower the bar back to your shoulders."],"img":"opengym/4857.webp","gif":null,"ext":1},{"id":"4858","n":"lateral walk push up","bp":"chest","eq":"body weight","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders","core"],"st":["Start in a high plank.","Do one push-up.","Step your hands and feet to the side.","Do another push-up.","Alternate direction after a set."],"img":"opengym/4858.webp","gif":null,"ext":1},{"id":"4859","n":"push up to side plank v. 2","bp":"chest","eq":"body weight","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders","obliques","core"],"st":["Start in a high plank.","Lower into a push-up.","Push up and rotate into a side plank, raising one arm.","Return to plank.","Alternate sides each rep."],"img":"opengym/4859.webp","gif":null,"ext":1},{"id":"4860","n":"push up with knee drive","bp":"waist","eq":"body weight","tg":"abs","mg":"triceps","sm":["triceps","hip flexors","shoulders"],"st":["Start in a high plank.","Lower into a push-up.","Push back up.","Drive one knee toward your chest.","Return and alternate legs."],"img":"opengym/4860.webp","gif":null,"ext":1},{"id":"4861","n":"kettlebell romanian deadlift","bp":"upper legs","eq":"kettlebell","tg":"hamstrings","mg":"glutes","sm":["glutes","lower back","grip muscles"],"st":["Hold a kettlebell in front of your thighs.","Soften your knees.","Push your hips back and lower the bell along your legs.","Keep your back flat.","Squeeze your glutes to stand."],"img":"opengym/4861.webp","gif":null,"ext":1},{"id":"4862","n":"barbell standing snatch grip shrug","bp":"back","eq":"barbell","tg":"traps","mg":"upper back","sm":["upper back","grip muscles","forearms","rhomboids"],"st":["Hold a barbell with a wide snatch grip at your thighs.","Stand tall with your chest up.","Shrug your shoulders straight up.","Pause at the top.","Lower slowly."],"img":"opengym/4862.webp","gif":null,"ext":1},{"id":"4864","n":"barbell sumo deadlift from deficit","bp":"upper legs","eq":"barbell","tg":"glutes","mg":"hamstrings","sm":["hamstrings","adductors","quadriceps","lower back"],"st":["Stand on a low platform with a wide stance and toes out.","Grip the bar inside your knees.","Brace and push the floor away.","Lock your hips out.","Lower the bar under control."],"img":"opengym/4864.webp","gif":null,"ext":1},{"id":"4865","n":"dumbbell overhead walking lunge","bp":"upper legs","eq":"dumbbell","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","shoulders","core"],"st":["Hold dumbbells overhead with locked arms.","Step forward into a lunge.","Lower your back knee near the floor.","Push through your front foot.","Step through into the next lunge."],"img":"opengym/4865.webp","gif":null,"ext":1},{"id":"4866","n":"barbell z press","bp":"shoulders","eq":"barbell","tg":"delts","mg":"triceps","sm":["triceps","core","upper chest","lower back"],"st":["Sit on the floor with legs straight and the bar at your shoulders.","Brace your core.","Press the bar overhead.","Lock out your arms.","Lower to the shoulders."],"img":"opengym/4866.webp","gif":null,"ext":1},{"id":"4867","n":"butterfly yoga flaps","bp":"upper legs","eq":"body weight","tg":"adductors","mg":"groin","sm":["groin","inner thighs","hip flexors"],"st":["Sit with the soles of your feet together.","Hold your feet.","Gently flap your knees up and down.","Keep your spine tall.","Continue for 30 seconds."],"img":"opengym/4867.webp","gif":null,"ext":1},{"id":"4870","n":"hip clam shell","bp":"upper legs","eq":"body weight","tg":"abductors","mg":"glutes","sm":["glutes","hip flexors","core"],"st":["Lie on your side with knees bent and feet together.","Keep your feet touching.","Lift your top knee.","Lower slowly.","Switch sides after your reps."],"img":"opengym/4870.webp","gif":null,"ext":1},{"id":"4871","n":"dumbbell 6 ways raise","bp":"shoulders","eq":"dumbbell","tg":"delts","mg":"rear deltoids","sm":["rear deltoids","rotator cuff","trapezius","upper back"],"st":["Hold light dumbbells at your sides.","Raise them to the side and lower.","Raise them to the front and lower.","Then bend forward and raise them out to the rear.","Complete all six variations as one rep."],"img":"opengym/4871.webp","gif":null,"ext":1},{"id":"4875","n":"bodyweight standing back stretch","bp":"back","eq":"body weight","tg":"spine","mg":"lats","sm":["lats","core"],"st":["Stand tall with feet hip width apart.","Clasp your hands in front of you and press your arms forward.","Round your upper back and tuck your chin slightly.","Feel the stretch between your shoulder blades and along the spine.","Hold for 20-30 seconds.","Release slowly and stand tall."],"img":"opengym/4875.webp","gif":null,"ext":1},{"id":"4876","n":"prayer push","bp":"shoulders","eq":"body weight","tg":"delts","mg":"chest","sm":["chest","triceps","core"],"st":["Stand or sit tall and press your palms together at chest height.","Point your fingers up and keep your elbows out.","Push your palms firmly into each other.","Hold the squeeze for 5-10 seconds.","Relax and shake out your arms.","Repeat for several rounds."],"img":"opengym/4876.webp","gif":null,"ext":1},{"id":"4880","n":"lying criss cross legs","bp":"waist","eq":"body weight","tg":"abs","mg":"lower abs","sm":["lower abs","hip flexors","obliques"],"st":["Lie on your back with legs raised slightly off the floor.","Press your lower back down.","Cross one leg over the other.","Switch and cross the other way.","Continue smoothly."],"img":"opengym/4880.webp","gif":null,"ext":1},{"id":"4881","n":"bridge hip abduction","bp":"upper legs","eq":"body weight","tg":"abductors","mg":"glutes","sm":["glutes","hamstrings","core"],"st":["Lie on your back with knees bent and feet flat on the floor.","Drive through your heels and lift your hips into a bridge.","Keeping the hips high, open both knees out to the sides.","Bring the knees back together without dropping the hips.","Lower slowly to the floor and repeat.","Keep your ribs down so your lower back does not arch."],"img":"opengym/4881.webp","gif":null,"ext":1},{"id":"4882","n":"side lying scissors","bp":"upper legs","eq":"body weight","tg":"abductors","mg":"glutes","sm":["glutes","obliques","hip flexors"],"st":["Lie on your side with your body in a straight line and head supported.","Stack your legs and lift the top leg slightly.","Raise the top leg up while the bottom leg lifts toward it.","Bring them back together in a smooth scissor motion.","Keep your hips stacked and still.","Finish your reps, then switch sides."],"img":"opengym/4882.webp","gif":null,"ext":1},{"id":"4883","n":"lying air cycles","bp":"waist","eq":"body weight","tg":"abs","mg":"lower abs","sm":["lower abs","hip flexors","quadriceps"],"st":["Lie on your back with your hands by your head or at your sides.","Lift your shoulders and legs slightly off the floor.","Pedal your legs as if riding a bicycle.","Keep your lower back pressed into the floor.","Breathe steadily and keep a smooth rhythm.","Lower your legs and rest when your form slips."],"img":"opengym/4883.webp","gif":null,"ext":1},{"id":"4884","n":"side lying outward knee kick","bp":"upper legs","eq":"body weight","tg":"abductors","mg":"glutes","sm":["glutes","hip flexors","obliques"],"st":["Lie on your side with your hips stacked and bottom leg bent.","Bend the top knee and bring it toward your chest.","Kick the top leg straight out to the side.","Pull the knee back in under control.","Keep your torso still the whole time.","Complete your reps, then switch sides."],"img":"opengym/4884.webp","gif":null,"ext":1},{"id":"4885","n":"lying incline hip raise","bp":"waist","eq":"body weight","tg":"abs","mg":"lower abs","sm":["lower abs","hip flexors"],"st":["Lie back on an incline surface and hold the top with your hands.","Bring your legs up with knees slightly bent.","Curl your pelvis and lift your hips off the surface.","Pause with your feet pointing toward the ceiling.","Lower your hips slowly.","Avoid swinging your legs."],"img":"opengym/4885.webp","gif":null,"ext":1},{"id":"4886","n":"lying flat hip raise","bp":"waist","eq":"body weight","tg":"abs","mg":"lower abs","sm":["lower abs","hip flexors"],"st":["Lie on your back with arms by your sides or under your hips.","Raise your legs so they point to the ceiling.","Tighten your abs and lift your hips a few centimetres.","Hold for a moment at the top.","Lower your hips slowly to the floor.","Keep the motion small and controlled."],"img":"opengym/4886.webp","gif":null,"ext":1},{"id":"4888","n":"dumbbell standing high windmill","bp":"waist","eq":"dumbbell","tg":"obliques","mg":"abdominals","sm":["abdominals","shoulders","hamstrings","lower back"],"st":["Stand with feet wide and press a dumbbell overhead with one arm.","Turn your feet slightly away from the weighted side.","Push your hips toward the weighted side and hinge forward.","Slide your free hand down your leg while your eyes stay on the dumbbell.","Reverse the movement to stand tall again.","Keep the arm locked and stacked over your shoulder, then switch sides."],"img":"opengym/4888.webp","gif":null,"ext":1},{"id":"4889","n":"dumbbell power clean","bp":"full body","eq":"dumbbell","tg":"glutes","mg":"hamstrings","sm":["hamstrings","quadriceps","trapezius","shoulders","core"],"st":["Stand over the dumbbells with feet hip width and grab them with a flat back.","Push through the floor and extend your hips and knees fast.","Shrug and pull the dumbbells up close to your body.","Drop under them and catch them on your shoulders in a quarter squat.","Stand tall, then lower with control to the floor.","Keep your back flat and the weights close throughout."],"img":"opengym/4889.webp","gif":null,"ext":1},{"id":"4890","n":"glute ham raise with extended arms","bp":"upper legs","eq":"leverage machine","tg":"hamstrings","mg":"glutes","sm":["glutes","lower back","calves"],"st":["Set up on the glute ham bench with your ankles locked in and thighs supported.","Extend your arms straight out in front of you.","Lower your torso toward the floor with a straight body.","Squeeze your hamstrings and glutes to pull yourself back up.","Stop when your body is in a straight line.","Move slowly and avoid arching your lower back."],"img":"opengym/4890.webp","gif":null,"ext":1},{"id":"4891","n":"hanging half windmill","bp":"waist","eq":"body weight","tg":"obliques","mg":"abdominals","sm":["abdominals","lats","grip muscles","hip flexors"],"st":["Hang from a pull-up bar with a firm overhand grip.","Raise both legs together toward one side of the bar.","Sweep them across the front in a half circle.","Lower the legs on the other side under control.","Keep the swing small and your shoulders active.","Repeat, alternating the direction."],"img":"opengym/4891.webp","gif":null,"ext":1},{"id":"4892","n":"elevated single leg squat","bp":"upper legs","eq":"body weight","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","core","calves"],"st":["Stand on a bench or box on one leg with the other leg hanging off the edge.","Reach your arms forward for balance.","Sit your hips back and bend the standing knee to lower.","Go as deep as you can while the knee tracks over your toes.","Push through the foot to stand back up.","Finish your reps, then switch legs."],"img":"opengym/4892.webp","gif":null,"ext":1},{"id":"4893","n":"kneeling half triceps extension","bp":"upper arms","eq":"cable","tg":"triceps","mg":"shoulders","sm":["shoulders","core"],"st":["Kneel facing the cable stack and hold the attachment with elbows bent.","Tuck your elbows close to your sides.","Press the handle down until your arms are straight.","Squeeze the triceps at the bottom.","Let the hands rise only halfway, keeping tension.","Keep your upper arms still throughout."],"img":"opengym/4893.webp","gif":null,"ext":1},{"id":"4894","n":"staggered leg side bridge","bp":"waist","eq":"body weight","tg":"obliques","mg":"abdominals","sm":["abdominals","glutes","shoulders"],"st":["Lie on your side with your forearm under your shoulder.","Stagger your feet, top foot in front of the bottom one.","Lift your hips so your body forms a straight line.","Hold the position while breathing steadily.","Keep the hips high and avoid rolling forward.","Hold for 20-30 seconds, then switch sides."],"img":"opengym/4894.webp","gif":null,"ext":1},{"id":"4895","n":"standing calf raise circle","bp":"lower legs","eq":"body weight","tg":"calves","mg":"soleus","sm":["soleus","ankles","feet"],"st":["Stand tall with feet hip width apart and hold a support if needed.","Rise onto the balls of your feet.","Trace a small circle with your heels while staying high.","Lower your heels slowly to the floor.","Reverse the circle direction on the next rep.","Keep your knees straight and your balance steady."],"img":"opengym/4895.webp","gif":null,"ext":1},{"id":"4896","n":"kneeling straight leg side kick","bp":"upper legs","eq":"body weight","tg":"abductors","mg":"glutes","sm":["glutes","obliques"],"st":["Get on all fours with hands under shoulders and knees under hips.","Extend one leg out to the side with the knee straight.","Lift the leg to about hip height.","Keep your hips and back steady.","Lower with control without touching down.","Finish your reps, then switch legs."],"img":"opengym/4896.webp","gif":null,"ext":1},{"id":"4897","n":"reverse sliding leg curl on floor with towel","bp":"upper legs","eq":"body weight","tg":"hamstrings","mg":"glutes","sm":["glutes","calves","core"],"st":["Lie on your back with your heels on a towel on a smooth floor.","Lift your hips into a bridge.","Slide your feet away from you by extending the knees.","Pull the heels back toward your hips with your hamstrings.","Keep your hips high the whole set.","Lower to the floor when you finish."],"img":"opengym/4897.webp","gif":null,"ext":1},{"id":"4898","n":"kick side jump","bp":"cardio","eq":"body weight","tg":"cardiovascular system","mg":"quadriceps","sm":["quadriceps","glutes","calves","core"],"st":["Stand tall with your knees slightly bent.","Jump up off both feet.","Kick one leg out to the side at the top.","Land softly on both feet with soft knees.","Repeat, alternating the kicking leg.","Keep a controlled, bouncy rhythm."],"img":"opengym/4898.webp","gif":null,"ext":1},{"id":"4899","n":"lever bent over wide row (plate loaded)","bp":"back","eq":"leverage machine","tg":"upper back","mg":"lats","sm":["lats","rear deltoids","biceps","rhomboids"],"st":["Load the machine and set your chest against the support.","Grab the wide handles with arms extended.","Pull the handles toward your lower chest, elbows flaring out.","Squeeze your shoulder blades together.","Return slowly until your arms are straight.","Keep your chest on the pad throughout."],"img":"opengym/4899.webp","gif":null,"ext":1},{"id":"4900","n":"elevated seated calf raise","bp":"lower legs","eq":"body weight","tg":"calves","mg":"soleus","sm":["soleus","ankles"],"st":["Sit on a bench with the balls of your feet on a raised step.","Rest weight or your hands on your thighs.","Lower your heels as far as you comfortably can.","Press up onto your toes as high as possible.","Pause briefly at the top.","Lower slowly and repeat."],"img":"opengym/4900.webp","gif":null,"ext":1},{"id":"4901","n":"dumbbell standing windmill","bp":"waist","eq":"dumbbell","tg":"obliques","mg":"abdominals","sm":["abdominals","shoulders","hamstrings","lower back"],"st":["Press a dumbbell overhead with one hand and stand with feet wide.","Turn your toes slightly away from the weight.","Push your hips out and hinge sideways.","Slide your free hand down your leg toward the floor.","Reverse the motion and stand tall.","Keep your eyes on the weight, then switch sides."],"img":"opengym/4901.webp","gif":null,"ext":1},{"id":"4902","n":"elevated single leg hip thrust","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"hamstrings","sm":["hamstrings","core"],"st":["Rest your upper back on a bench and put one foot on the floor or a raised step.","Lift the other leg off the ground.","Drive through the planted heel and lift your hips.","Squeeze the glute at the top with your torso level.","Lower slowly under control.","Complete your reps, then switch legs."],"img":"opengym/4902.webp","gif":null,"ext":1},{"id":"4903","n":"resistance band seated leg curl","bp":"upper legs","eq":"resistance band","tg":"hamstrings","mg":"calves","sm":["calves","glutes"],"st":["Anchor the band at foot height and sit facing it.","Loop the band around your heels.","Extend your legs straight in front of you.","Curl your heels back under the seat against the tension.","Squeeze the hamstrings at the end.","Return slowly without letting the band snap."],"img":"opengym/4903.webp","gif":null,"ext":1},{"id":"4904","n":"toe jump","bp":"lower legs","eq":"body weight","tg":"calves","mg":"ankles","sm":["ankles","feet"],"st":["Stand tall with feet close together and knees slightly bent.","Rise onto the balls of your feet.","Hop up quickly using mainly your ankles.","Land softly on the balls of your feet.","Keep your hops small and rhythmic.","Continue for 20-30 seconds."],"img":"opengym/4904.webp","gif":null,"ext":1},{"id":"4905","n":"banded glute ham raise v. 3","bp":"upper legs","eq":"band","tg":"hamstrings","mg":"glutes","sm":["glutes","lower back","calves"],"st":["Set up on a glute ham bench with your ankles locked and a band for support.","Cross your arms or hold the band in front of you.","Lower your torso toward the floor with a straight body.","Squeeze your hamstrings and glutes to pull yourself back up.","Stop when your body is in a straight line.","Move slowly and avoid jerking."],"img":"opengym/4905.webp","gif":null,"ext":1},{"id":"4906","n":"long lever decline sit up","bp":"waist","eq":"body weight","tg":"abs","mg":"hip flexors","sm":["hip flexors","core"],"st":["Lie on a decline bench with your feet secured.","Extend your arms overhead.","Curl your torso up, raising your arms with it.","Sit up until your chest is over your thighs.","Lower slowly back down.","Keep your arms reaching forward the whole time."],"img":"opengym/4906.webp","gif":null,"ext":1},{"id":"4907","n":"side plank with raised leg v. 2","bp":"waist","eq":"body weight","tg":"obliques","mg":"abdominals","sm":["abdominals","glutes","shoulders"],"st":["Set up in a side plank on your forearm with your body in a line.","Lift your top leg to hip height.","Keep your hips high and your core tight.","Hold for 20-30 seconds without dropping.","Lower down gently.","Repeat on the other side."],"img":"opengym/4907.webp","gif":null,"ext":1},{"id":"4908","n":"dumbbell over bench reverse wrist curl with mat","bp":"lower arms","eq":"dumbbell","tg":"forearms","mg":"wrist extensors","sm":["wrist extensors","grip muscles"],"st":["Kneel by a bench with forearms on it, palms down, wrists over the edge.","Hold a dumbbell in each hand.","Let your wrists lower gently.","Curl the weights up by extending your wrists.","Pause at the top, then lower slowly.","Keep your forearms still on the bench."],"img":"opengym/4908.webp","gif":null,"ext":1},{"id":"4909","n":"side to wide squat","bp":"upper legs","eq":"body weight","tg":"quads","mg":"glutes","sm":["glutes","adductors","hamstrings","core"],"st":["Stand with your feet together and arms in front.","Step one foot out to the side into a wide stance.","Sit down into a squat with your chest up.","Stand up and bring your feet back together.","Alternate the stepping side.","Keep your knees tracking over your toes."],"img":"opengym/4909.webp","gif":null,"ext":1},{"id":"4910","n":"dumbbell bent arm iso hold","bp":"upper arms","eq":"dumbbell","tg":"biceps","mg":"brachialis","sm":["brachialis","forearms","shoulders"],"st":["Stand tall with a dumbbell in each hand.","Curl the weights until your elbows are bent about 90 degrees.","Keep your elbows pinned to your sides.","Hold the position without letting the weights drop.","Breathe steadily during the hold.","Hold for 20-30 seconds, then lower under control."],"img":"opengym/4910.webp","gif":null,"ext":1},{"id":"4911","n":"inverted wide to narrow row","bp":"back","eq":"suspension trainer","tg":"upper back","mg":"lats","sm":["lats","biceps","rear deltoids","core"],"st":["Set a bar or straps at waist height and lie underneath.","Grab it with a wide grip and straighten your body.","Pull your chest toward the bar.","Bring your hands closer on the way up or between reps.","Lower yourself with control.","Keep your body in a straight line."],"img":"opengym/4911.webp","gif":null,"ext":1},{"id":"4912","n":"ring leg curl v. 2","bp":"upper legs","eq":"suspension trainer","tg":"hamstrings","mg":"glutes","sm":["glutes","calves","core"],"st":["Lie on your back with your heels in the rings.","Lift your hips into a bridge.","Pull the rings toward your glutes by bending the knees.","Pause and squeeze the hamstrings.","Extend your legs slowly back out.","Keep your hips high throughout."],"img":"opengym/4912.webp","gif":null,"ext":1},{"id":"4913","n":"narrow top half pull up","bp":"back","eq":"body weight","tg":"lats","mg":"biceps","sm":["biceps","upper back","forearms"],"st":["Grab a pull-up bar with a narrow grip and pull up to the top position.","Lower yourself to about halfway.","Pull back up until your chin clears the bar.","Keep your chest up and your elbows close.","Avoid swinging.","Repeat for your reps."],"img":"opengym/4913.webp","gif":null,"ext":1},{"id":"4914","n":"dumbbell deadlift (neutral grip)","bp":"upper legs","eq":"dumbbell","tg":"glutes","mg":"hamstrings","sm":["hamstrings","lower back","grip muscles","quadriceps"],"st":["Stand with feet hip width and a dumbbell in each hand, palms facing in.","Hinge at the hips with a flat back and lower the weights.","Keep the dumbbells close to your legs.","Push through your heels to stand tall.","Squeeze your glutes at the top.","Do not round your lower back."],"img":"opengym/4914.webp","gif":null,"ext":1},{"id":"4916","n":"reverse leg extension","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"hamstrings","sm":["hamstrings","lower back"],"st":["Get on all fours with your hands under your shoulders.","Brace your core and keep your back flat.","Extend one leg back and up.","Squeeze the glute at the top.","Lower the leg without touching the floor.","Finish your reps, then switch legs."],"img":"opengym/4916.webp","gif":null,"ext":1},{"id":"4917","n":"high bar inverted row","bp":"back","eq":"body weight","tg":"upper back","mg":"lats","sm":["lats","biceps","rear deltoids","core"],"st":["Set a bar at about chest height and grab it overhand.","Walk your feet forward until your arms are straight.","Keep your body in a straight line.","Pull your chest toward the bar.","Squeeze your shoulder blades together.","Lower yourself slowly."],"img":"opengym/4917.webp","gif":null,"ext":1},{"id":"4918","n":"alternate high hop","bp":"cardio","eq":"body weight","tg":"cardiovascular system","mg":"calves","sm":["calves","quadriceps","glutes"],"st":["Stand tall with your arms ready to swing.","Hop off one foot and drive the opposite knee up.","Land softly on the ball of your foot.","Switch legs on the next hop.","Swing your arms in rhythm with your legs.","Keep a quick, bouncy pace."],"img":"opengym/4918.webp","gif":null,"ext":1},{"id":"4919","n":"kneeling assisted sliding chin up","bp":"back","eq":"body weight","tg":"lats","mg":"biceps","sm":["biceps","upper back","forearms"],"st":["Kneel below a bar and grab it with an underhand grip.","Place a towel or slider under your knees.","Pull your chest toward the bar.","Use your legs lightly to help.","Lower slowly to straight arms.","Keep your shoulders away from your ears."],"img":"opengym/4919.webp","gif":null,"ext":1},{"id":"4920","n":"leg assisted ring pull up","bp":"back","eq":"suspension trainer","tg":"lats","mg":"biceps","sm":["biceps","upper back","forearms"],"st":["Hold the rings with a firm grip and stand with a bend in the knees.","Place your feet on the floor for light help.","Pull your elbows down and your chest between the rings.","Use your legs only as much as you need.","Lower with control.","Keep your core tight."],"img":"opengym/4920.webp","gif":null,"ext":1},{"id":"4921","n":"ring high row","bp":"back","eq":"suspension trainer","tg":"lats","mg":"upper back","sm":["upper back","biceps","rear deltoids"],"st":["Hold the rings and lean back with a straight body.","Pull the rings toward your forehead.","Flare your elbows out and squeeze your shoulder blades.","Pause briefly at the top.","Lower until your arms are straight.","Keep your hips up the whole time."],"img":"opengym/4921.webp","gif":null,"ext":1},{"id":"4922","n":"ring chest fly","bp":"chest","eq":"suspension trainer","tg":"pectorals","mg":"shoulders","sm":["shoulders","core","biceps"],"st":["Set the rings low and hold them in a plank position.","Keep your arms nearly straight with a small bend in the elbows.","Open your arms out to the sides, lowering your chest.","Pull the rings back together with your chest.","Keep your body in a straight line.","Go only as wide as you can control."],"img":"opengym/4922.webp","gif":null,"ext":1},{"id":"4923","n":"ring reverse fly","bp":"shoulders","eq":"suspension trainer","tg":"delts","mg":"rear deltoids","sm":["rear deltoids","upper back","rhomboids"],"st":["Hold the rings with arms straight and lean back.","Keep your body in a straight line.","Open your arms out to the sides.","Squeeze your shoulder blades together.","Return slowly to the start.","Keep your elbows only slightly bent."],"img":"opengym/4923.webp","gif":null,"ext":1},{"id":"4924","n":"long lever lying back extension","bp":"back","eq":"body weight","tg":"spine","mg":"glutes","sm":["glutes","hamstrings","rhomboids"],"st":["Lie face down with your arms extended overhead.","Squeeze your glutes to stabilize.","Lift your chest and arms off the floor.","Pause briefly at the top.","Lower with control.","Keep your neck neutral by looking down."],"img":"opengym/4924.webp","gif":null,"ext":1},{"id":"4928","n":"seated calf stretch v. 2","bp":"lower legs","eq":"body weight","tg":"calves","mg":"soleus","sm":["soleus","ankles"],"st":["Sit with one leg straight in front of you.","Loop your hands or a strap around the ball of your foot.","Gently pull your toes toward you.","Feel the stretch in the calf.","Hold for 20-30 seconds.","Switch legs."],"img":"opengym/4928.webp","gif":null,"ext":1},{"id":"4929","n":"lying calf stretch","bp":"lower legs","eq":"body weight","tg":"calves","mg":"soleus","sm":["soleus","ankles"],"st":["Lie on your back and lift one leg toward the ceiling.","Hold behind the thigh or use a strap on your foot.","Pull your toes toward your shin.","Keep the knee as straight as you comfortably can.","Hold for 20-30 seconds.","Switch legs."],"img":"opengym/4929.webp","gif":null,"ext":1},{"id":"4930","n":"lunge stretch","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hip flexors"],"st":["Step one foot forward into a lunge, back knee down on a mat.","Keep your torso upright.","Push your hips gently forward.","Feel the stretch in the front of the back hip and thigh.","Hold for 20-30 seconds.","Switch legs."],"img":"opengym/4930.webp","gif":null,"ext":1},{"id":"4931","n":"single leg calf stretch","bp":"lower legs","eq":"body weight","tg":"calves","mg":"soleus","sm":["soleus","ankles"],"st":["Stand facing a wall with one foot back and heel on the floor.","Place your hands on the wall.","Lean forward with a straight back leg.","Feel the stretch in the calf.","Hold for 20-30 seconds.","Switch legs."],"img":"opengym/4931.webp","gif":null,"ext":1},{"id":"4932","n":"lying bent knee figure 8","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"hip flexors","sm":["hip flexors","core","adductors"],"st":["Lie on your back with knees bent.","Lift one knee above the hip.","Trace a slow figure eight in the air with your knee.","Keep the movement smooth and controlled.","Keep your pelvis steady on the floor.","Switch legs after a set."],"img":"opengym/4932.webp","gif":null,"ext":1},{"id":"4933","n":"standing leg circle","bp":"upper legs","eq":"body weight","tg":"abductors","mg":"hip flexors","sm":["hip flexors","glutes","core"],"st":["Stand tall and hold a support for balance.","Lift one leg slightly off the floor.","Draw a smooth circle with the leg.","Keep your torso still.","Reverse the direction after several reps.","Switch legs."],"img":"opengym/4933.webp","gif":null,"ext":1},{"id":"4934","n":"reverse plank v. 2","bp":"waist","eq":"body weight","tg":"abs","mg":"glutes","sm":["glutes","hamstrings","shoulders","triceps"],"st":["Sit with your legs straight and your hands behind you.","Press into your hands and lift your hips.","Form a straight line from head to heels.","Keep your chin neutral.","Squeeze your glutes.","Hold for 20-30 seconds."],"img":"opengym/4934.webp","gif":null,"ext":1},{"id":"4935","n":"around the world superman","bp":"back","eq":"body weight","tg":"spine","mg":"glutes","sm":["glutes","rear deltoids","hamstrings"],"st":["Lie face down with your arms extended overhead.","Lift your chest, arms and legs off the floor.","Sweep your arms out to the sides toward your hips.","Return them overhead in a wide arc.","Keep your legs lifted.","Lower to the floor to rest."],"img":"opengym/4935.webp","gif":null,"ext":1},{"id":"4936","n":"sumo air squat","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"quadriceps","sm":["quadriceps","adductors","hamstrings"],"st":["Stand with feet wide and toes turned out.","Hold your hands in front of your chest.","Sit down between your legs.","Keep your chest up and knees over the toes.","Push through your heels to stand.","Squeeze the glutes at the top."],"img":"opengym/4936.webp","gif":null,"ext":1},{"id":"4937","n":"45 degree hip extension glute focused","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"hamstrings","sm":["hamstrings","lower back"],"st":["Set up on a 45 degree bench with your ankles locked.","Cross your arms over your chest and round your upper back slightly.","Lower your torso by hinging at the hips.","Squeeze the glutes to raise back up.","Stop when your body is in a straight line.","Avoid overarching your lower back."],"img":"opengym/4937.webp","gif":null,"ext":1},{"id":"4938","n":"wrist abduction","bp":"lower arms","eq":"body weight","tg":"forearms","mg":"wrist extensors","sm":["wrist extensors","wrist flexors"],"st":["Rest your forearm on a table with your hand off the edge.","Keep your palm facing in.","Tilt your hand up toward the thumb side.","Return to neutral slowly.","Keep your forearm still.","Do equal reps on both wrists."],"img":"opengym/4938.webp","gif":null,"ext":1},{"id":"4939","n":"superman row","bp":"back","eq":"body weight","tg":"upper back","mg":"rear deltoids","sm":["rear deltoids","lower back","rhomboids"],"st":["Lie face down with arms extended in front.","Lift your chest and arms slightly off the floor.","Pull your elbows back toward your ribs as if rowing.","Squeeze your shoulder blades together.","Extend your arms forward again.","Keep your neck neutral."],"img":"opengym/4939.webp","gif":null,"ext":1},{"id":"4942","n":"stationary arms throw","bp":"back","eq":"body weight","tg":"upper back","mg":"shoulders","sm":["shoulders","core"],"st":["Stand with feet shoulder width apart and arms at your sides.","Swing your arms up and back in a throwing motion.","Rotate through your torso slightly.","Keep the movement smooth and rhythmic.","Switch arms or alternate.","Continue for 20-30 seconds."],"img":"opengym/4942.webp","gif":null,"ext":1},{"id":"4944","n":"standing bent knee figure 8","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"hip flexors","sm":["hip flexors","core","adductors"],"st":["Stand tall and hold a support if needed.","Lift one knee in front of you.","Trace a slow figure eight with your knee.","Keep your standing leg steady.","Keep your torso upright.","Switch legs."],"img":"opengym/4944.webp","gif":null,"ext":1},{"id":"4945","n":"chest out hands behind (hold)","bp":"chest","eq":"body weight","tg":"pectorals","mg":"shoulders","sm":["shoulders","upper chest"],"st":["Stand tall and clasp your hands behind your back.","Straighten your arms.","Lift your chest and gently raise your hands.","Feel the stretch across the chest and shoulders.","Hold for 20-30 seconds.","Release slowly."],"img":"opengym/4945.webp","gif":null,"ext":1},{"id":"4948","n":"cable kneeling one arm lat pulldown","bp":"back","eq":"cable","tg":"lats","mg":"biceps","sm":["biceps","rhomboids","core"],"st":["Kneel facing the cable stack and grab the handle with one hand.","Sit tall with your chest up.","Pull the handle down toward your shoulder.","Squeeze your lat at the bottom.","Let the arm rise back up slowly.","Finish your reps, then switch arms."],"img":"opengym/4948.webp","gif":null,"ext":1},{"id":"4949","n":"bodyweight forward lunge (hinge at hips)","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","core"],"st":["Stand tall with feet hip width.","Step forward into a lunge.","Hinge your torso forward at the hips.","Lower until both knees are bent.","Push off the front foot to return.","Alternate legs."],"img":"opengym/4949.webp","gif":null,"ext":1},{"id":"4950","n":"bodyweight forward lunge (smaller stance upright torso)","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","core"],"st":["Stand tall with hands on your hips.","Take a short step forward.","Lower straight down, keeping your torso upright.","Keep the front knee over the ankle.","Push through the front foot to stand.","Alternate legs."],"img":"opengym/4950.webp","gif":null,"ext":1},{"id":"4951","n":"lever pendulum squat (plate loaded)","bp":"upper legs","eq":"leverage machine","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","adductors"],"st":["Load the machine and step onto the platform.","Place your shoulders under the pads.","Unlock the machine and lower in a controlled squat.","Go as deep as comfortable.","Push through your feet to stand.","Keep your chest up and heels down."],"img":"opengym/4951.webp","gif":null,"ext":1},{"id":"4957","n":"lying lat pulldown","bp":"back","eq":"cable","tg":"lats","mg":"biceps","sm":["biceps","rhomboids","rear deltoids"],"st":["Lie on a bench under a high pulley.","Grab the bar overhand.","Pull the bar down toward your chest.","Squeeze your lats.","Return slowly with straight arms.","Keep your core braced."],"img":"opengym/4957.webp","gif":null,"ext":1},{"id":"4958","n":"cable overhead single arm triceps extension (rope attachment)","bp":"upper arms","eq":"cable","tg":"triceps","mg":"shoulders","sm":["shoulders","core"],"st":["Hold a rope with one hand overhead and face away from the stack.","Keep your upper arm close to your head.","Extend your elbow until the arm is straight.","Squeeze the triceps.","Lower slowly.","Finish reps, then switch arms."],"img":"opengym/4958.webp","gif":null,"ext":1},{"id":"4959","n":"lunge thighs (form check)","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings"],"st":["Stand tall with feet hip width.","Step forward into a lunge.","Keep your front knee over your ankle.","Keep your torso upright.","Push back up to the start.","Compare with the incorrect position to correct your form."],"img":"opengym/4959.webp","gif":null,"ext":1},{"id":"4960","n":"cable high triceps extension","bp":"upper arms","eq":"cable","tg":"triceps","mg":"shoulders","sm":["shoulders","core"],"st":["Set the cable high and face it.","Hold the attachment with elbows bent.","Press down by extending your elbows.","Squeeze at the bottom.","Return slowly.","Keep your elbows near your sides."],"img":"opengym/4960.webp","gif":null,"ext":1},{"id":"4961","n":"dumbbell prone triceps kickback","bp":"upper arms","eq":"dumbbell","tg":"triceps","mg":"shoulders","sm":["shoulders","upper back"],"st":["Lie face down on an incline bench holding dumbbells.","Bend your elbows to 90 degrees and keep your upper arms close.","Extend your elbows until your arms are straight.","Squeeze the triceps.","Lower slowly.","Keep your upper arms still."],"img":"opengym/4961.webp","gif":null,"ext":1},{"id":"4962","n":"barbell box squat","bp":"upper legs","eq":"barbell","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","lower back"],"st":["Place a box behind you and a barbell on your upper back.","Push your hips back and sit onto the box.","Pause briefly without relaxing.","Drive through your feet to stand.","Keep your chest up.","Keep your knees tracking over your toes."],"img":"opengym/4962.webp","gif":null,"ext":1},{"id":"4963","n":"kettlebell box squat","bp":"upper legs","eq":"kettlebell","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","core"],"st":["Stand in front of a box holding a kettlebell at your chest.","Push your hips back and sit onto the box.","Pause briefly.","Drive through your feet to stand.","Keep your chest up.","Keep your elbows close."],"img":"opengym/4963.webp","gif":null,"ext":1},{"id":"4964","n":"jump shrug","bp":"upper legs","eq":"barbell","tg":"glutes","mg":"trapezius","sm":["trapezius","quadriceps","calves"],"st":["Stand holding a barbell at hip height.","Dip slightly with your knees.","Jump explosively and extend fully.","Shrug your shoulders at the top.","Land softly with bent knees.","Keep the bar close to your body."],"img":"opengym/4964.webp","gif":null,"ext":1},{"id":"4965","n":"jump box v. 2","bp":"upper legs","eq":"body weight","tg":"quads","mg":"glutes","sm":["glutes","calves","hamstrings"],"st":["Stand facing a box with feet shoulder width.","Dip and swing your arms back.","Jump onto the box with both feet.","Land softly with bent knees.","Stand tall on the box.","Step down carefully."],"img":"opengym/4965.webp","gif":null,"ext":1},{"id":"4966","n":"press under","bp":"shoulders","eq":"barbell","tg":"delts","mg":"triceps","sm":["triceps","upper back","core","glutes"],"st":["Hold a barbell overhead with a wide grip.","Press up so your arms lock out.","Drop into a squat while keeping the bar overhead.","Keep your arms locked.","Stand up tall.","Keep your core braced."],"img":"opengym/4966.webp","gif":null,"ext":1},{"id":"4967","n":"lateral raise arms (form check)","bp":"shoulders","eq":"dumbbell","tg":"delts","mg":"trapezius","sm":["trapezius","rear deltoids"],"st":["Stand tall with dumbbells at your sides.","Raise your arms out to the sides.","Stop at shoulder height.","Lower slowly.","Keep a slight bend in your elbows.","Compare with the incorrect position to correct your form."],"img":"opengym/4967.webp","gif":null,"ext":1},{"id":"4968","n":"quadruped leg curl","bp":"upper legs","eq":"body weight","tg":"hamstrings","mg":"glutes","sm":["glutes","calves","core"],"st":["Get on all fours with your hands under your shoulders.","Brace your core.","Curl one heel toward your glutes.","Squeeze the hamstring.","Lower slowly.","Finish reps, then switch legs."],"img":"opengym/4968.webp","gif":null,"ext":1},{"id":"4970","n":"assisted chin up (squat position)","bp":"back","eq":"assisted","tg":"lats","mg":"biceps","sm":["biceps","upper back","forearms"],"st":["Grab a bar with an underhand grip.","Bend your knees into a squat position.","Pull your chest toward the bar.","Use your legs only as much as you need.","Lower slowly.","Keep your shoulders down."],"img":"opengym/4970.webp","gif":null,"ext":1},{"id":"4971","n":"bodyweight single leg rdl","bp":"upper legs","eq":"body weight","tg":"hamstrings","mg":"glutes","sm":["glutes","lower back","core"],"st":["Stand on one leg with a slight bend in the knee.","Hinge forward as the other leg lifts behind you.","Keep your back flat.","Lower until you feel a hamstring stretch.","Squeeze your glutes to stand.","Finish reps, then switch legs."],"img":"opengym/4971.webp","gif":null,"ext":1},{"id":"4972","n":"decline sit up and russian twist","bp":"waist","eq":"body weight","tg":"obliques","mg":"abdominals","sm":["abdominals","hip flexors"],"st":["Lie on a decline bench with your feet secured.","Sit up toward your knees.","Twist your torso to one side at the top.","Twist to the other side.","Lower slowly to the bench.","Keep your movements controlled."],"img":"opengym/4972.webp","gif":null,"ext":1},{"id":"4973","n":"dumbbell incline biceps curl (70 degrees)","bp":"upper arms","eq":"dumbbell","tg":"biceps","mg":"brachialis","sm":["brachialis","forearms"],"st":["Set a bench to 70 degrees and sit back with a dumbbell in each hand.","Let your arms hang by your sides, palms forward.","Curl the weights up without moving your elbows.","Squeeze your biceps at the top.","Lower slowly to a full stretch.","Keep your back against the bench."],"img":"opengym/4973.webp","gif":null,"ext":1},{"id":"4974","n":"inverted row slide on floor","bp":"back","eq":"body weight","tg":"upper back","mg":"lats","sm":["lats","biceps","rear deltoids","core"],"st":["Lie under a bar or lower support with sliders under your heels.","Grab the bar overhand.","Pull your chest toward the bar.","Keep your body straight.","Lower slowly.","Keep your hips up."],"img":"opengym/4974.webp","gif":null,"ext":1},{"id":"4975","n":"lying leg raise v. 3","bp":"waist","eq":"body weight","tg":"abs","mg":"hip flexors","sm":["hip flexors","lower abs"],"st":["Lie on your back with legs straight and arms by your sides.","Press your lower back gently into the floor.","Lift both legs together until they point to the ceiling.","Lower them slowly, stopping before your back arches.","Keep your legs as straight as you comfortably can.","Breathe steadily through each rep."],"img":"opengym/4975.webp","gif":null,"ext":1},{"id":"4976","n":"mountain climber jump","bp":"cardio","eq":"body weight","tg":"cardiovascular system","mg":"core","sm":["core","quadriceps","shoulders","hip flexors"],"st":["Start in a high plank.","Drive one knee toward your chest.","Switch legs with a small jump.","Keep your hips low.","Maintain a fast, steady pace.","Rest when your form slips."],"img":"opengym/4976.webp","gif":null,"ext":1},{"id":"4977","n":"ring alternate superman","bp":"waist","eq":"suspension trainer","tg":"spine","mg":"glutes","sm":["glutes","rear deltoids","core"],"st":["Put your feet in the rings and get into a face-down plank.","Brace your core and keep your hips level.","Lift one arm forward while holding steady.","Return it and switch to the other arm.","Avoid letting your lower back sag.","Alternate sides for the full set."],"img":"opengym/4977.webp","gif":null,"ext":1},{"id":"4978","n":"ring kneeling ab rollout","bp":"waist","eq":"suspension trainer","tg":"abs","mg":"lats","sm":["lats","shoulders","lower abs","hip flexors"],"st":["Kneel and hold the rings at about knee height with a firm grip.","Brace your abs and keep a straight line from head to knees.","Roll the rings forward by extending your arms until you are long but still in control.","Pull the rings back toward your knees by contracting your abs.","Do not let your lower back sag at any point."],"img":"opengym/4978.webp","gif":null,"ext":1},{"id":"4979","n":"ring rollout","bp":"waist","eq":"suspension trainer","tg":"abs","mg":"core","sm":["core","shoulders","lats"],"st":["Kneel holding rings under your shoulders.","Brace your core and tuck your pelvis.","Roll your arms forward, extending your body.","Go as far as you can with a flat back.","Pull back to the start using your abs.","Keep your ribs down."],"img":"opengym/4979.webp","gif":null,"ext":1},{"id":"4980","n":"reverse flutter kick on floor (hand under head) v. 2","bp":"waist","eq":"body weight","tg":"abs","mg":"lower abs","sm":["lower abs","hip flexors","quadriceps"],"st":["Lie on your back with your hands under your head and legs extended.","Lift both heels a few inches off the floor and press your lower back down.","Kick one leg up higher while the other goes down, then switch in a steady rhythm.","Keep your legs fairly straight and your core tight.","Stop the set when your lower back starts to arch."],"img":"opengym/4980.webp","gif":null,"ext":1},{"id":"4981","n":"barbell close grip biceps curl","bp":"upper arms","eq":"barbell","tg":"biceps","mg":"brachialis","sm":["brachialis","forearms"],"st":["Stand holding a barbell with an underhand grip, hands closer than shoulder width.","Keep your elbows tucked against your sides.","Curl the bar up toward your shoulders without swinging.","Squeeze your biceps at the top for a moment.","Lower the bar slowly until your arms are straight."],"img":"opengym/4981.webp","gif":null,"ext":1},{"id":"4982","n":"negative dragon flag","bp":"waist","eq":"body weight","tg":"abs","mg":"lower abs","sm":["lower abs","hip flexors","lats","lower back"],"st":["Lie on a bench and grip the edge behind your head.","Raise your body into a straight vertical line on your upper back.","Lower your body slowly as one stiff plank, keeping hips from bending.","Stop just above the bench with your core tight.","Bend your knees to return to the start, then repeat."],"img":"opengym/4982.webp","gif":null,"ext":1},{"id":"4983","n":"top pull up hold","bp":"back","eq":"body weight","tg":"lats","mg":"biceps","sm":["biceps","forearms","grip muscles"],"st":["Grab a pull-up bar and pull yourself up.","Bring your chin above the bar.","Squeeze your shoulder blades down and back.","Hold for 5-15 seconds.","Lower yourself slowly.","Keep your body still."],"img":"opengym/4983.webp","gif":null,"ext":1},{"id":"4984","n":"kneeling modified hindu push up","bp":"chest","eq":"body weight","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders","upper chest","lower back"],"st":["Start on your knees and hands with hips high, like a pike.","Bend your elbows and swoop your chest down and forward close to the floor.","Push through your arms to glide your chest up and forward, arching slightly.","Reverse the path, pushing your hips back up to the start.","Move smoothly and keep your core engaged."],"img":"opengym/4984.webp","gif":null,"ext":1},{"id":"4985","n":"band assisted floor glute ham raise","bp":"upper legs","eq":"band","tg":"hamstrings","mg":"glutes","sm":["glutes","calves","lower back"],"st":["Anchor a band at head height and loop it around your chest or hold it to your chest.","Kneel with your feet held firmly under a stable object.","Lower your torso forward slowly with a straight line from knees to head.","Pull yourself back up with your hamstrings and glutes, using the band to help.","Keep your hips extended throughout."],"img":"opengym/4985.webp","gif":null,"ext":1},{"id":"4986","n":"dumbbell step up v. 2","bp":"upper legs","eq":"dumbbell","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","calves"],"st":["Hold a dumbbell in each hand and stand facing a sturdy bench.","Place one foot fully on the bench.","Drive through that heel to stand up tall on the bench.","Lower your trailing foot back down under control.","Finish your reps, then switch legs."],"img":"opengym/4986.webp","gif":null,"ext":1},{"id":"4987","n":"lying leg figure eight","bp":"waist","eq":"body weight","tg":"abs","mg":"lower abs","sm":["lower abs","hip flexors","obliques","adductors"],"st":["Lie on your back with your hands under your hips and legs lifted.","Press your lower back into the floor.","Trace a figure eight in the air with your feet, slowly and in control.","Keep your legs close together.","Change direction halfway through the set."],"img":"opengym/4987.webp","gif":null,"ext":1},{"id":"4988","n":"inverse leg curl with bench pads","bp":"upper legs","eq":"body weight","tg":"hamstrings","mg":"glutes","sm":["glutes","calves","core"],"st":["Anchor your ankles under the bench pads and kneel upright.","Cross your arms or hold them in front of you.","Lean forward slowly from the knees, keeping hips and torso in a straight line.","Lower as far as you can control.","Pull yourself back up with your hamstrings."],"img":"opengym/4988.webp","gif":null,"ext":1},{"id":"4989","n":"v sit cross punch","bp":"waist","eq":"body weight","tg":"abs","mg":"obliques","sm":["obliques","hip flexors","shoulders","triceps"],"st":["Sit with knees bent and lean back, lifting your feet off the floor.","Raise your fists in front of your chest.","Punch one arm across your body while twisting your torso.","Return to center and punch with the other arm.","Keep your chest tall and your balance steady."],"img":"opengym/4989.webp","gif":null,"ext":1},{"id":"4990","n":"knee tuck oblique crunch","bp":"waist","eq":"body weight","tg":"obliques","mg":"hip flexors","sm":["hip flexors","lower abs"],"st":["Lie on your back with your hands behind your head.","Lift your shoulders off the floor.","Tuck one knee in while rotating your opposite elbow toward it.","Return and repeat to the other side.","Move with control instead of pulling on your neck."],"img":"opengym/4990.webp","gif":null,"ext":1},{"id":"4991","n":"side plank rotation","bp":"waist","eq":"body weight","tg":"obliques","mg":"shoulders","sm":["shoulders","core","glutes"],"st":["Set up in a side plank on one forearm or hand with your top arm raised.","Lift your hips so your body is in a straight line.","Thread your top arm under your torso, rotating your chest toward the floor.","Rotate back and reach the arm up to the ceiling.","Complete your reps, then switch sides."],"img":"opengym/4991.webp","gif":null,"ext":1},{"id":"4992","n":"opposite crunch","bp":"waist","eq":"body weight","tg":"abs","mg":"obliques","sm":["obliques","hip flexors"],"st":["Lie on your back with hands lightly behind your head.","Lift one leg bent while curling your torso up.","Bring the opposite elbow toward the raised knee.","Lower slowly with control.","Alternate sides on each rep."],"img":"opengym/4992.webp","gif":null,"ext":1},{"id":"4994","n":"lying leg cross","bp":"waist","eq":"body weight","tg":"abs","mg":"lower abs","sm":["lower abs","adductors","hip flexors"],"st":["Lie on your back with your hands by your sides.","Lift both legs a little off the floor with your lower back pressed down.","Open them wide, then cross one leg over the other.","Open again and cross with the other leg on top.","Keep your core tight throughout."],"img":"opengym/4994.webp","gif":null,"ext":1},{"id":"5001","n":"dumbbell seated external shoulder rotation","bp":"shoulders","eq":"dumbbell","tg":"delts","mg":"rotator cuff","sm":["rotator cuff","rear deltoids"],"st":["Sit holding a light dumbbell with your elbow bent to 90 degrees and tucked to your side.","Rest your arm on your thigh or a pad for support.","Rotate your forearm upward and outward, keeping the elbow in place.","Pause briefly at the top.","Lower slowly, then switch arms after your reps."],"img":"opengym/5001.webp","gif":null,"ext":1},{"id":"5002","n":"dumbbell one arm y elevation","bp":"shoulders","eq":"dumbbell","tg":"delts","mg":"trapezius","sm":["trapezius","rotator cuff","upper back"],"st":["Hold a light dumbbell in one hand and hinge slightly or lie chest down on an incline bench.","Start with your arm hanging down.","Raise your arm diagonally overhead to form a Y with your thumb up.","Pause at the top.","Lower slowly, finish your reps, and switch sides."],"img":"opengym/5002.webp","gif":null,"ext":1},{"id":"5003","n":"standing single leg calf raise (on a staircase)","bp":"lower legs","eq":"body weight","tg":"calves","mg":"soleus","sm":["soleus","ankles","feet"],"st":["Stand on the edge of a stair on one foot, holding the rail for balance.","Let your heel drop below the step.","Rise up onto your toes as high as you can.","Pause at the top.","Lower slowly, then switch legs after your set."],"img":"opengym/5003.webp","gif":null,"ext":1},{"id":"5004","n":"suspension sumo squat","bp":"upper legs","eq":"suspension trainer","tg":"glutes","mg":"adductors","sm":["adductors","quadriceps","core"],"st":["Stand facing the anchor holding the handles with a wide stance.","Turn your toes out slightly.","Sit your hips down, keeping knees over toes.","Use the straps lightly for balance.","Push through your heels to stand.","Squeeze your glutes at the top."],"img":"opengym/5004.webp","gif":null,"ext":1},{"id":"5005","n":"band seated underhand grip row","bp":"back","eq":"band","tg":"upper back","mg":"lats","sm":["lats","biceps","rhomboids","rear deltoids"],"st":["Sit with your legs extended and the band looped around your feet.","Hold the band ends with an underhand grip, arms straight.","Pull your hands toward your lower ribs, keeping elbows close.","Squeeze your shoulder blades together.","Return slowly to the start."],"img":"opengym/5005.webp","gif":null,"ext":1},{"id":"5006","n":"suspension underhand grip inverted row","bp":"back","eq":"suspension trainer","tg":"upper back","mg":"lats","sm":["lats","biceps","rhomboids"],"st":["Hold the handles palms up and lean back with a straight body.","Brace your core.","Pull your chest toward your hands.","Squeeze your shoulder blades together.","Lower yourself slowly.","Walk your feet forward to make it harder."],"img":"opengym/5006.webp","gif":null,"ext":1},{"id":"5007","n":"suspension hammer curl","bp":"upper arms","eq":"suspension trainer","tg":"biceps","mg":"brachialis","sm":["brachialis","forearms"],"st":["Hold the handles with palms facing each other and lean back.","Keep your body in a straight line.","Curl your hands toward your head.","Keep your elbows high and still.","Lower slowly until arms are straight.","Keep your core tight."],"img":"opengym/5007.webp","gif":null,"ext":1},{"id":"5008","n":"suspension chin up","bp":"back","eq":"suspension trainer","tg":"lats","mg":"biceps","sm":["biceps","upper back","forearms"],"st":["Hold the handles palms facing you and lean back.","Brace your core and keep your body straight.","Pull your chest toward the handles.","Squeeze your elbows close to your sides.","Lower under control.","Adjust your foot position to change difficulty."],"img":"opengym/5008.webp","gif":null,"ext":1},{"id":"5009","n":"elevated standing calf raise v. 2","bp":"lower legs","eq":"body weight","tg":"calves","mg":"soleus","sm":["soleus","ankles","feet"],"st":["Stand with the balls of your feet on a step and your heels hanging off.","Hold something for balance.","Rise high onto your toes.","Pause and squeeze your calves.","Lower your heels below the step slowly."],"img":"opengym/5009.webp","gif":null,"ext":1},{"id":"5010","n":"barbell pause decline bench press","bp":"chest","eq":"barbell","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders"],"st":["Lie on a decline bench and grip the bar slightly wider than shoulders.","Unrack the bar and lower it to your lower chest.","Hold the bar still on your chest for a full second.","Press the bar up powerfully until your arms are straight.","Keep your feet secured and shoulder blades tight."],"img":"opengym/5010.webp","gif":null,"ext":1},{"id":"5011","n":"barbell pause incline bench press","bp":"chest","eq":"barbell","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders"],"st":["Lie on an incline bench and grip the bar slightly wider than shoulders.","Unrack the bar and lower it to your upper chest.","Hold the bar still on your chest for a full second.","Press up until your arms are straight.","Keep your shoulder blades pulled back."],"img":"opengym/5011.webp","gif":null,"ext":1},{"id":"5013","n":"barbell pause bench press","bp":"chest","eq":"barbell","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders"],"st":["Lie on a flat bench with your eyes under the bar and feet planted.","Lower the bar to your mid chest with control.","Pause for a second with the bar resting lightly.","Press up explosively until your arms lock.","Keep your shoulder blades pinched throughout."],"img":"opengym/5013.webp","gif":null,"ext":1},{"id":"5014","n":"barbell pause deadlift","bp":"upper legs","eq":"barbell","tg":"glutes","mg":"hamstrings","sm":["hamstrings","lower back","quadriceps","grip muscles","trapezius"],"st":["Stand with the bar over midfoot and grip just outside your legs.","Brace your core and flatten your back.","Lift the bar a few inches and hold the pause for a second.","Keep your back flat, then drive through your legs to stand tall.","Lower the bar under control."],"img":"opengym/5014.webp","gif":null,"ext":1},{"id":"5017","n":"pause squat","bp":"upper legs","eq":"barbell","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","adductors","lower back","core"],"st":["Set the bar on your upper back and stand shoulder width apart.","Brace your core and squat down to depth.","Pause in the bottom for about two seconds, staying tight.","Drive up through your whole foot.","Keep your chest up and knees tracking over your toes."],"img":"opengym/5017.webp","gif":null,"ext":1},{"id":"5023","n":"weighted seated leg raise on floor","bp":"waist","eq":"weighted","tg":"abs","mg":"hip flexors","sm":["hip flexors","lower abs","quadriceps"],"st":["Sit on the floor with your hands behind you and weight secured to your legs or between your feet.","Lean back slightly and brace your core.","Raise your legs up while keeping them as straight as you can.","Lower them slowly without touching the floor.","Keep your back from rounding too far."],"img":"opengym/5023.webp","gif":null,"ext":1},{"id":"5024","n":"resistance band serratus wall slide","bp":"back","eq":"resistance band","tg":"serratus anterior","mg":"trapezius","sm":["trapezius","shoulders","rotator cuff"],"st":["Stand facing a wall with a band around your forearms just below the elbows.","Place your forearms on the wall and push slightly outward against the band.","Slide your arms up the wall, reaching overhead.","Keep your ribs down and shoulder blades moving freely.","Slide back down slowly."],"img":"opengym/5024.webp","gif":null,"ext":1},{"id":"5025","n":"serratus wall slide","bp":"back","eq":"body weight","tg":"serratus anterior","mg":"trapezius","sm":["trapezius","shoulders","rotator cuff"],"st":["Stand facing a wall with your forearms resting on it.","Keep your elbows at shoulder width.","Press into the wall and slide your arms up as high as you can.","Keep your ribs down and neck relaxed.","Slide back down slowly and repeat."],"img":"opengym/5025.webp","gif":null,"ext":1},{"id":"5026","n":"resistance band serratus wall slide with foam roll","bp":"back","eq":"resistance band","tg":"serratus anterior","mg":"trapezius","sm":["trapezius","shoulders","rotator cuff"],"st":["Put a band around your forearms and place a foam roller on the wall under them.","Press your forearms into the roller and push slightly out against the band.","Roll the roller up the wall as you reach overhead.","Keep your ribs down and shoulders away from your ears.","Roll back down slowly."],"img":"opengym/5026.webp","gif":null,"ext":1},{"id":"5027","n":"foam roll serratus wall slide","bp":"back","eq":"roller","tg":"serratus anterior","mg":"trapezius","sm":["trapezius","shoulders","rotator cuff"],"st":["Stand facing a wall with a foam roller under your forearms against the wall.","Press your forearms firmly into the roller.","Roll the roller up the wall as you reach overhead.","Keep your core braced and neck relaxed.","Roll back down under control."],"img":"opengym/5027.webp","gif":null,"ext":1},{"id":"5028","n":"dumbbell goblet split squat v. 2","bp":"upper legs","eq":"dumbbell","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","adductors","core"],"st":["Hold a dumbbell vertically at your chest and step into a long split stance.","Keep your torso upright.","Lower your back knee toward the floor.","Drive through your front heel to stand back up.","Finish your reps, then switch legs."],"img":"opengym/5028.webp","gif":null,"ext":1},{"id":"5029","n":"kneeling back rotation","bp":"back","eq":"body weight","tg":"spine","mg":"obliques","sm":["obliques","core","shoulders"],"st":["Kneel on all fours with one hand behind your head.","Keep your hips still and your core lightly braced.","Rotate your elbow down toward the other arm, then open toward the ceiling.","Follow the elbow with your eyes.","Do your reps, then switch sides."],"img":"opengym/5029.webp","gif":null,"ext":1},{"id":"5030","n":"push up jack","bp":"chest","eq":"body weight","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders","core","calves"],"st":["Start in a high plank with your feet together.","Lower into a push up with control.","Push back up and jump your feet wide.","Jump your feet back together.","Keep your body straight and move rhythmically."],"img":"opengym/5030.webp","gif":null,"ext":1},{"id":"5031","n":"medicine ball lying leg raise","bp":"waist","eq":"medicine ball","tg":"abs","mg":"hip flexors","sm":["hip flexors","lower abs","quadriceps"],"st":["Lie on your back with a medicine ball squeezed between your feet.","Press your lower back into the floor.","Raise your legs until they are vertical.","Lower them slowly without letting your back arch.","Keep your grip on the ball firm."],"img":"opengym/5031.webp","gif":null,"ext":1},{"id":"5032","n":"leg raise oblique crunch","bp":"waist","eq":"body weight","tg":"obliques","mg":"hip flexors","sm":["hip flexors","lower abs"],"st":["Lie on your back with your hands behind your head.","Lift your legs together toward the ceiling.","Crunch your shoulders up and toward one side as the legs tilt the other way.","Lower and repeat to the other side.","Keep movements slow and controlled."],"img":"opengym/5032.webp","gif":null,"ext":1},{"id":"5033","n":"cable single arm triceps pushdown (rope attachment)","bp":"upper arms","eq":"cable","tg":"triceps","mg":"forearms","sm":["forearms","shoulders"],"st":["Attach a rope to a high pulley and grip it with one hand.","Keep your elbow tucked at your side.","Press the rope down until your arm is straight, turning the end out slightly.","Squeeze your triceps.","Return slowly, then switch arms."],"img":"opengym/5033.webp","gif":null,"ext":1},{"id":"5034","n":"landmine one arm bent over row v. 2","bp":"back","eq":"landmine","tg":"upper back","mg":"lats","sm":["lats","rhomboids","rear deltoids","biceps","lower back","forearms"],"st":["Stand over the end of a landmine bar and hinge your hips back with a flat back.","Grab the bar end or attachment with one hand.","Pull the bar up toward your hip, leading with your elbow.","Squeeze your back at the top.","Lower slowly, then switch sides."],"img":"opengym/5034.webp","gif":null,"ext":1},{"id":"5035","n":"weighted hyperextension","bp":"back","eq":"weighted","tg":"spine","mg":"glutes","sm":["glutes","hamstrings"],"st":["Set the pad at hip level on a hyperextension bench with your feet secured.","Hold a weight plate or dumbbell against your chest.","Lower your torso with a straight back.","Raise it until your body forms a straight line.","Do not overarch at the top."],"img":"opengym/5035.webp","gif":null,"ext":1},{"id":"5036","n":"exercise ball leg curl","bp":"upper legs","eq":"stability ball","tg":"hamstrings","mg":"glutes","sm":["glutes","calves","core"],"st":["Lie on your back with your heels on a stability ball.","Lift your hips into a bridge.","Curl the ball toward your glutes by bending your knees.","Extend your legs again slowly.","Keep your hips high the whole time."],"img":"opengym/5036.webp","gif":null,"ext":1},{"id":"5039","n":"silent burpee","bp":"full body","eq":"body weight","tg":"cardiovascular system","mg":"quadriceps","sm":["quadriceps","chest","core"],"st":["Stand with feet shoulder width apart.","Squat down and place your hands on the floor.","Step your feet back into a plank.","Step your feet forward to your hands.","Stand up tall.","Keep a steady pace for 30-60 seconds."],"img":"opengym/5039.webp","gif":null,"ext":1},{"id":"5040","n":"lying prone a","bp":"back","eq":"body weight","tg":"upper back","mg":"rear deltoids","sm":["rear deltoids","rhomboids","trapezius","lower back"],"st":["Lie face down with your arms out at about 45 degrees, palms down.","Rest your forehead lightly or look at the floor.","Lift your arms and chest slightly while squeezing your shoulder blades.","Hold for a second.","Lower with control and repeat."],"img":"opengym/5040.webp","gif":null,"ext":1},{"id":"5041","n":"lying prone t","bp":"back","eq":"body weight","tg":"upper back","mg":"rear deltoids","sm":["rear deltoids","rhomboids","trapezius","lower back"],"st":["Lie face down with arms straight out to the sides, thumbs up.","Keep your neck neutral.","Lift your arms off the floor by squeezing your shoulder blades.","Hold briefly.","Lower slowly."],"img":"opengym/5041.webp","gif":null,"ext":1},{"id":"5042","n":"lying prone w","bp":"back","eq":"body weight","tg":"upper back","mg":"rear deltoids","sm":["rear deltoids","rhomboids","trapezius","lower back"],"st":["Lie face down with elbows bent and hands by your head.","Keep your neck neutral.","Lift your elbows and hands off the floor, pulling the shoulder blades together.","Hold for a second.","Lower with control."],"img":"opengym/5042.webp","gif":null,"ext":1},{"id":"5043","n":"lying prone w to t","bp":"back","eq":"body weight","tg":"upper back","mg":"rear deltoids","sm":["rear deltoids","rhomboids","trapezius","lower back"],"st":["Lie face down in a W with elbows bent.","Lift your arms slightly off the floor.","Straighten your arms out to the sides into a T.","Pull back to the W while keeping your shoulder blades squeezed.","Repeat smoothly."],"img":"opengym/5043.webp","gif":null,"ext":1},{"id":"5044","n":"lying prone w to y","bp":"back","eq":"body weight","tg":"upper back","mg":"rear deltoids","sm":["rear deltoids","rhomboids","trapezius","lower back"],"st":["Lie face down in a W with elbows bent.","Lift your arms slightly off the floor.","Reach your arms forward and wide into a Y.","Pull back into the W with your shoulder blades squeezed.","Keep your neck relaxed and repeat."],"img":"opengym/5044.webp","gif":null,"ext":1},{"id":"5045","n":"reverse plank on elbows","bp":"waist","eq":"body weight","tg":"spine","mg":"glutes","sm":["glutes","hamstrings","shoulders","core"],"st":["Sit with legs extended and elbows under your shoulders.","Press into your elbows and lift your hips.","Form a straight line from head to heels.","Squeeze your glutes and breathe steadily.","Hold for 20-40 seconds."],"img":"opengym/5045.webp","gif":null,"ext":1},{"id":"5046","n":"v sit toe tap","bp":"waist","eq":"body weight","tg":"abs","mg":"hip flexors","sm":["hip flexors","obliques","shoulders"],"st":["Sit on the floor and lean back, lifting your legs into a V.","Reach both arms forward.","Crunch up and tap your toes with your fingers.","Lower slightly back while keeping your feet up.","Keep your chest open and repeat."],"img":"opengym/5046.webp","gif":null,"ext":1},{"id":"5047","n":"side bridge with bent leg","bp":"waist","eq":"body weight","tg":"obliques","mg":"glutes","sm":["glutes","shoulders","core"],"st":["Lie on your side with knees bent and your forearm under your shoulder.","Lift your hips so your body forms a line from shoulder to knee.","Keep your hips stacked and core tight.","Hold for 20-30 seconds.","Lower and switch sides."],"img":"opengym/5047.webp","gif":null,"ext":1},{"id":"5048","n":"superman w to y","bp":"back","eq":"body weight","tg":"spine","mg":"glutes","sm":["glutes","rear deltoids","upper back","trapezius","hamstrings"],"st":["Lie face down, arms in a W with elbows bent.","Lift your chest and legs slightly off the floor.","Reach your arms forward into a Y.","Return to the W while keeping the lift.","Lower fully after your reps."],"img":"opengym/5048.webp","gif":null,"ext":1},{"id":"5049","n":"superman w","bp":"back","eq":"body weight","tg":"spine","mg":"glutes","sm":["glutes","rear deltoids","upper back","trapezius","hamstrings"],"st":["Lie face down with elbows bent and hands by your head.","Squeeze your glutes.","Lift your chest, arms and legs slightly off the floor.","Pull your shoulder blades together and hold for a second.","Lower slowly."],"img":"opengym/5049.webp","gif":null,"ext":1},{"id":"5050","n":"lying alternate toe touch floor","bp":"waist","eq":"body weight","tg":"abs","mg":"obliques","sm":["obliques","hip flexors"],"st":["Lie on your back with both legs raised toward the ceiling.","Extend your arms up.","Crunch up and reach one hand toward the opposite foot.","Lower and reach with the other hand.","Keep your legs steady."],"img":"opengym/5050.webp","gif":null,"ext":1},{"id":"5051","n":"glute ham twist","bp":"waist","eq":"body weight","tg":"obliques","mg":"abdominals","sm":["abdominals","glutes","hamstrings","lower back"],"st":["Lie on your back with knees bent, feet flat and arms out wide.","Lift your hips into a bridge.","Rotate your knees and hips to one side.","Return to center and rotate to the other side.","Stay controlled and keep your shoulders on the floor."],"img":"opengym/5051.webp","gif":null,"ext":1},{"id":"5052","n":"single leg calf raise off step","bp":"lower legs","eq":"body weight","tg":"calves","mg":"soleus","sm":["soleus","ankles","feet"],"st":["Stand on one foot on the edge of a step, holding a rail for balance.","Let your heel lower below the step.","Rise as high as possible on your toes.","Pause briefly.","Lower slowly, then switch legs."],"img":"opengym/5052.webp","gif":null,"ext":1},{"id":"5054","n":"crab pose","bp":"shoulders","eq":"body weight","tg":"pectorals","mg":"shoulders","sm":["shoulders","wrist flexors","hip flexors","core"],"st":["Sit with knees bent and hands behind you, fingers pointing toward your feet.","Press into your hands and feet.","Lift your hips until your torso is flat.","Let your head relax back gently.","Hold for 20-30 seconds."],"img":"opengym/5054.webp","gif":null,"ext":1},{"id":"5055","n":"dead hang stretch","bp":"back","eq":"body weight","tg":"lats","mg":"shoulders","sm":["shoulders","grip muscles","forearms"],"st":["Grab a pull-up bar with an overhand grip, hands shoulder width apart.","Hang with your arms straight and feet off the floor.","Relax your shoulders and let your body lengthen.","Breathe steadily.","Hold for 20-30 seconds."],"img":"opengym/5055.webp","gif":null,"ext":1},{"id":"5057","n":"kneeling forward hip circles","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"hip flexors","sm":["hip flexors","core","adductors"],"st":["Kneel with your hands on your hips.","Push your hips forward slightly.","Draw large circles with your hips, leading forward and around.","Do several circles in one direction.","Switch direction and repeat."],"img":"opengym/5057.webp","gif":null,"ext":1},{"id":"5058","n":"kneeling neck stretch","bp":"neck","eq":"body weight","tg":"levator scapulae","mg":"trapezius","sm":["trapezius","sternocleidomastoid"],"st":["Kneel tall with your back straight.","Tilt your head to one side, ear toward shoulder.","Place a hand lightly on your head for a gentle pull.","Keep the opposite shoulder low.","Hold for 20-30 seconds, then switch sides."],"img":"opengym/5058.webp","gif":null,"ext":1},{"id":"5059","n":"heel press","bp":"lower legs","eq":"body weight","tg":"calves","mg":"soleus","sm":["soleus","ankles","feet"],"st":["Stand with the ball of one foot on a low step or wall, heel on the floor.","Hold something for balance.","Press your heel gently down and back.","Keep your knee straight for the calf.","Hold for 20-30 seconds, then switch legs."],"img":"opengym/5059.webp","gif":null,"ext":1},{"id":"5060","n":"prone cervical extension","bp":"neck","eq":"body weight","tg":"levator scapulae","mg":"trapezius","sm":["trapezius","upper back","sternocleidomastoid"],"st":["Lie face down with your forehead on the floor or a towel.","Keep your arms by your sides.","Slowly lift your head a few inches, keeping your chin tucked.","Pause briefly.","Lower slowly and repeat."],"img":"opengym/5060.webp","gif":null,"ext":1},{"id":"5061","n":"prone cervical extension isometric hold","bp":"neck","eq":"body weight","tg":"levator scapulae","mg":"trapezius","sm":["trapezius","upper back","sternocleidomastoid"],"st":["Lie face down with your arms by your sides.","Tuck your chin slightly.","Lift your head a few inches off the floor.","Hold steady while breathing normally.","Hold for 10-20 seconds, then lower slowly."],"img":"opengym/5061.webp","gif":null,"ext":1},{"id":"5062","n":"lying chin tucks","bp":"neck","eq":"body weight","tg":"levator scapulae","mg":"sternocleidomastoid","sm":["sternocleidomastoid","trapezius"],"st":["Lie on your back with your head resting on the floor and knees bent.","Gently draw your chin toward your throat.","Press the back of your head lightly into the floor.","Hold for 3-5 seconds.","Release and repeat."],"img":"opengym/5062.webp","gif":null,"ext":1},{"id":"5063","n":"seated chin tuck","bp":"neck","eq":"body weight","tg":"levator scapulae","mg":"sternocleidomastoid","sm":["sternocleidomastoid","upper back"],"st":["Sit tall on a chair with your shoulders relaxed and eyes forward.","Keep your chin level, not tilted up or down.","Slide your head straight back as if making a double chin.","Hold for 2-3 seconds without tensing your jaw.","Return slowly to the start and repeat for 10-12 reps."],"img":"opengym/5063.webp","gif":null,"ext":1},{"id":"5064","n":"dumbbell kneeling hold to stand clean grip","bp":"upper legs","eq":"dumbbell","tg":"glutes","mg":"quadriceps","sm":["quadriceps","core","hamstrings"],"st":["Kneel on one knee with the other foot flat in front and hold dumbbells at your shoulders.","Brace your core and keep your chest up.","Drive through the front foot to stand tall.","Lower back down under control to half kneeling.","Finish all reps, then switch legs."],"img":"opengym/5064.webp","gif":null,"ext":1},{"id":"5065","n":"dumbbell shoulder internal rotation at 90 abduction","bp":"shoulders","eq":"dumbbell","tg":"delts","mg":"rotator cuff","sm":["rotator cuff"],"st":["Lie on your side or stand with your upper arm out at 90 degrees and elbow bent 90 degrees.","Hold a light dumbbell with the forearm pointing up.","Rotate your forearm forward and down without moving the upper arm.","Pause briefly at the bottom.","Return slowly to the start, then switch arms after your reps."],"img":"opengym/5065.webp","gif":null,"ext":1},{"id":"5066","n":"dumbbell squat to overhead press","bp":"full body","eq":"dumbbell","tg":"quads","mg":"glutes","sm":["glutes","shoulders","triceps","core"],"st":["Stand with feet shoulder-width apart, dumbbells at your shoulders.","Sit your hips back and down into a squat with your chest up.","Drive up through your feet to stand.","Use that momentum to press the dumbbells overhead until your arms are straight.","Lower them to your shoulders and go into the next squat."],"img":"opengym/5066.webp","gif":null,"ext":1},{"id":"5067","n":"dumbbell incline squeeze press","bp":"chest","eq":"dumbbell","tg":"pectorals","mg":"upper chest","sm":["upper chest","triceps","shoulders"],"st":["Set a bench to a low incline and lie back with dumbbells pressed together over your chest.","Keep squeezing them against each other the whole set.","Lower them slowly to your upper chest.","Press back up until your arms are straight.","Keep your shoulder blades pinched back and feet planted."],"img":"opengym/5067.webp","gif":null,"ext":1},{"id":"5068","n":"weighted incline svend press","bp":"chest","eq":"weighted","tg":"pectorals","mg":"upper chest","sm":["upper chest","shoulders","triceps"],"st":["Set a bench to an incline and sit back with a weight plate held between your palms at chest height.","Squeeze the plate hard with both hands.","Push it straight out until your arms are extended.","Pull it back to your chest while still squeezing.","Keep your back against the pad and shoulders down."],"img":"opengym/5068.webp","gif":null,"ext":1},{"id":"5069","n":"kettlebell lunge with twist","bp":"waist","eq":"kettlebell","tg":"obliques","mg":"abdominals","sm":["abdominals","glutes","quadriceps"],"st":["Stand holding a kettlebell at chest height with both hands.","Step forward into a lunge, front knee over your ankle.","Rotate your torso toward the front leg, keeping hips square.","Turn back to center and push off the front foot to return.","Alternate legs for each rep."],"img":"opengym/5069.webp","gif":null,"ext":1},{"id":"5071","n":"kettlebell single arm overhead lunge","bp":"upper legs","eq":"kettlebell","tg":"glutes","mg":"quadriceps","sm":["quadriceps","shoulders","core","hamstrings"],"st":["Press a kettlebell overhead with one arm and keep that arm straight.","Step forward into a lunge and lower your back knee toward the floor.","Keep your ribs down and the weight stacked over your shoulder.","Push back to standing.","Finish your reps, then switch the kettlebell to the other arm."],"img":"opengym/5071.webp","gif":null,"ext":1},{"id":"5072","n":"kettlebell sit up press","bp":"waist","eq":"kettlebell","tg":"abs","mg":"shoulders","sm":["shoulders","triceps","hip flexors"],"st":["Lie on your back with your knees bent, holding a kettlebell at your chest.","Curl and sit up using your abs.","Press the kettlebell overhead as you reach the top.","Lower it back to your chest.","Roll back down slowly and repeat."],"img":"opengym/5072.webp","gif":null,"ext":1},{"id":"5073","n":"kettlebell sumo squat v. 2","bp":"upper legs","eq":"kettlebell","tg":"glutes","mg":"adductors","sm":["adductors","quadriceps","hamstrings"],"st":["Stand with feet wide and toes turned out, holding a kettlebell with both hands in front of you.","Keep your chest tall and back flat.","Sit down between your legs until your thighs are about parallel.","Push your knees out over your toes.","Drive through your heels to stand and squeeze your glutes."],"img":"opengym/5073.webp","gif":null,"ext":1},{"id":"5074","n":"landmine press","bp":"shoulders","eq":"landmine","tg":"delts","mg":"upper chest","sm":["upper chest","triceps","core"],"st":["Anchor one end of a barbell and hold the other end at your shoulder with both hands.","Stand with feet staggered and core braced.","Press the bar up and forward until your arms are straight.","Lower it back to your shoulder under control.","Keep your ribs down and avoid leaning back."],"img":"opengym/5074.webp","gif":null,"ext":1},{"id":"5075","n":"barbell muscle clean","bp":"full body","eq":"olympic barbell","tg":"traps","mg":"glutes","sm":["glutes","hamstrings","shoulders","quadriceps"],"st":["Set up over the bar with hands just outside your knees and your back flat.","Pull the bar off the floor, extending your hips and knees.","Shrug and pull the elbows high, keeping the bar close.","Rotate your elbows under and catch the bar on your shoulders without dropping into a squat.","Lower the bar back down under control."],"img":"opengym/5075.webp","gif":null,"ext":1},{"id":"5076","n":"dumbbell overhead lunge","bp":"upper legs","eq":"dumbbell","tg":"glutes","mg":"quadriceps","sm":["quadriceps","shoulders","core","hamstrings"],"st":["Press two dumbbells overhead with straight arms.","Step forward into a lunge, lowering your back knee toward the floor.","Keep your core tight and the dumbbells over your shoulders.","Push off the front foot to come back.","Alternate legs each rep."],"img":"opengym/5076.webp","gif":null,"ext":1},{"id":"5077","n":"bodyweight svend press","bp":"chest","eq":"body weight","tg":"pectorals","mg":"shoulders","sm":["shoulders","triceps"],"st":["Stand or sit tall with your palms together at chest height.","Squeeze your palms hard against each other.","Push your hands straight out in front of you.","Bring them back to your chest while still squeezing.","Keep your shoulders down and repeat."],"img":"opengym/5077.webp","gif":null,"ext":1},{"id":"5078","n":"seated chest clam","bp":"chest","eq":"body weight","tg":"pectorals","mg":"shoulders","sm":["shoulders","upper back"],"st":["Sit tall with your fingers lightly behind your head.","Start with your elbows pointing forward.","Slowly open your elbows out and back as far as is comfortable.","Squeeze your shoulder blades together.","Hold for 20-30 seconds while breathing steadily."],"img":"opengym/5078.webp","gif":null,"ext":1},{"id":"5079","n":"lying floor fly","bp":"chest","eq":"dumbbell","tg":"pectorals","mg":"shoulders","sm":["shoulders","upper chest"],"st":["Lie on your back holding dumbbells above your chest, palms facing in.","Keep a slight bend in your elbows.","Open your arms out until your upper arms touch the floor.","Squeeze your chest to bring the weights back together.","Keep your wrists straight and the motion slow."],"img":"opengym/5079.webp","gif":null,"ext":1},{"id":"5080","n":"palm up palm down rotation","bp":"shoulders","eq":"body weight","tg":"delts","mg":"rotator cuff","sm":["rotator cuff","forearms"],"st":["Stand tall and raise your arms out to your sides at shoulder height.","Turn your palms up so your thumbs point back.","Rotate them down so your thumbs point forward.","Keep your shoulders relaxed and your arms level.","Repeat smoothly for 10-15 rotations."],"img":"opengym/5080.webp","gif":null,"ext":1},{"id":"5081","n":"seated sky look","bp":"neck","eq":"body weight","tg":"levator scapulae","mg":"sternocleidomastoid","sm":["sternocleidomastoid"],"st":["Sit tall with your shoulders relaxed.","Slowly tip your head back to look up at the ceiling.","Keep your mouth closed and move only as far as feels comfortable.","Hold for 15-20 seconds.","Return your head to neutral slowly."],"img":"opengym/5081.webp","gif":null,"ext":1},{"id":"5087","n":"cable shoulder 90 degrees external rotation","bp":"shoulders","eq":"cable","tg":"delts","mg":"rotator cuff","sm":["rotator cuff","rear deltoids"],"st":["Set a cable at shoulder height and stand sideways to it.","Hold the handle with your upper arm out at 90 degrees and elbow bent 90 degrees.","Rotate your forearm up and back without moving your upper arm.","Pause, then return slowly.","Finish your reps, then switch arms."],"img":"opengym/5087.webp","gif":null,"ext":1},{"id":"5088","n":"cable shoulder internal rotation","bp":"shoulders","eq":"cable","tg":"delts","mg":"rotator cuff","sm":["rotator cuff","chest"],"st":["Set a cable at elbow height and stand sideways to it.","Hold the handle with your elbow tucked against your side at 90 degrees.","Rotate your forearm across your stomach.","Return slowly, keeping your elbow pinned.","Complete your reps, then switch sides."],"img":"opengym/5088.webp","gif":null,"ext":1},{"id":"5089","n":"cable shoulder 90 degrees internal rotation","bp":"shoulders","eq":"cable","tg":"delts","mg":"rotator cuff","sm":["rotator cuff","chest"],"st":["Set a cable at shoulder height and face away from it.","Hold the handle with your upper arm out at 90 degrees and elbow bent 90 degrees.","Rotate your forearm forward and down, keeping your upper arm still.","Pause, then return slowly.","Finish your reps, then switch arms."],"img":"opengym/5089.webp","gif":null,"ext":1},{"id":"5090","n":"cable standing row","bp":"back","eq":"cable","tg":"upper back","mg":"lats","sm":["lats","rhomboids","biceps","rear deltoids"],"st":["Set a cable at chest height and hold the handle, stepping back until there is tension.","Stand tall with your core braced.","Pull the handle toward your ribs, driving your elbows back.","Squeeze your shoulder blades together.","Return slowly until your arms are straight."],"img":"opengym/5090.webp","gif":null,"ext":1},{"id":"5091","n":"barbell reverse grip bench press","bp":"chest","eq":"barbell","tg":"pectorals","mg":"upper chest","sm":["upper chest","triceps","shoulders"],"st":["Lie on a bench and grip the bar with palms facing you, about shoulder-width.","Unrack the bar over your chest.","Lower it to your lower chest with elbows tucked.","Press it back up until your arms are straight.","Keep your feet down and shoulder blades pinched."],"img":"opengym/5091.webp","gif":null,"ext":1},{"id":"5092","n":"dumbbell single arm underhand front raise","bp":"shoulders","eq":"dumbbell","tg":"delts","mg":"upper chest","sm":["upper chest","biceps"],"st":["Stand tall with a dumbbell in one hand, palm facing forward.","Keep your core braced.","Raise the dumbbell in front of you to shoulder height.","Lower it slowly to your thigh.","Complete your reps, then switch arms."],"img":"opengym/5092.webp","gif":null,"ext":1},{"id":"5093","n":"dumbbell single arm floor press","bp":"chest","eq":"dumbbell","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders","core"],"st":["Lie on your back with your knees bent, holding a dumbbell at chest level.","Rest your other arm on the floor.","Press the dumbbell straight up until your arm is straight.","Lower it until your upper arm touches the floor.","Finish your reps, then switch arms."],"img":"opengym/5093.webp","gif":null,"ext":1},{"id":"5094","n":"landmine single arm press","bp":"shoulders","eq":"landmine","tg":"delts","mg":"triceps","sm":["triceps","upper chest","core"],"st":["Anchor a barbell and hold the free end at your shoulder with one hand.","Stand with feet staggered and core tight.","Press the bar up and forward until your arm is straight.","Lower it back to your shoulder.","Complete your reps, then switch arms."],"img":"opengym/5094.webp","gif":null,"ext":1},{"id":"5095","n":"dumbbell single arm overhead lunge","bp":"upper legs","eq":"dumbbell","tg":"glutes","mg":"quadriceps","sm":["quadriceps","shoulders","core","hamstrings"],"st":["Press a dumbbell overhead with one arm and lock it out.","Step forward into a lunge.","Lower your back knee toward the floor, keeping your torso upright.","Push through the front foot to return.","Finish your reps, then switch arms."],"img":"opengym/5095.webp","gif":null,"ext":1},{"id":"5096","n":"single arm overhead dumbbell squat","bp":"upper legs","eq":"dumbbell","tg":"quads","mg":"glutes","sm":["glutes","shoulders","core","hamstrings"],"st":["Press a dumbbell overhead with one arm and keep it locked out.","Stand with feet shoulder-width apart.","Sit your hips back and down into a squat.","Keep your ribs down and the weight over your shoulder.","Drive up to standing, then switch arms after your reps."],"img":"opengym/5096.webp","gif":null,"ext":1},{"id":"5097","n":"dumbbell single arm alternate decline bench press","bp":"chest","eq":"dumbbell","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders","core"],"st":["Lie on a decline bench holding a dumbbell in each hand over your chest.","Lower one dumbbell to the side of your chest.","Press it back up until your arm is straight.","Repeat with the other arm.","Keep your core tight and the bench-side arm steady."],"img":"opengym/5097.webp","gif":null,"ext":1},{"id":"5098","n":"dumbbell single arm alternate fly","bp":"chest","eq":"dumbbell","tg":"pectorals","mg":"shoulders","sm":["shoulders","upper chest"],"st":["Lie on a bench with a dumbbell in each hand above your chest.","Keep a soft bend in your elbows.","Lower one arm out to the side in a wide arc.","Squeeze your chest to bring it back up.","Alternate with the other arm."],"img":"opengym/5098.webp","gif":null,"ext":1},{"id":"5099","n":"kettlebell unilateral farmers walk","bp":"full body","eq":"kettlebell","tg":"forearms","mg":"grip muscles","sm":["grip muscles","obliques","trapezius","core"],"st":["Pick up a kettlebell in one hand and stand tall.","Brace your core and keep your shoulders level.","Walk with steady steps without leaning to the loaded side.","Walk for a set distance or time.","Switch hands and repeat."],"img":"opengym/5099.webp","gif":null,"ext":1},{"id":"5101","n":"dumbbell single power clean","bp":"full body","eq":"dumbbell","tg":"glutes","mg":"hamstrings","sm":["hamstrings","trapezius","shoulders","quadriceps"],"st":["Stand over a dumbbell with feet hip-width apart.","Hinge down and grip it with a flat back.","Explode up through your hips and shrug.","Pull the dumbbell up and catch it at your shoulder.","Lower it back down under control, then switch arms."],"img":"opengym/5101.webp","gif":null,"ext":1},{"id":"5105","n":"cross jump jack","bp":"full body","eq":"body weight","tg":"cardiovascular system","mg":"calves","sm":["calves","glutes","shoulders"],"st":["Stand with your feet together and arms by your sides.","Jump your feet apart while raising your arms overhead.","Jump again, crossing your legs and your arms in front of you.","Land softly on the balls of your feet.","Keep a steady rhythm and continue for 30-60 seconds."],"img":"opengym/5105.webp","gif":null,"ext":1},{"id":"5106","n":"alternate toe tap leg lift","bp":"waist","eq":"body weight","tg":"abs","mg":"lower abs","sm":["lower abs","hip flexors"],"st":["Lie on your back with both legs raised straight up.","Press your lower back into the floor.","Reach one leg up so your toes tap toward the ceiling.","Alternate legs with control.","Keep your core tight and breathe steadily."],"img":"opengym/5106.webp","gif":null,"ext":1},{"id":"5107","n":"captains chair leg raise","bp":"waist","eq":"body weight","tg":"abs","mg":"lower abs","sm":["lower abs","hip flexors","grip muscles"],"st":["Rest your forearms on the pads and press your back against the support.","Let your legs hang straight down.","Raise your knees or straight legs to hip height or higher.","Pause briefly at the top.","Lower your legs slowly without swinging."],"img":"opengym/5107.webp","gif":null,"ext":1},{"id":"5108","n":"dumbbell wood chop squat","bp":"waist","eq":"dumbbell","tg":"obliques","mg":"abdominals","sm":["abdominals","glutes","quadriceps","shoulders"],"st":["Stand with feet shoulder-width apart, holding a dumbbell with both hands by one hip.","Sit into a squat.","Stand up and swing the dumbbell diagonally across to overhead on the other side.","Rotate your torso and pivot your back foot as you go.","Return and repeat, then switch sides."],"img":"opengym/5108.webp","gif":null,"ext":1},{"id":"5118","n":"cable twist v. 2","bp":"waist","eq":"cable","tg":"obliques","mg":"core","sm":["core"],"st":["Set a cable at chest height and stand sideways to it.","Hold the handle with both hands in front of your chest.","Rotate your torso away from the cable, arms extended.","Keep your hips facing forward.","Return slowly, then switch sides after your reps."],"img":"opengym/5118.webp","gif":null,"ext":1},{"id":"5119","n":"dumbbell deadlift v. 2","bp":"upper legs","eq":"dumbbell","tg":"glutes","mg":"hamstrings","sm":["hamstrings","lower back","grip muscles","quadriceps"],"st":["Stand with feet hip-width apart, dumbbells at your sides or in front of your thighs.","Hinge at the hips and bend your knees slightly.","Lower the dumbbells along your legs with a flat back.","Drive your hips forward to stand tall.","Squeeze your glutes at the top."],"img":"opengym/5119.webp","gif":null,"ext":1},{"id":"5120","n":"cable kickback v. 2","bp":"upper legs","eq":"cable","tg":"glutes","mg":"hamstrings","sm":["hamstrings","core"],"st":["Attach an ankle strap to a low cable and hold the machine for support.","Stand tall with a slight bend in the standing knee.","Kick your working leg straight back.","Squeeze your glute at the top without arching your back.","Return slowly and switch legs after your reps."],"img":"opengym/5120.webp","gif":null,"ext":1},{"id":"5121","n":"dumbbell sumo squat","bp":"upper legs","eq":"dumbbell","tg":"glutes","mg":"adductors","sm":["adductors","quadriceps","hamstrings"],"st":["Stand with feet wide and toes turned out, holding a dumbbell with both hands in front of you.","Keep your chest tall.","Sit down until your thighs are about parallel.","Push your knees out over your toes.","Drive through your heels to stand."],"img":"opengym/5121.webp","gif":null,"ext":1},{"id":"5122","n":"barbell clean and jerk","bp":"full body","eq":"olympic barbell","tg":"traps","mg":"quadriceps","sm":["quadriceps","glutes","shoulders","triceps","hamstrings"],"st":["Set up over the bar with a flat back and hands outside your knees.","Pull the bar off the floor and catch it at your shoulders in a squat.","Stand up with the bar racked.","Dip slightly and drive the bar overhead, splitting your feet.","Recover your feet, stand tall and lower the bar under control."],"img":"opengym/5122.webp","gif":null,"ext":1},{"id":"5123","n":"cable reverse grip pulldown","bp":"back","eq":"cable","tg":"lats","mg":"biceps","sm":["biceps","upper back","rhomboids"],"st":["Sit at a pulldown station with palms facing you, hands shoulder-width apart.","Lean back slightly and keep your chest up.","Pull the bar down to your upper chest.","Squeeze your shoulder blades down and together.","Let the bar rise slowly until your arms are straight."],"img":"opengym/5123.webp","gif":null,"ext":1},{"id":"5124","n":"side jump twist","bp":"waist","eq":"body weight","tg":"obliques","mg":"abdominals","sm":["abdominals","calves","quadriceps"],"st":["Stand with your feet together and arms bent.","Jump and twist your hips and legs to one side while your shoulders face forward.","Land softly on the balls of your feet.","Jump again and twist to the other side.","Keep a steady rhythm for 30-45 seconds."],"img":"opengym/5124.webp","gif":null,"ext":1},{"id":"5126","n":"standing ab twist","bp":"waist","eq":"body weight","tg":"obliques","mg":"abdominals","sm":["abdominals"],"st":["Stand with feet shoulder-width apart, arms bent in front of your chest.","Keep your hips facing forward.","Rotate your upper body to one side.","Come back through the center and rotate the other way.","Keep a smooth rhythm for 20-30 twists."],"img":"opengym/5126.webp","gif":null,"ext":1},{"id":"5128","n":"seated back squeeze","bp":"back","eq":"body weight","tg":"upper back","mg":"rhomboids","sm":["rhomboids","rear deltoids"],"st":["Sit tall with arms at your sides or elbows bent.","Draw your shoulder blades back and together.","Hold the squeeze for 2-3 seconds.","Release slowly.","Keep your neck relaxed.","Repeat for your reps."],"img":"opengym/5128.webp","gif":null,"ext":1},{"id":"5129","n":"seated upper body rotation","bp":"waist","eq":"body weight","tg":"obliques","mg":"abdominals","sm":["abdominals","lower back"],"st":["Sit tall with arms crossed on your chest.","Keep your hips facing forward.","Rotate your torso to one side.","Return to the centre.","Rotate to the other side.","Move smoothly without forcing the twist."],"img":"opengym/5129.webp","gif":null,"ext":1},{"id":"5130","n":"triceps dip floor v. 2","bp":"upper arms","eq":"body weight","tg":"triceps","mg":"chest","sm":["chest","shoulders"],"st":["Sit on the floor with knees bent and hands behind you.","Lift your hips off the floor.","Bend your elbows to lower your hips.","Push through your palms to straighten your arms.","Keep your elbows pointing back.","Keep your shoulders away from your ears."],"img":"opengym/5130.webp","gif":null,"ext":1},{"id":"5131","n":"seated neck tap","bp":"neck","eq":"body weight","tg":"levator scapulae","mg":"sternocleidomastoid","sm":["sternocleidomastoid","upper back"],"st":["Sit tall with your shoulders relaxed.","Bring one hand up toward the side of your neck.","Tap lightly.","Switch to the other hand.","Keep your head level.","Continue at a gentle pace."],"img":"opengym/5131.webp","gif":null,"ext":1},{"id":"5132","n":"seated pulse back squeeze","bp":"back","eq":"body weight","tg":"upper back","mg":"rhomboids","sm":["rhomboids","rear deltoids"],"st":["Sit tall with elbows bent.","Draw your shoulder blades together.","Pulse your elbows back in small movements.","Keep your shoulders down.","Maintain the squeeze throughout.","Continue for 20-30 seconds."],"img":"opengym/5132.webp","gif":null,"ext":1},{"id":"5133","n":"seated behind back raise","bp":"back","eq":"body weight","tg":"upper back","mg":"rear deltoids","sm":["rear deltoids","triceps"],"st":["Sit tall with hands clasped behind your back.","Straighten your arms.","Lift your hands slightly away from your body.","Squeeze your shoulder blades together.","Lower slowly.","Keep your chest lifted."],"img":"opengym/5133.webp","gif":null,"ext":1},{"id":"5134","n":"seated ballerina","bp":"shoulders","eq":"body weight","tg":"delts","mg":"upper back","sm":["upper back","core"],"st":["Sit tall with arms by your sides.","Sweep your arms out and up in a wide arc.","Bring your hands overhead.","Lower them back with control.","Keep the movement graceful.","Repeat at an easy pace."],"img":"opengym/5134.webp","gif":null,"ext":1},{"id":"5135","n":"seated rotation stretch","bp":"waist","eq":"body weight","tg":"spine","mg":"obliques","sm":["obliques","lower back"],"st":["Sit tall with legs crossed or extended.","Place one hand behind you and the other on the opposite knee.","Rotate your torso toward the back hand.","Keep your spine long.","Hold for 20-30 seconds.","Switch sides."],"img":"opengym/5135.webp","gif":null,"ext":1},{"id":"5142","n":"smith hang clean","bp":"full body","eq":"smith machine","tg":"traps","mg":"glutes","sm":["glutes","hamstrings","shoulders","quadriceps"],"st":["Stand at the bar with it hanging at your knees, hands just outside your legs.","Keep your back flat.","Extend your hips and shrug explosively.","Pull your elbows high and catch the bar on your shoulders.","Lower the bar back to your knees and repeat."],"img":"opengym/5142.webp","gif":null,"ext":1},{"id":"5143","n":"power sled drag","bp":"full body","eq":"sled machine","tg":"hamstrings","mg":"glutes","sm":["glutes","quadriceps","calves","core"],"st":["Load a sled and attach a harness or straps.","Lean slightly forward and brace your core.","Walk with powerful steps, pushing through the balls of your feet.","Keep your back straight.","Cover a set distance, then rest and repeat."],"img":"opengym/5143.webp","gif":null,"ext":1},{"id":"5144","n":"medicine ball chest pass against wall","bp":"chest","eq":"medicine ball","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders","core"],"st":["Stand facing a wall with the ball held at your chest.","Take a small step back and set your feet.","Push the ball forcefully at the wall.","Catch it with soft elbows as it returns.","Bring it back to your chest and repeat."],"img":"opengym/5144.webp","gif":null,"ext":1},{"id":"5145","n":"posterior neck isometric","bp":"neck","eq":"body weight","tg":"levator scapulae","mg":"upper back","sm":["upper back","trapezius"],"st":["Sit or stand tall with your hands clasped behind your head.","Keep your chin level.","Press your head back into your hands without letting it move.","Hold for 5-10 seconds.","Relax and repeat a few times."],"img":"opengym/5145.webp","gif":null,"ext":1},{"id":"5146","n":"hangback bar stretch","bp":"back","eq":"body weight","tg":"lats","mg":"shoulders","sm":["shoulders","grip muscles"],"st":["Hold a bar with an overhand grip.","Lean your body back and let your arms and shoulders lengthen.","Relax your ribs and breathe slowly.","Hold for 20-30 seconds.","Step out of the stretch carefully."],"img":"opengym/5146.webp","gif":null,"ext":1},{"id":"5147","n":"resistance band assisted front rack stretch","bp":"upper legs","eq":"resistance band","tg":"quads","mg":"hip flexors","sm":["hip flexors","wrist flexors","shoulders"],"st":["Loop a band around a sturdy anchor and hold it with both hands in a front rack position.","Step back and let the band help your elbows lift.","Keep your elbows high and chest tall.","Hold for 20-30 seconds.","Release the tension slowly."],"img":"opengym/5147.webp","gif":null,"ext":1},{"id":"5148","n":"jumping single leg lunge","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","calves"],"st":["Stand in a lunge position.","Lower down, then jump explosively off your front leg.","Land softly on the same leg.","Control the next repetition, keeping your torso upright.","Switch legs after your reps."],"img":"opengym/5148.webp","gif":null,"ext":1},{"id":"5151","n":"kipping handstand push up","bp":"shoulders","eq":"body weight","tg":"delts","mg":"triceps","sm":["triceps","upper chest","core"],"st":["Kick up into a handstand against a wall.","Lower your head toward the floor under control.","Bend your hips and knees slightly, then drive them back out as you press.","Press up to lockout.","Keep your core tight and move carefully."],"img":"opengym/5151.webp","gif":null,"ext":1},{"id":"5152","n":"bodyweight kneeling hold to stand","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"quadriceps","sm":["quadriceps","core","hamstrings"],"st":["Kneel on one knee with the other foot flat in front.","Hold your arms in front of you for balance.","Drive through the front foot to stand tall.","Lower back down under control.","Finish your reps, then switch legs."],"img":"opengym/5152.webp","gif":null,"ext":1},{"id":"5153","n":"side to side hop","bp":"lower legs","eq":"body weight","tg":"calves","mg":"quadriceps","sm":["quadriceps","glutes","ankles"],"st":["Stand on one foot with a slight knee bend.","Hop sideways to the other foot.","Land softly and balance for a second.","Hop back to the first foot.","Keep your hips level and repeat for 20-30 hops."],"img":"opengym/5153.webp","gif":null,"ext":1},{"id":"5154","n":"lateral step up","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"quadriceps","sm":["quadriceps","adductors","hamstrings"],"st":["Stand sideways next to a box.","Place your near foot on the box.","Press through that foot to step up.","Lower back down slowly.","Finish your reps, then switch sides."],"img":"opengym/5154.webp","gif":null,"ext":1},{"id":"5155","n":"lateral step up with knee drive","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hip flexors","core"],"st":["Stand sideways next to a box with one foot on top.","Press through that foot to step up.","Drive your other knee up toward your chest.","Lower back down with control.","Finish your reps, then switch sides."],"img":"opengym/5155.webp","gif":null,"ext":1},{"id":"5156","n":"mountain climber slide with towel","bp":"waist","eq":"body weight","tg":"abs","mg":"shoulders","sm":["shoulders","hip flexors","quadriceps","core"],"st":["Place your feet on towels on a smooth floor and get into a plank.","Keep your core tight and shoulders over your wrists.","Slide one knee toward your chest.","Slide it back and switch legs.","Keep a steady pace and a flat back."],"img":"opengym/5156.webp","gif":null,"ext":1},{"id":"5157","n":"plank jack on elbows","bp":"waist","eq":"body weight","tg":"abs","mg":"shoulders","sm":["shoulders","glutes","hip flexors"],"st":["Get into a forearm plank with your elbows under your shoulders.","Keep your body in a straight line.","Jump your feet wide apart.","Jump them back together.","Keep your hips level and continue for 20-40 seconds."],"img":"opengym/5157.webp","gif":null,"ext":1},{"id":"5158","n":"plank jack slide with towel","bp":"waist","eq":"body weight","tg":"abs","mg":"shoulders","sm":["shoulders","adductors","groin"],"st":["Put your feet on towels on a smooth floor and get into a high plank.","Brace your core.","Slide your feet wide apart.","Slide them back together.","Keep your hips level and repeat."],"img":"opengym/5158.webp","gif":null,"ext":1},{"id":"5159","n":"plank on hands","bp":"waist","eq":"body weight","tg":"abs","mg":"obliques","sm":["obliques","shoulders","glutes"],"st":["Place your hands under your shoulders and extend your legs behind you.","Tuck your toes and lift your hips so the body forms a straight line.","Squeeze your glutes and brace your abs.","Keep your neck neutral and look at the floor.","Hold for 20-40 seconds, then lower your knees."],"img":"opengym/5159.webp","gif":null,"ext":1},{"id":"5161","n":"medicine ball throw squat with wall","bp":"shoulders","eq":"medicine ball","tg":"delts","mg":"triceps","sm":["triceps","quadriceps","glutes","core"],"st":["Stand facing a wall at arm's length and hold a medicine ball at your chest.","Squat down with your chest up and knees tracking over your toes.","Drive up explosively and throw the ball at the wall.","Catch the ball on the rebound with soft hands.","Reset your stance and repeat for controlled reps."],"img":"opengym/5161.webp","gif":null,"ext":1},{"id":"5162","n":"seated neck stretch","bp":"neck","eq":"body weight","tg":"levator scapulae","mg":"sternocleidomastoid","sm":["sternocleidomastoid","trapezius"],"st":["Sit tall on a chair with your shoulders relaxed.","Place one hand on the back of your head.","Gently guide your chin toward your chest until you feel a stretch.","Hold for 20-30 seconds while breathing slowly.","Release slowly and repeat."],"img":"opengym/5162.webp","gif":null,"ext":1},{"id":"5165","n":"plank pike slide with towel","bp":"waist","eq":"body weight","tg":"abs","mg":"shoulders","sm":["shoulders","hip flexors","obliques"],"st":["Put your toes on towels on a smooth floor and get into a straight-arm plank.","Brace your abs and keep your arms straight.","Slide your feet toward your hands as your hips rise into a pike.","Pause briefly at the top.","Slide your feet back to the plank without letting your hips drop."],"img":"opengym/5165.webp","gif":null,"ext":1},{"id":"5166","n":"single leg box jump","bp":"upper legs","eq":"body weight","tg":"quads","mg":"glutes","sm":["glutes","calves","hamstrings"],"st":["Stand facing a sturdy box on one foot.","Swing your arms and dip into a short quarter squat.","Jump up and land softly on the box on the same foot.","Stand tall, then step down carefully.","Finish all reps, then switch legs."],"img":"opengym/5166.webp","gif":null,"ext":1},{"id":"5167","n":"single leg glute bridge with external rotation","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"hamstrings","sm":["hamstrings","hip flexors","core"],"st":["Lie on your back with one knee bent and the other leg lifted.","Press through your planted heel and raise your hips.","Turn the raised knee gently outward as you hold the top.","Keep your hips level and squeeze your glutes.","Lower with control, finish your reps, then switch sides."],"img":"opengym/5167.webp","gif":null,"ext":1},{"id":"5169","n":"standing hip adduction v. 2","bp":"upper legs","eq":"body weight","tg":"adductors","mg":"inner thighs","sm":["inner thighs","groin","core"],"st":["Stand tall next to a wall or chair and hold on for balance.","Lift the outer leg slightly off the floor.","Swing it across the front of your standing leg.","Return slowly to the start without leaning.","Finish your reps, then turn around and switch legs."],"img":"opengym/5169.webp","gif":null,"ext":1},{"id":"5170","n":"kneeling pulse","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"hamstrings","sm":["hamstrings","core"],"st":["Kneel on all fours with your hands under your shoulders.","Lift one leg back with the knee bent at about 90 degrees.","Pulse the foot upward in small, controlled movements.","Keep your hips square and your back flat.","Finish the set, then switch legs."],"img":"opengym/5170.webp","gif":null,"ext":1},{"id":"5172","n":"arm crossover","bp":"chest","eq":"body weight","tg":"pectorals","mg":"shoulders","sm":["shoulders","upper chest"],"st":["Stand tall with your arms out to the sides at shoulder height.","Swing both arms forward and cross them in front of your chest.","Open them back out and squeeze your shoulder blades slightly.","Alternate which arm is on top.","Keep a steady, relaxed rhythm."],"img":"opengym/5172.webp","gif":null,"ext":1},{"id":"5173","n":"bodyweight standing fly","bp":"chest","eq":"body weight","tg":"pectorals","mg":"shoulders","sm":["shoulders","upper chest","core"],"st":["Stand with your feet hip-width apart and your arms out wide with slightly bent elbows.","Brace your core and keep your chest proud.","Sweep your arms together in front of your chest.","Squeeze your pecs hard for a second.","Open your arms back out with control."],"img":"opengym/5173.webp","gif":null,"ext":1},{"id":"5174","n":"wall pulse","bp":"upper arms","eq":"body weight","tg":"triceps","mg":"chest","sm":["chest","shoulders"],"st":["Stand facing a wall and place your hands on it, close together at chest height.","Step your feet back so your body leans in a straight line.","Bend your elbows slightly to bring your chest toward the wall.","Pulse in short, controlled movements.","Keep your elbows tucked and your core tight."],"img":"opengym/5174.webp","gif":null,"ext":1},{"id":"5178","n":"lever single leg extension (plate loaded)","bp":"upper legs","eq":"leverage machine","tg":"quads","mg":"hip flexors","sm":["hip flexors"],"st":["Sit in the machine and adjust the pad to rest on your lower shin.","Place one foot under the pad and keep the other planted.","Extend your knee until your leg is almost straight.","Pause briefly and squeeze your quads.","Lower slowly, finish your reps, then switch legs."],"img":"opengym/5178.webp","gif":null,"ext":1},{"id":"5179","n":"cable standing close grip row","bp":"back","eq":"cable","tg":"upper back","mg":"lats","sm":["lats","rhomboids","biceps","rear deltoids","core"],"st":["Attach a close grip handle to a cable at chest height and step back.","Stand with a slight knee bend and a braced core.","Pull the handle toward your lower ribs, elbows close to your body.","Squeeze your shoulder blades together.","Return slowly until your arms are straight."],"img":"opengym/5179.webp","gif":null,"ext":1},{"id":"5187","n":"burpee long jump with push up","bp":"full body","eq":"body weight","tg":"cardiovascular system","mg":"chest","sm":["chest","triceps","quadriceps","core"],"st":["Stand tall, then squat and place your hands on the floor.","Jump your feet back and do one push-up.","Jump your feet back toward your hands.","Explode into a long jump forward.","Land softly with bent knees and go into the next rep."],"img":"opengym/5187.webp","gif":null,"ext":1},{"id":"5188","n":"power clean thruster","bp":"full body","eq":"barbell","tg":"quads","mg":"glutes","sm":["glutes","shoulders","triceps","hamstrings","core"],"st":["Set up with the barbell over mid-foot and grip it just outside your knees.","Pull the bar explosively and catch it on your shoulders in a quarter squat.","Stand, then sink into a full front squat.","Drive up and press the bar overhead.","Lower the bar to your shoulders and then to the floor with control."],"img":"opengym/5188.webp","gif":null,"ext":1},{"id":"5190","n":"barbell clean and jerk v. 2","bp":"full body","eq":"olympic barbell","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","shoulders","triceps","upper back"],"st":["Grip the bar just outside your knees with a flat back.","Pull explosively and drop under the bar, catching it on your shoulders.","Stand up fully and reset your feet.","Dip, drive, and split your legs as you punch the bar overhead.","Recover your feet and lower the bar with control."],"img":"opengym/5190.webp","gif":null,"ext":1},{"id":"5192","n":"cluster","bp":"full body","eq":"barbell","tg":"quads","mg":"glutes","sm":["glutes","shoulders","hamstrings","triceps","core"],"st":["Start with the barbell on the floor and pull it to your shoulders in a clean.","Stand up with the bar racked on your shoulders.","Squat down into a deep front squat.","Drive up and press the bar overhead.","Lower the bar to your shoulders and repeat."],"img":"opengym/5192.webp","gif":null,"ext":1},{"id":"5193","n":"power sled rear drag v. 2","bp":"upper legs","eq":"sled machine","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","calves"],"st":["Load the sled and grip the handles or strap in front of you.","Lean slightly back with your chest up.","Walk backward in small, powerful steps.","Keep your knees soft and your core tight.","Cover your distance, then rest and repeat."],"img":"opengym/5193.webp","gif":null,"ext":1},{"id":"5194","n":"bodyweight muscle up v. 2","bp":"back","eq":"body weight","tg":"lats","mg":"biceps","sm":["biceps","triceps","chest","core"],"st":["Hang from a pull-up bar with a false or standard grip.","Pull explosively, bringing the bar toward your lower chest.","Lean forward and rotate your wrists over the bar.","Press up until your arms are fully straight.","Lower yourself back down with control."],"img":"opengym/5194.webp","gif":null,"ext":1},{"id":"5195","n":"seated neck side stretch","bp":"neck","eq":"body weight","tg":"levator scapulae","mg":"trapezius","sm":["trapezius","sternocleidomastoid"],"st":["Sit tall and relax your shoulders.","Tilt your ear toward one shoulder.","Rest your hand lightly on your head for a gentle added stretch.","Hold for 20-30 seconds.","Return to centre and switch sides."],"img":"opengym/5195.webp","gif":null,"ext":1},{"id":"5198","n":"single straight leg glute bridge hold","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"hamstrings","sm":["hamstrings","core"],"st":["Lie on your back with knees bent.","Straighten one leg.","Lift your hips with the planted foot.","Hold with hips level.","Hold for 20-30 seconds.","Lower and switch legs."],"img":"opengym/5198.webp","gif":null,"ext":1},{"id":"5203","n":"resistance band standing ab crunch","bp":"waist","eq":"resistance band","tg":"abs","mg":"obliques","sm":["obliques","hip flexors"],"st":["Anchor the band high and stand facing it with your feet hip-width apart.","Hold the handles at your head.","Bend forward by crunching your ribs toward your pelvis.","Squeeze your abs hard.","Return slowly to standing."],"img":"opengym/5203.webp","gif":null,"ext":1},{"id":"5204","n":"resistance band single arm overhead shoulder press","bp":"shoulders","eq":"resistance band","tg":"delts","mg":"triceps","sm":["triceps","upper chest","core"],"st":["Stand on the band with the handle in one hand at shoulder height.","Brace your core and keep your ribs down.","Press the handle straight overhead.","Pause at the top without leaning.","Lower with control, finish your reps, then switch arms."],"img":"opengym/5204.webp","gif":null,"ext":1},{"id":"5205","n":"resistance band overhead shoulder press","bp":"shoulders","eq":"resistance band","tg":"delts","mg":"triceps","sm":["triceps","upper chest","core"],"st":["Stand on the middle of the band and hold a handle in each hand at your shoulders.","Brace your abs and stand tall.","Press both handles overhead until your arms are straight.","Pause briefly.","Lower slowly back to shoulder height."],"img":"opengym/5205.webp","gif":null,"ext":1},{"id":"5213","n":"mountain climber v. 2","bp":"waist","eq":"body weight","tg":"abs","mg":"hip flexors","sm":["hip flexors","shoulders","quadriceps"],"st":["Start in a high plank with hands under shoulders.","Brace your core.","Drive one knee toward your chest.","Switch legs quickly.","Keep your hips low and level.","Continue for 20-40 seconds."],"img":"opengym/5213.webp","gif":null,"ext":1},{"id":"5214","n":"riding outdoor bicycle","bp":"cardio","eq":"body weight","tg":"cardiovascular system","mg":"quadriceps","sm":["quadriceps","hamstrings","calves","glutes"],"st":["Adjust your saddle so your leg is almost straight at the bottom of the pedal stroke.","Wear a helmet and check your brakes.","Start at an easy pace to warm up.","Pedal smoothly at a steady, comfortable rhythm for 20-60 minutes.","Cool down with a few minutes of easy pedalling."],"img":"opengym/5214.webp","gif":null,"ext":1},{"id":"5216","n":"sprint","bp":"cardio","eq":"body weight","tg":"cardiovascular system","mg":"hamstrings","sm":["hamstrings","glutes","quadriceps","calves"],"st":["Warm up well with jogging and dynamic stretches.","Start in a staggered stance and lean slightly forward.","Drive your arms and knees as you accelerate.","Run at maximum effort for 10-30 seconds.","Slow down gradually and rest fully before the next sprint."],"img":"opengym/5216.webp","gif":null,"ext":1},{"id":"5220","n":"extended side angle yoga pose","bp":"upper legs","eq":"body weight","tg":"adductors","mg":"obliques","sm":["obliques","hamstrings","glutes","groin"],"st":["Step your feet wide apart and turn one foot out.","Bend the front knee over the ankle.","Rest your forearm on your thigh and reach the other arm overhead.","Lengthen the whole side body and look up if comfortable.","Hold for 20-30 seconds and switch sides."],"img":"opengym/5220.webp","gif":null,"ext":1},{"id":"5223","n":"smith wide shrug","bp":"back","eq":"smith machine","tg":"traps","mg":"forearms","sm":["forearms","grip muscles","upper back"],"st":["Set the bar at thigh height and grip it wider than shoulder width.","Stand tall with your arms straight.","Shrug your shoulders straight up toward your ears.","Pause at the top.","Lower slowly without rolling your shoulders."],"img":"opengym/5223.webp","gif":null,"ext":1},{"id":"5224","n":"barbell wide shrug","bp":"back","eq":"barbell","tg":"traps","mg":"forearms","sm":["forearms","grip muscles","upper back"],"st":["Stand holding a barbell in front with a wide overhand grip.","Keep your arms straight and your chest up.","Lift your shoulders straight toward your ears.","Hold the top for a second.","Lower slowly under control."],"img":"opengym/5224.webp","gif":null,"ext":1},{"id":"5225","n":"smith back wide shrug","bp":"back","eq":"smith machine","tg":"traps","mg":"rhomboids","sm":["rhomboids","forearms","grip muscles"],"st":["Stand with your back to the bar, set at thigh height, and grip it wide behind you.","Lift the bar off the hooks and stand tall.","Shrug your shoulders straight up.","Pause at the top.","Lower slowly and keep your arms straight."],"img":"opengym/5225.webp","gif":null,"ext":1},{"id":"5226","n":"barbell back wide shrug","bp":"back","eq":"barbell","tg":"traps","mg":"rhomboids","sm":["rhomboids","forearms","grip muscles"],"st":["Hold a barbell behind your thighs with a wide overhand grip.","Stand tall with your chest up.","Shrug your shoulders straight up.","Squeeze at the top for a second.","Lower slowly without leaning forward."],"img":"opengym/5226.webp","gif":null,"ext":1},{"id":"5228","n":"myotatic crunch on bosu ball","bp":"waist","eq":"bosu ball","tg":"abs","mg":"obliques","sm":["obliques","hip flexors"],"st":["Lie back over a Bosu ball with your lower back supported.","Place your hands beside your head and your feet flat.","Let your torso extend gently over the ball.","Crunch up, bringing your ribs toward your hips.","Lower slowly through the full range."],"img":"opengym/5228.webp","gif":null,"ext":1},{"id":"5232","n":"dumbbell deadlift bent over row","bp":"back","eq":"dumbbell","tg":"upper back","mg":"lats","sm":["lats","rhomboids","biceps","hamstrings","glutes","lower back"],"st":["Stand holding dumbbells in front of your thighs.","Hinge at the hips with a flat back and soft knees.","Row the dumbbells toward your lower ribs.","Squeeze your shoulder blades.","Lower the weights slowly and stand back up."],"img":"opengym/5232.webp","gif":null,"ext":1},{"id":"5233","n":"cross body punch in squat position","bp":"full body","eq":"body weight","tg":"quads","mg":"glutes","sm":["glutes","obliques","shoulders","core"],"st":["Stand in a wide stance and sink into a half squat.","Keep your fists up near your chin.","Punch one arm across your body, rotating your torso.","Pull it back and punch with the other arm.","Stay low and keep a quick, controlled rhythm."],"img":"opengym/5233.webp","gif":null,"ext":1},{"id":"5234","n":"wall walks","bp":"shoulders","eq":"body weight","tg":"delts","mg":"triceps","sm":["triceps","core","upper chest"],"st":["Lie face down with your feet against a wall.","Place your hands beside your chest and push up into a plank.","Walk your feet up the wall as your hands walk toward it.","Stop where you can keep your body straight and braced.","Walk back down slowly with control."],"img":"opengym/5234.webp","gif":null,"ext":1},{"id":"5236","n":"bent arms chin up","bp":"back","eq":"body weight","tg":"lats","mg":"biceps","sm":["biceps","brachialis","rhomboids","core"],"st":["Hang from a bar with an underhand, shoulder-width grip.","Pull yourself up until your chin clears the bar.","Keep your elbows bent and your body still.","Hold briefly at the top.","Lower slowly until just short of straight arms."],"img":"opengym/5236.webp","gif":null,"ext":1},{"id":"5237","n":"single dumbbell decline overhead sit up","bp":"waist","eq":"dumbbell","tg":"abs","mg":"hip flexors","sm":["hip flexors","obliques","shoulders"],"st":["Lie on a decline bench with your feet secured.","Hold one dumbbell with both hands above your head.","Curl up and sit forward, keeping the weight overhead.","Pause at the top.","Lower slowly to the start."],"img":"opengym/5237.webp","gif":null,"ext":1},{"id":"5238","n":"medicine ball lunge with biceps curl","bp":"upper legs","eq":"medicine ball","tg":"glutes","mg":"quadriceps","sm":["quadriceps","biceps","hamstrings","core"],"st":["Stand holding a medicine ball at your thighs.","Step forward into a lunge.","Curl the ball up toward your chest as you lower.","Push back to standing while lowering the ball.","Alternate legs on each rep."],"img":"opengym/5238.webp","gif":null,"ext":1},{"id":"5239","n":"dumbbell biceps curl with overhead extension on stability ball","bp":"upper arms","eq":"dumbbell","tg":"biceps","mg":"triceps","sm":["triceps","core","forearms"],"st":["Sit tall on a stability ball holding a dumbbell.","Curl the dumbbell up with your elbow at your side.","Raise it overhead, lifting it with both hands.","Lower it behind your head for a triceps extension.","Extend, return to the front, and repeat."],"img":"opengym/5239.webp","gif":null,"ext":1},{"id":"5240","n":"ez barbell deadlift with biceps curl","bp":"upper legs","eq":"ez barbell","tg":"glutes","mg":"hamstrings","sm":["hamstrings","biceps","lower back","forearms"],"st":["Stand with an EZ bar in front of your thighs.","Hinge at the hips and lower the bar along your legs.","Stand tall by driving your hips forward.","Curl the bar up to your chest.","Lower it and repeat."],"img":"opengym/5240.webp","gif":null,"ext":1},{"id":"5241","n":"old school reverse extensions","bp":"back","eq":"body weight","tg":"spine","mg":"glutes","sm":["glutes","hamstrings"],"st":["Lie face down over a bench with your hips at the edge.","Hold the bench and keep your legs hanging down.","Lift your legs behind you until your body is straight.","Pause and squeeze your glutes.","Lower slowly without swinging."],"img":"opengym/5241.webp","gif":null,"ext":1},{"id":"5242","n":"kneeling abdominal draw in","bp":"waist","eq":"body weight","tg":"abs","mg":"obliques","sm":["obliques","lower back"],"st":["Kneel on all fours with your hands under your shoulders.","Relax your belly toward the floor.","Draw your navel up toward your spine.","Hold for 10-15 seconds while breathing normally.","Release slowly and repeat."],"img":"opengym/5242.webp","gif":null,"ext":1},{"id":"5243","n":"cable lying triceps extension (low)","bp":"upper arms","eq":"cable","tg":"triceps","mg":"forearms","sm":["forearms","shoulders"],"st":["Lie on a bench with a low pulley behind your head.","Hold the bar or rope with your arms up over your face.","Keep your upper arms still.","Bend your elbows to lower the handle toward your forehead.","Extend your arms back up."],"img":"opengym/5243.webp","gif":null,"ext":1},{"id":"5250","n":"lying bicycle crunch","bp":"waist","eq":"body weight","tg":"abs","mg":"obliques","sm":["obliques","hip flexors"],"st":["Lie on your back with your hands behind your head.","Lift your shoulders and bring your knees up.","Extend one leg while turning your opposite elbow toward the other knee.","Switch sides in a smooth pedalling motion.","Keep your lower back pressed down."],"img":"opengym/5250.webp","gif":null,"ext":1},{"id":"5261","n":"dumbbell incline shoulders press","bp":"shoulders","eq":"dumbbell","tg":"delts","mg":"triceps","sm":["triceps","upper chest"],"st":["Set a bench to about 60 to 75 degrees and sit back with a dumbbell in each hand.","Hold the weights at shoulder height.","Press the dumbbells up until your arms are straight.","Lower slowly to shoulder level.","Keep your back against the pad."],"img":"opengym/5261.webp","gif":null,"ext":1},{"id":"5265","n":"45 degree bicycle twisting crunch","bp":"waist","eq":"body weight","tg":"obliques","mg":"abdominals","sm":["abdominals","hip flexors"],"st":["Sit and lean back to about 45 degrees with your feet raised.","Place your hands behind your head.","Bring one knee in as you twist the opposite elbow toward it.","Alternate sides in a pedalling motion.","Keep your chest lifted and your core tight."],"img":"opengym/5265.webp","gif":null,"ext":1},{"id":"5266","n":"air twisting crunch","bp":"waist","eq":"body weight","tg":"obliques","mg":"abdominals","sm":["abdominals","hip flexors"],"st":["Lie on your back with your knees raised.","Place your hands behind your head.","Lift your shoulders and twist toward one knee.","Return and twist toward the other side.","Keep a slow rhythm and press your lower back down."],"img":"opengym/5266.webp","gif":null,"ext":1},{"id":"5274","n":"lying tuck crunch","bp":"waist","eq":"body weight","tg":"abs","mg":"hip flexors","sm":["hip flexors","obliques"],"st":["Lie on your back with your legs extended just off the floor.","Place your hands behind your head.","Pull your knees in and crunch your chest toward them.","Squeeze your abs at the top.","Extend and lower slowly."],"img":"opengym/5274.webp","gif":null,"ext":1},{"id":"5275","n":"lying toe touch","bp":"waist","eq":"body weight","tg":"abs","mg":"hip flexors","sm":["hip flexors","hamstrings"],"st":["Lie on your back with your legs straight up.","Reach your arms up toward your toes.","Lift your shoulders off the floor and touch your toes.","Lower your shoulders slowly.","Keep your legs steady."],"img":"opengym/5275.webp","gif":null,"ext":1},{"id":"5277","n":"bodyweight glute dominant step up","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","core"],"st":["Stand in front of a bench and place one foot on it.","Lean your torso slightly forward.","Press through your heel and step up until standing.","Lower slowly back down.","Finish your reps, then switch legs."],"img":"opengym/5277.webp","gif":null,"ext":1},{"id":"5278","n":"kneeling staggered push up","bp":"chest","eq":"body weight","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders","core"],"st":["Kneel and place your hands on the floor, one slightly forward of the other.","Keep your body straight from knees to head.","Lower your chest toward the floor.","Press back up.","Keep your elbows at about 45 degrees.","Switch hand positions on the next set."],"img":"opengym/5278.webp","gif":null,"ext":1},{"id":"5282","n":"landmine kneeling thruster press","bp":"shoulders","eq":"landmine","tg":"delts","mg":"quadriceps","sm":["quadriceps","triceps","glutes","core"],"st":["Kneel facing the landmine and hold the end of the bar at your chest.","Sit your hips back toward your heels.","Drive through your hips and press the bar up.","Straighten your arms fully at the top.","Lower back to your chest with control."],"img":"opengym/5282.webp","gif":null,"ext":1},{"id":"5284","n":"dumbbell sprinter thrust chest press","bp":"chest","eq":"dumbbell","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders","glutes","core"],"st":["Lie on a bench holding dumbbells at your chest.","Drive one knee up toward your chest.","Press the dumbbells up until your arms are straight.","Lower the dumbbells and switch legs.","Keep a steady rhythm."],"img":"opengym/5284.webp","gif":null,"ext":1},{"id":"5286","n":"standing hands position (pronation supination neutral)","bp":"lower arms","eq":"body weight","tg":"forearms","mg":"wrist flexors","sm":["wrist flexors","wrist extensors"],"st":["Stand tall with your arms hanging by your sides.","Bend your elbows and hold your forearms in front of you.","Rotate your palms down, then to neutral, then up.","Move slowly and keep your elbows still.","Repeat for several smooth rounds."],"img":"opengym/5286.webp","gif":null,"ext":1},{"id":"5287","n":"barbell full clean","bp":"full body","eq":"barbell","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","upper back","shoulders","forearms"],"st":["Stand with the bar over mid-foot and grip it just outside your knees.","Pull the bar explosively with a flat back.","Drop under the bar and catch it on your shoulders in a front squat.","Stand up fully.","Lower the bar with control to the floor."],"img":"opengym/5287.webp","gif":null,"ext":1},{"id":"5297","n":"cable kneeling preacher curl","bp":"upper arms","eq":"cable","tg":"biceps","mg":"forearms","sm":["forearms","brachialis"],"st":["Kneel in front of a bench with a low cable beside you.","Rest your upper arms on the pad.","Curl the handle up toward your shoulders.","Squeeze your biceps at the top.","Lower slowly until your arms are straight."],"img":"opengym/5297.webp","gif":null,"ext":1},{"id":"5298","n":"dumbbell preacher curl (turned torso)","bp":"upper arms","eq":"dumbbell","tg":"biceps","mg":"forearms","sm":["forearms","brachialis"],"st":["Sit at a preacher bench with a dumbbell in one hand.","Rotate your torso slightly toward the working arm.","Curl the dumbbell up to shoulder height.","Squeeze your biceps.","Lower slowly, finish your reps, then switch arms."],"img":"opengym/5298.webp","gif":null,"ext":1},{"id":"5299","n":"lever preacher curl (turned torso)","bp":"upper arms","eq":"leverage machine","tg":"biceps","mg":"forearms","sm":["forearms","brachialis"],"st":["Sit at the machine and adjust the seat so your arms rest on the pad.","Turn your torso slightly toward the working arm.","Curl the handle up toward your shoulder.","Squeeze at the top.","Lower slowly, then switch arms."],"img":"opengym/5299.webp","gif":null,"ext":1},{"id":"5301","n":"kettlebell full squat from deficit","bp":"upper legs","eq":"kettlebell","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","core"],"st":["Stand on a low platform holding a kettlebell at chest height.","Brace your core.","Sit your hips down as deep as you can.","Keep your chest up and heels down.","Drive through your feet to stand.","Keep the kettlebell close to your body."],"img":"opengym/5301.webp","gif":null,"ext":1},{"id":"5302","n":"balance board v. 2","bp":"lower legs","eq":"body weight","tg":"calves","mg":"ankles","sm":["ankles","feet","core"],"st":["Place the board on a flat, non-slip surface.","Step onto it with your feet shoulder-width apart.","Keep your knees soft and your core tight.","Tilt gently without letting the edges touch the floor.","Balance for 30-60 seconds."],"img":"opengym/5302.webp","gif":null,"ext":1},{"id":"5303","n":"dumbbell rear delt fly (45 degrees)","bp":"shoulders","eq":"dumbbell","tg":"delts","mg":"rhomboids","sm":["rhomboids","trapezius","upper back"],"st":["Set a bench to 45 degrees and lie chest down on it, a dumbbell in each hand.","Let your arms hang below you with a soft bend in the elbows.","Raise the weights out to the sides until your arms are level with your torso.","Squeeze your shoulder blades together at the top.","Lower slowly under control.","Keep your neck neutral and avoid swinging."],"img":"opengym/5303.webp","gif":null,"ext":1},{"id":"5304","n":"trap bar squat","bp":"upper legs","eq":"trap bar","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","adductors","lower back","core"],"st":["Stand inside the trap bar with feet shoulder-width apart and grip the handles.","Brace your core and keep your chest tall.","Sit your hips back and down until your thighs are about parallel.","Drive through your whole foot to stand up.","Lock out your hips at the top without leaning back.","Keep your knees tracking over your toes."],"img":"opengym/5304.webp","gif":null,"ext":1},{"id":"5307","n":"landmine one leg stiff leg deadlift","bp":"upper legs","eq":"landmine","tg":"hamstrings","mg":"glutes","sm":["glutes","lower back","core","grip muscles"],"st":["Hold the end of the landmine bar in front of you with both hands.","Stand on one leg with a slight knee bend.","Hinge at the hips and lower the bar while your free leg reaches back.","Keep your back flat and hips square.","Squeeze your glutes to return to standing.","Finish your reps, then switch legs."],"img":"opengym/5307.webp","gif":null,"ext":1},{"id":"5308","n":"ez bar russian twist sit up","bp":"waist","eq":"ez barbell","tg":"obliques","mg":"hip flexors","sm":["hip flexors","lower abs","shoulders"],"st":["Lie on your back with knees bent and hold the EZ bar over your chest.","Curl up into a sit-up position.","At the top, rotate your torso to one side, moving the bar with you.","Rotate back to center and lower yourself with control.","Alternate sides each rep.","Keep the weight light enough to move smoothly."],"img":"opengym/5308.webp","gif":null,"ext":1},{"id":"5309","n":"ez bar shoulder press sit up","bp":"waist","eq":"ez barbell","tg":"abs","mg":"shoulders","sm":["shoulders","triceps","hip flexors","lower abs"],"st":["Lie on your back with knees bent, holding the EZ bar at your chest.","Sit up while keeping the bar close to your body.","Once upright, press the bar overhead.","Lower the bar back to your chest.","Roll back down slowly to the floor.","Brace your core and avoid yanking with your neck."],"img":"opengym/5309.webp","gif":null,"ext":1},{"id":"5310","n":"elevated side lunge","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"quadriceps","sm":["quadriceps","adductors","hamstrings","inner thighs"],"st":["Stand tall next to a low step or platform.","Step one foot sideways onto the platform.","Push your hips back and bend that knee while the other leg stays straight.","Keep your chest up and the planted foot flat.","Push back to the start.","Complete your reps, then switch sides."],"img":"opengym/5310.webp","gif":null,"ext":1},{"id":"5311","n":"exercise ball serratus wall slide","bp":"back","eq":"stability ball","tg":"serratus anterior","mg":"shoulders","sm":["shoulders","trapezius","upper back"],"st":["Place a stability ball against a wall and rest your forearms on it.","Step back slightly so your body leans in.","Slide your forearms up the ball as you reach overhead.","Push into the ball and spread your shoulder blades at the top.","Slide back down slowly.","Keep your ribs down and avoid arching your lower back."],"img":"opengym/5311.webp","gif":null,"ext":1},{"id":"5312","n":"rear lunge from deficit","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","core"],"st":["Stand on a low step with your feet hip-width apart.","Step one foot back and down off the step.","Lower until the front thigh is about parallel.","Keep your torso tall and front knee stable.","Push through the front heel to return to the step.","Finish your reps, then switch legs."],"img":"opengym/5312.webp","gif":null,"ext":1},{"id":"5313","n":"dumbbell good morning squat","bp":"upper legs","eq":"dumbbell","tg":"hamstrings","mg":"glutes","sm":["glutes","quadriceps","lower back","core"],"st":["Hold a dumbbell at your chest and stand with feet shoulder-width apart.","Hinge at your hips with a flat back until you feel a hamstring stretch.","Stand back up and then sit down into a squat.","Drive up through your heels.","Repeat the hinge and squat as one rep.","Keep your chest up throughout."],"img":"opengym/5313.webp","gif":null,"ext":1},{"id":"5314","n":"dumbbell glute dominant step up","bp":"upper legs","eq":"dumbbell","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","core"],"st":["Hold a dumbbell in each hand and face a bench or box.","Place one foot fully on the box and lean your torso slightly forward.","Push through the heel of that foot to stand up.","Squeeze your glute at the top.","Lower with control.","Finish your reps, then switch legs."],"img":"opengym/5314.webp","gif":null,"ext":1},{"id":"5315","n":"cable glute dominant step up","bp":"upper legs","eq":"cable","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","core"],"st":["Hold the cable handle and stand facing a step.","Place one foot on the step.","Lean slightly forward from the hips.","Drive through the heel to stand up.","Lower slowly.","Finish your reps, then switch legs."],"img":"opengym/5315.webp","gif":null,"ext":1},{"id":"5316","n":"smith bent over narrow pronated grip row","bp":"back","eq":"smith machine","tg":"upper back","mg":"lats","sm":["lats","rhomboids","biceps","lower back","rear deltoids"],"st":["Set the bar at knee height and grip it with hands close together, palms down.","Hinge forward with a flat back and unlock the bar.","Pull the bar toward your lower ribs.","Squeeze your shoulder blades together.","Lower the bar slowly.","Keep your hips back and torso still."],"img":"opengym/5316.webp","gif":null,"ext":1},{"id":"5317","n":"resistance band pull apart (45 degrees)","bp":"shoulders","eq":"resistance band","tg":"delts","mg":"rear deltoids","sm":["rear deltoids","rhomboids","trapezius","upper back"],"st":["Hold a resistance band in both hands in front of you.","Raise your arms to about 45 degrees above horizontal.","Pull the band apart by moving your hands out to the sides.","Squeeze your shoulder blades together.","Return slowly to the start.","Keep your ribs down and your shoulders away from your ears."],"img":"opengym/5317.webp","gif":null,"ext":1},{"id":"5326","n":"lever multy mode rope lat pulldown","bp":"back","eq":"leverage machine","tg":"lats","mg":"biceps","sm":["biceps","rhomboids","upper back","grip muscles"],"st":["Sit at the machine and grab the rope handles.","Set your thighs under the pads and sit tall.","Pull the handles down toward your upper chest.","Drive your elbows down and back.","Let the handles rise slowly until your arms are straight.","Avoid leaning back too far."],"img":"opengym/5326.webp","gif":null,"ext":1},{"id":"5327","n":"lever t bar romanian deadlift","bp":"upper legs","eq":"leverage machine","tg":"hamstrings","mg":"glutes","sm":["glutes","lower back","grip muscles","core"],"st":["Stand at the T-bar lever and grip the handles.","Lift to stand with a slight bend in your knees.","Push your hips back and lower the bar along your thighs.","Stop when you feel a strong hamstring stretch.","Drive your hips forward to stand.","Keep your back flat all the way."],"img":"opengym/5327.webp","gif":null,"ext":1},{"id":"5328","n":"barbell standing shoulders press","bp":"shoulders","eq":"barbell","tg":"delts","mg":"triceps","sm":["triceps","upper chest","trapezius","core"],"st":["Hold the bar at shoulder height with hands just outside shoulder-width.","Stand tall with glutes and core braced.","Press the bar straight overhead, moving your head back slightly.","Lock out with the bar over mid-foot.","Lower the bar back to your shoulders.","Avoid leaning back."],"img":"opengym/5328.webp","gif":null,"ext":1},{"id":"5330","n":"dumbbell pullover v. 2","bp":"chest","eq":"dumbbell","tg":"pectorals","mg":"lats","sm":["lats","triceps","core"],"st":["Lie across or along a bench holding one dumbbell with both hands over your chest.","Keep a slight bend in your elbows.","Lower the dumbbell back behind your head in an arc.","Feel the stretch through your chest and lats.","Pull it back over your chest.","Keep your hips low and ribs down."],"img":"opengym/5330.webp","gif":null,"ext":1},{"id":"5332","n":"svend bench press","bp":"chest","eq":"weight plate","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders","upper chest"],"st":["Lie on a bench holding a plate between your palms at chest level.","Squeeze your palms together hard.","Press the plate straight up until your arms extend.","Keep squeezing the plate throughout.","Lower it back to your chest slowly.","Keep your feet planted."],"img":"opengym/5332.webp","gif":null,"ext":1},{"id":"5333","n":"lever trunk rotation","bp":"waist","eq":"leverage machine","tg":"obliques","mg":"lower back","sm":["lower back","core"],"st":["Sit in the machine and adjust the pads so your hips are fixed.","Hold the handles or brace your arms on the pads.","Rotate your torso to one side in a smooth motion.","Pause briefly at the end.","Return to center slowly.","Complete your reps, then switch sides."],"img":"opengym/5333.webp","gif":null,"ext":1},{"id":"5334","n":"cross twisting sit up v. 2","bp":"waist","eq":"body weight","tg":"obliques","mg":"abdominals","sm":["abdominals","hip flexors"],"st":["Lie on your back with knees bent and hands behind your head.","Sit up while rotating your torso.","Bring one elbow toward the opposite knee.","Lower back down slowly.","Alternate sides each rep.","Avoid pulling on your neck."],"img":"opengym/5334.webp","gif":null,"ext":1},{"id":"5335","n":"kettlebell swing clean grip front squat overhead press","bp":"full body","eq":"kettlebell","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","shoulders","core","triceps"],"st":["Stand over the kettlebell and swing it back between your legs.","Swing it up, then clean it to the rack position at your shoulder.","Squat down with the bell held in front of you.","Stand up and press the bell overhead.","Lower it back with control for the next rep.","Switch arms after your set."],"img":"opengym/5335.webp","gif":null,"ext":1},{"id":"5336","n":"kettlebell forward lunge v. 2","bp":"upper legs","eq":"kettlebell","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","core"],"st":["Hold a kettlebell at chest height or by your side.","Step forward into a lunge.","Lower until both knees are bent about 90 degrees.","Keep your front knee over your ankle.","Push back to the start.","Alternate legs."],"img":"opengym/5336.webp","gif":null,"ext":1},{"id":"5337","n":"burpee push up mountain climber complex","bp":"full body","eq":"body weight","tg":"cardiovascular system","mg":"chest","sm":["chest","triceps","core","quadriceps","shoulders"],"st":["Stand tall, then drop your hands to the floor and jump your feet back.","Do one push-up.","Run your knees in and out for several mountain climbers.","Jump your feet in toward your hands.","Jump up with arms overhead.","Keep a steady pace and a tight core."],"img":"opengym/5337.webp","gif":null,"ext":1},{"id":"5344","n":"v up hold","bp":"waist","eq":"body weight","tg":"abs","mg":"hip flexors","sm":["hip flexors","lower abs","core"],"st":["Sit on the floor with knees bent and lean back slightly.","Lift your legs and straighten them to form a V.","Reach your arms forward alongside your legs.","Hold for 15-30 seconds.","Keep your chest open and back from rounding.","Lower with control."],"img":"opengym/5344.webp","gif":null,"ext":1},{"id":"5349","n":"lever abduction leg raise","bp":"upper legs","eq":"leverage machine","tg":"abductors","mg":"glutes","sm":["glutes","core","hip flexors"],"st":["Set up in the machine with the pad on the outside of your leg.","Hold the supports for stability.","Raise your leg out to the side in a controlled motion.","Pause at the top.","Lower slowly.","Finish your reps, then switch legs."],"img":"opengym/5349.webp","gif":null,"ext":1},{"id":"5369","n":"cable kneeling one arm row","bp":"back","eq":"cable","tg":"upper back","mg":"lats","sm":["lats","rhomboids","biceps","core"],"st":["Kneel facing the cable stack and grab the handle with one hand.","Keep your torso upright and core braced.","Pull your elbow back toward your hip.","Squeeze your shoulder blade at the end.","Return slowly to the start.","Finish your reps, then switch sides."],"img":"opengym/5369.webp","gif":null,"ext":1},{"id":"5370","n":"cable standing one arm hammer curl (with rope)","bp":"upper arms","eq":"cable","tg":"biceps","mg":"brachialis","sm":["brachialis","forearms","grip muscles"],"st":["Attach the rope to a low pulley and hold it with one hand, thumb up.","Stand tall with your elbow tucked in.","Curl the rope toward your shoulder.","Squeeze the top for a second.","Lower slowly.","Finish your reps, then switch arms."],"img":"opengym/5370.webp","gif":null,"ext":1},{"id":"5371","n":"roll neck rotation lying on floor","bp":"neck","eq":"roller","tg":"levator scapulae","mg":"sternocleidomastoid","sm":["sternocleidomastoid","upper back"],"st":["Lie on your back with the roller under the base of your skull.","Place the roller under the neck and let your body weight settle onto it.","Gently turn your head slowly from side to side.","Pause on tender spots and breathe slowly for 20-30 seconds.","Keep your core braced and avoid rolling over joints or bone.","Roll for 30-60 seconds, then switch sides if needed."],"img":"opengym/5371.webp","gif":null,"ext":1},{"id":"5372","n":"roll neck decompress lying on floor","bp":"neck","eq":"roller","tg":"levator scapulae","mg":"sternocleidomastoid","sm":["sternocleidomastoid","upper back"],"st":["Lie on your back with the roller under the base of your skull.","Place the roller under the neck and let your body weight settle onto it.","Gently nod your chin and let your head relax into the roller.","Pause on tender spots and breathe slowly for 20-30 seconds.","Keep your core braced and avoid rolling over joints or bone.","Roll for 30-60 seconds, then switch sides if needed."],"img":"opengym/5372.webp","gif":null,"ext":1},{"id":"5373","n":"roll forearms standing against wall","bp":"lower arms","eq":"roller","tg":"forearms","mg":"wrist flexors","sm":["wrist flexors","wrist extensors"],"st":["Stand facing a wall with the roller held against it.","Place the roller under the forearm and let your body weight settle onto it.","Lean in and roll your forearm up and down the roller.","Pause on tender spots and breathe slowly for 20-30 seconds.","Keep your core braced and avoid rolling over joints or bone.","Roll for 30-60 seconds, then switch sides if needed."],"img":"opengym/5373.webp","gif":null,"ext":1},{"id":"5374","n":"roll biceps lying on floor","bp":"upper arms","eq":"roller","tg":"biceps","mg":"brachialis","sm":["brachialis","forearms"],"st":["Lie face down with the roller under one upper arm.","Place the roller under the biceps and let your body weight settle onto it.","Roll slowly from the elbow toward the shoulder.","Pause on tender spots and breathe slowly for 20-30 seconds.","Keep your core braced and avoid rolling over joints or bone.","Roll for 30-60 seconds, then switch sides if needed."],"img":"opengym/5374.webp","gif":null,"ext":1},{"id":"5375","n":"roll triceps side lying on floor","bp":"upper arms","eq":"roller","tg":"triceps","mg":"shoulders","sm":["shoulders","lats"],"st":["Lie on your side with the roller under the back of your upper arm.","Place the roller under the triceps and let your body weight settle onto it.","Roll slowly from the elbow toward the armpit.","Pause on tender spots and breathe slowly for 20-30 seconds.","Keep your core braced and avoid rolling over joints or bone.","Roll for 30-60 seconds, then switch sides if needed."],"img":"opengym/5375.webp","gif":null,"ext":1},{"id":"5376","n":"roll chest opener lying on floor","bp":"chest","eq":"roller","tg":"pectorals","mg":"shoulders","sm":["shoulders","upper chest"],"st":["Lie lengthwise on the roller along your spine with knees bent.","Place the roller under the chest and let your body weight settle onto it.","Open your arms out to the sides and let your chest relax.","Pause on tender spots and breathe slowly for 20-30 seconds.","Keep your core braced and avoid rolling over joints or bone.","Roll for 30-60 seconds, then switch sides if needed."],"img":"opengym/5376.webp","gif":null,"ext":1},{"id":"5377","n":"roll chest lying on floor","bp":"chest","eq":"roller","tg":"pectorals","mg":"upper chest","sm":["upper chest","shoulders"],"st":["Lie face down with the roller under one side of your chest.","Place the roller under the chest and let your body weight settle onto it.","Roll slowly side to side across the muscle.","Pause on tender spots and breathe slowly for 20-30 seconds.","Keep your core braced and avoid rolling over joints or bone.","Roll for 30-60 seconds, then switch sides if needed."],"img":"opengym/5377.webp","gif":null,"ext":1},{"id":"5378","n":"roll front shoulder and chest lying on floor","bp":"chest","eq":"roller","tg":"pectorals","mg":"shoulders","sm":["shoulders","upper chest","biceps"],"st":["Lie face down with the roller under your front shoulder.","Place the roller under the front shoulder and chest and let your body weight settle onto it.","Roll small amounts toward the chest and back.","Pause on tender spots and breathe slowly for 20-30 seconds.","Keep your core braced and avoid rolling over joints or bone.","Roll for 30-60 seconds, then switch sides if needed."],"img":"opengym/5378.webp","gif":null,"ext":1},{"id":"5379","n":"roll posterior shoulder lying on floor","bp":"shoulders","eq":"roller","tg":"delts","mg":"rear deltoids","sm":["rear deltoids","rotator cuff","lats"],"st":["Lie on your side with the roller under your rear shoulder.","Place the roller under the back of the shoulder and let your body weight settle onto it.","Roll slowly along the back of the shoulder.","Pause on tender spots and breathe slowly for 20-30 seconds.","Keep your core braced and avoid rolling over joints or bone.","Roll for 30-60 seconds, then switch sides if needed."],"img":"opengym/5379.webp","gif":null,"ext":1},{"id":"5380","n":"roll shoulder back rotation lying on floor","bp":"shoulders","eq":"roller","tg":"delts","mg":"rotator cuff","sm":["rotator cuff","upper back","rear deltoids"],"st":["Lie on your side with the roller under your upper back.","Place the roller under the shoulder and upper back and let your body weight settle onto it.","Rotate your top arm back and forth to open the shoulder.","Pause on tender spots and breathe slowly for 20-30 seconds.","Keep your core braced and avoid rolling over joints or bone.","Roll for 30-60 seconds, then switch sides if needed."],"img":"opengym/5380.webp","gif":null,"ext":1},{"id":"5381","n":"roll rhomboids","bp":"back","eq":"roller","tg":"upper back","mg":"rhomboids","sm":["rhomboids","trapezius"],"st":["Sit with the roller behind your upper back and cross your arms.","Place the roller under the rhomboids and let your body weight settle onto it.","Roll up and down between your shoulder blades.","Pause on tender spots and breathe slowly for 20-30 seconds.","Keep your core braced and avoid rolling over joints or bone.","Roll for 30-60 seconds, then switch sides if needed."],"img":"opengym/5381.webp","gif":null,"ext":1},{"id":"5382","n":"roll middle back lying on floor","bp":"back","eq":"roller","tg":"upper back","mg":"lats","sm":["lats","rhomboids","trapezius"],"st":["Lie on your back with the roller under your mid back, hands behind your head.","Place the roller under the middle back and let your body weight settle onto it.","Roll slowly up and down.","Pause on tender spots and breathe slowly for 20-30 seconds.","Keep your core braced and avoid rolling over joints or bone.","Roll for 30-60 seconds, then switch sides if needed."],"img":"opengym/5382.webp","gif":null,"ext":1},{"id":"5383","n":"roll lower back (side) lying on floor","bp":"back","eq":"roller","tg":"spine","mg":"lower back","sm":["lower back","obliques"],"st":["Lie on your side with the roller under your lower back.","Place the roller under the side of the lower back and let your body weight settle onto it.","Roll slowly up and down in a small range.","Pause on tender spots and breathe slowly for 20-30 seconds.","Keep your core braced and avoid rolling over joints or bone.","Roll for 30-60 seconds, then switch sides if needed."],"img":"opengym/5383.webp","gif":null,"ext":1},{"id":"5384","n":"roll thoracic spine lying on floor","bp":"back","eq":"roller","tg":"spine","mg":"upper back","sm":["upper back","rhomboids"],"st":["Lie on your back with the roller under your upper back, arms crossed.","Place the roller under the thoracic spine and let your body weight settle onto it.","Lift your hips and roll up and down the upper back.","Pause on tender spots and breathe slowly for 20-30 seconds.","Keep your core braced and avoid rolling over joints or bone.","Roll for 30-60 seconds, then switch sides if needed."],"img":"opengym/5384.webp","gif":null,"ext":1},{"id":"5385","n":"roll shoulder blade reach lying on floor","bp":"back","eq":"roller","tg":"upper back","mg":"rhomboids","sm":["rhomboids","shoulders"],"st":["Lie on your side with the roller under your shoulder blade.","Place the roller under the shoulder blade and let your body weight settle onto it.","Reach your top arm forward and back as you roll.","Pause on tender spots and breathe slowly for 20-30 seconds.","Keep your core braced and avoid rolling over joints or bone.","Roll for 30-60 seconds, then switch sides if needed."],"img":"opengym/5385.webp","gif":null,"ext":1},{"id":"5386","n":"roll around the world lying on floor","bp":"back","eq":"roller","tg":"upper back","mg":"shoulders","sm":["shoulders","trapezius","rhomboids"],"st":["Lie on your back with the roller under your upper back.","Place the roller under the upper back and shoulders and let your body weight settle onto it.","Sweep your arms in a wide arc overhead, like a snow angel.","Pause on tender spots and breathe slowly for 20-30 seconds.","Keep your core braced and avoid rolling over joints or bone.","Roll for 30-60 seconds, then switch sides if needed."],"img":"opengym/5386.webp","gif":null,"ext":1},{"id":"5387","n":"roll erector spinae lying on floor","bp":"back","eq":"roller","tg":"spine","mg":"lower back","sm":["lower back","glutes"],"st":["Lie on your back with the roller under your lower back.","Place the roller under the lower back muscles and let your body weight settle onto it.","Roll slowly with small movements and keep your core engaged.","Pause on tender spots and breathe slowly for 20-30 seconds.","Keep your core braced and avoid rolling over joints or bone.","Roll for 30-60 seconds, then switch sides if needed."],"img":"opengym/5387.webp","gif":null,"ext":1},{"id":"5388","n":"roll kneeling upper back rotation","bp":"back","eq":"roller","tg":"upper back","mg":"rhomboids","sm":["rhomboids","obliques","shoulders"],"st":["Kneel beside the roller and place one hand on it.","Place the roller under the upper back and let your body weight settle onto it.","Slide the roller forward as you rotate your chest open.","Pause on tender spots and breathe slowly for 20-30 seconds.","Keep your core braced and avoid rolling over joints or bone.","Roll for 30-60 seconds, then switch sides if needed."],"img":"opengym/5388.webp","gif":null,"ext":1},{"id":"5389","n":"roll pigeon stretch","bp":"upper legs","eq":"roller","tg":"glutes","mg":"hip flexors","sm":["hip flexors","hamstrings"],"st":["Sit on the roller and cross one ankle over the opposite knee.","Place the roller under the glutes and hip and let your body weight settle onto it.","Lean toward the crossed leg and roll gently.","Pause on tender spots and breathe slowly for 20-30 seconds.","Keep your core braced and avoid rolling over joints or bone.","Roll for 30-60 seconds, then switch sides if needed."],"img":"opengym/5389.webp","gif":null,"ext":1},{"id":"5390","n":"roll glutes sitting on floor","bp":"upper legs","eq":"roller","tg":"glutes","mg":"hamstrings","sm":["hamstrings","hip flexors"],"st":["Sit on the roller with your hands behind you.","Place the roller under the glutes and let your body weight settle onto it.","Roll slowly back and forth under your glutes.","Pause on tender spots and breathe slowly for 20-30 seconds.","Keep your core braced and avoid rolling over joints or bone.","Roll for 30-60 seconds, then switch sides if needed."],"img":"opengym/5390.webp","gif":null,"ext":1},{"id":"5391","n":"roll glute twist lying on floor","bp":"upper legs","eq":"roller","tg":"glutes","mg":"lower back","sm":["lower back","hip flexors"],"st":["Lie on your back with the roller under one glute.","Place the roller under the glutes and let your body weight settle onto it.","Let the knees drop to one side and twist gently.","Pause on tender spots and breathe slowly for 20-30 seconds.","Keep your core braced and avoid rolling over joints or bone.","Roll for 30-60 seconds, then switch sides if needed."],"img":"opengym/5391.webp","gif":null,"ext":1},{"id":"5392","n":"roll hamstrings and glute sitting on floor","bp":"upper legs","eq":"roller","tg":"hamstrings","mg":"glutes","sm":["glutes","calves"],"st":["Sit with the roller under your thighs and hands behind you.","Place the roller under the hamstrings and glutes and let your body weight settle onto it.","Lift your hips and roll from the knee toward the glutes.","Pause on tender spots and breathe slowly for 20-30 seconds.","Keep your core braced and avoid rolling over joints or bone.","Roll for 30-60 seconds, then switch sides if needed."],"img":"opengym/5392.webp","gif":null,"ext":1},{"id":"5393","n":"roll quadriceps (vastus lateralis) lying on floor","bp":"upper legs","eq":"roller","tg":"quads","mg":"quadriceps","sm":["quadriceps","hip flexors"],"st":["Lie on your side with the roller under the outer thigh.","Place the roller under the outer thigh and let your body weight settle onto it.","Roll from the hip down to above the knee.","Pause on tender spots and breathe slowly for 20-30 seconds.","Keep your core braced and avoid rolling over joints or bone.","Roll for 30-60 seconds, then switch sides if needed."],"img":"opengym/5393.webp","gif":null,"ext":1},{"id":"5394","n":"roll tibialis anterior","bp":"lower legs","eq":"roller","tg":"shins","mg":"calves","sm":["calves","ankles"],"st":["Kneel on all fours with the roller under your shins.","Place the roller under the shin and let your body weight settle onto it.","Roll gently from below the knee to the ankle.","Pause on tender spots and breathe slowly for 20-30 seconds.","Keep your core braced and avoid rolling over joints or bone.","Roll for 30-60 seconds, then switch sides if needed."],"img":"opengym/5394.webp","gif":null,"ext":1},{"id":"5395","n":"roll tibialis anterior (single leg) lying on floor","bp":"lower legs","eq":"roller","tg":"shins","mg":"calves","sm":["calves","ankles"],"st":["Rest one shin on the roller, supporting yourself on your hands.","Place the roller under the shin and let your body weight settle onto it.","Roll gently from below the knee to the ankle, then switch legs.","Pause on tender spots and breathe slowly for 20-30 seconds.","Keep your core braced and avoid rolling over joints or bone.","Roll for 30-60 seconds, then switch sides if needed."],"img":"opengym/5395.webp","gif":null,"ext":1},{"id":"5396","n":"roll peroneal side lying on floor","bp":"lower legs","eq":"roller","tg":"calves","mg":"ankles","sm":["ankles","shins"],"st":["Lie on your side with the roller under your outer lower leg.","Place the roller under the outer lower leg and let your body weight settle onto it.","Roll gently from the knee to the ankle.","Pause on tender spots and breathe slowly for 20-30 seconds.","Keep your core braced and avoid rolling over joints or bone.","Roll for 30-60 seconds, then switch sides if needed."],"img":"opengym/5396.webp","gif":null,"ext":1},{"id":"5397","n":"roll peroneal (single leg) side lying on floor","bp":"lower legs","eq":"roller","tg":"calves","mg":"ankles","sm":["ankles","shins"],"st":["Lie on your side with the roller under the outer lower leg, other foot behind for support.","Place the roller under the outer lower leg and let your body weight settle onto it.","Roll gently from the knee to the ankle, then switch legs.","Pause on tender spots and breathe slowly for 20-30 seconds.","Keep your core braced and avoid rolling over joints or bone.","Roll for 30-60 seconds, then switch sides if needed."],"img":"opengym/5397.webp","gif":null,"ext":1},{"id":"5398","n":"roll foot","bp":"lower legs","eq":"roller","tg":"calves","mg":"feet","sm":["feet","ankles"],"st":["Stand or sit with the roller under one foot.","Place the roller under the sole of the foot and let your body weight settle onto it.","Roll the sole from heel to toes, then switch feet.","Pause on tender spots and breathe slowly for 20-30 seconds.","Keep your core braced and avoid rolling over joints or bone.","Roll for 30-60 seconds, then switch sides if needed."],"img":"opengym/5398.webp","gif":null,"ext":1},{"id":"5399","n":"stick assisted isometric core","bp":"waist","eq":"body weight","tg":"abs","mg":"obliques","sm":["obliques","lower back"],"st":["Stand tall with your feet hip-width apart and hold a stick in both hands.","Raise the stick to the position you are cued for and keep your arms steady.","Brace your abs as if preparing for a light punch and tuck the ribs down.","Hold for 20-30 seconds while breathing steadily.","Lower the stick slowly and shake out your arms."],"img":"opengym/5399.webp","gif":null,"ext":1},{"id":"5400","n":"stick lat stretch","bp":"back","eq":"body weight","tg":"lats","mg":"shoulders","sm":["shoulders","triceps"],"st":["Stand tall and grip the stick with both hands, one end held high.","Reach the stick overhead and lean gently away from the higher hand.","Keep your hips square and your ribs from flaring out.","Hold for 20-30 seconds, feeling the stretch along your side and back.","Return to upright and switch sides."],"img":"opengym/5400.webp","gif":null,"ext":1},{"id":"5401","n":"stick shoulders stretch","bp":"shoulders","eq":"body weight","tg":"delts","mg":"chest","sm":["chest","upper back"],"st":["Stand tall and hold the stick behind your back with both hands.","Keep your arms straight and lift the stick slightly away from your body.","Stay tall and avoid arching your lower back.","Hold for 20-30 seconds.","Release slowly and repeat."],"img":"opengym/5401.webp","gif":null,"ext":1},{"id":"5402","n":"stick lunge with overhead raise stretch","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hip flexors","shoulders","core"],"st":["Hold a stick in both hands and step into a long lunge.","Lower your back knee toward the floor while keeping your torso upright.","Raise the stick overhead with straight arms.","Hold for 20-30 seconds, feeling the stretch at the front of the back hip.","Step back and repeat on the other leg."],"img":"opengym/5402.webp","gif":null,"ext":1},{"id":"5403","n":"stick standing twist stretch","bp":"waist","eq":"body weight","tg":"spine","mg":"obliques","sm":["obliques","upper back"],"st":["Stand with feet shoulder-width apart and rest a stick across your upper back.","Hold it with both hands and keep your hips facing forward.","Rotate your upper body slowly to one side.","Pause for a moment, then rotate to the other side.","Repeat for 10-12 slow turns and keep your knees soft."],"img":"opengym/5403.webp","gif":null,"ext":1},{"id":"5404","n":"stick pass around stretch","bp":"shoulders","eq":"body weight","tg":"delts","mg":"chest","sm":["chest","rotator cuff","upper back"],"st":["Stand tall and hold the stick in front of you with a wide overhand grip.","Keep your arms straight and raise the stick overhead.","Carry it back behind your body in a smooth arc.","Return the same way to the start.","Repeat for 8-10 slow passes and narrow your grip as you get more flexible."],"img":"opengym/5404.webp","gif":null,"ext":1},{"id":"5405","n":"stick side bend stretch","bp":"waist","eq":"body weight","tg":"obliques","mg":"abdominals","sm":["abdominals","lats"],"st":["Stand with feet hip-width apart and hold the stick overhead.","Keep your arms straight and your chest open.","Bend slowly to one side without leaning forward.","Hold for 15-20 seconds.","Return to center and bend to the other side."],"img":"opengym/5405.webp","gif":null,"ext":1},{"id":"5406","n":"stick side to front bend stretch","bp":"waist","eq":"body weight","tg":"spine","mg":"obliques","sm":["obliques","hamstrings","lats"],"st":["Stand with feet hip-width apart and hold the stick overhead.","Bend sideways to one side and hold briefly.","Then turn the torso forward and fold from your hips with a long back.","Hold for 15-20 seconds, then rise slowly.","Repeat on the other side."],"img":"opengym/5406.webp","gif":null,"ext":1},{"id":"5407","n":"stick overhead full sumo squat stretch","bp":"upper legs","eq":"body weight","tg":"adductors","mg":"glutes","sm":["glutes","quadriceps","shoulders"],"st":["Stand with your feet wider than your shoulders and toes turned out.","Raise the stick overhead with straight arms.","Sit down between your legs, keeping your chest tall and knees tracking over your toes.","Hold the bottom position for 20-30 seconds.","Press up through your feet to stand."],"img":"opengym/5407.webp","gif":null,"ext":1},{"id":"5408","n":"stick twist lunge stretch","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hip flexors","obliques"],"st":["Hold the stick across your chest or in front with both hands and step into a lunge.","Keep your front knee over your ankle.","Twist your torso over the front leg.","Hold for 15-20 seconds, breathing evenly.","Untwist, step back and switch legs."],"img":"opengym/5408.webp","gif":null,"ext":1},{"id":"5445","n":"standing abdominal vacuum","bp":"waist","eq":"body weight","tg":"abs","mg":"core","sm":["core","obliques"],"st":["Stand tall with your hands on your hips and feet hip-width apart.","Exhale fully until your lungs feel empty.","Pull your belly button toward your spine and hold it there.","Hold for 10-20 seconds without breathing in deeply.","Relax and breathe normally, then repeat."],"img":"opengym/5445.webp","gif":null,"ext":1},{"id":"5447","n":"lever pronated grip seated row (plate loaded)","bp":"back","eq":"leverage machine","tg":"upper back","mg":"lats","sm":["lats","rhomboids","biceps","rear deltoids"],"st":["Sit at the machine with your chest on the pad.","Grab the handles with palms facing down.","Pull your elbows back and squeeze your shoulder blades together.","Pause briefly.","Return slowly until your arms extend.","Keep your torso steady."],"img":"opengym/5447.webp","gif":null,"ext":1},{"id":"5448","n":"lever pronated grip seated scapular retraction shrug (plate loaded)","bp":"back","eq":"leverage machine","tg":"upper back","mg":"rhomboids","sm":["rhomboids","trapezius","rear deltoids"],"st":["Sit in the machine with your chest on the pad.","Grip the handles overhand with arms straight.","Pull your shoulder blades together without bending your elbows much.","Hold for a second.","Let your shoulder blades spread slowly.","Avoid shrugging toward your ears."],"img":"opengym/5448.webp","gif":null,"ext":1},{"id":"5449","n":"dumbbell standing drag curl v. 2","bp":"upper arms","eq":"dumbbell","tg":"biceps","mg":"brachialis","sm":["brachialis","forearms","rear deltoids"],"st":["Stand tall with a dumbbell in each hand, palms forward.","Curl the weights up, keeping them close to your torso.","Let your elbows travel slightly back.","Squeeze the biceps at the top.","Lower slowly along the same path.","Keep your torso still."],"img":"opengym/5449.webp","gif":null,"ext":1},{"id":"5450","n":"ez bar 21s","bp":"upper arms","eq":"ez barbell","tg":"biceps","mg":"brachialis","sm":["brachialis","forearms"],"st":["Stand holding an EZ bar with an underhand grip.","Curl from the bottom to halfway up for 7 reps.","Curl from halfway to the top for 7 reps.","Do 7 full-range curls.","Keep your elbows pinned to your sides.","Use a lighter weight than normal."],"img":"opengym/5450.webp","gif":null,"ext":1},{"id":"5451","n":"barbell kas glute bridge","bp":"upper legs","eq":"barbell","tg":"glutes","mg":"hamstrings","sm":["hamstrings","core"],"st":["Lie on your back with your knees bent and feet flat, loaded as the exercise requires.","Keep your shins roughly vertical with the knees kept slightly forward of the hips.","Squeeze your glutes and press your hips up until your body forms a line.","Pause for a second at the top without arching your back.","Lower under control and repeat."],"img":"opengym/5451.webp","gif":null,"ext":1},{"id":"5458","n":"dumbbell standing single arm cross raise","bp":"chest","eq":"dumbbell","tg":"pectorals","mg":"shoulders","sm":["shoulders","upper chest","core"],"st":["Stand holding a dumbbell by your opposite hip.","Keep a slight bend in your elbow.","Raise the dumbbell diagonally up and across to head height.","Squeeze your chest at the top.","Lower slowly.","Finish your reps, then switch arms."],"img":"opengym/5458.webp","gif":null,"ext":1},{"id":"5460","n":"explosive push up","bp":"chest","eq":"body weight","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders","core"],"st":["Start in a high plank with hands under shoulders.","Lower your chest toward the floor.","Push up explosively so your hands lift off.","Land softly with bent elbows.","Go straight into the next rep.","Keep your body in a straight line."],"img":"opengym/5460.webp","gif":null,"ext":1},{"id":"5466","n":"front plank with arm and leg lift (form check)","bp":"waist","eq":"body weight","tg":"abs","mg":"glutes","sm":["glutes","shoulders","core","lower back"],"st":["Start in a forearm or high plank with your body in a straight line.","Brace your abs and squeeze your glutes.","Lift one arm forward and the opposite leg back.","Hold for a couple of seconds.","Return and switch sides.","Keep your hips level."],"img":"opengym/5466.webp","gif":null,"ext":1},{"id":"5469","n":"dumbbell 21s","bp":"upper arms","eq":"dumbbell","tg":"biceps","mg":"brachialis","sm":["brachialis","forearms"],"st":["Stand holding a dumbbell in each hand, palms forward.","Curl from the bottom to halfway up for 7 reps.","Curl from halfway to the top for 7 reps.","Do 7 full-range curls.","Keep your elbows pinned to your sides.","Use a lighter weight than normal."],"img":"opengym/5469.webp","gif":null,"ext":1},{"id":"5470","n":"cable medius kickback","bp":"upper legs","eq":"cable","tg":"glutes","mg":"hip flexors","sm":["hip flexors","core"],"st":["Attach an ankle strap to a low pulley and clip it to one ankle.","Stand side-on to the stack, hold the frame and keep your torso tall.","Sweep the working leg out and slightly back, leading with the heel.","Pause briefly, then return slowly without leaning.","Finish all reps, then switch legs."],"img":"opengym/5470.webp","gif":null,"ext":1},{"id":"5471","n":"rounded back extension","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"hamstrings","sm":["hamstrings","lower back"],"st":["Set the pad at hip height and hook your heels under the rollers.","Cross your arms on your chest and let your upper back round slightly.","Lower your torso until you feel a stretch in the hamstrings.","Squeeze your glutes and lift until your body is nearly in line.","Stop before overarching and repeat with control."],"img":"opengym/5471.webp","gif":null,"ext":1},{"id":"5472","n":"lying bent legs raise","bp":"waist","eq":"body weight","tg":"abs","mg":"hip flexors","sm":["hip flexors","lower abs"],"st":["Lie on your back with hands under your hips or by your sides.","Bend your knees and lift your feet off the floor.","Curl your hips up slightly as you bring your knees toward your chest.","Lower your legs slowly without letting your lower back arch.","Repeat for the target reps."],"img":"opengym/5472.webp","gif":null,"ext":1},{"id":"5473","n":"shoulder width neutral grip pull up","bp":"back","eq":"body weight","tg":"lats","mg":"biceps","sm":["biceps","brachialis","upper back","forearms"],"st":["Grab neutral-grip handles about shoulder width apart and hang with arms straight.","Brace your core and pull your shoulder blades down.","Pull your chest toward your hands until your chin clears the bar.","Lower yourself slowly to a full hang.","Avoid swinging or kicking."],"img":"opengym/5473.webp","gif":null,"ext":1},{"id":"5476","n":"barbell staggered stance hip thrust","bp":"upper legs","eq":"barbell","tg":"glutes","mg":"hamstrings","sm":["hamstrings","quadriceps","adductors"],"st":["Sit with your upper back against a bench and a barbell over your hips.","Place one foot slightly ahead of the other.","Drive through your feet to lift your hips until your torso is level.","Squeeze your glutes at the top, keeping your chin tucked.","Lower under control, and swap the foot position on the next set."],"img":"opengym/5476.webp","gif":null,"ext":1},{"id":"5477","n":"vertical leg raise (on parallel bars) v. 2","bp":"waist","eq":"body weight","tg":"abs","mg":"hip flexors","sm":["hip flexors","lower abs","forearms"],"st":["Support yourself on parallel bars with straight arms and shoulders pushed down.","Keep your legs together and slightly bent or straight.","Raise your legs until they reach hip height or higher, curling your pelvis.","Lower them slowly without swinging.","Repeat for the target reps."],"img":"opengym/5477.webp","gif":null,"ext":1},{"id":"5478","n":"high knee lunge on bosu ball","bp":"upper legs","eq":"bosu ball","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","calves","core"],"st":["Stand with one foot on the bosu dome and the other behind you.","Lower into a lunge with your torso upright.","Drive through the front foot and bring the back knee up high.","Land softly and balanced, then repeat.","Switch legs after your set."],"img":"opengym/5478.webp","gif":null,"ext":1},{"id":"5479","n":"close grip pull up","bp":"back","eq":"body weight","tg":"lats","mg":"biceps","sm":["biceps","brachialis","upper back","forearms"],"st":["Grip the bar with hands a few centimetres apart, palms facing away.","Hang with straight arms and engage your shoulders.","Pull yourself up until your chin passes the bar.","Lower slowly to a full hang.","Keep your core tight and avoid swinging."],"img":"opengym/5479.webp","gif":null,"ext":1},{"id":"5480","n":"resistance band seated calf stretch","bp":"lower legs","eq":"resistance band","tg":"calves","mg":"soleus","sm":["soleus","hamstrings"],"st":["Sit on the floor with one leg straight and loop the band around the ball of that foot.","Hold the band ends with both hands and sit tall.","Gently pull your toes toward you.","Hold for 20-30 seconds, keeping your knee straight.","Release and switch legs."],"img":"opengym/5480.webp","gif":null,"ext":1},{"id":"5481","n":"seated foot slide","bp":"lower legs","eq":"body weight","tg":"calves","mg":"ankles","sm":["ankles","feet","shins"],"st":["Sit tall on a chair with your feet flat on the floor.","Keep your heel down and slide the foot forward along the floor.","Pull it back, letting the heel lift slightly toward the end.","Move smoothly through a comfortable range.","Repeat, then switch feet."],"img":"opengym/5481.webp","gif":null,"ext":1},{"id":"5482","n":"single leg hopping","bp":"upper legs","eq":"body weight","tg":"quads","mg":"calves","sm":["calves","glutes","hamstrings","ankles"],"st":["Stand on one leg with a slight knee bend and arms ready.","Hop up and forward or in place using your ankle and knee.","Land softly on the ball of the same foot.","Stay balanced and keep your hips level.","Complete your reps, then switch legs."],"img":"opengym/5482.webp","gif":null,"ext":1},{"id":"5483","n":"weighted seated calf raise v. 2","bp":"lower legs","eq":"weighted","tg":"calves","mg":"soleus","sm":["soleus"],"st":["Sit with the balls of your feet on a raised edge and weight resting on your knees.","Lower your heels until you feel a calf stretch.","Press up through the balls of your feet as high as you can.","Pause at the top, then lower slowly.","Keep your knees bent throughout."],"img":"opengym/5483.webp","gif":null,"ext":1},{"id":"5484","n":"weighted seated single calf raise v. 2","bp":"lower legs","eq":"weighted","tg":"calves","mg":"soleus","sm":["soleus","ankles"],"st":["Sit with one forefoot on a raised edge and weight on that knee.","Lower the heel for a full stretch.","Press up onto the ball of your foot as high as possible.","Pause, then lower under control.","Finish your reps and switch legs."],"img":"opengym/5484.webp","gif":null,"ext":1},{"id":"5496","n":"kettlebell elevated goblet squat","bp":"upper legs","eq":"kettlebell","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","core","adductors"],"st":["Stand with heels on a low plate, holding a kettlebell at your chest.","Keep your chest tall and elbows pointing down.","Squat down between your knees as deep as comfortable.","Drive through your feet to stand up.","Keep your torso upright throughout."],"img":"opengym/5496.webp","gif":null,"ext":1},{"id":"5497","n":"dumbbell plank pass through","bp":"waist","eq":"dumbbell","tg":"abs","mg":"obliques","sm":["obliques","shoulders","core","triceps"],"st":["Start in a high plank with a dumbbell beside one hand and feet wide.","Brace your core and keep hips level.","Reach the free hand under your body and grab the dumbbell.","Pass it across to the other side and place it down.","Repeat, alternating sides."],"img":"opengym/5497.webp","gif":null,"ext":1},{"id":"5498","n":"weighted plate overhead march","bp":"upper legs","eq":"weight plate","tg":"quads","mg":"core","sm":["core","shoulders","hip flexors","glutes"],"st":["Hold a weight plate overhead with straight arms.","Stand tall with ribs down and core braced.","Lift one knee toward hip height.","Lower it and lift the other knee in a controlled march.","Keep the plate steady and avoid leaning back."],"img":"opengym/5498.webp","gif":null,"ext":1},{"id":"5513","n":"bench dip on stability ball","bp":"upper arms","eq":"stability ball","tg":"triceps","mg":"chest","sm":["chest","shoulders"],"st":["Sit on a bench edge with hands beside your hips and heels on a stability ball.","Slide your hips off the bench with arms straight.","Bend your elbows to about 90 degrees, keeping them close.","Press back up until your arms are straight.","Keep your shoulders down and the ball steady."],"img":"opengym/5513.webp","gif":null,"ext":1},{"id":"5514","n":"twist crunch (legs up)","bp":"waist","eq":"body weight","tg":"obliques","mg":"lower abs","sm":["lower abs"],"st":["Lie on your back with knees bent and legs raised.","Place your hands lightly behind your head.","Crunch up and rotate one shoulder toward the opposite knee.","Lower with control and repeat to the other side.","Do not pull on your neck."],"img":"opengym/5514.webp","gif":null,"ext":1},{"id":"5515","n":"decline sit up v. 3","bp":"waist","eq":"body weight","tg":"abs","mg":"hip flexors","sm":["hip flexors","obliques"],"st":["Hook your feet under the pads on a decline bench and lie back.","Cross your arms over your chest.","Curl your torso up until you are sitting tall.","Lower back slowly without dropping.","Keep your neck relaxed."],"img":"opengym/5515.webp","gif":null,"ext":1},{"id":"5516","n":"lever hack squat","bp":"upper legs","eq":"leverage machine","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","adductors"],"st":["Set your shoulders under the pads and feet shoulder width on the platform.","Release the safety handles.","Lower until your thighs are at least parallel to the platform.","Press through your whole foot to stand.","Do not lock your knees hard at the top."],"img":"opengym/5516.webp","gif":null,"ext":1},{"id":"5518","n":"cable kneeling leaning forward one arm row","bp":"back","eq":"cable","tg":"upper back","mg":"lats","sm":["lats","rhomboids","biceps","rear deltoids"],"st":["Kneel facing a low cable with a handle in one hand.","Lean your torso forward and brace your core.","Pull your elbow back toward your hip.","Squeeze your shoulder blade, then return slowly.","Finish reps and switch sides."],"img":"opengym/5518.webp","gif":null,"ext":1},{"id":"5522","n":"ring pull up","bp":"back","eq":"suspension trainer","tg":"lats","mg":"biceps","sm":["biceps","upper back","forearms","core"],"st":["Grab the rings and hang with arms straight.","Brace your core and pull your shoulders down.","Pull until the rings reach your chest or chin passes them.","Turn your palms slightly in as you rise if comfortable.","Lower slowly to a full hang."],"img":"opengym/5522.webp","gif":null,"ext":1},{"id":"5524","n":"cable standing one arm face pull","bp":"shoulders","eq":"cable","tg":"delts","mg":"rear deltoids","sm":["rear deltoids","rotator cuff","upper back"],"st":["Set a cable at upper chest height with a single handle.","Stand tall and grab the handle with one hand.","Pull toward your face, elbow high and out.","Rotate your hand back slightly at the end.","Return slowly and switch sides after the set."],"img":"opengym/5524.webp","gif":null,"ext":1},{"id":"5526","n":"hip circle with hula hoop","bp":"waist","eq":"body weight","tg":"abs","mg":"obliques","sm":["obliques","glutes","hip flexors"],"st":["Stand with feet shoulder width apart, holding the hoop against your lower back.","Give it a push and start swinging your hips in circles.","Keep the motion smooth and steady.","Stay tall with a braced core.","Continue for a set time, then switch direction."],"img":"opengym/5526.webp","gif":null,"ext":1},{"id":"5527","n":"lever seated bent over rear delt fly","bp":"shoulders","eq":"leverage machine","tg":"delts","mg":"rear deltoids","sm":["rear deltoids","upper back","rhomboids"],"st":["Sit on the machine with your chest on the pad and grip the handles.","Keep a slight bend in your elbows.","Open your arms out and back, squeezing your shoulder blades.","Pause, then return slowly.","Do not shrug."],"img":"opengym/5527.webp","gif":null,"ext":1},{"id":"5528","n":"cable standing crossover overhead tricep extension","bp":"upper arms","eq":"cable","tg":"triceps","mg":"shoulders","sm":["shoulders","core"],"st":["Set two high pulleys with handles and face away from the stack.","Hold the handles overhead with elbows bent.","Cross your hands as you straighten your arms.","Pause, then return slowly.","Keep your elbows pointing forward."],"img":"opengym/5528.webp","gif":null,"ext":1},{"id":"5529","n":"weighted full squat with overhead press","bp":"full body","eq":"weighted","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","shoulders","triceps","core"],"st":["Hold the weight at your shoulders and stand with feet shoulder width.","Squat down deeply with chest up.","Drive up through your legs.","Use that momentum to press the weight overhead.","Lower it back to your shoulders and repeat."],"img":"opengym/5529.webp","gif":null,"ext":1},{"id":"5537","n":"high knee tap","bp":"cardio","eq":"body weight","tg":"cardiovascular system","mg":"hip flexors","sm":["hip flexors","core","quadriceps"],"st":["Stand tall with hands out in front at waist height.","Drive one knee up to tap your hand.","Lower it and switch quickly to the other knee.","Stay light on the balls of your feet.","Keep a fast, steady pace for time."],"img":"opengym/5537.webp","gif":null,"ext":1},{"id":"5553","n":"cable seated lats focused row","bp":"back","eq":"cable","tg":"lats","mg":"upper back","sm":["upper back","biceps","rhomboids"],"st":["Sit at the cable row with feet on the platform and knees slightly bent.","Grab the handle and lean back slightly.","Pull your elbows down and back toward your hips.","Squeeze your lats, then extend slowly.","Keep your chest up."],"img":"opengym/5553.webp","gif":null,"ext":1},{"id":"5554","n":"dumbbell kas glute bridge","bp":"upper legs","eq":"dumbbell","tg":"glutes","mg":"hamstrings","sm":["hamstrings","core"],"st":["Lie on your back with your knees bent and feet flat, loaded as the exercise requires.","Keep your shins roughly vertical with the knees kept slightly forward of the hips.","Squeeze your glutes and press your hips up until your body forms a line.","Pause for a second at the top without arching your back.","Lower under control and repeat."],"img":"opengym/5554.webp","gif":null,"ext":1},{"id":"5555","n":"bodyweight good morning","bp":"upper legs","eq":"body weight","tg":"hamstrings","mg":"glutes","sm":["glutes","lower back"],"st":["Stand with feet hip width and hands behind your head.","Soften your knees and push your hips back.","Lower your torso with a flat back until you feel a hamstring stretch.","Drive your hips forward to stand.","Keep your spine neutral."],"img":"opengym/5555.webp","gif":null,"ext":1},{"id":"5556","n":"negative push up","bp":"chest","eq":"body weight","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders","core"],"st":["Start at the top of a push-up with straight arms.","Brace your core and keep a straight line.","Lower your chest to the floor over 3-5 seconds.","Drop to your knees or reset at the bottom.","Return to the top and repeat."],"img":"opengym/5556.webp","gif":null,"ext":1},{"id":"5557","n":"standing chest stretch against door","bp":"chest","eq":"body weight","tg":"pectorals","mg":"shoulders","sm":["shoulders","biceps"],"st":["Stand in a doorway with your forearm against the frame, elbow at shoulder height.","Step through gently with the opposite foot.","Turn away until you feel a chest stretch.","Hold for 20-30 seconds.","Switch sides."],"img":"opengym/5557.webp","gif":null,"ext":1},{"id":"5577","n":"barbell paused sumo deadlift","bp":"upper legs","eq":"barbell","tg":"glutes","mg":"hamstrings","sm":["hamstrings","adductors","quadriceps","lower back","grip muscles"],"st":["Stand with a wide stance, toes out, and grip the bar inside your knees.","Brace and pull the slack out of the bar.","Lift the bar a few centimetres and pause for 1-2 seconds.","Drive your hips forward and stand tall.","Lower the bar under control."],"img":"opengym/5577.webp","gif":null,"ext":1},{"id":"5579","n":"ez bar seated wrist curl","bp":"lower arms","eq":"ez barbell","tg":"forearms","mg":"wrist flexors","sm":["wrist flexors","grip muscles"],"st":["Sit on a bench with forearms on your thighs and wrists past your knees.","Hold the EZ bar with an underhand grip.","Lower the bar by opening your fingers slightly.","Curl your wrists up as high as you can.","Keep your forearms still."],"img":"opengym/5579.webp","gif":null,"ext":1},{"id":"5582","n":"rear shift lunge from deficit","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","adductors"],"st":["Stand on a low step with feet together.","Step one leg back and down to the floor.","Lower into a lunge with the front knee over the foot.","Push through the front heel to step back up.","Complete reps and switch legs."],"img":"opengym/5582.webp","gif":null,"ext":1},{"id":"5583","n":"lever ab coaster crunch","bp":"waist","eq":"leverage machine","tg":"abs","mg":"obliques","sm":["obliques","hip flexors"],"st":["Sit on the machine, set the seat and grab the handles.","Place your legs on the pads and keep your back against the support.","Exhale and crunch your torso and knees toward each other.","Pause when your abs are fully squeezed.","Return slowly without letting the weight stack touch down."],"img":"opengym/5583.webp","gif":null,"ext":1},{"id":"5598","n":"inchworm and mountain climbers","bp":"full body","eq":"body weight","tg":"cardiovascular system","mg":"core","sm":["core","shoulders","hamstrings","quadriceps"],"st":["Stand tall, then hinge forward and walk your hands out to a plank.","Brace your core and keep a straight line.","Drive your knees to your chest alternately for several reps.","Walk your hands back to your feet.","Stand up and repeat."],"img":"opengym/5598.webp","gif":null,"ext":1},{"id":"5606","n":"dumbbell prone rear delt swing","bp":"shoulders","eq":"dumbbell","tg":"delts","mg":"rear deltoids","sm":["rear deltoids","upper back","rhomboids"],"st":["Lie face down on an incline bench with dumbbells hanging.","Keep a soft bend in your elbows.","Swing the weights out and up to shoulder height.","Lower slowly.","Keep your torso still."],"img":"opengym/5606.webp","gif":null,"ext":1},{"id":"5607","n":"band face pull","bp":"shoulders","eq":"band","tg":"delts","mg":"rear deltoids","sm":["rear deltoids","rotator cuff","upper back"],"st":["Anchor a band at head height and hold the ends.","Step back to create tension.","Pull the band toward your face, elbows high.","Squeeze your shoulder blades.","Return slowly."],"img":"opengym/5607.webp","gif":null,"ext":1},{"id":"5608","n":"band standing chest press v. 2","bp":"chest","eq":"band","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders","upper chest"],"st":["Anchor a band behind you and hold the ends at chest height.","Stand in a split stance for balance.","Press your hands forward until arms are straight.","Return slowly.","Keep your core braced."],"img":"opengym/5608.webp","gif":null,"ext":1},{"id":"5609","n":"cable standing face pull","bp":"shoulders","eq":"cable","tg":"delts","mg":"rear deltoids","sm":["rear deltoids","rotator cuff","upper back"],"st":["Set a cable at upper chest height with a handle.","Stand tall and pull toward your face.","Spread your hands apart at the end.","Squeeze your shoulder blades.","Return slowly."],"img":"opengym/5609.webp","gif":null,"ext":1},{"id":"5623","n":"biceps curl front step","bp":"upper arms","eq":"body weight","tg":"biceps","mg":"quadriceps","sm":["quadriceps","glutes","shoulders"],"st":["Stand tall with your elbows at your sides and palms up.","Step one foot forward while curling your hands up to your shoulders.","Step back as you lower your arms.","Alternate legs at a brisk, steady pace.","Keep your elbows pinned and your core tight."],"img":"opengym/5623.webp","gif":null,"ext":1},{"id":"5628","n":"landmine hack squat","bp":"upper legs","eq":"landmine","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","core"],"st":["Hold the end of a landmine bar at your chest.","Stand with feet shoulder width.","Squat down with your chest up.","Drive through your heels to stand.","Keep the bar close."],"img":"opengym/5628.webp","gif":null,"ext":1},{"id":"5630","n":"bodyweight narrow stance squat","bp":"upper legs","eq":"body weight","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","adductors"],"st":["Stand with feet close together.","Extend your arms forward for balance.","Sit down and back, keeping your heels down.","Descend until your thighs are parallel.","Press up to stand."],"img":"opengym/5630.webp","gif":null,"ext":1},{"id":"5631","n":"dumbbell standing bent arm lateral raise","bp":"shoulders","eq":"dumbbell","tg":"delts","mg":"trapezius","sm":["trapezius","rotator cuff"],"st":["Stand holding dumbbells with elbows bent about 90 degrees.","Raise your elbows out to the sides to shoulder height.","Pause briefly.","Lower slowly.","Avoid swinging."],"img":"opengym/5631.webp","gif":null,"ext":1},{"id":"5632","n":"barbell shoulder grip upright row","bp":"shoulders","eq":"barbell","tg":"delts","mg":"trapezius","sm":["trapezius","biceps","upper back"],"st":["Stand holding a barbell at your thighs with hands shoulder width.","Pull the bar up along your body.","Lead with your elbows up to chest height.","Lower slowly.","Keep the bar close."],"img":"opengym/5632.webp","gif":null,"ext":1},{"id":"5633","n":"barbell narrow stance squat v. 2","bp":"upper legs","eq":"barbell","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","adductors","core"],"st":["Rest a barbell on your upper back with feet close together.","Brace your core.","Squat down with your chest up.","Stand back up through your feet.","Keep your knees tracking over your toes."],"img":"opengym/5633.webp","gif":null,"ext":1},{"id":"5634","n":"dumbbell narrow stance squat","bp":"upper legs","eq":"dumbbell","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","adductors","core"],"st":["Hold dumbbells at your sides with feet close together.","Brace your core.","Squat down with your chest up.","Drive up to stand.","Keep your heels down."],"img":"opengym/5634.webp","gif":null,"ext":1},{"id":"5635","n":"dumbbell bent arm lateral raise","bp":"shoulders","eq":"dumbbell","tg":"delts","mg":"trapezius","sm":["trapezius","rotator cuff"],"st":["Stand with dumbbells and elbows bent.","Raise your elbows out to shoulder height.","Pause at the top.","Lower slowly.","Keep your torso still."],"img":"opengym/5635.webp","gif":null,"ext":1},{"id":"5636","n":"landmine kneeling one arm shoulder press v. 2","bp":"shoulders","eq":"landmine","tg":"delts","mg":"triceps","sm":["triceps","upper chest","core"],"st":["Kneel holding the end of a landmine bar at your shoulder.","Brace your core and keep your torso upright.","Press the bar up and forward until your arm is straight.","Lower slowly.","Switch sides after your set."],"img":"opengym/5636.webp","gif":null,"ext":1},{"id":"5637","n":"incline push up (on bench)","bp":"chest","eq":"body weight","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders","core"],"st":["Place hands on a bench slightly wider than shoulders.","Walk your feet back into a straight line.","Lower your chest to the bench.","Press back up.","Keep your core tight."],"img":"opengym/5637.webp","gif":null,"ext":1},{"id":"5649","n":"hollow rock","bp":"waist","eq":"body weight","tg":"abs","mg":"hip flexors","sm":["hip flexors","lower abs","core"],"st":["Lie on your back and lift your arms and legs into a hollow position.","Press your lower back into the floor.","Rock back and forth like a boat.","Keep your body rigid.","Continue for reps or time."],"img":"opengym/5649.webp","gif":null,"ext":1},{"id":"5656","n":"cable standing face pull (with rope)","bp":"shoulders","eq":"cable","tg":"delts","mg":"rear deltoids","sm":["rear deltoids","rotator cuff","upper back"],"st":["Attach a rope to a high pulley.","Grab it with both hands.","Pull toward your face, splitting the rope.","Squeeze your shoulder blades.","Return slowly."],"img":"opengym/5656.webp","gif":null,"ext":1},{"id":"5657","n":"cable side bend v. 2","bp":"waist","eq":"cable","tg":"obliques","mg":"core","sm":["core"],"st":["Stand side-on to a low cable holding the handle.","Keep your hips still.","Bend sideways away from the cable.","Return to upright.","Switch sides."],"img":"opengym/5657.webp","gif":null,"ext":1},{"id":"5658","n":"cable seated face pull (with rope)","bp":"shoulders","eq":"cable","tg":"delts","mg":"rear deltoids","sm":["rear deltoids","rotator cuff","upper back"],"st":["Sit facing a cable with a rope attachment.","Sit tall.","Pull the rope toward your face.","Squeeze your shoulder blades.","Return slowly."],"img":"opengym/5658.webp","gif":null,"ext":1},{"id":"5659","n":"barbell anderson squat","bp":"upper legs","eq":"barbell","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","core"],"st":["Set the bar in safety pins at the bottom of a squat.","Get under it and brace.","Drive up from a dead stop.","Lower back to the pins.","Reset on every rep."],"img":"opengym/5659.webp","gif":null,"ext":1},{"id":"5660","n":"barbell pin chest press","bp":"chest","eq":"barbell","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders","upper chest"],"st":["Set the pins just above your chest.","Lie under the bar with a firm grip.","Press the bar up.","Lower to the pins and pause.","Repeat."],"img":"opengym/5660.webp","gif":null,"ext":1},{"id":"5661","n":"dumbbell bent over row with chest support","bp":"back","eq":"dumbbell","tg":"upper back","mg":"lats","sm":["lats","rhomboids","biceps","rear deltoids"],"st":["Lie chest down on an incline bench with dumbbells.","Let your arms hang.","Row the weights up toward your ribs.","Squeeze your shoulder blades.","Lower slowly."],"img":"opengym/5661.webp","gif":null,"ext":1},{"id":"5662","n":"barbell power shrug","bp":"back","eq":"barbell","tg":"traps","mg":"upper back","sm":["upper back","forearms","grip muscles"],"st":["Hold a barbell at mid-thigh.","Dip your knees slightly.","Extend your hips and shrug explosively.","Lower the bar under control.","Keep your arms straight."],"img":"opengym/5662.webp","gif":null,"ext":1},{"id":"5663","n":"barbell behind the back deadlift","bp":"upper legs","eq":"barbell","tg":"glutes","mg":"hamstrings","sm":["hamstrings","lower back","forearms","grip muscles"],"st":["Stand in front of the bar behind your legs.","Squat down and grip the bar behind you.","Stand up by driving your hips forward.","Lower the bar under control.","Keep your back flat."],"img":"opengym/5663.webp","gif":null,"ext":1},{"id":"5664","n":"cable seated leg extension","bp":"upper legs","eq":"cable","tg":"quads","mg":"hip flexors","sm":["hip flexors"],"st":["Sit on a bench with an ankle strap attached to a low cable.","Hold the bench.","Extend your leg until straight.","Lower slowly.","Switch legs."],"img":"opengym/5664.webp","gif":null,"ext":1},{"id":"5665","n":"dumbbell bent over face pull","bp":"shoulders","eq":"dumbbell","tg":"delts","mg":"rear deltoids","sm":["rear deltoids","rotator cuff","upper back","rhomboids"],"st":["Hold a dumbbell in each hand and hinge at the hips with a flat back.","Let the weights hang below your shoulders, palms facing each other.","Pull the dumbbells toward your face, flaring your elbows out and up.","Squeeze your shoulder blades together at the top.","Lower with control and repeat without swinging."],"img":"opengym/5665.webp","gif":null,"ext":1},{"id":"5666","n":"dumbbell high pull","bp":"shoulders","eq":"dumbbell","tg":"delts","mg":"trapezius","sm":["trapezius","upper back","glutes","hamstrings","quadriceps"],"st":["Stand with feet shoulder-width apart, dumbbells hanging in front of your thighs.","Bend your knees and hips slightly, keeping your chest up.","Extend your hips and knees powerfully and pull the weights up with elbows leading.","Stop at about chest height, elbows above your wrists.","Lower the dumbbells under control and reset."],"img":"opengym/5666.webp","gif":null,"ext":1},{"id":"5667","n":"dumbbell z press","bp":"shoulders","eq":"dumbbell","tg":"delts","mg":"triceps","sm":["triceps","core","upper chest","trapezius"],"st":["Sit on the floor with your legs extended in front of you.","Hold the dumbbells at shoulder height, palms facing forward.","Brace your core and sit tall without leaning back.","Press the weights overhead until your arms are straight.","Lower them back to your shoulders with control."],"img":"opengym/5667.webp","gif":null,"ext":1},{"id":"5668","n":"barbell standing shoulder pin press","bp":"shoulders","eq":"barbell","tg":"delts","mg":"triceps","sm":["triceps","upper chest","core","trapezius"],"st":["Set the bar on safety pins at about shoulder height in a rack.","Step under it and grip just outside shoulder width.","Brace your core and squeeze your glutes.","Press the bar overhead, moving your head slightly back then through.","Lower the bar to rest on the pins, pause, and repeat."],"img":"opengym/5668.webp","gif":null,"ext":1},{"id":"5669","n":"barbell strict curl","bp":"upper arms","eq":"barbell","tg":"biceps","mg":"brachialis","sm":["brachialis","forearms","grip muscles"],"st":["Stand tall holding a barbell with an underhand shoulder-width grip.","Keep your elbows pinned to your sides and your torso still.","Curl the bar up toward your shoulders.","Squeeze your biceps at the top.","Lower slowly until your arms are fully straight."],"img":"opengym/5669.webp","gif":null,"ext":1},{"id":"5670","n":"barbell zercher deadlift","bp":"upper legs","eq":"barbell","tg":"glutes","mg":"hamstrings","sm":["hamstrings","lower back","quadriceps","core","forearms"],"st":["Place the bar on a low rack or the floor and stand over it.","Squat down and hook the bar in the crooks of your elbows.","Lift your chest and brace your core.","Stand up by driving through your legs and extending your hips.","Lower the bar back down under control, keeping your back flat."],"img":"opengym/5670.webp","gif":null,"ext":1},{"id":"5671","n":"bodyweight single leg kas glute bridge","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"hamstrings","sm":["hamstrings","core"],"st":["Lie on your back with one foot flat and the other leg lifted.","Keep your standing shin close to vertical.","Drive through your heel and lift your hips until in line with your torso.","Squeeze your glute at the top without arching.","Lower slowly, finish your reps, then switch legs."],"img":"opengym/5671.webp","gif":null,"ext":1},{"id":"5672","n":"bodyweight b stance good morning","bp":"upper legs","eq":"body weight","tg":"hamstrings","mg":"glutes","sm":["glutes","lower back","core"],"st":["Stand with one foot flat and the other slightly behind, toe resting on the floor.","Place your hands behind your head.","Push your hips back and hinge forward with a flat back.","Go down until you feel a stretch in the hamstring of the front leg.","Return to standing and switch legs after your set."],"img":"opengym/5672.webp","gif":null,"ext":1},{"id":"5680","n":"side mountain climber","bp":"full body","eq":"body weight","tg":"cardiovascular system","mg":"core","sm":["core","obliques","hip flexors","shoulders"],"st":["Start in a high plank with hands under your shoulders.","Drive one knee out toward the same-side elbow.","Return that foot and switch quickly to the other leg.","Keep your hips low and your core tight.","Continue at a brisk pace for the set time."],"img":"opengym/5680.webp","gif":null,"ext":1},{"id":"5684","n":"crossed arms front leg kick","bp":"upper legs","eq":"body weight","tg":"quads","mg":"hip flexors","sm":["hip flexors","glutes","core"],"st":["Stand tall with your arms crossed over your chest.","Shift your weight onto one leg.","Kick the other leg forward to about hip height with control.","Lower it and repeat for your reps.","Switch legs and keep your torso upright."],"img":"opengym/5684.webp","gif":null,"ext":1},{"id":"5695","n":"lean forward stretch","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"hamstrings","sm":["hamstrings","lower back"],"st":["Stand or sit in a stable position with one leg in front of the other.","Keep your back long and chest open.","Hinge forward from your hips until you feel a stretch in the glutes and hamstrings.","Hold for 20-30 seconds.","Return upright and switch sides."],"img":"opengym/5695.webp","gif":null,"ext":1},{"id":"5696","n":"cheat curl","bp":"upper arms","eq":"barbell","tg":"biceps","mg":"brachialis","sm":["brachialis","forearms","lower back","grip muscles"],"st":["Stand holding a barbell with an underhand grip, arms straight.","Lean back slightly and swing your hips to start the lift.","Curl the bar up to your chest.","Lower the bar slowly, resisting its weight.","Reset your posture before the next rep."],"img":"opengym/5696.webp","gif":null,"ext":1},{"id":"5697","n":"dumbbell lying row on rack","bp":"back","eq":"dumbbell","tg":"upper back","mg":"lats","sm":["lats","rhomboids","biceps","rear deltoids"],"st":["Lie face down on a raised bench with a dumbbell in each hand.","Let your arms hang straight down.","Row the weights up toward your ribs, elbows close to your body.","Squeeze your shoulder blades together at the top.","Lower slowly to full arm extension."],"img":"opengym/5697.webp","gif":null,"ext":1},{"id":"5698","n":"dumbbell walking calf raise","bp":"lower legs","eq":"dumbbell","tg":"calves","mg":"soleus","sm":["soleus","ankles","feet"],"st":["Hold a dumbbell in each hand at your sides.","Stand tall and rise onto the balls of your feet.","Step forward and stay up on your toes.","Alternate steps, keeping your heels lifted.","Walk for the set distance, then lower your heels."],"img":"opengym/5698.webp","gif":null,"ext":1},{"id":"5699","n":"45 degrees side bend","bp":"waist","eq":"body weight","tg":"obliques","mg":"abdominals","sm":["abdominals","lower back"],"st":["Set up on a 45 degree bench, lying on your side with your feet anchored.","Cross your arms over your chest.","Lower your upper body toward the floor.","Bend up sideways by contracting your oblique.","Finish all reps, then switch sides."],"img":"opengym/5699.webp","gif":null,"ext":1},{"id":"5700","n":"bodyweight walking calf raise","bp":"lower legs","eq":"body weight","tg":"calves","mg":"soleus","sm":["soleus","ankles","feet"],"st":["Stand tall with your feet hip-width apart.","Rise onto the balls of your feet as high as you can.","Take a step forward, staying on your toes.","Keep alternating steps without dropping your heels.","Lower your heels when you reach the end of the set."],"img":"opengym/5700.webp","gif":null,"ext":1},{"id":"5701","n":"barbell pin squat","bp":"upper legs","eq":"barbell","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","core","lower back"],"st":["Set the safety pins at the depth you want and place the bar on them.","Duck under the bar and lift it onto your upper back.","Squat down until the bar rests on the pins.","Pause briefly while staying tight.","Drive up through your whole foot to stand."],"img":"opengym/5701.webp","gif":null,"ext":1},{"id":"5702","n":"barbell deadlift from deficit","bp":"upper legs","eq":"barbell","tg":"glutes","mg":"hamstrings","sm":["hamstrings","lower back","quadriceps","grip muscles","core"],"st":["Stand on a low plate or platform with the bar over mid-foot.","Hinge down and grip the bar just outside your legs.","Flatten your back and brace your core.","Push the floor away and stand tall.","Lower the bar back under control."],"img":"opengym/5702.webp","gif":null,"ext":1},{"id":"5703","n":"cable incline biceps curl","bp":"upper arms","eq":"cable","tg":"biceps","mg":"brachialis","sm":["brachialis","forearms"],"st":["Set a low cable and lie back on an incline bench facing away from the stack.","Hold the handles with your arms hanging behind you.","Curl the handles up toward your shoulders.","Keep your elbows back and still.","Lower slowly until your arms are straight."],"img":"opengym/5703.webp","gif":null,"ext":1},{"id":"5704","n":"barbell hang power clean","bp":"upper legs","eq":"olympic barbell","tg":"glutes","mg":"hamstrings","sm":["hamstrings","trapezius","quadriceps","shoulders","forearms"],"st":["Hold the bar at mid-thigh with an overhand grip and a flat back.","Hinge slightly so the bar sits just above your knees.","Jump and shrug explosively, extending hips and knees.","Pull yourself under the bar and catch it on your shoulders in a quarter squat.","Stand tall, then lower the bar back to the hang."],"img":"opengym/5704.webp","gif":null,"ext":1},{"id":"5705","n":"barbell clean high pull","bp":"upper legs","eq":"olympic barbell","tg":"traps","mg":"glutes","sm":["glutes","hamstrings","shoulders","upper back","quadriceps"],"st":["Set up over the bar with feet hip-width apart and a flat back.","Lift the bar to your knees with your chest up.","Extend your hips and knees explosively and shrug hard.","Pull the bar up to chest height with elbows high and outside.","Lower the bar back to the floor with control."],"img":"opengym/5705.webp","gif":null,"ext":1},{"id":"5706","n":"barbell jefferson deadlift","bp":"upper legs","eq":"barbell","tg":"glutes","mg":"hamstrings","sm":["hamstrings","quadriceps","adductors","lower back","core"],"st":["Stand straddling the bar with one foot forward and one back.","Squat down and grip the bar with one hand in front and one behind.","Brace your core and lift your chest.","Stand up by driving through both legs.","Lower the bar with control and switch your stance on the next set."],"img":"opengym/5706.webp","gif":null,"ext":1},{"id":"5741","n":"cable kneeling crunch v. 2","bp":"waist","eq":"cable","tg":"abs","mg":"obliques","sm":["obliques","lower abs","hip flexors"],"st":["Kneel below a high cable with the rope held beside your head.","Keep your hips still and your back slightly rounded.","Crunch down, bringing your elbows toward your knees.","Squeeze your abs at the bottom.","Return slowly to the start without sitting back on your heels."],"img":"opengym/5741.webp","gif":null,"ext":1},{"id":"5745","n":"plyo squat","bp":"upper legs","eq":"body weight","tg":"quads","mg":"glutes","sm":["glutes","calves","hamstrings"],"st":["Stand with your feet shoulder-width apart.","Sit into a squat with your chest up.","Explode upward and jump as high as you can.","Land softly on bent knees and go straight into the next squat.","Keep your knees tracking over your toes."],"img":"opengym/5745.webp","gif":null,"ext":1},{"id":"5754","n":"dumbbell hip thrust v. 2","bp":"upper legs","eq":"dumbbell","tg":"glutes","mg":"hamstrings","sm":["hamstrings","quadriceps","core"],"st":["Sit with your upper back against a bench and a dumbbell on your hips.","Plant your feet flat, shoulder-width apart.","Drive through your heels and lift your hips until your torso is level.","Squeeze your glutes at the top with your chin tucked.","Lower under control and repeat."],"img":"opengym/5754.webp","gif":null,"ext":1},{"id":"5774","n":"single leg thrusts","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"hamstrings","sm":["hamstrings","core"],"st":["Rest your upper back on a bench with one foot flat and the other leg lifted.","Keep your arms out for balance.","Drive through your heel to lift your hips until level.","Squeeze your glute at the top.","Lower with control and switch legs after your reps."],"img":"opengym/5774.webp","gif":null,"ext":1},{"id":"5784","n":"lever reverse vertical hack squat","bp":"upper legs","eq":"leverage machine","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","calves"],"st":["Set the machine and stand with your chest against the pad, feet on the platform.","Grip the handles and brace your core.","Bend your knees and lower until your thighs are about parallel.","Press through your whole foot to stand.","Keep your knees tracking over your toes."],"img":"opengym/5784.webp","gif":null,"ext":1},{"id":"5800","n":"bodyweight lying prone ys","bp":"back","eq":"body weight","tg":"upper back","mg":"rear deltoids","sm":["rear deltoids","trapezius","lower back","rhomboids"],"st":["Lie face down with your arms extended overhead in a Y.","Turn your thumbs toward the ceiling.","Lift your arms off the floor, squeezing your shoulder blades.","Hold briefly at the top.","Lower with control and repeat."],"img":"opengym/5800.webp","gif":null,"ext":1},{"id":"5801","n":"band assisted muscle up","bp":"back","eq":"band","tg":"lats","mg":"biceps","sm":["biceps","triceps","chest","shoulders","core"],"st":["Loop a band over the bar and place your foot or knee in it.","Hang from the bar with a false or overhand grip.","Pull explosively, bringing your chest to the bar.","Lean over the bar and press yourself up to straight arms.","Lower back down slowly and repeat."],"img":"opengym/5801.webp","gif":null,"ext":1},{"id":"5803","n":"reverse hyperextension on bench","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"hamstrings","sm":["hamstrings","lower back","core"],"st":["Lie face down on a bench with your hips at the edge and legs hanging.","Hold the bench for support.","Squeeze your glutes and lift your legs until level with your body.","Pause at the top.","Lower your legs slowly without swinging."],"img":"opengym/5803.webp","gif":null,"ext":1},{"id":"5805","n":"wide glute pulse bridge","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"hamstrings","sm":["hamstrings","adductors"],"st":["Lie on your back with your knees bent and feet wide apart.","Lift your hips to the top of a bridge.","Pulse your hips up and down in small, controlled movements.","Keep your glutes squeezed throughout.","Lower fully after your set."],"img":"opengym/5805.webp","gif":null,"ext":1},{"id":"5810","n":"kicks leg bent","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"hamstrings","sm":["hamstrings","core","lower back"],"st":["Get on all fours with hands under shoulders and knees under hips.","Keep your core tight and back flat.","Lift one leg with the knee bent, pressing your foot toward the ceiling.","Squeeze your glute at the top.","Lower and repeat, then switch legs."],"img":"opengym/5810.webp","gif":null,"ext":1},{"id":"5813","n":"45 degree hyperextension (arms in front of chest)","bp":"back","eq":"body weight","tg":"spine","mg":"glutes","sm":["glutes","hamstrings","core"],"st":["Set the pad at hip height and hook your heels under the rollers.","Cross your arms over your chest.","Lower your torso with a straight back.","Raise yourself until your body forms a straight line.","Squeeze your glutes at the top and lower slowly."],"img":"opengym/5813.webp","gif":null,"ext":1},{"id":"5814","n":"cable low chest press","bp":"chest","eq":"cable","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders","upper chest"],"st":["Set the pulleys low and hold a handle in each hand.","Step forward into a split stance with elbows bent.","Press the handles up and forward in an arc.","Squeeze your chest as your hands meet.","Return slowly to the start."],"img":"opengym/5814.webp","gif":null,"ext":1},{"id":"5815","n":"lever one arm side chest press","bp":"chest","eq":"leverage machine","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders"],"st":["Sit in the machine with your back against the pad.","Grip one handle at chest level.","Press the handle forward until your arm is straight.","Squeeze your chest at the end.","Return slowly and switch arms after your set."],"img":"opengym/5815.webp","gif":null,"ext":1},{"id":"5816","n":"dumbbell one arm side lying bench press","bp":"chest","eq":"dumbbell","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders","core"],"st":["Lie on your side on a flat bench with a dumbbell in the top hand.","Bring the weight to your chest.","Press the dumbbell up until your arm is straight.","Lower it slowly to the chest.","Complete your reps, then switch sides."],"img":"opengym/5816.webp","gif":null,"ext":1},{"id":"5817","n":"dumbbell side lying external rotation (on a bench)","bp":"shoulders","eq":"dumbbell","tg":"delts","mg":"rotator cuff","sm":["rotator cuff","rear deltoids"],"st":["Lie on your side on a bench with a light dumbbell in the top hand.","Keep your elbow bent at 90 degrees and tucked to your side.","Rotate your forearm upward, keeping your elbow still.","Pause at the top.","Lower slowly and switch sides after your set."],"img":"opengym/5817.webp","gif":null,"ext":1},{"id":"5818","n":"weighted full can exercise","bp":"shoulders","eq":"weighted","tg":"delts","mg":"rotator cuff","sm":["rotator cuff","upper chest","trapezius"],"st":["Hold a light weight in each hand with thumbs pointing up.","Stand tall with arms at your sides.","Raise your arms diagonally forward to about shoulder height.","Pause briefly.","Lower slowly with control."],"img":"opengym/5818.webp","gif":null,"ext":1},{"id":"5819","n":"dumbbell empty can exercise","bp":"shoulders","eq":"dumbbell","tg":"delts","mg":"rotator cuff","sm":["rotator cuff","trapezius","upper chest"],"st":["Hold light dumbbells with your thumbs pointing down.","Stand tall with arms at your sides.","Raise your arms diagonally forward to shoulder height.","Hold briefly without shrugging.","Lower slowly with control."],"img":"opengym/5819.webp","gif":null,"ext":1},{"id":"5820","n":"dumbbell prone full can exercise","bp":"shoulders","eq":"dumbbell","tg":"delts","mg":"rear deltoids","sm":["rear deltoids","rotator cuff","upper back","trapezius"],"st":["Lie face down on a bench or floor with light dumbbells hanging.","Turn your thumbs to the ceiling.","Raise your arms out diagonally into a Y.","Squeeze your shoulder blades together.","Lower slowly under control."],"img":"opengym/5820.webp","gif":null,"ext":1},{"id":"5821","n":"cable kneeling shoulder 90 degrees external rotation press","bp":"shoulders","eq":"cable","tg":"delts","mg":"rotator cuff","sm":["rotator cuff","triceps","core","rear deltoids"],"st":["Kneel next to a cable with your elbow at shoulder height and bent 90 degrees.","Hold the handle and brace your core.","Rotate your forearm upward until it points to the ceiling.","Press the handle overhead.","Reverse the movement slowly and switch sides."],"img":"opengym/5821.webp","gif":null,"ext":1},{"id":"5822","n":"prone y raise","bp":"back","eq":"body weight","tg":"upper back","mg":"rear deltoids","sm":["rear deltoids","trapezius","lower back","rhomboids"],"st":["Lie face down with arms stretched overhead in a Y.","Turn your thumbs up.","Lift your arms, squeezing your shoulder blades.","Hold briefly at the top.","Lower with control."],"img":"opengym/5822.webp","gif":null,"ext":1},{"id":"5823","n":"barbell walking lunge","bp":"upper legs","eq":"barbell","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","core","adductors"],"st":["Place a barbell on your upper back and stand tall.","Step forward and lower until both knees are bent about 90 degrees.","Keep your torso upright.","Push through your front foot and bring the back leg forward into the next step.","Continue alternating legs for the set distance."],"img":"opengym/5823.webp","gif":null,"ext":1},{"id":"5825","n":"smith rear lunge v. 2","bp":"upper legs","eq":"smith machine","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","core"],"st":["Set the bar on your upper back and stand tall.","Step one foot back behind you.","Lower until your front thigh is about parallel to the floor.","Push through your front heel to return.","Finish your reps, then switch legs."],"img":"opengym/5825.webp","gif":null,"ext":1},{"id":"5837","n":"resistance band pull through","bp":"upper legs","eq":"resistance band","tg":"glutes","mg":"hamstrings","sm":["hamstrings","lower back","core"],"st":["Anchor the band low and face away from it, holding the band between your legs.","Step forward until you feel tension, feet shoulder-width apart.","Push your hips back with a flat back.","Squeeze your glutes and drive your hips forward to stand tall.","Keep your arms relaxed and straight."],"img":"opengym/5837.webp","gif":null,"ext":1},{"id":"5843","n":"lever incline fly","bp":"chest","eq":"leverage machine","tg":"pectorals","mg":"shoulders","sm":["shoulders","upper chest"],"st":["Sit in the machine with your back against the pad.","Grip the handles with elbows slightly bent.","Bring the handles together in front of your upper chest.","Squeeze your chest.","Return slowly to a comfortable stretch."],"img":"opengym/5843.webp","gif":null,"ext":1},{"id":"5844","n":"single arm side straight arm lat pulldown","bp":"back","eq":"cable","tg":"lats","mg":"triceps","sm":["triceps","core","rear deltoids"],"st":["Stand facing a high cable with one handle in your hand.","Keep your arm nearly straight and slightly angled.","Pull the handle down toward your thigh by squeezing your lat.","Hold briefly.","Let it rise slowly and switch sides after your set."],"img":"opengym/5844.webp","gif":null,"ext":1},{"id":"5846","n":"cross standing crunch","bp":"waist","eq":"body weight","tg":"abs","mg":"obliques","sm":["obliques","hip flexors"],"st":["Stand tall with your hands behind your head.","Lift one knee and rotate your torso.","Bring the opposite elbow toward that knee.","Return to standing.","Alternate sides for the set."],"img":"opengym/5846.webp","gif":null,"ext":1},{"id":"5853","n":"barbell incline rear delt row","bp":"shoulders","eq":"barbell","tg":"delts","mg":"rear deltoids","sm":["rear deltoids","upper back","rhomboids","trapezius"],"st":["Lie face down on an incline bench holding a barbell with a wide grip.","Let your arms hang straight down.","Row the bar up with elbows flared out.","Squeeze your shoulder blades at the top.","Lower slowly."],"img":"opengym/5853.webp","gif":null,"ext":1},{"id":"5854","n":"kettlebell standing calf raise","bp":"lower legs","eq":"kettlebell","tg":"calves","mg":"soleus","sm":["soleus","ankles","feet"],"st":["Hold a kettlebell in one hand and stand on the balls of your feet on a step if you like.","Keep your knees nearly straight.","Rise as high as you can on your toes.","Pause at the top.","Lower your heels slowly."],"img":"opengym/5854.webp","gif":null,"ext":1},{"id":"5855","n":"kettlebell clean and press","bp":"shoulders","eq":"kettlebell","tg":"delts","mg":"triceps","sm":["triceps","glutes","hamstrings","core","trapezius"],"st":["Stand with a kettlebell between your feet and hinge to grip it.","Drive your hips forward and pull the bell up to your shoulder.","Brace your core and press the bell overhead.","Lock out your arm with the bicep near your ear.","Lower to the shoulder, then back to the floor, and switch sides."],"img":"opengym/5855.webp","gif":null,"ext":1},{"id":"5856","n":"kettlebell concentration curl","bp":"upper arms","eq":"kettlebell","tg":"biceps","mg":"brachialis","sm":["brachialis","forearms"],"st":["Sit with your legs apart and a kettlebell in one hand.","Rest your elbow against your inner thigh.","Curl the kettlebell up toward your shoulder.","Squeeze at the top.","Lower slowly and switch arms."],"img":"opengym/5856.webp","gif":null,"ext":1},{"id":"5857","n":"kettlebell biceps curl","bp":"upper arms","eq":"kettlebell","tg":"biceps","mg":"brachialis","sm":["brachialis","forearms","grip muscles"],"st":["Stand holding a kettlebell by the handle with both hands or one.","Keep your elbows at your sides.","Curl the kettlebell toward your chest.","Squeeze your biceps.","Lower with control."],"img":"opengym/5857.webp","gif":null,"ext":1},{"id":"5858","n":"kettlebell floor fly","bp":"chest","eq":"kettlebell","tg":"pectorals","mg":"shoulders","sm":["shoulders","triceps"],"st":["Lie on your back holding a kettlebell in each hand above your chest.","Keep a slight bend in your elbows.","Lower your arms out to the sides until the elbows touch the floor.","Squeeze your chest to bring the weights back up.","Repeat with control."],"img":"opengym/5858.webp","gif":null,"ext":1},{"id":"5859","n":"kettlebell front raise","bp":"shoulders","eq":"kettlebell","tg":"delts","mg":"upper chest","sm":["upper chest","trapezius","core"],"st":["Stand tall holding a kettlebell with both hands by the sides of the handle.","Keep your arms nearly straight.","Raise the kettlebell to shoulder height.","Pause briefly.","Lower slowly without swinging."],"img":"opengym/5859.webp","gif":null,"ext":1},{"id":"5860","n":"kettlebell overhead triceps extension","bp":"upper arms","eq":"kettlebell","tg":"triceps","mg":"shoulders","sm":["shoulders","core"],"st":["Hold a kettlebell by the horns with both hands overhead.","Keep your elbows pointing forward.","Lower the weight behind your head by bending your elbows.","Extend your arms until they are straight.","Repeat without flaring your elbows."],"img":"opengym/5860.webp","gif":null,"ext":1},{"id":"5861","n":"kettlebell lying triceps extension skull crusher","bp":"upper arms","eq":"kettlebell","tg":"triceps","mg":"shoulders","sm":["shoulders","forearms"],"st":["Lie on a bench holding a kettlebell above your chest.","Keep your upper arms still.","Bend your elbows to lower the weight toward your forehead.","Extend your arms back to the start.","Repeat with control."],"img":"opengym/5861.webp","gif":null,"ext":1},{"id":"5862","n":"kettlebell wrist curl","bp":"lower arms","eq":"kettlebell","tg":"forearms","mg":"wrist flexors","sm":["wrist flexors","grip muscles"],"st":["Sit with your forearm on your thigh, palm up, holding a kettlebell.","Let your wrist extend downward.","Curl your hand up toward you.","Squeeze at the top.","Lower slowly and switch arms."],"img":"opengym/5862.webp","gif":null,"ext":1},{"id":"5863","n":"kettlebell standing one arm extension","bp":"upper arms","eq":"kettlebell","tg":"triceps","mg":"shoulders","sm":["shoulders","core"],"st":["Stand tall with a kettlebell held overhead in one hand.","Keep your upper arm close to your head.","Lower the weight behind your head by bending the elbow.","Straighten your arm back to the top.","Switch sides after your set."],"img":"opengym/5863.webp","gif":null,"ext":1},{"id":"5864","n":"bodyweight swing","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"hamstrings","sm":["hamstrings","core","shoulders"],"st":["Stand with feet shoulder-width apart and arms hanging.","Hinge back at your hips and swing your arms between your legs.","Snap your hips forward and stand tall.","Let your arms float up to chest height.","Repeat in a smooth rhythm."],"img":"opengym/5864.webp","gif":null,"ext":1},{"id":"5865","n":"wide stance jump squat to narrow stance jump squat","bp":"upper legs","eq":"body weight","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","adductors","calves"],"st":["Stand with your feet wide and squat down.","Jump up, bringing your feet together mid-air.","Land softly in a narrow stance and squat.","Jump again, landing back in the wide stance.","Keep your chest up and move at a steady pace."],"img":"opengym/5865.webp","gif":null,"ext":1},{"id":"5866","n":"decline diamond push up","bp":"chest","eq":"body weight","tg":"triceps","mg":"chest","sm":["chest","shoulders","core"],"st":["Place your feet on a bench and your hands close together under your chest.","Form a diamond with your thumbs and index fingers.","Lower your chest toward your hands.","Keep your body in a straight line.","Push back up to straight arms."],"img":"opengym/5866.webp","gif":null,"ext":1},{"id":"5867","n":"kettlebell bent over alternate twist row","bp":"back","eq":"kettlebell","tg":"upper back","mg":"lats","sm":["lats","rhomboids","biceps","obliques","core"],"st":["Hinge forward with a flat back holding a kettlebell in each hand.","Row one kettlebell toward your hip.","Rotate your torso slightly as you pull.","Lower the weight and repeat on the other side.","Alternate sides for the set."],"img":"opengym/5867.webp","gif":null,"ext":1},{"id":"5873","n":"ez barbell lying triceps extension","bp":"upper arms","eq":"ez barbell","tg":"triceps","mg":"shoulders","sm":["shoulders","forearms"],"st":["Lie on a bench holding an EZ bar above your chest.","Keep your upper arms vertical.","Bend your elbows to lower the bar toward your forehead.","Extend your arms back to the start.","Keep your elbows from flaring."],"img":"opengym/5873.webp","gif":null,"ext":1},{"id":"5874","n":"cable high pulley straight bar overhead triceps extension","bp":"upper arms","eq":"cable","tg":"triceps","mg":"shoulders","sm":["shoulders","core"],"st":["Attach a straight bar to a high pulley and face away from it.","Hold the bar behind your head with elbows bent.","Keep your elbows pointing forward.","Extend your arms forward and up.","Return slowly."],"img":"opengym/5874.webp","gif":null,"ext":1},{"id":"5876","n":"suspension triceps extension","bp":"upper arms","eq":"suspension trainer","tg":"triceps","mg":"shoulders","sm":["shoulders","core"],"st":["Hold the handles and lean forward with a straight body.","Start with your arms overhead and elbows bent.","Extend your arms, keeping your upper arms still.","Pause when your arms are straight.","Lower back slowly."],"img":"opengym/5876.webp","gif":null,"ext":1},{"id":"5879","n":"kettlebell side plank","bp":"waist","eq":"kettlebell","tg":"obliques","mg":"abdominals","sm":["abdominals","shoulders","glutes"],"st":["Lie on your side with your elbow under your shoulder.","Lift your hips into a straight line.","Hold a kettlebell in your top hand pointing up.","Hold for 20-30 seconds.","Lower and switch sides."],"img":"opengym/5879.webp","gif":null,"ext":1},{"id":"5880","n":"kettlebell calf raise and front squat","bp":"upper legs","eq":"kettlebell","tg":"quads","mg":"glutes","sm":["glutes","calves","core"],"st":["Hold a kettlebell at your chest with both hands.","Squat down with your chest up and knees tracking over your toes.","Drive up to standing.","At the top, rise onto your toes for a calf raise.","Lower your heels and repeat with control."],"img":"opengym/5880.webp","gif":null,"ext":1},{"id":"5881","n":"crab walk","bp":"full body","eq":"body weight","tg":"glutes","mg":"triceps","sm":["triceps","shoulders","core","quadriceps"],"st":["Sit on the floor, place your hands behind you and lift your hips off the ground.","Keep your hips high and your core braced.","Step with opposite hand and foot to move forward.","Walk for several steps, then go backward.","Keep your head neutral and your arms steady."],"img":"opengym/5881.webp","gif":null,"ext":1},{"id":"5882","n":"bodyweight wood chop squat","bp":"waist","eq":"body weight","tg":"obliques","mg":"abdominals","sm":["abdominals","glutes","quadriceps","shoulders"],"st":["Stand with feet shoulder-width apart and hands clasped above one shoulder.","Squat down while chopping your hands diagonally toward the opposite knee.","Rotate through your trunk and let your back foot pivot.","Stand up as you swing your arms back up.","Finish all reps, then switch sides."],"img":"opengym/5882.webp","gif":null,"ext":1},{"id":"5883","n":"barbell curl press extension","bp":"upper arms","eq":"barbell","tg":"biceps","mg":"shoulders","sm":["shoulders","triceps","forearms"],"st":["Stand holding a barbell with an underhand grip at thigh level.","Curl the bar up to your shoulders without swinging.","Press it overhead until your arms are straight.","Bend your elbows to lower the bar behind your head, keeping your upper arms still.","Extend, bring the bar back to the front and lower it under control.","Use a light weight to keep your form tidy."],"img":"opengym/5883.webp","gif":null,"ext":1},{"id":"5884","n":"dumbbell curl press extension","bp":"upper arms","eq":"dumbbell","tg":"biceps","mg":"shoulders","sm":["shoulders","triceps","forearms"],"st":["Stand with a dumbbell in each hand, arms at your sides.","Curl both dumbbells up to shoulder height.","Press them overhead until your arms are straight.","Bend your elbows to lower the weights behind your head.","Extend your arms, then bring the dumbbells back to your shoulders and down to your sides.","Keep your torso still and choose a manageable weight."],"img":"opengym/5884.webp","gif":null,"ext":1},{"id":"5885","n":"lotus pose breathing","bp":"full body","eq":"body weight","tg":"spine","mg":"core","sm":["core","hip flexors"],"st":["Sit on the floor with your legs crossed and each foot resting on the opposite thigh if comfortable.","Rest your hands on your knees and lengthen your spine.","Inhale slowly through your nose and fill your belly and chest.","Exhale slowly and fully.","Keep your shoulders relaxed and breathe steadily for 1-2 minutes."],"img":"opengym/5885.webp","gif":null,"ext":1},{"id":"5886","n":"kettlebell rotational deadlift","bp":"upper legs","eq":"kettlebell","tg":"glutes","mg":"hamstrings","sm":["hamstrings","lower back","obliques","core"],"st":["Stand with feet hip-width apart holding a kettlebell in both hands.","Push your hips back and lower the bell toward the outside of one foot.","Rotate your torso slightly as you reach, keeping your back flat.","Drive your hips forward to stand and unwind.","Repeat to the same side, then switch."],"img":"opengym/5886.webp","gif":null,"ext":1},{"id":"5887","n":"3 leg dog pose","bp":"full body","eq":"body weight","tg":"hamstrings","mg":"shoulders","sm":["shoulders","calves","glutes","core"],"st":["Start in downward dog with hands shoulder-width apart.","Press your hands into the floor and lengthen your spine.","Lift one leg straight up behind you, keeping your hips square.","Hold for 5 slow breaths.","Lower and switch legs."],"img":"opengym/5887.webp","gif":null,"ext":1},{"id":"5888","n":"chaturanga pose","bp":"upper arms","eq":"body weight","tg":"triceps","mg":"chest","sm":["chest","shoulders","core"],"st":["Start in a high plank with your wrists under your shoulders.","Shift slightly forward on your toes.","Bend your elbows straight back and lower to elbow height.","Keep your body in one line and your elbows near your ribs.","Hold briefly, then press back up."],"img":"opengym/5888.webp","gif":null,"ext":1},{"id":"5889","n":"corpse pose savasana","bp":"full body","eq":"body weight","tg":"spine","mg":null,"sm":[],"st":["Lie flat on your back with your legs extended and slightly apart.","Let your arms rest by your sides with palms up.","Close your eyes and let your whole body soften.","Breathe slowly for 2-5 minutes.","Roll to your side and sit up gently."],"img":"opengym/5889.webp","gif":null,"ext":1},{"id":"5890","n":"double pigeon pose","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"hip flexors","sm":["hip flexors","groin","lower back"],"st":["Sit with your legs crossed and stack one shin on top of the other.","Flex your feet to protect your knees.","Sit tall, then hinge forward over your shins.","Hold for 5 slow breaths.","Swap which leg is on top and repeat."],"img":"opengym/5890.webp","gif":null,"ext":1},{"id":"5891","n":"high lunge","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","hip flexors","shoulders"],"st":["Step one foot back into a long lunge with your back heel lifted.","Bend your front knee to about 90 degrees over your ankle.","Sweep your arms overhead and stand tall.","Hold for 5 slow breaths.","Step forward and switch legs."],"img":"opengym/5891.webp","gif":null,"ext":1},{"id":"5892","n":"lizard pose","bp":"upper legs","eq":"body weight","tg":"adductors","mg":"hip flexors","sm":["hip flexors","hamstrings","glutes"],"st":["Start in a low lunge with your back knee down or lifted.","Walk your front foot to the outer edge of your mat.","Place both hands inside the front foot.","Hold for 5 slow breaths.","Switch legs."],"img":"opengym/5892.webp","gif":null,"ext":1},{"id":"5894","n":"meditation","bp":"full body","eq":"body weight","tg":"spine","mg":"core","sm":["core"],"st":["Sit comfortably cross-legged, with hips slightly higher than your knees.","Lengthen your spine and relax your shoulders.","Rest your hands on your knees.","Close your eyes and settle into easy breathing.","Stay for 3-10 minutes."],"img":"opengym/5894.webp","gif":null,"ext":1},{"id":"5895","n":"mindful breathing meditation","bp":"full body","eq":"body weight","tg":"spine","mg":"core","sm":["core"],"st":["Sit tall in a comfortable position and relax your shoulders.","Rest your hands on your lap.","Breathe in slowly through your nose.","Breathe out slowly and notice the pause.","Continue for 3-10 minutes."],"img":"opengym/5895.webp","gif":null,"ext":1},{"id":"5896","n":"mountain pose","bp":"full body","eq":"body weight","tg":"spine","mg":"core","sm":["core","glutes","quadriceps","calves"],"st":["Stand with your feet together or hip-width apart.","Spread your toes and press evenly through both feet.","Lengthen your spine and draw your shoulders back and down.","Let your arms hang with palms forward.","Hold for 5 slow breaths."],"img":"opengym/5896.webp","gif":null,"ext":1},{"id":"5897","n":"puppy pose","bp":"back","eq":"body weight","tg":"lats","mg":"shoulders","sm":["shoulders","upper back","triceps"],"st":["Start on hands and knees with your hips over your knees.","Walk your hands forward and lower your chest toward the floor.","Keep your hips high above your knees.","Rest your forehead down and hold for 5 slow breaths.","Walk your hands back to return."],"img":"opengym/5897.webp","gif":null,"ext":1},{"id":"5898","n":"pyramid pose","bp":"upper legs","eq":"body weight","tg":"hamstrings","mg":"calves","sm":["calves","lower back","glutes"],"st":["Step one foot back with both feet facing forward.","Keep both legs straight and your hips square.","Hinge forward from your hips with a long back.","Hold for 5 slow breaths.","Rise slowly and switch legs."],"img":"opengym/5898.webp","gif":null,"ext":1},{"id":"5899","n":"revolved chair","bp":"upper legs","eq":"body weight","tg":"quads","mg":"glutes","sm":["glutes","obliques","core","shoulders"],"st":["Stand and sink your hips back into a chair pose.","Bring your palms together at your chest.","Twist and hook one elbow outside the opposite knee.","Hold for 5 slow breaths with your knees together.","Untwist and repeat on the other side."],"img":"opengym/5899.webp","gif":null,"ext":1},{"id":"5900","n":"revolved side angle pose","bp":"upper legs","eq":"body weight","tg":"quads","mg":"obliques","sm":["obliques","glutes","adductors","shoulders"],"st":["Step into a lunge with your back heel lifted.","Bring your palms together at your chest.","Twist and hook your elbow outside the front knee.","Hold for 5 slow breaths.","Switch sides."],"img":"opengym/5900.webp","gif":null,"ext":1},{"id":"5901","n":"revolved triangle pose","bp":"upper legs","eq":"body weight","tg":"hamstrings","mg":"obliques","sm":["obliques","glutes","lower back","calves"],"st":["Stand with your feet wide, back foot turned slightly.","Hinge forward with a flat back.","Place one hand down and reach the other arm up as you twist.","Hold for 5 slow breaths.","Come up and switch sides."],"img":"opengym/5901.webp","gif":null,"ext":1},{"id":"5902","n":"standing figure four pose","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"hip flexors","sm":["hip flexors","quadriceps","core","ankles"],"st":["Stand tall and shift your weight onto one leg.","Cross the other ankle over the standing thigh.","Bend your standing knee and sit your hips back.","Hold for 5 slow breaths with a long spine.","Switch legs."],"img":"opengym/5902.webp","gif":null,"ext":1},{"id":"5903","n":"standing half bend","bp":"upper legs","eq":"body weight","tg":"hamstrings","mg":"lower back","sm":["lower back","calves","glutes"],"st":["Stand with your feet hip-width apart.","Hinge forward from your hips and bring your hands to your shins or thighs.","Lengthen your spine until your back is flat.","Hold for 5 slow breaths.","Roll up slowly to stand."],"img":"opengym/5903.webp","gif":null,"ext":1},{"id":"5904","n":"thread the needle pose","bp":"back","eq":"body weight","tg":"upper back","mg":"rhomboids","sm":["rhomboids","shoulders","rotator cuff"],"st":["Start on hands and knees.","Slide one arm under your chest and rest your shoulder on the floor.","Keep your hips over your knees.","Hold for 5 slow breaths.","Return and switch arms."],"img":"opengym/5904.webp","gif":null,"ext":1},{"id":"5905","n":"tiger curl pose","bp":"waist","eq":"body weight","tg":"abs","mg":"lower back","sm":["lower back","glutes","hip flexors"],"st":["Start on hands and knees with a neutral spine.","Extend one leg behind you and look slightly forward.","Round your back and draw the knee toward your nose.","Extend again and repeat for 6-8 reps.","Switch legs."],"img":"opengym/5905.webp","gif":null,"ext":1},{"id":"5906","n":"twisted leg lunge pose","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"quadriceps","sm":["quadriceps","obliques","hip flexors"],"st":["Step into a low lunge with your back knee down.","Bring your palms together at your chest.","Twist toward the front leg and hook your elbow outside the knee.","Hold for 5 slow breaths.","Switch legs."],"img":"opengym/5906.webp","gif":null,"ext":1},{"id":"5907","n":"warrior iii pose","bp":"upper legs","eq":"body weight","tg":"hamstrings","mg":"glutes","sm":["glutes","lower back","core","calves"],"st":["Stand on one leg with your arms overhead.","Hinge forward and lift the back leg behind you.","Bring your torso and back leg level with the floor.","Hold for 5 slow breaths with your hips square.","Lower and switch legs."],"img":"opengym/5907.webp","gif":null,"ext":1},{"id":"5908","n":"revolved head to knee pose","bp":"waist","eq":"body weight","tg":"spine","mg":"obliques","sm":["obliques","hamstrings","lats"],"st":["Sit with one leg extended and the other foot against your inner thigh.","Rotate your chest toward the extended leg.","Reach one arm overhead and bend over the leg.","Hold for 5 slow breaths.","Rise and switch sides."],"img":"opengym/5908.webp","gif":null,"ext":1},{"id":"5910","n":"weighted chain sumo deadlift","bp":"upper legs","eq":"barbell","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","adductors","lower back","grip muscles"],"st":["Hang chains on a barbell and stand with a wide stance, toes pointed out.","Grip the bar inside your knees with a flat back.","Push the floor away and drive your knees out.","Stand tall as the chains lift and the load increases.","Lock out with your glutes, then lower the bar under control."],"img":"opengym/5910.webp","gif":null,"ext":1},{"id":"5911","n":"safety bar good morning","bp":"upper legs","eq":"barbell","tg":"hamstrings","mg":"glutes","sm":["glutes","lower back","core"],"st":["Set the safety bar on your upper back and shoulders and hold the handles.","Stand with feet shoulder-width apart and knees slightly bent.","Push your hips back and lower your torso until it is near parallel to the floor.","Keep your back flat and neck neutral.","Drive your hips forward to stand tall."],"img":"opengym/5911.webp","gif":null,"ext":1},{"id":"5912","n":"barbell weighted chains sumo deadlift","bp":"upper legs","eq":"barbell","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","adductors","lower back","grip muscles"],"st":["Loop chains over the ends of a barbell and take a wide stance, toes angled out.","Bend down and grip the bar with your hands inside your knees.","Brace your core and keep your chest up.","Push through your feet and stand, with the chains adding load as you rise.","Lock out your hips, then lower the bar with control."],"img":"opengym/5912.webp","gif":null,"ext":1},{"id":"5913","n":"reverse warrior pose","bp":"upper legs","eq":"body weight","tg":"quads","mg":"obliques","sm":["obliques","lats","glutes","adductors"],"st":["Step into a wide warrior II stance.","Bend your front knee over your ankle.","Reach your front arm up and lean back.","Rest your back hand on your leg.","Hold for 5 slow breaths, then switch."],"img":"opengym/5913.webp","gif":null,"ext":1},{"id":"5914","n":"four limbed staff","bp":"upper arms","eq":"body weight","tg":"triceps","mg":"chest","sm":["chest","shoulders","core"],"st":["Start in a high plank.","Shift slightly forward on your toes.","Bend your elbows straight back and lower.","Keep your body straight like a plank.","Hold briefly, then press back up."],"img":"opengym/5914.webp","gif":null,"ext":1},{"id":"5915","n":"3 leg chaturanga pose","bp":"upper arms","eq":"body weight","tg":"triceps","mg":"chest","sm":["chest","shoulders","core","glutes"],"st":["Start in a high plank and lift one leg behind you.","Keep your hips level.","Bend your elbows back and lower.","Hold briefly with your body in line.","Press up, lower the leg and switch."],"img":"opengym/5915.webp","gif":null,"ext":1},{"id":"5916","n":"cable seated high pulley overhead tricep extension","bp":"upper arms","eq":"cable","tg":"triceps","mg":"shoulders","sm":["shoulders","core"],"st":["Sit facing away from a high pulley and hold the handle overhead with both hands.","Keep your upper arms close to your ears and elbows pointing forward.","Straighten your arms to extend the handle up.","Slowly bend your elbows to lower it behind your head.","Keep your torso upright and your upper arms still."],"img":"opengym/5916.webp","gif":null,"ext":1},{"id":"5917","n":"happy baby pose","bp":"upper legs","eq":"body weight","tg":"adductors","mg":"hamstrings","sm":["hamstrings","groin","lower back","glutes"],"st":["Lie on your back and bend your knees toward your chest.","Hold the outsides of your feet.","Open your knees wide toward your armpits.","Rock gently side to side and hold for 5 slow breaths.","Release your feet and rest."],"img":"opengym/5917.webp","gif":null,"ext":1},{"id":"5921","n":"dumbbell hammer preacher curl","bp":"upper arms","eq":"dumbbell","tg":"biceps","mg":"brachialis","sm":["brachialis","forearms"],"st":["Sit at a preacher bench with your upper arms resting on the pad.","Hold a dumbbell with palm facing in, thumb up.","Curl the weight up toward your shoulder.","Squeeze at the top, then lower slowly until your arm is nearly straight.","Complete your reps, then switch arms or alternate."],"img":"opengym/5921.webp","gif":null,"ext":1},{"id":"5938","n":"russian twist chop","bp":"waist","eq":"body weight","tg":"obliques","mg":"abdominals","sm":["abdominals","shoulders","hip flexors"],"st":["Sit with your knees bent and lean back slightly.","Clasp your hands together in front of you.","Twist and chop your arms diagonally across your body.","Return to center and chop the other way.","Keep your chest tall and your core tight."],"img":"opengym/5938.webp","gif":null,"ext":1},{"id":"5943","n":"cable single arm neutral grip front raise","bp":"shoulders","eq":"cable","tg":"delts","mg":"upper chest","sm":["upper chest","core"],"st":["Stand facing away from a low pulley and hold the handle with a neutral grip.","Keep your arm nearly straight and your core braced.","Raise your arm forward to about shoulder height.","Pause briefly, then lower slowly.","Finish your reps and switch arms."],"img":"opengym/5943.webp","gif":null,"ext":1},{"id":"5944","n":"dumbbell single arm neutral grip front raise","bp":"shoulders","eq":"dumbbell","tg":"delts","mg":"upper chest","sm":["upper chest","core"],"st":["Stand tall holding a dumbbell at your side with palm facing in.","Brace your core and keep a soft bend in your elbow.","Raise the dumbbell forward to shoulder height.","Pause briefly, then lower with control.","Avoid swinging, finish all reps and switch arms."],"img":"opengym/5944.webp","gif":null,"ext":1},{"id":"5963","n":"vertical sit up","bp":"waist","eq":"body weight","tg":"abs","mg":"hip flexors","sm":["hip flexors","obliques"],"st":["Lie on your back with your legs raised straight toward the ceiling.","Place your hands behind your head or across your chest.","Curl your torso up and reach toward your feet.","Pause at the top.","Lower your upper body slowly to the floor."],"img":"opengym/5963.webp","gif":null,"ext":1},{"id":"5965","n":"1 2 stick drill","bp":"full body","eq":"body weight","tg":"cardiovascular system","mg":"quadriceps","sm":["quadriceps","calves","core"],"st":["Stand in an athletic stance with knees slightly bent.","Take quick steps in the set pattern, one then two.","Stay on the balls of your feet.","Keep your arms bent and swinging naturally.","Repeat for 20-30 seconds with sharp, light steps."],"img":"opengym/5965.webp","gif":null,"ext":1},{"id":"5966","n":"jump twist","bp":"full body","eq":"body weight","tg":"quads","mg":"glutes","sm":["glutes","calves","obliques","core"],"st":["Stand with feet shoulder-width apart in a slight squat.","Jump up and rotate your hips and feet to one side.","Land softly with bent knees.","Jump again and twist to the other side.","Keep your chest up and land quietly."],"img":"opengym/5966.webp","gif":null,"ext":1},{"id":"5967","n":"agility ball drill","bp":"full body","eq":"body weight","tg":"cardiovascular system","mg":"quadriceps","sm":["quadriceps","calves","core"],"st":["Set up with a ball in front of you in an athletic stance.","Move quickly around or over the ball with short, light steps.","Keep your hips low and eyes up.","Change direction without crossing your feet.","Work for 20-30 seconds, rest, then repeat."],"img":"opengym/5967.webp","gif":null,"ext":1},{"id":"5968","n":"burpee twist","bp":"full body","eq":"body weight","tg":"cardiovascular system","mg":"chest","sm":["chest","triceps","quadriceps","obliques","core"],"st":["Stand with feet shoulder-width apart.","Squat down, place your hands on the floor and jump your feet back to a plank.","Perform a push-up if you like.","Jump your feet forward under your hips.","Explode up, rotating your trunk as you jump, and land softly.","Alternate twist directions each rep."],"img":"opengym/5968.webp","gif":null,"ext":1},{"id":"5969","n":"dot drill","bp":"lower legs","eq":"body weight","tg":"calves","mg":"quadriceps","sm":["quadriceps","ankles","feet"],"st":["Mark five dots on the floor like the five on a die.","Stand on the balls of your feet next to the pattern.","Hop quickly from dot to dot in your chosen order.","Keep your hops small and your knees soft.","Work for 20-30 seconds, then rest."],"img":"opengym/5969.webp","gif":null,"ext":1},{"id":"5970","n":"heel to toe walk","bp":"full body","eq":"body weight","tg":"calves","mg":"ankles","sm":["ankles","feet","core","glutes"],"st":["Stand tall with your arms out to the sides.","Place your right heel directly in front of your left toes.","Shift your weight forward and step again with the other foot.","Keep your eyes forward and your core gently braced.","Walk 10-15 steps, then turn around and return."],"img":"opengym/5970.webp","gif":null,"ext":1},{"id":"5971","n":"l drill","bp":"full body","eq":"body weight","tg":"cardiovascular system","mg":"quadriceps","sm":["quadriceps","hamstrings","calves","glutes"],"st":["Place three cones in an L shape, about 5 yards apart.","Sprint from the start cone to the second and touch it.","Backpedal to the start.","Sprint to the second again, turn around the cone and weave around the third.","Return to the start along the same line.","Stay low through turns."],"img":"opengym/5971.webp","gif":null,"ext":1},{"id":"5972","n":"ladder drill","bp":"full body","eq":"body weight","tg":"cardiovascular system","mg":"calves","sm":["calves","quadriceps","ankles","core"],"st":["Lay an agility ladder flat on the ground.","Stand at the start in an athletic stance.","Step quickly with both feet into each square, one after another.","Stay light on the balls of your feet.","Pump your arms and keep your eyes up.","Jog back and repeat for several rounds."],"img":"opengym/5972.webp","gif":null,"ext":1},{"id":"5973","n":"lateral ladder drill","bp":"full body","eq":"body weight","tg":"abductors","mg":"adductors","sm":["adductors","calves","quadriceps","core"],"st":["Stand sideways at the start of an agility ladder.","Step both feet into the first square, one at a time.","Move sideways to the next square with quick steps.","Keep your hips low and your feet light.","Finish the ladder, then repeat facing the other way."],"img":"opengym/5973.webp","gif":null,"ext":1},{"id":"5974","n":"plyometric agility drill","bp":"full body","eq":"body weight","tg":"cardiovascular system","mg":"quadriceps","sm":["quadriceps","calves","glutes","core"],"st":["Set out a few markers within a small area.","Stand in an athletic stance on the balls of your feet.","Hop or step quickly between the markers in changing directions.","Land softly with bent knees.","Work for 20-30 seconds, rest, then repeat."],"img":"opengym/5974.webp","gif":null,"ext":1},{"id":"5975","n":"single leg balance cross punch","bp":"full body","eq":"body weight","tg":"abs","mg":"obliques","sm":["obliques","glutes","calves","shoulders"],"st":["Stand on one leg with a slight knee bend and fists up.","Brace your core.","Throw a cross punch, rotating your hips and shoulders.","Pull your fist back to guard.","Keep your standing foot steady.","Finish your reps, then switch legs."],"img":"opengym/5975.webp","gif":null,"ext":1},{"id":"5976","n":"t drill","bp":"full body","eq":"body weight","tg":"cardiovascular system","mg":"quadriceps","sm":["quadriceps","hamstrings","glutes","calves","adductors"],"st":["Set four cones in a T with the top cones 5 yards apart.","Sprint forward to the center cone and touch it.","Shuffle sideways to the left cone and touch it.","Shuffle across to the right cone, then back to the middle.","Backpedal to the start.","Keep your hips low and feet from crossing."],"img":"opengym/5976.webp","gif":null,"ext":1},{"id":"5977","n":"tight rope walk","bp":"full body","eq":"body weight","tg":"calves","mg":"ankles","sm":["ankles","feet","core","glutes"],"st":["Place a line of tape on the floor or imagine one.","Stand at one end with your arms out for balance.","Walk heel to toe along the line.","Keep your gaze ahead and your core braced.","Turn at the end and walk back."],"img":"opengym/5977.webp","gif":null,"ext":1},{"id":"5978","n":"toy soldier dynamic stretch","bp":"upper legs","eq":"body weight","tg":"hamstrings","mg":"glutes","sm":["glutes","hip flexors","core"],"st":["Stand tall with your arms stretched out in front of you.","Kick one straight leg up toward your hands.","Lower it and step forward.","Kick the other leg up.","Keep your chest upright and walk for about 10 reps per side."],"img":"opengym/5978.webp","gif":null,"ext":1},{"id":"5979","n":"x drill","bp":"full body","eq":"body weight","tg":"cardiovascular system","mg":"quadriceps","sm":["quadriceps","hamstrings","glutes","calves"],"st":["Set four cones in a square, with a center point.","Sprint diagonally from one corner through the center to the opposite corner.","Shuffle sideways along one edge to the next corner.","Backpedal or sprint diagonally again.","Stay low through turns and repeat."],"img":"opengym/5979.webp","gif":null,"ext":1},{"id":"5980","n":"sun salutation a","bp":"full body","eq":"body weight","tg":"hamstrings","mg":"shoulders","sm":["shoulders","core","triceps","quadriceps","lower back"],"st":["Stand in mountain pose and sweep your arms overhead.","Fold forward and step back to plank.","Lower, then press into upward dog and downward dog.","Step forward, rise and return to mountain.","Repeat the flow at a steady pace."],"img":"opengym/5980.webp","gif":null,"ext":1},{"id":"5981","n":"sun salutation b","bp":"full body","eq":"body weight","tg":"quads","mg":"hamstrings","sm":["hamstrings","shoulders","core","glutes","triceps"],"st":["Stand in mountain pose and sit into a chair pose with your arms overhead.","Fold forward, step back to plank and flow through chaturanga.","Press to downward dog.","Step forward into warrior I on each side, then flow again.","Link every move to your breath."],"img":"opengym/5981.webp","gif":null,"ext":1},{"id":"5982","n":"half sun salutation","bp":"full body","eq":"body weight","tg":"spine","mg":"hamstrings","sm":["hamstrings","shoulders","core"],"st":["Stand in mountain pose and sweep your arms overhead.","Fold forward with a long spine.","Lift halfway up with a flat back.","Fold again and rise up with your arms overhead.","Lower your hands to your heart and repeat."],"img":"opengym/5982.webp","gif":null,"ext":1},{"id":"5983","n":"vinyasa","bp":"full body","eq":"body weight","tg":"triceps","mg":"chest","sm":["chest","shoulders","core","lower back"],"st":["Start in plank pose.","Lower to chaturanga with your elbows by your ribs.","Roll forward into upward dog with an open chest.","Lift your hips to downward dog.","Hold for a breath or two and repeat."],"img":"opengym/5983.webp","gif":null,"ext":1},{"id":"5984","n":"123 back drill","bp":"full body","eq":"body weight","tg":"cardiovascular system","mg":"quadriceps","sm":["quadriceps","hamstrings","calves","glutes"],"st":["Set a cone line a few yards apart.","Sprint to the first cone and touch it, then back to the start.","Sprint to the second cone and back.","Go to the third cone and back.","Stay low when turning.","Rest, then repeat."],"img":"opengym/5984.webp","gif":null,"ext":1},{"id":"5985","n":"balloon drill","bp":"upper legs","eq":"body weight","tg":"quads","mg":"glutes","sm":["glutes","calves","core"],"st":["Toss a balloon into the air in an open space.","Stay on the balls of your feet with bent knees.","Move under the balloon and tap it up.","Use small hops to reach it.","Keep it up for 30-60 seconds."],"img":"opengym/5985.webp","gif":null,"ext":1},{"id":"5986","n":"cone drill","bp":"full body","eq":"body weight","tg":"cardiovascular system","mg":"quadriceps","sm":["quadriceps","hamstrings","calves","glutes"],"st":["Place several cones in a pattern a few yards apart.","Start in an athletic stance.","Sprint or shuffle around the cones in order.","Plant and cut with your hips low.","Finish the course, rest, then go again."],"img":"opengym/5986.webp","gif":null,"ext":1},{"id":"5988","n":"bottle weighted deadlift","bp":"upper legs","eq":"weighted","tg":"glutes","mg":"hamstrings","sm":["hamstrings","lower back","forearms"],"st":["Hold a bottle in each hand and stand with feet hip-width apart.","Hinge at your hips with a flat back and soft knees.","Lower the bottles along your legs to mid-shin.","Drive your hips forward to stand tall.","Squeeze your glutes at the top."],"img":"opengym/5988.webp","gif":null,"ext":1},{"id":"5989","n":"figure run","bp":"full body","eq":"body weight","tg":"cardiovascular system","mg":"quadriceps","sm":["quadriceps","hamstrings","calves","glutes"],"st":["Set two cones about 5 yards apart.","Start next to one cone in an athletic stance.","Run a figure-eight around both cones.","Lean into the turns and keep your hips low.","Run for 20-30 seconds, then change direction."],"img":"opengym/5989.webp","gif":null,"ext":1},{"id":"5990","n":"high hurdle jump to sprint and cut","bp":"full body","eq":"body weight","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","calves","core"],"st":["Stand facing a high hurdle with feet shoulder-width apart.","Swing your arms and jump over it, tucking your knees.","Land softly with bent knees.","Sprint forward right away.","Plant and cut sharply to one side.","Walk back and repeat, alternating cut directions."],"img":"opengym/5990.webp","gif":null,"ext":1},{"id":"5991","n":"partner shuffle","bp":"full body","eq":"body weight","tg":"abductors","mg":"adductors","sm":["adductors","quadriceps","calves","glutes"],"st":["Face a partner about 2 yards away in an athletic stance.","Have your partner move left or right.","Shuffle sideways to mirror them without crossing your feet.","Keep your hips low and chest up.","Work for 20-30 seconds, then swap roles."],"img":"opengym/5991.webp","gif":null,"ext":1},{"id":"5997","n":"lay down push up","bp":"chest","eq":"body weight","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders","core"],"st":["Lie face down with your hands under your shoulders.","Brace your core and glutes.","Push your body up into a straight plank.","Lower yourself all the way down until your chest rests on the floor.","Relax briefly, then push up again."],"img":"opengym/5997.webp","gif":null,"ext":1},{"id":"5998","n":"side lying hip adduction (left)","bp":"upper legs","eq":"body weight","tg":"adductors","mg":"inner thighs","sm":["inner thighs","glutes","core"],"st":["Lie on your left side with your legs straight.","Bend your right knee and place that foot in front of you.","Raise your left leg a few inches off the floor.","Pause at the top.","Lower slowly and repeat, then switch sides."],"img":"opengym/5998.webp","gif":null,"ext":1},{"id":"6000","n":"single leg bridge with outstretched leg (left)","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"hamstrings","sm":["hamstrings","core","lower back"],"st":["Lie on your back with your knees bent and feet flat.","Extend your left leg straight out.","Drive through your right heel to lift your hips.","Keep your hips level.","Pause at the top.","Lower slowly, finish your reps and switch legs."],"img":"opengym/6000.webp","gif":null,"ext":1},{"id":"6001","n":"single straight leg glute bridge hold (left)","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"hamstrings","sm":["hamstrings","core"],"st":["Lie on your back with both knees bent.","Straighten your left leg in line with your torso.","Press through the right heel to lift your hips.","Hold for 20-30 seconds with your hips level.","Lower slowly."],"img":"opengym/6001.webp","gif":null,"ext":1},{"id":"6005","n":"lying crunch (straight legs)","bp":"waist","eq":"body weight","tg":"abs","mg":"obliques","sm":["obliques"],"st":["Lie on your back with your legs straight.","Place your hands behind your head or across your chest.","Curl your shoulders off the floor.","Pause and squeeze your abs.","Lower slowly without pulling on your neck."],"img":"opengym/6005.webp","gif":null,"ext":1},{"id":"6006","n":"half squat side reach","bp":"waist","eq":"body weight","tg":"abs","mg":"obliques","sm":["obliques","quadriceps","glutes"],"st":["Stand with feet wider than shoulder-width.","Sit into a half squat.","Reach one arm overhead and lean sideways.","Return to center.","Reach to the other side.","Keep your chest up."],"img":"opengym/6006.webp","gif":null,"ext":1},{"id":"6007","n":"low lunge","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hip flexors","groin"],"st":["Step one foot forward into a lunge and lower your back knee.","Keep your front knee over your ankle.","Push your hips forward and lift your chest.","Reach your arms overhead if you like.","Hold for 20-30 seconds, then switch legs."],"img":"opengym/6007.webp","gif":null,"ext":1},{"id":"6008","n":"low lunge (left)","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hip flexors","groin"],"st":["Step your right foot forward and lower your left knee to the floor.","Keep your front knee over your ankle.","Push your hips forward and lift your chest.","Reach your arms overhead if you like.","Hold for 20-30 seconds, then switch legs."],"img":"opengym/6008.webp","gif":null,"ext":1},{"id":"6010","n":"celebratory knee drives","bp":"full body","eq":"body weight","tg":"hip flexors","mg":"quadriceps","sm":["quadriceps","glutes","shoulders","core"],"st":["Stand tall with your feet hip-width apart.","Drive one knee up as you raise your arms in a victory pose.","Lower and switch.","Keep a quick, bouncy rhythm.","Land lightly and work for 30 seconds."],"img":"opengym/6010.webp","gif":null,"ext":1},{"id":"6011","n":"side step rear delt row","bp":"shoulders","eq":"body weight","tg":"delts","mg":"rhomboids","sm":["rhomboids","upper back","quadriceps","glutes"],"st":["Stand in a slight squat with your arms out in front.","Step to the side.","Pull your elbows back and squeeze your shoulder blades.","Return your arms forward as you step back.","Alternate sides at a steady pace."],"img":"opengym/6011.webp","gif":null,"ext":1},{"id":"6013","n":"front leg kick","bp":"full body","eq":"body weight","tg":"hamstrings","mg":"glutes","sm":["glutes","hip flexors","core"],"st":["Stand tall with your arms at your sides.","Kick one straight leg up in front of you.","Lower it under control.","Switch legs in a smooth rhythm.","Keep your torso upright."],"img":"opengym/6013.webp","gif":null,"ext":1},{"id":"6014","n":"arm raise step in place","bp":"full body","eq":"body weight","tg":"cardiovascular system","mg":"shoulders","sm":["shoulders","quadriceps","calves"],"st":["Stand tall with your feet hip-width apart.","Step in place, lifting your knees.","Raise your arms overhead as you step.","Lower them as you continue.","Keep a steady rhythm for 30-60 seconds."],"img":"opengym/6014.webp","gif":null,"ext":1},{"id":"6016","n":"twisting crunch v. 2","bp":"waist","eq":"body weight","tg":"obliques","mg":"abdominals","sm":["abdominals","hip flexors"],"st":["Lie on your back with knees bent and hands behind your head.","Curl your shoulders off the floor.","Twist to bring one elbow toward the opposite knee.","Lower slowly.","Alternate sides for your reps."],"img":"opengym/6016.webp","gif":null,"ext":1},{"id":"6017","n":"stepback pulldown","bp":"back","eq":"body weight","tg":"lats","mg":"upper back","sm":["upper back","core","quadriceps"],"st":["Stand tall with your arms overhead.","Step one foot back.","Pull your elbows down and in as if doing a pulldown.","Return your arms and foot to start.","Alternate legs at a steady pace."],"img":"opengym/6017.webp","gif":null,"ext":1},{"id":"6019","n":"lying hyperextension hold","bp":"back","eq":"body weight","tg":"spine","mg":"glutes","sm":["glutes","hamstrings"],"st":["Lie face down with your arms extended.","Lift your chest, arms and legs a few inches.","Keep your neck neutral.","Squeeze your glutes and hold for 15-30 seconds.","Lower slowly."],"img":"opengym/6019.webp","gif":null,"ext":1},{"id":"6024","n":"lying alternate frog kick","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"hamstrings","sm":["hamstrings","lower back","core"],"st":["Lie face down with your arms under your forehead.","Bend one knee to 90 degrees with the sole toward the ceiling.","Lift that thigh off the floor by squeezing the glute.","Lower and switch legs.","Keep your hips on the floor."],"img":"opengym/6024.webp","gif":null,"ext":1},{"id":"6025","n":"lying frog kick","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"hamstrings","sm":["hamstrings","lower back","core"],"st":["Lie face down, knees bent and heels together.","Let your knees fall slightly out.","Lift both thighs off the floor by squeezing your glutes.","Pause at the top.","Lower with control and repeat."],"img":"opengym/6025.webp","gif":null,"ext":1},{"id":"6026","n":"side plank pull","bp":"waist","eq":"body weight","tg":"obliques","mg":"abdominals","sm":["abdominals","shoulders","glutes"],"st":["Get into a side plank on your forearm with your body in a straight line.","Reach your top arm overhead.","Pull your elbow down toward your ribs.","Keep your hips lifted.","Finish your reps, then switch sides."],"img":"opengym/6026.webp","gif":null,"ext":1},{"id":"6027","n":"punch step forward","bp":"full body","eq":"body weight","tg":"cardiovascular system","mg":"shoulders","sm":["shoulders","triceps","quadriceps","core"],"st":["Stand in a boxing stance with fists up.","Step forward with your lead foot.","Throw a punch as you step.","Return to your stance.","Alternate sides and keep a steady rhythm."],"img":"opengym/6027.webp","gif":null,"ext":1},{"id":"6032","n":"cable low seated row with v bar","bp":"back","eq":"cable","tg":"upper back","mg":"lats","sm":["lats","rhomboids","biceps","lower back"],"st":["Sit at the low pulley, feet on the platform, knees slightly bent, and hold the V bar.","Sit tall with your chest up and arms straight.","Pull the handle to your lower ribs, squeezing your shoulder blades together.","Pause briefly, keeping your torso still.","Extend your arms slowly until you feel a stretch in your back."],"img":"opengym/6032.webp","gif":null,"ext":1},{"id":"6033","n":"ab tuck","bp":"waist","eq":"body weight","tg":"abs","mg":"lower abs","sm":["lower abs","hip flexors"],"st":["Sit on the floor and lean back slightly.","Extend your legs in front of you.","Pull your knees to your chest as you bring your torso forward.","Extend again under control.","Keep your core braced."],"img":"opengym/6033.webp","gif":null,"ext":1},{"id":"6034","n":"barbell deadlift from blocks","bp":"upper legs","eq":"barbell","tg":"glutes","mg":"hamstrings","sm":["hamstrings","lower back","quadriceps","grip muscles"],"st":["Set the bar on blocks or a raised platform.","Stand with the bar over your mid-foot.","Hinge and grip the bar just outside your knees.","Brace your core and keep your back flat.","Drive through your feet to stand tall.","Lower the bar back to the blocks with control."],"img":"opengym/6034.webp","gif":null,"ext":1},{"id":"6035","n":"cable rear delt row (parallel bar)","bp":"shoulders","eq":"cable","tg":"delts","mg":"rhomboids","sm":["rhomboids","upper back","biceps"],"st":["Sit facing a low cable with a parallel bar attachment.","Hold the handles with your elbows flared.","Lean back slightly with a straight spine.","Pull the handles toward your chest.","Squeeze your shoulder blades.","Return slowly."],"img":"opengym/6035.webp","gif":null,"ext":1},{"id":"6036","n":"cable straight arm pulldown v. 2","bp":"back","eq":"cable","tg":"lats","mg":"triceps","sm":["triceps","core"],"st":["Stand facing a high cable and grab the bar with straight arms.","Hinge slightly at the hips.","Pull the bar down in an arc to your thighs.","Squeeze your lats.","Return slowly to the start."],"img":"opengym/6036.webp","gif":null,"ext":1},{"id":"6038","n":"smith donkey kick","bp":"upper legs","eq":"smith machine","tg":"glutes","mg":"hamstrings","sm":["hamstrings","core"],"st":["Set the bar of the Smith machine at a low height.","Get on all fours with one foot under the bar.","Press the bar up by extending your hip.","Squeeze your glute at the top.","Lower slowly and repeat before switching legs."],"img":"opengym/6038.webp","gif":null,"ext":1},{"id":"6041","n":"bottle weighted romanian deadlift","bp":"upper legs","eq":"weighted","tg":"hamstrings","mg":"glutes","sm":["glutes","lower back","grip muscles"],"st":["Stand with feet hip-width apart, holding a bottle in each hand in front of your thighs.","Soften your knees and push your hips back.","Lower the bottles along your legs with a flat back until you feel your hamstrings stretch.","Drive your hips forward to stand tall.","Keep your shoulders back and your core braced."],"img":"opengym/6041.webp","gif":null,"ext":1},{"id":"6042","n":"bottle weighted single leg romanian deadlift","bp":"upper legs","eq":"weighted","tg":"hamstrings","mg":"glutes","sm":["glutes","lower back","core","ankles"],"st":["Stand on one leg holding a bottle in each hand, with a slight bend in the knee.","Hinge at the hips and extend the free leg straight behind you.","Lower the bottles toward the floor with a flat back.","Squeeze your glute to return to standing.","Finish your reps, then switch legs."],"img":"opengym/6042.webp","gif":null,"ext":1},{"id":"6043","n":"bottle weighted swing","bp":"upper legs","eq":"weighted","tg":"glutes","mg":"hamstrings","sm":["hamstrings","lower back","shoulders","core"],"st":["Stand with feet wider than your hips, holding a bottle with both hands.","Hinge back and let the bottle swing between your legs.","Snap your hips forward and let the bottle swing to chest height.","Keep your arms relaxed, the hips do the work.","Let it fall back and hinge into the next rep."],"img":"opengym/6043.webp","gif":null,"ext":1},{"id":"6044","n":"bottle weighted front squat","bp":"upper legs","eq":"weighted","tg":"quads","mg":"glutes","sm":["glutes","core","hamstrings","upper back"],"st":["Hold a bottle in each hand at your shoulders, elbows pointing forward.","Stand with feet shoulder-width apart.","Sit your hips down and back until your thighs are about parallel.","Keep your chest up and knees tracking over your toes.","Press through your heels to stand."],"img":"opengym/6044.webp","gif":null,"ext":1},{"id":"6045","n":"bottle weighted sumo squat","bp":"upper legs","eq":"weighted","tg":"glutes","mg":"adductors","sm":["adductors","quadriceps","hamstrings","inner thighs"],"st":["Stand with feet wide and toes turned out, holding a bottle with both hands in front of you.","Bend your knees and lower your hips straight down.","Keep your knees pushing out over your toes.","Stop when your thighs are about parallel.","Drive up through your heels and squeeze your glutes."],"img":"opengym/6045.webp","gif":null,"ext":1},{"id":"6046","n":"bottle weighted split squat","bp":"upper legs","eq":"weighted","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","adductors","core"],"st":["Hold a bottle in each hand and step into a long split stance.","Keep your torso upright.","Lower your back knee toward the floor.","Press through the front heel to rise.","Complete your reps, then switch legs."],"img":"opengym/6046.webp","gif":null,"ext":1},{"id":"6047","n":"bottle weighted forward lunge","bp":"upper legs","eq":"weighted","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","calves","core"],"st":["Stand tall holding a bottle in each hand at your sides.","Step forward with one leg.","Lower until both knees are bent about 90 degrees.","Push off the front foot to return to standing.","Alternate legs each rep."],"img":"opengym/6047.webp","gif":null,"ext":1},{"id":"6048","n":"bottle weighted rear lunge","bp":"upper legs","eq":"weighted","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","core","calves"],"st":["Stand tall holding a bottle in each hand.","Step one leg back and lower your back knee toward the floor.","Keep your front shin vertical and your chest up.","Push through the front heel to come back.","Alternate legs, or finish one side then switch."],"img":"opengym/6048.webp","gif":null,"ext":1},{"id":"6049","n":"bottle weighted straight legs deadlift","bp":"upper legs","eq":"weighted","tg":"hamstrings","mg":"glutes","sm":["glutes","lower back","grip muscles"],"st":["Stand tall holding a bottle in each hand in front of your thighs.","Keep your legs almost straight, with a tiny knee bend.","Hinge forward, sliding the bottles down your legs.","Stop when you feel a firm hamstring stretch.","Squeeze your glutes to stand back up."],"img":"opengym/6049.webp","gif":null,"ext":1},{"id":"6050","n":"bottle weighted glute bridge","bp":"upper legs","eq":"weighted","tg":"glutes","mg":"hamstrings","sm":["hamstrings","core","lower back"],"st":["Lie on your back with knees bent and feet flat.","Hold a bottle across your hips with both hands.","Push through your heels and lift your hips.","Squeeze your glutes at the top, forming a straight line from shoulders to knees.","Lower slowly and repeat."],"img":"opengym/6050.webp","gif":null,"ext":1},{"id":"6051","n":"bottle weighted kneeling squat","bp":"upper legs","eq":"weighted","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","core","lower back"],"st":["Kneel on a mat with hips over knees, holding a bottle at your chest.","Sit your hips back toward your heels.","Pause lightly, keeping your back straight.","Drive your hips forward to return to upright.","Squeeze your glutes at the top."],"img":"opengym/6051.webp","gif":null,"ext":1},{"id":"6052","n":"bottle weighted overhead crunch","bp":"waist","eq":"weighted","tg":"abs","mg":"obliques","sm":["obliques","hip flexors","shoulders"],"st":["Lie on your back, knees bent, holding a bottle with both hands above your chest.","Extend your arms overhead or keep them over your face.","Curl your ribs toward your hips and lift your shoulders off the floor.","Pause at the top.","Lower slowly without dropping your head."],"img":"opengym/6052.webp","gif":null,"ext":1},{"id":"6053","n":"bottle weighted frog crunch","bp":"waist","eq":"weighted","tg":"abs","mg":"lower abs","sm":["lower abs","hip flexors","obliques"],"st":["Lie on your back with soles together, knees open, holding a bottle on your chest.","Curl your upper body up as you pull your knees in.","Bring your chest toward your knees.","Hold for a moment.","Lower with control and repeat."],"img":"opengym/6053.webp","gif":null,"ext":1},{"id":"6054","n":"bottle weighted side bend","bp":"waist","eq":"weighted","tg":"obliques","mg":"abdominals","sm":["abdominals","lower back","grip muscles"],"st":["Stand with feet hip-width apart, a bottle in one hand at your side.","Place the other hand lightly behind your head.","Bend sideways toward the bottle without leaning forward.","Return to upright by squeezing your side.","Finish your reps, then switch sides."],"img":"opengym/6054.webp","gif":null,"ext":1},{"id":"6055","n":"bottle weighted russian twist","bp":"waist","eq":"weighted","tg":"obliques","mg":"abdominals","sm":["abdominals","hip flexors","lower back"],"st":["Sit on the floor, knees bent, and lean back a little with a straight spine.","Hold a bottle with both hands in front of your chest.","Rotate your torso to one side and tap the bottle near the floor.","Rotate to the other side.","Keep your feet down or lifted for more challenge."],"img":"opengym/6055.webp","gif":null,"ext":1},{"id":"6056","n":"bottle weighted squatting alternate waves","bp":"full body","eq":"weighted","tg":"quads","mg":"glutes","sm":["glutes","shoulders","core","hamstrings"],"st":["Stand with feet shoulder-width apart, a bottle in each hand.","Squat down with your hips back.","As you stand, raise one arm up and the other down in a wave motion.","Switch arms on the next squat.","Move at a steady, controlled pace."],"img":"opengym/6056.webp","gif":null,"ext":1},{"id":"6057","n":"bottle weighted lying chest press","bp":"chest","eq":"weighted","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders","upper chest"],"st":["Lie on your back, knees bent, holding a bottle in each hand at chest level.","Press the bottles straight up until your arms are extended.","Keep your wrists straight.","Lower slowly until your elbows touch the floor or reach chest level.","Repeat for your reps."],"img":"opengym/6057.webp","gif":null,"ext":1},{"id":"6058","n":"bottle weighted svend press","bp":"chest","eq":"weighted","tg":"pectorals","mg":"upper chest","sm":["upper chest","triceps","shoulders"],"st":["Stand tall and press your palms together around a bottle at your chest.","Squeeze inward the whole time.","Push the bottle straight out in front of you.","Pause with your arms extended.","Bring it back to your chest slowly."],"img":"opengym/6058.webp","gif":null,"ext":1},{"id":"6059","n":"bottle weighted bent over row","bp":"back","eq":"weighted","tg":"upper back","mg":"lats","sm":["lats","rhomboids","biceps","lower back"],"st":["Hold a bottle in each hand and hinge forward with a flat back.","Let your arms hang below your shoulders.","Pull the bottles toward your hips, elbows close to your body.","Squeeze your shoulder blades together.","Lower slowly."],"img":"opengym/6059.webp","gif":null,"ext":1},{"id":"6060","n":"bottle weighted pullover","bp":"back","eq":"weighted","tg":"lats","mg":"chest","sm":["chest","triceps","core"],"st":["Lie on your back, knees bent, holding a bottle with both hands over your chest.","Keep your arms nearly straight.","Lower the bottle in an arc behind your head.","Stop when you feel a stretch in your sides.","Pull it back over your chest."],"img":"opengym/6060.webp","gif":null,"ext":1},{"id":"6061","n":"bottle weighted bent over reverse fly","bp":"shoulders","eq":"weighted","tg":"delts","mg":"rear deltoids","sm":["rear deltoids","upper back","rhomboids","trapezius"],"st":["Hinge forward with a flat back, a bottle in each hand hanging below you.","Keep a slight bend in your elbows.","Raise your arms out to the sides to shoulder height.","Squeeze your shoulder blades.","Lower slowly."],"img":"opengym/6061.webp","gif":null,"ext":1},{"id":"6063","n":"bottle weighted concentration curl","bp":"upper arms","eq":"weighted","tg":"biceps","mg":"brachialis","sm":["brachialis","forearms","grip muscles"],"st":["Sit with feet wide, a bottle in one hand, and rest your elbow on your inner thigh.","Let your arm hang fully.","Curl the bottle toward your shoulder.","Squeeze your biceps at the top.","Lower slowly, then switch arms."],"img":"opengym/6063.webp","gif":null,"ext":1},{"id":"6064","n":"bottle weighted reverse grip concentration curl","bp":"lower arms","eq":"weighted","tg":"forearms","mg":"biceps","sm":["biceps","brachialis","wrist extensors","grip muscles"],"st":["Sit with feet wide, holding a bottle with an overhand grip, elbow resting on your inner thigh.","Let your arm hang straight.","Curl the bottle up without bending your wrist.","Pause at the top.","Lower slowly, then switch arms."],"img":"opengym/6064.webp","gif":null,"ext":1},{"id":"6065","n":"bottle weighted kickback","bp":"upper arms","eq":"weighted","tg":"triceps","mg":"shoulders","sm":["shoulders","rear deltoids","core"],"st":["Hinge forward with a flat back, upper arm parallel to the floor, bottle in hand.","Keep your elbow tight at your side.","Straighten your arm behind you.","Squeeze your triceps.","Bend slowly, then switch arms."],"img":"opengym/6065.webp","gif":null,"ext":1},{"id":"6066","n":"bottle weighted two arms kickback","bp":"upper arms","eq":"weighted","tg":"triceps","mg":"shoulders","sm":["shoulders","rear deltoids","core"],"st":["Hinge forward with a flat back, a bottle in each hand, upper arms parallel to the floor.","Keep your elbows tucked.","Extend both arms straight behind you.","Squeeze at the top.","Return slowly."],"img":"opengym/6066.webp","gif":null,"ext":1},{"id":"6067","n":"bottle weighted overhead triceps extension","bp":"upper arms","eq":"weighted","tg":"triceps","mg":"shoulders","sm":["shoulders","core","forearms"],"st":["Stand or sit tall holding a bottle overhead with both hands.","Keep your elbows pointing forward.","Bend your elbows and lower the bottle behind your head.","Extend your arms to lift it back up.","Keep your upper arms still."],"img":"opengym/6067.webp","gif":null,"ext":1},{"id":"6068","n":"bottle weighted alternate biceps curl","bp":"upper arms","eq":"weighted","tg":"biceps","mg":"brachialis","sm":["brachialis","forearms","grip muscles"],"st":["Stand tall with a bottle in each hand, palms forward.","Curl one bottle toward your shoulder.","Lower it slowly as you curl the other.","Keep your elbows by your sides.","Avoid swinging your torso."],"img":"opengym/6068.webp","gif":null,"ext":1},{"id":"6069","n":"bottle weighted alternate hammer curl","bp":"upper arms","eq":"weighted","tg":"biceps","mg":"brachialis","sm":["brachialis","forearms","grip muscles"],"st":["Stand tall with a bottle in each hand, palms facing your body.","Curl one bottle up without rotating your wrist.","Lower it slowly.","Curl the other arm.","Keep your elbows pinned."],"img":"opengym/6069.webp","gif":null,"ext":1},{"id":"6070","n":"bottle weighted reverse curl","bp":"lower arms","eq":"weighted","tg":"forearms","mg":"brachialis","sm":["brachialis","biceps","wrist extensors","grip muscles"],"st":["Stand tall holding a bottle in each hand with palms facing down.","Keep your elbows at your sides.","Curl the bottles up with straight wrists.","Pause at the top.","Lower slowly."],"img":"opengym/6070.webp","gif":null,"ext":1},{"id":"6071","n":"bottle weighted upright row","bp":"shoulders","eq":"weighted","tg":"delts","mg":"trapezius","sm":["trapezius","biceps","upper back","forearms"],"st":["Stand tall holding bottles in front of your thighs, palms facing you.","Pull them up along your body, elbows leading.","Stop at about chest height.","Lower slowly.","Keep the bottles close to your torso."],"img":"opengym/6071.webp","gif":null,"ext":1},{"id":"6072","n":"bottle weighted armpit row","bp":"shoulders","eq":"weighted","tg":"delts","mg":"rear deltoids","sm":["rear deltoids","trapezius","upper back","biceps"],"st":["Hold a bottle in each hand and hinge slightly forward.","Pull your elbows out and up, bottles moving toward your armpits.","Squeeze your shoulder blades.","Lower slowly.","Keep your neck relaxed."],"img":"opengym/6072.webp","gif":null,"ext":1},{"id":"6073","n":"bottle weighted front raise","bp":"shoulders","eq":"weighted","tg":"delts","mg":"upper chest","sm":["upper chest","core","trapezius"],"st":["Stand tall with a bottle in each hand in front of your thighs.","Raise both arms straight in front to shoulder height.","Keep a slight bend in your elbows.","Pause.","Lower slowly without swinging."],"img":"opengym/6073.webp","gif":null,"ext":1},{"id":"6074","n":"bottle weighted lateral raise","bp":"shoulders","eq":"weighted","tg":"delts","mg":"trapezius","sm":["trapezius","rotator cuff","upper back"],"st":["Stand tall with a bottle in each hand at your sides.","Raise your arms out to the sides up to shoulder height.","Lead with your elbows.","Pause briefly.","Lower slowly."],"img":"opengym/6074.webp","gif":null,"ext":1},{"id":"6075","n":"bottle weighted alternate front raise","bp":"shoulders","eq":"weighted","tg":"delts","mg":"upper chest","sm":["upper chest","core"],"st":["Stand tall with a bottle in each hand.","Raise one arm forward to shoulder height.","Lower it slowly as you raise the other.","Keep your torso still.","Breathe steadily."],"img":"opengym/6075.webp","gif":null,"ext":1},{"id":"6076","n":"bottle weighted shoulder press","bp":"shoulders","eq":"weighted","tg":"delts","mg":"triceps","sm":["triceps","upper chest","trapezius","core"],"st":["Hold a bottle in each hand at shoulder height.","Brace your core and stand tall.","Press both bottles overhead until your arms are straight.","Lower back to shoulder height.","Do not arch your lower back."],"img":"opengym/6076.webp","gif":null,"ext":1},{"id":"6077","n":"bottle weighted halo","bp":"shoulders","eq":"weighted","tg":"delts","mg":"rotator cuff","sm":["rotator cuff","trapezius","core","triceps"],"st":["Stand tall holding a bottle at chest height with both hands.","Circle it around your head, staying close.","Keep your core braced and ribs down.","Complete the circle back to the front.","Reverse direction on the next set."],"img":"opengym/6077.webp","gif":null,"ext":1},{"id":"6092","n":"spider plank","bp":"waist","eq":"body weight","tg":"abs","mg":"obliques","sm":["obliques","hip flexors","shoulders","triceps"],"st":["Start in a high or forearm plank.","Keep your body in a straight line.","Bring one knee toward the same elbow.","Return to plank.","Alternate sides without letting your hips sag."],"img":"opengym/6092.webp","gif":null,"ext":1},{"id":"6094","n":"front leg lift under knee tap","bp":"waist","eq":"body weight","tg":"abs","mg":"hip flexors","sm":["hip flexors","quadriceps","core"],"st":["Stand tall with your feet hip-width apart and your hands out in front.","Lift one knee up and forward to hip height.","Reach both hands under that thigh and tap beneath the knee.","Lower the foot with control and switch legs.","Keep your chest up and stay light on your feet.","Alternate sides at a steady, bouncy pace."],"img":"opengym/6094.webp","gif":null,"ext":1},{"id":"6097","n":"back kick overhead press","bp":"full body","eq":"body weight","tg":"delts","mg":"triceps","sm":["triceps","glutes","hamstrings","core"],"st":["Stand with your feet hip-width apart and your hands at shoulder height.","Press both hands straight overhead as you kick one leg back.","Squeeze the glute at the top without arching your lower back.","Bring the hands and foot back to the start.","Switch legs and repeat at a lively pace.","Keep your core tight throughout."],"img":"opengym/6097.webp","gif":null,"ext":1},{"id":"6098","n":"swim leg circle","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"hip flexors","sm":["hip flexors","core","hamstrings"],"st":["Lie face down with your arms extended in front of you.","Lift one leg slightly off the floor.","Draw small, controlled circles with that leg.","Reverse the direction after several circles.","Lower the leg and repeat on the other side.","Keep your hips pressed down and your core braced."],"img":"opengym/6098.webp","gif":null,"ext":1},{"id":"6100","n":"bodyweight skipping","bp":"full body","eq":"body weight","tg":"cardiovascular system","mg":"calves","sm":["calves","quadriceps","hip flexors"],"st":["Stand tall with your feet together.","Step and hop on one foot while driving the opposite knee up.","Swing the opposite arm forward as you hop.","Switch sides in a rhythmic skip.","Land softly on the balls of your feet.","Keep going for 30-60 seconds."],"img":"opengym/6100.webp","gif":null,"ext":1},{"id":"6103","n":"jackknife","bp":"waist","eq":"body weight","tg":"abs","mg":"hip flexors","sm":["hip flexors","lower abs","core"],"st":["Lie on your back with your legs extended and your arms by your sides.","Lift both legs up toward the ceiling.","Press your arms into the floor and lift your hips slightly.","Raise your trunk and reach toward your toes.","Roll back down slowly with control.","Keep your movement smooth, without swinging."],"img":"opengym/6103.webp","gif":null,"ext":1},{"id":"6108","n":"bodyweight lying legs curl","bp":"upper legs","eq":"body weight","tg":"hamstrings","mg":"glutes","sm":["glutes","calves"],"st":["Lie on your front with your legs straight.","Rest your forehead on your hands.","Bend your knees and bring your heels toward your glutes.","Squeeze the hamstrings at the top.","Lower your feet slowly back to the floor.","Keep your hips pressed down throughout."],"img":"opengym/6108.webp","gif":null,"ext":1},{"id":"6120","n":"pavanamuktasana yoga pose","bp":"waist","eq":"body weight","tg":"glutes","mg":"lower back","sm":["lower back","hip flexors","core"],"st":["Lie on your back with your legs straight.","Bend your knees and draw them into your chest.","Wrap your arms around your shins and hug them in.","Keep your head and shoulders relaxed on the floor.","Breathe slowly and hold for 20-30 seconds.","Release and extend your legs."],"img":"opengym/6120.webp","gif":null,"ext":1},{"id":"6121","n":"ardha matsyendrasana yoga pose","bp":"waist","eq":"body weight","tg":"spine","mg":"obliques","sm":["obliques","glutes","hip flexors"],"st":["Sit tall with your legs extended.","Bend one knee and place that foot outside the opposite thigh.","Hug the bent knee with the opposite arm.","Place your other hand behind you and twist toward it.","Lengthen the spine and hold for 20-30 seconds.","Release and repeat on the other side."],"img":"opengym/6121.webp","gif":null,"ext":1},{"id":"6123","n":"dumbbell unilateral scapula raise","bp":"back","eq":"dumbbell","tg":"upper back","mg":"traps","sm":["traps","rhomboids","shoulders"],"st":["Stand holding a dumbbell in one hand at your side.","Keep your arm straight and your chest up.","Lift your shoulder blade straight up toward your ear.","Pause briefly at the top.","Lower with control.","Finish your reps, then switch arms."],"img":"opengym/6123.webp","gif":null,"ext":1},{"id":"6136","n":"dumbbell bent over scapula row","bp":"back","eq":"dumbbell","tg":"upper back","mg":"rhomboids","sm":["rhomboids","trapezius","rear deltoids"],"st":["Hold dumbbells and hinge forward with a flat back.","Let your arms hang straight down.","Squeeze your shoulder blades together without bending the elbows.","Hold for a moment.","Release the blades and let the weights drop slightly.","Keep your neck neutral throughout."],"img":"opengym/6136.webp","gif":null,"ext":1},{"id":"6137","n":"bodyweight standing scapula row","bp":"back","eq":"body weight","tg":"upper back","mg":"rhomboids","sm":["rhomboids","trapezius","rear deltoids"],"st":["Stand tall with your arms out in front or at your sides.","Keep your arms mostly straight.","Pull your shoulder blades back and together.","Hold the squeeze for a second.","Release slowly.","Avoid shrugging your shoulders to your ears."],"img":"opengym/6137.webp","gif":null,"ext":1},{"id":"6138","n":"namaskarasana yoga pose","bp":"upper legs","eq":"body weight","tg":"adductors","mg":"glutes","sm":["glutes","hip flexors","inner thighs"],"st":["Stand with your feet wider than your hips and toes turned out.","Lower into a deep squat.","Press your palms together at the chest.","Use your elbows to gently press your knees outward.","Keep your chest lifted and hold for 20-30 seconds.","Stand up slowly."],"img":"opengym/6138.webp","gif":null,"ext":1},{"id":"6139","n":"squat mobility twist","bp":"waist","eq":"body weight","tg":"quads","mg":"lower back","sm":["lower back","obliques","glutes","hip flexors"],"st":["Lower into a deep squat with your feet shoulder-width apart.","Place one hand on the floor or inside your knee.","Rotate your chest and reach the other arm up toward the ceiling.","Follow your hand with your eyes.","Return to the center and switch sides.","Keep your heels on the floor."],"img":"opengym/6139.webp","gif":null,"ext":1},{"id":"6140","n":"dumbbell seated external rotation","bp":"shoulders","eq":"dumbbell","tg":"delts","mg":"rotator cuff","sm":["rotator cuff","rear deltoids"],"st":["Sit on a bench holding a light dumbbell.","Rest your elbow on your thigh or bent at your side at 90 degrees.","Rotate your forearm upward and outward.","Pause at the top.","Lower slowly back to the start.","Finish your reps, then switch arms."],"img":"opengym/6140.webp","gif":null,"ext":1},{"id":"6141","n":"dumbbell standing driver","bp":"shoulders","eq":"dumbbell","tg":"delts","mg":"triceps","sm":["triceps","core","upper chest"],"st":["Stand holding a dumbbell at your shoulder.","Bend your knees slightly.","Drive up through your legs and press the dumbbell overhead.","Lock out without leaning back.","Lower the weight to your shoulder.","Switch arms after your set."],"img":"opengym/6141.webp","gif":null,"ext":1},{"id":"6142","n":"dumbbell seated reverse arnold press","bp":"shoulders","eq":"dumbbell","tg":"delts","mg":"triceps","sm":["triceps","upper chest","rotator cuff"],"st":["Sit upright holding dumbbells overhead with your palms forward.","Lower the weights while rotating your palms toward you.","Stop with the dumbbells in front of your chest.","Rotate your palms back outward as you press up.","Lock out the arms overhead.","Keep your back against the pad."],"img":"opengym/6142.webp","gif":null,"ext":1},{"id":"6143","n":"dumbbell seated single arm front raise","bp":"shoulders","eq":"dumbbell","tg":"delts","mg":"upper chest","sm":["upper chest","biceps","core"],"st":["Sit tall holding a dumbbell at your side.","Raise the dumbbell forward to shoulder height with a soft elbow.","Pause at the top.","Lower with control.","Avoid leaning back.","Finish your reps, then switch arms."],"img":"opengym/6143.webp","gif":null,"ext":1},{"id":"6144","n":"dumbbell straight arm crunch v. 2","bp":"waist","eq":"dumbbell","tg":"abs","mg":"obliques","sm":["obliques","core","shoulders"],"st":["Lie on your back with your knees bent.","Hold a dumbbell with straight arms over your chest.","Curl your upper back off the floor, reaching up.","Pause at the top.","Lower slowly.","Keep your lower back on the floor."],"img":"opengym/6144.webp","gif":null,"ext":1},{"id":"6145","n":"dumbbell reverse hyperextension on bench","bp":"upper legs","eq":"dumbbell","tg":"glutes","mg":"hamstrings","sm":["hamstrings","lower back"],"st":["Lie face down on a bench with your hips at the edge.","Hold a dumbbell between your feet.","Hold the bench for support.","Raise your legs until they align with your body.","Squeeze your glutes at the top.","Lower slowly."],"img":"opengym/6145.webp","gif":null,"ext":1},{"id":"6146","n":"dumbbell bent over row against wall","bp":"back","eq":"dumbbell","tg":"upper back","mg":"lats","sm":["lats","biceps","rhomboids"],"st":["Stand a step from a wall and hinge forward.","Support your forehead or free hand on the wall.","Hold a dumbbell in each hand with your arms hanging.","Row the weights toward your hips.","Squeeze your shoulder blades together.","Lower with control."],"img":"opengym/6146.webp","gif":null,"ext":1},{"id":"6147","n":"dumbbell alternate hammer strict curl","bp":"upper arms","eq":"dumbbell","tg":"biceps","mg":"brachialis","sm":["brachialis","forearms"],"st":["Stand holding dumbbells with your palms facing in.","Keep your elbows at your sides.","Curl one dumbbell up without swinging.","Lower it slowly.","Repeat with the other arm.","Keep your torso still."],"img":"opengym/6147.webp","gif":null,"ext":1},{"id":"6148","n":"dumbbell seated alternate overhead triceps extension","bp":"upper arms","eq":"dumbbell","tg":"triceps","mg":"shoulders","sm":["shoulders","core"],"st":["Sit upright holding a dumbbell in each hand overhead.","Lower one dumbbell behind your head by bending the elbow.","Keep your upper arm close to your head.","Extend the arm back up.","Repeat with the other arm.","Keep your core braced."],"img":"opengym/6148.webp","gif":null,"ext":1},{"id":"6149","n":"dumbbell seated drag curl","bp":"upper arms","eq":"dumbbell","tg":"biceps","mg":"brachialis","sm":["brachialis","forearms","rear deltoids"],"st":["Sit holding dumbbells with your palms forward.","Keep the weights close to your body.","Pull your elbows back as you curl.","Drag the dumbbells up along your torso.","Squeeze at the top.","Lower with control."],"img":"opengym/6149.webp","gif":null,"ext":1},{"id":"6150","n":"dumbbell seated double concentration curl","bp":"upper arms","eq":"dumbbell","tg":"biceps","mg":"brachialis","sm":["brachialis","forearms"],"st":["Sit on a bench with your feet wide.","Hold a dumbbell in each hand and lean forward.","Rest the backs of your upper arms on your inner thighs.","Curl both dumbbells up toward your shoulders.","Squeeze at the top.","Lower slowly to a full stretch."],"img":"opengym/6150.webp","gif":null,"ext":1},{"id":"6151","n":"dumbbell reverse push up","bp":"upper arms","eq":"dumbbell","tg":"triceps","mg":"shoulders","sm":["shoulders","chest","core"],"st":["Place two dumbbells on the floor and grip them.","Set up in a plank position.","Lower your chest with your elbows close to your body.","Stop just above the floor.","Press back up to the start.","Keep your body in a straight line."],"img":"opengym/6151.webp","gif":null,"ext":1},{"id":"6152","n":"dumbbell one arm snatch (left)","bp":"full body","eq":"dumbbell","tg":"glutes","mg":"hamstrings","sm":["hamstrings","shoulders","core","quadriceps"],"st":["Stand over a dumbbell with your feet shoulder-width apart.","Grip it with your left hand and hinge at the hips.","Drive up with your legs and hips.","Pull the dumbbell up close to your body and punch it overhead.","Lock out the arm.","Lower the weight back to the floor with control."],"img":"opengym/6152.webp","gif":null,"ext":1},{"id":"6156","n":"kettlebell bent over row","bp":"back","eq":"kettlebell","tg":"upper back","mg":"lats","sm":["lats","biceps","rhomboids"],"st":["Hold a kettlebell and hinge forward with a flat back.","Let your arm hang straight down.","Row the kettlebell toward your hip.","Squeeze your shoulder blade back.","Lower slowly.","Finish your reps, then switch arms."],"img":"opengym/6156.webp","gif":null,"ext":1},{"id":"6158","n":"dumbbell seated single arm overhead triceps extension","bp":"upper arms","eq":"dumbbell","tg":"triceps","mg":"shoulders","sm":["shoulders","core"],"st":["Sit upright holding a dumbbell in one hand overhead.","Keep the upper arm close to your head.","Lower the dumbbell behind your head by bending the elbow.","Extend the arm back to full lockout.","Keep your core braced.","Finish your reps, then switch arms."],"img":"opengym/6158.webp","gif":null,"ext":1},{"id":"6159","n":"dumbbell seated single arm overhead triceps extension (left)","bp":"upper arms","eq":"dumbbell","tg":"triceps","mg":"shoulders","sm":["shoulders","core"],"st":["Sit upright holding a dumbbell in your left hand overhead.","Keep the upper arm close to your head.","Lower the dumbbell behind your head by bending the elbow.","Extend the arm back to full lockout.","Keep your core braced.","Finish your reps, then switch to the right arm."],"img":"opengym/6159.webp","gif":null,"ext":1},{"id":"6160","n":"dumbbell frog hip thrust","bp":"upper legs","eq":"dumbbell","tg":"glutes","mg":"hamstrings","sm":["hamstrings","adductors","core"],"st":["Lie on your back with the soles of your feet together and knees out.","Rest a dumbbell on your hips.","Drive your hips up by pressing through your feet.","Squeeze your glutes at the top.","Lower slowly.","Keep your ribs down."],"img":"opengym/6160.webp","gif":null,"ext":1},{"id":"6161","n":"dumbbell lying leg curl","bp":"upper legs","eq":"dumbbell","tg":"hamstrings","mg":"calves","sm":["calves","glutes"],"st":["Lie face down on a bench.","Grip a dumbbell between your feet.","Curl your heels toward your glutes.","Squeeze the hamstrings at the top.","Lower with control.","Keep your hips on the bench."],"img":"opengym/6161.webp","gif":null,"ext":1},{"id":"6162","n":"dumbbell incline low fly","bp":"chest","eq":"dumbbell","tg":"pectorals","mg":"upper chest","sm":["upper chest","shoulders","biceps"],"st":["Set a bench to a low incline and lie back.","Hold dumbbells above your chest with a soft elbow bend.","Open your arms out and down in an arc.","Stop at a comfortable chest stretch.","Bring the dumbbells back together.","Keep the elbow bend constant."],"img":"opengym/6162.webp","gif":null,"ext":1},{"id":"6193","n":"kettlebell cossack squat","bp":"upper legs","eq":"kettlebell","tg":"adductors","mg":"glutes","sm":["glutes","quadriceps","hamstrings"],"st":["Hold a kettlebell at your chest and stand wide.","Shift your weight to one side.","Squat down with the other leg straight.","Keep the bent knee over your toes.","Push back to the center.","Alternate sides."],"img":"opengym/6193.webp","gif":null,"ext":1},{"id":"6194","n":"kettlebell shrug","bp":"back","eq":"kettlebell","tg":"traps","mg":"upper back","sm":["upper back","forearms","grip muscles"],"st":["Stand holding kettlebells at your sides.","Keep your arms straight.","Lift your shoulders straight up toward your ears.","Pause for a second at the top.","Lower slowly.","Keep your chest tall and neck relaxed."],"img":"opengym/6194.webp","gif":null,"ext":1},{"id":"6195","n":"band standing reverse curl","bp":"lower arms","eq":"band","tg":"forearms","mg":"brachialis","sm":["brachialis","biceps","wrist extensors"],"st":["Stand on a band holding the ends with an overhand grip.","Keep your elbows at your sides.","Curl your hands up toward your shoulders.","Pause at the top.","Lower slowly.","Keep your wrists straight."],"img":"opengym/6195.webp","gif":null,"ext":1},{"id":"6207","n":"side plank leg lift (left)","bp":"waist","eq":"body weight","tg":"obliques","mg":"glutes","sm":["glutes","core"],"st":["Lie on your left side and prop up on your forearm.","Lift your hips into a side plank.","Raise your top leg slowly.","Lower the leg without dropping your hips.","Repeat for your set.","Switch sides for the right-side version."],"img":"opengym/6207.webp","gif":null,"ext":1},{"id":"6208","n":"side plank with raised leg v. 2 (left)","bp":"waist","eq":"body weight","tg":"obliques","mg":"abdominals","sm":["abdominals","glutes","shoulders"],"st":["Lie on your left side and prop up on your left forearm, elbow under your shoulder.","Stack your feet and lift your hips into a straight line.","Raise your top leg to hip height.","Hold for 20-30 seconds.","Lower and repeat, then switch sides if you like."],"img":"opengym/6208.webp","gif":null,"ext":1},{"id":"6209","n":"kneeling straight leg kickback v. 2 (left)","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"hamstrings","sm":["hamstrings","core"],"st":["Start on all fours.","Extend your left leg straight behind you.","Lift it to hip height.","Squeeze the glute at the top.","Lower with control.","Keep your hips level."],"img":"opengym/6209.webp","gif":null,"ext":1},{"id":"6210","n":"elbow to knee side plank crunch (left)","bp":"waist","eq":"body weight","tg":"obliques","mg":"abdominals","sm":["abdominals","hip flexors","glutes","shoulders"],"st":["Set up in a left side plank on your forearm, top hand behind your head.","Lift your top leg slightly.","Bring your top elbow and knee together in front of you.","Extend back out to the straight position.","Repeat for reps, then do the other side."],"img":"opengym/6210.webp","gif":null,"ext":1},{"id":"6211","n":"bicycle crunch","bp":"waist","eq":"body weight","tg":"abs","mg":"obliques","sm":["obliques","hip flexors","core"],"st":["Lie on your back with your hands by your head.","Lift your shoulders and bring your knees up.","Twist to bring one elbow to the opposite knee.","Extend the other leg.","Switch sides in a pedalling motion.","Keep your lower back pressed down."],"img":"opengym/6211.webp","gif":null,"ext":1},{"id":"6214","n":"lying scissors cross","bp":"upper legs","eq":"body weight","tg":"adductors","mg":"hip flexors","sm":["hip flexors","lower abs","core"],"st":["Lie on your back with your legs lifted.","Press your lower back into the floor.","Open your legs wide.","Cross one leg over the other.","Open and cross the other leg on top.","Keep a steady rhythm."],"img":"opengym/6214.webp","gif":null,"ext":1},{"id":"6215","n":"dumbbell rollout","bp":"waist","eq":"dumbbell","tg":"abs","mg":"shoulders","sm":["shoulders","lats","core"],"st":["Kneel holding a dumbbell in each hand on the floor.","Brace your core.","Roll the dumbbells forward.","Go as far as you can keep your back flat.","Pull back to the start.","Avoid sagging at the hips."],"img":"opengym/6215.webp","gif":null,"ext":1},{"id":"6218","n":"dumbbell incline twist press","bp":"chest","eq":"dumbbell","tg":"pectorals","mg":"upper chest","sm":["upper chest","triceps","shoulders"],"st":["Lie on an incline bench holding dumbbells at chest level.","Palms face you.","Press up, rotating your palms forward.","Lock out at the top.","Lower, rotating back.","Keep your shoulders down."],"img":"opengym/6218.webp","gif":null,"ext":1},{"id":"6219","n":"cable standing single arm fly","bp":"chest","eq":"cable","tg":"pectorals","mg":"upper chest","sm":["upper chest","shoulders","biceps"],"st":["Stand sideways to a cable with the handle at chest height.","Step forward for balance.","Pull the handle across your body.","Squeeze your chest.","Return slowly.","Finish your reps, then switch arms."],"img":"opengym/6219.webp","gif":null,"ext":1},{"id":"6220","n":"suspender row","bp":"back","eq":"suspension trainer","tg":"upper back","mg":"lats","sm":["lats","biceps","rhomboids"],"st":["Hold the straps and lean back.","Keep your body in a straight line.","Pull your chest toward your hands.","Squeeze your shoulder blades.","Lower slowly.","Keep your core tight."],"img":"opengym/6220.webp","gif":null,"ext":1},{"id":"6221","n":"dumbbell standing french press","bp":"upper arms","eq":"dumbbell","tg":"triceps","mg":"shoulders","sm":["shoulders","core"],"st":["Stand holding one dumbbell overhead with both hands.","Keep your elbows pointing forward.","Lower the dumbbell behind your head.","Extend your arms back up.","Keep your core braced.","Avoid arching your back."],"img":"opengym/6221.webp","gif":null,"ext":1},{"id":"6222","n":"suspender squat jump","bp":"upper legs","eq":"suspension trainer","tg":"quads","mg":"glutes","sm":["glutes","calves","hamstrings"],"st":["Hold the straps with your arms extended.","Lower into a squat.","Jump up explosively.","Land softly.","Go straight into the next squat.","Keep your chest tall."],"img":"opengym/6222.webp","gif":null,"ext":1},{"id":"6231","n":"knee push up chest pullback","bp":"chest","eq":"body weight","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders","core"],"st":["Start in a knee push-up position.","Lower your chest to the floor.","Press back up.","Push your hips back toward your heels.","Return to the start.","Keep your core tight."],"img":"opengym/6231.webp","gif":null,"ext":1},{"id":"6232","n":"suspender biceps curl","bp":"upper arms","eq":"suspension trainer","tg":"biceps","mg":"forearms","sm":["forearms","brachialis","core"],"st":["Hold the straps and lean back.","Extend your arms.","Curl your hands toward your forehead.","Keep your elbows high.","Lower slowly.","Keep your body straight."],"img":"opengym/6232.webp","gif":null,"ext":1},{"id":"6234","n":"ring arm curl","bp":"upper arms","eq":"suspension trainer","tg":"biceps","mg":"forearms","sm":["forearms","brachialis","core"],"st":["Hold the rings and lean back.","Extend your arms.","Curl your hands toward your head.","Keep your elbows up.","Lower slowly.","Keep your body in a straight line."],"img":"opengym/6234.webp","gif":null,"ext":1},{"id":"6237","n":"ring one arm biceps curl","bp":"upper arms","eq":"suspension trainer","tg":"biceps","mg":"forearms","sm":["forearms","brachialis","core"],"st":["Hold one ring and lean back.","Extend your arm.","Curl your hand toward your head.","Keep your elbow up.","Lower slowly.","Finish your reps, then switch arms."],"img":"opengym/6237.webp","gif":null,"ext":1},{"id":"6252","n":"ring face pull","bp":"shoulders","eq":"suspension trainer","tg":"delts","mg":"rear deltoids","sm":["rear deltoids","upper back","rotator cuff"],"st":["Hold the rings and lean back.","Extend your arms.","Pull the rings toward your face.","Flare your elbows out.","Squeeze your shoulder blades.","Lower slowly."],"img":"opengym/6252.webp","gif":null,"ext":1},{"id":"6259","n":"ring single arm rear delt row","bp":"shoulders","eq":"suspension trainer","tg":"delts","mg":"rear deltoids","sm":["rear deltoids","upper back","biceps"],"st":["Hold one ring and lean back.","Extend your arm.","Pull your elbow out and back.","Squeeze the rear delt.","Lower slowly.","Finish your reps, then switch arms."],"img":"opengym/6259.webp","gif":null,"ext":1},{"id":"6262","n":"barbell standing wrist curl","bp":"lower arms","eq":"barbell","tg":"forearms","mg":"wrist flexors","sm":["wrist flexors","grip muscles"],"st":["Stand holding a barbell with an underhand grip.","Let your hands hang.","Curl your wrists up.","Squeeze the forearms.","Lower slowly.","Keep your arms still."],"img":"opengym/6262.webp","gif":null,"ext":1},{"id":"6264","n":"dumbbell prone alternate hammer curl","bp":"lower arms","eq":"dumbbell","tg":"forearms","mg":"brachialis","sm":["brachialis","biceps"],"st":["Lie chest down on an incline bench.","Hold dumbbells with palms facing in.","Curl one dumbbell up.","Lower it slowly.","Alternate arms.","Keep your elbows still."],"img":"opengym/6264.webp","gif":null,"ext":1},{"id":"6265","n":"dumbbell standing alternate reverse curl","bp":"lower arms","eq":"dumbbell","tg":"forearms","mg":"brachialis","sm":["brachialis","biceps","wrist extensors"],"st":["Stand holding dumbbells with an overhand grip.","Keep your elbows at your sides.","Curl one dumbbell up.","Lower slowly.","Alternate arms.","Keep your wrists straight."],"img":"opengym/6265.webp","gif":null,"ext":1},{"id":"6266","n":"cable seated overhead curl (sz bar)","bp":"upper arms","eq":"cable","tg":"biceps","mg":"brachialis","sm":["brachialis","forearms"],"st":["Sit facing the cable machine.","Grip the SZ bar and extend your arms.","Curl the bar toward your head.","Squeeze the biceps.","Lower slowly.","Keep your elbows high."],"img":"opengym/6266.webp","gif":null,"ext":1},{"id":"6267","n":"dumbbell standing arms rotate","bp":"lower arms","eq":"dumbbell","tg":"forearms","mg":"wrist flexors","sm":["wrist flexors","wrist extensors","grip muscles"],"st":["Stand holding light dumbbells at your sides.","Bend your elbows to 90 degrees.","Rotate your palms up.","Rotate your palms down.","Repeat smoothly.","Keep your elbows pinned."],"img":"opengym/6267.webp","gif":null,"ext":1},{"id":"6268","n":"ez barbell standing single arm neutral wrist curl","bp":"lower arms","eq":"ez barbell","tg":"forearms","mg":"wrist flexors","sm":["wrist flexors","grip muscles"],"st":["Stand holding one end of an EZ bar.","Keep your arm at your side.","Curl your wrist up.","Squeeze the forearm.","Lower slowly.","Finish your reps, then switch arms."],"img":"opengym/6268.webp","gif":null,"ext":1},{"id":"6269","n":"cable standing wrist roll","bp":"lower arms","eq":"cable","tg":"forearms","mg":"wrist flexors","sm":["wrist flexors","wrist extensors","grip muscles"],"st":["Stand facing the cable machine.","Hold the handle with straight arms.","Roll your wrists up.","Roll them back down.","Repeat smoothly.","Keep your arms still."],"img":"opengym/6269.webp","gif":null,"ext":1},{"id":"6270","n":"barbell larsen press","bp":"chest","eq":"barbell","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders","upper chest"],"st":["Lie on a bench and grip the bar.","Lift your feet off the floor.","Unrack the bar.","Lower it to your chest.","Press back up.","Keep your back flat."],"img":"opengym/6270.webp","gif":null,"ext":1},{"id":"6271","n":"barbell close grip larsen press","bp":"chest","eq":"barbell","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders"],"st":["Lie on a bench and hold the bar with a close, shoulder-width grip.","Lift your feet off the floor and stretch your legs out in front of you.","Lower the bar to your lower chest under control.","Press the bar back up until your arms are straight.","Keep your back flat on the bench and your core tight throughout."],"img":"opengym/6271.webp","gif":null,"ext":1},{"id":"6272","n":"dumbbell larsen press","bp":"chest","eq":"dumbbell","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders"],"st":["Sit on a bench with a dumbbell in each hand and lie back.","Press the dumbbells up and lift your feet off the floor, legs extended.","Lower the weights to the sides of your chest with control.","Press them back up until your arms are straight.","Keep your core braced so your lower back does not arch."],"img":"opengym/6272.webp","gif":null,"ext":1},{"id":"6288","n":"dolphin pose","bp":"shoulders","eq":"body weight","tg":"delts","mg":"hamstrings","sm":["hamstrings","upper back","triceps","calves"],"st":["Start on hands and knees, then lower to your forearms.","Tuck your toes and lift your hips up high.","Press your forearms into the floor.","Let your head hang between your arms.","Hold for 20-30 seconds."],"img":"opengym/6288.webp","gif":null,"ext":1},{"id":"6290","n":"chaturanga dandasana (four limbed staff pose)","bp":"chest","eq":"body weight","tg":"triceps","mg":"chest","sm":["chest","core","shoulders","glutes"],"st":["Start in a high plank with hands under shoulders.","Shift forward slightly.","Bend your elbows straight back to about 90 degrees.","Keep your body in one line, elbows close to your ribs.","Hold briefly, then press back up."],"img":"opengym/6290.webp","gif":null,"ext":1},{"id":"6291","n":"warrior pose ii","bp":"upper legs","eq":"body weight","tg":"quads","mg":"glutes","sm":["glutes","adductors","shoulders","core"],"st":["Stand with feet wide, turn your front foot out and back foot slightly in.","Bend your front knee over the ankle.","Extend both arms parallel to the floor.","Gaze over your front hand.","Hold for 20-30 seconds, then switch sides."],"img":"opengym/6291.webp","gif":null,"ext":1},{"id":"6292","n":"frog pose mandukasana","bp":"upper legs","eq":"body weight","tg":"adductors","mg":"groin","sm":["groin","inner thighs","hip flexors","glutes"],"st":["Start on hands and knees on a mat.","Slide your knees wide, with feet turned out and inline with knees.","Lower onto your forearms.","Push your hips back gently.","Hold for 20-30 seconds, breathing slowly."],"img":"opengym/6292.webp","gif":null,"ext":1},{"id":"6293","n":"peacock pose mayurasana","bp":"waist","eq":"body weight","tg":"abs","mg":"forearms","sm":["forearms","wrist flexors","shoulders","core"],"st":["Kneel and place your hands on the floor with fingers pointing back toward your feet.","Bring your elbows together under your belly.","Lean forward and rest your torso on your upper arms.","Extend your legs back and lift them.","Hold for a few breaths, then lower."],"img":"opengym/6293.webp","gif":null,"ext":1},{"id":"6294","n":"half frog pose ardha bhekasana","bp":"upper legs","eq":"body weight","tg":"quads","mg":"hip flexors","sm":["hip flexors","chest","shoulders","core"],"st":["Lie on your belly, propped on your forearms.","Bend one knee and reach back to hold that foot.","Gently press the foot toward your hip.","Keep your hips grounded.","Hold for 20-30 seconds, then switch legs."],"img":"opengym/6294.webp","gif":null,"ext":1},{"id":"6295","n":"sage marichi i pose marichyasana","bp":"waist","eq":"body weight","tg":"spine","mg":"obliques","sm":["obliques","hamstrings","glutes","shoulders"],"st":["Sit with one leg straight and the other knee bent, foot flat beside the straight leg.","Wrap your opposite arm around the bent knee.","Sit tall, then twist toward the bent knee.","Keep your spine long.","Hold for 20-30 seconds, then switch sides."],"img":"opengym/6295.webp","gif":null,"ext":1},{"id":"6296","n":"bird of paradise pose svarga dvijasana","bp":"upper legs","eq":"body weight","tg":"hamstrings","mg":"adductors","sm":["adductors","glutes","shoulders","core"],"st":["Stand and bind one arm behind your back around your bent knee.","Grab your hand with the other arm.","Step in and stand tall on the grounded leg.","Slowly straighten the lifted leg.","Hold for a few breaths, then switch."],"img":"opengym/6296.webp","gif":null,"ext":1},{"id":"6297","n":"wheel pose urdhva dhanurasana","bp":"back","eq":"body weight","tg":"spine","mg":"glutes","sm":["glutes","shoulders","triceps","hip flexors"],"st":["Lie on your back, knees bent, hands beside your head with fingers toward your feet.","Press into hands and feet and lift your hips.","Straighten your arms as you lift the crown of your head off the floor.","Press your chest toward the wall behind.","Hold for a few breaths, then lower slowly."],"img":"opengym/6297.webp","gif":null,"ext":1},{"id":"6298","n":"one legged upward bow pose eka pada urdhva dhanurasana","bp":"back","eq":"body weight","tg":"spine","mg":"glutes","sm":["glutes","hamstrings","shoulders","hip flexors"],"st":["Come into wheel pose with hands and feet pressing down.","Shift weight onto one foot.","Lift the other leg toward the ceiling.","Keep your hips high and level.","Hold briefly, lower, then switch legs."],"img":"opengym/6298.webp","gif":null,"ext":1},{"id":"6299","n":"dragonfly pose maksikanagasana","bp":"upper legs","eq":"body weight","tg":"adductors","mg":"hamstrings","sm":["hamstrings","groin","core","shoulders"],"st":["Squat with hands on the floor in front of you.","Place your knees high on your upper arms.","Lean forward and lift your feet off the floor.","Extend your legs wide to the sides.","Hold for a few breaths, then release."],"img":"opengym/6299.webp","gif":null,"ext":1},{"id":"6300","n":"half boat pose ardha navasana","bp":"waist","eq":"body weight","tg":"abs","mg":"hip flexors","sm":["hip flexors","lower back","quadriceps"],"st":["Sit with knees bent and lean back a little.","Lift your feet so your shins are parallel to the floor.","Extend your arms forward.","Keep your chest open and spine long.","Hold for 15-30 seconds."],"img":"opengym/6300.webp","gif":null,"ext":1},{"id":"6301","n":"eagle pose garudasana","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"quadriceps","sm":["quadriceps","shoulders","upper back","ankles"],"st":["Stand and bend your knees slightly.","Cross one thigh over the other, hooking the foot behind the calf if you can.","Wrap your arms, one under the other, palms together.","Sit your hips low and lift your elbows.","Hold for 20-30 seconds, then switch."],"img":"opengym/6301.webp","gif":null,"ext":1},{"id":"6302","n":"two legged inverted staff pose dwi pada viparita dandasana","bp":"back","eq":"body weight","tg":"spine","mg":"shoulders","sm":["shoulders","glutes","triceps","hip flexors"],"st":["Start in a headstand or lie on your back with elbows on the floor.","Arch your back and bring your feet toward the floor.","Keep your forearms firm.","Stay in the backbend, breathing steadily.","Hold briefly, then come out carefully."],"img":"opengym/6302.webp","gif":null,"ext":1},{"id":"6303","n":"camel pose ustrasana","bp":"upper legs","eq":"body weight","tg":"quads","mg":"hip flexors","sm":["hip flexors","chest","core","shoulders"],"st":["Kneel with knees hip-width apart and hands on your lower back.","Push your hips forward.","Lean back and reach for your heels.","Lift your chest and let your head drop gently if comfortable.","Hold for 15-30 seconds, then rise."],"img":"opengym/6303.webp","gif":null,"ext":1},{"id":"6304","n":"dancer pose natarajasana","bp":"upper legs","eq":"body weight","tg":"quads","mg":"hip flexors","sm":["hip flexors","glutes","chest","shoulders"],"st":["Stand tall and bend one knee, holding that foot behind you.","Kick your foot back into your hand.","Reach your free arm forward.","Tilt your torso forward as the leg lifts.","Hold for 20-30 seconds, then switch."],"img":"opengym/6304.webp","gif":null,"ext":1},{"id":"6316","n":"basic to cross donkey kick","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"hamstrings","sm":["hamstrings","core","shoulders","glutes"],"st":["Start on hands and knees.","Lift one leg back with a bent knee, sole toward the ceiling.","Lower it, then kick it across behind your other leg.","Alternate basic and cross kicks.","Keep your hips level, then switch legs."],"img":"opengym/6316.webp","gif":null,"ext":1},{"id":"6318","n":"single curtsy lunge","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"quadriceps","sm":["quadriceps","adductors","hamstrings","core"],"st":["Stand tall with feet hip-width apart.","Step one leg diagonally behind the other.","Bend both knees and lower your hips.","Keep your chest up and front knee over your toes.","Push up and return, then switch sides."],"img":"opengym/6318.webp","gif":null,"ext":1},{"id":"6327","n":"bodyweight low split squat","bp":"upper legs","eq":"body weight","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","adductors"],"st":["Step one foot forward into a long split stance.","Keep your torso upright and your hands on your hips.","Lower your back knee toward the floor as far as you can control.","Drive through your front foot to stand back up.","Finish all reps, then switch legs."],"img":"opengym/6327.webp","gif":null,"ext":1},{"id":"6328","n":"dumbbell low split squat","bp":"upper legs","eq":"dumbbell","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","adductors"],"st":["Hold a dumbbell in each hand and step into a long split stance.","Keep your chest up and your front foot flat.","Lower your back knee toward the floor in a controlled way.","Push through your front heel to rise.","Complete your reps, then switch legs."],"img":"opengym/6328.webp","gif":null,"ext":1},{"id":"6329","n":"barbell low split squat","bp":"upper legs","eq":"barbell","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","adductors"],"st":["Rest a barbell across your upper back and step into a long split stance.","Brace your core and keep your torso tall.","Lower your back knee toward the floor under control.","Press through your front foot to stand up.","Finish your reps, then switch legs."],"img":"opengym/6329.webp","gif":null,"ext":1},{"id":"6335","n":"side kick through","bp":"waist","eq":"body weight","tg":"abs","mg":"obliques","sm":["obliques","shoulders","hip flexors"],"st":["Start in a high plank, then rotate onto one hand with your chest turned to the side.","Lift your hips and keep your core tight.","Sweep your top leg under your body and through the gap.","Return the leg to the start with control.","Repeat, then switch sides."],"img":"opengym/6335.webp","gif":null,"ext":1},{"id":"6336","n":"bodyweight slow to explosive squats","bp":"upper legs","eq":"body weight","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","calves"],"st":["Stand with your feet shoulder-width apart.","Lower into a squat over about three seconds.","Pause briefly at the bottom with your chest up.","Explode upward into a jump.","Land softly with bent knees and go straight into the next rep."],"img":"opengym/6336.webp","gif":null,"ext":1},{"id":"6341","n":"humble warrior pose","bp":"upper legs","eq":"body weight","tg":"hamstrings","mg":"quadriceps","sm":["quadriceps","glutes","shoulders","chest"],"st":["Step into a wide lunge with the front knee bent.","Clasp your hands behind your back.","Fold your torso inside your front thigh.","Let your arms float overhead.","Hold for 20-30 seconds, then switch sides."],"img":"opengym/6341.webp","gif":null,"ext":1},{"id":"6344","n":"holding squat","bp":"upper legs","eq":"body weight","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","core"],"st":["Stand with your feet shoulder-width apart.","Sit down into a squat until your thighs are about parallel to the floor.","Keep your chest up and your knees tracking over your toes.","Hold the position while breathing steadily.","Hold for 20-40 seconds, then stand up."],"img":"opengym/6344.webp","gif":null,"ext":1},{"id":"6350","n":"lying prone y raise","bp":"back","eq":"body weight","tg":"upper back","mg":"rear deltoids","sm":["rear deltoids","trapezius","lower back"],"st":["Lie face down with your arms stretched overhead in a Y shape.","Keep your forehead near the floor and your neck long.","Lift your arms off the floor by squeezing your shoulder blades.","Pause for a second at the top.","Lower your arms slowly and repeat."],"img":"opengym/6350.webp","gif":null,"ext":1},{"id":"6354","n":"lever outdoor seated leg press","bp":"upper legs","eq":"leverage machine","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","calves"],"st":["Sit on the seat with your back against the pad.","Place your feet on the footplates, shoulder-width apart.","Push the plates away until your legs are nearly straight.","Do not lock your knees at the top.","Bend your knees to return slowly and repeat."],"img":"opengym/6354.webp","gif":null,"ext":1},{"id":"6355","n":"lever outdoor seated chest press","bp":"chest","eq":"leverage machine","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders"],"st":["Sit with your back flat against the pad and grip the handles at chest height.","Keep your shoulders down and back.","Press the handles forward until your arms are almost straight.","Pause briefly.","Let the handles come back slowly and repeat."],"img":"opengym/6355.webp","gif":null,"ext":1},{"id":"6356","n":"lever outdoor seated lat pulldown","bp":"back","eq":"leverage machine","tg":"lats","mg":"biceps","sm":["biceps","rhomboids","rear deltoids"],"st":["Sit down and grab the handles overhead.","Lean back very slightly and lift your chest.","Pull the handles down toward your upper chest, driving your elbows down.","Squeeze your back at the bottom.","Let your arms rise slowly until fully stretched, then repeat."],"img":"opengym/6356.webp","gif":null,"ext":1},{"id":"6358","n":"ez barbell standing wrist curl","bp":"lower arms","eq":"ez barbell","tg":"forearms","mg":"wrist flexors","sm":["wrist flexors","grip muscles"],"st":["Stand holding an EZ bar with an underhand grip, arms hanging in front.","Keep your elbows still and close to your body.","Curl your wrists upward, lifting the bar a short distance.","Squeeze at the top.","Lower the bar slowly and repeat."],"img":"opengym/6358.webp","gif":null,"ext":1},{"id":"6359","n":"dumbbell standing wrist curl","bp":"lower arms","eq":"dumbbell","tg":"forearms","mg":"wrist flexors","sm":["wrist flexors","grip muscles"],"st":["Stand with a dumbbell in each hand, palms facing forward.","Keep your arms still at your sides.","Curl your wrists up, bringing the dumbbells toward your forearms.","Squeeze at the top.","Lower slowly and repeat."],"img":"opengym/6359.webp","gif":null,"ext":1},{"id":"6360","n":"cable standing wrist curl","bp":"lower arms","eq":"cable","tg":"forearms","mg":"wrist flexors","sm":["wrist flexors","grip muscles"],"st":["Face a low cable pulley and grab the handle with an underhand grip.","Step back and let your arms hang with elbows tucked.","Curl your wrists upward against the cable.","Squeeze at the top.","Lower with control and repeat."],"img":"opengym/6360.webp","gif":null,"ext":1},{"id":"6361","n":"ez barbell standing wrist reverse curl","bp":"lower arms","eq":"ez barbell","tg":"forearms","mg":"wrist extensors","sm":["wrist extensors","grip muscles"],"st":["Stand holding an EZ bar with an overhand grip, arms hanging in front.","Keep your elbows still at your sides.","Extend your wrists to raise the bar upward.","Hold briefly at the top.","Lower slowly and repeat."],"img":"opengym/6361.webp","gif":null,"ext":1},{"id":"6362","n":"dumbbell standing wrist reverse curl","bp":"lower arms","eq":"dumbbell","tg":"forearms","mg":"wrist extensors","sm":["wrist extensors","grip muscles"],"st":["Stand with a dumbbell in each hand, palms facing down.","Keep your upper arms still.","Lift the backs of your hands up by extending your wrists.","Pause at the top.","Lower slowly and repeat."],"img":"opengym/6362.webp","gif":null,"ext":1},{"id":"6363","n":"cable standing wrist reverse curl","bp":"lower arms","eq":"cable","tg":"forearms","mg":"wrist extensors","sm":["wrist extensors","grip muscles"],"st":["Face a low cable and grab the handle with an overhand grip.","Step back and let your arms hang with elbows close to your sides.","Extend your wrists to pull the handle upward.","Hold for a second.","Lower under control and repeat."],"img":"opengym/6363.webp","gif":null,"ext":1},{"id":"6364","n":"ez barbell seated wrist reverse curl","bp":"lower arms","eq":"ez barbell","tg":"forearms","mg":"wrist extensors","sm":["wrist extensors","grip muscles"],"st":["Sit and rest your forearms on your thighs, holding an EZ bar overhand.","Let your wrists hang past your knees.","Extend your wrists to lift the bar.","Squeeze at the top.","Lower slowly and repeat."],"img":"opengym/6364.webp","gif":null,"ext":1},{"id":"6365","n":"ez barbell standing back wrist curl","bp":"lower arms","eq":"ez barbell","tg":"forearms","mg":"wrist flexors","sm":["wrist flexors","grip muscles"],"st":["Stand holding an EZ bar behind your back with an underhand grip.","Keep your elbows still and your chest up.","Curl your wrists to raise the bar slightly.","Squeeze at the top.","Lower with control and repeat."],"img":"opengym/6365.webp","gif":null,"ext":1},{"id":"6366","n":"dumbbell standing back wrist curl","bp":"lower arms","eq":"dumbbell","tg":"forearms","mg":"wrist flexors","sm":["wrist flexors","grip muscles"],"st":["Stand with a dumbbell in each hand behind your back, palms facing back.","Keep your arms still and your chest tall.","Curl your wrists upward.","Squeeze at the top.","Lower slowly and repeat."],"img":"opengym/6366.webp","gif":null,"ext":1},{"id":"6367","n":"cable standing back wrist curl v. 2","bp":"lower arms","eq":"cable","tg":"forearms","mg":"wrist flexors","sm":["wrist flexors","grip muscles"],"st":["Stand with your back to a low cable and hold the handle behind you.","Keep your elbows tucked and your chest up.","Curl your wrists to pull the handle upward.","Squeeze at the top.","Lower with control and repeat."],"img":"opengym/6367.webp","gif":null,"ext":1},{"id":"6392","n":"cable lateral pulldown with mag grip","bp":"back","eq":"cable","tg":"lats","mg":"biceps","sm":["biceps","rhomboids","rear deltoids"],"st":["Sit at the pulldown station and grab the grip overhead.","Lean back slightly and lift your chest.","Pull the grip down to your upper chest, driving your elbows down.","Squeeze your lats at the bottom.","Let the bar rise slowly to a full stretch and repeat."],"img":"opengym/6392.webp","gif":null,"ext":1},{"id":"6406","n":"ez barbell preacher curl","bp":"upper arms","eq":"ez barbell","tg":"biceps","mg":"brachialis","sm":["brachialis","forearms"],"st":["Sit at a preacher bench with your upper arms resting on the pad.","Hold an EZ bar with an underhand grip.","Curl the bar up toward your shoulders.","Squeeze your biceps at the top.","Lower slowly until your arms are almost straight and repeat."],"img":"opengym/6406.webp","gif":null,"ext":1},{"id":"6419","n":"resistance band reverse crunch v. 2","bp":"waist","eq":"resistance band","tg":"abs","mg":"lower abs","sm":["lower abs","hip flexors"],"st":["Lie on your back and hold the band firmly with both hands.","Lift your bent knees over your hips.","Curl your pelvis upward, bringing your knees toward your chest.","Hold for a moment at the top.","Lower with control and repeat."],"img":"opengym/6419.webp","gif":null,"ext":1},{"id":"6423","n":"bodyweight triceps extension from plank position","bp":"upper arms","eq":"body weight","tg":"triceps","mg":"shoulders","sm":["shoulders","core"],"st":["Start in a forearm-height plank with your hands under your shoulders.","Keep your body in a straight line.","Lean forward and bend your elbows to lower your head toward your hands.","Press back up by straightening your arms.","Keep your core tight and repeat."],"img":"opengym/6423.webp","gif":null,"ext":1},{"id":"6424","n":"dumbbell good morning","bp":"upper legs","eq":"dumbbell","tg":"hamstrings","mg":"glutes","sm":["glutes","lower back","core"],"st":["Stand with feet hip-width apart, holding one dumbbell against your chest.","Soften your knees slightly.","Push your hips back and lean your torso forward with a flat back.","Stop when you feel a stretch in your hamstrings.","Drive your hips forward to stand tall."],"img":"opengym/6424.webp","gif":null,"ext":1},{"id":"6425","n":"kettlebell good morning v. 2","bp":"upper legs","eq":"kettlebell","tg":"hamstrings","mg":"glutes","sm":["glutes","lower back","core"],"st":["Stand with feet hip-width apart, holding a kettlebell at your chest.","Keep your knees slightly bent.","Push your hips back and tip your torso forward, back flat.","Lower until you feel your hamstrings stretch.","Squeeze your glutes to return upright."],"img":"opengym/6425.webp","gif":null,"ext":1},{"id":"6428","n":"90 degree heel touch v. 2","bp":"waist","eq":"body weight","tg":"abs","mg":"obliques","sm":["obliques"],"st":["Lie on your back with knees bent and feet flat.","Lift your shoulders slightly off the floor.","Reach your right hand toward your right heel.","Switch and reach your left hand to your left heel.","Keep your core tight and continue alternating."],"img":"opengym/6428.webp","gif":null,"ext":1},{"id":"6435","n":"heel glute bridge","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"hamstrings","sm":["hamstrings","core","lower back"],"st":["Lie on your back with knees bent and heels on the floor, toes lifted.","Keep your arms by your sides.","Press through your heels and raise your hips.","Squeeze your glutes at the top.","Lower slowly."],"img":"opengym/6435.webp","gif":null,"ext":1},{"id":"6437","n":"resistance band shoulder adduction","bp":"shoulders","eq":"resistance band","tg":"lats","mg":"shoulders","sm":["shoulders","rear deltoids","triceps","core"],"st":["Anchor a band overhead and hold the handle with your arm raised.","Stand tall with your core braced.","Pull your arm down toward your side.","Keep your elbow straight or slightly bent.","Return slowly, then switch arms."],"img":"opengym/6437.webp","gif":null,"ext":1},{"id":"6438","n":"bent over shoulder pendulum","bp":"shoulders","eq":"body weight","tg":"delts","mg":"rotator cuff","sm":["rotator cuff","upper back"],"st":["Stand beside a bench and rest one hand on it, hinging forward at the hips.","Let the other arm hang straight down, relaxed.","Swing the arm gently forward and back in a small arc using your body's motion.","Then swing it side to side and in small circles.","Keep the shoulder loose and the movement easy.","Do equal time on both sides."],"img":"opengym/6438.webp","gif":null,"ext":1},{"id":"6439","n":"resistance band standing single arm shoulder flexion","bp":"shoulders","eq":"resistance band","tg":"delts","mg":"upper chest","sm":["upper chest","core"],"st":["Stand on the band with one foot and hold the handle at your thigh, palm down.","Brace your core and keep your torso upright.","Raise the arm forward to shoulder height with a slight elbow bend.","Pause briefly at the top.","Lower slowly against the band tension.","Finish your reps, then switch arms."],"img":"opengym/6439.webp","gif":null,"ext":1},{"id":"6440","n":"resistance band standing single arm lateral shoulder extension","bp":"shoulders","eq":"resistance band","tg":"delts","mg":"rear deltoids","sm":["rear deltoids","upper back"],"st":["Anchor the band at about waist height and stand sideways to it.","Hold the handle with the far hand, arm across your body.","Keep your chest tall and core braced.","Sweep the arm out and slightly back to the side with a soft elbow.","Return slowly to the start without letting the band snap.","Complete all reps, then turn around and switch arms."],"img":"opengym/6440.webp","gif":null,"ext":1},{"id":"6441","n":"resistance band standing external rotation","bp":"shoulders","eq":"resistance band","tg":"delts","mg":"rotator cuff","sm":["rotator cuff","rear deltoids","upper back"],"st":["Anchor the band at elbow height and stand sideways to it.","Hold the handle with the far hand, elbow bent 90 degrees and tucked at your side.","Rotate the forearm outward, keeping the elbow pinned.","Pause when your hand points forward or slightly out.","Return slowly under control.","Finish your reps, then switch sides."],"img":"opengym/6441.webp","gif":null,"ext":1},{"id":"6442","n":"bear plank kickback","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"hamstrings","sm":["hamstrings","core","shoulders"],"st":["Start on hands and knees, then lift your knees a few centimetres off the floor.","Keep your back flat and core braced.","Extend one leg back and up, squeezing your glute.","Bring the knee back in without touching down.","Repeat, then switch legs."],"img":"opengym/6442.webp","gif":null,"ext":1},{"id":"6443","n":"half seated leg circle","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"hip flexors","sm":["hip flexors","core","adductors"],"st":["Sit on the floor leaning back slightly on your hands.","Lift one leg a little off the floor.","Draw slow circles in the air with that foot.","Keep your core engaged and your torso steady.","Switch directions, then switch legs."],"img":"opengym/6443.webp","gif":null,"ext":1},{"id":"6444","n":"yoga vajrasana thunderbolt diamond pose","bp":"upper legs","eq":"body weight","tg":"quads","mg":"ankles","sm":["ankles","shins","feet"],"st":["Kneel on the floor with your knees together.","Point your toes back and sit on your heels.","Rest your hands on your thighs.","Lengthen your spine and breathe slowly.","Hold for 30-60 seconds."],"img":"opengym/6444.webp","gif":null,"ext":1},{"id":"6464","n":"bodyweight frog hip thrust","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"hamstrings","sm":["hamstrings","adductors","core"],"st":["Lie on your back with the soles of your feet together and knees falling out.","Keep your feet close to your hips.","Push through your feet to lift your hips.","Squeeze your glutes at the top.","Lower slowly and repeat."],"img":"opengym/6464.webp","gif":null,"ext":1},{"id":"6465","n":"smith frog hip thrust","bp":"upper legs","eq":"smith machine","tg":"glutes","mg":"hamstrings","sm":["hamstrings","adductors","core"],"st":["Sit with your upper back on a bench and the Smith bar over your hips.","Put the soles of your feet together, knees open.","Drive your hips up until your body is level.","Squeeze your glutes at the top.","Lower under control and repeat."],"img":"opengym/6465.webp","gif":null,"ext":1},{"id":"6466","n":"side plank bent leg lift","bp":"waist","eq":"body weight","tg":"obliques","mg":"abdominals","sm":["abdominals","glutes","shoulders"],"st":["Lie on one side and prop yourself on your forearm.","Lift your hips so your body forms a line.","Bend your top knee and lift it upward.","Lower it without dropping your hips.","Finish your reps, then switch sides."],"img":"opengym/6466.webp","gif":null,"ext":1},{"id":"6485","n":"weighted plate standing lateral raise","bp":"shoulders","eq":"weight plate","tg":"delts","mg":"trapezius","sm":["trapezius","rotator cuff"],"st":["Stand tall holding a plate in each hand at your sides.","Keep a slight bend in your elbows.","Raise your arms out to the sides up to shoulder height.","Pause briefly.","Lower slowly and repeat."],"img":"opengym/6485.webp","gif":null,"ext":1},{"id":"6486","n":"band bent over rear lateral raise v. 2","bp":"shoulders","eq":"band","tg":"delts","mg":"rear deltoids","sm":["rear deltoids","rhomboids","trapezius"],"st":["Stand on a band and hinge forward with a flat back.","Hold the band ends in each hand.","Raise your arms out to the sides up to shoulder height.","Squeeze your shoulder blades together.","Lower slowly and repeat."],"img":"opengym/6486.webp","gif":null,"ext":1},{"id":"6510","n":"cable single arm high row","bp":"back","eq":"cable","tg":"lats","mg":"upper back","sm":["upper back","rear deltoids","biceps"],"st":["Set a cable to a high position and hold the handle with one hand.","Brace your core and stand or kneel tall.","Pull the handle toward your torso, driving your elbow back.","Squeeze your shoulder blade at the end.","Return slowly, then switch arms."],"img":"opengym/6510.webp","gif":null,"ext":1},{"id":"6511","n":"cable single arm high scapular row","bp":"back","eq":"cable","tg":"upper back","mg":"rhomboids","sm":["rhomboids","trapezius","rear deltoids"],"st":["Set a cable high and hold the handle with one hand.","Stand tall with your core braced.","Pull your shoulder blade back and down, bending the elbow slightly.","Squeeze at the end.","Release slowly, then switch arms."],"img":"opengym/6511.webp","gif":null,"ext":1},{"id":"6512","n":"cable single arm low scapular row","bp":"back","eq":"cable","tg":"upper back","mg":"rhomboids","sm":["rhomboids","trapezius","rear deltoids"],"st":["Set a cable low and hold the handle with one hand.","Hinge slightly forward with a flat back.","Pull your shoulder blade back toward your spine.","Squeeze for a second.","Return slowly, then switch arms."],"img":"opengym/6512.webp","gif":null,"ext":1},{"id":"6513","n":"lever bent over row (with chest support)","bp":"back","eq":"leverage machine","tg":"upper back","mg":"lats","sm":["lats","rear deltoids","biceps"],"st":["Lean your chest against the pad and grab the handles.","Keep your shoulders relaxed.","Pull the handles toward your body, driving your elbows back.","Squeeze your shoulder blades together.","Lower slowly and repeat."],"img":"opengym/6513.webp","gif":null,"ext":1},{"id":"6514","n":"lever bent over neutral grip row (with chest support)","bp":"back","eq":"leverage machine","tg":"upper back","mg":"lats","sm":["lats","rear deltoids","biceps"],"st":["Lean your chest on the pad and take a neutral grip on the handles.","Start with your arms extended.","Pull the handles toward your ribs, elbows close to your body.","Squeeze at the end.","Return slowly and repeat."],"img":"opengym/6514.webp","gif":null,"ext":1},{"id":"6515","n":"lever bent over single arm neutral grip row (with chest support)","bp":"back","eq":"leverage machine","tg":"upper back","mg":"lats","sm":["lats","rear deltoids","biceps"],"st":["Lean your chest against the pad and grip one handle, palm in.","Start with your arm extended.","Pull the handle back, driving your elbow past your torso.","Squeeze your back at the end.","Return slowly, finish your reps, then switch arms."],"img":"opengym/6515.webp","gif":null,"ext":1},{"id":"6516","n":"lever bent over wide grip row (with chest support)","bp":"back","eq":"leverage machine","tg":"upper back","mg":"rear deltoids","sm":["rear deltoids","rhomboids","biceps"],"st":["Lean your chest on the pad and take the wide handles.","Start with your arms extended.","Pull the handles back with your elbows flared out.","Squeeze your shoulder blades together.","Return slowly and repeat."],"img":"opengym/6516.webp","gif":null,"ext":1},{"id":"6517","n":"lever bent over single arm wide grip row (with chest support)","bp":"back","eq":"leverage machine","tg":"upper back","mg":"rear deltoids","sm":["rear deltoids","rhomboids","biceps"],"st":["Lean your chest on the pad and grip one wide handle.","Start with your arm extended.","Pull the handle back with your elbow flaring out.","Squeeze at the end.","Return slowly, finish your reps, then switch arms."],"img":"opengym/6517.webp","gif":null,"ext":1},{"id":"6523","n":"lever linear hack squat","bp":"upper legs","eq":"leverage machine","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","calves"],"st":["Stand on the platform with your back against the pad and shoulders under the supports.","Place your feet shoulder-width apart.","Lower into a squat until your thighs are about parallel.","Press through your feet to stand.","Keep your back against the pad throughout."],"img":"opengym/6523.webp","gif":null,"ext":1},{"id":"6537","n":"push up pull","bp":"chest","eq":"body weight","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders","lats"],"st":["Start in a high plank with your hands under your shoulders.","Lower your chest to the floor in a push-up.","Press back up to the top.","Drag one hand across the floor as if pulling yourself forward.","Alternate sides and keep your core tight."],"img":"opengym/6537.webp","gif":null,"ext":1},{"id":"6539","n":"armless prayer stretch","bp":"upper legs","eq":"body weight","tg":"lats","mg":"shoulders","sm":["shoulders","lower back"],"st":["Kneel on the floor and sit your hips back toward your heels.","Reach your arms forward and lower your chest.","Let your forehead rest near the floor.","Relax your shoulders and breathe deeply.","Hold for 20-30 seconds."],"img":"opengym/6539.webp","gif":null,"ext":1},{"id":"6540","n":"big turn back stretch","bp":"back","eq":"body weight","tg":"spine","mg":"obliques","sm":["obliques","lats"],"st":["Stand tall with feet hip-width apart and arms out in front.","Slowly rotate your upper body to one side, leading with the arms.","Keep your hips facing forward as much as you can.","Turn until you feel a comfortable stretch through the back.","Hold for 20-30 seconds, breathing calmly.","Return to center and repeat on the other side."],"img":"opengym/6540.webp","gif":null,"ext":1},{"id":"6541","n":"bodyweight bench squat","bp":"upper legs","eq":"body weight","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","core"],"st":["Stand in front of a bench with feet shoulder-width apart.","Push your hips back and bend your knees to lower.","Lightly touch the bench with your glutes without dropping onto it.","Keep your chest up and knees tracking over your toes.","Drive through your whole foot to stand back up.","Squeeze your glutes at the top."],"img":"opengym/6541.webp","gif":null,"ext":1},{"id":"6542","n":"cable kneeling high to low fly","bp":"chest","eq":"cable","tg":"pectorals","mg":"shoulders","sm":["shoulders","core"],"st":["Set the cables high and kneel between them, holding a handle in each hand.","Keep a slight bend in your elbows.","Sweep your arms down and together in front of your hips.","Squeeze your chest at the bottom.","Return slowly and repeat."],"img":"opengym/6542.webp","gif":null,"ext":1},{"id":"6543","n":"cable front raise (rope attachment)","bp":"shoulders","eq":"cable","tg":"delts","mg":"upper chest","sm":["upper chest","core"],"st":["Attach a rope to a low pulley and face away from the machine.","Hold the rope ends and let your arms hang with the cable between your legs.","Raise your arms forward to shoulder height with soft elbows.","Pause briefly at the top.","Lower slowly without letting the stack rest.","Keep your torso still, no swinging."],"img":"opengym/6543.webp","gif":null,"ext":1},{"id":"6544","n":"cable goblet squat","bp":"upper legs","eq":"cable","tg":"quads","mg":"glutes","sm":["glutes","core","hamstrings"],"st":["Attach a handle or rope to a low pulley and hold it against your chest.","Step back until there is tension and set your feet shoulder-width apart.","Sit your hips down and back, keeping your chest tall.","Lower until your thighs are about parallel to the floor.","Push through your feet to stand up.","Keep your elbows pointing down throughout."],"img":"opengym/6544.webp","gif":null,"ext":1},{"id":"6545","n":"handstand hold on wall","bp":"shoulders","eq":"body weight","tg":"delts","mg":"triceps","sm":["triceps","upper back","core"],"st":["Place your hands on the floor a short distance from a wall.","Kick up carefully until your heels rest on the wall.","Push the floor away and keep your arms straight.","Tighten your core and glutes.","Hold for 15-30 seconds, then come down with control."],"img":"opengym/6545.webp","gif":null,"ext":1},{"id":"6546","n":"landmine single leg hip thrust","bp":"upper legs","eq":"landmine","tg":"glutes","mg":"hamstrings","sm":["hamstrings","core"],"st":["Rest your upper back on a bench with a padded landmine bar across your hips.","Plant one foot on the floor and extend the other leg or hold it up.","Drive through the planted heel and lift your hips.","Squeeze the glute at the top with your torso level.","Lower with control.","Finish your reps, then switch legs."],"img":"opengym/6546.webp","gif":null,"ext":1},{"id":"6547","n":"hanging hollow hold","bp":"waist","eq":"body weight","tg":"abs","mg":"lower abs","sm":["lower abs","hip flexors","grip muscles"],"st":["Grab a pull-up bar with an overhand grip and hang with straight arms.","Brace your abs and tuck your pelvis slightly.","Lift your legs forward a little so your body forms a gentle hollow shape.","Keep your shoulders active and avoid swinging.","Hold the position for as long as you can with good form.","Lower down under control."],"img":"opengym/6547.webp","gif":null,"ext":1},{"id":"6548","n":"decline knee raise","bp":"waist","eq":"body weight","tg":"abs","mg":"lower abs","sm":["lower abs","hip flexors"],"st":["Lie on a decline bench and grip the top behind your head.","Extend your legs with a slight knee bend.","Pull your knees up toward your chest, curling the pelvis off the bench.","Pause briefly at the top.","Lower your legs slowly without letting the hips drop hard.","Keep the movement smooth, not jerky."],"img":"opengym/6548.webp","gif":null,"ext":1},{"id":"6549","n":"weighted plate standing around the world","bp":"shoulders","eq":"weight plate","tg":"delts","mg":"core","sm":["core","upper back","forearms"],"st":["Stand tall and hold a weight plate with both hands at your waist.","Brace your core and keep your feet planted.","Raise the plate up and over to one side in a wide circle, then around your head.","Bring it back down on the other side.","Keep your hips still as the plate travels.","Do half the reps in each direction."],"img":"opengym/6549.webp","gif":null,"ext":1},{"id":"6550","n":"incline push up on a smith bar","bp":"chest","eq":"body weight","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders","core"],"st":["Set the Smith bar at about waist height and rack it securely.","Place your hands on the bar slightly wider than your shoulders.","Keep your body in a straight line.","Lower your chest to the bar.","Push back up to straight arms."],"img":"opengym/6550.webp","gif":null,"ext":1},{"id":"6551","n":"bodyweight reverse lunge with overhead reach","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","core"],"st":["Stand tall with your feet hip-width apart.","Step one foot back and lower into a lunge.","Reach both arms overhead as you lower.","Push through your front foot to stand.","Alternate legs."],"img":"opengym/6551.webp","gif":null,"ext":1},{"id":"6552","n":"cable romanian deadlift","bp":"upper legs","eq":"cable","tg":"hamstrings","mg":"glutes","sm":["glutes","lower back","grip muscles"],"st":["Attach a straight bar to a low pulley and face the machine.","Hold the bar, step back and stand tall with soft knees.","Push your hips back and slide the bar down your thighs.","Keep your back flat and shoulders pulled back.","Lower until you feel a hamstring stretch.","Drive your hips forward to stand up."],"img":"opengym/6552.webp","gif":null,"ext":1},{"id":"6554","n":"glute ham sit up","bp":"waist","eq":"leverage machine","tg":"abs","mg":"hip flexors","sm":["hip flexors","lower back","quadriceps"],"st":["Set your feet under the pads of a glute ham bench, hips on the support.","Cross your arms over your chest and lean back to a comfortable depth.","Brace your abs and curl up until your torso is upright.","Pause briefly at the top.","Lower slowly under control.","Keep your lower back from over-arching at the bottom."],"img":"opengym/6554.webp","gif":null,"ext":1},{"id":"6555","n":"ab mat sit up","bp":"waist","eq":"body weight","tg":"abs","mg":"hip flexors","sm":["hip flexors","obliques"],"st":["Lie back on an ab mat with knees bent and feet flat.","Cross your arms over your chest or place your hands by your ears.","Curl your torso up until you are sitting tall.","Pause briefly at the top.","Lower back down slowly.","Avoid pulling on your neck."],"img":"opengym/6555.webp","gif":null,"ext":1},{"id":"6558","n":"dumbbell banded wall sit","bp":"upper legs","eq":"dumbbell","tg":"quads","mg":"glutes","sm":["glutes","adductors","hamstrings"],"st":["Put a band around your thighs and stand with your back against a wall.","Slide down until your thighs are about parallel.","Hold a dumbbell in both hands in front of you.","Push your knees out against the band.","Hold for 20-40 seconds."],"img":"opengym/6558.webp","gif":null,"ext":1},{"id":"6559","n":"weighted plate tibialis anterior curl","bp":"lower legs","eq":"weight plate","tg":"shins","mg":"calves","sm":["calves","ankles"],"st":["Sit on a bench and rest a plate on your forefoot.","Keep your heel on the floor.","Pull your toes up toward your shin.","Pause at the top.","Lower slowly and repeat."],"img":"opengym/6559.webp","gif":null,"ext":1},{"id":"6560","n":"90 to 90 stretch","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"hip flexors","sm":["hip flexors","adductors","lower back"],"st":["Sit on the floor with one leg bent in front and the other bent out to the side, both at about 90 degrees.","Sit tall with your hands on the floor.","Hinge forward over the front shin until you feel a stretch in the hip.","Hold for 20-30 seconds, breathing calmly.","Come back up slowly.","Switch sides."],"img":"opengym/6560.webp","gif":null,"ext":1},{"id":"6561","n":"lever ab swing","bp":"waist","eq":"leverage machine","tg":"abs","mg":"obliques","sm":["obliques","hip flexors"],"st":["Sit in the machine and secure yourself with the pads.","Hold the handles and brace your core.","Swing your legs to one side using your abs.","Return to the centre with control.","Repeat on the other side."],"img":"opengym/6561.webp","gif":null,"ext":1},{"id":"6570","n":"glute bridge walk","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"hamstrings","sm":["hamstrings","core"],"st":["Lie on your back with knees bent and feet flat.","Lift your hips into a glute bridge.","Keep the hips high and walk your feet out a few small steps.","Then walk them back in toward your body.","Keep your hips level and avoid sagging.","Lower with control when finished."],"img":"opengym/6570.webp","gif":null,"ext":1},{"id":"6584","n":"barbell feet flat bench press","bp":"chest","eq":"barbell","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders"],"st":["Lie on a bench and place your feet flat on it, knees bent.","Grip the bar slightly wider than your shoulders.","Lower the bar to your mid-chest.","Press it back up until your arms are straight.","Keep your lower back flat and your core tight."],"img":"opengym/6584.webp","gif":null,"ext":1},{"id":"6599","n":"bear crawl low hip","bp":"full body","eq":"body weight","tg":"cardiovascular system","mg":"shoulders","sm":["shoulders","quadriceps","core"],"st":["Start on hands and feet with your knees slightly off the floor.","Keep your hips low and your back flat.","Crawl forward with opposite hand and foot.","Stay controlled and quiet.","Crawl for 20-30 seconds."],"img":"opengym/6599.webp","gif":null,"ext":1},{"id":"6600","n":"bodyweight supported squat","bp":"upper legs","eq":"body weight","tg":"quads","mg":"glutes","sm":["glutes","hamstrings"],"st":["Hold on to a sturdy support at chest height.","Stand with feet shoulder-width apart.","Sit your hips back and down into a squat.","Keep your chest up and your heels down.","Stand back up by pushing through your feet."],"img":"opengym/6600.webp","gif":null,"ext":1},{"id":"6601","n":"lever glute press","bp":"upper legs","eq":"leverage machine","tg":"glutes","mg":"hamstrings","sm":["hamstrings","quadriceps"],"st":["Position yourself on the machine and set your feet on the platform.","Brace your core.","Press the platform away by driving through your heels.","Squeeze your glutes at the end.","Return slowly and repeat."],"img":"opengym/6601.webp","gif":null,"ext":1},{"id":"6606","n":"smith curtsey lunge","bp":"upper legs","eq":"smith machine","tg":"glutes","mg":"quadriceps","sm":["quadriceps","adductors","hamstrings"],"st":["Set the bar on your upper back and unrack it, feet hip-width apart.","Step one leg back and diagonally behind the other, like a curtsey.","Lower until your front thigh is near parallel, chest tall.","Press through the front heel to return to standing.","Finish all reps, then switch sides."],"img":"opengym/6606.webp","gif":null,"ext":1},{"id":"6618","n":"low lunge yoga pose anjaneyasana i","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hip flexors","groin"],"st":["Start in a lunge with the front knee over the ankle.","Lower the back knee to the floor and untuck the toes.","Sink your hips forward and down.","Raise both arms overhead and lift your chest.","Hold for 20-30 seconds, breathing calmly.","Step back and switch legs."],"img":"opengym/6618.webp","gif":null,"ext":1},{"id":"6632","n":"diagonal reach on chair","bp":"waist","eq":"body weight","tg":"abs","mg":"obliques","sm":["obliques","core","shoulders"],"st":["Sit tall on the front edge of a chair with feet flat.","Extend your arms out in front of you.","Reach one hand diagonally down toward the opposite foot, rotating your torso.","Return to upright with control.","Reach to the other side and keep alternating."],"img":"opengym/6632.webp","gif":null,"ext":1},{"id":"6648","n":"cable high pull with rope attachment","bp":"shoulders","eq":"cable","tg":"delts","mg":"rear deltoids","sm":["rear deltoids","upper back","trapezius","biceps"],"st":["Attach a rope to a high pulley and grip an end in each hand.","Step back until the cable is taut, with a slight lean back.","Pull the rope toward your face, elbows flaring high.","Squeeze your shoulder blades together at the end.","Let the rope return slowly to the start."],"img":"opengym/6648.webp","gif":null,"ext":1},{"id":"6692","n":"barbell deadlift (side pov)","bp":"upper legs","eq":"barbell","tg":"glutes","mg":"hamstrings","sm":["hamstrings","lower back","quadriceps","grip muscles","trapezius"],"st":["Stand with the bar over mid-foot and grip it just outside your legs.","Brace your core, flatten your back and pull the slack out of the bar.","Push the floor away and stand up, keeping the bar close to your legs.","Lock out the hips without leaning back.","Hinge at the hips and lower the bar under control."],"img":"opengym/6692.webp","gif":null,"ext":1},{"id":"6693","n":"cable kneeling side crunch","bp":"waist","eq":"cable","tg":"obliques","mg":"core","sm":["core"],"st":["Attach a rope to a high pulley and kneel beside the stack.","Hold the rope at the side of your head.","Crunch sideways, bringing your elbow toward your hip.","Pause and squeeze your side.","Return slowly, then switch sides after your reps."],"img":"opengym/6693.webp","gif":null,"ext":1},{"id":"6698","n":"weight plate standing biceps curl","bp":"upper arms","eq":"weight plate","tg":"biceps","mg":"brachialis","sm":["brachialis","forearms","grip muscles"],"st":["Stand tall holding a plate at its sides with both hands, arms down.","Keep your elbows tucked against your ribs.","Curl the plate up toward your chest.","Squeeze your biceps at the top.","Lower the plate slowly to full arm extension."],"img":"opengym/6698.webp","gif":null,"ext":1},{"id":"6705","n":"supine windshield wipers","bp":"waist","eq":"body weight","tg":"obliques","mg":"abdominals","sm":["abdominals","hip flexors","lower back"],"st":["Lie on your back with arms out to the sides, palms down.","Lift your legs straight up over your hips.","Lower both legs to one side without touching the floor.","Bring them back up through the middle.","Lower to the other side and keep alternating."],"img":"opengym/6705.webp","gif":null,"ext":1},{"id":"6733","n":"lever good morning on the hack squat machine","bp":"upper legs","eq":"leverage machine","tg":"hamstrings","mg":"glutes","sm":["glutes","lower back"],"st":["Set up under the shoulder pads with feet shoulder-width apart.","Unlock the machine and stand tall.","Push your hips back and lean your torso forward with a flat back.","Lower until you feel a hamstring stretch.","Drive your hips forward to stand.","Keep your knees slightly bent throughout."],"img":"opengym/6733.webp","gif":null,"ext":1},{"id":"6734","n":"sled angled single leg press","bp":"upper legs","eq":"sled machine","tg":"quads","mg":"glutes","sm":["glutes","hamstrings"],"st":["Sit in the angled sled and place one foot in the middle of the platform.","Release the safety and lower the sled by bending the knee.","Go as deep as you can with your back against the pad.","Press through your heel to straighten the leg without locking out.","Keep your hips flat on the seat.","Finish the reps and switch legs."],"img":"opengym/6734.webp","gif":null,"ext":1},{"id":"6735","n":"dumbbell banded hip thrust","bp":"upper legs","eq":"dumbbell","tg":"glutes","mg":"hamstrings","sm":["hamstrings","core"],"st":["Put a band around your thighs and rest your upper back on a bench.","Place a dumbbell across your hips and hold it steady.","Plant your feet and push your knees out against the band.","Drive your hips up until your torso is level.","Squeeze the glutes at the top.","Lower slowly."],"img":"opengym/6735.webp","gif":null,"ext":1},{"id":"6737","n":"resistance band side plank glute raise","bp":"waist","eq":"band","tg":"abductors","mg":"obliques","sm":["obliques","glutes","core"],"st":["Put a band around your thighs or ankles and get into a side plank on your forearm.","Lift your hips so your body forms a straight line.","Raise the top leg up against the band.","Pause briefly.","Lower the leg with control.","Finish the reps, then switch sides."],"img":"opengym/6737.webp","gif":null,"ext":1},{"id":"6738","n":"resistance band reverse hyper with stability ball on flat bench","bp":"upper legs","eq":"band","tg":"glutes","mg":"hamstrings","sm":["hamstrings","lower back"],"st":["Lie face down with your hips over a stability ball on a flat bench.","Loop a band around your feet and anchor it low in front.","Hold the bench for stability.","Raise both legs until they are in line with your body.","Squeeze your glutes at the top.","Lower slowly against the band."],"img":"opengym/6738.webp","gif":null,"ext":1},{"id":"6739","n":"cable kneeling hip abduction","bp":"upper legs","eq":"cable","tg":"abductors","mg":"glutes","sm":["glutes","core"],"st":["Attach an ankle cuff to a low pulley and put it on one ankle.","Kneel on all fours with the cuffed leg on the outside.","Keep your back flat and hips square.","Lift the knee out to the side against the cable.","Pause briefly at the top.","Lower with control, then switch legs after your reps."],"img":"opengym/6739.webp","gif":null,"ext":1},{"id":"6741","n":"resistance band kneeling leg half circle on bench","bp":"upper legs","eq":"band","tg":"glutes","mg":"hamstrings","sm":["hamstrings","core"],"st":["Place a band around your thighs or ankles and kneel on a bench with hands on its edge.","Keep your back flat and hips level.","Lift one leg out behind you.","Sweep it in a half circle out to the side.","Return along the same path under control.","Finish the reps, then switch legs."],"img":"opengym/6741.webp","gif":null,"ext":1},{"id":"6742","n":"cable donkey diagonal kickback","bp":"upper legs","eq":"cable","tg":"glutes","mg":"hamstrings","sm":["hamstrings","core"],"st":["Attach an ankle cuff to a low pulley and put it on one ankle.","Get on all fours facing the machine.","Keep your core braced and back flat.","Kick the leg back and slightly out on a diagonal.","Squeeze your glute at the top.","Return slowly, then switch legs after your reps."],"img":"opengym/6742.webp","gif":null,"ext":1},{"id":"6744","n":"resistance band side walk squat","bp":"upper legs","eq":"band","tg":"abductors","mg":"glutes","sm":["glutes","quadriceps"],"st":["Put a band around your thighs or just above the knees.","Drop into a quarter squat with chest up.","Step sideways, keeping tension on the band.","Bring the trailing foot in without letting the feet touch.","Take several steps one way, then return the other way.","Keep your knees pushed out."],"img":"opengym/6744.webp","gif":null,"ext":1},{"id":"6745","n":"cable seated foot eversion","bp":"lower legs","eq":"cable","tg":"calves","mg":"ankles","sm":["ankles","feet","shins"],"st":["Sit with your leg extended and a cable cuff on your foot.","Position the cable so it pulls the foot inward.","Keep your leg still.","Turn the sole of your foot outward against the cable.","Pause, then return slowly.","Finish the reps and switch feet."],"img":"opengym/6745.webp","gif":null,"ext":1},{"id":"6746","n":"cable seated foot inversion","bp":"lower legs","eq":"cable","tg":"calves","mg":"ankles","sm":["ankles","feet","shins"],"st":["Sit with your leg extended and a cable cuff on your foot.","Position the cable so it pulls the foot outward.","Keep your leg still.","Turn the sole of your foot inward against the cable.","Pause, then return slowly.","Finish the reps and switch feet."],"img":"opengym/6746.webp","gif":null,"ext":1},{"id":"6747","n":"kneeling glute press","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"hamstrings","sm":["hamstrings","core"],"st":["Get on all fours with hands under shoulders and knees under hips.","Brace your core and keep your back flat.","Press one foot back and up, leading with the heel.","Squeeze the glute at the top without arching your back.","Lower with control.","Finish the reps, then switch legs."],"img":"opengym/6747.webp","gif":null,"ext":1},{"id":"6748","n":"kneeling single hamstring curl","bp":"upper legs","eq":"body weight","tg":"hamstrings","mg":"glutes","sm":["glutes","calves"],"st":["Get on all fours with hands under shoulders.","Keep your back flat and core tight.","Bend one knee and curl your heel toward your glute.","Squeeze the hamstring at the top.","Lower the foot slowly.","Finish the reps, then switch legs."],"img":"opengym/6748.webp","gif":null,"ext":1},{"id":"6749","n":"seated hip external rotation","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"hip flexors","sm":["hip flexors"],"st":["Sit tall on a bench or chair with feet flat.","Lift one foot slightly off the floor.","Keep your knee still and rotate the lower leg inward so the thigh turns outward.","Pause when you feel the hip working.","Return slowly.","Finish the reps, then switch legs."],"img":"opengym/6749.webp","gif":null,"ext":1},{"id":"6750","n":"standing balance hip rotation","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"core","sm":["core","ankles"],"st":["Stand tall on one leg with a soft knee, holding a wall if needed.","Lift the other knee to hip height.","Rotate the lifted knee out to the side, then back to the front.","Keep your torso steady.","Move slowly and smoothly.","Finish the reps, then switch legs."],"img":"opengym/6750.webp","gif":null,"ext":1},{"id":"6751","n":"side lying diagonal backward leg raise","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"hamstrings","sm":["hamstrings","core"],"st":["Lie on your side with legs stacked and your bottom arm supporting your head.","Brace your core and keep your hips stacked.","Lift the top leg up and slightly back on a diagonal.","Squeeze your glute at the top.","Lower slowly.","Finish the reps, then switch sides."],"img":"opengym/6751.webp","gif":null,"ext":1},{"id":"6752","n":"lying rectus abdominis activation crunch","bp":"waist","eq":"body weight","tg":"abs","mg":"obliques","sm":["obliques","hip flexors"],"st":["Lie on your back with knees bent and feet flat.","Place your hands lightly on your abs or behind your head.","Exhale and curl your shoulders off the floor.","Feel the abs tighten at the top.","Lower back slowly.","Keep your neck relaxed."],"img":"opengym/6752.webp","gif":null,"ext":1},{"id":"6753","n":"lying scalene muscles activation","bp":"neck","eq":"body weight","tg":"levator scapulae","mg":"sternocleidomastoid","sm":["sternocleidomastoid","upper back"],"st":["Lie on your back with your head resting on the floor.","Relax your shoulders away from your ears.","Gently tilt your head to one side without lifting your shoulder.","Feel a light engagement along the side of your neck.","Return to the middle slowly.","Alternate sides for several reps."],"img":"opengym/6753.webp","gif":null,"ext":1},{"id":"6754","n":"bodyweight lying shoulder external rotation","bp":"shoulders","eq":"body weight","tg":"delts","mg":"rotator cuff","sm":["rotator cuff","rear deltoids"],"st":["Lie on your side with your elbow bent 90 degrees and tucked at your waist.","Rest your forearm across your stomach.","Rotate your forearm upward, keeping the elbow in.","Pause at the top.","Lower slowly.","Finish the reps, then switch sides."],"img":"opengym/6754.webp","gif":null,"ext":1},{"id":"6755","n":"cable kneeling shoulder external rotation","bp":"shoulders","eq":"cable","tg":"delts","mg":"rotator cuff","sm":["rotator cuff","rear deltoids"],"st":["Kneel side-on to a low cable and hold the handle with the far hand.","Tuck your elbow at your side, bent to 90 degrees.","Rotate your forearm outward, away from your belly.","Pause briefly at the end.","Return slowly and switch arms after your reps."],"img":"opengym/6755.webp","gif":null,"ext":1},{"id":"6756","n":"cable kneeling shoulder internal rotation","bp":"shoulders","eq":"cable","tg":"delts","mg":"rotator cuff","sm":["rotator cuff","chest"],"st":["Kneel side-on to a low cable and hold the handle with the near hand.","Tuck your elbow at your side, bent to 90 degrees.","Rotate your forearm inward across your belly.","Pause briefly at the end.","Return slowly and switch arms after your reps."],"img":"opengym/6756.webp","gif":null,"ext":1},{"id":"6757","n":"dumbbell standing single arm biceps curl","bp":"upper arms","eq":"dumbbell","tg":"biceps","mg":"brachialis","sm":["brachialis","forearms"],"st":["Stand tall holding a dumbbell at your side, palm facing forward.","Keep your elbow tucked at your side.","Curl the weight up toward your shoulder.","Squeeze your biceps at the top.","Lower slowly until the arm is straight.","Finish the reps, then switch arms."],"img":"opengym/6757.webp","gif":null,"ext":1},{"id":"6758","n":"dumbbell over the bench supination","bp":"lower arms","eq":"dumbbell","tg":"forearms","mg":"wrist flexors","sm":["wrist flexors","biceps"],"st":["Sit by a bench and rest your forearm on it with your hand past the edge.","Hold a dumbbell with a hammer grip.","Keep your forearm still.","Rotate your palm up as far as you can.","Return slowly to the start.","Finish the reps, then switch arms."],"img":"opengym/6758.webp","gif":null,"ext":1},{"id":"6759","n":"seated tibialis anterior press","bp":"lower legs","eq":"body weight","tg":"shins","mg":"calves","sm":["calves","ankles","feet"],"st":["Sit tall with your heels on the floor.","Lift the toes of one foot as high as you can.","Press them up against light resistance such as the other foot.","Pause at the top.","Lower slowly.","Finish the reps, then switch feet."],"img":"opengym/6759.webp","gif":null,"ext":1},{"id":"6760","n":"cable kneeling twist","bp":"waist","eq":"cable","tg":"obliques","mg":"core","sm":["core","shoulders"],"st":["Set a cable at chest height and kneel sideways to it.","Hold the handle with both hands in front of your chest.","Brace your abs and keep your hips square.","Rotate your torso away from the machine.","Return slowly under control.","Finish the reps, then switch sides."],"img":"opengym/6760.webp","gif":null,"ext":1},{"id":"6761","n":"half pigeon hip stretch","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"hip flexors","sm":["hip flexors","adductors","lower back"],"st":["Start on all fours and bring one knee forward behind your wrist.","Slide the other leg straight back.","Square your hips to the floor.","Fold forward gently over the front leg.","Hold for 20-30 seconds, breathing calmly.","Switch sides."],"img":"opengym/6761.webp","gif":null,"ext":1},{"id":"6762","n":"diagonal bend hold","bp":"back","eq":"body weight","tg":"spine","mg":"obliques","sm":["obliques","lats","hamstrings"],"st":["Stand with feet wider than your hips.","Reach one arm overhead and toward the opposite foot.","Bend diagonally, keeping your hips facing forward.","Reach only as far as is comfortable.","Hold for 20-30 seconds, breathing calmly.","Return to standing and switch sides."],"img":"opengym/6762.webp","gif":null,"ext":1},{"id":"6763","n":"seated forearms stretch","bp":"lower arms","eq":"body weight","tg":"forearms","mg":"wrist flexors","sm":["wrist flexors","wrist extensors"],"st":["Sit tall and extend one arm in front of you, palm up.","With the other hand, gently pull the fingers back toward you.","Keep the elbow straight and shoulders relaxed.","Hold for 20-30 seconds.","Turn the palm down to stretch the other side, then switch arms."],"img":"opengym/6763.webp","gif":null,"ext":1},{"id":"6764","n":"forward bend back stretch","bp":"back","eq":"body weight","tg":"spine","mg":"hamstrings","sm":["hamstrings","glutes"],"st":["Stand with feet hip-width apart.","Hinge forward at the hips with soft knees.","Let your arms and head hang down.","Relax your neck and shoulders.","Hold for 20-30 seconds, breathing calmly.","Roll up slowly to stand."],"img":"opengym/6764.webp","gif":null,"ext":1},{"id":"6765","n":"neck stretch with hand assisted","bp":"neck","eq":"body weight","tg":"levator scapulae","mg":"sternocleidomastoid","sm":["sternocleidomastoid","trapezius"],"st":["Sit or stand tall with your shoulders relaxed.","Place one hand on the side of your head.","Gently tilt your head toward the shoulder, using light pressure.","Keep the opposite shoulder down.","Hold for 20-30 seconds, breathing calmly.","Release slowly and switch sides."],"img":"opengym/6765.webp","gif":null,"ext":1},{"id":"6766","n":"roll ball posterior tibialis (single leg) side lying on floor","bp":"lower legs","eq":"massage ball","tg":"calves","mg":"soleus","sm":["soleus","shins","ankles"],"st":["Lie on your side with a small ball under the inside of your lower leg.","Support yourself with your hands and the other leg.","Slowly roll the leg along the ball from calf toward ankle.","Pause on tender spots with light pressure.","Breathe and relax the leg.","Roll for 30-60 seconds, then switch legs."],"img":"opengym/6766.webp","gif":null,"ext":1},{"id":"6767","n":"roll ball side lying scalene muscles activation","bp":"neck","eq":"massage ball","tg":"levator scapulae","mg":"sternocleidomastoid","sm":["sternocleidomastoid","trapezius"],"st":["Lie on your side with a small ball under the side of your neck.","Support your head with a pillow or your hand.","Relax your shoulder.","Gently press or nod to roll over the ball.","Keep the pressure light.","Do 30-60 seconds, then switch sides."],"img":"opengym/6767.webp","gif":null,"ext":1},{"id":"6768","n":"roll ball side lying scalene muscles activation (side pov)","bp":"neck","eq":"massage ball","tg":"levator scapulae","mg":"sternocleidomastoid","sm":["sternocleidomastoid","trapezius"],"st":["Lie on your side with a small ball under the side of your neck.","Support your head so your neck stays neutral.","Relax your shoulder.","Gently move your head to roll over the ball.","Keep the pressure light.","Do 30-60 seconds, then switch sides."],"img":"opengym/6768.webp","gif":null,"ext":1},{"id":"6769","n":"roll ball lying semispinalis capitis muscle activation","bp":"neck","eq":"massage ball","tg":"levator scapulae","mg":"upper back","sm":["upper back","trapezius"],"st":["Lie on your back with knees bent and a small ball under the base of your skull.","Relax your head onto the ball.","Make small nods or turns to roll over the muscle.","Keep the pressure gentle.","Breathe slowly.","Continue for 30-60 seconds."],"img":"opengym/6769.webp","gif":null,"ext":1},{"id":"6770","n":"kneeling sartorius stretch","bp":"upper legs","eq":"body weight","tg":"quads","mg":"hip flexors","sm":["hip flexors","adductors"],"st":["Kneel on one knee in a half-kneeling position.","Tuck your pelvis and squeeze the glute of the back leg.","Shift your hips forward slightly.","Lean slightly to the side of the back leg.","Hold for 20-30 seconds, breathing calmly.","Switch legs."],"img":"opengym/6770.webp","gif":null,"ext":1},{"id":"6771","n":"kneeling iliopsoas stretch","bp":"upper legs","eq":"body weight","tg":"hip flexors","mg":"quadriceps","sm":["quadriceps","core"],"st":["Kneel on one knee with the other foot forward.","Tuck your pelvis and brace your abs.","Shift your weight forward until you feel the stretch at the front of the hip.","Raise the arm on the kneeling side overhead.","Hold for 20-30 seconds, breathing calmly.","Switch legs."],"img":"opengym/6771.webp","gif":null,"ext":1},{"id":"6772","n":"standing peroneus muscles stretch","bp":"lower legs","eq":"body weight","tg":"calves","mg":"ankles","sm":["ankles","feet"],"st":["Stand near a wall for balance.","Cross one foot behind and turn the sole so the outer edge presses into the floor.","Gently shift your weight onto that foot.","Feel the stretch along the outside of the lower leg.","Hold for 20-30 seconds, breathing calmly.","Switch feet."],"img":"opengym/6772.webp","gif":null,"ext":1},{"id":"6773","n":"standing tibialis anterior stretch","bp":"lower legs","eq":"body weight","tg":"shins","mg":"calves","sm":["calves","ankles","feet"],"st":["Stand near a wall for balance.","Place the top of one foot on the floor behind you with toes curled under.","Gently bend the standing knee to press forward.","Feel the stretch along the shin.","Hold for 20-30 seconds, breathing calmly.","Switch feet."],"img":"opengym/6773.webp","gif":null,"ext":1},{"id":"6774","n":"seated rhomboid stretch","bp":"back","eq":"body weight","tg":"upper back","mg":"rhomboids","sm":["rhomboids","trapezius","rear deltoids"],"st":["Sit tall and clasp your hands in front of your chest.","Push your arms forward and round your upper back.","Tuck your chin slightly and spread the shoulder blades apart.","Hold for 20-30 seconds while breathing steadily.","Release slowly and repeat."],"img":"opengym/6774.webp","gif":null,"ext":1},{"id":"6775","n":"standing foot muscles activation","bp":"lower legs","eq":"body weight","tg":"calves","mg":"feet","sm":["feet","ankles","shins"],"st":["Stand tall with feet hip-width apart.","Spread your toes wide and press all of them into the floor.","Lift your toes while keeping the ball of the foot down.","Lower them one by one.","Keep your arch lifted.","Repeat for 10-15 slow reps."],"img":"opengym/6775.webp","gif":null,"ext":1},{"id":"6776","n":"cable standing single delt row","bp":"shoulders","eq":"cable","tg":"delts","mg":"rear deltoids","sm":["rear deltoids","upper back","biceps","rhomboids"],"st":["Set a cable at chest height and grab the handle with one hand.","Stand with feet staggered and your torso slightly braced.","Pull the handle toward you with your elbow flared out.","Squeeze the rear shoulder at the end.","Extend slowly, then switch arms after your reps."],"img":"opengym/6776.webp","gif":null,"ext":1},{"id":"6785","n":"band seated hip abduction v. 2","bp":"upper legs","eq":"resistance band","tg":"abductors","mg":"glutes","sm":["glutes","hip flexors"],"st":["Sit tall on a bench with a band around your thighs above the knees.","Keep your feet flat and planted.","Press your knees apart against the band.","Hold for a second at the widest point.","Bring the knees back together slowly."],"img":"opengym/6785.webp","gif":null,"ext":1},{"id":"6786","n":"faber test","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"hip flexors","sm":["hip flexors","adductors","groin"],"st":["Lie on your back with legs straight.","Place one foot on the opposite knee.","Let the bent knee drop out to the side.","Relax and notice how far it goes.","Hold for 20-30 seconds without forcing it.","Switch legs."],"img":"opengym/6786.webp","gif":null,"ext":1},{"id":"6787","n":"hip external rotation test","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"hip flexors","sm":["hip flexors"],"st":["Sit or lie with the knee bent 90 degrees.","Keep the thigh still.","Swing the lower leg inward so the hip rotates outward.","Stop where you feel a stretch or end of range.","Note how far each side goes.","Repeat on the other leg."],"img":"opengym/6787.webp","gif":null,"ext":1},{"id":"6788","n":"hip internal rotation test","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"adductors","sm":["adductors","hip flexors"],"st":["Sit or lie with the knee bent 90 degrees.","Keep the thigh still.","Swing the lower leg outward so the hip rotates inward.","Stop where you feel a stretch or end of range.","Note how far each side goes.","Repeat on the other leg."],"img":"opengym/6788.webp","gif":null,"ext":1},{"id":"6789","n":"leg length test","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"hip flexors","sm":["hip flexors","lower back"],"st":["Lie flat on your back with legs straight and feet together.","Relax your hips and arms.","Compare the position of your heels or ankles.","Bend your knees and lift your hips, then lower and straighten again.","Check again for any difference.","Stay relaxed throughout."],"img":"opengym/6789.webp","gif":null,"ext":1},{"id":"6790","n":"shoulder external rotation test","bp":"shoulders","eq":"body weight","tg":"delts","mg":"rotator cuff","sm":["rotator cuff","upper back"],"st":["Stand or lie with your elbow bent 90 degrees and tucked at your side.","Keep your elbow against your body.","Rotate your forearm outward slowly.","Stop where you feel a stretch or end of range.","Note how far each side goes.","Repeat on the other arm."],"img":"opengym/6790.webp","gif":null,"ext":1},{"id":"6791","n":"shoulder internal rotation test","bp":"shoulders","eq":"body weight","tg":"delts","mg":"rotator cuff","sm":["rotator cuff","upper back"],"st":["Stand tall with your feet hip-width apart.","Reach one arm behind your back with the palm facing out.","Slide your hand slowly up your spine as far as is comfortable.","Note how high your thumb reaches, keeping your chest open.","Lower the arm, then repeat with the other side to compare."],"img":"opengym/6791.webp","gif":null,"ext":1},{"id":"6792","n":"shoulder level test","bp":"shoulders","eq":"body weight","tg":"delts","mg":"trapezius","sm":["trapezius","upper back"],"st":["Stand relaxed with your feet hip-width apart and arms hanging loose.","Look straight ahead and let your shoulders settle naturally.","Check in a mirror, or ask a friend, whether both shoulders are at the same height.","Roll the shoulders once and re-check without shrugging.","Note any difference and repeat now and then to track it."],"img":"opengym/6792.webp","gif":null,"ext":1},{"id":"6793","n":"posterior chain flexibility test","bp":"upper legs","eq":"body weight","tg":"hamstrings","mg":"lower back","sm":["lower back","calves","glutes"],"st":["Stand with your feet together and your knees straight.","Hinge at the hips and slowly reach down toward your toes.","Let your head and arms hang relaxed without bouncing.","Note how far your fingertips reach.","Hold for 20-30 seconds, breathing calmly.","Rise slowly, rolling up one vertebra at a time."],"img":"opengym/6793.webp","gif":null,"ext":1},{"id":"6794","n":"thomas test","bp":"upper legs","eq":"body weight","tg":"quads","mg":"hip flexors","sm":["hip flexors","groin"],"st":["Sit at the end of a bench, then lie back and hug one knee to your chest.","Let the other leg hang off the edge with the thigh relaxed.","Keep your lower back flat on the bench.","Notice whether the hanging thigh rises above the bench or the knee straightens.","Hold for 20-30 seconds, breathing calmly.","Switch legs and compare."],"img":"opengym/6794.webp","gif":null,"ext":1},{"id":"6795","n":"thomas frontal test","bp":"upper legs","eq":"body weight","tg":"quads","mg":"hip flexors","sm":["hip flexors","adductors"],"st":["Sit at the end of a bench and lie back, pulling one knee to your chest.","Let the other leg hang down off the edge, fully relaxed.","Keep your lower back pressed down and your pelvis still.","Watch whether the hanging leg drifts outward or the thigh lifts.","Hold for 20-30 seconds, breathing calmly.","Switch legs and compare."],"img":"opengym/6795.webp","gif":null,"ext":1},{"id":"6796","n":"smith sumo chair squat","bp":"upper legs","eq":"smith machine","tg":"glutes","mg":"quadriceps","sm":["quadriceps","adductors","hamstrings"],"st":["Place a chair behind you and set the bar on your upper back.","Take a wide stance with toes turned out.","Sit back and down until you lightly touch the chair.","Keep your knees tracking over your toes.","Drive through your heels to stand up."],"img":"opengym/6796.webp","gif":null,"ext":1},{"id":"6797","n":"barbell bench lateral step up","bp":"upper legs","eq":"barbell","tg":"glutes","mg":"quadriceps","sm":["quadriceps","adductors","hamstrings","calves"],"st":["Place the bar on your upper back and stand beside a bench.","Put the inside foot flat on the bench.","Press through that heel and stand up on the bench.","Lower the other foot back down under control.","Complete your reps, then switch sides."],"img":"opengym/6797.webp","gif":null,"ext":1},{"id":"6798","n":"resistance band standing balance glute kickback","bp":"upper legs","eq":"resistance band","tg":"glutes","mg":"hamstrings","sm":["hamstrings","core","lower back"],"st":["Loop the band around your ankles or hold it under your standing foot.","Stand on one leg with a slight bend in the knee and brace your abs.","Kick the other leg straight back against the band.","Squeeze your glute at the top without arching your lower back.","Return slowly with control.","Finish all reps, then switch sides."],"img":"opengym/6798.webp","gif":null,"ext":1},{"id":"6799","n":"dumbbell lying oblique v up","bp":"waist","eq":"dumbbell","tg":"obliques","mg":"hip flexors","sm":["hip flexors","core"],"st":["Lie on your back holding a dumbbell with both hands overhead.","Lift your legs and torso together, angling toward one side.","Reach the dumbbell toward your feet.","Lower back down slowly.","Alternate sides each rep."],"img":"opengym/6799.webp","gif":null,"ext":1},{"id":"6800","n":"dumbbell military press russian twist with legs floor off","bp":"waist","eq":"dumbbell","tg":"obliques","mg":"abdominals","sm":["abdominals","shoulders","triceps","hip flexors"],"st":["Sit leaning back slightly with knees bent and feet off the floor.","Hold dumbbells at your shoulders.","Press both dumbbells overhead.","Lower them, then twist your torso to one side.","Twist to the other side and repeat the sequence."],"img":"opengym/6800.webp","gif":null,"ext":1},{"id":"6801","n":"dumbbell seated military press in out leg raise on floor","bp":"waist","eq":"dumbbell","tg":"abs","mg":"shoulders","sm":["shoulders","triceps","hip flexors","lower abs"],"st":["Sit on the floor leaning back slightly, dumbbells at your shoulders.","Press the dumbbells overhead.","Pull your knees in, then extend the legs out as the weights stay up.","Lower the dumbbells to your shoulders.","Repeat, keeping your back long and core braced."],"img":"opengym/6801.webp","gif":null,"ext":1},{"id":"6802","n":"dumbbell seated military hold alternate leg raise on floor","bp":"waist","eq":"dumbbell","tg":"abs","mg":"shoulders","sm":["shoulders","hip flexors","lower abs","triceps"],"st":["Sit on the floor leaning back a little and press the dumbbells overhead.","Keep your arms locked and steady.","Raise one leg off the floor.","Lower it and raise the other leg.","Keep alternating, then lower the weights."],"img":"opengym/6802.webp","gif":null,"ext":1},{"id":"6803","n":"side and front in out","bp":"waist","eq":"body weight","tg":"abs","mg":"obliques","sm":["obliques","hip flexors","core"],"st":["Sit on the floor leaning back, hands behind you for support.","Lift your feet off the floor with knees bent.","Extend your legs out to one side and pull them back in.","Extend them straight in front and pull back in.","Repeat the pattern on the other side."],"img":"opengym/6803.webp","gif":null,"ext":1},{"id":"6804","n":"plank alternate anti gravity pull up","bp":"waist","eq":"body weight","tg":"abs","mg":"shoulders","sm":["shoulders","obliques","core","lats"],"st":["Start in a forearm or high plank with your body in a straight line.","Brace your core and squeeze your glutes.","Pull one arm up and back toward your ribs.","Return it to the floor under control.","Alternate arms without rocking your hips."],"img":"opengym/6804.webp","gif":null,"ext":1},{"id":"6805","n":"dumbbell alternate v up","bp":"waist","eq":"dumbbell","tg":"abs","mg":"hip flexors","sm":["hip flexors","obliques","core"],"st":["Lie on your back with a dumbbell in each hand, arms overhead.","Lift your torso and one leg at the same time.","Reach the weights toward your raised foot.","Lower slowly to the floor.","Alternate legs each rep."],"img":"opengym/6805.webp","gif":null,"ext":1},{"id":"6806","n":"dumbbell military press russian twist with legs floor off v. 2","bp":"waist","eq":"dumbbell","tg":"obliques","mg":"abdominals","sm":["abdominals","shoulders","triceps","hip flexors"],"st":["Sit leaning back slightly with knees bent and feet off the floor.","Hold dumbbells at your shoulders.","Press both dumbbells overhead and lower them.","Twist your torso to one side, then the other.","Keep your chest tall and breathe steadily."],"img":"opengym/6806.webp","gif":null,"ext":1},{"id":"6809","n":"dumbbell overhead sit up with legs on bench","bp":"waist","eq":"dumbbell","tg":"abs","mg":"hip flexors","sm":["hip flexors","shoulders","core"],"st":["Lie on the floor with calves resting on a bench, knees bent.","Hold a dumbbell with both hands above your chest or overhead.","Curl up into a sit-up, keeping your arms extended.","Reach toward your knees at the top.","Lower back down slowly."],"img":"opengym/6809.webp","gif":null,"ext":1},{"id":"6810","n":"band lying bent knee raise","bp":"waist","eq":"band","tg":"abs","mg":"hip flexors","sm":["hip flexors","lower abs"],"st":["Lie on your back with a band looped around your feet or anchored.","Place your hands by your sides and brace your core.","Bring your knees toward your chest against the band.","Pause briefly at the top.","Lower your feet slowly without arching your back."],"img":"opengym/6810.webp","gif":null,"ext":1},{"id":"6811","n":"stick subscapularis muscle relax","bp":"upper arms","eq":"body weight","tg":"delts","mg":"rotator cuff","sm":["rotator cuff","shoulders"],"st":["Hold a stick in one hand and bend your elbow to 90 degrees.","Place the other hand on the stick and rotate the arm outward.","Gently push into a comfortable stretch.","Hold for 20-30 seconds.","Release and repeat on the other arm."],"img":"opengym/6811.webp","gif":null,"ext":1},{"id":"6812","n":"roll ball seated pectineus activation","bp":"upper legs","eq":"medicine ball","tg":"adductors","mg":"inner thighs","sm":["inner thighs","groin","hip flexors"],"st":["Sit tall on a chair with a ball between your knees.","Place your feet flat and keep your back straight.","Squeeze the ball gently with your thighs.","Hold the squeeze for 5-10 seconds.","Relax and repeat several times."],"img":"opengym/6812.webp","gif":null,"ext":1},{"id":"6813","n":"barbell bench press (side pov)","bp":"chest","eq":"barbell","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders","upper chest"],"st":["Lie on a bench with your eyes under the bar and feet planted.","Grip the bar slightly wider than shoulder width and unrack it.","Lower the bar to your mid chest with elbows at about 45 degrees.","Touch lightly and press back up over your shoulders.","Keep your shoulder blades pinched throughout."],"img":"opengym/6813.webp","gif":null,"ext":1},{"id":"6820","n":"kettlebell incline fly","bp":"chest","eq":"kettlebell","tg":"pectorals","mg":"upper chest","sm":["upper chest","shoulders","biceps"],"st":["Lie on an incline bench holding a kettlebell in each hand above your chest.","Keep a soft bend in the elbows.","Open your arms wide in an arc until you feel a chest stretch.","Squeeze the chest to bring the weights back together.","Control the weights and keep your wrists stable."],"img":"opengym/6820.webp","gif":null,"ext":1},{"id":"6833","n":"kettlebell seated lateral raise","bp":"shoulders","eq":"kettlebell","tg":"delts","mg":"trapezius","sm":["trapezius","rotator cuff"],"st":["Sit upright on a bench holding a kettlebell in each hand at your sides.","Keep a slight bend in your elbows.","Raise your arms out to the sides to shoulder height.","Pause at the top.","Lower slowly without swinging."],"img":"opengym/6833.webp","gif":null,"ext":1},{"id":"6878","n":"sitting yoga pose siddhasana","bp":"upper legs","eq":"body weight","tg":"adductors","mg":"hip flexors","sm":["hip flexors","lower back","core"],"st":["Sit on the floor and bend your knees.","Place one heel against your inner thigh and the other foot in front of it.","Rest your hands on your knees and lengthen your spine.","Relax your shoulders and look straight ahead.","Hold for 30-60 seconds, breathing slowly.","Switch the cross of your legs and repeat."],"img":"opengym/6878.webp","gif":null,"ext":1},{"id":"6879","n":"supported headstand yoga pose sirsasana","bp":"shoulders","eq":"body weight","tg":"delts","mg":"core","sm":["core","upper back","trapezius","rotator cuff"],"st":["Kneel and place your forearms on the mat with your fingers interlaced.","Set the crown of your head lightly on the floor against your hands.","Lift your knees and walk your feet toward your face.","Lift your legs slowly, using your core, until they point to the ceiling.","Keep most of the weight in your forearms and shoulders.","Hold briefly, then lower with control and rest in child's pose."],"img":"opengym/6879.webp","gif":null,"ext":1},{"id":"6880","n":"forearms stand yoga pose pincha mayurasana","bp":"shoulders","eq":"body weight","tg":"delts","mg":"core","sm":["core","upper back","lats","triceps"],"st":["Start on your forearms and knees with your elbows under your shoulders.","Press your forearms into the floor and tuck your toes.","Lift your hips high and walk your feet toward your elbows.","Swing or float one leg up, then bring the other to meet it.","Keep your ribs in and your gaze between your hands.","Hold briefly, then lower with control."],"img":"opengym/6880.webp","gif":null,"ext":1},{"id":"6881","n":"lever cross lat pulldown","bp":"back","eq":"leverage machine","tg":"lats","mg":"biceps","sm":["biceps","rhomboids","upper back"],"st":["Adjust the seat and thigh pad, then grab the handles.","Sit tall with your chest up.","Pull the handles down and across toward your torso.","Squeeze your lats at the bottom.","Return slowly to a full stretch."],"img":"opengym/6881.webp","gif":null,"ext":1},{"id":"6890","n":"dumbbell z press v. 2","bp":"shoulders","eq":"dumbbell","tg":"delts","mg":"triceps","sm":["triceps","core","upper chest"],"st":["Sit on the floor with legs extended and dumbbells at your shoulders.","Brace your core and keep your back tall.","Press both dumbbells overhead until your arms are straight.","Lower them to your shoulders under control.","Avoid leaning back during the press."],"img":"opengym/6890.webp","gif":null,"ext":1},{"id":"6891","n":"dumbbell alternate z press","bp":"shoulders","eq":"dumbbell","tg":"delts","mg":"triceps","sm":["triceps","core","obliques"],"st":["Sit on the floor with legs extended, dumbbells at your shoulders.","Brace your core and sit tall.","Press one dumbbell overhead.","Lower it and press the other arm.","Keep alternating without tilting your torso."],"img":"opengym/6891.webp","gif":null,"ext":1},{"id":"6901","n":"cow yoga pose bitilasana","bp":"back","eq":"body weight","tg":"spine","mg":"core","sm":["core","chest","hip flexors"],"st":["Start on hands and knees, with wrists under shoulders and knees under hips.","Inhale and let your belly drop toward the floor.","Lift your chest and tailbone while your gaze goes slightly forward.","Keep your shoulders away from your ears.","Hold for 3-5 breaths.","Return to a neutral spine."],"img":"opengym/6901.webp","gif":null,"ext":1},{"id":"6902","n":"cow face yoga pose gomukhasana","bp":"shoulders","eq":"body weight","tg":"triceps","mg":"shoulders","sm":["shoulders","glutes","chest","hip flexors"],"st":["Sit with one knee stacked over the other and your feet beside your hips.","Reach one arm up and bend the elbow, hand down your back.","Sweep the other arm behind you and try to clasp your fingers.","Keep your spine tall and your chest open.","Hold for 20-30 seconds, breathing calmly.","Switch sides and repeat."],"img":"opengym/6902.webp","gif":null,"ext":1},{"id":"6910","n":"deep push up on parallel bars","bp":"chest","eq":"body weight","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders","upper chest","core"],"st":["Grip two parallel bars and hold a straight plank position.","Keep your elbows at about 45 degrees.","Lower your chest below the level of your hands.","Press back up until your arms are straight.","Keep your body in one line throughout."],"img":"opengym/6910.webp","gif":null,"ext":1},{"id":"6913","n":"sitting scapular adduction","bp":"back","eq":"body weight","tg":"upper back","mg":"rhomboids","sm":["rhomboids","trapezius","rear deltoids"],"st":["Sit tall with arms relaxed at your sides or held in front.","Keep your neck relaxed.","Pull your shoulder blades together and slightly down.","Hold the squeeze for 2-3 seconds.","Release slowly and repeat."],"img":"opengym/6913.webp","gif":null,"ext":1},{"id":"6914","n":"sitting scapular adduction v. 2","bp":"back","eq":"body weight","tg":"upper back","mg":"rhomboids","sm":["rhomboids","trapezius","rear deltoids"],"st":["Sit tall with elbows bent and hands by your ribs.","Keep your neck relaxed.","Draw your elbows back and pinch your shoulder blades together.","Hold for 2-3 seconds.","Return slowly and repeat."],"img":"opengym/6914.webp","gif":null,"ext":1},{"id":"6944","n":"swimming crawl style","bp":"full body","eq":"body weight","tg":"cardiovascular system","mg":"shoulders","sm":["shoulders","lats","core","triceps"],"st":["Stand with feet shoulder-width apart and knees slightly bent.","Swing one arm forward and over in a crawl stroke.","Alternate arms in a smooth, continuous rhythm.","Rotate your torso slightly with each stroke.","Keep going at a steady pace for 30-60 seconds."],"img":"opengym/6944.webp","gif":null,"ext":1},{"id":"6958","n":"lateral hurdle jump","bp":"upper legs","eq":"body weight","tg":"quads","mg":"glutes","sm":["glutes","calves","hamstrings","adductors"],"st":["Stand beside a low hurdle with feet together.","Swing your arms and jump sideways over it.","Land softly on both feet with knees bent.","Jump straight back over the other way.","Keep your ground contact quick and controlled."],"img":"opengym/6958.webp","gif":null,"ext":1},{"id":"6959","n":"band assisted push up","bp":"chest","eq":"band","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders","core"],"st":["Anchor a band across a rack or set of bars at chest height.","Rest your torso on the band in a plank position.","Lower your chest toward the floor, elbows at 45 degrees.","Press up using the bounce of the band as help.","Keep your body in a straight line."],"img":"opengym/6959.webp","gif":null,"ext":1},{"id":"6961","n":"uneven pull up","bp":"back","eq":"body weight","tg":"lats","mg":"biceps","sm":["biceps","upper back","forearms","core"],"st":["Hang from the bar with one hand higher or on a towel and the other lower.","Brace your core and pull your chest up.","Lead with the working arm and pull your chin toward the bar.","Lower yourself under control.","Switch the hand positions on the next set."],"img":"opengym/6961.webp","gif":null,"ext":1},{"id":"6964","n":"dumbbell standing t spine press","bp":"back","eq":"dumbbell","tg":"upper back","mg":"shoulders","sm":["shoulders","triceps","core","trapezius"],"st":["Stand with your feet hip-width apart and the dumbbells at shoulder height.","Brace your abs and lift your chest tall.","Press the dumbbells overhead while gently extending your upper back.","Keep your ribs down and avoid arching your lower back.","Lower to your shoulders with control.","Repeat for the planned reps."],"img":"opengym/6964.webp","gif":null,"ext":1},{"id":"6982","n":"wrist full push up","bp":"chest","eq":"body weight","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders","wrist extensors","core"],"st":["Start in a plank with your hands under your shoulders.","Spread your fingers and keep your wrists stacked.","Lower your chest to the floor under control.","Press back to the top.","Keep your body straight from head to heels."],"img":"opengym/6982.webp","gif":null,"ext":1},{"id":"6986","n":"downward dog push up against wall","bp":"shoulders","eq":"body weight","tg":"delts","mg":"triceps","sm":["triceps","upper chest","core"],"st":["Stand facing a wall and place your hands on it with hips back.","Lower your head toward the wall, bending the elbows.","Push explosively away from the wall.","Land softly back into the start position.","Keep your core braced and back flat."],"img":"opengym/6986.webp","gif":null,"ext":1},{"id":"7019","n":"stability ball rollout on knees","bp":"waist","eq":"stability ball","tg":"abs","mg":"lower back","sm":["lower back","shoulders","lats","core"],"st":["Kneel facing a stability ball with your forearms resting on top.","Brace your abs and keep your hips in line with your back.","Roll the ball forward, extending your body.","Stop before your lower back sags.","Pull the ball back in using your abs."],"img":"opengym/7019.webp","gif":null,"ext":1},{"id":"7054","n":"dumbbell standing hands torsion","bp":"lower arms","eq":"dumbbell","tg":"forearms","mg":"wrist flexors","sm":["wrist flexors","wrist extensors","grip muscles"],"st":["Stand holding a dumbbell by its handle in front of you.","Keep your elbows bent and close to your sides.","Rotate your forearms and wrists inward and outward.","Move slowly through the full range.","Keep your shoulders relaxed."],"img":"opengym/7054.webp","gif":null,"ext":1},{"id":"7055","n":"weight plate standing hands torsion","bp":"lower arms","eq":"weight plate","tg":"forearms","mg":"wrist flexors","sm":["wrist flexors","wrist extensors","grip muscles"],"st":["Stand holding a plate at its sides in front of you.","Keep your elbows bent and close to your sides.","Rotate the plate left and right using your wrists and forearms.","Move slowly and under control.","Keep your shoulders relaxed."],"img":"opengym/7055.webp","gif":null,"ext":1},{"id":"7056","n":"dumbbell standing reverse curl rotate","bp":"lower arms","eq":"dumbbell","tg":"forearms","mg":"brachialis","sm":["brachialis","biceps","wrist extensors"],"st":["Stand holding dumbbells with an overhand grip at your thighs.","Curl the weights up while keeping your elbows tucked.","At the top, rotate your forearms so the palms turn up.","Rotate back and lower slowly.","Keep your wrists strong and avoid swinging."],"img":"opengym/7056.webp","gif":null,"ext":1},{"id":"7107","n":"lever seated single leg press v. 2","bp":"upper legs","eq":"leverage machine","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","calves"],"st":["Sit in the machine and put one foot on the platform.","Keep your back against the pad.","Press the platform away until your leg is almost straight.","Lower slowly until your knee bends to about 90 degrees.","Finish your reps, then switch legs."],"img":"opengym/7107.webp","gif":null,"ext":1},{"id":"7108","n":"lever seated leg extension v. 3","bp":"upper legs","eq":"leverage machine","tg":"quads","mg":"quadriceps","sm":["quadriceps","hip flexors"],"st":["Sit with your back against the pad and shins behind the roller.","Align your knees with the machine pivot.","Extend your legs until they are nearly straight.","Squeeze your quads at the top.","Lower with control."],"img":"opengym/7108.webp","gif":null,"ext":1},{"id":"7113","n":"dumbbell straight arm pullover v. 2","bp":"chest","eq":"dumbbell","tg":"pectorals","mg":"lats","sm":["lats","triceps","shoulders","core"],"st":["Lie on a bench holding one dumbbell above your chest with straight arms.","Keep a slight softness in your elbows and brace your core.","Lower the weight in an arc back over your head until you feel a stretch.","Keep your ribs down and your hips on the bench.","Pull the dumbbell back over your chest.","Repeat with a smooth tempo."],"img":"opengym/7113.webp","gif":null,"ext":1},{"id":"7114","n":"ez barbell standing upright row","bp":"shoulders","eq":"ez barbell","tg":"delts","mg":"trapezius","sm":["trapezius","biceps","upper back","forearms"],"st":["Stand tall holding the EZ bar with a shoulder-width grip.","Let the bar hang in front of your thighs.","Pull it up along your body, leading with your elbows.","Stop around chest height without shrugging hard.","Lower the bar slowly to the start.","Keep your torso upright throughout."],"img":"opengym/7114.webp","gif":null,"ext":1},{"id":"7129","n":"bodyweight lying alternate legs curl","bp":"upper legs","eq":"body weight","tg":"hamstrings","mg":"glutes","sm":["glutes","calves","core"],"st":["Lie face down with your legs straight and your forehead on your hands.","Bend one knee and bring the heel toward your glute.","Squeeze the back of your thigh at the top.","Lower the leg slowly.","Repeat with the other leg.","Alternate for the planned reps."],"img":"opengym/7129.webp","gif":null,"ext":1},{"id":"7154","n":"side shuffle high knee","bp":"cardio","eq":"body weight","tg":"cardiovascular system","mg":"quadriceps","sm":["quadriceps","hip flexors","calves","glutes"],"st":["Stand with feet hip-width apart and knees slightly bent.","Shuffle sideways for a few steps.","Lift your knees high with each step.","Stay light on your feet and pump your arms.","Change direction and continue for 30-60 seconds."],"img":"opengym/7154.webp","gif":null,"ext":1},{"id":"7155","n":"cable seated reverse shrug","bp":"back","eq":"cable","tg":"traps","mg":"trapezius","sm":["trapezius","rhomboids","upper back"],"st":["Sit with a low cable behind you, holding the handle behind your back.","Keep your arms straight and chest tall.","Shrug your shoulders up and slightly back.","Hold for a second.","Lower slowly to the start."],"img":"opengym/7155.webp","gif":null,"ext":1},{"id":"7175","n":"inline skating","bp":"cardio","eq":"body weight","tg":"cardiovascular system","mg":"quadriceps","sm":["quadriceps","glutes","hamstrings","calves","core"],"st":["Put on skates, helmet and pads, and stand with your knees slightly bent.","Push one skate out to the side and glide on the other.","Alternate pushes with a relaxed arm swing.","Keep your chest up and your weight over the skates.","Skate at a steady pace for 10-30 minutes.","Slow down gradually to stop."],"img":"opengym/7175.webp","gif":null,"ext":1},{"id":"7176","n":"lever seated calf press v. 2","bp":"lower legs","eq":"leverage machine","tg":"calves","mg":"soleus","sm":["soleus","ankles","feet"],"st":["Sit in the machine and place the balls of your feet on the platform.","Extend your knees almost fully.","Press up as high as you can onto your toes.","Pause at the top.","Lower your heels slowly for a good stretch."],"img":"opengym/7176.webp","gif":null,"ext":1},{"id":"7177","n":"lever seated single calf press","bp":"lower legs","eq":"leverage machine","tg":"calves","mg":"soleus","sm":["soleus"],"st":["Sit in the machine and place the ball of one foot on the platform.","Rest the other foot on the floor or the support.","Press up through your toes as high as you can.","Pause and squeeze your calf.","Lower your heel slowly for a full stretch.","Finish all reps, then switch sides."],"img":"opengym/7177.webp","gif":null,"ext":1},{"id":"7194","n":"criss cross stepback hops","bp":"upper legs","eq":"body weight","tg":"quads","mg":"calves","sm":["calves","glutes","hamstrings","core"],"st":["Stand tall with your feet hip-width apart and your knees soft.","Hop and cross one foot in front of the other.","Hop back out, then step one foot back behind you.","Land softly on the balls of your feet each time.","Keep a quick, rhythmic pace.","Alternate sides for the planned time."],"img":"opengym/7194.webp","gif":null,"ext":1},{"id":"7198","n":"resistance band glute bridge abduction","bp":"upper legs","eq":"resistance band","tg":"glutes","mg":"hamstrings","sm":["hamstrings","core","lower back"],"st":["Lie on your back with your knees bent and the band just above your knees.","Press through your heels to lift your hips.","At the top, push your knees apart against the band.","Bring the knees back together.","Lower your hips slowly.","Repeat for the planned reps."],"img":"opengym/7198.webp","gif":null,"ext":1},{"id":"7199","n":"resistance band lying bent knee hip abduction","bp":"upper legs","eq":"resistance band","tg":"abductors","mg":"glutes","sm":["glutes","core"],"st":["Lie on your side with the band above your knees and your knees bent.","Stack your hips and rest your head on your arm.","Lift your top knee up against the band without rolling back.","Pause, then lower slowly.","Keep your feet together like a clamshell.","Finish all reps, then switch sides."],"img":"opengym/7199.webp","gif":null,"ext":1},{"id":"7200","n":"resistance band seated bent knee abduction","bp":"upper legs","eq":"resistance band","tg":"abductors","mg":"glutes","sm":["glutes","core"],"st":["Sit tall on a bench or chair with the band just above your knees.","Plant your feet flat and hip-width apart.","Press your knees out against the band.","Hold briefly at the widest point.","Bring the knees back slowly.","Keep your back straight throughout."],"img":"opengym/7200.webp","gif":null,"ext":1},{"id":"7201","n":"resistance band lying leg raise v. 2","bp":"waist","eq":"resistance band","tg":"abs","mg":"hip flexors","sm":["hip flexors","lower abs","quadriceps"],"st":["Lie on your back with the band around your feet or anchored behind your head.","Press your lower back into the floor.","Raise your legs together toward the ceiling.","Lower them slowly without arching your back.","Stop just above the floor.","Repeat for the planned reps."],"img":"opengym/7201.webp","gif":null,"ext":1},{"id":"7202","n":"resistance band side lunge","bp":"upper legs","eq":"resistance band","tg":"glutes","mg":"quadriceps","sm":["quadriceps","adductors","hamstrings","core"],"st":["Stand with the band under your feet or around your thighs, feet together.","Step wide to one side.","Sit your hips back and bend that knee, keeping the other leg straight.","Keep your chest up and your heel down.","Push back to the start.","Finish all reps, then switch sides."],"img":"opengym/7202.webp","gif":null,"ext":1},{"id":"7204","n":"resistance band standing balance glute kickback v. 2","bp":"upper legs","eq":"resistance band","tg":"glutes","mg":"hamstrings","sm":["hamstrings","core","lower back"],"st":["Place the band around your ankles and stand tall on one leg.","Hold a wall or rail for balance if needed.","Keep a slight bend in your standing knee.","Kick the other leg back, squeezing the glute.","Return slowly without leaning forward.","Finish all reps, then switch sides."],"img":"opengym/7204.webp","gif":null,"ext":1},{"id":"7205","n":"resistance band squat jump","bp":"upper legs","eq":"resistance band","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","calves","core"],"st":["Place the band above your knees and stand with feet shoulder-width.","Squat down with your chest up.","Explode upward into a jump.","Land softly, absorbing into the next squat.","Keep your knees pressing out against the band.","Repeat for the planned reps."],"img":"opengym/7205.webp","gif":null,"ext":1},{"id":"7206","n":"resistance band lateral step and squat","bp":"upper legs","eq":"resistance band","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","core"],"st":["Put the band around your thighs and stand tall.","Step one foot out to the side.","Sit down into a squat.","Stand up and bring your feet together.","Keep the knees from caving in.","Finish all reps, then switch sides."],"img":"opengym/7206.webp","gif":null,"ext":1},{"id":"7207","n":"resistance band bulgarian squat","bp":"upper legs","eq":"resistance band","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","adductors","core"],"st":["Stand in front of a bench, band under your front foot and held at your shoulders.","Rest the top of your back foot on the bench.","Lower straight down until your front thigh is parallel.","Keep your torso tall.","Press through your front heel to rise.","Finish all reps, then switch sides."],"img":"opengym/7207.webp","gif":null,"ext":1},{"id":"7208","n":"resistance band kneeling back kick","bp":"upper legs","eq":"resistance band","tg":"glutes","mg":"hamstrings","sm":["hamstrings","lower back","core"],"st":["Start on hands and knees with the band around your foot and hands.","Keep your back flat and your core braced.","Kick one leg straight back and up.","Squeeze your glute at the top.","Lower slowly.","Finish all reps, then switch sides."],"img":"opengym/7208.webp","gif":null,"ext":1},{"id":"7209","n":"resistance band kneeling leg half circle","bp":"upper legs","eq":"resistance band","tg":"glutes","mg":"hamstrings","sm":["hamstrings","core","hip flexors"],"st":["Start on hands and knees with the band around your thighs or foot.","Lift one leg out to the side with a bent knee.","Sweep it in a half circle, back and up.","Keep your hips level and your core tight.","Reverse the circle to return.","Finish all reps, then switch sides."],"img":"opengym/7209.webp","gif":null,"ext":1},{"id":"7210","n":"resistance band plank jack","bp":"waist","eq":"resistance band","tg":"abs","mg":"shoulders","sm":["shoulders","obliques","glutes","hip flexors"],"st":["Place the band above your knees and get into a high plank.","Brace your abs and keep your hips level.","Jump your feet out wide.","Jump them back together.","Keep your hands under your shoulders.","Repeat at a steady pace."],"img":"opengym/7210.webp","gif":null,"ext":1},{"id":"7211","n":"resistance band lying hyperextension abduction","bp":"upper legs","eq":"resistance band","tg":"glutes","mg":"lower back","sm":["lower back","hamstrings"],"st":["Lie face down with the band around your ankles.","Rest your forehead on your hands.","Lift both legs slightly off the floor.","Open your legs out against the band.","Bring them back together and lower slowly.","Keep the movement small and controlled."],"img":"opengym/7211.webp","gif":null,"ext":1},{"id":"7212","n":"resistance band air bike v. 2","bp":"waist","eq":"resistance band","tg":"abs","mg":"obliques","sm":["obliques","hip flexors","quadriceps"],"st":["Lie on your back, hands behind your head, band around your feet.","Lift your shoulders and bring one knee toward your chest.","Rotate your opposite elbow toward that knee.","Extend the other leg against the band.","Alternate in a pedalling motion.","Keep a steady rhythm."],"img":"opengym/7212.webp","gif":null,"ext":1},{"id":"7213","n":"side lying internal rotation","bp":"shoulders","eq":"body weight","tg":"delts","mg":"rotator cuff","sm":["rotator cuff","chest"],"st":["Lie on your side with your elbow bent to 90 degrees and tucked to your ribs.","Rest the forearm on the floor in front of you.","Rotate your forearm up toward your belly.","Lower it slowly back to the floor.","Finish your reps, then switch sides."],"img":"opengym/7213.webp","gif":null,"ext":1},{"id":"7216","n":"opposite arm and leg raise against wall","bp":"back","eq":"body weight","tg":"spine","mg":"glutes","sm":["glutes","core","shoulders","hamstrings"],"st":["Stand facing a wall in a bent over position with your hands on it.","Brace your core.","Lift one arm and the opposite leg at the same time.","Hold for a second without twisting.","Lower and repeat on the other side."],"img":"opengym/7216.webp","gif":null,"ext":1},{"id":"7217","n":"floor t raise v. 2","bp":"back","eq":"body weight","tg":"upper back","mg":"rear deltoids","sm":["rear deltoids","rhomboids","trapezius","lower back"],"st":["Lie face down with your arms out to the sides in a T.","Keep your forehead near the floor and neck neutral.","Lift your arms off the floor by pinching your shoulder blades.","Hold for a second at the top.","Lower with control."],"img":"opengym/7217.webp","gif":null,"ext":1},{"id":"7228","n":"ring wide pull up","bp":"back","eq":"suspension trainer","tg":"lats","mg":"biceps","sm":["biceps","upper back","forearms","core"],"st":["Grab the rings with a wide overhand grip and hang with arms straight.","Brace your core.","Pull your chest toward the rings, driving elbows down and out.","Pause at the top.","Lower slowly to a full hang."],"img":"opengym/7228.webp","gif":null,"ext":1},{"id":"7229","n":"kettlebell plank pass through","bp":"waist","eq":"kettlebell","tg":"abs","mg":"shoulders","sm":["shoulders","obliques","core"],"st":["Start in a high plank with a kettlebell beside one hand.","Spread your feet wide for balance.","Grab the kettlebell and slide it across under your body.","Place it down on the other side.","Keep your hips level and repeat in the other direction."],"img":"opengym/7229.webp","gif":null,"ext":1},{"id":"7230","n":"kettlebell gorilla row","bp":"back","eq":"kettlebell","tg":"upper back","mg":"lats","sm":["lats","biceps","grip muscles","core"],"st":["Place two kettlebells on the floor between your wide stance.","Hinge at the hips with a flat back and grab both handles.","Row one kettlebell to your hip while the other stays down.","Lower it and row the other side.","Keep your hips and shoulders square."],"img":"opengym/7230.webp","gif":null,"ext":1},{"id":"7231","n":"dumbbell incline single arm y raise","bp":"shoulders","eq":"dumbbell","tg":"delts","mg":"trapezius","sm":["trapezius","rear deltoids","upper back"],"st":["Lie face down on an incline bench with a dumbbell in one hand.","Let the arm hang straight down.","Raise your arm forward and up in a Y shape, thumb up.","Squeeze at the top.","Lower slowly and switch arms after your reps."],"img":"opengym/7231.webp","gif":null,"ext":1},{"id":"7232","n":"standing scapular rotation","bp":"back","eq":"body weight","tg":"upper back","mg":"trapezius","sm":["trapezius","shoulders"],"st":["Stand tall with arms relaxed at your sides.","Lift your shoulders up toward your ears.","Roll them back, then down.","Bring them forward and up again in a circle.","Reverse the direction after several reps."],"img":"opengym/7232.webp","gif":null,"ext":1},{"id":"7233","n":"standing scapular rotation (front pov)","bp":"back","eq":"body weight","tg":"upper back","mg":"trapezius","sm":["trapezius","rhomboids","rotator cuff","shoulders"],"st":["Stand tall with your arms at your sides.","Lift your shoulders gently up.","Roll them back and down in a smooth circle.","Reverse the direction.","Keep your neck relaxed.","Repeat for the planned reps."],"img":"opengym/7233.webp","gif":null,"ext":1},{"id":"7234","n":"dumbbell standing scapular external rotation","bp":"back","eq":"dumbbell","tg":"upper back","mg":"rear deltoids","sm":["rear deltoids","rotator cuff","rhomboids"],"st":["Stand tall holding a light dumbbell with your elbow bent at 90 degrees and tucked at your side.","Keep your upper arm still and your shoulder blade pulled back and down.","Rotate your forearm outward as far as you comfortably can.","Pause briefly, then slowly return to the start.","Finish all reps, then switch arms."],"img":"opengym/7234.webp","gif":null,"ext":1},{"id":"7235","n":"dumbbell standing scapular external rotation (front pov)","bp":"back","eq":"dumbbell","tg":"delts","mg":"rotator cuff","sm":["rotator cuff","rhomboids","trapezius"],"st":["Stand tall holding a light dumbbell with your elbow tucked and bent to 90 degrees.","Keep your upper arm against your side.","Rotate your forearm outward, away from your body.","Squeeze your shoulder blade back.","Return slowly.","Finish all reps, then switch sides."],"img":"opengym/7235.webp","gif":null,"ext":1},{"id":"7237","n":"barbell hook grip deadlift","bp":"upper legs","eq":"barbell","tg":"glutes","mg":"hamstrings","sm":["hamstrings","lower back","grip muscles","upper back"],"st":["Stand with the bar over mid-foot and grip it with your thumbs under your fingers.","Hinge down, brace your core and keep your back flat.","Push the floor away and stand up, keeping the bar close to your legs.","Lock out with hips and knees extended.","Lower the bar under control by hinging at the hips first."],"img":"opengym/7237.webp","gif":null,"ext":1},{"id":"7251","n":"hanging front lever raise","bp":"waist","eq":"body weight","tg":"abs","mg":"lower abs","sm":["lower abs","lats","hip flexors","grip muscles"],"st":["Hang from a pull-up bar with a firm grip.","Pull your shoulders down and tighten your core.","Raise your straight body up toward horizontal, keeping your arms straight.","Hold the top position for a moment.","Lower slowly without swinging."],"img":"opengym/7251.webp","gif":null,"ext":1},{"id":"7252","n":"dumbbell incline powell raise","bp":"shoulders","eq":"dumbbell","tg":"delts","mg":"rear deltoids","sm":["rear deltoids","rotator cuff","upper back"],"st":["Lie chest down on an incline bench holding a light dumbbell in one hand.","Let the arm hang straight below your shoulder.","Raise the dumbbell out to the side, leading with your elbow, up to shoulder height.","Pause, then lower with control.","Complete your reps and switch sides."],"img":"opengym/7252.webp","gif":null,"ext":1},{"id":"7255","n":"seated frog half to full sit up","bp":"waist","eq":"body weight","tg":"abs","mg":"hip flexors","sm":["hip flexors","lower abs","groin"],"st":["Sit on the floor with the soles of your feet together and knees dropped out.","Lower your back halfway to the floor under control.","Pause, then lower fully to lie flat.","Curl your torso back up to sitting, using your abs.","Keep your feet together and avoid yanking on your neck."],"img":"opengym/7255.webp","gif":null,"ext":1},{"id":"7263","n":"sitting uppercut on chair","bp":"waist","eq":"body weight","tg":"abs","mg":"obliques","sm":["obliques","shoulders","core"],"st":["Sit tall on the edge of a chair with your fists up by your chin.","Brace your core.","Rotate your torso and punch one fist upward in an uppercut.","Snap it back and punch with the other hand.","Keep a quick, steady rhythm for the set."],"img":"opengym/7263.webp","gif":null,"ext":1},{"id":"7274","n":"suspension trainer pike","bp":"waist","eq":"suspension trainer","tg":"abs","mg":"lower abs","sm":["lower abs","shoulders","hip flexors","core"],"st":["Place your feet in the straps and get into a plank with hands on the floor.","Keep your arms straight and body in a line.","Lift your hips toward the ceiling, pulling your feet in.","Pause at the top with legs fairly straight.","Lower back to plank with control."],"img":"opengym/7274.webp","gif":null,"ext":1},{"id":"7275","n":"suspension trainer front plank","bp":"waist","eq":"suspension trainer","tg":"abs","mg":"core","sm":["core","shoulders","glutes"],"st":["Set your feet in the straps and place your forearms or hands on the floor.","Form a straight line from head to heels.","Squeeze your glutes and brace your abs.","Hold without letting your hips sag or rise.","Keep breathing steadily for the whole hold."],"img":"opengym/7275.webp","gif":null,"ext":1},{"id":"7276","n":"bottle weighted gorilla row","bp":"back","eq":"weighted","tg":"upper back","mg":"lats","sm":["lats","biceps","rear deltoids","grip muscles"],"st":["Stand wide with a bottle on the floor between your feet and hinge forward.","Keep your back flat and grip a bottle in each hand.","Row one bottle up to your hip while the other stays down.","Lower it, then row with the other side.","Keep your hips steady and alternate sides."],"img":"opengym/7276.webp","gif":null,"ext":1},{"id":"7278","n":"suspension trainer lat stretch","bp":"back","eq":"suspension trainer","tg":"lats","mg":"shoulders","sm":["shoulders","upper back","core"],"st":["Hold the straps and lean back with straight arms.","Sit your hips back and drop your chest between your arms.","Feel the stretch along the sides of your back.","Hold for 20-30 seconds.","Return slowly to standing."],"img":"opengym/7278.webp","gif":null,"ext":1},{"id":"7279","n":"suspension trainer squat power pull","bp":"upper legs","eq":"suspension trainer","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","lats","upper back"],"st":["Hold the straps with arms extended and sink into a squat.","Keep your chest tall and knees tracking over toes.","Drive up through your legs.","As you rise, pull the straps toward your chest.","Lower your arms and sit back into the next squat."],"img":"opengym/7279.webp","gif":null,"ext":1},{"id":"7281","n":"resistance band leg kickback","bp":"upper legs","eq":"band","tg":"glutes","mg":"hamstrings","sm":["hamstrings","lower back","core"],"st":["Loop a band around your ankles or anchor it low and loop it on one foot.","Stand tall holding something for balance.","Kick the working leg straight back.","Squeeze your glute at the top without arching your back.","Return slowly, then switch legs."],"img":"opengym/7281.webp","gif":null,"ext":1},{"id":"7282","n":"resistance band walk","bp":"upper legs","eq":"band","tg":"abductors","mg":"glutes","sm":["glutes","quadriceps","calves"],"st":["Place a band around your thighs or ankles.","Sit into a slight squat with feet hip width apart.","Step sideways, keeping tension in the band.","Bring the trailing foot in without letting the band go slack.","Walk back the other way to even it out."],"img":"opengym/7282.webp","gif":null,"ext":1},{"id":"7287","n":"trap bar overhead press","bp":"shoulders","eq":"trap bar","tg":"delts","mg":"triceps","sm":["triceps","upper chest","trapezius","core"],"st":["Stand inside the trap bar and hold it at shoulder height with a neutral grip.","Brace your core and squeeze your glutes.","Press the bar overhead until your arms lock out.","Pause, then lower to your shoulders.","Keep your ribs down and avoid leaning back."],"img":"opengym/7287.webp","gif":null,"ext":1},{"id":"7294","n":"lying pelvic tilt","bp":"waist","eq":"body weight","tg":"abs","mg":"lower back","sm":["lower back","glutes","hip flexors"],"st":["Lie on your back with your knees bent and feet flat.","Take a breath in with a neutral spine.","Exhale, tilting your pelvis so your lower back presses into the floor.","Hold for a moment.","Release back to neutral.","Repeat slowly."],"img":"opengym/7294.webp","gif":null,"ext":1},{"id":"7306","n":"standing side neck stretch","bp":"neck","eq":"body weight","tg":"levator scapulae","mg":"trapezius","sm":["trapezius","sternocleidomastoid"],"st":["Stand tall with your shoulders relaxed.","Tilt your head toward one shoulder.","Rest a hand lightly on your head for slight pressure.","Keep the opposite shoulder low.","Hold for 20-30 seconds, breathing calmly.","Switch sides."],"img":"opengym/7306.webp","gif":null,"ext":1},{"id":"7310","n":"seated hamstring stretch with chair","bp":"upper legs","eq":"body weight","tg":"hamstrings","mg":"calves","sm":["calves","lower back"],"st":["Sit on the front edge of a chair.","Straighten one leg with the heel on the floor and toes up.","Keep the other foot flat and your back long.","Hinge forward at the hips until you feel a stretch.","Hold for 20-30 seconds, breathing calmly.","Switch legs."],"img":"opengym/7310.webp","gif":null,"ext":1},{"id":"7326","n":"dumbbell reverse lunge from deficit","bp":"upper legs","eq":"dumbbell","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","core"],"st":["Stand with your front foot on a low platform, holding dumbbells at your sides.","Step one foot back and lower until the back knee nearly touches the floor.","Keep your torso upright and front knee steady.","Push through the front heel to return.","Finish reps and switch legs."],"img":"opengym/7326.webp","gif":null,"ext":1},{"id":"7327","n":"lever leg extension (inward toes)","bp":"upper legs","eq":"leverage machine","tg":"quads","mg":"hip flexors","sm":["hip flexors","shins"],"st":["Sit in the machine with the pad on your lower shins.","Turn your toes slightly inward.","Extend your knees until your legs are straight.","Squeeze your quads for a second.","Lower the weight slowly."],"img":"opengym/7327.webp","gif":null,"ext":1},{"id":"7328","n":"dumbbell hyperextension","bp":"back","eq":"dumbbell","tg":"spine","mg":"glutes","sm":["glutes","hamstrings","lower back"],"st":["Set up on a hyperextension bench with the pads at your hips.","Hold a dumbbell against your chest.","Lower your torso with a flat back.","Raise up until your body forms a straight line.","Avoid overarching at the top."],"img":"opengym/7328.webp","gif":null,"ext":1},{"id":"7329","n":"dumbbell jefferson curl","bp":"back","eq":"dumbbell","tg":"spine","mg":"hamstrings","sm":["hamstrings","glutes","core"],"st":["Stand on a low step holding a light dumbbell in front of you.","Tuck your chin and slowly roll down one vertebra at a time.","Let the dumbbell hang near your shins.","Pause at the bottom, then roll up slowly.","Keep the weight light and the movement smooth."],"img":"opengym/7329.webp","gif":null,"ext":1},{"id":"7341","n":"hopping pendulum","bp":"upper legs","eq":"body weight","tg":"quads","mg":"calves","sm":["calves","glutes","core"],"st":["Stand on one leg with a slight knee bend.","Hop sideways to land on the other foot.","Swing the free leg across behind you for balance.","Land softly and stay controlled.","Keep alternating at a steady pace."],"img":"opengym/7341.webp","gif":null,"ext":1},{"id":"7342","n":"wide plank side tap","bp":"waist","eq":"body weight","tg":"abs","mg":"obliques","sm":["obliques","shoulders","core"],"st":["Start in a high plank with feet wider than your hips.","Brace your core and keep your hips level.","Lift one hand and tap your opposite hip or thigh.","Return the hand and tap with the other side.","Move slowly without rocking."],"img":"opengym/7342.webp","gif":null,"ext":1},{"id":"7374","n":"smith sumo deadlift","bp":"upper legs","eq":"smith machine","tg":"glutes","mg":"hamstrings","sm":["hamstrings","adductors","lower back","quadriceps"],"st":["Stand with feet wide, toes turned out, and grip the bar inside your knees.","Brace your core and keep your chest up.","Push your feet into the floor and stand tall.","Lock out your hips at the top.","Lower the bar by pushing your hips back."],"img":"opengym/7374.webp","gif":null,"ext":1},{"id":"7384","n":"lever hip thrust (plate loaded)","bp":"upper legs","eq":"leverage machine","tg":"glutes","mg":"hamstrings","sm":["hamstrings","quadriceps","core"],"st":["Sit with your back against the pad and belt secured over your hips.","Plant your feet flat, shoulder width apart.","Drive your hips up until your body is level.","Squeeze your glutes at the top.","Lower with control."],"img":"opengym/7384.webp","gif":null,"ext":1},{"id":"7385","n":"pull up (negative)","bp":"back","eq":"body weight","tg":"lats","mg":"biceps","sm":["biceps","upper back","forearms","grip muscles"],"st":["Jump or step up so your chin is above the bar.","Grip the bar slightly wider than your shoulders.","Lower yourself slowly over 3-5 seconds.","Stop at a full hang with straight arms.","Step back up and repeat."],"img":"opengym/7385.webp","gif":null,"ext":1},{"id":"7389","n":"wall plank","bp":"waist","eq":"body weight","tg":"abs","mg":"shoulders","sm":["shoulders","glutes","obliques"],"st":["Stand facing a wall and place your forearms or hands on it.","Walk your feet back until your body is in a slanted line.","Brace your abs and squeeze your glutes.","Keep your head neutral.","Hold for 20-40 seconds.","Step in to finish."],"img":"opengym/7389.webp","gif":null,"ext":1},{"id":"7411","n":"weighted full squat from deficit","bp":"upper legs","eq":"weighted","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","adductors","core"],"st":["Stand with your heels on a low plate or platform, holding a weight at your chest.","Brace your core and keep your chest up.","Squat as deep as comfortable.","Keep your knees tracking over your toes.","Drive up to standing."],"img":"opengym/7411.webp","gif":null,"ext":1},{"id":"7412","n":"reverse lunge high knee forward lunge","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","hip flexors","core"],"st":["Stand tall with hands on hips.","Step back into a reverse lunge.","Drive that back leg forward into a high knee.","Step the same leg forward into a forward lunge.","Push back to standing and switch legs after your reps."],"img":"opengym/7412.webp","gif":null,"ext":1},{"id":"7413","n":"elevated two legs hip thrust","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"hamstrings","sm":["hamstrings","quadriceps","core","lower back"],"st":["Sit on the floor with your upper back against a bench and knees bent.","Plant your feet hip-width apart.","Drive through your heels to lift your hips.","Squeeze your glutes at the top.","Lower slowly.","Repeat for the planned reps."],"img":"opengym/7413.webp","gif":null,"ext":1},{"id":"7414","n":"crunch against wall","bp":"waist","eq":"body weight","tg":"abs","mg":"hip flexors","sm":["hip flexors","obliques"],"st":["Lie on your back with your feet and calves resting on a wall, knees bent about 90 degrees.","Place your hands lightly behind your head.","Curl your shoulders off the floor.","Pause at the top.","Lower with control.","Repeat for the planned reps."],"img":"opengym/7414.webp","gif":null,"ext":1},{"id":"7415","n":"planche dip on parallel bars","bp":"upper arms","eq":"body weight","tg":"triceps","mg":"shoulders","sm":["shoulders","chest","core","hands"],"st":["Support yourself on parallel bars with straight arms.","Lean forward and shift your weight over your hands.","Bend your elbows to lower your body under control.","Keep your core tight and elbows close.","Press back up to straight arms."],"img":"opengym/7415.webp","gif":null,"ext":1},{"id":"7416","n":"cable standing neutral grip fly","bp":"chest","eq":"cable","tg":"pectorals","mg":"upper chest","sm":["upper chest","shoulders","biceps"],"st":["Set the pulleys at chest height and grab the handles.","Step forward with a staggered stance and a slight elbow bend.","Bring your hands together in front of your chest.","Squeeze your pecs for a moment.","Return slowly until you feel a stretch."],"img":"opengym/7416.webp","gif":null,"ext":1},{"id":"7417","n":"overhead sit up with legs on bench","bp":"waist","eq":"body weight","tg":"abs","mg":"hip flexors","sm":["hip flexors","lower abs","shoulders"],"st":["Lie on your back with your calves resting on a bench, knees bent.","Extend your arms overhead.","Curl your torso up, keeping your arms by your ears.","Reach toward your knees.","Lower slowly."],"img":"opengym/7417.webp","gif":null,"ext":1},{"id":"7418","n":"staggered leg glute bridge","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"hamstrings","sm":["hamstrings","core","lower back"],"st":["Lie on your back with your knees bent, one foot forward of the other.","Press through both heels to lift your hips.","Squeeze your glutes at the top.","Keep your hips level.","Lower slowly.","Switch the foot position halfway through."],"img":"opengym/7418.webp","gif":null,"ext":1},{"id":"7419","n":"straight leg glute bridge","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"hamstrings","sm":["hamstrings","lower back","core"],"st":["Lie on your back with your legs straight and your heels on the floor.","Press your heels down and lift your hips.","Squeeze your glutes at the top.","Keep your ribs down.","Lower slowly.","Repeat for the planned reps."],"img":"opengym/7419.webp","gif":null,"ext":1},{"id":"7449","n":"dumbbell standing front and lateral raise","bp":"shoulders","eq":"dumbbell","tg":"delts","mg":"upper chest","sm":["upper chest","trapezius","core"],"st":["Stand holding dumbbells at your sides.","Raise both arms to the front up to shoulder height.","Lower them back down.","Raise them out to your sides to shoulder height.","Lower with control and repeat."],"img":"opengym/7449.webp","gif":null,"ext":1},{"id":"7455","n":"single leg lateral hop","bp":"upper legs","eq":"body weight","tg":"quads","mg":"glutes","sm":["glutes","calves","ankles"],"st":["Stand on one leg with a slight knee bend.","Hop sideways a short distance.","Land softly on the same foot and hold your balance.","Hop back the other way.","Complete reps, then switch legs."],"img":"opengym/7455.webp","gif":null,"ext":1},{"id":"7463","n":"spider mountain climber","bp":"waist","eq":"body weight","tg":"abs","mg":"obliques","sm":["obliques","hip flexors","shoulders","core"],"st":["Start in a high plank, hands under shoulders.","Drive one knee toward the outside of your elbow.","Return that foot and switch legs.","Keep your hips low and your core braced.","Move at a quick, controlled pace."],"img":"opengym/7463.webp","gif":null,"ext":1},{"id":"7469","n":"dumbbell goblet squat with calf raise","bp":"upper legs","eq":"dumbbell","tg":"quads","mg":"glutes","sm":["glutes","calves","core"],"st":["Hold a dumbbell at your chest.","Squat down with your chest up.","Drive up to standing.","Rise onto your toes at the top.","Lower your heels and go into the next squat."],"img":"opengym/7469.webp","gif":null,"ext":1},{"id":"7499","n":"double plank jack to 4 mountain climber","bp":"full body","eq":"body weight","tg":"cardiovascular system","mg":"core","sm":["core","shoulders","hip flexors","quadriceps"],"st":["Start in a high plank.","Jump your feet wide and together twice.","Do four mountain climbers, driving your knees alternately.","Keep your hips level.","Flow through the sequence at a steady pace."],"img":"opengym/7499.webp","gif":null,"ext":1},{"id":"7512","n":"ring archer pull up","bp":"back","eq":"suspension trainer","tg":"lats","mg":"biceps","sm":["biceps","upper back","core","grip muscles"],"st":["Hang from rings with a wide grip.","Pull up toward one hand, leaving the other arm straight.","Reach the top with your chin by that hand.","Lower under control.","Alternate sides each rep."],"img":"opengym/7512.webp","gif":null,"ext":1},{"id":"7517","n":"ring one arm pull up","bp":"back","eq":"suspension trainer","tg":"lats","mg":"biceps","sm":["biceps","upper back","core","grip muscles"],"st":["Hang from one ring with a firm grip.","Brace your core and keep your legs together.","Pull your chin up toward the ring.","Lower with control to a full hang.","Complete reps, then switch arms."],"img":"opengym/7517.webp","gif":null,"ext":1},{"id":"7538","n":"lying floor slide","bp":"back","eq":"body weight","tg":"upper back","mg":"rear deltoids","sm":["rear deltoids","trapezius","shoulders"],"st":["Lie on your back with knees bent and arms in a goalpost position.","Keep your back and wrists on the floor.","Slide your arms up overhead.","Return slowly to the start.","Move within your comfortable range."],"img":"opengym/7538.webp","gif":null,"ext":1},{"id":"7543","n":"forward backward hop","bp":"lower legs","eq":"body weight","tg":"calves","mg":"quadriceps","sm":["quadriceps","glutes","core"],"st":["Stand tall with your feet together.","Hop forward a short distance on the balls of your feet.","Hop back to the start.","Land softly with your knees slightly bent.","Keep a quick tempo.","Repeat for the planned time."],"img":"opengym/7543.webp","gif":null,"ext":1},{"id":"7547","n":"dumbbell goblet sumo squat","bp":"upper legs","eq":"dumbbell","tg":"glutes","mg":"adductors","sm":["adductors","quadriceps","inner thighs","core"],"st":["Stand with feet wide and toes out, holding a dumbbell at your chest.","Keep your chest up.","Squat down between your legs.","Keep your knees pointing over your toes.","Drive up and squeeze your glutes."],"img":"opengym/7547.webp","gif":null,"ext":1},{"id":"7548","n":"kettlebell swing to goblet squat","bp":"full body","eq":"kettlebell","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","core","grip muscles"],"st":["Swing the kettlebell up to chest height from a hip hinge.","Catch it at your chest in a goblet hold.","Sit into a deep squat.","Stand up and lower the bell back between your legs.","Hinge and swing again."],"img":"opengym/7548.webp","gif":null,"ext":1},{"id":"7549","n":"dumbbell goblet bulgarian split squat","bp":"upper legs","eq":"dumbbell","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","core"],"st":["Place your rear foot on a bench and hold a dumbbell at your chest.","Step the front foot forward.","Lower your back knee toward the floor.","Keep your torso tall.","Push through the front heel and switch legs after your reps."],"img":"opengym/7549.webp","gif":null,"ext":1},{"id":"7550","n":"dumbbell bulgarian split squat from deficit","bp":"upper legs","eq":"dumbbell","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","adductors"],"st":["Stand with your front foot on a low platform and your rear foot on a bench.","Hold dumbbells at your sides.","Lower until your back knee is near the floor.","Keep your front knee steady.","Drive up and switch legs."],"img":"opengym/7550.webp","gif":null,"ext":1},{"id":"7551","n":"bodyweight heel elevated bulgarian split squat","bp":"upper legs","eq":"body weight","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","calves"],"st":["Place your rear foot on a bench and front heel on a small plate.","Hold your hands at your chest.","Lower straight down.","Keep your front knee over your toes.","Push up and switch legs."],"img":"opengym/7551.webp","gif":null,"ext":1},{"id":"7552","n":"barbell zercher bulgarian split squat","bp":"upper legs","eq":"barbell","tg":"quads","mg":"glutes","sm":["glutes","core","hamstrings","upper back"],"st":["Rest the barbell in the crooks of your elbows.","Put your rear foot on a bench.","Lower your back knee toward the floor.","Keep your chest up.","Drive up and switch legs."],"img":"opengym/7552.webp","gif":null,"ext":1},{"id":"7553","n":"doorway chest stretch","bp":"chest","eq":"body weight","tg":"pectorals","mg":"shoulders","sm":["shoulders","upper chest","biceps"],"st":["Stand in a doorway with forearms on the frame, elbows at 90 degrees.","Step one foot forward.","Lean gently through the door until you feel a stretch.","Hold for 20-30 seconds.","Breathe slowly and step back."],"img":"opengym/7553.webp","gif":null,"ext":1},{"id":"7554","n":"parallel bars bent knee inverted row","bp":"back","eq":"body weight","tg":"upper back","mg":"lats","sm":["lats","biceps","rear deltoids","core"],"st":["Lie under parallel bars and grab them.","Bend your knees with feet on the floor.","Keep your body straight from shoulders to knees.","Pull your chest to the bars.","Lower slowly."],"img":"opengym/7554.webp","gif":null,"ext":1},{"id":"7555","n":"jumping jack high knee","bp":"full body","eq":"body weight","tg":"cardiovascular system","mg":"quadriceps","sm":["quadriceps","calves","hip flexors","shoulders"],"st":["Stand tall with arms at your sides.","Jump your feet out and raise your arms overhead.","Jump back in and bring one knee high.","Alternate knees each rep.","Stay light on your feet."],"img":"opengym/7555.webp","gif":null,"ext":1},{"id":"7556","n":"squat jack","bp":"upper legs","eq":"body weight","tg":"quads","mg":"glutes","sm":["glutes","adductors","calves"],"st":["Start in a squat with hands at your chest.","Jump your feet out wide.","Hop back to the narrow squat stance.","Stay low the whole time.","Land softly and keep your chest up."],"img":"opengym/7556.webp","gif":null,"ext":1},{"id":"7557","n":"wall sit (narrow stance)","bp":"upper legs","eq":"body weight","tg":"quads","mg":"glutes","sm":["glutes","calves","core"],"st":["Lean your back on a wall with feet close together.","Slide down until your thighs are about parallel.","Keep knees over ankles.","Hold for 20-60 seconds.","Slide back up slowly."],"img":"opengym/7557.webp","gif":null,"ext":1},{"id":"7558","n":"wall sit from deficit","bp":"upper legs","eq":"body weight","tg":"quads","mg":"glutes","sm":["glutes","calves","core"],"st":["Stand with your heels on a low platform and your back on a wall.","Slide down until thighs are parallel.","Keep your back flat.","Hold for 20-45 seconds.","Slide up carefully."],"img":"opengym/7558.webp","gif":null,"ext":1},{"id":"7559","n":"dumbbell goblet wall sit","bp":"upper legs","eq":"dumbbell","tg":"quads","mg":"glutes","sm":["glutes","core","shoulders"],"st":["Hold a dumbbell at your chest and lean on a wall.","Slide down until thighs are parallel.","Keep your knees above your ankles.","Hold for 20-45 seconds.","Stand up slowly."],"img":"opengym/7559.webp","gif":null,"ext":1},{"id":"7560","n":"bodyweight single leg squat","bp":"upper legs","eq":"body weight","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","core","calves"],"st":["Stand on one leg with the other lifted in front.","Extend your arms for balance.","Lower down with control.","Keep your knee over your toes.","Push up and switch legs."],"img":"opengym/7560.webp","gif":null,"ext":1},{"id":"7561","n":"bodyweight single leg squat with support","bp":"upper legs","eq":"body weight","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","core"],"st":["Hold a stable support with one hand.","Stand on one leg with the other lifted.","Lower down as far as you can with control.","Use the support only as much as needed.","Push up and switch legs."],"img":"opengym/7561.webp","gif":null,"ext":1},{"id":"7562","n":"seated quadriceps stretch v. 2","bp":"upper legs","eq":"body weight","tg":"quads","mg":"hip flexors","sm":["hip flexors"],"st":["Sit sideways on a bench or chair edge.","Bend one knee, tucking your foot behind you.","Hold your ankle and gently pull it toward your glutes.","Hold for 20-30 seconds.","Switch sides."],"img":"opengym/7562.webp","gif":null,"ext":1},{"id":"7563","n":"kettlebell swing clean grip front squat","bp":"upper legs","eq":"kettlebell","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","core","shoulders","lower back"],"st":["Stand with feet shoulder-width apart and the kettlebell on the floor in front of you.","Hinge back and swing the bell between your legs.","Drive your hips forward to swing, catching it in a clean position at your chest.","Squat down with your chest tall.","Stand back up and lower the bell to swing again.","Keep your back flat throughout."],"img":"opengym/7563.webp","gif":null,"ext":1},{"id":"7564","n":"cable split stance single arm row","bp":"back","eq":"cable","tg":"upper back","mg":"lats","sm":["lats","biceps","rear deltoids","core"],"st":["Stand in a split stance facing a low cable.","Grab the handle with one hand.","Row to your hip, squeezing the shoulder blade.","Keep your torso steady.","Return slowly and switch sides."],"img":"opengym/7564.webp","gif":null,"ext":1},{"id":"7565","n":"barbell bent arm pullover v. 2","bp":"back","eq":"barbell","tg":"lats","mg":"chest","sm":["chest","triceps","core"],"st":["Lie on a bench holding a barbell above your chest.","Keep a slight elbow bend.","Lower the bar behind your head.","Pull it back over your chest.","Keep your ribs down."],"img":"opengym/7565.webp","gif":null,"ext":1},{"id":"7566","n":"dumbbell hack squat","bp":"upper legs","eq":"dumbbell","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","calves"],"st":["Hold dumbbells behind you with your heels slightly raised.","Keep your chest up.","Squat down.","Stay tall.","Drive up through your feet."],"img":"opengym/7566.webp","gif":null,"ext":1},{"id":"7577","n":"bodyweight heel elevated squat","bp":"upper legs","eq":"body weight","tg":"quads","mg":"glutes","sm":["glutes","calves","core"],"st":["Stand with your heels on a small plate.","Extend your arms in front.","Squat deep with your chest up.","Keep your knees tracking over your toes.","Stand back up."],"img":"opengym/7577.webp","gif":null,"ext":1},{"id":"7578","n":"cable front squat with v bar","bp":"upper legs","eq":"cable","tg":"quads","mg":"glutes","sm":["glutes","core","upper back"],"st":["Hold a V bar at chest height.","Stand a step back from the cable.","Squat down with your elbows up.","Keep your chest tall.","Stand up."],"img":"opengym/7578.webp","gif":null,"ext":1},{"id":"7581","n":"kettlebell contralateral reverse lunge","bp":"upper legs","eq":"kettlebell","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","core"],"st":["Hold a kettlebell in one hand.","Step back with the opposite leg.","Lower until the back knee nears the floor.","Push through the front foot.","Finish reps and switch sides."],"img":"opengym/7581.webp","gif":null,"ext":1},{"id":"7582","n":"kettlebell ipsilateral reverse lunge","bp":"upper legs","eq":"kettlebell","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","obliques","core"],"st":["Hold a kettlebell in one hand.","Step back with the leg on the same side.","Lower under control.","Keep your torso upright.","Push back up and switch sides."],"img":"opengym/7582.webp","gif":null,"ext":1},{"id":"7583","n":"cable neutral grip lat pulldown","bp":"back","eq":"cable","tg":"lats","mg":"biceps","sm":["biceps","upper back","rhomboids","forearms"],"st":["Sit at the lat pulldown station, thighs secured, and grab the neutral-grip handle.","Lean back slightly and brace your core.","Pull the handle down to your upper chest, driving your elbows toward your ribs.","Squeeze your shoulder blades together at the bottom.","Let the handle rise slowly until your arms are fully extended."],"img":"opengym/7583.webp","gif":null,"ext":1},{"id":"7584","n":"cable kneeling high low anti rotation chop","bp":"waist","eq":"cable","tg":"abs","mg":"obliques","sm":["obliques","core","shoulders","glutes"],"st":["Kneel side-on to a high cable and hold the handle with both hands.","Brace your core and keep your hips square.","Chop the handle diagonally down across your body, arms mostly straight.","Do not let your torso rotate; the arms and shoulders do the travel.","Return slowly under control, finish your reps, then switch sides."],"img":"opengym/7584.webp","gif":null,"ext":1},{"id":"7585","n":"twist turn lift","bp":"waist","eq":"body weight","tg":"obliques","mg":"core","sm":["core","hip flexors"],"st":["Lie on your back with your knees bent and arms extended.","Lift your shoulders and legs off the floor.","Twist your torso and bring your knees toward one side.","Turn back through the centre and lift again.","Repeat to the other side, keeping the movement smooth and controlled."],"img":"opengym/7585.webp","gif":null,"ext":1},{"id":"7586","n":"cable ipsilateral glute dominant step up","bp":"upper legs","eq":"cable","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","core"],"st":["Stand in front of a box with a cable handle in the hand on your working side.","Place one foot fully on the box.","Lean your torso forward slightly.","Drive through the heel to stand up.","Lower slowly.","Finish all reps, then switch sides."],"img":"opengym/7586.webp","gif":null,"ext":1},{"id":"7587","n":"cable single arm high row with chest support","bp":"back","eq":"cable","tg":"lats","mg":"upper back","sm":["upper back","rear deltoids","biceps","rhomboids"],"st":["Set a handle on a high pulley and lean your chest against the support.","Grab the handle with one hand and let your arm extend.","Pull your elbow back and down toward your hip.","Squeeze your shoulder blade at the end of the pull.","Return slowly to full extension, finish your reps, then switch arms."],"img":"opengym/7587.webp","gif":null,"ext":1},{"id":"7588","n":"weighted front raise hold","bp":"shoulders","eq":"weight plate","tg":"delts","mg":"upper chest","sm":["upper chest","trapezius","core","forearms"],"st":["Stand tall holding a weight plate with both hands at your thighs.","Raise it straight in front of you to shoulder height.","Keep your arms nearly straight and your ribs down.","Hold the position, breathing steadily, for 20-40 seconds.","Lower the plate slowly with control."],"img":"opengym/7588.webp","gif":null,"ext":1},{"id":"7589","n":"cable kneeling glute kickback","bp":"upper legs","eq":"cable","tg":"glutes","mg":"hamstrings","sm":["hamstrings","lower back","core"],"st":["Attach an ankle cuff to a low cable and kneel on hands and knees facing it.","Brace your core and keep your back flat.","Kick the cuffed leg back and up.","Squeeze at the top.","Return slowly.","Finish all reps, then switch sides."],"img":"opengym/7589.webp","gif":null,"ext":1},{"id":"7590","n":"dumbbell glute dominant bulgarian split squat","bp":"upper legs","eq":"dumbbell","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","adductors","core"],"st":["Hold a dumbbell in each hand and stand with your back foot on a bench.","Step the front foot out far enough for your shin to stay near vertical.","Lean your torso forward slightly.","Lower until the thigh is parallel.","Drive through your front heel to rise.","Finish all reps, then switch sides."],"img":"opengym/7590.webp","gif":null,"ext":1},{"id":"7591","n":"cable lying face pull","bp":"shoulders","eq":"cable","tg":"delts","mg":"rear deltoids","sm":["rear deltoids","upper back","rhomboids","rotator cuff"],"st":["Lie on your back with the cable set low behind your head and hold the rope ends.","Start with your arms extended.","Pull the rope toward your face, elbows flaring out and wide.","Squeeze your shoulder blades together at the end.","Return slowly to the start."],"img":"opengym/7591.webp","gif":null,"ext":1},{"id":"7592","n":"cable incline rear delt fly with back support","bp":"shoulders","eq":"cable","tg":"delts","mg":"rear deltoids","sm":["rear deltoids","upper back","rhomboids","trapezius"],"st":["Lie chest down on an incline bench between two cable stations.","Grab the opposite handles, arms hanging with a slight bend.","Raise your arms out to the sides until they reach shoulder level.","Pause and squeeze your rear delts.","Lower slowly without swinging."],"img":"opengym/7592.webp","gif":null,"ext":1},{"id":"7593","n":"sled glute dominant leg press","bp":"upper legs","eq":"sled machine","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","adductors"],"st":["Sit in the sled and place your feet high and wide on the platform.","Release the safety and lower the sled until your knees reach about 90 degrees.","Keep your lower back pressed into the seat.","Push through your heels to extend your legs without locking the knees.","Lower under control for each rep."],"img":"opengym/7593.webp","gif":null,"ext":1},{"id":"7597","n":"cable high row with chest support","bp":"back","eq":"cable","tg":"lats","mg":"upper back","sm":["upper back","rear deltoids","biceps","rhomboids"],"st":["Set the cable high and lean your chest against the support pad.","Grab the handles and extend your arms.","Pull your elbows back and slightly down.","Squeeze your shoulder blades together at the end.","Let your arms extend slowly to the start."],"img":"opengym/7597.webp","gif":null,"ext":1},{"id":"7598","n":"dumbbell contralateral glute dominant bulgarian split squat","bp":"upper legs","eq":"dumbbell","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","adductors","core"],"st":["Hold one dumbbell in the hand opposite your front leg.","Put your back foot on a bench and step the front foot forward.","Lean your torso forward slightly.","Lower until the front thigh is parallel.","Drive up through the front heel.","Finish all reps, then switch sides."],"img":"opengym/7598.webp","gif":null,"ext":1},{"id":"7619","n":"jack burpee v. 2","bp":"full body","eq":"body weight","tg":"cardiovascular system","mg":"quadriceps","sm":["quadriceps","glutes","chest","shoulders","core"],"st":["Stand with your feet shoulder-width apart.","Squat down, place your hands on the floor and jump your feet back to a plank.","Lower your chest to the floor and push up, or skip the push-up if you prefer.","Jump your feet back toward your hands.","Jump up, spreading your arms and legs like a jumping jack, then repeat."],"img":"opengym/7619.webp","gif":null,"ext":1},{"id":"7620","n":"barbell banded bench press","bp":"chest","eq":"barbell","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders","upper chest"],"st":["Set bands on the bar and lie on a flat bench with your feet planted.","Unrack the bar over your chest with a firm grip.","Lower it to your mid chest under control.","Press up and out until your arms are straight.","Keep your shoulder blades pinched and your feet down."],"img":"opengym/7620.webp","gif":null,"ext":1},{"id":"7621","n":"barbell pin bench press conventional grip","bp":"chest","eq":"barbell","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders","upper chest"],"st":["Set the pins at a height just above your chest and lie on the bench.","Grab the bar at about shoulder-width plus a little.","Pause the bar on the pins to remove momentum.","Press the bar straight up until your arms lock out.","Lower back to the pins with control and reset for each rep."],"img":"opengym/7621.webp","gif":null,"ext":1},{"id":"7622","n":"lying single leg hamstring stretch against wall","bp":"upper legs","eq":"body weight","tg":"hamstrings","mg":"calves","sm":["calves","glutes","lower back"],"st":["Lie on your back with your hips close to a wall.","Rest one heel on the wall with your leg as straight as feels comfortable.","Keep the other leg flat on the floor.","Relax and breathe, letting the hamstring lengthen.","Hold for 20-30 seconds, then switch legs."],"img":"opengym/7622.webp","gif":null,"ext":1},{"id":"7623","n":"single arm lat stretch against wall","bp":"back","eq":"body weight","tg":"lats","mg":"shoulders","sm":["shoulders","obliques","triceps"],"st":["Stand beside a wall and place one hand on it above head height.","Step your feet back slightly.","Press your hips away and lean your chest down toward the floor.","Feel the stretch along your side and under the armpit.","Hold for 20-30 seconds, then switch arms."],"img":"opengym/7623.webp","gif":null,"ext":1},{"id":"7624","n":"flying lizard yoga pose utthan pristhasana","bp":"upper legs","eq":"body weight","tg":"adductors","mg":"hip flexors","sm":["hip flexors","hamstrings","glutes","core"],"st":["Start in a low lunge with your front foot between your hands.","Lower your forearms to the floor or blocks.","Drop your back knee or keep it lifted.","Let your hips sink.","Hold for 20-30 seconds, breathing slowly.","Step back and switch sides."],"img":"opengym/7624.webp","gif":null,"ext":1},{"id":"7625","n":"dumbbell bent over curl","bp":"upper arms","eq":"dumbbell","tg":"biceps","mg":"brachialis","sm":["brachialis","forearms","upper back"],"st":["Hold a dumbbell in each hand and hinge forward with a flat back.","Let your arms hang straight down.","Curl the weights up toward your shoulders, elbows fixed.","Squeeze at the top.","Lower slowly until your arms are straight."],"img":"opengym/7625.webp","gif":null,"ext":1},{"id":"7626","n":"landmine squat","bp":"upper legs","eq":"landmine","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","core","adductors"],"st":["Hold the end of the landmine bar against your chest with both hands.","Stand with your feet shoulder-width apart.","Sit your hips down and back, keeping your chest tall.","Squat until your thighs are about parallel to the floor.","Drive through your whole foot to stand back up."],"img":"opengym/7626.webp","gif":null,"ext":1},{"id":"7627","n":"landmine overhead rear lunge","bp":"upper legs","eq":"landmine","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","shoulders","core"],"st":["Hold the end of the landmine bar at your shoulder.","Step one foot back into a lunge.","As you rise, press the bar overhead.","Lower the bar to your shoulder while you lunge back again.","Complete your reps and switch legs."],"img":"opengym/7627.webp","gif":null,"ext":1},{"id":"7648","n":"dumbbell ipsilateral single leg stiff leg deadlift","bp":"upper legs","eq":"dumbbell","tg":"hamstrings","mg":"glutes","sm":["glutes","lower back","core","grip muscles"],"st":["Hold a dumbbell in the hand on the same side as your standing leg.","Shift your weight to that leg with a soft knee.","Hinge at the hips and reach the weight toward the floor.","Extend the other leg straight behind you.","Return to standing by squeezing your glute.","Finish all reps, then switch sides."],"img":"opengym/7648.webp","gif":null,"ext":1},{"id":"7693","n":"sitting alternate knee to elbow twist","bp":"waist","eq":"body weight","tg":"obliques","mg":"hip flexors","sm":["hip flexors","core"],"st":["Sit tall on the floor, leaning back slightly with your hands behind your head.","Lift your feet off the floor.","Twist and bring one elbow toward the opposite knee.","Return to centre and repeat on the other side.","Alternate sides at a steady pace."],"img":"opengym/7693.webp","gif":null,"ext":1},{"id":"7743","n":"cable half kneeling face pull","bp":"shoulders","eq":"cable","tg":"delts","mg":"rear deltoids","sm":["rear deltoids","upper back","rotator cuff","core"],"st":["Set a rope at head height and half kneel facing the stack.","Hold the rope ends with your palms facing in.","Pull the rope toward your face, elbows high and wide.","Squeeze your shoulder blades together.","Return slowly. Switch the leading knee after your set."],"img":"opengym/7743.webp","gif":null,"ext":1},{"id":"7744","n":"cable standing supinated face pull (with rope)","bp":"shoulders","eq":"cable","tg":"delts","mg":"rear deltoids","sm":["rear deltoids","upper back","biceps","rotator cuff"],"st":["Set the rope at face height and grip it with your palms facing up.","Step back and stand tall.","Pull the rope toward your face, elbows leading.","Squeeze your shoulder blades at the end.","Return slowly to the start."],"img":"opengym/7744.webp","gif":null,"ext":1},{"id":"7745","n":"standing supinated face pull (with towels)","bp":"shoulders","eq":"body weight","tg":"delts","mg":"rear deltoids","sm":["rear deltoids","upper back","biceps","rotator cuff"],"st":["Loop a towel around a sturdy anchor and hold both ends, palms up.","Lean back with your arms extended.","Pull your hands toward your face, elbows wide.","Squeeze your shoulder blades together.","Lower yourself slowly. Walk your feet in to make it harder."],"img":"opengym/7745.webp","gif":null,"ext":1},{"id":"7746","n":"nordic hamstring curl","bp":"upper legs","eq":"body weight","tg":"hamstrings","mg":"glutes","sm":["glutes","calves","core"],"st":["Kneel on a pad with your ankles held down firmly.","Keep your body straight from knees to head.","Lower forward as slowly as you can.","Catch yourself with your hands at the bottom.","Push back up and repeat."],"img":"opengym/7746.webp","gif":null,"ext":1},{"id":"7747","n":"dumbbell prone w raise","bp":"shoulders","eq":"dumbbell","tg":"delts","mg":"rear deltoids","sm":["rear deltoids","upper back","rhomboids","rotator cuff"],"st":["Lie face down on a bench or the floor with a light dumbbell in each hand.","Bend your elbows to about 90 degrees.","Lift your arms out and up into a W shape.","Squeeze your shoulder blades together.","Lower slowly and repeat."],"img":"opengym/7747.webp","gif":null,"ext":1},{"id":"7751","n":"kettlebell swing clean grip front squat v. 2","bp":"upper legs","eq":"kettlebell","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","core","shoulders","lower back"],"st":["Stand with feet shoulder-width apart and the kettlebell on the floor in front of you.","Hinge back and swing the bell between your legs.","Drive your hips forward to swing, catching it in a clean position at your chest.","Squat down with your chest tall.","Stand back up and lower the bell to swing again.","Keep your back flat throughout."],"img":"opengym/7751.webp","gif":null,"ext":1},{"id":"7839","n":"dead bug v. 3","bp":"waist","eq":"body weight","tg":"abs","mg":"hip flexors","sm":["hip flexors","obliques","shoulders"],"st":["Lie on your back with arms straight above you and knees bent at 90 degrees.","Press your lower back into the floor.","Lower one arm and the opposite leg toward the floor.","Return to the start.","Alternate sides with a slow tempo.","Keep your ribs down."],"img":"opengym/7839.webp","gif":null,"ext":1},{"id":"7850","n":"reverse air cycling","bp":"waist","eq":"body weight","tg":"abs","mg":"lower abs","sm":["lower abs","hip flexors","core"],"st":["Lie on your back and lift your hips slightly with hands under your glutes.","Raise your legs.","Pedal backward in a smooth circle.","Keep your lower back pressed down.","Continue for a set time or reps."],"img":"opengym/7850.webp","gif":null,"ext":1},{"id":"7854","n":"side plank twist arm delt raise","bp":"waist","eq":"body weight","tg":"obliques","mg":"shoulders","sm":["shoulders","core"],"st":["Set up in a side plank on your forearm.","Raise your top arm up toward the ceiling.","Rotate and thread your arm under your torso.","Open back up and raise the arm again.","Complete your reps, then switch sides."],"img":"opengym/7854.webp","gif":null,"ext":1},{"id":"7859","n":"explosive dynamic plank","bp":"waist","eq":"body weight","tg":"abs","mg":"core","sm":["core","shoulders","chest","hip flexors"],"st":["Start in a high plank, hands under shoulders.","Brace your core and squeeze your glutes.","Move quickly, hopping or shifting your hands and feet.","Keep your hips level and avoid sagging.","Rest when your form slips."],"img":"opengym/7859.webp","gif":null,"ext":1},{"id":"7864","n":"lever overhead triceps extension","bp":"upper arms","eq":"leverage machine","tg":"triceps","mg":"shoulders","sm":["shoulders","core"],"st":["Adjust the seat and sit with your back supported.","Grip the handles overhead with your elbows pointing up.","Extend your arms until they are almost straight.","Squeeze your triceps at the top.","Lower slowly behind your head."],"img":"opengym/7864.webp","gif":null,"ext":1},{"id":"7879","n":"dumbbell incline triceps kickback","bp":"upper arms","eq":"dumbbell","tg":"triceps","mg":"rear deltoids","sm":["rear deltoids","upper back","forearms"],"st":["Lie chest down on an incline bench with a dumbbell in each hand.","Pin your upper arms to your sides.","Straighten your elbows to kick the weights back.","Squeeze your triceps.","Return slowly.","Keep your upper arms still."],"img":"opengym/7879.webp","gif":null,"ext":1},{"id":"7880","n":"dumbbell kneeling triceps kickback","bp":"upper arms","eq":"dumbbell","tg":"triceps","mg":"rear deltoids","sm":["rear deltoids","core","forearms"],"st":["Kneel beside a bench with one hand and the same-side knee on it.","Hold a dumbbell in the free hand with your upper arm against your side.","Extend your elbow to kick the weight back.","Squeeze your triceps.","Lower slowly.","Finish all reps, then switch sides."],"img":"opengym/7880.webp","gif":null,"ext":1},{"id":"7882","n":"plate push","bp":"chest","eq":"weight plate","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders","core"],"st":["Stand with a weight plate held at your chest, elbows bent.","Brace your abs and bend your knees slightly.","Push the plate out explosively with both arms.","Fully extend your arms.","Pull the plate back to your chest with control.","Repeat for the planned reps."],"img":"opengym/7882.webp","gif":null,"ext":1},{"id":"7883","n":"landmine deadlift","bp":"upper legs","eq":"landmine","tg":"glutes","mg":"hamstrings","sm":["hamstrings","lower back","quadriceps","core","grip muscles"],"st":["Load one end of the barbell in a landmine and stand facing it, feet hip-width.","Hinge back and grip the bar end with both hands.","Brace your abs and keep your back flat.","Drive your hips forward to stand.","Lower the bar under control.","Repeat for the planned reps."],"img":"opengym/7883.webp","gif":null,"ext":1},{"id":"7884","n":"lever push up with towels","bp":"chest","eq":"body weight","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders","core"],"st":["Place your hands on towels on the floor in a plank.","Keep your body in a straight line.","Lower your chest toward the floor.","Press back up.","Keep your elbows at about 45 degrees.","Repeat for the planned reps."],"img":"opengym/7884.webp","gif":null,"ext":1},{"id":"7892","n":"dumbbell seated triceps extension v. 2","bp":"upper arms","eq":"dumbbell","tg":"triceps","mg":"shoulders","sm":["shoulders","forearms","core"],"st":["Sit on a bench with back support, holding one dumbbell overhead with both hands.","Keep your upper arms close to your head.","Lower the weight behind your head by bending your elbows.","Extend your arms back up.","Keep your core tight.","Repeat for the planned reps."],"img":"opengym/7892.webp","gif":null,"ext":1},{"id":"7895","n":"kneeling rotation torso rear fly to thread through","bp":"back","eq":"body weight","tg":"delts","mg":"rhomboids","sm":["rhomboids","rear deltoids","obliques"],"st":["Start on hands and knees.","Place one hand behind your head and rotate your torso open, elbow to the ceiling.","Return and thread that arm under your chest.","Let your shoulder reach toward the floor.","Keep your hips still.","Finish all reps, then switch sides."],"img":"opengym/7895.webp","gif":null,"ext":1},{"id":"7921","n":"cable seated unilateral bicep curl","bp":"upper arms","eq":"cable","tg":"biceps","mg":"brachialis","sm":["brachialis","forearms"],"st":["Sit facing a low cable and hold the handle with one hand.","Rest your elbow near your side.","Curl the handle up toward your shoulder.","Squeeze at the top.","Lower slowly and switch arms after your set."],"img":"opengym/7921.webp","gif":null,"ext":1},{"id":"7922","n":"cable seated single arm unilateral bicep curl","bp":"upper arms","eq":"cable","tg":"biceps","mg":"brachialis","sm":["brachialis","forearms"],"st":["Sit upright with a low cable handle in one hand.","Keep your elbow tucked in.","Curl up toward your shoulder without leaning back.","Squeeze at the top for a second.","Lower under control, then switch arms."],"img":"opengym/7922.webp","gif":null,"ext":1},{"id":"7994","n":"dumbbell glute bridge chest press","bp":"chest","eq":"dumbbell","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders","glutes","hamstrings","core"],"st":["Lie on your back holding dumbbells at chest level, knees bent.","Lift your hips into a bridge.","Press the dumbbells up over your chest.","Lower with control while holding your hips high.","Finish your reps, then lower your hips."],"img":"opengym/7994.webp","gif":null,"ext":1},{"id":"7995","n":"dumbbell bent over y raise","bp":"shoulders","eq":"dumbbell","tg":"delts","mg":"rear deltoids","sm":["rear deltoids","trapezius","rhomboids"],"st":["Hold a light dumbbell in each hand and hinge at the hips with a flat back.","Let your arms hang below your shoulders, palms facing each other.","Raise both arms forward and up at about 45 degrees to form a Y.","Pause briefly at the top and squeeze your shoulder blades.","Lower the weights slowly under control.","Keep your neck long and avoid swinging your torso."],"img":"opengym/7995.webp","gif":null,"ext":1},{"id":"7999","n":"resistance band 45 degree hip extension glute focused","bp":"upper legs","eq":"resistance band","tg":"glutes","mg":"hamstrings","sm":["hamstrings","lower back"],"st":["Set up on a 45 degree hip extension bench with the band anchored under your feet and held across your upper back.","Cross your arms or hold the band at your shoulders.","Hinge forward at the hips with a flat back until you feel your hamstrings stretch.","Drive your hips forward and squeeze your glutes to come back up.","Stop when your body is in a straight line.","Do not over-arch your lower back at the top."],"img":"opengym/7999.webp","gif":null,"ext":1},{"id":"8002","n":"resistance band wide stance anti rotation chop","bp":"waist","eq":"resistance band","tg":"abs","mg":"obliques","sm":["obliques","core","shoulders","glutes"],"st":["Anchor the band at one side and stand sideways with your feet wide.","Hold the handle with both hands.","Brace your core.","Press or chop diagonally while keeping your torso square.","Return slowly. Switch sides after your set."],"img":"opengym/8002.webp","gif":null,"ext":1},{"id":"8025","n":"kettlebell wood chop","bp":"waist","eq":"kettlebell","tg":"obliques","mg":"shoulders","sm":["shoulders","glutes","core"],"st":["Hold a kettlebell with both hands and stand with your feet wide.","Start with it high beside one shoulder.","Rotate and chop down to the opposite knee.","Pivot your back foot as you turn.","Return with control and switch sides."],"img":"opengym/8025.webp","gif":null,"ext":1},{"id":"8052","n":"kneeling thoracic rotation","bp":"back","eq":"body weight","tg":"spine","mg":"obliques","sm":["obliques","upper back","shoulders"],"st":["Kneel on all fours with your hands under your shoulders.","Place one hand behind your head.","Rotate your upper body and point that elbow toward the ceiling.","Follow your elbow with your eyes and keep your hips square.","Return and touch the elbow toward the opposite arm.","Do your reps, then switch sides."],"img":"opengym/8052.webp","gif":null,"ext":1},{"id":"8075","n":"dumbbell single leg hip thrust v. 2","bp":"upper legs","eq":"dumbbell","tg":"glutes","mg":"hamstrings","sm":["hamstrings","core","quadriceps"],"st":["Sit with your upper back against a bench and a dumbbell on your hips.","Plant one foot and lift the other leg.","Drive your hips up until your body is straight.","Squeeze your glute at the top.","Lower slowly, finish your reps, then switch legs."],"img":"opengym/8075.webp","gif":null,"ext":1},{"id":"8076","n":"weighted plate push up","bp":"chest","eq":"weighted","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders","core"],"st":["Have a partner place a plate on your upper back, or set it carefully yourself.","Get into a high plank.","Lower your chest to the floor, elbows at about 45 degrees.","Press back up to straight arms.","Keep your body in a straight line."],"img":"opengym/8076.webp","gif":null,"ext":1},{"id":"8083","n":"cable straight leg diagonal kickback","bp":"upper legs","eq":"cable","tg":"glutes","mg":"hamstrings","sm":["hamstrings","core"],"st":["Attach an ankle cuff to a low cable pulley and strap it to one ankle.","Face the machine and hold the frame for balance.","Keep your leg straight and kick it back and slightly out to the side.","Squeeze your glute at the top without leaning forward.","Return slowly without letting the weight stack touch down.","Finish your reps, then switch legs."],"img":"opengym/8083.webp","gif":null,"ext":1},{"id":"8084","n":"negative biceps leg concentration curl","bp":"upper arms","eq":"body weight","tg":"biceps","mg":"brachialis","sm":["brachialis","forearms"],"st":["Sit with your legs apart and hold a weight in one hand.","Rest the back of your upper arm against your inner thigh.","Curl the weight up with help from your other hand if needed.","Lower it very slowly over about 3 to 4 seconds.","Keep your upper arm still against your leg.","Do your reps, then switch arms."],"img":"opengym/8084.webp","gif":null,"ext":1},{"id":"8085","n":"resistance band standing balance hip abduction","bp":"upper legs","eq":"band","tg":"abductors","mg":"glutes","sm":["glutes","core","ankles"],"st":["Put a band around your ankles and stand on one leg.","Hold something for balance if needed.","Lift the free leg out to the side.","Keep your torso upright.","Lower slowly and switch legs after your set."],"img":"opengym/8085.webp","gif":null,"ext":1},{"id":"8130","n":"moving child pose","bp":"upper legs","eq":"body weight","tg":"lats","mg":"lower back","sm":["lower back","shoulders","glutes"],"st":["Start on all fours with your knees slightly wider than your hips.","Sit your hips back toward your heels and reach your arms forward.","Let your chest sink toward the floor.","Rock forward and back slowly, then walk your hands to each side.","Breathe deeply and relax your neck.","Move gently for 30 to 60 seconds."],"img":"opengym/8130.webp","gif":null,"ext":1},{"id":"8141","n":"cable standing crossover","bp":"chest","eq":"cable","tg":"pectorals","mg":"upper chest","sm":["upper chest","shoulders","biceps"],"st":["Set the pulleys at a high position and grab a handle in each hand.","Step forward with a slight lean.","Bring your hands together in a wide arc.","Squeeze your chest as your hands cross.","Return slowly to a stretch."],"img":"opengym/8141.webp","gif":null,"ext":1},{"id":"8142","n":"resistance band lying leg press","bp":"upper legs","eq":"resistance band","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","adductors"],"st":["Lie on your back and loop a band around your feet, holding the ends.","Bring your knees toward your chest.","Press your feet away until your legs are almost straight.","Control the band as it pulls you back.","Repeat for your reps."],"img":"opengym/8142.webp","gif":null,"ext":1},{"id":"8143","n":"triceps dip on high parallel bars","bp":"upper arms","eq":"body weight","tg":"triceps","mg":"chest","sm":["chest","shoulders","forearms"],"st":["Grip the bars and lift yourself with straight arms.","Keep your body upright and elbows close.","Lower until your upper arms are about parallel to the floor.","Press back up to straight arms.","Avoid shrugging your shoulders."],"img":"opengym/8143.webp","gif":null,"ext":1},{"id":"8146","n":"lying pelvic floor relaxation and deep breathing","bp":"waist","eq":"body weight","tg":"abs","mg":"core","sm":["core","hip flexors"],"st":["Lie on your back with your knees bent and feet flat.","Rest your hands on your lower belly.","Breathe in slowly through your nose and let your belly rise.","Let your pelvic floor and hips soften as you inhale.","Breathe out slowly through your mouth.","Continue for 1 to 2 minutes at a relaxed pace."],"img":"opengym/8146.webp","gif":null,"ext":1},{"id":"8162","n":"deep lunge to hamstring stretch","bp":"upper legs","eq":"body weight","tg":"hamstrings","mg":"hip flexors","sm":["hip flexors","glutes","calves"],"st":["Step into a deep lunge with both hands on the floor.","Hold for a breath and feel the front of the back hip open.","Shift your hips back and straighten the front leg.","Flex your front foot and fold gently over it.","Hold for 20 to 30 seconds.","Return to the lunge and switch legs."],"img":"opengym/8162.webp","gif":null,"ext":1},{"id":"8188","n":"standing ankle circles v. 2","bp":"lower legs","eq":"body weight","tg":"calves","mg":"ankles","sm":["ankles","feet","shins"],"st":["Stand tall and hold a wall or chair for balance.","Lift one foot slightly off the floor.","Draw slow circles with your toes.","Do about 10 circles in one direction.","Switch to the other direction.","Change feet and repeat."],"img":"opengym/8188.webp","gif":null,"ext":1},{"id":"8189","n":"wide chin up","bp":"back","eq":"body weight","tg":"lats","mg":"biceps","sm":["biceps","upper back","forearms","rhomboids"],"st":["Hang from a bar with an underhand grip wider than shoulders.","Brace your core.","Pull until your chin is over the bar.","Squeeze your back at the top.","Lower slowly to a full hang."],"img":"opengym/8189.webp","gif":null,"ext":1},{"id":"8191","n":"cable standing hip flexion","bp":"upper legs","eq":"cable","tg":"hip flexors","mg":"core","sm":["core","quadriceps"],"st":["Attach an ankle strap and face away from a low cable.","Hold a support for balance.","Lift your knee in front of you.","Pause at the top.","Lower slowly. Switch legs after your set."],"img":"opengym/8191.webp","gif":null,"ext":1},{"id":"8192","n":"dumbbell sumo deadlift","bp":"upper legs","eq":"dumbbell","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","adductors","lower back"],"st":["Stand with a wide stance, toes turned out, and a dumbbell between your feet.","Hinge down and grab it with both hands.","Keep your chest up and back flat.","Drive through your feet to stand tall.","Lower the weight under control."],"img":"opengym/8192.webp","gif":null,"ext":1},{"id":"8193","n":"cable reverse woodchop","bp":"waist","eq":"cable","tg":"obliques","mg":"shoulders","sm":["shoulders","glutes","core"],"st":["Set the cable low and stand side-on to the stack.","Hold the handle with both hands.","Pull it diagonally up across your body.","Pivot your back foot and rotate your torso.","Return slowly. Switch sides after your set."],"img":"opengym/8193.webp","gif":null,"ext":1},{"id":"8194","n":"lying knee raise","bp":"waist","eq":"body weight","tg":"abs","mg":"lower abs","sm":["lower abs","hip flexors"],"st":["Lie on your back with your legs extended.","Press your lower back into the floor.","Draw your knees up toward your chest.","Pause briefly.","Lower slowly without arching."],"img":"opengym/8194.webp","gif":null,"ext":1},{"id":"8195","n":"sitting side bend on a chair","bp":"waist","eq":"body weight","tg":"obliques","mg":"core","sm":["core"],"st":["Sit tall on a chair with feet flat.","Place one hand behind your head.","Bend sideways toward the floor.","Return to upright using your side muscles.","Repeat on the other side."],"img":"opengym/8195.webp","gif":null,"ext":1},{"id":"8197","n":"sitting swimmer on a chair","bp":"shoulders","eq":"body weight","tg":"delts","mg":"upper back","sm":["upper back","core","shoulders"],"st":["Sit upright near the edge of a chair.","Lean forward slightly with a flat back.","Reach one arm forward and the other back, then alternate.","Move in a steady rhythm.","Keep your core braced."],"img":"opengym/8197.webp","gif":null,"ext":1},{"id":"8199","n":"sitting woodchopper on a chair","bp":"waist","eq":"body weight","tg":"obliques","mg":"shoulders","sm":["shoulders","core"],"st":["Sit tall on a chair and clasp your hands together.","Raise your arms diagonally up to one side.","Chop down across your body to the opposite knee.","Rotate through your torso.","Alternate sides at an easy pace."],"img":"opengym/8199.webp","gif":null,"ext":1},{"id":"8200","n":"sitting prayer chest squeeze on a chair","bp":"chest","eq":"body weight","tg":"pectorals","mg":"shoulders","sm":["shoulders","triceps"],"st":["Sit tall on a chair.","Bring your palms together in front of your chest.","Press your palms firmly into each other.","Hold for 10-15 seconds.","Release and repeat."],"img":"opengym/8200.webp","gif":null,"ext":1},{"id":"8202","n":"sitting alternate abduction twist on a chair","bp":"upper legs","eq":"body weight","tg":"abductors","mg":"glutes","sm":["glutes","obliques","core"],"st":["Sit tall near the edge of a chair.","Lift one leg and open it out to the side.","Twist your torso toward that leg.","Return to centre.","Alternate sides."],"img":"opengym/8202.webp","gif":null,"ext":1},{"id":"8203","n":"sitting russian twist on a chair","bp":"waist","eq":"body weight","tg":"obliques","mg":"hip flexors","sm":["hip flexors","core"],"st":["Sit near the edge of a chair and lean back slightly.","Clasp your hands in front of your chest.","Rotate your torso to one side.","Return to centre and rotate to the other side.","Keep your chest tall."],"img":"opengym/8203.webp","gif":null,"ext":1},{"id":"8220","n":"deep knee bend","bp":"upper legs","eq":"body weight","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","calves","core"],"st":["Stand with your feet shoulder-width apart.","Sit your hips back and down as deep as you can.","Keep your heels down and chest up.","Pause at the bottom.","Drive up to standing."],"img":"opengym/8220.webp","gif":null,"ext":1},{"id":"8221","n":"dumbbell lateral raise plank","bp":"waist","eq":"dumbbell","tg":"abs","mg":"shoulders","sm":["shoulders","core"],"st":["Set up in a plank with your hands on dumbbells.","Brace your core and widen your feet.","Lift one dumbbell out to the side.","Avoid twisting your hips.","Lower and alternate arms."],"img":"opengym/8221.webp","gif":null,"ext":1},{"id":"8222","n":"dumbbell underhand renegade row","bp":"waist","eq":"dumbbell","tg":"abs","mg":"lats","sm":["lats","biceps","core","shoulders"],"st":["Set up in a plank with your hands on dumbbells, palms facing forward.","Widen your feet for balance.","Row one dumbbell up to your ribs.","Keep your hips level.","Lower and alternate arms."],"img":"opengym/8222.webp","gif":null,"ext":1},{"id":"8223","n":"dumbbell renegade row on stability ball","bp":"waist","eq":"dumbbell","tg":"abs","mg":"lats","sm":["lats","upper back","core","shoulders"],"st":["Place your feet on a stability ball and your hands on dumbbells.","Brace into a strong plank.","Row one dumbbell up to your ribs.","Keep your hips level.","Lower and alternate arms."],"img":"opengym/8223.webp","gif":null,"ext":1},{"id":"8224","n":"resistance band renegade row","bp":"waist","eq":"resistance band","tg":"abs","mg":"lats","sm":["lats","upper back","core","shoulders"],"st":["Anchor a band and get into a plank facing it.","Hold the band in one hand.","Row your elbow back to your ribs.","Keep your hips level.","Return slowly and alternate arms."],"img":"opengym/8224.webp","gif":null,"ext":1},{"id":"8225","n":"dumbbell renegade row walk","bp":"waist","eq":"dumbbell","tg":"abs","mg":"lats","sm":["lats","core","shoulders","chest"],"st":["Start in a plank with a dumbbell in each hand.","Row one dumbbell up.","Place it down and step the hands forward.","Repeat with the other arm.","Keep your hips level."],"img":"opengym/8225.webp","gif":null,"ext":1},{"id":"8274","n":"biceps curl under table","bp":"upper arms","eq":"body weight","tg":"biceps","mg":"brachialis","sm":["brachialis","forearms","upper back"],"st":["Lie under a strong table and grip its edge with an underhand grip.","Keep your body straight with heels on the floor.","Pull your chest toward the table by bending the elbows.","Squeeze your biceps.","Lower slowly."],"img":"opengym/8274.webp","gif":null,"ext":1},{"id":"8289","n":"side lying chest stretch","bp":"chest","eq":"body weight","tg":"pectorals","mg":"shoulders","sm":["shoulders","upper chest"],"st":["Lie on your side with your knees bent and arms in front of you.","Lift your top arm and open it back like a book.","Let your chest rotate open.","Hold for 20-30 seconds.","Return and switch sides."],"img":"opengym/8289.webp","gif":null,"ext":1},{"id":"8299","n":"cable half kneeling single arm row v. 2","bp":"back","eq":"cable","tg":"upper back","mg":"lats","sm":["lats","biceps","core","rhomboids"],"st":["Half kneel facing the cable with the handle in one hand.","Keep your torso tall.","Row your elbow back past your ribs.","Squeeze your shoulder blade.","Return slowly and switch sides."],"img":"opengym/8299.webp","gif":null,"ext":1},{"id":"8303","n":"seated upright twists on a chair","bp":"waist","eq":"body weight","tg":"obliques","mg":"core","sm":["core"],"st":["Sit tall with feet flat and arms crossed over your chest.","Rotate your torso to one side.","Pause briefly.","Rotate to the other side.","Keep your hips still."],"img":"opengym/8303.webp","gif":null,"ext":1},{"id":"8327","n":"resistance band drag curl","bp":"upper arms","eq":"resistance band","tg":"biceps","mg":"brachialis","sm":["brachialis","forearms"],"st":["Stand on the band with feet hip-width apart and hold the handles at your thighs.","Keep your chest up and core braced.","Curl by dragging your hands up your body while the elbows move behind you.","Squeeze at the top for a moment.","Lower under control until your arms are straight."],"img":"opengym/8327.webp","gif":null,"ext":1},{"id":"8331","n":"kettlebell half kneeling halo","bp":"shoulders","eq":"kettlebell","tg":"delts","mg":"rotator cuff","sm":["rotator cuff","triceps","core"],"st":["Kneel on one knee with the other foot forward and hold the kettlebell upside down at chest height.","Squeeze your glutes and keep your ribs down.","Circle the bell around your head slowly, keeping it close.","Complete the reps, then reverse the direction.","Switch the kneeling leg and repeat."],"img":"opengym/8331.webp","gif":null,"ext":1},{"id":"8342","n":"bodyweight standing scapular external rotation","bp":"shoulders","eq":"body weight","tg":"delts","mg":"rotator cuff","sm":["rotator cuff","rear deltoids","upper back"],"st":["Stand tall with your elbows bent at your sides.","Keep your palms facing forward.","Rotate your forearms outward and squeeze your shoulder blades together.","Hold for a second.","Return slowly to the start.","Keep your ribs down and your shoulders away from your ears."],"img":"opengym/8342.webp","gif":null,"ext":1},{"id":"8343","n":"bodyweight standing t spine press","bp":"back","eq":"body weight","tg":"spine","mg":"upper back","sm":["upper back","shoulders","core"],"st":["Stand with your feet hip width apart.","Clasp your hands in front of your chest.","Press your arms up and slightly back while lifting your chest.","Extend through your upper back without flaring your ribs.","Return to the start under control.","Repeat for smooth, slow reps."],"img":"opengym/8343.webp","gif":null,"ext":1},{"id":"8358","n":"hamstring bridge","bp":"upper legs","eq":"body weight","tg":"hamstrings","mg":"glutes","sm":["glutes","lower back","core"],"st":["Lie on your back with knees bent and heels placed a bit farther from your hips.","Press your heels into the floor.","Lift your hips until your body forms a straight line from shoulders to knees.","Squeeze your glutes at the top.","Lower slowly and repeat."],"img":"opengym/8358.webp","gif":null,"ext":1},{"id":"8362","n":"resistance band standing single arm lateral raise","bp":"shoulders","eq":"resistance band","tg":"delts","mg":"trapezius","sm":["trapezius","rotator cuff"],"st":["Stand on the band and hold the handle in one hand at your side.","Keep a slight bend in the elbow and your torso still.","Raise your arm out to the side up to shoulder height.","Lower slowly against the band.","Complete the reps, then switch arms."],"img":"opengym/8362.webp","gif":null,"ext":1},{"id":"8363","n":"resistance band standing 90 degrees shoulder external rotation","bp":"shoulders","eq":"resistance band","tg":"delts","mg":"rotator cuff","sm":["rotator cuff","rear deltoids","upper back"],"st":["Anchor the band at shoulder height and hold the handle with your elbow raised to shoulder level, bent 90 degrees.","Keep the upper arm still.","Rotate your hand up and back until the forearm points to the ceiling.","Return slowly to the start.","Do all reps, then switch arms."],"img":"opengym/8363.webp","gif":null,"ext":1},{"id":"8364","n":"resistance band overhead shoulder press v. 2","bp":"shoulders","eq":"resistance band","tg":"delts","mg":"triceps","sm":["triceps","upper chest","trapezius"],"st":["Stand on the band with feet shoulder-width apart and hold the handles at shoulder height.","Brace your core and keep ribs down.","Press the handles overhead until your arms are straight.","Lower them back to your shoulders under control.","Repeat without leaning back."],"img":"opengym/8364.webp","gif":null,"ext":1},{"id":"8365","n":"resistance band pass through","bp":"shoulders","eq":"resistance band","tg":"delts","mg":"rotator cuff","sm":["rotator cuff","chest","upper back"],"st":["Hold the band in front of your thighs with a wide grip and straight arms.","Stand tall.","Raise the band overhead and keep going back behind your body.","Reverse the path to return to the front.","Widen your grip if it feels too tight."],"img":"opengym/8365.webp","gif":null,"ext":1},{"id":"8366","n":"kettlebell side swing v. 2","bp":"waist","eq":"kettlebell","tg":"obliques","mg":"abdominals","sm":["abdominals","glutes","hamstrings","shoulders"],"st":["Stand with feet wider than hips and hold a kettlebell with both hands.","Hinge at the hips and swing the bell between your legs.","Drive your hips forward and swing it up and across to one side.","Let it fall back through your legs and swing to the other side.","Keep your back flat throughout."],"img":"opengym/8366.webp","gif":null,"ext":1},{"id":"8369","n":"seated over head straight arm stretch","bp":"chest","eq":"body weight","tg":"pectorals","mg":"shoulders","sm":["shoulders","lats","triceps"],"st":["Sit tall on a chair or bench.","Interlace your fingers and straighten your arms.","Raise them overhead with palms facing up.","Lift your chest and reach slightly back.","Breathe normally and hold for 20 to 30 seconds.","Release slowly."],"img":"opengym/8369.webp","gif":null,"ext":1},{"id":"8374","n":"step out from squat","bp":"upper legs","eq":"body weight","tg":"quads","mg":"glutes","sm":["glutes","adductors","hip flexors"],"st":["Stand with your feet together.","Squat down by pushing your hips back.","Stand up while stepping one foot out to the side.","Bring that foot back in and squat again.","Alternate sides each rep.","Keep your chest up and knees tracking over your toes."],"img":"opengym/8374.webp","gif":null,"ext":1},{"id":"8375","n":"lever angled leg press","bp":"upper legs","eq":"leverage machine","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","calves"],"st":["Sit in the machine with your back flat on the pad and feet on the platform shoulder-width apart.","Release the safety handles.","Lower the platform until your knees are bent about 90 degrees.","Press through your whole foot until your legs are nearly straight.","Do not lock your knees out."],"img":"opengym/8375.webp","gif":null,"ext":1},{"id":"8399","n":"side floor tap plank","bp":"waist","eq":"body weight","tg":"obliques","mg":"abdominals","sm":["abdominals","shoulders","glutes"],"st":["Start in a high plank with hands under shoulders and feet wide.","Keep your body in a straight line.","Reach one hand out to tap the floor at the side without twisting your hips.","Return it and tap with the other hand.","Keep the pace steady and controlled."],"img":"opengym/8399.webp","gif":null,"ext":1},{"id":"8423","n":"seated lean back on a chair","bp":"waist","eq":"body weight","tg":"abs","mg":"hip flexors","sm":["hip flexors","obliques"],"st":["Sit tall near the front of a sturdy chair with your feet flat on the floor.","Brace your core and keep your shoulders relaxed.","Cross your arms over your chest.","Lean back slowly while keeping your back straight.","Stop where you can still hold your form, then return to upright using your abs."],"img":"opengym/8423.webp","gif":null,"ext":1},{"id":"8424","n":"seated cross body punch on a chair","bp":"chest","eq":"body weight","tg":"pectorals","mg":"shoulders","sm":["shoulders","obliques"],"st":["Sit tall near the front of a sturdy chair with your feet flat on the floor.","Brace your core and keep your shoulders relaxed.","Raise your fists to guard position.","Punch one arm across your body, rotating the trunk slightly.","Pull it back and punch with the other arm.","Keep a quick, smooth rhythm."],"img":"opengym/8424.webp","gif":null,"ext":1},{"id":"8431","n":"seated overhead stretch on a chair","bp":"back","eq":"body weight","tg":"lats","mg":"shoulders","sm":["shoulders","triceps","obliques"],"st":["Sit tall near the front of a sturdy chair with your feet flat on the floor.","Brace your core and keep your shoulders relaxed.","Interlace your fingers and raise your arms overhead.","Turn your palms to the ceiling and reach up tall.","Hold for 20-30 seconds while breathing steadily."],"img":"opengym/8431.webp","gif":null,"ext":1},{"id":"8433","n":"seated forward bend stretch on a chair","bp":"upper legs","eq":"body weight","tg":"hamstrings","mg":"lower back","sm":["lower back","glutes","calves"],"st":["Sit near the front of a sturdy chair and extend one leg with the heel on the floor.","Keep your back long.","Hinge forward from the hips and reach toward your toes.","Hold for 20-30 seconds.","Switch legs and repeat."],"img":"opengym/8433.webp","gif":null,"ext":1},{"id":"8434","n":"seated forward roll up on a chair","bp":"waist","eq":"body weight","tg":"abs","mg":"lower abs","sm":["lower abs","hip flexors","lower back"],"st":["Sit tall on the edge of a chair with your arms crossed or reaching forward.","Tuck your chin and round your lower back.","Roll your spine forward one segment at a time.","Reach toward your knees and pause.","Roll back up slowly to a tall position.","Keep the motion smooth and controlled."],"img":"opengym/8434.webp","gif":null,"ext":1},{"id":"8479","n":"bosu ball balance counterbalanced skater squat","bp":"upper legs","eq":"bosu ball","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","core","ankles"],"st":["Stand on one foot on the bosu ball and hold your arms in front for balance.","Reach the free leg back behind you.","Sit your hips back and lower into a single-leg squat.","Drive through the standing foot to rise.","Finish the reps, then switch legs."],"img":"opengym/8479.webp","gif":null,"ext":1},{"id":"8502","n":"dumbbell kneeling opposite shoulder press","bp":"shoulders","eq":"dumbbell","tg":"delts","mg":"triceps","sm":["triceps","core","glutes"],"st":["Kneel on one knee and hold a dumbbell at shoulder height in the hand opposite the raised knee.","Keep your torso tall and glutes tight.","Press the dumbbell overhead until your arm is straight.","Lower under control to your shoulder.","Finish the reps, then switch sides."],"img":"opengym/8502.webp","gif":null,"ext":1},{"id":"8505","n":"dumbbell kneeling twist down up raise","bp":"waist","eq":"dumbbell","tg":"obliques","mg":"abdominals","sm":["abdominals","shoulders","glutes"],"st":["Kneel on both knees and hold one dumbbell with both hands beside one hip.","Keep your hips square.","Twist and lift the dumbbell diagonally up across your body.","Reverse the path back down to the hip.","Finish the reps, then switch sides."],"img":"opengym/8505.webp","gif":null,"ext":1},{"id":"8533","n":"kneeling to standing squat","bp":"upper legs","eq":"body weight","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","core"],"st":["Kneel on both knees with your torso upright.","Step one foot forward and then the other so both feet are flat.","Press up to stand, then sit back into a squat.","Return to kneeling under control.","Alternate which foot steps first."],"img":"opengym/8533.webp","gif":null,"ext":1},{"id":"8536","n":"bodyweight tibialis raise wall supported","bp":"lower legs","eq":"body weight","tg":"shins","mg":"calves","sm":["calves","ankles"],"st":["Stand with your back against a wall and your feet a bit in front of you.","Keep your legs straight.","Lift your toes toward your shins as high as you can.","Lower slowly to the floor.","Keep the movement smooth and repeat."],"img":"opengym/8536.webp","gif":null,"ext":1},{"id":"8546","n":"lying prone y to t to w","bp":"back","eq":"body weight","tg":"upper back","mg":"rear deltoids","sm":["rear deltoids","rhomboids","trapezius","lower back"],"st":["Lie face down with your forehead near the floor and arms extended overhead in a Y.","Lift your arms slightly and hold.","Move them out to a T, then bend the elbows into a W.","Squeeze your shoulder blades together.","Reverse the order and repeat."],"img":"opengym/8546.webp","gif":null,"ext":1},{"id":"8585","n":"mid back elbow squeeze","bp":"back","eq":"body weight","tg":"upper back","mg":"rhomboids","sm":["rhomboids","rear deltoids","trapezius"],"st":["Stand or sit tall with your hands by your head or elbows bent in front.","Pull your elbows back and down.","Squeeze your shoulder blades together.","Hold for a second at the end.","Return slowly to the start.","Keep your neck relaxed."],"img":"opengym/8585.webp","gif":null,"ext":1},{"id":"8604","n":"lever seated leg curl (plate loaded)","bp":"upper legs","eq":"leverage machine","tg":"hamstrings","mg":"calves","sm":["calves","glutes"],"st":["Sit in the machine and adjust the pad above your ankles.","Keep your back against the support.","Curl your heels down and back as far as you can.","Squeeze your hamstrings briefly.","Return slowly without letting the weight crash."],"img":"opengym/8604.webp","gif":null,"ext":1},{"id":"8608","n":"resistance band sumo squat","bp":"upper legs","eq":"band","tg":"glutes","mg":"quadriceps","sm":["quadriceps","adductors","hamstrings"],"st":["Stand on the band with feet wider than shoulders and toes angled out.","Hold the band at your chest or shoulders.","Sit down between your legs, keeping your chest up.","Push your knees out over your toes.","Drive up through your heels and squeeze your glutes."],"img":"opengym/8608.webp","gif":null,"ext":1},{"id":"8610","n":"chinese plank","bp":"waist","eq":"body weight","tg":"abs","mg":"obliques","sm":["obliques","glutes","shoulders"],"st":["Set up in a plank on your forearms with elbows under shoulders.","Squeeze your glutes and brace your abs.","Keep your body in one straight line.","Breathe steadily and hold for 20-40 seconds.","Lower down to rest."],"img":"opengym/8610.webp","gif":null,"ext":1},{"id":"8611","n":"resistance band seated eversion foot","bp":"lower legs","eq":"band","tg":"calves","mg":"ankles","sm":["ankles","feet","shins"],"st":["Sit with one leg extended and loop the band around the forefoot, anchored on the inside.","Keep your leg still.","Turn your foot outward against the band.","Return slowly.","Finish the reps, then switch feet."],"img":"opengym/8611.webp","gif":null,"ext":1},{"id":"8612","n":"resistance band seated inversion foot","bp":"lower legs","eq":"band","tg":"calves","mg":"ankles","sm":["ankles","feet","shins"],"st":["Sit with one leg extended and loop the band around the forefoot, anchored on the outside.","Keep your leg still.","Turn your foot inward against the band.","Return slowly.","Finish the reps, then switch feet."],"img":"opengym/8612.webp","gif":null,"ext":1},{"id":"8613","n":"dumbbell preacher swing curl","bp":"upper arms","eq":"dumbbell","tg":"biceps","mg":"brachialis","sm":["brachialis","forearms","shoulders"],"st":["Rest your upper arms on a preacher pad and hold dumbbells with an underhand grip.","Keep your shoulders down.","Curl the weights up with a small drive from the bottom.","Squeeze at the top.","Lower slowly until your arms are almost straight."],"img":"opengym/8613.webp","gif":null,"ext":1},{"id":"8614","n":"cable standing single arm horizontal triceps extension","bp":"upper arms","eq":"cable","tg":"triceps","mg":"shoulders","sm":["shoulders","core"],"st":["Set the cable at chest height and stand facing away holding the handle by your shoulder.","Take a split stance for balance.","Extend your arm forward until it is straight.","Return slowly while keeping the elbow still.","Finish the reps, then switch arms."],"img":"opengym/8614.webp","gif":null,"ext":1},{"id":"8615","n":"seated alternate dynamic chest stretch on a chair","bp":"chest","eq":"body weight","tg":"pectorals","mg":"shoulders","sm":["shoulders","upper back"],"st":["Sit tall near the front of a sturdy chair with your feet flat on the floor.","Brace your core and keep your shoulders relaxed.","Open one arm out to the side and rotate the trunk slightly.","Feel the stretch across your chest.","Return and switch arms in a smooth rhythm."],"img":"opengym/8615.webp","gif":null,"ext":1},{"id":"8616","n":"seated elbow chest fly on a chair","bp":"chest","eq":"body weight","tg":"pectorals","mg":"shoulders","sm":["shoulders"],"st":["Sit tall near the front of a sturdy chair with your feet flat on the floor.","Brace your core and keep your shoulders relaxed.","Raise your elbows to chest height with forearms up.","Squeeze your elbows together in front of you.","Open them out again under control.","Keep your shoulders away from your ears."],"img":"opengym/8616.webp","gif":null,"ext":1},{"id":"8617","n":"seated external rotation on a chair","bp":"shoulders","eq":"body weight","tg":"delts","mg":"rotator cuff","sm":["rotator cuff","rear deltoids","upper back"],"st":["Sit tall near the front of a sturdy chair with your feet flat on the floor.","Brace your core and keep your shoulders relaxed.","Tuck your elbows at your sides bent to 90 degrees.","Rotate your forearms outward, squeezing your shoulder blades.","Return slowly and repeat."],"img":"opengym/8617.webp","gif":null,"ext":1},{"id":"8618","n":"seated chest press on a chair","bp":"chest","eq":"body weight","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders"],"st":["Sit tall near the front of a sturdy chair with your feet flat on the floor.","Brace your core and keep your shoulders relaxed.","Bring your hands to chest height and press your palms together.","Press forward until your arms are straight.","Draw them back to your chest slowly."],"img":"opengym/8618.webp","gif":null,"ext":1},{"id":"8619","n":"seated arm crossover on a chair","bp":"chest","eq":"body weight","tg":"pectorals","mg":"shoulders","sm":["shoulders"],"st":["Sit tall near the front of a sturdy chair with your feet flat on the floor.","Brace your core and keep your shoulders relaxed.","Open your arms wide to the sides at shoulder height.","Sweep them together so they cross in front of your chest.","Open back out and alternate which arm is on top."],"img":"opengym/8619.webp","gif":null,"ext":1},{"id":"8620","n":"seated decline chest press on a chair","bp":"chest","eq":"body weight","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders"],"st":["Sit tall near the front of a sturdy chair with your feet flat on the floor.","Brace your core and keep your shoulders relaxed.","Start with your hands at chest height.","Press them diagonally down and forward until your arms are straight.","Return slowly to the chest and repeat."],"img":"opengym/8620.webp","gif":null,"ext":1},{"id":"8621","n":"seated pec dec on a chair","bp":"chest","eq":"body weight","tg":"pectorals","mg":"shoulders","sm":["shoulders"],"st":["Sit tall near the front of a sturdy chair with your feet flat on the floor.","Brace your core and keep your shoulders relaxed.","Raise your forearms in front of you with elbows bent at shoulder height.","Squeeze your forearms together.","Open them back to the sides under control."],"img":"opengym/8621.webp","gif":null,"ext":1},{"id":"8622","n":"seated incline chest press on a chair","bp":"chest","eq":"body weight","tg":"pectorals","mg":"upper chest","sm":["upper chest","triceps","shoulders"],"st":["Sit tall near the front of a sturdy chair with your feet flat on the floor.","Brace your core and keep your shoulders relaxed.","Start with your hands near your chest.","Press them diagonally up and forward until your arms are straight.","Lower back to the chest slowly."],"img":"opengym/8622.webp","gif":null,"ext":1},{"id":"8633","n":"seated shoulder press on a chair","bp":"shoulders","eq":"body weight","tg":"delts","mg":"triceps","sm":["triceps","trapezius"],"st":["Sit tall near the front of a sturdy chair with your feet flat on the floor.","Brace your core and keep your shoulders relaxed.","Raise your hands to shoulder height with elbows bent.","Press them overhead until your arms are straight.","Lower back to your shoulders under control."],"img":"opengym/8633.webp","gif":null,"ext":1},{"id":"8634","n":"seated rotating boxing rolls on a chair","bp":"shoulders","eq":"body weight","tg":"cardiovascular system","mg":"shoulders","sm":["shoulders","obliques","core"],"st":["Sit tall near the front of a sturdy chair with your feet flat on the floor.","Brace your core and keep your shoulders relaxed.","Raise your fists in a boxing guard.","Roll your arms in circles while rotating your trunk side to side.","Keep a quick, rhythmic pace."],"img":"opengym/8634.webp","gif":null,"ext":1},{"id":"8652","n":"seated shoulder tap on a chair","bp":"shoulders","eq":"body weight","tg":"delts","mg":"core","sm":["core","obliques"],"st":["Sit tall near the front of a sturdy chair with your feet flat on the floor.","Brace your core and keep your shoulders relaxed.","Reach one hand across to tap the opposite shoulder.","Return and tap with the other hand.","Keep the pace steady."],"img":"opengym/8652.webp","gif":null,"ext":1},{"id":"8653","n":"seated open up and under swing on a chair","bp":"chest","eq":"body weight","tg":"pectorals","mg":"shoulders","sm":["shoulders","obliques","lats"],"st":["Sit tall near the front of a sturdy chair with your feet flat on the floor.","Brace your core and keep your shoulders relaxed.","Swing both arms open to the sides.","Rotate and sweep them under and across your body.","Open back out and alternate directions with a smooth rhythm."],"img":"opengym/8653.webp","gif":null,"ext":1},{"id":"8654","n":"seated overhead triceps extension on a chair","bp":"upper arms","eq":"body weight","tg":"triceps","mg":"shoulders","sm":["shoulders","core"],"st":["Sit tall near the front of a sturdy chair with your feet flat on the floor.","Brace your core and keep your shoulders relaxed.","Raise your arms overhead and bend your elbows so your hands drop behind your head.","Extend your arms back up until straight.","Lower slowly and keep your elbows pointing forward."],"img":"opengym/8654.webp","gif":null,"ext":1},{"id":"8655","n":"seated underhand arm circle on a chair","bp":"shoulders","eq":"body weight","tg":"delts","mg":"rotator cuff","sm":["rotator cuff","upper back"],"st":["Sit tall near the front of a sturdy chair with your feet flat on the floor.","Brace your core and keep your shoulders relaxed.","Extend your arms out to the sides with palms facing up.","Draw small circles, then gradually bigger.","Reverse the direction after a set."],"img":"opengym/8655.webp","gif":null,"ext":1},{"id":"8660","n":"sled side leg press","bp":"upper legs","eq":"sled machine","tg":"quads","mg":"glutes","sm":["glutes","adductors","hamstrings"],"st":["Position yourself on the sled in a side-facing posture with one foot on the platform.","Brace your core and keep your hips stable.","Push the platform away with the working leg.","Return slowly under control.","Finish the reps, then switch sides."],"img":"opengym/8660.webp","gif":null,"ext":1},{"id":"8661","n":"cable incline y raise with back support","bp":"shoulders","eq":"cable","tg":"delts","mg":"trapezius","sm":["trapezius","rear deltoids","upper back"],"st":["Lie chest-down on an incline bench with a cable handle in each hand.","Keep your neck neutral.","Raise your arms forward and up in a Y shape.","Pause at the top.","Lower slowly with straight arms."],"img":"opengym/8661.webp","gif":null,"ext":1},{"id":"8662","n":"cable incline close grip shoulder press with v bar","bp":"shoulders","eq":"cable","tg":"delts","mg":"triceps","sm":["triceps","upper chest"],"st":["Sit on an incline bench with a cable and V bar anchored low behind you.","Hold the bar at chest height with a narrow grip.","Press upward until your arms are straight.","Lower back to the chest slowly.","Keep your back against the pad."],"img":"opengym/8662.webp","gif":null,"ext":1},{"id":"8663","n":"cable incline y raise wrist straps with back support","bp":"shoulders","eq":"cable","tg":"delts","mg":"trapezius","sm":["trapezius","rear deltoids","upper back"],"st":["Fasten the wrist straps to the cables and lie chest-down on an incline bench.","Keep your neck neutral.","Raise your arms forward and up into a Y shape.","Squeeze your shoulders at the top.","Lower slowly."],"img":"opengym/8663.webp","gif":null,"ext":1},{"id":"8664","n":"dumbbell curtsey lunge v. 2","bp":"upper legs","eq":"dumbbell","tg":"glutes","mg":"quadriceps","sm":["quadriceps","adductors","hamstrings"],"st":["Stand holding dumbbells at your sides.","Step one foot back and across behind the other leg.","Lower until the front thigh is nearly parallel to the floor.","Push through the front foot to stand.","Alternate legs or finish one side before switching."],"img":"opengym/8664.webp","gif":null,"ext":1},{"id":"8701","n":"weighted bag walking lunge","bp":"upper legs","eq":"sandbag","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","core"],"st":["Hold the bag at your chest or on your shoulders.","Stand tall.","Step forward and lower until both knees are about 90 degrees.","Push through the front foot and bring the back leg forward.","Continue, alternating legs."],"img":"opengym/8701.webp","gif":null,"ext":1},{"id":"8702","n":"torque tank push","bp":"upper legs","eq":"sled machine","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","calves","core"],"st":["Grip the handles of the tank and lean forward.","Keep your back flat and core tight.","Drive with short, powerful steps.","Keep your hips low and push over the distance.","Rest and repeat."],"img":"opengym/8702.webp","gif":null,"ext":1},{"id":"8703","n":"battling rope pull","bp":"back","eq":"rope","tg":"lats","mg":"biceps","sm":["biceps","grip muscles","core","glutes"],"st":["Anchor the rope and hold the ends in a staggered stance.","Lean back slightly with your core tight.","Pull the rope toward you hand over hand.","Keep your chest tall and drive with your legs.","Return smoothly and repeat."],"img":"opengym/8703.webp","gif":null,"ext":1},{"id":"8704","n":"burpee jump box","bp":"full body","eq":"body weight","tg":"cardiovascular system","mg":"quadriceps","sm":["quadriceps","glutes","chest","shoulders","core"],"st":["Stand facing a box.","Drop into a squat, kick your feet back and lower into a push-up.","Jump your feet back in.","Explode up and jump onto the box.","Step down carefully and repeat."],"img":"opengym/8704.webp","gif":null,"ext":1},{"id":"8712","n":"lever romanian deadlift (plate loaded)","bp":"upper legs","eq":"leverage machine","tg":"hamstrings","mg":"glutes","sm":["glutes","lower back","grip muscles"],"st":["Stand in the machine and grip the handles with a flat back.","Keep a soft bend in your knees.","Hinge at the hips, pushing them back as you lower.","Stop when you feel the hamstrings stretch.","Drive your hips forward to stand."],"img":"opengym/8712.webp","gif":null,"ext":1},{"id":"8744","n":"seated alternate knee extension on chair","bp":"upper legs","eq":"body weight","tg":"quads","mg":"hip flexors","sm":["hip flexors","core"],"st":["Sit tall near the front of a sturdy chair with your feet flat on the floor.","Brace your core and keep your shoulders relaxed.","Straighten one knee by lifting the foot until the leg is level.","Squeeze your thigh, then lower slowly.","Switch legs and keep alternating."],"img":"opengym/8744.webp","gif":null,"ext":1},{"id":"8750","n":"ring pullover","bp":"back","eq":"suspension trainer","tg":"lats","mg":"biceps","sm":["biceps","chest","core"],"st":["Hang from the rings with an overhand grip.","Pull your hips up and bring your knees to your chest.","Rotate backward, pulling the body over the rings.","Lower under control.","Keep the movement smooth."],"img":"opengym/8750.webp","gif":null,"ext":1},{"id":"8755","n":"split squat heel raise","bp":"upper legs","eq":"body weight","tg":"quads","mg":"calves","sm":["calves","glutes","soleus"],"st":["Stand in a split stance with one foot well forward.","Lower into a split squat with an upright torso.","Push up through your front foot to stand.","Rise onto the toes of your back foot or both feet.","Lower your heel and repeat.","Finish your reps, then switch legs."],"img":"opengym/8755.webp","gif":null,"ext":1},{"id":"8798","n":"barbell lying seal row on rack","bp":"back","eq":"barbell","tg":"upper back","mg":"lats","sm":["lats","rhomboids","biceps","rear deltoids"],"st":["Lie face down on a raised bench so the bar hangs below you.","Grip the bar slightly wider than shoulders.","Row the bar up toward your chest by pulling elbows back.","Squeeze your shoulder blades together.","Lower slowly."],"img":"opengym/8798.webp","gif":null,"ext":1},{"id":"8799","n":"leverage single leg deadlift on hack squat machine","bp":"upper legs","eq":"leverage machine","tg":"hamstrings","mg":"glutes","sm":["glutes","lower back","quadriceps"],"st":["Step onto the machine platform and set your back against the pad.","Place one foot on the platform and lift the other slightly.","Hinge at the hip and lower with control.","Drive through the standing foot to come back up.","Squeeze your glute at the top.","Do your reps, then switch legs."],"img":"opengym/8799.webp","gif":null,"ext":1},{"id":"8800","n":"smith staggered stance romanian deadlift","bp":"upper legs","eq":"smith machine","tg":"hamstrings","mg":"glutes","sm":["glutes","lower back","grip muscles"],"st":["Stand under the smith bar with one foot slightly behind the other.","Grip the bar and unrack it.","Hinge at the hips with a flat back and the bar close to your legs.","Lower until you feel a stretch in the hamstrings.","Drive your hips forward to stand tall.","Switch which foot is forward after your set."],"img":"opengym/8800.webp","gif":null,"ext":1},{"id":"8847","n":"lever standing lateral raise","bp":"shoulders","eq":"leverage machine","tg":"delts","mg":"trapezius","sm":["trapezius","rotator cuff"],"st":["Stand in the machine with pads against your arms.","Keep your torso upright.","Raise your arms out to the sides to shoulder height.","Pause at the top.","Lower slowly."],"img":"opengym/8847.webp","gif":null,"ext":1},{"id":"8873","n":"weighted dumbbell lying knee raise","bp":"waist","eq":"dumbbell","tg":"abs","mg":"hip flexors","sm":["hip flexors","lower abs"],"st":["Lie on your back with a dumbbell secured between your feet.","Keep your lower back pressed down.","Bring your knees toward your chest.","Lower your feet slowly without touching the floor.","Repeat for controlled reps."],"img":"opengym/8873.webp","gif":null,"ext":1},{"id":"8874","n":"resistance band speed step","bp":"upper legs","eq":"band","tg":"glutes","mg":"quadriceps","sm":["quadriceps","calves"],"st":["Place a band around your thighs or ankles.","Stand in a quarter squat.","Take quick small steps to the side.","Keep tension on the band and your chest up.","Move in both directions."],"img":"opengym/8874.webp","gif":null,"ext":1},{"id":"8875","n":"cable lying single leg hip flexion","bp":"upper legs","eq":"cable","tg":"hip flexors","mg":"quadriceps","sm":["quadriceps","core"],"st":["Lie on your back with the ankle strap attached to the low cable and one foot in it.","Brace your core and press your lower back into the floor.","Pull the knee up toward your chest with control.","Pause briefly, then lower the leg slowly against the cable.","Keep the other leg relaxed and your hips still.","Finish all reps, then switch legs."],"img":"opengym/8875.webp","gif":null,"ext":1},{"id":"8876","n":"cable lying hip flexion (reverse squat)","bp":"upper legs","eq":"cable","tg":"hip flexors","mg":"quadriceps","sm":["quadriceps","glutes","core"],"st":["Lie on your back with the cable attached to both ankles or a strap around your feet.","Start with your legs extended and your core braced.","Pull your knees toward your chest in a smooth curl.","Pause at the top without lifting your head.","Lower your legs slowly until they are almost straight.","Keep your lower back flat on the floor throughout."],"img":"opengym/8876.webp","gif":null,"ext":1},{"id":"8877","n":"resistance band fingers extension","bp":"lower arms","eq":"resistance band","tg":"forearms","mg":"wrist extensors","sm":["wrist extensors","hands"],"st":["Loop a light band around your fingers and thumb of one hand.","Rest your forearm on a table or your thigh.","Start with the fingers curled in a relaxed fist.","Spread your fingers open against the band's pull.","Close them back slowly with control.","Do all reps, then switch hands."],"img":"opengym/8877.webp","gif":null,"ext":1},{"id":"8878","n":"cable 45 degrees reverse fly","bp":"shoulders","eq":"cable","tg":"delts","mg":"rear deltoids","sm":["rear deltoids","upper back","rhomboids"],"st":["Set two cable handles at a low or mid height and grab them crossed over.","Hinge forward at the hips to about 45 degrees with a flat back.","Keep a slight bend in your elbows.","Pull the handles out and back in a wide arc until your arms are in line with your torso.","Squeeze your shoulder blades gently at the end.","Return slowly and keep your torso still."],"img":"opengym/8878.webp","gif":null,"ext":1},{"id":"8879","n":"cable half kneeling external rotation press","bp":"shoulders","eq":"cable","tg":"delts","mg":"rotator cuff","sm":["rotator cuff","core","triceps"],"st":["Kneel on one knee side-on to the cable with the handle at chest height.","Hold the handle near your shoulder with your elbow bent.","Brace your core and keep your hips square.","Rotate your forearm outward, then press the handle overhead.","Return along the same path with control.","Finish your reps and switch sides."],"img":"opengym/8879.webp","gif":null,"ext":1},{"id":"8880","n":"cable standing jab","bp":"shoulders","eq":"cable","tg":"pectorals","mg":"shoulders","sm":["shoulders","triceps","core"],"st":["Stand facing away from the cable with the handle at chest height in one hand.","Take a staggered stance and keep your core tight.","Punch the handle forward quickly, rotating your hips a little.","Stop just before your elbow locks out.","Return the hand with control to your chin.","Do all reps, then switch arms."],"img":"opengym/8880.webp","gif":null,"ext":1},{"id":"8881","n":"cable forearm pronation","bp":"lower arms","eq":"cable","tg":"forearms","mg":"wrist flexors","sm":["wrist flexors","grip muscles"],"st":["Sit beside a low cable and hold the handle with your forearm resting on your thigh.","Start with your palm facing up and your wrist neutral.","Rotate your forearm so the palm turns down.","Pause, then rotate back slowly against the cable.","Keep your elbow still and move only the forearm.","Complete your reps and switch arms."],"img":"opengym/8881.webp","gif":null,"ext":1},{"id":"8882","n":"neutral wrist roller","bp":"lower arms","eq":"weighted","tg":"forearms","mg":"wrist flexors","sm":["wrist flexors","wrist extensors","grip muscles"],"st":["Hold the wrist roller with a neutral, thumbs-up grip and your arms out in front.","Let the weight hang from the rope with the rope unwound.","Roll the bar with your wrists to wind the rope up.","Keep your arms steady and your shoulders relaxed.","When the weight reaches the bar, lower it slowly by unwinding.","Stop if your forearms burn too much to keep control."],"img":"opengym/8882.webp","gif":null,"ext":1},{"id":"8891","n":"weighted bag good morning","bp":"upper legs","eq":"weighted","tg":"hamstrings","mg":"glutes","sm":["glutes","lower back","core"],"st":["Place the weighted bag across your upper back and hold it in place.","Stand with your feet hip width and your knees slightly bent.","Push your hips back and lower your torso with a flat back.","Go down until you feel a stretch in the hamstrings.","Drive your hips forward to stand tall again.","Keep your neck neutral all the way."],"img":"opengym/8891.webp","gif":null,"ext":1},{"id":"8892","n":"kettlebell staggered stance deadlift","bp":"upper legs","eq":"kettlebell","tg":"hamstrings","mg":"glutes","sm":["glutes","lower back","grip muscles"],"st":["Stand with one foot slightly behind the other.","Hold a kettlebell in front of your thighs.","Hinge at the hips and lower the bell toward the floor.","Keep your back flat and weight mostly on the front foot.","Drive your hips forward to stand tall.","Switch stances after your set."],"img":"opengym/8892.webp","gif":null,"ext":1},{"id":"8894","n":"knee tuck push up","bp":"chest","eq":"body weight","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders","core"],"st":["Start in a push-up position with a straight body.","Lower your chest toward the floor.","Press back up.","Pull one knee toward your chest.","Return the leg and repeat on the other side.","Keep your hips level."],"img":"opengym/8894.webp","gif":null,"ext":1},{"id":"8895","n":"45 degrees back extension scapular adduction","bp":"back","eq":"body weight","tg":"spine","mg":"rhomboids","sm":["rhomboids","glutes","hamstrings"],"st":["Set up on the 45 degree bench with your hips on the pad and your feet locked in.","Cross your arms or hold them out wide.","Raise your torso until your body forms a straight line.","At the top, pull your shoulder blades together.","Lower back down slowly without rounding.","Do not overarch at the top."],"img":"opengym/8895.webp","gif":null,"ext":1},{"id":"8896","n":"bent over back extension scapular adduction","bp":"back","eq":"body weight","tg":"spine","mg":"rhomboids","sm":["rhomboids","glutes","hamstrings"],"st":["Stand and hinge forward with a flat back and your arms hanging.","Keep your knees softly bent.","Raise your torso toward upright.","At the top, pull your shoulder blades together.","Lower back to the bent over position slowly.","Keep your neck in line with your spine."],"img":"opengym/8896.webp","gif":null,"ext":1},{"id":"8899","n":"cable standing y raise v. 2","bp":"shoulders","eq":"cable","tg":"delts","mg":"trapezius","sm":["trapezius","rotator cuff","upper back"],"st":["Stand facing the low cable with a handle in each hand or one handle at a time.","Start with your arms low and a slight bend in your elbows.","Lift your arms up and out to form a Y shape.","Keep your thumbs pointing up and your ribs down.","Lower slowly back to the start.","Avoid shrugging toward your ears."],"img":"opengym/8899.webp","gif":null,"ext":1},{"id":"8900","n":"cable standing jab v. 2","bp":"shoulders","eq":"cable","tg":"pectorals","mg":"shoulders","sm":["shoulders","triceps","core"],"st":["Stand facing away from the cable and hold the handle at chest height.","Step into a staggered stance and brace your core.","Punch forward fast and rotate your torso slightly.","Stop short of locking out your elbow.","Pull the hand back under control.","Repeat, then switch arms."],"img":"opengym/8900.webp","gif":null,"ext":1},{"id":"8901","n":"cable single arm lateral raise v. 2","bp":"shoulders","eq":"cable","tg":"delts","mg":"trapezius","sm":["trapezius","rotator cuff"],"st":["Stand side-on to the low cable and hold the handle with the far hand.","Keep a slight bend in your elbow.","Raise your arm out to the side up to shoulder height.","Pause briefly at the top.","Lower slowly against the cable.","Avoid leaning or swinging, then switch arms."],"img":"opengym/8901.webp","gif":null,"ext":1},{"id":"8916","n":"side to side hop v. 2","bp":"full body","eq":"body weight","tg":"cardiovascular system","mg":"quadriceps","sm":["quadriceps","calves","glutes"],"st":["Stand on two feet with your knees slightly bent.","Hop sideways to one side, landing softly on the balls of your feet.","Immediately hop back to the other side.","Keep your chest up and your hips low.","Use your arms for balance and rhythm.","Go for a set time or a set number of reps."],"img":"opengym/8916.webp","gif":null,"ext":1},{"id":"8946","n":"seated single leg raise","bp":"upper legs","eq":"body weight","tg":"hip flexors","mg":"quadriceps","sm":["quadriceps","core"],"st":["Sit tall on the edge of a bench with your hands beside you.","Extend one leg straight out in front.","Lift the leg a few inches higher while keeping the knee straight.","Pause and lower it slowly.","Keep your back straight and your core tight.","Finish all reps, then switch legs."],"img":"opengym/8946.webp","gif":null,"ext":1},{"id":"8956","n":"heels squat slide wall","bp":"upper legs","eq":"body weight","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","calves"],"st":["Stand with your back against a wall and your feet a little forward.","Press your heels into the floor.","Slide down the wall until your thighs are near parallel.","Keep your knees tracking over your toes.","Press through your heels to slide back up.","Keep your back in contact with the wall."],"img":"opengym/8956.webp","gif":null,"ext":1},{"id":"8971","n":"side lunge stretch v. 2","bp":"upper legs","eq":"body weight","tg":"adductors","mg":"groin","sm":["groin","inner thighs","hamstrings"],"st":["Stand with your feet wide apart and toes pointing forward.","Shift your weight to one side and bend that knee.","Keep the other leg straight with the foot flat or toes up.","Sit your hips back and feel the stretch on the inner thigh.","Hold for 20-30 seconds.","Switch sides and repeat."],"img":"opengym/8971.webp","gif":null,"ext":1},{"id":"8987","n":"half kneeling side lunge","bp":"upper legs","eq":"body weight","tg":"adductors","mg":"groin","sm":["groin","glutes","quadriceps"],"st":["Start in a half kneeling position with one knee down and the other foot forward.","Turn your front foot out to the side.","Shift your hips sideways toward the straight leg.","Keep your chest up and feel the inner thigh open.","Return to the center with control.","Do all reps, then switch sides."],"img":"opengym/8987.webp","gif":null,"ext":1},{"id":"8990","n":"lever side seated single arm rear delt fly","bp":"shoulders","eq":"leverage machine","tg":"delts","mg":"rear deltoids","sm":["rear deltoids","upper back","rhomboids"],"st":["Sit sideways on the machine with your chest against the pad.","Grab the handle with the outside hand.","Start with your arm in front of you and a soft bend in your elbow.","Pull the handle out and back until your arm is in line with your shoulder.","Return slowly without letting the weight stack touch down.","Finish the reps, then switch sides."],"img":"opengym/8990.webp","gif":null,"ext":1},{"id":"8991","n":"barbell zercher back extension","bp":"back","eq":"barbell","tg":"spine","mg":"glutes","sm":["glutes","hamstrings","core"],"st":["Hold the barbell in the crook of your elbows against your chest.","Set up on a back extension bench with your hips on the pad.","Lower your torso with a flat back until you feel a hamstring stretch.","Raise your torso until your body is in a straight line.","Avoid hyperextending at the top.","Use a light weight and control the bar."],"img":"opengym/8991.webp","gif":null,"ext":1},{"id":"9002","n":"bird dog plank","bp":"waist","eq":"body weight","tg":"abs","mg":"core","sm":["core","glutes","shoulders"],"st":["Get into a plank on your hands or forearms with your body in a line.","Brace your core and squeeze your glutes.","Lift one arm forward and the opposite leg back.","Keep your hips level and do not twist.","Hold for a few seconds.","Return and switch sides."],"img":"opengym/9002.webp","gif":null,"ext":1},{"id":"9009","n":"reverse hyperextension on stability ball","bp":"upper legs","eq":"stability ball","tg":"glutes","mg":"hamstrings","sm":["hamstrings","lower back","core"],"st":["Lie face down over the ball with your hands on the floor.","Let your legs hang down with your toes light on the floor.","Squeeze your glutes and raise both legs until they are in line with your body.","Pause at the top.","Lower slowly without swinging.","Keep your hands planted and your core tight."],"img":"opengym/9009.webp","gif":null,"ext":1},{"id":"9010","n":"medicine ball crunch on stability ball","bp":"waist","eq":"medicine ball","tg":"abs","mg":"core","sm":["core","hip flexors"],"st":["Sit on the ball and roll down until your lower back is supported.","Hold the medicine ball against your chest or overhead.","Brace your core and crunch your ribs toward your hips.","Pause at the top.","Lower back over the ball with control.","Keep your feet firmly on the floor."],"img":"opengym/9010.webp","gif":null,"ext":1},{"id":"9024","n":"lying abdominal scissors crunch","bp":"waist","eq":"body weight","tg":"abs","mg":"lower abs","sm":["lower abs","hip flexors","obliques"],"st":["Lie on your back with your hands behind your head.","Lift your shoulders and your legs slightly off the floor.","Scissor your legs up and down in alternating motion.","Crunch your ribs toward your hips.","Keep your lower back pressed down.","Continue for a set count of reps."],"img":"opengym/9024.webp","gif":null,"ext":1},{"id":"9025","n":"sitting woodchopper on stability ball","bp":"waist","eq":"stability ball","tg":"obliques","mg":"core","sm":["core","shoulders"],"st":["Sit tall on the ball with your feet wide.","Hold the weight or handle high on one side.","Rotate and chop diagonally down to the opposite hip.","Keep your arms mostly straight and your hips steady.","Return along the same path.","Complete your reps, then switch sides."],"img":"opengym/9025.webp","gif":null,"ext":1},{"id":"9040","n":"sprint against wall","bp":"cardio","eq":"body weight","tg":"cardiovascular system","mg":"hip flexors","sm":["hip flexors","quadriceps","calves"],"st":["Place your hands on a wall and lean forward with a straight body line.","Brace your core.","Drive one knee up while the other leg stays extended.","Switch legs quickly in a running rhythm.","Keep your hips level.","Go hard for 10-20 seconds, then rest."],"img":"opengym/9040.webp","gif":null,"ext":1},{"id":"9041","n":"smith front leg elevated split squat","bp":"upper legs","eq":"smith machine","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","adductors"],"st":["Set a low platform under the smith bar and put your front foot on it.","Place the bar across your upper back and unrack it.","Step the back foot behind you.","Lower your back knee toward the floor.","Press through the front heel to stand.","Do all reps, then switch legs."],"img":"opengym/9041.webp","gif":null,"ext":1},{"id":"9042","n":"smith elevated split squat","bp":"upper legs","eq":"smith machine","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","adductors"],"st":["Place a bench behind the smith machine and rest your back foot on it.","Position the bar on your upper back and unrack it.","Step the front foot forward.","Lower your hips until the front thigh is near parallel.","Drive up through the front foot.","Complete the reps, then switch legs."],"img":"opengym/9042.webp","gif":null,"ext":1},{"id":"9043","n":"hanging tucked front lever hold","bp":"waist","eq":"body weight","tg":"abs","mg":"lats","sm":["lats","core","shoulders"],"st":["Hang from a pull-up bar with an overhand grip.","Pull your shoulder blades down and tuck your knees to your chest.","Lean back and raise your hips until your back is horizontal.","Keep your arms straight.","Hold for 5-15 seconds.","Lower back down with control."],"img":"opengym/9043.webp","gif":null,"ext":1},{"id":"9044","n":"hanging advanced tucked front lever hold","bp":"waist","eq":"body weight","tg":"abs","mg":"lats","sm":["lats","core","shoulders"],"st":["Hang from a pull-up bar with straight arms.","Lift your body to horizontal in a tucked position.","Open your hips slightly so your back is flat.","Keep your shoulder blades pulled down.","Hold for 5-10 seconds.","Lower down slowly."],"img":"opengym/9044.webp","gif":null,"ext":1},{"id":"9045","n":"hanging front lever hold","bp":"waist","eq":"body weight","tg":"abs","mg":"lats","sm":["lats","core","shoulders"],"st":["Hang from a pull-up bar with an overhand grip.","Pull your shoulder blades down and tighten your core.","Raise your whole body to horizontal with your legs straight.","Keep your arms locked and your body in one line.","Hold for as long as you can with good form.","Lower down slowly."],"img":"opengym/9045.webp","gif":null,"ext":1},{"id":"9047","n":"straight hip single leg curl on stability ball","bp":"upper legs","eq":"stability ball","tg":"hamstrings","mg":"glutes","sm":["glutes","core","calves"],"st":["Lie on your back with one heel on the ball and the other leg raised.","Lift your hips so your body forms a line.","Curl the ball toward your glutes with the one leg.","Keep your hips high.","Extend the leg slowly back out.","Finish the reps and switch legs."],"img":"opengym/9047.webp","gif":null,"ext":1},{"id":"9048","n":"mountain climber cross kick","bp":"full body","eq":"body weight","tg":"abs","mg":"obliques","sm":["obliques","hip flexors","shoulders"],"st":["Start in a high plank with your hands under your shoulders.","Brace your core.","Drive one knee across your body toward the opposite elbow.","Return the foot and switch legs quickly.","Keep your hips low and level.","Keep up a steady pace for a set time."],"img":"opengym/9048.webp","gif":null,"ext":1},{"id":"9049","n":"incline hip raise","bp":"waist","eq":"body weight","tg":"abs","mg":"lower abs","sm":["lower abs","hip flexors"],"st":["Lie on an incline bench and hold the top edge behind your head.","Bring your legs up so your knees are over your hips.","Curl your pelvis up to lift your hips off the bench.","Pause at the top.","Lower slowly without swinging.","Keep the movement small and controlled."],"img":"opengym/9049.webp","gif":null,"ext":1},{"id":"9066","n":"4 way single leg hop","bp":"lower legs","eq":"body weight","tg":"calves","mg":"quadriceps","sm":["quadriceps","glutes","ankles"],"st":["Stand on one leg with a soft knee.","Hop forward and land softly.","Hop back to the start, then hop to each side.","Hold each landing for a moment.","Keep your chest up and your knee over your foot.","Repeat the pattern, then switch legs."],"img":"opengym/9066.webp","gif":null,"ext":1},{"id":"9070","n":"pogo jump 2 foot","bp":"lower legs","eq":"body weight","tg":"calves","mg":"soleus","sm":["soleus","ankles","quadriceps"],"st":["Stand tall with your knees nearly straight.","Hop off the balls of your feet.","Keep your heels off the ground.","Bounce quickly with minimal knee bend.","Stay light and quiet on landing.","Go for a set time or number of hops."],"img":"opengym/9070.webp","gif":null,"ext":1},{"id":"9180","n":"stick standing shoulder mobilization in extension","bp":"shoulders","eq":"body weight","tg":"delts","mg":"chest","sm":["chest","rotator cuff"],"st":["Stand tall holding a stick behind your back with an overhand grip.","Keep your arms straight.","Lift the stick back and away from your body.","Stay tall and avoid leaning forward.","Hold for a moment.","Lower slowly and repeat."],"img":"opengym/9180.webp","gif":null,"ext":1},{"id":"9181","n":"stick standing shoulder mobilization in external rotation","bp":"shoulders","eq":"body weight","tg":"delts","mg":"rotator cuff","sm":["rotator cuff","rear deltoids"],"st":["Stand holding a stick with both hands, elbows tucked at your sides and bent.","Push the stick with the stronger hand to rotate the other arm outward.","Keep your elbow glued to your side.","Move only as far as is comfortable.","Return to the start slowly.","Switch sides and repeat."],"img":"opengym/9181.webp","gif":null,"ext":1},{"id":"9184","n":"stick shoulder mobilization in abduction","bp":"shoulders","eq":"body weight","tg":"delts","mg":"rotator cuff","sm":["rotator cuff","lats"],"st":["Hold a stick with both hands in front of you.","Keep one arm relaxed and guide it with the other.","Raise the stick sideways and up.","Keep your torso upright.","Pause at the top.","Lower and switch sides."],"img":"opengym/9184.webp","gif":null,"ext":1},{"id":"9185","n":"standing alternating shoulder flexion with rope","bp":"shoulders","eq":"rope","tg":"delts","mg":"upper back","sm":["upper back","core","forearms"],"st":["Stand tall holding a rope in one hand at your side.","Raise your arm forward to shoulder height or above.","Hold briefly at the top.","Lower it slowly.","Alternate arms each rep.","Keep your ribs down and shoulders relaxed."],"img":"opengym/9185.webp","gif":null,"ext":1},{"id":"9187","n":"stick standing front raise","bp":"shoulders","eq":"body weight","tg":"delts","mg":"upper chest","sm":["upper chest","trapezius"],"st":["Stand tall holding a stick at your thighs with an overhand grip.","Keep your arms straight.","Raise the stick in front of you to shoulder height or above.","Keep your ribs down and your core tight.","Lower slowly to the start.","Repeat for smooth reps."],"img":"opengym/9187.webp","gif":null,"ext":1},{"id":"9213","n":"dumbbell lying straight arm press on floor","bp":"chest","eq":"dumbbell","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders","core"],"st":["Lie on the floor with a dumbbell in each hand above your chest.","Keep your arms straight and your wrists strong.","Lower your arms slightly and then press back up.","Squeeze your chest at the top.","Keep your feet planted and core tight.","Control the weights through each rep."],"img":"opengym/9213.webp","gif":null,"ext":1},{"id":"9246","n":"wide stance thoracic rotation","bp":"waist","eq":"body weight","tg":"spine","mg":"obliques","sm":["obliques","core","upper back"],"st":["Stand with your feet wide and your knees slightly bent.","Hinge slightly forward with your hands behind your head.","Rotate your chest to one side as far as you can.","Keep your hips facing forward.","Return to the center.","Rotate to the other side and repeat."],"img":"opengym/9246.webp","gif":null,"ext":1},{"id":"9248","n":"forward backward shuffle","bp":"cardio","eq":"body weight","tg":"cardiovascular system","mg":"quadriceps","sm":["quadriceps","glutes","calves"],"st":["Stand in an athletic stance with soft knees.","Shuffle forward a few steps on the balls of your feet.","Shuffle back to the start without crossing your feet.","Keep your hips low and your chest up.","Move quickly but stay balanced.","Repeat for a set time."],"img":"opengym/9248.webp","gif":null,"ext":1},{"id":"9272","n":"sitting floor tibialis raise","bp":"lower legs","eq":"body weight","tg":"shins","mg":"calves","sm":["calves","ankles"],"st":["Sit on the floor with your legs straight and your hands behind you.","Keep your heels on the floor.","Pull your toes up toward your shins.","Hold for a moment.","Lower the toes slowly.","Repeat for the set."],"img":"opengym/9272.webp","gif":null,"ext":1},{"id":"9304","n":"cable neutral grip wide pulldown v. 3","bp":"back","eq":"cable","tg":"lats","mg":"biceps","sm":["biceps","upper back","rhomboids"],"st":["Sit at the pulldown station with your thighs under the pads.","Grab the wide neutral grip handles.","Lean back slightly and keep your chest up.","Pull the handles down toward your upper chest.","Squeeze your lats at the bottom.","Let the handles rise slowly with control."],"img":"opengym/9304.webp","gif":null,"ext":1},{"id":"9310","n":"standing isometric hold calf raise","bp":"lower legs","eq":"body weight","tg":"calves","mg":"soleus","sm":["soleus","ankles","feet"],"st":["Stand tall with your feet hip width apart.","Rise onto the balls of your feet.","Hold the top position for 20 to 30 seconds.","Keep your ankles straight and stable.","Lower your heels slowly.","Rest briefly between holds."],"img":"opengym/9310.webp","gif":null,"ext":1},{"id":"9311","n":"isometric hold wide hand push up","bp":"chest","eq":"body weight","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders","core"],"st":["Start in a push-up position with hands wider than your shoulders.","Lower your chest until your elbows are bent.","Hold this position for 10 to 20 seconds.","Keep your body in a straight line.","Press back up to the start.","Rest and repeat."],"img":"opengym/9311.webp","gif":null,"ext":1},{"id":"9312","n":"high bar incline push up","bp":"chest","eq":"body weight","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders","core"],"st":["Set a bar at about waist or chest height.","Place your hands on it slightly wider than your shoulders.","Walk your feet back so your body is in a straight line.","Lower your chest to the bar.","Press back up to straight arms.","Keep your core and glutes tight."],"img":"opengym/9312.webp","gif":null,"ext":1},{"id":"9313","n":"ring isometric hold reverse ab rollout","bp":"waist","eq":"suspension trainer","tg":"abs","mg":"core","sm":["core","lats","shoulders"],"st":["Hang or set yourself up with the rings under your forearms.","Brace your core and tuck your pelvis.","Move into the rollout position and stop.","Keep your body in a straight line.","Hold for 10-20 seconds.","Return slowly."],"img":"opengym/9313.webp","gif":null,"ext":1},{"id":"9314","n":"45 degree hip extension glute focused v. 2","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"hamstrings","sm":["hamstrings","lower back"],"st":["Set the pad at hip height and lock your heels in.","Cross your arms over your chest.","Hinge forward at the hips with a straight back.","Drive your hips forward and squeeze your glutes.","Stop when your body is in a straight line.","Lower slowly each rep."],"img":"opengym/9314.webp","gif":null,"ext":1},{"id":"9315","n":"elevated split squat","bp":"upper legs","eq":"body weight","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","adductors"],"st":["Stand a stride length in front of a bench and rest your back foot on it.","Keep your torso upright.","Lower your back knee toward the floor.","Keep your front knee over your foot.","Drive through the front heel to stand.","Finish the reps, then switch legs."],"img":"opengym/9315.webp","gif":null,"ext":1},{"id":"9316","n":"ring elevated pike push up from deficit","bp":"shoulders","eq":"suspension trainer","tg":"delts","mg":"triceps","sm":["triceps","upper chest","core"],"st":["Set the rings low and put your hands on them with your feet on a box.","Raise your hips into a pike shape.","Lower your head between the rings.","Keep the rings steady and close to your body.","Press back up to straight arms.","Keep your core tight."],"img":"opengym/9316.webp","gif":null,"ext":1},{"id":"9317","n":"seated isometric hold pull up","bp":"back","eq":"body weight","tg":"lats","mg":"biceps","sm":["biceps","upper back","grip muscles"],"st":["Set up a bar so you can sit under it.","Grab the bar with an overhand grip.","Pull yourself up until your chin is above the bar.","Hold the top position.","Hold for 5-10 seconds.","Lower down slowly."],"img":"opengym/9317.webp","gif":null,"ext":1},{"id":"9318","n":"lying floor negative dragon flag","bp":"waist","eq":"body weight","tg":"abs","mg":"lower abs","sm":["lower abs","core","lats"],"st":["Lie on a mat and hold something fixed behind your head.","Raise your body into a straight line on your upper back.","Brace your core.","Lower your body slowly keeping it straight.","Stop just above the floor.","Bring your legs back up and reset."],"img":"opengym/9318.webp","gif":null,"ext":1},{"id":"9319","n":"lying floor negative half dragon flag","bp":"waist","eq":"body weight","tg":"abs","mg":"lower abs","sm":["lower abs","core","lats"],"st":["Lie on a mat and hold something fixed behind your head.","Lift your hips and tuck your knees.","Brace your core.","Lower your body slowly with bent knees.","Stop just above the floor.","Reset and repeat."],"img":"opengym/9319.webp","gif":null,"ext":1},{"id":"9320","n":"isometric hold close grip chin up","bp":"back","eq":"body weight","tg":"lats","mg":"biceps","sm":["biceps","forearms","upper back"],"st":["Grip the bar with palms facing you and hands close together.","Pull yourself up until your chin is over the bar.","Hold for 5 to 15 seconds.","Keep your shoulders down and core tight.","Lower slowly under control.","Rest and repeat."],"img":"opengym/9320.webp","gif":null,"ext":1},{"id":"9321","n":"lying floor horizontal flutter kick","bp":"waist","eq":"body weight","tg":"abs","mg":"lower abs","sm":["lower abs","hip flexors","quadriceps"],"st":["Lie on your back with your legs straight and hands under your hips.","Lift your feet a few inches off the floor.","Kick your legs up and down in small alternating motions.","Keep your lower back pressed down.","Breathe steadily.","Continue for 20 to 40 seconds."],"img":"opengym/9321.webp","gif":null,"ext":1},{"id":"9322","n":"lying floor single leg negative dragon flag","bp":"waist","eq":"body weight","tg":"abs","mg":"lower abs","sm":["lower abs","core","lats"],"st":["Lie on a mat and hold something fixed behind your head.","Raise your body into a straight line with one leg tucked.","Extend the other leg straight.","Lower slowly while keeping your hips level.","Stop just above the floor.","Reset and switch legs."],"img":"opengym/9322.webp","gif":null,"ext":1},{"id":"9323","n":"wide bench air squat","bp":"upper legs","eq":"body weight","tg":"quads","mg":"glutes","sm":["glutes","adductors","hamstrings"],"st":["Stand in front of a bench with your feet wide and toes turned out.","Push your hips back and lower down.","Lightly touch the bench.","Keep your knees tracking over your toes.","Press through your heels to stand.","Keep your chest tall."],"img":"opengym/9323.webp","gif":null,"ext":1},{"id":"9324","n":"long lever standing hip extension","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"hamstrings","sm":["hamstrings","core","lower back"],"st":["Stand tall holding a support if needed.","Keep your leg straight.","Lift it back behind you.","Stop when your hips begin to tilt.","Squeeze your glute at the top.","Lower it slowly and switch legs."],"img":"opengym/9324.webp","gif":null,"ext":1},{"id":"9325","n":"isometric hold push up","bp":"chest","eq":"body weight","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders","core"],"st":["Start in a straight-arm plank with hands under your shoulders.","Lower halfway down until your elbows are bent.","Hold the position for 10 to 20 seconds.","Keep your body straight from head to heels.","Press back up.","Rest and repeat."],"img":"opengym/9325.webp","gif":null,"ext":1},{"id":"9359","n":"single leg hamstring bridge","bp":"upper legs","eq":"body weight","tg":"hamstrings","mg":"glutes","sm":["glutes","core","lower back"],"st":["Lie on your back with one foot flat and the other leg raised.","Press your heel into the floor.","Lift your hips until your body forms a line.","Squeeze your glutes at the top.","Lower slowly.","Finish the reps, then switch legs."],"img":"opengym/9359.webp","gif":null,"ext":1},{"id":"9385","n":"smith jm bench press","bp":"upper arms","eq":"smith machine","tg":"triceps","mg":"chest","sm":["chest","shoulders","forearms"],"st":["Lie on a bench under the smith bar with a shoulder width grip.","Unrack the bar over your chest.","Lower the bar toward your chin or upper chest by bending your elbows.","Keep your elbows slightly in.","Press the bar back up.","Use a light weight and control the path."],"img":"opengym/9385.webp","gif":null,"ext":1},{"id":"9387","n":"lever angled single leg press","bp":"upper legs","eq":"leverage machine","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","adductors"],"st":["Sit on the machine and place one foot on the platform.","Release the safety handles.","Lower the platform until your knee is bent about 90 degrees.","Press through your heel to push it back.","Do not lock your knee at the top.","Finish the reps, then switch legs."],"img":"opengym/9387.webp","gif":null,"ext":1},{"id":"9398","n":"lever standing pec fly","bp":"chest","eq":"leverage machine","tg":"pectorals","mg":"upper chest","sm":["upper chest","shoulders","biceps"],"st":["Stand in the machine with your hands on the handles.","Keep your elbows slightly bent.","Bring the handles together in front of your chest.","Squeeze your chest at the end.","Return slowly until you feel a stretch.","Keep your chest tall and your back still."],"img":"opengym/9398.webp","gif":null,"ext":1},{"id":"9408","n":"repeated small jumps","bp":"cardio","eq":"body weight","tg":"cardiovascular system","mg":"calves","sm":["calves","quadriceps","ankles"],"st":["Stand tall with feet hip-width apart and arms relaxed at your sides.","Hop up a few centimetres by pushing through the balls of your feet.","Land softly on the balls of your feet and rebound straight away.","Keep your knees almost straight and your chest tall.","Continue for 20-30 seconds at a quick, steady rhythm."],"img":"opengym/9408.webp","gif":null,"ext":1},{"id":"9409","n":"standing bent knee calf raise with a chair support","bp":"lower legs","eq":"body weight","tg":"calves","mg":"soleus","sm":["soleus","ankles","feet"],"st":["Stand behind a chair and hold it for balance.","Bend your knees slightly.","Raise your heels as high as you can.","Pause at the top.","Lower your heels slowly.","Keep your knees bent throughout."],"img":"opengym/9409.webp","gif":null,"ext":1},{"id":"9410","n":"barbell standing bent knee calf raise from deficit","bp":"lower legs","eq":"barbell","tg":"calves","mg":"soleus","sm":["soleus","ankles","feet"],"st":["Rest a barbell across your upper back and stand with the balls of your feet on a low platform.","Soften your knees into a slight bend and keep that angle throughout.","Lower your heels below the platform until you feel a stretch in your calves.","Press up onto your toes as high as you can.","Pause briefly at the top, then lower slowly with control."],"img":"opengym/9410.webp","gif":null,"ext":1},{"id":"9411","n":"standing bent knee alternating calf raise with a chair support","bp":"lower legs","eq":"body weight","tg":"calves","mg":"soleus","sm":["soleus","ankles","feet"],"st":["Stand behind a chair and hold it with both hands.","Bend your knees slightly.","Raise one heel as high as possible.","Lower it slowly.","Raise the other heel.","Keep alternating without locking your knees."],"img":"opengym/9411.webp","gif":null,"ext":1},{"id":"9451","n":"lying floor 6 inch hold","bp":"waist","eq":"body weight","tg":"abs","mg":"lower abs","sm":["lower abs","hip flexors","core"],"st":["Lie on your back with your legs straight and arms by your sides.","Press your lower back into the floor and brace your abs.","Lift your heels and shoulders about 15 cm off the floor.","Keep your lower back flat and breathe steadily.","Hold for 20-30 seconds, then lower and rest."],"img":"opengym/9451.webp","gif":null,"ext":1},{"id":"9484","n":"dumbbell romanian deadlift to squat","bp":"upper legs","eq":"dumbbell","tg":"hamstrings","mg":"glutes","sm":["glutes","quadriceps","lower back","grip muscles"],"st":["Stand holding a dumbbell in each hand in front of your thighs.","Push your hips back and lower the weights along your legs with a flat back.","Feel the hamstring stretch, then drive your hips forward to stand.","Bend your knees and sit down into a squat with your chest up.","Stand back up and repeat the sequence."],"img":"opengym/9484.webp","gif":null,"ext":1},{"id":"9485","n":"kettlebell romanian deadlift to squat","bp":"upper legs","eq":"kettlebell","tg":"hamstrings","mg":"glutes","sm":["glutes","quadriceps","lower back","grip muscles"],"st":["Hold a kettlebell with both hands in front of your thighs.","Hinge at the hips and slide the bell down your legs with a flat back.","Squeeze your glutes to return to standing.","Bend your knees and lower into a squat, keeping the bell close to your chest.","Stand up and repeat for the planned reps."],"img":"opengym/9485.webp","gif":null,"ext":1},{"id":"9486","n":"dish hold","bp":"waist","eq":"body weight","tg":"abs","mg":"lower abs","sm":["lower abs","hip flexors","core"],"st":["Lie on your back with arms overhead and legs straight.","Press your lower back into the floor and tighten your abs.","Lift your arms, shoulders and legs a few centimetres off the floor.","Keep your body in a shallow dish shape and breathe.","Hold for 20-30 seconds, then relax."],"img":"opengym/9486.webp","gif":null,"ext":1},{"id":"9487","n":"sitting floor leg raise","bp":"waist","eq":"body weight","tg":"abs","mg":"lower abs","sm":["lower abs","hip flexors","quadriceps"],"st":["Sit on the floor with your hands planted behind your hips and legs extended.","Lean back slightly and brace your abs.","Raise both legs together a short way off the floor.","Lower them slowly without letting your heels drop to the ground.","Repeat for the planned reps."],"img":"opengym/9487.webp","gif":null,"ext":1},{"id":"9488","n":"pike stand","bp":"shoulders","eq":"body weight","tg":"delts","mg":"upper back","sm":["upper back","hamstrings","core"],"st":["Start on all fours and walk your feet in while lifting your hips high.","Form an upside-down V with straight arms and legs.","Press the floor away and let your head hang between your arms.","Keep your heels reaching toward the floor.","Hold for 20-30 seconds while breathing slowly."],"img":"opengym/9488.webp","gif":null,"ext":1},{"id":"9489","n":"hanging side lean","bp":"waist","eq":"body weight","tg":"obliques","mg":"abdominals","sm":["abdominals","lats","grip muscles"],"st":["Hang from a pull-up bar with an overhand grip and legs together.","Brace your abs and keep your arms straight.","Lean your legs and hips toward one side, bending through the waist.","Return to centre under control.","Lean to the other side and alternate for the planned reps."],"img":"opengym/9489.webp","gif":null,"ext":1},{"id":"9491","n":"cable side lying single arm lateral raise","bp":"shoulders","eq":"cable","tg":"delts","mg":"rear deltoids","sm":["rear deltoids","rotator cuff","upper back"],"st":["Set a low pulley and lie on your side with the handle in your top hand.","Keep your arm straight or slightly bent.","Raise the handle in an arc up to about shoulder height or a bit higher.","Pause briefly at the top.","Lower slowly, finish your reps, then switch sides."],"img":"opengym/9491.webp","gif":null,"ext":1},{"id":"9492","n":"cable lying upright row (sz bar)","bp":"shoulders","eq":"cable","tg":"delts","mg":"trapezius","sm":["trapezius","biceps","upper back"],"st":["Lie on your back with your feet toward a low pulley and grip the SZ bar.","Start with arms extended over your thighs.","Pull the bar up toward your chin, leading with your elbows.","Pause when your elbows reach shoulder height.","Lower the bar slowly to the start."],"img":"opengym/9492.webp","gif":null,"ext":1},{"id":"9493","n":"lever belt sumo squat","bp":"upper legs","eq":"leverage machine","tg":"glutes","mg":"quadriceps","sm":["quadriceps","adductors","inner thighs","hamstrings"],"st":["Attach the belt around your hips and stand with a wide stance, toes out.","Keep your chest tall and brace your core.","Bend your knees and sit down between your legs.","Lower until your thighs are about parallel.","Drive through your feet to stand up."],"img":"opengym/9493.webp","gif":null,"ext":1},{"id":"9494","n":"lever belt romanian deadlift","bp":"upper legs","eq":"leverage machine","tg":"hamstrings","mg":"glutes","sm":["glutes","lower back","quadriceps"],"st":["Wear the belt and stand tall with soft knees.","Push your hips back and lower your torso with a flat back.","Stop when you feel a stretch in the hamstrings.","Squeeze your glutes and drive your hips forward to stand.","Repeat with smooth control."],"img":"opengym/9494.webp","gif":null,"ext":1},{"id":"9503","n":"suspender rear delt row","bp":"shoulders","eq":"suspension trainer","tg":"delts","mg":"rear deltoids","sm":["rear deltoids","upper back","rhomboids","biceps"],"st":["Hold the handles and lean back with arms straight and body in a line.","Brace your core and glutes.","Pull your hands toward your chest with elbows flared out wide.","Squeeze your shoulder blades together.","Lower slowly until your arms are straight again."],"img":"opengym/9503.webp","gif":null,"ext":1},{"id":"9509","n":"lever sitting toe raise","bp":"lower legs","eq":"leverage machine","tg":"shins","mg":"soleus","sm":["soleus","ankles","feet"],"st":["Sit at the machine with the pads over your thighs and balls of your feet on the platform.","Lower your heels for a calf stretch.","Press up onto your toes as high as you can.","Pause briefly at the top.","Lower slowly and repeat."],"img":"opengym/9509.webp","gif":null,"ext":1},{"id":"9510","n":"partner assisted pull up","bp":"back","eq":"assisted","tg":"lats","mg":"biceps","sm":["biceps","upper back","forearms"],"st":["Hang from a pull-up bar with an overhand grip.","Have your partner hold your legs or hips.","Pull your chest toward the bar.","Pause at the top.","Lower yourself slowly.","Ask your partner to give just enough help."],"img":"opengym/9510.webp","gif":null,"ext":1},{"id":"9511","n":"box assisted pull up","bp":"back","eq":"body weight","tg":"lats","mg":"biceps","sm":["biceps","upper back","forearms"],"st":["Place a box under a pull-up bar.","Grip the bar and rest one or both feet on the box.","Pull up until your chin clears the bar.","Use your legs as little as possible.","Lower slowly.","Keep your core tight."],"img":"opengym/9511.webp","gif":null,"ext":1},{"id":"9512","n":"box single leg assisted pull up","bp":"back","eq":"body weight","tg":"lats","mg":"biceps","sm":["biceps","upper back","forearms"],"st":["Place a box under a pull-up bar.","Grip the bar and rest one foot on the box.","Pull up until your chin clears the bar.","Push lightly with the foot on the box.","Lower slowly.","Switch the assisting leg on the next set."],"img":"opengym/9512.webp","gif":null,"ext":1},{"id":"9513","n":"countermovement jump arms pull","bp":"upper legs","eq":"body weight","tg":"quads","mg":"glutes","sm":["glutes","calves","hamstrings"],"st":["Stand with feet shoulder-width apart and arms back.","Dip quickly into a quarter squat while swinging your arms down and back.","Swing your arms forward and up as you explode off the floor.","Extend fully through hips, knees and ankles.","Land softly with bent knees and reset."],"img":"opengym/9513.webp","gif":null,"ext":1},{"id":"9514","n":"countermovement jump arms on hip","bp":"upper legs","eq":"body weight","tg":"quads","mg":"glutes","sm":["glutes","calves","hamstrings"],"st":["Stand with feet shoulder-width apart and hands on your hips.","Dip quickly into a quarter squat.","Explode upward, extending hips, knees and ankles.","Reach for maximum height without using your arms.","Land softly on bent knees and reset."],"img":"opengym/9514.webp","gif":null,"ext":1},{"id":"9515","n":"dumbbell sitting good morning","bp":"back","eq":"dumbbell","tg":"hamstrings","mg":"glutes","sm":["glutes","lower back","upper back"],"st":["Sit on a bench with feet flat and hold a dumbbell against your chest.","Sit tall and brace your core.","Hinge forward from the hips, keeping your back flat.","Stop when your torso is about halfway down.","Squeeze your back and glutes to sit tall again."],"img":"opengym/9515.webp","gif":null,"ext":1},{"id":"9516","n":"barbell elevated heel clean grip squat","bp":"upper legs","eq":"barbell","tg":"quads","mg":"glutes","sm":["glutes","adductors","lower back","core"],"st":["Place your heels on small plates and hold a bar across your upper back with a clean-width grip.","Brace your core and keep your chest up.","Sit down into a deep squat with knees tracking over toes.","Pause at the bottom.","Drive up through your feet to stand."],"img":"opengym/9516.webp","gif":null,"ext":1},{"id":"9517","n":"weighted kettlebell dead bug","bp":"waist","eq":"kettlebell","tg":"abs","mg":"lower abs","sm":["lower abs","hip flexors","core","shoulders"],"st":["Lie on your back holding a kettlebell above your chest with straight arms.","Raise your knees to a tabletop position.","Press your lower back into the floor.","Extend one leg out while keeping your back flat.","Return it and alternate sides."],"img":"opengym/9517.webp","gif":null,"ext":1},{"id":"9518","n":"kettlebell pullover dead bug","bp":"waist","eq":"kettlebell","tg":"abs","mg":"lower abs","sm":["lower abs","lats","core","hip flexors"],"st":["Lie on your back holding a kettlebell above your chest and knees at tabletop.","Brace your core and keep your lower back down.","Lower the kettlebell overhead while extending the opposite leg.","Return to the start under control.","Switch sides and repeat."],"img":"opengym/9518.webp","gif":null,"ext":1},{"id":"9601","n":"bodyweight patrick step","bp":"upper legs","eq":"body weight","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","calves"],"st":["Stand on a low step on one leg.","Slowly bend the knee and lower the other heel to the floor.","Keep your knee tracking over your toes.","Tap the floor lightly.","Push through the standing leg to rise.","Do your reps, then switch legs."],"img":"opengym/9601.webp","gif":null,"ext":1},{"id":"9602","n":"bodyweight patrick step from stepbox","bp":"upper legs","eq":"body weight","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","calves"],"st":["Stand on the edge of a step box on one leg.","Lower the other foot toward the floor.","Keep your knee in line with your toes.","Touch the floor lightly.","Push up through the standing leg.","Do your reps, then switch legs."],"img":"opengym/9602.webp","gif":null,"ext":1},{"id":"9603","n":"bodyweight poliquin step","bp":"upper legs","eq":"body weight","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","calves"],"st":["Stand with one foot on a low step.","Lower the other foot toward the floor with control.","Keep your knee in line with your toes.","Touch the floor lightly.","Drive back up through the working leg.","Do your reps, then switch legs."],"img":"opengym/9603.webp","gif":null,"ext":1},{"id":"9604","n":"bodyweight poliquin step from stepbox","bp":"upper legs","eq":"body weight","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","calves"],"st":["Stand on a step box on one leg.","Lower the other foot toward the floor with control.","Keep your torso upright.","Lightly tap the floor.","Press up through your working leg.","Do your reps, then switch legs."],"img":"opengym/9604.webp","gif":null,"ext":1},{"id":"9605","n":"bodyweight peterson step from stepbox","bp":"upper legs","eq":"body weight","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","calves"],"st":["Stand on a step box on one leg.","Lower the other foot slowly toward the floor.","Keep your knee stable and your torso tall.","Touch the floor lightly.","Rise back up through the working leg.","Do your reps, then switch legs."],"img":"opengym/9605.webp","gif":null,"ext":1},{"id":"9606","n":"box drop jump","bp":"upper legs","eq":"body weight","tg":"quads","mg":"glutes","sm":["glutes","calves","hamstrings"],"st":["Stand on the edge of a low box with feet hip-width apart.","Step off, do not jump, and land on both feet.","Absorb the landing by bending your knees and hips.","Immediately explode upward into a jump.","Land softly and reset."],"img":"opengym/9606.webp","gif":null,"ext":1},{"id":"9607","n":"isometric mid thighs pull","bp":"upper legs","eq":"barbell","tg":"glutes","mg":"hamstrings","sm":["hamstrings","lower back","upper back","grip muscles"],"st":["Set a bar in a rack at mid-thigh height and grip it just outside your legs.","Stand with a flat back and slightly bent knees.","Brace your core and chest up.","Pull up on the bar as hard as you can without it moving.","Hold for 5 seconds, then release gradually."],"img":"opengym/9607.webp","gif":null,"ext":1},{"id":"9608","n":"walking backward on a treadmill","bp":"cardio","eq":"leverage machine","tg":"cardiovascular system","mg":"quadriceps","sm":["quadriceps","calves","glutes"],"st":["Set the treadmill to a very slow speed and hold the handrails.","Turn to face away from the direction of the belt.","Step back gently, landing on the toes first.","Keep your chest tall and take small steps.","Continue for several minutes at a comfortable pace."],"img":"opengym/9608.webp","gif":null,"ext":1},{"id":"9609","n":"kettlebell deadlift v. 2","bp":"upper legs","eq":"kettlebell","tg":"glutes","mg":"hamstrings","sm":["hamstrings","lower back","quadriceps","grip muscles"],"st":["Stand with feet hip-width apart and the kettlebell between your feet.","Hinge and bend your knees to grip the handle with a flat back.","Brace your core and push the floor away.","Stand fully tall, squeezing your glutes.","Lower the bell back to the floor with control."],"img":"opengym/9609.webp","gif":null,"ext":1},{"id":"9610","n":"weighted plate overhead forward lunge","bp":"upper legs","eq":"weight plate","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","shoulders","core"],"st":["Hold a weight plate overhead with straight arms.","Step forward into a long stride.","Lower your back knee toward the floor.","Keep your torso upright and the plate steady.","Push back to the start and alternate legs."],"img":"opengym/9610.webp","gif":null,"ext":1},{"id":"9611","n":"bodyweight overhead forward lunge","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","shoulders","core"],"st":["Stand tall with your arms extended overhead.","Step forward into a long stride.","Lower your back knee toward the floor.","Keep your ribs down and arms in line with your ears.","Push back to the start and alternate legs."],"img":"opengym/9611.webp","gif":null,"ext":1},{"id":"9612","n":"dumbbell step over box","bp":"upper legs","eq":"dumbbell","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","calves","grip muscles"],"st":["Hold a dumbbell in each hand and stand beside a box.","Step one foot up onto the box.","Press through it and bring your other foot up.","Step down to the far side one foot at a time.","Repeat, alternating the leading leg."],"img":"opengym/9612.webp","gif":null,"ext":1},{"id":"9653","n":"standing torso twist arms swing","bp":"waist","eq":"body weight","tg":"obliques","mg":"abdominals","sm":["abdominals","shoulders","lower back"],"st":["Stand with feet shoulder-width apart and arms relaxed.","Rotate your torso to one side, letting your arms swing around.","Let your back heel lift slightly if needed.","Rotate smoothly to the other side.","Continue at an easy rhythm for 30 seconds."],"img":"opengym/9653.webp","gif":null,"ext":1},{"id":"9676","n":"lever lying knee flexion","bp":"upper legs","eq":"leverage machine","tg":"hamstrings","mg":"calves","sm":["calves","glutes"],"st":["Lie face down on the machine with the pad above your heels.","Grip the handles and keep your hips down.","Curl your heels toward your glutes.","Squeeze at the top.","Lower slowly back to the start."],"img":"opengym/9676.webp","gif":null,"ext":1},{"id":"9677","n":"plank side jump","bp":"waist","eq":"body weight","tg":"abs","mg":"obliques","sm":["obliques","shoulders","quadriceps","core"],"st":["Start in a high plank with hands under your shoulders.","Brace your abs and keep your back flat.","Jump both feet a short way to one side.","Jump them back through the centre to the other side.","Keep a steady rhythm for 20-30 seconds."],"img":"opengym/9677.webp","gif":null,"ext":1},{"id":"9679","n":"hopping high knee tap","bp":"cardio","eq":"body weight","tg":"cardiovascular system","mg":"hip flexors","sm":["hip flexors","quadriceps","calves","core"],"st":["Stand tall with one hand held out in front at waist height.","Hop on one leg while driving the opposite knee up to tap your hand.","Land softly and quickly switch legs.","Keep your chest upright.","Continue at a lively pace for 20-30 seconds."],"img":"opengym/9679.webp","gif":null,"ext":1},{"id":"9690","n":"dumbbell elevated heel front squat","bp":"upper legs","eq":"dumbbell","tg":"quads","mg":"glutes","sm":["glutes","adductors","core"],"st":["Place your heels on small plates and hold a dumbbell at your chest.","Brace your core and keep your elbows up.","Sit down into a deep squat.","Keep your chest tall and knees tracking over toes.","Drive up to stand."],"img":"opengym/9690.webp","gif":null,"ext":1},{"id":"9691","n":"bodyweight elevated heel front squat","bp":"upper legs","eq":"body weight","tg":"quads","mg":"glutes","sm":["glutes","adductors","core"],"st":["Place your heels on a low plate or wedge.","Hold your hands in front of your chest.","Sit down into a deep squat with your chest tall.","Keep your knees tracking over your toes.","Press up to stand and repeat."],"img":"opengym/9691.webp","gif":null,"ext":1},{"id":"9692","n":"kettlebell alternating arm thruster","bp":"full body","eq":"kettlebell","tg":"quads","mg":"glutes","sm":["glutes","shoulders","triceps","core"],"st":["Hold a kettlebell in each hand at shoulder height.","Squat down with your chest tall.","Drive up and press one kettlebell overhead.","Lower it back to your shoulder as you squat again.","Press the other arm on the next rep."],"img":"opengym/9692.webp","gif":null,"ext":1},{"id":"9693","n":"dumbbell alternating arm thruster","bp":"full body","eq":"dumbbell","tg":"quads","mg":"glutes","sm":["glutes","shoulders","triceps","core"],"st":["Hold a dumbbell in each hand at shoulder height.","Squat down with your chest tall.","Drive up and press one dumbbell overhead.","Lower it back to your shoulder as you squat again.","Alternate arms each rep."],"img":"opengym/9693.webp","gif":null,"ext":1},{"id":"9694","n":"barbell half kneeling shoulders press","bp":"shoulders","eq":"barbell","tg":"delts","mg":"triceps","sm":["triceps","upper chest","core","glutes"],"st":["Kneel on one knee with the other foot forward and a barbell at your shoulder.","Squeeze your glutes and brace your core.","Press the bar overhead until your arms are straight.","Lower under control to your shoulder.","Finish your reps, then switch legs."],"img":"opengym/9694.webp","gif":null,"ext":1},{"id":"9695","n":"landmine half kneeling shoulders press","bp":"shoulders","eq":"landmine","tg":"delts","mg":"triceps","sm":["triceps","upper chest","core","glutes"],"st":["Kneel on one knee and hold the end of the landmine at your shoulder.","Brace your core and squeeze your glutes.","Press the end up and forward until your arm is straight.","Lower slowly to your shoulder.","Complete your reps, then switch sides."],"img":"opengym/9695.webp","gif":null,"ext":1},{"id":"9696","n":"barbell frog stance deadlift","bp":"upper legs","eq":"barbell","tg":"glutes","mg":"hamstrings","sm":["hamstrings","adductors","lower back","grip muscles"],"st":["Stand with feet wide, toes turned out, and a bar over mid-foot.","Hinge and bend your knees to grip the bar.","Brace your core and keep your back flat.","Drive through your feet to stand tall.","Lower the bar with control."],"img":"opengym/9696.webp","gif":null,"ext":1},{"id":"9697","n":"kettlebell bottoms up single arm overhead carry","bp":"shoulders","eq":"kettlebell","tg":"delts","mg":"rotator cuff","sm":["rotator cuff","forearms","grip muscles","core"],"st":["Clean a kettlebell so it is upside down with the bell above your fist.","Press it overhead with a firm wrist.","Brace your core and stand tall.","Walk slowly in a straight line.","Lower it safely and switch arms."],"img":"opengym/9697.webp","gif":null,"ext":1},{"id":"9698","n":"dumbbell chest supported row","bp":"back","eq":"dumbbell","tg":"upper back","mg":"lats","sm":["lats","rhomboids","rear deltoids","biceps"],"st":["Lie face down on an incline bench with a dumbbell in each hand.","Let your arms hang straight down.","Row the weights toward your ribs.","Squeeze your shoulder blades together.","Lower slowly."],"img":"opengym/9698.webp","gif":null,"ext":1},{"id":"9699","n":"dumbbell single arm chest supported row","bp":"back","eq":"dumbbell","tg":"upper back","mg":"lats","sm":["lats","rhomboids","rear deltoids","biceps"],"st":["Lie face down on an incline bench holding a dumbbell in one hand.","Let your arm hang straight down.","Row the dumbbell toward your hip.","Squeeze your back at the top.","Lower slowly, finish your reps, then switch arms."],"img":"opengym/9699.webp","gif":null,"ext":1},{"id":"9700","n":"bodyweight walking low lunge","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","hip flexors","core"],"st":["Stand tall with your hands on your hips.","Step forward into a long stride.","Lower your back knee close to the floor.","Push through your front foot and step the back leg forward.","Continue walking forward, alternating legs."],"img":"opengym/9700.webp","gif":null,"ext":1},{"id":"9701","n":"long distance lunge (low lunge)","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","hip flexors","groin"],"st":["Stand tall with hands on your hips.","Take a very long step forward.","Sink down until your back knee hovers above the floor.","Keep your torso upright and front knee over the ankle.","Push back to the start and switch legs."],"img":"opengym/9701.webp","gif":null,"ext":1},{"id":"9702","n":"bodyweight pulse goblet squat","bp":"upper legs","eq":"body weight","tg":"quads","mg":"glutes","sm":["glutes","adductors","core"],"st":["Stand with feet shoulder-width apart and hands clasped at your chest.","Squat down to a deep position.","Pulse up and down a few centimetres at the bottom.","Keep your chest tall and heels down.","Stand up after the planned pulses."],"img":"opengym/9702.webp","gif":null,"ext":1},{"id":"9703","n":"kettlebell z press","bp":"shoulders","eq":"kettlebell","tg":"delts","mg":"triceps","sm":["triceps","upper chest","core","upper back"],"st":["Sit on the floor with legs extended and hold a kettlebell at your shoulder.","Sit tall and brace your core.","Press the kettlebell overhead until your arm is straight.","Lower it slowly to your shoulder.","Finish your reps, then switch arms."],"img":"opengym/9703.webp","gif":null,"ext":1},{"id":"9704","n":"suspender headstand","bp":"full body","eq":"suspension trainer","tg":"delts","mg":"core","sm":["core","upper back","triceps"],"st":["Set the straps at a low height.","Place your forearms or hands on the floor.","Lift your hips and place your feet in the straps.","Press your body up into a stable position.","Hold for 10 to 20 seconds.","Lower slowly and rest."],"img":"opengym/9704.webp","gif":null,"ext":1},{"id":"9705","n":"cable lying floor front raise","bp":"shoulders","eq":"cable","tg":"delts","mg":"upper chest","sm":["upper chest","core"],"st":["Lie on your back with your feet toward a low pulley and hold the handle.","Start with your arm by your thigh.","Raise your arm up over your chest with a slight elbow bend.","Pause at the top.","Lower slowly and repeat, then switch arms."],"img":"opengym/9705.webp","gif":null,"ext":1},{"id":"9803","n":"standing tibialis raise wall supported","bp":"lower legs","eq":"body weight","tg":"shins","mg":"calves","sm":["calves","ankles","feet"],"st":["Stand with your back against a wall and feet a little forward.","Keep your legs straight.","Lift your toes as high as you can, keeping your heels down.","Pause at the top.","Lower slowly and repeat."],"img":"opengym/9803.webp","gif":null,"ext":1},{"id":"9819","n":"hanging knee raise","bp":"waist","eq":"body weight","tg":"abs","mg":"lower abs","sm":["lower abs","hip flexors","grip muscles","lats"],"st":["Hang from a pull-up bar with arms straight.","Brace your abs and avoid swinging.","Raise your knees toward your chest.","Tilt your pelvis up at the top.","Lower slowly and repeat."],"img":"opengym/9819.webp","gif":null,"ext":1},{"id":"9821","n":"plank leg lift mountain climber","bp":"waist","eq":"body weight","tg":"abs","mg":"obliques","sm":["obliques","hip flexors","shoulders","core"],"st":["Start in a high plank with hands under your shoulders.","Lift one leg straight back.","Bring that knee in toward your chest.","Return and switch legs.","Keep your hips level and your core tight."],"img":"opengym/9821.webp","gif":null,"ext":1},{"id":"9848","n":"leverage standing hip thrust","bp":"upper legs","eq":"leverage machine","tg":"glutes","mg":"hamstrings","sm":["hamstrings","core","adductors"],"st":["Adjust the machine so the pad sits across your hips.","Stand with your feet hip width apart.","Lower your hips back slightly.","Drive your hips forward and squeeze your glutes.","Return slowly to the start.","Keep your ribs down."],"img":"opengym/9848.webp","gif":null,"ext":1},{"id":"9849","n":"side plank clamshell","bp":"upper legs","eq":"body weight","tg":"abductors","mg":"glutes","sm":["glutes","obliques","core"],"st":["Lie on your side in a side plank, supported on your forearm with knees bent.","Lift your hips so your body is in a line.","Keep your feet together and open your top knee upward.","Close it under control.","Finish your reps, then switch sides."],"img":"opengym/9849.webp","gif":null,"ext":1},{"id":"9862","n":"lever single arm preacher curl (plate loaded)","bp":"upper arms","eq":"leverage machine","tg":"biceps","mg":"brachialis","sm":["brachialis","forearms"],"st":["Sit at the machine with your upper arm resting on the pad and grip the handle.","Start with your arm almost straight.","Curl the handle up toward your shoulder.","Squeeze at the top.","Lower slowly, then switch arms."],"img":"opengym/9862.webp","gif":null,"ext":1},{"id":"9863","n":"cable side lying floor single leg kickback","bp":"upper legs","eq":"cable","tg":"glutes","mg":"hamstrings","sm":["hamstrings","core"],"st":["Lie on your side with a cuff on your top ankle.","Position the cable behind you.","Kick your top leg back and slightly up.","Squeeze your glute at the top.","Return slowly.","Do your reps, then switch sides."],"img":"opengym/9863.webp","gif":null,"ext":1},{"id":"9865","n":"lever belt deadlift (v bar)","bp":"upper legs","eq":"leverage machine","tg":"glutes","mg":"hamstrings","sm":["hamstrings","quadriceps","lower back","grip muscles"],"st":["Stand on the platform with the belt around your hips and grip the V bar.","Bend your knees and hinge with a flat back.","Brace your core.","Drive your feet down and stand tall.","Lower with control."],"img":"opengym/9865.webp","gif":null,"ext":1},{"id":"9866","n":"lever belt deadlift (straight bar)","bp":"upper legs","eq":"leverage machine","tg":"glutes","mg":"hamstrings","sm":["hamstrings","quadriceps","lower back","grip muscles"],"st":["Stand on the platform with the belt around your hips and grip the straight bar.","Bend your knees and hinge with a flat back.","Brace your core.","Drive your feet down and stand tall.","Lower with control."],"img":"opengym/9866.webp","gif":null,"ext":1},{"id":"9867","n":"cable 45 degrees reverse grip reverse fly","bp":"shoulders","eq":"cable","tg":"delts","mg":"rear deltoids","sm":["rear deltoids","upper back","rhomboids"],"st":["Stand at a cable station and grab the handles with palms up.","Hinge forward about 45 degrees.","Pull your arms out and back in a wide arc.","Squeeze your shoulder blades.","Return slowly."],"img":"opengym/9867.webp","gif":null,"ext":1},{"id":"9868","n":"cable 45 degrees single arm reverse fly","bp":"shoulders","eq":"cable","tg":"delts","mg":"rear deltoids","sm":["rear deltoids","upper back","rhomboids"],"st":["Stand at a cable station and take one handle.","Hinge forward about 45 degrees.","Pull your arm out and back in an arc.","Squeeze your shoulder blade.","Return slowly and switch sides."],"img":"opengym/9868.webp","gif":null,"ext":1},{"id":"9869","n":"cable 45 degrees single arm reverse grip reverse fly","bp":"shoulders","eq":"cable","tg":"delts","mg":"rear deltoids","sm":["rear deltoids","upper back","rhomboids"],"st":["Stand at a cable station and take one handle with your palm up.","Hinge forward about 45 degrees.","Pull your arm out and back in an arc.","Squeeze your shoulder blade.","Return slowly and switch sides."],"img":"opengym/9869.webp","gif":null,"ext":1},{"id":"9870","n":"cable incline single arm y raise with back support","bp":"shoulders","eq":"cable","tg":"delts","mg":"trapezius","sm":["trapezius","upper back","rotator cuff","rear deltoids"],"st":["Lie face down on an incline bench with a cable handle in one hand.","Let your arm hang down.","Raise it up and out in a Y shape.","Pause with your thumb up.","Lower slowly, then switch arms."],"img":"opengym/9870.webp","gif":null,"ext":1},{"id":"9871","n":"cable incline single arm y raise wrist straps with back support","bp":"shoulders","eq":"cable","tg":"delts","mg":"trapezius","sm":["trapezius","upper back","rotator cuff","rear deltoids"],"st":["Lie face down on an incline bench with the strap on one wrist.","Let your arm hang down.","Raise it up and out in a Y shape.","Pause at the top.","Lower slowly, then switch arms."],"img":"opengym/9871.webp","gif":null,"ext":1},{"id":"9872","n":"cable lying bench cross lateral raise","bp":"shoulders","eq":"cable","tg":"delts","mg":"rear deltoids","sm":["rear deltoids","upper back","rotator cuff"],"st":["Lie on a flat bench between two low cable pulleys and grab each handle with the opposite hand.","Start with your arms crossed over your body and a slight bend in the elbows.","Raise both arms out and up in a wide arc until your hands are about shoulder height.","Pause briefly at the top without shrugging.","Lower slowly back to the crossed position.","Keep your back flat on the bench and avoid swinging."],"img":"opengym/9872.webp","gif":null,"ext":1},{"id":"9873","n":"cable lying bench single arm cross lateral raise","bp":"shoulders","eq":"cable","tg":"delts","mg":"rear deltoids","sm":["rear deltoids","upper back","rotator cuff"],"st":["Lie on a flat bench next to a low pulley and take the handle with the far hand.","Start with your arm across your body and a soft bend in the elbow.","Raise the arm out and up in an arc until it reaches about shoulder height.","Hold for a moment, then lower with control.","Keep your torso still and your shoulder away from your ear.","Finish your reps, then switch sides."],"img":"opengym/9873.webp","gif":null,"ext":1},{"id":"9874","n":"cable lying single arm cross lateral raise","bp":"shoulders","eq":"cable","tg":"delts","mg":"rear deltoids","sm":["rear deltoids","upper back","rotator cuff"],"st":["Lie on the floor next to a low pulley and grip the handle with the far hand.","Begin with your arm across your body and the elbow slightly bent.","Raise your arm out and up in a smooth arc to about shoulder height.","Pause briefly at the top.","Lower slowly back across your body without letting the weight stack rest.","Complete your reps, then switch sides."],"img":"opengym/9874.webp","gif":null,"ext":1},{"id":"9875","n":"cable sitting bench single arm twisting row","bp":"back","eq":"cable","tg":"upper back","mg":"lats","sm":["lats","rhomboids","biceps","rear deltoids","core"],"st":["Sit on a bench facing a low cable with your feet braced and take the handle in one hand.","Sit tall with your arm extended and your torso turned slightly toward the cable.","Pull the handle back while rotating your torso and wrist toward your hip.","Squeeze your shoulder blade toward your spine at the end.","Return slowly with your arm extended and your torso rotating back.","Keep your chest up, then switch sides after your reps."],"img":"opengym/9875.webp","gif":null,"ext":1},{"id":"9876","n":"lever belt romanian deadlift (straight bar)","bp":"upper legs","eq":"leverage machine","tg":"hamstrings","mg":"glutes","sm":["glutes","lower back","grip muscles"],"st":["Step into the machine, set the belt securely and hold the straight bar with an overhand grip.","Stand tall with your knees slightly bent and your chest up.","Push your hips back and slide the bar down along your thighs.","Lower until you feel a strong hamstring stretch while your back stays flat.","Drive your hips forward to stand back up.","Squeeze your glutes at the top without leaning back."],"img":"opengym/9876.webp","gif":null,"ext":1},{"id":"9877","n":"lever belt romanian deadlift (v bar)","bp":"upper legs","eq":"leverage machine","tg":"hamstrings","mg":"glutes","sm":["glutes","lower back","grip muscles"],"st":["Step into the machine, secure the belt and take the V bar with both hands.","Stand tall with soft knees and your shoulders back.","Hinge at the hips, pushing them back as the bar slides down your thighs.","Lower until your hamstrings are well stretched, keeping your back flat.","Drive your hips forward and stand up straight.","Squeeze your glutes at the top."],"img":"opengym/9877.webp","gif":null,"ext":1},{"id":"9878","n":"cable zercher squat","bp":"upper legs","eq":"cable","tg":"quads","mg":"glutes","sm":["glutes","adductors","core","lower back"],"st":["Attach a bar or handle to a low cable and hook it in the bends of your elbows, close to your chest.","Stand facing away from the stack with your feet shoulder width apart.","Brace your core and sit down and back until your thighs are about parallel.","Keep your chest tall and your knees tracking over your toes.","Push through your whole foot to stand back up.","Keep your elbows tucked and the load close to your body."],"img":"opengym/9878.webp","gif":null,"ext":1},{"id":"9890","n":"standing pelvic lift","bp":"upper legs","eq":"body weight","tg":"glutes","mg":"core","sm":["core","hamstrings","lower abs"],"st":["Stand tall with your feet hip width apart and your hands on your hips.","Soften your knees slightly.","Tuck your tailbone under and lift the front of your pelvis by squeezing your glutes and lower abs.","Hold for 2 seconds.","Release slowly to a neutral pelvis.","Keep your upper body still and breathe normally."],"img":"opengym/9890.webp","gif":null,"ext":1},{"id":"9927","n":"cable lying incline side leg raise","bp":"upper legs","eq":"cable","tg":"abductors","mg":"glutes","sm":["glutes","core","obliques"],"st":["Lie on your side on an incline surface.","Attach the cuff to your top ankle.","Raise your top leg out to the side.","Pause at the top.","Lower with control.","Do your reps, then switch sides."],"img":"opengym/9927.webp","gif":null,"ext":1},{"id":"9928","n":"cable lying incline single leg kickback","bp":"upper legs","eq":"cable","tg":"glutes","mg":"hamstrings","sm":["hamstrings","core","lower back"],"st":["Lie on an incline surface with the cuff on one ankle.","Hold the support for stability.","Kick your leg back and up.","Squeeze your glute at the top.","Lower slowly.","Do your reps, then switch legs."],"img":"opengym/9928.webp","gif":null,"ext":1},{"id":"9929","n":"leverage single leg squat on hack squat machine","bp":"upper legs","eq":"leverage machine","tg":"quads","mg":"glutes","sm":["glutes","hamstrings","adductors"],"st":["Set your back against the pad and step onto the platform.","Place one foot on the platform and lift the other slightly.","Lower into a squat with control.","Keep your knee tracking over your toes.","Press back up through the working leg.","Do your reps, then switch legs."],"img":"opengym/9929.webp","gif":null,"ext":1},{"id":"9930","n":"barbell california press","bp":"chest","eq":"barbell","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders","upper chest"],"st":["Lie on a flat bench and hold a barbell above your chest with a shoulder width grip.","Bend your elbows to lower the bar toward your forehead like a skull crusher.","As it nears your head, let the elbows travel down so the bar moves toward the upper chest.","Press the bar up and slightly back over your shoulders.","Lower again along the same path and repeat.","Use a lighter weight and keep your wrists straight."],"img":"opengym/9930.webp","gif":null,"ext":1},{"id":"9931","n":"dumbbell spider curl","bp":"upper arms","eq":"dumbbell","tg":"biceps","mg":"brachialis","sm":["brachialis","forearms"],"st":["Lie face down on an incline bench with a dumbbell in each hand and your arms hanging straight down.","Keep your upper arms vertical and your palms facing forward.","Curl the dumbbells up toward your shoulders.","Squeeze your biceps at the top.","Lower slowly until your arms are fully extended.","Keep your chest on the pad and avoid swinging."],"img":"opengym/9931.webp","gif":null,"ext":1},{"id":"9932","n":"barbell banded weighted plate bench press","bp":"chest","eq":"barbell","tg":"pectorals","mg":"triceps","sm":["triceps","shoulders","upper chest"],"st":["Lie on a bench and make sure the bands and plates are secured on the barbell.","Unrack the bar and hold it over your chest with your arms extended.","Lower the bar to your mid chest under control.","Press it back up, fighting the rising band tension.","Lock out your elbows without losing shoulder position.","Keep your feet planted and shoulder blades pinched together."],"img":"opengym/9932.webp","gif":null,"ext":1},{"id":"9933","n":"dumbbell seated alternating lateral raise","bp":"shoulders","eq":"dumbbell","tg":"delts","mg":"trapezius","sm":["trapezius","rotator cuff","rear deltoids"],"st":["Sit upright on a bench with a dumbbell in each hand at your sides.","Keep a slight bend in your elbows.","Raise one arm out to the side until it reaches shoulder height.","Lower it slowly, then raise the other arm.","Keep your torso still and avoid shrugging.","Alternate sides for your reps."],"img":"opengym/9933.webp","gif":null,"ext":1},{"id":"9940","n":"weighted sandbag forward lunge","bp":"upper legs","eq":"sandbag","tg":"glutes","mg":"quadriceps","sm":["quadriceps","hamstrings","core","adductors"],"st":["Hold a sandbag against your chest or across your shoulders and stand tall.","Step forward with one leg into a long stride.","Lower until both knees are about 90 degrees with your torso upright.","Push through the front foot to return to standing.","Repeat with the other leg.","Keep your front knee over your ankle and the bag tight to your body."],"img":"opengym/9940.webp","gif":null,"ext":1},{"id":"9942","n":"standing cross legs core stretch","bp":"waist","eq":"body weight","tg":"abs","mg":"obliques","sm":["obliques","lower back"],"st":["Stand tall and cross one leg in front of the other.","Raise the arm on the same side as the back leg overhead.","Reach and lean gently toward the opposite side.","Feel the stretch along your side and abs.","Hold for 20-30 seconds while breathing steadily.","Return to standing and repeat on the other side."],"img":"opengym/9942.webp","gif":null,"ext":1},{"id":"9969","n":"lying supine heel slide","bp":"upper legs","eq":"body weight","tg":"hamstrings","mg":"quadriceps","sm":["quadriceps","hip flexors","calves"],"st":["Lie on your back with both legs straight.","Slowly slide one heel along the floor toward your buttocks.","Bend the knee as far as feels comfortable.","Pause for a second.","Slide the heel back out until the leg is straight.","Repeat for your reps, then switch legs."],"img":"opengym/9969.webp","gif":null,"ext":1},{"id":"9971","n":"lying supine straight knee raise","bp":"upper legs","eq":"body weight","tg":"hip flexors","mg":"quadriceps","sm":["quadriceps","core"],"st":["Lie on your back with one knee bent and the other leg straight.","Tighten the thigh of the straight leg so the knee is locked.","Lift the leg to the height of your bent knee.","Hold for a moment.","Lower slowly to the floor.","Finish your reps, then switch legs."],"img":"opengym/9971.webp","gif":null,"ext":1},{"id":"9977","n":"lying supine abdominal breathing","bp":"waist","eq":"body weight","tg":"abs","mg":"core","sm":["core","obliques"],"st":["Lie on your back with your knees bent and your hands on your belly.","Breathe in slowly through your nose.","Feel your belly rise under your hands.","Breathe out slowly through your mouth.","Let your belly lower gently.","Continue for 1 to 2 minutes."],"img":"opengym/9977.webp","gif":null,"ext":1},{"id":"9980","n":"stick assisted standing shoulder flexion","bp":"shoulders","eq":"assisted","tg":"delts","mg":"upper chest","sm":["upper chest","rotator cuff","triceps"],"st":["Stand tall holding a stick with both hands at hip level, palms down.","Keep the working arm relaxed and let the other hand lead.","Raise the stick forward and overhead as far as is comfortable.","Pause at the top.","Lower slowly back to the start.","Keep your ribs down and avoid arching your back."],"img":"opengym/9980.webp","gif":null,"ext":1},{"id":"9986","n":"standing towel foot crunch","bp":"lower legs","eq":"body weight","tg":"calves","mg":"feet","sm":["feet","shins","ankles"],"st":["Stand with one foot flat on a towel laid on a smooth floor.","Keep your heel down.","Curl your toes to pull the towel toward you.","Release and repeat until the towel is bunched under your foot.","Hold on to a support if you need balance.","Do your reps, then switch feet."],"img":"opengym/9986.webp","gif":null,"ext":1},{"id":"9988","n":"resistance band kneeling sissy squat","bp":"upper legs","eq":"resistance band","tg":"quads","mg":"core","sm":["core","hip flexors","glutes"],"st":["Set the band at a stable anchor and kneel with it around your body or hands.","Keep your hips forward and your body in a straight line from knees to head.","Lean back slowly, keeping your hips extended.","Go as far as you can control.","Use your quads to pull yourself back up.","Keep your core braced and your movement smooth."],"img":"opengym/9988.webp","gif":null,"ext":1},{"id":"9989","n":"stick assisted standing shoulder internal rotation","bp":"shoulders","eq":"assisted","tg":"delts","mg":"rotator cuff","sm":["rotator cuff","chest","lats"],"st":["Stand tall holding a stick behind your back, one hand low and the other high.","Let the lower hand grip the stick as the working arm.","With the top hand, gently pull the stick up so the lower hand rises along your back.","Go until you feel a mild stretch.","Hold for 2 seconds, then release.","Keep your shoulders level, then switch sides."],"img":"opengym/9989.webp","gif":null,"ext":1},{"id":"9990","n":"standing isometric shoulder internal rotation against wall","bp":"shoulders","eq":"body weight","tg":"delts","mg":"rotator cuff","sm":["rotator cuff","chest","lats"],"st":["Stand sideways to a wall with your elbow bent to 90 degrees and tucked at your side.","Place the inside of your fist or forearm against the wall.","Press into the wall as if rotating your arm inward.","Hold the contraction for 5-10 seconds.","Relax and rest briefly.","Keep your elbow at your side, then switch arms."],"img":"opengym/9990.webp","gif":null,"ext":1},{"id":"9994","n":"ball assisted lying bent knee isometric hip adduction","bp":"upper legs","eq":"stability ball","tg":"adductors","mg":"inner thighs","sm":["inner thighs","glutes","core"],"st":["Lie on your back with your knees bent.","Place a ball between your knees.","Squeeze the ball with your inner thighs.","Hold for 5 to 10 seconds.","Release slowly.","Repeat for several reps."],"img":"opengym/9994.webp","gif":null,"ext":1},{"id":"9995","n":"isometric wrist extension","bp":"lower arms","eq":"body weight","tg":"forearms","mg":"wrist extensors","sm":["wrist extensors","grip muscles"],"st":["Sit with your forearm resting on a table, palm down and wrist at the edge.","Place your other hand on top of the working hand.","Try to lift the hand up while the top hand resists.","Hold for 5-10 seconds with no movement.","Relax slowly.","Repeat, then switch arms."],"img":"opengym/9995.webp","gif":null,"ext":1},{"id":"9996","n":"resistance band isometric thumb extension","bp":"lower arms","eq":"resistance band","tg":"forearms","mg":"hands","sm":["hands","wrist extensors"],"st":["Loop a light resistance band around your thumb and the base of your fingers.","Rest your hand on a table or your thigh.","Push your thumb out against the band.","Hold the tension for 5-10 seconds without moving.","Release slowly.","Repeat, then switch hands."],"img":"opengym/9996.webp","gif":null,"ext":1},{"id":"9999","n":"plank knee tap","bp":"waist","eq":"body weight","tg":"abs","mg":"obliques","sm":["obliques","core","shoulders"],"st":["Start in a forearm or high plank.","Brace your core.","Lower one knee gently toward the floor.","Return it and switch sides.","Keep your hips level.","Breathe steadily."],"img":"opengym/9999.webp","gif":null,"ext":1}];
